INSERT INTO "fact" VALUES('interp:AQ14101437:p072095ef7a','p072095ef7a','interpellation','2024-12-27','{"councillors": ["李芳儒"], "dept": "民政", "doc_no": "AQ14101437", "doc_type": "書面質詢", "session": "第14屆第05次臨時大會", "term": 14, "title": "為應安養中心床位不足導致許多家庭須居家照護，因而導致家庭經濟中斷或有居家照護之需求，故本席要求放寬補助對象，除原有的補助對象外，應增加居家照護者，或因居家照護而導致無工作之民眾申請。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDFAF4EDBF90C6BE5C452D6F7DA616DC9FB6415EE6369E3C2C62F3DF37482B742013494B728C640FB0','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101435:p072095ef7a','p072095ef7a','interpellation','2024-12-27','{"councillors": ["李芳儒"], "dept": "教育", "doc_no": "AQ14101435", "doc_type": "書面質詢", "session": "第14屆第05次臨時大會", "term": 14, "title": "近期大巨蛋連續舉辦多場活動,經民眾反映並實地查訪後，發現大巨蛋B2廁所，有一處將部分隔間上鎖，僅剩兩間可供使用及一處廁所內有電燈損壞，導致光線不足、廁所設有標註「男廁」「女廁」的二維碼，但未清楚說明用途，民眾可能誤以為是意見回饋管道。對於民眾的便利性與安全性造成影響，亟需改善。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDCF28F828E4CD4871A3B1B4F3E9A37C7ED558646515BA3F0362F3DF37482B742092DB93D405529A1E','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101434:p072095ef7a','p072095ef7a','interpellation','2024-12-27','{"councillors": ["李芳儒"], "dept": "工務", "doc_no": "AQ14101434", "doc_type": "書面質詢", "session": "第14屆第05次臨時大會", "term": 14, "title": "臺北市社會住宅政策已推行多年，並陸續興建與完工多處社會住宅。然而，目前的社會住宅房型分配與家庭戶數結構比例不符，導致許多家庭無法受惠於社會住宅政策。為此，本席要求應根據實際需求對房型比例進行調整：將一房型比例調整為40%，二房型及三房型各為30%，以更符合家庭戶數結構比例及住宅需求。此外，可考慮將現有的一房型與套房型合併為二房型或三房型，以提高這兩類房型的比例，兼顧資源分配公平及民眾實際需求。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDFAF4EDBF90C6BE5C85370451109D2EAC05445DE133E4CF6C62F3DF37482B74203EF23741765E4054','2026-09-28T10:12:56Z');
