INSERT INTO "fact" VALUES('interp:AQ14101263:pc524c2d6ef','pc524c2d6ef','interpellation','2024-09-24','{"councillors": ["李柏毅"], "dept": "教育", "doc_no": "AQ14101263", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "本月22日中華職棒周思齊選手退役儀式中，周思齊選手代表許多棒球從業人員提出立碑紀念之建議，因台北小巨蛋前身係臺北市立棒球場，懇請台北市政府、台北捷運公司體育局審慎評估規劃立碑紀念之可能性，讓本市能夠有更完整的棒球文化。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBD159BF33CC56040B5CCCCE778B72B8F5852520BA1B5A86B5A62F3DF37482B74205BC6708AC8D44241','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101262:pc524c2d6ef','pc524c2d6ef','interpellation','2024-09-24','{"councillors": ["李柏毅"], "dept": "警政衛生", "doc_no": "AQ14101262", "doc_type": "書面質詢", "session": "第14屆休會", "term": 14, "title": "本市率全國之先，增設食安官以來，先後由府級參議、公管中心主任、衛生局副局長及秘書長兼任食安官，但皆有窒礙之處，故未發揮最佳效能，至今尚在調整中。本席雖肯定市府及衛生局為食安投入之心力，但因食安官未經考試院銓敘職系，皆為府、局高層兼任，而兼任之食安官往往沒有第一線之食安管理經驗，具食安管理經驗者又無適當升遷管道，本席爰此質詢，並具體要求：\r\n一、衛生局應設置一席簡任專門委員或簡任技正，由擔任過食藥科長者出任，專責督導食藥科及稽查科，協助食安官綜理本市食安相關事宜。\r\n二、目前出缺之簡任技正職務，建請由食藥科長升任，建立慣例。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBD159BF33CC56040B55F5C078B5CE6FE8437D2004F36FB814762F3DF37482B7420A193847D9D62AC4B','2026-09-28T10:12:56Z');
