INSERT INTO "fact" VALUES('interp:AQ14101118:p4cf586308f','p4cf586308f','interpellation','2024-06-24','{"councillors": ["詹為元"], "dept": "交通", "doc_no": "AQ14101118", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "有鑑於最近台北捷運意外衝突頻傳，除了設置緊急對講機外，建請市府增設手機緊急通報系統。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477312A73E4DB7D5CF237A133CDAB0EE4174F60C7DD474B6F9A3','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101116:p06dbec1b42','p06dbec1b42','interpellation','2024-06-21','{"councillors": ["郭昭巖"], "dept": "民政", "doc_no": "AQ14101116", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "為使臺北市政府青年局（以下簡稱青年局）能儘速掌握本市青年群體意見和需求，本席建請青年局研議能「定期」邀請15歲至45歲之青年代表，召開青年意見彙集會議。青年代表應包括國內、國際青年代表，俾能廣泛了解青年需求及建議，並向青年朋友宣導本市青年局政策。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477321DE13BE19CF294A7A133CDAB0EE4174FC02E4E8D2C477DA','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101114:p072095ef7a','p072095ef7a','interpellation','2024-06-20','{"councillors": ["李芳儒"], "dept": "工務", "doc_no": "AQ14101114", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "現行社會住宅申請資格限制過於嚴格，許多有迫切需求的居民無法符合申請資格，無法受惠於社會住宅政策。本席要求原有社宅申請資格放寬為：百分之五十分位點家庭之平均所得，或所得總額平均分配家庭成員人口數，達中低收入戶最低生活費標準者，以利更多有迫切需求之居民入住。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47732620F4252B883E427A133CDAB0EE41740FB878502E2DC966','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101113:p072095ef7a','p072095ef7a','interpellation','2024-06-20','{"councillors": ["李芳儒"], "dept": "民政", "doc_no": "AQ14101113", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "針對「臺北市政府大專青年學生公部門暑期工讀計畫」，北市原民會應在臺北市各大專院校推廣，並與原資中心合作，做宣傳及協助報名。青年學生除能實地瞭解市政工作外，更可拓展未來求職的管道，力求讓更多族人學子能參加工讀計畫。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC4773740712FEEB62013E7A133CDAB0EE4174F2918938E180C4B7','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101110:p9ff03a516c','p9ff03a516c','interpellation','2024-06-19','{"councillors": ["林珍羽"], "dept": "財政建設", "doc_no": "AQ14101110", "doc_type": "書面質詢", "session": "第14屆第04次臨時大會", "term": 14, "title": "鑒於光華數位新天地近年發生數件民眾墜樓案件，且事發地點竟有重複情形。顯見市府管理單位對該商場之安全管理存有不足，爰要求台北市市場處針對光華數位新天地之安全管理於一個月內提出檢討改善方案。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477377D13AEE6EE411FB7A133CDAB0EE41743B7D6079856A6279','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101108:pcb793ad399','pcb793ad399','interpellation','2024-06-13','{"councillors": ["何孟樺"], "dept": "警政衛生", "doc_no": "AQ14101108", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "本市兒童遊戲場均應依衛生福利部之規範進行報備，並由場域主管機關列冊管理，然經查衛生局、商業處所轄場域縮有設置兒童遊戲場卻未積極列冊管理，實有疏失，宜儘速研謀改善。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477375CEF8B2C5F275CA7A133CDAB0EE4174F694B48CADE0A4CF','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101107:pcb793ad399','pcb793ad399','interpellation','2024-06-13','{"councillors": ["何孟樺"], "dept": "警政衛生", "doc_no": "AQ14101107", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "查本市雖已啟用多處固定式聲音照相系統，然諸多位址取締成效不彰且未有針對噪音車易出沒位址加強設置，故為維護本市住民安寧，請市府評估於數處噪音車易出沒位址設置固定式聲音照相系統，並針對本市各路段進行整體評估、增設。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC477330AAD0258E6538AE7A133CDAB0EE41741B330F45D7F983AE','2026-09-28T10:12:56Z');
