INSERT INTO "fact" VALUES('interp:AQ14101082:p67335d29b9','p67335d29b9','interpellation','2024-06-04','{"councillors": ["鍾沛君"], "dept": "工務", "doc_no": "AQ14101082", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "經查公園路燈工程管理處，本年度累積未完成路燈件數共計233件：其中包括上個年度仍有175件迄未執行；今年已立案議員建議新設路燈案件計47件，去年積欠尚未執行完畢，今年又持續累積積欠數量。且該處目前開缺超過20人，工程人員離職率居高不下，甚至股長、副工程司都有缺額，顯見該處已經落入人力短缺造成業務執行延宕的惡性循環，請該處說明檢討改進方案？"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47734354C9BD609DF0BAF79698F1B928EA5A4B4F2592D37B400A','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101081:p67335d29b9','p67335d29b9','interpellation','2024-06-04','{"councillors": ["鍾沛君"], "dept": "交通", "doc_no": "AQ14101081", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "據臺北市停車管理工程處統計，轄下停車場及路邊停車費民國一百一十二年度遭欠金額為兩千七百萬餘元，目前僅催討到約四百萬餘元，經強制執行未繳及移送中金額還有兩千三百萬餘元。經查監察院曾糾正本市停管處長期以來執行效能不佳，五年前積欠停車至今有九百萬元尚在移送或執行依然滯欠，行政執行實際成效有限，造成市庫負擔。敦請市府持續精進稽催及執行方法，以落實使用者付費精神和維護停車位有效使用？"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47734919F83EF0E15376F79698F1B928EA5A54E963211A672610','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101080:p67335d29b9','p67335d29b9','interpellation','2024-06-04','{"councillors": ["鍾沛君"], "dept": "民政", "doc_no": "AQ14101080", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "台北市第一殯儀館即將功成身退，依據議會決議責成殯葬處規劃，將第二殯儀館周邊的黎元停車場改建為禮儀業者大樓，同時規劃在相鄰的青峰公園擴建地下停車場。落成後可望規劃業者進駐，改善周邊長年亂象，並增加停車空間，以紓解第二殯儀館的停車需求。請殯葬處說明目前的可行性研究進度、未來規劃運作模式等，並建議殯葬處更審慎考慮大樓命名，以增加附近居民接納和業者進駐的意願。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC4773839DD779738ED487F79698F1B928EA5A8E79E0F63EA76E97','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101079:p67335d29b9','p67335d29b9','interpellation','2024-06-04','{"councillors": ["鍾沛君"], "dept": "教育", "doc_no": "AQ14101079", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "臺北市藝文推廣處近年來辦理「文化就在巷子裡」的成效和促進藝術文化的成效本席予以肯定，但近期接獲反映，基層表演團體由於規模不大或非專業演出團體，無法與專業團體競爭有限的表演名額，成為遺珠之憾。敦請文化局偕同資訊局評估建立演藝資源線上平台，媒合表演團體與場地資源，讓更多表演業團體都有進行成果發表或展演的機會，進而促進文化交流。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47739597FD2A260A7CF7F79698F1B928EA5AA0787EE9D39F8133','2026-09-28T10:12:56Z');
INSERT INTO "fact" VALUES('interp:AQ14101078:p67335d29b9','p67335d29b9','interpellation','2024-06-04','{"councillors": ["鍾沛君"], "dept": "工務", "doc_no": "AQ14101078", "doc_type": "書面質詢", "session": "第14屆第03次定期大會", "term": 14, "title": "台北市文山區興泰段一小段242、243、244地號住宅新建案日前進行建築主體拆除工程，由於基地位於山坡地且擋土牆年久失修，下方疑似還有礦坑遺跡，附近居民擔憂肇生坍塌風險。請問建管處與大地工程處，現有建商監測報告只提供到民國一百零九年為止，協調後新設監測點取得之監測報告若於竣工時一併申報，資料時差之空窗期如何改善？且文山區遺留許多早年舊礦坑遺址但記錄混亂，影響營造安全評估，請問大地處有無相關清查、釐清之計畫？"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=57C198030E58D192E32086BA71068357975026367EEC924CABC202F24FBC47733662D54073B251A4F79698F1B928EA5AD2289D2698041BDD','2026-09-28T10:12:56Z');
