INSERT INTO "fact" VALUES('platform:2022-local:p4b727b88dc','p4b727b88dc','platform','2022-11-26','{"district_id": "tpe-council-02", "election": "2022-local", "office": "tpe_councilor", "text": "從政多年，世正始終堅持：不收紅包、不炒土地、不包工程！為什麼如此堅持？因為每張選票都是選民\n的信賴與託付，不該是牟取自己私利的工具！今年仍將本此信念爭取鄉親們的支持，當然還有這些年的\n服務成績，如更新校園設施、改善社區環境、打通交通瓶頸、增加停車空間、協助佈設社區關懷據點、\n修訂建築施工損鄰處理規則以幫助弱勢鄰損戶、公廁全面換裝感應式水龍頭、推動胖卡餐車試辦計畫…\n等各種提高鄉親生活品質的服務項目。\n世正未來四年任期政見目標：\n提升托育服務：增加公托量能，協助提高準公托教保品質，協助年輕家長養育寶貝下一代。\n建設特色公園：近年共融式公園概念興起，將推動港湖公園更新現代化，讓孩子開心安全成長。\n加速日照佈建：臺北市邁入超高齡社會，日照服務需求逐年增加，有必要加緊增建長者日間照護中心。\n強化青年服務：推動市府青年發展處升級，強化對青年族群工作、協助生涯規劃及社會參與之服務。\n加強地方建設：路平、燈亮、水溝通、污水接管、停車空間增加、改善交通瓶頸，推動捷運民生汐止線\n及東環線盡快動工…民眾有陳情，世正親自來處理。\n世正一直要求自己，專職專業為民服務、關注教育、關懷弱勢、提高鄉親生活品質，雖然現在的政治流\n行 「用嘴講」，但政治是服務眾人之事，世正認為，政治應該是要 「做正事」！讓民眾真正感受到選\n出來的議員是真正在為民眾服務，而不是為自己服務！世正擔任議員這些年來，深刻體會政府法令及施\n政常與民眾需求有落差，民代擔任著傾聽民意、發掘真相、協助弱勢鄉親們得到幫助的角色，懇請您支\n持認真做正事的世正，讓世正繼續能為鄉親來服務，來感謝您的支持！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p4b727b88dc','p4b727b88dc','profile','2022-11-26','{"education": ["• 臺北市立民生國小", "• 介壽國中", "• 建國高級中學", "• 國立政治大學政治學系學士", "• 國立政治大學政治研究所碩士"], "election": "2022-local", "experience": ["• 中華電視台記者及助理導播", "• 企業管理顧問公司企劃部經理", "• 中國電視公司記者及主播", "• 第八 ~ 十三屆臺北市議員", "• 救國團臺北市委會指導委員", "• 內湖區體育會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p47f1fe2e84','p47f1fe2e84','platform','2022-11-26','{"district_id": "tpe-council-02", "election": "2022-local", "office": "tpe_councilor", "text": "【交通平權】\n1. 捷運東環段與民生汐止線加速動工，捷運工程期間強化道路交通維持措施；爭取拓寬港湖聯外道路與港墘大\n橋興建、強化大數據運用分析，有效降低塞車指數。\n2. 推動道路平權、為機車族群發聲、督促市府全面檢討，放寬對機車不合理限制；爭取公共場所參建停車場，\n解決停車需求。\n3. 水域平權：水域活動開放區域回歸 「原則開放，例外禁止」 之立法原則。\n【友善動物】加速興建新動物之家；持續推廣設置寵物活動公園，讓台北市成為友善動物城市。\n【住得安穩】\n1. 危樓、海砂屋獎勵優先更新、簡化都市更新流程。\n2. 加速汰換瓦斯老舊管線，以維用氣安全。\n3. 提高老舊房屋健檢獎勵，推廣安全社區認證。\n【食得安全】要求加強稽查、落實管理、資訊公開透明，食品安全不可輕忽。\n【拚得放心】爭取增加公立、非營利幼兒園名額；提高生育獎勵金；增設社區公共托育家園、公辦民營托嬰中心。\n【老得安心】恢復重陽敬老金、擴大敬老卡使用範圍、推廣銀髮照顧在地化、獎勵青銀共居、加強日間與居家照護。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p47f1fe2e84','p47f1fe2e84','profile','2022-11-26','{"education": ["國立台灣大學政治學系碩士"], "election": "2022-local", "experience": ["• 美國國務院 IVLP 訪問學人", "• 國立台北商業大學講師", "• 台北市體育運動舞蹈協會理事長", "• 台北市拳擊協會副理事長", "• 台北市屏東同鄉會理事", "• 扶輪社東欣社公關主委", "• 國民黨文傳會主委兼發言人"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p28d7d936d9','p28d7d936d9','profile','2022-11-26','{"education": ["• 臺灣大學政治系", "• 中山女高"], "election": "2022-local", "experience": ["• 國會助理、環保署署長秘書", "• 台北市政府市長室專門委員", "• 台北市觀傳局主任秘書", "• 國民黨智庫策略研究組顧問", "• 國民黨革實院副院長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p32da79905a','p32da79905a','platform','2022-11-26','{"district_id": "tpe-council-02", "election": "2022-local", "office": "tpe_councilor", "text": "四大政見、十五項堅持，關切公共議題、堅持清廉參政、深植基層服務，強化市政監督功能，全力捍衛市民權益與謀求市民福利。\n【地區發展】\n1、強化勞動局就業媒合功能，為失業者提供多元就業輔導方案，保障勞工權益，留住優秀人才，擺脫低薪困境。\n2、持續爭取港湖建設，放寬容積獎勵、危老社區改建，加速都市更新，並監督都更處執行進度。\n3、打造傳統市場新樣貌，為傳統市場注入新元素。\n4、增進港湖地區觀光發展，打造白石湖園區及南港茶葉文化園區。\n5、捍衛港湖好山好水，推動關閉內湖焚化爐，改設環保博物館。\n【交通改善】\n6、全力改善港湖地區交通問題，監督捷運民生汐止線與捷運環狀線東環段興建期程，改善內湖科學園區及南港軟體園區周邊動線。\n【居住安全】\n7、爭取增建青年社會住宅，制定青年能負擔之社會住宅租金，政府帶頭降房租，讓青年租得起臺北市房屋。\n8、全力推動瓦斯儲存槽退出住宅區，確保市民安全及監督達使用年限之住户瓦斯管線汰舊換新。\n9、強化醫療衛生及健康中心之功能，推動弱勢醫療照顧中心及免費巡迴駐診。\n10、加強社區治安及員警巡邏，提升值班警員為民服務品質。\n【親子照護】\n11、有感育兒政策，包含：增加公托數量、提升托育人員就業率、閒置小學校舍改設為托育中心、企業彈性工時、凍卵補助。\n12、促進在地托嬰、老年人日間照顧，降低中低收入戶就業障礙，關懷獨居老人，並推動社區關懷、警民合作，提高生活及居住品質。\n13、爭取銀髮族長輩更多妥善照顧及優惠福利，包含：公立醫院65歲以上免收掛號費、社會住宅增設長者入住專區、臺北市立聯合醫院進駐社會住\n宅設立診所、提升公立長照中心設置比例，社會住宅或閒置學區增加長、日照機構比例、提高長照中心工作人員待遇及福利，訂定相關管理辦法。\n14、寒冬送暖愛心活動持續發光發熱，讓弱勢族群孩子擁有快樂童年，得到應有照顧。\n15、推廣毛小孩領養代替購買觀念，改善收容所環境，落實寵物登記制度，增設寵物運動公園、全力打造動物友善城市。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p32da79905a','p32da79905a','profile','2022-11-26','{"education": ["• 臺北市立大學教育行政與評鑑所博士", "• 康寧大學企業管理碩士", "• 德明商專", "• 國立基隆高級中學", "• 新北市瑞芳國民中學"], "election": "2022-local", "experience": ["• 民進黨臺北市議會第 10、11、12 屆市議員", "• 民進黨臺北市議會黨團總召集人", "• 民進黨第 15、16、17、18 屆中央執行委員", "• 獅子會、扶輪社、國際同濟會會長", "• 綠色和平電台主持人", "• 內政部宗教諮詢委員會諮詢委員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p54ba4cd655','p54ba4cd655','platform','2022-11-26','{"district_id": "tpe-council-02", "election": "2022-local", "office": "tpe_councilor", "text": "婦幼代言人\n1. 擴大辦理國小學童營養午餐有機米及有機蔬菜。搭配牛奶或優酪乳。\n2. 爭取二到四歲幼兒私幼每學期補助20,000元。\n3. 打造英語友善城市，推動南港優先示範區，擴大辦理英語夏令營。\n4. 打造親子科學數位圖書館，持續推動親子生物數位圖書館。\n5. 持續推動親子爆米花電影院結合市圖行動書車推廣閱讀。\n市政大建設\n1. 推動南港六本木結合東區門戶計畫，打造台北新都心，建立南港空橋連接系統，自中國信託到南港車站到北部流行音樂中心，再到南港\n機廠社會住宅。\n2. 爭取 「捷運信義線東延地下化」 從玉成公園至南港國宅再到中央研究院，成功獲得市府回應延伸至廣慈 / 奉天宮站規劃案已留設尾軌（設\n於中坡南路下方），在工程上已保留具有續行延伸至中研院地區之可行性，持續推進中。\n3. 成功爭取南港13個工業區變更為 「產業生活特定專用區」，開發期程再展延自變更公告後開始算起六年、工二用增額容積提高獎勵到\n400%，將持續檢討一二類老舊建物認定標準，爭取全面放寬。\n4. 設置義民廟並發展更具特色的客家文化主題園區。\n5. 推動設備完善的幸福友善銀髮養生村。\n樂活好幸福\n1. 持續推動寵物運動公園設施再升級。舉辦毛小孩運動會。變裝趴、愛心美容健檢等專屬活動。\n2. 65歲以上申請敬老悠遊卡或愛心悠遊卡，使用點數倍增，持卡每月免費1000點，並擴大點數可使用範圍。\n3. 關心內湖復育園區設施，爭取舉辦親子活動。\n4. 活化世大運網球場。\n5. 增加活化商圈行銷活動；強化青年創業輔導；保障新住民就業及社會保險權益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p54ba4cd655','p54ba4cd655','profile','2022-11-26','{"education": ["• 美國加州大學 Fullerton 分校 MBA 碩士", "• 美國南加州大學 (USC)", "• 中山女高", "• 誠正國中", "• 南港國小"], "election": "2022-local", "experience": ["• 英國里茲大學博士研究", "• 第十、十一、十二、十三屆台北市議員", "• 台北市婦女會常任理事", "• 中國國民黨婦女部主任", "• 任務型國大代表", "• 景文技術學院、北台科技學院講師"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pa2aee439f8','pa2aee439f8','profile','2022-11-26','{"education": ["⊙麗山國小", "⊙西湖國中", "⊙景文高中", "⊙真理大學財經法律學系"], "election": "2022-local", "experience": ["⊙國立台灣大學碩士生", "⊙黃珊珊團隊 Since 1998(24 年 )", "⊙台灣民眾黨北市黨部副主委", "⊙ 2020 九合一大選民眾黨發言人", "⊙蔡壁如委員辦公室", "⊙林國成議員辦公室", "⊙台北市後備指揮部組長", "⊙麗山國小校友會會長", "⊙中華民國動物福利環保協進會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p499663cb96','p499663cb96','profile','2022-11-26','{"education": ["• 國立臺北大學企業管理學系", "• 台北市私立東山高中", "• 台北市立西松國中", "• 台北市立西松國小"], "election": "2022-local", "experience": ["• 台灣大學政治系研究所（就讀中）", "• 台北市議員張茂楠辦公室主任", "• 民主進步黨全國黨代表", "• 台灣青年公民參與協會創會理事", "• 台北市西松高中校友會常務理事", "• 台北市苗栗縣同鄉會秘書長", "• 社團法人台北市銀髮族協會秘書長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p6925e37a0b','p6925e37a0b','platform','2022-11-26','{"district_id": "tpe-council-03", "election": "2022-local", "office": "tpe_councilor", "text": "續 5 屆共 20 年，錫欽持續兌現承諾，做到 「全勤」 出席率 ( 除防疫隔離 )、「全職」24 小時投入，以及 「全方位」\n問政表現，將您的大小事 「用心看戴」！\n錫欽已經為您做到：\n1. 成功催生 You Bike 並精進 2.0 版，使 You Bike 成為台北之光、台灣之光。\n2. 成功爭取永春陂濕地公園，兼具生態、環保、教育及滯洪等多功能。\n3. 成功在信義計畫區爭取第一座狗活動區，為狗狗打造鑽石級活動場域。\n4. 成功爭取松菸水稻田，提供北市孩童食農教育優質學習環境。\n5. 成功推動松山區延壽國宅都市更新，並要求擴大都更獎勵及提升效率。\n6. 成功協助基隆路台泥預拌廠遷址，提升週邊生活環境品質。\n未來錫欽將繼續 「戴動台北」，為您做到：\n1. 善盡議員職責，並承先啟後，提升整體議會問政品質。\n2. 致力城市生態永續發展，監督市府相關施政建設配套。\n3. 繼續優化 You Bike 為 3.0 版，落實節能減碳新生活。\n4. 為友善動物城市持續發聲，創造寵物、飼主及市民三贏。\n5. 監督市府改革都市更新沈疴，提高容積獎勵、提升效率、擴大公辦都更。\n6. 擴大生育及托育照護補助，減輕年輕夫妻負擔，解決少子化危機。\n7. 推動北市為敬老、尊老的長者樂園，增加老人照護相關經費。\n8. 減少人口流失，責成市府新團隊提出具體方案，再創北市競爭力。\n9. 重視新住民需求，營造友善、和諧、前進的多元社會價值。\n10. 持續堅持 「全勤全職全方位」 問政理念。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p6925e37a0b','p6925e37a0b','profile','2022-11-26','{"education": ["• 淡江大學國際事務與戰略研究所法學碩士", "• 東吳大學政治系法學士", "• 成功高中", "• 永吉國中", "• 永吉國小", "• 永春國小"], "election": "2022-local", "experience": ["• 第 9 至 13 屆台北市議員", "• 國民黨文傳會副主委兼發言人", "• 博愛國小及東山高中家長會長", "• 市議會法規委員會第二召集人", "• 市議會教育交通財建工務等委員會第一召集人。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p6da9705b68','p6da9705b68','profile','2022-11-26','{"education": ["• 永春國小", "• 永吉國中", "• 祐德高中", "• 中華技術學院二技部", "• 崇右技術學院二專部", "• 淡江大學大陸研究所"], "election": "2022-local", "experience": ["• 綠色和平電台主持人", "• 台北市彰化同鄉會顧問", "• 台北市活力旺聯誼會理事", "• 2008 總統大選長昌競選總部全國組織部執行長", "• 謝長廷競選台北市長競選總部副總幹事", "• 立法委員卓榮泰、徐國勇辦公室主任", "• 第十、十一、十二、十三屆台北市議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p3092978976','p3092978976','profile','2022-11-26','{"education": ["• 中國文化大學中國文學研究所博士", "• 台灣大學政治系碩士", "• 輔仁大學中國文學研究所碩士", "• 淡江大學中國文學系學士", "• 桃園武陵高中", "• 桃園新明國中", "• 桃園富台國小畢業"], "election": "2022-local", "experience": ["• 第 4、5 屆立法委員", "• 第 6、7、11、12、13 屆台北市議員", "• 任務型國大代表", "• 台北縣觀光旅遊局局長", "• 中國文化大學助理教授", "• 淡江大學講師", "• 聯合報主編"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p369c0f3b74','p369c0f3b74','platform','2022-11-26','{"district_id": "tpe-council-03", "election": "2022-local", "office": "tpe_councilor", "text": "1. 已成功爭取3歲、4歲私托補助及公托及非營利幼兒園建置，同為照顧0歲至2歲嬰幼兒，持續要求政府增設托嬰中心及多元化補助政策。\n2. 發展多元學習管道，積極推動官方第二美語政策，要求增加雙語教學制度、與強化特色學校的設立，並推動國際姐妹市學童交流。\n3. 積極協助推動學校成立棒球、足球校隊，培育選手強化足球與棒球根基，與協助建置國手培養的升學管道。\n4. 增加毒品防治政策預算，強化緝查與推動立法強制感化機制，建置防護網預防毒品進入校園殘毒年輕學子。\n5. 嚴格把關校園營養午餐並建置安全食品供應鏈，讓學童吃的放心；推動老舊校舍改建，維護學童就學安全，藉由改建爭取興建地下停車\n場，規劃獨立出入口讓學童安心上課。\n6. 爭取擴大不孕症的補助，包含年齡放寬及取卵次數的增加等項目。\n7. 積極推動台灣無形與有形文化資產古蹟保存；爭取松菸文化園區與台北機廠鐵道博物館串連與活化再利用，讓文化價值與人文資源得以\n傳承\n8. 積極推動都市更新及老屋更新，協助文化藝術及活力注入社區型塑新風貌，並爭取放寬老舊房屋附掛電梯或爬梯機之條件及法規。\n9. 鼓勵都更加速，爭取大眾運輸導向型發展 TOD 升級版，將公共建設的 「社會住宅」 周邊 500 公尺範圍納入都更推動區，提高容積獎勵\n回饋公共空間設置托嬰托老設施。\n10. 已爭取完工的健康公宅、動工中的廣慈公宅與即將發包的三興公宅及六張犁公宅規畫及興建預算超過 315 億元，並爭取降低住宅租金費\n用，未來也會持續協助中央住都中心興建社宅數量。\n11. 以尊重民意協助推動催生民生汐止線興建；積極爭取中央預算補助捷運南北向東環段興建，建置完整捷運路網，改善信義區縱向交通便利。\n12. 已爭取台北市動物保護專戶設立，由動保處規劃設立執行方針，擴大動物救援、媒合民間協助，以利動保資源整合。\n13. 針對虐待動物累犯已正式提案除加重處分及刑事責任外，並須強制接受感化，協助中央與地方推動立法。\n14. 法制化寵物飼養與照顧指南，提升飼主的責任；並建立其他非犬貓小動物絕育補助、及收容場所的規劃。\n15. 已完成推動限塑、廚餘減量及再生、太陽能建置等友善環境政策，持續推動綠能能源政策並爭取汰換電動汽、機車補助金額提高。\n16. 持續推動市府閒置空間作為青年創業辦公室及青年創業貸款零利率，鼓勵青年創業。\n17. 支持國內服裝設計產業，全力媒合在地設計師與國際接軌；推動時尚設計平台，提供設計師由校園育成階段至創業之協助。\n18. 落實長照在地化，建置社區照護機構爭取照服員居家照顧，並持續要求市府恢復發放重陽敬老禮金及推動滿65歲長者假牙補助與視力健檢。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p369c0f3b74','p369c0f3b74','profile','2022-11-26','{"education": ["• 國立臺北藝術大學文化資產與藝術創新博士", "• 國立臺北教育大學文化創意產業經營學系碩士", "• 世新大學傳播研究所碩士"], "election": "2022-local", "experience": ["• 臺北市議會第十至十三屆議員", "• 民進黨中央常務委員", "• 臺北市議會民進黨團總召", "• 財團法人文化臺灣基金會董事", "• 財團法人礦工兒子教育基金會董事", "• 世界彰化同鄉會總會副秘書長", "• 中華民國迷你足球協會推廣大使", "• SPCA 台灣防止虐待動物協會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p4cf586308f','p4cf586308f','platform','2022-11-26','{"district_id": "tpe-council-03", "election": "2022-local", "office": "tpe_councilor", "text": "以前我看到選舉公報裡的政見時，雖然每位候選人都洋洋灑灑列了一大堆政見，但如何具體實行卻付之闕如。在有限的表格空間\n內，我將最主要的三個政見寫上，其餘的請大家參見我的臉書專頁（搜尋 : 詹為元 政治我們的事 )\n1、建立信任感 加速都更進度\n台北市的屋齡已是六都當中最老的，四十年以上的老舊公寓佔了 43.95%。而松山區與信義區的屋齡分列北市十二個行政區中\n的二、三名 ! 看著年長者面對老舊公寓 「望樓梯興嘆」，擁有電梯的嶄新房子刻不容緩。都市更新除了容積獎勵以及釘子戶\n等艱難的問題之外，更重要的是彼此之間的 「不信任感」，民眾不信任民間建商擔心他們私藏利潤，但政府主導的公辦都更\n又曠日廢時。因此，我提出的政見是導入都更中心成立第三方的監察與仲裁人的角色，透過專案式的管理進入每一個民間都\n更案，民眾有問題即可請教負責該案的都更中心官員，透過一定公權力的背書來降低民眾與建商之間的不信任感，加速都更\n的進行。\n2、0-6 歲政府加倍養 公托再增設\n目前政府育兒政策皆從補貼著手，但根本的問題還是學費太貴了。以目前兩歲以下的托嬰中心來看，公辦民營的托嬰中心雖\n然學費最便宜 1.1 萬元，但松山區僅有 85 位的名額，信義區更僅有 40 位而已，根本不夠用。社區公共托育家園雖也是次便宜\n約 1.45 萬元，但松山區只有 2 家、信義區只有 3 家，隔壁的文山區卻有 10 家。準公共化的托嬰中心雖名稱有公共性質，但學\n費已飆升兩倍到 2.1 萬元，更別提私立托嬰中心了。因此，我提出的政見是將托嬰中心市場化，價格較貴的私立托嬰中心自由\n發展，但政府應提供最低比例的的公共托嬰中心，例如仿照德國將幼兒的托育服務覆蓋率至 35%，提供新手爸媽一個平價友\n善的托嬰環境。\n3、毛小孩的保護與遊憩自由\n動保警察設立雖是内政部的權責，但中央始終只聞樓梯響，因此台北市可以優先試辦成立，給予調查權，未來面對動物虐待\n情事可以更快抓到兇手；另外就是松山信義區的寵物專用公園太少了，幾個比較大的社區公園都應該劃定寵物公園專區，例\n如信義區中強公園、松山區敦北公園等以不影響現狀運動團體場地為主，讓毛小孩能解開繩子的束縛開心的遊憩。\n剩下政見諸如推動台北成為 NFT Taipei 的亞洲示範城市、加速 Youbike1.0 與 2.0 的整合、重視長者權益打造銀髮友善城市……\n請見臉書。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
