INSERT INTO "fact" VALUES('profile:2022-local:p9ff03a516c','p9ff03a516c','profile','2022-11-26','{"education": ["• 台北市中山國小", "• 台北市衛理女中國中部", "• 台北市泰北高中廣告設計科", "• 台南應用科技大學美術系學士"], "election": "2022-local", "experience": ["• 臺北市政府 柯文哲市長隨行秘書", "• 臺北市政府 副發言人", "• 台灣民眾黨 創黨發言人", "• 三立電視台 行銷公關", "• 台北市議員林國成 特別助理", "• 銘傳大學管理學院 EMBA 碩士班"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p41a7902cc9','p41a7902cc9','profile','2022-11-26','{"education": ["銘傳大學新聞學系"], "election": "2022-local", "experience": ["• TVBS 主播", "• TVBS 主持人", "• TVBS 政治記者", "• 臺灣大學政治研究所（就讀中）"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pdbfe9d98cc','pdbfe9d98cc','platform','2022-11-26','{"district_id": "tpe-council-04", "election": "2022-local", "office": "tpe_councilor", "text": "（一）守護長輩：爭取假牙、老花眼鏡及助聽器等各項補助。\n（二）婦女保障：補助婦女凍卵及各項健檢免費補助。\n（三）兒童教育：落實學齡前教育義務化。\n（四）青年政策：敦促市府設青年局，幫助青年圓夢，生涯發展。\n（五）完善醫療：提升市立聯合醫院成為醫學中心。\n（六）民生汐止：加速推動並增設捷運民生西路、重慶北路站。\n（七）大圓環站：增設捷運圓環站，活絡圓環商圈。\n（八）社子輕軌：爭取民族西路輕軌站，延伸路網至臺北車站。\n（九）淡水河岸：發展大稻埕水岸人文園區。\n（十）廢除一殯：爭取區域再造。\n（十一）文創平台：加強傳統藝術、文化與世界文創業交流。\n（十二）公園活化：完善花博、河濱、新生公園機能。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pdbfe9d98cc','pdbfe9d98cc','profile','2022-11-26','{"education": ["• 中山國小", "• 大直國中", "• 景文高中", "• 崇右技術學院（二年制畢）"], "election": "2022-local", "experience": ["• 臺北市議會第 13 屆副議長", "• 第 11、12、13 屆臺北市議員", "• 淡江大學大陸研究所碩士生", "• 國民黨中央委員", "• 國民黨全國青工會副總會長", "• 國民黨台北市黨部副主委", "• 國民黨青年團台北市團長", "• 臺北市體育總會副總會長", "• 臺北市里長聯誼會總會長", "• 臺北市大同區體育會理事長", "• 臺北市中山區圓山里里長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc164e1064f','pc164e1064f','profile','2022-11-26','{"education": ["• 東海大學中文系", "• 泰北高中", "• 明倫國中", "• 大龍國小"], "election": "2022-local", "experience": ["1 台灣大學 EMPA 政治學系研究所在學\n2 第十三屆台北市議員\n3 民進黨台北市黨部執行長\n4 2016 蔡英文總統競選辦公室行政組主任、2012 財委會專員\n5 游錫堃辦公室秘書\n6 簡余晏辦公室助理\n7 蘇貞昌市長競選辦公室文宣部\n8 嘉義旅北同鄉會水上分會幹事\n9 新北市宜蘭同鄉會行政助理"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pfd93c2126e','pfd93c2126e','platform','2022-11-26','{"district_id": "tpe-council-04", "election": "2022-local", "office": "tpe_councilor", "text": "一、改善台北停車問題\n・爭取於校園改建時增設地下停車場，創造更多停車空間。\n・推動更新現有老舊立體停車場、增設新式機械停車場。\n・推動公有停車場運用車牌辨識系統驗證資格，讓全部在地里民皆享有停車優惠。\n二、打造友善育兒城市\n・推動台北市聯合醫院婦幼院區升格兒童醫院，強化兒童醫療。\n・爭取新設服務業家長適用時段之公托，讓更多家長可享受公托福利。\n三、打造寵物友善城市\n・爭取增設狗狗活動區，讓飼主可就近帶寵物放風。\n・推動寵物友善交通運輸，讓中大型犬也能便利出門。\n四、活絡市場商圈發展\n・爭取傳統市場優化整建，為市場注入新活力。\n・爭取市府協助商圈發展特色，再創地方繁榮。\n五、推動民生汐止線\n・督促市府加速捷運興建工程，提供居民便捷交通並促進沿線商圈發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
