INSERT INTO "fact" VALUES('profile:2022-local:pc50235ea45','pc50235ea45','profile','2022-11-26','{"education": ["• 文化大學政治系", "• 百齡高中", "• 建成國中", "• 靜心國小"], "election": "2022-local", "experience": ["• 民進黨發言人", "• 蔡英文競選連任辦公室發言人", "• 民進黨中央黨部青年部主任、新聞輿情部主任", "• 台北市第 12 屆市議員", "• 政大法研所在職碩班"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pa0224cb763','pa0224cb763','platform','2022-11-26','{"district_id": "tpe-council-05", "election": "2022-local", "office": "tpe_councilor", "text": "1. 推動容積獎勵提升、老舊社區公辦都更，加速城市更新\n2. 提升社會住宅建設量，調降租金、讓青年、弱勢優先承租\n3. 監督捷運萬大線施工品質與工程進度，確保 2025 年完工通車\n4. 提高北市托育品質，增加幼托人員待遇，讓好人才留在台北市\n5. 推動校舍改建、提升教育資源，同時提升學區鄰近社區更新動能\n6. 增設寵物友善空間、寵物運動公園，打造毛孩宜居城市\n7. 整合觀光資源，發展各區特色觀光，聯合觀光推廣讓效益 1+1>2\n8. 持續推動洛陽停車場及西寧國宅聯合開發，順利改建，成為淡水河岸新地標\n並帶動台北西區新活力", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pa0224cb763','pa0224cb763','profile','2022-11-26','{"education": ["• 美國印弟安那州立大學政治學碩士", "• 國立成功大學學士", "• 世界新聞專科學校公共關係科畢業"], "election": "2022-local", "experience": ["• 台北市議會第九、十、十一、十二、十三屆議員", "• 台北市議會民進黨團總召集人", "• 台北市議會民進黨團幹事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pefa8e31df3','pefa8e31df3','profile','2022-11-26','{"education": ["美國 菲力狄克森大學資管碩士"], "election": "2022-local", "experience": ["• 台北市議會黨團副書記長", "• 中國國民黨中央常務委員", "• 伯仲文教基金會副執行長", "• 台北市中原客家崇正會理事長", "• 台北市政府客家事務委員會委員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p62ab44979e','p62ab44979e','platform','2022-11-26','{"district_id": "tpe-council-05", "election": "2022-local", "office": "tpe_councilor", "text": "一、「台北監督連線」 民生第一 4 大主張\n1. 推動公共托育：增加公共托嬰設施、公立與非營利幼兒園，減輕家長負擔。\n2. 保障青年樂業：提高青年創業貸款額度；擴大企業實習策略聯盟。\n3. 廣建公共住宅：公共住宅結合公共與社福設施，打造特色公宅；加速危老建築重建；提升社會住宅戶數。\n4. 增設樂齡照護：65 歲以上長者免掛號費，擴大敬老卡使用範圍；增加日照中心，到府沐浴車服務，老\n有所終。\n二、個人政見：已實現長者免繳健保費、議會質詢網路直播等多項公開透明政見，展望未來冀望達成以\n下目標\n1. 支持 18 歲公民權修憲：全球已一百多個國家，用法律保障 18 歲公民權，籲請支持台灣進步的力量。\n2. 推動分包商在驗收後 30 日內取得報酬：參酌歐盟法 (Directive 2011/7/EU on combating late\npayment in commercial transactions) 以及美國聯邦政府之 US Prompt Payment Act 規定，確保\n政府採購所有下包商在 30 日內取得報酬，避免統包商挾其市場影響力，對下游分包商款項拖欠，違背\n公平交易精神並危及中小微企業與其職工之生存權。\n3. 推動降稅措施：這三年來受疫情重創，應對於娛樂稅、營業稅採優惠稅率措施，恢復昔日消費人潮與\n榮景。\n4. 向中央爭取財稅合理：牌照稅為地方稅，稅率中央明訂，中低收基本交通工具稅，多比房屋稅高，實\n有檢討必要。\n5. 支持廣建共融式遊戲場；淘汰老舊設施，加強安全維護，拓展市民休閒空間。\n6. 強化勞資爭議平台，督促勞工權益、職業安全衛生等教育訓練，以提升職場環境安全衛生及勞僱和諧。\n7. 持續監督打擊詐騙：率先質詢出國打工淪詐騙犯問題，要求科技辦案，強化消費者保護，確保市民財\n產。\n8. 要求合理建管政策：漏水鑑定金額過高，市民無法負擔，應予調降，頂樓加蓋政策相較其他五都仍有\n檢討必要。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p62ab44979e','p62ab44979e','profile','2022-11-26','{"education": ["• 台中二中", "• 臺北大學夜間部法學士", "• 臺灣大學法學碩士"], "election": "2022-local", "experience": ["• 「台北監督連線」 中正萬華參選人", "• 律師", "• 立法院資深助理", "• 真理大學財經系講師", "• 青雲科技大學講師", "• 法律扶助基金會律師", "• 民間司改會執行委員", "• 台北律師公會第 25 屆監事", "• 2011 青商總會國家副總會長", "• 台北市翻譯商業同業公會理事長", "• 中正一分局義警大隊副大隊長", "• 國立臺北大學法學院傑出院友。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
