INSERT INTO "fact" VALUES('profile:2022-local:p06dbec1b42','p06dbec1b42','profile','2022-11-26','{"education": ["• 中國文化大學青少年兒童福利研究所", "• 輔仁大學統計系", "• 辭修高中", "• 大理女中", "• 西園國小"], "election": "2022-local", "experience": ["• 台北市議員", "• 台北市婦女會常務監事", "• 李仁人議員特助", "• 救國團台北市團委會指導委員", "• 台北市新移民女姓關懷協會常務理事", "• 台北市朝陽社會關懷協會理事長", "• 臺北市萬華區體育會理事長", "• 世界及台北市郭氏宗親會常務理事", "• 中華民國新青溪協會理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd697b2a2b5','pd697b2a2b5','platform','2022-11-26','{"district_id": "tpe-council-05", "election": "2022-local", "office": "tpe_councilor", "text": "一、推動都市更新，放寬容積，增加樓地板面積，讓老舊社區更有都市更新意願並\n拆除釘子戶。\n二、市有土地活化，建構青年住宅，完成青年住者有其屋。\n三、主張廢除 12 年國教入學方式，恢復基測，減輕學子痛苦。\n四、主張立刻發放 1,500 元重陽敬老津貼。\n五、小平路平，爭取九十處道路重新銑鋪及側溝更新、同安街新建電梯、中華路景\n觀人行天橋及舊環南高架橋墩美化改善、水源永春天橋彩繪，落實地方建設。\n六、成立多處 YouBike 微笑單車及智慧型公車站亭，銜接回家最後一哩路。\n七、督促中正區、萬華區各里衛生下水道工程銜接、修護及後巷美化。\n八、爭取多處公園綠美化及園內各項休閒設施設置。\n九、興建青年公園首座頂棚籃球場，於 4 號出口改建共融遊戲場及體健設施、增設\n座椅、路燈、導擺步道及修護園路。\n十、爭取中正區首座古亭狗公園活動專區。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd697b2a2b5','pd697b2a2b5','profile','2022-11-26','{"education": ["國立臺灣大學政治研究所碩士"], "election": "2022-local", "experience": ["• 臺北市議員", "• 臺北縣議員", "• 財團法人流浪動物之家基金會董事長", "• 臺北市福安國中地理老師", "• 臺北市青年楷模", "• 大學籃賽大學明星球員", "• 中華民國三分球紀錄保持人"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p155e15fe02','p155e15fe02','profile','2022-11-26','{"education": ["私立輔仁大學醫學院護理學系\n畢業"], "election": "2022-local", "experience": ["• 國立臺灣大學 EMBA 碩士在職專班 110 級國企組在學。", "• 中華航空機長，飛行經歷 20 年，飛行時數超過 15000小時。", "• 台北市義消總隊金華義消分隊長，義消經歷 30 年，拯救無數生命。", "• 社團法人中華民國救助技術諮詢與發展協會理事長。", "• 臺大醫院急診醫學部研究助理。", "• 四個孩子的奶爸，老婆的依靠"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:p7dbdadb454','p7dbdadb454','platform','2022-11-26','{"district_id": "tpe-council-06", "election": "2022-local", "office": "tpe_councilor", "text": "一、翻轉都市更新流程，增加都市更新誘因。活化故宮國寶資源，台北國際觀光城市。\n1. 檢討簡易都更流程，加速老舊社區重建，利用提高獎勵鼓勵高齡社區住戶加速整合並解決釘子戶問題，改善台北居\n住品質落實都市更新。\n2. 善用中華文化文物資源，台北市應利用故宮國寶增設地標型建築博物館與美術館、活化閒置土地 ( 如空總 )，提升\n觀光與經濟產值，讓台北成為華人世界的觀光、藝術、文化首都。\n3. 雙北合作，推動景美溪與新店溪流域整治。\n二、創新規劃，改善交通動線。永續環境，調整土地負載。\n1. 解決辛亥隧道壅塞，二殯新路明年完工，將紓解交通動線。\n2. 加速推動捷運南環線工程以及捷運東環段，落實公車站牌全面數位化。\n3. 增建地下停車場，充電停車格法規優先改專用，檢討街道紅、黃線規劃。\n4. 加速公私墓遷移，落實山坡綠美化與水土保持。\n三、優化教育，引入資源。社區合作，落實終身學習。\n1. 持續增設公立托育機構，廣設校園課後安親班。\n2. 深化雙語以及程式教育，增進邏輯能力。\n3. 結合里辦公室及社區發展協會，營造終身學習環境。\n四、服務鄰里，強化社區治安。弱勢照護，創造安心環境。\n1. 結合里巡守隊，維持監視器妥善率，社區緊急安全鈕，落實即時通報，強化治安。\n2. 繼續電線桿及變電箱地下化工程，保障用路安全。\n3. 科技協助輪椅族權益，落實無障礙以及大眾運輸友善環境。\n4. 增設公辦民營長照機構，讓青年安心工作。\n五、檢討法令，確保執法正當性。簡化程序，提升政府效率。\n1. 建構市民與市府雙向溝通平台，簡化行政流程，增進施政效能。\n2. 檢討不合時宜法令，剷除惡法，保障公務體系執法正當性。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:p741562d334','p741562d334','profile','2022-11-26','{"education": ["• 台大企管碩士", "• 台大工商管理系學士"], "election": "2022-local", "experience": ["• 台積電卓越工程師獎，並領有多項專利獎項", "• 立法委員賴士葆青年總顧問", "• 中華愛傳資訊媒體發展協會秘書長", "• 下一代幸福聯盟理事長", "• 大安區龍安國民小學家長會會長", "• 臺北市國小學生家長會聯合會理事、性別平等教育委員會總召", "• 著有《用對愛之語》、《這樣養寵物，家庭超幸福》等暢銷書"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pc524c2d6ef','pc524c2d6ef','platform','2022-11-26','{"district_id": "tpe-council-06", "election": "2022-local", "office": "tpe_councilor", "text": "一、公費長照\n降低公費補助門檻、提高補助金額、擴大私立長照機構補助範圍。\n二、保障青年入企實習名額\n凡台北市公共工程、大型標案均需雇用 30% 以上本市青年。\n三、凍卵補助、拒絕月經貧窮\n保障女性生育選擇權，凡本市 35 歲以下未生育女性，均可一次性申請凍卵補助，及往\n後 10 年的保存費用。\n四、提高生育補助及育兒津貼\n生育獎勵金提高為第一胎 5 萬、第二胎 6 萬；第 3 胎起，每胎 7 萬，育兒津貼延長為 0 到\n6 歲。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc524c2d6ef','pc524c2d6ef','profile','2022-11-26','{"education": ["• 美國南加大航太機械系碩士", "• 長庚大學機械系", "• 臺北市立成功高級中學"], "election": "2022-local", "experience": ["• 臺北市議員", "• 世新大學兼任助理教授", "• 臺北市議員李新辦公室主任", "• 益鼎股份有限公司核電專案工程師", "• 臺北市幼兒足球協會理事長", "• 臺北市體育總會射擊協會副理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('profile:2022-local:paf86790352','paf86790352','profile','2022-11-26','{"education": ["臺灣大學政治系公共行政組畢業"], "election": "2022-local", "experience": ["• 羅智強辦公室主任", "• 王鴻薇辦公室主任", "• 丁守中競選市長辦公室發言人", "• 國民黨副發言人", "• 國家政策研究會趨勢暨數據分析中心顧問", "• 110 全國性公投意見發表會 - 公投綁大選 - 正方代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
INSERT INTO "fact" VALUES('platform:2022-local:pea1a4317b4','pea1a4317b4','platform','2022-11-26','{"district_id": "tpe-council-06", "election": "2022-local", "office": "tpe_councilor", "text": "【欣儀為您完成】\nⓋ學童搭捷運享 6 折優惠；「班班有冷氣」 冷氣汰換與電費不再由家長募款買單。\nⓋ恢復發放重陽敬老金及老人健保補助。\nⓋ推動北市青年尋職輔導津貼。\nⓋ設置多處捷運雙向電扶梯。\nⓋ辛亥、懷恩隧道壁體美化及更新改善。\nⓋ台北市立圖書館在舊 AIT 結合音樂中心興建；設置大安森林公園共融式遊具。\n【欣儀為您爭取】\n1. 從小顧到老！提高生育獎勵金、增加公托（幼）、社區日照及長照。\n2. 教育是最好的投資！落實雙語及數位教育，學童營養午餐物調差額由市府補足。\n3. 教師權益我維護！增加學生輔導服務津貼及教師升等檢定補助。\n4. 搶救青年失業潮！推動「青年尋職輔導津貼 2.0」、把關就業權益。\n5. 長者照顧智慧化！推動社區長者緊急照護及救援 E 化系統。\n6. 提供弱勢便民服務！敦促市府成立一站式窗口、簡化相關補助手續。\n7. 推動防災型都更修法！放寬山限區「山坡地老舊社區」都更、降低公辦都更門檻。\n8. 行車順暢不再塞！拓寬木柵路四、五段道路用地，推動不合理的交通路型更新。\n9. 力拼交通升級！加速推動「捷運南環段」，增設出口；持續廣設「捷運雙向手扶梯及電梯」。\n10. 打破隧道陰森印象！接續美化「莊敬隧道」壁體。\n11. 打造台北文化新地標！加速推動「大安音樂圖書中心」建設進度，督促舊市圖儘速轉型「社福基地」。\n12. 營造繽紛城市花園！優化「大安森林公園」，打造都會永續棲地。\n13. 落實三貓計畫！設置貓空景觀吊橋、振興貓空產業、減少貓纜虧損。\n14. 行銷台北走向國際！一站式便利申請北市各大景點拍攝、加碼補助新銳影音團隊。\n15. 向英雄致敬！維護警消及醫護權益、提升裝備效能，補足員額。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
