INSERT INTO "fact" VALUES('platform:2022-local:p1a163d6714','p1a163d6714','platform','2022-11-26','{"district_id": "tpe-council-06", "election": "2022-local", "office": "tpe_councilor", "text": "一、健康台北：各行政區增闢運動中心二館，校園夜間開放市民租用，讓市民就近運動。\n二、安全城市：擴大獎勵公辦都更，危老房舍改建，容積增設地下停車場，共創官民雙贏。\n三、青年首都：公托、臨托社區化，減輕雙薪家庭托幼負擔，提高年輕人落籍北市意願。\n四、樂活都會：盤點閒置市有房舍、土地，規劃社區整合型長照、日照與居家服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
