INSERT INTO "fact" VALUES('platform:2022-local:p072095ef7a','p072095ef7a','platform','2022-11-26','{"district_id": "tpe-council-07", "election": "2022-local", "office": "tpe_councilor", "text": "回到 『原』 點、莫忘初衷，建設完善原民新故鄉\n要求 「確實執行臺北市原住民族生活發展自治條例，建立符合我們\n自己的規範。」\n監督 「臺北市原住民族文化創生基地之規劃，提供族人創造及發揮\n的場域。」\n改變 「政策概念應以家及人口數為基礎，才能有效全面照顧」\n持續 「推動原住民族教育，從學齡前至高中職有系統的傳授」\n改善 「原民老人安養安居品質，增加原民家庭臨托顧養彈性，豐富\n提升原民長者生活內容和品質」\n強化 「都會區原住民族認同感，增加原民生存、文化、技藝、語言\n學習管道」\n用台北的力量做出完善適切的原民政策", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/01%E8%87%BA%E5%8C%97%E5%B8%82/%E8%87%BA%E5%8C%97%E5%B8%82%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-09-30T13:59:05Z');
