INSERT INTO "fact" VALUES('interp:AQ14102642:pea1a4317b4','pea1a4317b4','interpellation','2026-09-30','{"councillors": ["王欣儀"], "dept": "交通", "doc_no": "AQ14102642", "doc_type": "書面質詢", "session": "第14屆第08次定期大會", "term": 14, "title": "完善公車身心障礙乘客溝通協助流程及駕駛教育訓練，提升無障礙服務品質。"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=F626A9A3C33FECE0DAEC37626CEDBFBDF4D1149F9F07E2CC8B5F425E168168B00B8C6131082889C3D53A4C142158021656AA3DE9373F58B0','2026-10-01T22:46:29Z');
INSERT INTO "fact" VALUES('summary:14-05:pcb793ad399','pcb793ad399','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:36:44Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=15"}, {"page": 1016, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=20"}, {"page": 1017, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=21"}, {"page": 1018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=22"}, {"page": 1018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=22"}, {"page": 1019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=23"}, {"page": 1019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=23"}], "councilor_points": ["何孟樺議員指出某國小學童發生衝突後，學校隔了4天連假才進行校安通報，且教育局一開始僅依偏差行為處理，未依新修訂之《校園霸凌防制準則》第71條規定即刻立案調查。何孟樺議員要求教育局檢討校安通報延遲狀況，並加強通報時間管理。何孟樺議員建議教育局於校園霸凌防制整體計畫中，強化113年版準則變動部分之教育宣導與督導。"], "response": "教育局局長說明導師最初係以偏差行為處理，家長於4月24日提出申請後已正式立案調查，並於20天內書面告知家長。市長表示教育局一開始係依照相關程序辦理，後續會強化通報時間管理與變動條文宣導。", "response_removed": false, "topic": "校園霸凌防制與通報機制檢討"}, {"citations": [{"page": 3084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665497BB289A06D3DE213DDBAB098C8228A75CBD135B6E516E358A852238F00A7C162#page=9"}, {"page": 3087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665497BB289A06D3DE213DDBAB098C8228A75CBD135B6E516E358A852238F00A7C162#page=12"}, {"page": 3087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665497BB289A06D3DE213DDBAB098C8228A75CBD135B6E516E358A852238F00A7C162#page=12"}], "councilor_points": ["何孟樺議員指出臺北市2026年底前應申報外牆安全之建物共有1,904棟，目前僅申報412棟，進度嚴重落後。何孟樺議員指出已申報案件中需修繕者占近六成且有案件拖延4年未改善，另有21棟發生2次以上外牆剝落之建築未落實申報。何孟樺議員要求建築管理工程處訂定今年度申報目標值與輔導方案、優先輔導多次剝落之建築申報，並建議都市發展局研議針對D級與E級公安疑慮案件提供加碼型修繕補助。"], "response": "建築管理工程處處長說明將按區段分級並直接進社區輔導，亦會清查連續剝落建築，同意訂定今年度目標值與落實方案。都市發展局局長與建築管理工程處處長表示同意帶回研議針對公安疑慮案件之加碼型補助方案。", "response_removed": false, "topic": "建築物外牆安全申報與修繕加碼補助機制"}, {"citations": [{"page": 441, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=8"}, {"page": 441, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=8"}, {"page": 443, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=10"}, {"page": 442, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=9"}, {"page": 444, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=11"}], "councilor_points": ["何孟樺議員指出重慶南路一段有12條公車路線需左轉襄陽路，公車頻繁橫切車道且行人眾多，建議參考紐約第二大道經驗重新配置車道，增設公車專用道與行人庇護島。何孟樺議員建議參考新加坡經驗，於學校與醫院等行人眾多場所周邊之兩線道以下筆直道路，增設減速彎與行人庇護島以促使車輛減速。"], "response": "交通局局長表示重慶南路車道重新配置很有意思，會再進行仔細研究。交通局局長說明目前交通友善區與通學區域規劃皆朝此方向進行，會針對社區小路增設減速彎與庇護島進行努力。", "response_removed": false, "topic": "重慶南路與社區道路交通環境改造"}, {"citations": [{"page": 107, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=2"}, {"page": 108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=3"}, {"page": 109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=4"}, {"page": 108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=3"}, {"page": 109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=4"}], "councilor_points": ["何孟樺議員指出2025雙北世壯運票務系統發生訂單消失、棒球決賽索票卡機導致系統重複給票（原本限索4張卻給8張），以及日韓外語網站僅翻譯標題等問題。何孟樺議員指出廠商發信通知超額索票時未以密件副本寄送，導致民眾電郵個資洩漏，涉及違反《個人資料保護法》及契約規定。何孟樺議員要求產業發展局檢討測試流程與招標規格漏洞，並依約要求廠商檢討個資保護及將案件移送相關單位。"], "response": "產業發展局副局長說明購票系統有進行壓力測試，索票卡機係因評估不會有瞬間大流量而未於規格中特別規範。產業發展局局長與副局長承認未用密件副本發信屬廠商疏失，承諾會依約要求廠商檢討個資保護並進行處理。", "response_removed": false, "topic": "世壯運線上票務系統故障與個人資料洩漏檢討"}, {"citations": [{"page": 880, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494B45F90DCEF9BE6109CB2E9097E3B7FD7AA12815378EF354A852238F00A7C162#page=3"}, {"page": 880, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494B45F90DCEF9BE6109CB2E9097E3B7FD7AA12815378EF354A852238F00A7C162#page=3"}, {"page": 881, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494B45F90DCEF9BE6109CB2E9097E3B7FD7AA12815378EF354A852238F00A7C162#page=4"}], "councilor_points": ["何孟樺議員指出臺北市有15.4%人口（約40萬人）將台語當作首要語言，但市府缺乏專責單位與專職人力推動《國家語言發展法》事務。何孟樺議員建議秘書處、研究發展考核委員會與人事處研議設置專責單位、成立府級會報及建立核考機制。何孟樺議員建議民政局訂定辦法加碼補助里辦公處及區公所辦理國家語言活動，並鼓勵文宣採用標準書面用法。"], "response": "秘書長表示會針對成立專責單位等事項進行研究。民政局局長說明目前已有相關規劃並請區公所宣導補助，同意帶回研議國家語言加碼補助辦法。", "response_removed": false, "topic": "國家語言發展法專責單位建置與跨局處推動"}, {"citations": [{"page": 495, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=1"}, {"page": 496, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=2"}, {"page": 497, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=3"}], "councilor_points": ["何孟樺議員指出市面上現泡咖啡自動販賣機未依法標示登錄字號與牛奶過敏原等資訊，且衛生局近2年稽查數量波動大，缺乏固定清單。何孟樺議員指出衛生局過往稽查對象有三分之二來自商業處移案之選物販賣機，顯示未全面掌握食品自動販賣機設置狀況。何孟樺議員要求衛生局與商業處合作宣導食安知識、輔導規模化廠商，並建立自動販賣機納管清單與廠商主動登錄機制。"], "response": "衛生局局長與食品藥物管理科科長說明不合格者會要求限期改善，未來會持續對選物及冷藏販賣機加強稽查輔導。衛生局局長表示同意與商業處合作宣導，並將研議建立納管清單與廠商主動登錄機制。", "response_removed": false, "topic": "自動販賣機食安標示與納管稽查機制"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-09"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=10", "transcript_pages": [1006, 1007, 1008, 1009, 1010, 1011, 1015, 1016, 1017, 1018, 1019, 1020, 1021, 1022, 1023, 1024], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD