: "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC16A161F81D9FFA0E4ED6AE014B94985465CCBD84475479F76A852238F00A7C162#page=7", "transcript_pages": [1738, 1739, 1740, 1741, 1742, 1743, 1744, 1745, 1746, 1747], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC16A161F81D9FFA0E4ED6AE014B94985465CCBD84475479F76A852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 5}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=1", "transcript_pages": [106, 107, 108, 109, 110, 111, 112, 113], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 16}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=6", "transcript_pages": [439, 440, 441, 442, 443, 444, 445], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162", "videos": [{"date": "2025-05-26", "group": 14}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162','2026-10-01T09:36:44Z');
INSERT INTO "fact" VALUES('summary:14-05:pccc2308c1b','pccc2308c1b','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T02:06:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1130, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162#page=2"}, {"page": 1131, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162#page=3"}, {"page": 1131, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162#page=3"}], "councilor_points": ["侯漢廷議員指出中央違法扣減地方補助款，要求臺北市政府採取緩慢執行中央委辦任務、重新實施禁萊豬自治條例、警方不介入政治陳抗、增訂酒駕等重罪鞭刑自治條例，以及限制反對預算之民代服務等五項具體手段反制中央。"], "response": "臺北市市長說明最重要是中央違法剋扣地方補助款，希望中央依法將核定款項撥給地方，不需要造成中央與地方對抗。", "response_removed": false, "topic": "中央扣減地方補助款之因應措施"}, {"citations": [{"page": 302, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654951E72A3DD27F4F5551B3640C9264FEA6118D42A557D363C7A852238F00A7C162#page=1"}, {"page": 303, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654951E72A3DD27F4F5551B3640C9264FEA6118D42A557D363C7A852238F00A7C162#page=2"}, {"page": 304, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654951E72A3DD27F4F5551B3640C9264FEA6118D42A557D363C7A852238F00A7C162#page=3"}, {"page": 305, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654951E72A3DD27F4F5551B3640C9264FEA6118D42A557D363C7A852238F00A7C162#page=4"}], "councilor_points": ["侯漢廷議員指出臺北市長照住宿式機構收費基準已14年未修訂。侯漢廷議員建議市府依物價指數調整上限、提供申請範本，並放寬價格上限與相關管制，回歸市場機制以吸引業者投入長照產業。"], "response": "衛生局局長說明正在蒐集29家機構現況進行研議修正。衛生局局長表示會強化市場機制，在政府監督與市場運作間取得平衡。", "response_removed": false, "topic": "長照住宿式機構收費基準放寬"}, {"citations": [{"page": 1799, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1B63265DACD4722EFF8DE4F1DB28A6985F511D5DE830B2B2BA852238F00A7C162#page=3"}, {"page": 1800, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1B63265DACD4722EFF8DE4F1DB28A6985F511D5DE830B2B2BA852238F00A7C162#page=4"}, {"page": 1800, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1B63265DACD4722EFF8DE4F1DB28A6985F511D5DE830B2B2BA852238F00A7C162#page=4"}], "councilor_points": ["侯漢廷議員指出草山行館業者未獲核准即公開宣傳民宿開業、使用明火及增設違建，監督機制有所缺失。侯漢廷議員要求市府禁止業者開設民宿、嚴格監督違規行為，並應強化歷史文史展覽與陳列。"], "response": "文化局局長表示不允許業者開設對外營業之民宿，並承諾要求業者以文史為導向帶動營運。觀光傳播局局長亦表示同意。", "response_removed": false, "topic": "草山行館營運轉型與文史保存"}, {"citations": [{"page": 332, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10E21A52356DFEC374D30CC401D61EE9042C6F169D9BA4DD1A852238F00A7C162#page=3"}, {"page": 333, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10E21A52356DFEC374D30CC401D61EE9042C6F169D9BA4DD1A852238F00A7C162#page=4"}, {"page": 334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10E21A52356DFEC374D30CC401D61EE9042C6F169D9BA4DD1A852238F00A7C162#page=5"}], "councilor_points": ["侯漢廷議員指出民營停車場電動汽車充電車位設置達成率僅有7.6%，並指出市府以廢止營業登記證要求業者設置缺乏法律授權。侯漢廷議員要求撤銷該處分，並建議由車商出資設立補助專款、設計合理的充電收費機制或設立替代繳付制度。"], "response": "交通局局長坦言先前之解釋存在不合理之處並承諾進行檢討，亦表示會向中央反映車商分擔費用等實務建議。", "response_removed": false, "topic": "電動汽車充電車位設置與處分檢討"}, {"citations": [{"page": 1140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162#page=12"}, {"page": 2902, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493D26B7B3A768403DF26CA722D065A6D7958AC4F67347F01EA852238F00A7C162#page=1"}, {"page": 2904, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493D26B7B3A768403DF26CA722D065A6D7958AC4F67347F01EA852238F00A7C162#page=3"}], "councilor_points": ["侯漢廷議員指出工務局代辦工程金額高達1,285億元，造成基層同仁超時工作與缺額嚴重。侯漢廷議員要求將代辦業務納入預算與員額評估、合理分配案件，並建立專屬獎勵機制。"], "response": "工務局局長表示相關意見公正客觀，將帶回府級進行檢討與改善。", "response_removed": false, "topic": "工務局工程代辦業務人力分配"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-10"], "dept": null, "doc_type": "市政總質詢", "group": 15, "heading": "市政總質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162#page=1", "transcript_pages": [1129, 1130, 1131, 1132, 1133, 1134, 1135, 1136, 1137, 1138, 1139, 1140], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC106B148B82A8E28EF8E8FD5D2D16AE641A7333A6F6C76DF27A852238F00A7C162", "videos": [{"date": "2025-06-10", "group": 15}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493D26B7B3A768403DF26CA722D065A6D7958AC4F67347F01EA852238F00A7C162#page=1", "transcript_pages": [2902, 2903, 2904, 2905, 2906], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493D26B7B3A768403DF26CA722D065A6D7958AC4F67347F01EA852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 2}]}, {"dates": ["2025-04-14"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 1, "heading": "警政衛生部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13