INSERT INTO "fact" VALUES('summary:14-05:pa0224cb763','pa0224cb763','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:38:45Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=18"}, {"page": 452, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=4"}, {"page": 3062, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=10"}, {"page": 3063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=11"}, {"page": 3062, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=10"}, {"page": 3064, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=12"}], "councilor_points": ["劉耀仁議員指出博愛特區內有業者經營德州撲克場所，且都市發展局與警察局公文往返長達227天始開出裁罰書，無法阻嚇違規業者。劉耀仁議員建議市府將裁罰流程縮短至一個月內，並對現場舉發仍持續營業的店家實施斷水斷電。"], "response": "都市發展局局長說明會檢討橫向聯繫與行政程序，並與警察局合作執行下一階段裁處；警察局副局長表示已依正俗專案辦理第一階段裁罰並進行列管；警察局局長補充說明跨局處已討論查獲後先行裁處而不必等待起訴書；臺北市建築管理工程處管理科科長表示會研議縮短限改時間。", "response_removed": false, "topic": "博愛特區德州撲克查處與裁罰流程"}, {"citations": [{"page": 449, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=1"}, {"page": 450, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=2"}, {"page": 451, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=3"}, {"page": 451, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=3"}, {"page": 451, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=3"}], "councilor_points": ["劉耀仁議員指出市府規劃將45輛大型垃圾車停車場改設於華中里，事先未與里長及里民溝通，導致清明假期收到兩千多筆抗議書。劉耀仁議員表示華中里周邊環境與交通不適合停放大型垃圾車，要求市府明確承諾不會將停車場設於華中里。"], "response": "環境保護局局長說明該地點僅為評估點尚未定案，承諾會做最完整的評估，不會選擇不適合的地點硬做停車場；水利工程處處長說明現場看交通狀況確實較混亂。", "response_removed": false, "topic": "淡水河水岸計畫垃圾車停車場設置"}, {"citations": [{"page": 973, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=3"}, {"page": 972, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=2"}], "councilor_points": ["劉耀仁議員指出成功高中蝴蝶昆蟲博物館擁有四萬多件館藏，但每年僅少量經費且人力不符運作需求，要求市府將學校計算出的一年196萬元需求列為單獨預算並增加2名員額，同時請觀光傳播局協助宣傳。"], "response": "市長表示很願意支持，會與學校及榮譽館長積極溝通實際需求並給予協助，亦會請觀光傳播局協助加強宣傳；教育局局長說明該場館經費已調高至80萬元，亦有補助冷氣改善費用290萬元，會再與學校協商需求並全力支持。", "response_removed": false, "topic": "成功高中蝴蝶昆蟲博物館營運與預算"}, {"citations": [{"page": 483, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=5"}, {"page": 484, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=6"}, {"page": 484, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=6"}], "councilor_points": ["劉耀仁議員指出平日上午7點半到8點半上班時間，萬華民眾在捷運龍山寺站經常無法擠上任何一班列車。劉耀仁議員建議市府研議在該尖峰時段每5班列車安排1班由亞東醫院發車且過站不停直達龍山寺站的列車。"], "response": "臺北大眾捷運股份有限公司總經理說明該區段已發車至2分鐘一班的系統極限，承諾會在3個月內研議改善方案。", "response_removed": false, "topic": "捷運龍山寺站尖峰時段疏運改善"}, {"citations": [{"page": 61, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=1"}, {"page": 61, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=1"}, {"page": 63, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=3"}], "councilor_points": ["劉耀仁議員指出廣州街進行全封閉施工卻仍可在系統借到路權，且台北通App充斥過期與錯誤的施工改道資訊。劉耀仁議員要求資訊局修正台北通未更正的資訊，並改善跨局處橫向聯繫與圖資整合。"], "response": "資訊局局長表示會在市政總質詢前進行盤點與討論，並研究將圖資整合至單一平臺以提供完整與正確訊息；警察局交通警察大隊行政組組長說明無法得知道路挖掘管理中心的施工路段。", "response_removed": false, "topic": "台北通App與道路施工資訊整合"}, {"citations": [{"page": 1777, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=7"}, {"page": 1778, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=8"}, {"page": 1779, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=9"}], "councilor_points": ["劉耀仁議員指出東園國小少棒隊獲得全國國小硬式棒球冠軍，市府花費5,500萬元鋪設人工草皮的青年公園棒球場應定位為少棒專屬訓練基地。劉耀仁議員建議體育局將青年公園棒壘球場移交教育局，並要求教育局對東園國小出國比賽提供情蒐與防護等支援。"], "response": "體育局局長表示會朝向建議方向與教育局共同努力；教育局局長說明會先協調提供東園國小專屬練習時段，並針對比賽加強防護與情蒐等支援。", "response_removed": false, "topic": "青年公園棒球場營運與移交管理"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-06"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=1", "transcript_pages": [971, 972, 973, 974, 975, 976, 977, 986, 987, 988], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162", "videos": [{"date": "2025-06-06", "group": 10}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=9", "transcript_pages": [3061, 3062, 3063, 3064, 3065, 3066], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162", "videos": [{"date": "2025-04-24", "group": 10}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=1", "transcript_pages": [449, 450, 451, 452, 453, 454], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 10}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=1", "transcript_pages": [778, 779, 780, 781, 782], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 8}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 6, "heading": "教育部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=7", "transcript_pages": [1777, 1778, 1779, 1780, 1781, 1782], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 6}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=1", "transcript_pages": [61, 62, 63, 64, 65], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 14}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=1", "transcript_pages": [479, 480, 481, 482, 483, 484, 485], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162", "videos": [{"date": "2025-05-26", "group": 16}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162','2026-10-01T09:38:45Z');
INSERT INTO "fact" VALUES('summary:14-05:p4b727b88dc','p4b727b88dc','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:40:20Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=44"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=44"}, {"page": 1923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=2"}, {"page": 1926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=5"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=44"}, {"page": 697, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=47"}, {"page": 1926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=5"}, {"page": 696, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=46"}, {"page": 1928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=7"}], "councilor_points": ["吳世正議員指出，臺北市特教生人數逐年上升，國小至高中階段分散式資源班師生比惡化，現行實施超過30年的融合教育制度造成普通班教師、行政人員及學生沉重負擔。吳世正議員建議市府向中央反映檢討融合教育制度，並要求增加特教預算與專班，提高助理員人力與服務時數，以維持教學品質與照顧特教生需求。"], "response": "市長表示，近2年已增加特教經費1.9億元並提高特教助理員待遇，會請教育局針對分散式特教班盤點資源，在不影響普通生受教權下給予特教生適當照顧。教育局局長說明，114年度將增加9個集中式特教班及34個資源班，特教助理員時數已從113年度75萬小時提高至85萬小時，後續會評估增加特教專班與人力配置。", "response_removed": false, "topic": "特殊教育與融合教育資源配置"}, {"citations": [{"page": 690, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=40"}, {"page": 690, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=40"}, {"page": 2991, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=22"}, {"page": 2991, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=22"}, {"page": 2994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=25"}, {"page": 691, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=41"}, {"page": 691, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=41"}], "councilor_points": ["吳世正議員表示，公園處勞務委外經費從109年度3億多元增至114年度高達4億多元，且規劃將路燈換裝及維護作業全面採PFI模式委外，恐引發工會憂心員工權益並影響搶修效率。吳世正議員要求市府停止路燈與園藝工程隊全面委外政策，應補齊原有編制人力並保障勞工權益。"], "response": "副市長說明，採用PFI模式係為推動路燈智慧化管理，設有廠商接獲故障通報需於6小時內修繕完成之機制，過渡期仍由路燈隊監督。市長表示，過渡期間會保障同仁工作權益，持續與工會溝通，在不影響同仁權益下提升路燈管理與維修效率。", "response_removed": false, "topic": "公園處勞務委外及路燈維護管理"}, {"citations": [{"page": 681, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=19"}, {"page": 682, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=20"}, {"page": 682, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=20"}, {"page": 687, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=25"}], "councilor_points": ["吳世正議員指出，美國對臺課徵32%關稅政策將影響臺北市約2,800家企業，要求勞動局主動分析受影響產業，避免等倒閉或裁員才進場。吳世正議員建議勞動局定期邀請學者專家開會研商，並具體盤點穩定就業與短期上工等資源。"], "response": "勞動局局長表示，市府已與學者專家開會並持續關注企業動態，規劃輔導企業避免大量解僱，若發生大量解僱將啟動轉銜輔導或「台北隊接住您」短期上工計畫。勞動局就業安全科科長及就業服務處處長說明，市府已預估編列約8,000多萬元穩定就業預算與1.94億元短期上工預算，預計可提供約1,000個短期工作機會。", "response_removed": false, "topic": "關稅政策衝擊與勞工就業因應措施"}, {"citations": [{"page": 698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=48"}, {"page": 536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=1"}, {"page": 537, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=2"}, {"page": 542, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=7"}, {"page": 699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=49"}, {"page": 541, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=6"}], "councilor_points": ["吳世正議員指出，臺北市受詐騙財損金額居高不下，且青少年涉及詐欺罪嫌疑人數及擔任車手比例增加。吳世正議員建議警察局檢討現行防詐宣導方式，邀請網路與青少年專家研擬防制計畫，並要求市府增加打詐與防詐的人力、設備及預算。"], "response": "市長表示，市府重視打詐與青少年涉詐問題，會請警察局、財政局及主計處統整並評估於下年度預算增加防詐經費與人力。警察局刑事警察大隊大隊長與警察局局長說明，警察局已與資訊局、法務局成立專案小組利用AI爬蟲過濾非法廣告，並由刑事警察大隊專責人員進行網路巡邏與查緝。", "response_removed": false, "topic": "詐騙防制與青少年犯罪預防"}, {"citations": [{"page": 314, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=10"}, {"page": 315, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=11"}], "councilor_points": ["吳世正議員指出，市府新設行人庇護島因設計位置突出且未考慮用路人駕駛習慣，導致近3年發生至少34件車輛撞擊庇護島事故，例如羅斯福路與景中街路口已發生10次碰撞。吳世正議員要求交通局檢討現有庇護島設計，應優先退縮斑馬線至既有分隔島內，並因地制宜加高警示設施。"], "response": "交通局局長說明，會親自至現場檢視行車軌跡與設計，對於有疑慮的案例進行微調優化。市長表示，市府將進行全面總體檢，重新檢視庇護島設置，改以行穿線退縮方式改善，避免再發生車輛碰撞事件。", "response_removed": false, "topic": "行人庇護島設計與改善"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=39", "transcript_pages": [689, 690, 691, 692, 693, 694, 696, 697, 698, 699, 700, 701, 702], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162", "videos": [{"date": "2025-06-02", "group": 4}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=22", "transcript_pages": [2991, 2992, 2993, 2994, 2995], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 6}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=1", "transcript_pages": [536, 537, 538, 539, 540, 541, 542, 543, 544], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 14}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 4, "heading": "民政部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=16", "transcript_pages": [678, 679, 680, 681, 682, 683, 684, 685, 686, 687, 688], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 4}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 13, "heading": "教育部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=1", "transcript_pages": [1922, 1923, 1924, 1925, 1926, 1928], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 13}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=21", "transcript_pages": [97, 98, 99, 100, 101, 102, 103, 104], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 15}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=8", "transcript_pages": [312, 313, 314, 315, 316], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162','2026-10-01T09:40:20Z');
INSERT INTO "fact" VALUES('summary:14-05:pefa8e31df3','pefa8e31df3','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:42:06Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3004, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=9"}, {"page": 3005, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=10"}, {"page": 3006, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=11"}, {"page": 3007, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=12"}], "councilor_points": ["吳志剛議員詢問新工處與都發局對道路認定標準的差異，並指出市民大道等路段地目仍為鐵路用地，與實際道路使用現況不符。吳志剛議員指出都市計畫法規定每3至5年需進行一次通盤檢討，但松山區等行政區曾多年未依規定實施通盤檢討。吳志剛議員建議市府應依照實際使用狀況進行都市計畫通盤檢討，以維護市民權益。"], "response": "新工處處長說明道路認定係依都市計畫圖劃定範圍，維護時會按現況或開闢部分處理，設施及地下化道路亦納入維管。都發局局長表示都市計畫法規定每3至5年進行通盤檢討，過去因行政區輪檢致時程不一，承諾今年會啟動全市通盤檢討，並針對市民大道等實際道路使用狀況進行檢討處理。", "response_removed": false, "topic": "都市計畫道路認定與通盤檢討"}, {"citations": [{"page": 1963, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1405E0D1FEE946B96DCA11C5C8FA52EFF4F2E5E141774B7CEA852238F00A7C162#page=17"}, {"page": 2101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=21"}, {"page": 2101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=21"}, {"page": 2102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=22"}, {"page": 2102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=22"}, {"page": 2103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=23"}], "councilor_points": ["吳志剛議員指出部分傳統市場整建後人流與生意不如以往，詢問市場處是否有提供租金優惠或振興措施。吳志剛議員關切環南市場停車場標租多次流標原因，並反映地下室車道分隔島欠缺明確標示易釀事故，以及車位遭違規占用理貨等問題。吳志剛議員建議市場處多與攤商溝通合作，積極解決營運困境並協助環南市場維持批發業務發展。"], "response": "市場處處長說明消費型態與人口結構改變影響市場人流，持續推動精進計畫與攤位改造計畫。市場處處長表示已重新檢討停車場標租價格合理性，將即刻改善地下室分隔島識別標誌，並對違規占用加強管理與劃設理貨空間，預計5月下旬完成一期2樓整修工程後保留做理貨區使用。", "response_removed": false, "topic": "傳統市場活化與環南市場營運管理"}, {"citations": [{"page": 762, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=26"}, {"page": 763, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=27"}, {"page": 763, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=27"}], "councilor_points": ["吳志剛議員關切北市人行道拓寬工程的準則與效益，指出拓寬後車道縮減（如南昌路一段與二段）易造成公車停靠與車輛壅塞，並影響聯合醫院婦幼院區急診救護車通行。吳志剛議員反映自行車騎士常於拓寬人行道及騎樓高速騎乘與行人爭道，強調應先解決違規騎乘問題。吳志剛議員要求市府拓寬前應與在地里長充分溝通協調，傾聽地方實際交通需求。"], "response": "交通局局長說明拓寬係依據市區道路設計手冊等規範提供安全通行空間，針對南昌路案例會於6月4日向地方說明並加強溝通，亦會進行違規騎乘稽查。市長回應道路規劃已改為人本交通概念，強調拓寬時會整體考量避免衝擊車流，並持續宣導自行車騎乘規範與完善標示。", "response_removed": false, "topic": "人行道拓寬工程與交通衝擊評估"}, {"citations": [{"page": 2103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=23"}, {"page": 181, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=11"}, {"page": 181, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=11"}, {"page": 182, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=12"}, {"page": 183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=13"}], "councilor_points": ["吳志剛議員關注違規騎乘電動滑板車現象，指出其缺乏專責管理單位與國家檢驗標準。吳志剛議員列舉日本、韓國、新加坡及美國紐約等各國對個人行動器具的規範，建議市府主動擬定安全規範與行駛區域。吳志剛議員要求市府考量北北基桃生活圈需求，跨縣市共同研議行政命令與明確管理辦法。"], "response": "交通局局長說明電動滑板車因缺乏安全審驗且時速常超過慢車規範25公里而禁止行駛道路，目前尚無專責單位。交通局局長表示地方單獨訂定規範在實務操作上有困擾，六都皆希望由中央統一整合，承諾利用2個月時間與中央研究安全審驗規範並加強宣導。", "response_removed": false, "topic": "電動滑板車管理規範與跨縣市整合"}, {"citations": [{"page": 526, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=11"}, {"page": 526, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=11"}, {"page": 527, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=12"}, {"page": 527, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=12"}], "councilor_points": ["吳志剛議員關注環保局規劃於萬華區華中里河濱公園設置垃圾車停車場一事，反映當地居民對於交通流量增加、車輛廢氣噪音及水岸公園權益受損之疑慮。吳志剛議員指出臺北農產運銷公司周邊每日已有大量車輛與板車進出，要求市府不可在未溝通前定案。吳志剛議員建議環保局最後決定前必須召開說明會與公聽會，充分聽取地方心聲。"], "response": "環保局局長澄清該案尚未定案，係因大同區3號水門工程需替45臺萬華區垃圾車另尋地點，目前仍於評估階段，承諾未確認適當地點前不會搬遷。環保局局長說明會將板車問題納入交通流量評估，並承諾方案評估時會召開說明會與居民溝通，選擇衝擊最小的地點。", "response_removed": false, "topic": "萬華區華中里垃圾車停車場設置評估"}, {"citations": [{"page": 763, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=27"}, {"page": 764, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=28"}, {"page": 764, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=28"}, {"page": 765, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=29"}], "councilor_points": ["吳志剛議員指出臺北市今年1月至4月發生6,278件詐騙案，損失金額達52億4,090萬元，且案件數逐月增加，詢問市府防範措施。吳志剛議員指出前三大詐騙手法為投資詐騙、網路購物及一般購物詐騙，詢問防詐工作中最困難與最難突破之處。吳志剛議員要求警察局於報稅季加強防詐宣導並提出有效方案，實際維護市民財產安全。"], "response": "警察局局長說明已透過分齡分眾宣導、銀行臨櫃攔阻，並於今年1月至4月下架8,100多件網路詐騙訊息，亦指出犯罪首謀位於境外為查緝困難點。市長表示臺北市攔阻詐騙金額為六都最高，將嚴格要求社群平台業者負起企業責任下架詐騙廣告，從源頭切斷詐騙管道。", "response_removed": false, "topic": "防範詐騙與打擊詐欺犯罪"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=25", "transcript_pages": [761, 762, 763, 764, 765, 766, 767, 768, 769], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162", "videos": [{"date": "2025-06-03", "group": 6}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 7, "heading": "工務部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=9", "transcript_pages": [3004, 3005, 3006, 3007, 3008], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 7}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=10", "transcript_pages": [525, 526, 527, 528], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 13}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 5, "heading": "民政部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=1", "transcript_pages": [694, 695, 696, 697, 698, 699, 700], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 5}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1405E0D1FEE946B96DCA11C5C8FA52EFF4F2E5E141774B7CEA852238F00A7C162#page=16", "transcript_pages": [1962, 1963], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1405E0D1FEE946B96DCA11C5C8FA52EFF4F2E5E141774B7CEA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 14}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=21", "transcript_pages": [2101, 2102, 2103], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162", "videos": [{"date": "2025-05-13", "group": 4}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=11", "transcript_pages": [181, 182, 183, 184, 185], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162','2026-10-01T09:42:06Z');
INSERT INTO "fact" VALUES('summary:14-05:p155e15fe02','p155e15fe02','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:44:01Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 811, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162#page=9"}, {"page": 1704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=26"}, {"page": 1706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=28"}, {"page": 1706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=28"}, {"page": 1710, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=32"}, {"page": 1704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=26"}, {"page": 1707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=29"}], "councilor_points": ["張志豪議員指出本選區發生國小代理教師於校園墜樓之事件，詢問教育體系安排剛到任者接任高年級畢業班導師之合理性。張志豪議員指出國小導師中代理教師比例達9.39%，高年級導師中代理教師比例更達22%，過高比例與調度方式反映出制度分配問題。張志豪議員要求公布各國小代理教師比例、研擬高年級導師年資門檻、檢討教師諮商輔導預算與建立代理教師備援與退場機制。"], "response": "教育局局長說明管控代理教師比例係為避免少子女化減班導致正式教師被資遣，正式員額皆依法聘滿。教育局局長表示高年級缺額較多係因教師多偏好低年級，現已安排主任設置雙導師機制並請督學協助學校危機處理。教育局人事室主任說明代理教師表現優良經教評會通過可續聘兩次，教育局局長亦承諾於本會期結束前就議員訴求提出書面回覆。", "response_removed": false, "topic": "代理教師導師配置與校園心理支持"}, {"citations": [{"page": 898, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=5"}, {"page": 898, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=5"}, {"page": 899, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=6"}, {"page": 901, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=8"}, {"page": 902, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=9"}, {"page": 903, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=10"}, {"page": 904, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=11"}, {"page": 901, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=8"}, {"page": 902, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=9"}, {"page": 905, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=12"}], "councilor_points": ["張志豪議員詢問市府在設計前未辦理說明會即決策拆除公館圓環，並指出改為正交路口後等待時間將從120秒增加至180秒。張志豪議員表示該處近7年僅1件A1事故，且違規案件多係標線標誌不佳導致機車未依規定二段式左轉，貿然填平車行地下道亦會影響羅斯福路每小時148班之公車動線與切斷原水幹管。張志豪議員要求市府暫緩拆除計畫、重新進行全面性效益分析、公開評估資料並舉辦公聽會聽取民意。"], "response": "交通局局長說明該地點連續7年交通事故肇事第1名，拆除圓環改為正交路口係以安全為優先考量，並可透過號誌與路型設計改善車流。市長表示自來水事業處已針對水管切斷進行詳細評估，市府會加強跨局處橫向聯繫與溝通。交通局局長表示已彙整5月29日說明會之地方意見並重新評估，承諾會再召開說明會與民眾溝通並於本會期結束前回覆。", "response_removed": false, "topic": "公館圓環拆除案之交通影響評估與決策流程"}, {"citations": [{"page": 805, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162#page=3"}, {"page": 806, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162#page=4"}, {"page": 807, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162#page=5"}, {"page": 807, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162#page=5"}, {"page": 1713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=35"}], "councilor_points": ["張志豪議員指出青少年性侵害案件中有大量源於網路交友，質疑現行防治措施成效並關注交友軟體缺乏未成年風險警語與防護門檻。張志豪議員建議研議地方自治法規或建立行政指導，要求交友平臺設置未成年風險警語與年齡辨識機制，並於行政院會報反映此議題。張志豪議員要求跨局處建立青少年性侵害防治工作小組，並於115學年度完成性平與法制課程內容修訂，納入網路交友風險拆解。"], "response": "社會局局長說明性侵害防治工作係結合警政、教育、社政及衛政等單位進行，並透過學校課程及iWIN平臺進行宣導。法務局局長表示目前中央與地方均無強制交友軟體設置警語之法規，承諾會研議可行方案向議員及市長報告。教育局局長表示將於115學年度補充相關教學教材，並跨局處推動校園數位風險防範措施。", "response_removed": false, "topic": "青少年網路交友性侵害防範與平臺管理"}, {"citations": [{"page": 414, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=9"}, {"page": 415, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=10"}, {"page": 416, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=11"}, {"page": 416, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=11"}], "councilor_points": ["張志豪議員指出捷運環狀線南環段Y04站施工現場人行通道淨寬未達簡報承諾之150公分，部分區段實測僅130公分甚至70公分，影響通行權利。張志豪議員指出周邊許多屋齡超過50年之老舊建築，建議市府主導預防性結構安全評估與補強，而非僅於鄰損發生後才進行鑑定。張志豪議員要求市府針對施工期間尖峰時段交通衝擊提出備用替代方案，並於下會期開議前提出精進方案報告。"], "response": "捷運工程局局長說明木柵路路幅狹小，施工期間會另行開闢符合基準的人行道或於圍籬外設置1.5公尺人行道。捷運工程局局長表示若有必要可啟動第三方優先辦理建物調查，施工前亦會做地方保護。捷運工程局局長說明將利用高速公路、水源快速道路及堤外道路疏解車流，並承諾於下會期開議前提出精進方案報告。", "response_removed": false, "topic": "捷運南環段Y04站施工之人行空間與建物安全配套"}, {"citations": [{"page": 2157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=17"}, {"page": 2158, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=18"}, {"page": 2158, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=18"}, {"page": 2160, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=20"}, {"page": 2160, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=20"}], "councilor_points": ["張志豪議員指出復興北路瓦斯外洩搶修時，因開關閥立棒鏽蝕斷裂而無法及時關閉，暴露管線老舊問題。張志豪議員表示全市使用中超過40年之瓦斯開關閥達5,419個，並出示照片指出搶修現場施工人員於瓦斯外洩處抽菸，要求2週內提出更換計畫及1週內提出懲處改善措施。"], "response": "產業發展局公用事業科科長說明該開關閥於民國70年裝設，開關閥並未規定使用年限，但會要求天然氣公司進行巡查與專案抽查。產業發展局局長表示施工人員於搶修現場抽菸係不可接受之行為，將要求大台北瓦斯公司提出說明並懲處相關人員。產業發展局局長承諾將要求瓦斯公司於汰換管線時同步檢測超過40年之開關閥，若堪用度不足將同步更換。", "response_removed": false, "topic": "老舊天然氣開關閥汰換與管線施工安全管理"}, {"citations": [{"page": 3185, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=20"}, {"page": 3185, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=20"}, {"page": 3183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=18"}, {"page": 3184, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=19"}, {"page": 3186, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=21"}], "councilor_points": ["張志豪議員指出水利工程處抽水站輪班人員適用勞動基準法，但過去未依法給付加班費，經勞動局於114年1月21日開立裁處書認定違法。張志豪議員以民法5年請求權時效估算，受影響之現職與離退人員約400人，積欠加班費估算達1.37億元。張志豪議員要求勞動局積極協助勞工，並要求工務局於2週內提出加班費主動清查與返還計畫。"], "response": "水利工程處處長說明過去係因計算方式短缺而非全部未給付，目前已啟動主動清查，規劃每2個月清查1年並於清查後給付。勞動局勞動基準科科長證實水利處過去給付方式違法，且薪資請求權時效為5年。工務局局長承認過去依106年協議之計算方式違法，自113年12月起已依法給付，並承諾於2週內提出加班費返還計畫與時間表。", "response_removed": false, "topic": "水利處抽水站人員加班費積欠與補發計畫"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-06"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "http