809, 810, 811], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549C35BAC39D1E644FA0C5E3549C6CD502D7451245448122E7FA852238F00A7C162", "videos": [{"date": "2025-05-02", "group": 10}]}, {"dates": ["2025-05-06"], "dept": "教育", "doc_type": "部門質詢", "group": 2, "heading": "教育部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162#page=25", "transcript_pages": [1703, 1704, 1705, 1706, 1707, 1708, 1709, 1710, 1711, 1712, 1713], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC122F2C7E65A995CF7616BC257C5FAB6DED7CF06524DA8A2D5A852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 2}]}, {"dates": ["2025-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 6, "heading": "財政建設部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=17", "transcript_pages": [2157, 2158, 2159, 2160, 2161, 2162, 2163, 2164, 2165], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 6}]}, {"dates": ["2025-05-23"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "heading": "交通部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=7", "transcript_pages": [412, 413, 414, 415, 416, 417, 418, 419], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162", "videos": [{"date": "2025-05-23", "group": 13}