INSERT INTO "fact" VALUES('summary:14-05:p499663cb96','p499663cb96','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:45:32Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1855, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=24"}, {"page": 2056, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=3"}, {"page": 2057, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=4"}, {"page": 2060, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=7"}, {"page": 2055, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=2"}, {"page": 2058, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=5"}], "councilor_points": ["張文潔議員指出松山區敦北狗公園之工程規劃與完工時程說明不一，要求市府說明具體進度並如期完工。此外，張文潔議員關切比特犬等具攻擊性犬隻進入狗公園之安全規範，要求市府完善入園注意事項，並盤點現有狗活動區以推動大小犬分區設置。"], "response": "動物保護處處長說明敦北狗公園由區公所辦理工程，預計於今年底完工。動物保護處處長表示將研議調整狗公園注意事項，並盤點現有狗活動區空間以研議大小犬分區處置。", "response_removed": false, "topic": "狗公園與狗活動區設施改善"}, {"citations": [{"page": 3022, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=2"}, {"page": 3023, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=3"}, {"page": 3024, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=4"}, {"page": 3025, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=5"}], "councilor_points": ["張文潔議員指出有都市更新會取得變更後的立案證書，依市府同仁說明備齊資料申請補助，卻遭都市更新處以超過原核准立案1年時效為由駁回。張文潔議員詢問該證書效力，建議市府不應剝奪民眾權益並影響都市更新進度。"], "response": "都市更新處處長說明補助申請仍以原始核准立案日期為準，該次僅變更圖記印模，並表示會後將再提供報告。", "response_removed": false, "topic": "都市更新會立案證書與補助申請爭議"}, {"citations": [{"page": 2060, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=7"}, {"page": 2061, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=8"}, {"page": 2062, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=9"}, {"page": 2063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=10"}, {"page": 2062, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=9"}, {"page": 2063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=10"}], "councilor_points": ["張文潔議員指出「臺北好購推廣平台」採購金額與筆數下滑，且展售活動參與家數與點閱人數偏少，行銷宣傳顯有不足。張文潔議員要求市府檢討現行以高額成交量為主的獎勵機制，新增鼓勵新創企業之獎項，並研議開放非企業民眾參與購買。"], "response": "產業發展局局長說明將重新檢視並舉辦說明會與行銷活動，並即刻要求執行單位檢討活動辦理方式。產業發展局局長表示將調整供應方獎勵機制，並針對開放非企業購買進行研議。", "response_removed": false, "topic": "「臺北好購推廣平台」營運與新創獎勵機制"}, {"citations": [{"page": 459, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=8"}, {"page": 462, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=11"}, {"page": 461, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=10"}, {"page": 462, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=11"}], "councilor_points": ["張文潔議員指出二代悠遊卡資安等級與功能較高，但流通量僅占整體少數，且市府發行之卡別多仍採用一代卡。張文潔議員要求悠遊卡公司加強主力行銷，並積極與市府各機關溝通擴大二代卡發行。"], "response": "悠遊卡公司總經理說明將持續與市府機關溝通並推動二代卡，加強相關行銷推廣。公共運輸處處長表示公車愛心卡可透過契約變更方式研議轉換。", "response_removed": false, "topic": "悠遊卡二代卡推廣與市府發卡合作"}, {"citations": [{"page": 873, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=31"}, {"page": 874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=32"}, {"page": 875, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=33"}], "councilor_points": ["張文潔議員指出裝設敬老愛心設備之計程車數量過少，導致長者難以叫車，要求市府提升服務量能。張文潔議員建議於台北通內建叫車服務，並研議開放將480點敬老點數用於採購成人紙尿褲等長者所需用品。"], "response": "臺北市市長說明將請資訊局與公共運輸處規劃研議台北通叫車功能，並研議點數用於不同實際需求品項。公共運輸處處長與資訊局局長說明將與業者討論設備補助，且技術上可配合系統架構。社會局局長表示將針對不同使用情況進行研議。", "response_removed": false, "topic": "敬老愛心計程車數量與叫車服務改善"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=29", "transcript_pages": [871, 872, 873, 874, 875, 876, 877, 878, 879, 880, 881, 882, 883, 884, 885], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "videos": [{"date": "2025-06-05", "group": 8}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=1", "transcript_pages": [3021, 3022, 3023, 3024, 3025, 3026, 3027, 3028], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 8}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=21", "transcript_pages": [411, 412, 413, 414, 415, 416], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 7}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢",