INSERT INTO "fact" VALUES('summary:14-05:pe9aa863557','pe9aa863557','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:32:15Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 539, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=7"}, {"page": 260, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=34"}, {"page": 541, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=9"}, {"page": 541, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=9"}, {"page": 542, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=10"}, {"page": 543, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=11"}, {"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=13"}, {"page": 255, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=29"}, {"page": 543, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=11"}, {"page": 544, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=12"}, {"page": 547, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=15"}], "councilor_points": ["張斯綱議員針對北投士林科技園區整體發展提出質詢，關注輝達等企業進駐後的交通影響，要求臺北市政府及早規劃社子輕軌、接駁公車及周邊替代道路。張斯綱議員關切新光人壽於 T17、T18 地塊的合約履約與輝達設廠協議進度、T12 用地招商規劃，以及中央補助款刪減對公車調度站的影響。張斯綱議員指出北士科發展將帶來大量人口，建議設立北士科產業服務中心，並評估籌備洲美國小、轉型中正高中為雙語國際高中及於國際羽球館納入多元體育設施。"], "response": "臺北市長與交通局局長說明，社子輕軌預計 6 年內搭配區段徵收做完，並已規劃園區接駁公車；地政局局長表示已收到新光人壽回函稱會依合約履約，若變更道路將重談權利金。臺北市長表示今年將成立洲美國小籌備處，國際羽球館總經費約 52 億元，將評估納入其他運動項目；產發局局長表示已調整北士科產業服務中心量能，提供企業進駐協助。交通局局長說明受到補助款刪減影響者為北士科公車調度站，將與財政局研議應對方案。", "response_removed": false, "topic": "北士科整體發展與周邊配套規劃"}, {"citations": [{"page": 977, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=30"}, {"page": 983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=36"}, {"page": 979, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=32"}], "councilor_points": ["張斯綱議員詢問臺北市政府是否能率先將中低收入戶納入喪葬費用全額減免對象，以減輕弱勢民眾負擔。張斯綱議員指出殯葬業務提成獎金支給要點沿用二十餘年未修訂，質疑二線單位領取獎金之合理性，建議將獎金發放比例由 25% 提高至 28% 以照顧一線同仁。張斯綱議員指出殯葬處提交之資料將墓政管理課誤植為有兩位課長，並建議合理調整永續殯禮課與墓政管理課的人力配置。"], "response": "殯葬管理處處長表示，針對中低收入戶喪葬費用全額減免將進行內部研究與研議。殯葬管理處處長說明，會計與政風等科室因參與驗收等業務而列入發放標準，且資料顯示兩位課長確屬貼錯誤植，後續會檢討調整人力配置。", "response_removed": false, "topic": "殯葬處業務運作與提成獎金分配"}, {"citations": [{"page": 2929, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=22"}, {"page": 2932, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=25"}, {"page": 2930, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=23"}, {"page": 2933, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=26"}, {"page": 2933, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=26"}], "councilor_points": ["張斯綱議員關注老舊建築加裝外開鐵門擋道受罰問題，指出住戶常因影響逃生通道或消防設施而面臨 6 萬元至 30 萬元罰鍰。張斯綱議員指出許多老舊大樓無管理委員會，且公安申報過程可能遭廠商坐地喊價，建議市府應以輔導代替處罰。張斯綱議員要求建築管理工程處建立專責窗口，並於 1 個月內制定管理公共安全檢查申報與複檢廠商之相關規範。"], "response": "建築管理工程處處長說明，法規主要規範防火門開啟不可影響直通樓梯迴轉半徑與疏散通道，目前已從 8 樓以上及 6 樓以上集合住宅逐步推動。建築管理工程處處長表示，無管委會者會在出入口貼公告輔導，對未改善者會先輔導限期改善才裁罰，並承諾委託複檢廠商協助初檢及加強管理。", "response_removed": false, "topic": "老舊建築鐵門外開改善與公安申報"}, {"citations": [{"page": 256, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=30"}, {"page": 257, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=31"}, {"page": 258, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=32"}, {"page": 259, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=33"}], "councilor_points": ["張斯綱議員指出高齡駕駛肇事數量逐年增加，認為現行宣導品誘因不足，建議比照好孕專車概念，提供自願繳回駕照的長者每年 3,000 元計程車乘車金。張斯綱議員關切 YouBike 事故率提升與維修頻率問題，指出傷害保險理賠率僅 24% 偏低，且發生孩童因鏈蓋破損摔車斷牙事件。張斯綱議員要求交通局重新檢視 YouBike 保險理賠範圍，並建議推動先投保再借車制度以保障騎乘者安全。"], "response": "交通局局長表示，願與財主單位研議提供計程車等乘車補助作為高齡者繳回駕照之替代方案。交通局局長說明，YouBike 保險理賠率較低係因理賠範圍侷限於骨折、住院與失能等條件，將協調擴張理賠內容，並願與北北桃共同研議實施先投保再借車制度。", "response_removed": false, "topic": "高齡駕駛換照獎勵與公共自行車管理"}, {"citations": [{"page": 1880, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=10"}, {"page": 1881, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=11"}], "councilor_points": ["張斯綱議員指出長青樂活遊臺北與市政建設參觀活動之行程景點重複度過高，建議結合大巨蛋導覽或文化展覽進行差異化規劃。張斯綱議員建議市府將因議員席次出缺而控留的參觀車輛額度，平均分配給同選區之其他議員使用。張斯綱議員指出臺北市部分旅館最高與最低定價差距懸殊，要求觀光傳播局檢討備查制度並訂定定價上限標準，避免影響觀光發展。"], "response": "觀光傳播局局長表示，將重新全盤規劃參訪行程以呈現多元樣貌。觀光傳播局局長說明，臺北市旅館房價目前採備查制，會進行稽查確認是否高於報備價格，並將研議相關改進目標。", "response_removed": false, "topic": "市政參訪觀光景點規劃與旅館房價管理"}, {"citations": [{"page": 575, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=15"}, {"page": 575, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=15"}, {"page": 576, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=16"}, {"page": 576, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=16"}], "councilor_points": ["張斯綱議員建議臺北市政府扮演領頭羊，編列公費預算補助 30 歲至 45 歲子宮頸抹片或 HPV 篩檢陽性之婦女施打 HPV 疫苗，每人補助 3 劑共 3,000 元，並將其伴侶納入追蹤。張斯綱議員指出士林區與北投區之學童塗氟合約醫療院所數量一度過少，造成資訊落差，建議市府拉齊行政流程，於每年 8 月開學前確定並公告合約院所名單。"], "response": "衛生局局長表示，經專家會議確定療效後，補助 HPV 疫苗方案在實際執行上非常可行，會將計畫往前推進。衛生局局長與衛生局科長說明，合約院所係每兩年簽約並持續更新，承諾會配合學校時程，於 8 月開學前做完整確認與公告。", "response_removed": false, "topic": "子宮頸癌防治補助與學童牙齒塗氟服務"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=7", "transcript_pages": [539, 540, 541, 542, 543, 544, 545, 546, 547, 548, 549, 575, 576, 577], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 2}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=21", "transcript_pages": [2928, 2929, 2930, 2931, 2932, 2933, 2934, 2935, 2936], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 3}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=1", "transcript_pages": [561, 574, 575, 576, 577, 578, 579, 580, 581], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 15}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=30", "transcript_pages": [977, 978, 979, 980, 981, 982, 983], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 16}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=7", "transcript_pages": [1877, 1878, 1879, 1880, 1881, 1882, 1883, 1884], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 11}]}, {"dates": ["2025-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 10, "heading": "財政建設部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162", "videos": [{"date": "2025-05-16", "group": 10}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=28", "transcript_pages": [254, 255, 256, 257, 258, 259, 260], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162','2026-10-01T09:32:15Z');
INSERT INTO "fact" VALUES('summary:14-05:p7dbdadb454','p7dbdadb454','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:47:49Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2997, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=2"}, {"page": 2998, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=3"}, {"page": 2998, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=3"}], "councilor_points": ["徐弘庭議員指出興隆路公車亭座椅遭拆除後遺留螺絲釘造成民眾受傷，詢問市府管轄與維護狀況。徐弘庭議員要求工務局建立市有財產清單與圖資管理機制，並將巡查責任納入維護契約。"], "response": "新建工程處處長表示目前正配合人行道普查建置數位影像圖資。工務局局長說明預計於今年完成街景相關基本資料建檔，並會於委外契約中要求巡查責任。", "response_removed": false, "topic": "市有財產管理與座椅設施安全"}, {"citations": [{"page": 713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=20"}, {"page": 715, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=22"}, {"page": 717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=24"}, {"page": 716, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=23"}], "councilor_points": ["徐弘庭議員指出臺中市將 182 萬 1,639 人納入民防團隊並分為 3,501 組，詢問臺北市城鎮韌性演習的規劃與動員規模。徐弘庭議員要求市府掌握演習細節，並對指定下防空避難室的重點驗證區居民加強宣導。"], "response": "兵役局局長表示臺北市演習編組為 4 群 23 組，並依中央規定規劃演習。兵役局權益編管科科長補充今年指定松山區、中山區及中正區為實際下到防空設施避難的重點驗證區，市府均有規劃宣導。", "response_removed": false, "topic": "全民防衛動員演練與民防編組"}, {"citations": [{"page": 187, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=17"}], "councilor_points": ["徐弘庭議員表示現行 75 歲以上高齡駕駛繳回駕照的贈品誘因不足，建議市府提供大眾運輸月票等實質優惠。徐弘庭議員建議市府要求或規範高齡駕駛開車需配備自動緊急煞車系統（AEB），以降低事故風險。"], "response": null, "response_removed": true, "topic": "高齡駕駛換照誘因與車輛安全設備"}, {"citations": [{"page": 760, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=24"}, {"page": 190, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=20"}, {"page": 188, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=18"}, {"page": 760, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=24"}, {"page": 761, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=25"}], "councilor_points": ["徐弘庭議員指出捷運南環線動工將造成木柵地區交通衝擊，建議成立府級單位整合工期並規劃堤外調撥車道與免費接駁公車。徐弘庭議員要求市府加速羅斯福路地下道填平工程，並利用假日進行交通演習與宣導。"], "response": "市長表示已由副市長召開會議，並指示參採議員提出的建議方向。交通局局長說明羅斯福路圓環拆除與地下道填平預計於 9 月開學前完工，並會整合各項工程避開重疊時間。", "response_removed": false, "topic": "捷運南環線施工交通疏導措施"}, {"citations": [{"page": 758, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=22"}, {"page": 2084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=4"}, {"page": 759, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=23"}], "councilor_points": ["徐弘庭議員指出翡翠水庫發電每度僅以 1.6 元賣給台電，導致臺北市每年短收約 2 億 7,000 萬元。徐弘庭議員要求市府積極協調立法院修正再生能源發展條例第 3 條，爭取合理的綠能售電價格。"], "response": "翡翠水庫管理局局長表示已拜託臺北市籍立法委員推動修法。市長表示將積極爭取，並與各縣市及各黨派立法委員溝通，目標於今年讓立法院審議通過。", "response_removed": false, "topic": "翡翠水庫售電收益與再生能源法規修法"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162#page=14", "transcript_pages": [750, 751, 752, 753, 754, 755, 756, 757, 758, 759, 760, 761], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162", "videos": [{"date": "2025-06-03", "group": 6}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 7, "heading": "工務部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162#page=1", "transcript_pages": [2996, 2997, 2998, 2999, 3000, 3001, 3002, 3003], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549148AD9F30C34375419AB249D356180B177D27A2B3178B456A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 7}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162#page=13", "transcript_pages": [528, 529, 530, 531, 532, 533, 534, 535], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665492992DA2B7E555C184D30CC401D61EE90A6153D9EB3A52462A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 13}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 5, "heading": "民政部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162#page=19", "transcript_pages": [712, 713, 714, 715, 716, 717], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B8F4216C166384BF29AA352E672794361F5BAC1CABEFB945A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 5}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1405E0D1FEE946B96DCA11C5C8FA52EFF4F2E5E141774B7CEA852238F00A7C162#page=12", "transcript_pages": [1958, 1959, 1960, 1961, 1962], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1405E0D1FEE946B96DCA11C5C8FA52EFF4F2E5E141774B7CEA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 14}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162#page=1", "transcript_pages": [2081, 2082, 2083, 2084, 2085, 2086, 2087, 2088], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC160188CEA2638EB6C2DA2554ADEFCA5074DDC30482AF6AB14A852238F00A7C162", "videos": [{"date": "2025-05-13", "group": 4}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162#page=15", "transcript_pages": [185, 186, 187, 188, 189, 190], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15FABD16B66F1108B877599FF01F4888D99297C7D6D09CD11A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC18545FCD16CA5DEFB0DC0A5B4FD064229359AC63A10675DF7A852238F00A7C162','2026-10-01T09:47:49Z');
INSERT INTO "fact" VALUES('summary:14-05:p62ab44979e','p62ab44979e','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:49:27Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 308, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549C524163110C3256EC21607C8E540D49BEC3DC23A11249DE0A852238F00A7C162#page=1"}, {"page": 311, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549C524163110C3256EC21607C8E540D49BEC3DC23A11249DE0A852238F00A7C162#page=4"}, {"page": 312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549C524163110C3256EC21607C8E540D49BEC3DC23A11249DE0A852238F00A7C162#page=5"}, {"page": 313, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549C524163110C3256EC21607C8E540D49BEC3DC23A11249DE0A852238F00A7C162#page=6"}, {"page": 312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549C524163110C3256EC21607C8E540D49BEC3DC23A11249DE0A852238F00A7C162#page=5"}], "councilor_points": ["徐立信議員指出，有警察局交通大隊員警發生交通事故後未維持現場並擅自離場，且未依標準作業程序通報及處理。徐立信議員表示，該員警與受害民眾和解時使用不當言語，且事故現場圖繪製與實際車輛停放位置有出入，質疑處理過程存有瑕疵。徐立信議員要求警察局查明處理流程是否違規，並加強員警教育訓練與進行內部議處。"], "response": "警察局局長說明，該事故因員警協助受傷騎士就醫而離開現場，坦言處置過程確實有瑕疵，若經查證未依規定處理將進行查處與議處。警察局交通警察大隊大隊長與警察局信義分局分局長表示，肇事原因經分析係汽車開門肇致，同仁負完全責任，並承諾重新檢視案情與處理流程。", "response_removed": false, "topic": "員警交通事故處理流程與處置檢討"}, {"citations": [{"page": 3047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=2"}, {"page": 3048, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=3"}, {"page": 3049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=4"}, {"page": 3050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=5"}, {"page": 3050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=5"}, {"page": 3052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176EE6B93B96E798AFA852238F00A7C162#page=7"}], "councilor_points": ["徐立信議員指出，都市發展局實施社會住宅隨到隨辦改採郵寄掛號受理，但因各郵局開門營業時間不同，造成準時於八時三十分寄件的弱勢民眾排序落後。徐立信議員表示，臺北市並無八時營業的郵局，此項規定導致資訊不透明與制度不公平，損害弱勢族群優先入住權益。徐立信議員建議檢討該申請機制，並要求暫緩未完成簽約部分以保障市民權益。"], "response": "都市發展局局長說明，公告規則係採郵戳時間為依據，執行過程並無疏失，但同意制度面造成弱勢民眾無法優先入住的問題可進行討論與修正。都市發展局住宅服務科科長表示，每次隨到隨辦均提早五個工作天公告供民眾瞭解資訊，未來會研議更公平的受理方式。", "response_removed": false, "topic": "社會住宅隨到隨辦郵寄申請機制檢討"}, {"citations": [{"page": 656, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B73264CB1F0B892C5082AED12844DEC70A99D342CD4D9466A852238F00A7C162#page=1"}, {"page": 658, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B73264CB1F0B892C5082AED12844DEC70A99D342CD4D9466A852238F00A7C162#page=3"}, {"page": 661, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B73264CB1F0B892C5082AED12844DEC70A99D342CD4D9466A852238F00A7C162#page=6"}, {"page": 661, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B73264CB1F0B892C5082AED12844DEC70A99D342CD4D9466A852238F00A7C162#page=6"}, {"page": 659, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549B73264CB1F0B892C5082AED12844DEC70A99D342CD4D9466A852238F00A7C162#page=4"}], "councilor_points": ["徐立信議員指出，地政局製作的反詐騙宣導影片雖標註臺語版，但內容僅旁白改為臺語配音，市長發言仍為國語，缺乏誠意。徐立信議員表示，該影片在網路上的點閱率偏低，且未規劃客語、原民語及新住民語言版本，無法有效達到多族群宣傳效果。徐立信議員建議未來製作宣導影片應涵蓋多元族群語言，並請民政局、客家事務委員會與原住民族事務委員會等單位共同協助推廣。"], "response": "地政局局長說明，當時因考量流利度而由幕僚建議市長講國語，坦承有精進空間，未來會檢討規劃臺語、客語等多語言版本，並透過新聞媒體報導來擴大宣傳效果。客家事務委員會主任委員與原住民族事務委員會主任委員表示，全力支持客語宣導，並可從特定原住民語言開始逐次推動。", "response_removed": false, "topic": "地政反詐騙宣導影片語言多樣性與推廣效益"}, {"citations": [{"page": 299, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=1"}, {"page": 300, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=2"}, {"page": 300, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=2"}, {"page": 302, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=4"}, {"page": 301, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=3"}, {"page": 302, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=4"}, {"page": 301, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=3"}, {"page": 303, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=5"}], "councilor_points": ["徐立信議員指出，華江國小校門口通學巷在禁行時段仍有汽機車違規闖入呼嘯而過，對學童上下學安全造成嚴重威脅。徐立信議員表示，該路段未設有導護志工與防護阻隔設施，且缺乏減速平臺及人行步道空間，保護措施明顯不足。徐立信議員要求交通局、警察局與學校於三個月內提出具體改善方案，並考量源頭管制或彎曲道路減速設計。"], "response": "交通局局長說明，會請同仁與校方及地方溝通，嘗試運用交通錐、連桿或道路減速設計來強化阻隔，儘速進行改善。華江國民小學校長與警察局萬華分局交通組組長表示，將調整導護崗位、於放學時段設置交通錐及連桿，並加強通學巷違規車輛取締與宣導。", "response_removed": false, "topic": "華江國小通學巷與校園周邊交通安全改善"}, {"citations": [{"page": 1071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=1"}, {"page": 1072, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=2"}, {"page": 1073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=3"}, {"page": 1074, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=4"}, {"page": 1075, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=5"}, {"page": 1073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=3"}], "councilor_points": ["徐立信議員指出，螢橋國小學童上下學時因人行道狹窄、燈柱擋道及雜物停放，被迫於車縫與馬路上通行。徐立信議員表示，汀洲路與泉州路口轉角紅線僅劃設五公尺，疑順應店家停車需求而影響行人與學童安全。徐立信議員要求市府一週內前往現場會勘，針對東側人行道拓寬、路燈移設及違規占用進行整體規劃改善。"], "response": "市長說明，會維護學童通學安全，承諾在一週內安排會勘並擬定整體改善計畫。交通局局長與交通管制工程處處長表示，轉角劃設五公尺紅線係考量機車停車需求，後續將會同相關單位清除雜物，並於西側規劃標線型人行道與行人專用時相。", "response_removed": false, "topic": "螢橋國小周邊及汀洲路泉州路口人行道安全"}, {"citations": [{"page": 1075, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=5"}, {"page": 1077, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=7"}, {"page": 1078, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=8"}, {"page": 1079, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=9"}], "councilor_points": ["徐立信議員指出，校園推動普特共融過程中發生學童肢體衝突疑慮，導致其他學生家長對校園安全產生擔憂。徐立信議員表示，特教助理員未能在事發第一時間防止衝突，且教師承受過度情緒壓力，顯示相關教育與輔導資源仍有不足。徐立信議員建議教育局、社會局與衛生局積極提供專業資源，檢討特教輔導機制並保護所有學生的受教權。"], "response": "市長說明，普特融合為正向方向，將請教育局邀集專家學者檢視現場問題，尋求根本解決方案以避免班級對立。教育局局長表示，現已安排特教助理員以全陪方式照顧該名學生，並會加強普通班教師的特教研習與身心協助。", "response_removed": false, "topic": "校園普特共融與特教生輔導資源維護"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-09"], "dept": null, "doc_type": "市政總質詢", "group": 13, "heading": "市政總質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162#page=1", "transcript_pages": [1071, 1072, 1073, 1074, 1075, 1076, 1077, 1078, 1079, 1080], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162", "videos": [{"date": "2025-06-09", "group": 13}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 9, "heading": "工務部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665493FC93EA9D4E0787ED5119AB32B931A176