{"date": "2025-05-06", "group": 3}]}, {"dates": ["2024-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1D59F0DDA554D32F01CC900482EDC67FBEAD080B52AEC1628A852238F00A7C162#page=11", "transcript_pages": [2193, 2194, 2195, 2196, 2197, 2198], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1D59F0DDA554D32F01CC900482EDC67FBEAD080B52AEC1628A852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 8}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162#page=1", "transcript_pages": [299, 300, 301, 302, 303, 304], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC12311A08E86A16AFE8CF9D41CE96365356A89F656AEC1F598A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 7}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC1D29C9C518915623193F3CB971D71653D6C091DFF8E04136BA852238F00A7C162','2026-10-01T09:49:27Z');
