INSERT INTO "fact" VALUES('summary:14-05:p741562d334','p741562d334','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:51:05Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 714, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=12"}, {"page": 732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=30"}, {"page": 597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549C3CBEDD30FD47B58DA4C7BBF64AC7B1EF455997608CA6360A852238F00A7C162#page=4"}, {"page": 713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=11"}, {"page": 730, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=28"}], "councilor_points": ["曾獻瑩議員指出社群平臺充斥名人冒名詐騙廣告，造成民眾重大財產損失，警察局雖積極通報下架但平臺業者配合度下降。曾獻瑩議員建議市府提升預防詐騙預算、公布防詐績效較落後的金融機構、導入AI大數據分析報案資料，並依消費者保護法針對平臺業者採一案一罰裁罰。"], "response": "市長說明市府已多次向平臺業者反映並發函要求遵守臺灣法律，若不配合將依消保法開罰，並由法務局研議一案一罰的可行性；警察局局長及刑事警察大隊大隊長表示已開始公布防詐績效較落後的金融機構，預算將提高至600萬元並導入AI進行犯罪分析；法務局局長表示將研議把單次刊登行為進行調查開罰。", "response_removed": false, "topic": "社群平臺詐騙廣告防制與裁罰"}, {"citations": [{"page": 1917, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F1CAC801204DB0107A9A58DD7ED62932DB23EE769240C8DCA852238F00A7C162#page=12"}, {"page": 2116, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=13"}, {"page": 2117, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=14"}, {"page": 2118, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=15"}], "councilor_points": ["曾獻瑩議員指出臺北市1至4月實收統籌分配稅款較預計短差41.04億元，詢問短撥原因及中央撥付原則變更對市府的影響。曾獻瑩議員要求財政局積極爭取臺北市應有權益，並針對新版財政收支劃分法公布後的預算籌編與額外財源預做準備。"], "response": "財政局局長說明財政部今年3月改按實際稅收撥付致有短撥，主因營業稅實收達成率不足及退稅增加，12月會做總整理，且8月會通知試算金額；財政局局長表示若依新版財劃法公式計算，臺北市大約會增加300億元，市府會採穩健原則編列預算並預做準備。", "response_removed": false, "topic": "地方政府統籌分配稅款短撥與財劃法修法因應"}, {"citations": [{"page": 192, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=1"}, {"page": 195, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=4"}, {"page": 194, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=3"}, {"page": 196, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=5"}], "councilor_points": ["曾獻瑩議員指出臺北市75歲以上駕駛人數達十三萬多人，高齡駕駛面臨操作不當等風險，並舉日本東京經驗為例。曾獻瑩議員建議市府研擬補助車輛加裝反暴衝裝置的可行性，並制定短、中、長期配套措施以降低交通事故發生率。"], "response": "交通局局長說明臺北市75歲以上汽車駕駛有8萬6千人、機車有4萬9千人，認同可透過車輛防呆機制避免踩錯油門；交通局局長表示會在一個月內研議補助反暴衝裝置的可行性，並繼續探討中、長期做法與向中央協調。", "response_removed": false, "topic": "高齡駕駛交通安全與車輛防暴衝裝置引進"}, {"citations": [{"page": 907, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=4"}, {"page": 909, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=6"}, {"page": 907, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=4"}, {"page": 910, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=7"}, {"page": 908, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=5"}], "councilor_points": ["曾獻瑩議員指出罷免案第二階段連署人數眾多，質疑僅交由戶政事務所人員難以判斷冒名連署，關心查詢單寄送標準與查核方式。曾獻瑩議員建議全部寄送查詢單或採去識別化方式公布連署人身分證末三碼，並向中央確認查核作法。"], "response": "臺北市選舉委員會主任委員說明依規定須有「疑似」偽造情形才能寄發查詢單，全寄會逾越中央規定，且法令未授權公布去識別化身分證字號；臺北市選舉委員會主任委員表示會向中央函詢相關作法的可行性。", "response_removed": false, "topic": "罷免連署查核與查詢單寄送機制"}, {"citations": [{"page": 2890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=9"}, {"page": 2891, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=10"}, {"page": 2890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=9"}, {"page": 2892, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=11"}, {"page": 2888, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=7"}], "councilor_points": ["曾獻瑩議員關注臺北大巨蛋舉辦演唱會時球場平面搖滾區可容納約2萬人，關切散場逃生動線是否充足，並指出媒體質疑消防安全驗證報告與電腦模擬參數未公開。曾獻瑩議員要求市府釐清安全疑慮、研議公開驗證報告重點摘要，並發布聲明正面回應報導。"], "response": "建築管理工程處處長說明大巨蛋球場平面設有5處逃生動線設計，經性能審查驗證球場平面區可容納15,000人，並表示可考慮公開報告結論或重點摘要；體育局綜合企劃科科長與建築管理工程處處長表示會彙整數據資料，於次日發布新聞稿對外說明。", "response_removed": false, "topic": "臺北大巨蛋演唱會避難動線與安檢資料公開"}, {"citations": [{"page": 1913, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F1CAC801204DB0107A9A58DD7ED62932DB23EE769240C8DCA852238F00A7C162#page=8"}, {"page": 1912, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F1CAC801204DB0107A9A58DD7ED62932DB23EE769240C8DCA852238F00A7C162#page=7"}], "councilor_points": ["曾獻瑩議員指出去年國中會考英語聽力測驗因考場設備故障致重播延後，造成散場噪音干擾考生應考並引發申訴。曾獻瑩議員要求市府宣導試務SOP、保障考生自救申訴權利，並建議長遠向中央反映將英聽調整至非最後一節應考。"], "response": "教育局中等教育科科長說明全國試務會已修改規定，若遇到散場或周邊噪音干擾將立即暫停播放英聽；教育局局長表示會先檢查設備，提醒學校與宣導學生聽不清楚時可提出申訴，並認同將英聽向前挪調整節次的建議。", "response_removed": false, "topic": "國中會考英聽測驗設備故障因應與試務改善"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02", "2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=9", "transcript_pages": [711, 712, 713, 714, 715, 716, 717, 718, 729, 730, 731, 732], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162", "videos": [{"date": "2025-06-02", "group": 5}, {"date": "2025-06-03", "group": 5}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 1, "heading": "工務部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABE