INSERT INTO "fact" VALUES('summary:14-05:p684c26bf24','p684c26bf24','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:52:25Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 419, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=2"}, {"page": 419, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=2"}, {"page": 421, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=4"}, {"page": 422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=5"}, {"page": 422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=5"}], "councilor_points": ["李傅中武議員指出臺北市詐騙案件與財損金額增加，雖然破獲率為六都最高，但追回財損之金額與比例偏低。李傅中武議員要求警察局向市長報告，並建議市府成立府級跨局處的打詐隊以保障市民安全。"], "response": "警察局局長說明警方目前透過宣導、金融機構攔阻、帳戶凍結及要求平台下架假投資網頁等方式防詐，並表示會配合與各局處聯合合作。", "response_removed": false, "topic": "詐騙防制與追贓機制建立"}, {"citations": [{"page": 516, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=6"}, {"page": 517, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=7"}, {"page": 518, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=8"}, {"page": 518, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=8"}, {"page": 518, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=8"}, {"page": 520, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=10"}], "councilor_points": ["李傅中武議員指出臺北市國小與國中棒球成績優異，但高中端因缺乏合格標準青棒場地、軟硬體設備與運動科學資源，導致優秀球員流失至外縣市。李傅中武議員建議市府制定短、中、長期的國高中棒球振興計畫，提供全額公費補助與獎學金，並建立升學、就業及退休轉業管道。"], "response": "市長表示認同，並說明已請教育局及體育局研擬振興青棒之短、中、長期計畫，以留住並吸引優秀棒球人才。", "response_removed": false, "topic": "國高中棒球振興計畫與留才機制"}, {"citations": [{"page": 1795, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1704DBCAC80CFDCBEF3C76F532C2F395C0FCABED8C430680CA852238F00A7C162#page=13"}, {"page": 1794, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1704DBCAC80CFDCBEF3C76F532C2F395C0FCABED8C430680CA852238F00A7C162#page=12"}, {"page": 1795, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1704DBCAC80CFDCBEF3C76F532C2F395C0FCABED8C430680CA852238F00A7C162#page=13"}], "councilor_points": ["李傅中武議員指出臺北市擴大敬師獎勵金發放對象至私立幼教職工，卻未包含原住民族語、閩南語及客家語等國家語言之支援教師。李傅中武議員建議教育局修改敬師獎勵實施要點，將本土語言支援教師納入發放對象，給予同等尊重。"], "response": "教育局局長說明敬師獎勵金過去以專任教職員為主，由於兼任教師種類與人數眾多，表示需要一個月時間研議。", "response_removed": false, "topic": "本土語言支援教師敬師獎勵金發放"}, {"citations": [{"page": 402, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC184B3F5E79717A383C66C546CE5D43BD35ACDD42A8E513516A852238F00A7C162#page=9"}, {"page": 402, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC184B3F5E79717A383C66C546CE5D43BD35ACDD42A8E513516A852238F00A7C162#page=9"}, {"page": 403, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC184B3F5E79717A383C66C546CE5D43BD35ACDD42A8E513516A852238F00A7C162#page=10"}, {"page": 404, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC184B3F5E79717A383C66C546CE5D43BD35ACDD42A8E513516A852238F00A7C162#page=11"}], "councilor_points": ["李傅中武議員指出臺北市部分道路劃設分流式指向線，造成單一車道出現兩組標線，易使駕駛誤以為可並行而引發交通事故與路權爭議。李傅中武議員建議交通局回歸交通工程、教育與執法，重新檢討該標線劃設之適當性。"], "response": "交通局局長說明分流式指向線旨在預告車輛提前分流，並表示會蒐集實務案例與中央單位探討路權認定與檢討。", "response_removed": false, "topic": "道路分流式指向線標誌標線劃設檢討"}, {"citations": [{"page": 22, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1476C31E3AAA98D5660760B25D414C3080132ECA95764E61EA852238F00A7C162#page=2"}, {"page": 22, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1476C31E3AAA98D5660760B25D414C3080132ECA95764E61EA852238F00A7C162#page=2"}, {"page": 23, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1476C31E3AAA98D5660760B25D414C3080132ECA95764E61EA852238F00A7C162#page=3"}, {"page": 24, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1476C31E3AAA98D5660760B25D414C3080132ECA95764E61EA852238F00A7C162#page=4"}, {"page": 24, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1476C31E3AAA98D5660760B25D414C3080132ECA95764E61EA852238F00A7C162#page=4"}], "councilor_points": ["李傅中武議員指出犬隻咬傷事件仍有未通報黑數，且具攻擊性犬隻若未適當防護即進入狗公園，將危害其他民眾與寵物安全。李傅中武議員建議動物保護處於現場明確告示規範與罰則，並檢討全面裝設監視器以釐清責任。"], "response": "動物保護處處長說明會於注意事項補充告示，針對監視器裝設及具有攻擊性犬隻之列管追蹤進行盤點與研議。", "response_removed": false, "topic": "狗公園安全與攻擊性犬隻管理"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162#page=1", "transcript_pages": [511, 512, 513, 514, 515, 516, 517, 518, 520], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 1}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 16, "heading": "工務部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549B4B08FA62475FD304BD00601F0FC74F239AF49E1C49FBEFCA852238F00A7C162#page=7", "transcript_pages": [3204, 3205, 3206, 3207], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549B4B08FA62475FD304BD00601F0FC74F239AF49E1C49FBEFCA852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 16}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 8, "heading": "警政衛生部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162#page=1", "transcript_pages": [418, 419, 420, 421, 422, 423, 424, 425], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549191474CCBBB2A509F42857368A0B776DA2F7E89BA97E166AA852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 8}]}, {"dates": ["2025-05-02"], "dept": "民政", "doc_type": "部門質詢", "group": 11, "heading": "民政部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549B8DCDDA4F9225EE765F3FF7A