12}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC165EEB421DAC0954760760B25D414C308BA61CAD04A811595A852238F00A7C162','2026-10-01T09:52:25Z');
INSERT INTO "fact" VALUES('summary:14-05:p69fa47e9b2','p69fa47e9b2','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:54:05Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 793, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=3"}, {"page": 794, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=4"}, {"page": 795, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=5"}, {"page": 795, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=5"}, {"page": 796, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=6"}, {"page": 792, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=2"}], "councilor_points": ["李建昌議員指出，立法院通過立法院職權行使法並統刪中央總預算 939 億 7,500 萬元，要求行政院各部會自行刪減 636 億元，且將多項國安與資安預算刪至 1 元。此外，李建昌議員亦關注罷免連署出現偽造簽名之情事，詢問市長與市府團隊對相關國會爭議與預算刪減之看法與立場。"], "response": "市長說明面對六四天安門事件應面對歷史且不認同血腥鎮壓，並表示中央扣除地方補助款時，會站出來爭取市民權利。副市長表示自己為事務官出身，不便對外詳細說明。文化局局長與法務局局長表示相關議題非屬其職務範圍。主計處處長說明該刪減係立法院之決議而非市議會所為。財政局局長表示市府依法編列預算並執行，並說明行政院於 5 月 16 日突然刪減原已核定之臺北市一般性補助款。", "response_removed": false, "topic": "中央預算刪減與國會法案爭議之立場"}, {"citations": [{"page": 3115, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=20"}, {"page": 3117, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=22"}, {"page": 3118, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=23"}, {"page": 3116, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=21"}, {"page": 3117, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=22"}], "councilor_points": ["李建昌議員詢問預算 34 億元的敦化地下大排工程規劃進度，指出該工程深度達地底下 40 米且蓄水容量等同 16 座標準游泳池，要求市府說明完工後能否保證周邊區域不再發生積水情形。同時，李建昌議員亦建議市府重視虎林街、吳興街及成功路五段等老舊社區的積淹水問題。"], "response": "水利工程處處長說明治水無法保證完全不淹水，但該工程可將降雨容受度目標提升至每小時 88.8 毫米，有效降低災害風險，並表示吳興街周邊已進行涵管改修工程以改善瓶頸。工務局局長說明敦化北路段係利用道路箱涵進行貯留，有信心將排水標準提升至每小時 88.8 毫米，對周邊排水效能有重大幫助。", "response_removed": false, "topic": "敦化地下大排工程與地區排水改善"}, {"citations": [{"page": 1831, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=28"}, {"page": 1830, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=27"}], "councilor_points": ["李建昌議員指出內湖潭美國小學生人數爆滿，反映該校因當初規劃缺乏前瞻性而未設有地下停車場與游泳池。李建昌議員建議教育局在進行二期校舍增建時，應重新將游泳池或地下停車場納入整體規劃考量。"], "response": "教育局局長說明二期計畫目前規劃為增建教室以縮短工期，並表示若在不影響工期或對學校發展更有利的前提下，會再檢視基地條件並研議結合游泳池等設施之可行性。", "response_removed": false, "topic": "潭美國小校舍增建與設施規劃"}, {"citations": [{"page": 168, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=22"}], "councilor_points": ["李建昌議員建議交通局應以內湖科技園區發展歷程為鑑，針對士林北投科技園區因企業總部進駐帶來的交通需求，預先規劃近、中程之交通路網、停車場及公共運輸等基礎設施。"], "response": "交通局局長說明內部已設定民國 120 年與 130 年等檢核點以做好基礎建設，並表示會採納建議以兩年為週期進行檢核，避免重蹈內科交通壅塞之覆轍。", "response_removed": false, "topic": "士林北投科技園區交通前瞻規劃"}, {"citations": [{"page": 169, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=23"}, {"page": 170, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=24"}], "councilor_points": ["李建昌議員指出民眾反映去年公車關門夾傷乘客案件達 352 件，並表示部分大型客運業者之智慧防夾系統裝設比例僅有 3%甚至 0%，要求交通局與公共運輸處加強監督業者裝設進度。"], "response": "公共運輸處處長說明案件通報標準，並表示今年一定會達成 80%之裝設目標。交通局局長補充說明已與業者達成共識，會列管確保達成今年八成之裝設目標。", "response_removed": false, "topic": "公車智慧防夾系統裝設進度"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 7, "heading": "市政總質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162#page=1", "transcript_pages": [791, 792, 793, 794, 795, 796, 797], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162", "videos": [{"date": "2025-06-03", "group": 7}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=20", "transcript_pages": [3115, 3116, 3117, 3118], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162", "videos": [{"date": "2025-04-24", "group": 12}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 11, "heading": "警政衛生部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665493E8EB2D456711C169E7098EB832D849C407A05D701EA7369A852238F00A7C162#page=16", "transcript_pages": [485, 486, 487], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665493E8EB2D456711C169E7098EB832D849C407A05D701EA7369A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 11}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 6, "heading": "民政部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=29", "transcript_pages": [746, 747, 748], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 6}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 9, "heading": "教育部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=25", "transcript_pages": [1828, 1829, 1830, 1831], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 9}]}, {"dates": ["2025-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 11, "heading": "財政建設部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC11B488CC5BB2268713F809CE8C5B8F0EFDDE53530A9EEEADAA852238F00A7C162#page=14", "transcript_pages": [14, 15, 16, 17], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC11B488CC5BB2268713F809CE8C5B8F0EFDDE53530A9EEEADAA852238F00A7C162", "videos": [{"date": "2025-05-16", "group": 11}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 1, "heading": "交通部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=21", "transcript_pages": [167, 168, 169, 170], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 1}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162','2026-10-01T09:54:05Z');
INSERT INTO "fact" VALUES('summary:14-05:p47f1fe2e84','p47f1fe2e84','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T02:10:06Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2909, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=2"}, {"page": 2909, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=2"}, {"page": 2910, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=3"}, {"page": 2911, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=4"}, {"page": 2910, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=3"}, {"page": 553, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=21"}, {"page": 554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=22"}, {"page": 2913, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=6"}, {"page": 2913, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=6"}, {"page": 554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=22"}], "councilor_points": ["李明賢議員指出南港產專區公辦都更7599專案成案率偏低且有撤案情形，詢問相關環節之阻礙因素。李明賢議員詢問內湖產專區主要計畫進度及適用戶數、經濟效益與交通衝擊之評估狀況。李明賢議員建議市府檢討老舊房屋合法認定過於嚴苛的問題，避免阻礙防災型都更與危老重建之推動。"], "response": "都市發展局局長與都市更新處處長說明，公辦都更案件因財務試算與住戶期待有落差導致後續意願降低，會持續分析原因並檢討改進。都市發展局局長表示，內湖產專區主要計畫預計3至6個月內發布實施，並會進行相關數據統計與評估。都市更新處處長與建築管理工程處處長說明，合法房屋認定有自治條例規定，亦可透過簡化程序轉送認定。", "response_removed": false, "topic": "產業專用區與防災型都市更新推動"}, {"citations": [{"page": 240, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=14"}, {"page": 241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=15"}, {"page": 242, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=16"}, {"page": 244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=18"}, {"page": 245, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=19"}, {"page": 246, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=20"}, {"page": 244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=18"}], "councilor_points": ["李明賢議員指出臺北市開放三車道以上道路免強制待轉進度緩慢，且部分路段出現待轉牌面與標線復原之狀況。李明賢議員表示堤頂大道導引標線過於複雜易造成碰撞，且港墘路左轉車道減半導致交通回堵，影響用路人權益。李明賢議員要求市府承諾待轉牌只減不增，並儘速改善堤頂大道標線與恢復港墘路雙左轉車道。"], "response": "交通局局長與交通管制工程處處長表示，會以安全為前提朝待轉牌只減不增的方向努力。交通管制工程處處長說明，預計於6月底前完成堤頂大道導引標線之調整。交通局局長表示，會依據實際車流數據即刻調整港墘路左轉車道。", "response_removed": false, "topic": "機車路權與交通標線改善"}, {"citations": [{"page": 965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=18"}, {"page": 966, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=19"}, {"page": 967, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=20"}, {"page": 967, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=20"}, {"page": 968, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=21"}, {"page": 969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=22"}, {"page": 970, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=23"}], "councilor_points": ["李明賢議員指出臺北市人口持續流失且新生兒人數減少，詢問市府對於人口下降之應對策略。李明賢議員關注市民領取生育補助後遷出戶籍之狀況，建議分析原因並滾動式檢討政策。李明賢議員指出托育補助要求父母雙方皆須設籍臺北市之規定排除部分家庭，要求市府放寬對租屋等經濟弱勢家庭之補助條件。"], "response": "民政局局長說明，人口流失受房價與軌道建設影響，市府設有人口對策委員會推動重點計畫，並會修正早產兒生育補助相關規定。社會局局長表示，會優先研議租屋與經濟弱勢家庭在托育補助上的考量與照顧。", "response_removed": false, "topic": "少子女化人口對策與托育補助"}, {"citations": [{"page": 566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=6"}, {"page": 566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=6"}, {"page": 567, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=7"}, {"page": 568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=8"}, {"page": 568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=8"}, {"page": 570, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=10"}, {"page": 571, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=11"}, {"page": 569, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=9"}], "councilor_points": ["李明賢議員指出網路社群平台有賣家販售未經核准且含有褪黑激素之睡眠軟糖及瘦瘦筆，並宣稱誇大療效，要求市府積極查處。李明賢議員指出違規廣告案件量居高不下且稽查人力不足，詢問市府之因應措施。李明賢議員建議市府從源頭控管網路販售，並針對重複違規之累犯業者加重處分以保障消費者權益。"], "response": "衛生局局長與食品藥物管理科科長說明，未經許可販售含褪黑激素產品涉違法藥物會移送檢調，並會聯繫中央與平台要求下架或屏蔽訊息。衛生局局長與食品藥物管理科科長表示，會補滿稽查員額並加重累犯業者之處分，持續研議改善方案。", "response_removed": false, "topic": "網路違規藥品與醫療廣告查處"}, {"citations": [{"page": 1898, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=28"}, {"page": 1900, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=30"}, {"page": 1900, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=30"}, {"page": 2245, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=27"}], "councilor_points": ["李明賢議員指出臺北市設有瓦斯設備之學校中，僅約半數裝設瓦斯漏氣火警自動警報設備，關心校園安全防護狀況。李明賢議員表示瓦斯漏氣偵測設備費用不高，建議教育局與產業發展局主動提供經費補助並輔導學校全面加裝。"], "response": "教育局局長說明，會即刻督導學校並提供相關經費協助加裝偵測設備。產業發展局局長表示，會與教育局橫向溝通，協助學校加速相關設備之更新。", "response_removed": false, "topic": "校園瓦斯安全設備裝設與補助"}, {"citations": [{"page": 554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=22"}, {"page": 555, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=23"}, {"page": 556, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=24"}, {"page": 2914, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=7"}, {"page": 2914, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=7"}, {"page": 556, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=24"}], "councilor_points": ["李明賢議員指出道路挖掘違規裁罰金額過低，導致部分業者多次違規仍罰不怕，無法達到嚇阻效果。李明賢議員指出新建工程處委外廠商未申請路證即於學校周邊封路施工，影響交通與學生安全。李明賢議員建議市府建立累犯連續處罰與三振機制，並檢討內部督導與懲處責任。"], "response": "市長與道路挖掘管理中心主任說明，違規多屬行政程序問題，會檢討施工維護管理辦法，並研議加重處罰或連續處罰機制。工務局局長表示，會進行深切檢討並訂出檢討計畫與相關懲處。", "response_removed": false, "topic": "道路挖掘違規裁罰與施工管理"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=17", "transcript_pages": [549, 550, 551, 552, 553, 554, 555, 556, 557, 558, 559, 560, 570], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 2}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=1", "transcript_pages": [2908, 2909, 2910, 2911, 2912, 2913, 2914, 2915], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 3}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=1", "transcript_pages": [561, 566, 567, 568, 569, 570,