 "group": 10}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=13", "transcript_pages": [239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162','2026-10-01T02:10:06Z');
INSERT INTO "fact" VALUES('summary:14-05:pc524c2d6ef','pc524c2d6ef','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:55:36Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=34"}, {"page": 2920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=13"}, {"page": 2922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=15"}, {"page": 2922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=15"}, {"page": 568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=36"}, {"page": 568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=36"}, {"page": 569, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=37"}, {"page": 2927, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=20"}, {"page": 567, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=35"}, {"page": 2925, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=18"}], "councilor_points": ["李柏毅議員指出臺北市屋齡超過30年的房屋達10萬棟，但過去26年平均每年僅完成10件都市更新，質疑推動進度過慢，並反映都市更新處員額缺額達20%、加班費支領比例過低及過度補休等問題，要求市府檢討人力與福利政策。李柏毅議員舉921危樓都市更新案完成後因稅務與地政權管爭議卡關為例，要求市府於1週內協調解決並簡化產權登記行政流程。李柏毅議員建議市府將30%的防災型都更容積獎勵置於容積移轉之前，以確保民眾能夠實質獲益。"], "response": "市長表示會盡努力減少都市更新處人力缺額，並承諾在合法程序下於1週內了解並處理危樓案的稅單開立爭議。人事處處長與都市發展局局長說明已採取彈性進用、專技轉任及爭取工程獎金等措施留才，並會檢討加班費預算與研擬精進策略。都市更新處處長說明會透過分流審議加速無爭議案件，並確認防災型都更獎勵屬於專屬獎勵，會在審議中確保民眾可以拿到。", "response_removed": false, "topic": "都市更新推動進度與人力及行政流程改善"}, {"citations": [{"page": 232, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=6"}, {"page": 233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=7"}, {"page": 234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=8"}, {"page": 235, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=9"}, {"page": 235, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=9"}, {"page": 236, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=10"}, {"page": 238, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=12"}, {"page": 239, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=13"}, {"page": 237, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=11"}], "councilor_points": ["李柏毅議員指出新北市公車設有到站顯示螢幕及車上無線網路（Wi-Fi），建議臺北市公車研議比照裝設更清晰的到站顯示設備，並要求市府於2個月內提出全市公車候車亭普及免費無線網路的計畫。李柏毅議員反映臺北捷運僅在旅客詢問處等熱點提供免費無線網路，月臺與車廂內部卻缺乏訊號，要求捷運公司於1個月內評估強化月臺與車廂無線網路設備的成本與可行性。"], "response": "公共運輸處處長表示提供清楚的到站訊息與預估時間是努力方向，會研議公車到站顯示螢幕，並承諾於2個月內就候車亭免費無線網路進行盤點與提報計畫。臺北大眾捷運股份有限公司總經理說明列車未提供無線網路係考量韓國與臺灣網路吃到飽費用差異及成本效益，但承諾會在1個月內評估強化月臺通訊與無線網路服務之技術及費用。", "response_removed": false, "topic": "公車與捷運大眾運輸資訊顯示及無線網路服務改善"}, {"citations": [{"page": 1871, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=1"}, {"page": 1872, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=2"}, {"page": 1874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=4"}, {"page": 1874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=4"}, {"page": 1875, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=5"}, {"page": 1875, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=5"}], "councilor_points": ["李柏毅議員指出世壯運官方周邊商品店發生多元支付設備故障及現場人員宣稱無法使用悠遊卡之情況，且擺放於市政府前的吉祥物氣球出現嚴重色差，要求市府加強營運管理與品質控管。李柏毅議員反映中正運動中心重新營運前存在多項缺失與設備損壞，質疑市府督導不周，要求體育局積極協調並確保能在預定日期順利啟用。"], "response": "觀光傳播局局長及綜合行銷科科長說明現場平時皆有提供悠遊卡支付服務，可能因多元支付設備故障或人員教育訓練不足造成誤會，並表示會深入了解吉祥物氣球色差原因。體育局局長及運動產業科科長說明已陸續修整改善運動中心缺失，會依契約公平處理相關費用，並承諾中正運動中心會在6月7日正式啟用。", "response_removed": false, "topic": "世界壯年運動會籌備營運與運動中心啟用管理"}, {"citations": [{"page": 2219, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=1"}, {"page": 2220, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=2"}, {"page": 2222, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=4"}, {"page": 2224, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=6"}, {"page": 2225, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=7"}, {"page": 2223, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=5"}, {"page": 2221, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=3"}], "councilor_points": ["李柏毅議員關注輝達總部傳出意圖落腳北投士林科技園區T17及T18地號土地，提醒市府該地已設定地上權予新光人壽，合約原則上不得轉移，要求市府釐清第三方插手或合作的適法性問題。李柏毅議員要求市府主動掌握相關訊息並嚴謹研議合約，在不違法、不陷入圖利疑慮的前提下，全力協助輝達進駐臺北市及相關供電配套設施。"], "response": "產業發展局局長表示市府會全力爭取並協助世界級科技企業進駐臺北市，若有相關契約問題會依合約進行。財政局局長說明該案為設定地上權契約而非BOT，依約須於取得全部建物使用執照並經市府審查同意後始得移轉，若乙方違約終止契約，市府將重新辦理公開招標。", "response_removed": false, "topic": "輝達總部進駐北士科土地合約適法性與協助"}, {"citations": [{"page": 571, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=39"}, {"page": 572, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=40"}, {"page": 572, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=40"}, {"page": 573, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=41"}], "councilor_points": ["李柏毅議員反映接獲民眾陳情天然氣公司接獲瓦斯漏氣通報後，因配合店家營業未立即遮斷，延遲近6個小時才處理，要求市府在一週內提出檢討報告並落實標準作業程序。李柏毅議員指出臺北市50年以上老舊天然氣管線達225公里，且缺乏法定汰換年限，建議市府比照自來水管訂定瓦斯管線使用年限，以確保公共安全。"], "response": "產業發展局局長說明依規定瓦斯公司應於30分鐘內到場判斷處置，事件必定以公安為優先，承諾在1週內提出檢討報告，並會與專家及中央能源署討論研議訂定瓦斯管線使用年限。消防局局長說明一般通說是確認洩漏位置後處理，以防止災害事故擴大。市長表示牽涉公共安全應按標準作業程序辦理，會請相關局處深入了解，並研議訂定管線使用年限。", "response_removed": false, "topic": "天然氣管線洩漏處置機制與老舊管線汰換年限"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=32", "transcript_pages": [564, 565, 566, 567, 568, 569, 570, 571, 572, 573, 574, 575], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 2}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=13", "transcript_pages": [2920, 2921, 2922, 2923, 2924, 2925, 2926, 2927, 2928], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 3}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=2", "transcript_pages": [562, 563, 593], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 15}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=1", "transcript_pages": [948, 949, 950, 951, 952, 953, 954], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 16}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=1", "tra