INSERT INTO "fact" VALUES('summary:14-05:p072095ef7a','p072095ef7a','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:57:09Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 660, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=10"}, {"page": 546, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=11"}, {"page": 547, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=12"}, {"page": 547, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=12"}, {"page": 318, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=14"}, {"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=10"}, {"page": 322, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=18"}], "councilor_points": ["李芳儒議員指出個人行動器具違規件數增加且民眾不熟悉規範，建議市府參考國外與國內試行經驗，運用電子圍欄與 GPS 技術建立智慧監管機制，以管理個人行動器具之行駛區域與車速。李芳儒議員要求交通局檢視人行道號誌共桿與天空纜線地下化，並明確劃分道路與非道路空間，同時研議在電動輔助自行車設置電子圍欄以提升行人友善環境。"], "response": "警察局局長與交通管制工程處總工程司說明個人行動器具不能行駛於慢車道與人行道，交通局運輸管理科技正表示目前個人行動器具僅能在學校或特定封閉場域行駛。交通局運輸管理科技正說明車輛審驗標準屬中央權責，交通局局長則表示樂於了解高雄等地的電子圍欄實施經驗並進行研議。", "response_removed": false, "topic": "個人行動器具監管與道路交通安全規劃"}, {"citations": [{"page": 655, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=5"}, {"page": 691, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=29"}, {"page": 655, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=5"}, {"page": 655, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=5"}, {"page": 657, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=7"}, {"page": 657, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=7"}, {"page": 658, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=8"}, {"page": 659, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=9"}, {"page": 693, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=31"}], "councilor_points": ["李芳儒議員建議將秘書處、人事處、主計處、政風處、研考會、資訊局、法務局及公訓處等 8 個幕僚單位整併為行政管理局，以簡化組織結構並優化人力。李芳儒議員說明各幕僚單位導入 AI 的具體方向，並建議由原住民族事務委員會與建築管理工程處優先試辦補助申請及建照審查之 AI 化。李芳儒議員要求市府建構幕僚 AI 整合平臺，降低跨局處系統重複開發之成本。"], "response": "市長表示市府已公布使用人工智慧作業指引，鼓勵各局處透過概念驗證（POC）引進 AI 新技術以提高行政效率，並請建築管理工程處與都市更新處評估研議導入 AI。秘書長表示整併 8 個單位涉及個別法令限制而有困難，但認同重複性業務應透過 AI 整合，研究發展考核委員會主任委員亦表示數位治理概念應貫穿全府。", "response_removed": false, "topic": "市府幕僚單位整併與行政資源 AI 化"}, {"citations": [{"page": 652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=2"}, {"page": 652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=2"}, {"page": 652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=2"}, {"page": 688, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=26"}, {"page": 689, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=27"}, {"page": 690, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=28"}], "councilor_points": ["李芳儒議員說明臺灣原住民族由 9 族正名為 16 族之歷史與正名條件，並強調依據憲法增修條文與原住民族基本法，原住民族權益屬集體權利與歷史補償，政策制定不應實施排富原則。李芳儒議員建議原住民族事務委員會研議給予第一代非原住民配偶相應之福利措施，並將原住民長照收容安置補助區域擴大至新北市、基隆市及宜蘭縣。李芳儒議員建議針對取得照護訓練證照且在家自行照顧失能家屬之原住民家庭給予補助。"], "response": "市長對於原住民族正名關係進行回應，並同意議員對原住民族政策方向之建議。原住民族事務委員會主任委員表示已在修正補助作業要點，預計 6 月修正完成以擴大長照安置補助區域至新北市、基隆市及宜蘭縣，並會針對非原住民配偶福利與自家照顧補助進行研議。", "response_removed": false, "topic": "原住民族權益與政策保障"}, {"citations": [{"page": 693, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=31"}, {"page": 1934, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=13"}, {"page": 1935, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=14"}], "councilor_points": ["李芳儒議員指出非學校型態實驗教育機構借用公有校舍之租金低廉，與其收取的昂貴學費不成比例，恐產生公有資源支撐私人收費之不對等情形。李芳儒議員建議教育局研究訂定落日條款、建立合理的使用費機制，並引導教育理念相近之非學機構與市立實驗學校進行合作或合併。"], "response": "教育局局長說明已注意到非學機構收費偏高情形並將納入評鑑參考，未來續租場地時會要求機構與學校增加互動交流。教育局局長表示同意對理念相近單位的融合進行討論，並會將落日條款、使用費機制與實驗學校資源整合等建議帶回研議。", "response_removed": false, "topic": "非學校型態實驗教育機構管理與資源整合"}, {"citations": [{"page": 659, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=9"}, {"page": 659, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=9"}, {"page": 660, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=10"}, {"page": 660, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=10"}], "councilor_points": ["李芳儒議員指出臺北市屋齡 40 年以上房屋占 79%，建議市府以基地面積大且房型單純之整建住宅（如南機場一號基地）作為公辦都更基地，採政府出資、民眾以地換屋方式辦理。李芳儒議員建議市府配合大都更與防災型都更需求，妥善規劃中繼住宅及日照、托育等社會福利設施。"], "response": "都市發展局局長說明目前保留 517 戶社宅作為都更中繼使用，已申請配租 349 戶。市長表示整建住宅為市府推動重點，已推出專案增加容積獎勵與貸款利息補助，並調降公辦都更意願門檻至 80%，將持續協助各整宅項目之整合與推進。", "response_removed": false, "topic": "整建住宅公辦都更與中繼住宅規劃"}, {"citations": [{"page": 1936, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=15"}, {"page": 1937, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=16"}, {"page": 1937, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=16"}], "councilor_points": ["李芳儒議員指出臺北市高齡化程度高，卻缺乏衛福部核定之銀髮健身俱樂部據點。李芳儒議員建議體育局與教育局合作，盤點校園閒置空間引進高齡健康訓練設備，並將雲端 AI 智慧健身設備普及至運動中心與健康中心。"], "response": "體育局局長表示會積極推動導入適合長者之 AI 訓練設備，並與教育局保持聯繫。教育局局長表示將檢討校園樂齡學堂等空間，規劃開設長者健身課程並擬訂辦理時程。", "response_removed": false, "topic": "銀髮族智慧健身設備普及與校園閒置空間利用"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=1", "transcript_pages": [651, 652, 654, 655, 657, 658, 659, 660, 661], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162", "videos": [{"date": "2025-06-02", "group": 4}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 6}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/