INSERT INTO "fact" VALUES('summary:14-05:p772a0a5bf9','p772a0a5bf9','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T09:58:37Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 843, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=1"}, {"page": 844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=2"}, {"page": 845, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=3"}], "councilor_points": ["指出輝達預計進駐北投士林科技園區T17與T18用地，使科技產業專用區腹地趨於飽和。建議市府針對洲美里9鄰與10鄰後段約八十幾公頃土地辦理整體規劃開發，並先解除禁建限制或開放修繕，以提供科技園區所需腹地。"], "response": "市長表示會進行整體評估，都市發展局將依都市計畫法做通盤考量，該區域未來有機會作為市政儲備用地並積極推動規劃。", "response_removed": false, "topic": "北投士林科技園區整體開發與洲美里後段解禁"}, {"citations": [{"page": 399, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=9"}], "councilor_points": ["指出市立聯合醫院總院區編制員額增加至1,076位，實際在院本部服務者僅617位，要求查明其餘員額安置情形。指出聯醫每年藥品採購金額達三十多億元，原裝藥比例偏低，並要求更換涉違法瑕疵之藥劑部主管。"], "response": "市立聯合醫院院長與衛生局局長表示會徹查員額與藥品採購問題，並說明已啟動藥劑部主管遴選程序。", "response_removed": false, "topic": "臺北市立聯合醫院員額編制與藥品採購機制檢討"}, {"citations": [{"page": 848, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=6"}, {"page": 849, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=7"}], "councilor_points": ["指出圓山風景區內市民形成的休閒聚落遭市府列為違建拆除，壓縮長者活動空間。要求市府暫緩未拆除部分，並由秘書長或副市長召集相關單位進行整合規劃，設置涼亭、廁所及運動休閒設施。"], "response": "大地工程處處長說明該區域經清查有132座違建，因大型棚架存在危險性，預計分批拆除。市長表示會依監察院要求依法辦理，並做完整的整體規劃。", "response_removed": false, "topic": "圓山風景區違建拆除與休閒場域整合規劃"}, {"citations": [{"page": 2070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=17"}, {"page": 2071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=18"}, {"page": 2072, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=19"}], "councilor_points": ["指出台北畜產公司向承銷人收取的管理費過低，導致每隻家禽銷售虧損，且負擔屠宰業者營運成本。要求市府與畜產公司落實董事會決議及承諾，將管理費率調升至千分之1.5，並檢討屠宰線續約與經營機制。"], "response": "台北畜產公司董事長說明管理費已調升至千分之1.15，未來會朝千分之1.5努力，並於合約到期後按建議處理。產業發展局局長表示已責成畜產公司與業者密切溝通。", "response_removed": false, "topic": "台北畜產公司經營管理與費用調漲檢討"}, {"citations": [{"page": 849, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=7"}, {"page": 474, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=23"}, {"page": 850, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=8"}], "councilor_points": ["指出北投市場拆除重建致使周遭交通進入黑暗期，且中繼市場佔用原有的83個停車位。建議市府向台鐵局協調，將鄰近台鐵員工訓練中心舊址約1.2公頃土地規劃為臨時停車場。"], "response": "交通局局長說明已與台鐵局溝通，台鐵局有意將該處規劃為停車場，市府會積極協助並共同促成。", "response_removed": false, "topic": "北投市場重建交通因應與臨時停車場規劃"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=1", "transcript_pages": [843, 844, 845, 846, 847, 848, 849, 850, 851, 852, 853, 854, 855], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "videos": [{"date": "2025-06-05", "group": 8}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=13", "transcript_pages": [3033, 3034, 3035, 3036, 3037], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 8}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=6", "transcript_pages": [396, 397, 398, 399, 400, 401, 402, 403, 404, 405], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 7}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=22", "transcript_pages": [770, 771, 772, 773, 774, 775, 776, 777], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 7}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=4", "transcript_pages": [1835, 1836, 1837, 1838, 1839, 1840, 1841], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 10}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=17", "transcript_pages": [2070, 2071, 2072, 2073, 2074, 2075], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162", "videos": [{"date": "2025-05-13", "group": 3}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=22", "transcript_pages": [473, 474, 475, 476, 477, 478], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162", "videos": [{"date": "2025-05-26", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/