INSERT INTO "fact" VALUES('summary:14-05:pcc848fb570','pcc848fb570','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:00:04Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 628, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=33"}, {"page": 629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=34"}, {"page": 629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=34"}, {"page": 630, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=35"}, {"page": 627, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=32"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=30"}, {"page": 628, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=33"}], "councilor_points": ["林亮君議員指出中央暫緩核撥一般性補助款約37億元將影響市府各局處預算與政策執行。林亮君議員建議市長說服同黨立法委員支持行政院辦理追加預算，以利儘速解決地方補助款撥付問題。"], "response": "市長說明被刪除的預算依法無法以追加預算方式補上，並表示最快方式為請行政院直接撥付核定的地方一般性補助款。消防局局長說明相關裝備採購因中央預算凍結與統籌分配調整而受到影響。主計處處長說明一般性補助款分為指定辦理與非指定項目。", "response_removed": false, "topic": "中央一般性補助款扣減影響與因應"}, {"citations": [{"page": 633, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=38"}, {"page": 871, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=15"}, {"page": 1673, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=17"}, {"page": 1674, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=18"}, {"page": 634, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=39"}, {"page": 1674, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=18"}], "councilor_points": ["林亮君議員指出高中與國中小生理用品補助兌換率停滯於四成左右，建議將酷課雲派券改為結合數位學生證靠卡領取並擴增品項與通路。林亮君議員要求市府研議於親子館及區公所等公營場館服務台提供急用生理用品。"], "response": "教育局局長表示將研議調整兌換管道與品項，並與研究發展考核委員會合作檢視執行成效。市長承諾於1個月內盤點各局處轄管公有場地與親子館等設施並評估擴大提供急用生理用品。研究發展考核委員會主任秘書表示將與教育局合作進行政策研考。", "response_removed": false, "topic": "學生與公共場館月經平權政策推進"}, {"citations": [{"page": 866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=10"}, {"page": 866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=10"}, {"page": 868, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=12"}, {"page": 869, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=13"}], "councilor_points": ["林亮君議員建議社會局擴大青年脫貧專案招募名額並放寬每戶限1人參加之限制，同時結合青年局資源導入國際職涯培力。林亮君議員詢問低收入戶就學及交通補助限制25歲以下之原因，建議針對25歲以上有回頭就學進修需求者建立彈性評估機制。"], "response": "社會局局長說明專案名額與備取機制會進行評估，並同意就超過25歲之特殊個案由社工進行彈性評估與資源連結。青年局局長表示青年赴海外實習計畫對經濟弱勢身分者會給予特別考量並提供生活津貼補助，樂意與社會局合作。", "response_removed": false, "topic": "青年脫貧專案名額與低收入戶就學補助條件放寬"}, {"citations": [{"page": 630, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=35"}, {"page": 631, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=36"}, {"page": 632, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=37"}, {"page": 633, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=38"}], "councilor_points": ["林亮君議員指出世壯運禮包合約禁止中國製產品且品項缺乏產地與材質標示，質疑市府於賽事結束後的6月才驗收無法事前把關品質與食安。林亮君議員要求市府將審核程序前置，於前期即要求廠商提供產地證明與相關文件。"], "response": "體育局局長說明目前採分期給付並於6月驗收，針對外界疑慮已要求廠商提供證明文件，若經查違約將依約扣款開罰。市長表示未來會檢視並研議將合約中的審核程序往前提。", "response_removed": false, "topic": "世壯運禮包設計製作與驗收流程審查"}, {"citations": [{"page": 439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=8"}, {"page": 440, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=9"}, {"page": 440, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=9"}], "councilor_points": ["林亮君議員指出清潔隊員心理諮詢服務使用率極低，主因為通報須經區隊長與人事室呈報，缺乏隱密性致隊員不敢使用。林亮君議員要求環境保護局改善諮詢環境，建立獨立且具隱密性的專屬心理諮詢管道。"], "response": "環境保護局局長坦言現行流程經由區隊長確實可能造成陳情障礙，承諾於1個月內研議改善通報流程並提供獨立隱密之諮詢空間。", "response_removed": false, "topic": "清潔隊員心理衛生與職場照護機制"}, {"citations": [{"page": 3161, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=16"}, {"page": 3161, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=16"}, {"page": 3163, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=18"}, {"page": 3163, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=18"}], "councilor_points": ["林亮君議員指出臺北市老舊建築比例高但都更審議天數冗長，建議借鏡建築管理工程處之委託審查雙軌制，推動都更師制度化以分攤審查量能。林亮君議員要求都市更新處向中央反映建議，促使都更專業審查制度化。"], "response": "都市更新處處長說明目前已有專業估價師提前進場與行政助手預審等分流機制以加速審查，並表示會將都更專業制度化之建議向中央反映。", "response_removed": false, "topic": "都市更新審議效率與專業制度化研議"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=30", "transcript_pages": [625, 626, 627, 628, 629, 630, 631, 632, 633, 634, 635, 636], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D86