338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=16", "transcript_pages": [1672, 1673, 1674, 1675, 1676, 1677, 1678], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 1}]}, {"dates": ["2025-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1AC32224B63560F40F78DCC91A3FE9A73F17CD805578FC087A852238F00A7C162#page=1", "transcript_pages": [2173, 2174, 2175, 2176, 2177], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1AC32224B63560F40F78DCC91A3FE9A73F17CD805578FC087A852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 7}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 6, "heading": "交通部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=14", "transcript_pages": [294, 295, 296, 297, 298], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 6}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162','2026-10-01T10:00:04Z');
INSERT INTO "fact" VALUES('summary:14-05:p5fb3d560bb','p5fb3d560bb','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:02:14Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1169, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=29"}, {"page": 1169, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=29"}, {"page": 1994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F4894335C47D45DB616BC257C5FAB6DE678DDC56B32FFABCA852238F00A7C162#page=2"}, {"page": 1994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F4894335C47D45DB616BC257C5FAB6DE678DDC56B32FFABCA852238F00A7C162#page=2"}, {"page": 1168, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=28"}], "councilor_points": ["林延鳳議員指出世壯運智慧手錶出現中國製及電池造假疑慮，且大禮包契約金額擴充至5,728萬5,000元，但報名人數僅2萬5,000人。林延鳳議員詢問政風處是否介入調查重複得標的違規疑慮廠商，並要求市府嚴格把關驗收、正視約聘僱人員加班未打卡之權益問題。"], "response": "體育局局長說明智慧手錶尚未進行驗收與付款，將依契約嚴格執行，並會再瞭解約聘僱人員加班情況。市長表示會依約要求廠商提供資料並追究責任，並請政風室與各局處研擬機制規範調查中廠商的投標事宜。2025雙北世界壯年運動會執行辦公室主任說明原本即編列5,000多萬元預算。", "response_removed": false, "topic": "世界壯年運動會籌備管理與採購驗收"}, {"citations": [{"page": 1999, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F4894335C47D45DB616BC257C5FAB6DE678DDC56B32FFABCA852238F00A7C162#page=7"}, {"page": 2215, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=17"}, {"page": 2215, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=17"}, {"page": 2213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=15"}, {"page": 2211, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=13"}, {"page": 2212, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=14"}, {"page": 2216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=18"}], "councilor_points": ["林延鳳議員指出前山公園男女公共浴池花費近1,700萬元整修後，仍存在水量不足與水溫不夠問題，且泉源公園泡腳池未與地方溝通即暫停開放。林延鳳議員要求市府團隊跨單位溝通合作，提早整理溫泉井並對北投溫泉資源進行合理分配與規劃。"], "response": "產業局局長說明受地震影響導致水溫驟降，已獲准辦理取供事業，並會召集相關單位進行討論規劃。臺北自來水事業處處長說明預計於12月完成溫泉井整理，且公共管線預計於115年9月完工。產業發展局公用事業科科長表示因泉源公園井水溫度下降無法恢復，目前政策方向為全力支援復興公園泡腳池。", "response_removed": false, "topic": "前山公園公共浴池與北投溫泉資源管理"}, {"citations": [{"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162#page=3"}, {"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162#page=3"}, {"page": 2958, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162#page=4"}, {"page": 2956, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162#page=2"}], "councilor_points": ["林延鳳議員指出臺北市20年以上老舊污水管線達1,086公里，但檢視進度僅約二成，且道路挖掘補丁不良導致民眾摔倒受傷。林延鳳議員要求市府針對管線較老舊的士林區與北投區優先檢視，優化地下管線綜合圖資並加強道路開挖品質控管。"], "response": "衛生下水道工程處處長說明目前已優先針對20年以上大管線進行檢視，並會將士林區與北投區老舊小管線納入後續計畫優先推動。工務局局長表示因台電施工未落實品質控管，後續會對瑕疵扣點計罰，並承諾於1個月內提供改善說明報告。", "response_removed": false, "topic": "老舊污水管線檢視與道路挖掘品質控管"}, {"citations": [{"page": 1172, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=32"}, {"page": 1173, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=33"}, {"page": 1170, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=30"}, {"page": 1171, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=31"}, {"page": 1173, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=33"}], "councilor_points": ["林延鳳議員引用民調指出市長施政滿意度為六都倒數第二、不滿意度達27.7%，且街訪顯示民眾對施政成果無感。林延鳳議員要求市府專注於市政建設，並提醒市長與市府團隊在面對選舉與罷免議題時應堅守行政中立原則。"], "response": "市長說明任內推進大巨蛋啟用、捷運興建、生生喝鮮奶、都更與減債等政策，並表示各界指教皆會虛心接受。市長表示會研擬機制，並對中央施政抱持同樣的標準與期許。", "response_removed": false, "topic": "市政績效評估與行政中立規範"}, {"citations": [{"page": 653, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491B30518CFD9CFC28222903D15D8D1843C79DEE27FED1BA86A852238F00A7C162#page=19"}, {"page": 654, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491B30518CFD9CFC28222903D15D8D1843C79DEE27FED1BA86A852238F00A7C162#page=20"}, {"page": 655, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491B30518CFD9CFC28222903D15D8D1843C79DEE27FED1BA86A852238F00A7C162#page=21"}], "councilor_points": ["林延鳳議員指出遊行活動疑有外籍學生及移工被動員參與並支領每人800元報酬，要求市府若查明人力仲介公司違法應嚴加裁處。林延鳳議員亦指出北市醫療院所近5年發生171件誤用非法移工案，建議市府加強宣導與源頭管理。"], "response": "勞動局局長說明外國人參與合法集會遊行受相關法規規範，身分與活動認定由移民署調查，並說明雇主若不知情誤用非法外勞原則上不予處罰但會裁罰違法仲介。勞動力重建運用處處長表示尊重檢調與移民署調查結果，若確認違法事證將依就業服務法處理。", "response_removed": false, "topic": "遊行活動疑涉動員移工與非法移工查處"}, {"citations": [{"page": 222, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC13484A3803147BA1BA066F097ED9D423BC302EB24EEFCFC82A852238F00A7C162#page=13"}, {"page": 222, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC13484A3803147BA1BA066F097ED9D423BC302EB24EEFCFC82A852238F00A7C162#page=13"}, {"page": 223, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC13484A3803147BA1BA066F097ED9D423BC302EB24EEFCFC82A852238F00A7C162#page=14"}], "councilor_points": ["林延鳳議員指出輝達宣布進駐北士科前，士林與北投主要幹道已長期塞車，道路服務水準恐惡化至F級。林延鳳議員要求市府預先做妥交維計畫與交通改善配套，並跨局處盤整廠商進駐量體進行整體交通評估。"], "response": "交通局局長說明預計於年底提出士林北投整體交通規劃，並會整理各項工程開工日程以避免重疊，同時加速規劃接駁路線與公車路網。", "response_removed": false, "topic": "北投士林科技園區周邊交通衝擊與配套規劃"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-12"], "dept": null, "doc_type": "市政總質詢", "group": 16, "heading": "市政總質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162#page=28", "transcript_pages": [1168, 1169, 1170, 1171, 1172, 1173, 1174, 1175, 1176, 1177, 1178], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162", "videos": [{"date": "2025-06-12", "group": 16}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162#page=1", "transcript_pages": [2955, 2956, 2957, 2958, 2959], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665498E635348AD96312B8C7717274067087FE5CB492381A81ED2A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 5}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549CA7E1D473E4692C7E7E20318967E66E3A4F6D7A86D1488CAA852238F00A7C162#page=6", "transcript_pages": [377, 378, 379, 380, 381, 382, 383, 384], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549CA7E1D473E4692C7E7E20318967E66E3A4F6D7A86D1488CAA852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 6}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491B30518CFD9CFC28222903D15D8D1843C79DEE27FED1BA86A852238F00A7C162#page=17", "transcript_pages": [651, 652, 653, 654, 655], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491B30518CFD9CFC28222903D15D8D1843C79DEE27FED1BA86A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 2}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F4894335C47D45DB616BC257C5FAB6DE678DDC56B32FFABCA852238F00A7C162#page=1", "transcript_pages": [1993, 1994, 1995, 1996, 1997, 1998, 1999], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F4894335C47D45DB616BC257C5FAB6DE678DDC56B32FFABCA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 16}]}, {"dates": ["2024-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162#page=12", "transcript_pages": [2210, 2211, 2212, 2213, 2214, 2215, 2216, 2217, 2218], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1DC35B9DBF5242693BCDA3DCAE4FCE1A8325225D7BABD5CE8A852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 9}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC13484A3803147BA1BA066F097ED9D423BC302EB24EEFCFC82A852238F00A7C162#page=12", "transcript_pages": [221, 222, 223, 224, 225, 226], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC13484A3803147BA1BA066F097ED9D423BC302EB24EEFCFC82A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 4}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC10E5FDE2D5851F0A744D2262CA66AF22FBA8AC1ECF4E0DE26A852238F00A7C162','2026-10-01T10:02:14Z');
INSERT INTO "fact" VALUES('summary:14-05:pcdef61ef89','pcdef61ef89','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:03:51Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1120, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=40"}, {"page": 1121, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=41"}, {"page": 42, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=10"}, {"page": 337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=2"}, {"page": 1122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=42"}, {"page": 339, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=4"}, {"page": 1122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=42"}, {"page": 338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=3"}, {"page": 1123, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=43"}, {"page": 340, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=5"}], "councilor_points": ["林杏兒議員指出輝達進駐北士科園區後，周邊社子島開發案從動工到進駐預計需時 14 年，建議市府效仿其他重劃區縮短開發期程至 7 年完工。林杏兒議員要求市府重新評估洲美快速道路與淡北道路採全線高架規劃，以避免車流匯入平面道路造成嚴重壅塞。林杏兒議員建議社子輕軌分兩階段興建並於洲美地區暫設機廠，且研議將捷運淡水線芝山站延伸支線至北士科園區以滿足通勤需求。"], "response": "臺北市市長表示社子島開發案已提起上訴，並將依照目前規劃期程推進。交通局局長說明將檢討大度路快慢分隔島打除與車流分流方案，並審慎評估洲美快速道路與大度路高架動線的可行性。捷運工程局局長表示已將社子輕軌南北向先行及尋找洲美地區暫設機廠納入第一方案，並會研究捷運支線延伸路廊的可行性。", "response_removed": false, "topic": "北士科園區整體開發與交通配套"}, {"citations": [{"page": 1980, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=12"}, {"page": 1982, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=14"}, {"page": 1983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=15"}, {"page": 1983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=15"}], "councilor_points": ["林杏兒議員詢問 2025 雙北世界壯年運動會官網推薦旅遊行程之價格審核機制，指出阿朗壹古道 3 日遊行程在官網售價達 23,000 元至 25,000 元，遠高於旅行社官網相同行程之 12,000 元至 13,000 元。林杏兒議員表示市府背書之得獎行程價格過高且價差達一倍，易引發消費爭議，要求市府檢討審查標準與契約規範。"], "response": "觀光傳播局局長說明相關行程係經徵選評估合理價格，且有推薦 30 條自由行路線供選手選擇，承諾會全面盤點網路類似行程並進行調整。觀光傳播局觀光發展科科長說明官網推薦行程係因廠商保證 6 人即可出團，旅行社已調整網路原產品。法務局主任消費者保護官說明業者須充分正確揭露消費資訊，且旅遊契約須符合中央規定。", "response_removed": false, "topic": "2025世界壯年運動會推薦旅遊行程價格審核"}, {"citations": [{"page": 321, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=6"}, {"page": 934, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=12"}, {"page": 935, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=13"}, {"page": 936, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=14"}, {"page": 933, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=11"}, {"page": 935, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=13"}], "councilor_points": ["林杏兒議員指出罷免連署作業中，連署表格影印產生 0.2 公分誤差、字體粗細體變更、樓層填寫及簡體字書寫等認定標準混亂，造成民眾與連署團體困擾。林杏兒議員建議市府向中央選舉委員會正式提議，比照有效票認定標準制定一套明確統一的罷免連署有效與無效認定規範，並調整連署書格式為一人一格。"], "response": "民政局戶籍行政科科長說明中央選舉委員會表示收件時不會拿尺量測表格尺寸，僅確認整體格式是否正確。民政局局長表示連署書最終認定權在中央選舉委員會，對於塗改部分僅剔除該個人，並同意向中央選舉委員會正式反映制定明確標準之建議。", "response_removed": false, "topic": "罷免連署作業審核標準與格式規範"}, {"citations": [{"page": 3133, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=15"}, {"page": 316, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=1"}, {"page": 317, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=2"}, {"page": 318, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=3"}, {"page": 319, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=4"}], "councilor_points": ["林杏兒議員詢問陽明山七星山山林大火延燒狀況與搶救 SOP，指出山林火災延燒迅速，應注意預防延燒至建築物。林杏兒議員指出全臺北市領有臂章可進入火場協勤之義消共有 115 人，但部分分隊面罩及消防裝備不足，且手套汰換速度慢，要求市府儘快補足配備以保障打火弟兄安全。"], "response": "消防局局長說明七星山火災受天候與山區地形影響，搶救重點在於防止延燒至建築物，並承諾盤點及補齊義消個人裝備。消防局災害搶救科科長補充說明將立即補足 115 位領臂章義消的面罩不足部分，並定期檢測面罩與清洗消防衣。", "response_removed": false, "topic": "陽明山山林火災搶救與義消裝備保障"}, {"citations": [{"page": 336, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=1"}, {"page": 1119, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=39"}, {"page": 337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=2"}, {"page": 337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=2"}], "councilor_points": ["林杏兒議員指出行政院刪減臺北市一般性補助款近 38 億元，嚴重影響社會福利、教育及基礎建設。林杏兒議員要求市府態度應保持強硬，建議財政局聯合全國地方政府共同向中央提起行政訴訟，追回被刪減之補助款項。"], "response": "臺北市市長表示將窮盡所有方法爭取市民應有福利，若訴願遭駁回將提起行政訴訟尋求救濟。財政局副局長說明 114 年度一般性補助款由 138.9 億元減為 101 億元，市府已發函行政院要求補足，並將研議訴訟等方式確保市政運作。", "response_removed": false, "topic": "中央刪減地方一般性補助款爭議"}, {"citations": [{"page": 319, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=4"}, {"page": 320, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=5"}, {"page": 321, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=6"}], "councilor_points": ["林杏兒議員指出臺北市 1、2 月投資詐騙金額超過 10 億元，且警方目前多僅查獲車手而難以突破詐騙集團核心首腦。林杏兒議員建議市府建立高額「窩裡反」獎勵金制度，提高舉報上線獎金至 50 萬元並提供保護措施，以吸引車手擔任內線協助抓獲詐騙首腦。"], "response": "警察局局長說明臺灣警方能查獲車手、車手頭及洗錢中心，但機房多設於境外，並表示高額獎金舉發制度確實會有效果，將向中央警政署與刑事局反映研議提高獎金。", "response_removed": false, "topic": "詐騙案件防制與車手舉報獎勵機制"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-10"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=38", "transcript_pages": [1118, 1119, 1120, 1121, 1122, 1123, 1124, 1125, 1126, 1127], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162", "videos": [{"date": "2025-06-10", "group": 14}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 13, "heading": "工務部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=9", "transcript_pages": [3127, 3128, 3129, 3130, 3131, 3132, 3133, 3134], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 13}]}, {"dates": ["2025-04-14"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 3, "heading": "警政衛生部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=1", "transcript_pages": [316, 317, 318, 319, 320, 321, 322], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162", "videos": [{"date": "2025-04-14", "group": 3}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=11", "transcript_pages": [933, 934, 935, 936, 937, 938, 939], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 15}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=12", "transcript_pages": [1980, 1981, 1982, 1983, 1984, 1985, 1986], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 15}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=9", "transcript_pages": [41, 42, 43, 44, 45, 46], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178D