INSERT INTO "fact" VALUES('summary:14-05:p9ff03a516c','p9ff03a516c','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:05:37Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3175, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=10"}, {"page": 3176, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=11"}, {"page": 3177, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=12"}, {"page": 3177, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=12"}, {"page": 3180, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=15"}, {"page": 3176, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=11"}, {"page": 3179, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=14"}, {"page": 3178, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=13"}, {"page": 3178, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=13"}], "councilor_points": ["林珍羽議員指出近5年外牆剝落通報達1,553案，且近一年發生2起外牆剝落砸傷民眾事件，質疑建築管理工程處外牆安檢與修繕補助執行率僅33%。林珍羽議員表示都市更新處整建維護補助近2年案件數為零，且應申報外牆安檢的建築物申報率僅18.75%，要求市府積極輔導與檢討預算執行。"], "response": "建築管理工程處處長說明外牆修繕補助已提高至20萬元，採取實支實付全額給付，並會透過管理委員會進行輔導；都市更新處處長說明已推出簡化程序的套餐方案協助民眾申請，並與建築管理工程處合作提供補助資訊。", "response_removed": false, "topic": "建築物外牆剝落防護與都市更新整建維護預算執行檢討"}, {"citations": [{"page": 362, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654952A08CBD10ED0DEFAE9C542891D139F30DBBCBB2D2D150F9A852238F00A7C162#page=16"}, {"page": 362, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654952A08CBD10ED0DEFAE9C542891D139F30DBBCBB2D2D150F9A852238F00A7C162#page=16"}, {"page": 362, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB9637356654952A08CBD10ED0DEFAE9C542891D139F30DBBCBB2D2D150F9A852238F00A7C162#page=16"}], "councilor_points": ["林珍羽議員指出醫療院所存在真實與申報護病比不符的狀況，且急診室及加護病房等特殊單位目前僅計算人床比而未納入護病比。林珍羽議員建議臺北市立聯合醫院及衛生局檢討獎金制度，修正護病比計算標準並以病房為單位計算，同時配合辦理護理專案勞檢。"], "response": null, "response_removed": true, "topic": "護理人員權益保障與特殊單位護病比計算改善"}, {"citations": [{"page": 927, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=34"}, {"page": 947, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=54"}, {"page": 948, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=55"}], "councilor_points": ["林珍羽議員指出現行75歲以上高齡駕駛每3年換照機制並無年齡上限，致高齡駕駛肇事問題頻傳。林珍羽議員建議借鏡日本駕照自願返還機制，結合企業提供生活利多優惠，協助長者建立大眾運輸生活圈，並要求交通局提報檢討報告。"], "response": "交通局局長說明正研究相關作法與資料串接可行性，承諾於兩個月內提出具體可行方案；市長表示會整體評估以鼓勵長者繳回駕照。", "response_removed": false, "topic": "高齡駕駛交通安全與駕照自願繳回誘因機制"}, {"citations": [{"page": 922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=29"}, {"page": 923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=30"}, {"page": 925, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=32"}], "councilor_points": ["林珍羽議員指出公園及人行道路面高低差與坡度影響行動不便者通行，建議以臺北躍動館新生館輪椅夢公園為起點，規劃行天宮、圓山及中山站等3條無障礙示範路線。林珍羽議員要求市府以中山區作為示範起點，建立由點到線、由線到面及制度化的無障礙通行系統。"], "response": "市長表示同意先從議員建議的路線與新生躍動館試做無障礙動線規劃，檢討改善後再擴展至其他區域。", "response_removed": false, "topic": "中山區無障礙通行系統與示範路線規劃"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-06"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162#page=29", "transcript_pages": [922, 923, 924, 925, 926, 927, 928, 946, 947, 948, 949, 950], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162", "videos": [{"date": "2025-06-06", "group": 9}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 15, "heading": "工務部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F2C320877AF8B65635BDEC69285AD7A852238F00A7C162#page=10", "transcript_pages": [3175, 3176, 3177, 3178, 3179, 3180, 3181], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB96373566549158126A65576749F79F