907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162#page=8", "transcript_pages": [2148, 2149, 2150, 2151, 2152, 2153, 2154, 2155, 2156, 2157], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1041259747D1E57CBFCA9F4E224401525ED2F36679688EC9CA852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 6}]}, {"dates": ["2025-05-23"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "heading": "交通部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162#page=1", "transcript_pages": [406, 407, 408, 409, 410, 411, 412], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC18D0911CA49993ECF8EFFEECADFF0D07843180A5AAD567469A852238F00A7C162", "videos": [{"date": "2025-05-23", "group": 13}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC13DA650E72E781E1EE1BC28D3B4379BDD30F93493FB550159A852238F00A7C162','2026-10-01T10:05:37Z');
INSERT INTO "fact" VALUES('summary:14-05:p41a7902cc9','p41a7902cc9','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T02:08:18Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1891, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=21"}, {"page": 1893, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=23"}, {"page": 2226, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=8"}, {"page": 2231, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=13"}, {"page": 2234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=16"}, {"page": 1890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=20"}, {"page": 1895, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=25"}, {"page": 2230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=12"}, {"page": 2231, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=13"}, {"page": 2233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=15"}], "councilor_points": ["柳采葳議員指出雙北世界壯年運動會外國選手報名人數與大巨蛋觀賽索票率偏低，且宣傳管道缺乏系統性與涵蓋面。柳采葳議員表示配合世壯運現金券的商圈與地下街比例過低且種類過於複雜，並關切開幕式維安因中央官員出席變更而需重新調整的情形。"], "response": "體育局局長說明志工證譯名錯誤已及時更正，並會透過跨局處合作與多元管道加強宣傳，以提高進場觀賽人數。商業處處長說明已提供多元管道整合店家優惠，市場處處長說明已協調夜市加入活動，產業局局長表示將檢討相關行銷宣傳措施以供未來借鏡。雙北世界壯年運動會執行辦公室發言人表示接獲中央通知改派副總統出席後，已立即召開準備會議並重新規劃全盤維安作業。", "response_removed": false, "topic": "雙北世界壯年運動會籌辦宣傳與商圈整合"}, {"citations": [{"page": 959, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=12"}, {"page": 960, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=13"}], "councilor_points": ["柳采葳議員指出臺北市里鄰建設服務經費基礎額度自民國 98 年維持每里每年 30 萬元迄今未因物價通膨調整，導致部分里資源不足。柳采葳議員表示現行加碼級距制度調整後，仍有 127 個里的人均經費減少，且各里間人均經費差距過大，要求市府研擬提高 30 萬元基準額度並建立平衡機制。"], "response": "民政局局長說明里鄰建設服務經費係綜合考量人口數、面積及公告土地現值等指標進行加碼補助。民政局局長表示因需顧及市府財政與財政紀律，先前擬調整為 40 萬元起跳之方案未果，但承諾會進行滾動式檢討並研擬相關精進措施。", "response_removed": false, "topic": "里鄰建設服務經費分配與基準額度調整"}, {"citations": [{"page": 586, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=26"}, {"page": 587, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=27"}, {"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=29"}, {"page": 588, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=28"}, {"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=29"}], "councilor_points": ["柳采葳議員指出青少年涉犯喪屍煙彈案件比例上升，且警方查獲涉案學生的數據與學校主動通報紀錄存在顯著落差。柳采葳議員表示各校對毒品與電子煙的校規懲處規範不一且欠缺統一標準，建議市府成立跨局處新興毒品專案辦公室，並統一校規規範與通報程序。"], "response": null, "response_removed": true, "topic": "喪屍煙彈校園防制與跨局處查緝"}, {"citations": [{"page": 228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=2"}, {"page": 229, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=3"}, {"page": 230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=4"}], "councilor_points": ["柳采葳議員詢問市府引進無車柱電子圍籬式共享電動輔助自行車試辦計畫之可行性，並質疑其若仍需設置腳踏車樁是否背離電子圍籬概念。柳采葳議員關切雙北跨區騎乘規範與制度是否一致，並要求市府重視共享車輛鋰電池之安全防護措施。"], "response": "交通局局長說明電子圍籬為無形站點管理，引進係以試辦心態提供使用者更多元便利的選擇。交通局局長表示將與新北市等鄰近縣市溝通管理規範，並會就鋰電池安全問題對業者進行謹慎要求。", "response_removed": false, "topic": "共享電動輔助自行車試辦計畫"}, {"citations": [{"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=57"}, {"page": 587, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=55"}, {"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=57"}], "councilor_points": ["柳采葳議員指出市府盤點的 28 項 AI 應用過半停留在概念驗證階段，建議資訊局提出落地進度報告。柳采葳議員指出警察局目前欠缺 AI 應用規劃且資料多為紙本，要求警察局於 1 個月內提出警政數位資料建立知識庫計畫案，並由資訊局於下會期開議前提出 1 項警政 AI 應用計畫。"], "response": "資訊局局長表示會處理 AI 落地進度報告，並強調發展 AI 需先將資料電子化與數位化，資訊局將全力協助警察局。警察局局長表示會努力做警政數位資料建立知識庫計畫案，市長表示會請警察局積極研究將 AI 應用於犯罪防治。", "response_removed": false, "topic": "警政系統導入 AI 與資料數位化"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=1", "transcript_pages": [533, 534, 535, 536, 537, 538, 539, 584, 585, 586, 587, 588, 589, 590, 591, 592, 593, 594, 595], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 2}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=8", "transcript_pages": [2915, 2916, 2917, 2918, 2919, 2920], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 3}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=2", "transcript_pages": [562, 565, 566, 585, 586, 587, 588, 589, 590, 591, 592, 593], "transcript_url": "https://gaz.tcc.g