], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=1", "transcript_pages": [227, 228, 229, 230, 231, 232], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162','2026-10-01T02:08:18Z');
INSERT INTO "fact" VALUES('summary:14-05:paf86790352','paf86790352','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:07:24Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 86, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=10"}, {"page": 87, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=11"}, {"page": 88, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=12"}], "councilor_points": ["楊植斗議員指出市府調派主管層級公務員擔任世壯運場館經理，導致部分主任級官員需請假而無法列席議會質詢。楊植斗議員表示公務人員日常政務已相當繁重，關切大量抽調人力營運場館是否會影響市政運作。楊植斗議員建議市府未來若舉辦大型盛會，應考慮編列預算委託專業經理人或廠商管理場館，讓局處官員回歸本職。"], "response": null, "response_removed": true, "topic": "大型活動場館經理指派對市政運作之影響"}, {"citations": [{"page": 2982, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=13"}, {"page": 2983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=14"}, {"page": 2983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=14"}, {"page": 2985, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=16"}, {"page": 2986, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=17"}, {"page": 2984, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=15"}, {"page": 2985, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=16"}, {"page": 2986, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=17"}], "councilor_points": ["楊植斗議員指出大安森林公園音樂臺過去有漏水狀況，詢問市府緊急維護措施與未來重新設計的預算及施工規劃。楊植斗議員表示颱風造成公園內七十株樹木倒伏，關切後續整平與補植進度，並關注苗木規格與樹木銀行平臺運用。楊植斗議員建議市府善用樹木資源媒介平臺，評估移植樹齡較大且適合的樹木補植至大安森林公園，以維護公園景觀。"], "response": "工務局公園路燈工程處處長說明音樂臺已設置透明遮雨棚改善漏水，今年進行規劃設計，明年編列施工費，並會挑選活動淡季施工。工務局公園路燈工程處處長表示倒伏的七十株樹木已於年初處理樹頭，並分兩批補植三十棵樹幹直徑八公分的苗木，其餘地點將持續評估周遭樹蔭狀況再決定是否補植。工務局局長與工務局公園路燈工程處處長說明補植樹木包含六株自其他地點移入的樹種，若公園或綠地有合適空間，會透過平臺進行較大樹木的移植媒合。", "response_removed": false, "topic": "大安森林公園設施維護與樹木倒伏補植"}, {"citations": [{"page": 686, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=36"}, {"page": 687, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=37"}, {"page": 685, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=35"}, {"page": 687, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=37"}, {"page": 688, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=38"}], "councilor_points": ["楊植斗議員表示民間企業辦理大型開發案有意申請移工協助施工，但目前因公益性認定問題而面臨卡關。楊植斗議員指出公務體系與建築產業均面臨嚴重缺工及薪資落差，若中央法規將促進就業納入公益性範圍，市府應審慎思考因應。楊植斗議員要求市府主動發函向中央主管機關詢問明確的公益性界定與促進就業標準，以利未來設定地上權及民間參與開發案有所遵循。"], "response": "土地開發總隊總隊長說明先前針對特定案件之土方處理問題曾函詢中央，中央回覆依權責卓處。臺北市市長說明財政局過去地上權案件曾基於具有公益性規定申請移工。土地開發總隊總隊長表示會再針對移工申請與公益性標準函詢中央主管機關。", "response_removed": false, "topic": "大型開發案申請移工之公益性認定標準"}, {"citations": [{"page": 2986, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=17"}, {"page": 2987, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=18"}, {"page": 2988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=19"}, {"page": 2989, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=20"}, {"page": 2990, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=21"}, {"page": 2991, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=22"}], "councilor_points": ["楊植斗議員指出市府規定六樓至七樓集合住宅需進行公共安全檢查申報，列管達七千六百多筆，關切目前申報進度與輔導機制。楊植斗議員表示公安申報費用由數萬元至數十萬元不等，民眾常不知如何選擇且欠缺專業知識，詢問市府是否設有諮詢平臺提供輔導。楊植斗議員建議市府在二〇二七年開罰前應提升輔導量能並加強宣導，針對無管委會的社區提供更簡便的諮詢管道與協助措施。"], "response": "建築管理工程處處長說明六樓至七樓公安申報於今年開始推動，目前設有輔導期，預計至一百一十六年（二〇二七年）才針對有管委會大樓開罰，一百一十八年針對無管委會大樓開罰。建築管理工程處處長表示市府每年安排約二千件現場初勘輔導，並透過新聞稿、折頁、官網宣導及舉辦說明會，協助民眾了解申報程序。", "response_removed": false, "topic": "六樓至七樓集合住宅公共安全申報與輔導"}, {"citations": [{"page": 324, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=20"}, {"page": 325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=21"}, {"page": 327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=23"}, {"page": 327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=23"}, {"page": 325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=21"}, {"page": 326, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=22"}, {"page": 328, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=24"}], "councilor_points": ["楊植斗議員指出市府成功爭取主辦二〇二九智慧運輸世界大會，預估將有二萬人次參與及兩百場論壇，屬大型國際盛會。楊植斗議員表示過去市府推動無人公車實驗未留存相關數據資料，要求市府在籌辦大會過程中汲取教訓並完善事前的數據與政策準備。楊植斗議員建議市府提早成立專案小組，並展現彈性積極向中央爭取預算補助與整合民間協會資源，以確保盛會圓滿舉辦。"], "response": "交通局局長說明該盛會係由中華民國智慧運輸協會與臺北市政府共同組團爭取，結合產官學界與中央單位資源。交通局局長表示目前正與中央政府及相關協會進行合作、經費補助及流程設計，未來會尋找專業會展執行單位協助推動。", "response_removed": false, "topic": "籌辦智慧運輸世界大會之規劃與跨單位合作"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=22", "transcript_pages": [672, 673, 674, 675, 676, 677, 678, 679, 680, 681, 682, 683, 684, 685, 686, 687, 688, 689], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162", "videos": [{"date": "2025-06-02", "group": 4}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=11", "transcript_pages": [2980, 2981, 2982, 2983, 2984, 2985, 2986, 2987, 2988, 2989, 2990, 2991], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 6}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 14}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 4, "heading": "民政部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=6", "transcript_pages": [668, 669, 670, 671, 672, 673, 674, 675, 676, 677, 678], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 4}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 13, "heading": "教育部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=7", "transcript_pages": [1928, 1929, 1930, 1931, 1932, 1933], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 13}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=8", "transcript_pages": [84, 85, 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 15}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=18", "transcript_pages": [322, 323, 324, 325, 326, 327, 328, 329], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162','2026-10-01T10:07:24Z');
INSERT INTO "fact" VALUES('summary:14-05:p6ad3a2608b','p6ad3a2608b','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:08:59Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2882, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=1"}, {"page": 2882, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=1"}, {"page": 2884, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=3"}, {"page": 2885, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=4"}, {"page": 2887, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=6"}, {"page": 2883, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665496F721328B39FEABEA7CFEB403B94286A666540AC58FA4E9FA852238F00A7C162#page=2"}], "councilor_points": ["汪志冰議員指出民眾對道路頻頻開挖滿意度不佳，且近5年道路挖掘違規累計1,905件，主要違規單位多為管線事業單位與市府新建工程處。汪志冰議員表示未確實執行交通維持或管制恐影響用路人安全，要求市府檢討違規原因、加重對違規慣犯的罰鍰與抽查，並精準規劃教育訓練與檢討規費。"], "response": "工務局局長說明道路挖掘違規多與通報及行政管理有關，市府已設定每年違規率不超過2%的內控目標，並將於1個月內研議精進方案。新建工程處處長表示施工人員因輪替而有流動，將定期辦理教育訓練並檢討執行流程。", "response_removed": false, "topic": "道路開挖與回填違規管理"}, {"citations": [{"page": 613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549C3CBEDD30FD47B58DA4C7BBF64AC7B1EF455997608CA6360A852238F00A7C162#page=20"}, {"page": 916, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=13"}, {"page": 921, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=18"}, {"page": 919, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=16"}, {"page": 920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162#page=17"}], "councilor_points": ["汪志冰議員指出有民眾因地政事務所早期測量錯誤致房屋門號與土地登記錯置，要求市府以專案方式協助處理該特別陳情案並提高損害賠償效率。汪志冰議員建議地政局加強都市更新預檢機制宣導，並儘快將危老重建案納入預檢機制，同時主動協助老舊建築辦理陽臺補登作業。"], "response": "地政局局長表示該錯置案會進行專案處理，並說明都市更新土地建築線與地籍線預檢作業已調整至公開展覽前實施，預計於5月將危老重建納入預檢，並承諾會分階段協助住戶辦理陽臺補登與政策宣導。", "response_removed": false, "topic": "土地登記錯置與都市更新預檢機制"}, {"citations": [{"page": 704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=2"}, {"page": 706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=4"}, {"page": 707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=5"}, {"page": 708, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162#page=6"}], "councilor_points": ["汪志冰議員指出臺北市推行無障礙設施改善已有26年，但累計仍有約6,000件待改善場所，其中住宅類與市府轄管學校、捷運站等場所不合格比例偏高。汪志冰議員要求市府加快公務單位無障礙設施改善進度、彙整集合住宅改善困難，並建議提高原有住宅無障礙設施改善的補助金額與上限以增進改善誘因。"], "response": "建築管理工程處處長說明會將住宅無障礙設施補助金額上限提高至49萬元，並從寬審查社區提出的改善計畫。市長表示會優先輔導特殊教育學校改善，並請建築管理工程處研議提高補助比例及鼓勵自主檢查提前申報，以縮短改善期程。", "response_removed": false, "topic": "既有公共建築物無障礙設施改善"}, {"citations": [{"page": 2112, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=9"}, {"page": 2111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=8"}], "councilor_points": ["汪志冰議員指出臺北自來水事業處推動電子帳單20年，申辦戶數僅占27%，且近14年紙本帳單與催繳單郵資花費達6億元，行動支付占比亦偏低。汪志冰議員表示四大瓦斯公司電子帳單占比平均僅5.7%，要求市府克服資深用戶資訊落差、提供多元優惠方案，以達成淨零排放無紙化目標。"], "response": "臺北自來水事業處處長說明因房屋地址與用戶資料建立之行業特性及防範詐騙考量致推動困難，但近年已提升成長率，承諾於3個月內提出精進方案。產業發展局局長表示會督促四大瓦斯公司研議電子優惠方案，並將電子帳單成長率納入考核指標，於3個月內提供精進方案。", "response_removed": false, "topic": "公共事業無紙化電子帳單推動"}, {"citations": [{"page": 205, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=14"}, {"page": 207, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=16"}, {"page": 207, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=16"}], "councilor_points": ["汪志冰議員指出交通局推動YouBike違規記點新制，但警察局開罰的YouBike違規與酒駕案件未能同步輸入記點系統，導致記點與停權機制出現漏洞。汪志冰議員要求交通局與警察局建立跨機關通報機制並共享違規數據，同時於違規熱點設置警語及加強交通安全宣導。"], "response": "交通局局長說明因警察局PDA執法設備規範未能登錄YouBike車號致無法對接，同意與警察局向中央建議調整系統並設置警語。警察局交通警察大隊大隊長表示會函請警政署請示建置資料共享平台。", "response_removed": false, "topic": "YouBike違規記點與警察裁罰資訊對接"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02", "2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢第5組", "transcript_pag