 920, 921, 922], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494EF1707269AF5CB355C23F5F16917FDE07B28EF06312B3D5A852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 14}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 12, "heading": "教育部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F1CAC801204DB0107A9A58DD7ED62932DB23EE769240C8DCA852238F00A7C162#page=1", "transcript_pages": [1906, 1907, 1908, 1909, 1910], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1F1CAC801204DB0107A9A58DD7ED62932DB23EE769240C8DCA852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 12}]}, {"dates": ["2025-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 5, "heading": "財政建設部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162#page=5", "transcript_pages": [2108, 2109, 2110, 2111, 2112, 2113, 2114], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1CC0BABB26BC26D44C7AB13A8A191A2B910C7E5245F0459D5A852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 5}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 3, "heading": "交通部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162#page=13", "transcript_pages": [204, 205, 206, 207, 208, 209], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC14CC4A8218002DC749B6F7BEBDB3A1639F5A5FE0F70E12898A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 3}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC105ABAF1F830EB5590C5E3549C6CD502D506B96AC9C312F72A852238F00A7C162','2026-10-01T10:08:59Z');
INSERT INTO "fact" VALUES('summary:14-05:p6da9705b68','p6da9705b68','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:10:35Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 992, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=22"}, {"page": 994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=24"}, {"page": 994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=24"}, {"page": 995, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=25"}, {"page": 787, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=10"}, {"page": 783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=6"}, {"page": 789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=12"}, {"page": 784, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=7"}], "councilor_points": ["洪健益議員質詢第二殯儀館舊大樓地下一樓法定停車位遭違規堆放花架與變更為倉儲，以及二樓空間遭堆放物品等情形，質疑空間變更的合法性與預算來源。洪健益議員要求市府將地下一樓回歸停車使用，不得指定法定停車位給特定業者，並查明變更程序的同意核准層級與責任。"], "response": "建築管理工程處處長說明先前已對違規行為進行處罰，後續會至現場勘查並依規辦理。臺北市市長、副市長與民政局局長表示，會向殯葬管理處了解空間規劃與管理解決方案，若有違法違規將依法裁處並要求業者改善。", "response_removed": false, "topic": "第二殯儀館設施規劃與空間使用管理"}, {"citations": [{"page": 68, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=8"}, {"page": 70, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=10"}, {"page": 69, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=9"}, {"page": 72, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=12"}, {"page": 73, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=13"}, {"page": 74, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=14"}, {"page": 67, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=7"}, {"page": 74, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=14"}], "councilor_points": ["洪健益議員指出雙北世界壯年運動會行動化服務 App 載入緩慢且缺乏選手賽事資訊，質疑多項資訊系統標案金額高昂但履約品質不佳。洪健益議員指出店家串聯行銷活動之現金券使用率低，且電子地圖定位不準確、店家資訊欠缺，要求市府檢討廠商裁罰並進行改善。"], "response": "資訊局局長表示 App 係依大會要求建置，承認廠商履約情形不理想，將依合約條款進行裁罰並提供檢討資料。商業處處長說明會持續檢視與加強店家資訊、商品內容及電子地圖定位功能。", "response_removed": false, "topic": "雙北世界壯年運動會資訊系統與行銷活動成效"}, {"citations": [{"page": 488, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=10"}, {"page": 991, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=21"}, {"page": 992, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=22"}, {"page": 490, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=12"}, {"page": 490, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=12"}, {"page": 491, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=13"}], "councilor_points": ["洪健益議員建議市府研議推動市區公車加裝緊急輔助煞車系統（AEB），並持續落實公車駕駛指叉運動，以降低事故發生率。洪健益議員指出臺北市公車急救醫藥箱配備比例低且部分管理欠佳，建議研議比照其他縣市將急救醫藥箱列入評鑑項目。"], "response": "交通局局長與公共運輸處處長表示指叉運動會持續落實，並承諾在一個月內收集法規與技術可行性資料，針對急救醫藥箱及緊急煞車系統進行評估。", "response_removed": false, "topic": "市區公車安全設備與急救醫藥箱配備研議"}, {"citations": [{"page": 1771, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=1"}, {"page": 1774, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=4"}, {"page": 1775, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=5"}, {"page": 1775, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=5"}, {"page": 1776, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=6"}, {"page": 1776, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=6"}, {"page": 1773, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=3"}], "councilor_points": ["洪健益議員指出觀光傳播局建置之「來臺北有好宿」網站瀏覽次數與活躍停留時間偏低，且推薦名單未包含部分具代表性之旅宿，質疑推廣效益不佳。洪健益議員質疑年度預算給予一年，發包契約卻僅涵蓋數個月，致使未委外期間網站內容更新停滯，要求檢討預算執行與決算合規性。"], "response": "觀光傳播局局長說明該品牌成立時間尚短，承諾會重新盤點優化網站內容，並全面檢討發包契約期程及補交相關資料。", "response_removed": false, "topic": "「來臺北有好宿」網站推廣效益與發包履約"}, {"citations": [{"page": 980, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=10"}, {"page": 981, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=11"}, {"page": 982, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=12"}, {"page": 982, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=12"}, {"page": 983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=13"}, {"page": 981, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=11"}], "councilor_points": ["洪健益議員質疑北投士林科技園區暫定古蹟「汾陽居」遭誤拆事件中，過往文資審議會議官員未利益迴避、未依文資法進行評估公告及裁罰法條適用等疑義。洪健益議員要求政風單位確認該案是否已依法移送檢調廉政機關，並補齊完整過程資料與報告。"], "response": "文化局局長說明當時法令允許官員出席審議且後續法令已完備，並表示文化局先前已主動舉報但檢察官不起訴，故依法行政進行裁罰。臺北市市長與政風處處長表示會確認移送情形，若有不足會補做，並提供完整資料給議員。", "response_removed": false, "topic": "北投士林科技園區汾陽居文資審議與處分"}, {"citations": [{"page": 3055, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=3"}, {"page": 3056, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=4"}, {"page": 3057, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=5"}, {"page": 3058, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=6"}, {"page": 3060, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=8"}, {"page": 3058, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=6"}], "councilor_points": ["洪健益議員建議都市發展局針對財務異常或不當轉賣之都市更新實施者建立專責管控機制與標準作業流程，以維護地主權益。洪健益議員指出都市更新執行代拆（強制拆除）程序耗時過久，建議市府檢視並縮短相關協調與審議流程。"], "response": "都市發展局局長與都市更新處處長說明，市府已建置電腦化列管機制定期追蹤進度，若有財務異狀陳情會要求實施者說明。都市發展局局長表示代拆程序因依法通知及協調程序需一定時程，承諾會重新檢視流程以尋求縮短時間之可行性。", "response_removed": false, "topic": "都市更新實施者管控與代拆程序"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-06"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162#page=7", "transcript_pages": [977, 978, 979, 980, 981, 982, 983, 984, 985, 986, 988, 989, 990, 991, 992, 993, 994, 995, 996], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1B89898AE05247713941941C3B6562A8B8D47D403A0CEF4DFA852238F00A7C162", "videos": [{"date": "2025-06-06", "group": 10}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162#page=1", "transcript_pages": [3053, 3054, 3055, 3056, 3057, 3058, 3059, 3060, 3061], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB963735665495C29E865DBD19E39FCD426E585516D95A90D93C5E533F55DA852238F00A7C162", "videos": [{"date": "2025-04-24", "group": 10}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162#page=6", "transcript_pages": [454, 455, 456, 457, 458, 459], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493197C73A901C7C78DD0E703A6BB354DAC6C1F12B65213E11A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 10}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162#page=5", "transcript_pages": [782, 783, 784, 785, 786, 787, 788, 789, 790], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549BCDFFC8CBC2D52B9E7E20318967E66E32A026EA8D25ED453A852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 8}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 6, "heading": "教育部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162#page=1", "transcript_pages": [1771, 1772, 1773, 1774, 1775, 1776, 1777], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1115F2C671780F1D30E856B4814F9527E5FF6F215A11FC5A0A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 6}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162#page=5", "transcript_pages": [65, 66, 67, 68, 69, 70, 71, 72, 73, 74, 75], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1684E5A2BA77D342748F2313A77D0D3F8D7AB57D4AE5FE22FA852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 14}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1C81CF4D108129C92A5F4F65746A6E7AEFAEFB5C215B07C6DA852238F00A7C162#page=7", "transcript_pages": [485, 486, 487, 488, 489, 490, 491, 492, 493]