INSERT INTO "fact" VALUES('summary:14-05:p22b242559b','p22b242559b','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:12:04Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 856, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=14"}, {"page": 858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=16"}, {"page": 859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=17"}, {"page": 3040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=20"}, {"page": 3040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=20"}, {"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=18"}, {"page": 3041, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=21"}, {"page": 857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=15"}, {"page": 858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=16"}], "councilor_points": ["洪婉臻議員指出台北市社會住宅發生遭拍攝不雅影片、瓦斯外洩及毒品入侵等問題，並質疑青創戶審查過於形式化與報修維修天數過長。洪婉臻議員要求檢討青創社宅申請審查機制、建立監督與檢舉專線、提升查核專業能力，並立即改善瓦斯外洩等安全疑慮。"], "response": "台北市長說明若確認違反入住規範或刑事法律將依法處理，並承諾一週內釐清情況與對青創戶申請嚴格把關。都市發展局局長說明若違反租約有妨害風化疑慮會終止租約，並承諾一個月內針對社宅報修與瓦斯安全提出精進報告及優先處理相關檢測。", "response_removed": false, "topic": "社會住宅管理與居住安全改善"}, {"citations": [{"page": 866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=24"}, {"page": 455, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=4"}, {"page": 867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=25"}, {"page": 457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=6"}, {"page": 867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=25"}, {"page": 868, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=26"}, {"page": 454, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=3"}, {"page": 455, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=4"}], "councilor_points": ["洪婉臻議員指出台北市民營與市有停車場收費過高，部分民營停車場每小時高達300元，且有入場找不到車位仍被收費之不合理現象。洪婉臻議員要求落實入場15分至30分鐘內免收費政策、市有停車場符合每小時60元費率上限，並檢討社宅與市有非公用停車場租金機制。"], "response": "台北市長表示請停管處進行研議與評估，認同未停到車位不應收費。交通局局長與停車管理工程處處長說明將對民營業者進行道德勸說、協調市有場地收費規範，並承諾於1個月至2個月內提出實施計畫與精進做法。", "response_removed": false, "topic": "停車場收費管理與入場免收費機制改善"}, {"citations": [{"page": 754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=6"}, {"page": 755, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=7"}, {"page": 756, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=8"}, {"page": 752, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=4"}, {"page": 755, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=7"}, {"page": 757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=9"}], "councilor_points": ["洪婉臻議員指出出養兒童於托育期間發生嚴重受虐事件，且保母自行填寫之發展檢核表與訪視紀錄呈現矛盾，質疑訪視機制流於形式與監管失靈。洪婉臻議員要求依法進行行政罰鍰、追究失職人員責任，並建立更嚴格之無依幼童照顧標準與共同訪視機制。"], "response": "社會局局長說明已實施7加1政策，並已對涉案保母進行廢證與公告等行政裁處。秘書長表示訪視不應流於形式，承諾於1個月內由社會局就檢討與建議事項提出落實報告。", "response_removed": false, "topic": "托育與出養兒童保護監管體系檢討"}, {"citations": [{"page": 1846, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=15"}, {"page": 1847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=16"}, {"page": 1847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=16"}, {"page": 1847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=16"}, {"page": 1849, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=18"}, {"page": 1850, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=19"}], "councilor_points": ["洪婉臻議員指出幼兒園發生性侵害案件，加害人遭判刑28年8個月，質疑教育局早獲通報卻未即時啟動行政調查與停職處分，且承辦人員缺乏專業訓練。洪婉臻議員要求針對認定之45起個案採一罪一罰進行行政裁處、學前科充實專業人力、設置單一窗口並協助家屬申請國賠。"], "response": "教育局局長說明已對加害人處以終身不得聘任，並將於取得法院判決書後依據結果研議後續處置，承諾於3週內提出精進計畫。", "response_removed": false, "topic": "幼兒園性侵害事件處置與學前教育監督機制"}, {"citations": [{"page": 2076, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=23"}, {"page": 2077, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=24"}, {"page": 2078, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=25"}, {"page": 2077, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=24"}], "councilor_points": ["洪婉臻議員指出環南市場啟用3個月內發生10次停電，且2樓飲食區生意不佳與近200份攤商連署希望停用水表免繳基本費遭拒。洪婉臻議員要求檢討設計施工疏失、提出賠償與2樓活化方案、處理解約停水訴求，並增加第一魚果市場改建說明會開會頻率。"], "response": "產業局局長與市場處處長說明已進行設備盤點，並已與水處討論停止用水事宜，承諾於2週內研議攤商損失補償與精進計畫，同時要求相關單位加強與第一魚果市場攤商溝通。", "response_removed": false, "topic": "公有市場改建維護與營運管理"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=13", "transcript_pages": [855, 856, 857, 858, 859, 860, 861, 862, 863, 864, 865, 866, 867, 868, 869, 870, 871], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "videos": [{"date": "2025-06-05", "group": 8}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=17", "transcript_pages": [3037, 3038, 3039, 3040, 3041, 3042, 3043, 3044, 3045], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 8}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=15", "transcript_pages": [405, 406, 407, 408, 409, 410, 411], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 7}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=1", "transcript_pages": [749, 750, 751, 752, 753, 754, 755, 756, 757], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 7}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=10", "transcript_pages": [1841, 1842, 1843, 1844, 1845, 1846, 1847, 1849, 1850], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 10}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=22", "transcript_pages": [2075, 2076, 2077, 2078, 2079, 2080], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162", "videos": [{"date": "2025-05-13", "group": 3}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=1", "transcript_pages": [452, 453, 454, 455, 456, 457, 458], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162", "videos": [{"date": "2025-05-26", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162','2026-10-01T10:12:04Z');
INSERT INTO "fact" VALUES('summary:14-05:p28d7d936d9','p28d7d936d9','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:13:54Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1112, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=32"}, {"page": 338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=23"}, {"page": 1978, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=10"}, {"page": 333, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=18"}, {"page": 337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=22"}, {"page": 1111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=31"}, {"page": 1979, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=11"}], "councilor_points": ["游淑慧議員指出偷拍與數位性暴力犯罪氾濫，要求臺北市政府研議針對特殊針孔攝影器材實名制購買之可行性，並建請編列預算更新學校反偷拍設備與將性影像犯罪納入警察局績效評分。游淑慧議員詢問校園與補習班之兒童性影像侵害防治作為，建議教育局將反針孔偷拍檢測納入補習班聯合稽查，並明確規範教師導護權益與政策。"], "response": "警察局局長表示已要求各機關與警察局定期抽檢反偷拍，並說明網路巡邏機制與戰時任務；針對績效評分會進行引導，並會通報涉案之軍公教人員上級長官。教育局局長說明已有155所學校按照警察局建議功能更新反針孔器材，並承諾將反針孔偷拍檢測納入補習班聯合稽查常規，同時統一規範教師導護相關政策。", "response_removed": false, "topic": "數位性暴力防範與反針孔偷拍管理"}, {"citations": [{"page": 3124, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=6"}, {"page": 3122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=4"}, {"page": 3125, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=7"}, {"page": 3126, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=8"}], "councilor_points": ["游淑慧議員指出京華城改建案已申請變更設計取消20%之容積獎勵，建議臺北市政府應順勢取消原先簽訂之協議書。游淑慧議員表示業者既然已取消容積獎勵，市府不應再要求業者承擔認養公園50年、道路鋪面整修或提供800平方公尺空間等公益回饋義務，避免衍生圖利爭議。"], "response": "都市發展局局長說明業者係因應變更設計申請取消20%容積獎勵，協議書取消與否及公益設施收受仍需市府內部討論與雙方合意。公園路燈工程管理處處長、產業發展局工商服務科科長及新建工程處處長均表示，相關公園維護、新創扶持及道路維護均可由市府相關局處自行辦理，不影響機關運作。", "response_removed": false, "topic": "京華城改建案取消容積獎勵與公益回饋處理"}, {"citations": [{"page": 940, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=18"}, {"page": 941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=19"}, {"page": 944, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=22"}, {"page": 945, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=23"}, {"page": 945, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=23"}, {"page": 941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=19"}], "councilor_points": ["游淑慧議員建議臺北市政府應跨局處合作，比照原住民權益，優先保留3%熱門展演場地給身心障礙者街頭藝人。游淑慧議員指出身心障礙者與中低收入戶在就業與創業資源上相對不足，要求社會局主動整合資源並提供如同原住民族事務委員會之扶助措施。游淑慧議員關切臺北市失智長者走失風險，建議加強推廣防走失手鍊與GPS定位器等科技輔具。"], "response": "社會局局長表示會主動與文化局溝通協調身心障礙街頭藝人之表演需求，並檢討整合各局處資源以提供就業與創業協助。社會局局長說明GPS定位器補助金額相當高，惟因需持續連線產生通訊費用，家屬多選擇手機設定替代，致配戴率較低。", "response_removed": false, "topic": "身心障礙者權益保障與弱勢族群就業創業扶助"}, {"citations": [{"page": 34, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=2"}, {"page": 35, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=3"}, {"page": 36, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=4"}, {"page": 34, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=2"}, {"page": 36, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=4"}], "councilor_points": ["游淑慧議員詢問輝達（NVIDIA）選擇落腳北投士林科技園區T17、T18基地之處置進度，並關切地上權人新光人壽履約建照及開工時程。游淑慧議員指出新光人壽依法可將建物租賃予第三人經營，詢問市府對於直接移轉地上權契約或由業者租賃予輝達之政策立場與行政協助處置。"], "response": "產業發展局局長與地政局土地開發總隊總隊長說明，市府先前已提供相關土地資訊予輝達參考，並有掌握新光人壽提出變更設計之申請。產業發展局局長表示若建物完工後可依法全部或部分出租予第三方使用，市府將對輝達投資案提供全力行政協助。", "response_removed": false, "topic": "輝達總部進駐北士科地上權與租賃合作機制"}, {"citations": [{"page": 36, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=4"}, {"page": 37, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=5"}, {"page": 38, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=6"}, {"page": 40, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=8"}], "councilor_points": ["游淑慧議員指出臺北市市有土地面積於112年至113年間增加500萬平方公尺，要求財政局提供詳細原因與清單說明。游淑慧議員指出市府持有的富邦金控股票以每股10元票面價值列帳低估市值，且富邦金控獲利創新高但股利配發率僅約41.8%，要求財政局於股東會爭取市府股東權益。"], "response": "財政局局長說明市有土地增加包含撥用土地，並表示會後將提供詳細資料清單予議員。財政局局長說明財產列帳係依審計與會計規定辦理，未來會在資料加註備註，並表示富邦金控殖利率達5.3%，市府會在股東會為市民爭取最大權益。", "response_removed": false, "topic": "市有財產列帳管理與富邦金控股票資產評估"}, {"citations": [{"page": 341, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=6"}, {"page": 342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=7"}, {"page": 343, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=8"}, {"page": 341, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=6"}], "councilor_points": ["游淑慧議員關切捷運文湖線遇大雨落雷採取降速行駛之原因，要求捷運局與臺北大眾捷運股份有限公司儘速評估設備重置與大修計畫。游淑慧議員詢問中央縮減一般性補助款對基北北桃TPASS通勤月票與公車調度站等設施之影響，並關切萬大一期及信義線東延段財務修正計畫卡關中央之因應對策。"], "response": "臺北大眾捷運股份有限公司總經理說明落雷與降速係基於安全考量，重置計畫會與捷運局進行討論。交通局局長與公共運輸處處長表示若缺少中央補助對通勤月票影響極大，會儘速整理補助款類別；捷運工程局局長說明財務修正計畫若未核定恐影響廠商施工，將提出至府級討論。", "response_removed": false, "topic": "中央補助款縮減影響與捷運財務修正計畫進度"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-10"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=26", "transcript_pages": [1106, 1107, 1108, 1109, 1110, 1111, 1112, 1113, 1114, 1115, 1116, 1117, 1118], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162", "videos": [{"date": "2025-06-10", "group": 14}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 13, "heading": "工務部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=1", "transcript_pages": [3119, 3120, 3121, 3122, 3123, 3124, 3125, 3126, 3127], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 13}]}, {"dates": ["2025-04-14"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 3, "heading": "警政衛生部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=17", "transcript_pages": [332, 333, 334, 335, 336, 337, 338], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162", "videos": [{"date": "2025-04-14", "group": 3}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=17", "transcript_pages": [939, 940, 941, 942, 943, 944, 945, 946, 947], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 15}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=5", "transcript_pages": [1973, 1974, 1975, 1976, 1977, 1978, 1979, 1980], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 15}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=1", "transcript_pages": [33, 34, 35, 36, 37, 38, 39, 40, 41], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 13}]}, {"dates": ["2025-05-23"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=6", "transcript_pages": [341, 342, 343, 344, 345, 346, 347, 348], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162", "videos": [{"date": "2025-05-23", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162','2026-10-01T10:13:54Z');
INSERT INTO "fact" VALUES('summary:14-05:p32da79905a','p32da79905a','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:15:26Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 469, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=18"}, {"page": 470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=19"}, {"page": 471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=20"}, {"page": 468, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1B65333C4C1826D1F3F3526C62AC4E50155F42B7BF78D2AD0A852238F00A7C162#page=17"}], "councilor_points": ["王孝維議員指出捷運淡水站發生雨水灌入車廂及站體漏水狀況，1個月內已發生2次，要求市府說明解決方案並防止民眾滑倒。王孝維議員關切捷運民生汐止線臺北市段（規劃9站）之設計發包進度與機廠設置，並針對捷運環東線路網規劃提出改善建議。"], "response": "臺北大眾捷運股份有限公司總經理說明，車廂進水係因極端氣候下大風雨自屋頂與月台灌入，已規劃屋頂水流阻擋設施，並於改善前採列車調度因應。捷運工程局局長表示，民生汐止線臺北市段已整合交通部審查意見，將規劃共用機廠，並持續針對東環段招標事宜舉辦說明會以吸引廠商投標。", "response_removed": false, "topic": "捷運設施防漏水改善與路網工程進度"}, {"citations": [{"page": 889, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=47"}, {"page": 889, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=47"}, {"page": 2067, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=14"}, {"page": 890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=48"}, {"page": 2068, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=15"}, {"page": 2069, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=16"}, {"page": 2069, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC19F8B0BA550084CC004F4208D4F94176282B0BFF151A8E214A852238F00A7C162#page=16"}], "councilor_points": ["王孝維議員指出台北花市占地一萬一千多坪，市府每年僅收取大約2,400萬元租金，遠低於市有土地之潛在收益。王孝維議員表示花市年交易額達25億元，質疑承銷商等環節未依規定開立發票與繳稅，要求市府於114年12月31日委託合約到期後採公開標售並加強監管。"], "response": "市場處處長及市場處批發市場科科長說明，花卉公司係依規定收取管理費並依法繳納營業稅，承銷商稅務事宜已函請國稅局處理，若有逃漏稅事證可逕行舉發。稅捐稽徵處處長說明，國內銷售貨物依法應繳納營業稅，該稅項屬於國稅範疇。", "response_removed": false, "topic": "台北花市營運效益與稅務監管改善"}, {"citations": [{"page": 886, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=44"}, {"page": 886, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=44"}, {"page": 888, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=46"}, {"page": 887, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=45"}], "councilor_points": ["王孝維議員指出南港區玉成段二小段360地號都更案中，有業者未申請拆除執照即連夜強拆民宅，損害住戶權益。王孝維議員要求市府與警察局依法嚴查約談違法業者，並清查其他都更案是否亦有類似強拆情事。"], "response": "市長表示若屬違法強拆，警察局受理報案後將約談調查，查證屬實會移送法辦並依規定裁處。建築管理工程處處長與都市更新處處長說明，擅自拆除將依建築法裁罰，且因建物現況與送審內容不符，都市更新處會重新審視事業計畫報告書。", "response_removed": false, "topic": "南港都更案未申請拆照強拆民宅之查處"}, {"citations": [{"page": 393, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=3"}, {"page": 395, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=5"}, {"page": 396, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=6"}], "councilor_points": ["王孝維議員建議警察局應將警力集中於打擊詐欺、毒品與黑道暴力等重大犯罪，避免因過度處理交通檢舉與開立紅單而分散維安力量。"], "response": "警察局局長說明目前治安案件以詐欺為主，警方已成立掃黑專責隊進行系統性掃黑。警察局局長表示去年開立交通紅單約238萬張，今年1至3月開立約70萬張。", "response_removed": false, "topic": "警政打擊犯罪維安與交通檢舉開單權衡"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162#page=43", "transcript_pages": [885, 886, 887, 888, 889, 890, 891, 892], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1C467C2ED301423C0A5F4F65746A6E7AE07C1CF8C51752319A852238F00A7C162", "videos": [{"date": "2025-06-05", "group": 8}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162#page=8", "transcript_pages": [3028, 3029, 3030, 3031, 3032, 3033], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB9637356654931A63EDE40187582C062B480799C460208F26067A8218DD0A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 8}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162#page=1", "transcript_pages": [391, 392, 393, 394, 395, 396], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549D485625907D1F7B829AA352E672794364AE0722FCA5090C7A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 7}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162#page=18", "transcript_pages": [766, 767, 768, 769, 770], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665492576924ADC4BA3D8D96F00F4A8D98CD23E172ACCFC798C5DA852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 7}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162#page=1", "transcript_pages": [1832, 1833, 1834, 1835], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1C0A9121C7B9BCD34ED6AE014B94985462734610197981CE0A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 10}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/