INSERT INTO "fact" VALUES('summary:14-05:pea1a4317b4','pea1a4317b4','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:17:34Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1098, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=18"}, {"page": 1105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=25"}, {"page": 1106, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=26"}, {"page": 1099, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=19"}, {"page": 1104, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=24"}, {"page": 1102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=22"}, {"page": 1103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=23"}, {"page": 1104, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=24"}], "councilor_points": ["王欣儀議員指出公館圓環連續7年肇事率第一，要求市府針對決定拆除圓環並封閉車行地下道提出完整專業評估與數據說帖。王欣儀議員建議市府將說明資料公告於網站，並召開地方說明會納入周邊學校家長，以清楚反映民意。"], "response": "交通局局長說明填平車行地下道改為正交路型係以安全為優先考量，且評估延滯秒數與施工期程後認為填平為最優方案。新建工程處處長表示圓環下方為通風井且鄰近捷運新店線隧道，打基樁加蓋需耗時21至25個月並占用2個車道。捷運工程局局長說明基礎工程學會評估確認填平方案不會受損捷運隧道。市長表示會彙整數據由顧問公司向地方說明，並將完整說帖公告於網站與再加開說明會。", "response_removed": false, "topic": "公館圓環拆除與填平車行地下道工程評估"}, {"citations": [{"page": 929, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=7"}, {"page": 929, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=7"}, {"page": 931, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=9"}, {"page": 930, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=8"}, {"page": 932, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=10"}], "councilor_points": ["王欣儀議員指出市府防災資訊分散於各局處且網站連線不穩定，建議參考東京都防災網站設立跨局處整合專區。王欣儀議員要求市府檢討兵役局的全民國防應變手冊僅提供電子檔問題，建議研議印製紙本手冊並檢討避難貼紙標示。"], "response": "秘書長說明消防局正以東京都為學習對象進行網頁改版，預計年底前完成整合網頁更新，並會請兵役局研議紙本手冊之印製發行。警察局民防管制中心主任表示「北市警政App」已優化防空避難介面，未來希望與消防局相關系統進一步整合。兵役局局長表示已進行相關宣導檢討，配合宣導市民避難地點。", "response_removed": false, "topic": "跨局處防災資訊整合與紙本宣導手冊發行"}, {"citations": [{"page": 330, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=15"}, {"page": 331, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=16"}], "councilor_points": ["王欣儀議員詢問市府對於便利商店若納入戰時補給體系的維安與秩序維護能力，指出警力負擔之隱憂。王欣儀議員指出無地下室的社區居民缺乏明確避難指引與開門機制，並指出「北市警政APP」下載與點擊率偏低且戰時恐因斷網無法使用。王欣儀議員要求市府提報至府級建立明確的防災專區，並透過家戶信箱投遞等實體管道宣導避難地點。"], "response": "警察局局長說明便利商店屬民間營業場所，維持秩序、交通疏導與救治傷患為警察責任，會於平時進行分層分眾宣導。警察局局長說明市內共有6,052個防空避難所可容納1,300萬人，並承諾於1週內答復相關檢討作為。", "response_removed": false, "topic": "戰時防空避難與物資補給應變規劃"}, {"citations": [{"page": 356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=21"}, {"page": 356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=21"}, {"page": 358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=23"}, {"page": 357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=22"}, {"page": 361, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=26"}], "councilor_points": ["王欣儀議員指出例行性交通標線工程決標時間延遲至年中，影響執行效能。王欣儀議員指出將禁停紅黃線劃設業務由交工處移交停管處後產生權責分工重疊、兩單位出工不一致導致違停民怨等問題。王欣儀議員建議市府儘速優化分工流程，訂定明確單一窗口與處理時限SOP。"], "response": "交通管制工程處處長說明決標延遲係因人力青黃不接，已建置SOP簡化程序以提前備標。交通局局長說明業務移交係為減輕交工處負擔並避免人力重複，對磨合期造成的困擾表達抱歉，承諾於3個月內進行檢討。停車管理工程處處長表示會與交工處協調細節，提升分工合作效率。", "response_removed": false, "topic": "路邊禁停紅黃線業務劃分與分工流程"}, {"citations": [{"page": 1106, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=26"}, {"page": 3134, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=16"}, {"page": 3135, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=17"}, {"page": 3136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=18"}, {"page": 3136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=18"}], "councilor_points": ["王欣儀議員指出風災倒樹資料統計零散且缺乏統一標準，調閱近3年颱風倒樹統計為3,336株（約5,000公噸），但環保局統計進焚化廠高達16,004公噸，數量差距超過3倍。王欣儀議員指出修樹作業不落實為倒樹主因，要求市府針對高風險路段進行精細盤點並優先修剪。"], "response": "工務局局長說明環保局統計數量可能包含民間或軍方處理者，將再確認統計落差原因，並同意就高風險路段進行盤點修剪。水利工程處處長說明河濱區雜木林隨淤土處理未納入統計，後續會建立管理制度。公園處處長表示已推動5年計畫型修剪計畫，配合預算增加進行巡迴修剪，今年將按照計畫執行並進行高風險盤點。", "response_removed": false, "topic": "風災倒樹處置與路樹維護管理"}, {"citations": [{"page": 1094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=14"}, {"page": 1094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=14"}, {"page": 1095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=15"}, {"page": 1095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=15"}, {"page": 1096, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=16"}, {"page": 1097, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=17"}], "councilor_points": ["王欣儀議員詢問面對民進黨發動之大罷免潮，市府是否將其視為期中選舉嚴正以待，並詢問市長預計何時投入輔選及聲援行動。王欣儀議員指出罷免理由缺乏正當性，詢問市府採取何種行動激發民眾出門投下不同意罷免票。王欣儀議員詢問若有立法委員遭罷免對地方監督力道與未來選舉之影響。"], "response": "市長表示民進黨發動無差別大罷免不具正當性且違反民主原則，會與5位立法委員站在一起，等議會會期告一段落後展開協助。市長表示大罷免係對中央政府與總統的不信任投票，呼籲不認同的民眾勇敢投下不同意票。市長指出若立委遭罷免將減弱國會監督力道，且中央刪減地方補助款27%將影響弱勢與教育權益，市府已針對補助款被刪提出訴願及救濟。", "response_removed": false, "topic": "大罷免潮應對與藍營立法委員聲援"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-10"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=14", "transcript_pages": [1094, 1095, 1096, 1097, 1098, 1099, 1100, 1101, 1102, 1103, 1104, 1105, 1106], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162", "videos": [{"date": "2025-06-10", "group": 14}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 13, "heading": "工務部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=16", "transcript_pages": [3134, 3135, 3136, 3137, 3138, 3139], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 13}]}, {"dates": ["2025-04-14"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 3, "heading": "警政衛生部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=13", "transcript_pages": [328, 329, 330, 331, 332], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162", "videos": [{"date": "2025-04-14", "group": 3}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=7", "transcript_pages": [929, 930, 931, 932, 933], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 15}]}, {"dates": ["2025-05-12"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=1", "transcript_pages": [1969, 1970, 1971, 1972, 1973], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162", "videos": [{"date": "2025-05-12", "group": 15}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=22", "transcript_pages": [54, 55, 56, 57, 58, 59, 60], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 13}]}, {"dates": ["2025-05-23"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162#page=20", "transcript_pages": [355, 356, 357, 358, 359, 360, 361], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1391053260B64DA5DF39DF02156C2EEE70B83AEF2E3D69BA9A852238F00A7C162", "videos": [{"date": "2025-05-23", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162','2026-10-01T10:17:34Z');
INSERT INTO "fact" VALUES('summary:14-05:p70a5d9018c','p70a5d9018c','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:19:37Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1000, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=4"}, {"page": 1001, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=5"}, {"page": 1002, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=6"}, {"page": 1004, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=8"}, {"page": 1005, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=9"}, {"page": 447, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=14"}, {"page": 448, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=15"}, {"page": 1003, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=7"}, {"page": 446, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2511A6AE2350377E51A5FDE6CC1DE26358AB6CCEA852238F00A7C162#page=13"}], "councilor_points": ["王閔生議員指出公館圓環連續 7 年為臺北市肇事熱點第一名，每年開出高達 7,000 張罰單，要求市府解決高違規與高事故問題。王閔生議員表示市府宣布廢除公館圓環及填平車行地下道前缺乏溝通與相關資料，未公開車流模擬數據與工程評估，要求市府充分向地方說明。王閔生議員要求市府在 2 週內公開車流模擬與工程圖，且在相關設計圖及交維計畫確定並溝通前不得動工。"], "response": "臺北市市長與交通局局長說明，廢除圓環並改為正交路口是基於安全考量，若保留車行地下道因打基樁工程難度高且工期需增加 1.5 至 2 年，故評估填平地下道。交通局局長與交通管制工程處處長表示已召開說明會蒐集地方意見，會將車流模擬與專業評估公開說明，並請副市長跨局處溝通處理。", "response_removed": false, "topic": "公館圓環廢除與路型規劃"}, {"citations": [{"page": 1029, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=33"}, {"page": 1029, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=33"}, {"page": 122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=17"}], "councilor_points": ["王閔生議員指出忠孝東路四段部分捷運及地下街出入口占用人行道、無遮蔽且設施老舊，建議市府結合人行道拓寬工程進行整體市容美學改造。王閔生議員建議比照中山捷運站改造經驗，啟動忠孝東路四段自忠孝復興站至忠孝敦化站的站體與地下街出入口改造規劃。"], "response": "捷運工程局局長說明，過往地下街出入口未設雨遮係因周邊商家不同意及結構限制，但若設計出兼具美觀與友善的空間可與人行道拓寬分開處理。臺北市市長表示認同整體改造的方向，並表示會由副市長召集各局處研擬推動忠孝東路四段整體改造規劃。", "response_removed": false, "topic": "忠孝東路四段及捷運出入口改造"}, {"citations": [{"page": 997, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=1"}, {"page": 998, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=2"}, {"page": 998, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=2"}, {"page": 999, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=3"}, {"page": 999, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=3"}, {"page": 1000, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=4"}], "councilor_points": ["王閔生議員指出永康街假日行人漫步區試辦計畫事前溝通不足，且市府民調採路上隨機詢問未真實反映在地住戶意見，導致在地居民反映出入受干擾及店家生意受影響。王閔生議員表示該區域屬於住宅區而非商業區，常態性封街會破壞長期建立的住商融合模式，建議改採配合節日不定期辦理活動的方式封街。"], "response": "臺北市市長說明，試辦期間已彙集居民、店家與里長意見，民調顯示有 89%在地居民表示滿意，但也會將反對意見納入檢討。臺北市市長表示，會邀集交通局、產業發展局、商業處及文化局研商，以維持在地住商融合為目標來考量後續規劃。", "response_removed": false, "topic": "永康街假日行人漫步區試辦"}, {"citations": [{"page": 505, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=11"}, {"page": 507, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=13"}, {"page": 508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=14"}, {"page": 507, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=13"}, {"page": 508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=14"}], "councilor_points": ["王閔生議員指出市長曾承諾加碼補助公費疫苗接種處置費每劑 100 元卻尚未實現，要求市府正視基層醫療院所負擔。王閔生議員建議市府優先針對 0 歲至 5 歲嬰幼兒 19 劑公費疫苗補助處置費每劑 100 元，一年預算約 2,500 萬元，或依疫苗類別採不同級距補助。"], "response": "衛生局局長說明，臺北市學齡前兒童公費疫苗每年約施打 25 萬劑，已與醫療團體討論並行文疾病管制署研商。衛生局局長表示，因考量成人流感疫苗等整體施打量與公平性，會進行整體估算並尋求最平衡的方式爭取預算推出補助方案。", "response_removed": false, "topic": "嬰幼兒公費疫苗處置費補助"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-09"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162#page=1", "transcript_pages": [997, 998, 999, 1000, 1001, 1002, 1003, 1004, 1005, 1029, 1031, 1032, 1033, 1034, 1035], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC140E3D6E5B72B3B4B0C5E3549C6CD502DFBE60D365C410458A852238F00A7C162", "videos": [{"date": "2025-06-09", "group": 11}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 11, "heading": "工務部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665497BB289A06D3DE213DDBAB098C8228A75CBD135B6E516E358A852238F00A7C162#page=13", "transcript_pages": [3088, 3089, 3090, 3091, 3092, 3093, 3094, 3095], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665497BB289A06D3DE213DDBAB098C8228A75CBD135B6E516E358A852238F00A7C162", "videos": [{"date": "2025-04-24", "group": 11}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 12, "heading": "警政衛生部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162#page=11", "transcript_pages": [505, 506, 507, 508, 509, 510, 511, 512, 513, 514, 515], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB96373566549B3BEC18874257DD9C21607C8E540D49BF9E1A18D1867426CA852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 12}]}, {"dates": ["2025-05-02"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494B45F90DCEF9BE6109CB2E9097E3B7FD7AA12815378EF354A852238F00A7C162#page=14", "transcript_pages": [891, 892, 893, 894, 895, 896, 897, 898, 899, 900, 901, 902, 903], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665494B45F90DCEF9BE6109CB2E9097E3B7FD7AA12815378EF354A852238F00A7C162", "videos": [{"date": "2025-05-02", "group": 13}]}, {"dates": ["2025-05-06"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC16A161F81D9FFA0E4ED6AE014B94985465CCBD84475479F76A852238F00A7C162#page=16", "transcript_pages": [1747, 1748, 1749, 1750, 1751, 1752, 1753, 1754, 1755], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC16A161F81D9FFA0E4ED6AE014B94985465CCBD84475479F76A852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 5}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162#page=13", "transcript_pages": [118, 119, 120, 121, 122, 123, 124, 125, 126, 127], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1B425B2651D71F6416B29A287333E31DCB4C4486768233785A852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 16}]}, {"dates": ["2025-05-26"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC1DDA1EB7E2