INSERT INTO "fact" VALUES('summary:14-05:p8ff8ce5488','p8ff8ce5488','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:26:55Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 596, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=1"}, {"page": 598, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=3"}, {"page": 599, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=4"}, {"page": 601, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=6"}, {"page": 604, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=9"}, {"page": 291, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=11"}, {"page": 292, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=12"}, {"page": 603, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=8"}, {"page": 293, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=13"}, {"page": 598, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=3"}, {"page": 601, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=6"}, {"page": 602, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=7"}, {"page": 604, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=9"}, {"page": 291, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=11"}, {"page": 293, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=13"}], "councilor_points": ["苗博雅議員指出，市府規劃拆除公館圓環並填平地下公車專用道，但新規劃之永久路型圖存在行人穿越距離過長、車流交織動線複雜及可能形成交通瓶頸等問題。苗博雅議員表示，翡翠原水管通水後即可廢除圓環下方之自來水輸水箱涵，無須抬升路面，建議保留公車專用地下道以降低施工難度與交通衝擊。"], "response": "市長說明決議拆除圓環係因交通事故頻繁，原規劃填平地下道係考量保留加蓋會導致路面抬升且橋下淨高不足，針對路型圖未完善之處會再修正，並表示會就廢除輸水箱涵及保留地下道可行性進行專業評估；交通局局長說明將於說明會收集地方意見，並對路型與地下道保留方案進行研議與利弊權衡；臺北自來水事業處總工程師說明翡翠原水管通水後，廢除該輸水箱涵仍可滿足供水調度需求。", "response_removed": false, "topic": "公館圓環拆除及地下道保留規劃"}, {"citations": [{"page": 606, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=11"}, {"page": 607, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=12"}, {"page": 1662, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=6"}, {"page": 1663, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=7"}, {"page": 610, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=15"}, {"page": 606, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=11"}, {"page": 609, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=14"}, {"page": 610, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=15"}], "councilor_points": ["苗博雅議員指出，市府對兒少性侵與虐童案件之行政裁罰存在制度缺漏，包括教育局錯誤認定《教保服務人員條例》不含性侵害而未處罰鍰，以及對同一行為人在不同幼兒園侵犯多名幼童之行為數認定混亂。苗博雅議員要求市府於 2 個月內制定具體明確之行政裁罰標準作業規範，釐清按受害兒童人數認定行為數分別裁罰，並於法院判決前或起訴前即及時進行行政裁罰。"], "response": "市長表示認同議員訴求，說明條文文義應包含性侵且事證明確即應行政裁罰，承諾於 2 個月內提出標準規範；教育局局長說明曾請示教育部國教署認為該條文不含性侵，故改依幼兒教育及照顧法處分，信義區狼師案已採一幼兒一處罰補開罰 360 萬元，並承諾檢討行為數認定標準；法務局局長表示條文文義解釋上應包含性侵害。", "response_removed": false, "topic": "兒少性侵害及虐童案件行政裁罰機制"}, {"citations": [{"page": 873, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=17"}, {"page": 874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=18"}, {"page": 874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=18"}, {"page": 875, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=19"}, {"page": 876, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=20"}, {"page": 877, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=21"}, {"page": 876, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=20"}, {"page": 873, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=17"}], "councilor_points": ["苗博雅議員指出，「土耳其台灣中心」相關勸募專案存在前案違法集資、善款流向與平臺扣款金額兜不攏、勸募期滿後仍持續扣繳定期定額捐款，以及前案尚有 9,500 萬元結餘未釐清即獲准開立新案等嚴重疑慮。苗博雅議員要求社會局於 1 週內依照《公益勸募條例》第 21 條調閱該單位 3 個勸募案之帳冊進行財務查核，若拒絕或規避應廢止其勸募許可。"], "response": "社會局局長說明會針對該單位進行全面檢討與財務查核，要求團體提出合理說明，並與法務局研議處理定期定額扣款與海外監督事宜；社會局人民團體科科長說明部分款項係因執行期間差異或集資平臺扣款等因素，並說明相關案件正進行行政訴訟與審查。", "response_removed": false, "topic": "土耳其台灣中心公益勸募專案監督"}, {"citations": [{"page": 446, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=15"}, {"page": 447, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=16"}, {"page": 444, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=13"}, {"page": 445, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=14"}, {"page": 446, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=15"}], "councilor_points": ["苗博雅議員指出，臺北市立聯合醫院招聘約用住院醫師時宣稱月薪 11 萬元，實際計算加班費時卻僅以本薪 5 萬元為基準，未將每月經常性給予之獎勵金納入工資計算，違反《勞動基準法》及相關法院判例。苗博雅議員要求聯合醫院應與工會協商，於總質詢前提出一合法的具體方案以解決加班費計算爭議。"], "response": "臺北市立聯合醫院院長說明公立醫院給薪分為薪資與獎勵金，獎勵金係來自醫院盈餘且每月浮動發給，承諾於總質詢前提出一具體方案（如提高值班費等方式）來改善待遇；臺北市政府勞動局勞動基準科科長說明依《勞動基準法》，凡因工作獲得之報酬，不論名目只要具經常性給予及勞務對價性即屬工資。", "response_removed": false, "topic": "臺北市立聯合醫院約用住院醫師薪資結構"}, {"citations": [{"page": 3147, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=2"}, {"page": 3148, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=3"}], "councilor_points": ["苗博雅議員指出，鼎越公司向北市府掛件申請取消 20% 容積獎勵，卻向上市公司中石化投資人發布重大訊息稱「並非取消」，涉有公告不實之嫌。苗博雅議員要求都市發展局將相關公文移送金管會告發，並建議市府利用都市計畫通盤檢討機制主動檢討並取消京華城不合理的都市計畫。"], "response": "都市發展局局長說明鼎越公司送件申請書載明文字為「取消」，若金管會詢問會本於事實說明，並同意提供公文供議員告發；針對都市計畫通盤檢討，局長表示該都市計畫目前非違法狀態，若主動取消可能有適法性疑慮。", "response_removed": false, "topic": "京華城土地容積獎勵爭議與都市計畫檢討"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=1", "transcript_pages": [596, 597, 598, 599, 600, 601, 602, 603, 604, 605, 606, 607, 608, 609, 610, 611], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162", "videos": [{"date": "2025-05-29", "group": 3}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=1", "transcript_pages": [3146, 3147, 3148, 3149, 3150, 3151, 3152, 3153], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 14}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 9, "heading": "警政衛生部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162#page=12", "transcript_pages": [443, 444, 445, 446, 447, 448], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665498FA54FCFDB3BC26B62B822D674ED591A0CF2BD2265CC7A12A852238F00A7C162", "videos": [{"date": "2025-04-15", "group": 9}]}, {"dates": ["2025-05-02"], "dept": "民政", "doc_type": "部門質詢", "group": 12, "heading": "民政部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=15", "transcript_pages": [871, 872, 873, 874, 875, 876, 877], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162", "videos": [{"date": "2025-05-02", "group": 12}]}, {"dates": ["2025-05-06"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=1", "transcript_pages": [1657, 1658, 1659, 1660, 1661, 1662, 1663, 1664], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 1}]}, {"dates": ["2025-05-15"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1AC32224B63560F40F78DCC91A3FE9A73F17CD805578FC087A852238F00A7C162#page=5", "transcript_pages": [2177, 2178, 2179, 2180, 2181, 2182], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC1AC32224B63560F40F78DCC91A3FE9A73F17CD805578FC087A852238F00A7C162", "videos": [{"date": "2025-05-15", "group": 7}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 6, "heading": "交通部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=8", "transcript_pages": [288, 289, 290, 291, 292, 293, 294], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 6}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162','2026-10-01T10:26:55Z');
INSERT INTO "fact" VALUES('summary:14-05:p369c0f3b74','p369c0f3b74','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:28:34Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 727, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=10"}, {"page": 730, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=13"}, {"page": 732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=15"}, {"page": 729, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=12"}, {"page": 732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=15"}, {"page": 733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=16"}], "councilor_points": ["許淑華議員指出剴剴案訪視紀錄記載之兒童狀況與實際受虐解剖結果存有落差，詢問追蹤機制是否過於消極。許淑華議員要求建立社工獎勵與安全保障機制，並建議增加保母健康檢查之精神疾病項目、訂定保母拒絕訪視與收出養評估之標準作業程序（SOP）。"], "response": "社會局局長表示相關訪視資料均已提送檢調，目前已增加全日托訪視次數與社工教育訓練。秘書長與社會局局長說明將就精進作為、相關處理流程 SOP 及社工獎勵機制進行整體檢討並提出報告。", "response_removed": false, "topic": "剴剴案檢討與托育訪視制度改善"}, {"citations": [{"page": 3102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=7"}, {"page": 3102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=7"}, {"page": 3103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=8"}, {"page": 3104, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=9"}, {"page": 3105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=10"}, {"page": 3105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=10"}, {"page": 3106, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=11"}], "councilor_points": ["許淑華議員詢問世壯運橄欖球場草皮養護進度、大巨蛋花費 1.5 億元開幕式之漏水與音響因應方案，以及府前廣場花費 919 萬元臨時設置沙灘排球場之規劃。許淑華議員指出天母棒球場編列 1 億 4,500 萬元及追加 3,650 萬元預算，卻於 10 月才動工無法趕上 5 月賽事，要求體育局一個星期內提出改善計畫。"], "response": "體育局代理科長、體育局世壯運執行辦公室主任及體育局科長說明橄欖球場養草進行中，大巨蛋賽事期間將管控漏水區域座位並加裝音響，府前廣場場地經與相關協會溝通確認。體育局代理科長說明天母棒球場因教育部體育署補助計畫於去年 8 月通過，故於 10 月動工。", "response_removed": false, "topic": "世壯運場館籌備與改善工程進度"}, {"citations": [{"page": 733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=16"}, {"page": 735, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=18"}, {"page": 735, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=18"}, {"page": 736, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=19"}, {"page": 736, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=19"}, {"page": 737, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=20"}, {"page": 739, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=22"}], "councilor_points": ["許淑華議員詢問研考會主任委員對府級管制案件如環南市場完工時程、第二美術館進度及社會住宅戶數之掌握狀況。許淑華議員指出 1999 話務中心市民陳情前十大項目連續兩年類別相同，建議研考會邀集各局處討論具體解決方案。"], "response": "研考會科長說明環南市場預計 5 月正式營運，第二美術館施工狀況正常。研考會主任委員說明陳情案件以交通類為主並設有預警機制，表示會進一步與各局處討論核心問題。", "response_removed": false, "topic": "研考會府級管制案件管考與市民陳情回應"}, {"citations": [{"page": 739, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=22"}, {"page": 1821, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=18"}, {"page": 1822, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=19"}, {"page": 1822, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=19"}, {"page": 1823, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=20"}], "councilor_points": ["許淑華議員指出音樂圖書館中心標案流標 6 次後，市府提出追加預算 43 億元至 114 億元，詢問是否符合預算法規定。許淑華議員表示雙永國小校舍改建工程已流標 5 次，要求教育局精算物價與人工成本，於一個星期內提出學校工程改善報告。"], "response": "教育局局長與文化局局長說明音樂圖書館中心係依物價指數調整及訪商估價調整總價款，若議會同意追加即可續辦招標。教育局局長說明雙永國小工程將召開流標檢討會，並會同工務單位評估成本調整方案。", "response_removed": false, "topic": "台北音樂圖書館中心預算與校舍改建工程流標"}, {"citations": [{"page": 3108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=13"}, {"page": 3109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=14"}, {"page": 3109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=14"}], "councilor_points": ["許淑華議員指出路燈 PFI 計畫總經費 30.95 億元及行道樹委外預算龐大，詢問路燈隊與園藝隊人力缺口狀況。許淑華議員要求市府明確劃分委外廠商與路燈隊之權責，並確保職工權益不因業務委外而受損。"], "response": "公園處處長說明路燈隊缺額 23 人、園藝隊缺額 11 人，承諾路燈隊 4 個分隊不會整併或縮編。工務局局長與勞動局科長說明會於契約中劃清權責，並依勞動基準法規定保障職工權益。", "response_removed": false, "topic": "公園處維護計畫委外與職工權益保障"}, {"citations": [{"page": 152, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=6"}, {"page": 153, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=7"}, {"page": 154, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=8"}], "councilor_points": ["許淑華議員反映民眾騎乘 YouBike 因鏈蓋破損致鞋帶捲入摔傷，指出每年 1,154 件事故中理賠率僅 16.7％且僅限死亡、失能或住院。許淑華議員要求交通局於一個月內明訂車輛檢修頻率，並增加非住院受傷之保險理賠範疇。"], "response": "交通局局長與法務局消費者保護官表示業者處置態度不妥，產品安全性應由業者舉證。交通局局長承諾將於一個月內與相關單位研議檢修頻率與放寬保險理賠種類。", "response_removed": false, "topic": "YouBike車輛檢修與保險理賠機制改善"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 7, "heading": "市政總質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162", "videos": [{"date": "2025-06-03", "group": 7}]}, {"dates": ["2025-04-24"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162#page=7", "transcript_pages": [3102, 3103, 3104, 3105, 3106, 3107, 3108, 3109, 3110], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665495F4CEA2CB072A0D47227BF33D36A75A8C35AE6992260B1E2A852238F00A7C162", "videos": [{"date": "2025-04-24", "group": 12}]}, {"dates": ["2025-04-17"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 11, "heading": "警政衛生部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665493E8EB2D456711C169E7098EB832D849C407A05D701EA7369A852238F00A7C162#page=14", "transcript_pages": [483, 484, 485, 486, 488, 489, 490, 491, 492, 493, 494], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665493E8EB2D456711C169E7098EB832D849C407A05D701EA7369A852238F00A7C162", "videos": [{"date": "2025-04-17", "group": 11}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 6, "heading": "民政部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162#page=10", "transcript_pages": [727, 728, 729, 730, 731, 732, 733, 734, 735, 736, 737, 738, 739], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB963735665491D0C4445112905A562B822D674ED591AB85541FA28B0B55FA852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 6}]}, {"dates": ["2025-05-08"], "dept": "教育", "doc_type": "部門質詢", "group": 9, "heading": "教育部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162#page=17", "transcript_pages": [1820, 1821, 1822, 1823, 1824, 1825, 1826, 1827, 1828], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66629308CD85D631C6736907423338DC1D53A7C7868F5F9B4D9C6CEAEE7044DFA20BFB61CC0AD8E96A852238F00A7C162", "videos": [{"date": "2025-05-08", "group": 9}]}, {"dates": ["2025-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 11, "heading": "財政建設部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC11B488CC5BB2268713F809CE8C5B8F0EFDDE53530A9EEEADAA852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC11B488CC5BB2268713F809CE8C5B8F0EFDDE53530A9EEEADAA852238F00A7C162", "videos": [{"date": "2025-05-16", "group": 11}]}, {"dates": ["2025-05-20"], "dept": "交通", "doc_type": "部門質詢", "group": 1, "heading": "交通部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162#page=6", "transcript_pages": [152, 153, 154, 155, 156, 157, 158, 159, 160, 161], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC15EE530E54A7D52CC4AC565CB02BBF17361752DD6D69516F7A852238F00A7C162", "videos": [{"date": "2025-05-20", "group": 1}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE652CF8DB760312CDD6736907423338DC1732D46B642F66419F1A5D0F2F262283CE52C288B36C679A8A852238F00A7C162','2026-10-01T10:28:34Z');
INSERT INTO "fact" VALUES('summary:14-05:p4cf586308f','p4cf586308f','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:30:10Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 322, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=7"}, {"page": 325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=10"}, {"page": 325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=10"}, {"page": 324, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=9"}, {"page": 327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB96373566549A7231FEA443CF7F98D9DD67FAF8F47C88B44185F728E2581A852238F00A7C162#page=12"}], "councilor_points": ["詹為元議員指出台北市設有 1,943 個公用垃圾桶，但巡查員與移動式攝影機數量不足以覆蓋所有熱點，導致部分區域屢次出現亂丟垃圾遭開罰的情況。詹為元議員建議市府重新檢討垃圾桶開口設計以減少家戶垃圾傾倒，並引進太陽能壓縮等智慧型垃圾桶進行試點。"], "response": "環境保護局局長說明移動式攝影機採動態調配，並已向中央建請提高亂丟垃圾裁罰上限。環境保護局局長表示會研議試行調整垃圾桶開口設計，並評估與廠商合作試辦智慧型垃圾桶。", "response_removed": false, "topic": "公用垃圾桶設置與亂丟垃圾稽查改善"}, {"citations": [{"page": 924, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=2"}, {"page": 52, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC1D56E1421355E9A68DD0E703A6BB354DA8D48C284F8701A0CA852238F00A7C162#page=20"}, {"page": 925, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=3"}, {"page": 926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=4"}], "councilor_points": ["詹為元議員指出寵物友善公車開辦至今搭乘率偏低，平日平均單月僅有 2 隻狗狗搭乘。詹為元議員表示主因在於班次間隔過長（例如平日 9 時 20 分首班車後須等到下午 1 時才有次班車），不符飼主遛狗時間習慣，要求市府主動研議增加班次。"], "response": "動物保護處處長表示寵物友善公車仍有存在必要，承諾於 1 個月內與公共運輸處協調調整班次的可行性。公共運輸處業務稽查科科長表示會配合動物保護處進行路線與班次協調。", "response_removed": false, "topic": "寵物友善公車乘車率與班次規劃調整"}, {"citations": [{"page": 3140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=22"}, {"page": 3142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=24"}, {"page": 3139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=21"}, {"page": 3140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665496E403DCDFCA95280C062B480799C4602B52D2DF98199CE9CA852238F00A7C162#page=22"}], "councilor_points": ["詹為元議員關注內湖東湖段 575 專案公辦都更第 1 次招商流標狀況，指出該案具指標性，若因基地小、獲利低導致廠商無意願，可能影響民眾對公辦都更之信心。詹為元議員建議市府檢討招標條件與相關誘因，提出改善方案以保障公辦都更順利推動。"], "response": "都市更新處處長與都市發展局局長說明將彙整意見並放寬投標資格，以吸引中小型開發商參與第 2 次招商。都市更新處處長補充說明公辦都更可由公部門全力協助前期整合與審議加速。", "response_removed": false, "topic": "海砂屋575專案公辦都更招商與誘因機制"}, {"citations": [{"page": 926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=4"}, {"page": 928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=6"}, {"page": 928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=6"}, {"page": 928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB963735665490D62F2375928B4B954DE696ABE702E017D3006E010489FCDA852238F00A7C162#page=6"}], "councilor_points": ["詹為元議員指出現行早期療育補助多集中於傳統醫事治療，而舞蹈、戲劇等輔助療法申請人次極少甚至掛零。詹為元議員建議市府參考其他縣市作法，明確訂定專業標準並將「適應體育」與多元項目納入早療補助範圍，以滿足特殊兒童需求。"], "response": "社會局局長說明目前已有平臺登錄與審核機制，並表示將召開專家學者會議研商是否將「適應體育」及其他多元項目納入補助。", "response_removed": false, "topic": "早期療育多元服務項目與補助機制"}, {"citations": [{"page": 1987, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=19"}, {"page": 1987, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=19"}, {"page": 1989, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=21"}, {"page": 1988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC18A8D2F7DEE54C004B784B7C40E2B9C4CA302CAF69F42480BA852238F00A7C162#page=20"}], "councilor_points": ["詹為元議員指出文化局推動「文化小旅行」部分景點介紹文字過於軟性，缺乏深度歷史爬梳。詹為元議員質疑專案投入 857 萬元預算，卻缺乏現場實際到訪人數與導覽預約轉出效益的統計，要求市府檢討文字品質與改善數據追蹤。"], "response": "文化局局長表示部分景點深度確實不足，承諾回去檢討並加強內容調整。文化局文化資源科科長與文化局局長說明官網已有點閱率統計，並承諾後續會加強個別景點與預約轉出數據的紀錄。", "response_removed": false, "topic": "文化小旅行景點介紹深度與效益評估"}, {"citations": [{"page": 1081, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=1"}, {"page": 1083, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=3"}, {"page": 1084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=4"}, {"page": 1084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=4"}, {"page": 1083, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=3"}], "councilor_points": ["詹為元議員指出台北市「寶貝我愛你」政策補助 2 至 4 歲念私幼每學期 2 萬 6,000 元，但 5 歲大班家戶所得 70 萬元以上者每學期僅補助 2,543 元，落差高達 9 成，造成家長負擔。詹為元議員建議市府在公幼數量尚未滿足需求前，研議將「寶貝我愛你」補助擴及 5 歲大班或縮小補助差距。"], "response": "台北市長表示會做整體評估並彙整各界意見。教育局局長說明 5 歲幼兒優先入學公幼，且若擴大補助可能遭中央扣減一般性補助款。", "response_removed": false, "topic": "私立幼兒園補助額度與年齡落差改善"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-10"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162#page=1", "transcript_pages": [1081, 1082, 1083, 1084, 1085, 1086, 1087, 1088, 1089, 1090, 1091, 1092, 1093, 1094], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE622A15BAFFAD0DF906736907423338DC18D573E38E2DB20178673E6B0AD5A3B6D2691909713547553A852238F00A7C162", "videos": [{"date": "2025-06-10", "group": 14}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 13, "heading": "工務部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665