INSERT INTO "fact" VALUES('summary:14-05:p06dbec1b42','p06dbec1b42','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T02:11:55Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 665, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=15"}, {"page": 666, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=16"}, {"page": 667, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=17"}, {"page": 554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=19"}], "councilor_points": ["郭昭巖議員指出艋舺公園景觀改善工程將於6月動工並預計明年7月完工，要求市府就親水廣場防滑設施、人流動線、電力配置與施工圍籬妥善規劃，避免影響周邊商家與交通。郭昭巖議員建議市府應串連龍山地下商場與龍山文創B2動線，並整合跨局處資源於改建後舉辦常態性大型活動以活絡在地觀光與經濟。郭昭巖議員要求市府召開跨局處會議，妥善因應工程期間街友安置、物資定點發放及萬華警力加強等問題。"], "response": "市長說明水池周邊採用粗糙花崗岩防滑設計，相關供電與照明設施均會事先規劃，並會一併進行整體規劃將人潮導入地下街。市長與公園路燈工程管理處處長表示會儘量降低施工對動線的影響，警察局局長亦表示會協助萬華分局並配合辦理跨局處協調。", "response_removed": false, "topic": "艋舺公園景觀改善與周邊整體發展"}, {"citations": [{"page": 669, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=19"}, {"page": 2970, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=1"}, {"page": 669, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=19"}, {"page": 2970, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=1"}, {"page": 2970, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=1"}, {"page": 670, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=20"}], "councilor_points": ["郭昭巖議員指出萬大捷運線沿線推動大眾運輸導向型發展（TOD）容積獎勵十幾年無一成案，主因在於基準容積未提高，無法吸引住戶與實施者投入改建。郭昭巖議員表示不宜以臨路寬未達30公尺為由否決放寬基準容積，要求市府藉由今年都市計畫通盤檢討，運用與時俱進的容積總量管制思維調整沿線土地使用分區。郭昭巖議員建議市府結合捷運聯合開發與防災型都更等配套機制，以加速老舊社區更新並保障居民居住安全。"], "response": "市長說明已將相關議題納入今年全市通盤檢討討論，並啟動TOD 3.0計畫專案進行捷運場站及萬大線沿線周邊容積檢討。都市發展局局長表示會將通檢與TOD執行計畫同步進行檢討，並將議員意見納入討論。", "response_removed": false, "topic": "萬大捷運線沿線土地使用分區與容積率檢討"}, {"citations": [{"page": 1946, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=25"}, {"page": 78, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=2"}, {"page": 78, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=2"}, {"page": 79, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=3"}, {"page": 77, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=1"}], "councilor_points": ["郭昭巖議員指出萬華商圈廊帶計畫預算實際分配給萬華區金額過少（113年僅114萬6,800元），且共通性行政費過高，要求重新檢討預算編列與執行成效。郭昭巖議員建議商業處應結合都市發展局與工務局進行整體環境景觀改造，並納入在地大飯店與專家學者共同評估推廣在地觀光。郭昭巖議員指出市場與市集精進計畫缺乏專業團隊協助，要求市府重啟輔導團隊、開放第二階段申請，並加強輔導西昌街與廣州街夜市之空攤引進特色攤位。"], "response": "商業處處長說明共通性行政經費包含持續了解商圈需求與追蹤成效，並表示會整理資料及修正計畫內容。市場處處長表示會提供精進計畫統計資料，並會向自治會進行了解以輔導市集發展。", "response_removed": false, "topic": "商圈廊帶與市集精進計畫執行檢討"}, {"citations": [{"page": 551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=16"}, {"page": 551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=16"}, {"page": 552, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=17"}], "councilor_points": ["郭昭巖議員指出市府擬於華中里堤外停放45台垃圾車之規劃引發在地2,000多份連署反彈，要求市府評估對交通衝擊最小之方案並加強與在地溝通。郭昭巖議員表示萬華與中正區河岸短中長期規劃內容不足，要求市府於今年上半年召開會議並於年底前提出中期與長期規劃。郭昭巖議員指出光復橋堤外等處存在雜草堆積、高低落差過大導致民眾摔倒等問題，要求水利工程處加強環境維護與安全管理。"], "response": "環保局局長表示會仔細評估影響地方之因素，並整合跨局處資訊儘速完成評估。工務局水利工程處處長表示同意於今年上半年召開會議，並於年底提出基本規劃。", "response_removed": false, "topic": "華中里堤外垃圾車停放案與河岸景觀規劃"}, {"citations": [{"page": 555, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=20"}, {"page": 557, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=22"}, {"page": 557, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=22"}], "councilor_points": ["郭昭巖議員指出萬華區報案率與刑案數均居臺北市第三（113年報案數15萬8,658件、刑案5,481件），且警民比達1比370，導致員警請調人數達26人居全市第一，要求警察局檢討人力配置並加強心理輔導。郭昭巖議員指出113年萬華區詐騙案件達933件且財損金額達3億7,830萬元，要求市府檢討防詐宣導深度與廣度，並結合校園劇團宣導與科技執法以提升防詐效果。"], "response": "警察局局長表示會進行人力評估瞭解狀況，並說明防詐將從源頭管理及透過網路平臺投放宣導資訊，後續會將精進作為資料提交議員。", "response_removed": false, "topic": "萬華分局警力配置與治安防詐檢討"}, {"citations": [{"page": 1941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=20"}, {"page": 1941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=20"}, {"page": 1942, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=21"}], "councilor_points": ["郭昭巖議員指出捷運盃街舞大賽不應僅由捷運公司以550萬元預算單打獨鬥，要求市府進行整體規劃並整合體育局、青年局、觀光傳播局、商業處與文化局資源升級為國際賽事。郭昭巖議員對比新北市青年局編列440萬元並資助獲勝選手出國參賽，建議臺北市體育局與青年局投入預算補助，並結合企業贊助與聯名悠遊卡行銷以提升觀光效益。"], "response": null, "response_removed": true, "topic": "捷運盃街舞大賽跨局處資源整合與推動"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162#page=11", "transcript_pages": [661, 662, 663, 664, 665, 666, 667, 668, 669, 670, 671, 672], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162", "videos": [{"date": "2025-06-02", "group": 4}]}, {"dates": ["2025-04-22"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162#page=1", "transcript_pages": [2970, 2972, 2973, 2974, 2975, 2976, 2977, 2978, 2979, 2980], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F2442161514EE10B53D5313F25E58EEC69CC4AC62831F8E7A852238F00A7C162", "videos": [{"date": "2025-04-22", "group": 6}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162#page=16", "transcript_pages": [551, 552, 553, 554, 555, 556, 557, 558, 559, 560], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB963735665497D475A0DE78742A3DD0E703A6BB354DA833B757EFF7D7614A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 14}]}, {"dates": ["2025-04-28"], "dept": "民政", "doc_type": "部門質詢", "group": 4, "heading": "民政部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162#page=1", "transcript_pages": [663, 664, 665, 666, 667, 668], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549A2809FD8CCB9F1CFA5F4F65746A6E7AE9AA75B58C05E2582A852238F00A7C162", "videos": [{"date": "2025-04-28", "group": 4}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 13, "heading": "教育部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162#page=17", "transcript_pages": [1938, 1939, 1940, 1941, 1942, 1943, 1944, 1945, 1946], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1DE9E7FD99CCE24A874F8795B683F2AD8FD0C9A82BB53E536A852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 13}]}, {"dates": ["2025-05-19"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162#page=1", "transcript_pages": [77, 78, 79, 80, 81, 82, 83, 84], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE670FFE98A86206D656736907423338DC173220395D3464931C66C546CE5D43BD3AADC495AC5C7D475A852238F00A7C162", "videos": [{"date": "2025-05-19", "group": 15}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162#page=1", "transcript_pages": [305, 306, 307, 308, 309, 310, 311, 312], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC1A6DF43774A257154494C76E2F4EE9F9BAAE2E4EEA39E0546A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6E237495FF2E8C78C6736907423338DC11FA0BCD26452F22F1DD1208C3DFD48AE6CBF931729761E45A852238F00A7C162','2026-10-01T02:11:55Z');
INSERT INTO "fact" VALUES('summary:14-05:p3d9ce55419','p3d9ce55419','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:31:47Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 612, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=17"}, {"page": 613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=18"}, {"page": 613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=18"}, {"page": 614, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=19"}, {"page": 615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=20"}, {"page": 615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=20"}, {"page": 616, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=21"}], "councilor_points": ["鍾佩玲議員指出2025雙北世界壯年運動會籌備及執行過程出現多項缺失，包括賽程公告延遲與更動頻繁、報到與檢錄流程混亂致外國選手被迫棄賽、報名系統出錯及定向越野選手被迫闖紅燈等問題。鍾佩玲議員指出賽事在裁判與志工管理上亦顯混亂，例如藥檢人員通行證每日分區發放且未供餐，並統計抱怨賽事資訊與行政管理缺失至少有150件。鍾佩玲議員要求市府面對賽事比分顯示錯誤、選手失溫及相簿上傳錯誤等問題，應認真面對民眾抱怨並進行全面檢討。"], "response": "臺北市市長表示賽事整體而言算及格，發現缺失會即刻改進，會後將進行總檢討並吸取經驗以改善未來事前準備與細節。體育局局長說明相關狀況均有彙整並做精進，藥檢部分係由衛生局委外處理，後續會一起精進檢討。", "response_removed": false, "topic": "2025雙北世界壯年運動會辦理缺失與檢討"}, {"citations": [{"page": 281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=1"}, {"page": 283, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=3"}, {"page": 284, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=4"}, {"page": 285, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=5"}, {"page": 285, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=5"}], "councilor_points": ["鍾佩玲議員指出輝達確定進駐北投士林科技園區後將帶來大量人車潮，加上淡北道路工程交維計畫未將輝達進駐因素納入考量，恐使當地面臨嚴重交通噩夢。鍾佩玲議員建議市府立場應更強硬，要求新北市訂定大眾運輸移轉目標值，並加速啟動洲美快速道路延伸銜接國道1號等紓解方案，避免北士科變成內科2.0。"], "response": "交通局局長說明會努力避免北士科成為內科2.0，士北科周邊交通服務水準會在委託規劃案中重新調查並放大輝達影響比重，也會與新北市進一步協調大眾運輸移轉機制。交通局綜合規劃科科長表示針對洲美匝道及國道銜接工程，近期會與新建工程處開會溝通能否縮短工期以因應交通狀況。", "response_removed": false, "topic": "北投士林科技園區與淡北道路交通衝擊因應"}, {"citations": [{"page": 3154, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=9"}, {"page": 3156, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=11"}, {"page": 3157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=12"}], "councilor_points": ["鍾佩玲議員指出社宅「162快速服務」核心業務為保固與修繕，但市府卻在點交後半年的保固期內另編預算採購，且從109年至今17案金額高達3,400萬元，質疑有圖利廠商之嫌。鍾佩玲議員表示162快速服務約有8至9成屬物管人員即可完成之服務性質工作，若半年內需高強度修繕亦反映施工與驗收品質有問題，要求政風處進行調查。"], "response": "都發局局長說明162快速服務主要是提供駐點人力以提高服務時效，因過往未實施前簡單保固派工常需一週以上，係基於服務時效考量而非護航。政風處第二科科長表示會調回相關資料釐清案情。", "response_removed": false, "topic": "社會住宅「162快速服務」採購案檢討"}, {"citations": [{"page": 1664, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=8"}, {"page": 1666, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=10"}, {"page": 1667, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC14E7F06D36BCFD940F7E51C276181B535AEF46AC3C1EDA10CA852238F00A7C162#page=11"}], "councilor_points": ["鍾佩玲議員指出近3年校園性別與霸凌事件通報量增加，但成案比例僅約10%，原因包含舉證困難及第一線教師處置知能不足，並舉例有教師在班上公開交叉質問學生是否霸凌。鍾佩玲議員表示依規定行為人應接受心理輔導與性平教育，但資料顯示有一成行為人未接受心理輔導、三成僅接受低時數輔導，且違反專業倫理的教師類別甚至完全無心理輔導，要求補齊追蹤漏洞。"], "response": "教育局局長說明通報量多係因規定知悉24小時內須通報，後續聘請外聘委員調查程序較嚴格；針對行為人輔導漏洞會再進行瞭解並補上，並持續辦理教師性平研習。", "response_removed": false, "topic": "校園霸凌與性別事件處置及行為人輔導"}, {"citations": [{"page": 857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=1"}, {"page": 859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=3"}, {"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=4"}, {"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=4"}, {"page": 859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549F7FBBDB2CE90706AD96F00F4A8D98CD2C17008E5C8BE8502A852238F00A7C162#page=3"}], "councilor_points": ["鍾佩玲議員指出社會局規劃於年底推出生成式AI輔導情緒不穩定青少年，但尚未依市府作業指引提送內控流程與檢核表，且未編列新增預算。鍾佩玲議員提醒AI工具應注意安全與危機處置，要求第一線社工必須參與對話模型訓練評估，並建立AI檢測到自殘或自殺意向時的危機介入機制與加強社工人員訓練。"], "response": "社會局局長說明該案先前因銜接問題中斷後改以補助案完成，未來會補齊檢核表，且已規劃讓第一線社工與少年中心試用參與，並設有自殘自殺意向的危機介入與通報控管機制。", "response_removed": false, "topic": "生成式人工智慧輔導青少年政策與內控機制"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162#page=16", "transcript_pages": [611, 612, 613, 614, 615, 616, 617, 618, 619, 620, 621, 622, 623, 624, 625], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162", "videos": [{"date": "2025-05-29", "group": 3}]}, {"dates": ["2025-04-25"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162#page=8", "transcript_pages": [3153, 3154, 3155, 3156, 3157, 3158, 3159, 3160, 3161], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D4B8009D9FE39771A02DB963735665491F8CB959313ACB618E57DA4F3D0ADBF529631CD75704C2D5A852238F00A7C162", "videos": [{"date": "2025-04-25", "group": 14}]}, {"dates": ["2025-04-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 9, "heading": "警政衛生部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963