A7C162", "videos": [{"date": "2025-05-15", "group": 7}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 6, "heading": "交通部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162#page=1", "transcript_pages": [281, 282, 283, 284, 285, 286, 287, 288], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE60F2D2BD8B80F28A96736907423338DC10886F2C9682519BD77635FFCD1EC325FD87F7FCB3DE0E7E1A852238F00A7C162", "videos": [{"date": "2025-05-22", "group": 6}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC14851DFBFD2D860530C5E3549C6CD502D591CD360C6B1EA96A852238F00A7C162','2026-10-01T10:31:47Z');
INSERT INTO "fact" VALUES('summary:14-05:pd697b2a2b5','pd697b2a2b5','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T02:13:24Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 340, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162#page=1"}, {"page": 342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162#page=3"}, {"page": 344, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162#page=5"}, {"page": 344, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162#page=5"}], "councilor_points": ["鍾小平議員詢問警察局局長關於調查局傳喚相關人員之程序與比例原則。鍾小平議員指出多個行政區發生罷免連署活動，詢問擺攤連署之申請標準、路權與集會遊行規定，以及捷運站周邊距離劃分。鍾小平議員建議警察局對於爭議文宣進行勸導，並詢問如何維持行政中立及避免衝突。"], "response": "警察局局長說明警察局秉持行政中立與依法行政，依刑事訴訟法、道路交通管理處罰條例或集會遊行法辦理，並會派員維安與疏導交通。警察局捷運警察隊隊長表示捷運站體及腹地依規定不得進行競選活動，警方會協助現場治安維護，並勸導團體與學校及醫院出入口保持適當距離。警察局保安科科長說明若有不當文宣可向現場員警反映，警方會進行溝通。", "response_removed": false, "topic": "罷免案連署與警察執法維安標準"}, {"citations": [{"page": 1037, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=1"}, {"page": 1038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=2"}, {"page": 1039, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=3"}, {"page": 1039, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=3"}, {"page": 1040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=4"}, {"page": 1038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=2"}], "councilor_points": ["鍾小平議員指出中央扣減臺北市 30 億元一般補助款預算，詢問受影響之市政項目與排擠效應。鍾小平議員表示臺北市對中央稅收貢獻比例高，要求市府說明財政劃分現況與統籌分配稅款分配比例。鍾小平議員建議中央與地方應建立夥伴關係，關注弱勢族群與基層權益。"], "response": "臺北市市長說明預算刪減影響教育、社會福利及基礎設施，並表示中央與地方應為夥伴關係。文化局局長說明預算刪減會在市府整體預算中產生排擠效應。財政局局長說明臺北市在統籌分配稅款貢獻超過 40%，但分到比例僅 15%。民政局局長說明預算刪減會影響基層建設、生育獎勵金及里鄰長福利。", "response_removed": false, "topic": "中央補助款刪減與財政劃分影響"}, {"citations": [{"page": 2047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1F9F4CDAF6D9E049F41FCE7CCBC2E5BB62F9E69D4CD350845A852238F00A7C162#page=6"}], "councilor_points": ["鍾小平議員詢問社會局關於剴剴案民間協會外部督導之職責與領取費用情形。鍾小平議員指出外部督導未落實監督責任，要求社會局檢討相關機制。鍾小平議員要求社會局提出行政調查報告。"], "response": "社會局婦女福利及兒童托育科科長說明外部督導累積領取之費用統計與業務職責，並表示會在 1 週內提供行政調查資料。", "response_removed": false, "topic": "剴剴案外部督導責任與行政調查"}, {"citations": [{"page": 1040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=4"}, {"page": 2941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549E2B1CC5A028892BE5E5DADD4F67B0284A15CF0A962639887A852238F00A7C162#page=1"}], "councilor_points": ["鍾小平議員詢問都市更新處審議案件的人力配置現況與具體增加作法。鍾小平議員指出都更案數量龐大，建議運用住宅及都市更新中心行政法人機制補充人力。"], "response": "都市發展局局長、都市更新處處長及住宅及都市更新中心執行長說明持續請增人力之情形，以及都市中心協助辦理都更案之現況。", "response_removed": false, "topic": "都市更新審議人力配置與推動"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-06-09"], "dept": null, "doc_type": "市政總質詢", "group": 12, "heading": "市政總質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162#page=1", "transcript_pages": [1037, 1038, 1039, 1040], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162", "videos": [{"date": "2025-06-09", "group": 12}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 4, "heading": "工務部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549E2B1CC5A028892BE5E5DADD4F67B0284A15CF0A962639887A852238F00A7C162#page=1", "transcript_pages": [2941, 2942], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549E2B1CC5A028892BE5E5DADD4F67B0284A15CF0A962639887A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 4}]}, {"dates": ["2025-04-14"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162#page=1", "transcript_pages": [340, 341, 342, 343, 344, 345, 346], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6EFD653CE07AF13DDA02DB963735665493AE00441BE2D0003A3DB483AE5426AE184DC0F118788B903A852238F00A7C162", "videos": [{"date": "2025-04-14", "group": 4}]}, {"dates": ["2025-04-29"], "dept": "民政", "doc_type": "部門質詢", "group": 9, "heading": "民政部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549732D46B642F664191DD1208C3DFD48AECDE3DD351ED48D45A852238F00A7C162#page=1", "transcript_pages": [791, 792], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE62D2CBBF5CC4DB5ECA02DB96373566549732D46B642F664191DD1208C3DFD48AECDE3DD351ED48D45A852238F00A7C162", "videos": [{"date": "2025-04-29", "group": 9}]}, {"dates": ["2025-05-06"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC161F9A7D6484B1524D9C6CEAEE7044DFAF98AE9962A99A9D7A852238F00A7C162#page=1", "transcript_pages": [1720, 1721], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DC39DDDABE3FE9F96736907423338DC161F9A7D6484B1524D9C6CEAEE7044DFAF98AE9962A99A9D7A852238F00A7C162", "videos": [{"date": "2025-05-06", "group": 4}]}, {"dates": ["2025-05-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 2, "heading": "財政建設部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1F9F4CDAF6D9E049F41FCE7CCBC2E5BB62F9E69D4CD350845A852238F00A7C162#page=5", "transcript_pages": [2046, 2047, 2048], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE669B5B74E1D63E06D6736907423338DC1F9F4CDAF6D9E049F41FCE7CCBC2E5BB62F9E69D4CD350845A852238F00A7C162", "videos": [{"date": "2025-05-13", "group": 2}]}, {"dates": ["2025-05-23"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC19E13B1B16E4626D2A5F4F65746A6E7AEA2D5B2120916BBCBA852238F00A7C162#page=11", "transcript_pages": [391, 392, 393], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6D154A1884C35E7026736907423338DC19E13B1B16E4626D2A5F4F65746A6E7AEA2D5B2120916BBCBA852238F00A7C162", "videos": [{"date": "2025-05-23", "group": 11}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B918DC6F83B7CE8B6736907423338DC1A1C0FFCA5B84ECBAED6AE014B949854637F4F4FBD90FA597A852238F00A7C162','2026-10-01T02:13:24Z');
INSERT INTO "fact" VALUES('summary:14-05:p67335d29b9','p67335d29b9','summary','2025-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T10:33:22Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 251, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=25"}, {"page": 251, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=25"}, {"page": 253, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=27"}, {"page": 254, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=28"}, {"page": 250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=24"}, {"page": 254, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=28"}], "councilor_points": ["鍾沛君議員指出近五年65歲以上高齡駕駛為第一當事人的肇事比例逐步攀升，且現行制度下有22.4萬名滿83歲的高高齡駕駛因日出條款終身免換照。鍾沛君議員建議刪除高齡換照不溯及既往條款、參考國外制度導入實際駕駛能力測驗，並提供主動繳回駕照的加碼獎勵。"], "response": "交通局局長表示認同高齡換照與檢測的重要性，並說明會將刪除不溯及既往條款列為向中央建議的項目。交通局局長表示會在兩週內盤點地方可採取的作為及建請中央修法的項目。", "response_removed": false, "topic": "高齡駕駛換照制度與安全機制改善"}, {"citations": [{"page": 579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=47"}, {"page": 579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=47"}, {"page": 578, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=46"}, {"page": 580, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=48"}], "councilor_points": ["鍾沛君議員指出去年度全國簽署預立醫療決定書共25,816人次，臺北市占8,468人，但相較於本市65歲以上人口57.4萬人，簽署速度遠跟不上高齡化人口結構變化。鍾沛君議員建議市府擴大補助市民預立醫療照護諮商費用、提高醫事人員津貼，並擴充提供諮商服務的醫療院所數量。"], "response": "市長表示同意於一個月內提出評估報告。市立聯合醫院院長說明預立醫療決定書適用於末期病人、重度失智、不可逆轉昏迷及永久植物人等五大類情況。", "response_removed": false, "topic": "預立醫療照護諮商推廣與費用補助"}, {"citations": [{"page": 973, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=26"}, {"page": 974, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=27"}, {"page": 975, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=28"}, {"page": 976, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=29"}, {"page": 972, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=25"}, {"page": 973, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=26"}, {"page": 976, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=29"}], "councilor_points": ["鍾沛君議員指出捷運公司及市府各機關外包清潔人員面臨換包商特休歸零問題，要求市府全面盤點勞務採購合約是否納入派駐勞工權益保障條款，並統計各機關定期抽查訪視狀況。鍾沛君議員建議市府評估逐步將清潔等輔助性人力納入正式僱傭關係。"], "response": "勞動局局長表示已啟動專案清查，會在一個月內完成合約盤點與各機關抽查狀況統計。人事處處長說明清潔人力屬於輔助性工作，現行政策正逐步管制退離並採委外處理，會在符合法令下保障權益。", "response_removed": false, "topic": "市府外包清潔人員勞動權益保障"}, {"citations": [{"page": 561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=29"}, {"page": 563, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=31"}, {"page": 564, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=32"}], "councilor_points": ["鍾沛君議員指出捷運公司訂定的競選活動管理辦法規範車站出入口6公尺內限制競選活動，但在執行罷免團體違規宣傳時存在執法落差。鍾沛君議員要求市府與捷運公司釐清管理規範，並在面對各團體時落實一致的執法標準與行政中立。"], "response": "市長表示市府堅持行政中立且標準一致，凡違反規定者皆會依法處罰。臺北大眾捷運股份有限公司總經理說明是依大眾捷運法於路權範圍內裁處，若管理辦法解釋有疑義會檢討使其更明確。", "response_removed": false, "topic": "捷運車站周邊競選活動管理與行政中立"}, {"citations": [{"page": 1887, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=17"}, {"page": 1889, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=19"}, {"page": 1889, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=19"}], "councilor_points": ["鍾沛君議員指出普通班內情緒行為障礙特教生情緒爆發時影響師生安全與教學秩序，建議優化通報應變機制並提供全時段陪班人力。鍾沛君議員要求教育局於一個月內提出提升特教學生助理員人力、覆蓋率及時數比率的精進報告。"], "response": "教育局局長說明目前時薪、月薪及約聘特教助理員共999位，照顧時數已達77萬小時，並表示同意於一個月內提供人力提升計畫。", "response_removed": false, "topic": "融合教育特教生情緒行為處理與助理員配置"}], "session": "第14屆第5次定期大會", "sources": [{"dates": ["2025-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162#page=28", "transcript_pages": [560, 561, 562, 563, 564, 577, 578, 579, 580, 581, 582, 583, 584], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6DB6C894C03E381CE6736907423338DC15A95D08991582798494A067263F26EE855635BEAE38C0790A852238F00A7C162", "videos": [{"date": "2025-05-27", "group": 2}]}, {"dates": ["2025-04-21"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162#page=29", "transcript_pages": [2936, 2937, 2938, 2939, 2940], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE68E8B779F45862B8DA02DB96373566549F73613D64BBE2983C77A8BA43D4A83EBD3BA392ED9151B52A852238F00A7C162", "videos": [{"date": "2025-04-21", "group": 3}]}, {"dates": ["2025-04-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162#page=3", "transcript_pages": [563, 564, 565, 581, 582, 583, 584, 585], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE623F64863CFA31463A02DB9637356654933D71AB447C428C5A5F4F65746A6E7AE28362C85FF68AAC5A852238F00A7C162", "videos": [{"date": "2025-04-18", "group": 15}]}, {"dates": ["2025-05-05"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162#page=25", "transcript_pages": [972, 973, 974, 975, 976, 977], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE663E6DCF3C8E15DE4A02DB96373566549ECFC449C4FF26D05F4F762CDB128AEE48718CBDDD9C88EB5A852238F00A7C162", "videos": [{"date": "2025-05-05", "group": 16}]}, {"dates": ["2025-05-09"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162#page=14", "transcript_pages": [1884, 1885, 1886, 1887, 1888, 1889], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE63980B99A7368C7A86736907423338DC1372C42644ED83F21DA96A9FC687A721EC17161E5F3D286A5A852238F00A7C162", "videos": [{"date": "2025-05-09", "group": 11}]}, {"dates": ["2025-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 10, "heading": "財政建設部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162#page=17", "transcript_pages": [2235, 2236, 2237, 2238, 2239, 2240], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6C0694BC5D388D1CB6736907423338DC18616AF3B725D02F8E728C0B8BBF7348C219C1BBD57C52C20A852238F00A7C162", "videos": [{"date": "2025-05-16", "group": 10}]}, {"dates": ["2025-05-22"], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65E7B85B0CD2C36C16736907423338DC1C67076F5DA60E74EDD0E703A6BB354DACE0B61062BF7A926A852238F00A7C162#page=23",