INSERT INTO "fact" VALUES('profile:2022-local:p0301fbe4bc','p0301fbe4bc','profile','2022-11-26','{"education": ["醒吾科技大學-行銷與流通管理系畢"], "election": "2022-local", "experience": ["新北市第三屆議員\n醒吾科大研究所碩士班\n獲頒第九屆原曙獎促進原住民社會\n發展有功人士\n獲頒104年度原住民族教師大會暨\n推展原住民族教育有功人員\n擔任2020年新北市政府原住民文\n化資產傳統藝術類/審議委員\n擔任2016年新北市傑出演藝團隊-\n旅北都蘭部落文化藝術團/藝術總\n監"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/12-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%BA%8C%E3%80%81%E5%8D%81%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
