INSERT INTO "fact" VALUES('profile:2022-local:p07511ae4ba','p07511ae4ba','profile','2022-11-26','{"education": ["國立臺灣師範大學政治學研究所博\n士\n中國文化大學企業管理學系學士\n臺北市立中正高級中學"], "election": "2022-local", "experience": ["現任新北市議會第三屆議員，中國\n國民黨文傳會副主任委員，中國國\n民黨淡水區黨部主任委員。\n曾任中國國民黨發言人，中國國民\n黨新北市青工總會總會長，開南大\n學專任助理教授，立法院國會助理\n，考試院國家文官學院講座，公務\n人員考試閱卷委員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/01-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
