INSERT INTO "fact" VALUES('platform:2022-local:p0a54e1b425','p0a54e1b425','platform','2022-11-26','{"district_id": "nwt-council-04", "election": "2022-local", "office": "nwt_councilor", "text": "一、六年幼托，免負擔：1、加強教保人員身心健康，以保障受托幼童之安全。\n2、落實三胎的優先權利。\n3、廣設公共托育、幼兒園。\n二、十年長照，零負擔：1、廣設社區型老人關懷據點，因應快速的老人化社會。\n2、設立銀髮社區，活化老人文化。\n三、都更改建，保家園：1、為居的安全，加速都更進度。\n2、以里為單位，辦理都更說明會，協助都更完成。\n四、雙語教學，國際化：1、推動國中小，學校全面雙語課程規劃與實踐。\n2、辦理各項英語活動，讓語言可以在日常生活中落實。\n五、醫療量能，要保全：1、確保三重聯合醫院的醫療效能顧及三重蘆洲。\n2、加速蘆洲醫院的興建工程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/04-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%9B%9B%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
