INSERT INTO "fact" VALUES('platform:2022-local:p0bbaad845c','p0bbaad845c','platform','2022-11-26','{"district_id": "nwt-council-03", "election": "2022-local", "office": "nwt_councilor", "text": "一、督促捷運環狀線儘早完成以利市民搭乘，爭取新莊捷運線延伸至桃園。\n二、督促電影文化中心第二期儘速施工。\n三、建議市府寬列體育、文化、教育及社會福利經費，增設市立托兒所，增加生育、獨居老人照護、中低收入\n戶、急難救助補助。\n四、督促市府檢討規劃給孩童上、下學安全友善通行環境。\n五、爭取各級學校教室普設86吋教學觸控電視設備，充實教學設備改善及教學環境。\n六、督促儘速完成台65高架道路增設引道聯接高速公路，以改善五股交流道擁塞交通。\n七、優先完成塭仔圳重劃區內30公尺計劃道路，疏導交通。\n八、儘速完成塔寮坑溪及中港第三抽水站，以維護大新莊地區防洪安全。\n九、增設兒童共融式遊憩場所，提供孩童優質活動空間。\n十、督促儘速完成污水住戶接管，改善居住環境衛生。\n十一、督促規劃潭底溝及十八份坑溪為生態河川，改善沿岸鄰近住宅生活環境。\n十二、爭取新泰國小增設地下停車場。\n十三、爭取文高一設多功能運動中心及地下停車場。\n十四、徵收私有土地完成新莊文明文德活動中心與新莊國小球場共構改建，設公托、長照、老人、社區活動\n中心及地下停車場。\n十五、督促知識產業園區原司法用地興建多功能轉運站。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/03-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
