INSERT INTO "fact" VALUES('platform:2022-local:p0d18f05a99','p0d18f05a99','platform','2022-11-26','{"district_id": "nwt-council-11", "election": "2022-local", "office": "nwt_councilor", "text": "1.康寧街南下匝道，同興路延伸康寧街，吉林街儘速拓寬，交通立即可改善\n2.推動二高南下銜接環東\n3.推動汐止轉運中心\n4.汐科站增設出入口並爭取無障礙空間至經貿園區\n5.推動全國動保專線，並爭取興建汐止寵物公園\n6.推動汐止棒球三級制，並爭取棒球場興建\n7.台62線快速道路延伸至萬里\n8.推動萬里行政大樓，公有市場都更，全新打造新商場，停車空間\n9.提升北海岸醫療，長照服務，推動台大金山分院升級\n10.打造北海岸深度旅遊，推動海岸線自行車專用道串聯", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/11-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
