INSERT INTO "fact" VALUES('platform:2022-local:p1593d3a5bb','p1593d3a5bb','platform','2022-11-26','{"district_id": "nwt-council-08", "election": "2022-local", "office": "nwt_councilor", "text": "「為我們的城市 為我們的未來 跨越期待 看見未來」\n一、打造以新北市為核心千萬人口級的一流國際城市。\n二、傾聽基層聲音，反應基層民意，監督市政，建設光榮希望的新北市。\n三、選票補助款全數捐贈國中小教育。\n四、活得自在，活得有尊嚴。增設老人、幼兒活動設施「一里一銀髮俱樂部」、「一里一托幼」，推動「幼銀\n共榮」融合銀髮俱樂部與公托設施，推動「青銀共居」，打造「長照社區化」之社區長照據點。\n五、提高獎勵生育、托育補助及幼兒教育品質，積極鼓勵青年攜幼移居，增建青年住宅。\n六、利用公有土地獎勵民間投資或建案回饋加速設置幼兒、托老中心、停車場，解決民眾民生問題；增設圖書\n館，推廣學童閱讀計畫。\n七、推動十五年國民義務教育，強化技職教育分流，獎勵新北市產業與技職教育之共榮。\n八、打通瓶頸道路，降低公安危機；加速老舊社區更新並加速徵收開闢公園，提升居住環境安全與品質。\n九、督促市府全面盤點現有巷弄內汽、機車臨停、禁停與消防公安間的平衡問題，整理及新設自行車道提供安\n全舒適的親民環境，增益民眾福祉。\n十、爭取鄰里寵物公園專區，讓毛小孩及飼主有良好的休憩環境。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/08-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%85%AB%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p1593d3a5bb','p1593d3a5bb','profile','2022-11-26','{"education": ["國立政治大學經營管理碩士"], "election": "2022-local", "experience": ["國立臺灣大學ＥＭＢＡ碩士生\n德霖技術學院講師\n新北市議會國民黨黨團書記長\n國際獅子會３００Ｂ２區第二副總\n監\n國際扶輪社３４９０地區副秘書\n新北市宜蘭縣同鄉會副理事長\n新北市土城宜蘭同鄉會榮譽理事長\n新北市義勇消防總隊副總隊長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/08-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%85%AB%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p17660b9c13','p17660b9c13','bulletin','2022-11-26','{"district_id": "nwt-council-07", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/07-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p17660b9c13','p17660b9c13','platform','2022-11-26','{"district_id": "nwt-council-07", "election": "2022-local", "office": "nwt_councilor", "text": "城市建設好用「興」\n1.加速推動公辦都市更新程進程、建立自辦都更整合輔導機制。\n2.獎勵民間參與危老重建計畫、爭取都更容積獎勵最大化。\n3.設置數位智慧城市設施、擬定市容景觀、建築美學綱要計畫。\n長者福利最用「興」\n1.落實長者居家服務、日間照顧、居家復健、喘息服務、輔具購買及無障礙空間改造補助、\n公費安置、送餐服務、到宅沐浴 、交通接送的服務。\n2.輔導成立長者社團，鼓勵健康長者投入鄰里服務、社區托育、社會公益、主動學習等活\n動，體現敬老尊賢的倫理價值。\n3.爭取65歲以上長者假牙補助、持續發放敬老年金，增加敬老愛心點數。\n婦幼關懷好安「興」\n1.提高生育津貼，整合社區資源，打造友善育兒環境。\n2.增設公幼托兒機構與托幼補貼；因應國家雙語政策，加強雙語教學課程。\n3.規劃學童與夜歸婦女安全回家通道。\n4.婦女可申請3萬元一次性的凍卵補貼，往後3年也可申請一年 5000 元的卵子保存補助。\n青年創業最貼「興」\n1.結婚入籍永和生活的年輕人，每一戶可獲新台幣10 萬元「成家基金」。\n2.善用閒置公有房舍，成立青年新創基地、青年設計基地，並給予青創貸款。\n3.啟動疫情後經濟振興計畫，推動原有商圈再生活化，並發展永和主題旅遊及創意遊程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/07-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p17660b9c13','p17660b9c13','profile','2022-11-26','{"education": ["1.竹林小學", "2.福和國中", "3.北士商", "4.淡水工商管理學院", "5.大葉大學管理學院碩士班畢業"], "election": "2022-local", "experience": ["1.第六、七、八屆永和市民代表", "2.第一、二屆新北市議員（黨團幹事長、書記長） 3.世芳同濟會會長", "4.永和區博愛社區理事長", "5.新北市健康關懷協會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/07-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
