INSERT INTO "fact" VALUES('profile:2022-local:p253400be4a','p253400be4a','profile','2022-11-26','{"education": ["文化大學青少年兒童福利碩士、\n醒吾技術學院企管科二專、\n清傳商職、新泰國中、林口國小"], "election": "2022-local", "experience": ["第一、二、三屆新北市議員、第十", "六、十七屆代表、第十六屆縣議員、國民黨林口區黨部主委、林口區體育會理事長、林口區婦女會理事長、安桂獅子會會長、林口高中、林口國中、林口國小、麗園國小家長會長、新泰國中校友會理事長、文化大學法學博士候選人。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/02-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p3387fc5b50','p3387fc5b50','bulletin','2022-11-26','{"district_id": "nwt-council-12", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/12-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%BA%8C%E3%80%81%E5%8D%81%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p3387fc5b50','p3387fc5b50','platform','2022-11-26','{"district_id": "nwt-council-12", "election": "2022-local", "office": "nwt_councilor", "text": "一、教育&體育培植\n1、推動全齡化族語學習制度，族語教學納入補教體制，設立模範族語家庭獎勵機制。\n2、推動設立阿美族沉浸式族語實驗小學。\n3、制訂完整體育人才培育及退役後輔導計畫。(包含全國原住民運動會選手之培植)\n4、推動全國原住民族運動會「社會組別及傳統項目」運動員選拔機制設置。\n5、推動原住民族食農教育園區設置、原民作物可食地景之規劃。\n二、文化發展傳承\n1、爭取舉辦本市「原住民族嘉年華會」。\n2、要求市府重新審定族群領袖選拔制度，尊重各族群推舉方式。\n3、制訂各地區文化事務推動獎勵機制，鼓勵各族群加入各區協進會運作。\n4、文化祭儀預算，除依人口比例外，應考量少數族群需求，給予相對應資源。\n三、經濟產業升級\n1、爭取本市境內各大產業園區之「原住民專屬空間」，前期租賃費用減半。\n2、爭取設置原住民青創產業孵化器及加速器，編訂長期預算聘請專業團隊輔導陪伴。\n3、爭取開辦原住民族傳統工藝職業訓練，並與企業合作，增加族人斜槓收入。\n4、結合新興產業趨勢，輔導中高齡傳統產業族人利用已具備之技能，開創其他收入。\n5、爭取開辦新興創業工具之課程教學輔導，提升原住民族青年職場競爭力。\n四、落實居住正義\n1、訂定本市各河海濱聚落安置短中長期計畫設置。\n2、保障現有原住民國宅之河海濱聚落遷移住戶之永久居住權益，推動「以租代購」方案，取得所有權。\n3、訂定本市原住民國宅及社宅自治條例。\n4、爭取多處設置原住民族專屬社會住宅，持續爭取提高現有社宅原住民族人之比例。\n5、整合中央及地方現有資源，增設青年購屋、族人租屋諮詢服務窗口。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/12-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%BA%8C%E3%80%81%E5%8D%81%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
