INSERT INTO "fact" VALUES('platform:2022-local:p40ecce9eaa','p40ecce9eaa','platform','2022-11-26','{"district_id": "nwt-council-09", "election": "2022-local", "office": "nwt_councilor", "text": "【公民參與】2019以『參與式預算』精神，首創社區居民參與「圖書館新店分館改造建設案」為藝術風格圖書\n館。透過「參與式設計」，完成小城僑仁公園、大豐交通、瑠公、馬公、十四張、陽光運動公園等10座以上特色\n公園改善。\n【翻轉教育】推動偏鄉實驗教育，新增烏來德拉南實驗國小、坪林實驗國中，石碇國小轉型中。國中小班班有冷\n氣已到位並建置能源管理系統（EMS)完成除大豐小科技執法，保障學童穿越路口通行安全，並精進文山區各校通\n學巷。推動三語（中、英、電腦語言）教育，將程式語言向下扎根至5歲以上幼兒。\n【守護婦幼】通過「新北市電子煙及加熱式菸具管理自治條例」、「新北市自動選物販賣機管理自治條例」保護\n兒少，堅持「毒品零容忍」守護校園安全。以新店分局警察志工中隊成立雙城暖心站，定期關懷弱勢邊緣家庭。\n捐出競選得票每票30元補助，作為弱勢學子助學金每年發放。\n【青年創生】爭取公有市場給創業青年第一年攤位每月一元，第二年5折申請。為初尋職青年（新北市15歲至25歲\n的應屆畢業生）一年期定期保險。提供青創貸款利息補貼、青年租房補貼，推動新店寶高智慧園區育成青創中\n心，已完成央北青年住宅，推動新店安民段、斯馨段青年集合住宅。\n【活絡經濟】2020完成碧潭有約廣場，五年內推動十四張站捷運聯合開發（B 單元），2021完成寶高智慧園區一\n期，截至目前進駐鴻海、研揚、Garmin 航電、特斯拉等高科技公司，2022智慧園區二期規劃設計中，可望帶動\n16000個就業機會及286億元年產值的產業鏈。\n【城市永續】全台離都會最近的和美山螢火蟲步道就在碧潭，揪公民團體復育螢火蟲棲地，延伸碧潭堰生態廊\n道。因應氣候變遷，各項市府建設加入 SDGs 指標，並鼓勵企業 ESG 承擔社會責任，公私協力一起達到2030淨零\n碳排目標。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/09-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B9%9D%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
