INSERT INTO "fact" VALUES('platform:2022-local:p4b20356198','p4b20356198','platform','2022-11-26','{"district_id": "nwt-council-05", "election": "2022-local", "office": "nwt_councilor", "text": "●教育推廣更普及\n1.持續推動國家兒童未來館的建置。\n2.程式及語言教育向下紮根\n3.持續推行公共托育中心及公立附設幼兒園的建置。\n4.持續優化教學環境：校舍補強、老舊校舍改建，完成班班有冷氣。\n●生活品質更提升：\n1.設置專款基金，補貼青年弱勢族群租金。\n2.優化長者照護及推廣優質課程\n4.發展新創事業及招商，增加就業機會。\n5.爭取建置新北表演中心，推廣優質藝文活動。\n●城市發展再進化\n1.有效改善污水下水道工程。\n2.持續推動老舊社區都更，改善市容。\n3.推動電桿電纜地下化，整頓市容。\n4.增闢停車空間解決停車問題。\n5.持續推動泰板經浮洲輕軌，完成三環六線最後一塊拼圖。\n6.爭取建置體育局及資訊局。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/05-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p4b20356198','p4b20356198','profile','2022-11-26','{"education": ["光仁高中\n美國南伊利諾州大學\n台大政治碩士"], "election": "2022-local", "experience": ["新北市第1、2、3屆議員。新北市\n議會黨團副書記長。板橋區彰化同\n鄉會理事長。新北市關懷婦幼協會\n創會理事長。新北市優質舞蹈協會\n創會理事長。新北市毛小孩關懷協\n會創會理事長。板橋區工商婦女公\n益推展協會會長。2010年板橋青\n商會會長。新北家協、板橋家協、\n新北市教師會顧問。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/05-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
