INSERT INTO "fact" VALUES('bulletin:2022-local:p4ef4c72e4c','p4ef4c72e4c','bulletin','2022-11-26','{"district_id": "nwt-council-09", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/09-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B9%9D%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p4ef4c72e4c','p4ef4c72e4c','platform','2022-11-26','{"district_id": "nwt-council-09", "election": "2022-local", "office": "nwt_councilor", "text": "托育瑜你\n打造新店大文山托育友善空間 實踐在地托育\n■ 盤點閒置空間,做為社區托育與幼教場所\n■ 輔導具有相關專業之公私立機構,經營前項托育空間,使其成為教育與家庭間的中介單位,落實托育社區化,讓孩子們可以在地長大\n■ 增設特色公園與綠地,擴大市民休憩空間\n安養瑜你\n社區活動中心 長輩日照社區化 實踐在地安養\n■ 盤點閒置空間,作為微型化日照據點,延緩長輩老化\n■ 輔導公私立專業機構,就近提供日照服務,減輕小家庭經濟與交通接送困難\n■ 協助社區增加老人福利中心,讓老人照顧社區化\n助青瑜你\n提升產業 翻轉升級 推動新店大文山地區青創基地\n■ 以文化與歷史,結合地方創生,留住人才,讓地方生生不息\n■ 推動文化內容產業,發展電商通路\n■ 發展5G AIoT內容產業,以零汙染的數位內容、智慧應用,翻轉產業升級\n■ 推動在地青創基地,支持青年創業孵化夢想\n文化瑜你\n保留歷史文化 讓新店大文山找回光榮\n■ 地方建設與產業轉型,以文化與歷史,向下紮根\n■ 歷史遺址轉型公園化,串聯交通建設,彰顯在地人文價值\n■ 盤點舊古道,轉型親山步道\n交通瑜你\n爭取交通要平權 行人安心 用路人放心\n■ 爭取道路、產業道路、停車空間場域、公車路線等交通基礎建設,讓市民行得便利\n■ 強力要求完善電信收訊、網路等基礎建設,保障市民通訊,提升在地數位力！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/09-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B9%9D%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
