INSERT INTO "fact" VALUES('platform:2022-local:p4f70f84a10','p4f70f84a10','platform','2022-11-26','{"district_id": "nwt-council-05", "election": "2022-local", "office": "nwt_councilor", "text": "持續推動反對廢除死刑，堅決要求速審速決。\n酒駕、毒品零容忍，保障市民安全。\n協助保障爭取軍公教警消勞現職與退休權益。\n增設長照服務機構，同時建置友善安養環境。\n整治道路交通標誌標線規劃，改善交通壅塞問題。\n廣設共融式遊具，創造在地特色公園。\n提升新北居住品質，加速危老建築改善。\n活化閒置空間轉型青年社宅，放寬入住資格條件，減輕青年租房壓力。\n加強科技力量與創新變革，優化新北智慧城市，擴展國際能見度。\n持續整治雜亂電纜線，改善市容景觀，還給市民乾淨的天空。\n監督食安法規確實執行，守護全民健康。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/05-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
