INSERT INTO "fact" VALUES('bulletin:2022-local:p88c19e0eaf','p88c19e0eaf','bulletin','2022-11-26','{"district_id": "nwt-council-08", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/08-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%85%AB%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p88c19e0eaf','p88c19e0eaf','platform','2022-11-26','{"district_id": "nwt-council-08", "election": "2022-local", "office": "nwt_councilor", "text": "˙ 打造鶯歌外環道，分散市區車流。\n˙ 新建鶯歌生命紀念園區。\n˙ 加強區域排水系統，因應極端氣候。\n˙ 持續爭取鶯歌公四公園興建多功能活動中心、運動休閒場所、政府機關辦事處。\n˙ 推動智慧公車系統，增加公園、老街、博物館及各景點路線及班次。\n˙ 持續推動提供清明公墓除草服務、鶯歌清潔隊服務中心興建。\n˙ 加速興建捷運三鶯線、樹林萬大線、鳳鳴臨時火車站。\n˙ 推動樹林、鶯歌鐵路立體化，消弭危險平交道。\n˙ 新設北二高金城交流道。\n˙ 推動土城司法園區設立生態公園綠地。\n˙ 持續推動三峽長福及鶯歌公八公園停車場立體化、三峽河整治及長福橋改建。\n˙ 爭取設立三峽大豹溪風景區。\n˙ 持續推動設置各項親子及長者共融性特色公園。\n˙ 督促市府輔導污染業者，加強稽查非法棄置垃圾，於污染熱區設置空氣、水質感測器，還給居民乾\n淨之生活環境。\n˙ 設置寵物公園讓毛小孩及飼主有良好的休憩環境。\n˙ 閒置教室，轉化為公托公幼並延長服務時間，強化社區長照機制；加強學校課後輔導，減輕家長負\n擔。\n˙ 關懷弱勢族群，結合公家及民間資源，持續捐出每票30元之選舉補助款給社福團體。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/08-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%85%AB%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
