INSERT INTO "fact" VALUES('profile:2022-local:pa16e054479','pa16e054479','profile','2022-11-26','{"education": ["五股國小畢業。五股國中畢業。西\n湖工商畢業。醒吾技術學院畢業。\n文化大學政治學研究所碩士畢業。"], "election": "2022-local", "experience": ["輔仁大學商學研究所博士班。\n新北市議員、台北縣議員、五股鄉\n民代表、海龍蛙兵教官、新北市親\n子協會創會長、新北市救難協會創\n會長、新北市籃球委員會主委、台\n北澎湖同鄉會理事、醒吾科大校友\n會理事長、台灣幸福基金會董事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/02-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pa5b5a879f8','pa5b5a879f8','bulletin','2022-11-26','{"district_id": "nwt-council-07", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/07-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pa5b5a879f8','pa5b5a879f8','platform','2022-11-26','{"district_id": "nwt-council-07", "election": "2022-local", "office": "nwt_councilor", "text": "1.新基建-改善基礎建設，擺脫老舊都市，活化閒置空間，創造市民活動空間，持續汙水下水\n道建置、汰換老舊水、電、瓦斯管線，打造優質生活環境。\n2.新安居-加速、鼓勵危老都更，爭取更多公辦都更機會、活化閒置場域興建社會住宅，守護\n市民居家財產安全。\n3.新捷運-推動秀朗區段捷運規劃，完善大眾運輸路網，優化周邊交通，改善聯外交通路線，\n通勤路線更加多元方便。\n4.新校園-提升新北教學品質、校園環境與新北技職教學，推動特色教育和在地就學，建置全\n面性校園安全網，守護保護學童更安全。\n5.新社福-重視社福關懷，建置銀髮俱樂部及日間照護中心，完善在地醫療體系，讓長者得到\n最好的照顧，鼓勵銀髮學習，讓長者走出家門，享受樂適快活不在家當LKK。\n6.新育兒-完善婦幼政策，打造共融環境，結合產、官、學力量，讓公托、幼收量成長，減輕\n家長壓力，讓父母安心，打造特色共融公園與友善校園，讓親子同樂共享好時光。\n7.新商圈-改造舊有商圈，振興地方經濟，保存在地特色，研擬「商圈自治發展條例」法規，\n永和每個角落都充滿太多故事，延續在地價值，透過熱情與理念，傳承世世代代。\n8.新保育-打造保育都市，豐富綠色生活，打造生態遊憩資源，創造自然環境教育的體驗，為\n當代與下一代人們更好的環境發展，都市保護區是重要的公共空間。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/07-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
