INSERT INTO "fact" VALUES('platform:2022-local:pb726cd88aa','pb726cd88aa','platform','2022-11-26','{"district_id": "nwt-council-03", "election": "2022-local", "office": "nwt_councilor", "text": "1.加速新莊第一公墓遷葬，推動公墓用地變更，設置新莊森林公園\n2.爭取福營運動中心興建，加速閒置公有土地活化，平衡南北新莊發展\n3.調整里基層工作經費核發標準，依人口數設置級距，均衡新舊社區里民待遇\n4.呼籲恢復社團活動補助款，專注銀髮樂活照顧與在地青年社區營造工作，提升社群互助動能\n5.建立社區型防災與全民防衛機制，擴大新莊區民參與，有效對抗天災人禍風險\n6.推動塭仔圳土地開發共榮機制，重劃區開發兼顧周邊既存社區需求，開發效益回歸在地居民\n7.運用重劃後市府配回土地，推動替代發展模式，改善交通瓶頸與用路問题", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/03-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
