INSERT INTO "fact" VALUES('bulletin:2022-local:pd8dcd7dc3f','pd8dcd7dc3f','bulletin','2022-11-26','{"district_id": "nwt-council-13", "elected": true, "election": "2022-local", "office": "nwt_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/12-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%BA%8C%E3%80%81%E5%8D%81%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd8dcd7dc3f','pd8dcd7dc3f','platform','2022-11-26','{"district_id": "nwt-council-13", "election": "2022-local", "office": "nwt_councilor", "text": "一、福利權益：1.要求提高各項補助、急難救助並簡化程序及降低條件。2.爭取提高原住民族國宅配比、租屋補助、購\n屋利息補貼。3.爭取增加建構及修繕住宅補助戶並提高補助金額。4.敦促市府提高「敬老愛心卡」每月補助點數並擴大\n使用範圍。5.監督落實「新北市保障原住民族就業自治條例」。\n二、健全制度：1.推動成立公法人「新北市原住民族基金會」，推動就（創）業、長照、教育、居住、法律扶助、語言\n文化，補足行政資源缺漏。2.爭取開辦「原住民族微型保險」，並串聯原家中心、文健站、原教中心、語推人員、就服\n站、各族群團體、信仰組織，建構完整原住民社會安全網及文化經濟支持體系。3.成立原住民族青年服務小組及青年論\n壇，關注青年族人議題，並分項輔導及培植原住民族青年卓越人才。4.監督各項補助及經費公平保障支持多元信仰。5.\n爭取補助族群領導人公共事務費用。\n三、文教體產：1.監督市府獨立編列常態預算辦理各族群文化祭典、各區歲時祭儀；配合各協進會、同鄉會等人民團體\n，辦理文化及傳統技藝活動。2.爭取挹注經費發展原住民族文創產業及農特產市集，設立交流平台並推廣工藝師制度，\n辦理文化尋旅相關活動。3.爭取新北市原住民族生育津貼、育兒津貼及幼教補助。敦促增加公托原住民族生錄取名額。\n4.擴大體育發展預算，培育原住民族運動人才。訂定獎（補）助辦法，補助原住民族體育生相關器材費、訓練費、營養\n費、教練費。5.敦促市府定期辦理原住民族各項傳統競技及專長運動項目活動，並提高全原運等賽事獎勵金。6.整合跨\n局處資源建立小農、工藝、文創、觀旅等整體原住民產業創就業輔導平台。\n四、原鄉建設：1.配合區公所推動發展全區文化觀光產業，推廣一部落多休閒。2.爭取建設烏來泰雅文化園區，整合資\n源、建構各部落傳統市集及在地商場。3.爭取各項地方建設及產業發展預算，支持各部落及社區推動總體營造。4.敦促\n完成烏來區內聯絡道路、景觀道路。極力爭取各產業道路改善工程。5.爭取原鄉泰雅山徑重建及各里舊有登山步道再造\n工程預算。6.監督越域引水計畫進程、捍衛部落權利，守護泰雅山林。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/02%E6%96%B0%E5%8C%97%E5%B8%82/12-%E6%96%B0%E5%8C%97%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1-%E7%AC%AC%E5%8D%81%E4%BA%8C%E3%80%81%E5%8D%81%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
