INSERT INTO "fact" VALUES('bulletin:2022-local:p1181c0434b','p1181c0434b','bulletin','2022-11-26','{"district_id": "tao-council-09", "elected": true, "election": "2022-local", "office": "tao_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC9%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p1181c0434b','p1181c0434b','platform','2022-11-26','{"district_id": "tao-council-09", "election": "2022-local", "office": "tao_councilor", "text": "家興熟悉行政法令與程序，更了解鄉親們的生活需求，所以我將秉持永續服務的精\n神、促進地方繁榮：\n1.積極爭取公立托嬰及托育所，讓年輕夫婦能安心工作。\n2.爭取社會住宅、於公有地興建住宅。\n3.建立食安機制、讓百姓對食的安全無慮。\n4.積極爭取現代化農機設備及農業政策推廣、協助農民的成長。\n5.落實勞工就業及勞工退休準備金提撥率、以防止惡性歇業事件發生。\n6.推動弱勢團體及提高老人三節敬老金與為鄉親爭取更好的福利政策，讓幼有所育\n長有所尊。\n7.爭取更多的地方建設經費以加強基層建設讓楊梅更好、如行的安全。\n8.監督政府提高服務效率、杜絕浪費公帑。\n9.督促政府加強推動楊梅區各項公共建設。\n10.積極爭取秀才步道、福人步道、清水步道、保甲步道改善及12座公園增設兒童遊\n戲器材、成人運動器材以推動全民保健運動。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC9%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p1181c0434b','p1181c0434b','profile','2022-11-26','{"education": ["淡江大學推廣教育大學部結業、治平\n高級中學畢、仁美國中畢、高榮國小\n畢、先鋒企業管理修畢、中華企管修\n畢。"], "election": "2022-local", "experience": ["第1、2屆桃園市議員；第14、15、16、17屆桃園縣\n議員；第14、15屆桃園縣楊梅鎮民代表；市議會無\n黨聯盟總召；楊梅李姓宗親會會長；治平高級中學\n校友會會長；楊梅區太極氣功協會理事長；楊梅區\n高山社區發展協會理事長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC9%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
