INSERT INTO "fact" VALUES('platform:2022-local:p130f21a381','p130f21a381','platform','2022-11-26','{"district_id": "tao-council-01", "election": "2022-local", "office": "tao_councilor", "text": "生長在軍人世家的婉如，從小培養出不投機取巧、不徇私舞弊的人格特質、誠懇活力、勤奮正義是婉如一向的工作態度，秉\n持此特質與態度，累積多年民意代表服務民眾的熱忱與經驗，持續督促市府加強為民服務，施政必須透明公開，經費當省則\n省。各級首長用人唯才，獎勵優秀公務人員，領導者必須以身作則，不得循私舞弊，列舉參選政見如下：\n1.推動老舊市區都市更新，擴大老屋拉皮補助，整頓人行道，優化公園設施，活化閒置國有土地，提供市民更多元的休憩場\n所，建立美麗新桃園。\n2.縮短交通黑暗期，推動共享經濟廣泛建構U-Bike2.0、U-moto及各型交通工具的分享，積極推動棕線、綠線捷運及鐵路地下化\n的興建，解決都市交通擁擠及空污問題。\n3.加強天羅地網建置密度，減少治安死角，充實警力維護治安、交通，為市民的生活安全把關。\n4.鼓勵生育，普設公共托嬰中心，爭取向下延伸義務教育一年，減輕家長育兒負擔。\n5.廣設創業基地，服務青年朋友充分就業或創業，加強就業輔導，協助中高齡者重回職場。\n6.推動桃園區特色觀光，一山（虎頭山）、二水（南崁溪、埤塘）、三商圈（站前商圈、藝文商圈、博愛路商圈）、四個歷\n史建築（忠烈祠、七七藝文町、桃園文學館及農會穀倉），打造桃園成為全國最好玩的城市。\n7.催生桃園市立醫院成立，提升桃園醫療資源，加強食品藥物源頭及衛生管理，推動食安資訊透明化，為市民健康把關，加\n強建築物消防安檢，建立防災地圖，確保市民居住安全。\n8.輔導社福機構健全發展，增設各種非營利組織，加速無障礙、輔具補助效率，照顧弱勢族群。\n你來說我來做，共同監督市政，邁向現代化、資訊化、科技化的直轄市。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
