INSERT INTO "fact" VALUES('platform:2022-local:p4daea08205','p4daea08205','platform','2022-11-26','{"district_id": "tao-council-01", "election": "2022-local", "office": "tao_councilor", "text": "美梅這幾年擔任市議員無論是出席率、爭取社會福利和地方建設都受到地方民眾的肯定，要讓大家在桃園生活的\n每一步，能夠更方便、更安心！用理性問政，同理心服務，一本初衷做有益大眾的事。美梅持續推動虎頭山公園\n和周邊的南崁溪的休閒場域的串連、大有梯田公園、民富社福館、南昌營區和桃林鐵路活化、文昌公園地下停車\n場、爭取完成體育班三級銜接教育、青年就業補助和中高齡就業補助與中路足球場的興建、社會租宅和租金補貼\n政策、國中小班班有冷氣、易淹水地區的改善和延平路延伸打通到八德；了解婦幼與長者需求，完成65歲以上長\n者的健保補助和愛心敬老卡可以搭乘桃園機捷和托育補助和幼童上幼兒園的教育補助費、國強幼兒園興建，努力\n推動貼心政策，就是要讓大家更幸福！未來，美梅持續推動增設公立幼兒園、爭取市立醫療院所。一、公共建設\n：爭取增設活動中心和停車場和運動相關場地、推動共融式公園、整治南崁溪、東門溪、茄苳溪與監督污水下水\n道建設，提升居住環境品質。持續關心中油的遷廠和公安問題。二、交通：爭取全市及往返雙北間完善公車運輸\n網。爭取新增設交流道和桃園往中壢的快速道路，督促市府如期完成捷運綠線、棕線儘速施作。爭取國際路延伸\n富國路和幸福路延伸、爭取無尾巷打通讓居住更安全交通便利。持續推動公共租借式自行車的設置。持續推動無\n障礙愛心計程車，讓身障者行的更便利、爭取愛心敬老卡點數搭火車。三、社會福利：推動社會租宅和租金補貼\n政策，讓弱勢家庭和新婚青年安居。督促市府制定幼兒教育補助和生育補助。落實照顧低收入戶及急難救助；爭\n取殘障福利，建構完善無障礙空間。推動青年和婦女創業補助輔導措施。老人和幼兒照護方面推動一區一日照中\n心、長期照護和關懷據點，增設2歲以下公托，解決上班族的負擔，充分利用學校和公家廳舍閒置空間。爭取巡\n守隊、義警、義消民防志工設備經費補助。爭取培育體育運動選手相關補助費。爭取農民發展精緻農業，補助肥\n料和農機購置經費。推動友善動物環境相關政策。願以豐富之經驗，全力爭取人民權益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p4daea08205','p4daea08205','profile','2022-11-26','{"education": ["會稽國小。文昌國中。復旦高級中學。\n美國羅倫斯科技大學資訊系統碩士。"], "election": "2022-local", "experience": ["聖德基督學院大眾傳播系。桃園市議員。桃園縣青\n工總會總會長。桃園市保母協會理事長。桃園市陳\n姓宗親會副總長。桃園市體育會足球委員主任委員\n。龍鳳獅子會創會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
