INSERT INTO "fact" VALUES('platform:2022-local:p91c849f8de','p91c849f8de','platform','2022-11-26','{"district_id": "tao-council-12", "election": "2022-local", "office": "tao_councilor", "text": "一、加速推動觀音區保障里市民活動中心興建計畫。\n二、督促桃園市政府儘速完成月桃路全線拓寬至草漯地區縮短與青埔特區路程，帶動\n周邊地區發展。\n三、推廣在地農產、發展休閒農業。\n四、友善育兒環境、爭取育兒津貼。\n五、落實回饋金回饋在地機制，提升地方各項福利。\n六、要求環境保護單位嚴格稽查固定污染源確保空氣品質。\n七、「2023 世界客家博覽會」連結觀音景點以帶動觀光發展", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC12%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
