INSERT INTO "fact" VALUES('platform:2022-local:p9762ae1d2a','p9762ae1d2a','platform','2022-11-26','{"district_id": "tao-council-11", "election": "2022-local", "office": "tao_councilor", "text": "1.完成頭洲科技園區、捷運新屋-中壢線捷運計畫。\n2.開闢公一埤塘公園並開通新榮路至民族路計畫道路。\n3.更新區內公園為共融式特色遊具並爭取「新屋旗艦型公園」。\n4.重啟中山西路一段兩線道拓寬四線道案。\n5.重新檢討新屋都市計畫、擴建部桃新屋分院。\n6.爭取新屋沿海成為「市級風景區」，台61橋下興建大型運動公園。\n7.完成永安低碳轉運中心、觀海橋重建，改善假日交通問題。\n8.落實新屋各小學「一校一外師」、「班班有觸屏，人人有平板」政策。\n9.提升區內監視器數量，治安無死角。\n10.提高新屋農機補助，輔導農友機械化生產。\n11.推廣新屋休閒農業區、推動新屋地方創生，吸引青年返鄉。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC11%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
