INSERT INTO "fact" VALUES('platform:2022-local:pa300cd1703','pa300cd1703','platform','2022-11-26','{"district_id": "tao-council-13", "election": "2022-local", "office": "tao_councilor", "text": "一、推動桃原新政福利2.0升級。\n二、爭取成家基金補助減輕青年負擔。\n三、依據桃園市原住民族自治發展條例，持續督促市政府迅速擬定相關子法，以利落實保障原住\n民族政治參予，經濟發展、創業就業、教育文化、社會福利、居住權益。\n四、整合原住民族權益服務機構，設置原住民族專責諮詢專線電話1994。爭取成立原住民就業人\n力站，單一窗口整合局處資源，主動聯繫、輔導、追蹤，訓用合一協助青年族人就業。\n五、爭取考取技術士證照提高補助。\n六、推動原住民族經濟產業服務平台，協助原住民族取得創業基金與事業維持扶助金之貸款或補\n助。\n七、積極盤點閒置空間設置文化健康站並培力長照相關人才投入長照事業。\n八、協助原住民族長者發揮銀色智慧，建立青銀族群互為導師制度，協助文化健康站轉型成為青\n銀共榮共好之基地。\n九、全面推動國中小雙語教育提升國際競爭力。\n十、建立體育人才資料庫，協助輔導轉職、創業，擴大專任教練員額，鼓勵投入基層三級體育教\n育。\n十一、爭取提高事務幹部工作津貼，提升族群領袖地位。\n十二、提高各區原住民生活教育協進會預算辦理各項活動。\n十三、持續爭取設置集會空間及天幕廣場。\n十四、加速完成原住民專屬社會住宅完工並提高社宅原住民優先戶申請比例。\n十五、支持18歲公民權。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC13%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
