INSERT INTO "fact" VALUES('platform:2022-local:pbe960798bf','pbe960798bf','platform','2022-11-26','{"district_id": "tao-council-14", "election": "2022-local", "office": "tao_councilor", "text": "福利權益：\n1、爭取提升原住民社會住宅比例\n2、增加公托原住民族生錄取名額\n3、增加成立原住民傳統農耕示範區\n教體發展：\n1、協助輔導成立原住民課後輔導班\n2、利用E化教學，落實原住民學生學習族語之權益\n3、增加羅浮完全中學科系多樣化及發展原住民族教育特色\n4、培育原住民體育人才，輔導體育人才多元發展及就業\n產業文化：\n1、推廣原住民傳統文化活動及技藝，常辦理相關技藝課程及建立原民技藝交流平台\n2、爭取國際原住民文創園區規劃發展原住民族文創產業及農特產市集\n青年扶植：\n1、結合各族群成立原住民青年諮詢委員會，並定時舉辦青年論壇及交流活動\n2、增加原住民多元職業訓練專班及證照班\n3、增加原住民青年創業空間，輔導原住民青年創業\n原鄉發展：\n1、爭取自來水管線延伸至羅浮、義盛、霞雲\n2、推動原鄉醫療，爭取成立醫療中心及洗腎中心\n3、協助族人處理電信通訊問題\n4、妥處原住地保留地、違建糾紛\n6、完善市管道路及增加觀光亮點，美化部落\n7、市管風景區及羅浮溫泉攤販租金優惠及長期輔導", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pbe960798bf','pbe960798bf','profile','2022-11-26','{"education": ["桃園市中壢區林森國民小學\n桃園市立東興國民中學\n桃園市啟英高級中等學校\n亞洲大學管理學學士"], "election": "2022-local", "experience": ["桃園市議員王仙蓮服務處秘書。桃園市議員蘇志強\n服務處秘書。桃園市中壢區協進會青年組長。桃園\n市楊梅區文化健康站督導。桃園市原住民原卡拉社\n遷移大潭新村協會總幹事。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pd53aa3f775','pd53aa3f775','bulletin','2022-11-26','{"district_id": "tao-council-14", "elected": true, "election": "2022-local", "office": "tao_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd53aa3f775','pd53aa3f775','platform','2022-11-26','{"district_id": "tao-council-14", "election": "2022-local", "office": "tao_councilor", "text": "情為民所繫 利為民所謀 權為民所用 青年承擔 謙恭傾聽 用心服務\n一、推動建置原住民族文化創意園區以及青年創業育成孵化器，形成產業聚落。\n二、規劃首座原住民族文化主題公園，打造桃園為連結國際多元文化國門窗口。\n三、爭取青年國內外不同領域企業職場實習機會，增廣視野及裝備職場競爭力。\n四、協調統合公部門與民間企業徵聘職缺，定期舉辦專屬原住民就業博覽媒合。\n五、設置原住民族語教學幼兒園、增加培訓族語保母人數，語言學習向下扎根。\n六、增設老人日間文化健康關懷站以及提供接送服務，提升照顧服務支持系統。\n七、簡化社會福利申辦程序，建立單一服務窗口，結合教會提供弱勢家庭關懷。\n八、提高預算支持原住民社團協會，舉辦語言文化傳承、學習、發揚相關事務。\n九、建設復興區泰雅族文化觀光園區、推動設置北橫國家風景區升級休旅產業。\n十、強化與教會協力合作推展社會福利、語言文化學習、孩童安親等各項施政。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd53aa3f775','pd53aa3f775','profile','2022-11-26','{"education": ["美國紐約聖若望大學企業管理碩士\n東吳大學企業管理系\n國立屏東高中"], "election": "2022-local", "experience": ["桃園市第二屆市議員、全國原住民傑出青年、國立\n臺灣師範大學原資中心諮詢委員、立法委員國會辦\n公室主任、大紐約地區台灣學生會長、駐紐約台北\n經濟文化辦事處專員、聯合國原住民族常設論壇觀\n察員、教育部格大學講師、國發展研究院諮詢委員\n、中華人權協會副主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
