INSERT INTO "fact" VALUES('platform:2022-local:pd68cbb089b','pd68cbb089b','platform','2022-11-26','{"district_id": "tao-council-14", "election": "2022-local", "office": "tao_councilor", "text": "1、捍衛原民土地地用權益及提升土地經濟效益。\n2、貫徹原住民族教育法，保障就學權益。\n3、培植原民各式多元產業發展及品牌精緻化。\n4、推廣發展原民各族群文化純粹精神。\n5、落實原民青年創業，提供青創基金及輔導計劃。.\n6、繼續爭取原民各項福利、安心居住、就學、就業、就養於桃園。\n7、積極推動原民部落營造、觀光、交通、水電等建設。\n8、保障原民就業權，爭取工作機會。\n9、盡心、盡力、盡意服務，一切為原民鄉親，榮神益人。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC14%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
