INSERT INTO "fact" VALUES('platform:2022-local:pd9c62a6359','pd9c62a6359','platform','2022-11-26','{"district_id": "tao-council-13", "election": "2022-local", "office": "tao_councilor", "text": "1. 設置原住民托嬰中心免費\n2. 租屋補助提高到1萬元\n3. 區主席及頭目津貼提高至最低薪資\n4. 建購修繕補助門檻要降低以嘉惠更多族人\n5. 市府工程就業保障並提高原住民任用員額創造族人就業機會\n6. 保障原住民單親扶養家庭者工作優先權\n7. 結合工商企業者對原住民團體提供廣泛的贊助\n8. 企業任用原住民及弱勢者提高獎勵金額\n9. 於桃園中正國際機場及桃捷各站設立原住民手工藝服飾音樂及美食展售店\n10. 推行幼兒園沉浸式族語教學\n11. 增設原住民射箭練習場\n12. 爭取原住民各區設置原住民集會所\n13. 簡化政府相關補助經費核銷流程\n14. 都會區原住民老人安養中心設置\n15. 爭取原住民族人安祥歸根車馬費", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC13%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd9c62a6359','pd9c62a6359','profile','2022-11-26','{"education": ["花蓮縣立光復國小\n花蓮縣立光復國中\n國立台東高商\n國立台北商業大學二專部"], "election": "2022-local", "experience": ["國立台北商業大學\n服飾公司會計\n哈佛結婚攝影廣場專員\n國泰人壽業務襄理\n複合式餐廳負責人\n悅來(遠來)五星飯店行銷專員\n太魯閣國家公園導覽人員\n原住民仙島部落發展協會理事\n原騰企業有限公司\n拉拉山大山菊茶莊負責人"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC13%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pecea4f5e79','pecea4f5e79','bulletin','2022-11-26','{"district_id": "tao-council-08", "elected": true, "election": "2022-local", "office": "tao_councilor", "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC8%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf18367e3f6','pf18367e3f6','bulletin','2022-11-26','{"district_id": "tao-council-03", "elected": true, "election": "2022-local", "office": "tao_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf18367e3f6','pf18367e3f6','platform','2022-11-26','{"district_id": "tao-council-03", "election": "2022-local", "office": "tao_councilor", "text": "1.持續監督八德大鶯豐德交流道，要求二年內土地徵收及動工。\n2.原行政用地規劃興建北區青少年活動中心(桃寶館、 桃漾館)。\n3.因文小二用地閒置而設棒壘球場，去年提議興建仁德國小，預計113年招生。\n4.持續督促中央大學在八德擴大都市計畫預定地興建八德分校打造『智慧健康創新園區』。\n5.爭取整治大仁溜池、廣興溜池及瑞興溜池綠化美化及環湖步道。持續推動公園特色化、埤塘活化及打卡景點。\n6.關心捷運綠線G01、G04招商及商場規畫，完善周圍商業機能，打開G02至G03橋下道路連接六號生活道路。\n7.爭取八德公車轉運站，交通更快速便捷，加強醫療便利性，增加大型醫院專車。茄苳路國小永豐路截彎取直。山下街打\n通至新興路。\n中華路5巷瓶頸道路打通工程、規劃興豐路2189巷至福德一路177巷道路拓寬8米道路。\n八德區茄苳路91巷瓶頸道路打通工程、樹仔坡截彎取直瓶頸道路打通工程、和平路到介壽道路工程定線案\n8.積極推動仁德國小、公托及青少年活動中心，優化校園環境，減輕家庭負擔，青年多元學習。\n9.持續關心雨水下水道、滯洪池及汙水下水道工程。\n10.加強路平道路養護、道路拓寬及交通安全問題。爭取閒置用地，有效利用。\n11.爭取大勇國小擴建、大福國小增建、永豐國中小增建、八德國中擴建、督促教育局重劃中華電信國中預定地增建。\n12.持續推動八德公托中心及親子館，提供優質托嬰環境、減輕家庭負擔及親子共同學習成長空間。\n13.配合長照2.0政策佈建ABC據點，持續設立日照中心，並爭取八德一據點一藥師制度，對特殊需求長者提供送藥到府及\n居家藥事服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf18367e3f6','pf18367e3f6','profile','2022-11-26','{"education": ["省立中壢高商畢\n清雲科技大學財金系畢\n清雲科技大學國際企業管理研究所碩士"], "election": "2022-local", "experience": ["桃園市第一、二屆市議員\n民進黨桃園市黨部主委、民進黨中央黨部第十九、\n二十屆中執委、八德區呂姓宗親會理事長、八德區\n林姓宗親會理事長、運動協會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf5d653e12b','pf5d653e12b','bulletin','2022-11-26','{"district_id": "tao-council-05", "elected": true, "election": "2022-local", "office": "tao_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf5d653e12b','pf5d653e12b','platform','2022-11-26','{"district_id": "tao-council-05", "election": "2022-local", "office": "tao_councilor", "text": "一、爭取提高國中小營養午餐經費補助。\n二、推動舊校舍翻新、營造優質教育環境。\n三、督促早日設置航空城開發區內具現代化、科技化之新校園教育環境。\n四、爭取各地區普設「托嬰中心」、「公立幼兒園」或「準公共化幼兒園」解決幼兒托育困境，減輕年青家長的負擔。\n五、爭取航空城開發區興建社會住宅與建立多處停車場，解決未來停車問題，並成立青年住宅專區。\n六、增加青年創業貸款額度，免費提供青年專業技能教育訓練，提升青年本職學能，創造高薪機會。\n七、督促早日完成清華大學桃園醫療及教育園區興建與提升醫療服務品質。\n八、持續爭取興建大園體育園區早日完成，造福百姓。\n九、積極爭取台15線至台61線，國二甲延伸第二階段路廊建置。\n十、爭取「捷運輕軌」大園觀音線早日規劃興建，帶動大園-南港客運園區-草漯-觀音新生活圈的發展。\n十一、爭取機場捷運A15站航城路直接銜接國二東向道路以減輕中正東路之交通流量。\n十二、國家級重要濕地－「許厝港濕地」配合自行車連絡網及遊客服務中心，督促政府做好完善的規劃與興建。\n十三、積極爭取市區瓶頸道路打通，建構完整市區連通網。\n十四、持續爭取大竹交流道改善，國二道往青埔特區跨越中正東路二段高架道路早日完成。\n十五、積極爭取五青路往青埔特區路段拓寬。\n十六、積極爭取國際路一段新街溪順水左岸堤防道路至民族街口，分流國二道甲線至台61線車潮。\n十七、全力爭取拆遷戶提高重建補償價格，協助徵收戶早日重建家園。\n十八、督促早日完成安置街廓配地與安置住宅之興建。\n十九、爭取航空城開發區公園（公25）內建置龍樹坑路祭紀念公園及其他公園內建置寵物公園。\n二十、爭取建置社區及各路口監視系統完整化，維護社會治安、提高破案率。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf5d653e12b','pf5d653e12b','profile','2022-11-26','{"education": ["萬能科技大學、大興高級中學"], "election": "2022-local", "experience": ["桃園市議會國民黨團總召、桃園市議會第一、二屆市議員、桃園縣第17屆縣議員、大園鄉民代表會第15、", "16、18屆代表、第17屆副主席、桃園市義勇警察大園中隊中隊長、台灣更生保護會桃園分會輔導員、大園鄉槌球促進會理事長、大園鄉徐氏宗親會理事長、內海國小家長會會長、後備幹部訓練班274期"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf6c2aa658b','pf6c2aa658b','bulletin','2022-11-26','{"district_id": "tao-council-01", "elected": true, "election": "2022-local", "office": "tao_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf6c2aa658b','pf6c2aa658b','platform','2022-11-26','{"district_id": "tao-council-01", "election": "2022-local", "office": "tao_councilor", "text": "1. 爭取跨縣市工作者交通費補助金，每月1000元\n2. 爭取社會住宅符合申請者，若未中籤差額由市政府補助\n3. 爭取興建重劃區公車運輸(如中路、經國、小檜溪)\n4. 爭取符合接種年齡者全面施打子宮頸癌疫苗\n5. 爭取增加各公園的主題性，使其成為主題公園，帶動桃園觀光，提升效益\n6. 為因應捷運開通，重新檢視桃園區紅綠燈設置秒數、街距、以改善交通便利\n7. 結合在地創業青年，發展桃園觀光打造特色都市", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
