INSERT INTO "fact" VALUES('platform:2022-local:pfb84d9f2a1','pfb84d9f2a1','platform','2022-11-26','{"district_id": "tao-council-10", "election": "2022-local", "office": "tao_councilor", "text": "1.協助單親家庭改善養育、教育困境。\n2.加速親子館、共融公園興建，爭取規畫極限運動場。\n3.廣設老人安養、樂齡中心；加強獨居老人照護。\n4.尊重多元移民族群、規畫進修課程、鼓勵新移民走入社會。\n5.興建青年出租公營住宅、䧏低就業青年租屋負擔。\n6.強化技職教育、鼓勵就業進修、解決產業人才欠缺困境。\n7.督促政府逐年清運店子湖垃圾場垃圾，規畫興建環保公園。\n8.擴大檢討龍潭都市計畫，釋出可建築用地，解決高房價困境，並取得國民運動中心及轉運站、大賣場用地。\n9.打造桃園成為寵物友善城市，辦理免費寵物健檢、疫苗注射。落實動物保護法。\n10.檢討農業稻作休耕、農藥、肥料補助、紅火蟻防治政策，嘉惠農民振興農業。\n11.優化市區人行道友善行走空間、廣設停車場疏解市區交通壓力。\n12.放寬農地變更為停車場用地門檻，解決老舊社區停車問題。\n13.銅鑼圈山坡地劃出範圍：推動都市計畫、產業專區規畫，均衡地方發展。\n14.督促政府加強石門都市計畫範圍內公共設施修建、養護。解決長期空污間題。\n15.增加國道客運行駛路線及班次，提昇通勤族移動效率。\n16.加強辦理青少年球類、水、陸各項運動競賽，走出戶外，減少電腦、手機使用時間。\n17.自來水、智慧路燈普及化。電線電纜地下化，推動傳統市場現代化。\n18.提高補助辦理烹飪、講座、研習、藝文、歌舞、技藝、攝影、插花、瑜珈、旅遊等課程、強化終身學習環境。\n19.鼓勵各級學校提倡四維八德、品格教育，端正青少年中心思想，強化國家認同。\n20.打造龍潭逐步邁向科技、觀光、文化、農業、幸福、微笑、品格新市鎮。\n21.推動大石門地區成為「三坑水鄉休閒農業區」；活絡農村經濟，加速公共設施新建，吸引青農返鄉服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/03%E6%A1%83%E5%9C%92%E5%B8%82/%E6%A1%83%E5%9C%92%E5%B8%82%E7%AC%AC10%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
