INSERT INTO "fact" VALUES('platform:2022-local:p05e0ff7c92','p05e0ff7c92','platform','2022-11-26','{"district_id": "txg-council-02", "election": "2022-local", "office": "txg_councilor", "text": "一、青年友善政策\n1.落實居住正義，推動社宅四年8000戶，建立多元空間共享計畫。\n2.建立青年友善城市，推動成立青年事務局，整合資源孕育青創力。\n3.支持青年創業，成立青年創業基金，打造優質創業環境。\n二、教育優先尊重文化\n1.強化學校各項硬體設施，打造優質教學環境，提升教學品質。\n2.實踐學校特色教學，創造學童多元學習環境。\n3.推動國際、校際交流活動，開創學童視野與國際觀。\n4.落實古蹟空間再利用，連結歷史及文化資產區域，再現土地與人民的歷史。\n5.推動文化資產導覽系統，達成文化資產推廣及教育的功能。\n三、重視環保與生態\n1.因應環境氣候變遷，推動減塑政策。\n2.持續要求減碳，嚴查空污，保護地球生存環境。\n3.重視水土保持，推動成立國家自然公園。\n四、推動建設繁榮經濟\n1.推動在地特色大型共融公園，打造具有多元刺激、互動、有趣且舒適的遊戲環境。\n2.海線雙捷運，捷運藍線四年內動工，捷運橘線通過可行性評估。\n3.以輕軌連結海線沿途觀光景點，串連台中三井outlet、高美濕地、梧棲觀光漁港等景點，創造觀光產值。\n五、開創優質政治\n1.清廉參選、重視民意，積極服務。\n2.拒絕貪汙、利益勾結。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p05e0ff7c92','p05e0ff7c92','profile','2022-11-26','{"education": ["梧棲國小、梧棲國中、\n清水高中、國立中興大\n學農藝學系畢業。"], "election": "2022-local", "experience": ["第二、三屆台中市議員、立法委員\n蔡其昌辦公室主任、台中市海灣故\n事文化創意協會理事長、台中市壘\n球大聯盟協會理事長、台中縣梧棲\n鎮藝術文化協會常務理事兼總幹\n事、民主進步黨台中市黨部執行委\n員、海線社區大學、文山社大講\n師、地方文化館推動諮詢委員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
