INSERT INTO "fact" VALUES('platform:2022-local:p0db9a469b7','p0db9a469b7','platform','2022-11-26','{"district_id": "txg-council-12", "election": "2022-local", "office": "txg_councilor", "text": "一、持續捐血、做志工，推動社會善良風，帶動民代優質服務。\n二、持續堅持三不：不交際、不應酬、不包工程，全職服務、監督市府。\n三、已完成太平市民大道打通，持續打通各地巷道，改善交通。\n四、已建制全市最多路口監視器及停車場設置( 育賢路 900 格停車位)，持續爭取充電樁改善太平區治安\n及停車不足問題。\n五、持續推動路平專案整合管線施工( 已完成多數人孔蓋下地) ，以減少道路修修補補問題，以保障人民\n行的安全。\n六、已完成多處滯洪池興建，持續督促市政府改善太平區域排水，以解決強降雨淹水問題，保障市民安全。\n七、持續爭取公車候車亭興建及公車串聯讓公車族更方便。\n八、持續督促市府培訓失業勞工第二就業專長及多舉辦就業徵才活動，以改善失業勞工就業問題。\n九、推動有利民生法案及政策，爭取綠地公園設施(已完成多處公園公廁、兒童運動器械及體健設施)\n完成太平美樂地造福鄉里。\n十、持續督促市府輔導農民發展精緻農業，改善農業發展、增加農民收入，打造太平成為台中的小瑞士。\n十一、持續督促市府寬列預算，充實警察、消防及救災人員之裝備設備，以維護第一線救災值勤人員之安全。\n十二、關懷長者已完成社區活動中心修繕及改建，讓長者有休閒去處。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p0db9a469b7','p0db9a469b7','profile','2022-11-26','{"education": ["成功國小、育英國中、\n台中高工、國立空中大\n學、國立中興大學公共\n政策碩士"], "election": "2022-local", "experience": ["太平市市民代表、\n台中市後備憲兵理事長、\n台中縣議員、\n3屆市議員、\n空中大學面授講師、\n一貫道總會候補理事、\n新平國小家長會長、\n星光、和風、慈濟、佛光會會員、\n捐血38年1018次、\n廣亮慈善會95年監事、\n24968個服務案件、\n獲頒衛福部2500小時金質獎、\n獲頒市府5067小時博愛獎"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p0e846013a3','p0e846013a3','bulletin','2022-11-26','{"district_id": "txg-council-01", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p0e846013a3','p0e846013a3','platform','2022-11-26','{"district_id": "txg-council-01", "election": "2022-local", "office": "txg_councilor", "text": "1. 爭取外埔區大東里第一公墓遷葬及地目變更後建設為多功能停車場與綠美化公園或運動\n休閒中心、推動大甲美人山運動公園建設；聯結溫寮溪替代道路發展周邊生活圈，提供\n居民更多生活休閒空間。\n2. 國中小營養午餐補助，減輕家庭負擔。\n3. 爭取甲安埔區新增建公立托嬰中心及幼兒園，落實青年敢養敢生。\n4. 強化銀髮日照與居家服務、擴大共餐與健促、落實社區長照政策。\n5. 推動臨時保母托育平台、婦女平權與社會工作的推廣，媒合就業及社會安全網的落實。\n6. 爭取甲安埔區寵物公園暨設立動物專責機構，簡化行政流程處理相關流浪動物衍生問題\n。\n7. 閒置公有土地增設地下或立體停車場，解決停車空間不足，妥善運用公用空間再造，創\n造便民舒適的友善環境。\n8. 甲安埔區特定農業區改編，以利偏鄉產業發展；擴增大甲幼獅工業區，增加就業機會。\n9. 加速建置雨水下水道工程，預防氣候變遷所造成的不可抗力洪災。\n10.電路管線地下化及共同管道建置，減少管線維修與道路開挖。\n11.結合甲安埔文化觀光(大甲媽祖文化季、外埔區忘憂谷、松柏漁港觀光魚貨集散及大安媽\n祖文化園區)，促進文化觀光產業的發展，增加地方經濟效益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p0e846013a3','p0e846013a3','profile','2022-11-26','{"education": ["大甲鎮順天國小\n臺中縣立日南國中\n嶺東科技大學國際貿易科\n畢業\n嶺東技術學院企業管理系\n畢業"], "election": "2022-local", "experience": ["臺中市政府民政局專員\n臺中市大甲正勤愛心協會理事\n臺中市動物保護協會理事長\n臺中市民防大隊副大隊長\n臺中市大甲民眾服務社理事長\n外埔區青年工作會會長\n300C2區安甲獅子會會長\n臺中市體育發展基金會理事\n臺中市議員楊永昌特助"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-02T15:34:15Z');
