INSERT INTO "fact" VALUES('platform:2022-local:p132d0ba6f0','p132d0ba6f0','platform','2022-11-26','{"district_id": "txg-council-05", "election": "2022-local", "office": "txg_councilor", "text": "1.爭取打造水岸公園城市，改善城市景觀。\n2.爭取延續捷運到中清路大雅公園，民生路至豐原經神岡。\n3.爭取增設工業區用地，並加速豐洲二期及擴大神岡都市計畫產業園區推動。\n4.爭取大雅第一市場設施環境及設備改善。\n5.爭取調降房屋稅、地價稅。\n6.爭取重新調整都市計畫公設用地比例\n7.爭取大雅區六寶及忠義里、神岡區山坡地地目解編。\n8.爭取改善教學環境及設備，提升教育品質。\n9.爭取公托數量及教學品質提升，監督非營利幼兒園教學成效。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
