INSERT INTO "fact" VALUES('platform:2022-local:p374ade2a7f','p374ade2a7f','platform','2022-11-26','{"district_id": "txg-council-13", "election": "2022-local", "office": "txg_councilor", "text": "1.督促市政府提出並執行有效的後疫情振興地方經濟方案。\n2.推動社宅倍增計畫，協助青年安心成家。\n3.擴大生育補助，推動能生敢養政策。\n4.強化長照2.0能量，增設社區據點及日照中心。\n5.催生屯區環線捷運系統。\n6.擴大大里都市計畫，增加公共設施用地，改善大里生活環境。\n7.推動霧峰都市計畫，打造霧峰為綠色觀光文化城，活絡地方經濟。\n8.加速開發夏田產業園區與塗城產業園區，解決中小企業缺地問題。\n9.全面盤點大里及霧峰學校及公家閒置空間，爭取廣設停車場\n10.利用大里、霧峰河川地，開闢水岸步道及綠地公園，並設立運動休憩場。\n11.爭取大里德芳路一段(省農會至東榮路)拓寬工程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p374ade2a7f','p374ade2a7f','profile','2022-11-26','{"education": ["曉明女中\n臺中女中\n成功大學外文系\n中興大學法政碩士"], "election": "2022-local", "experience": ["日本亞細亞航空公司 空服員\n菩提醫院人事主任\n第五、七屆立委簡肇棟服務處助理\n民進黨中評委、全國黨代表\n第二屆臺中市議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p38f0e18566','p38f0e18566','bulletin','2022-11-26','{"district_id": "txg-council-07", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC07%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p38f0e18566','p38f0e18566','platform','2022-11-26','{"district_id": "txg-council-07", "election": "2022-local", "office": "txg_councilor", "text": "一、搭乘計程車敬老愛心卡單趟補助提高到一百元，並納入台鐵連線。\n二、筏子溪迎賓廊道延伸至烏日建國路橋，並增設自行車道。\n三、爭取幹線公車穿越南屯地區，特別是五權西路、向上路、公益路。\n四、爭取南屯拖吊場儘速遷移，並改建為文化圖書館及停車場。\n五、督促文中52儘快設校招生，解決文山地區學童就學之苦。\n六、積極推動南屯水肥廠優化與遷移，比照臺中肉品市場模式。\n七、早日催生南屯國際足球園區完成硬體建設，帶動地方建設繁榮，提升臺中足\n球國際水準。\n八、持續督促推動道路燙平專案及共融公園陽光公廁建設。\n九、比照班班有冷氣，督促市府向中央爭取學童營養午餐費用全額補助。\n十、督促市府積極推動共享人力及電動運具普遍化，減少碳排放，邁向永續環境。\n十一、努力爭取溝墘里活動中心早日完成，兌現市府的承諾。\n十二、中台社區大型開發日益增加，水土保持的超前佈署應落實，減低民怨。\n十三、精密機械園區附近高壓電塔應儘速完成地下化，讓周遭居民免於恐懼陰影。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC07%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
