INSERT INTO "fact" VALUES('bulletin:2022-local:p3bdea4d82b','p3bdea4d82b','bulletin','2022-11-26','{"district_id": "txg-council-13", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p3bdea4d82b','p3bdea4d82b','platform','2022-11-26','{"district_id": "txg-council-13", "election": "2022-local", "office": "txg_councilor", "text": "1.爭取機場捷運(橘線)路線自臺中國際機場起至大里霧峰。\n2.爭取台74線下平面道路霧峰段儘速完成通車。\n3.爭取霧峰區中正路與振興街打通工程，使甲寅、本鄉、本堂、中正里等民眾進出免繞道。\n3.儘速增設台74縣十九甲北出匝道，提供十九甲、大里及太平地區居民更便利的行車環境。\n4.爭取中興路一段2巷拓寬工程，有效改善大里溪南地區對外交通。\n5.爭取普遍增設「微笑單車2.0電輔車(YouBike2.0E)」讓民眾騎乘時可以更輕鬆省力。\n6.關注農產品行銷、農業和農產品相關政策，協助農民解決蟲害防治並提高農損補助。\n7.持續爭取友善共融公園，讓市民擁有更好的休閒運動空間。\n8.增加公托量能、公幼倍增計畫，提高對0-6歲嬰幼的經費補助，提升年輕人生孩子的意願，減\n輕育兒負擔。\n9.推動絕育取代撲殺，把關市府編列之相關預算，為流浪動物福祉嚴格把關。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p3bdea4d82b','p3bdea4d82b','profile','2022-11-26','{"education": ["一、亞洲大學碩士二、國立聯合大學(二專)三、臺中市光華高工四、臺中縣立成功國中五、大里鄉立塗城國小"], "election": "2022-local", "experience": ["一、大里市民代表會主席二、臺中市議會國民黨團副書記長三、啟里文教基金會董事四、大里區後備軍人輔導中心輔導組長五、國際佛光會中華總會顧問六、大里國際青商會貳零零陸年會長七、草湖國際獅子會會員八、大里國際同濟會會員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p4534422a22','p4534422a22','bulletin','2022-11-26','{"district_id": "txg-council-02", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p4534422a22','p4534422a22','platform','2022-11-26','{"district_id": "txg-council-02", "election": "2022-local", "office": "txg_councilor", "text": "●爭取「捷運藍線」延伸到清水與港區，便利海線交通，要求進度加速。\n●爭取海線第二座社會住宅在清水區興建，讓弱勢者也能「住者有其屋」。\n●推動鰲峰山整體規畫，目前公墓禁葬已4年，爭取加速公園化，擴增綠地休憩空間。\n●海線仍有五成以上公有地未妥善利用，爭取釋出活化運用，促進地方經濟繁榮。\n●公共設施保留地（學校與機關用地）檢討後，督促加速市地重劃，確實還地於民，\n使土地資源有效利用。\n●爭設觀音雕像文化園區、露營區等景觀設施，增加海線觀光景點。\n●重視長者福利，督促政府在各區遍設銀髮族照護、關懷據點；提高「假牙裝設」補\n助名額。\n●督促市府增設公托與公幼，並提高生育津貼、幼童照顧等相關補助，讓年輕人敢生\n敢養。\n●重視學童，力促市府提高學校營養午餐的品質；加速老舊校舍改建。\n●振興產業，督促市府規畫工業園區或工業用地，協助廠場合法化；並積極開發台中\n港公有土地，繁榮地方。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
