INSERT INTO "fact" VALUES('platform:2022-local:p48e6ddc8ab','p48e6ddc8ab','platform','2022-11-26','{"district_id": "txg-council-05", "election": "2022-local", "office": "txg_councilor", "text": "一、基於國際「兩公約」及誠信原則，潭雅神居民應有免於迫遷的恐懼。\n二、爭取潭雅神興建社會住宅。\n三、爭取增加潭雅神公托公幼數量，提升托育品質及設施。\n四、爭取改善各級學校教學及教室設施。\n五、爭取特殊教育學生教育友善環境，健全特教師資。\n六、爭取潭雅神兒童公園設立特色安全遊具\n七、爭取潭雅神輔導商圈成立\n八、爭取改善綠園道及潭心自行車道人車分道系統設置\n九、監督豐洲二期園區開發，盡速協議補償承租戶。\n十、監督擴大神岡都市計畫產業園區規畫及區段徵收。\n十一、爭取機場捷運延伸至豐洲科技園區\n十二、爭取推動潭子火車站周邊都更\n十三、爭取頭家路開通至昌平東七路\n十四、爭取潭興路二段拓寬\n十五、爭取動物保護經費，關切流浪犬貓問題，讓台中成為動物友善社會", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
