INSERT INTO "fact" VALUES('profile:2022-local:p4cf2ea7107','p4cf2ea7107','profile','2022-11-26','{"education": ["亞洲大學碩士、南開科\n大工管系畢、慈明高級\n中學、明道初中、塗城\n國小"], "election": "2022-local", "experience": ["臺中市議會國民黨團副書記長、教\n育文化委員會總召、大里新移民女\n性家庭關懷協會理事長、大里鄉民\n代表、大里市民代表、臺中縣議員\n全國好人好事代表、大里千禧獅子\n會會長、臺中市婦宣副大隊長、南\n開科大聯合學會長、大里區婦工會\n大里金城宮主委、體總巧固球主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC13%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
