INSERT INTO "fact" VALUES('platform:2022-local:p523ee3cc4f','p523ee3cc4f','platform','2022-11-26','{"district_id": "txg-council-06", "election": "2022-local", "office": "txg_councilor", "text": "台灣是咱的國家。\n台中市成為開放進步城市。\n1､落實居住正義，建構完善住宅政策，人人住得安心\n2､守護世代正義，環境永續；落實減碳政策，發展綠色能源\n3､獎助生育、補助養育、強化托育；育兒政策升級，確保孩子自由自主成長\n4､擴大長輩生活層面，建構樂齡好生活；國中小營養午餐免費、營養加倍；廣設長照中心、公托、親子館\n5､捷運藍線市區地下化，儘速動工；建構完整捷運路網\n6､督促市府加速開發水湳轉運中心\n7､打通市政路延伸至工業區一路；督促市府打通漢翔路、福林路，串連新市政中心、水湳、中科、台中工業區\n8､督促市府扶植新創產業，發展策略產業，創造就業機會，提升薪資所得\n9､營造人本生活，增設人行友善空間；建設共融親善公園；打造人與寵物互動、互樂環境\n10､強化治安，建構警民聯防體系，通報系統電子化，加強處理治安事件能力\n11､營造台中地方文化特色，加強國際與區域文化交流，培養學童本土觀與國際觀\n12､強化社會安全網，照顧弱勢；檢討並放寬各項福利津貼申請標準，簡化申請手續\n13､市民導向的市政監督，市民才是台中市的主人", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC06%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
