INSERT INTO "fact" VALUES('bulletin:2022-local:p5c9b9b56d3','p5c9b9b56d3','bulletin','2022-11-26','{"district_id": "txg-council-01", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p5c9b9b56d3','p5c9b9b56d3','platform','2022-11-26','{"district_id": "txg-council-01", "election": "2022-local", "office": "txg_councilor", "text": "1、 大安溪南北兩側沿岸國市共有土地整合再利用。\n2、 外埔區第一公墓已遷葬完成利用該土地新闢建設甲安埔大型公園。\n3、 大甲運動公園積極推動早日進行施設。\n4、 甲安埔附設幼兒園增加招生人數，善用現有閒置空間增設公辦民營幼兒園\n，達到幼托照護一條龍。\n5、 推動日南東一街新闢道路及黎明橋南側銜接處拓寬慢車道寬度一致。\n6、 大甲松柏漁港北側爭取合法衝浪區及戲水區。\n7、 溫寮溪育德橋連接至台61線西濱濱海快速公路。\n8、 舊大安溪橋南北兩側銜接。\n9、 大甲區第一市場新建重建。\n10、 大甲納骨塔增建。\n11、 於甲安埔地區公有地興建社會住宅。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5c9b9b56d3','p5c9b9b56d3','profile','2022-11-26','{"education": ["大華科技大學資訊管理系\n私立培元高級中學商業經\n營科\n日南國民中學"], "election": "2022-local", "experience": ["李榮鴻議員特助、中國國民黨大甲\n區黨部主委、大甲國際青年商會會\n長、救國團大甲會會長、環境保護\n促進會副理事長、大甲北區扶輪社\n社長、甲安埔廠協會理事、大台中\n青工總會副總會長、大甲青工會會\n長、日南國小家長會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC01%E9%81%B8%E5%8D%80%20.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p61b4f46026','p61b4f46026','bulletin','2022-11-26','{"district_id": "txg-council-05", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p61b4f46026','p61b4f46026','platform','2022-11-26','{"district_id": "txg-council-05", "election": "2022-local", "office": "txg_councilor", "text": "1、 潭雅神豐都市計畫已經成功整合，再積極推動潭子、大雅、神岡、豐原為台中市的副都心，\n促進均衡發展！\n2、 督促市政府65歲以上長輩健保補貼不可少，營養午餐全免費、營養加倍！\n3、 督促市政府重新整合，原縣區的交通路網。\n4、 督促市政府持續興建社會住宅，落實居住正義及育兒各項政策升級。\n5、 積極爭取潭、雅、神地區公辦日照中心及增設親子館。\n6、 積極爭取潭子區與北屯區都市計畫整合，規劃符合現代使用的公共設施用地。\n7、 積極爭取綠空廊道立體高架橋樑及橋下各項體能、遊憩、休閒設施。\n8、 督促市政府整合國道4號、環中路、環中東路高架橋下閒置空間再利用！\n9. 積極爭取專案變更北屯區敦富路、南興路、南興北三路延伸潭子區福貴路、復興路、中山路\n促進潭子區的發展！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
