INSERT INTO "fact" VALUES('profile:2022-local:p6de837bcdd','p6de837bcdd','profile','2022-11-26','{"education": ["逢甲大學土木水利工程\n與建設規劃博士。\n美國東華盛頓大學公共\n行政碩士。\n美國東華盛頓大學商業\n管理學士。\n臺中市修平技術學院。\n臺中市衛道中學。"], "election": "2022-local", "experience": ["僑光技術學院兼任助理教授。\n仁愛國小家長會長。\n中國國民黨臺中市黨部副主委。\n臺中市警友會第五辦事處主任。\n臺中市乒乓球協會理事長。\n臺中直轄市議會第一、二、三屆議\n員。\n北屯國際同濟會長。\n義消四平分隊技術顧問。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC08%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
