INSERT INTO "fact" VALUES('platform:2022-local:p76eb310762','p76eb310762','platform','2022-11-26','{"district_id": "txg-council-02", "election": "2022-local", "office": "txg_councilor", "text": "1.推動台中海線捷運路網，加速捷運藍線到台中港、機場捷運到梧棲漁港、鐵路雙軌化、海線轉運中\n心興建，建構便捷港區大眾運輸路網\n2.台中港鐵路支線觀光化，串連港區高美濕地、梧棲漁港、舶來品商圈、三井outlet、客庄觀光景點\n3.捷運車站設計融入在地特色，廣邀在地人才參與設計新車站\n4.加速海線雙港國際化，推動市鎮中心發展與台中國際機場周邊整體開發\n5.持續推動滿65歲老人、社會弱勢族群免費健保、免費裝假牙\n6.孕婦產前檢查及無痛分娩免費、0至6歲幼童育兒津貼一萬元\n7.爭取國中、國小免費營養午餐、弱勢學童免費課後輔導(單親、隔代教養家庭、低收入戶)\n8.爭取開發關連工業區二、三期，加強工廠輔導與管理\n9.推動海洋及風電產業技職教育及專長訓練，創造地方商機與就業機會\n10.爭取海線會展中心、濱海遊憩區與大型購物中心投資，促進港區經貿發展\n11.加速海線雙港國際化，推動市鎮中心發展與台中國際機場周邊整體開發\n12.持續台中市樹木保護與動物保護工作，推動大肚山、海岸濕地自然生態保育\n13.加強海線河川（南勢溪、米粉寮溝（清水大排）、梧棲大排、安良港大排、仁民中排）污染監測與\n防治工作，運用ＡＩ人工智慧提升環保查緝成效\n14.推動台中港區污水管線建置與家戶接管\n15.推動海線古蹟歷史建築活化再利用，促進觀光旅遊導覽", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p76eb310762','p76eb310762','profile','2022-11-26','{"education": ["一.逢甲大學機械與航\n空工程博士二.國立雲\n林科大工管碩士三.逢\n甲大學機械工程學系\n四.樹德工專機械工程\n科五.清水國中六.清水\n國小"], "election": "2022-local", "experience": ["一.台中市議會第一、第二、第三\n屆議員二.教育部授證助理教授三.\n逢甲大學兼任助理教授四.建國、\n南開科大兼任講師五.西寧國小志\n工、家長會長六.清水橋頭里守望\n相助隊分隊長七.民進黨全國黨代\n表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
