INSERT INTO "fact" VALUES('platform:2022-local:p7b15486e9d','p7b15486e9d','platform','2022-11-26','{"district_id": "txg-council-03", "election": "2022-local", "office": "txg_councilor", "text": "1要求市府統籌公務空間有效配置，落實公托、公幼、青銀共融專用友善環境，將\n里民活動中心正規使用。2要求全市推動「通用建設」，打造無障礙環境。3延續爭\n取學校基礎建設、教學設備提升所需的經費。4加速推動在地學校雙語教學提升學\n生語文能力。5擴充優化圖書館閱讀環境、提升館內設備全面e化。6爭取經費協助\n地方廟宇文化延續傳承。7要求擴充衛生單位的編制及業務項目內容，落實特定傳\n染病的防治措施。8增設優化全區監視系統，維護治安保障居民安全。9有效配置交\n通運具，提升偏鄉基本權益，建立龍井區東西向居民生活圈專用道路。10打造區內\n觀光特色景點，串聯旅遊環線創意行銷11爭取公設用地以多目標用途，設立運動休\n閒館。既有運動場地增設風雨球場。12配合農會推廣智慧農業、創造多元行銷，提\n升農民收入。13持續要求關聯工業區二、三期公設開發，大肚山上6里(新庄子、蔗\n廍新訂都市計畫)產業專區、及新訂烏日(溪南產業發展特定區計畫)加速設立。14\n打造龍井區山、海、行政、都會區完整友善的宜居環境。15監督台中市政府以公正\n、公開、透明的方式，持續辦理大肚山上6里(新庄子、蔗廍新訂都市計畫)。16爭\n取東海里納入都市計畫後，居民既有的權益。17完成龍井建設藍圖、連結大肚地方\n開發、加速烏日創新門戶。\n更多資訊請上FB，搜尋「林孟令-聽您命令」", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC03%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
