INSERT INTO "fact" VALUES('platform:2022-local:p8d459b0e8d','p8d459b0e8d','platform','2022-11-26','{"district_id": "txg-council-10", "election": "2022-local", "office": "txg_councilor", "text": "一、推廣設置公托公幼中心，提升公托公幼比例，解決年輕世代育兒難題。\n二、擴大青年及弱勢族群租屋補貼，以實踐居住正義。\n三、推動校園飲食教育，讓學生認識食物原形及來源，培養正確飲食習慣，\n為國民終身健康從小奠基。\n四、督促市府落實設置智慧即時交管中心，以人性科技改善交通壅塞問題。\n五、推廣都更設置公益性地下停車場，並請市府提撥部分停車費設立維護營\n運基金。\n六、推動臺中車站周邊設立電商特區。\n七、持續推動中西區都市更新。\n八、督促市府面對毒品及藥害環境衝擊問題，確實建立藥物回收機制，並於\n校園進行反毒及藥物正確回收教育。\n九、持續督促市府針對公衛以及用藥問題擴大稽查，藉以提升公衛水準、維\n護民眾健康。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
