INSERT INTO "fact" VALUES('platform:2022-local:p9b10016d53','p9b10016d53','platform','2022-11-26','{"district_id": "txg-council-08", "election": "2022-local", "office": "txg_councilor", "text": "一、持續監督廍子里太和段224、225地號興建市場(核定規劃中)\n二、持續監督北屯區兒童公園闢建地下停車場(核定規畫中)\n三、持續監督北屯區設置寵物公園(核定規劃中)\n四、持續監督梅川南、北路拓寬工程(核定規畫中)\n五、持續監督大坑里光明橋及和平里光榮橋改建(已會勘)\n六、推動全面美化人孔蓋(已提案)\n七、推動松山街往西打通至昌平東八街(已提案)\n八、推動北屯溪東地區新增派出所(已提案)\n九、推動南興公園籃球場興建風雨球場(已提案)\n十、推動制定汽柴油車占用電動充電車格處罰條例(已提案)\n十一、推動綠線捷運從延伸至大坑經補庫(多次提案)\n十二、推動敬老愛心卡搭乘台鐵區間車(多次提案)\n十三、推動重劃區普設號誌燈及監視器\n十四、推動廣設汽、機車停車格\n十五、堅持清白專職從政不包工程不收紅包不兼職不買票", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC08%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
