INSERT INTO "fact" VALUES('platform:2022-local:pb0896ad0d6','pb0896ad0d6','platform','2022-11-26','{"district_id": "txg-council-12", "election": "2022-local", "office": "txg_councilor", "text": "1.推動太平區新聯合行政中心設立完成。爭取小孩國家養，推動國中小營養午餐免費以降低家長壓力並提高生育意願。\n2.爭取建設捷運，由捷運綠線向北延伸至大坑，再由藍線向東延伸至大里、太平。\n3.加速推動台74線銜接國一交流道，及增設十九甲、六順橋和草湖閘道，以解決台74線壅塞問題。\n4.推動托育一條龍升級，增加嬰幼兒福利，並爭取公幼、公托及非營利幼兒園增設。\n5.提升老人福利。如：敬老愛心卡使用範圍增加、長照政策推動、社區據點推動、老人共學延緩老化、長青學苑增設。\n6.推動市民及親子空間設立，公園綠地普及化、公園塑膠致癌遊具逐步退場、閒置公共空間活化。\n7.爭取太平公共停車空間，解決停車問題。爭取育賢路停車場與建立體、中興停車場加蓋以增加停車空間。\n8.協助解決工業用地不足問題並推動產業健檢，協助夕陽產業轉型。\n9.持續推動「農產品產銷失衡救助基金」，擴大預算規模以降低產銷失衡，並救助經濟農產品產業，確實照顧農民。\n10.持續爭取設置監視錄影設備及建立聯防預警系統，提高破案率，有效嚇阻犯罪行為發生，還給人民免於恐懼的生活。\n11.推動太平市民大道南段（宜文街銜接至台中小鎮永富街）都市計畫恢復及爭取施作，解決太平南北向道路壅塞問題。\n12.太平環太東路銜接東平路777巷一路接至甲提路等堤防道路貫通，來解決東西向橫跨北屯、太平、大里等交通路網。\n13.持續監督市府實施治水防災計畫，並推動南太平光興路設置地下雨水道，銜接滯洪池。降低急降雨造成淹水機會。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
