INSERT INTO "fact" VALUES('profile:2022-local:pb7c3e560be','pb7c3e560be','profile','2022-11-26','{"education": ["太平國小\n中平國中\n台南女子技術學院音樂\n系\n亞洲大學管理學碩士"], "election": "2022-local", "experience": ["台中市議員李麗華服務處 主任\n台中市體育總會健行登山委員會\n主任委員\n社團法人台中市活力社區關懷協會\n副總幹事\n黃復興黃安地黨部 小組長\n台中市太平區體育會跆拳道委員會\n主任委員\n中國國民黨太平區青工會 會長\n慈濟、合濟、星光、廣亮、福田等\n會員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pb9f15b697d','pb9f15b697d','bulletin','2022-11-26','{"district_id": "txg-council-12", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pb9f15b697d','pb9f15b697d','platform','2022-11-26','{"district_id": "txg-council-12", "election": "2022-local", "office": "txg_councilor", "text": "1. 持續推動太平區閒置公共空間增設公設民營托嬰中心、社區公共家園、親子館，滿足新手爸媽就近托嬰需求。\n2. 持續增設公共化幼兒園並增設2歲專班，提供優質教保服務，讓小資家庭家長安心就業。\n3. 持續追蹤太平區聯合行政中心興建進度，示範綠建築，帶動區域繁榮。\n4. 持續推動屯區環線大平霧捷運計畫、捷運藍線延伸太平區，導引區域均衡發展、屯區市區化\n5. 持續促成太平區市民大道三期興建工程，規劃「南太平延伸段」健全路網，促進南太平便捷繁榮。\n6. 持續推動太平坪林地區辦理擴大都市計畫，擴大市區發展核心，釋出軍方太平區土地，完善公共設施，提升生活環境\n品質。\n7. 爭取新訂太平光興隆地區為擴大都市計畫區域，有秩序讓南太平都市發展能適地適用。\n8. 爭取依「都市計畫法」劃定太平頭汴坑風景特定區，發展多元山岳遊憩旅遊，推動低海拔山區觀光，協助青年返鄉就\n業。\n9. 爭取國中小學營養午餐免費、營養加倍，落實「食農教育法」，吃當季、食在地、惜食，符合生態永續的飲食生活。\n10. 爭取社宅倍增四年八千，落實居住正義；新設青年事務局輔導年輕人就業、創業、職涯發展、公共參與，陪伴青年自\n我實現。\n11. 推動整合市政府相關新住民的局處資源，建構教育文化、進修就業、福利救助……等單一窗口，建構新住民友善環境。\n12. 荔枝樁象結合產官學採取綜合防治，全方位、全區防治，導引農民學習新觀念、新技術及補助資材，友善從農環境。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pb9f15b697d','pb9f15b697d','profile','2022-11-26','{"education": ["1東汴國小。2太平國中。\n3慈明高中。\n4勤益科技大學二專。\n5建國科技大學。\n6國立中興大學碩士。"], "election": "2022-local", "experience": ["1台中市第二、三屆市議員。2民進\n黨台中市黨部執行委員、黨代表。\n3立法委員蔡其昌市政辦公室秘書。\n4立法委員何欣純助理。5立法委員\n簡肇棟助理。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC12%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
