INSERT INTO "fact" VALUES('profile:2022-local:pc23c7f41f1','pc23c7f41f1','profile','2022-11-26','{"education": ["中興大學農業企業經營\n管理碩士\n東海大學公共事務碩士"], "election": "2022-local", "experience": ["第1.2.3屆臺中市議員\n第16屆台中縣議員\n民主進步黨中央評議委員\n台中縣政府機要秘書\n行政院機要秘書\n台中市軟式網球委員會主委\n台中市棒球委員會副主委\n豐原區羽球委員會主委\n台中市台南同鄉會會長\n豐東國中、南陽國小會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC04%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
