INSERT INTO "fact" VALUES('platform:2022-local:pc33bbdf232','pc33bbdf232','platform','2022-11-26','{"district_id": "txg-council-09", "election": "2022-local", "office": "txg_councilor", "text": "1.北區肉品市場原址推動規劃：主題公園、社會住宅、商場。\n2.台中市交通號誌全面盤查，創造友善行的空間。\n3.增加第三胎生育津貼並保障優先入學(公托公幼)。\n4.推動特色主題公園之建置。\n5.調降社會住宅租金，並提高租屋族租金補助。\n6.爭取捷運通勤族月票優惠。\n7.改善公車重疊路線，有效減少公車搭乘時間。\n8.亞健康長輩陪伴照護資源爭取及完善長青學苑規劃。\n9.民政局增設專屬新住民業務科。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC09%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc33bbdf232','pc33bbdf232','profile','2022-11-26','{"education": ["雲林縣北港鎮南陽國小\n北港國中\n省立東石高中\n修平技術學院資管系畢\n逢甲大學公共政策研究\n所畢"], "election": "2022-local", "experience": ["陳有江市議員服務處主任十八年\n第三屆臺中市議會國民黨團書記長\n中華民國童子軍木章資格\n臺中市義警北區中隊中隊長\n後備軍人北區輔導中心主任\n盲人福利協進會顧問\n總工會顧問\n藥師公會顧問\n醫事放射師公會顧問\n幼兒教育暨福利協會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC09%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
