INSERT INTO "fact" VALUES('platform:2022-local:pcfbb6f7ae5','pcfbb6f7ae5','platform','2022-11-26','{"district_id": "txg-council-04", "election": "2022-local", "office": "txg_councilor", "text": "一、 督促市府.加強蓋社會住宅\n二、 督促市府.多蓋運動場所(籃球場、羽球場、網球場、直排輪等)\n三、 爭取各大小公園廣設成人健身器材、兒童遊樂設施\n四、 督促市府落實老人長照及幼兒托育政策，提高生育津貼\n五、 爭取敬老愛心卡能連結各種交通工具(台鐵、高鐵...等)\n六、 針對高速公路或平面道路易塞車路段，督促市府積極爭取中央協助解決\n七、 重視學童營養午餐品質，加強幼童照顧措施", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC04%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
