INSERT INTO "fact" VALUES('platform:2022-local:pdb99f46393','pdb99f46393','platform','2022-11-26','{"district_id": "txg-council-06", "election": "2022-local", "office": "txg_councilor", "text": "1. 保障幼兒福利補助，落實公托、公幼倍增；成功爭取西屯第一座親子館及大\n公托。\n2. 確保各級校園軟、硬體設施完善，落實教育建設預算優先補助校園。\n3. 鼓勵青年回鄉就業輔導，增加在地創業補助，設立青年局保障青年權益。\n4. 成立新住民科，協助新住民融入在地風俗習慣及生活。\n5. 堅持落實老人長照工作，督促社區老人照護及老人日托體系完成。\n6. 協助婦女就業及建置婦幼安全網，保護受虐兒及遭家暴婦女。\n7. 堅持保護家園有效遏止空污，強力監督中火發電各項違失。\n8. 敦促水湳經貿園區各項建設開發進度，儘速完成以造福鄉里。\n9. 重視治安維護，增設監視系統，加強警民連線，聯防社區安全。\n10. 改善老舊公園設施，推動共融式遊樂場、讓「玩」變成大家的權利。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC06%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
