INSERT INTO "fact" VALUES('bulletin:2022-local:pe2d169d28b','pe2d169d28b','bulletin','2022-11-26','{"district_id": "txg-council-07", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC07%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe2d169d28b','pe2d169d28b','platform','2022-11-26','{"district_id": "txg-council-07", "election": "2022-local", "office": "txg_councilor", "text": "2018年以九票差距落選，四年來持續揭弊、打擊不公義。 我是吳佩芸，過去與未來堅持走在改革路上！\n交通拚改革 路要平、市民用路更安心\n1. 監督路平品質，改善永春（東）路、黎明路等重要道路之平整，防止龜裂破損，保障市民行車安全。\n2. 全面體檢道路標線，改善路口人車分流設計。 3. 盤點公有閒置空地，增設停車空間，停車資訊電子化。\n友善幼托 防範虐童再發生 充足南屯教育資源\n1. 落實訪視輔導及評鑑，淘汰違法業者，資訊揭露公開透明。 2. 檢視南屯區國小閒置空間，增設公幼公托。\n3. 嚴格監督南屯溪西地區新設國中期程與規劃，保障當地學童就學權益，並持續爭取足夠的教育資源。\n藥有專業 把關健康我最行！\n1. 推廣藥師專業，完善社區照護。 2. 重視醫療人員之基本權益，落實醫藥分業，保障基層勞動條件。\n嚴防空汙 守護你我環境\n1. 督促文山焚化爐加速轉型、減少排放量，要求資訊、進度公開，定期執行健康風險評估。\n2. 監督市府落實管制各項空氣污染源排放，明訂中火、中龍鋼鐵及排污工廠減排時程。\n3. 提升南屯污水下水道接管率，讓工業區污水處理廠協助接手水肥處理，停用南屯水肥廠。\n居住正義 宜居城市 監督社宅不跳票\n1. 拒絕市府不當賣地賺錢、圖利建商，落實社會住宅興建。 2. 推廣特色兒童遊戲場，共融遊具合格零風險。\n議會革新 勇敢揭弊 打擊不公義！\n1. 開放議會，擴大公民參與，促進資訊透明化，議會紀錄即時公開上網。\n2. 定時公布助理費流向，杜絕詐領助理費。 3. 去除議員特權歪風，杜絕關說壓迫行為。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC07%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe2d169d28b','pe2d169d28b','profile','2022-11-26','{"education": ["中國醫藥大學藥學系學士\n曉明女子高級中學"], "election": "2022-local", "experience": ["時代力量臺中黨部副執行長\n時代力量秘書長暨發言人\n臺中榮民總醫院藥師\n臺北市立萬芳醫院藥師\n南屯國民運動中心有氧老師\n健身工廠有氧老師\n中國醫藥大學第十九屆學生自治會\n會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC07%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
