INSERT INTO "fact" VALUES('profile:2022-local:peb9379450b','peb9379450b','profile','2022-11-26','{"education": ["亞洲大學經營管理學系\n碩士、弘光科技大學護\n理系"], "election": "2022-local", "experience": ["1、中山醫學美容專班2、79年度公務人員普考及格3、94年度就業服務專業人員合格。4、中國醫藥學院急診護理師。5、署立豐原醫院護理師。6、臺中市烏日區溪南國中幹事(80~82年)。7、第十七屆烏日鄉民代表會代表。8、第十六屆臺中縣議會議員。9、臺中市議會第一、二、三屆直轄市議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC03%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf114d7f539','pf114d7f539','bulletin','2022-11-26','{"district_id": "txg-council-05", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf114d7f539','pf114d7f539','platform','2022-11-26','{"district_id": "txg-council-05", "election": "2022-local", "office": "txg_councilor", "text": "朝國從參政開始【堅持對鄉親的承諾】\n腳踏實地一步一腳印；不敢懈怠，大台中升格直轄市後帶動整個潭雅神的進步，朝國深耕地方；\n全職在地服務，有許多重要的地方建設還未完成，未來的四年讓朝國繼續來替鄉親打拚。\n1、爭取鐵路潭子段高架下設置停車場。\n2、爭取潭子區第二產業園區。\n3、督促國道四號延伸潭子74號線早日完工。\n4、督促74號快速道路高架銜接國道一號早日完工。\n5、推動地方精緻農業，活絡地方經濟產業推廣。\n6、推動社區醫療團隊照顧社區老、婦、幼保建工作\n7、爭取潭子區內國小雙語教學資源平均分配。\n8、爭取潭子區設置親子館及老人日間托老中心。\n9、爭取生育、育兒津貼(就學)補助，改善少子化問題。\n10、爭取為弱勢團體發聲謀福利；爭取更完善的照顧。\n11、協助勞工、青年夫婦安心就業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf114d7f539','pf114d7f539','profile','2022-11-26','{"education": ["潭子區新興國小畢業。\n潭子區潭子國中畢業。\n育民高級職業學校畢業。"], "election": "2022-local", "experience": ["潭子區第17屆鄉民代表。\n台中縣第16屆縣議員。\n潭子鄉民眾服務社理事長。\n潭子區朝國慈善協會創會理事長。\n中國國民黨潭子區黨部95~97年主\n委。\n大台中直轄市第一~三屆市議員。\n大台中直轄市第一屆市議會副書記\n長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC05%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf17204b4f6','pf17204b4f6','bulletin','2022-11-26','{"district_id": "txg-council-02", "elected": true, "election": "2022-local", "office": "txg_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf17204b4f6','pf17204b4f6','platform','2022-11-26','{"district_id": "txg-council-02", "election": "2022-local", "office": "txg_councilor", "text": "一、【爭取設置海線寵物公園】\n爭取大小犬分離的運動區域，設置跳躍跨欄、隧道水泥管、棧橋、遮陽和避雨設施等設施。\n二、【AI系統確實在高中職端落實】\n(一)在人才培育方面規劃AI教育向下扎根 (二)實際動手操作，進一步了解人工智慧\n三、【協助海線南山截水溝計畫第三期推動】\n協助推動南山截水溝計畫3期，造福約1萬9000人，以解水患之苦。\n四、【督促捷運藍線跨黨派推動小組，儘速啟動徵收與開工作業】\n儘速成立「台中市捷運推動小組」，共同攜手合作，推動台中捷運藍線動工。\n五、【港務回饋金專款專用於台中港區】\n將落實了解各區分配額度及使用情形，並爭取港務回饋金專款專用於台中港區。\n六、【梧棲大村里、大庄里及永寧里、永安里、興農里等二里三里多功能聯合活動中心經費到位，\n督促儘速動工】\n經費亦到位，督促儘速興建運動休閒設施及里民活動中心，促進地方發展。\n七、【慢飛天使資源不能停】\n未來將督促市府在早療天使政策推動，未來能更加周全。\n八、【爭取梧棲新行政中心 便利民眾洽公促進地方繁榮】\n梧棲區公所為為四十年老舊建物，辦公、停車空間都不足,將爭取梧棲新行政中心。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/04%E8%87%BA%E4%B8%AD%E5%B8%82/%E8%87%BA%E4%B8%AD%E5%B8%82%E7%AC%AC02%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
