INSERT INTO "fact" VALUES('bulletin:2022-local:p053f357afa','p053f357afa','bulletin','2022-11-26','{"district_id": "tnn-council-01", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p053f357afa','p053f357afa','platform','2022-11-26','{"district_id": "tnn-council-01", "election": "2022-local", "office": "tnn_councilor", "text": "1. 爭取推動中山高速公路新營交流道北上出口改善工程，解決交通瓶頸問題。\n2. 爭取新營區新東里設置立體停車場，解決停車問題。3. 爭取柳營科學園區。\n4. 爭取 65 歲以上老人健保全額補助，並推動偏鄉醫療接送專車。5. 重陽敬老金\n比照其他五都提高至一千五百元，並依年齡累進增加。6. 爭取市府編列「成家基\n金」，提供新婚夫妻低利貸款，婚後 3 年生育子女可免繳利息，6 年生 2 胎減\n免3 0％貸款償還，10 年生 3 胎可免償還，以提高年輕人婚育意願。7. 國中小學\n生營養午餐免費。8. 爭取辦理嘉南大圳新營分線（新東國中旁至長榮路橋分期分\n段施工）渠道改建，完成新營區藍綠軸帶人行步道建設。9. 持續爭取新營區長榮\n路以北、以西農地變更為商業住宅用地。10. 爭取市府廣設社區型監視系統，保\n障人民生命財產安全。11. 爭取活化台糖新營總廠土地，帶動親子休閒與觀光旅\n遊。12. 持續爭取推動東山區黑曜金咖啡公路優質化工程。13. 爭取鹽水月津港訂\n為國家級燈會永久場址，串連新營天鵝湖、後壁小南海、柳營德元埤等推動水上\n遊樂運動設施，帶動觀光發展。14. 爭取台灣蘭花生物科技園區擴大，增加就業\n機會。15. 爭取白河交流道到關子嶺風景區公路擴寬，以利觀光。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p053f357afa','p053f357afa','profile','2022-11-26','{"education": ["新營國小、新東國中、臺南\n二中、興國中學、文化大學\n法律系學士、中正大學政治\n研究所碩士。"], "election": "2022-local", "experience": ["國立中正大學政治所博碩\n班受邀講座、科技部南部\n科學工業園區管理局第二\n屆勞資爭議調解委員、北\n臺南家扶中心扶幼委員、\n救國團南市指導委員、紅\n十字會臺南縣支會理事、\n臺南縣總工會常務監事、\n臺南縣15、16屆議員、臺\n南市1、2、3屆議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
