INSERT INTO "fact" VALUES('profile:2022-local:p0b2f4ae4bb','p0b2f4ae4bb','profile','2022-11-26','{"education": ["國立臺灣大學政治學系學士\n國立中山大學政治學研究所\n碩士"], "election": "2022-local", "experience": ["立法委員郭國文服務處執\n行長\n臺南市長賴清德辦公室秘\n書\n民主進步黨第18屆全國黨\n代表\n市議員郭國文服務處助理\n國立臺南藝術大學兼任講\n師\n崑山科技大學兼任講師\n國立高雄師範大學兼任講\n師"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%83%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p2a6efe5b42','p2a6efe5b42','bulletin','2022-11-26','{"district_id": "tnn-council-05", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p2a6efe5b42','p2a6efe5b42','platform','2022-11-26','{"district_id": "tnn-council-05", "election": "2022-local", "office": "tnn_councilor", "text": "1 爭取加速建置公共托嬰中心，讓育兒更輕鬆，托嬰更安心，公共托嬰不再抽籤一位難\n求。\n2 爭取112年起於三年內完成65歲以上長者健保費全額補助。\n3 爭取於各行政區，加速建造社會住宅，讓年輕人居住更安心，成家更輕鬆。\n4 督促加速南科（善化、新市）-新化-高鐵捷運（深綠線）路線規劃，並於臺南市先進\n運輸系統中優先建置本路線。\n5 督促鐵路立體化北延工程：永康-新市-善化儘速完成規劃建置。\n6 爭取建造南科地區大型醫療機構，提昇南科區域居民醫療品質。\n7 檢討善化、新化、新市高密度住宅區停車場空間，規劃建造合適停車場（塔），讓居\n家停車更便利。\n8 提案檢討新化、山上、新市、善化、安定區，都市計劃範圍規劃合理性，加速南科生\n活圈都會化。\n9 推動農地使用多功能化，強化農業用地輔導取代罰款處分措施。\n10推動制訂交通違規處分行政規則，讓市民安心上路，遵守交通規則，免受取締處分。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
