INSERT INTO "fact" VALUES('platform:2022-local:p2b1524aa5e','p2b1524aa5e','platform','2022-11-26','{"district_id": "tnn-council-06", "election": "2022-local", "office": "tnn_councilor", "text": "一、 整治現有溪道，美綠化兩岸為都會親水公園，做為\n居民休憩場所。\n二、 爭取公立小學增設公托幼兒場所，以減輕年青家長\n負擔，提升年青人生育意願。\n三、 督促加速污、雨、水道施作進度，以利徹底解決\n安南區水患。\n四、 建請市府統籌產、經、學、推廣安南區精緻農、漁\n業發展，提升農漁民經濟附加價值。\n五、 力促安南區外塭屠宰場之遷移，以利該區域之整體\n發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
