INSERT INTO "fact" VALUES('platform:2022-local:p31246e4e9a','p31246e4e9a','platform','2022-11-26','{"district_id": "tnn-council-02", "election": "2022-local", "office": "tnn_councilor", "text": "1. 嚴格審查市府預算，確實監督施政成效；秉持家婆認真精神，爭取市民福祉。\n2. 賡續建設佳里區第二聯合活動中心、七股區三股活動中心，將軍區扇形鹽田觀景台、舊馬沙溝漁港再\n造，學甲區糖鐵綠美化往山寮延續，擴寬七股區176線往雷達站及西港往南科保西橋道路等工程。\n3. 極力爭取大北門藝文中心在佳里，新建七股區大寮景觀公園、內含室內體育館室，新建西港綠川廊道\n第五期綠美化；厚植民眾文化涵養，完善青少年活動空間，提升市民休閒品質。\n4. 整體規劃大北門區域發展，儘速啟動七股工業區，強化佳里、西港、學甲工業區基礎建設，增加就業\n機會、促進經濟發展。\n5. 照顧勞工權益，新建社會住宅，增加幼兒津貼，提高租屋補助；以減輕年輕人負擔，厚植國家生產力\n及競爭力。\n6. 落實社福政策，加強長照2.0服務網；輔導新住民就養，關懷高風險家庭及弱勢族群；推行偏鄉醫療\n服務，照顧銀髮族群就醫就養。\n7. 完善保母及托育品質，改善學校設施及教育設備；加速偏鄉小校轉型整合，落實資源分享。\n8. 消防、警政員額編制確實，充實救災設備，完整教育訓練，確保人員安全；嚴格取締毒品、槍枝，保\n障人民生命財產安全。\n9. 重視農漁牧業基礎建設，推動年輕族群返鄉參與；建立相關產品產銷平台，輔導自主產品開發、販\n售，增加農漁牧業收益。\n10. 支持低碳永續之生活理念，綠色環保愛地球；強化區域排水系統，建置抽水站，溝渠定期整治疏通。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
