INSERT INTO "fact" VALUES('bulletin:2022-local:p366135182a','p366135182a','bulletin','2022-11-26','{"district_id": "tnn-council-01", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p366135182a','p366135182a','platform','2022-11-26','{"district_id": "tnn-council-01", "election": "2022-local", "office": "tnn_councilor", "text": "1.打造科技發展重鎮\n串連嘉科南科爭取新營設立都市型科學園區納入南部科學發展S型廊帶。\n2.積極發展交通建設\n持續爭取新營火車站前後站周遭倉庫土地活化/新營交流道增設匝道，重塑新營東西向聯外交通，找回臺南門面的驕傲。\n3.加強社會福利關懷\n爭取65歲以上長者免健保費/鑽石婚慰問金，減輕青年照顧家中長輩的負擔。\n4.保存珍貴文化遺產\n爭取鹽水月津港景觀橋重新打造，讓昔日媽祖入港民俗再現。\n5.關注基本民生議題\n持續爭取東山白河山區自來水供給普及。\n6.文創結合農業產業\n挹注文創量能活化白河蓮花節及蓮花產業，打造白河農業品牌。\n7.再創臺南蘭花驕傲\n後壁蘭花園區今年開始由中央接管，未來爭取園區及活動內容升級，打造國家級蘭花產業專區。\n8.打造親水水域空間\n臺南擁有非常豐富的水域資源應多加利用，未來持續爭取柳營德元埤荷蘭村、新營天鵝湖、鹽水月津港，增加水域活動，打造\n親水安全空間。\n9.持續爭取活化糖廠\n新營糖廠位居新營中心地帶，長期閒置對於新營地區發展造成阻礙，未來也會持續爭取糖廠活化，帶動溪北整體發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
