INSERT INTO "fact" VALUES('platform:2022-local:p65b3509caa','p65b3509caa','platform','2022-11-26','{"district_id": "tnn-council-07", "election": "2022-local", "office": "tnn_councilor", "text": "1. 爭取永康區正南三路高架化﹐從康橋大道平交道為起點往北銜接台一\n線與鹽水溪北外環道﹐徹底解決鹽行地區的交通讓要上高速公路的車\n子更順暢。\n2. 大灣交流道改善案﹐北上引道往北延伸能容納更多北上車流﹐才不會\n回堵在交流道口。\n3. 次10-5號15米計畫道路從國光五街往高速公路便道已要開闢了﹐應打\n通往復華三街更能產生更大的效益，以減輕大灣交流道流量。\n4. 爭取大型羽毛球場館，以利舉辦大型比賽(場地至少10面以上)，因羽\n球已是全民運動了。\n5. 督促市府社會住宅目標數量務必達標﹐以利無殼蝸牛的居住正義並普\n級化。\n6. 全市警力分配率，應重新檢討，配備更新，以降低人民受害，提高社\n會安定，百姓安居樂業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%83%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p65b3509caa','p65b3509caa','profile','2022-11-26','{"education": ["崑山科技大學企業管理研究\n所碩士，崑山中學，永康國\n小。"], "election": "2022-local", "experience": ["台南縣第十六屆議會議員，永康市第三屆市民代表，永康市農會第十四屆農會代表，大灣廣護宮第", "十七、二十一屆董監事會董事長，大灣國民小學家長會八十一年會長（三屆），永康國際青年商會１９９２年會長，台南市網球協會副主任委員，大灣消防隊義消顧問，台南市議會第二、三屆市議員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%83%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p668e9dc01a','p668e9dc01a','bulletin','2022-11-26','{"district_id": "tnn-council-11", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p668e9dc01a','p668e9dc01a','platform','2022-11-26','{"district_id": "tnn-council-11", "election": "2022-local", "office": "tnn_councilor", "text": "我全力推動新豐區的建設，長期關心弱勢團體以及獨居老人，輔導弱勢孩童英文以及為婦女團體發聲，注重社會安\n全，重視地方產業及觀光發展未來我會加倍爭取新豐區各鄰里基礎建設改善，如道路重鋪、水溝排水改善、交通號\n誌改善，以及擴大爭取特色公園等。\n我會持續爭取以下建設：\n■爭取設立新豐區國民運動中心、關廟風雨球場。\n■緊盯沙崙區域醫院成立與相關進程，提升新豐區市民醫療品質。\n■緊盯捷運藍線規劃，要求市府加速辦理推動。\n■增加新豐區公車接駁站、Tbike站、長照喘息服務的落實。\n■活化86橋下空間，建置特色公園，汰換罐頭遊具設施，持續打造共融式公園。\n■在地傳統市場再生，環境及設施改善，推動青年返鄉就業\n■全面提升校園安全，補足校園警衛經費，並防堵毒品污染校園，加強宣導18歲以下禁菸(含電子菸)之健康觀念。\n■爭取增加重要路口監視器數量，確保交通及社區安全。\n■平衡南北歸仁發展，堅持保留在地文化，爭取活化社區老宅帶動觀光。\n■持續爭取市府擴大辦理「登月計畫」(拒絕月經貧窮)。\n■爭取活化現有社區活動中心、加碼補助共餐活動餐費，愛心不間斷。\n■擴大辦理老人健保補助，逐年編列預算，逐年放寬年齡限制。\n■建置關廟婦女親子館，增加婦女、親子活動場域，促進二性平權。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p668e9dc01a','p668e9dc01a','profile','2022-11-26','{"education": ["加州美國大學碩士\n私立長榮女子高級中學\n歸仁國中\n保西國小"], "election": "2022-local", "experience": ["●現任台南市議員 第3屆議員", "●（聯合太平洋工業公司）", "●美國大同公司跟美商HP惠普公司商業夥伴", "●新麗企業股份有限公司（股票上市公司）：國外業務經理", "●聖藍科技股份有限公司（國內最大民營鋼鐵集團 義聯集團所轉投資）：國外業務經理"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p7093adff2e','p7093adff2e','bulletin','2022-11-26','{"district_id": "tnn-council-06", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p7093adff2e','p7093adff2e','platform','2022-11-26','{"district_id": "tnn-council-06", "election": "2022-local", "office": "tnn_councilor", "text": "01. 持續爭取排水整治工程經費，以改善安南區在強降雨後淹水情形。\n02. 爭取65歲以上老人健保福利津貼全額補助，比照其他五都、採有條件排富。\n03. 因應外來人口移入重劃區，督促重劃區內民生建設進度，增加道路開闢，以求一併帶動地區繁榮。\n04. 安南區人口遞增，為地方治安，同時不加重警察勤務負擔，力爭市府補足員警編制，讓警民比同時維持\n平衡。\n05. 為促進產業發展，協助工業區廠商與市府溝通，改善園區內交通及道路等基礎建設，提升百姓就業機\n會。\n06. 爭取編列鄰長事務費比照六都實施，以符合公平正義。\n07. 為農漁民福祉發聲，農漁道路持續鋪設及維護，並督促市府做好穩定價格等相關措施。\n08. 注重民眾精神生活，爭取安南圖書館增加館藏，讓內部閱覽空間相關設施更舒適完善。\n09. 持續監督市府就天馬電台自2013年完成遷移後，原基地的開發招商進度。\n10. 關注國中小各學校特色，加強本土教育，融入傳統技藝，深植環境保育愛地球觀念，健全學生德智體群\n美均衡發展。\n11. 爭取安南區增加興建國民住宅，抑制房價高漲，讓百姓能有購屋期待。\n12. 爭取中央動漫博物館，落腳安南區台灣歷史博館園區。\n13. 爭取警察、消防、義警、義消、義交人員等裝備防護安全提升，以保護執勤救災時生命安全保障。\n14. 監督城西焚化爐運作，妥善營運狀況及地方回饋措施。\n15. 監督政府兌現各項婦幼津貼、幼兒教育等補助及長照施行政策，落實社會福利以照護百姓。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
