INSERT INTO "fact" VALUES('platform:2022-local:p7d35e68b0a','p7d35e68b0a','platform','2022-11-26','{"district_id": "tnn-council-07", "election": "2022-local", "office": "tnn_councilor", "text": "支持18歲公民權修憲案\n爭取提高生育補助及育兒津貼\n爭取65歲以上長者免繳健保費\n補足警消人員編制，強化社區安全網絡\n捍衛年青人權益，促設市府青年局\n加速推動永康全民運動中心\n加速推動永康鐵路地下化、以利改善交通\n加速推動永康區社會住宅進度、落實居住正義\n捍衛勞工權益，落實弱勢族群保障\n優化地方產業，增加在地就業機會", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%83%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p81ed4e72fb','p81ed4e72fb','bulletin','2022-11-26','{"district_id": "tnn-council-06", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p81ed4e72fb','p81ed4e72fb','platform','2022-11-26','{"district_id": "tnn-council-06", "election": "2022-local", "office": "tnn_councilor", "text": "一、打造宜居安南：遊子返南！定居樂業！年輕城鄉！翻轉安南區！\n二、推動「便捷交通網」，發展安南區大眾捷運系統：\n1. 「安南直達專車」：往返直達沙崙高鐵站、南科。\n2. 「護長顧學公車」：長者照護專車、學生通學專車。\n3. 「綠色交通佈點」：爭取共享電動機車進入安南區。\n三、產業品牌化發展，共創永續家園：\n1. 「製鞋產業優化」：爭取全國鞋展在台南舉辦，催生「鞋藝創新據點」，向下扎根並推廣製鞋職人精神，推進台南鞋業為世界級精\n品的目標努力。\n2. 「農漁產業升級」：推動智慧漁業，促進養殖產業升級與提高產值，爭取延伸冷鏈公共建設、加強產銷調節能力，有效改善及提升\n農漁民生活品質，改善地方投資環境、實現區域均衡發展。\n3. 「特色商圈營造」：打造安南區專屬的特色商圈，帶動安南區商業經濟發展，使安南區生活機能更加完善。\n四、衡量市府財政狀況，爭取逐步增加65歲以上年長者之健保費至全額補助、提高各項老年醫療補助。\n五、爭取增設安南區特色公園以及溪畔休閒空間。\n六、減輕房租、買房經濟壓力，並確保住宅消防安全。\n七、長期耕耘基層運動隊伍，呼應112年台南全運會：\n1. 「提高奪牌獎金」：參加全運會、全中運選手的奪牌獎金增加。\n2. 「導入運動科學」：強化基層運動隊伍訓練品質，以運動科學為基礎，提供運動傷害防護員、物理治療師、專業體能訓練等，照顧\n基層選手的身體。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p81ed4e72fb','p81ed4e72fb','profile','2022-11-26','{"education": ["台南女子技術學院附設專科\n部五年制\n（現為台南應用科技大學）\n成功大學政治經濟研究所碩\n士"], "election": "2022-local", "experience": ["民進黨台南市黨部顏純左\n主委 特助\n民進黨台南市黨部黃先柱\n主委 執行長\n民進黨台南市黨部潘新傳\n主委 執行長\n2018黃偉哲市長競選總部\n發言人\n2020蔡英文競選總部執行\n總幹事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p8ce5863792','p8ce5863792','bulletin','2022-11-26','{"district_id": "tnn-council-11", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p8ce5863792','p8ce5863792','platform','2022-11-26','{"district_id": "tnn-council-11", "election": "2022-local", "office": "tnn_councilor", "text": "持續督促市府從「水利交通」、「行政經濟」、「醫療衛生」、「知識教育」等四大面向，讓府城古都的未來發展\n邁向智慧型的創新與活力。\n一、水利交通\n（一）完成開闢德糖路通往奇美博物館。\n（二）完成開闢高發三路通往高鐵站區。\n（三）加速開闢台86線東西向龍崎延伸至內門。\n（四）爭取開闢仁德勝利路通往文華路並持續督促三爺溪及港尾溝整治工程。\n（五）爭取文賢消防隊、德南派出所遷建至仁德區崑崙路。\n二、行政經濟\n（一）關廟果菜市場，回歸地方使用。\n（二）推動高鐵站區之會展中心辦展、參展、舉辦會議、商務等，帶動台南經濟發展，提升國際城市的競爭力。\n（三）推動開發港墘段綠能產業園區，創造地方與產業雙贏。\n三、醫療衛生\n（一）推動高鐵站區設置成大醫院造福偏鄉地區。\n（二）推動規劃健康園區、醫療中心。\n四、知識教育\n（一）爭取公立學校設置附屬幼兒園。\n（二）關心學童教育，推動雙語學校。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
