INSERT INTO "fact" VALUES('profile:2022-local:p8f6be5dfb4','p8f6be5dfb4','profile','2022-11-26','{"education": ["崇學國小畢業\n崇明國中畢業\n長榮中學畢業\n澳洲昆士蘭大學飯店管理學\n系畢業"], "election": "2022-local", "experience": ["市議員曾信凱服務處執行\n長\n曾順良之友會社會公益執\n行企劃\n曾信凱青年軍團總召\n澳洲雪梨Westin Sydney\nHotel宴會部門"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p95abd41bcd','p95abd41bcd','bulletin','2022-11-26','{"district_id": "tnn-council-10", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p95abd41bcd','p95abd41bcd','platform','2022-11-26','{"district_id": "tnn-council-10", "election": "2022-local", "office": "tnn_councilor", "text": "1.全力催生「青年局」，以能統整年輕人之需求，務使年輕人在政府的專責服務單位下，能工作有前景成家住有\n屋。\n2.督促設置「癌之愛全人關懷大樓」。類此大樓在許添財市長時代曾經公開動土要興健，卻動土之後灰飛煙滅！在\n罹癌比率高漲的社會，台南市政府有責為市民健康提供更貼切的醫療服務。\n3.請加速位於東區生產路上已延宕 12 年的國立科學未來館之興建案，食言未有東區小巨蛋的政府，請積極推動東\n區重大建設。\n4.增加污水下水道管路之埋設，提升市民現代化的生活品質。\n5.還成大里民遭拆除之成大里活動中心，以多功能使用為目標，不只嘉惠成大里民，以成就多贏之高效能建設\n案。\n6.爭取 65 歲以上老人健保全額補助，並推動老人看病公車。\n7.重陽敬老金應比照其他五都提高至一千五百元，並依年齡累進增加。\n8.強化 0-6 歲國家養政策，爭取普設公托公幼，提高生育及托育補助，減輕經濟不穩定的年輕父母生活壓力。\n9.國中小營養午餐免費、減少流浪教師數額、提供代理教師完整聘期、落實特教生就學權益降低師生比保障師\n資。\n10.因應通膨驚人房物價高漲，中低收入戶審議標準應適當調整以落實照顧弱勢之衷旨！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
