INSERT INTO "fact" VALUES('platform:2022-local:p9e4deeec48','p9e4deeec48','platform','2022-11-26','{"district_id": "tnn-council-10", "election": "2022-local", "office": "tnn_councilor", "text": "■「好的，就繼續。」\n這是府城古都得以傳承數百年依然亮眼的價值基礎，我們這一代，仍得肩負起同樣的責任，守護美好的文化傳統、節慶習\n俗、古蹟資產，讓台南持續以「台灣魅力之都」邁向國際。\n■我們一起「堅定向前」\n回應新時代的需求，城市永續發展必須在傳統中保有新創的活力，請您跟筱薇一起，讓我們不同世代的台南人，能以堅定\n向前的步伐，為我們共同的家園的建設與福利打拚。\n一、 推動由「產、學、研、青壯、樂齡」代表組成「都市願景研議小組」，定期向市府提出民間對於城市發展願景的構想藍\n圖。\n二、 爭取經費推動更具美學概念、在地特色的傳統巷弄風貌。\n三、 建置更多現代公共藝術，強化東區藝術、文化、休閒的區域發展特色。\n四、 督促市府重新研議在東區建置小巨蛋室內場館的可行性方案。\n五、 因應人口高齡化趨勢，主張一區一座國民運動中心；社區公園增設銀髮族強化肌力體健設施。\n六、 推動65歲以上銀髮族免費肌力檢測，提早因應肌少症帶來的失智、失能健康風險。\n七、 持續督促市府成立青年局，統籌辦理新世代各項城市生活與發展權益。\n八、 積極推動綠能及AI數位科技智能導入交通建設網絡。\n九、 督促強化國際觀光宣導，佈局因應後疫情時代全球旅遊潮。\n十、 持續爭取提高家庭托育補助費用，減輕新家庭負擔。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9e4deeec48','p9e4deeec48','profile','2022-11-26','{"education": ["國立成功大學政治經濟研究\n所碩士"], "election": "2022-local", "experience": ["大台南市第三屆市議員(議\n會觀察聯盟多次評選為優\n質議員)\n立委林俊憲辦公室主任\n民進黨全國黨代表、台南\n市代表\n台南市慢速壘球協會副理\n事長\n成功國際青年商會社區公\n益主委\n新世代社福協會理事\n進學國小校友會副理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pa72e327247','pa72e327247','bulletin','2022-11-26','{"district_id": "tnn-council-08", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pa72e327247','pa72e327247','platform','2022-11-26','{"district_id": "tnn-council-08", "election": "2022-local", "office": "tnn_councilor", "text": "一、捍衛年輕人，促設青年局，提高預算協助青年就業、創業。\n二、爭取65歲以上長者健保費全額補助。\n三、重陽敬老金應比照其它五都提高至一千五百元，並依年齡累進增加。\n四、提高0~6歲國家養政策，爭取普設公托幼托，提高生育及托育補助。\n五、國中小營養午餐免費，減少流浪教師數額，提供代理教師完整聘期，落\n實特教生就學權益， 降低師生比保障師資。\n六、優化觀光文化等地方特色產業，增加就業機會。\n七、督促穩定民生物房價，保障消費者權益，減輕業者營運負擔。\n八、改善假日鬧區交通，並增進公共運輸環境及品質。\n九、強化治安補足警力，保障市民安全。\n十、整治疏通排水系統，改善地方易積淹水地區。\n十一、提升弱勢族群保障，督促政府提供保險、補助等資源。\n十二、推動校園音樂教育多元化，讓孩童接觸學習各種音樂文化。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
