INSERT INTO "fact" VALUES('platform:2022-local:pb3f833e29c','pb3f833e29c','platform','2022-11-26','{"district_id": "tnn-council-06", "election": "2022-local", "office": "tnn_councilor", "text": "1. 強化「0-6歲國家一起養」政策，爭取普設公托公\n幼，提高生育及托育補助，減輕年輕家庭育兒負擔。\n2. 國中小營養午餐免費、減少流浪教師數額、提供代理\n教師完整聘期、落實特教生就學權益，降低師生比，\n保障師資。\n3. 爭取65歲以上老人健保全額補助，並推動老人看病公\n車。\n4. 重陽敬老金應比照其他五都提高至一千五百元，並依\n年齡累進增加。\n5. 因應通膨驚人房物價高漲，中低收入戶審議標準應適\n當調整以落實照顧弱勢之宗旨！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
