INSERT INTO "fact" VALUES('platform:2022-local:pc85eff1bca','pc85eff1bca','platform','2022-11-26','{"district_id": "tnn-council-11", "election": "2022-local", "office": "tnn_councilor", "text": "一：督促政府，成立青年事務局，協助青年解決就業、創業、結婚、生育、居住問題，讓北漂青年能夠\n返鄉，讓其它縣市青年，願意移居台南。\n二：爭取適合各年齡層使用的全齡化公園，讓老、中、幼童等不同世代，能攜手共享同一休憩空間。\n三：爭取西拉雅國家風景區延伸至龍崎，結合龍崎原有景點，特殊地景，讓龍崎成為台南休憩聖地及最\n美後花園。\n四：監督砲校主體工程與5條聯外道路建設時程，讓砲校及早完工，挹注關廟經濟發展，讓關廟擁有更完\n整的交通網。\n五：盤點綠能智慧園區暨南關線各項重大建設案中，需地方政府配合的事項。全力督促市府，抓緊時\n程，配合中央政府，讓各項建設案如期完工，帶動南關線整體發展。\n六：增設食物銀行，惜物平台，擴大關懷據點服務量能。提升監視器妥善率與治安死角見警率，來強化\n社區安全網。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc85eff1bca','pc85eff1bca','profile','2022-11-26','{"education": ["嘉南藥理科技大學藥學碩士"], "election": "2022-local", "experience": ["臺南市政府 市政顧問\n社團法人台南市藥師公會\n發言人\n台南市嘉南藥理大學校友\n會 理事長\n吉安醫院社團法人 執行長\n財團法人臺灣省臺南市首\n廟天壇附設臺南市私立天\n壇老人養護中心執行長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
