INSERT INTO "fact" VALUES('platform:2022-local:pcaffb2c88c','pcaffb2c88c','platform','2022-11-26','{"district_id": "tnn-council-05", "election": "2022-local", "office": "tnn_councilor", "text": "ㄧ、督促市府積極爭取新市至善化路段鐵路高架化，解決平交道塞車問題。\n二、督促市府積極爭取捷運深綠線，串連南科園區與綠能科學城雙引擎，形塑科技生活廊帶。\n三、督促市府加速進行 A、B、C、D、E、N、O區塊南科特定區開發，建構完整的產業及居住生活圈。\n四、爭取在南科特定區設置大型醫院，以解決南科周邊地區日增人口，醫療量能不足的問題。\n五、爭取普設路口監視器，有效釐清交通肇事責任及遏止犯罪。\n六、爭取教育經費，改善新市、新化、善化、安定、山上等五區幼兒園、國中小學校，校園環境及老舊\n校舍，讓學童上課專心，家長放心。\n七、爭取興建立體停車場、地下停車場，改善停車問題。\n八、爭取南科火車站旁公滯 11 用地，設置特色公園及兒童遊戲場。\n九、爭取提高生育、托育補助，增設平價公共托嬰中心及幼幼專班，讓年輕人敢婚、願生、樂養。\n十、爭取 65 歲長者免健保費。\n十一、督促市府打造毛小孩樹葬園區，讓毛小孩有安息處所，提供主人追思懷念的地方。\n十二、督促市府加速建設南科周邊地區污水下水道系統，將南科周邊地區打造為宜居科技城。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pcaffb2c88c','pcaffb2c88c','profile','2022-11-26','{"education": ["國立中山大學碩士\n國立台南高商\n臺南市新市國民中學\n臺南市新市國民小學"], "election": "2022-local", "experience": ["臺南市新市兒童關懷協會\n理事長\n新市國小志工團團長\n善化分局義警分隊第三小\n隊長\n善化蘭心扶輪社社長\n臺南市議員林慶鎭服務處\n秘書"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pcbeffa2080','pcbeffa2080','bulletin','2022-11-26','{"district_id": "tnn-council-09", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pcbeffa2080','pcbeffa2080','platform','2022-11-26','{"district_id": "tnn-council-09", "election": "2022-local", "office": "tnn_councilor", "text": "1. 強力監督市政，捍衞市民權益。\n2. 加強警民合作，反詐騙宣導及肅槍肅毒，維護社會治安。\n3. 興建鯤鯓安平跨港大橋，連接四草大橋，紓解塞車不便，帶動大安平區之觀光人潮。\n4. 促進安平觀光遊艇園區發展，提升觀光熱潮商機。\n5. 台南機場應軍民分離，提升為國際機場，便利商務觀光需求。\n6. 加速南山公墓徵收遷移，將其綠美化，打造成為現代化生命宗教園區。\n7. 要求南區老舊國宅公辦都更+危老條例，改善生活機能，增加停車空間與拓寬道路。\n8. 督促喜樹、灣裡市地重劃，完善公共設施及加速社會住宅完工，結合黃金海岸的\n自然生態，以觀光休閒振興鯤喜灣區域繁榮。\n9. 推動青年就業方向，畢業即就業。\n10. 爭取台86快速道路橋下，加強照明設備，興建免費停車場及青少年運動場。\n11. 比照五都，爭取65歲以上老人免繳健保費，減輕年輕人負擔。\n12. 爭取國中、小學童免費營養午餐。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pcbeffa2080','pcbeffa2080','profile','2022-11-26','{"education": ["臺灣首府大學"], "election": "2022-local", "experience": ["1.臺南市議會第15、16屆議員2.直轄市臺南市議會第", "1、2、3屆議員3.中國國民黨第19、20、21屆中央委員4.臺南市議會國民黨黨團書記長5.安平開臺天后宮管理委員6.臺南市體育總會滾球委員會主任委員7.臺南市體育總會滑輪溜冰委員會副主委8.安平魅力商圈理事長9.臺南市義消安平中隊顧問10.臺南市中醫師公會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
