INSERT INTO "fact" VALUES('platform:2022-local:pcf94e87b4e','pcf94e87b4e','platform','2022-11-26','{"district_id": "tnn-council-08", "election": "2022-local", "office": "tnn_councilor", "text": "1. 現有空地增設停車場，徹底解決停車位不足問題，並達到區域均衡建設開發。\n2. 督促政府徹底解決淹水問題達成零水患。\n3. 整體檢討都市計畫發展，加速「都市更新」及「社會住宅開發建設」。\n4. 落實長照政策，增設日照中心，65歲以上老人免健保費，提高補助老人長照津貼。\n5. 落實幼兒政策，增設幼兒園、提高生育補助，督促政府廣增設公共化幼兒園教保服\n務及減輕家長負擔。\n6. 爭取國中小營養午餐免費，落實食材在地化，督促為幼兒食品安全及營養均衡把關。\n7. 強力監督食品安全，維護府城美食文化聲譽。\n8. 爭取居住正義，凍漲房屋稅且不得回溯，還財於民。\n9. 重視員警、義消、義警、民防、義刑、守望相助巡守隊之裝備及福利。\n10.爭取年輕及中高齡族群多元化工作取向「訓」「用」合一。\n11.督促傳統市場多元化、多樣化營運，提高生活機能。\n12.積極督促政府普設各項運動專屬場館及場所，提升競技效益。\n13.督促政府積極開發社區公園及育樂設施，並全面檢討里社區活動中心老舊重建，落\n實各里都有活動中心，以提升居民生活品質。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pcf94e87b4e','pcf94e87b4e','profile','2022-11-26','{"education": ["大光國小、成功國中、南英\n商工、崑山工專、崑山技術\n學院、成功大學管理研究所\n碩士"], "election": "2022-local", "experience": ["第1 2 3屆直轄市臺南市議\n員、臺南市第13 14 15 16\n屆議員、臺南市北區小康\n里里長、憲兵學校預備士\n官班147期、臺南市後備憲\n兵聯絡中心主任委員、臺\n南市後備憲兵荷松協會創\n會理事長、臺南市北區後\n備軍人輔導中心主任、崑\n山科技大學台南市校友會\n理事長、中華民國童軍木\n章持有人"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pd22952c6d1','pd22952c6d1','bulletin','2022-11-26','{"district_id": "tnn-council-02", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd22952c6d1','pd22952c6d1','platform','2022-11-26','{"district_id": "tnn-council-02", "election": "2022-local", "office": "tnn_councilor", "text": "1. 推動南41線佳里、西港段跨曾文溪至安南區段之交通系統建設，連結西港、\n佳里都市計畫與新吉工業區、臺南市主要計畫區的生活圈聯絡道路。\n2. 推動國道一號增設西港交流道紓解麻豆、佳里丶西港等地區通勤民眾前往南\n科的交通雍塞問題。\n3. 一區一特色公園，重視城市綠化、結合地方創生、打造樂居城市應有的共融\n式特色主題公園。\n4. 全力配合台61沿線濱海水陸遊憩軸帶規劃建設，發展打造臺南濱海大北門區\n遊憩觀光並帶動地方產業生計。\n5. 爭取提高青年生育補助津貼、延長育兒補助津貼。\n6. 爭取臺南市65歲以上長者免健保費。\n7. 爭取房屋稅凍漲、停徵追溯15年，減輕民眾負擔。\n8. 加速臺南七股科技工業區開發完成為南科供應鏈衛星基地，帶動大北門區就\n業機會及居住繁榮。\n9. 爭取西港區拓寬東側外環道北段建設，多年爭取的東外環道南段已完工。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd22952c6d1','pd22952c6d1','profile','2022-11-26','{"education": ["南榮科技大學畢業"], "election": "2022-local", "experience": ["國立成功大學研究班結業\n臺南縣議會第14 15 16屆\n縣議員\n臺南市合併直轄市一二三\n屆市議員\n臺南市議會民進黨團第五\n任總召集\n臺南市歷屆議員協進會理\n事\n元極舞功法推廣協會第六\n屆理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pd551ff873c','pd551ff873c','bulletin','2022-11-26','{"district_id": "tnn-council-08", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd551ff873c','pd551ff873c','platform','2022-11-26','{"district_id": "tnn-council-08", "election": "2022-local", "office": "tnn_councilor", "text": "1. 爭取65歲老年健保免費。\n2. 強力爭取台南市警政同仁近千位缺額於112年內補齊。\n3. 爭取中西區和緯路五段延伸工程30公頃學產地能夠活化變更為都會科技\n產業專區及住宅用地，促進產業發展、增加就業機會、優化居住環境。\n4. 爭取延平國中校園腹地興建地下停車場，以解決公園沿路停車空間不足問\n題。\n5. 爭取北區鎮北坊歷史街區串連及致力整合交通、觀光、文化政策，帶動舊\n城區觀光與文化經濟同步提升。\n6. 要求市府就中西區原有商圈進行特色整合，舉辦大型活動可串連，並極力\n爭取接駁車至路外停車場以利遊客觀光動線，減少市區交通打結。\n7. 致力推動友善育兒環境，擴增親子悠遊館丶公托家園丶特色遊戲場，推動\n夜間托育及定點臨托服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd551ff873c','pd551ff873c','profile','2022-11-26','{"education": ["協進國小 金城國中 美和護\n專\n長榮大學經營管理研究所碩\n士\n國立成功大學政治經濟研究\n所碩士"], "election": "2022-local", "experience": ["第14、15、16屆台南市議\n員\n第一、二、三屆直轄市台\n南市議員\n民進黨台南市黨部主委\n民進黨中央黨部發言人\n黃偉哲競選市長發言人\n富樂夢教育基金會董事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
