INSERT INTO "fact" VALUES('platform:2022-local:pd9cfdab43f','pd9cfdab43f','platform','2022-11-26','{"district_id": "tnn-council-06", "election": "2022-local", "office": "tnn_councilor", "text": "一、爭取建設安南區轄內兒童特色公園\n二、增設商60消防分隊\n三、爭取安南區公所原地重建，活化安南新中心\n四、比照五都爭取鄰長發放工作津貼\n五、增加新生兒津貼及育兒補助\n六、全力爭取安南捷運線盡速開闢\n七、打造區域公車環狀線，增加公共運輸便民使用\n八、監督安南區汙水管線設置進度\n九、監督安南區淹水問題\n十、督促市府重視垃圾清運環保議題\n十一、爭取農漁民福利政策，增加在地農漁民行銷通路\n十二、爭取安南親子館設施\n十三、爭取台江文化中心藝文活動，打造安南文創環境", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd9cfdab43f','pd9cfdab43f','profile','2022-11-26','{"education": ["南榮科技大學（資訊管理）\n專科部二年制。"], "election": "2022-local", "experience": ["溪心社區長壽會會長、長\n安社區發展協會理事長、\n王國清國大代表助理、王\n昱婷立法委員秘書、台南\n市第16屆市議員、大台南\n直轄市第一屆及第三屆議\n員、安南婦女會15、16屆\n常務理監事、聖恩宮慈心\n會會長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AD%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pde03bc1f3f','pde03bc1f3f','bulletin','2022-11-26','{"district_id": "tnn-council-05", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pde03bc1f3f','pde03bc1f3f','platform','2022-11-26','{"district_id": "tnn-council-05", "election": "2022-local", "office": "tnn_councilor", "text": "1. 支持同意滿 18 歲公民投票權\n2. 推動成立青年事務局，建構輔導青年創業及就業\n3. 加速推動全市各區成立長照中心，強化照顧貧困失養老人\n4. 要求市政府完成虎頭溪沿岸整治工程，杜絕水患，確保市民生命財產安全\n5. 爭取預算改善農水路更新，加速推動農路建設\n6. 督促市政府行銷農產品，帶動相關休閒農業與觀光旅遊，活絡農民收益\n7. 監督市政府兌現各項福利政策，爭取提高婦幼津貼，生育津貼，幼兒教育補\n助\n8. 爭取公共閒置空間活化再利用，促進地方發展\n9. 爭取健保福利補助及鄰長事務費，比照其他直轄市五都實施\n10.推動地方創生，發展合適地域特色產業，讓青年回流，趨緩人口及發展不均\n等問題\n11.柷青服務不分黨派，柷青服務沒有距離", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pde03bc1f3f','pde03bc1f3f','profile','2022-11-26','{"education": ["新化國小 新化國中 長榮女\n中\n遠東科技大學附設專科進修\n學校"], "election": "2022-local", "experience": ["民主進步黨新化區主任 總\n統蔡英文 立委黃偉哲新化\n區競選總部副執行長 立委\n林宜瑾新化區競選總部總\n幹事 民主進步黨台南市黨\n部執行委員\n台南市議員林志聰服務處\n執行長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%94%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pdee0d267cf','pdee0d267cf','bulletin','2022-11-26','{"district_id": "tnn-council-02", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pdee0d267cf','pdee0d267cf','platform','2022-11-26','{"district_id": "tnn-council-02", "election": "2022-local", "office": "tnn_councilor", "text": "一、 積極爭取跨曾文溪橋防止溪北邊緣化，打進南科生活圈，將工業區跟\n工業區串聯起來，帶動附近就業人口，跟整個食衣住行的產業鏈發\n展。\n二、 持續推動：爭取台南市六十五歲以上長者健保費補助與其他五都平等\n待遇。\n三、 爭取大北門區之農水路更新改善工程及農路建設加速推動，保障農民\n權益。\n四、 持續推動宗教廟宇傳統文化資產的傳承與保存。\n五、 推廣大北門沿海地區漁港及潟湖觀光旅遊結合在地美食文化。\n六、 督促及爭取市府建構完善社會福利，照顧長者幼者、保障弱勢團體。\n七、 持續監督落實水患改善工程，解決鄉親水患之苦。\n八、 爭取增設佳里多功能使用會館，以提升市民生活品質。\n九、 爭取建置西港親子悠遊館，讓空間作最大的活用。\n十、 推動藝文活動舉辦，提升參與欣賞藝術的機會，以提升居民生活品質。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%BA%8C%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
