INSERT INTO "fact" VALUES('profile:2022-local:peb60a03c25','peb60a03c25','profile','2022-11-26','{"education": ["立德大學地區發展管理研究\n所碩士\n長榮大學土地開發應用與管\n理系\n國立嘉義農專農田水利工程\n科"], "election": "2022-local", "experience": ["臺南市第3屆直轄市議員\n臺南市仁德區公所區長\n嘉南藥理大學兼任講師\n臺南市仁德區行善團團長\n臺南市愛馨慈善會理事長\n臺南市慢速壘球協會理事\n臺南市慢壘委員會常務委\n員\n臺南市仁德棒球協會理事\n長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%B8%80%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf52ecfedf1','pf52ecfedf1','bulletin','2022-11-26','{"district_id": "tnn-council-03", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf52ecfedf1','pf52ecfedf1','platform','2022-11-26','{"district_id": "tnn-council-03", "election": "2022-local", "office": "tnn_councilor", "text": "1. 持續爭取治安、治水丶防災經費，解決水患，保障人民生命丶財產安全。\n2. 堅持清廉問政，監督市府推動各項政策，嚴格把關人民的納稅錢，防止貪弊。\n3. 維護居住環境衛生，監督市府落實稽查，避免農、漁、畜牧業用地遭受污染。\n4. 配合工業區的開發，鼓勵青年返鄉就業，與企業共同合作輔導訓練，培育優質人力，提倡優質工作環境。\n5. 推動各區在地觀光產業丶精緻農業，將各區傳統農業發展為高價值產業並強化行銷地方文化與特色，串連商圈推動\n輕旅行，創造商機。\n6. 爭取各區增設主題特色公園及運動場館，並提升休憩品質。\n7. 推動整合醫療照顧與長照機構相關資源，加強照護長輩服務體系，廣推長照 2.0 。\n8. 持續爭取擴編生育補助丶育嬰補助及幼兒教育補助，增加生育率，減少家庭負擔，爭取增設公托丶公幼，推動\n幼兒托育相關政策。\n9. 續推政府增加補助農業保險金額，增加農民參與保險意願，減少天災帶來的損失。\n10. 推動職業安全衛生及健康管理，提倡安全的工作環境，避免職業災害，創造幸福家庭。\n11. 爭取設置臨托場所，讓照顧長輩及幼兒者，有更充裕的時間可利用及喘息。\n12. 爭取下營區六里聯合活動中心。\n14. 爭取官田區隆本里及隆田里聯合活動中心。\n15. 爭取麻豆區跨曾文溪大橋連接善化烏橋中路進入南科。\n16. 爭取農水路及道路修繕經費，讓人民有條安全回家的路。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf52ecfedf1','pf52ecfedf1','profile','2022-11-26','{"education": ["嘉南藥理大學學士、碩士\n南光中學\n下營國中"], "election": "2022-local", "experience": ["臺南市第 3 屆巿議員\n台南市議員陳文賢服務處\n主任\n民主進步黨 5 屆全國黨代表\n凱達格蘭學校國家領導與\n發展策略班\n善化糖廠職業安全衛生管\n理師\n下營反垃圾掩埋場自救會\n會長\n下營商圈文化觀光促進會\n理事長\n台灣生活環境安全衛生學\n會秘書長\n甲級空氣污染、廢水處理\n防制專責人員\n甲級職業安全、衛生管理師"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf85bbe331d','pf85bbe331d','bulletin','2022-11-26','{"district_id": "tnn-council-08", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf85bbe331d','pf85bbe331d','platform','2022-11-26','{"district_id": "tnn-council-08", "election": "2022-local", "office": "tnn_councilor", "text": "教育更進步\n1、推動校園設施汰舊換新，加速科技設備的提升，讓孩子們受教育的環境更優質。\n2、配合2030年雙語國家政策，提升各級學校雙語教育資源，接軌國際，並增加與國際間各級學校交流的機會。\n長照更幸福\n1、推動更多資源進入社區，強化社區共同照護的能量，並且透過社區供餐關懷長者。\n2、在社區中導入醫療資源協助照護長輩，讓長者安心養身保健，也讓青年族群得以安心在外工作。\n生活更安全\n1、補足警察、消防第一線人員員額及盡速汰換老舊設備，並落實警消人員職後定時受訓，強化治安及消防量能。\n2、通盤檢討排水規劃，在面對極端氣候下強降雨的情況，重新整治水路，改善排水系統，避免逢雨必淹的情形。\n交通更順暢\n1、優先保留公有大型停車場部分車位給在地居民，舒緩停車空間不足及道路交通壅塞之問題。\n2、通盤檢討騎樓與人行道的使用，打造友善行人的城市，並且透過地方法規完善地制定，讓鄉親『安全行走』。\n育兒更安心\n1、持續增設公托、準公托，提高育兒津貼及生育津貼，並且重視托育孩童的環境，讓孩子安全、家長安心。\n2、推動特色公園、共融遊樂場持續建置，並導入孩童參與主題的決定，一同打造快樂親子城市。\n青年更宜居\n1、伴隨著高科技產業進駐，持續盤點可以使用並且適合的地點，推動社會住宅的興建。\n2、推動社會住宅納入育兒、長照相關設施規劃，減少青年移居後所面臨的困擾，讓台南成為真正的宜居城市。\n觀光更精彩\n1、協助社區營造、地方創生的推動，並串連各商圈、古蹟資源，將台南深厚地文化底蘊融入，提升觀光產值。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf85bbe331d','pf85bbe331d','profile','2022-11-26','{"education": ["國立成功大學法律學系\n國立成功大學法律碩士"], "election": "2022-local", "experience": ["執業律師\n蔡英文賴清德臺南市競總\n中西區主任\n立委林俊憲特助\n黃偉哲市府青年委員\n民進黨臺南市中西區主任\n臺南市機車商業同業公會\n法律顧問\n臺南市民宿文化發展協會\n法律顧問\n臺南市慢速壘球協會法律\n顧問\n臺南市赤嵌朋派商圈發展\n協會法律顧問\n臺南市傳愛慈善會法律顧\n問\n志光公職補習班法律講師"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%85%AB%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pfb2d71d270','pfb2d71d270','bulletin','2022-11-26','{"district_id": "tnn-council-03", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pfb2d71d270','pfb2d71d270','platform','2022-11-26','{"district_id": "tnn-council-03", "election": "2022-local", "office": "tnn_councilor", "text": "一、為地方爭取建設、為百姓謀福利，為民喉舌！\n二、督促六甲外環道二、三、四期後續工程進度，極力爭取六甲的生命\n紀念館。\n三、台灣首府大學退場後，督促市府全力推動麻豆全民運動館的設置。\n四、爭取六甲、官田、麻豆、下營區重劃區內農水路改善工程。\n五、督促官田區南 120 道路拓寬工程盡速完工；極力爭取二鎮環保運\n動公園內設置風雨球場。\n六、下營區的抽水站必需重新、徹底評估設計、改善未解決淹水的損失\n與痛苦。\n七、督促市府盡速改善麻豆、大內、下營、官田等易淹水區，免除民眾\n長久飽受淹水之苦。\n八、爭取石仔瀨抽水站加裝 3CM 機組以防風災淹水；大內區石仔瀨天\n后宮至大內分駐所段道路拓寬工程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-02T15:34:15Z');
