INSERT INTO "fact" VALUES('platform:2022-local:p0a7ed05f4f','p0a7ed05f4f','platform','2022-11-26','{"district_id": "khh-council-11", "election": "2022-local", "office": "khh_councilor", "text": "一、推動捷運大寮週邊道路開通及商圈開發。\n二、爭取林園、大寮一里一公園。\n三、爭取大坪頂特定的開發。\n四、爭取大寮三隆路拓寬。\n五、爭取大寮區81期重劃內，設置綜合性活動中心。\n六、爭取義仁里天池路往鳳山水庫道路拓寬。\n七、督促市政府重視青年就業及勞工低薪問題。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
