INSERT INTO "fact" VALUES('platform:2022-local:p0c8ddd8f31','p0c8ddd8f31','platform','2022-11-26','{"district_id": "khh-council-13", "election": "2022-local", "office": "khh_councilor", "text": "1.秉持110服務精神，關懷正義、服務效率。在原鄉區與都會區設置服務處，受理族人服務案件。免費法律諮詢，保障族人權益。\n服務不分顏色，為原住民幸福加油！\n2.爭取那瑪夏布農族祭儀場，及拉魯哇族男子聚會所興建。尊重原住民各族群傳統文化。\n3.持續爭取，原鄉農路改善，水利設施經費。讓農民有安全農路，從事農產品種植及採收、運輸。\n4.推動原鄉觀光產業，那瑪夏螢火蟲擴大獎勵復育面積。建置賞螢步道，保障觀光客安全。\n5.推廣本市原住民文創及農創產業。督促市府輔導農民農產商品認證，積極鼓勵原鄉農產品申請﹝三章一Q﹞標章。符合上架各\n大通路銷售，讓原鄉農產永續發展。\n6.增加都會區原住民假日市集據點，讓原住民攤商進駐，提升原住民文創者經濟收入。舉辦原住民人才培育，提供銷售通路、\n商品質優化、包裝行銷等課程訓練。\n7.要求市府在杉林大愛園區水利排水工程持續改善。督促原民會多在園區舉辦活動，活絡園區相關產業。\n8.督促原民會寬籌原民社團經費，積極協助原住民社團、教會辦理各項活動。活絡原住民團體。\n9.爭取原住民育兒托育、家庭教育，以及老人長輩照護資源；要求市政府落實輔導原住民青年就業，並強化專業職能訓練措施。\n10.監督政府重視原住民軍警升遷，提拔優秀原住民軍警。充實警用應勤裝備。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
