INSERT INTO "fact" VALUES('platform:2022-local:p0cc93dda14','p0cc93dda14','platform','2022-11-26','{"district_id": "khh-council-12", "election": "2022-local", "office": "khh_councilor", "text": "一、爭取設置都會區原住民參議會，落實原住民青年公共事務參與。\n二、爭取設置都會區原住民實驗學校，強化原住民文化復育與族語推廣工作。\n三、爭取原住民社會住宅配額，設置青年社宅，健全原住民購屋、租屋、修繕等補助機制。\n四、持續推動原鄉產業發展計劃，設置原住民產業合作平台，強化原住民產業經濟與創業輔導。\n五、持續爭取設置原住民主題意象場域，強化原住民族社會認同與社會地位。\n六、落實原住民長照政策與執行，健全文健站營運輔導，強化年長者照護工作。\n七、健全原住民社會服務網路，強化全方位社會福利服務工作。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
