INSERT INTO "fact" VALUES('profile:2022-local:p1017771de1','p1017771de1','profile','2022-11-26','{"education": ["國立中山大學海洋事務研究\n所管理碩士\n國立中山大學海洋環境及工\n程學系工學學士"], "election": "2022-local", "experience": ["社團評鑑高雄市優質議員\n高雄市議會民進黨團副總召\n陳菊秘書\n陳其邁發言人\n蔡英文高雄市競選總部副總幹事\n立委李昆澤國會辦公室執行長\n台灣海洋治理策進學會理事長\n國立中山大學校友總會理事\n全國大專院校優秀青年代表\n行政院青年國是會議全國代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
