INSERT INTO "fact" VALUES('bulletin:2022-local:p166829ffde','p166829ffde','bulletin','2022-11-26','{"district_id": "khh-council-04", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p166829ffde','p166829ffde','platform','2022-11-26','{"district_id": "khh-council-04", "election": "2022-local", "office": "khh_councilor", "text": "雅芬當選議員即努力爭取重大建設，左楠要成為優質生活圈，建設仍有許多需要補強之處。雅芬期待您的支持，繼續為鄉親幸\n福+芬。\n為主婦安心加分：雅芬是五個孩子的母親，最了解婦女需求。左楠托兒、日照據點必須大幅增加；多數長輩仍有社會參與能力\n，設長青局推動高齡友善樂活事務。\n為青年成家立業加分：楠科（中油舊廠址，台積電將進駐）、橋科廠商提撥適當名額優先錄用在地子弟，工作期間結婚者，要\n求市府視財政狀況補助房租，生育者發獎金。\n為教育質量加分：爭取楠梓國小新建校舍、增設藍田國小。未來爭取楠梓新設國中、科學實驗中學留在楠梓、高雄大學附設中\n小學，強化雙語、科技教學。\n為洽公、活動便利加分：後勁設楠梓第二行政中心、高大特定區新建合署辦公大樓。增設里民活動中心；高大特定區藍田等三\n里、右昌國昌等四里、清豐里；爭取左營新光、菜公里與楠梓坑東寧等五里。\n為交通順暢加分：左楠道路系統多處嚴重塞車，未來橋科、楠科車輛大增，園區西側與台1線聯絡道路、鐵路高架或地下化、\n消除「百慕達」、捷運紫線必須加速完成。\n為生活品質加分：楠科開發不容許污染，後勁部落應都市更新。左楠老舊公園、兒童遊戲場必須重整，人行道必須整平。強化\n運動中心機能，增設夜間運動場地。右昌淹水改善計畫早日完成，後勁溪親水環境再提升。\n警消待遇加分：雅芬是警眷，深知警消辛勞。警消車輛、裝備、電腦老舊，爭取逐年汰舊換新。高雄市警察繁重加給為雙北市\n七成，爭取至同一標準。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p166829ffde','p166829ffde','profile','2022-11-26','{"education": ["高雄市私立國際商工畢"], "election": "2022-local", "experience": ["立法委員黃昭順辦公室助理\n高雄市義勇消防防火宣導大隊新\n莊分隊顧問、高雄市善心慈善會\n顧問、社團法人高雄市青少年服\n務協會顧問、高雄市楠陽桌球聯\n誼會顧問、國立高雄科技大學校\n友總會顧問、高雄市救國團楠梓\n區團委會會長、中國國民黨第19\n、20、21屆全國代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p1a372613bb','p1a372613bb','bulletin','2022-11-26','{"district_id": "khh-council-11", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p1a372613bb','p1a372613bb','platform','2022-11-26','{"district_id": "khh-council-11", "election": "2022-local", "office": "khh_councilor", "text": "1.轉型顧經濟，繁榮看得見，加速推動捷運到林園時程、國道七號，翻轉林園大寮工業區的宿命。\n2.顧大又顧小，家長好放心，社會住宅在林園大寮、盤點現有閒置空間並活化，持續增設日托、臨托、夜托、開懷據點等，托幼\n也托老。\n3.觀光再升級，形象大翻轉，增加大寮林園自行車步道，推動老街再造，加強林園海岸線景觀美化，擴大觀光效益。\n4.親子加藝文，預算要增加，爭取各大藝文活動在林園大寮，盤點區域增設特色公園、寵物友善公園、兒童運動公園，讓孩子能\n就近玩也讓寵物有去處。\n5.人口不外流，留住好青年，支持在地青年創業，國營企業優先聘用在地子弟，石化稅收專款專用建設地方，讓人才適得其所，\n讓企業不再缺工。\n6.弱勢加倍顧，各族群都要，身心障礙、特殊境遇、新住民、二度就業等身分，彌平資訊落差，加速融入社會。\n7.空汙要改善，全力來監督，務實面對問題，輔導工業、企業進行綠能減碳措施，實際解決問題。\n8.18歲公民權，一定要同意，青年是我們的末來，力挺18歲公民參與公共事務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p1a372613bb','p1a372613bb','profile','2022-11-26','{"education": ["高雄市普門高級中學。高雄\n市立空中大學科技管理學系\n。國立高雄科技大學財政稅\n務系碩士。"], "election": "2022-local", "experience": ["高雄市第2屆市議員。中殼潤滑油\n股份有限公司董事長。民主進步\n黨第17至20屆全國黨代表。凱達\n格蘭學校第13期國家領導發展策\n略班。澳洲國際商業學院。林園\n環保促進會理事長。林園頂厝社\n區發展協會理事長。林園游泳協\n會理事長。林園國小家長委員會\n會長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
