INSERT INTO "fact" VALUES('profile:2022-local:p1f29618250','p1f29618250','profile','2022-11-26','{"education": ["正修科技大學創意產業經營\n學位學程管理學士、高雄高\n商、鳳西國中、正義中學附\n設國中部、鳳西國小"], "election": "2022-local", "experience": ["國民黨高雄市議會黨團副總召\n國民黨21屆中央委員、高雄青工\n總會副總會長、高雄市鳳山區農\n會理事、台灣黃埔眷村協會理事\n、正修科大校友會會務顧問、商\n科聯誼會副會長、鳳邑開漳聖王\n廟管理委員會秘書長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p2f80f9c3fa','p2f80f9c3fa','bulletin','2022-11-26','{"district_id": "khh-council-06", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC6%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p2f80f9c3fa','p2f80f9c3fa','platform','2022-11-26','{"district_id": "khh-council-06", "election": "2022-local", "office": "khh_councilor", "text": "1. 嚴格監督台積電設廠動工進度、施工品質，並如期提供高雄市民工作機會。\n2. 嚴格監督輕軌（博愛大順路、美術館路、中鼓山、鹽埕）施工品質及交通軌道安全。\n3. 爭取鼓山區內惟段 9 小段 54～55 地號土地，未來開發興建規劃，應納入鼓山行政機關及鼓山（里）聯合活動中心等空間，\n提供鼓山居民洽公及社團活動使用。\n4. 督促鼓山區內惟藝術中心工程品質，並如期完工開放提供市民使用。\n5. 爭取龍子里凹子底森林公園、龍水里美術園區經常性舉辦親子共融活動。\n6. 爭取政府編列預算鼓勵鹽埕、鼓山、旗津老舊公寓修建或重建補助。\n7. 爭取幼兒教育、國小、國中、高中，全民教育費由政府負擔。\n8. 爭取鹽埕區老舊商場重建或修建機制，由政府公權力協助召開重建及修建機制，達成繁榮的鹽埕商場場域。\n9. 督促鹽埕、鼓山區國民運動中心興建進度，並持續爭取旗津區興建國民運動中心。\n10. 督促政府正在研議旗津第二過港隧道路線規劃的進度，俾便後續工程規劃。\n11. 向中央政府爭取國民年金老年給付金額調升至每月 5000 元以上（因國內物價指數升高）\n12. 爭取婦女權益落實保障，工作待遇符合兩性平等工作權。\n13. 爭取國家協助青年首次購屋（20~30 坪）自備款由政府墊支，爭取政府土地興建青年社會住宅，責成政府成立青年第一次購\n屋自備款墊支基金專戶。\n14. 督促國民雙語教育於 2025 年落實，加強國際語言教學，以提升台灣人民未來在國際的競爭力。\n15. 爭取市府與民間醫療機構合作興建近海離島旗津長照醫療中心。\n16. 支持滿十八歲青年公民權入憲，為了讓年輕人更了解自己可以決定自己與國家的未來。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC6%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
