INSERT INTO "fact" VALUES('bulletin:2022-local:p2f9a17557d','p2f9a17557d','bulletin','2022-11-26','{"district_id": "khh-council-07", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('profile:2022-local:p2f9a17557d','p2f9a17557d','profile','2022-11-26','{"education": ["正興國小、道明中學、正修\n工專土木工程科、國立中山\n大學人力資源管理研究所碩\n士、國立中山大學公共事務\n管理研究所博士。"], "election": "2022-local", "experience": ["高雄市第一•二屆市議員、正修\n科技大學助理教授、中國國民黨\n高雄市市黨部主任委員、中國國\n民黨中央組織發展委員會青年部\n主任、高雄市正忠文教協會理事\n長、高雄市政府公務人力發展中\n心講師。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p3879bb14b6','p3879bb14b6','bulletin','2022-11-26','{"district_id": "khh-council-07", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p3879bb14b6','p3879bb14b6','platform','2022-11-26','{"district_id": "khh-council-07", "election": "2022-local", "office": "khh_councilor", "text": "一、成功爭取建置寶業滯洪池遊戲場。\n持續推動鄰里公園成為特色公園，兼顧長輩與兒童發展與社區運動的共融理念。\n二、監督交通建設(輕軌、黃線捷運)不要有交通黑暗期。\n督促市府提出周延交通計劃、提供足夠停車空間，並與市民溝通。\n三、成功監督市府還債 71 億，持續監督市府減債績效。\n四、高雄要有好空氣，監督中區焚化廠如期於 2025 年除役。\n五、關心年輕人就業與創業，持續監督市府青創績效，協助在地青年圓夢。\n六、關心弱勢\n１. 持續督促市府將閒置空間轉為老人長照及幼兒托育的據點。\n２. 持續督促市府扶助弱勢家庭，法規鬆綁並整合公私資源落實之。\n七、反毒政見\n持續打造無毒高雄，為毒品防制擔任反毒志工。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p3879bb14b6','p3879bb14b6','profile','2022-11-26','{"education": ["北一女中\n臺灣大學法律系\n中山大學政治學研究所碩士"], "election": "2022-local", "experience": ["•執業律師(律師高考及格)", "•民進黨發言人(2011年-2012年)", "•高雄市議會第2屆議長", "•高雄市議員(2002年迄今)", "•高雄縣議員(1998年-2002年)"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p3e5fdd3f09','p3e5fdd3f09','bulletin','2022-11-26','{"district_id": "khh-council-03", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p3e5fdd3f09','p3e5fdd3f09','platform','2022-11-26','{"district_id": "khh-council-03", "election": "2022-local", "office": "khh_councilor", "text": "1.督促政府引進高端產業留住人才，厚植經濟實力，增加青壯年就業機會，提高基本工資。\n2.健全各產業園區功能，園區內設置青創育成中心，降低青年創業門檻。\n3.監督政府防洪排水計畫，整治阿公店溪、典寶溪以及各排水系統，完善抽水站及設備，徹底杜絕淹水問題。\n4.要求政府積極改善空氣品質，嚴格監管廢水排入河川，捍衛市民健康\n5.督促政府興建全市各區多功能運動中心，充實室內外運動場館設備，滿足市民休閒運動健身之需求。\n6.串連大岡山地區觀光資源，整體規劃觀光景點，活化在地歷史建築，保留眷村文化。\n7.力促捷運紫線(高雄學園線)興建，結合沿線橋科、台積電與周遭大學產學合作，提升本市科技競爭實力。\n8.完整高雄捷運路網，推動北高雄海線（新台１７線至台南市政府）捷運規劃，繁榮沿海地區。\n9.督促高雄新市鎮後期開發區與橋頭科學園區發展作通盤整合。\n10.縮減城鄉差距，力促政府調整合理預算資源配置。\n11.督促政府健全農漁貨產銷制度，拓增外銷通路，爭取放寬農漁業天然災害補助標準，保障農漁民收益。\n12.監督政府落實長照保險制度，營造「以家為核心；社區為輔」的多元長照制度。\n13.增加幼兒園托育補助，善用國小閒置校舍增設公立幼兒園，減輕父母育兒負擔。\n14.擴增公共托嬰據點，增加各據點托嬰人數，提供年輕父母喘息服務。\n15.要求全面檢討教改，建立開放多元、資源豐足的終身教育體系。\n16.要求完善警察、消防人員裝備，補足警消超勤津貼。\n17.督促政府完善動保制度，改善流浪犬貓收容環境，增加寵物認養據點。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p3e5fdd3f09','p3e5fdd3f09','profile','2022-11-26','{"education": ["國立中山大學高階公共政策\n碩士\n聯合工專畢業\n市立高雄高工畢業"], "election": "2022-local", "experience": ["高雄縣第15、16屆縣議員\n救國團橋頭鄉團委會會長\n高雄縣青工總會會長\n高雄市農會理事\n高雄市議會1∼3屆議員(現任)"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p4014175838','p4014175838','bulletin','2022-11-26','{"district_id": "khh-council-11", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p4014175838','p4014175838','platform','2022-11-26','{"district_id": "khh-council-11", "election": "2022-local", "office": "khh_councilor", "text": "一、提昇治安工作，確保林園大寮優質安全之生活環境。\n二、嚴密監控林園、大寮工業區之污染防治，提昇工安、環保，確保居民健康安全。\n三、全力爭取高雄捷運系統延伸至林園，並連結大寮成一環狀系統以利地方發展。\n四、中芸漁港擴建、觀光漁市場興建及林園海岸復育景觀再造應速完成以提升地方繁榮發展。\n五、落實弱勢團體之照顧及各項津貼補助應予放寬。\n六、健全老人、婦幼及身心障礙者福利救助。\n七、爭取生育補助、提升托育及幼教照顧，創造人口正成長。\n八、爭取林園、大寮地區觀光、文化、各項公共設施之早日開發以創造優質生活空間。\n九、提昇教育品質，重視倫理教育工作，保障各級教師權益。\n十、創造、爭取大寮、林園鄉親就業機會並適時輔導進入職場發揮人力保障生活。\n十一、協助高雄市推展各項工作，謀造全體鄉親幸福。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
