INSERT INTO "fact" VALUES('platform:2022-local:p571db4dee7','p571db4dee7','platform','2022-11-26','{"district_id": "khh-council-09", "election": "2022-local", "office": "khh_councilor", "text": "鳳山女兒李雅靜，點亮鳳山、鳳山亮起來！\n一、青年新希望：全力支持18歲公民權修憲！推動青年就業、創業輔導機制，降低青年失業率，提高生育補助、提升托育政策，\n讓年輕人敢生、能養。\n二、鳳山健康醫療產業園區：爭取五甲農業區轉型，打造鳳山健康醫療產業園區，引進醫學中心等級醫院進駐，強化鳳山醫療量\n能及資源，引進智慧醫材產業鏈，讓鳳山成為南台灣健康醫療產業重地。\n三、活化國有土地：成功爭取誠智里灣頭南巷國有地，為鳳山留下淨土，持續推動開發教育文化學苑、專職技能訓練場域等文教\n社福建設，符合鄉親公共利益使用項目。\n四、強化社會安全網：爭取補足治安、公安、勞安專業人員員額，並爭取汰換老舊裝備，強化社會安全網，讓市民安心。\n五、再現黃埔風華：持續推動地方創生結合黃埔新村，連結周邊經濟產業、文化，重現黃埔風華，打造成為全台唯一活的眷村博\n物館。\n六、璀璨鳳山溪：持續推動改善鳳山溪流域水質整治，美化沿岸親水空間，打造區段親水公園、裝置藝術燈區，夜晚蛻變為璀璨\n燈河，吸引人潮、帶動商機。\n七、商圈生態共榮：打造全齡無差別化特色形象商圈、市場、夜市，結合地方生態活絡在地商機，形成庶民經濟生態圈，全面振\n興庶民經濟。\n八、推動便利停車：繼成功爭取鳳山運動園區地下停車場、北昌路停車場，持續推動設置停車場，解決鳳山停車困境。\n九、活化閒置空間：盤點、推動活化市有閒置空間，增設育幼、銀髮樂活空間、國民運動中心、兒童運動中心等。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p571db4dee7','p571db4dee7','profile','2022-11-26','{"education": ["中山大學公共事務管理研究\n所碩士、輔英技術學院環境\n工程衛生系、大仁藥專工業\n安全衛生科、鳳西國中、鳳\n山國小"], "election": "2022-local", "experience": ["高雄市議會第1至3屆議員、國民\n黨團副總召、書記長、全國青工\n會總會長、中常委、文傳會副主\n委、輔英科大校友會理事長、大\n仁及正修科大校友會顧問、中山\n大學環工所博士候選人、鳳西扶\n輪社社長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p57f3031d97','p57f3031d97','bulletin','2022-11-26','{"district_id": "khh-council-09", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p57f3031d97','p57f3031d97','platform','2022-11-26','{"district_id": "khh-council-09", "election": "2022-local", "office": "khh_councilor", "text": "以「堅持對，骨力做」的精神全力打拼，張漢忠全心全力貢獻地方，爭取鳳山的繁榮和進步\n1.儘速新建鳳山捷運黃線路網，積極爭取沿線商家、住家的損失補助與措施辦法，在黃線捷運的落實過程中，讓市民\n更安心。\n2.發揮鳳山衛武營藝文中心、大東文化藝術中心等硬體優勢，結合周邊景點，如：鳳儀書院、曹公圳、兵仔市等特色\n街，以及百年廟宇文化、美食小吃，運用新創科技體驗，與傳統共生，形塑「吃」、「玩」、「遊」之高品質鳳山文\n化祭。\n3.持續推動老舊社區活化更新，危險及老舊建築優先體檢，強化安全結構，讓民眾住得安心。\n4.監督市府保障勞工生活、權益與就業的安全，爭取提升最低基本薪資與福利政策。支持地方創生，爭取青年創業計\n畫與補助措施。\n5.高齡人口多，落實加強長期照顧設施、廣設關懷與樂齡據點，提升照護量能，降低家庭照顧者負擔，讓長者互助學\n習，保持社交，並享有新知識技能。\n6.徹底改善道路品質，改進危險路口，增加市區公有停車位供給量，讓市民交通更便利。\n7.改善流浪動物處境，落實寵物晶片管理制度，提倡認養代替購買。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p57f3031d97','p57f3031d97','profile','2022-11-26','{"education": ["仁德醫護管理專科學校。三\n信家商。中正高工。忠孝國\n中。梓官國小"], "election": "2022-local", "experience": ["第一二三屆高雄市議員。第十六\n屆高雄縣議員。慶忠機車行負責\n人。高雄市羽球委員會主任委員\n。高雄市交通義勇警察副大隊長\n。高縣機動車修理工會理事長。\n鳳山滑輪溜冰推廣協會理事長。\n鳳山區保興宮管委會常務監事。\n鳳山慈福宮副主任委員。和春技\n術學院肄業。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
