INSERT INTO "fact" VALUES('platform:2022-local:p5a88055433','p5a88055433','platform','2022-11-26','{"district_id": "khh-council-07", "election": "2022-local", "office": "khh_councilor", "text": "一、落實「高雄表參道計畫」，再打造再繁榮火車站附近特色商圈。\n二、督促高雄捷運黃線儘速完工，並減低施工交通黑暗期負面影響。\n三、加速高雄肉品市場、三民街友服務中心遷移，並有效開發原址。\n四、擴大鐵路地下化後綠園道多元化功能，加強觀光、休憩等功能。\n五、透過都市更新，規劃三民區為連貫大高雄南北經濟重要新樞紐。\n六、中都已經有第二美術館園區之稱，中都磚窯場應配合當地發展。\n七、持續督促降低路邊停車收費，透過減少收費等，減輕民眾負擔。\n八、高雄進入老年化時代，推動長照專業人員培訓，好好照顧長輩。\n九、增添公托中心數目，讓年輕夫妻不用碰運氣抽籤，無後顧之憂。\n十、建構三民區為智慧城市，透過網路讓衣食住行娛樂等更為便捷。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
