INSERT INTO "fact" VALUES('profile:2022-local:p5b92ea164d','p5b92ea164d','profile','2022-11-26','{"education": ["國立中山大學海事所碩士\n國立中山大學海資系"], "election": "2022-local", "experience": ["高雄市議會特色公園小組召集人\n高雄市議會國民外交促進會副會\n長\n高雄市議會民進黨團書記長\n高雄市政府新聞局主秘\n陳菊市長辦公室副主任\n立委趙天麟國會執行長\n謝長廷秘書\n高雄市游泳委員會副主委\n高雄市鳳美客家事務協會顧問\n高雄市台東同鄉會理事\n高雄市屏東同鄉會理事\n新高雄嘉義同鄉會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
