INSERT INTO "fact" VALUES('platform:2022-local:p5fb0b50e0f','p5fb0b50e0f','platform','2022-11-26','{"district_id": "khh-council-09", "election": "2022-local", "office": "khh_councilor", "text": "一、老人小孩國家養，擴大生育補助，廣建托嬰中心、平價幼兒園，關懷橘世代、銀髮世代，落實長照及關懷據點，推動全齡\n化公園。\n二、推動正派政治，打造公義高雄，監督政府謹守行政倫理、程序正義、財政紀律。\n三、督促捷運黃線以TOD導向模式開發鳳山，提升土地使用強度、高效能聯合開發，安全施工，優質完工。\n四、中崙引進新產業園區，以國土計畫、都市更新提高土地利用及公共設施配置效益，永續都市發展。\n五、推廣智慧交通，路口號誌智慧調整車流時間，增加路邊戶外停車供給量及智慧資訊，加強鳳山交通流暢度。\n六、落實鳳山中城計劃，優質開發重劃區、購物中心、藝文特區、藝術村，優化聯外交通系統，活化地方經濟。\n七、終結鳳山水患，鳳山溪整治分洪導流，污水、雨水下水道定期清疏。\n八、深化客家語言傳承，獎勵客語認證，辦理客家族群節慶活動，扶植客家音樂、文化人才，鼓勵客語歌曲創作。\n九、打造流行音樂產業鏈，運用豐富多元的音樂、表演、藝術展演設施，扶植在地音樂演唱、創作人才，發展音樂相關產業。\n十、推動運動康健城市，鼓勵騎乘自行車，推廣滑板、霹靂舞、運動攀岩等奧運新增運動，擴大運動中心使用效益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
