INSERT INTO "fact" VALUES('platform:2022-local:p6c04b95991','p6c04b95991','platform','2022-11-26','{"district_id": "khh-council-10", "election": "2022-local", "office": "khh_councilor", "text": "●速建國道七號，從海邊貨櫃碼頭直接引流大貨卡車上國 1 國 10 台 88 遠離平面道路\n●比照台北松山機場爭取小港機場南北牆邊道路美化及穿越機場地下道工程\n●續爭取前鎮新草衙土地處理自治條例成效及鄉親權益維護與優惠大沿海遷村工程\n●成功爭取小港機場北側圍牆彩繪暨數公園器材、大坪頂大型兒童公園新增設\n●督促水利局加速防災極端氣候、下水道生活溝排水清淤清理工程暨環境工程\n●質詢並督促加強公私監視系統，整合聯防機制，汰舊更新器材\n●提案並督促市政府鼓勵青年愛國從軍、立業致富、生涯規劃、青年創業輔導事宜\n●督促市政府爭取長照暨日照中心資源，促進社政和醫政整合、加強噴藥減蚊\n●續監督市政府跨局處合作，協助高污染產業轉型減污暨成年青少年學童毒品防治工作\n●督促市政府透過公共建設或土地獎勵投資，增加公私停車場位\n●爭取各區推動雙語教育增設公私幼兒園，落實資源均衡，打造安全移居幼兒城市\n●爭取完善專業安全前鎮小港複合式運動中心暨各級學校 PU 跑道新增與改善\n●爭取前鎮漁港改造、周邊道路綠化暨捷運黃線延伸前鎮漁港暨各巷道重刨鋪工程\n●續爭取設立前鎮小港各處增設公共自行車 2.0 租賃站\n●爭取近億元整治美化中安路旁鳳山溪前鎮河及數座抽水站工程", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p6c04b95991','p6c04b95991','profile','2022-11-26','{"education": ["國立中山大學社會科學院高\n階公共政策碩士\n私立東方工業專科學校\n小港國中國小\n海汕國小"], "election": "2022-local", "experience": ["合併前六七屆合併後一二三屆議\n員\n小港區濟南里長\n高雄市議會保安小組召集人\n市議會國民外交委員會副會長\n社政交通小組副召集人\n農水利海洋小組副召集人\n環保督導專案小組委員\n地政士公會顧問\n港安關懷協會榮譽理事長\n身心障礙權益保障推動小組委員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p784edcac1f','p784edcac1f','bulletin','2022-11-26','{"district_id": "khh-council-05", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p784edcac1f','p784edcac1f','platform','2022-11-26','{"district_id": "khh-council-05", "election": "2022-local", "office": "khh_councilor", "text": "一、推動高雄市政府行政中心北遷仁武西營區\n二、為交通瓶頸找方法，為車潮分流出路\n三、爭取國十大社交流道\n四、打通仁武中華路跨越後勁溪直達省道\n五、打通仁武水管路穿越中油廠區連接左營後昌路與台17線接軌\n六、打通仁武區仁雄路通往都會瓶頸點\n七、緊追仁武仁心路二、三期進度\n八、爭取仁武區仁林路拓寬案\n九、灣內國小舊校舍籌設托嬰托老中心\n十、開發文小四學校預定地，爭取籌建學校，滿足仁武區人口增長，學童就學需求\n十一、有效開發高屏溪沿岸土地，增加大樹區學子休閒運動場所\n十二、新設納骨塔，解決納骨塔位嚴重不足問題\n十三、迎接仁武安居，廣建社會住宅，讓年輕人住得起負擔得起\n十四、持續為解決水患找方法，為急降雨淹水找出路\n十五、持續緊追大社區段徵收進度，不能再讓當地居民等十年", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p784edcac1f','p784edcac1f','profile','2022-11-26','{"education": ["國立中山大學高階公共政策\n碩士畢業"], "election": "2022-local", "experience": ["第三屆高雄市議會議員、高雄市\n議會民進黨團副總召\n仁武區福清宮主任委員\n仁武分局民防中隊長\n仁武區派出所警友站站長、仁武\n義消分隊顧問團長\n仁武國小志工隊大隊長\n仁武區農會理事長、仁武區農會\n常務監事\n仁武里里長(第1-2屆)\n仁武鄉鄉民代表(第14-15屆)\n仁武同心慈善會理事長、仁武體\n育會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
