INSERT INTO "fact" VALUES('platform:2022-local:p7e37a0d533','p7e37a0d533','platform','2022-11-26','{"district_id": "khh-council-05", "election": "2022-local", "office": "khh_councilor", "text": "1.爭取共構仁武區第三間派出所及社會青年住宅\n2.加速推動仁武產業園區進度\n3.推動大社觀音山國家風景區\n4.推動大社九十八公頃區段徵收\n5.推動大樹區自來水廠為文化觀光古蹟景點\n6.監督鳥松捷運工程進度及爭取規劃延伸路線至仁武、大社\n7.推動升級路口監視器車輛辨識系統\n8. 創造青年就業環境，產業優先錄取在地青年\n9. 落實社會福利政策，扶助身心障礙、老人獨居及中低收入之關懷措施\n10.推動爭取警察執勤專用個人急救包\n11.督促推動捷運楠梓五甲線並連結仁武區域公共交通運輸網.解決交通顛峰塞車情形\n12.極力爭取開闢國道 10 號大社交流道，讓大社.仁武.鳥松.大樹四區生活區車輛流動更為順暢\n13.爭取仁武區國民運動中心.讓大社.仁武.鳥松.大樹居民有安全完善的運動環境\n14.配合落實 2030 中央雙語教學環境.爭取開辦雙語實驗國小\n15.推動規劃一里一親子共融特色公園，設置寵物活動區域", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
