INSERT INTO "fact" VALUES('platform:2022-local:p8f648dc5fb','p8f648dc5fb','platform','2022-11-26','{"district_id": "khh-council-10", "election": "2022-local", "office": "khh_councilor", "text": "①督促市府在111年年底前動工興建捷運黃線。\n②督促市府向中央爭取捷運黃線前鎮區公所站延伸前至前鎮漁港港區內。\n③督促市府加快興建社會住宅。\n④繼續支持、關懷弱勢、艱苦人活動。\n⑤督促市府保障大林蒲居民權益，並儘速完成遷村計畫。\n⑥督促市府在113年年底前完成興建小港國民運動中心。\n⑦督促市府加速增設公托中心與公共托育家園。\n⑧督促市府正視長照人員不足的問題。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
