INSERT INTO "fact" VALUES('platform:2022-local:p9277fb9817','p9277fb9817','platform','2022-11-26','{"district_id": "khh-council-01", "election": "2022-local", "office": "khh_councilor", "text": "一、爭取旗山區籌建殯儀館（非火化場），讓東高雄居民能夠尊嚴地走完最後一哩路。\n二、爭取市府閒置空間成為老人長照或幼兒托育之據點，並推動老幼共學協助分擔照顧責任。\n三、爭取東高雄地方建設，城鄉並進、均衡發展，讓在地青年有更多返鄉就業的機會。\n四、爭取台84線延伸至甲仙區，並持續監督台86線延伸至內門區之進度。\n五、持繽監督於旗山區設置運動中心之進度，完善東高雄運動空間。\n六、重視偏鄉長輩就醫或日常接駁的便利性，並持續改善候車亭、提升安全性。\n七、關注市府對於農民災害相關補助的審查合理性，保障農民權益。\n八、為毒品防制擔任永遠的防毒志工，為打造無毒高雄而努力監督。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC1%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9277fb9817','p9277fb9817','profile','2022-11-26','{"education": ["鼓山國小畢業\n旗山中學初中部畢業\n省立高雄高工畢業\n高雄市立空大法學學士畢業"], "election": "2022-local", "experience": ["現任\n高雄市議員\n旗山天后宮副主任委員\n北高雄家扶中心扶幼委員\n曾任\n光陽工業公司從業員\n民進黨四屆選任全國黨代表\n旗山地區機關聯合員工消費合作\n社經理\n旗山東區扶輪社社員\n高雄市議會民進黨團副總召\n高雄縣第十五、十六屆議員\n高雄市第一、二屆議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC1%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
