INSERT INTO "fact" VALUES('profile:2022-local:p9481daebd3','p9481daebd3','profile','2022-11-26','{"education": ["高雄市三民區莊敬國小\n高雄市三民區陽明國中\n高雄市立新莊高中\n東海大學政治學、法學學士"], "election": "2022-local", "experience": ["立法委員蔡其昌辦公室主任\n高雄市政府教育局機要秘書\n高雄市政府陳菊市長秘書\n高雄市體育會手球委員會主任委\n員\n高雄市第 2、3屆議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p96f82c8eb5','p96f82c8eb5','bulletin','2022-11-26','{"district_id": "khh-council-09", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p96f82c8eb5','p96f82c8eb5','platform','2022-11-26','{"district_id": "khh-council-09", "election": "2022-local", "office": "khh_councilor", "text": "1. 秉持一貫為民服務之精神與理想，為提升市民福祉之政策辯護，推動及展開基層代言急先鋒。\n2. 全心全力監督市政，讓地方百姓繳納的稅款真正做到取之於民、用之於民。\n3. 維護公益，照顧弱勢，扮演官與民之間的橋樑，盡力消弭兩造之間因認知誤差所產生的不公不義之情事。\n4. 監督平衡城鄉之總體發展，督促市政單位用心經營各城鄉地方特色，促銷觀光及文化以推動地方之經濟繁榮。\n5. 重視品德教育、提高生育補助、關懷老人長照、捍衛空汙守護食安、拒絕酒駕、以電能帶動經濟發展，打造一個有願景、有\n未來、宜居、安全及祥和的高雄社會環境。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p96f82c8eb5','p96f82c8eb5','profile','2022-11-26','{"education": ["和春技術學院附設進修學院\n企業管理系。"], "election": "2022-local", "experience": ["1.高雄市高縣退伍軍人協會榮譽理事長。2.高雄市高縣眷村文化發展協會榮譽理事長。3.高雄市高縣山東同鄉會榮譽理事長。4.高雄市關懷公教退休人員協會顧問。5.高雄市黃國山黨部委員。", "6.高雄市黃山埔黨部常委。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p9855161b0b','p9855161b0b','bulletin','2022-11-26','{"district_id": "khh-council-08", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC8%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p9855161b0b','p9855161b0b','platform','2022-11-26','{"district_id": "khh-council-08", "election": "2022-local", "office": "khh_councilor", "text": "1. 要提高公幼、公托及準公托的質與量：增設公幼及公托中心，提高生育津貼補助，減輕家長育兒負擔\n2. 要打造高齡友善環境：增設社區照顧關懷據點，優化長照服務，減輕家庭照顧長者的壓力\n3. 改善空汙：反對南電北送，加速淨零排放時程，加速發展氫能及綠能產業，加速電動公車全面化、設立電動汽機車充電樁\n(站)\n4. 要解決熱區停車位不足問題：增設立體停車場\n5. 持續推動社會住宅：四年內再興建 2 萬戶社會住宅，增加青年及弱勢族群居住比例，落實居住正義\n6. 持續加碼租金補貼，減輕租屋族負擔\n7. 持續推廣城市運動風氣：成功推動高雄銀行培育在地優秀體育選手之後，繼續推動公營事業單位培育在地優秀體育選手，\n完善學校三級培訓制度，並優化現有場館設施\n8. 協助青年就業：迎接未來高科技產業人才需求，積極培育在地人才就業，接軌在地工作機會\n9. 強化監控警示系統：持續改善現有道路監視系統良率，增設巷弄監視器，確保婦幼人身安全\n10. 持續爭取路平：嚴格把關高雄市各道路的施工品質，並減少人孔蓋的設置，確保民眾行的安全\n11. 持續改造傳統市場：全面補強傳統市場硬體設備及改善公廁環境品質，增設機車停車位，提供安全、舒適的購物環境", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC8%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9855161b0b','p9855161b0b','profile','2022-11-26','{"education": ["大同國小、前金國中\n高師大附中、中山醫學院\n國立高雄大學碩士"], "election": "2022-local", "experience": ["高雄市議會第三屆議員、國立高\n雄師範大學博士班(博士候選人)\n、2020高雄市長補選陳其邁競選\n總部發言人、高雄市議會民進黨\n團幹事長、高雄市嘉義同鄉會副\n總幹事、高師大附中校友會創會\n理事長、立法委員國會助理、立\n委趙天麟服務處執行長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC8%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pa6c879148f','pa6c879148f','bulletin','2022-11-26','{"district_id": "khh-council-01", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC1%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pa6c879148f','pa6c879148f','platform','2022-11-26','{"district_id": "khh-council-01", "election": "2022-local", "office": "khh_councilor", "text": "1.督促「內門觀光休閒園區」規劃，維護旗美地區不同宗教文化特色及民俗慶典傳承先民優良傳統文化，活絡東高雄觀光景點\n旅遊產業。\n2.持續推動馬頭山劃設為「國家自然公園」，保護馬頭山地景與豐富的動植物生態。\n3.建請規劃高雄「輕軌、捷運」路線延伸至旗美地區。\n4.爭取台 29 線，由「杉林小份尾往甲仙寶隆」路段拓寬截彎取直，確保民眾交通安全。\n5.建請政府重視旗美地區溪流之防洪、防災工程及農路產業道路舖設維護，保障民眾生命財產安全。\n6.開創青少年、婦幼、新住民就業機會及保障年長者之權益。\n7.建請市府成立「完整農產品物聯網產銷通路」擴展外銷國際市場保障農漁產品收益。\n8.監督「食品安全」及「學童城鄉教育資源落差」維護學生授教權。\n9.督促市府加強規劃社會福利政策，從生育、保育、教養、教育、就學、就業以及新住民老年長輩與身心障礙者之照顧服務，\n協助經濟弱勢族群脫貧計劃之濟助服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC1%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pa6c879148f','pa6c879148f','profile','2022-11-26','{"education": ["內門鄉西門國小畢業。內門\n鄉內門國中畢業。高美醫專\n二專畢業。"], "election": "2022-local", "experience": ["1.前立委鍾紹和服務處旗山區主任", "2.旗山鎮大德里第15、16、17屆里長3.高雄縣縫紉商業同業公會理事長4.高雄縣旗山鎮鎮長5.高雄市旗山區區長6.高雄市第六大隊義消大隊長7.高雄市議會第1、3屆市議員", "8.旗山天后宮副主任委員9.三農宮委員10.興南宮副主任委員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC1%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
