INSERT INTO "fact" VALUES('profile:2022-local:paaca349186','paaca349186','profile','2022-11-26','{"education": ["美國密西根州立大學廣告公\n關與行銷碩士\n高雄醫學大學高齡長照碩士"], "election": "2022-local", "experience": ["台新銀行行銷傳播處襄理\n中央廣播電台公關專員\n張簡秋風社福基金會附設松喬老\n人養護中心主任\n輔英科技大學業界講師\n元智大學資訊傳播學系"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC11%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pad272e8b0a','pad272e8b0a','bulletin','2022-11-26','{"district_id": "khh-council-04", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pad272e8b0a','pad272e8b0a','platform','2022-11-26','{"district_id": "khh-council-04", "election": "2022-local", "office": "khh_councilor", "text": "一、楠梓科技產業園區設置，推動專業進修產學合作，聘用在地人才，增加青年就業，加強周圍建設及生活機能。振興高雄\n經濟，市府不任意舉債。\n二、加速右昌高鐵線連結高雄學園捷運紫線、新台十七線全線通車、鐵路地下化延至楠梓，楠梓火車站站體更新，串聯北高\n雄交通路網。\n三、爭取生育、育兒、托育津貼提高，增設公托、公幼、托嬰中心，減輕家庭經濟負擔。\n四、落實長照福利政策，重視長輩及弱勢安全照護；爭取新住民權益、婦女福利，放寬補助門檻。\n五、重視勞工權益，提供多元就業輔導，培訓產業人才，促進二度就業機會。\n六、持續推動蓮池潭觀光園區，結合舊城古蹟、見城計劃、半屏山，發展高鐵站商圈，創造觀光與文創產業。\n七、爭取左營海軍眷村文化景觀整體規劃，增加興建社會住宅，老舊社區住宅維護。\n八、改善空氣汙染，節能減碳，生活減塑；推動綠能交通、綠能產業，打造健康宜居生活。\n九、爭取學校軟硬體設備更新，網路教學，擴充圖書館藏書，強化英語教學，監督營養午餐品質。\n十、爭取高雄大學特定區公共設施，提升生活機能，設立圖書館，督促文小２國小校舍、兒８多功能大樓、楠仔坑運動中心\n儘速完工、打造後勁溪生態公園。\n十一、爭取左營曾子路與華夏路口多功能活動中心，增設左營第二運動中心，廣設風雨球場。\n十二、推動城市科技化、強化治安網路、網路警察；增設監視器，提升警消裝備，保障市民安全。\n十三、推動「路平專案」、友善人行空間、維護行道樹、無障礙設施、加強排水設施，打造多元公園，增加各年齡層遊具、\n規劃公園友善寵物空間。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pad272e8b0a','pad272e8b0a','profile','2022-11-26','{"education": ["義守大學管理系學士\n高雄師範大學教育學碩士"], "election": "2022-local", "experience": ["高雄市第一、二、三屆議員、高\n雄市第七屆議員、左營區新下里\n里長、十七全黨代表、婦聯會楠\n梓支會主委、左營救國團會長、\n楠梓社會教育站顧問、高雄市龍\n舟委員會主委、博仁慈善會顧問\n、嘉義同鄉會顧問、雲林同鄉會\n顧問。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC4%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pb651ab4c24','pb651ab4c24','bulletin','2022-11-26','{"district_id": "khh-council-07", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pb651ab4c24','pb651ab4c24','platform','2022-11-26','{"district_id": "khh-council-07", "election": "2022-local", "office": "khh_councilor", "text": "【為經濟找活路】1.推動鐵路地下化沿線土地開發及活化並要求制訂「高雄市綠園道自治條例」，導入公共藝術結合文創、觀光、\n休閒、運動產業來活化綠色廊帶綜效，展現園道新風貌。2.推動「高雄消費日」點亮高雄新經濟，營造高雄消費新未來。【為三\n民拚發展】1.推動三民區都市計畫通盤檢討，以平衡區域發展。2.推動「三民區閒置土地及設施」活化或再生計劃（如：加速高\n雄肉品市場遷移、活化公車金獅湖站與中都磚窯廠等場域）來提升及活絡三民競爭力。3.監督三民全民運動中心如期完工並推動\n「三民第二運動中心」加速設立，且結合多功能用途打造更完善運動及培訓空間。【為老幼謀福利】1.推動平價幼托，增設公共\n托育中心及幼兒園來減輕家長負擔，提升幼兒教育品質。2.關心銀髮世代，落實社區長照關懷，推動全齡化公園讓長輩享有更多\n的休閒空間。3.推動中高齡就業投入職場之運作機制及獎勵方案。【為交通更便捷】1.監督輕軌二階大順段施工期間車流順暢，\n降低交通黑暗期的衝擊，避免車流溢流至主幹道，要求儘速建置大順輕軌替代道路，讓三民交通更順暢。2.監督捷運黃線加速動\n工興建，並推動周邊相關接駁規劃更便利【為客家揚文化】推動客家文化及客語傳承並爭取在客家義民節舉辦「客家文化藝術季\n」，結合客家相關團體辦理客家傑出人士薪傳獎及客家音樂、美食民俗技藝等活動。【為觀光創亮點】推動金獅湖觀光再升級，\n點亮金獅湖打造「高雄入口門戶新印象」，創造觀光新價值。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pb651ab4c24','pb651ab4c24','profile','2022-11-26','{"education": ["正興國小、道明中學國中部\n、台南女子技術學院五專部\n室內設計科、正修科技大學\n經營管理研究所碩士"], "election": "2022-local", "experience": ["高雄市第2、3屆議員\n立委侯彩鳳服務處主任\n財團法人大揚教育基金會執行長\n高雄市體育會電子競技委員會主\n委\n正修科技大學兼職講師\n正修科技大學校友會副總會長\n高雄區勞工總工會常務理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC7%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
