INSERT INTO "fact" VALUES('profile:2022-local:pbf82bd2bda','pbf82bd2bda','profile','2022-11-26','{"education": ["1國立高雄應用科技大學工\n業工程與管理系碩士班。2\n國立高雄工專電子科。3高\n雄市瑞祥國中。4高雄縣立\n五甲國小。"], "election": "2022-local", "experience": ["一第3屆高雄市議員二高雄市運\n動健康休閒體驗協會理事長三大\n高雄不動產開發商業同業公會顧\n問四高雄市真善美中小企業跨業\n交流協會顧問五第1、2屆高雄市\n議員六第15、16屆高雄縣議員七\n第8屆鳳山市民代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC9%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pca1534fd78','pca1534fd78','bulletin','2022-11-26','{"district_id": "khh-council-10", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pca1534fd78','pca1534fd78','platform','2022-11-26','{"district_id": "khh-council-10", "election": "2022-local", "office": "khh_councilor", "text": "一、健全社會福利，增加市民權益：督促市政府落實年幼及長者之相關社會福利措施與服務，強化婦女權益與人身安全保障。\n二、活絡地方經濟，創造就業機會：加速推動前鎮漁港改造計畫，創造整體觀光經濟效益，督促市政府規劃發展地方經濟，扶\n助商圈夜市經營，活絡庶民經濟，強化招商引資，創造就業機會，降低失業率。\n三、強化社會治安，保障身家安全：督促市政府加強社會治安之改善，增添警力設備，廣設及維護監視系統，加強社區巡守，\n確實保障市民安全。\n四、改善交通環境，解決交通問題：爭取加速興建國道七號，保障小港市民用路安全，督促市政府增建停車場，紓解社區停車\n位不足問題。\n五、降低空氣污染，補助人民健檢：督促市政府嚴格管控前鎮小港工業大廠，要求提出改善並降低空氣污染，嚴格執行高雄港\n區船隻車輛低硫燃油政策，爭取以空污基金補助市民健康檢查。³\n六、點亮前鎮小港，建設美好家園：督促市政府持續推動新草衙、籬仔內、崗山仔等舊部落都市更新，推動危老建築重建，嘉\n惠地方；儘速完成大林蒲遷村計劃，早日落實居住正義。\n七、加強就業服務，保障勞工權益：督促市政府加強就業服務，保障勞工就業權利，推動就業管道，落實勞動檢查。³³\n八、爭取社宅興建，推動智能住宅示範場域：爭取社會住宅興建，並爭取將智能設施應用在社會住宅上，推動前鎮小港成為智\n能社區示範場域，讓市民住的更安全、更便利。\n九、爭取全齡化公園、保障兒童遊戲權：爭取多元化遊具設施讓老幼能共同遊憩，督促市府落實既有公園遊具維護，保障兒童\n遊戲權。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
