INSERT INTO "fact" VALUES('platform:2022-local:pd5e81d8daa','pd5e81d8daa','platform','2022-11-26','{"district_id": "khh-council-02", "election": "2022-local", "office": "khh_councilor", "text": "(一)爭取阿蓮、田寮、路竹、湖內、茄萣地方建設，促進城鄉均衡發展。\n(二)重視社區發展及關懷據點設立，配合社區需求兼併老人關懷照護措施。\n(三)督促市政改善水利設施，解決各區水患，加強便民措施並加強公共工程管理。\n(四)舉辦地方特產傳統文化活動，推廣地方特色，建立農漁產品品牌，提高促銷能力，增加農漁民所得。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC2%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
