INSERT INTO "fact" VALUES('bulletin:2022-local:pd6d4a2688f','pd6d4a2688f','bulletin','2022-11-26','{"district_id": "khh-council-03", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd6d4a2688f','pd6d4a2688f','platform','2022-11-26','{"district_id": "khh-council-03", "election": "2022-local", "office": "khh_councilor", "text": "1. 持續爭取台61線儘速延伸至永安、彌陀、梓官。\n2. 爭取橋頭科學園區交流道延伸至海線\n3. 持續推動路平、燈亮、水溝清。\n4. 因應極端氣候來臨，要求市府完善保險補助機制。\n5. 加速推動智慧農漁業補助措施。\n6. 推動大岡山地區在地商圈活化、再造榮景。\n7. 推動增設漁業博物館。\n8. 持續推動公有市場改建及更新\n9. 解決空屋率高與社宅興建緩慢，希望達到一區一社宅，推動配對租屋獎勵。\n10. 持續要求危老建築擴大補助及都市更新。\n11. 爭取生育津貼與托育補助要加碼。\n12. 單親家庭優先配對入住社宅。\n13. 爭取高齡長者居家安全設施補助。\n14. 持續推動新闢或更新為親子共融式公園。\n15. 持續推動現有社區及里民活動中心設備維護與更新。\n16. 推動海線海岸觀光開發與設施興建，強化海線觀光資源", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd6d4a2688f','pd6d4a2688f','profile','2022-11-26','{"education": ["樹德科技大學休閒與觀光管\n理系"], "election": "2022-local", "experience": ["中國國民黨20、21屆黨代表\n梓官國際同濟會顧問\n高雄市三山退休消防人員協會顧\n問\n高雄市後備指揮部委顧團組訓顧\n問\n梓官城隍廟常務監察"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC3%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
