INSERT INTO "fact" VALUES('platform:2022-local:pdb769d207d','pdb769d207d','platform','2022-11-26','{"district_id": "khh-council-05", "election": "2022-local", "office": "khh_councilor", "text": "1.凸顯地方農村特色，推動觀光休憩產業，創造樂活新商機。\n2.推動新住民友善照顧政策，保障婦女權益，增進獨居老人健康照護服務。\n3.督促市府全面檢視排水系統，避免雨水無法宣洩造成災情。\n4.監督政府，革新行政效率，落實提升為民服務品質。\n5.督促政府加速改善投資環境，增進市民就業條件。\n6.督促政府落實就業輔導及工安維護。\n7.爭取擴充教學設備，提升教學品質。\n8.堅持照顧基層權益，爭取地方建設經費，全力為地方發聲。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('profile:2022-local:pdb769d207d','pdb769d207d','profile','2022-11-26','{"education": ["大樹國小畢業\n大樹國中畢業\n嘉義師專畢業\n嘉義師院畢業\n高雄師範大學成教所碩士畢"], "election": "2022-local", "experience": ["嘉義縣竹崎國小教師\n國立嘉師實小教師\n行政院南服中心副執行長\n高雄縣議員(第14、15、16屆)\n高雄市議員(第1、3屆)"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pebefe4a168','pebefe4a168','bulletin','2022-11-26','{"district_id": "khh-council-05", "elected": true, "election": "2022-local", "office": "khh_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pebefe4a168','pebefe4a168','platform','2022-11-26','{"district_id": "khh-council-05", "election": "2022-local", "office": "khh_councilor", "text": "幸福家鄉，鄉親共好\n1.監督市政\n2.社區關懷據點，資源整合與運用，長輩在地樂活學習（長輩開心晚輩放心）\n3.學前教育、公托資源彈性增設（減少家長育兒負擔）\n4.防止校園霸凌，學生安心學習（飛鳳用心家長放心）\n5.鄉親用路安全，道路重鋪前置作業，跨單位工作協調討論（平安回家的路）\n6.延長建置捷運系統，建置完善大眾交通（增加鄉親交通方便）\n7.培訓社區營造人才、青年人力回流鄉里、婦女二度就業、銀髮人力運用（老中青人力運用）\n8.共推跨越合作，休閒觀光農業（推廣產業增加收入）\n9.爭取國營與在地大廠，增加錄取在地子弟（子弟在地工作，就近照顧家庭）\n10.公共空間環境、閒置空間再利用（更多休閒地方）", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC5%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
