INSERT INTO "fact" VALUES('platform:2022-local:pefafc6bfe5','pefafc6bfe5','platform','2022-11-26','{"district_id": "khh-council-10", "election": "2022-local", "office": "khh_councilor", "text": "1.中小學全面雙語教育，為孩子奠定國際競爭力。\n2.增設夜間籃球場及複合式運動區，滿足市民運動需求。\n3.推動寵物公園，落實動物生命及環境教育。\n4.加速國道七號興建，守護沿海路周邊居民交通安全。\n5.完善長照2.0減輕年輕人照顧負擔，出外打拼沒煩惱。\n6.成立長照局，讓長照推動更有效率，照顧長輩更周全。\n7.嚴厲監督空污，提升公共運輸效能。\n8.落實青年社會住宅，有巢讓年輕人安心築夢。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC10%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
