INSERT INTO "fact" VALUES('platform:2022-local:pf0705e5ab8','pf0705e5ab8','platform','2022-11-26','{"district_id": "khh-council-06", "election": "2022-local", "office": "khh_councilor", "text": "1. 推動灣區舊港觀光廊帶，帶動鼓鹽商機 2. 爭取旗津區內與聯外交通建設，解決交通困境\n3. 專業監督高雄治水規畫，因應極端氣候 4. 重視在地歷史文化傳承，兼顧傳統潮流\n5. 健全嬰幼兒教養托機制，打造幸福高雄 6. 倡議城市淨零排放路徑，打造健康高雄\n7. 促進經濟產業多元發展，打造富裕高雄 8. 加速都市更新舊城開發，打造公義高雄\n9. 完善社會安全網絡建置，打造安心高雄 10. 推廣城市治理智能應用，打造智慧高雄", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC6%E9%81%B8%E5%8D%80.pdf','2026-10-02T15:34:15Z');
