INSERT INTO "fact" VALUES('platform:2022-local:p0c53d0c54a','p0c53d0c54a','platform','2022-11-26','{"district_id": "kee-council-05", "election": "2022-local", "office": "kee_councilor", "text": "1. 改善基金公路塞車之短期改善規畫已有成效，賡續推動長期新闢道路以達徹底改善\n2. 武崙溪淹水整治之短期改善規畫已於五年內展現成效，賡續監督與推動中期與長期改善\n3. 活化與改造老舊社區與公共設施，推動監督增建停車場設施\n4. 持續監督推動捷運建置，並爭取相關交通便利措施\n5. 建置各區域所需之籃球場與游泳池等，相關運動休閒場所與設施\n6. 秉持初衷監督市政與為民服務", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
