INSERT INTO "fact" VALUES('platform:2022-local:p14d633690b','p14d633690b','platform','2022-11-26','{"district_id": "kee-council-02", "election": "2022-local", "office": "kee_councilor", "text": "一、安心環境 - 全面升級數位化監視器。\n二、推動長照 - 爭取設置複合園區。\n三、共融公園 - 推動親子公園。\n四、推出寵物友善政策 - 建置基隆第一家寵物公園。\n五、持續監督市區道路平整，維護市民通行安全。\n六、協助清寒家庭、身障人士、獨居長者及弱勢族群爭取社會福利。\n七、積極推動市政建設，督促市府提昇行政效率。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p14d633690b','p14d633690b','profile','2022-11-26','{"education": ["仁愛國小\n銘傳國中\n基隆海事職業學校\n崇右技術學院副學士\n海洋大學輪機系碩士"], "election": "2022-local", "experience": ["基隆市林右昌市長秘書\n基隆市信義區孝忠里第二十屆里長\n基隆市市議員陳東財服務處助理\n國際獅子會 300F 區 2021 年基隆港獅\n子會會長\n基隆市深澳坑警友站副站長\n基隆市義警中隊副中隊長\n基隆市陳胡姚宗親會理事\n基隆市海龍潛水游泳協會理事\n基隆市義消第一大隊\n義消宣導信二分隊顧問\n基隆市銘傳國中家長會副會長\n基隆市登山協會監事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p2ea4ebdaec','p2ea4ebdaec','bulletin','2022-11-26','{"district_id": "kee-council-03", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p2ea4ebdaec','p2ea4ebdaec','platform','2022-11-26','{"district_id": "kee-council-03", "election": "2022-local", "office": "kee_councilor", "text": "1. 持續推動本市都市更新工作，督促市政府擬定全市都市更新期程，全力推動仁愛區都市更新作業。\n2. 推動崁仔頂漁市面貌，改善環境，打造成為台灣築地，並督促市政府將周邊環境打造成為海鮮美食聚落。\n3. 督促市政府正視獅球嶺步道改善及環境維護工作。\n4. 督促市政府發展紅淡山、獅球嶺觀光登山活動，吸引外地人利用假日時間搭乘大眾運輸工具前來登山，同時帶\n動市區觀光產業發展。\n5. 督促市政府改善假日市區塞車問題，妥善進行道路交通維持工作。\n6. 督促市政府改善少將頂、南榮新村、獅球嶺等地區高地供水問題。\n7. 督促市政府對於公園街、自來街等老舊社區進行環境改善，活化商圈，再造榮景。\n8. 督促市政府對鄰里公園盡速進行兒童遊具改善，並適度改造鄰里公園為社區共融公園。\n9. 督促市政府強化對於弱勢、身心障礙人士的生活照顧，協助鄰里推動相關照顧工作。\n10. 督促市政府增加公托、公幼的名額，減輕年輕父母的負擔，並推動幼兒智慧教育。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p2ea4ebdaec','p2ea4ebdaec','profile','2022-11-26','{"education": ["國立台灣大學管理學院碩士\n在職專班資訊管理組畢業"], "election": "2022-local", "experience": ["基隆市議會第十九屆議員\n基隆律師公會理事長\n基隆市政府法律顧問、市政顧問\n基隆市政府婦女權益促進會委員\n基隆市義消總隊顧問\n基隆市蔬菜公會法律顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p4538d68136','p4538d68136','bulletin','2022-11-26','{"district_id": "kee-council-07", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p4538d68136','p4538d68136','platform','2022-11-26','{"district_id": "kee-council-07", "election": "2022-local", "office": "kee_councilor", "text": "1. 盡速推動確認捷運路廊、務必及早通過環境影響評估、讓捷運工程進度早日落實、以帶動地方繁榮。\n2. 督促市府落實長照 2.0 及降低公辦幼托收費政策、敦使民間疾苦充分改善。\n3. 北五堵研發新鎮進度一直落後，未來將督促市府加緊規劃進度、以期地方因而共榮共享、並遏止人口外移及造就\n更多就業機會。\n4. 監督市府落實路要平、水要通、燈要亮的基本建設政策，使基隆成為一個既宜居又友善的城市。\n5. 爭取更多經費淘汰老式監視系统，品質提昇、數量務必需要增加以彌補警力不足，確保人民居家環境安全。\n6. 在中央政策山坡地比例對基隆解編放寬後，將建議市府能借此機會簡化手續及開放既有道路用地販售，做為容積\n移轉之條件，推動都市更新案件使多數危老能更新改建。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p4538d68136','p4538d68136','profile','2022-11-26','{"education": ["五堵國小\n安樂國中\n立德中學\n南亞工專畢業"], "election": "2022-local", "experience": ["國民黨七堵區黨部青工會長\n百福社區理事長\n後備軍人輔導中心主任\n基隆市議會第 16、17 屆議員\n第 18 屆副議長\n第 19 屆議長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p5d30348128','p5d30348128','bulletin','2022-11-26','{"district_id": "kee-council-06", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC6%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%85%AD%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5d30348128','p5d30348128','profile','2022-11-26','{"education": ["天主教輔仁大學臨床心理學系\n畢業"], "election": "2022-local", "experience": ["左下角工作室，投入社區工作、\n關注在地議題\n基隆市議員王醒之辦公室研究員，\n協助法律諮詢、陳情案件，投入政\n策研究，針對市公車虧損改善、暖\n暖國道客運及公車Ｒ８６問題、東\n勢街 1.2 公里電纜地下化、過港興隆\n街懸臂式步道、八堵天橋拆除、碇\n內垃圾清運點等提出改革方案，持\n續針對民生議題發聲！"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC6%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%85%AD%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p64cf4c6164','p64cf4c6164','bulletin','2022-11-26','{"district_id": "kee-council-05", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p64cf4c6164','p64cf4c6164','platform','2022-11-26','{"district_id": "kee-council-05", "election": "2022-local", "office": "kee_councilor", "text": "一、候車空間改善 : 安樂沿線候車空間，過去四年，顯著改善，長庚醫院站擴建，友善人行道，之豪將繼續監督改善。\n二、路平品質改善 : 麥金路示範道路計畫，基金一二三路改善計畫，皆在過去四年內陸續推動完工，之豪將繼續監督推動地下管線更換與路面\n改善。\n三、親子特色公園 : 過去四年，成功催生安樂三期 ( 四維 ) 親子公園，基隆市內尚有眾多公園空間安全、品質、可玩性，有提升之空間，之豪將\n持續監督改善。\n四、監督基隆捷運 : 基隆捷運計畫在過去四年內，升级為中運量捷運，目前已在綜合規畫階段預計近期可完成報部報院進行核定。屆時，捷運與\n基隆各區之間的接駁方案，將會決定基隆市未來之通勤模式，之豪將持續監督捷運進度。\n五、推動國際交流 : 過去四年，台灣躍升國際矚目焦點，基隆市在後疫情時代，需要積極拓展國際交流，不僅是商機，更是城市發展之關鍵。之\n豪將持續監督基隆的國際交流。\n六、推動行政改革 : 基隆市行政制度需要在國土規劃與區域整合下，審慎重新思考各種可能性。基隆未來發展之利基關鍵為能否有效創建有效\n率之機構單位，吸引優質行政擘劃官僚，處理捷運與新市鎮發展之複雜課題，之豪將持續監督行政改革。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p64cf4c6164','p64cf4c6164','profile','2022-11-26','{"education": ["國立臺灣大學政治學研究所\n碩士\n加拿大英屬哥倫比亞大學學士"], "election": "2022-local", "experience": ["國立政治大學亞太所博士班\n基隆青年陣線前理事長\n義消安樂第二分隊總顧問\n基隆張廖簡宗親會監事\n總統府諮議"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p713a68ddc7','p713a68ddc7','bulletin','2022-11-26','{"district_id": "kee-council-02", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p713a68ddc7','p713a68ddc7','platform','2022-11-26','{"district_id": "kee-council-02", "election": "2022-local", "office": "kee_councilor", "text": "1. 積極推動國中、小雙語教學課程，規劃良好英語教學環境。\n2. 積極要求市政府將田寮河的景觀改造、河水整治給市民一個運動休閒的地方。\n3. 積極爭取經費改善易淹水地區路面及排水系統，以利市民免受淹水之苦。\n4. 促請自來水公司更換老舊管線，改善高地供水加壓設備，增加大型蓄水池，以利民眾供水問題。\n5. 促請市政府建設兒童、青少年的活動場所。\n6. 促請市政府維護全市砲台，保存文化資產。\n7. 促請市政府持續市民安全意外保險制度。\n8. 促請市政府加強婦幼、身心障礙、老年、失業者等弱勢族群照顧與保護。\n9. 積極推動救急救災通報系統，健全監視系統，做到治安無死角。\n10. 積極要求市政府路平專案並改善騎樓的地面高度一致，推動市容整頓，加強公共建設，營造美麗新基隆。\n11. 促請市府打造「基隆科學園區」，串聯成為北台灣科技產業廊帶，重整活化六堵工業區、大武崙工業區、北台科技園區，創造\n就業機會，留住優秀人才。\n12. 積極推動維護基隆海域自然生態。\n13. 積極爭取寵物公園，打造一個動物友善城市。\n14. 強力監督基隆市田徑場主建築拆除重建 ( 含停車場 ) 及周邊運動服務設施改善工程，施工進度及品質提供市民優質運動空間。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
