INSERT INTO "fact" VALUES('bulletin:2022-local:p9511ed61a5','p9511ed61a5','bulletin','2022-11-26','{"district_id": "kee-council-03", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p9511ed61a5','p9511ed61a5','platform','2022-11-26','{"district_id": "kee-council-03", "election": "2022-local", "office": "kee_councilor", "text": "一座城市的核心是人，唯有以人為本、用心思考、行動向前，才能與基隆共同奔向璀燦的未來！\n1. 以爭取忠一路及市中心地下道改造的成功經驗，進而推動步行城市，持續爭取系列友善行人和空間再造計畫，\n改善市容、提升生活品質、串連商圈、吸引觀光客。\n2. 以推動委託行再起的成功經驗，持續進行地方創生及青年返鄉計畫，同時輔導青年創業永續發展，並將週邊仁\n愛市揚、廟口夜市、孝三美食、歷史廟宇串連，目標提升觀光及經濟產值，打造專屬基隆特色文化品牌。\n3. 以爭取廟口汰換自來水管線的成功歷程，持續監督自來水公司檢視老舊管線汰換，同時改善道路品質、活化停\n車空間。\n4. 以爭取成功國小改造經驗，持續推動校園核心改造計畫，讓各校發展特色，資源進入社區，融入鄰里公園，讓\n校園及社區共融共好。\n5. 以成功增設育仁休閒公園經驗，持續爭取活化閒置空間，提升社區生活品質。\n6. 因應高齡化趨勢，持續爭取日照中心設置仁愛區，讓老有所托，子女上班安心。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9511ed61a5','p9511ed61a5','profile','2022-11-26','{"education": ["國 立台灣 海 洋 大 學 航 運 管 理 所\n碩士\n開南大學法律學系\n基隆二信高中\n基隆聖心國中\n基隆仁愛國小"], "election": "2022-local", "experience": ["基隆市議員\n基隆市登山協會理事長\n基隆市體育會跆拳道委員會主委\n基隆市後備指揮部仁愛區輔導中心主任\n基隆市體育會籃球委員會副主委\n慶安宮顧問\n基隆市 YesWeCan 夢想起飛協進會\n榮譽理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p9676d94c25','p9676d94c25','bulletin','2022-11-26','{"district_id": "kee-council-08", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p9676d94c25','p9676d94c25','platform','2022-11-26','{"district_id": "kee-council-08", "election": "2022-local", "office": "kee_councilor", "text": "用心服務、守護原民\n增編年度經費及地區協進會活動經費\n文化 : 增編經費、推展族語、傳承傳統手工藝、促進都市原鄉交流\n教育 : 兒童課輔、充實原民教育課程、推展部大教育取得大專學位、原住民子女教育獎助學金、持續爭取原住民部\n落大學經費\n幼老 : 增加育兒津貼、托育津貼補助、幼教福利\n關懷長者，增設“文化健康站 ”、老人假牙補助\n青年 : 設立青創基地、青年會議、觀摩交流、原植培力青年\n勞工 : 安全衛生講座、職安卡訓練、勞工權益安全網\n社福 : 原住民微型意外險續辦 ( 免保費、團保 )、房屋建構及修繕補助、租屋租金補貼、健保自付額補助\n就業 : 就業媒合、職業訓練、暑期大專工讀、婦女創業研習班、職業汽車訓練補助、取得專業級證照市府補助\n體育 : 增編體育經費、促進縣市交流、培植原民體育人才、辦理各項體育活動\n經建 : 爭取“一區一聚會所”、爭取七堵社會住宅原住民保留戶、改善會館週邊環境、完成地區經建設備", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
