INSERT INTO "fact" VALUES('bulletin:2022-local:pb8d37de6ca','pb8d37de6ca','bulletin','2022-11-26','{"district_id": "kee-council-01", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pb8d37de6ca','pb8d37de6ca','platform','2022-11-26','{"district_id": "kee-council-01", "election": "2022-local", "office": "kee_councilor", "text": "1. 推動市府招商引資，重視基隆三大工業區 ( 五堵、六堵、大武崙 ) 再造計畫，吸引各類廠商進駐基隆，創造就業\n機會，讓基隆人才回流，增加家庭聚時間。\n2. 結合「四師平台」，留住在地建築師、律師、醫師、會計師服務市民、企業。\n3. 推動雨天跑場、現代槌球場，區域室內運動中心，強健市民身心；推動親老館，館內設置老人、兒童運動中心\n及教練，減少老人肌少症、培養兒童健康運動習慣，減少健保支出及家庭負擔。\n4. 落實社會福利，檢討政府釋出閒置空間，奬勵社區力量整合民間資源做合理之配置運用。\n5. 推動市府成立公托中心，鼓勵企業成立托嬰中心，協助新手爸媽適應新生活。\n6. 增加婦女生育及相關疫苗施打補助；以優惠稅率鼓勵企業提供有薪育嬰假。\n7. 要求市政府設置青年對話平台，鼓勵年輕人參與公共事務。\n8. 推動新豐街 303 巷聯外道路計畫，以消解新豐街塞車困境。\n9. 爭取推動三軍總醫院於基隆成立教學醫院及海洋醫學研究中心。\n10 持續推動基隆港內客外貨政策，促進港務再生計畫，提振基隆經濟活力。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
