INSERT INTO "fact" VALUES('platform:2022-local:pc5ca833edd','pc5ca833edd','platform','2022-11-26','{"district_id": "kee-council-02", "election": "2022-local", "office": "kee_councilor", "text": "一、民意優先監督市政\n二、推動後疫情新時代\n三、銀青共居活潑陪伴\n四、婦幼共融多元照護\n五、社會關懷全民參與\n六、走出校園進入社區\n七、力倡國民健康運動\n八、重構田寮生態廊道", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc5ca833edd','pc5ca833edd','profile','2022-11-26','{"education": ["東信國小\n暖暖中學\n崇右技術學院應用外文系\n台北市立大學競技運動訓練\n研究所碩士"], "election": "2022-local", "experience": ["國家網球代表隊員\n土地銀行高級辦事員\n電視台網球轉播球評\n基隆流行運動舞協會理事長\n基隆市議會第 19 屆市議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pc6805a606d','pc6805a606d','bulletin','2022-11-26','{"district_id": "kee-council-01", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pc6805a606d','pc6805a606d','platform','2022-11-26','{"district_id": "kee-council-01", "election": "2022-local", "office": "kee_councilor", "text": "1. 支持公民權行使年齡下修至 18 歲，讓年輕新世代皆能參與公共事務，用自己的公民權，決定自己的未來。\n2. 堅決反對台電四接填海造地，保護海洋生態及人民安全。\n3 爭取捷運直達基隆站，串聯北北基都會生活圈，讓市民通勤更便利。\n4. 繼續爭取中正路公車修理廠開發為第二座東岸商場，引進大型購物中心及停車場，帶動三沙灣地區整體發展。\n5. 爭取推動義二路及和平島老街再造，提升優質生活環境並推廣低碳旅遊，打造休閒新據點。\n6. 監督東五軍港遷移進度，盡速打造郵輪產業園區，帶動產業創新，創造就業機會，振興基隆經濟。\n7. 振興傳統市場轉型，加速推動富貴市場拆除並改建為觀光市場，提升哨船頭地區的生活機能，促進就業，帶動繁榮。\n8. 爭取閒置低度利用之國有地，進行綠美化改造，增加市民多元休憩空間。\n9. 因應少子化、老年化社會現象，爭取建置社區銀髮醫療與長照系統。\n10. 解決高地用水需求，爭取加速更換老舊自來水管線，捍衛民眾用水權。\n11. 爭取台電變電箱地下化，保障人民用電安全。\n12. 推動親善動物城市，加強宣導動保法教育，廣設動物友善空間及設施，打造友善兼具休閒娛樂的毛小孩保護園區。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc6805a606d','pc6805a606d','profile','2022-11-26','{"education": ["國立臺灣海洋大學法律研究所碩\n士\n省立基隆高中\n正濱國中\n正濱國小"], "election": "2022-local", "experience": ["基隆市第 16、17、18、19 屆議員\n大沙灣經濟文化發展促進會創會長\n基隆市警察志工中隊中隊長\n國民黨中央黨部組發會副主委\n中央獅子會第 38 屆會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
