INSERT INTO "fact" VALUES('platform:2022-local:pc731cbdeae','pc731cbdeae','platform','2022-11-26','{"district_id": "kee-council-07", "election": "2022-local", "office": "kee_councilor", "text": "【促進地方經濟發展及創造就業機會】\n一、賡續督促市府加速「北五堵新市鎮」計畫落實執行以利帶動地方經濟繁榮。\n二、爭取市府加速提高六堵、大武崙等二大工業區容積與建蔽率，並限期提出轉型改進方案，以吸引廠商進駐帶動地方產業發展與就業機會。\n【改善交通環境及提升道路品質安全】\n三、賡續爭取光明路人行道擴寬為七米寬，成為七堵區「光明路示範道路計畫」。\n四、爭取市府將七堵區工建路及工建西路兩側人行道拓寬，串聯基隆河自行車道及台五線，並爭取將共享自行車往北延伸到七堵運用示範道路空間，七堵各地公園\n以及基隆河自行車道串連成為自行車路網，一步一步建立綠色運輸動脈。\n五、爭取市府積極將本市捷運規劃，沿線地區都市計畫通盤檢討包含計畫時程、水與綠環境改善、推動社會住宅。\n【打造休憩場域及增建市民公共空間】\n六、賡續爭取規劃基隆河沿岸步道串聯與優質化及整治親水休閒遊憩區。\n七、賡續爭取百福公園重新整體大改造，讓七堵區居民能真正擁有大型活動公園。\n八、賡續爭取現泰安公園規劃中朝生態公園予以規劃施作，讓泰安社區擁有鄰里公共活動空間。\n九、賡續爭取七堵區 - 富民里公園 - 崇義河濱公園土地闢建公園經費，建置成為基隆河自行車道的休憩地點。\n十、爭取建請市府將七堵區明德國中禮堂改為「多功能活動中心」。\n十一、爭取市府將七堵區長興公園重新再造，並設置地下停車場一併解決活動空間及停車問題。\n【加強公托長照資源及提升社區服務】\n十二、賡續爭取市府編列經費，補助市民家中患有重大疾病雇請外勞看護或送安養專業機構治療者，予以酌情補助經費減輕其家庭經濟負擔。\n十三、賡續爭取全市幼兒公托班免抽籤入學，以減輕市民經濟負擔。\n十四、賡續社區闔家歡增加篩檢名額，以利市民健康保健。\n十五、賡續督促市府加強對本市各弱勢團體身心障礙者之福利爭取。\n十六、爭取調升鄰長事務費比照雙北以保障權益，同時也提供市民更優質服務。\n耿直親切 輝動為民 堅定信念 深耕基層", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc731cbdeae','pc731cbdeae','profile','2022-11-26','{"education": ["七堵國小\n明德國中\n國立基隆商工"], "election": "2022-local", "experience": ["基隆市議會第 15、16、17、18、19 屆\n市議員中隊長\n前基隆市團管區七堵區、暖暖區後備\n軍人聯絡官督導官\n七堵國小、明德國中、私立光隆家商、\n國立基隆高中家長會會長\n七堵區團委會會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pda246e75d9','pda246e75d9','bulletin','2022-11-26','{"district_id": "kee-council-04", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%9B%9B%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pda246e75d9','pda246e75d9','platform','2022-11-26','{"district_id": "kee-council-04", "election": "2022-local", "office": "kee_councilor", "text": "西岸文化展現：推廣「蒐集舊地名活動」，從罾仔寮、鬼仔坑、碼頭、流籠頭、香蕉湖、仙洞、火號仔、白米甕、外木山、孚基仔、內木山、\n大竿林、烏橋頭、蚵殼港等中山區各地舊地名，以「東歷史場景、西貨漁博覽」推動西岸風情文化觀光廊帶。\n社福友善城市：推動基隆社會安全網建置，發展銀青共融室內場所，監督全市公共場所完整設置無障礙空間。推動滿六個月寶寶施打免\n費 13 價肺炎鏈球菌疫苗，中山區長者免費全口假牙、就醫搭乘計程車由敬老卡補助，中山區小巴公車延伸路線直達長庚醫院。\n交通快捷便利：協調中山區城際快捷客運 1813D 通車成功，持續完善中山區第二條城際快捷客運 1550B 從中和路發車。推動市內公車持\n續發展區域跳蛙公車，市民遊客區域移動更便利。\n智慧海港城市：爭取公車客運到站資訊合併，到站準確報時系統優化，市內道路路段維修資訊、公有停車場資訊、客輪船舶靠港資訊，\n並爭取增設智能大數據即時看板。\n樂活宜居：積極爭取設置公有立體停車場，持續爭取親子全齡遊憩公園、寵物友善公園，監督地下公共管道纜線 ( 自來水、瓦斯 ) 施工及\n路面鋪設規範，確保路面平整。主張廢除機車二段式左轉。\n綠能環保護海：推動市政、議政公文系統無紙化，全市增設充電站，爭取設置市區 UBIKE 租還點。推動協和電廠轉型燃氣電廠改善空氣\n品質，推動採用 FSRU。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%9B%9B%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pda246e75d9','pda246e75d9','profile','2022-11-26','{"education": ["新埔工專機械工程科\n經國管理暨健康學院人力資源系\n國立臺灣海洋大學人文社會學院\n海洋文化所碩士論文口試中"], "election": "2022-local", "experience": ["民主進步黨基隆市黨部第 17 屆執行長\n立法委員何志偉國會辦公室主任\n基隆市雞籠山國際青年商會 2022 會長\n泰翔會計事務所業務主任"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%9B%9B%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
