INSERT INTO "fact" VALUES('profile:2022-local:pdc038109e9','pdc038109e9','profile','2022-11-26','{"education": ["金山國小\n金山國中\n光隆商職\n經國管理學院\n國立海洋大學航管系企管組碩士"], "election": "2022-local", "experience": ["62 年至 104 年源成魚行負責人\n基隆花藝設計協會創會會長\n工商經營研究社全國第四任理事長\n基隆如意同濟會第三任會長\n基隆光華獅子會 18、19 屆理事長\n基隆仁愛慈善婦女會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%89%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe0c873075f','pe0c873075f','bulletin','2022-11-26','{"district_id": "kee-council-07", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe0c873075f','pe0c873075f','platform','2022-11-26','{"district_id": "kee-council-07", "election": "2022-local", "office": "kee_councilor", "text": "1、 增進城市區域性環境綠美化，友善婦幼、銀髮族。爭取閒置空地，高架橋下規劃綠地，同時設置銀髮族與親子\n的活動設備，以達到老幼共融之目的。\n2、 區域性推動婦幼文教發展關懷服務，實施一里一據點。\n3、帶動銀髮身心健康發展活動企劃與長期照顧服務產業。\n4、 促進北五堵國際研發新鎮規劃案，增加在地就業機會，吸引青年返鄉，帶動產業發展。\n5、 督促七堵社會住宅興建案，進而輔導在地青年人創業計畫申請。\n6、 促進基隆捷運計畫案週邊交通改善，提升交通網絡發達。\n7、 增設風雨運動場、寵物公園、兒童設施、銀髮設施，提供七堵區民眾雨天的青少年、親子活動空間。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe0c873075f','pe0c873075f','profile','2022-11-26','{"education": ["經國管理暨健康學院畢業"], "election": "2022-local", "experience": ["基隆市政府林右昌市長秘書\n基隆市達摩愛心會執行長\n民主進步黨基隆市黨部第 18 屆執委\n民主進步黨基隆市黨部第 17 屆評委\n基隆市女童軍會監事\n基隆市曾姓宗親會監事\n海洋大學法律研究所"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe2fb1316f3','pe2fb1316f3','bulletin','2022-11-26','{"district_id": "kee-council-06", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC6%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%85%AD%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe2fb1316f3','pe2fb1316f3','platform','2022-11-26','{"district_id": "kee-council-06", "election": "2022-local", "office": "kee_councilor", "text": "1. 爭取廣設風雨操場。\n2. 爭取停車空間。\n3. 爭取暖暖水源地成為水資源生態教育文創園區。\n4. 增設銀髮族健身俱樂部。\n5. 爭取長者所需，日照、安養、養護長照機構。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC6%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%85%AD%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe2fb1316f3','pe2fb1316f3','profile','2022-11-26','{"education": ["經國學院學士"], "election": "2022-local", "experience": ["基隆市議會第十八、十九屆議員。\n基隆市第十八屆、十九屆里長\n( 暖暖區碇祥里 )。\n碇祥社區發展協會理事長。\n疼厝邊關懷協會理事長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC6%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E5%85%AD%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe4e53fab22','pe4e53fab22','bulletin','2022-11-26','{"district_id": "kee-council-02", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe4e53fab22','pe4e53fab22','platform','2022-11-26','{"district_id": "kee-council-02", "election": "2022-local", "office": "kee_councilor", "text": "一、堅決反對台電協和電廠改為天然氣發電，堅決反對填海造陸興建第四天然氣接收站。\n二、強力監督市府早日完成全市污水處理接管，讓田寮河早日清澈並興建田寮河親水區。\n三、強力要求自來水公司徹底改善大深澳坑地區高地供水，建構穩定高地供水網絡。\n四、爭取本市各項社會福利補助應與雙北標準一致，不應淪為二等公民。\n五、爭取本市積極活化信義區老舊眷舍、校舍，提供民眾作有效之利用。\n六、賡續爭取更多 WOW-BUS 跳蛙公車路線，便利民眾搭乘的快捷公車。\n七、爭取市府將原「基稅莊」活化使用，闢建為青年住宅或培育青年運動成長空間。\n八、嚴格監督政府落實長照政策及老人福利並應充實各里老人健康休憩設施。\n九、爭取深澳坑路 86 巷口交通號誌，改善微笑台北附近地區交通擁塞問題。\n十、積極爭取 62 快速道路增設槓子寮交流道，以利廣大深澳坑地區通勤民眾使用。\n十一、強力監督天外天空氣品質及保麗龍處理方式，改善信義區空氣品質。\n十二、爭取放寬本市老人三節慰問金審核標準，落實敬老愛老政策。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe4e53fab22','pe4e53fab22','profile','2022-11-26','{"education": ["① 基 隆 市 中 興 國 小 畢 業。\n② 基 隆 市 銘 傳 國 中 畢 業。\n③ 國 立 基 隆 高 中 畢 業。\n④銘傳大學中文系畢業。"], "election": "2022-local", "experience": ["①國立台灣海洋大學海洋法律\n研究所在學中。\n②陽信銀行辦事員。\n③市議員韓良圻服務處助理、執行長。\n④基隆市公寓大廈協會理事長。\n⑤基隆市宜蘭同鄉會理事。\n⑥信義區守望相助隊中隊長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe6b713b78b','pe6b713b78b','bulletin','2022-11-26','{"district_id": "kee-council-07", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe6b713b78b','pe6b713b78b','platform','2022-11-26','{"district_id": "kee-council-07", "election": "2022-local", "office": "kee_councilor", "text": "1. 協助七堵區校園周邊環境改善，優化教育品質，提升學童學習成效。\n2. 爭取基隆市第三處身障洗車中心，設立於七堵區為弱勢族。\n3. 開元停車場拆除後爭取車棚綠能，全面運用太陽能板增設汽機車加電站、電池交換站。\n4. 爭取百福車站汽機車停車處設綠能雨陽棚。\n5. 打造社區公園是我的家，管理公園硬體建設之維護，落實花草樹木照護修剪。\n6. 犬貓照護 : (1) 協助流浪在外毛小孩，認養給予一個溫暖的家。(2) 爭取大型寵物公園選址在百福公園，另外一里\n一處設置小型寵物公園。(3) 推動催生爭取寵物銀行第二期工程 - 於寵物銀行周邊增闢墓園植葬生命園區。\n7. 全面發展七堵鐵道公園。\n8. 基隆捷運之後續，攸關七堵區未來的發展，督促基隆市政府落實基隆捷運建設。\n9. 國民運動中心 : 七堵區社宅旁爭取興建基隆市第二座國民運動中心，以嘉惠市民。\n10. 推動串聯基隆河自行車步道，強化步道周邊綠美化及公廁設施。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe6b713b78b','pe6b713b78b','profile','2022-11-26','{"education": ["一、猴洞國小", "二、瑞芳國中", "三、聖心高中", "四、私立崇右企專", "五、國立空中大學生活科學系畢"], "election": "2022-local", "experience": ["一、現任第 19 屆基隆市議員", "二、第 18 屆基隆市議員", "三、現任基隆市警察之友會第三分局第三辦事處主任", "四、百福巡守隊顧問", "五、義消七堵第一二婦宣分隊顧問", "六、中信金融管理學院金融管理研究所研究生"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC7%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%B8%83%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf01251f3d6','pf01251f3d6','bulletin','2022-11-26','{"district_id": "kee-council-05", "elected": true, "election": "2022-local", "office": "kee_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf01251f3d6','pf01251f3d6','platform','2022-11-26','{"district_id": "kee-council-05", "election": "2022-local", "office": "kee_councilor", "text": "接棒基隆，延續光榮！過去驊珈擔任蔡適應立委服務處執行秘書 6 年期間，辦理 8 千多件陳情案，看見基層遇見的大小問題，更\n在 6 年服務期間，協助推動各項公共建設執行及完成：大武崙基金一二三路道路改善、大武崙溪整治、基隆安和親子公園改善、\n壯觀社區高地供水改善、自強隧道內人行道上自來水管遷移、橘郡社區候車亭改善、基金一路湖海路國家新城電桿下地、安一路\n排水改善等。\n未來驊珈將繼續傾聽基層的聲音，希望透過進入議會殿堂改善並提升市民生活品質，這是我目前規劃完成目標：\n1. 推動安樂區公共污水管線全面完成佈設接管。\n2. 監督大武崙森林公園興建符合在地需求。\n3. 推動情人湖公園週邊再生計畫。\n4. 推動劉銘傳隧道週邊停車空間設置。\n5. 推動增加安一路週邊停車空間。\n6. 推動設立寵物友善公園。\n我支持 18 歲公民權修憲案，我也將持續推動年青人共同關心基隆、關心生活，召集大家一起「顧家鄉，拚未來」！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf01251f3d6','pf01251f3d6','profile','2022-11-26','{"education": ["長榮大學會計資訊學系學士\n國立基隆女子高級中學"], "election": "2022-local", "experience": ["立法委員蔡適應服務處執行秘書\n基隆市魯冰花文化促進會理事長\n台灣頭國際文化交流協會總幹事\n基隆市野百合文化促進會幹事\n基隆市吳姓宗親會\n基隆市小英之友會\n104 年全國大專 優秀青年"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/20%E5%9F%BA%E9%9A%86%E5%B8%82/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E5%9F%BA%E9%9A%86%E5%B8%82%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1_%E7%AC%AC%E4%BA%94%E9%81%B8%E5%8D%80.pdf','2026-10-03T01:15:31Z');
