INSERT INTO "fact" VALUES('platform:2022-local:p1dfe78406f','p1dfe78406f','platform','2022-11-26','{"district_id": "cyq-council-06", "election": "2022-local", "office": "cyq_councilor", "text": "一.縣政發展：推動阿里山、曾文水庫觀光產業，帶動地方繁榮。\n二.社會福利：關心少子化問題及弱勢族群，爭取長者兒童婦女福利。\n三.鄉里建設：爭取村里道路改善，產業道路整建鋪設，農產品運輸的便利。\n四.興建水利：推動智慧農業促進產業升級，鼓勵年輕人回鄉發展，爭取地方防洪治水工程，維護人民\n財產安全。\n五.人文教育：重視新住民民生、教育與福利，促進族群融合。\n六.產業效益：結合人文鄉土特性，以旅遊觀光產業為目標，創造更大經濟效益。\n七.銀髮長照：重視高齡化社會問題，爭取老人照護措施，爭取經費補助紓緩家庭負擔。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
