INSERT INTO "fact" VALUES('platform:2022-local:p20ff42291a','p20ff42291a','platform','2022-11-26','{"district_id": "cyq-council-04", "election": "2022-local", "office": "cyq_councilor", "text": "1.年少有魄力，新動力，有責任，傾聽民意重視公民力量，全力做最好的服務。\n2.透過馬稠後工業園區及嘉義科學園區創造優質就業環境平台，鼓勵及輔導青年\n返鄉就業。\n3.監督縣政府各部門施政執行成效，積極爭取各項資源及基礎建設，打造完善公\n共設施，塑造及提升生活環境。\n4.面對氣候變遷，針對易淹水地區全面檢討排水系統與加強河川整治，建立治水\n園區。\n5.推廣商圈市集及文化相關活動，打造旅遊新地標。\n6.國際局勢詭譎多變，為維護農漁民權益，積極輔導優質農漁產品，強化內銷及\n拓展國際通路。\n7.提高本縣生育獎勵金補助以落實照顧婦幼核心價值。\n8.重視各地長照據點照護資源，安定長者生活讓福利服務需求有所依。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
