INSERT INTO "fact" VALUES('platform:2022-local:p2e80c438ad','p2e80c438ad','platform','2022-11-26','{"district_id": "cyq-council-01", "election": "2022-local", "office": "cyq_councilor", "text": "一、爭取通學步道，守護學童上下學安全。\n二、爭取運動空間，提升鄉親生活品質。\n三、陪伴不老社區，落實在地安老，爭取提高老人食堂供餐補助。\n四、爭取廣設日照中心。\n五、推動適性閱讀，設立漂書站，讓知識漂流，二手書自由。\n六、創造藝文空間，為地方村莊注入藝術，生活美學。\n七、推廣在地農產，提升附加價值。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
