INSERT INTO "fact" VALUES('platform:2022-local:p3ff598cd47','p3ff598cd47','platform','2022-11-26','{"district_id": "cyq-council-01", "election": "2022-local", "office": "cyq_councilor", "text": "1.「以太保市治理經驗，擴大服務區域」，太保市是嘉義縣人口唯一正成長的鄉鎮市，也使第一\n選區議員席次增加一席，榮利本諸清廉、務實、真誠的初衷，爭取擴大服務鄉親的機會。\n2.嘉科落腳太保巿、水上鄉有南靖產業園區、鹿草鄉有馬稠後產業園區，本人將力促政府早日開\n發完成，引領台商回流，擴大就業市場。\n3.高鐵特區暨縣治第二期都市計畫開發案，總面積達343公頃，目前縣政府擬公辦開發，為確保地\n主權益，將監督縣府，做妥善及合理的分配，比例不得低於自辦。\n4.縣治特區對面商圈開發案停滯多年，將督促各局處力邀大賣場進駐，帶動區域發展，打造宜居\n宜業好住宅。\n5.本選區轄內溫室面積為嘉義縣密度最高，為協助青農拓展優質農產品市場，將積極推動外銷通\n路，增加收益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
