INSERT INTO "fact" VALUES('platform:2022-local:p4641992cd3','p4641992cd3','platform','2022-11-26','{"district_id": "cyq-council-03", "election": "2022-local", "office": "cyq_councilor", "text": "01.活化公園綠地，打造親子與毛孩友善空間：\n盤點公園綠地，爭取有效活化，打造親子安全遊戲場域和毛孩友善空間，促進親子\n休閒娛樂。\n02.農業農產升級與改善農民產業道路：\n結合在地農會與縣農會推廣農產價值再提升；無論夜間巡視或清晨耕作，農業產業\n道路安全有其重要性，改善道路路燈照明或使用標線以保障農民安全。\n03.推動老人食堂再進化，中央廚房有保險、有保障：\n推動社區老人食堂安全升級，對村里社區老人食堂建立保險機制，更有保障。\n04.發展綠色能源，打造永續嘉義新風貌：\n爭取嘉義縣社區轉型，推展綠色能源接地氣，人民參與公民電廠生產合作社，永續\n社區發展目標。\n05.熊骨力、好央甲：全力為鄉親服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
