INSERT INTO "fact" VALUES('platform:2022-local:p83296121ab','p83296121ab','platform','2022-11-26','{"district_id": "cyq-council-01", "election": "2022-local", "office": "cyq_councilor", "text": "一、我承諾：專業問政、監督不分黨派、不貪不取、全力為百姓發聲。\n二、我堅定：支持18歲公民權，守護嘉義、愛台灣！\n三、我專業：用心監督縣政、嚴格審查預算，避免縣府濫用公帑、使財政持續惡化。\n四、我用心：督促嘉義縣各產業園區之開發，增加就業機會、協助青年返鄉，推動地方創生。\n五、我守護：老弱婦孺殘障人士之權益，督促縣府加速長照服務的普及，健全公共托育保母系\n統、營造良好育兒環境，讓父母安心生養。\n六、我要求：嘉義縣政府依據都市發展需要及實際發展情況、參考人民建議，加速進行各鄉鎮都\n市計畫通盤檢討，增加土地利用價值。\n七、我爭取：水上鄉鐵路高架化，解決交通壅塞；活化水上機場並建構完善的聯外道路，促使觀\n光交通更便利。\n八、我堅持：善用本縣優勢資源、結合本土文化特色，促使嘉義成為國際友善觀光農業大縣。\n九、我推動：公私合力針對空氣、水環境污染物之稽查，加強取締地下工廠、違法開發、不法排\n放廢水、污水、廢氣和非法棄置固體廢棄物。\n十、我捍衛：軍公教警的尊嚴和權益，爭取教育經費充分編列、提昇學童就學品質、充實義警消\n裝備，保障其生命財產安全。\n★琬蓁八年來的專業認真，值得您用選票再次支持連任肯定！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
