INSERT INTO "fact" VALUES('platform:2022-local:p8d9dd3cb6d','p8d9dd3cb6d','platform','2022-11-26','{"district_id": "cyq-council-05", "election": "2022-local", "office": "cyq_councilor", "text": "一、堅持正直、重義、同理心的服務理念，為布袋、義竹鄉親打拼。\n二、堅持監督縣政平衡發展，維護布袋、義竹鄉親、新住民同胞應得的權益。\n三、堅持督促縣府推動科技農漁牧業，有效提升產值、減少勞動力付出，並降低損\n害，藏富於鄉親。\n四、堅持督促縣府落實並提升長照、日托服務，確實照顧、維護鄉親幸福、安心的\n生活。\n五、堅持督促縣府徹底改善區域、村里及農漁排水，有效解決社區及農漁牧產業，\n免除鄉親水患苦境。\n六、堅持持續督促縣府加強廣設路口監視系統及照明設備，維護社區治安，讓鄉親\n安居樂業。\n七、堅持爭取資源，致力發展布袋、義竹觀光產業，並推展在地特色宗教、民俗、\n文化與藝文活動。\n八、堅持制訂政策，結合政府、慈善團體資源，強化弱勢鄉親服務與照顧。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
