INSERT INTO "fact" VALUES('platform:2022-local:p9e3fb5292e','p9e3fb5292e','platform','2022-11-26','{"district_id": "cyq-council-06", "election": "2022-local", "office": "cyq_councilor", "text": "1.爭取中埔三和地區設立高中或完全中學，讓三和地區及鄰近學子得以就近就學培育人才。\n2.爭取都市計畫內老舊高壓電塔完全地下化整治市容，以利地方繁榮發展。\n3.爭取易淹水地區老舊排水道改善，監督執行地下水道改善工程。\n4.為維護地方治安爭取增設三和派出所，以利便民服務。\n5.監督三和地區都市計畫完成通盤檢討之執行。\n6.推行地方休閒運動及場設改善。\n7.爭取中埔鄉設立托育中心及水域縣民運動中心。\n8.監督改善吳鳳廟特區環境改善，以利地方經濟效益發展。\n9.持續推動客家文化協會永續經營。\n10.全心全職為民服務排解艱難──追求幸福與繁榮。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9e3fb5292e','p9e3fb5292e','profile','2022-11-26','{"education": ["1.和睦國小", "2.大業國中", "3.東吳高職", "4.台北體專", "5.台北體育學院碩士（在職專班）"], "election": "2022-local", "experience": ["1.中埔鄉第16 17屆村長2.第16至19屆嘉義縣議員3.92至97年榮獲嘉義縣調解績優人員4.95至110年榮獲調解行政院長獎及法務部長獎5.和睦國小校友會創會理事長6.客家文化協會創會理事長7.嘉義縣義交大隊顧問8.台北體育學院校友會副會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
