INSERT INTO "fact" VALUES('platform:2022-local:pa6f49c19ee','pa6f49c19ee','platform','2022-11-26','{"district_id": "cyq-council-05", "election": "2022-local", "office": "cyq_councilor", "text": "1.繁榮博士的故鄉，建設海港新樂園。\n2.全方位監督縣政，深耕基層用心傾聽。\n3.推動布袋港周邊觀光休閒產業，以促進經濟繁榮發展。\n4.持續爭取引進大型智慧園區開發，解決鄉親就業難題。\n5.督促落實年長者、婦幼及弱勢團體之社會福利。\n6.加強本區排水系統整治及抽水站水利施設，確保生命財產安全。\n7.促進農漁產業轉型升級，提高競爭力及增進農漁民收入。\n8.協助推廣賽鴿苓等地方民俗特色文化活動，以利保留傳承。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
