INSERT INTO "fact" VALUES('platform:2022-local:pb2388adf20','pb2388adf20','platform','2022-11-26','{"district_id": "cyq-council-06", "election": "2022-local", "office": "cyq_councilor", "text": "一、全力爭取經費建設，發展地方觀光。\n二、促請縣府關懷老弱婦孺及身心障礙者，加強推動社會福利政策。\n三、促請縣府提升教育、文化、醫療服務等活動。\n四、建議政府重視阿里山沿線，國有財產局、林務局承租人權益，讓民眾安心居住永續經營。\n五、讓嘉義農工大縣早日實現。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
