INSERT INTO "fact" VALUES('bulletin:2022-local:pb55b5c39b2','pb55b5c39b2','bulletin','2022-11-26','{"district_id": "cyq-council-01", "elected": true, "election": "2022-local", "office": "cyq_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pb55b5c39b2','pb55b5c39b2','platform','2022-11-26','{"district_id": "cyq-council-01", "election": "2022-local", "office": "cyq_councilor", "text": "一、發展工商\n推動嘉義科學園區、馬稠後產業園區、水上南靖產業園區加速開發，帶動嘉義縣全面發展。\n二、農業升級\n督促縣府持續提出智慧農業計畫，輔導農民增加農產品品質、產量，強化品牌、行銷世界。\n三、促進觀光\n督促縣府運用水上、鹿草、太保豐富人文與自然風貌，規劃觀光軸線亮點，吸引遊客商機。\n四、強化建設\n針對鄉親所需地方建設如道路修建、防洪排水、公園綠地，積極協調各政府單位全力解決。\n五、完善社福\n關心年長者、婦女、兒童及弱勢民眾的社會福利需求，督促縣府完善措施，擴大服務資源。\n六、清淨家園\n督促縣府積極改善影響縣民健康的空氣、水、廢棄物等各項污染問題，提升生活環境品質。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
