INSERT INTO "fact" VALUES('platform:2022-local:pc1797c29f3','pc1797c29f3','platform','2022-11-26','{"district_id": "cyq-council-05", "election": "2022-local", "office": "cyq_councilor", "text": "監督縣政，讓嘉義縣朝向農工大縣大步向前行\n爭取建設，讓義竹布袋成為是一個宜居的鄉鎮\n爭取銀髮族相關活動設施，讓長者可樂齡生活\n爭取擴大工業區開發範圍，增加民眾就業機會\n爭取地方特色產業行銷機會，增加農特產銷售\n整合政府及民間資源，投入教育縮短城鄉差距", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc1797c29f3','pc1797c29f3','profile','2022-11-26','{"education": ["文化大學法律系學士\n國立嘉義大學管理學院碩\n士"], "election": "2022-local", "experience": ["臺灣大學生物產業傳播暨發展學系\n碩士班\n嘉義縣第16、17屆議員\n立法委員陳明文國會助理\n嘉義縣工商發展投資策進會總幹事\n台灣區飲料工業同業公會理事長\n中華民國全國工業總會監事\n嘉義縣體育會總幹事\n義竹義消顧問團長\n民進黨第十三屆全國黨代表\n義竹鄉後備輔導中心副主任\n過溝建德宮顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pc43d61be75','pc43d61be75','bulletin','2022-11-26','{"district_id": "cyq-council-02", "elected": true, "election": "2022-local", "office": "cyq_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pc43d61be75','pc43d61be75','platform','2022-11-26','{"district_id": "cyq-council-02", "election": "2022-local", "office": "cyq_councilor", "text": "農工大縣 琴來實現 議會尚青 專業問政 深耕 做事 顧弱勢\n老人福利：督促縣府向中央爭取老人福利，落實中央政府長照計畫。\n農、工業：推動農漁牧產品精緻化、科技化農業保障農民生計輔導農業轉型升級。引進AI產業進駐嘉\n義，發展無人機產業，設置科學園區。督促縣府實現農工大縣的願景。\n社 區：爭取各社團辦理活動經費補助，設置青少年活動場地，並提高各社區的補助額度。\n教 育：改善各中小學軟硬體設備，爭取中低收入戶學童營養午餐免費，推廣並補助民俗文化藝術\n經費。\n婦 幼：爭取外籍配偶及中低收入戶家庭，提供幼兒免費托育服務。\n農 路：加速早期農田水路改善工程，全面興建擋土牆，並鋪設柏油路面、拓寬路面，以利農機出\n入。\n治 水：爭取整治六腳排水及易淹水地區抽水站之設置，確保民眾安全，全面改善轄區大、中、小\n排水系統，並增各聚落排水溝加蓋，以護民眾行的安全。\n觀 光：結合大阿里山風景區及中崙溫泉、瑞里風景區、東石漁人碼頭、民雄演藝廳、新港奉天\n宮、民雄大士爺廟、民雄鵝肉街、故宮南院…等景點，成為獨具地方特色之觀光路線，並\n結合各地方 區營造，提昇總體經濟價值。\n衛生防疫：督促縣府配合中央防疫指揮中心落實防疫的工作，並請縣府規劃後疫情時代來臨時各局因\n應方針。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc43d61be75','pc43d61be75','profile','2022-11-26','{"education": ["國小"], "election": "2022-local", "experience": ["第15、16屆新港鄉民代表\n第15－19屆嘉義縣議員\n第17、18屆嘉義縣議會黨團總召\n第17屆嘉義縣民進黨主委\n新港奉天宮副董事長\n新港姊妹連線榮譽理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pee042263a3','pee042263a3','bulletin','2022-11-26','{"district_id": "cyq-council-02", "elected": true, "election": "2022-local", "office": "cyq_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pee042263a3','pee042263a3','platform','2022-11-26','{"district_id": "cyq-council-02", "election": "2022-local", "office": "cyq_councilor", "text": "一、爭取社區週邊與重要道路兩側之特定農業用地開放，以利地方產業均衡發展。\n二、推動六級農業強化精緻農業與農特產品品牌化、網路行銷，以利休閒農業發展提升農民經濟效\n益。\n三、推動青年創業輔導計畫與職訓，提升青年在地創業與就業機會。\n四、爭取政府落實社會福利政策之公平，讓農業縣與六都享平等福利。\n五、敦促都市計畫通盤檢討，活化新港、民雄競爭力、爭取建設以民雄和新港為核心的新都心。\n六、督促河川疏濬整治，設置大型抽水站，解決低窪地區水患。\n七、督促社區道路側溝與下水道定期清淤以利環境衛生與雨季排水。\n八、持續爭取新港台糖265公頃農場設置「台灣農業機械暨農產加工智慧園區」以利區域發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pee042263a3','pee042263a3','profile','2022-11-26','{"education": ["國立中正大學政治研究所\n碩士\n稻江科技暨管理學院\n協志工商\n新港國中\n復興國小"], "election": "2022-local", "experience": ["嘉義縣議會第18、19屆議員、全\n國創新創業總會第22屆副總會\n長、新港香藝文化園區創辦人、\n新港鄉民代表會第17屆代表、第\n18屆副主席、代理主席、新港愛\n鄉慈善會創會理事長、協志工商\n校友會創會理事長、新港奉天宮\n董事、南華大學管理學院博士生"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
