INSERT INTO "fact" VALUES('platform:2022-local:pf34dbb0816','pf34dbb0816','platform','2022-11-26','{"district_id": "cyq-council-06", "election": "2022-local", "office": "cyq_councilor", "text": "一、積極爭取各項建設經費及落實城鄉平衡發展。\n二、配合縣府農業政策推動，建構產銷機制，保障農民利益。\n三、敦促縣府爭取經費來為新住民婦女及弱勢團體的生活，並舉辦輔導就業及技能訓練。\n四、提案爭取社區預算，辦理老年人活動與學習課程，提升照顧樂齡族鄉親。\n五、敦請政府重視山區林班地承租人權利，尋求合法、合理之政策，得使百姓安心永續經營，安居樂\n業。\n六、全心全力，專職為民服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
