INSERT INTO "fact" VALUES('platform:2022-local:pf36732b982','pf36732b982','platform','2022-11-26','{"district_id": "cyq-council-02", "election": "2022-local", "office": "cyq_councilor", "text": "一、發展藝文體育活動：音樂藝術氛圍紮根，運動體育發光發熱。\n二、協助農業產銷機制：提升農民農事收入，推廣精緻農業路線。\n三、保障弱勢團體福祉：婦孺老幼外籍配偶，竭力爭取福利保障。\n四、拉近城鄉教育差距：推動相關教育政策，翻轉嘉義孩童發展。\n五、長照發展老化趨勢：銀髮照護比例加重，樂活長輩輕鬆晚輩。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf36732b982','pf36732b982','profile','2022-11-26','{"education": ["民雄國民小學\n民雄國民中學\n國立後壁高級中學\n國立嘉義大學土木與水資\n源工程系"], "election": "2022-local", "experience": ["民雄鄉民代表會19.20.21屆鄉民\n代表\n民雄後備輔導中心主任\n嘉義縣民雄國民小學家長會會長\n民雄文教基金會董事\n救國團嘉義縣民雄鄉團委會會長\n民雄鄉民眾服務社理事長\n嘉義縣民雄國民小學校友會創會\n理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf8096bf662','pf8096bf662','bulletin','2022-11-26','{"district_id": "cyq-council-07", "elected": true, "election": "2022-local", "office": "cyq_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf8096bf662','pf8096bf662','platform','2022-11-26','{"district_id": "cyq-council-07", "election": "2022-local", "office": "cyq_councilor", "text": "1.堅守原住民文化，捍衛原住民權益，監督縣政，為民喉舌，爭取鄉親福祉。\n2.促請縣府重視原住民母語教學課程，培訓原住民教師，以彌補山區老師嚴重不足的情況。\n3.加強都市原住民文化會館周邊設施，完善館內設備，使都市原住民有良好的文化傳授、技\n藝學習、聚會活動的場所。\n4.繼續爭取經費落實基礎建設，改善各村農路，提升飲水品質，健全消防系統，培訓體育人\n才，強化電力與電信功能，並積極爭取野溪整治及曾文溪護岸工程，以維護鄉親生命財產\n安全。\n5.繼續爭取山美至里佳道路開通工程，完善鄉內道路連貫系統。\n6.督請縣府將169線納入生活圈道路，並改善129線急彎路段及改善155線、149甲線等鄉內主\n要道路。\n7.督請縣府加強山區醫療服務，加強老人照護，增加生產補助並落實急難救助等社會福利。\n8.促請縣府重視觀光、文化、農特產及原住民傳統技藝等各項產業發展，配合部落特色，營\n造部落企業，繁榮地方經濟。\n9.促請縣府寬列經費補助原住民各歲時祭儀及文化活動。\n10.督請縣府重視遷徙至永久屋鄉親的各項權益，並輔導就業及協助發展永久屋之各項產業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf8096bf662','pf8096bf662','profile','2022-11-26','{"education": ["南榮科技大學專科部畢業"], "election": "2022-local", "experience": ["一、嘉義縣第十九屆縣議員二、阿里山鄉代表會第19、20屆主席", "三、阿里山鄉後備軍人輔導中心主任四、阿里山鄉農會常務監事", "五、阿里山鄉部落大學副校長", "六、鄒族達邦社、特富野社庫巴文化發展協會常務理事七、里佳社區發展協會第一、二屆理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf81ea83e96','pf81ea83e96','bulletin','2022-11-26','{"district_id": "cyq-council-03", "elected": true, "election": "2022-local", "office": "cyq_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf81ea83e96','pf81ea83e96','platform','2022-11-26','{"district_id": "cyq-council-03", "election": "2022-local", "office": "cyq_councilor", "text": "一、已爭取平林里辦公處晴雨棚及地面修繕工程（已設計發包）\n二、已爭取162+300公尺與98路口改善工程（施工中）。\n三、專業問政：監督政府施政、降低城鄉差距、落實均衡發展。\n四、婦幼代言：爭取婦幼福利、關懷幼童青少年就學及身心健全發展。\n五、關心老年：促請政府關懷獨居老世大心靈健康及心理輔導\n六、關懷弱勢族群：關懷新住民生活適應、輔導單親家庭、身心障礙者心理成長。\n七、農民代言：野溪、擋土牆、堤防施作及整治、灌溉溝渠、產業道路改善、以利農\n產品運輸、增加農民收入。\n八、持續爭取國中、小，軟、硬體設施，促使學童德智體群均衡發展。\n九、加強大埔美工業區釋放更多職缺、讓北漂青年能返鄉就業、照顧年邁長者，共享\n天倫之樂。\n十、“顧嘉 ”愛嘉 ”成為最 ”嘉 ”代言人", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf81ea83e96','pf81ea83e96','profile','2022-11-26','{"education": ["一大林國小畢業\n二宏仁女中畢業\n三大同高商畢業\n四稻江科技暨管理學院畢\n業"], "election": "2022-local", "experience": ["一大林鎮調解委員\n二大林鎮第十三至十五屆代表\n三大林國小家長會長\n四救國團大林團委會長\n五大林鎮婦女會理事長\n六台灣省耘善協會總幹事\n七立法委員翁重鈞特別助理\n八嘉義縣第十四至十九屆縣議員\n九嘉義新移民女性關懷協會理事\n長\n十婦聯分會常務委員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
