INSERT INTO "fact" VALUES('platform:2022-local:pf90666f0d2','pf90666f0d2','platform','2022-11-26','{"district_id": "cyq-council-06", "election": "2022-local", "office": "cyq_councilor", "text": "一、落實老人長期照護、日間照護及社區老人食堂開辦。\n二、振興山區觀光產業，建設經濟、特色之旅遊動線規劃。\n三、保護農民特殊產業推廣，青年返鄉種植各項優惠方案。\n四、推行閒置空間再利用，創造更多生活學習運動空間。\n五、推廣公共托嬰政策，減輕青年成家負擔。\n六、選區內路平、排水、平坦順暢，讓回家之路安全，讓生命財產，得以保障。\n七、融入地方文化，推廣13庄頭嘉年華會。\n八、關懷弱勢權益，保障勞工權利。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/12%E5%98%89%E7%BE%A9%E7%B8%A3/%E5%98%89%E7%BE%A9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
