INSERT INTO "fact" VALUES('platform:2022-local:p33130c7539','p33130c7539','platform','2022-11-26','{"district_id": "nan-council-02", "election": "2022-local", "office": "nan_councilor", "text": "一、持續推展九九峰步道延伸工程，並結合當地農產業特色、藝術人文、觀光、休閒，期使能\n俾益地方發展。\n二、敦促並監督縣府，落實乘車卡可搭計程車或繳健保費。\n三、持續監督促縣府，推動高科技、綠能轉化中心，並於各鄉鎮建置垃圾分篩場，減低垃圾量，\n維持並提升垃圾處理的量能。\n四、督促縣府落實相關青年政策，俾能讓北漂青年得有回鄉就業，就近照顧父母的機會。\n五、持續監督縣府，對於推展新住民的各項業務辦理，期使新住民更融入台灣社會，了解台灣\n精神、文化。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
