INSERT INTO "fact" VALUES('platform:2022-local:p3cb312bfb9','p3cb312bfb9','platform','2022-11-26','{"district_id": "nan-council-02", "election": "2022-local", "office": "nan_councilor", "text": "熱誠服務縣民，永不停止。\n一、社福：\n1、爭取社區關懷據點設立，落實政府長照政策。提供社區老人樂齡課程，活絡銀髮族退休生活。\n2、建構縣內醫療網路，爭取大型醫療院所進駐，提升醫療服務品質。\n3、幼兒生育補助加碼，減輕新手爸媽負擔。\n4、結合社會資源，關懷弱勢族群。\n二、就業：\n1、建議縣府成立青年事務局，統籌青年創業就業等事務，吸引青年返鄉就業。\n2、促請縣府強化職業訓練，結合地方資源及產業特色，提升職場競爭力，增加就業機會。\n3、促請縣府宣傳多元就業政策，提供青年、中高齡及二度就業者，求職便利。\n三、治安：\n1、補足警消員額及設備，拒絕暴力黑道，保障縣民生命安全。\n2、全力支持警政消防及防災預算，打擊犯罪，強化防災。\n3、督促完善警政治安監視系統，加強監控維護社區鄰里的治安與保障婦幼安全。\n四、教育：\n1、注重教育品質，落實品格教育，提升學生基本能力，拉近城鄉差距。\n2、活化校園閒置空間，推廣成人終身學習。\n3、力推增設公營托兒所，爭取幼兒教育補助，解決年輕世代育兒難題。\n五、農業：\n1、重視農田道路維護，改善灌溉排水系統。\n2、加強輔導精緻農業發展，促進農業升級，協助農產品行銷，增加農民收益。\n3、結合觀光，積極爭取設立精緻農業休閒園區。\n六、觀光：整合縣內觀光資源，發展地方特色觀光，吸引觀光人潮。\n七、財政：嚴格監督縣府財政預算編列與運用。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
