INSERT INTO "fact" VALUES('platform:2022-local:p53af85927a','p53af85927a','platform','2022-11-26','{"district_id": "nan-council-01", "election": "2022-local", "office": "nan_councilor", "text": "1. 聽取地方人民之聲音，並兼顧弱勢族群之需求，有效分配社會資源，使有限資源足以發揮最大效能，\n同時積極推廣公益，促進社會服務活動，發揚民間互助力量。\n2. 推廣農業發展，保障農民權利，並改善農民生活，讓農業重現生機。\n3. 提倡運動休閒活動，以發揚體育精神，並落實體育之相關政策。\n4. 推廣宗教相關之節慶活動，結合文化與觀光，發展在地文化特色，以發揚宗教文化，讓傳統宗教的景\n致與內涵得永續發展。\n5. 推廣在地特色文化，打造文化創意的觀光產業，與在地企業合作徵才，促進地方就業發展，以達雙贏\n的成效。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
