INSERT INTO "fact" VALUES('platform:2022-local:p5c9f9f446a','p5c9f9f446a','platform','2022-11-26','{"district_id": "nan-council-05", "election": "2022-local", "office": "nan_councilor", "text": "2022 陳宜君政見\n【文化教育】\n監督縣府辦理國中小多元文化教育課程、建置零至二歲托育資源系統、推動食農教育，提升學童綠色\n飲食知識。\n【社福照顧】\n監督縣府提升長照師資專業能力、推動生育津貼加碼補助、完善現代社會住宅，打造青年安心居住環\n境。\n【環境保護】\n將農廢與垃圾轉作生質燃料，解決垃圾問題。推動綠色低碳旅遊計劃。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
