INSERT INTO "fact" VALUES('platform:2022-local:p99f76f925a','p99f76f925a','platform','2022-11-26','{"district_id": "nan-council-01", "election": "2022-local", "office": "nan_councilor", "text": "1. 監督縣政反映民意，爭取經費建設地方，協助產業及社區發展，傳遞民情、為民發聲。\n2. 督促政府落實社會福利政策，打造全齡友善安全環境。\n3. 督促政府整合提升育兒資源，打造親子共學遊戲空間。\n4. 督促政府推動公部門連結產業，協助青年職訓就業，青銀共創世代共融。\n5. 督促政府推動農村社區土地重劃，促進土地合理利用，合法發展產業及觀光。\n6. 督促政府推廣地方文化、工藝教育，深根傳承在地文化。\n7. 督促公部門輔導農民及文化產業，強化數位培訓，擴大銷售管道，促進數位轉型發展。\n8. 督促政府強化縣民就醫便利性及可近性，開辦免費醫療專車，提供就醫及探病一車到位的交通接送服\n務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
