INSERT INTO "fact" VALUES('platform:2022-local:pce66fab6ae','pce66fab6ae','platform','2022-11-26','{"district_id": "nan-council-02", "election": "2022-local", "office": "nan_councilor", "text": "1、民主前進，挺 18。\n2、爭取生育補助、育兒津貼 123：第一胎 2 萬、第二胎 3 萬、每月補助 2 千至三歲。\n3、鄉鎮特色將現有公園規劃或新建，設「親子共融寵物公園」。\n4、持續爭取設立國民運動中心、棒球場。( 提供青少年運動、老年人活動、親子館、表演場館 )\n5、爭取敬老愛心卡可搭計程車、國道客運、縣內合作之醫療院所就醫費、付健保費。\n6、交通不打結，設立多功能轉運站。\n7、加強推廣各鄉鎮老街商圈及社區產業、市場進行創意營造辦理促銷活動，搭配在地特色與節慶活動刺激消費活絡商圈。\n8、改善市區停車問題，督促設立部分路段路邊停車收費。\n9、爭取縣府推動單親、弱勢兒童課後安親；公辦民營托育中心。\n10、關注偏遠產業道路、邊坡堤防、水圳護欄之修建與維護，保護居民與農民安全。\n11、爭取青創基地，鼓勵南投青年留在家鄉，發展文創產業，創業築夢。\n12、爭取國中小學軟硬體設備更新及補足，免費校外體育教學活動。\n13、針對重要道路及易肇事路段加裝監視器及交通號誌改善，以促進交通安全及民眾生命財產的維護。\n14、優化與廣設監視系統，治安加強，提升警力配置及裝備。\n15、要求縣府配合內政部推動「宗教團體以自然人名義登記不動產處理暫行條例」，加強協助宗教團體輔導其土地使用\n合法化。\n16、加強鼓勵宗教團體辦理習俗推廣及傳統祭儀文化活動，以傳承正向信仰教化人心。\n17、增加原住民及新住民、客家族群等多元文化活動辦理，促進族群融合，同時強力推動性別平等、反家暴與反詐騙。\n18、推動『幼托保母、長照及看護服務人力管理平台』，\n19、補助國一女生免費接種 HPV 子宮頸癌疫苗。\n20、爭取生活圈道路投 17 線，北中寮延伸到南中寮 ( 中寮國小 )，道路拓寬。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pce66fab6ae','pce66fab6ae','profile','2022-11-26','{"education": ["僑光國小\n南投國中\n中華醫事學院\n國立勤益科技大學\n國立暨南大學 碩士"], "election": "2022-local", "experience": ["南投縣第 19 屆 縣議員\n草屯鎮 20 屆 鎮民代表\n草屯鎮平宮 主委\n三龍宮 副主委\n中寮玄義宮 科儀法師\n柯蔡宗親會 理事\n防治公害協會 理事\n僑光國小導護志工\n草屯青商會會長\n民進黨縣黨部 財務長\n草屯商圈發展協會 理事長\n南投縣民俗文化技藝推廣發展協會 理事長\n現任民進黨南投縣黨部 主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
