INSERT INTO "fact" VALUES('platform:2022-local:pdb3cfd1da4','pdb3cfd1da4','platform','2022-11-26','{"district_id": "nan-council-01", "election": "2022-local", "office": "nan_councilor", "text": "1. 支持 18 歲公民入憲。\n2. 支持政府政策持續提高基本工資，改善全民的生活品質。\n3. 協助各校發展特色教育，結合在地文化留住優質學生。\n4. 爭取中央經費，建設地方和改善學校教學設備。\n5. 全力推動建設青年住宅，讓年輕人買的起便宜的住宅。\n6. 維護居家服務被照顧者的權益，保障照服員的工作尊嚴。\n7. 關懷新住民議題，幫助新住民解決生活適應問題，並協助解決安排其子女教育相關問題。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
