INSERT INTO "fact" VALUES('platform:2022-local:pdffeb5d50f','pdffeb5d50f','platform','2022-11-26','{"district_id": "nan-council-03", "election": "2022-local", "office": "nan_councilor", "text": "1. 敦促縣府對社會福利，落實老人長青照護，獨居老人、婦幼、新住民、\n身心障礙、弱勢家庭，生活有所依。\n2. 敦促補足警消人力，社區巡守隊，義警消裝備經費補助，推廣智能ｅ化\n監視器。\n3. 關懷原墾農民，依法爭取土地所有權，保障原墾農民生存權與工作權。\n4. 積極爭取，縣內國中、國小建設經費，充實學校軟硬體設備，提升教學\n環境及學習競爭力，給在地子弟受教更好環境。\n5. 爭取青少年戶外體適能活動場地，補助設施及經費。\n6. 推動文化升級，爭取傳承與創新客家文化藝術，落實客家文化藝術多樣\n性。\n7. 超越黨派，積極爭取地方建設，勤跑基層，傾聽民意，秉持為民服務為\n天職信念，全職全時服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC3.4%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
