INSERT INTO "fact" VALUES('platform:2022-local:pe563198cd8','pe563198cd8','platform','2022-11-26','{"district_id": "nan-council-04", "election": "2022-local", "office": "nan_councilor", "text": "依竹山、鹿谷的產業特色，結合觀光、文創、農特產等打造休閒旅遊美麗\n山城。\n爭取中央資源，協助地方改善水利灌溉設施河岸堤防、農路，讓農民有完\n善的灌溉系統，安全平順的生產運輸農路，保障生命財產安全\n極力爭取偏鄉無自來水區，自來水延管工程，提升鄉親生活品質\n全力推動竹山防空壕作戰指揮所暨日本時期宿舍群為「竹山町昭和村文化\n藝術園區」帶動竹山、鹿谷地區觀光、經濟發展\n全力推動木屐寮生態園區設置「水環境調蓄水源功能暨親子生態戲水池」\n創造觀光產質，帶動地方繁榮", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC3.4%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
