INSERT INTO "fact" VALUES('platform:2022-local:pf8e5702de0','pf8e5702de0','platform','2022-11-26','{"district_id": "nan-council-01", "election": "2022-local", "office": "nan_councilor", "text": "1. 監督招商進度，鼓勵年輕人回鄉，創造就業機會。\n2. 協商垃圾處理整體政策，配合資源循環再利用，建立低塑南投家園。\n3. 活化文化資產，加強藝文展演。\n4. 強健體魄，支持從校園紮根，由社區推展，舉辦各類體育競賽暨增設親子共融公園。\n5. 增加長照關懷據點，擴大送餐訪視對象，樂活南投。\n6. 爭取專案推動地方特色農產，協助加工包裝行銷。\n7. 開設婦女家事才藝班，開拓視野，永續學習及交流。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
