INSERT INTO "fact" VALUES('platform:2022-local:p086a5401ee','p086a5401ee','platform','2022-11-26','{"district_id": "mia-council-05", "election": "2022-local", "office": "mia_councilor", "text": "1.爭取建置南庄汙水處理廠，改善中港溪鄉親用水的品質及衛生問題。\n2.爭取興建全功能市民健康休閒中心及全新圖文資訊閱聽中心，為鄉親營造高品質生活環境。\n3.建構頭份便利行路網，擴大北台三強城市生活圈往頭份延伸，推動中山高五楊高架延伸至造橋。\n4.活化頭份建國親子花市，推動市集活動及配合農會推動茶、梨、橘、蜂蜜等頭份特色產業加值品牌行\n銷。\n5.爭取中央開闢頭份第二交流道，解決頭份市區交通阻塞問題。\n6.全面補強警政市區監視系統，連線整合設置、維護全市鄰里巷弄監視系統，全天候保護市民通行、居住\n及財產安全。\n7.輔導公私立托育機構，全面監督並提升幼兒照顧保護專業水準，協助分擔年輕父母育兒辛勞。\n8.爭取補助各村里、社區、社團建設與活動經費，充分重視基層民眾對鄰里、社區生活環境、建設改善的\n心聲，藉由社區活動辦理，展現關愛鄰里、社區的參與推動活力。\n9.照顧新住民及補助弱勢團體。配合中央推動長照政策，照顧銀髮族長者。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
