INSERT INTO "fact" VALUES('platform:2022-local:p16234bc127','p16234bc127','platform','2022-11-26','{"district_id": "mia-council-05", "election": "2022-local", "office": "mia_councilor", "text": "鄭聚然是現任的苗栗縣議員，在這片土地生活三十餘年，對地方的認同感不亞於任何人。聚然在乎的是鄉\n親生活的福祉、苗栗縣的繁榮，以及提升老幼弱勢族群的權益。\n經濟方面，聚然會持續鼓勵青年創業、扶植地方特色產業發展，照顧經濟建設同時也爭取育兒與老人津貼\n及福利，讓年輕家庭能無後顧之憂。\n民政方面，聚然堅守廉政愛民理念，關懷老幼，同時也媒介社會資源與集結民間力量，協助弱勢族群安身\n立命。\n四年任期以來，聚然秉持熱誠致力為鄉親爭取權益、全心服務有目共睹，同時也積極與政府協調政策，成\n為民意與政府溝通的橋樑。\n人民所關心的，就是聚然掛心的。廉政愛民，企業經營，務實創新理念，鄭聚然懇請各位鄉親支持，讓聚\n然與苗栗縣鄉親繼續在第一線打拼！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
