INSERT INTO "fact" VALUES('platform:2022-local:p5d606775f7','p5d606775f7','platform','2022-11-26','{"district_id": "mia-council-04", "election": "2022-local", "office": "mia_councilor", "text": "1.推動苗栗地區整體醫療品質提升。\n2.推動高鐵特定區都市建設整體發展，並督促縣府以兼顧永續發展指標做規劃。\n3.督促縣府規劃後龍設置產專園區，帶動地方經濟繁榮。\n4.督促縣府落實長照2.0政策，完善長照機制。\n5.監督縣府推動高齡、婦幼、兒少、身障等各項福利及設施，關懷新住民生活權益，協助弱勢及高風險家\n庭，並追蹤後續安全照顧。\n6.爭取增加公共托育設施等計畫，減輕家長負擔。\n7.捍衛警、消、醫護、勞工族群等權益。\n8.督促縣府發展數位治理及開發實用性APP，均衡數位落差。\n9.督促縣府做好農、漁、牧產銷制度及提高農漁民收入。\n10.推動永續好生活、健康好生活、快樂好生活。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5d606775f7','p5d606775f7','profile','2022-11-26','{"education": ["成功國小畢業\n後龍國中畢業\n沙鹿高級工業職業\n學校畢業\n育達商業科技大學\n畢業"], "election": "2022-local", "experience": ["中國科技大學企管研究所肄業\n後龍鎮鎮民代表\n後龍鎮調解委員\n苗栗縣都市計畫委員\n苗栗縣都市設計審議委員\n苗栗縣醫事審議委員\n苗栗縣竹南民防中隊長\n苗栗縣好生活協會理事長\n苗栗縣第12、13、14、16、17、18、19屆議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
