INSERT INTO "fact" VALUES('platform:2022-local:p73638623c3','p73638623c3','platform','2022-11-26','{"district_id": "mia-council-01", "election": "2022-local", "office": "mia_councilor", "text": "一、在地深耕、專業問政、傾聽民意、服務用心。\n二、公民政治：推動公共議題焦點探討，讓好的公民意見納入縣府施政。\n三、服務用心：建立選民服務機制，即時回報，您的問題，美露處理。\n四、樂活苗栗：結合縣內山海美景與客家特色，協助地方創生經費爭取，讓觀光產業升級。\n五、幸福苗栗：於議會督促縣府擴大服務老人、婦女、兒少、新移民、身心障礙與弱勢團體之資源，加強\n長期關懷與輔導等服務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p73638623c3','p73638623c3','profile','2022-11-26','{"education": ["一、育達科技大學學士。", "二、宜蘭高級商業職校畢業。", "三、頭城初中、國小畢業。"], "election": "2022-local", "experience": ["公館鄉公所第十七、十八屆鄉長。\n公館鄉民代表會第十九屆主席。\n苗栗縣第十六屆縣議員。\n立法委員徐耀昌公館服務處主任。\n公館鄉代表會第十七屆副主席。\n公館鄉第十五、十六屆代表。\n苗栗縣消防局婦女防火宣導隊分隊長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p7785630ccb','p7785630ccb','bulletin','2022-11-26','{"district_id": "mia-council-01", "elected": true, "election": "2022-local", "office": "mia_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p7785630ccb','p7785630ccb','platform','2022-11-26','{"district_id": "mia-council-01", "election": "2022-local", "office": "mia_councilor", "text": "參選是為了服務更多鄉親，我來自基層，了解民眾所需，為民喉舌，縮短民眾與政府之間的距離，扮演鄉\n親與政府部門溝通之橋樑，扮演好人民公僕的角色，服務鄉親。\n擔任民意代表從基層做起，一步一腳印，瞭解民眾所需，體認民眾所苦，點滴皆存於心。『苦民所苦，憂\n民所憂』，現下失業率偏高，如何讓勞工權益獲得更好的保障？婦幼、身障等弱勢團體等的社福利政策制\n定與落實，居住環境治安的改善，監督政府部門，期能更有效率的解決民眾問題，讓鄉親皆能擁有更好的\n生活品質。\n碧玉的天職─全心關懷弱勢族群。\n碧玉的信念─深入基層了解民意。\n碧玉的方向─勤勞服務回饋鄉親。\n碧玉的努力─看緊公帑杜絕浪費。\n碧玉的目標─專業問政稱職民代。\n碧玉的心願─共創苗栗美好生活。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
