INSERT INTO "fact" VALUES('platform:2022-local:p7ff0488a73','p7ff0488a73','platform','2022-11-26','{"district_id": "mia-council-05", "election": "2022-local", "office": "mia_councilor", "text": "一、積極提倡發展觀光事業，促進農、漁業合作，開創新機；\n二、為婦幼發聲，持續為弱勢挺身；\n三、責成警政、教育單位提出相關措施，全力防止毒與賭進入校園；\n四、敦促教育單位加強「生活與倫理教育課程、完善學子生活品格教育及法治觀念」；\n五、監督縣政，為民發聲，建立政府與民眾良好的溝通橋樑；\n六、續為中小企業發聲，並敦促政府提供並協助良好的發展環境。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
