INSERT INTO "fact" VALUES('platform:2022-local:p85163b491e','p85163b491e','platform','2022-11-26','{"district_id": "mia-council-06", "election": "2022-local", "office": "mia_councilor", "text": "1、監督縣府團隊、創造苗栗幸福願景。\n2、全力爭取地方建設、提升生活品貭、繁榮地方發展。\n3、輔導休閒農業、慢活轉形。\n4、創立客家特殊品牌、豐富新住民族群文化。\n創造多元就業環境、設置新住民關懷據點。\n5、督促縣府團隊、打造科技新都邁向國際文化城市。\n提高青年返鄉就業意願及更多工作機會。\n6、都市更新活化、土地利用一鄉鎮一親子公園。\n7、提高自來水普及率。\n8、大安溪堤防有效利用設置自行車道及親子運動步道。\n9、輔導農產品、網路行銷競爭力提升、提高農友收入。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
