INSERT INTO "fact" VALUES('platform:2022-local:p8884777d0a','p8884777d0a','platform','2022-11-26','{"district_id": "mia-council-04", "election": "2022-local", "office": "mia_councilor", "text": "一.關心孩子，協助婦女，爭取婦幼權益。\n二.為弱勢朋友及家庭爭取安全平等的生活權利。\n三.促請縣府落實社會福利政策，照顧弱勢家庭。\n四.督促縣府做好治安工作，人人能夠安居樂業。\n五.協助新住民及其家族成立各項組織及活動，打造幸福城市。\n六.加速公共設施保留地檢討，維護地主權益，提昇地方建設。\n七.爭取經費補助社區、社團、長壽會、義警、義消、守望相助隊、環保義工隊…，做好社區總體營造。\n八.推廣藝文活動，提升縣民文藝氣息。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p8884777d0a','p8884777d0a','profile','2022-11-26','{"education": ["頭份國小畢業\n頭份初中畢業\n清傳高職畢業\n台中技術學院畢業\n玄奘大學大眾傳播\n研究所碩士"], "election": "2022-local", "experience": ["1.現任苗栗縣第19屆縣議員", "2.苗栗縣第17屆18屆縣議員", "3.陳超明立委竹南服務處特別助理", "4.苗栗縣議會教育小組召集人", "5.竹南鎮第17屆18屆鎮民代表", "6.私立群林幼兒園負責人", "7.竹南青溪婦女協會理事長", "8.義警義消民防守望相助隊顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p88d808b116','p88d808b116','bulletin','2022-11-26','{"district_id": "mia-council-02", "elected": true, "election": "2022-local", "office": "mia_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p88d808b116','p88d808b116','platform','2022-11-26','{"district_id": "mia-council-02", "election": "2022-local", "office": "mia_councilor", "text": "1.活絡三義、銅鑼、西湖三鄉鎮商圈再造，配合中央觀光政策強化在地休憩產業。\n2.持續推動銅鑼科技園區產業進駐，鼓勵企業回饋地方、擴大在地就業、加強弱勢青年職訓輔導。\n3.爭取設置南苗栗環保辦公室，逐年降低空污排放，監督縣內高汙染產業、惡意傾倒廢棄物情形，讓家鄉\n永續發展。\n4.持續降低農民負擔，輔導在地農業，保障農民權益、鼓勵青農返鄉，推廣休閒農業發展。\n5.發揚苗栗在地特色產業，輔導青年回家鄉創業，活化苗栗產業競爭力，保障新住民權益。\n6.力抗少子化，讓青年成家更輕鬆、減輕年輕夫婦養兒育女之負擔。\n7.推動縣內雙語教學，督促縣府優化各級學校環境，讓苗栗學子未來不是夢。\n8.服務處提供免費法律諮詢、解決民眾困難，定期公布問政報告。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p88d808b116','p88d808b116','profile','2022-11-26','{"education": ["中原大學工學博士\n國立勤益科技大學\n工業碩士"], "election": "2022-local", "experience": ["現任第十九屆苗栗縣議員\n現任中華民國跆拳道協會副理事長\n現任苗栗縣跆拳道委員會主任委員\n現任苗栗縣職業總工會副理事長\n現任苗栗縣小英之友會秘書長\n三義鄉義警消、民防、警友會顧問\n第十八屆苗栗縣議員\n第三屆三義觀光文化發展協會理事長\n第十七、十八屆三義鄉農會理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
