INSERT INTO "fact" VALUES('platform:2022-local:p8ed34655bd','p8ed34655bd','platform','2022-11-26','{"district_id": "mia-council-05", "election": "2022-local", "office": "mia_councilor", "text": "一、爭取佈建偏鄉社區服務據點，讓服務與關懷不受地域性的影響，並開發各項到宅服務，主動發現個案\n並提供即時的協助及辦理社區衛教及宣導活動，提升偏鄉照顧服務資訊的觸及率，讓偏鄉長輩都能做\n快樂老人家。\n二、爭取經費在頭份市設立羽球場。\n三、督促縣府謀因應對策、有效激勵縣總生育率促進人口成長。\n四、爭取義消福利、強化治安巡防，防止詐騙。\n五、爭取學生冷氣及營養午餐補助，減輕家長負擔。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC5%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
