INSERT INTO "fact" VALUES('platform:2022-local:pac79da9ed6','pac79da9ed6','platform','2022-11-26','{"district_id": "mia-council-02", "election": "2022-local", "office": "mia_councilor", "text": "1、良善幫助弱勢：提案婦幼教育、弱勢家庭及急難救助各項補助計畫。\n2、用心地方建設：持續爭取促進公共建設，包括推動西湖溪路堤共構第四期延伸至台13線計劃。\n3、堅持做對的事：成立鄉親公益服務中心，反映民情需求及爭取地方社團經費。\n4、強化農民權益：水資源是農民的命脈，站在第一線為農民的水利資源發聲。\n5、增設日照中心：解決銀髮長照安養問題，以達到「在地老化、健康樂齡」的目的。\n6、活化觀光產業：串聯在地特色景點、小吃、民宿，打造觀光行銷產業鏈。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC2%E3%80%813%E3%80%816%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
