INSERT INTO "fact" VALUES('platform:2022-local:pd051265925','pd051265925','platform','2022-11-26','{"district_id": "mia-council-04", "election": "2022-local", "office": "mia_councilor", "text": "出自基層，以回應基層需求為主要參政理念，務實與行動，是爭取地方認同的問政主軸。\n強化縣府與地方的鏈結，針對後龍、造橋、竹南等地區，依照城鄉需求爭取合理資源分配，為富鎮拓建\n設，為僻壤爭資源，廣徵地方人士建言，使縣級、鎮級單位，以及政府與人民之間建立暢通管道，切實反\n應人民意見，嚴格監督預算執行成效，經費花在刀口上務求本縣財政平衡，且兼顧社會福利與地方建設。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
