INSERT INTO "fact" VALUES('platform:2022-local:pecb7e2d705','pecb7e2d705','platform','2022-11-26','{"district_id": "mia-council-04", "election": "2022-local", "office": "mia_councilor", "text": "1.秉持「誠實、勤快、活力」的理念。盡心盡力為民服務。\n2.積極爭取高鐵特定區、商業區周邊產業之開發與繁榮。\n3.積極推動長照2.0居家、社區、住宿式照顧服務及家庭支持，普及照顧服務體系，實現在地老化目標。\n4.紓解單親家庭照顧子女的經濟及托育壓力，協助弱勢家庭兒童及少年緊急生活扶助。建構完善的兒少福\n利制度及安全的成長環境，促進婦女福利，維護婦女權益並提升婦女地位。\n5.督促縣府實現休閒公園之規劃與開發，使休閒與觀光結合進而帶動地方繁榮。\n6.督促縣府振興外埔與龍鳳漁港為休閒與觀光漁港，進而振興漁民經濟，改善漁民生活。\n7.督促縣府重視發展建立社區特色以提升社區文化及生活品質。\n8.積極推動如何防護少子化的衝擊與社會福利政策息息相關。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC4%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:15:31Z');
