INSERT INTO "fact" VALUES('platform:2022-local:p1c64cd8d07','p1c64cd8d07','platform','2022-11-26','{"district_id": "hua-council-04", "election": "2022-local", "office": "hua_councilor", "text": "玲蘭從政以來，秉持著「由感恩出發，從謙卑做起」的態度，待人誠懇、做事認真、熱心公正、\n積極負責，一路走來，始終如一。\n觀光：\n一、串聯花蓮南區瑞穗、玉里、卓溪、富里等四鄉鎮及台東北區、東區等鄉鎮，組成花蓮南區\n觀光圈。\n二、藉由鄉長任內規劃富里六十石山行車路線的經驗，玲蘭將持續向中央爭取經費，使玉里赤\n柯山及南區各農業園區觀光動線更便利順暢。\n三、將瑞穗文旦柚、茶葉、酪農等農業，結合泛舟等觀光產業，共創雙贏。\n農業：目前花蓮縣的農業面臨了許多困境，包括人工匱乏、工資上漲、肥料漲價，但所有的農\n產品依然無法提升價格，讓廣大的農民收入減少，玲蘭會帶著農民朋友的期望努力，爭\n取更多農業補助。\n教育：繼續爭取公益團體及企業協助各級學校，並加強推動禮義廉恥、尊親孝道及社會的倫理\n道德觀念。\n人親，土更親，玲蘭腳踏實地的在南區土地上生活了五十年，了解南區鄉親的需求，請鄉親再\n給玲蘭服務的機會。真心實意，為您發聲。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
