INSERT INTO "fact" VALUES('platform:2022-local:p2b1e47921b','p2b1e47921b','platform','2022-11-26','{"district_id": "hua-council-03", "election": "2022-local", "office": "hua_councilor", "text": "一丶落實服務以民為先，積極反映人民心聲以維護人民權益。\n二、致力提升學童營養午餐質與量，以維護學童身心健康。\n三、廣設親子活動空間，提升優良育兒品質。\n四丶活化閒置空間、增進休閒運動場所，並以提升銀髮族長照機能。\n五、有效監督政府施政，以提升行政效率品質。\n六、關懷弱勢、維護農民與勞工權益。\n七丶推動綠色環保、打造鄉鎮樂活宜居環境。\n八、落實農業政策，提升農業經濟效益，以增進農民收益。\n九、促成國道六號延伸至花蓮，提升觀光產業產值。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
