INSERT INTO "fact" VALUES('platform:2022-local:p48561646c9','p48561646c9','platform','2022-11-26','{"district_id": "hua-council-01", "election": "2022-local", "office": "hua_councilor", "text": "一、全力推動花東快速道路興建。\n二、加速花蓮至吉安段鐵路高架化。\n三、落實警消值勤傷害法律免費諮詢，並編列救助經費，讓警消無後顧之憂。\n四、積極爭取新住民及偏鄉子女教育補助，暨就業保障。\n五、照顧毛小孩權益，爭取往生火化補助。\n六、持續推動社會安全、經濟繁榮、環境永續、居住正義、財政紀律。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p48561646c9','p48561646c9','profile','2022-11-26','{"education": ["大漢技術學院\n花蓮高工\n國風國中\n明廉國小"], "election": "2022-local", "experience": ["花蓮市民代表 19 丶 20 屆\n民眾黨花蓮縣黨部副主委\n行政院客家委員會諮詢委員\n花蓮縣子午線文教慈善協會顧問\n花蓮市國聯巡守隊顧問\n花蓮縣體育會健行委員會副主委\n花蓮代天府委員\n美崙福慈宮財務組長\n花蓮聖元壇顧問\n花蓮縣奇石協會監事\n花蓮縣永安石會監事\n花蓮縣花東玉石協會常務理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p59f3c4e6f1','p59f3c4e6f1','bulletin','2022-11-26','{"district_id": "hua-council-07", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p59f3c4e6f1','p59f3c4e6f1','platform','2022-11-26','{"district_id": "hua-council-07", "election": "2022-local", "office": "hua_councilor", "text": "1. 堅定信念 : 全力監督縣政各項業務，加強部落基層建設，為民喉舌，爭取福利。\n2. 土地政策 : 全力爭取增劃編原住民保留地，加速辦理保留地業務取得權狀，捍衛族人權益。\n3. 教育紮根 : 全力推動原住民族語學習及文化紮根工作；培養及扶植體育、文化、藝術專才。\n4. 產業促進 : 全力推動部落經濟、文化產業，促進經濟發展，建立行銷平台；提升專業職能，\n創造就業機會。\n5. 權益宣導 : 全力協助與提供各項權益及福利資訊，法律諮詢及法律扶助。\n6. 社會福利 : 督促及推展部落文化健康照顧計畫，繼續協助一部落一文健站，持續關懷弱勢及\n高風險家庭。\n7. 婦女權益 : 爭取婦女權益，辦理各項研習，發現與發展部落長才，提升婦女在部落參與公共\n事務。\n8. 部落建設 : 督促縣府協助部落辦理一部落一聚會所興辦事業計畫，協助與協調用地取得。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p59f3c4e6f1','p59f3c4e6f1','profile','2022-11-26','{"education": ["國立台北商專國際貿易\n科畢\n國立花蓮師範學院幼兒\n教育系畢\n國立東華大學族群關係\n與文化研究所畢"], "election": "2022-local", "experience": ["賦力慧企管顧問公司駐泰國特別助理\n花蓮縣私立快樂幼兒園園長\n勞動部北區職訓局花東地區講師\n國立東華大學業師\n原住民委員會性平委員會委員\n花蓮縣政府南區不動產糾紛調處委員會\n委員\n瑞穗鄉鄉民代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
