INSERT INTO "fact" VALUES('platform:2022-local:p60222eb82f','p60222eb82f','platform','2022-11-26','{"district_id": "hua-council-01", "election": "2022-local", "office": "hua_councilor", "text": "堅持友善親子共融環境 | 推動共融式遊具公園，打造親子共遊環境。\n堅持社區安全絕不退讓 | 集結社區共識，推動居家環境安全。\n堅持社區關懷永續經營 | 推動各項學習課程，落實社區關懷活動。\n堅持推動觀光接軌國際 | 藝術文化進駐，活絡產業，提升就業率。\n堅持推動市區便捷巴士 | 推動市區交通網路，增進共運輸量能。\n堅持榮民榮眷權益 | 保留眷村文化，推動眷村再造計畫。\n堅持新住民照顧協助 | 開設文化課程，推動交流活動。\n堅持居住品質優化 | 爭取經費改善路面整平及排水系統。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p60222eb82f','p60222eb82f','profile','2022-11-26','{"education": ["國立花蓮高級農業職業\n學校"], "election": "2022-local", "experience": ["花蓮縣議會第十四、十五、十六、十七、", "十八、十九屆縣議員花蓮縣議會第十九屆 KMT 黨團書記長國民黨花蓮縣黨部副主委花蓮縣退伍軍人協會顧問花蓮市民意長青會顧問花蓮縣謝姓宗親會顧問花蓮縣籃球協會榮譽理事長花蓮市老人會榮譽理事長花蓮縣美崙福慈宮顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
