INSERT INTO "fact" VALUES('platform:2022-local:p61ef3c7a52','p61ef3c7a52','platform','2022-11-26','{"district_id": "hua-council-05", "election": "2022-local", "office": "hua_councilor", "text": "※ 守護原住民土地權利，解決原住民保留地……等土地相關問題。\n※ 爭取各部落聚會所土地取得以及相關程序上問題，儘快完善各部落聚會所，落實一部落一聚會所，並建設多功\n能型聚會所，讓建設有一物多用的功能。\n※ 健全原住民長照服務體系，讓部落老人家老有所根、心有歸屬，並發展老幼共學，發揮部落長者的智慧與部落\n孩子一同學習一同成長，實踐文化傳承。\n※ 爭取原住民優秀子弟公費留學機會，讓優秀原住民子弟能拓展眼界、擁有國際觀和大格局來回饋部落、鄉里。\n※ 重視體育人才培育及完善後續職涯規劃，讓優秀的運動健將能留鄉有所發展。\n※ 重視婦女權益，協助舉辦相關研習課程發揮部落婦女所長，讓文化、藝術、手工藝……等，文化傳承重要工作，\n落實在生活中的每個角落。\n※ 積極爭取原住民疫情重創補助金，因疫情重創生計的家庭，藉由這類補助能轉型、重建原本產業穩定生計。\n※ 提供免費法律諮詢、案件調解服務，解決土地案件、勞資糾紛、行車糾紛……等棘手法律問題，守護原住民族\n人朋友的法律權益。\n※ 營造齊頭式教育環境，爭取原民教育補助編列，讓花蓮的孩童有更好的教育師資、環境、設備。\n※ 嚴格監督政府增加編列原民各項福利預算。\n※ 重視醫療體系的人員編制和醫療效能、相關醫療設備是否在重大傳染疾病擴散前能有效防堵、運作，保障所有\n民眾的生命安全。\n※ 爭取原住民部落相關基礎建設，與鄉里基層民代合作，傾聽地方所需。\n※ 爭取原住民傳統領域相關課程、計畫，扶植部落培養部落優秀人才。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p61ef3c7a52','p61ef3c7a52','profile','2022-11-26','{"education": ["開南大學管理學碩士\n國立高雄應用科技大學\n學士\n國立花蓮高級商業職業\n學校\n花蓮縣立國風國民中學\n若瑟國民小學"], "election": "2022-local", "experience": ["花蓮縣議會第 19 屆縣議員\n吉安鄉第 19 丶 20 屆鄉民代表\n花蓮縣青工總會原住民委員\n花蓮縣周利根議員服務處主任\n吉安鄉民眾服務站理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
