INSERT INTO "fact" VALUES('platform:2022-local:p6efd903822','p6efd903822','platform','2022-11-26','{"district_id": "hua-council-03", "election": "2022-local", "office": "hua_councilor", "text": "1. 督促縣府活化花蓮閒置公共空間，全面推動地方創生。\n2. 要求健全花蓮社福網絡，加強高齡友善。\n3. 推動產業及觀光發展，讓年青人有更多就業機會。\n4. 加速推動智慧校園，增加學習資源提升偏鄉數位之機會與能力。\n5. 推動東海岸 SDGs 永續旅行，辦理國際性觀光活動。\n6. 配合本縣觀光產業、督促縣府規劃交通網、疏解民眾塞車困境，\n並縮短城鄉差距、提升觀光品質。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:p6efd903822','p6efd903822','profile','2022-11-26','{"education": ["大漢技術學院"], "election": "2022-local", "experience": ["花 蓮 縣 第 15、16、17、18 屆 縣 議 員 及第 16 屆花蓮縣議會副議長丶壽豐鄉第", "14、15、16 屆 鄉 民 代 表、 婦 聯 青 溪 壽豐支分會主任委員、婦聯青溪花蓮縣主任委員、中華民國婦女聯合會花蓮分會常務委員、國民黨壽豐鄉黨部委員、國民黨壽豐鄉黨部婦工委員、壽豐鄉志學社區理事長、中國國民黨第 17、18、19全國黨代表、現任花蓮縣第 19 屆縣議員、花蓮縣觀光大使志工隊大隊長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
