INSERT INTO "fact" VALUES('platform:2022-local:p94f5630fc0','p94f5630fc0','platform','2022-11-26','{"district_id": "hua-council-04", "election": "2022-local", "office": "hua_councilor", "text": "一、強力監督縣府合理分配資源，強化南區建設促進觀光產業鏈經濟。\n二、督促縣政加速健全鄉鎮社福網絡，拉近城鄉差距，打造優質友善環境。\n三、促進地方整體規劃，以文化為創意行動平台協助地方改造活化閒置空間及地盡其利的舒適環境。\n四、培訓青年力新思維，吸收專業人才創造城市蛻變，促進地方多元面向發展就業商機。\n五、充實學校教育資源，提升偏遠校區數位學習能力強化學生競爭力。\n六、尊重軍、公、教、警、消專業強力捍衛其權益及尊嚴，督促治安及救災相關單位救災設備及人員訓\n練，建立完整防災體系，保障人民生命財產安全。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
