INSERT INTO "fact" VALUES('platform:2022-local:pa64148501e','pa64148501e','platform','2022-11-26','{"district_id": "hua-council-05", "election": "2022-local", "office": "hua_councilor", "text": "一、積極爭取婦女權益，協助辦理各項婦女研習。\n二、協助青年提升職業技能，爭取並創造就業機會。\n三、積極籌設物資銀行，使急難受助者能即時獲得協助。\n四、努力推動原住民部落特色產業，開發建立行銷平台。\n五、關懷照顧老弱婦孺、低收入戶、單親及高風險家庭。\n六、積極協助急難救助，法律扶助及交通事故的工作。\n七、努力推動原住民族語學習及文化扎根工作。\n八、尊重各宗教信仰給予應有的扶植。\n九、積極督促政府辦理各類公職考試輔導。\n十、積極爭取各部落聚會所設立，文化場域設置。\n十一、努力爭取原住民地區各項建設。\n十二、積極爭取原住民文化健康站，達成每部落皆有文化健康站。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
