INSERT INTO "fact" VALUES('platform:2022-local:pc671c2e6f7','pc671c2e6f7','platform','2022-11-26','{"district_id": "hua-council-03", "election": "2022-local", "office": "hua_councilor", "text": "我 參 選 的 區 域 是 花 蓮 縣 吉 安 鄉 第 三 選 區，包 含 吉\n安、壽豐、鳳林、萬榮、光復、豐濱六鄉鎮，本著「心\n繫鄉里、守護鄉親、繁榮鄉里、力拼經濟」的態度，\n因此我主張：六帶一路，「六帶」就是自然生態保\n育帶、東海岸觀光帶、都市發展中心帶、產業居住\n帶、教育科技帶、觀光休閒農業帶，「一路」意指\n蘇花高速公路銜接花東高速公路，如此花蓮才能全\n方位發展開來，讓花蓮值得更好。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc671c2e6f7','pc671c2e6f7','profile','2022-11-26','{"education": ["花蓮縣明義國小\n花蓮縣立吉安國中\n國立花蓮高級工業職業\n學校\n大漢技術學院\n國立東華大學企管碩士"], "election": "2022-local", "experience": ["中國國民黨中常委\n中國國民黨青工總會全國總會長\n中國國民黨花蓮黨部副主委\n花蓮縣青年工作總會總會長\n中國國民黨第 19 屆、第 20 屆黨代表\n財團法人花蓮縣教育基金會董事長\n聖南宮管理委員會主委\n永安宮管理委員會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC3%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
