INSERT INTO "fact" VALUES('platform:2022-local:pdb287922cd','pdb287922cd','platform','2022-11-26','{"district_id": "hua-council-10", "election": "2022-local", "office": "hua_councilor", "text": "護權益 顧民生\n1. 促請設立卓溪鄉老人長照中心，建置「醫養合一」照護機制，讓老人能在自己家鄉安老，讓照護更安心，實現長照在地化。\n2. 促請改善原鄉照服員薪資及勞動條件、精進服務模式、強化人力培育及技職訓練，滿足原鄉及偏遠地區長照需求。\n3. 後疫情時代各項產業環境變化，爭取加強原住民族亮點產業推升計畫，設置部落行銷據點，開展創新投資、創造經濟動能。\n4. 後疫情產業發展策略：爭取配合輔助政策計畫鼓勵創業投資，促進產業升級，振興部落經濟發展，穩定部落生計。\n5. 爭取智慧農業輔導團隊，設立部落－生技有機農場，增進部落種植技藝、農地畜產管銷技術，增加部落婦女及族人收入。\n6. 爭取環境永續丶產業創新、運用部落生態優勢環境資源，輔導部落種植高經濟作物，加強現有特用作物品質產銷多元發展。\n7. 面對極端氣候環境衝擊，部落簡水及農灌水源，遭受暴雨沖刷，地質變動，年年水荒，生計深陷困境， 促請政府勇於面對從速從\n優檢視水荒困境地區，全面改善部落人民民生用水。\n8. 面臨高齡社會，爭取設立「原鄉國際慈悲關懷」部落，建置部落追求互信合力醫到宅 老終安目標，關懷長者、身障者、弱勢族群\n及社會邊緣人，提供完善的人性關懷服務。\n9. 國土計畫法 114 年 4 月 30 日制度實施，促請重視原住民傳統領域土地劃設、適度調整及放寬農地變建地之變更丶更正編定政策，\n並加強化社聚落居住環境土地，因應部落居住需求。\n10. 促請加強督促申辦增劃編原住民保留地辦理進度與稽核機制，依法處理核配不實取得耕作權與所有權之土地，杜絕侵權。\n11. 爭取設立平地鄉鎮山地原住民聯誼中心基地與設施，提供族人生活關懷照護聯繫丶留鄉青年子女各技職資源培訓，民族文化技藝\n傳承學習與諮詢服務平台。\n12. 為落實原住民族教育，運用脈絡戮力向上級爭取各項資源及經費推動原鄉教育、充實在地產業、地方教育、民族文化等資源。為\n促進花蓮縣原鄉農業部落產業發展，促請政府重視小農特殊化、強調品種特殊性，做好花蓮縣農業三品三專（品種專有、品牌專區、\n品質專業）讓花蓮縣的商品有更好的價值、奠定花蓮縣休閒農業發展的基礎。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC8-10%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pdb287922cd','pdb287922cd','profile','2022-11-26','{"education": ["明新科技大學管研所管\n理學碩士畢業\n大漢工商專科學校財稅\n科畢業"], "election": "2022-local", "experience": ["現任卓溪鄉民代表會主席\n花蓮縣政府南區服務中心副主任\n卓溪鄉代表會三屆代表一屆副主席\n87-89 玉里鎮公所 89-91 富里鄉公所\n原保地登記專員\n啟智中心教保主任\n台灣師範大學特教學系學分班\n文化大學地政學系學分班\n原住民土地登記專業人員結業"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC8-10%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pde739c60c6','pde739c60c6','bulletin','2022-11-26','{"district_id": "hua-council-01", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pde739c60c6','pde739c60c6','platform','2022-11-26','{"district_id": "hua-council-01", "election": "2022-local", "office": "hua_councilor", "text": "民意急先鋒 鄉親的麥克風\n1. 長期關注並推廣扶老攜幼的青少年、銀髮族議題，讓年輕人願意留在花蓮發展，安居樂業，創建青\n銀共好環境。\n2. 安全、適當的幼教環境體系建置，鼓勵生育並重視幼兒相關福利政策，減緩超高齡社會的嚴峻情況。\n3. 構築公園新亮點，打破傳統公園既定印象，創造創新、安全、適合各年齡層的新式公園，提升在地\n居住好品質並創造觀光新景點。\n4. 持續監督美崙溪整治計畫，妥善整體規劃休憩環境與景觀建設。\n5. 打造花蓮市成為步行城市，推動生活便利安全性，宜居、安居、樂居。\n6. 推動社區巷弄經濟學，提高花蓮特色經濟發展。\n7. 爭取改善停車空間，解決觀光高峰期在地人停車的困境。\n8. 提升在地傳統市場，各方面進行改善，友善店家友善民眾，打造安全、衛生、乾淨新五星級市場。\n9. 持續推動各項公益活動，讓愛傳遞下去。支持推動花蓮加入參與聯合國 SDGs 永續發展行列。\n10. 積極監督政府各項政策及工程，讓花蓮環境更加成為友善城市，加強並維護花蓮的軟硬實力，帶動\n整體經濟。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('profile:2022-local:pde739c60c6','pde739c60c6','profile','2022-11-26','{"education": ["國立東華大學管理學院\n高階經營管理碩士畢"], "election": "2022-local", "experience": ["花蓮縣議會第 1 9 屆議員\n中國國民黨第 21 屆中央委員\n花蓮縣婦女經貿文化交流協會創會會長\n中華民國青溪婦女協會常務理事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pebe5dd40b0','pebe5dd40b0','bulletin','2022-11-26','{"district_id": "hua-council-06", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pebe5dd40b0','pebe5dd40b0','platform','2022-11-26','{"district_id": "hua-council-06", "election": "2022-local", "office": "hua_councilor", "text": "一、部落基礎建設：\n1. 打造社區居住安全環境。\n2. 資訊站的設置，活絡部落資訊傳達。\n3. 各鄉鎮文化產業經濟的發展。\n4. 各鄉鎮意象設置，表徵在地文化特色：將地名建物回歸各鄉鎮或其他與部落有關\n淵源的傳統文化命名。\n5. 建構部落完整廣播系統，以利傳達訊息。\n二、開辦部落社區大學：\n1. 營造社區文化語言、學習環境。\n2. 社區學童課輔中心，營造國中小學課後輔導機制。\n三、推動社會福利工作，結合原住民族家庭服務中心辦理：濟弱扶傾，就業服務，法律\n輔導，救濟物資發放，與門諾基金會，資源連結推動社區醫療體制。\n四、文化產業發展 : 提升各鄉鎮文物館典藏之文物。\n五、籌組地方建設諮詢委員會組織。\n六、強化部落社會組織 - 部落頭目制度及年齡階級制度之推動。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
