INSERT INTO "fact" VALUES('profile:2022-local:peca6b544a1','peca6b544a1','profile','2022-11-26','{"education": ["花崗國中\n花蓮高工\n慈濟科技大學醫學影像\n暨放射科學系\n東華大學公共行政學系\n硏究所法學碩士"], "election": "2022-local", "experience": ["花蓮市第十七屆補選市長丶第十八屆市\n長\n第十六～十八屆縣議員\n中國國民黨中央常務委員\n國家考試及格醫事放射師\n救國團 96 年度花蓮縣社會優秀青年\n（花蓮縣衛生局丶富里鄉衛生所丶蘇澳\n榮民醫院）醫事放射師"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf662504649','pf662504649','bulletin','2022-11-26','{"district_id": "hua-council-02", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf662504649','pf662504649','platform','2022-11-26','{"district_id": "hua-council-02", "election": "2022-local", "office": "hua_councilor", "text": "( 一 ) 積極、用心、腳踏實地、務實的為民服務，排難、解紛，讓本區鄉親力求安和樂利。\n( 二 ) 關懷青少年教育、思維、休閒、運動、就業、抒發情緒等，輔助正向發展。\n( 三 ) 重視婦幼、身障、清寒中低收入等弱勢族群，督促政府對於教育、社福等預算不得縮減，\n並確實公平落實執行。\n( 四 ) 地方應興應革強力監督，建設積極爭取，並要求盡力符合民意。\n( 五 ) 本區噪音、禁限建、公有地遍佈，長期阻礙發展，困擾鄉親，定聽取民意，並結合村、鄉、\n縣及各級民代共同發聲，要求突破解決。\n( 六 ) 本區農、漁、工、商、休閒等業，督促政府重視輔導補助，並積極發展特色。\n( 七 ) 會傾聽民意，不分族群及黨派、不畏困難，公正的做該做的事。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC1%E3%80%812%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:15:31Z');
