INSERT INTO "fact" VALUES('bulletin:2022-local:p1ef26e24fe','p1ef26e24fe','bulletin','2022-11-26','{"district_id": "tnn-council-09", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p1ef26e24fe','p1ef26e24fe','platform','2022-11-26','{"district_id": "tnn-council-09", "election": "2022-local", "office": "tnn_councilor", "text": "1、母語是國際化根本應比照中英文時數授課。\n2、改正國高中歷史課本開羅宣言不實內容確保台灣主權。\n3、傳承父親李文正前議員熱愛鄉土精神一人當選兩人服務。\n4、環保局應實施省時省力省錢升降子母車定點收垃圾從大樓開始。\n5、透天厝污水接管有補助公寓大廈污水改管也應補助才符合公平並提高污水接管率。\n6、營造鯤喜灣成為世界級親水海岸通盤檢討整體規劃帶動地方發展。\n7、輔導媲美四草綠色隧道四鯤鯓紅樹林自然生態旅遊。\n8、廢止公職選舉每票30元補助。\n9、解構台南運河水域營造親水環境帶動沿岸水上觀光發展。\n10、利用河道港灣碼頭停泊遊艇帆船發展離島藍色公路使台南更具海洋城市魅力。\n11、行政區單位應隨選區調整合併減開源節流增加老人福利。\n12、督促建平8街西端、華平路尾拓寬、和緯路連接安北路、遠洋漁港連接永華路跨港大橋儘速完成。\n13、恢復古都全馬設計一鯤鯓到七鯤鯓路線以建城400年賣點。\n14、86底下應有機車便道永成路應向南延伸。\n15、增加人力物力儘速結紮tnr解決流浪動物社會問題。\n16、補助老人裝假牙經費能夠全部到位。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('profile:2022-local:p1ef26e24fe','p1ef26e24fe','profile','2022-11-26','{"education": ["長榮大學會計資訊系\n崑山中學\n安平國中\n日新國小"], "election": "2022-local", "experience": ["直轄市台南市議會第3屆市\n議員\n中山大學政治學研究所\n台南市議員李文正特別助\n理\n南都電台我愛台灣節目主\n持人\n台南行動教會執行長\n民進黨第16～20屆全國黨\n員代表"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E4%B9%9D%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p2b61a7fe14','p2b61a7fe14','bulletin','2022-11-26','{"district_id": "tnn-council-13", "elected": true, "election": "2022-local", "office": "tnn_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%BA%8C%E5%8F%8A%E7%AC%AC%E5%8D%81%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p2b61a7fe14','p2b61a7fe14','platform','2022-11-26','{"district_id": "tnn-council-13", "election": "2022-local", "office": "tnn_councilor", "text": "1. 成立台南原住民0-6歲幼兒托育照顧中心，增取相關托育補助，以減輕家庭照顧及經濟上的負擔，同時引進族語文化教育以達到傳\n承文化語言之功能；\n2. 健全原住民長者照顧政策，除廣設原住民族文化健康站，協助關照長者的身心健康之外，也積極爭取長者之健康醫療補助，讓長\n輩老有所依；\n3. 爭取建置「原住民族聚會所」，營造一個適合族人聚會與活動之溫暖安全的「家」，可做為部落大學、幼兒托育、長輩安養等生\n活的場域，達到幼有所養、老有所依、老幼共學的目標；\n4. 爭取設置「原住民體育公園」或戶外適合大型傳統競技及球類體育活動之設施及空間，以積極推動族人健康運動之目標；\n5. 協助原住民各教會及社團辦理活動，以及增加相關補助經費，以積極發展原住民教育、文化及體育等各項活動，有助於族人身心\n靈的健全照顧與發展；\n6. 建置台南原住民完善之健康醫療政策，尤其針對勞動之中壯青年族人部分，除了加強相關醫療與健康的宣導與補助之外，亦增進\n相關社會福利補助之措施，以建構安全穩定之家庭照顧服務平台；\n7. 建置台南原住民勞工在就業機會、職能輔導、勞資協調、法律諮詢與溫暖陪同等全面性的服務平台，讓族人安心就業與生活，尤\n其針對原住民青年及婦女就業部分提供更多的就職選擇與機會；\n8. 持續推動與建構更完善之民族教育政策，以及提供幼童免費之課後輔導，並爭取擴大學生就學（國中小及大專院校）相關補助以\n及獎學金金額及名額提高，另外針對多元才藝的孩子給予多元智能培訓獎勵金，達到鼓勵與協助培育原住民多元人才的發展；\n9. 建構安全、便宜及便利之租屋平台服務，並爭取建立原住民安全社會住宅政策，讓族人安居樂業，實現居住正義。\n10. 持續推動「台南札哈木原住民族文創園區」工程，積極發展原住民族傳統與現代之文化、藝術、歌謠與舞蹈，並建構原鄉與台南\n原住民農特產銷平台與據點，成為台南新亮點。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/05%E8%87%BA%E5%8D%97%E5%B8%82/%E7%AC%AC%E5%8D%81%E4%BA%8C%E5%8F%8A%E7%AC%AC%E5%8D%81%E4%B8%89%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
