INSERT INTO "fact" VALUES('profile:2022-local:p6fa88d626e','p6fa88d626e','profile','2022-11-26','{"education": ["南開工專畢業\n苗栗國中畢業\n大同國小畢業"], "election": "2022-local", "experience": ["第17、18屆泰安鄉鄉長。\n中國國民黨鄉黨部主任委員。\n北泰雅鄉區聯誼會副會長。\n苗栗縣議員助理。\n苗栗國中家長會長。\n斯瓦細格教會長執。\n梅園、汶水國小職員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/08%E8%8B%97%E6%A0%97%E7%B8%A3/%E7%AC%AC7%E3%80%818%E9%81%B8%E8%88%89%E5%8D%80/%E7%AC%AC7%E3%80%818%E9%81%B8%E8%88%89%E5%8D%80%E8%AD%B0%E5%93%A1%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p629769c6e4','p629769c6e4','bulletin','2022-11-26','{"district_id": "hua-council-07", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p629769c6e4','p629769c6e4','platform','2022-11-26','{"district_id": "hua-council-07", "election": "2022-local", "office": "hua_councilor", "text": "1. 爭取原住民族傳統競技、體育發展、培育原住民運動專業人才預算經費提昇。\n2. 督促政府活化原鄉學校閒置空間，積極發展老幼共學環境。\n3. 督促政府扶植原住民各項產業、強化原住民各項職業訓練，打造屬於花蓮縣原住民族文化創\n意產業，以改善原住民經濟，提升就業機會。\n4. 加速推動設立「原住民流行音樂基地」，透過音樂活動爭取文創產業能見度，吸引流行音樂\n產業匯聚，打造花蓮縣成為太平洋左岸音樂重鎮。\n5. 支持原鄉回流青年，督促政府培植輔導跨部落原住民族青農或創農企業，推動跨部落休閒農\n業連結。\n6. 協助原鄉爭取交通基礎建設經費，逐步改善各部落農路及主要聯絡道路，以維護鄉親生命財\n產安全。\n7. 督促縣府加強原鄉醫療服務，強化老人照護並落實急難救助等社會福利。\n8. 督促政府落實「一部落一聚會所」，促成各部落聚會所工程如期如質完工，以提供部落族人\n優質的生活休憩與歲時祭儀活動空間。\n9. 督促政府推動與建構完善之民族教育政策，提升族語文化的地位。\n10. 推展原住民技職教育，輔導取得各職類技能證照，爭取企業民間等實習實戰經驗以利未來\n求職及創業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('profile:2022-local:p629769c6e4','p629769c6e4','profile','2022-11-26','{"education": ["私立四維高級中學\n大漢技術學院資訊工程\n科"], "election": "2022-local", "experience": ["第 19 屆瑞穗鄉民代表會代表\n第 20 屆瑞穗鄉民代表會副主席\n第 19 屆花蓮縣議會議員\n111 年花蓮縣議會農業小組召集人"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p9c11191d7e','p9c11191d7e','bulletin','2022-11-26','{"district_id": "hua-council-06", "elected": true, "election": "2022-local", "office": "hua_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p9c11191d7e','p9c11191d7e','platform','2022-11-26','{"district_id": "hua-council-06", "election": "2022-local", "office": "hua_councilor", "text": "全心全力 守護部落\n專業監督 行政細節\n一、生活在安全的環境：重新檢視各部落生活條件，調查潛在危機區包括道路建設、擋土設施、溪流整治、\n環境汙染，事先勘查、統計， 編列預算提早施作改善工程，預防災害發生，達到預防勝於治療的效果，\n保障部落基本生活品質。有地就要有路，爭取經費，鋪設產業道路，讓族人能充分發揮土地利用價值。\n二、定居在自己的土地：全力協助取得原住民保留地所有權狀，不要再讓族人空等待。監督國土計畫實施進\n度與執行細節，確保部落建物順利合法化，積極運用國土計畫工具，協助部落發展並新增部落住宅，讓\n返鄉定居 心願成真。\n三、產業在文化中發展：不讓青年孤單奮戰，積極統合原住民部落青年創業資源，督促政府有效搭建原住民\n特色產業平台，提供六級化產業類別合作支援，提高部落青年經濟收益。\n四、文化在日常中傳承：督促政府盡速完成一部落一聚會所，同時串聯各項如文健站等軟體計劃，促使聚會\n所實質上成為部落文化中心，時時傳承部落文化。建立部落文化資料庫平台，提供部落青年田調口訪資\n源，累積耆老智慧，透過科技媒介克服空間障礙，成為新的傳承文化管道。爭取資源，擴大各部落各類\n型文化傳承工作。\n五、教育在時代中精進：擴大推動民族教育，讓 wawa 在文化脈絡中學習世界的知識，提高原住民學生教育\n獎學金，精進適性教育，鼓勵投入軍警、輔導國考擔任公教人員，穩定部落青年工作職業，提高部落在\n社會發聲的力量。\n不分黨派 全心問政 不分部落 全面服務", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
INSERT INTO "fact" VALUES('profile:2022-local:p9c11191d7e','p9c11191d7e','profile','2022-11-26','{"education": ["世新大學社會研究所\n碩士畢業\n文藻外語大學副學士\n天主教聖功女中"], "election": "2022-local", "experience": ["花蓮縣議會第 19 屆議員\n總統府原轉會委員\n立法院國會助理\n台南市議員助理\n花蓮海星中學原專班教師\n花蓮水土保持局農村再生顧問師\n花蓮縣光復鄉大馬太鞍社區發展協會\n總幹事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T01:43:45Z');
