INSERT INTO "fact" VALUES('platform:2022-local:p328720939d','p328720939d','platform','2022-11-26','{"district_id": "khh-council-14", "election": "2022-local", "office": "khh_councilor", "text": "忠德「新選擇 新希望 原民福祉看得見」\n監督市政、爭取預算，促進原住民族共同權益及利益。\n於擔任高雄市政府顧問一職，誠心溝通協調，完成多項族人陳情服務案件；高忠德忠於人民，服務重執行講效率，鄉親安心。\n政見理念：\n1、督促政府儘速修復南橫（勤和～拉芙蘭）路段為永久安全路廊，使其恢復榮景，促進部落產業發展\n2、責成市府增編部落建設經費預算，打造桃源區為宜居文化鄉城，推展原住民文化觀光產業\n3、積極爭取預算，健全桃源區部落路平專案，建設公共衛生及安全設施\n4、為確保部落生命財產安全，督促政府積極爭取各部落護岸工程經費預算\n5、營造部落年輕化，爭取資源鼓勵知識青年留在部落發展長才\n6、增設桃源區完整資訊監控系統\n7、建山里行政區土地權責移轉桃源區公所管理\n8、督促政府修復高山島農路，嘉惠農民，利興農業發展\n9、極力爭取興建高中里風雨球場\n10、設置原住民專屬假日部落市集，提供族人展示空間及行銷通路\n11、社會住宅公設空間設置原創商鋪，族人創作品有展現機會\n12、落實保障都會區族人，爭取租屋及青年創業設備補助\n13、建置政府與原住民教會之夥伴關係，寬列經費，使教會自主性辦理事務，凝聚族人向心力\n14、設立原住民人民社團同鄉會聯合辦公室，檢討並明訂各項補助規定，健全人民團體服務效能\n15、關懷大高雄原住民軍職子弟升遷及權利維護事項\n16、全力捍衛族人勞工權益，責成市府成立原住民勞工糾紛專屬諮詢服務", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p328720939d','p328720939d','profile','2022-11-26','{"education": ["高雄市樟山國小\n高雄市寶來國中\n陸軍士官學校"], "election": "2022-local", "experience": ["陸軍士官長，執業高山嚮導及搜\n救斜角早午餐負責人，台灣原住\n民權益促進會委員，台中市布農\n族邁阿尚協會理事，高雄市桃源\n區南橫傳統領域文化自然資源自\n治協會籌備主任委員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/05%E7%9B%B4%E8%BD%84%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/06%E9%AB%98%E9%9B%84%E5%B8%82/%E9%AB%98%E9%9B%84%E5%B8%82%E7%AC%AC12.13.14.15%E9%81%B8%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('platform:2022-local:p35747b7ff2','p35747b7ff2','platform','2022-11-26','{"district_id": "nan-council-07", "election": "2022-local", "office": "nan_councilor", "text": "1、秉持公平、正義與比例原則，力促縣政府落實執行地方均衡之發展。\n2、積極爭取營造原鄉特色之基礎建設，推動並扶持原鄉部落文化、生態及農業遊憩觀\n光產業。\n3、力促縣政府積極改善原鄉農、產業道路，以改善並活絡原鄉農業之經濟產業。\n4、力促縣政府優先改善原鄉教育環境與設備，以縮短城鄉教育資源之差距。\n5、力促縣政府積極扶持原鄉民間長照機構之設立，以落實原鄉老人及弱勢族群之起居\n生活與身心健康照護。\n6、力促縣政府落實都會原住民就業輔導與經濟、生活之照護。\n7、積極爭取十六省道之拓寬改善工程，以確保農產運輸與交通的安全。\n8、積極爭取濁水溪線消防分隊（站）之設立，以保障人民生命財產之安全。\n9、積極監督縣政府落實中央政府制定或推動之原住民族相關政策與事務。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC6.7.8%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p35747b7ff2','p35747b7ff2','profile','2022-11-26','{"education": ["南投縣立信義鄉地利國小\n畢業\n南投縣立民和國中畢業\n國立南投高中畢業\n文化大學史學系畢業"], "election": "2022-local", "experience": ["國民黨信義鄉民眾服務站主任\n救國團信義鄉團委會主任\n後備軍人信義鄉輔導中心主任\n南投縣信義鄉第 20 屆鄉民代表\n信義鄉體育委員會會長\n南投縣原住民教育協進會理事長\n南投縣第 19 屆縣議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC6.7.8%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('platform:2022-local:p7ff5ea1b58','p7ff5ea1b58','platform','2022-11-26','{"district_id": "nan-council-06", "election": "2022-local", "office": "nan_councilor", "text": "一、落實原住民族基本法維護原住民傳統領域及原住民保留地，爭取回復邵族原住民\n應獲得保障的固有傳統土地資源、居住生活及文化產業經濟發展等權利。\n二、全職為民服務，爭取地方建設，加強農業、觀光休閒及工商業發展，提升縣民生\n活水準、就業機會及收入。\n三、持續關懷協助落實弱勢老弱婦孺福利措施，爭取更完善保障中低收入戶、老人、\n身心障礙及單親家庭等弱勢族群權益的政策。\n四、繼續為提升都會區原住民生活、居住、工作、就學、就醫與文化傳承發展權益，\n加強向政府爭取更多立即可行的措施方案。\n五、落實每年舉辦都會區與原鄉平地原住民歲時祭典文化等常態性活動。\n六、全力爭取興建「南投縣都會區原住民文化活動聚會所」。\n七、服務不分區域，照顧不分族群，以南投縣原住民族群需求與權益為優先。\n八、落實保障原住民族政治文化、經濟社福與教育權，堅持土地資源環境與居住正義，\n促進地方均衡永續發展及族群和諧共榮。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC6.7.8%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p7ff5ea1b58','p7ff5ea1b58','profile','2022-11-26','{"education": ["魚池初中畢業\n南投高中畢業\n臺灣大學商學系畢業\n暨南大學公共行政系碩士\n專班畢業"], "election": "2022-local", "experience": ["現任南投縣第 19 屆平地原住民議員\n原住民族委員會邵族前專任委員\n現任邵族民族議會議長\n現任南投縣都會原住民生活關懷協會理事長\n現任日月村睦鄰救援隊隊長\n現任伊達邵明德長青會理事長\n現任南投縣體育會傳統射箭委員會主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/10%E5%8D%97%E6%8A%95%E7%B8%A3/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%AC%AC6.7.8%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p75beb1f83f','p75beb1f83f','profile','2022-11-26','{"education": ["東華大學族群關係與\n文化硏究所\n淡江大學中國語文學系\n花蓮女中\n宜昌國中\n忠孝國小"], "election": "2022-local", "experience": ["花蓮縣第 16. 17. 18. 19 屆縣議員\n花蓮縣棒委會主委\n花蓮縣原住民族部落大學校長\n製作邦查 wa wa 放暑假有聲書獲金曲獎\n原住民電台台長\n花蓮縣體育會理監事\n花蓮縣管樂協會理事長\n飛碟聯播網等媒體工作 13 年\n長年推動產業工藝體育等"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/15%E8%8A%B1%E8%93%AE%E7%B8%A3/%E8%8A%B1%E8%93%AE%E7%B8%A3%E7%AC%AC4-7%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
