INSERT INTO "fact" VALUES('profile:2022-local:p11220dd311','p11220dd311','profile','2022-11-26','{"education": ["政治大學 政治\n學系\n彰化高中\n精誠國中\n東芳國小"], "election": "2022-local", "experience": ["總統蔡英文彰化競\n選總部 青年部主\n任\n彰化市長林世賢競\n選總部 執行總幹\n事\n彰化縣磺溪文化永\n續協會 理事長\n民主進步黨中央黨\n部青年部 督導幹\n部\n彰化縣醫療界聯盟\n執行秘書\n喚醒彰化青年聯盟\n發起人\n政治大學野火陣線\n社長\n台灣中社 秘書長\n臺灣大學國家發展\n研究所 碩士生"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p2512c12a07','p2512c12a07','bulletin','2022-11-26','{"district_id": "cha-council-07", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p2512c12a07','p2512c12a07','platform','2022-11-26','{"district_id": "cha-council-07", "election": "2022-local", "office": "cha_councilor", "text": "面臨百業蕭條的經濟局勢，需要振興家鄉，我們就必須做多方面考量、找出原因、對症下藥，將聘請北斗區地方\n賢能士紳組成策略顧問團，一起為北斗區四鄉鎮的建設及福利認真打拼。\n一、我將盡議員之責，審查監督縣府預算之職責，為大北斗地區之縣民爭取福利。\n二、必需加強治安及消防設施，充分利用資源，使警消系統更加完備堅強。\n三、督促縣府落實社會福利政策，保障婦女、兒童、老人、殘障朋友、勞工及弱勢族群之權益。\n四、勸導鼓勵失學及待業的青少年，輔導他們學習第二專長，並依其專長、興趣，參與縣府合法登記之民間文\n化、藝陣等社團，改善青少年治安問題。\n五、整合北斗區四鄉鎮地方特色、文化之美、花卉之都、美食街、農家特產品，結合奠安宮等廟宇、促進地方觀\n光事業均衡發展。\n六、強化大北斗地區醫療網。\n七、提昇國中（小）教育硬（軟）體建設，落實偏遠地方教育、減少城鄉差距。\n八、維護及提倡鄉土文化之延續，使本土文化發揚光大。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p2512c12a07','p2512c12a07','profile','2022-11-26','{"education": ["螺陽國小畢業\n北斗國中畢業\n中州技術學院（五專部）\n畢業\n日本沖繩國際大學畢業"], "election": "2022-local", "experience": ["李醫師診所公關\n國際佛光會中華總會北斗分會會員\n彰化七星獅子會第32屆會長\n彰化信德慈善會永久會員\n彰化慈化慈善會永久會員\n彰化神將藝陣文化協進會顧問\n北斗國小家長委員會常務委員\n螺陽國小家長委員會顧問\n彰化縣議會第17、18、19屆議員"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
