INSERT INTO "fact" VALUES('platform:2022-local:p3ed0c8611d','p3ed0c8611d','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "●監督縣府預算及執行效能\n●督促縣府關懷婦幼安全及權益、弱勢族群照護、銀髮族身心保健。\n●全力支持警政消防預算，以保障社區鄰里的治安與婦幼安全。\n●督促改造公共空間，爭取閒置土地栽植花木，營造宜居城市。\n●督促政府對於弱勢家庭的實質給予補助。\n●積極推動發展在地特色產業、文化慶典、觀光景點，凝聚在地鄉親的力量，\n發展特色觀光產業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
