INSERT INTO "fact" VALUES('platform:2022-local:p5109e73e40','p5109e73e40','platform','2022-11-26','{"district_id": "cha-council-05", "election": "2022-local", "office": "cha_councilor", "text": "一、乾淨選舉、理性監督縣府施政、杜絕貪汙瀆職、誠信服務。\n二、致力公益、扶助弱勢、健全社會福利制度。\n三、督促縣府積極進行全縣土地使用計劃，推動城鄉發展擴大都市計劃，以縮短城鄉差距繁榮地方經\n濟，提升就業機會。\n四、推動改善區域排水，避免豪雨成災，保障人民生命財產安全。\n五、督促道路拓寬工程，並推動全面電線電纜地下化，以改善道路景觀及居住環境。\n六、爭取設立農產品產銷中心增加農民收益，活絡地方產業文化，促進地方繁榮。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
