INSERT INTO "fact" VALUES('platform:2022-local:p552f706578','p552f706578','platform','2022-11-26','{"district_id": "cha-council-08", "election": "2022-local", "office": "cha_councilor", "text": "1、關心青年發展，推動產業升級與創新，改善青年就業結構。\n2、關懷弱勢族群並協助新住民培養競爭力。\n3、爭取農漁牧業產業升級，結合地方資源以推廣觀光事業，行銷地方特色。\n4、推廣中科園區，吸引廠商進駐，增加就業機會。\n5、守護長者，協助各社區關懷據點辦理各項服務。\n6、監督環境污染、廢土處理，實現永續發展。\n7、推動文化傳承，重視教育扎根，建立家鄉認同感\n8、議會透明監督，堅持行使議員的監督職責。\n9、堅守民主信念，秉持清廉，勤政態度。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
