INSERT INTO "fact" VALUES('platform:2022-local:p55a8560181','p55a8560181','platform','2022-11-26','{"district_id": "cha-council-07", "election": "2022-local", "office": "cha_councilor", "text": "忠於所託 勇於建言 建設大北斗 守護好家園\n1：民意優先、繁榮地方、照顧弱勢、提振經濟。\n2：防疫第一、配合指引、平安健康、保護庶民。\n3：監督縣政、服務鄉親、看緊縣庫、做好鄉親與縣府之間的橋樑。\n4：關懷長輩、關心年輕人、關照婦幼，讓老有所終、壯有所用、幼有所長。督促縣府全方位重視社會福利。\n5：教育是百年大計，持續爭取各級學校軟硬體建設，加強營養午餐食材控管暨質的提升。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p55a8560181','p55a8560181','profile','2022-11-26','{"education": ["一田尾國小畢業。二田尾\n國中畢業。三省立北斗高\n中畢業。四國立台中商專\n附設空專國貿科畢業。五\n大葉大學國際企業管理學\n系碩士畢業。"], "election": "2022-local", "experience": ["一彰化縣議會第十二、十三、十六、", "十七、十八、十九屆議員。二彰化縣田尾鄉第十三、十四屆鄉長。三彰化家扶中心員林區扶幼主任委員。四74年當選全國優秀青年。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p5e8deeebcb','p5e8deeebcb','bulletin','2022-11-26','{"district_id": "cha-council-01", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p5e8deeebcb','p5e8deeebcb','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "1.推動長照據點普及化，結合地區醫療診所定期社區健檢，65歲以上獨居失智\n行動不便長者定期訪視。\n2.檢討排水系統與改善河川與水資源污染及整治，提升防洪功能美化環境強力\n監督改善轄區排水問題。\n3.推動地方產業提升與轉型，爭取優質就業機會，擺脫低薪惡名。\n4.恢復「國中小學校保全」學生安心上學。\n5.簡化青年創業獎勵補助政策，鼓勵青年人成功創業。\n6.提升警義消人員裝備經費，加速老舊設備汰新，確保執勤人員安全。\n7.廣推共融遊戲場域，打造育兒友善環境，建立全齡的無障礙公共空間。\n8.推動縣內農業升級，推廣農產品多元行銷通路。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5e8deeebcb','p5e8deeebcb','profile','2022-11-26','{"education": ["花壇國小\n精誠中學\n彰化高中\n東海大學公共行\n政學系"], "election": "2022-local", "experience": ["彰化縣議會第十九\n屆議員\n花壇鄉第十六、\n十七屆鄉長\n花壇青商會2011年\n會長\n精誠獅子會2012年\n會長\n彰化縣八卦山民主\n福利協會第七屆、\n第八屆總會長\n民進黨彰化縣黨部\n執行長\n彰化縣活力旺企業\n協會秘書長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
