INSERT INTO "fact" VALUES('platform:2022-local:p63a75ffdd4','p63a75ffdd4','platform','2022-11-26','{"district_id": "cha-council-08", "election": "2022-local", "office": "cha_councilor", "text": "一、電語一通，服務就到。\n二、監督縣政，舉發貪腐，為民申冤，維護公義。\n三、建請縣府闢建芳苑工業區工區路銜接台76線以西延伸工程道路，促進地方繁榮與\n交通便利性。\n四、繼續推動二林四鄉鎮農特產推廣行銷改善農民生計。\n五、長期關懷弱勢團體，幫助其就業及補助等各項福利。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p63a75ffdd4','p63a75ffdd4','profile','2022-11-26','{"education": ["1.二林工商畢業", "2.大城國中畢業", "3.大城國小畢業"], "election": "2022-local", "experience": ["1.彰化縣議會第18屆議員無黨團結聯盟會長。", "2.彰化縣議會第13、14、15、16、", "17、18屆議員。", "3.婦女防火宣導分隊顧問。", "4.彰 化縣議會第17屆議員超黨派會長。", "5.二林四鄉鎮婦女弱勢團體召集。", "6.二林工商校友會理事。", "7.吳氏宗親會理事。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p6ce59c8b7a','p6ce59c8b7a','bulletin','2022-11-26','{"district_id": "cha-council-01", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p6ce59c8b7a','p6ce59c8b7a','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "一、落實「老有所終」老年人長期受照護，並發揮銀髮力。「壯有所用」壯年\n人能發揮所長，免於失業，而安居樂業。「幼有所長」幼年托育安全，人\n本教育並能快樂學習好好地成長。祥和富裕居住的社會環境。\n二、推動基礎建設，從彰化熱點拉起串聯，發展觀光，促進地方產業升級並整\n合資源打造以發展經濟促進地方繁榮的政策方針！\n三、結合縣府與地方慈善團體，共同照護社會弱勢，使鰥夫、寡婦、孤兒、沒\n有子女的老人家，以至殘疾的人，都能得到照顧。\n四、普設彰化縣非營利事業托兒所，以減輕雙薪家庭經濟負擔\n五、國中小學校增設冷氣裝備以利提供優質學習環境！\n六、讓彰化成音樂之都，藉音樂撫慰民心，增進親子互動，提供街頭藝人及在\n校學生音樂表演平台！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
