INSERT INTO "fact" VALUES('profile:2022-local:p714564bb74','p714564bb74','profile','2022-11-26','{"education": ["明道大學學士、明道大學\n管理學院碩士"], "election": "2022-local", "experience": ["‧受理來自全台家暴、性侵、無喪葬費個案等上萬件", "‧公益演講上千場", "‧彰化縣議員五屆", "‧員林鎮民代表一屆", "‧志工訓練專任講師", "‧電視台特別來賓"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
