INSERT INTO "fact" VALUES('platform:2022-local:p84790f7b7b','p84790f7b7b','platform','2022-11-26','{"district_id": "cha-council-08", "election": "2022-local", "office": "cha_councilor", "text": "一、極力促進二林精密機械園區近期內通過環境影響評估並儘速完成園區開發，創造\n更多就業機會，以解決人口老化及外流問題。\n二、爭取經費徹底整治二林區四鄉鎮區域排水設施，做好防汛防災，確保民眾生命財\n產安全。\n三、輔導發展特色農業及休閒農業，振興農村經濟並扶助傳統產業，照顧農民生計。\n四、積極建置長期照護據點並結合社會資源關懷獨居老人及弱勢家庭、低收入戶等落\n實社會福利政策。\n五、輔助廠商進駐中科四期園區生產，造就年輕人在地就業機會。\n六丶督促東西向76線快速道路，二林芳苑段，聯外道路週邊工程整治。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p84790f7b7b','p84790f7b7b','profile','2022-11-26','{"education": ["1.二林國小畢業。", "2.二林國中畢業。", "3.曉陽商工畢業。"], "election": "2022-local", "experience": ["1.彰化縣議會第15.16.19屆縣議員。", "2.現任二林高級中學校友會理事長。", "3.二林鎮第16.17屆鎮長。", "4.二林鎮農會第13屆理事長。", "5.二林國際獅子會會長。", "6.二林地區工業促進會顧問。", "7.中科二林園區環境督導委員。", "8.中國國民黨二林鎮黨部主任委員。", "9.二林鎮後備軍人輔導中心總督導。", "10.二林老人會顧問。", "11.中華民國十大傑出農村青年。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p8e16944c0c','p8e16944c0c','bulletin','2022-11-26','{"district_id": "cha-council-01", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p8e16944c0c','p8e16944c0c','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "彰化，大步向前走！\n各項公共事務的推動，不會因為政黨的輪替而有所停滯。差別的只是在於，執政\n的人有沒有用心、有效率的推動各項縣政建設。彰化很好，有富含文化的傳統底\n蘊、有隱形冠軍的中小企業、有多樣豐富物產的農業生產、有各行各業的優質\n勞動力。我們要做的，是如何有效整合行政效能，讓原本的彰化優勢發光發熱。\n彰化，可以更好；陞漢相信，彰化可以大步向前走！\n未來，陞漢將持續在「優化教育環境」、「催化基礎建設」、「提升產業環\n境」、「落實有效福利」等四個面向上努力，促成縣政府訂定相關的施政方針。\n優化教育環境：陞漢於108.2首倡國中小減人不減班，終促成111學年度開始，國\n中小班級人數減少1人。希望降低師生比，減少優質教師流失。未來朝向促成國\n中小每班再減少2人方向努力。並檢討教育資源分配，提升教安品質，留住彰化\n好人才。\n催化基體建設：要求針對重大民生基礎建設－火葬場、市民廣場、公共托育與托\n嬰、社會住宅、藝文展演中心、一鄉鎮一全齡公園、流浪動物收容所等提出具體\n方案。\n提升產業環境：田園工廠轉型面臨問題、產業用地與開發問題、觀光產業提升與\n能見度、老農保障與青農發展、優化各項行政申辦程序等持續監督縣府作為。\n落實有效福利：針對老弱婦孺等福利措施，檢討非法定福利的浪費，有效落實把\n資源給有需要的人、臨時急難的人。\n彰化很好，不一定模仿其他城市的發展模式，身為政治工作者，是提出符合彰化\n人心中的生活願景，督促縣府更有效積極的作為，將彰化打造成全民都願意來\n居住、願意來發展、願意來投資的宜居城市！我是莊陞漢，用心聽、認真做！！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
