INSERT INTO "fact" VALUES('profile:2022-local:pa541a75c0d','pa541a75c0d','profile','2022-11-26','{"education": ["花蓮縣太昌國民小學、花\n蓮縣吉安國民中學、花蓮\n縣四維高級中學、國立臺\n中科技大學附設空中進修\n學院副學士。"], "election": "2022-local", "experience": ["彰化縣和美鎮婦女會理事長、彰化\n縣和美鎮嘉犁社區理事長、中國國\n民黨第21屆全國代表、彰化縣林姓\n宗親會理事、彰化縣和美青溪婦女\n協會理事長、彰化縣自強早覺會理\n事長、彰化縣千禧獅子會會長、彰\n化縣和美國小家長會長。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pa562c04924','pa562c04924','bulletin','2022-11-26','{"district_id": "cha-council-06", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pa562c04924','pa562c04924','platform','2022-11-26','{"district_id": "cha-council-06", "election": "2022-local", "office": "cha_councilor", "text": "1.推動彰化縣政府遷移至田中高鐵特定區，均衡彰化縣整體發展\n2.監督縣府財政預算統籌，落實公平原則，爭取教育預算合理分配，縮短城鄉差距\n3.持續推動改善長青福利卡使用功能，讓此卡不僅只能搭公車，新增旅遊、飲食、搭乘計程車的功能，讓長青福\n利卡成為電子錢包、悠遊卡及國民旅遊卡四合一福利卡，促進長輩使用福利卡的便利性與多樣性，照顧長者的\n晚年生活。\n4.響應政府長照2.0政策，持續全面推動，彰化縣長者免費共餐\n5.推動托育一條龍再進化，提升公托質與量，增設非營利幼兒園。建構友善親子共學共遊空間，廣設親子廁所及\n停車格，擴展友善育兒環境\n6.加速推動水域整治計劃兼顧生態水質改善，提供優質親水河岸空間。整治區域排水，改善易淹水問題，確保鄉\n親生活安全\n7.力促縣府輔導農民發展精緻農業，改善農業發展，增加農民收入\n8.爭取興建社會住宅，只租不售，以嘉惠勞工、青年及弱勢家庭\n9.推動建構微型創業平台，提供優質青年創業環境\n10.督促縣府持續推動中小學童，免費營養午餐政策並充實校園設備", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
