INSERT INTO "fact" VALUES('platform:2022-local:pabebe8045d','pabebe8045d','platform','2022-11-26','{"district_id": "cha-council-02", "election": "2022-local", "office": "cha_councilor", "text": "一、持續加強社會關懷據點功能，運用政府資源與志工力量，及社會資源，讓長者在社區一起運\n動學習，共餐聊天，生活更充實，減輕子女的照顧壓力，家庭生活更美滿。\n二、推動兩性平權，提供婦女更多職訓機會，增加與社會接軌能力。\n三、持續向政府爭取經費，鼓勵年輕人回鄉投人農業，種植高經濟特色作物，振興農村發展。\n四、持續爭取地方道路，溝渠，交通號誌等地方建設。\n五、爭取公托及日照中心的設立，減輕所有家庭兼顧職場與照顧家裡長者之壓力。\n六、持續推動鹿港頂番婆水五金田園生產聚落，及都市計劃的規畫，力拼十年內完成，讓大鹿港\n地區有合法工業用地，用以利地方產業發展，年輕人有更多就業機會。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
