INSERT INTO "fact" VALUES('profile:2022-local:pb08c299d75','pb08c299d75','profile','2022-11-26','{"education": ["淡江大學全球政治經濟學\n系\n國立溪湖高中"], "election": "2022-local", "experience": ["立法委員陳素月國會辦公室主任\n行政院中區婦女企業諮詢委員\n民進黨彰化縣黨部縣代表\n永靖國小校友會副秘書長\n彰化縣長魏明谷競選團隊新聞部\n副主任\n立委陳素月縣議員陳秋蓉聯合服\n務處秘書\n美國賓州印第安那大學交換生"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pc2837b9078','pc2837b9078','bulletin','2022-11-26','{"district_id": "cha-council-02", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pc2837b9078','pc2837b9078','platform','2022-11-26','{"district_id": "cha-council-02", "election": "2022-local", "office": "cha_councilor", "text": "1.守護兒少成長，為地方爭取設立公共化托嬰中心，爭取公幼增班，檢討托育品質，監督評鑑制\n度；爭取親子館，提供婦幼安心休憩時間，傾聽地方婦幼心聲，提高婦幼健康補助，積極協助\n婦女就業。\n2.強化在地語言及雙語教育，培養國家未來人才，順利接軌國際。\n3.發揚傳統宗教文化價值，並爭取廟會傳承交流補助。\n4.提倡運動風氣及教育，推廣體育活動，監督及爭取全民運動館。\n5.重視文化保存、環境教育，監督及爭取活化中央廣播電台鹿港分台用地。\n6.積極發展鹿港觀光產業，結合鄰近鄉鎮特色產業，爭取假日市集，提供街頭藝人表演平台。\n7.落實長期照護，整合社區與鄰里資源，打造友善高齡環境；媒合義診醫護人員，為弱勢族群強\n化醫療照護需求及相關資訊上的供給。\n8.促請縣府加強並推廣青年職業訓練，成立青創基地協助青年創業，建立創業平台，增加青年朋\n友互動的機會，提升各領域的創新能量，及職場競爭力。\n9.加強推廣寵物登記及飼主責任教育，增加預算對寵物絕育、疫苗，推動認養代替購買，改善寵\n物殯葬問題，落實生命教育，及爭取寵物公園。\n◎超越黨派，爭取建設，監督縣政，勤跑基層，傾聽民意，做好服務，落實社福，關懷弱勢。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pc2837b9078','pc2837b9078','profile','2022-11-26','{"education": ["鹿東國小\n鹿港國中\n私立精誠高中\n私立東海大學"], "election": "2022-local", "experience": ["國立台灣大學法律學分班\n國立彰化師範大學EMBA進修中\n第19屆彰化縣議員\n彰化縣無黨團結聯盟副會長\n彰化縣轉生慈善會榮譽理事長\n浩大法治研究協會顧問團團長\n退休警察人員協會顧問\n彰化縣阡藝歌友會顧問\n鹿港國際青年商會\n文開國小家長會顧問\n鹿東國小家長會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
