INSERT INTO "fact" VALUES('platform:2022-local:pc81816dba9','pc81816dba9','platform','2022-11-26','{"district_id": "cha-council-04", "election": "2022-local", "office": "cha_councilor", "text": "一、監督縣政工作落實，財政用到最適當\n二、督促縣政加強經濟發展、創造就業機會、帶動年輕人返鄉工作。\n三、落實長照制度、加強對年長者生活照顧。\n四、加強有計劃性精緻農業、照顧農民、提高農民收入\n五、加強排水功能、應付氣候異常天氣以利人民居家安全。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
