INSERT INTO "fact" VALUES('platform:2022-local:pca8b402da0','pca8b402da0','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "（一）嚴加把關預算，杜絕浪費，讓納稅財源做最妥善之運用。\n（二）積極爭取建設，均衡城鄉發展，帶動商機。\n（三）監督縣政，提升行政效率，加強服務品質。\n（四）傾聽民意，重視民眾需求，做縣民最有力的代言人。\n（五）善盡職責，溝通協調，為民服務，為民謀福。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pca8b402da0','pca8b402da0','profile','2022-11-26','{"education": ["彰化縣立陽明國\n中畢業。"], "election": "2022-local", "experience": ["彰化縣議會17、", "18、19屆副議長。彰化縣議會15、", "16、17、18、19屆縣議員。彰化市彩鳳庵管理委員會副主任委員。彰化市西勢仔聖安宮顧問團團長。彰化市燒坑仔北極宮榮譽主任委員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pd54a8a6e3d','pd54a8a6e3d','bulletin','2022-11-26','{"district_id": "cha-council-01", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd54a8a6e3d','pd54a8a6e3d','platform','2022-11-26','{"district_id": "cha-council-01", "election": "2022-local", "office": "cha_councilor", "text": "‧守護婦幼\n一、普及兒童共融式公園，增進兒童遊戲安全，協助兒童健全發育。增設公園\n遮陰設施並加強設施養護，營造優質的親子同樂園地。\n二、為解決中高齡婦女重返職場續航困境，在社區籌備設立婦女二度創業輔導\n教學中心、廣聘優良業師，傳授技能，並配合婦女低利貸款，輔導創業，\n迎接人生第二春。\n‧為青年發聲\n一、擴大國中生公費施打HPV疫苗，包括男性與女性，不但可預防女性子宮頸\n癌，還可以同時預防多種生殖系統癌症，保護男生同時保護女生。\n二、力求彰化交流道特定區解編，引進高科技、高產值產業鏈及物流專區，提\n供青年就業機會，提高彰化青年薪資水平，鼓勵青年返鄉定居。\n‧照顧長者\n為體恤長者並鼓勵長者外出活動，計畫擴增長青幸福卡服務項目：長青幸福卡\n服務項目現有僅客運，未來積極爭取擴充：客運、計程車、醫療與休閒運動。\n‧人才留住由教育開始\n一、配合國家2030雙語政策，爭取編列預算協助中小學外語師資資源到位，外\n語教育從小學紮根，每個孩童都能得到完整扎實的外語教育。\n二、編列預算補助偏鄉學生（中小學）到選區內學校就讀交通費用，提高選區\n內學校就讀率。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd54a8a6e3d','pd54a8a6e3d','profile','2022-11-26','{"education": ["亞洲大學休閒與\n遊憩管理學系碩\n士"], "election": "2022-local", "experience": ["彰化市長林世賢助\n理新動力智庫婦幼\n組召集人社會安全\n網彰化召集人彰化\n青商會理事精誠獅\n子會會友大欣獅子\n會顧問信義國中小\n家長委員會顧問南\n瑤宮笨港進香顧問\n團團長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pd59786772b','pd59786772b','bulletin','2022-11-26','{"district_id": "cha-council-03", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pd59786772b','pd59786772b','platform','2022-11-26','{"district_id": "cha-council-03", "election": "2022-local", "office": "cha_councilor", "text": "一、傾聽民意、深耕基層、最暸解鄉親需求，認真打拼，服務看得到。\n二、爭取經費，全方位推動地方建設，促進地方發展；規劃闢建產業道路、出海路，以利農漁\n民生產運輸，提高農漁業收入。\n三、爭取道路養護經費，以維行車安全，加強區域排水浚渫及排水溝渠清淤，以維排水暢通。\n四、結合和美區觀光資源，推動地方觀光產業，增加鄉親觀光收入。\n五、爭取經費，配合社區社團，辦理社區生活講座或聯誼活動及結合地方公益團體，加強扶助\n弱勢、守護婦幼、關懷長青福利，以利鄉親安居樂業。\n六、全力促進地方產業轉型及升級，及農民提升農業智能、推廣休閒農業，以利地方農工業均\n衡發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd59786772b','pd59786772b','profile','2022-11-26','{"education": ["彰化縣伸港國中畢業。"], "election": "2022-local", "experience": ["一、彰化縣議會第17、18、19屆議員。", "二、伸港鄉民代表會第14、16屆代表第15屆副主席。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
