INSERT INTO "fact" VALUES('platform:2022-local:pd654f0eb86','pd654f0eb86','platform','2022-11-26','{"district_id": "cha-council-03", "election": "2022-local", "office": "cha_councilor", "text": "1.爭取美寮路拓寬工程，保障居民、學子出入通行生命財產安全。\n2.爭取塭仔港泊地，推動定位觀光景點。\n3.爭取保障老年、婦幼、弱勢團體，其應有權益福利。\n4.協助農漁會，保障農民耕作權、漁民漁業權及爭取農漁民權益、褔利，改善農漁民生活。\n5.監督縣府為民喉舌、民意優先。\n6.推動並支持彰化縣自然生態環境保護及動物保護自治條例各項的相關法案。\n7.嚴格監督彰濱工業區廢棄物處理機構並要求落實環境保護工作、保障民眾身體健康及漁業資\n源。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pd654f0eb86','pd654f0eb86','profile','2022-11-26','{"education": ["彰化師範大學碩士"], "election": "2022-local", "experience": ["彰化縣第18、19屆議員。彰化縣無\n黨團結聯盟副會長。和群國中校友\n會第三第四屆理事長。彰化區漁會\n第9屆顧問、12屆理事。伸港老人\n會顧問。鎮平子龍宮輔導宮主。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pde3ba04564','pde3ba04564','bulletin','2022-11-26','{"district_id": "cha-council-08", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pde3ba04564','pde3ba04564','platform','2022-11-26','{"district_id": "cha-council-08", "election": "2022-local", "office": "cha_councilor", "text": "1.督促76線儘速完工，擴充王功漁港服務中心、延線增設農產果菜市場，吸引觀光人\n潮購買，強化輸出通路。\n2.督促縣府設立中科二林園區專責窗口，協助廠商設廠，保障在地員工基本佔比，提\n高薪資水準，從根本解決人口老化、外流問題。\n3.持續推動社區據點，強化長照衛福大樓功能，亦供婦幼、在地居民使用，保障老少\n婦幼權益。\n4.第一線反映農、漁民所需，配合農田水利管理處區外擴大服務，督促縣府定期改善\n農田溝渠，避免第一級產業成為經濟弱勢。\n5.透過網路、現代傳播媒體等媒介，推廣在地觀光。\n6.為弱勢家庭、團體、獨居長輩，謀取社會福利。\n7.利用自身法律所學，協助民眾簡易案件排除。\n8.建請縣府恢復敬老年金369政策\n9.加強濁水溪床綠化植被，沿路種植喬木，減少大城、竹塘受六輕懸浮粒子影響。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pde3ba04564','pde3ba04564','profile','2022-11-26','{"education": ["1.二林國小", "2.員林高中", "3.台中中國醫藥大學中國藥學暨中藥資源學系"], "election": "2022-local", "experience": ["1.中國醫藥大學學生分會長2.2020總統立委大選志工3.民進黨彰化縣黨部青年聯絡處主任4.民進黨中央青年部國務青研習班隊輔議題思辯學堂引言人5.立法委員黃秀芳助理6.台中中國醫藥大學科技法律碩士生"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC08%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe6a68f8efe','pe6a68f8efe','bulletin','2022-11-26','{"district_id": "cha-council-07", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe6a68f8efe','pe6a68f8efe','platform','2022-11-26','{"district_id": "cha-council-07", "election": "2022-local", "office": "cha_councilor", "text": "監督縣政、爭取建設、服務鄉親、敢言顧人民權益\n一、督促縣府儘速完成大北斗區（北斗鎮、田尾鄉、埤頭鄉、溪州鄉）高速公路與觀光景點聯結及濁水溪系淨美\n化、公路花園、花博公園、地方小吃結合完成觀光旅遊規劃。\n二、督促縣府重視社會福利、照顧困苦無依老人及弱勢殘障同胞。\n三、督促縣府重視社會治安，保護人民生命財產安全，早日完成各重要路口監視系統設置。\n四、督促縣府改善各區域、大、中、小排水系統流暢及各農田道路給水系統改善，以保障農民權益。\n五、當一位專職議員，為人民爭取權益，做好民眾與政府間溝通橋樑。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe6a68f8efe','pe6a68f8efe','profile','2022-11-26','{"education": ["溪州國小\n明道中學初中部\n彰化高中(肄)\n中台醫專醫技科"], "election": "2022-local", "experience": ["彰化縣議會第1415161718屆縣議員\n民進黨彰化縣議會黨團召集人\n凱達格蘭學校「民間領袖與地方發展\n班」第一期\n民進黨中央政策說明種子教官"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC07%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe83951e77b','pe83951e77b','bulletin','2022-11-26','{"district_id": "cha-council-04", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pe83951e77b','pe83951e77b','platform','2022-11-26','{"district_id": "cha-council-04", "election": "2022-local", "office": "cha_councilor", "text": "1.均衡發展：推動縣治中心南移，均衡彰化整體發展。\n2.監督財政：檢視地方財政，要求謹守財政紀律範疇。\n3.健康樂活：爭取共融式休憩設施，打造親子健康運動園區。\n4.關懷身障：建置身障就業前教育，整合身障夥伴就業資源。\n5.保護婦幼：推動完善社會安全網，推動受家暴婦幼緊急避難所。\n6.照顧農民：打造農產市集，整合產銷系統，搭建兩岸農特產銷售平台。\n7.升級教育：改善教育資源不均，合理分配教育預算，縮短城鄉差距。\n8.青年返鄉：推動青年返鄉各項資源整合，提高青年首購自住房屋補助。\n9.長青福利：推動建置社區長青日托中心，建立獨居老人安心通報網。\n10.新住民權益：改善弱勢新住民生活環境、提升弱勢新住民家庭子女教育品質", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pe83951e77b','pe83951e77b','profile','2022-11-26','{"education": ["國立彰化師範大學公共事\n務與公民教育法學碩士畢\n業"], "election": "2022-local", "experience": ["彰化縣第十八、十九屆議員、啟思民本\n教育基金會董事、防災社區推廣協會理\n事長、彰化縣不動產評價委員會委員、\n彰化縣身障權益保障委員會委員、彰化\n縣網球委員會主委、彰化縣曹姓宗親會\n理事、彰化縣青年公益協會榮譽理事\n長、彰化縣青工總會長、螢光慈善會常\n務監事、員林桌球委員會主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pe906df4ffb','pe906df4ffb','bulletin','2022-11-26','{"district_id": "cha-council-02", "elected": true, "election": "2022-local", "office": "cha_councilor", "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:ped36affbe1','ped36affbe1','bulletin','2022-11-26','{"district_id": "cha-council-04", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:ped36affbe1','ped36affbe1','platform','2022-11-26','{"district_id": "cha-council-04", "election": "2022-local", "office": "cha_councilor", "text": "l.認真審查縣政府預、決算，及強力監察縣政府財產之經營管理及處分，並審慎審查縣政府所屬事業機構之組織章程。\n2.增加社會預算比例，保障婦幼安全，健全幼兒托育環境、檢討教育品質，讓父母安心工作、孩子快樂成長；推動兩性平權，推廣家\n暴防治觀念、落實老人、身心障礙、特殊境遇家庭、婦幼、勞工等弱勢團體照顧，並加強職訓與生活補助。\n3.打造員林、永靖、大村生活圈，加速周遭社區更新，全面改善周圍交通及排水系統工程以提升生活機能。\n4.鼓勵全民終身學習，加強獎勵社區結合各項資源、增設社區關懷據點，鼓勵社區民眾參與志工服務。\n5.定期舉辦免費法律諮詢及社區巡迴服務，堅持照顧弱勢家庭。\n6.持續推動「警消賠償訴訟基金」作為警消後盾，以使警消執勤無後顧之憂。\n7.爭取大村鄉門牌整編，以利消防救災單位及用路人便於尋址。\n8.持續追蹤員林南區派出所興建進度，以確保轄區治安並妥適調配警力執勤範園。\n9.重視教育督促縣府寬列經費，爭取縣內國小課桌椅改為調整式課桌椅，提升優質學習環境。\n10.督促縣府重視農業升級，積極行銷彰化地方農特產品，鼓勵年輕人投入休閒農業發展，並協助農民天然災害申請補助。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:ped36affbe1','ped36affbe1','profile','2022-11-26','{"education": ["國立彰化師範大學企業高\n階管理碩士。"], "election": "2022-local", "experience": ["彰化縣議會第18、19屆議員。員林鎮第", "17、18、19屆鎮民代表。員林螢光慈善會第20屆理事長。彰化縣愛吾礙慢飛天使關懷協會執行長。員永村社區大學課程審議委員、彰化縣員林市福寧宮聖媽會常務理事。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf353cb0d78','pf353cb0d78','bulletin','2022-11-26','{"district_id": "cha-council-03", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf353cb0d78','pf353cb0d78','platform','2022-11-26','{"district_id": "cha-council-03", "election": "2022-local", "office": "cha_councilor", "text": "．堅持居住正義，爭取社會住宅及青年住宅興建。\n．後疫情時代，協助在地青年輔導創業並提高青年創業基金額度。\n和美\n．針對在地需求，開辦職業技能訓練，降低失業率，提高工作待遇。\n．運用公有土地，增加和美停車空間，改善市容，讓全民便利使用。\n．運用閒置空間，增加運動休閒場域。\n．推廣道東朱子文化祭，再現道東書院古蹟風華，提升古建築活化利用。\n線西\n．爭取線西濱海生態公園設立，增加在地特色旅遊據點。\n．爭取台61線快速道路休息站設立，便利往來遊客，並活絡地方產業。\n伸港\n．致力推動海濱觀光活動，爭取彰濱隔離水道導入常態性水上活動。\n．加強環境教育與保育，深化推廣伸港溼地生態旅遊。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pf3e3aca021','pf3e3aca021','bulletin','2022-11-26','{"district_id": "cha-council-04", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pf3e3aca021','pf3e3aca021','platform','2022-11-26','{"district_id": "cha-council-04", "election": "2022-local", "office": "cha_councilor", "text": "一、秉持專業問政，設立服務處，提供法律諮詢，解決縣民問題，保障縣民權利。\n二、力行清廉從政，爭取建設絕不指定包商、不拿回扣。\n三、嚴格審查督促縣府預算之編列，讓有限財源發揮最高效益。\n四、監督縣府確實做好區域排水系統（石笱排水、板本排水、湳港排水、東溝排水…）整治，解決水患，保障人民生命財產安全。\n五、持續爭取員林舊百果山風景區綠美化工程，提供更友善的遊憩環境，帶動地方經濟發展。\n六、敦促縣府早日完成員林鐵路高架下的多功能空間規劃、東彰道路北延段（山腳路外環道），讓員林的都市機能更完善。\n七、持續爭取經費強化永靖景觀園藝園區人口意象，提升永靖觀光能見度。\n八、爭取設置永靖鄉風雨球場以利民眾使用。\n九、持續爭取設置大村鄉東區消防隊，以保障鄉親生命財產安全。\n十、持續關心地方產業發展，協助勞工就業，促進勞資和諧共贏。\n十一、關心弱勢族群，確實維護其權益。\n十二、支持青年參政機會，力挺18歲公民投票權過關，讓台灣民主更進步。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pf3e3aca021','pf3e3aca021','profile','2022-11-26','{"education": ["青山國小\n明倫國中\n中州科技大學應用外語系\n副學士\n逢甲大學經營管理碩士"], "election": "2022-local", "experience": ["2014年-2017年擔任彰化縣長魏明谷秘\n書\n2017年-2018年擔任立法委員陳素月國\n會助理\n第十九屆彰化縣議員\n民主進步黨第19屆全國黨代表\n員林市福寧宮聖媽會常務理事\n永靖國民小學校友會理事\n彰化縣張氏宗親會監事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
