INSERT INTO "fact" VALUES('platform:2022-local:pfb3039844c','pfb3039844c','platform','2022-11-26','{"district_id": "cha-council-06", "election": "2022-local", "office": "cha_councilor", "text": "社頭、田中、二水有山有水有人情味。\n但這裡少了年輕人的聲音！少了年輕人共同參政\n妤亘 願意為鄉親請願與發聲，貢獻年輕的熱情與創意\n監督政府，建議政府，全心照顧這片土地\n1.交通運輸、環境生態、社區設施 硬體要用心\n2.社會安全、婦女權益、育兒教養 軟體要貼心\n3.產業招商、青年創業、投資環境 經營要有心\n4.長者照顧、弱勢福利、長照發展 服務要愛心\n小女子大心願 GO！彰化更好！\n蕭妤亘懇請鄉親全力支持 謝謝您！", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pfb3039844c','pfb3039844c','profile','2022-11-26','{"education": ["國立員林家商\n社頭國中\n湳雅國小"], "election": "2022-local", "experience": [], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pfe8b24619c','pfe8b24619c','bulletin','2022-11-26','{"district_id": "cha-council-06", "elected": true, "election": "2022-local", "office": "cha_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pfe8b24619c','pfe8b24619c','platform','2022-11-26','{"district_id": "cha-council-06", "election": "2022-local", "office": "cha_councilor", "text": "一、八堡－圳景觀廊道拓建，將田中八堡－圳廊道往北延伸至社頭鄉張厝村，再往南打通田中二水瓶頸段串連到\n名間，成為台灣最美麗最適合運動的水圳觀光廊道。\n二、田中馬拉松結合二水、社頭一起走向國際，將台灣米倉馬拉松延伸至二水、社頭打造國際大賽事。將社頭襪\n世界、田中尋米樂、二水柚香中的地方景觀產業透過馬拉松運動有效行銷至全世界。\n三、大力推動老人社會福利化，二十一世紀台灣已成為銀髮族的新世紀，迫切需要有長期規劃的政策、有效監督\n政府的社區老人在地老化政策得以落實。鼓勵創造就業機會讓青年返鄉照顧老人，使其晚年活得有尊嚴，還\n能受到良好的照顧！\n四、加速推動高鐵交通連結、雙鐵接駁站、大型展覽館、MOOVO自行車建置等，讓田中、二水、社頭快速連結都市\n化發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:pfe8b24619c','pfe8b24619c','profile','2022-11-26','{"education": ["田中國小畢業、田中國中\n畢業、達德商工畢業、國\n立虎尾科技大學工業工程\n管理碩士班畢業"], "election": "2022-local", "experience": ["彰化縣議會第19屆議員、田中鎮第\n1 5 、 1 6 屆 鎮 長 、 國 立 虎 尾 科 技 大\n學傑出校友、前彰化縣農田水利會\n第四屆會務委員、田中家扶中心委\n員、彰化縣海軍陸戰隊退伍隊員協\n會理事長、田中義消中隊長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
