INSERT INTO "fact" VALUES('platform:2022-local:pfef463b912','pfef463b912','platform','2022-11-26','{"district_id": "cha-council-09", "election": "2022-local", "office": "cha_councilor", "text": "一、提高原住民購屋補助。\n二、持續關注原住民各項福利政策。督促政府落實執行。\n三、制定原住民年滿55歲就能享有長者各項福利。\n四、強化族語學習環境。\n落實族語家庭化。\n五、堅持專業全方位的服務。\n嚴守清廉從政不包工程、不從事非法事業。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/09%E5%BD%B0%E5%8C%96%E7%B8%A3/%E5%BD%B0%E5%8C%96%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
