INSERT INTO "fact" VALUES('platform:2022-local:p0269a7a258','p0269a7a258','platform','2022-11-26','{"district_id": "hsq-council-2022-02", "election": "2022-local", "office": "hsq_councilor", "text": "（一）誠心、誠意為民喉舌一切以民意為依歸、為鄉親謀福祉，用心為鄉親服務。\n（二）營建湖口老街生機，延續整治畚箕窩溪沿岸觀光地帶，提供鄉親休閒運動去處。\n（三）要求公部門做到路要平、燈要亮、水溝要通、公共場所要清潔、公園及道路雜草要修\n剪，提升鄉親生活品質。\n（四）請營區退縮並拓寬勝利路，解決交通壅塞問題，督促縣府興建湖口勝利路至竹北環北\n路之橫跨鳳山溪高架道路交通改善工程，以紓解湖口交流道與工業區之交通。\n（五）爭取湖口設立YouBike提供民眾便利使用，廣設風雨球場提供青少年正當休閒活動地\n點。\n（六）強化路口監視系統讓交通順暢，重要路口影像監控，治安零死角。\n（七）建議軍方遷移湖口裝甲584旅營區，建設完整交流道，解決湖口交流道壅塞情形。\n（八）推動湖南村中湖路12公頃軍方用地設置特色戰車生態公園。\n（九）捷運輕軌線「湖口〜新竹工業區～竹北～高鐵新竹站」（紫線）延伸至湖口老街與桃\n園輕軌接線，串成桃竹竹大生活圈。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
