INSERT INTO "fact" VALUES('platform:2022-local:p58cfedf28a','p58cfedf28a','platform','2022-11-26','{"district_id": "hsq-council-2022-03", "election": "2022-local", "office": "hsq_councilor", "text": "一、督促縣府重視坡頭漁港船筏進出航道及港內定期清淤工程，紅毛港紅樹林至鳳坑漁港\n周邊工程進度控管及長期環境維護。\n二、持續争取農委會農路改善工程，提升農產品運輸及進出安全。\n三、協助偏遠國中小教學環境改善，提升在地就學意願，縮小城鄉差距。\n四、督促縣府活化各國中小閒置空間，設置社區圖書室，提供在地學子假日閱讀使用。\n五、督促縣府加速「台一線替代道路，竹北─新豐段」新闢工程，以解決上下班壅塞情\n形。\n六、督促縣府解決大山崎地區就學問題（短期目標儘速完成松林國小擴建案，長期目標透\n過新設學校疏解山崎、松林等校學童活動空間不足問題）。\n七、爭取設立特色公園，並於公園改造同時評估設置地下停車空間，以解決都市計劃區內\n停車位不足問題。\n八、督促改善新豐火車站周邊髒亂問題，還給鄉民一個乾淨門面。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
