INSERT INTO "fact" VALUES('platform:2022-local:p7ebaff8b82','p7ebaff8b82','platform','2022-11-26','{"district_id": "hsq-council-2022-04", "election": "2022-local", "office": "hsq_councilor", "text": "1.監督縣府政策執行率，監督縣府財政。\n2.爭取經費，建設關西鎮。\n3.行銷關西農產品，解決農產品銷售問題，增加農民收入。\n4.爭取教育資源，推動各校特色教學，提升英文學習，減少城鄉差距。\n5.整合觀光資源，串連旅遊景點，發展社區輕旅行，帶進人潮及錢潮。\n6.推動社區關懷據點，配合長照2.0計劃，提供共餐服務，關心長輩。\n7.推動社區農村再生計劃，活化社區注入動力，帶動社區發展新力量。\n8.專業服務，您放心，有事就找徐瑜新。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
