INSERT INTO "fact" VALUES('platform:2022-local:p805026e22d','p805026e22d','platform','2022-11-26','{"district_id": "hsq-council-2022-06", "election": "2022-local", "office": "hsq_councilor", "text": "1.推動內灣聯外道路拓寬新闢工程計畫。\n2.針對少子化影響偏鄉教育資源不足的問題積極爭取各項因應措施。\n3.持續強化銀髮照護推動關懷據點及老人共餐服務。\n4.積極爭取尖石鄉設置客家多元活動中心發揚在地客家傳統文化。\n5.推動地方發展及活化歷史建築物再利用結合周邊商圈等文化景點資源帶動內灣商圈觀光\n效益打造內灣所成為文化觀光亮點。\n6.推廣在地農產品協助農民提升農作產值與行銷。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC06%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
