INSERT INTO "fact" VALUES('platform:2022-local:pc434fc9959','pc434fc9959','platform','2022-11-26','{"district_id": "hsq-council-2022-02", "election": "2022-local", "office": "hsq_councilor", "text": "1、湖口不是殯葬矽谷！堅決反對在湖口鄉波羅村設立第二個生命紀念園區。\n2、爭取湖口往來新竹高鐵站接駁車。\n3、爭取湖口設立室內多功能綜合國民運動中心。\n4、具體改善湖口工業區交通壅塞與停車格短缺問題。\n5、爭取人口紅利，編列經費落實6歲前小孩政府養，18歲前青少年政府跟家長一起教。\n6、勞工人權覺醒，設立勞工急（危）難救助單一窗口受理機制。\n7、因應缺電危機，爭取設立再生能源專區，讓新竹縣成為再生能源的示範縣。\n8、高漲房價讓年輕人負擔不起，建立完善的社會住宅制度，讓有房不再是難題，緩解不\n合理房價推升。\n9、爭取經費推動村村有長輩共餐食堂，提供日照、保健服務，讓子女安心工作減輕負\n擔，落實關懷長輩。並提供送餐照顧弱勢家庭。\n10、爭取中小學營午餐費每人由45元提高為65元。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
