INSERT INTO "fact" VALUES('platform:2022-local:pf6c1f4c229','pf6c1f4c229','platform','2022-11-26','{"district_id": "hsq-council-2022-04", "election": "2022-local", "office": "hsq_councilor", "text": "一、主張安全與環境最少破壞下興建外環道改善關西交通問題。\n二、督促縣府加強查緝遏止環境污染事件發生。\n三、爭取關西地區急重症醫療機構。\n四、推銷關西休閒觀光、傳承客家多元文化。\n五、打造創生機會、鼓勵青年返鄉創業。\n六、加強高齡化照顧及社區關懷據點服務。\n七、落實社會福利提高育兒津貼及學齡前教育補助。\n八、爭取監視系統建置釐清交通事故責任、打擊不法。\n九、提倡社區營造及農村再生，打造關西為宜居鄉鎮。\n十、建立與縣府良好溝通機制，監督把關縣府各項施政。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/07%E6%96%B0%E7%AB%B9%E7%B8%A3/%E6%96%B0%E7%AB%B9%E7%B8%A3%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
