INSERT INTO "fact" VALUES('platform:2022-local:p87b8234ec7','p87b8234ec7','platform','2022-11-26','{"district_id": "hsz-council-05", "election": "2022-local", "office": "hsz_councilor", "text": "國寶擔任四任民意代表，以『感恩的心、走一輩子的路』不忘初衷\n監督市府各項政策讓市民擁有更好的生活品質。\n1.積極爭取65歲以上健保費全額減免。\n2.竹香南、北路延伸至彩虹橋。\n3.監督機場周邊、頭前溪沿岸都市計畫及香山24里的城鄉發展。\n4.爭取受工業污染農地，成立產業園區，解決農民因土壤問題無法耕作困\n境。\n5.成立『青年創業育成中心』提供無償提供臨時辦公室以及法律、稅務申\n請青年貸款等疑問諮詢。\n6.落實毒品防制，加強校園反毒宣導、強力反對廢除死刑。\n7.機場周邊住戶福利政策爭取與推動。\n8.積極爭取增設香山區『微笑單車you bike』設置點，解決交通問題＆推廣\n觀光。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/21%E6%96%B0%E7%AB%B9%E5%B8%82/%E6%96%B0%E7%AB%B9%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
