INSERT INTO "fact" VALUES('platform:2022-local:pc2358d4e80','pc2358d4e80','platform','2022-11-26','{"district_id": "hsz-council-04", "election": "2022-local", "office": "hsz_councilor", "text": "●督促市府重視各項產業經濟發展。\n●設立法服中心，提供民眾法律等相關服務。\n●重視公立幼托及長者長照各項社福政策。\n●爭取身障團體及弱勢族群福利與就業。\n●重視動物保護議題，推動公立動物火化場。\n●成立南寮地區電力改善監督小組。\n●監督南寮海水淡化廠。\n●落實社區巡守協助警力維護地方治安。\n●爭取興建機場滯洪池，改善低窪地區及南寮地區排水問題。\n●推動客家文化及客家語言發展。\n●重視新冠疫情衝擊及各項疫苗就診防疫等。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/21%E6%96%B0%E7%AB%B9%E5%B8%82/%E6%96%B0%E7%AB%B9%E5%B8%82%E7%AC%AC04%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
