INSERT INTO "fact" VALUES('platform:2022-local:pd2fe2e07d4','pd2fe2e07d4','platform','2022-11-26','{"district_id": "hsz-council-05", "election": "2022-local", "office": "hsz_councilor", "text": "監督市政、為民服務、爭取民眾福祉。\n積極關懷長者、婦幼權益、協助及輔導弱勢族群能自力更生。\n串聯各景點發展觀光旅遊休閒產業、增進觀光收益、\n盤點公共土地或鼓勵民間土地參與政府興辦工商科技園區、\n打造「人文科技大學城」、培育優秀人才、在地服務、\n振興產業、繁榮經濟、增加地方收益。\n積極爭取客雅大道向東延伸、接通高峰路科學園區交通網路更活絡、\n敦促政府落實環保（空污、水污、噪音污）加強防治。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/21%E6%96%B0%E7%AB%B9%E5%B8%82/%E6%96%B0%E7%AB%B9%E5%B8%82%E7%AC%AC05%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
