INSERT INTO "fact" VALUES('platform:2022-local:p0806f7b08e','p0806f7b08e','platform','2022-11-26','{"district_id": "kin-council-02", "election": "2022-local", "office": "kin_councilor", "text": "1.持續推動在金門設置教育學程，提供金大學生及金門籍大學畢業生修習，培育中小學師資在地化。\n2.持續關心特教生及弱勢學生權益，強化適應體育及相關職能與生活能力課程、營隊。\n3.推動成立公辦民營之實驗學校，讓不同特質之孩子可以有選擇教育方式之權利。\n4.爭取金湖金沙地區運動專業教練名額，並以台灣經驗為參考，協助金湖金沙地區成立兼顧基本\n學力能力之體育班。\n5.爭取金沙及金湖地區土地重劃範圍，建設東半島。\n6.推動金廈大橋(由金沙接至廈門翔安機場)，活絡金沙地區之經濟與發展。\n7.持續監督醫發基金之使用，讓金門醫院持續改善醫療品質。\n8.推動金門醫院成立坐月子中心，以服務為導向。\n9.推動中風醫療中心及中風患者專門復健專區，提高中風患者治療效果並減少家屬辛勞。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
