INSERT INTO "fact" VALUES('platform:2022-local:p1fde6dcdf7','p1fde6dcdf7','platform','2022-11-26','{"district_id": "kin-council-01", "election": "2022-local", "office": "kin_councilor", "text": "【推動透明政府、監督縣政議政】－持續要求資訊公開、落實公民參政權利\n【詳審預算決算、看緊人民荷包】－督促落實財政紀律、減少預算浮濫支出\n【善用在地資源、島鄉永續發展】－堅持守護公有資產、續推閒置資源利用\n【強化醫療能量、厚植文化教育】－促進醫療在地生根、發展優質地方國教\n【提倡多元產業、獎助青年回流】－倡議金酒多角經營、傳統產業體質升級\n【觀光產業轉型、打造優勢環境】－優化觀光旅遊品質、創造金門島嶼優勢", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p1fde6dcdf7','p1fde6dcdf7','profile','2022-11-26','{"education": ["國立金門大學島嶼休閒資\n源發展研究所畢業。"], "election": "2022-local", "experience": ["曾任職金門大學行政助\n理、金門日報記者、蘋果\n日報金門駐地記者，現為\n第七屆金門縣議員。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p25eb3bd5ad','p25eb3bd5ad','bulletin','2022-11-26','{"district_id": "kin-council-01", "elected": true, "election": "2022-local", "office": "kin_councilor", "page": 4, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p25eb3bd5ad','p25eb3bd5ad','platform','2022-11-26','{"district_id": "kin-council-01", "election": "2022-local", "office": "kin_councilor", "text": "*督促落實老人、弱勢族群福利措施、社會救助，保障其經濟安全、健康維護、生活照顧。\n*督促本縣社區照顧關懷據點計畫，落實辦理長者送餐、定點取餐、定點共食服務，並積極推動\n增加其服務天數時段，完善生活照顧。\n*督促政府提升醫療水平，爭取縣政提撥經費強化醫療軟硬體設備，並爭取增加專業醫療人員常\n駐金門。\n*推動強化新的醫療技術的發展，如增設遠端會診設備...等，完善本縣醫療資源填補醫療資源缺\n口，減少居民赴台看診之不便與不安。\n*督促縣府重視觀光產業服務品質，落實景區設施經常性養護修繕、經營管理，建立友善旅遊環\n境。\n*推動各鄉鎮特色景點開發，積極行銷在地活動節慶、創意話題、美食及伴手禮，均衡全島觀光\n蓬勃發展。\n*提升公共托育品質，爭取預算編列育兒補助、托育專業人員久任獎勵辦法，減輕托育壓力，友\n善托育職場及托育環境。\n*督促政府輔導青年打造多元就業管道，推動創業青年培訓課程並爭取經費補助，全面性的完善\n青創培育。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
