INSERT INTO "fact" VALUES('platform:2022-local:p5305e35a1b','p5305e35a1b','platform','2022-11-26','{"district_id": "kin-council-01", "election": "2022-local", "office": "kin_councilor", "text": "1、監督政府打造體育優質環境，落實培育潛優選手，發展體育觀光之願景\n2、監督政府落實婦幼及老人照護政策，共同打造養生健康快樂島嶼\n3、監督政府戮力營造青年就業環境，落實協助青年在鄉服務政策\n4、監督政府落實教育政策，營造優質的學習環境", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5305e35a1b','p5305e35a1b','profile','2022-11-26','{"education": ["銘傳大學公共事務學系碩士"], "election": "2022-local", "experience": ["金門農工幹事\n金門大學講師\n金門體育會理事長\n金門縣富康一村金城新莊\n社區發展協會理事長\n金門縣土風舞協會理事長\n金門縣婦女權益促進會總\n幹事"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p5d3742517f','p5d3742517f','bulletin','2022-11-26','{"district_id": "kin-council-02", "elected": true, "election": "2022-local", "office": "kin_councilor", "page": 3, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p5d3742517f','p5d3742517f','platform','2022-11-26','{"district_id": "kin-council-02", "election": "2022-local", "office": "kin_councilor", "text": "1、爭取金廈大橋，永保兩岸和平；推動小三通盡速復航。\n2、加強醫療改革與服務，提升本縣醫療水平。\n3、加強社會救助與福利，關懷弱勢族群。\n4、爭取幼托及長照措施升級轉型，改善高齡化及少子女化問題。\n5、運用教育資源，提升地區學生學力，輔以多元學習管道，落實全人教育。\n6、振興地區觀光旅遊與各產業均衡發展，增加就業機會。\n7、地區特色文化再提升，推展兩岸文化宗教體育交流。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p5d3742517f','p5d3742517f','profile','2022-11-26','{"education": ["永達技術學院企業經營管\n理系畢業學士學位"], "election": "2022-local", "experience": ["第15屆全代會黨代表\n第1屆青工會總會長\n第五屆、第六屆、第七屆\n金門縣議會議員\n金門縣飲食公會理事長\n金門縣旅行公會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:p6655ec3cf6','p6655ec3cf6','bulletin','2022-11-26','{"district_id": "kin-council-02", "elected": true, "election": "2022-local", "office": "kin_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p6655ec3cf6','p6655ec3cf6','platform','2022-11-26','{"district_id": "kin-council-02", "election": "2022-local", "office": "kin_councilor", "text": "1、建設金門，從議會改變開始 議員素質及全方位的思維，議會必需有新聲代來推動。\n2、監督縣府各項地方建設，改善城鄉差距，促進東半島平衡。\n3、加強醫療服務，落實培養在地醫療人員常駐金門。\n4、規劃養老院，讓金門的老人福利更完善，減輕年輕人的壓力。\n5、成立個人服務團隊，協助醫療危難救助，讓百姓有感。\n6、深入基層，了解民意，協助照顧弱勢族群。\n7、協助民眾申請土地及房屋使用執照問題，將過去的不便民流程簡化行政程序透明化。\n8、金門要更進步，需要您神聖的一票，大家一起來改變金門，將金門建設成為一個和平試範區\n的島嶼。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
INSERT INTO "fact" VALUES('profile:2022-local:p6655ec3cf6','p6655ec3cf6','profile','2022-11-26','{"education": ["何浦國小\n金沙國中\n泰北高中\n台北工專\n金門大學碩士畢業"], "election": "2022-local", "experience": ["精忠衛隊協會榮譽理事長\n金門縣志願役官兵協會理\n事長\n第三士校協會理事長\n金門縣紅十字會理事\n金門縣義勇消防總隊顧問\n金門縣農工職業學校家長\n會顧問"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
