INSERT INTO "fact" VALUES('platform:2022-local:p71429f8392','p71429f8392','platform','2022-11-26','{"district_id": "kin-council-02", "election": "2022-local", "office": "kin_councilor", "text": "1、加強中小學雙語教育，爭取圖書教育資源，提升青少年國際競爭力\n2、加強公共托育資源，減輕家長照顧負擔\n3、推動路燈安心專案，多盞燈夜裡更安心\n4、落實跟騷法，強化執法能量，創造安全生活環境\n5、推動活化閒置資產，建立鄰里安心樂活據點\n6、強化東半島基礎建設，融入文化科技元素賦予新風貌\n7、推動東半島濱海觀光廊道，串聯景點創造新體驗\n8、強化審查會分權制度，完備議會制度化運作\n9、推動參與式預算，民主扎根貼近在地\n10、全力支持並監督馬山港進度，為縣政專業把關", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%BA%8C%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
