INSERT INTO "fact" VALUES('platform:2022-local:paabe4fcc71','paabe4fcc71','platform','2022-11-26','{"district_id": "kin-council-01", "election": "2022-local", "office": "kin_councilor", "text": "1、支持興建金廈大橋，繁榮大金廈生活圈。\n2、推動小三通之復航，力挽金門低迷經濟。\n3、持續關心綠色生態，育林護林永續環境。\n4、督促縣府開源節流，正視嚴守財政紀律。\n5、提升金酒營運績效，富裕縣庫支應建設。\n6、把關公共工程品質，營造金門美好形象。\n7、強化長期照顧體系，布建更多服務資源。\n8、再造金酒公司組織，績效導向專業經營。\n9、開展新四通(通水、通橋、通電、通氣)之規畫，融合兩岸繁榮金門。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/18%E9%87%91%E9%96%80%E7%B8%A3/02%E8%AD%B0%E5%93%A1%E7%AC%AC%E4%B8%80%E9%81%B8%E5%8D%80%E5%85%AC%E5%A0%B1.pdf','2026-10-03T12:05:58Z');
