INSERT INTO "fact" VALUES('platform:2022-local:p12b5bce2ff','p12b5bce2ff','platform','2022-11-26','{"district_id": "lie-council-03", "election": "2022-local", "office": "lie_councilor", "text": "一、推動東、西二島港埠建設。\n二、推動示範住宅，落實住者有其屋。\n三、落實二島室內運動場館。\n四、爭取經費興建東莒海淡廠。\n五、爭取經費興建東、西二島停車場。\n六、推動軍方釋出營區利用價值及規劃。\n七、爭取老人福利，強化照顧服務。\n八、教育提升，多元化的發展。\n九、提昇醫療品質，為鄉親健康把關。\n十、監督縣府海洋政策落實，永續維護海洋資源。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC03%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
