INSERT INTO "fact" VALUES('platform:2022-local:p42b074a657','p42b074a657','platform','2022-11-26','{"district_id": "lie-council-01", "election": "2022-local", "office": "lie_councilor", "text": "1.爭取興建南竿鄉介壽-梅石-仁愛濱海自行車步道，開發縣民休閒新景點。\n2.督促新任縣長建議中央辦理離島特考，維持本縣各機關用人安定，增加本縣子弟\n擔任公職機會。\n3.督促都市計劃通盤檢討，讓土地發揮最大價值，以平民怨。\n4.與新任縣長共同向交通部、NCC爭取加速興建第四條台馬海纜，建立本縣安\n全、可靠及高速的網路環境。\n5.督促縣府開通南竿-高雄航線，服膺民意需求。\n6.要求馬酒公司規劃觀光工廠目標，提升馬酒企業形象，廣開財源謀求縣民福祉。\n7.要求縣府制定真正有利於身心障礙者的工作機會及友善環境空間。\n8.監督縣民樂活多功能體育館暨社福中心工程進度，充實體育休閒硬體設施，推廣\n全民運動及兒少福利。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
