INSERT INTO "fact" VALUES('platform:2022-local:p801af9bb5b','p801af9bb5b','platform','2022-11-26','{"district_id": "lie-council-01", "election": "2022-local", "office": "lie_councilor", "text": "1.深耕基層，反映民意，監督縣政，撙節公帑。\n2.持續推動港埠建設，提升海運及港埠作業安全。\n3.強化長照計畫，提升醫療健康照護品質。\n4.優化旅遊環境，提升觀光產業發展。\n5.提升教育環境設施及資源設備，精進教學品質。\n6.關懷弱勢族群及新住民生活照顧，保障就業機會。\n7.重視勞工權益及福祉，輔導青年創業，創造多元產業。\n8.爭取解決廟宇土地之爭議。\n9.爭取基層建設，推動及營造一村一特色優質居住環境。\n10.爭取簡化合法建物申請流程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
