INSERT INTO "fact" VALUES('bulletin:2022-local:p80648d9bc8','p80648d9bc8','bulletin','2022-11-26','{"district_id": "lie-council-02", "elected": true, "election": "2022-local", "office": "lie_councilor", "page": 2, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p80648d9bc8','p80648d9bc8','platform','2022-11-26','{"district_id": "lie-council-02", "election": "2022-local", "office": "lie_councilor", "text": "1.積極爭取北竿示範住宅之興建，解決鄉民最迫切的住屋需求，以維居住正義。\n2.全力配合立委、縣府爭取北竿機場擴建以及南北竿大橋之興建，以提昇地區長遠發展。\n3.爭取北竿比照南竿福利園區，設置大同之家，讓長者老有所養。\n4.督促縣府加強北竿道路網之綠美化工作，以及規劃林相更新，以厚植觀光實力。\n5.敦促縣府協同風管處針對壁山觀景台及停車位置加以規劃設置提昇觀光形象。\n6.爭取興建北竿室內多功能展演館，活化地區藝文生根工作。\n7.督促縣府辦理北竿全區都市計畫通盤檢討，以促進土地有效利用，活絡地方經濟。\n8.敦請縣府就北竿中正路老舊國宅進行安檢，並規劃都更之可行性，以維居民安全。\n9.推動塘岐軍方靶場之遷移，以維居民生活品質。\n10.爭取增設塘岐怡園至馬鼻灣濱海道路，讓重型車輛、貨、卡車改由該路段行駛，以維街道\n人、車安全。\n11.爭取興建北竿塘岐老人活動中心，讓長者能有個安全舒適之休閒場所。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
