INSERT INTO "fact" VALUES('platform:2022-local:p80b70f8afd','p80b70f8afd','platform','2022-11-26','{"district_id": "lie-council-01", "election": "2022-local", "office": "lie_councilor", "text": "一、督促全面檢討都市計畫並進行土地重劃，使土地更有效利用。\n二、要求推動人才培育計劃，協助青年回鄉服務，解決地區人才斷層問題。\n三、要求積極維護海洋生態資源，杜絕非法籠漁具捕撈作業。\n四、督促政府有效運用公彩基金，擴建老人安養設施及推動各項社會福利。\n五、推動興建停車場，解決民眾停車問題。\n六、繼續推動興建合宜住宅，解決民眾居住問題。\n七、興建復興村入村道路，改善目前入村交通困境。\n八、推動牛角大澳老街復興，增加地區具特色觀光資源。\n九、督促保護馬祖戰地及閩東文化特色，強化內涵，以獨特性吸引觀光人\n潮。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
