INSERT INTO "fact" VALUES('bulletin:2022-local:pbeebeff320','pbeebeff320','bulletin','2022-11-26','{"district_id": "lie-council-01", "elected": true, "election": "2022-local", "office": "lie_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pbeebeff320','pbeebeff320','platform','2022-11-26','{"district_id": "lie-council-01", "election": "2022-local", "office": "lie_councilor", "text": "一、嚴格審查監督縣庫，為人民看緊政府的荷包。\n二、建立最完善的校園安全網，維護學童受教安全。\n三、發展最具馬祖特色的農漁工商產業，振興經濟。\n四、闢建沿海環島公路，作為自行車和行人專用步道。\n五、檢討都自條例，因地制宜，放寬保護區建物面積。\n六、爭取國際藝術島活動經費，至少一半由縣府統籌使用。\n七、落實獨居或窮苦老人的福利，及居家照顧等措施。\n八、爭取0-6歲的小孩政府來養經費，向企業界、慈善團體募款。\n九、全面將自來水管汰舊換新，使居民安心飲用自來水。\n十、強力要求將警察與消防人員編制足額到位，不可缺編。\n十一、要求每個月定一~二天為縣民時間，由縣長一整天親自接待縣民陳情。\n十二、結合立委，縣長，議會力量，共同要求中央政府早日恢復小三通。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
