INSERT INTO "fact" VALUES('bulletin:2022-local:pc89f756052','pc89f756052','bulletin','2022-11-26','{"district_id": "lie-council-02", "elected": true, "election": "2022-local", "office": "lie_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:pc89f756052','pc89f756052','platform','2022-11-26','{"district_id": "lie-council-02", "election": "2022-local", "office": "lie_councilor", "text": "一、推動興建「南北竿跨海大橋」有效資源整合，縮短城鄉差距。\n二、爭取推動「北竿機場擴建工程」，全面提昇馬祖對外空中交通。\n三、督促縣府成立專案小組，推動北竿鄉合宜住宅及社會住宅興建計畫。\n四、提升白沙碼頭設施，未來建設及動線作整體規劃，逐年推動完成。（包括新增浮動碼頭、南堤延伸\n工程丶北堤貨運碼頭改善、新旅運大樓、馬祖大橋銜接點等）。\n五、爭取經費，推動北竿鄉芹壁村停車場興建工程。\n六、充實北竿觀光，督促北竿鄉北海坑道重新開放，以利觀光發展。\n七、推動北竿塘岐老人活動中心興建工程。\n八、積極推動北竿鄉塘岐靶場遷移。\n九、爭取推動馬鼻灣遊憩休閒（育樂漁業）碼頭，帶動地方觀光多元發展。\n十、督促推動橋仔漁具展示館內部設施，提昇漁村文化內涵。\n十一、充實北竿醫療量能，增加北竿鄉衛生所洗腎醫療服務。\n十二、爭取水環境計畫，改善橋仔阿南境週邊整體環境。\n十三、推動興建北竿鄉芹壁龍角峰景觀平台。\n十四、改善上村到壁山 ，壁山到莒光堡道路，以維人車安全。\n十五、爭取推動坂里村40據點到混砲連濱海道路工程。\n十六、充實規劃塘岐村得天泉到馬鼻灣道路系統。\n十七、爭取推動塘岐至橋仔88據點濱海道路，維護行車安全性與便利性。\n十八、推動北竿中沃口碼頭延伸工程。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC02%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
