INSERT INTO "fact" VALUES('bulletin:2022-local:p01d2a3630f','p01d2a3630f','bulletin','2022-11-26','{"district_id": "lie-mayor", "elected": true, "election": "2022-local", "office": "lie_mayor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-04T09:21:14Z');
INSERT INTO "fact" VALUES('platform:2022-local:p01d2a3630f','p01d2a3630f','platform','2022-11-26','{"district_id": "lie-mayor", "election": "2022-local", "office": "lie_mayor", "text": "一、強化馬祖城市品牌，提升馬祖自明性。\n二、建構健全與便利之交通網絡。\n三、打造宜居城市，全方位提供育才及留才資源，穩定地方成長。\n四、落實環境永續政策，成為永續島嶼。\n五、建立友善觀光旅遊環境，提升觀光品質，打造綠色旅行產業。\n六、以文化加值馬祖各產業基礎，接軌國際交流，提升質量與內涵。\n七、維護民生基礎，提供穩定及安全建設，打造宜居島嶼。\n八、確保各年齡層縣民擁有健康福祉，加強智慧醫療服務。\n九、落實公開透明智慧治理，提升行政效能，打造廉能政府。\n十、扶植地方特色產業，創造經濟動能。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/19%E9%80%A3%E6%B1%9F%E7%B8%A3/%E9%80%A3%E6%B1%9F%E7%B8%A3%E7%AC%AC01%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-03T12:05:58Z');
