ipt_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=8", "transcript_pages": [3669, 3670, 3671, 3672, 3673, 3674, 3675], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162','2026-10-01T22:36:33Z');
INSERT INTO "fact" VALUES('summary:14-01:pccc2308c1b','pccc2308c1b','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:38:24Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=2"}, {"page": 1070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=2"}, {"page": 1071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=3"}, {"page": 1072, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=4"}, {"page": 1073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=5"}, {"page": 1073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=5"}, {"page": 1074, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=6"}], "councilor_points": ["侯漢廷議員指出「臺北市兒童及少年寄養家庭管理自治條例」修正放寬年齡門檻對增加合適寄養家庭效果有限，且過去5年寄養家庭數從143戶下降至109戶，建議市府針對宗教團體、慈善團體、退休白領及教育業者等標的群體進行宣傳，並在自治條例或相關指引中加強審核機制。侯漢廷議員表示修法新增損害賠償規定，若寄養兒童造成損害不應由社會局負擔，建議向中央反映將全臺寄養兒童納入保險，由保險公司進行風險管理與賠償。侯漢廷議員強調增加寄養家庭誘因不可將提高金錢數作為唯一目標。"], "response": "社會局局長說明下修年齡門檻係希望將寄養家庭年輕化且不漏接有心人士，並表示會朝向議員建議的標的群體推廣宣傳。社會局局長與社會局兒童及少年福利科科長說明損害賠償目前係採預訂契約三方討論機制，並表示衛生福利部社會及家庭署已召集相關單位共同研議保險事宜。社會局局長表示增加誘因時一定會注意避免以金錢為唯一目標。", "response_removed": false, "topic": "兒童及少年寄養家庭管理自治條例修正"}, {"citations": [{"page": 1076, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=8"}, {"page": 1703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=1"}, {"page": 1704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=2"}, {"page": 1706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=4"}, {"page": 1706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=4"}, {"page": 1707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=5"}, {"page": 1705, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=3"}], "councilor_points": ["侯漢廷議員指出市有土地與建物存在眷村、宿舍等長年產權爭議或與現況不符之陳年舊案，財政局對列管財產若僅一味要求說明或採取懲處，對缺乏專業且剛上任的基層承辦人員顯得「不教而誅」且不合情理。侯漢廷議員建議財政局應主動輔導與協助各局處，以合作及釐清現況為原則，減少以究責作為主要手段。"], "response": "財政局局長說明市有土地若遭占用會依民法處理，每年皆有督導各局處財管人員開會與教育訓練，並會進行財產抽查與輔導。財政局局長表示對於陳年舊案會以輔導為優先，並承諾會與相關局處共同輔導解決與主動合作。", "response_removed": false, "topic": "市有財產管理與陳年產權爭議處理"}, {"citations": [{"page": 2011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC#page=5"}, {"page": 2012, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC#page=6"}, {"page": 2013, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC#page=7"}, {"page": 2010, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC#page=4"}], "councilor_points": ["侯漢廷議員指出敦化國小合唱團參與兩岸交流活動遭抹紅指控，教育局調查報告要求停止交流，係屬於「政治介入校園」及「向民進黨下跪」之行為。侯漢廷議員表示學生與家長皆同意參與交流，且歌曲審查與國安法令非教育局審查範圍，要求教育局未來面對類似抹紅攻訐應全面駁回，並以中華民國憲法與兩岸人民關係條例為基石。"], "response": "教育局局長說明學校制服已有40年歷史，調查報告係督學依據校長報告意見提出建議，教育局並未事前審核演出內容。教育局局長表示歌曲審查非教育局權責，並同意教育應以中華民國憲法及兩岸人民關係條例為基石。", "response_removed": false, "topic": "敦化國小合唱團兩岸交流爭議與教育局處置"}, {"citations": [{"page": 2811, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=6"}, {"page": 2811, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=6"}, {"page": 2812, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=7"}, {"page": 2812, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=7"}, {"page": 2813, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=8"}], "councilor_points": ["侯漢廷議員指出士林區福國路新闢道路通車前劃設1個左轉車道，4月30日通車後改為4線道且僅有半個直左車道造成車輛回堵，且雙黃線設計易致車輛擦撞，經會勘後始改善完成。侯漢廷議員表示5月9日交通局才確認改善，但施工單位在4月30日即搶先通車係「先上車後補票」，要求交通局修改標準作業程序（SOP），並對施工單位搶先通車之行為進行懲處。"], "response": "交通局局長說明福國路車道增加後有調整空間，現場經會勘溝通後已改善完成。交通局局長承諾會檢討改善程序，並修改「臺北市重要道路工程通車勘驗標準作業程序」。", "response_removed": false, "topic": "福國路新闢道路車道配置缺失與通車程序檢討"}, {"citations": [{"page": 3508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549CF4854F542B2083763A340E0C238AC3BDE71B5ED9BE81AD4F4C5805618A66E9002D1DE3DCEB210BC#page=1"}, {"page": 3511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549CF4854F542B2083763A340E0C238AC3BDE71B5ED9BE81AD4F4C5805618A66E9002D1DE3DCEB210BC#page=4"}], "councilor_points": ["侯漢廷議員指出近2年臺北市發生3起臨路建案天坑事故，部分營造廠3年內違規達10次至二十多次，但過往裁罰過輕，要求市府建立累罰、記點公告及重點關注機制。侯漢廷議員建議工務局針對地下室開挖及連續壁工程加強巡檢，並對頻繁違規廠商採取審慎監督態度。"], "response": "工務局局長與建築管理工程處處長說明信義區天坑案已依建築法最重罰則對承造人及監造人各處以9萬元罰鍰。工務局局長與建築管理工程處處長表示目前正在研議違規廠商的加強管理、記點、上網公告及累罰機制，並會針對地下室開挖建案加強道路巡檢。", "response_removed": false, "topic": "建案施工致天坑公安事故與違規廠商裁罰管理"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 4, "heading": "民政部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162#page=1", "transcript_pages": [1069, 1070, 1071, 1072, 1073, 1074, 1075, 1076], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A37B3A94B2B8EFB08322F6B39C8B36FB86D35F9A8D8B7E68A852238F00A7C162", "videos": [{"date": "2023-04-17", "group": 4}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 10, "heading": "財政建設部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC#page=1", "transcript_pages": [1703, 1704, 1705, 1706, 1707], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497A7CBCC59E78E77E6B4139C000F2559EE59F618F24A580D64E153C9C384F694702D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 10}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 3, "heading": "教育部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC#page=1", "transcript_pages": [2007, 2008, 2009, 2010, 2011, 2012, 2013], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A21C775CBD2A136A2E9E5633EBB374114C38C79DB1ECD32F04737C8DBCD88DC002D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 3}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 18, "heading": "交通部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC#page=1", "transcript_pages": [2806, 2807, 2808, 2809, 2810, 2811, 2812, 2813], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654975896B8D4FD693522E9E5633EBB37411986F54F829ACF0222CFEE2BB696503E802D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 18}]}, {"dates": ["2023-05-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 11, "heading": "警政衛生部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491C9DF21035B46C04707192FE38705FD390C1E7D7D4BD5B0F549D6E6EA8F6AC75