INSERT INTO "fact" VALUES('summary:14-01:pa0224cb763','pa0224cb763','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:40:09Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2483, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=3"}, {"page": 2483, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=3"}, {"page": 2484, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=4"}, {"page": 2486, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=6"}, {"page": 2488, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=8"}, {"page": 2487, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=7"}, {"page": 2486, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=6"}], "councilor_points": ["劉耀仁議員指出臺北市登記之純電動車與可充電油電混合車已超過1萬輛，但公有停車場充電樁僅有五百多格，數量遠遠不足且落後歐盟標準。劉耀仁議員建議交通局將2025年公有停車場充電樁設置目標由1,200支提升至1,500支，並研議將智慧停車柱與充電樁合為一體。劉耀仁議員要求交通局主動向中央爭取2023年至2024年規劃的9.8億元停車費收費柱結合充電樁補助預算。"], "response": "交通局局長與停車管理工程處處長說明，臺北市公有停車場設置充電處比例已將近1%，會朝2025年達到1,500支充電樁的目標檢討與努力。交通局局長表示會評估智慧停車柱結合充電技術的可行性，並評估符合條件以申請中央9.8億元補助計畫。", "response_removed": false, "topic": "公有停車場電動汽車充電樁設置與中央補助爭取"}, {"citations": [{"page": 3226, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC#page=2"}], "councilor_points": ["劉耀仁議員指出大臺北地區腸病毒就診人次升高，且腸病毒71型易引發重症與高致死率，對5歲以下幼兒威脅甚鉅。劉耀仁議員表示腸病毒71型疫苗2劑費用達7,000元，對家庭負擔沉重，建議市府向衛福部ACIP催促評估公費施打。劉耀仁議員建議市府若中央未納入公費，應比照過去輪狀病毒疫苗補助經驗，針對臺北市5歲以下幼兒提供自費接種部分金額補助。"], "response": "衛生局局長表示鼓勵幼兒接種腸病毒71型疫苗，並說明會向中央催促加速處理。衛生局局長表示若中央無法補助，市府會加緊研擬針對5歲以下高風險族群提供適度費用補助。", "response_removed": false, "topic": "腸病毒71型疫苗自費接種補助"}, {"citations": [{"page": 1320, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162#page=9"}, {"page": 1321, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162#page=10"}], "councilor_points": ["劉耀仁議員指出陽明山臻愛樓塔位剩餘數量有限，加上公墓遷葬與每年5,000個塔位需求，詢問市府興建新靈骨塔之規劃。劉耀仁議員針對第一殯儀館拆遷計畫，指出僅規劃250位平面停車場過於短視，建議考量當地商業與拜拜停車需求，評估興建地下停車場。"], "response": "殯葬管理處處長說明臻愛樓塔位尚餘10,971個，並已預定於文山區規劃興建12萬個塔位，將召開說明會向地方溝通。殯葬管理處處長說明第一殯儀館預計於明年春節過後拆遷，短期規劃地面綠美化與停車空間，針對興建地下停車場之建議會進行評估。", "response_removed": false, "topic": "陽明山臻愛樓塔位使用量與第一殯儀館拆遷規劃"}, {"citations": [{"page": 1535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=1"}, {"page": 1536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=2"}, {"page": 1536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=2"}, {"page": 1537, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=3"}], "councilor_points": ["劉耀仁議員指出台北通APP顯示之行動裝置充電地點資訊缺漏且分布極度不均，例如萬華區29個地點中南萬華僅有2個。劉耀仁議員建議資訊局協調警察局於各派出所設置無線充電或充電座，以改善充電地點分布不均之問題。劉耀仁議員提及公共USB充電站存在植入病毒之「充電陷阱」資安風險，要求資訊局對公家機關之充電設施進行定期檢查與宣導。"], "response": "資訊局局長說明會了解台北通充電站資訊缺漏問題，並表示若警察局設置充電站會納入台北通顯示。資訊局局長說明資訊局並未設置公共充電站，但作為公部門資訊安全督導機關，會通知並請權管局處特別注意USB等設施之資安檢查。", "response_removed": false, "topic": "台北通APP行動裝置充電地點資訊與資安維護"}, {"citations": [{"page": 4155, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC#page=15"}, {"page": 4155, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC#page=15"}, {"page": 4156, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC#page=16"}], "councilor_points": ["劉耀仁議員指出西寧大樓為海砂屋，詢問臺北市市長對於西寧綜合大樓暨洛陽停車場整體開發可行性評估方案之選擇。劉耀仁議員建議市府將西寧大樓與洛陽停車場進行聯合開發合建，打造淡水河岸新地標與政績，並表示會協助協調攤商與停車問題，建議將國宅住戶安置至福星國小新社會住宅。"], "response": "臺北市市長說明目前考量西寧市場攤商安置與洛陽停車場停車需求等問題，會採納議員建議納入整體評估考量。臺北市市長表示希望劉耀仁議員協助協調萬華當地的攤商與停車問題。", "response_removed": false, "topic": "西寧綜合大樓暨洛陽停車場整體開發案"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC#page=14", "transcript_pages": [4154, 4155, 4156, 4157, 4158, 4159, 4160, 4161, 4163, 4164], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC", "videos": [{"date": "2023-05-30", "group": 3}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 14, "heading": "民政部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162#page=1", "transcript_pages": [1312, 1313, 1314, 1315, 1316, 1317, 1318, 1319, 1320, 1321, 1322], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 14}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=1", "transcript_pages": [1535, 1536, 1537, 1538, 1539, 1540], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 3}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=11", "transcript_pages": [2061, 2062, 2063, 2064, 2065, 2066, 2067, 2068, 2069], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 5}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=2", "transcript_pages": [2482, 2483, 2484, 2485, 2486, 2487, 2488, 2489, 2490], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 4}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 17, "heading": "警政衛生部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC#page=1", "transcript_pages": [3225, 3226, 3227, 3228, 3229, 3230, 3231, 3232, 3233], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 17}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 9, "heading": "工務部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=1", "transcript_pages": [3691, 3692, 3693, 3694, 3695], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC','2026-10-01T22:40:09Z');
INSERT INTO "fact" VALUES('summary:14-01:p4b727b88dc','p4b727b88dc','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:41:56Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3852, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=18"}, {"page": 3853, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=19"}, {"page": 3854, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=20"}, {"page": 3854, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=20"}], "councilor_points": ["指出中央規定勞工每年應有8小時以上的勞動教育時數，但市府政策白皮書漏寫「以上」二字，導致執行產生疑慮，建議市府召集相關單位協調，不應限制僅有8小時（「研究發展考核委員會整理出來的政策白皮書中，寫的太清楚了，少了 2 個字『以上』，這下子就差很多了」、「希望由工務局召集勞動局、各處、人事處、各企業工會及聯合會，就 8 小時以上的勞教問題提出處理的方案」）。表示工務局之勞動教育補助基準與勞動局不一致，且補助費用過低，建議應比照勞動局標準進行調整（「工務局的規定和勞動局不一樣」、「補助基準的調整，工務局應該比照勞動局，把這些補助分列開來」）。建議工務局研究編列工務局各處工會聯合會之相關勞動教育經費（「請工務局研究編列聯合會相關勞教的經費」）。"], "response": "工務局局長表示會邀集會議並請勞動局定調，後續執行面將依照定調方式提供各處與工會，並配合勞動局調整更新補助基準表（「我會邀集會議，尤其也會請勞動局在會議上向大家做比較明確的定調」、「後續也會就勞動局今年所調整的部分，配合工務局原本建立的基準表把它更新」）。", "response_removed": false, "topic": "基層勞工勞動教育權益與補助標準檢討"}, {"citations": [{"page": 1777, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=27"}, {"page": 1780, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=30"}, {"page": 1776, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=26"}], "councilor_points": ["指出市長指示研議ChatGPT用於市政治理的可行性，但公務部門涉及法律責任與公共敏感資訊保護，不宜貿然推行或過於冒進（「因為 ChatGPT 還存在很多的疑慮，畢竟我們是公務部門，不是一般商業部門……真的不宜貿然從事」、「公共敏感資訊的保護，必須嚴格確保資訊安全……本席覺得公務部門不用這麼早和這麼急的推動 ChatGPT」）。表示ChatGPT存在資料庫過舊或錯誤、技術限制及資訊安全風險等問題，且產出資料仍需人工查核，會增加公務員負擔（「因資料庫過舊或錯誤導致回答不正確」、「仍須人工加強審核和監管，這是另一個本席覺得非常麻煩的事情」、「ChatGPT 已經開始有了資訊安全風險」）。以詢問ChatGPT現任臺北市市長及市長經歷皆出現嚴重錯誤為例，強調機器不能代表政府回答問題，提醒市府應深入研究而不宜躁進（「連這麼基本市長是誰的問題都答錯，還要引入市府」、「機器可以諮詢，但是不能代表政府回答問題，這一定要注意……ChatGPT 應用於公部門應深入研究，不宜躁進」）。"], "response": "資訊局局長說明ChatGPT應用於公部門可省下時間與人力，但也認同提供資訊時需注意個資與機敏訊息安全，且回答具原創性若不熟悉專業無從判斷對錯，並表示謹遵議員指示不冒進，會深入分析考量（「熟悉相關業務的使用者，可以省下非常多時間」、「在提供訊息時，必須要考量資料安全的相關議題」、「謹遵議員指示」）。", "response_removed": false, "topic": "ChatGPT於公務部門應用之疑慮與資安風險"}, {"citations": [{"page": 3204, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=7"}, {"page": 3205, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=8"}, {"page": 3206, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=9"}], "councilor_points": ["詢問菸害防制法修正後明文禁止花香、果香、巧克力及薄荷4種口味添加物之妥當性，建議市府向中央反映條文應加上「等」字以防範業者添加其他成分（「規定花香、果香、巧克力及薄荷不能加，其他的可不可以加」、「關於這一點，如果你們有跟中央開會的時候要表達一下，條文沒有人這樣子訂的」）。指出業者在網路上以「霧化器」、「烤菸器」等關鍵字或零件名稱化整為零規避稽查，要求衛生局擴大關鍵字搜尋並加強查核（「業者沒這麼傻啦……要從霧化器、霧化芯去尋找」、「新名詞叫烤菸器，不叫加熱菸了……請你們要注意」）。建議衛生局應加重對網路購物平台的約束，對於違規賣家與平台依法進行裁處（「局長你們要加重對平台的約束、請平台業者加強下架、加強查核」、「該罰的，就要罰」）。"], "response": "衛生局局長表示會向中央醫事司反映口味禁令疑慮，並會擴大關鍵字搜尋處理相關違規資料，衛生局健康管理科科長說明依修法規定網路平台最高可裁處20萬元到100萬元罰鍰（「我們會來反映……有機會的話，我會跟醫事司反映」、「這些關鍵字我們會再擴大搜尋」、「最高罰鍰是 20 萬元到 100 萬元」）。", "response_removed": false, "topic": "菸害防制法網路稽查與平台管理"}, {"citations": [{"page": 2604, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=3"}, {"page": 2605, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=4"}, {"page": 2607, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=6"}, {"page": 2603, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=2"}], "councilor_points": ["指出臺中捷運發生吊臂掉落事故，詢問同為無人駕駛系統之文湖線若發生類似狀況是否有防範機制（「文湖線也是同樣的無人駕駛系統……13 秒的時間為什麼反應不及？這是我們今天要探討的事情」）。表示目前文湖線列車防撞機制需實體接觸偵障桿才會啟動煞車，無法遠距離偵測，建議應加裝遠距離監測與警示機制（「我們的偵測範圍只有接觸到，它才會偵測到」、「是不是在列車上要加裝遠距離偵測的機制？我覺得這個可以研究」）。要求捷運公司認真研究加強預警與監測機制，避免類似事件在臺北市發生（「總經理，一定要認真處理這些事，如果類似的事發生在臺北市，我覺得死傷會更慘重，所以一定要記取這次的教訓」）。"], "response": "臺北捷運股份有限公司總經理說明站內可透過不關閉車門、切斷電力或拉動緊急把手阻止列車出發，針對遠距離辨識將尋求技術測試，並會研擬評估早期偵測機制（「要如何讓列車留在站體裡？有幾個方法：首先，針對車門、月台門，讓它不要關閉……即時把電力切斷」、「針對距離或相當距離的辨識，不管是影像或光達，這部分我們可以尋求一些技術的測試」、「會再來評估看哪種形式比較能早期偵測到」）。", "response_removed": false, "topic": "捷運無人駕駛系統異物入侵防撞與預警機制"}, {"citations": [{"page": 2234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=1"}, {"page": 2235, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=2"}, {"page": 2235, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=2"}, {"page": 2237, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=4"}], "councilor_points": ["指出臺北市立大學培養許多優秀國手與金牌選手，但校內有34支球隊卻僅有2位專任教練，人力嚴重不足（「市立大學培養了許多優秀的國家人才，甚至還有奧運金牌選手」、「34 支球隊只有 2 位專任教練，根本就不夠，一看就知道差太遠了」）。表示因缺少專任教練，導致教授需兼任帶隊或自掏腰包外聘教練，且可能造成優秀選手於大學階段流失至外縣市（「因為沒有專任教練……教授只好下來當教練，東兼西兼」、「北市大沒有辦法提供更專精的訓練，導致高中畢業的選手只能到外縣市就讀」）。建議教育局與市立大學研究專任教練需求，比照過往成功經驗向市府爭取增加專任教練員額（「請局長和市立大學研究一下專任教練的需求，把理想方案、中間方案、最基本的要求都列出來」、「希望你們研究各項方案，請北市大提供給局長，市政總質詢時我還會再提出這個問題」）。"], "response": "教育局局長認同有球隊應有專任運動教練指導，並表示專任教練對比賽成績確實有很大幫助，會與市立大學一起努力爭取（「如果有球隊的話，應該要有專任的運動教練來指導會更好」、「專任教練的確幫忙很大……我們會來一起努力」）。", "response_removed": false, "topic": "臺北市立大學體育專任教練員額擴增"}, {"citations": [{"page": 3209, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=12"}, {"page": 3210, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=13"}], "councilor_points": ["指出臺北市小家電資源回收量已達六百多公噸並持續增加，建議市府參考臺中市與高雄市經驗推動「家電診所」（「臺北市近 5 年小家電資源回收量是越來越高……可以看到現在已經達到六百多公噸了」、「參考一下他們的辦法。制訂一些符合臺北市的規定與設施，你們可以自己成立或媒合民間修繕團體」）。表示修復後尚可使用的家電可捐贈給弱勢家庭，兼具環保觀念與資源再利用（「可能一點點壞掉，電線接一接就好了又可以用，如果本身不想用，可以捐給弱勢家庭或團體來使用」）。要求環境保護局於2個月內提出規劃計畫，研究人員培訓與技術配合（「給你們 2 個月時間研究他們如何配置，需要什麼人員與技術上的配合」、「2 個月時間提報出來」）。"], "response": "環境保護局局長表示會評估推動家電再利用（reuse），但因同仁需接受培訓與取得證照，同意於2個月內提出規劃計畫（「確實有些弱勢家庭購買新品可能花費不起，但家電故障或某種零件修復後尚能使用」、「重複使用（reuse）位階是比回收（recycle）都還高……我們會評估」）。", "response_removed": false, "topic": "家電診所推動與廢棄小家電修復再利用"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 7}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=25", "transcript_pages": [1775, 1776, 1777, 1778, 1779, 1780, 1781, 1782], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 14}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=1", "transcript_pages": [2234, 2235, 2236, 2237, 2238, 2239], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 14}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=2", "transcript_pages": [2603, 2604, 2605, 2606, 2607, 2608, 2609, 2610], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 9}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 16, "heading": "警政衛生部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=7", "transcript_pages": [3204, 3205, 3206, 3207, 3208, 3209, 3210, 3211, 3212], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 16}]}, {"dates": ["2023-05-26"], "dept": "工務", "doc_type": "部門質詢", "group": 18, "heading": "工務部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=16", "transcript_pages": [3850, 3851, 3852, 3853, 3854, 3855], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC", "videos": [{"date": "2023-05-26", "group": 18}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162','2026-10-01T22:41:56Z');
INSERT INTO "fact" VALUES('summary:14-01:pefa8e31df3','pefa8e31df3','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:43:47Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2437, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=8"}, {"page": 2437, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=8"}, {"page": 2439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=10"}, {"page": 2439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=10"}, {"page": 2440, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=11"}, {"page": 2441, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=12"}], "councilor_points": ["吳志剛議員詢問機車退出人行道政策的初衷與例外，指出仁愛路2段將機車格移至大馬路致汽車格遭取消，以及人行道機車與自行車對行人造成危害。吳志剛議員指出停車管理工程處與交通警察大隊對未立牌人行道停車之執法標準不一，容易產生糾紛。吳志剛議員建議交通局做整體交通規劃，於尖峰時段設立行人專用時相，並透過提倡大眾運輸及 YouBike 改變市民交通習慣。"], "response": "交通局局長說明該政策初衷係維護行人及弱勢用路人安全，幹道優先推動，並會視狀況設置行人早開或專用時相。停車管理工程處處長與交通警察大隊大隊長說明未實施機退範圍若有劃設格位可停放，未立牌處則依檢舉或交警依規定舉發。交通局局長表示會檢討更便民彈性，並認同應提倡大眾運輸與 YouBike 以減少私人運具使用。", "response_removed": false, "topic": "機車退出人行道政策配套與交通規劃"}, {"citations": [{"page": 1974, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=8"}, {"page": 1974, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=8"}, {"page": 1975, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=9"}, {"page": 1976, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=10"}, {"page": 1976, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=10"}, {"page": 1977, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=11"}], "councilor_points": ["吳志剛議員詢問北市棒壘球場地分配與天母棒球場、大巨蛋之公益時段運用，建議體育局協調非賽事時段供球隊訓練。吳志剛議員指出學校球隊訓練經費與基層推廣站補助款於10月撥款過晚，建議改為半年或每季撥款，並指出教練外縣市比賽住宿補助700元過低。吳志剛議員指出北市培養之優秀選手於高中階段遭外縣市挖角，建議研議離縣退還獎助金或將留才納入教練考核。"], "response": "體育局局長說明北市有37座棒壘球場，天母棒球場公益時段及回饋天數共約120天，大巨蛋未來預計提供10天公益天數，體育局會擔任協調平台。教育局局長表示會研議改採半年期方式撥款，並說明專任教練可申請最高2,000元差旅費外加700元補助，明年將調高外聘教練補助。教育局局長與體育局局長表示北市獎補助經費已較外縣市高，且已將輔導學生在地升學納入專任教練考核加分項目。", "response_removed": false, "topic": "三級棒球場地分配與培訓留才機制"}, {"citations": [{"page": 3703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=2"}, {"page": 3703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=2"}, {"page": 3704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=3"}, {"page": 3704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=3"}, {"page": 3705, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=4"}, {"page": 3705, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=4"}], "councilor_points": ["吳志剛議員指出建照申請涉及劃設消防車輛救災活動空間指導原則時，預審小組開會頻率約1至2個月，最長需等待半年的案件影響建築業者資金與交屋。吳志剛議員強調「指導原則」依行政程序法不具強制力，若相對人拒絕應停止且不得處分。吳志剛議員建議市府訂定自治條例給予強制力，或比照其他縣市作為都更獎勵誘因，而非將政府責任轉嫁給民眾。"], "response": "建築管理工程處處長與都市發展局局長說明預審小組平均1至2個月開會一次，最長等候5個月係因邀請專家學者時間較難協調。建築管理工程處處長表示指導原則為輔導措施，北市已頒布行政規則據以執行，現正與消防局研討通案性提升建築自救能力之檢討原則以簡化程序。都市發展局局長與建築管理工程處處長表示後續會研議訂定自治條例或獎勵機制之建議。", "response_removed": false, "topic": "劃設消防車輛救災活動空間指導原則審查與定位"}, {"citations": [{"page": 2962, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=6"}, {"page": 2964, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=8"}, {"page": 2965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=9"}], "councilor_points": ["吳志剛議員詢問派出所配置電擊槍數量與使用時機。吳志剛議員指出電擊槍體積過大且單發裝填、緊急時不便攜帶，自108年發放至今僅使用過3次，且對心血管疾病患者有傷害風險。吳志剛議員建議警察局向中央反映基層使用困難，並授權基層員警大膽使用警棍或警槍以利自保。"], "response": "警察局局長說明全北市配發355支電擊槍，各分局約1至2支，每個月皆有常訓。警察局局長表示電擊槍係中央發放之輔助型設備，目的在避免嫌犯第一時間傷亡，坦言突發狀況時攜帶確實不便。警察局局長表示會將基層回饋與使用情形反映給中央警政署進行全國性修正。", "response_removed": false, "topic": "基層警察配備電擊槍之使用效能與效益評估"}, {"citations": [{"page": 4279, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=33"}, {"page": 4281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=35"}, {"page": 4282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=36"}, {"page": 4280, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=34"}, {"page": 4281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=35"}, {"page": 4282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=36"}], "councilor_points": ["吳志剛議員詢問中正區南福里劃分之評估進度，指出南福里戶數達4,785戶、人口達1萬1,754人，已超過自治條例4,000戶之劃分門檻。吳志剛議員指出南福里有資源不足、幅員廣大及公衛警政兵單件數達一般里3倍等問題，建議試辦劃分為2個里或在市長4年任期內解決。吳志剛議員要求在正式劃分前，區公所應先給予南福里更多人力與資源支援。"], "response": "民政局局長與市長表示全北市共有12個里超過4,000戶、14個里未達1,000戶，依自治條例須全盤考量，且因明年有總統及立委大選，評估規劃將於選後啟動。市長與民政局局長承諾在通盤評估期間，區公所與民政局會提供人力與相關支援，以減輕里長負擔。", "response_removed": false, "topic": "中正區南福里重新劃分與行政資源分配"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=33", "transcript_pages": [4279, 4280, 4281, 4282, 4283, 4284, 4285, 4286, 4287, 4288, 4289], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 6}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=5", "transcript_pages": [1417, 1418, 1419, 1420, 1421], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 18}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=10", "transcript_pages": [1557, 1558, 1559, 1560, 1561], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 4}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=7", "transcript_pages": [1973, 1974, 1975, 1976, 1977], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 1}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=7", "transcript_pages": [2436, 2437, 2438, 2439, 2440, 2441, 2442, 2443], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 2}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=5", "transcript_pages": [2961, 2962, 2963, 2964, 2965, 2966, 2967, 2968], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 4}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=1", "transcript_pages": [3702, 3703, 3704, 3705, 3706], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC','2026-10-01T22:43:47Z');
INSERT INTO "fact" VALUES('summary:14-01:p155e15fe02','p155e15fe02','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:45:42Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4042, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=4"}, {"page": 4044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=6"}, {"page": 4042, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=4"}, {"page": 4046, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=8"}, {"page": 4044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=6"}, {"page": 4045, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=7"}, {"page": 4040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=2"}, {"page": 4041, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=3"}], "councilor_points": ["張志豪議員指出，臺北市被道路掩埋的瓦斯閥門總數為7,218個，但產業發展局於記者會說明的數字卻為3,613個，短少3,605個，並表示「產發局拿假資料給議員」。張志豪議員要求市府於3日內對資料造假問題提出調查報告，並要求瓦斯公司夜間外勤值勤人力應至少保持在2組以上。"], "response": "市長說明，內部會深刻檢討數據落差問題，避免再提供不實數據給議員，並會針對清查流程進行檢討後回報報告。產業發展局局長說明，已訂定施工前、中、後的標準作業程序，預計2年內將所有被掩埋的瓦斯逆止閥重新做提升露出。", "response_removed": false, "topic": "瓦斯逆止閥被掩埋與數據落差改善"}, {"citations": [{"page": 2146, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=2"}, {"page": 2148, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=4"}], "councilor_points": ["張志豪議員指出，臺北市高中以下學生在111年自傷自殺人數為1,583人，詢問教育局與衛生局是否設有學生身心科就診的橫向通報勾稽機制，以做到防患於未然。張志豪議員建議教育局與衛生局合作對就診個案進行觀察勾稽，並建議修正霸凌應變小組組成，改由校外賢達或專業人士擔任召集人，避免行政力干擾專業判斷。"], "response": "教育局局長說明，教育局與衛生局有合作媒合醫院提供青少年身心科諮詢服務，但個別就診訊息目前尚無直接轉給學校的機制，後續會再研議跨局處合作聯通訊息的可行性。教育局局長表示，霸凌小組組成屬於中央法規，將來若有機會會向中央提出建議。", "response_removed": false, "topic": "學生自傷自殺防治與校園霸凌因應機制"}, {"citations": [{"page": 4070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=32"}, {"page": 4071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=33"}, {"page": 4074, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=36"}, {"page": 4075, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=37"}, {"page": 4071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=33"}, {"page": 4074, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=36"}, {"page": 4076, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=38"}], "councilor_points": ["張志豪議員指出，臺北市消防局法定編制員額為2,063人，實際人數為1,845人，其中外勤人力約1,500人，詢問市府如何補足人力落差並改善消防人員勤休權益。張志豪議員建議市府爭取將消防人員服務人口比從1比1,362調降至低於1,000，並要求市府全力支持補足消防人力。"], "response": "市長表示，會全力支持補足消防人力，並先以服務人口比1比1,000為目標，第一階段預計於115年達到目標。消防局局長說明，目前正向中央爭取受訓員額，預計115年達到2,063人的法定編制員額，並希望於117年至118年間達到員額2,490人，以落實每天8小時勤務。", "response_removed": false, "topic": "消防編制員額補足與勤務勤休權益改善"}, {"citations": [{"page": 2557, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=1"}, {"page": 2558, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=2"}, {"page": 2561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=5"}, {"page": 2561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=5"}, {"page": 2559, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=3"}], "councilor_points": ["張志豪議員指出，依據《道路交通標誌標線號誌設置規則》第226條規定，統計大安區與文山區142個無號誌且有發生事故的路口中，就有37個路口的車禍數量超過法定標準卻未設號誌。張志豪議員建議交通局與資訊局、警察局合作，運用大數據建構科學化模型改善道路設計，並要求交通局於總質詢前提交評估構想。"], "response": "交通局局長說明，會先與資訊局討論資源與檢視方法，並表示會利用半年的時間逐一檢視這37處路口，會在總質詢前將初步構想向議員報告。資訊局專門委員表示，在資料乾淨準確的前提下，透過大數據與視覺化呈現優先設置號誌路口在技術上可行，會配合交通局進行規劃。", "response_removed": false, "topic": "無號誌路口交通安全與號誌設置標準"}, {"citations": [{"page": 2561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=5"}, {"page": 2565, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=9"}, {"page": 2566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=10"}, {"page": 2566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=10"}], "councilor_points": ["張志豪議員指出，忠孝西路禁行機車政策施行已超過40年，目前市府僅開放深夜23時至隔日6時通行，車流量每小時僅400至600輛次，數據容易失真。張志豪議員建議交通局應擴大試辦規模，選擇車流量較大的時段或設計不同情境進行模擬，以取得代表性數據。"], "response": "交通局局長說明，會設計如提早至夜間9時或休假情境進行操作與數據模擬。交通管制工程處處長說明，因考量上下午尖峰開放預估會引進4,000至6,000輛的交通量，基於安全疑慮才先於低交通量時段開放，後續會持續運用數學方法預測與規劃。", "response_removed": false, "topic": "忠孝西路禁行機車政策檢討與開放試辦"}, {"citations": [{"page": 3600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=14"}, {"page": 3602, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=16"}, {"page": 3604, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=18"}, {"page": 3603, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=17"}], "councilor_points": ["張志豪議員指出，臺北市大地工程處管轄的154條山區公有步道監視器數量為0，而近5年山區搜救案達94件，平均每件搜救耗時約7小時。張志豪議員建議市府採用記憶卡循環紀錄方式克服山區網路傳輸困難，並要求大地工程處於1個月內研議以四獸山試辦設置監視器的可行性評估及費用預估。"], "response": "大地工程處處長說明，山區設置監視器過去受限於缺乏電源與網路線，且需考量錄影監視器自治條例規範與合法性，會於1個月內進行評估並了解相關法令。消防局災害搶救科科長表示，認同於岔路設置監視器確認失蹤點能有效縮減搜救時間的邏輯。", "response_removed": false, "topic": "山區步道搜救與監視器設置"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=1", "transcript_pages": [4039, 4040, 4041, 4042, 4043, 4044, 4045, 4046, 4070, 4071, 4072, 4073, 4074, 4075, 4076, 4077, 4078], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 1}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=23", "transcript_pages": [1304, 1305, 1306, 1307, 1308, 1309, 1310], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 13}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=15", "transcript_pages": [1821, 1822, 1823, 1824, 1825, 1826, 1827, 1828, 1829], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 16}]}, {"dates": ["2023-05-02", "2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=1", "transcript_pages": [2145, 2146, 2147, 2148, 2149, 2150, 2151, 2152, 2153, 2154, 2155], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 10}, {"date": "2023-05-04", "group": 10}]}, {"dates": ["2023-05-09"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=1", "transcript_pages": [2557, 2558, 2559, 2560, 2561, 2562, 2563, 2564, 2565, 2566, 2567], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC", "videos": [{"date": "2023-05-09", "group": 7}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=22", "transcript_pages": [3057, 3058, 3059], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 7}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=14", "transcript_pages": [3600, 3601, 3602, 3603, 3604, 3605, 3606, 3607], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC','2026-10-01T22:45:42Z');
INSERT INTO "fact" VALUES('summary:14-01:p499663cb96','p499663cb96','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:48:25Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2287, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=17"}, {"page": 2289, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=19"}, {"page": 2288, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=18"}], "councilor_points": ["張文潔議員指出公立與非營利幼兒園抽籤及錄取結果公布時間過晚，造成家長因不確定性先報名私立幼兒園，開學後候補上又需轉學而增加幼兒適應壓力，建議研擬將抽籤與報到日程整體提前（「建議公幼、準公共、非營利幼兒園抽籤錄取的時間可以整體提前，避免造成公幼作業的衝突，也降低孩子們面臨轉學的可能性」）。張文潔議員表示私立教保服務機構設施設備改善補助要求校方自籌25%且以3年申請1次為限，缺乏誘因且不符消耗品更換現況，建議取消自籌25%規定並改為每年皆可申請（「具體要求，應該取消配合自籌總經費之 25%的規定，以及應該修改 3 年申請 1 次補助的規定」）。張文潔議員反映教育局稽查人員前往幼兒園稽查時態度生硬且對園內人員施壓，要求稽查應站在人的立場並檢討程序與態度（「教育局去稽查、去輔導沒有錯，但你們要站在人的立場」）。"], "response": "教育局局長說明抽籤日程提前部分會進行研議，精算期程作業並努力檢討（「提前的部分我們來研議。能不能做到 3 月、4 月我們來努力，期程作業有精算的必要性」）。教育局局長表示會檢討改進私立教保機構補助相關規定（「非常謝謝議員提供意見，我們會檢討改進」）。教育局學前教育科科長說明內部已檢討稽查程序、流程與態度，並請同仁配戴密錄器（「這部分我們已與同仁檢討稽查程序、流程與態度，也都請同仁要配戴密錄器」）。", "response_removed": false, "topic": "幼兒園抽籤日程與私立教保機構補助規範檢討"}, {"citations": [{"page": 1338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=3"}, {"page": 1339, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=4"}, {"page": 1339, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=4"}, {"page": 1340, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=5"}, {"page": 1341, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=6"}], "councilor_points": ["張文潔議員指出民政局部分區公所單身聯誼活動進度仍標示「規劃中」，且活動內容太過制式，建議增加浪漫氛圍並加強事後撥電話關懷等管考措施（「不但要讓聯誼的內容要再更浪漫，我認為要去管考聯誼後續」）。張文潔議員表示臺北市生育獎勵金提高補助於112年4月4日實施且不溯及既往，導致去年12月至今年3月出生之三千多名新生兒家長未受惠，要求應回溯至市長就職日12月25日（「應該要回溯到他就職日也就是 12 月 25 日」）。"], "response": "民政局局長說明會好好規劃並營造良好氛圍與地點，且會去了解事後管考作法（「我們要好好的規劃、好好營造氣氛」、「議員，我們一定會去了解」）。民政局人口政策科科長補充說明各區公所在2月燈節時每區已各辦理1場，共已辦理12場單身聯誼活動（「各區公所在 2 月燈節時每區已各辦理 1 場」、「已經辦理 12 場單身聯誼活動」）。民政局局長表示認同應重視所有孩子，會往溯及既往的方向前進（「我覺得還是要溯及既往」、「好，往這個方向前進」）。", "response_removed": false, "topic": "單身聯誼活動辦理與生育獎勵金回溯"}, {"citations": [{"page": 2767, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=7"}, {"page": 2768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=8"}, {"page": 2770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=10"}, {"page": 2769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=9"}], "councilor_points": ["張文潔議員指出臺北市128座公有立體停車場中有51座不符法定2%之婦幼停車格標準，且發出9萬6千多張婦幼停車證卻僅有1,729格婦幼車位，數量明顯不足（「光是你提供給我的資料就有 51 座不符標準，所以我認為你應該要全面檢討」）。張文潔議員建議應優先提升政府機關、公營事業、百貨公司及零售式量販店之婦幼停車格比例至3%至5%，並優先於小兒科與婦產科診所周邊劃設路邊婦幼車位（「應該要優先提升政府機關以及公營事業、百貨公司、零售式量販店的婦幼停車格位，比例必須達到 3%至 5%，並且要優先增設婦幼停車格位在有需求的小兒科診所或是婦產科診所周邊」）。"], "response": "停車管理工程處處長表示會重新檢視公有停車場婦幼車位數量（「我們會重新檢視」）。停車管理工程處處長說明若有適合地點不排除擴大試辦路邊婦幼車位，並承諾於1個月內進行整理與盤查回覆（「不排除再來擴大試辦」、「請議員給我 1 個月的時間整理及盤查」）。", "response_removed": false, "topic": "公有停車場婦幼停車格設置率與劃設檢討"}, {"citations": [{"page": 2924, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=28"}], "councilor_points": ["張文潔議員指出新手媽媽面對生產常感茫然且坊間待產包資訊混亂，建議衛生局應展現貼心照護，於明年編列預算提供待產包並搭配媽媽手冊發放（「本席具體強烈的建議，就是明年編列預算的時候，必須要有這一個項目，然後再搭配媽媽手冊，或者是搭配什麼樣的產檢時期，就把它送給媽媽們」）。張文潔議員要求衛生局針對待產包補助計畫與經費研議，於1個月內給予回覆（「針對這個明年編列預算，這個研議大概多久可以給本席一個回覆」、「能不能 1 個月」）。"], "response": "衛生局局長表示肯定該計畫，並承諾會慎重考慮經費及相關措施，朝此方向研議（「我覺得這個計畫非常的好，我們會朝這個方向來研議看看，還有包括經費等等相關的措施，我們都會慎重的考慮」）。衛生局局長同意於1個月內提供回覆（「能不能 1 個月」、「好，謝謝議員」）。", "response_removed": false, "topic": "新手媽媽待產包發放規劃與補助"}, {"citations": [{"page": 2762, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=2"}, {"page": 2763, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=3"}, {"page": 2764, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=4"}, {"page": 2765, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=5"}, {"page": 2763, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=3"}, {"page": 2764, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=4"}], "councilor_points": ["張文潔議員指出捷運信義線東延段施工列管250件損鄰案，且福德街沿線民宅出現地層下陷30至60公分，導致大雨時雨水倒灌，要求捷運局確實公開監測數據並做好改善溝通（「監測民宅內最嚴重的下陷情況，甚至有 3、40 公分，4、50 公分」、「尤其要跟鄰房都做好溝通」）。張文潔議員反映工程施工與半夜運送材料產生噪音影響居民作息，並詢問信義線東延段預計完工時程（「常常會收到住戶跟我陳情，比如路面板不平導致聲音很大，也有民眾跟我說你們常常利用清晨或是半夜的時候運送工程材料」、「信義線東延段到底什麼時候會完工」）。"], "response": "捷運工程局第二工程處處長說明福德街地層已穩定，未來車站頂板做完後進行道路復舊，會將路面降回與建物平齊並一併處理解決管溝與排水系統（「連續壁下完之後周邊 2 側的地盤已經穩定」、「整個路面我們會一起修成跟原來的建物」）。捷運工程局局長表示會與地方民眾溝通施工時段，並說明信義線東延段預計於114年底完工（「這個施工時段我們再跟地方民眾溝通一下」、「大概預計於 114 年底一定會完工」）。", "response_removed": false, "topic": "捷運信義線東延段施工損鄰與地層下陷處置"}, {"citations": [{"page": 2917, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=21"}, {"page": 2919, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=23"}, {"page": 2920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=24"}, {"page": 2918, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=22"}], "councilor_points": ["張文潔議員反映民眾陳情1樓餐廳產生運轉低頻噪音與油煙異味困擾樓上住戶長達半年，且稽查人員約定晚上10時稽查卻遲至10時40分才到場，質疑處理流程與效率（「這個餐廳常常發出機器運轉的聲音，以及產生異味」、「約到一個晚上 10 時的時間……你們是 10 時 40 分才到」）。張文潔議員建議環保局應檢討人力配置，並提供儀器放置於陳情人家中進行持續檢測，引入技術協助源頭改善（「如果能夠放置檢測的儀器在陳情人家裡，他同意了，你就去檢測嘛」、「希望你們能夠像你講的……引入技術」）。"], "response": "環境保護局局長說明稽查人員因交通狀況致抵達時間延誤會檢討改善，並表示低頻噪音與逸散異味靠單純稽查處罰效果有限，將引入技術輔導店家進行源頭改善（「這件事情，我們會改善」、「源頭改善比那個還重要，我想說引入技術」）。環境保護局局長表示同意提供設備於民眾希望且同意的地點進行檢測蒐證（「當然是我們提供設備」、「設置的地點，我們是設置在當地民眾希望能夠同意的地點」）。", "response_removed": false, "topic": "餐廳低頻噪音與異味稽查問題改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=1", "transcript_pages": [1336, 1337, 1338, 1339, 1340, 1341, 1342, 1343, 1344, 1345], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 15}]}, {"dates": ["2023-04-25", "2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=8", "transcript_pages": [1683, 1684, 1685, 1686, 1687, 1688, 1689, 1690, 1691], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 9}, {"date": "2023-04-27", "group": 9}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=15", "transcript_pages": [2285, 2286, 2287, 2288, 2289, 2290, 2291, 2292], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 16}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=1", "transcript_pages": [2761, 2762, 2763, 2764, 2765, 2766, 2767, 2768, 2769, 2770, 2771, 2772], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 16}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 2, "heading": "警政衛生部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=21", "transcript_pages": [2917, 2918, 2919, 2920, 2921, 2922, 2923, 2924, 2925, 2926, 2927], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 2}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=19", "transcript_pages": [3680, 3681, 3682, 3683, 3684, 3685, 3686, 3687, 3688, 3689, 3690], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162','2026-10-01T22:48:25Z');
INSERT INTO "fact" VALUES('summary:14-01:pe9aa863557','pe9aa863557','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:50:09Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1851, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=14"}, {"page": 1855, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=18"}, {"page": 1853, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=16"}, {"page": 1850, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=13"}, {"page": 1851, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=14"}], "councilor_points": ["張斯綱議員指出臺北市動物之家現有 1,033 隻動物且中繼園區接近爆滿，質疑提供之新館可收容數量資料前後不一，指出動保處同仁「對於數字的部分很不擅長」。張斯綱議員要求動物保護處檢討流浪犬貓認養補助預計受理 250 隻之標準過低，建議改為提供認養飼主 3 年至 4 年之寵物保險費以提高誘因。張斯綱議員詢問臺北市合法寵物生命事業登記狀況與消費糾紛，要求動保處在一星期內清查相關數據並與法制單位研議管理自治條例。"], "response": "動物保護處處長說明中繼園區會調整籠舍擴充空間，新蓋動物之家規劃可收容犬隻 700 隻與貓隻 300 隻，並就資料提供舊版數據表達歉意與檢討。動物保護處處長表示認養補助若超過預計之 250 隻會挹注經費，並會考量議員提出補助 3 年寵物保險之建議。動物保護處處長表示臺北市目前無寵物殯葬業者，承諾在一星期內清查消費糾紛與登記數據，並與法制單位研議相關管理規範。", "response_removed": false, "topic": "動物之家收容與寵物生命事業管理"}, {"citations": [{"page": 4386, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=16"}, {"page": 4387, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=17"}, {"page": 4388, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=18"}, {"page": 4385, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=15"}, {"page": 4386, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=16"}, {"page": 4387, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=17"}], "councilor_points": ["張斯綱議員詢問市府處理民進黨中央黨部性騷擾案件之進度，要求勞動局不能讓對方無限期延後回函，若未依限期 5 天回覆應依法召開性別平等委員會審查。張斯綱議員指出場所主人若對性騷擾事件保持緘默未盡責任「事實上就是個幫凶」，詢問場所負責人應負之連帶責任。張斯綱議員指出媒體報導性騷擾案情未獲授權，要求警察局調查擅自透露案情之員警並予以內部處分，同時發函媒體說明該發言未經內部證實。"], "response": "勞動局局長說明民進黨中央黨部尚未在 6 月 5 日限期內書面回函，市長表示絕不容許無故拖延，若未回覆將依法召開性別平等委員會進行審查與開罰。社會局局長澄清性騷擾防治法規定場所主人應協助報案與蒐證，未盡責任可處 1 萬元至 10 萬元罰鍰，被害人若於非執行職務期間受害應立即向該場域主管反映。警察局局長與警察局北投分局分局長均表示未授權對外說明案情，警察局局長承諾會進行內部調查處分擅自透露案情之員警，並發函媒體說明。", "response_removed": false, "topic": "政黨性騷擾案件申訴處置與未授權說明調查"}, {"citations": [{"page": 3519, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=5"}, {"page": 3520, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=6"}, {"page": 3521, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=7"}, {"page": 3522, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=8"}, {"page": 3523, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=9"}], "councilor_points": ["張斯綱議員指出臺北市列管 24 處山坡地老舊聚落安全狀況穩定，但各土地管理機關租約條件不一，致使住戶「霧煞煞」。張斯綱議員質疑市府會議紀錄規定「租約到期即不再續租」，致使部分局處不予續約或改收占用補償金，造成住戶恐慌。張斯綱議員建議市府於府級層級成立工作小組，在 2 個月內訂定統一的標準作業程序與公版租賃契約，保障住戶權益。"], "response": "工務局局長與大地工程處處長說明列管之老舊聚落每年均進行水土保持巡勘，目前狀況良好且在安全範圍內，無強制立即拆遷之必要。工務局局長表示市府財產管理由財政局訂定一致性原則，將會整合工務局所屬新工處與公園處之簽約條件。工務局局長承諾會在 2 個月內進行整體檢討，先訂出整體原則並研擬標準作業程序。", "response_removed": false, "topic": "山坡地老舊聚落安全評估與租約統一"}, {"citations": [{"page": 1844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=7"}, {"page": 1845, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=8"}, {"page": 1846, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=9"}, {"page": 1848, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=11"}, {"page": 1844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=7"}, {"page": 1847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=10"}], "councilor_points": ["張斯綱議員質疑前市府推動之「元宇宙臺北隊」與願景白皮書缺乏落實面，指出 112 年度未編列相關大專案預算，形容該政策「基本上就全劇終」。張斯綱議員指出跨部門元宇宙任務小組長達 5 個月未曾開會，且智慧城市場域實驗案落地率僅 11%，認為政策「華而不實」。張斯綱議員指出國際上元宇宙已有退燒趨勢，建議資訊局重新整理並了結該政策，勿讓市民一頭霧水。"], "response": "資訊局局長說明元宇宙願景成分較高，且軟硬體技術尚未成熟，資訊局暫無針對元宇宙大專案編列預算，但會保留 VR 與 AR 等關鍵技術。資訊局局長與產業發展局局長均表示元宇宙任務小組尚未開會，資訊局局長說明目前於地政局進行虛擬地政事務所概念驗證，尚無計畫繼續往下走。資訊局局長表示會檢討實驗案落地率問題，並承諾協助各局處進行技術評估。", "response_removed": false, "topic": "元宇宙政策執行成效與檢討"}, {"citations": [{"page": 4395, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=25"}, {"page": 4395, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=25"}, {"page": 4397, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=27"}, {"page": 4397, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=27"}, {"page": 4400, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=30"}], "councilor_points": ["張斯綱議員反映北投中繼市場夏季冷氣不足且下雨漏水，要求市場處儘速補強改善。張斯綱議員指出舊北投市場建物結構嚴重受損且裂縫擴大，主張整棟拆除重建，並建議北投區公所另覓市有地重建，不要與市場綁在一起。張斯綱議員要求市府關心未搬遷至中繼市場之 52 家攤商權益，並考量未來新建市場之容積與建蔽率，以滿足攤商坪數需求。"], "response": "市場處處長說明會處理中繼市場自動門無法關閉致冷氣外散及漏水保固問題，並預估中繼市場使用年限因改建而拉長。市長與市場處處長表示若確定全棟拆除改建，預計期程約 5 年至 7 年，會確保結構安全；民政局局長表示區公所若拆除不願再投入補強預算，會於公有資產盤點會議提出搬遷計畫。市場處處長與市長承諾會辦理說明會與未搬遷之 53 攤商充分溝通，確保攤商權利並盡力協助後續安置。", "response_removed": false, "topic": "北投市場改建與中繼市場改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=14", "transcript_pages": [4384, 4385, 4386, 4387, 4388, 4389, 4390, 4391, 4392, 4393, 4394, 4395, 4396, 4397, 4398, 4399, 4400, 4416], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC", "videos": [{"date": "2023-06-05", "group": 9}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=19", "transcript_pages": [1382, 1383, 1384, 1385, 1386, 1387, 1388, 1389, 1390, 1391, 1392, 1393], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 16}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=6", "transcript_pages": [1843, 1844, 1845, 1846, 1847, 1848, 1849, 1850, 1851, 1852, 1853, 1854, 1855, 1856, 185