videos": [{"date": "2023-05-18", "group": 13}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=4", "transcript_pages": [3518, 3519, 3520, 3521, 3522, 3523, 3524, 3525, 3526, 3527, 3528], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC','2026-10-01T22:50:09Z');
INSERT INTO "fact" VALUES('summary:14-01:p7dbdadb454','p7dbdadb454','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:52:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1435, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=23"}, {"page": 1548, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=1"}, {"page": 1550, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=3"}, {"page": 1550, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=3"}, {"page": 1552, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=5"}, {"page": 1552, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=5"}], "councilor_points": ["徐弘庭議員指出市府在富邦集團設有 4 席董事與 9 席獨立董事，並關注現任獨立董事在政黨輪替後多未依慣例辭職的情況。他指出外界對獨立董事酬勞是否回捐黨中央存在疑慮，建議市府發文告知現任獨立董事關於遴選辦法的變更，提示其知所進退。"], "response": "財政局局長說明市府已修正獨立董事遴選作業要點，目前依規定若無違法或自願辭職無法主動解職，但富邦金控預計於 6 月進行改選。財政局局長表示會斟酌發文內容，轉達議員關於知所進退的意見。", "response_removed": false, "topic": "富邦金控獨立董事遴選與派任"}, {"citations": [{"page": 4249, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=3"}, {"page": 4250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=4"}, {"page": 4250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=4"}, {"page": 4251, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=5"}, {"page": 4252, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=6"}], "councilor_points": ["徐弘庭議員指出公共住宅不應為了湊數字而「為蓋而蓋」，現行租金設定過高且未能真正照顧到最需要的族群。他要求市府賦予公共住宅更有目的性的政策價值，優先保障如單身獨居老人與低收入戶等弱勢族群的基本居住權。他並建議市府從雙北及北北基桃區域發展的角度規劃交通與公共住宅。"], "response": "臺北市長說明新辦社會住宅的腳步不會停下，但同意推動政策的核心目的是解決居住問題。臺北市長表示市府不會為蓋而蓋，將結合包租代管、都市更新分回戶、EOT 與 TOD 等多元政策工具，提供給真正有需求的民眾。", "response_removed": false, "topic": "公共住宅政策檢討與定位"}, {"citations": [{"page": 1554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=7"}, {"page": 1555, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=8"}, {"page": 1556, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=9"}, {"page": 1556, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=9"}], "councilor_points": ["徐弘庭議員指出臺北市於 2022 年每日漏水量仍達 27 萬噸，且給水管待汰換管線中有 571 公里因圖資問題無法考據年份。他表示截至 111 年待汰換管線仍有 999 公里，若按每年約 110 公里的速度推進尚需 9 年才可換完。他要求市府成立防漏專案並加速汰換進度，以因應極端氣候帶來的水資源挑戰。"], "response": "臺北自來水事業處處長說明市府目標於 114 年將漏水率降至 10%，現行的 20 年汰換計畫將於 114 年階段性結束。臺北自來水事業處處長表示目前正在準備下一階段計畫，預計後年提出更積極的方案報告。", "response_removed": false, "topic": "自來水管線漏水與汰換計畫"}, {"citations": [{"page": 1431, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=19"}, {"page": 1432, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=20"}], "councilor_points": ["徐弘庭議員指出外送與清潔等平臺式媒合服務蓬勃發展，但現行就業服務法等舊有法令已不足以應對新型態平臺經濟。他表示不知情消費者在沒有主觀犯意下使用平臺服務，若媒合到非法外勞仍會受到法律裁罰，完全不合情理。他要求市府檢討法令漏洞，並向中央建議修法，給予平臺提供方更多查證責任與罰則。"], "response": "法務局局長說明新型態消費行為導致爭議增加，現行法令確實無法有效規範且有不合理處，會進行具體修法討論。勞動局局長表示情理上確實有調整必要，會向中央反映研究修正就業服務法相關法條。", "response_removed": false, "topic": "平臺經濟新型態勞動法令修法"}, {"citations": [{"page": 1983, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=17"}, {"page": 1984, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=18"}, {"page": 1985, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=19"}, {"page": 1986, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=20"}, {"page": 1985, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=19"}], "councilor_points": ["徐弘庭議員質疑市府簽署典藏切結是「喪權辱國的條約」，指出歷年主燈多難以長期保存，目前將重 20 公噸的主燈拆解暫存於北投機廠並非典藏良策。他詢問主燈最終去處，並要求市府於 6 月底前確定具體地點。"], "response": "觀光傳播局局長說明因 109 年 12 月申辦燈會時曾簽署典藏承諾，目前正對 3 個評估中的地點進行簽呈。觀光傳播局局長表示預計 6 月底前可以確定主燈的設置地點。", "response_removed": false, "topic": "臺灣燈會主燈典藏與處置"}, {"citations": [{"page": 4254, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=8"}, {"page": 4255, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=9"}, {"page": 4256, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=10"}, {"page": 4256, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=10"}], "councilor_points": ["徐弘庭議員陳情福德坑環保復育公園連續遭違法集團偷倒垃圾，截至 112 年 4 月單次清運量即達 11 公噸，甚至偷走環保局監視器，指其公然挑戰公權力。他要求市府警察局與環保局展現魄力，於 1 個月內完成逮捕業者、裝設監視器與設置圍籬等 3 項工作。"], "response": "臺北市長表示絕不縱容違法行為，承諾於 1 個月內逮捕違法業者，並要求警察局儘速設好 5 支監視器。環境保護局局長說明會請環保警察跨區偵辦，警察局局長亦表示警察局會全力偵辦並拿出決心把人抓到。", "response_removed": false, "topic": "福德坑公園遭偷倒垃圾與公權力執行"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=1", "transcript_pages": [4247, 4248, 4249, 4250, 4251, 4252, 4253, 4254, 4255, 4256, 4257], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 6}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=17", "transcript_pages": [1429, 1430, 1431, 1432, 1433, 1434, 1435], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 18}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=1", "transcript_pages": [1548, 1549, 1550, 1551, 1552, 1553, 1554, 1555, 1556, 1557], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 4}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=17", "transcript_pages": [1983, 1984, 1985, 1986, 1987, 1988], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 1}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=1", "transcript_pages": [2430, 2431, 2432, 2433, 2434, 2435, 2436], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 2}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=18", "transcript_pages": [2974, 2975, 2976, 2977, 2978, 2979], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 4}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC','2026-10-01T22:52:19Z');
INSERT INTO "fact" VALUES('summary:14-01:p62ab44979e','p62ab44979e','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T22:56:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1058, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=2"}, {"page": 1059, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=3"}, {"page": 1061, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=5"}, {"page": 1062, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=6"}, {"page": 1057, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=1"}, {"page": 1063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=7"}], "councilor_points": ["徐立信議員指出，有足球隊串連多個學籍並以校友會名義於網路公開募款，質疑資金流向非學校專戶且規避監督。徐立信議員詢問相關單位是否有申請補助及如何進行查核，要求主管機關說明監管機制與查處作為。"], "response": "體育局競技運動科科長說明，該足球隊未申請基層選手運動訓練站補助。教育局體育及衛生保健科科長表示，捐款應依會計程序納入學校專款專用或經家長會組織運作。社會局局長與人民團體科科長說明，該校友會未申請公益勸募許可，若於網路對不特定對象公開勸募涉違反規定，將於 2 個月內調閱帳務並依法查處。法務局局長表示，未曾針對該案確認過相關資料。", "response_removed": false, "topic": "學校足球隊公開募款監督與管理"}, {"citations": [{"page": 1733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=8"}, {"page": 1734, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=9"}, {"page": 1734, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=9"}, {"page": 1736, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=11"}, {"page": 1736, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=11"}], "councilor_points": ["徐立信議員指出，臺北市消費指數增幅高於全國，市府以公告地價計收市有土地租金且營業用加乘計費，致使承租民眾租金負擔過高。徐立信議員表示，部分房屋兼具自用與部分營業使用，全數適用較高費率並不合理，建議檢討計價標準。"], "response": "主計處處長表示，認同臺北市消費指數增幅較大，市府已成立物價督導小組按月監督物價。財政局局長說明，市有土地租金係依公告地價依法計收，自用可享 6 折優惠，營業用係依國稅局提供營業事實加乘，承諾將就個別陳情案件深入了解。", "response_removed": false, "topic": "市有土地出租租金計收標準檢討"}, {"citations": [{"page": 2076, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC#page=7"}, {"page": 2597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F0E2FE9639433EE0E4A21447E7507E4593A86FA0F2D95E7947CC1112AA866B2202D1DE3DCEB210BC#page=10"}, {"page": 2597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F0E2FE9639433EE0E4A21447E7507E4593A86FA0F2D95E7947CC1112AA866B2202D1DE3DCEB210BC#page=10"}, {"page": 2598, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F0E2FE9639433EE0E4A21447E7507E4593A86FA0F2D95E7947CC1112AA866B2202D1DE3DCEB210BC#page=11"}], "councilor_points": ["徐立信議員指出，部分多元化計程車駕駛利用轉隊申辦流程的時間差違規「雙開」加入多個車隊，導致民眾叫車資訊與實際到場車輛不符。徐立信議員質疑市府缺乏防堵措施，建議建立查核機制並對違規行為予以裁罰。"], "response": "交通局局長說明，現行缺乏管控易生此情形，支持透過資訊系統落實管理並處理申訴案件。公共運輸處處長表示，法規嚴禁駕駛加入多個車隊，市府已建請交通部建置駕駛員資料查詢平台並預計 5 月底完成，若查獲明確違規事證必依法裁處。", "response_removed": false, "topic": "多元化計程車違規跨車隊執業與管理"}, {"citations": [{"page": 3769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC#page=1"}, {"page": 3770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC#page=2"}, {"page": 3770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC#page=2"}, {"page": 3772, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC#page=4"}], "councilor_points": ["徐立信議員指出，新建大樓儲水箱破裂漏水影響住戶用水，建商將原本圖說標示的 20 公分鋼筋混凝土私自改為 0.5 公分構造，質疑市府核發使用執照時未嚴格審查。徐立信議員要求市府行使公權力，追究建商與監造人簽證不實之責任。"], "response": "都市發展局局長表示，將主動召集起造人、承造人及監造人溝通處理，若簽證內容不實將依法處理。建築管理工程處處長說明，使用執照審查係針對主要構造與設備，將要求承造人及監造人限期說明並追究相關行政責任。", "response_removed": false, "topic": "新建大樓儲水箱結構不符與使照審查"}, {"citations": [{"page": 2071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC#page=2"}, {"page": 2071, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC#page=2"}, {"page": 2073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC#page=4"}], "councilor_points": ["徐立信議員指出，幼兒園發生幼童頭部及面部受傷事故未及時通報教育局與通知家長，且事後仍繼續帶幼童至標示 5 歲至 12 歲使用的公園遊戲場遊玩。徐立信議員詢問該行為是否構成「消極不作為」之不當對待，要求教育局積極監督與處置。"], "response": "教育局局長表示，緊急案件規定應於 24 小時內通報，坦言該公園設施確實不適合幼兒使用，承諾於 1 週內處理並要求改善。教育局學前教育科科長補充說明，若幼兒有特殊狀況設有輔導方案，因先前未接獲該案通報，後續將進行處理。", "response_removed": false, "topic": "幼兒園幼童受傷事故通報與不當遊戲場使用"}, {"citations": [{"page": 3167, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549995123E3CA0147C2CAB74A80DEAD8FD60C0DEB76BEB1491C490F00C7A04EBCEA02D1DE3DCEB210BC#page=4"}, {"page": 3169, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549995123E3CA0147C2CAB74A80DEAD8FD60C0DEB76BEB1491C490F00C7A04EBCEA02D1DE3DCEB210BC#page=6"}], "councilor_points": ["徐立信議員指出，基層員警空勤務腰帶重約 2.8 公斤且掛載多項裝備，於追逐執勤時易造成身體負擔與脊椎傷害。徐立信議員建議市府採購具備輕量與反光安全功能的戰術背心，以保障員警執勤安全與健康。"], "response": "警察局局長說明，認同戰術背心具備輕巧與安全優勢，表示中央已統一採購約 5,600 件戰術背心，預計於同年 10 月配發予臺北市外勤員警使用。", "response_removed": false, "topic": "基層員警勤務裝備過重與戰術背心配發"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 3, "heading": "民政部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162#page=1", "transcript_pages": [1057, 1058, 1059, 1060, 1061, 1062, 1063, 1064, 1065, 1066, 1067, 1068], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162", "videos": [{"date": "2023-04-17", "group": 3}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 12, "heading": "財政建設部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC#page=7", "transcript_pages": [1732, 1733, 1734, 1735, 1736, 1737], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549D69B27018CCB8C2B1A783FDF0608F3F19380766CC688E547670A6A48C3B5AA9002D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 12}]}, {"dates": ["2023-05-02"], "dept": "教育", "doc_type": "部門質詢", "group": 6, "heading": "教育部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC#page=1", "transcript_pages": [2070, 2071, 2072, 2073, 2074, 2075, 2076], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B27AFB2503BFD2B177C617FF3C4303D737CC58261A7A3D3E2AB7D812C6F9F24C02D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 6}]}, {"dates": ["2023-05-09"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F0E2FE9639433EE0E4A21447E7507E4593A86FA0F2D95E7947CC1112AA866B2202D1DE3DCEB210BC#page=9", "transcript_pages": [2596, 2597, 2598, 2599, 2600, 2601], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F0E2FE9639433EE0E4A21447E7507E4593A86FA0F2D95E7947CC1112AA866B2202D1DE3DCEB210BC", "videos": [{"date": "2023-05-09", "group": 8}]}, {"dates": ["2023-05-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549995123E3CA0147C2CAB74A80DEAD8FD60C0DEB76BEB1491C490F00C7A04EBCEA02D1DE3DCEB210BC#page=1", "transcript_pages": [3164, 3165, 3166, 3167, 3168, 3169, 3170, 3171], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549995123E3CA0147C2CAB74A80DEAD8FD60C0DEB76BEB1491C490F00C7A04EBCEA02D1DE3DCEB210BC", "videos": [{"date": "2023-05-18", "group": 14}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC#page=1", "transcript_pages": [3769, 3770, 3771, 3772, 3773, 3774, 3775], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654909BB843E2B82F046A9D767C738F32E9AFD03DB5F7C94DB762F5C5F207E9FB12702D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 14}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654905F10926EAC0E85ADCA11C5C8FA52EFFF1D75E00EE7142A4A852238F00A7C162','2026-10-01T22:56:19Z');
INSERT INTO "fact" VALUES('summary:14-01:p741562d334','p741562d334','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:00:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4225, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=12"}, {"page": 4227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=14"}, {"page": 4227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=14"}, {"page": 4228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=15"}, {"page": 4228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=15"}, {"page": 4229, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=16"}, {"page": 4230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=17"}], "councilor_points": ["曾獻瑩議員指出臺北市市民 1 年被詐騙有 4 千多個案件、金額高達 8 億 2,500 萬元且有許多「黑數」，詢問警察局防詐政策中何者做得最好。曾獻瑩議員表示臺北市去年攔阻詐騙 1,100 件，落後臺南市的 2,500 件，而預算僅 100 萬元且其中 61 萬元用於購買禮券，建議提高預算、增加金融機構攔阻獎勵並公布績優銀行。曾獻瑩議員說明「打詐五法」修正後給予警察局處罰未即時下架詐騙廣告的權限，建議警察局主動搜報、建立下架 KPI，並請資訊局等跨局處運用科技協助預防詐騙。"], "response": "市長說明臺北市破獲率為六都第一，且阻詐與懲詐為重點，今年 1 至 4 月成功攔阻詐騙金額達 3 億 2,000 多萬元。市長承諾將預防詐欺經費翻倍提高，於今年下半年動用預備金執行，並會公布績優銀行、研擬獎勵與跨局處合作機制。警察局局長表示「證券投資信託及顧問法」修正後廣告採實名制，若未依限下架可開罰，資訊局局長與市長亦回應會由跨局處團隊共同努力並定期公布主動撤下廣告之數據。", "response_removed": false, "topic": "市政預防詐騙與預算資源配置"}, {"citations": [{"page": 4230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=17"}, {"page": 4232, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=19"}, {"page": 4233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=20"}, {"page": 4233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=20"}, {"page": 4234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=21"}, {"page": 4235, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=22"}, {"page": 4236, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=23"}], "councilor_points": ["曾獻瑩議員指出臺北市人口減少比率為亞洲首都最快，建議人口對策委員會要求各局處提出指標，並辦理「友善育兒企業認證」。曾獻瑩議員表示市政大樓幼兒園 107 至 109 學年度中籤率僅約 15% 至 21%，且社會住宅 6 成劃為 1 房設計無法滿足二胎家庭居住需求，建議增加房型比例配套。曾獻瑩議員建議參考日本經驗將「助婚」納入政策，並指出臺北市家庭教育預算平均每人僅 6.4 元，主張結合教育局加強婚前教育與親職教育。"], "response": "市長說明人口對策委員會於 6 月開會並每季召開，將召集各局處研擬目標，並同意於下半年研議推動友善育兒企業認證及調整社宅房型比例。市長表示市政大樓幼兒園規劃於 8 月將名額由 12 個增加至 36 個，並指示民政局參考國外做法評估「助婚」獎勵或補助，於下會期開議前提出初步研究報告。市長說明已親自主持府級家庭教育委員會，將研擬相關政策；教育局局長補充說明家庭教育經費除家扶中心編列 1,500 萬元外，中央教育部亦補助 1,200 多萬元。", "response_removed": false, "topic": "少子化因應與助婚育兒及家庭教育推動"}, {"citations": [{"page": 3193, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=16"}, {"page": 3194, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=17"}, {"page": 3196, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=19"}], "councilor_points": ["曾獻瑩議員指出臺北市市民 1 年被詐騙總金額達 8 億 2,500 萬元且共有四千多個案件，但警察局 1 年預防詐騙預算僅 100 萬元，其中 61 萬元用於購買禮券，第三季反詐宣導執行金額甚至是零。曾獻瑩議員表示臺北市去年攔阻詐騙一千一百多件，低於臺南市的 2,500 件，建議警察局將資源往前挪移至預防詐騙，並加強與金融機構合作與鼓勵措施。曾獻瑩議員要求警察局於 1 個月內研擬並提供與金融機構合作之具體執行方案。"], "response": "警察局局長表示治安工作為預防與偵查並重，去年「打詐」績效為六都第一，並承諾會全力推動與金融機構及有 ATM 營業場所之聯繫。警察局局長說明預防詐騙預算確實不夠，預計明年增加編列 50 萬元至 150 萬元，並答應於 1 個月內提供與金融機構合作之具體計畫方案。衛生局局長表示前端預防可避免後續損失，預防詐騙預算越多越好。", "response_removed": false, "topic": "警政預防詐騙資源與金融機構合作機制"}, {"citations": [{"page": 3782, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=3"}, {"page": 3783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=4"}, {"page": 3781, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=2"}], "councilor_points": ["曾獻瑩議員指出民眾因鄰近深開挖工地施工而感到擔憂，且打 1999 反映損鄰後竟僅被要求找工地主任說明，質疑該處理流程。曾獻瑩議員建議都市發展局建築管理工程處要求建商於施工前召開施工說明會，向周邊住戶說明地質資料、工期與工法。曾獻瑩議員要求市府建立明確溝通管道與損鄰處理作業流程，讓周邊居民能充分掌握施工狀況。"], "response": "建築管理工程處處長說明未來針對符合深開挖規模之基地，將要求廠商及委託外審機構於辦理施工計畫外審時，邀集周邊住戶參與說明會。建築管理工程處處長表示會研議改進損鄰回應流程，預計製作 A4 紙張大小說明事項，於實施現況鑑定時直接交付住戶，告知損鄰受理專線與處理 SOP。建築管理工程處處長同意建商與鄰舍溝通具有加分效果，並表示後續會研議處理方式。", "response_removed": false, "topic": "深開挖建築工地施工溝通與損鄰處理作業"}, {"citations": [{"page": 3783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=4"}, {"page": 3783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=4"}, {"page": 3784, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=5"}, {"page": 3785, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=6"}], "councilor_points": ["曾獻瑩議員指出住二山限區都更針對海砂屋給予容積率最高 1.8 倍獎勵，但耐震能力不足 0.35 以下者目前僅有 1.5 倍且無額外獎勵，詢問是否能一併提高。曾獻瑩議員表示住二山限區高度限制為 21 公尺，質疑建築高度與建蔽率限制可能導致海砂屋都更無法實施高額容積獎勵。曾獻瑩議員建議市府進行試算與研議，避免因高度限制使獎勵無法落實，以利居住安全有風險的居民順利更新房屋。"], "response": "都市發展局局長說明海砂屋因具立即危險故給予 30% 容積獎勵，耐震力不足 0.35 的部分正於第 3 季協助都更優惠獎勵措施中研議處理方式。都市更新處處長與都市發展局局長說明住二山限區高度限制為 21 公尺，建蔽率放寬至 60%，部分原量體較高的社區可能無法完全實現獎勵。都市更新處處長與都市發展局局長表示原則上希望透過都市計畫專案調整高度的方式處理，並強調已想好對策可以解決該問題。", "response_removed": false, "topic": "住二山限區都市更新容積獎勵與高度限制"}, {"citations": [{"page": 2710, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=9"}, {"page": 2711, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=10"}, {"page": 2712, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=11"}], "councilor_points": ["曾獻瑩議員指出 12 家公車業者在去年超時評鑑中有 11 家得到 0 分，顯示駕駛員超時工作情況普遍且嚴重。曾獻瑩議員說明公車駕駛應有員額為 5,500 人、去年應聘 5,287 人，但實際僅有 3,779 人，人力缺口高達 3 成致使駕駛必須加班。曾獻瑩議員要求交通局督促業者改善駕駛員勞動條件與薪資結構，並於 1 至 2 個月內提出具體解決方案與報告。"], "response": "公共運輸處處長說明法規規定駕駛每日握方向盤時間上限為 10 小時。交通局局長表示超時問題涉及公共安全，主因為駕駛普遍缺員，目前正透過科技設備降低工作負荷及減少不必要路線。交通局局長說明根本原因在於薪資結構，承諾會將問題放在心上，並與業者座談研議改善待遇與控管工時，於 1 至 2 個月內提出方向報告。", "response_removed": false, "topic": "公車駕駛超時工作與人力缺口改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=12", "transcript_pages": [4225, 4226, 4227, 4228, 4229, 4230, 4231, 4232, 4233, 4234, 4235, 4236], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 5}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 11, "heading": "民政部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=7", "transcript_pages": [1238, 1239, 1240, 1241, 1242, 1243, 1244, 1245, 1246, 1247], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD