-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=16", "transcript_pages": [3193, 3194, 3195, 3196, 3197], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 15}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 15, "heading": "工務部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=1", "transcript_pages": [3780, 3781, 3782, 3783, 3784, 3785, 3786, 3787, 3788], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC','2026-10-01T23:00:21Z');
INSERT INTO "fact" VALUES('summary:14-01:p47f1fe2e84','p47f1fe2e84','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:06:03Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=7"}, {"page": 3144, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=11"}, {"page": 3144, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=11"}, {"page": 3145, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=12"}, {"page": 3135, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=2"}, {"page": 3137, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=4"}, {"page": 3138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=5"}, {"page": 3141, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=8"}, {"page": 3134, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=1"}, {"page": 3136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=3"}, {"page": 3136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=3"}, {"page": 3139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=6"}], "councilor_points": ["李明賢議員指出臺北市每年行人發生交通事故傷亡平均約2,050人，且有六成發生在路口。李明賢議員質疑忠孝東路四段連續4年蟬聯車輛不禮讓行人最危險路段，案件數逐年增加，要求警察局納入科技執法並加強取締。李明賢議員詢問行人早開與專用時相的具體評估標準，並指出忠孝復興路口因車流回堵取消試辦全時相，要求交通管制工程處落實人本交通。"], "response": "警察局交通警察大隊大隊長表示已訂定防制計畫，針對車不讓人加強專案執法，並承諾將忠孝東路四段納入科技執法強化。交通管制工程處副總工程司說明全市已劃設393處行人早開及229處行人專用時相，預計年底前優先於學校與醫院周邊擴大至900處早開號誌，並以路段服務水準D級以上及尖峰每小時行人量達300人作為評估全時相的標準。", "response_removed": false, "topic": "行人路口通行安全與不禮讓行人執法"}, {"citations": [{"page": 4372, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=2"}, {"page": 4373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=3"}, {"page": 4374, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=4"}, {"page": 4375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=5"}, {"page": 4375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=5"}, {"page": 4376, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=6"}, {"page": 4378, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=8"}, {"page": 4373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=3"}, {"page": 4377, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=7"}], "councilor_points": ["李明賢議員指出南港路2段230公尺人行道有55座障礙物，星雲街68巷450公尺有63座障礙物，要求市府加速普查、設立申訴專線，並一邊普查一邊修補。李明賢議員指出內湖新明路321巷標線型人行道120公尺有15座障礙物，全北市1,987處標線型人行道升級為實體人行道數量為零，要求112年至少完成5條改善並提升至府級列管。"], "response": "市長表示已成立府級專案小組列管追蹤，會增加預算採邊普查邊修補模式，並承諾112年最少完成5條標線型人行道改為實體人行道。工務局局長表示南港路2段與星雲街68巷會以人本方式專案規劃改善。新建工程處處長說明112年針對人行道淨寬展開普查，將於7月底前清除南港路與星雲街明顯障礙物，並已發包於112年施作5條標線型人行道改為實體人行道。交通局局長與交通管制工程處處長說明會加速清查1,987處標線型人行道，並配合人本主義原則優先保障行人路寬。", "response_removed": false, "topic": "實體與標線型人行道無障礙改善"}, {"citations": [{"page": 2340, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=11"}, {"page": 2342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=13"}, {"page": 2342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=13"}, {"page": 2343, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=14"}, {"page": 2344, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=15"}, {"page": 2345, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=16"}, {"page": 2346, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=17"}], "councilor_points": ["李明賢議員指出少子化下臺北市國小學生數8年增加1萬人，國中卻減少415班，且額滿學校如敦化國小8年減27班，詢問教育局資源分配是否合理。李明賢議員關心減班導致之超額教師處置，要求教育局確保遴選機制公平，並主動提供心理輔導與關懷。李明賢議員指出電子菸侵入校園問題嚴重，國小查獲案例從108年1例增加至111年6例，要求教育局訂定目標管理調降數據。"], "response": "教育局局長說明國小人數增加係因生肖年及跨區就讀，額滿學校減班主因是少子化下新生班較畢業班少之自然減班，敦化國小則受校舍工程施工影響。教育局局長表示減班採緩降方式進行，超額教師有遴選與3年不重複釋出之保障機制，教師研習中心亦增加諮商點提供關懷。教育局局長表示學校全面禁菸，會加強宣導、親子講座及識菸輔導，並承諾努力讓國小電子菸案例下降。", "response_removed": false, "topic": "少子化下國中小學額滿減班與超額教師處置"}, {"citations": [{"page": 1371, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=8"}, {"page": 1372, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=9"}, {"page": 1373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=10"}, {"page": 1374, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=11"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=12"}, {"page": 1376, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=13"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=12"}, {"page": 1372, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=9"}], "councilor_points": ["李明賢議員詢問社會局與交通局能否協調業者引進適合身障者使用之共享運具，並關心機車改裝補助與一體成型車輛之路徑。李明賢議員指出有身障者自備改裝重機報名臺北市4家機車駕訓班全遭拒絕，要求身障小組與交通局主動瞭解個案並溝通。李明賢議員指出全臺北市有106處公車候車站有樹木等障礙物阻擋身障者通行，要求市府列管並主動改善。"], "response": "社會局局長說明身障者類別多元且考量安全，目前共享運具因個別需求及業者營利考量較難布點，建議以個別購買改裝補助為主；另承諾會與交通局合力瞭解4家駕訓班拒絕報名原因，並在無障礙推動小組列管處理公車站障礙物。交通局運輸管理科科長說明法規無限制，但共享業者與製造商考量市場未成熟暫無引進規劃，重機考照部分會再向監理所瞭解細節。", "response_removed": false, "topic": "身心障礙者交通運具與無障礙通行權益"}, {"citations": [{"page": 1868, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=31"}, {"page": 1870, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=33"}, {"page": 1872, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=35"}, {"page": 1872, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=35"}, {"page": 1873, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=36"}, {"page": 1874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=37"}], "councilor_points": ["李明賢議員詢問動物保護處處長是否連署民間推動之茶茶法案，並指出臺北市動檢員僅12人，需負擔每年1萬多件救援，建議支持設立動保警察。李明賢議員指出新建動物之家預定115年完工，目前中繼站收容873隻犬貓、超收213隻，要求動保處改善環境並與民間團體合作推動認領養。"], "response": "動物保護處處長表示會上網連署茶茶法案，並說明中央正在研議設置動保警察。動物保護處處長說明新建動物之家預計115年7月底竣工，中繼站超收問題會調整硬體籠舍、利用原址空間，並與民間團體合作作為送養分站，亦有提供10大項嫁妝及線上領養等措施。", "response_removed": false, "topic": "動物保護法案連署與動物之家超收改善"}, {"citations": [{"page": 2477, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=21"}, {"page": 2478, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=22"}, {"page": 2478, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=22"}, {"page": 2479, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=23"}, {"page": 2479, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=23"}], "councilor_points": ["李明賢議員舉安康路、內湖路一段及舊宗路一段開放機車騎內線後事故下降之數據，建議交通局因地制宜，優先開放公車靠站多及違停多的道路。李明賢議員指出忠孝西路開放機車夜間通行4個月以來開放時段零機車事故，要求交通局提前開放時段或於假日開放。"], "response": "交通局局長表示支持在公車及路邊停車頻繁路段讓機車移至內側以減少右側碰撞。交通局局長說明預計9月會有模擬數據，正朝提前開放時段、離峰或假日開放方向進行分析與評估。", "response_removed": false, "topic": "機車內側車道開放與忠孝西路通行時段"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=1", "transcript_pages": [4371, 4372, 4373, 4374, 4375, 4376, 4377, 4378, 4379, 4380, 4381, 4382, 4383, 4384], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC", "videos": [{"date": "2023-06-05", "group": 9}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=7", "transcript_pages": [1370, 1371, 1372, 1373, 1374, 1375, 1376, 1377, 1378, 1379, 1380, 1381, 1382], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 16}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=31", "transcript_pages": [1868, 1869, 1870, 1871, 1872, 1873, 1874], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 17}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 18, "heading": "教育部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=10", "transcript_pages": [2339, 2340, 2341, 2342, 2343, 2344, 2345, 2346, 2347], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 18}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 3, "heading": "交通部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=21", "transcript_pages": [2477, 2478, 2479, 2480], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 3}]}, {"dates": ["2023-05-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=1", "transcript_pages": [3134, 3135, 3136, 3137, 3138, 3139, 3140, 3141, 3142, 3143, 3144, 3145, 3146], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC", "videos": [{"date": "2023-05-18", "group": 13}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC','2026-10-01T23:06:03Z');
INSERT INTO "fact" VALUES('summary:14-01:pc524c2d6ef','pc524c2d6ef','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:08:07Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=21"}, {"page": 1859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=22"}, {"page": 1859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=22"}, {"page": 1860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=23"}, {"page": 1861, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=24"}], "councilor_points": ["李柏毅議員指出成功市場與環南市場在改建過程中多次辦理契約與設計變更，其中環南市場契約變更6次、設計變更15次，增加預算已突破10億元。李柏毅議員表示環南市場有4次、成功市場有3次係為了符合GHP（食品良好衛生規範準則）而變更契約，質疑市府未能一次到位，要求市府訂出底線並加強與攤商溝通，避免預算無限追加。李柏毅議員建議未來所有公有市場興建與改建計畫，均應尋求包含GHP專業團隊的廠商參與投標。"], "response": "市場處處長說明契約變更主因包含攤商使用需求改變，並表示環南市場第6次契約變更應為最後一次，且成功市場未來針對GHP部分不會再變更契約。市場處處長表示會記取教訓，未來北投市場等公有市場興改建計畫於勞務案發包時，均會要求建築團隊一併搭配GHP團隊合作。", "response_removed": false, "topic": "公有市場改建與GHP規範契約變更"}, {"citations": [{"page": 4406, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=36"}, {"page": 4409, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=39"}, {"page": 4407, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=37"}, {"page": 4408, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=38"}, {"page": 4406, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=36"}], "councilor_points": ["李柏毅議員引述2023年遠見雜誌民調與研考會調查數據，指出市長滿意度在六都最低且比前市長低了20%，質疑市府團隊雖認真做事但缺乏能讓民眾記憶的亮點。李柏毅議員以好市多A肝莓果事件為例，指出外縣市皆直接裁罰或強制下架，臺北市卻因考量法律細節與法規適用問題而僅採現場輔導，未及時為市民權益開罰發聲，形容市長「太過冷靜，太過理性」。李柏毅議員要求市府展現敢擔當的態度，積極捍衛市民食安權益，並加強市政宣傳以創造施政亮點。"], "response": "市長說明市府團隊已積極解決大巨蛋、捷運東環段及人口提升等前任市府無法克服的困難，並表示會持續加強宣傳與做出讓市民有感的改變。市長與法務局局長說明好市多事件第一時間已要求違規商品下架，並三次約談業者要求更正和解條款以保障市民求償權，後續會檢討並展現開罰態度以捍衛食安。", "response_removed": false, "topic": "市長施政滿意度與好市多A肝莓果開罰態度"}, {"citations": [{"page": 2457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=1"}, {"page": 2459, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=3"}, {"page": 2459, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=3"}, {"page": 2458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=2"}, {"page": 2461, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=5"}], "councilor_points": ["李柏毅議員指出市長於選前提出深蹲20次免費搭公車的概念，並舉羅馬尼亞克盧日納波卡推行深蹲換公車票及相關專家研究為例，說明該政策具可行性且有助於促進市民健康與公共運輸搭乘率。李柏毅議員詢問市長就任五個多月來的評估進度，並質疑將該案交由體育局主政且需由交通局配合貼補之分工架構較為被動，恐拖延實施時程。李柏毅議員要求公共運輸處於本會期完成深蹲換乘公車的可行性評估，並要求交通局、捷運公司與公共運輸處於下會期提出結合交通設施鼓勵市民運動的初步方案。"], "response": "交通局局長、公共運輸處處長與臺北大眾捷運股份有限公司總經理皆表態支持運動與公共運輸結合的方向。交通局局長說明府內目前由體育局主政規劃U-Sport方案，交通局負責配合提供公共運輸優惠，承諾會再與體育局研究並結合相關局處落實。臺北大眾捷運股份有限公司總經理表示會傾向在既有捷運站體設計及安全無虞前提下，鼓勵民眾多走樓梯以達節能減碳與運動效果。", "response_removed": false, "topic": "深蹲換乘公車與運動結合交通政策"}, {"citations": [{"page": 4420, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=50"}, {"page": 4421, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=51"}, {"page": 4422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=52"}, {"page": 4421, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=51"}], "councilor_points": ["李柏毅議員提出數據指出臺北市小客車約有74萬輛、純電動車有9,000多輛，但公有學校及場所充電樁僅525支（占汽車格位0.47%），計程車休息站402格車位僅10支充電樁（占0.25%），且全數為慢充而無快充。李柏毅議員指出市府與市議會地下停車場五、六百個車位中各僅有1支慢充，並反映計程車服務站設置慢充不符合司機休息時間與實用需求，且相關預算包裹於維護費中未向交通委員會報告。李柏毅議員建議市府跳脫閉門造車，應主動向交通委員會報告預算，並考量發包尋求民間專業團隊合作（如BOT模式）以加速建置快充與充電場域。"], "response": "秘書長說明市府大樓規劃於明年啟動延壽計畫更新電力與消防系統，預計115年將於B1設置2座快充站及30座一般充電站。停車管理工程處處長說明目前平面停車場已設置5座快充，並表示依交通部管理辦法未來充電將收取電費。市長坦言充電樁建置速度過慢且低使用率不符合設置目的，承諾會加速辦理、提前規劃期程，並將提高快充比例、向交通委員會報告預算及與民間團隊合作。", "response_removed": false, "topic": "公有停車場與機關電動車充電樁建置"}, {"citations": [{"page": 1863, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=26"}, {"page": 1864, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=27"}, {"page": 1865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=28"}, {"page": 1866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=29"}, {"page": 1865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=28"}, {"page": 1867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=30"}], "councilor_points": ["李柏毅議員反映文山區新榮公園有三級保育類動物台灣藍鵲築巢並攻擊民眾，已造成10多位里民受傷就醫。李柏毅議員質疑動保處僅貼告示要求民眾不要靠近，未依《野生動物保育法》中危及公共安全之規定進行捕捉移置，屬於「張貼告示給鳥看」的作法。李柏毅議員要求動保處不得再拖延研議，必須在一個星期內將台灣藍鵲移置至安全的環境或動物園，並回報處置結果。"], "response": "動物保護處處長說明台灣藍鵲為保育類動物，貼告示係提醒民眾注意安全，並已協調公園路燈工程管理處針對附近樹木進行修枝以改變其棲息環境。動物保護處處長表示會再前往現場會勘，並承諾於一個星期內回覆處置狀況與結果。", "response_removed": false, "topic": "新榮公園台灣藍鵲傷人與防護處置"}, {"citations": [{"page": 3147, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=14"}, {"page": 3148, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=15"}, {"page": 3149, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=16"}], "councilor_points": ["李柏毅議員指出臺北市食安官無額外加給、無銓敘職務與法定權責，且15個月僅簽決行26件公文，質疑食安官無法直接指揮跨局處或行使考績評鑑權，恐淪為「黑官」或「紙老虎」。李柏毅議員認為由衛生局副局長兼任食安官會造成職責重疊與錯亂，要求若無法釐清獨立權責則不如廢除。李柏毅議員要求市府建請中央修法賦予食安官銓敘職務與法定權責，並修正食安自治條例以賦予食安官督導、調度、指揮及考績評鑑權力，於總質詢前提出報告。"], "response": "衛生局局長表示體卹兼任食安官之辛勞，並認為食安官有跨局處協調之需要，業務並非疊床架屋。衛生局副局長說明食安官係由市長指派並獲授權，可透過跨局處整合運作與代表與會，目前雖無考績評鑑權，但能藉由兼任掌握局處業務運作。衛生局局長承諾會針對相關建議進行討論，並於總質詢前向議員報告市府的想法與規劃。", "response_removed": false, "topic": "臺北市食安官法定權責與職務定位"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=35", "transcript_pages": [4405, 4406, 4407, 4408, 4409, 4416, 4417, 4418, 4419, 4420, 4421, 4422, 4423, 4424, 4425, 4426], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC", "videos": [{"date": "2023-06-05", "group": 9}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 16}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=21", "transcript_pages": [1858, 1859, 1860, 1861, 1862, 1863, 1864, 1865, 1866, 1867, 1868], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 17}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 18, "heading": "教育部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=25", "transcript_pages": [2354, 2355, 2356, 2357], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 18}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 3, "heading": "交通部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=1", "transcript_pages": [2457, 2458, 2459, 2460, 2461], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 3}]}, {"dates": ["2023-05-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=13", "transcript_pages": [3146, 3147, 3148, 3149, 3150, 3151, 3152, 3153, 3154, 3155, 3156, 3157], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC", "videos": [{"date": "2023-05-18", "group": 13}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=1", "transcript_pages": [3515, 3516, 3517, 3518], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC','2026-10-01T23:08:07Z');
INSERT INTO "fact" VALUES('summary:14-01:p072095ef7a','p072095ef7a','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:10:10Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=8"}, {"page": 2241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=8"}, {"page": 2242, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=9"}, {"page": 2244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=11"}], "councilor_points": ["李芳儒議員要求建置完整原住民族教育體制，成立原住民族教育審議委員會、健全原住民族教育資源中心，並建議將委員會召集人提升由市長擔任。李芳儒議員指出北市族語師資嚴重高齡化，61歲以上教師占62%，且高級認證取得困難，建議特聘通過中高級認證並取得20學分者先進入國小授課，給予3年取得高級證照之緩衝期。李芳儒議員建請臺北市立大學成立原住民專班，以培育專門學科與語言文化人才，健全原住民族師資體系。"], "response": "教育局局長說明教育資源中心可行，但由教審會調度資源中心老師在體制運作上較困難，且召集人層級調整需再研議，並表示市府責無旁貸推動全民原教，針對放寬中高級認證授課等建議將研議辦理。臺北市立大學校長說明學校設有語言相關專班，將研議原住民專班適合之專長系所，並與教育局討論所需資源。", "response_removed": false, "topic": "原住民族教育體制建置與族語師資培育"}, {"citations": [{"page": 3213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=16"}, {"page": 3214, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=17"}], "councilor_points": ["李芳儒議員指出「臺北市原住民衛生醫療自治條例」已18年未修正，鑑於原住民死亡率高於一般市民，且18年來醫療物價指數增加20%，建議全面檢視修正該自治條例。李芳儒議員訴求放寬老人收容安置補助地點至外縣市安養機構，並依物價漲幅提高醫療補助3萬元上限。李芳儒議員要求衛生局協助原住民族委員會增加醫療保健服務項目，涵蓋精神診療與非族群因素衍生之疾病診療。"], "response": "衛生局局長表示會跨局處與原住民族委員會合作討論並進行檢視。", "response_removed": false, "topic": "原住民衛生醫療自治條例檢討與健康照顧政策"}, {"citations": [{"page": 1758, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=8"}, {"page": 1759, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=9"}], "councilor_points": ["李芳儒議員肯定市場處修改規則將原住民與身心障礙者列為優先分配對象（改建市場3%以內），但質疑已改建市場排除範圍過大，導致多數既有市場難以適用。李芳儒議員建議針對既有市場設立專設攤位，以承租2年、得續租2年共4年為主進行輪替，照顧弱勢族群與原住民之就業權利。李芳儒議員要求市場處加強管理，建立淘汰不適攤商與查處轉租之機制，以活絡市場競爭力。"], "response": "市場處處長說明新建市場完全適用新規則，既有改建市場須俟空攤釋出始能提供原住民申請。市場處處長表示專設攤位之建議立意良善，將研究相關法規適用並找市場攤商開會討論，並承諾落實例行管理與淘汰機制。", "response_removed": false, "topic": "公有零售市場攤位優先分配與專設攤位設置"}, {"citations": [{"page": 3856, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=22"}, {"page": 3858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=24"}, {"page": 3860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=26"}], "councilor_points": ["李芳儒議員指出現行社會住宅一房型比例約占65%過高，無法滿足家庭居住需求甚至拆散家庭，建議調降一房型比例至30%或35%，並提高二房型與三房型比例。李芳儒議員反對加籤政策，要求落實競選政見中保留20%社會住宅給生育第二胎家庭優先入住之政策。李芳儒議員要求都發局與住都中心簡化聯繫流程，縮短社宅報修等待時間，並針對老舊國宅全面檢修漏水、門鈴及照明設備。"], "response": "都市發展局局長說明因新建戶數有限，保留20%會排擠其他族群，短期看加籤可提高中籤率2倍，並確認社宅住戶人口增加時可申請更換房型。都市發展局局長承諾會檢討聯繫流程以儘速維修社宅，並會重新檢修國宅。", "response_removed": false, "topic": "社會住宅房型配比與修繕管理"}, {"citations": [{"page": 1752, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=2"}, {"page": 1753, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=3"}, {"page": 1754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=4"}, {"page": 1755, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=5"}], "councilor_points": ["李芳儒議員質疑臺北自來水事業處及工程總隊總人數1,062人，依「臺北市促進原住民就業自治條例」每滿50人應進用1人計算應進用20人，現僅進用12名原住民員工，要求足額進用。李芳儒議員建議自來水事業處多進用具備技術或碩博士學歷之原住民，擔任6至13職等之聘用人員。"], "response": "臺北自來水事業處處長說明依規定原住民進用基準以勞保身分378人計算應進用7人，目前實際進用勞保11人及職員1人共12人，已符合法定進用標準。臺北自來水事業處處長表示未來會多進用原住民技術人員。", "response_removed": false, "topic": "促進原住民就業自治條例與自來水處進用比例"}, {"citations": [{"page": 1142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=14"}, {"page": 1142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=14"}, {"page": 1143, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=15"}, {"page": 1143, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=15"}], "councilor_points": ["李芳儒議員建議將大稻埕碼頭原住民攤位租期由現行1年1約調整為總計可待3年（採1年1約，營運成效佳者得延長2年），以利攤商穩定經營。李芳儒議員要求原住民族委員會善用太原廳舍提供原住民社團設址，發揮推動市政與宣導福利之效益。李芳儒議員要求規劃活化娜魯灣商場，恢復商鋪營運或結合長青學苑、部落大學、沈浸式幼兒園，並建議未來部落大學與長青學苑應選在交通便利處。"], "response": "原住民族事務委員會主任委員表示大稻埕攤位如廠商績效良好且願意續租，可延長1年並至多延長二次。原住民族事務委員會主任委員說明太原廳舍今年已租給廠商，將於契約終止前研議未來營運方向；娜魯灣商場目前正進行耐震補強，會將議員建議納入未來空間規劃。", "response_removed": false, "topic": "原住民場館設施活化與攤位租期管理"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=11", "transcript_pages": [1139, 1140, 1141, 1142, 1143, 1144], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 7}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=1", "transcript_pages": [1751, 1752, 1753, 1754, 1755, 1756, 1757, 1758, 1759], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 14}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=6", "transcript_pages": [2239, 2240, 2241, 2242, 2243, 2244], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 14}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 9}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 16, "heading": "警政衛生部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=15", "transcript_pages": [3212, 3213, 3214, 3215, 3216], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 16}]}, {"dates": ["2023-05-26"], "dept": "工務", "doc_type": "部門質詢", "group": 18, "heading": "工務部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=21", "transcript_pages": [3855, 3856, 3857, 3858, 3859, 3860], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC", "videos": [{"date": "2023-05-26", "group": 18}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162','2026-10-01T23:10:10Z');
INSERT INTO "fact" VALUES('summary:14-01:pcc848fb570','pcc848fb570','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:14:43Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2638, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=5"}, {"page": 2639, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=6"}, {"page": 2640, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=7"}, {"page": 2638, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=5"}, {"page": 2637, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=4"}], "councilor_points": ["林亮君議員指出臺中捷運發生吊臂掉落事故後，捷運文湖線現行站務人員發現異物需通報行控中心之程序可能延誤緊急處置，建議應授權現場人員採取阻擋車門或切斷電力等即時措施，並建議研議於高架路段設置遠距離高空墜落物 AI 監測系統。（引文：「針對這個部分，如果現在臺北捷運文湖線的站務人員發現異物之後，能不能阻止發車？你們有沒有相關的 SOP？需要幾秒來做這件事情？」、「同樣地，像臺北捷運文湖線這樣高架段的部分，其實也應該要有這樣的設置……幫忙北捷排除障礙、或立刻通報行控中心」） 林亮君議員表示除了建築工程之外，路權借用如附掛招牌或牆面清洗等高空作業難以事前掌握，要求臺北大眾捷運股份有限公司檢討緊急營運操作流程並提送報告。（引文：「如果是附掛招牌、懸掛或大樓牆面清洗，這你們就……沒辦法掌握，對不對？」、「針對緊急營運操作檢討……要麻煩總經理在市政總質詢之前，針對這整個部分提供 1 份報告給本質詢組，可以嗎？」）"], "response": "臺北大眾捷運股份有限公司總經理說明已發布最新公告授權現場站務人員透過阻擋車門、月台門、切斷電力或拉動列車拉把等4種方式緊急處置，且行控中心接獲訊息後亦會執行全線斷電以控管風險。（引文：「今天已經發出公告，類似這樣的事件，我們就授權現場站務人員，透過阻擋車門、月台門，或做電力切斷處置，或列車裡的拉把停止出發，使用這 4 種方式來處置這種情境」、「行控中心現在最新的程序也是簡化，一旦有這樣的訊息，我們就會做全線的斷電」） 臺北大眾捷運股份有限公司總經理表示將積極了解並蒐集遠距離監測技術以評估可行性，並承諾於總質詢前提交處置檢討與技術盤點報告。（引文：「我們會積極了解應用的可能性，同時也會廣泛蒐集一些可以偵測距離的技術，如果可行的話，我們會建置。」、「針對程序已經修改的，我們把修改的狀況做一個報告。」） 交通管制工程處處長說明高架道路設置 AI 攝影機係利用影像辨識追蹤車輛異常停滯，並於產生警報時調閱螢幕聯絡警察局派員排除狀況。（引文：「我們在高架道路上設置的是攝影機，利用影像辨識的方式追蹤車輛，如果發現車輛有停下來的時候……就會在監控中心產生 alarm……請交通警察大隊派員到現場排除」）", "response_removed": false, "topic": "捷運文湖線異物入侵應變與防護機制"}, {"citations": [{"page": 1876, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC#page=2"}, {"page": 1878, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC#page=4"}, {"page": 1876, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC#page=2"}, {"page": 1877, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC#page=3"}], "councilor_points": ["林亮君議員指出公有零售市場面臨攤位品項分布不均及離峰時間許多攤位未營業等狀況，導致競爭力不如超市，詢問市場處對於攤位活化與多元管理的作為。（引文：「市場明明下午傍晚四點才關，但是這整間市場有在營業的攤販很少……失去原本零售市場攤販很多元還可以比價的優點」、「最重要的還是確保市場攤販類型的多元性……請處長在總質詢前初步回復這部分，以及市場攤販多元化具體管理方式之初步規劃。」） 林亮君議員建議市場處應積極由上而下盤點各市場周邊超市與商場的競爭條件，並針對離峰時間思考黃昏市場或多元時間利用等活化方案。（引文：「早市是一個方向，空攤在下午接近傍晚時候有另外的利用方式，以鼓勵活化這些攤位」、「盤點每一市場和其周邊店家的競爭力……由上而下積極了解和投入資源。」）"], "response": "市場處處長說明市場營運以建築安全及食品安全為優先，並釐清無人承租之「法定空攤」與有繳租但現場未營業攤位之差異。（引文：「最重要的還是安全二個字。」、「對於政府而言，空攤是有一個攤位在那沒有人承租，根本收不到錢，沒有租金可以收，在市場處定位成空攤；到現場看空攤數不是這樣……其實這在廣義上可以認定另一種空攤。」） 市場處處長表示曾思考日間販售生鮮、夜間與其他攤商合作改為餐飲之聯合經營模式，並說明市集精進計畫係由點擴及面提升環境與攤商素質，承諾於總質詢前初步回復管理規劃。（引文：「白天一樣賣蔬菜、水果、生鮮魚肉，到晚上的時候可以和其他攤商達成默契，將座位收好再承租，再從事晚上的使用，像這是另類活化市場的思考方式」、「市集精進計畫分為三大面向……希望以這樣一個方式，將攤商的素質及整體環境提升」）", "response_removed": false, "topic": "公有零售市場空攤管理與活化策略"}, {"citations": [{"page": 1046, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162#page=4"}, {"page": 1047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162#page=5"}, {"page": 1047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162#page=5"}, {"page": 1045, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162#page=3"}], "councilor_points": ["林亮君議員指出人口推估報告顯示臺北市在幼兒達學齡階段（0至6歲及31至37歲）遷出比例特別高，單靠提高生育獎勵金無法解決人口流失問題且佔用民政局過半預算，質疑政策效益。（引文：「零到 6 歲，大概是 6 歲的這個區間，以及 31 歲到 36 歲、37 歲，這兩個區間人口遷出的比例特別高。」、「單純以加碼的方式，提升生育奬勵金，本席認為這是非常冒進的做法」） 林亮君議員表示生育獎勵金屬於重要給付行政，要求民政局應與法務局研議將「臺北市生育獎勵金發放辦法」提升為自治條例送議會審議，以受議會監督。（引文：「未來的生育奬勵金高達 9 億多元，在這種狀況下，市政府是否應該將這麼重要的給付行政，以自治條例的方式送議會審議？」、「請民政局回去之後和法務局研議，將臺北市生育獎勵金發放辦法落實為自治條例……1 個月內給本席一個初步的回應？」）"], "response": "民政局局長說明臺北市提高第一胎生育獎勵金至 4 萬元，並搭配戶籍居住滿 10 個月與居住、育兒政策以留住人口，會觀察申請數據並檢討設籍規定。（引文：「只要設籍在北北基滿 10 個月，申請時戶籍設籍在臺北市，生第一胎就可以領 4 萬元獎勵金，這樣就可以儘量留住這些人口。」、「我們先觀察 2 個月時間……如果嚴重的話，就要從設籍的規定，尋求改變做法。」） 民政局人口政策科科長表示市府即將成立人口對策委員會，針對人口問題進行全盤瞭解。（引文：「市政府馬上要成立人口對策委員會，針對議員關心的問題，我們會立即做更詳細、全盤的瞭解。」） 法務局局長說明給付行政若涉及公共利益及重大事項有層級化法律保留之必要，將與民政局研討評估變更為條例之可行性；民政局局長承諾於1個月內研議並給予初步回應。（引文：「給付行政如果涉及公共利益及重大事項的話，會有法律保留的必要。所以這個問題如果有需要的話，法務局會和民政局來研討」、「民政局會和法務局來檢討。」）", "response_removed": false, "topic": "生育獎勵金政策與人口自治條例"}, {"citations": [{"page": 3551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549620CA27A3F29B54462B74DFE80EC498C0BB2A6A10A18EC03AE4CD9AF0450F54602D1DE3DCEB210BC#page=10"}, {"page": 3549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549620CA27A3F29B54462B74DFE80EC498C0BB2A6A10A18EC03AE4CD9AF0450F54602D1DE3DCEB210BC#page=8"}, {"page": 3550, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549620CA27A3F29B54462B74DFE80EC498C0BB2A6A10A18EC03AE4CD9AF0450F54602D1DE3DCEB210BC#page=9"}], "councilor_points": ["林亮君議員指出「臺北市公園管理自治條例」修正草案將動物攻擊性之認定擴及農業委員會公告之外的所有動物，恐有法明確性不足及包山包海之問題，要求市府具體定義「攻擊性」與「適當防護措施」。（引文：「修正說明中沒有辦法釐清哪種動物是具攻擊性或是不具攻擊性，在不同的場域規定是否有所不同。」、「請具體定義何謂『動物攻擊性之有無』？……再來是何謂『適當防護措施』？」） 林亮君議員指出公園處稽查人力不足致使實際裁罰件數極少，建議除了裁罰與檢討執法人力外，應與動物保護處合作辦理寵物行為訓練課程與飼主教育講習。（引文：「1 月至 4 月只勸導 7 件，裁罰 0件。」、「除了裁罰以外，也應該輔導飼主跟犬隻參加相關行為課程的講習」）"], "response": "公園路燈工程管理處處長與青年公園管理所主任說明具攻擊性動物目前以農業委員會公告為主，修法說明係預留未來公園型態改變時報請核准公告之彈性，防護措施指繩鍊或箱體。（引文：「目前具有攻擊性的動物是依照農業委員會公告的危險犬隻。」、「修正說明中，『不包括』的意思是因為公園有很多種樣態……或許有個公告的機會，但是還是要上簽至市長核准後才行公告。」、「就是繩鍊、箱體擇一即可。」） 公園路燈工程管理處處長承認實務上需現行犯始能即時執法，並表示會依議員建議具體檢討定義、評估人力並配合動保處辦理講習。（引文：「實務上，如同議員剛剛所說的，可能是現行犯的狀況下才有辦法執法」、「謝謝議員。」）", "response_removed": false, "topic": "公園管理自治條例修法與動物管理"}, {"citations": [{"page": 2259, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=3"}, {"page": 2260, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=4"}, {"page": 2261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=5"}, {"page": 2259, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=3"}, {"page": 2261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=5"}], "councilor_points": ["林亮君議員指出臺北市參與閩南語沉浸式教學計畫之國中小學校比例不到1%，詢問教育局局長學校未參與之困難，並建議參考桃園市「閩華雙聲帶試辦計畫」將補助單位縮小至個別教師以提高誘因。（引文：「總共是 2 所國中和 1 所國小參與沈浸式閩南語的教學計畫。但是全臺北市總共有 102 所國中，國小有 177 所，等於不到 1%的學校有投入的意願。」、「參考桃園市的閩華雙聲帶試辦計畫……將單位縮小到個別的教師，提供個別教師更多的資源和支持，能夠有誘因將本土語言納入教學當中。」） 林亮君議員指出現行本土語言選修調查表缺乏進階選項，要求教育局調整問卷調查並於總質詢前提出初步規劃報告。（引文：「本土語言課程選修調查表當中發現，其實少了一個進階的選項。」、「本土語言課程選修調查表當中，能夠提供進階班的選項……不知道湯局長可不可以承諾，至少在總質詢之前就這個部分，給本席一些初步計畫的規劃，以及相關的調整？」）"], "response": "教育局局長說明閩南語開設班級多達5088班，學校未參與沉浸式計畫多因教師需改變授課語言習慣與增加備課時間，承諾會多加鼓勵並交流辦理注意事項。（引文：「閩南語教學人數是最多，開設的班級大概有5,088 班，上課學生大概有十二萬一千多名學生。」、「可能在講課的時候做語言轉換，也許老師本身比較不習慣，所以當老師要參與這個課程的時候，老師要應用到講課，可能在備課上要多做準備。」）", "response_removed": false, "topic": "中小學本土語言沉浸式教學推廣"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162#page=1", "transcript_pages": [1043, 1045, 1046, 1047, 1048], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162", "videos": [{"date": "2023-04-17", "group": 2}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 18, "heading": "財政建設部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC#page=1", "transcript_pages": [1875, 1876, 1877, 1878, 1879], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654928959BCFC24F51EB0F1A92AA68C9C631FB4E13B975B947BA3294F53A4744D6D302D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 18}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC#page=1", "transcript_pages": [2257, 2258, 2259, 2260, 2261, 2262, 2263, 2264], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549447EA055CB5EC5CB59661F4B5187A9D1E72D6FF9C393ED9AE534E7B24520F0B602D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 15}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC#page=1", "transcript_pages": [2634, 2635, 2636, 2637, 2638, 2639, 2640, 2641], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549E6C72546062BF3741611575CF38E043BA5F9BCD4F12C41CA228B5493CA3E467F02D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 10}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 8, "heading": "警政衛生部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665493B4201232074AE4923B8A02B322F7FAAF2794CB452BD1AF3D13742D54BA5CA6502D1DE3DCEB210BC#page=9", "transcript_pages": [3069, 3070, 3071, 3072, 3073, 3074], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665493B4201232074AE4923B8A02B322F7FAAF2794CB452BD1AF3D13742D54BA5CA6502D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 8}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549620CA27A3F29B54462B74DFE80EC498C0BB2A6A10A18EC03AE4CD9AF0450F54602D1DE3DCEB210BC#page=7", "transcript_pages": [3548, 3549, 3550, 3551, 3552, 3553], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549620CA27A3F29B54462B74DFE80EC498C0BB2A6A10A18EC03AE4CD9AF0450F54602D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 3}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654964E26AE17ED3993FA3853EA5999DF0C2A21B6E20E990F930A852238F00A7C162','2026-10-01T23:14:43Z');
INSERT INTO "fact" VALUES('summary:14-01:p5fb3d560bb','p5fb3d560bb','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:16:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=20"}, {"page": 1038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=20"}, {"page": 1039, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=21"}, {"page": 1040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=22"}, {"page": 1041, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=23"}, {"page": 1040, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=22"}], "councilor_points": ["林延鳳議員指出臺北市青年失業率高，於就業博覽會提供「1,481 個實習機會，只有 439 人應徵」，且勞動局過去「沒有掌握」實際轉正職或媒合成功率。林延鳳議員指出臺北青年職涯中心（TYS）現場陳設阻礙逃生動線「桌子還是擺在逃生口的前面」，且委外管理費用「1 年花了超過 1 億 7,000 萬元」，質疑整體績效低下。林延鳳議員要求勞動局針對青年失業率、實習媒合成功率及館舍安全改善事項「在 1 個月以內給我一份報告」。"], "response": "勞動局局長說明就業博覽會實習職缺「初媒的人次就達到 423 位，所以初媒率已經到達 96.36%」，並承諾「今年開始會以 4 週做一次調查的方式」呈現明確資料，且「在 1 個月內給你最滿意的答覆」。就業服務處處長說明逃生門疑慮時表示「消防局真的每半年都會定期來安檢」，後由勞動局局長補充「責成就服處，請他們立刻改善」並徵詢專業意見。", "response_removed": false, "topic": "青年就業政策與臺北青年職涯中心營運改善"}, {"citations": [{"page": 2198, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=21"}, {"page": 2199, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=22"}, {"page": 2200, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=23"}, {"page": 2200, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=23"}], "councilor_points": ["林延鳳議員指出芝山岩東砲台石塊產生嚴重裂縫「寶特瓶幾乎可以整個塞進去」，拉起封鎖線後三週仍未見實質修補，恐生嚴重公安疑慮「砸到人、砸死人的時候，誰要負責」。林延鳳議員指出當地登山步道軍事崗哨與雨農閱覽室等建物未妥善管理，建議市府應「跨局處的討論，然後把這邊活化」及「籌措經費，而且要增加本市的自主財源」以維護文資。林延鳳議員要求工務局公園路燈工程管理處確認修復時程，並要求市府於 1 個月內提出跨局處討論與整體活化報告「打造亮點遊程活動」。"], "response": "工務局公園路燈工程管理處總工程司說明砲台修復部分由該處處理，「預計 6 月 10 日以前會修好」，步道崗哨修復「現在已經開施工單在施做了」。文化局局長說明「財源的確是非常緊迫，也希望中央和市府能夠儘量多給一些預算」。", "response_removed": false, "topic": "芝山岩考古遺址維護與設施改善"}, {"citations": [{"page": 3750, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC#page=14"}, {"page": 3750, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC#page=14"}], "councilor_points": ["林延鳳議員指出劍潭整宅共有「5 棟」「一共有在一千一百多戶」，樓梯龜裂縫隙「超過 2 公分甚至是 3 公分以上」，且外牆輕碰即碎，存有嚴重公共安全與救災風險。林延鳳議員指出整宅室內坪數狹小「最大也才 12 坪」，走廊堆放瓦斯桶與金紙等物品，質疑僅靠修繕補助無法改變結構安全，詢問都更政策規劃。林延鳳議員要求市府優先將劍潭整宅納入「公辦都更」區域，派遣人員駐點並召開說明會協助整合改建。"], "response": "都市發展局局長說明整宅居住面積小，研析方向為「更新之後，希望會接近原來的室內坪數」，並預計於「第三季」提出整宅都更策略，承諾「協助朝公辦都更的方式」辦理。都市發展局處長說明，若住戶有需求「會比照公辦都更 7599 的概念，會優先去做輔導」，並針對公共空間提供最高九成的修繕補助。", "response_removed": false, "topic": "劍潭整宅公辦都更與公共安全改善"}, {"citations": [{"page": 4103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=2"}], "councilor_points": ["林延鳳議員指出前市長舉辦雙城論壇「動支市庫 107 萬元」，審計部不准核銷變成市府呆帳，詢問市府對追討款項之態度與具體作為。林延鳳議員提出「債權人催債聲明書」，要求市長簽署以展現追討態度，並指出「既然當初議會對這筆錢做成決議，就代表必須要尊重民意」。林延鳳議員表示追討欠款係展現態度「不要讓所有的臺北市市民朋友失望」，要求市府立即處理相關善後作業。"], "response": "市長說明「這個部分會持續向審計處溝通，也會提出申復，我們也會跟議會溝通」。市長表示「要尊重議會，因為那時候是議會做的決議」，且「需要徵得議會的同意」，無法代表議會做決議。", "response_removed": false, "topic": "雙城論壇預算核銷與款項追討"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=1", "transcript_pages": [4102, 4103, 4104, 4105, 4106, 4107, 4129, 4130, 4131, 4132, 4133, 4134, 4135, 4136], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 2}]}, {"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 1, "heading": "民政部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=20", "transcript_pages": [1038, 1039, 1040, 1041, 1042], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162", "videos": [{"date": "2023-04-17", "group": 1}]}, {"dates": ["2023-04-25"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_ur