C#page=1", "transcript_pages": [3075, 3076, 3077, 3078, 3079, 3080], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499FB5C4B131A9D740FB7C57C39CF4D192E25BD779F866846ED6BC13EF21971C1D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 9}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC#page=9", "transcript_pages": [3745, 3746, 3747, 3748, 3749, 3750], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 12}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC','2026-10-01T23:16:21Z');
INSERT INTO "fact" VALUES('summary:14-01:pcdef61ef89','pcdef61ef89','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:17:55Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1787, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=5"}, {"page": 1788, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=6"}, {"page": 1789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=7"}, {"page": 1791, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=9"}, {"page": 1793, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=11"}, {"page": 1794, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=12"}, {"page": 1789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=7"}, {"page": 1791, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=9"}], "councilor_points": ["林杏兒議員指出臺北市流浪貓收容數居全國第一且占比達24.82%，質疑認養率下降與補助誘因不足，建議明訂認養送寵物終身保險計畫以提高認養率。林杏兒議員表示一般民眾抓捕街貓送醫絕育卻需自費並被強制植入晶片登記，造成愛心民眾負擔，要求市府建立簡便流程與相關配套。"], "response": "動物保護處處長說明因出險率與理賠金額過高導致業者投標意願低，目前已將補助提高至1,500元，並承諾研究認養送保險計畫。動物保護處處長表示會再與合作團體討論民眾抓捕街貓之絕育合作流程與提議。", "response_removed": false, "topic": "流浪動物收容認養與街貓絕育管理"}, {"citations": [{"page": 2988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=9"}, {"page": 2988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=9"}, {"page": 2992, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=13"}, {"page": 2990, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=11"}, {"page": 2993, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=14"}], "councilor_points": ["林杏兒議員指出臺北市民防人員缺額達506人且50歲以上占7成，要求警察局檢討人力配置並增加專責人員負責民防業務。林杏兒議員建議整合民防、義警與守望相助隊等民力組織統一管理，並增加常態訓練時數與技能培訓。林杏兒議員建議提高常訓經費與每年每人1萬元的聯誼活動費用，並提供交通、醫療及稅務減免等招募誘因。"], "response": "警察局局長表示民防、義警與義交組織調配正在研議辦理中，並承諾會研究辦理專職訓練與增加訓練時數。警察局局長說明認同提高津貼與成員福利，相關建議會納入研討並建議中央一起研究。", "response_removed": false, "topic": "民防團隊人力編制與訓練福利改善"}, {"citations": [{"page": 4326, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=4"}, {"page": 4327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=5"}, {"page": 4328, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=6"}, {"page": 4328, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=6"}, {"page": 4327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=5"}, {"page": 4325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=3"}], "councilor_points": ["林杏兒議員指出臺北市立聯合醫院未將公職護理師納入危勞職務，致使其需至65歲才能屆齡退休且需輪值三班，影響醫療品質。林杏兒議員出示155位員工連署書，要求市府重啟全面調查與召開會議，尊重多數意願，並協助年長護理師轉任非危勞職務。"], "response": "蔣市長說明將請聯醫進行全面調查，顧及絕大多數護理人員意願與生涯規劃，並研擬計畫尊重意願協助安排以減輕負擔。臺北市立聯合醫院院長說明係因中央無落日條款且需機構處理現任60歲至65歲公職護理同仁，承諾於3個月內針對所有醫護進行全面調查做為施政參考。", "response_removed": false, "topic": "臺北市立聯合醫院公職護理師危勞職務認定"}, {"citations": [{"page": 4330, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=8"}, {"page": 4330, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=8"}, {"page": 4331, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=9"}, {"page": 4332, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=10"}, {"page": 4332, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=10"}, {"page": 4333, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=11"}], "councilor_points": ["林杏兒議員指出地下式消防栓與排氣閥辨識不易，且警察開罰依據標線與消防栓周邊5公尺規定不一，造成無紅線處開罰爭議。林杏兒議員指出臺北市有2,018處需補劃紅線，其中士林區與北投區占1,024處，質疑局處橫向聯繫不足，要求建立跨局處通報系統與明確執法標準。"], "response": "蔣市長說明將重新全面檢討建置通報系統流程與標準作業程序（SOP），並研究標誌標線機制提供民眾依循。消防局局長與警察局局長說明執法以標誌標線為依據，若無劃設紅線無法開罰，會行文交通管制工程處補劃紅線並通報檢討。臺北自來水事業處處長說明新設消防栓完工後會第一時間彙報給消防局與交通管制工程處等單位。", "response_removed": false, "topic": "地下式消防栓標誌標線劃設與跨局處通報機制"}, {"citations": [{"page": 2993, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=14"}, {"page": 3629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=18"}, {"page": 3630, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=19"}, {"page": 3631, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=20"}, {"page": 3632, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=21"}], "councilor_points": ["林杏兒議員指出臺北市行道樹總數量89,158棵，自辦工班在幅員最廣的北區僅配置14位人力，要求市府同時考量面積與幅員重新檢討並增加人力。林杏兒議員指出委外修剪廠商以前無需檢附照片即可核銷請款，質疑有惡意灌水圖利疑慮，要求市府追查過去4、5年來的請款狀況。"], "response": "公園路燈工程管理處處長說明每年例行修剪一次，承諾會將幅員與樹木數量一併納入考量以檢討人力配置。公園路燈工程管理處處長說明自今年3月起已要求檢附照片請款，並承諾於3個星期內追查請款疑義並給予答覆。", "response_removed": false, "topic": "行道樹修剪人力配置與委外請款核銷追查"}, {"citations": [{"page": 2142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=26"}, {"page": 2143, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=27"}, {"page": 2143, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=27"}], "councilor_points": ["林杏兒議員指出前市府於調解成立支付臺北表演藝術中心工程242,693,708元經費，質疑未選擇仲裁或訴訟以爭取更低支付金額。林杏兒議員提出監造費用重複計價、展延390.5天合理性等21項疑點，要求市府檢討監造單位疏失與合約執行情形。"], "response": "文化局局長說明該筆1億多元款項係因多次工程變更，調解委員會認定屬原主契約下應給付範疇，且評估仲裁輸的可能性大並有利息與訴訟風險，表示會後將詳細了解議員提出的資料與疑點。", "response_removed": false, "topic": "臺北表演藝術中心工程變更與調解款項爭議"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=1", "transcript_pages": [4323, 4324, 4325, 4326, 4327, 4328, 4329, 4330, 4331, 4332, 4333, 4334], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC", "videos": [{"date": "2023-06-02", "group": 8}]}, {"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=12", "transcript_pages": [1166, 1167, 1168, 1169, 1170, 1171, 1172, 1173, 1174], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 8}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=4", "transcript_pages": [1786, 1787, 1788, 1789, 1790, 1791, 1792, 1793, 1794], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 15}]}, {"dates": ["2023-05-02"], "dept": "教育", "doc_type": "部門質詢", "group": 9, "heading": "教育部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=25", "transcript_pages": [2141, 2142, 2143], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 9}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 1, "heading": "交通部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492237BF4F7EC0E56EC4B81A6024F97FA69A039C2603C45894DDE59675020FB9B802D1DE3DCEB210BC#page=1", "transcript_pages": [2405, 2406, 2407, 2408, 2409, 2410, 2411, 2412], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492237BF4F7EC0E56EC4B81A6024F97FA69A039C2603C45894DDE59675020FB9B802D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 1}]}, {"dates": ["2023-05-15", "3031-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 5, "heading": "警政衛生部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=8", "transcript_pages": [2987, 2988, 2989, 2990, 2991, 2992, 2993], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 5}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=17", "transcript_pages": [3628, 3629, 3630, 3631, 3632, 3633], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 6}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC','2026-10-01T23:17:55Z');
INSERT INTO "fact" VALUES('summary:14-01:p9ff03a516c','p9ff03a516c','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:20:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3599, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=13"}, {"page": 3598, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=12"}], "councilor_points": ["林珍羽議員指出臺北市大彎北段商業區違規住宅存在多年歷史背景，要求市府向中央爭取解套方案（「請蔣市府積極向內政部營建署溝通，甚至要請市長請命到行政院會取得最終解決方案」）。林珍羽議員建議市府重新檢討違反都市計畫法之裁罰必要性，並向行政執行署主動行文申請暫緩執行（「針對違規住宅違反都市計畫法之裁罰，請你重新思考是不是有裁罰的必要性，或者是有什麼樣的方法可以暫緩執行」；「裁罰案件，請臺北市政府主動行文行政執行署暫緩執行」）。林珍羽議員要求市府廢止限制市民遷徙自由的告知單，避免損及居民權利（「請停止威嚇限制市民自由，臺北市中山區大彎北段土地使用分區不得作住宅使用告知單……可不可立即廢止、停止違憲的作為」）。"], "response": "都市發展局局長說明已將檢討案陳報內政部，並會向市長報告至行政院說明（「我們認為有交代清楚」；「可以，我會跟市長報告」）。都市發展局局長表示確定之原處分無法撤銷，但若義務人申請延緩會從寬認定，並承諾帶回討論停止告知單事宜（「因為最高行政法院判決的原處分已經確定了，所以我們沒有辦法去撤銷」；「我們都會從寬的認定來同意」；「可以討論」）。", "response_removed": false, "topic": "大彎北段商業區違規住宅通盤檢討與裁罰"}, {"citations": [{"page": 4061, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=23"}, {"page": 4065, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=27"}, {"page": 4066, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=28"}, {"page": 4061, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=23"}, {"page": 4066, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=28"}], "councilor_points": ["林珍羽議員詢問市長對上任半年滿意度與市政表現之評分，並指出前朝柯市府留有189件工程會在現任市長任期完工（「你可不可以為你上任半年給自己打個分數」；「從柯市府時期規劃的 5,000 萬元以上的工程案件至 255 億元的工程案件，在柯市府任內規劃，但是會在蔣萬安市長任期裡完工以及剪綵的，總共有 189 件」）。林珍羽議員給予市府團隊75分，期許市府團隊善用公務人員並拿出讓人民有感的市政成績單（「我給你 75 分，因為市政是一棒接著一棒，這八萬大軍經過了 8 年的磨練，市政能夠繼續推動」；「期許市長儘速拿出讓人民有感的市政成績單」）。"], "response": "市長說明團隊會加倍努力推動政策，並表示滿意度分數應由市民客觀來打（「團隊會加倍努力，市民的意見非常重要」；「分數由市民打」）。市長表示市政是一棒接一棒且具有延續性，會感念歷任市長奠下的基礎（「我想市政絕對是一棒接一棒」；「我們要感念的，不只是柯前市長，還有郝前市長、馬前市長，甚至前任的市長，大家共同努力奠下的基礎」）。", "response_removed": false, "topic": "市府團隊施政滿意度評分與前朝工程移交"}, {"citations": [{"page": 1816, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=10"}, {"page": 1815, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=9"}], "councilor_points": ["林珍羽議員詢問鐵皮屋加裝彩色光電板政策之權責與試辦規劃，指出產業發展局僅編列460萬元補助私部門，與環境保護局編列1億元補助形成落差（「關於鐵皮屋變成彩色光電板，你認為是市容美觀？還是要邁向 2050 年的淨零排放？還是因為產業發展」；「今年度編列 460 萬元，要補助私有部門……但是你知道嗎？環保局編列 1 億元」）。林珍羽議員要求市府即刻召開能源政策跨局處會議，並在進行可行性評估報告後再做試辦（「本席要求，即刻召開臺北市能源政策跨局處會議」；「針對鐵皮屋彩色太陽能板，進行評估試辦的可行性報告，請提供可行性報告後，再開始做試辦」）。林珍羽議員要求建築管理工程處針對既存違建禁止修繕與免請領雜項執照標準之衝突研擬配套（「請建築管理工程處針對北市禁違建修繕與「設置再生能源設施免請領雜項執照標準」檢討衝突的地方並研擬配套」）。"], "response": "產業發展局局長說明發展太陽光電主因係為降低碳排放以達淨零排放目標，試辦前會由副市長召集相關局處釐清法規與分工（「發展太陽光電最主要的原因是希望能夠透過乾淨的再生能源，去降低碳的排放量」；「在試辦之前，由他來召集相關局處把責任分工」）。產業發展局局長承諾會在5月召開能源政策跨局處會議，並遵照議員指示辦理相關評估（「預計 5 月開第 1 次會議」；「我們僅遵議員的指示辦理」）。", "response_removed": false, "topic": "鐵皮屋彩色光電板計畫與能源政策跨局處平台"}, {"citations": [{"page": 4096, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=58"}, {"page": 3052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=17"}, {"page": 4097, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=59"}, {"page": 4100, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=62"}, {"page": 4097, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=59"}, {"page": 3049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=14"}, {"page": 4101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=63"}], "councilor_points": ["林珍羽議員指出市立聯合醫院護病比過高且開床進度不如預期，建議市府勿盲目擴床並優先改善護病比（「現在聯醫的護病比是 1：10，遠高於國際」；「在擴床之前請優先改善 7 大院區的護病比」）。林珍羽議員指出衛生局放棄浩然敬老院西側3,060平方公尺空間極為可惜，要求重新評估整體長照規劃（「去年 8 月 23 日府級會議討論過這塊基地……將這個 3,060 平方公尺的空間規劃為長照住宿機構」；「請重新審慎評估浩然二期基地西側通盤檢討可能性」）。林珍羽議員建議市府檢討組織變革，評估成立長照局專責橫向整合各局處資源（「有沒有設立長照局的可能性？有沒有可能從現有的人員編制重新編組、規劃」）。"], "response": "衛生局局長說明6個月內難以開出500張實體床，因該基地較狹長且考量營運效益，故規劃於陽明院區興建智慧醫療大樓布建200床（「的確不太可能在 6 個月內開出 500 張實體床」；「基地比較狹長……我們在陽明院區裡興建智慧醫療大樓，未來可能會布建 200 床」）。市長表示會全面評估市府組織變革，並承諾在6個月內針對長照體系進行整體評估（「我們會全面地評估市府整體的組織變革」；「請給我們 6 個月時間評估再回覆議員」）。衛生局局長與市立聯合醫院院長允諾會優先改善護病比且不壓縮急性病床占比（「可以做到」）。", "response_removed": false, "topic": "市立聯合醫院護病比與長照局設立評估"}, {"citations": [{"page": 1298, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=17"}, {"page": 1300, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=19"}, {"page": 1301, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=20"}], "councilor_points": ["林珍羽議員指出臺北市僱用百人以上之2,186家公司中僅90間設置哺（集）乳室，且今年度僅21間申請補助，顯示職場環境極不友善（「臺北市近 5 年來，2,186 家百人以上的公司，只有 90 間的哺(集)乳室」；「2,186 間百人以上的公司，今年度只有 21 間公司申請補助」）。林珍羽議員要求勞動局於勞檢提示單增列哺（集）乳室檢查項目，並於3個月內提出提升哺（集）乳室設置比率之短中長期計畫（「本席具體要求，勞檢提示單要增列哺(集)乳室檢查項目」；「我希望 3 個月可以拿到提升臺北市友善哺(集)乳室設置短中長期計畫」）。林珍羽議員建議勞動局會同法務局研擬相關罰則並向中央提案增設（「請局長會同局內的相關人員以及法務局，針對相關的罰則做研擬，會同法務局協助提案增設罰則」）。"], "response": "勞動局局長表示百人以上公司未設置者僅48家，但承認職場環境尚未達到友善程度（「我們的數據只有 48 家沒有哺(集)乳室」；「我覺得這樣的環境還沒有達到友善的程度」）。勞動局局長承諾在一周內將哺（集）乳室納入勞檢項目，並於3個月內規劃提升設置率之計畫（「可以」；「一周內」；「我們先做 3 個月的期程計畫」）。勞動局就業安全科科長說明過往曾3次建議中央修法，將再次強烈行文建請中央重視（「我們在很多年前，曾經 3 次建議中央修法，如果可以，我們會再次強烈的行文請中央修法」）。", "response_removed": false, "topic": "職場哺（集）乳室設置率與勞動檢查改善"}, {"citations": [{"page": 2582, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=26"}, {"page": 2583, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=27"}, {"page": 2584, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=28"}, {"page": 2584, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=28"}], "councilor_points": ["林珍羽議員指出臺北捷運目前多元支付加值售票機僅設於10個站點且僅限購買旅遊票，支付便利性落後其他縣市（「目前多元售票機，只有設在 10 個站點可以買到票？同時間一般市民根本沒有辦法享受這樣多元支付的功能，因為它只販售旅遊票」）。林珍羽議員詢問捷運局編列4.53億元重置閘門之採購內容，要求市府加速建置並保留閘門支付模式的擴充性與包容性（「捷運局編了 4.53 億元，據說要做閘門口的重置」；「請讓臺北捷運重回領頭羊的地位」；「請總經理在合約建置的過程中，保留閘門支付模式的擴充性」）。"], "response": "臺北捷運公司總經理說明重置案涵蓋117個捷運站之軟硬體更新與NFC、信用卡及QR Code等多元支付，預計於114年底建置完成（「包含 117 個捷運站、前臺閘門、軟硬體的新功能……」；「114 年年底完成建置，大概 115 年就可以投入商業服務了」）。臺北捷運公司總經理表示合約設計已涵蓋擴充性條款，亦將悠遊卡納入擴充項目中（「我們當初就有設計這樣的條款」；「現在悠遊卡公司針對 Apple Pay 的悠遊卡，也納入擴充性裡面」）。", "response_removed": false, "topic": "臺北捷運閘門多元支付建置"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=23", "transcript_pages": [4061, 4062, 4063, 4064, 4065, 4066, 4067, 4068, 4069, 4070, 4096, 4097, 4098, 4099, 4100, 4101], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 1}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=14", "transcript_pages": [1295, 1296, 1297, 1298, 1299, 1300, 1301, 1302, 1303, 1304], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 13}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=6", "transcript_pages": [1812, 1813, 1814, 1815, 1816, 1817, 1818, 1819, 1820, 1821], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 16}]}, {"dates": ["2023-05-02", "2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=11", "transcript_pages": [2155, 2156, 2157, 2158, 2159, 2160, 2161], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 10}, {"date": "2023-05-04", "group": 10}]}, {"dates": ["2023-05-09"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=26", "transcript_pages": [2582, 2583, 2584, 2585, 2586, 2587], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC", "videos": [{"date": "2023-05-09", "group": 7}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=14", "transcript_pages": [3049, 3050, 3051, 3052, 3053, 3054, 3055, 3056, 3057], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 7}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=7", "transcript_pages": [3593, 3594, 3595, 3596, 3597, 3598, 3599, 3600], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC','2026-10-01T23:20:21Z');
INSERT INTO "fact" VALUES('summary:14-01:p41a7902cc9','p41a7902cc9','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:21:55Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3529, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=15"}, {"page": 3530, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=16"}, {"page": 3531, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=17"}, {"page": 3535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=21"}, {"page": 3535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=21"}, {"page": 3529, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=15"}, {"page": 3530, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=16"}, {"page": 3532, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=18"}, {"page": 3533, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=19"}, {"page": 3534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=20"}], "councilor_points": ["柳采葳議員詢問新建工程處承諾每年新增 5 條實體人行道的執行條件與方式，並指出 107 年至今僅設置 8 條實體人行道。議員表示交通管制工程處 109 年與 112 年共提供 142 處建議改為實體人行道的路段，經會勘僅 13 處可施作，要求市府加快人行道改善與普查進度。議員關注今年 1 月至 4 月新建工程處自行巡查人行道坑洞件數接近去年整年件數的情形，要求工務局加強基層稽查與維護管理。"], "response": "新建工程處處長說明早期 12 公尺以上道路多已設置實體人行道，新設常面臨高程影響出入及排水溝管線等問題，目前規劃採護欄或路緣石等實體區隔方式試辦。工務局局長表示會由副市長召集的專案平臺進行跨局處整合，並與地區民眾及里長會勘取得共識後辦理。新建工程處處長說明今年度預計完成 30 公尺以上道路總長度 390 公里的人行道普查，並會持續研議完成年度 KPI 目標。", "response_removed": false, "topic": "實體人行道設置與人行道環境改善"}, {"citations": [{"page": 1365, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=2"}, {"page": 1365, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=2"}, {"page": 1366, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=3"}, {"page": 1366, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=3"}, {"page": 1367, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=4"}, {"page": 1367, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=4"}, {"page": 1368, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=5"}, {"page": 1369, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=6"}], "councilor_points": ["柳采葳議員指出臺北市 111 年新生人口數降至史上新低 14,528 人，並反映中山區濱中等多處公共托育家園面臨承辦單位不願續約的狀況，關注今年底合約到期的 31 家公托後續運作。議員詢問準公共托嬰中心 3 年內有 9 家因招生不足或疫情結束營運的情形，要求社會局積極提出留任與續約機制。議員指出定點臨托推動 5 年僅 5 個行政區設置，且萬華與大同區開辦延期，要求社會局加速在中山區等處評估點位並提早開辦。"], "response": "社會局局長說明少子化原因複雜，市府正持續尋找有意願的單位進行重新招標與溝通，並規劃久任薪資等福利鼓勵托育人員留任。社會局局長表示大同區定點臨托因工程延期影響，承諾於當年 8 月開辦，並會積極在各區推動臨托服務。", "response_removed": false, "topic": "公立與準公共托育設施營運與定點臨托布建"}, {"citations": [{"page": 3536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=22"}, {"page": 3538, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=24"}, {"page": 3539, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=25"}, {"page": 3539, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=25"}], "councilor_points": ["柳采葳議員指出學校前及士林官邸附近等精華路段出現路燈長達 2 個月不亮的情形，並指出去年路燈故障超過 5 天以上的案件達 384 件，要求市府全面通盤檢視。議員反映民眾車輛遭路燈底座凸出的路緣石刮傷，要求公園路燈工程管理處積極處理，不應「推給」其他局處或直接取消停車格。"], "response": "公園路燈工程管理處處長說明多數長天期不亮屬台電供電或線路問題，已通報並聯繫台電儘速修復。路燈工程隊隊長與工務局局長說明調查路燈基座凸出路緣石者共有 30 處，已先張貼反光貼紙警示，並會會同交通單位辦理會勘改善或微調格位。", "response_removed": false, "topic": "路燈故障維修與基座凸出安全改善"}, {"citations": [{"page": 2333, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=4"}, {"page": 2334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=5"}, {"page": 2336, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=7"}, {"page": 2336, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=7"}, {"page": 2335, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=6"}], "councilor_points": ["柳采葳議員指出臺北市 110 年與 111 年均有 11 處展演地點完全無人登記，112 年更增加至 13 處，包括中山堂廣場及臺北市立美術館廣場等地點亦無人使用。議員建議文化局不應只表示「困難」，應針對冷門及少人使用的場地提出利多或活化政策，並要求列出所有場地的困難點報告。"], "response": "文化局局長說明街頭藝人多考量打賞效益與場域特性而傾向選擇熱門場地，坦言場地熱與不熱兩極化確實存在困難。文化局局長表示未來會與產業發展局等局處合作結合市集活動提供表演空間，並規劃年底透過嘉年華評比拉高街頭藝人身價，同時承諾提供專案報告。", "response_removed": false, "topic": "街頭藝人展演場地活化與管理"}, {"citations": [{"page": 3157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=24"}, {"page": 3159, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=26"}, {"page": 3160, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=27"}, {"page": 3161, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=28"}], "councilor_points": ["柳采葳議員詢問臺北市循環杯點位試辦至 111 年 12 月 31 日停止後的政策方向，並指出目前平均每日借用僅 209 杯、配合店家平均每日不到 1 人使用。議員指出民眾主要擔心衛生問題與地點不便，且台北通地圖定位有落差，要求環境保護局積極推廣並由衛生局將循環杯納入年度稽查項目。議員建議可以在人流量大的捷運站出口試辦循環杯借還服務，以提高整體使用率。"], "response": "環境保護局局長說明配合中央法規，今年要求連鎖超商門市循環杯比例達 5%，臺北市受約束店家有 250 家，並有自備環保杯優惠制度並行。衛生局局長表示會研議將循環杯衛生檢驗納入年度稽查項目，環境保護局局長亦表示已於公館捷運站試辦並會視情形評估推廣。", "response_removed": false, "topic": "循環杯推廣政策與衛生稽查"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-05"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC#page=30", "transcript_pages": [4400, 4401, 4402, 4403, 4404, 4405, 4409, 4410, 4411, 4412, 4413, 4414, 4415], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC", "videos": [{"date": "2023-06-05", "group": 9}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 16, "heading": "民政部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162#page=1", "transcript_pages": [1364, 1365, 1366, 1367, 1368, 1369, 1370], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654990E616DCFFF1E7A793DD4E85566F1C1BCFBA5E343AB30AD4A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 16}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC#page=1", "transcript_pages": [1838, 1839, 1840, 1841, 1842, 1843], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549453DEEE7CF4DF6CF23B8A02B322F7FAAF5A6553FC1B61FF7BDEF966A22CFC4A602D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 17}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 18, "heading": "教育部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC#page=1", "transcript_pages": [2330, 2331, 2332, 2333, 2334, 2335, 2336, 2337, 2338, 2339], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549FE97FA290BC0B2847241EDEFDD9C7910D1895BEEDD0E09357BD75FE21A4CCF9302D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 18}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 3, "heading": "交通部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC#page=14", "transcript_pages": [2470, 2471, 2472, 2473, 2474, 2475, 2476, 2477], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665499CD3ABA326CC9D91689AFCE66286F4808F7C1697350CF9905A34A50A9C06547E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 3}]}, {"dates": ["2023-05-18"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC#page=24", "transcript_pages": [3157, 3158, 3159, 3160, 3161, 3162, 3163], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549DDF9ADA21B0590536C935823F58C14CDDCD8E8308BBF461F2617D9A8B74AC20202D1DE3DCEB210BC", "videos": [{"date": "2023-05-18", "group": 13}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC#page=14", "transcript_pages": [3528, 3529, 3530, 3531, 3532, 3533, 3534, 3535, 3536, 3537, 3538, 3539, 3540], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A9AB4CE0EA3640761940DFEE53EA9219A7495F3FA678754DD0254C8A5E65DB0D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665496E853D31EF930B5C63BD102CAC9A5F00A378B4370DDCFEEFA30EC98B78CB876802D1DE3DCEB210BC','2026-10-01T23:21:55Z');
INSERT INTO "fact" VALUES('summary:14-01:paf86790352','paf86790352','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:24:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1130, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=2"}, {"page": 1131, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=3"}, {"page": 1131, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=3"}, {"page": 1133, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=5"}, {"page": 1145, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=17"}, {"page": 1145, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=17"}, {"page": 2252, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=19"}, {"page": 1132, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=4"}], "councilor_points": ["楊植斗議員詢問在座局處首長對台海發生戰爭或衝突之看法，並引述新聞指出印尼政府已宣布「35萬移工撤僑計畫」，關切若發生戰禍致移工撤離時失能長者之照護與預先整備機制。楊植斗議員建議市府於菲律賓及印尼移工契約上研議請其「先安置好這些失能的長者或是獨居的長者再離開」，並請民政局參考《戰爭下的平民生存手冊》宣導防空避難空間及備妥乾糧物資小包裹。楊植斗議員指出國外廠商因顧慮臺海戰爭風險而不敢至松菸辦展，建議研究發展考核委員會於民意調查中納入市民對兩岸戰爭之看法與防災意識問題。"], "response": "勞動局局長說明會行文中央勞動部預做準備並研議善後措施；社會局局長表示若居服員撤僑，第一優先會與長照系統合作進行銜接支援，並透過民間捐款或與勞動局協調契約合規性。民政局局長說明臺北市「456個里都有做防空避難」，並透過萬安演習或大規模演習預做準備，但若無中央指示地方很難自行辦理相關應變措施。研究發展考核委員會主任委員承諾會在今年度的調查中規劃防災與戰爭相關問卷，並協請相關局處盤點問題研擬內容。", "response_removed": false, "topic": "兩岸局勢整備與民防撤僑應變"}, {"citations": [{"page": 2621, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=20"}, {"page": 2622, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=21"}, {"page": 2622, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=21"}, {"page": 2623, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=22"}, {"page": 2624, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=23"}], "councilor_points": ["楊植斗議員詢問過往雙北市推出「1,280元定期票」時僅限定綁定悠遊卡之原因，並關切未來北北基桃全面開放「1,200元月票」實施多卡通後，悠遊卡市場遭瓜分之因應對策。楊植斗議員建議交通局等單位向交通部爭取繼續以悠遊卡作為主要綁定支付工具，以維護臺北市政府資產收益。楊植斗議員要求悠遊卡投資控股股份有限公司落實營運目標，持續提升會員黏著度並做好市場競爭準備。"], "response": "交通局運輸管理科科長說明當初推行1,280元定期票係為縮短修改時間及配合悠遊卡超過9成之市占率，後續其他卡片因系統未配合而未加入。交通局局長說明中央推動1,200元月票政策開宗明義要求多卡通不可特別綁定，但市府會在實務操作上儘量讓悠遊卡使用率再攀高。悠遊卡投資控股股份有限公司總經理說明將推出手機設定卡片等便利行銷方案，並承諾今年目標達「290萬會員人數」及交易金額「100億元」。", "response_removed": false, "topic": "1200基北北桃定期票與悠遊卡營運策略"}, {"citations": [{"page": 1767, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=17"}, {"page": 1768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=18"}, {"page": 1769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=19"}, {"page": 1769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=19"}, {"page": 1770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=20"}, {"page": 1771, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=21"}], "councilor_points": ["楊植斗議員詢問動物保護處目前鼓勵飼主投保寵物保險發放「1,500元」超商提貨券之規劃原因，並質疑僅發放「7-Eleven」提貨券是否有獨厚特定業者之嫌疑。楊植斗議員建議動保處考量飼主消費便利性，改採出示單據「直接發現金」補助之方式，並研議提高認養寵物保險預算金額以鼓勵民眾認養。楊植斗議員指出衛生局無法管理動物醫院，建議動保處評估設立市立動物醫院之可行性以利管理與建立口碑。"], "response": "動物保護處處長說明過去直接採購寵物保險因廠商評估賠率流標3次，故滾動檢討改為補助1,500元禮券，並由委託廠商向門市數量足夠之超商採購提貨券。動物保護處處長表示議員建議很好，會朝發放現金的方向研議處理，亦會研議提高認養保險預算之可行性。動物保護處處長表示會與獸醫師公會及產業進行討論溝通，並將相關評估報告送交議員研究室。", "response_removed": false, "topic": "寵物保險補助發放方式與寵物專責醫院研議"}, {"citations": [{"page": 1135, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=7"}, {"page": 1135, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=7"}, {"page": 1136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=8"}, {"page": 1136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=8"}, {"page": 1138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=10"}, {"page": 1144, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=16"}, {"page": 1137, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=9"}], "councilor_points": ["楊植斗議員指出市府針對低收入戶及中低收入戶提供保額「30萬元」之微型保險，但自「去年12月」清查後至「今年4月」間新產生的低收入戶無法納保，出現長達數月的保障空窗期。楊植斗議員建議市府因應公益型保險籌措困難，可由市府編列預算代繳微型保險保費，或預先了解狀況做到無縫接軌。楊植斗議員要求社會局儘速完成保險公司洽談，並於空窗期間尋求民間捐款等資源提供額外保障，補足社會安全網漏洞。"], "response": "社會局社會救助科科長說明微型保險係運用民間資源承保，目前已洽談約「100萬元」保費額度，會儘快處理納保作業。社會局局長說明微型保險屬於公益性質而非預算內容，市府會提早於每年中旬開始洽談來年合作之保險公司與額度，避免銜接出現問題。社會局局長表示針對空窗期會進行調查了解，若知悉需求將動用民間捐款協助處理，並已由其他局處首長提供保險公司資訊進行拜訪溝通。", "response_removed": false, "topic": "弱勢族群微型保險保障空窗期"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162#page=1", "transcript_pages": [1129, 1130, 1131, 1132, 1133, 1134, 1135, 1136, 1137, 1138, 1139, 1144, 1145], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 7}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC#page=16", "transcript_pages": [1766, 1767, 1768, 1769, 1770, 1771, 1772, 1773, 1774, 1775], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654913DAB93479D5FE6EDEADF897A6745357C503B047104972752E8A0D337611D05E02D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 14}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC#page=17", "transcript_pages": [2250, 2251, 2252, 2253, 2254, 2255, 2256], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB963735665493D7FAF9F419EE4D7198FE74F0907F787BD92F3BA3292F4A6FDC3AE74540BCAD002D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 14}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC#page=20", "transcript_pages": [2621, 2622, 2623, 2624, 2625, 2626, 2627, 2628, 2629, 2630, 2631, 2632, 2633], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665495CDBD1F1A0AAF4818580DC0E2417E4F6EDC668873815834ADC588672B8DCA0D102D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 9}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 16, "heading": "警政衛生部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC#page=1", "transcript_pages": [3198, 3199, 3200, 3201, 3202, 3203, 3204], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549706E59058B394820CD8F6FC88322C35963089F9DCE20FA447A65329FF13675CD02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 16}]}, {"dates": ["2023-05-26"], "dept": "工務", "doc_type": "部門質詢", "group": 18, "heading": "工務部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC#page=8", "transcript_pages": [3842, 3843, 3844, 3845, 3846, 3847, 3848, 3849, 3850], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665492861F041E0C7F46F6D3396F29A5CFE0B54E6CC8ACA9867024AEE975E286BC34002D1DE3DCEB210BC", "videos": [{"date": "2023-05-26", "group": 18}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654906B148B82A8E28EFE03B6E57708536465A5EB2A8459D5D76A852238F00A7C162','2026-10-01T23:24:19Z');
INSERT INTO "fact" VALUES('summary:14-01:p6ad3a2608b','p6ad3a2608b','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-01T23:26:23Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3186, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=9"}, {"page": 3187, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=10"}, {"page": 3188, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=11"}, {"page": 3190, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=13"}, {"page": 3191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=14"}, {"page": 3189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=12"}], "councilor_points": ["汪志冰議員指出全國概估約有 1,000 輛行動餐車（胖卡），但臺北市政府至今缺乏主政單位且無登記統計數字，導致業者遊走於法律邊緣。汪志冰議員表示胖卡快閃營業模式引發占用道路、違規停車、食品安全、廢棄物及瓦斯設備安全等多頭馬車與管轄漏洞問題。汪志冰議員要求市府正視問題，建議研議自治條例或請中央整合一套完整的法令規範供業者依循與各單位管理。"], "response": "警察局局長說明，胖卡若占用道路擺攤或違規停車會依「道路交通管理處罰條例」告發處分，但若於停車場或私人土地營業則非警察局管轄。衛生局食品藥物管理科科長表示，販售食品均適用「食品安全衛生管理法」，臨時流動型採抽查機制，但因無特別註記且流動性高而難以掌握。消防局局長表示，車上使用燃氣設備具潛在危險但目前無法令規範常態行為，並與警察局局長、衛生局局長及環境保護局局長皆同意應訂定專法或整合管理機制。", "response_removed": false, "topic": "行動餐車（胖卡）經營規範與跨局處管理"}, {"citations": [{"page": 1248, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=17"}, {"page": 1250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=19"}, {"page": 1252, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=21"}, {"page": 1254, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=23"}], "councilor_points": ["汪志冰議員指出，臺北市符合一定規模的 69 家殯葬業者依規定須聘置專任禮儀師，但乙級證照考試門檻過高且題目偏離實務，對小規模業者造成沉重負擔。汪志冰議員指出，殯葬管理處發出的公函「語焉不詳」，導致 10 家已於 6 月底前完成改善的業者仍收到 10 萬元的裁處書，質疑市府「搞烏龍」且「挖個洞讓業者跳進去」。汪志冰議員要求市府解決公文不清所造成的業者裁罰損失，並向中央反映檢討不合理的考題。"], "response": "殯葬管理處處長坦承禮儀師考題確實「不合時宜」，表示市府可向中央反映將考試內容與現行禮儀習慣結合。民政局局長表示，若業者依公文字面意思於 6 月 30 日前完成改善，照理「不應該」被開罰。殯葬管理處處長說明查核計畫原定於 4 月底辦理，但也承認公文內容呈現不夠清楚。", "response_removed": false, "topic": "殯葬禮儀服務業專任禮儀師設置規定與查核裁罰"}, {"citations": [{"page": 2704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=3"}, {"page": 2707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=6"}], "councilor_points": ["汪志冰議員指出微型電動二輪車、電動輔助自行車與電動機車的路權、掛牌及保險規範複雜，連官員現場受測都會誤答，一般民眾更是「霧煞煞」。汪志冰議員指出微型電動二輪車 5 年內肇事達 804 件、傷亡 707 人，肇事率暴增 2 倍，且北市尚有約 1 萬 8,000 輛舊車未換牌，按目前速度需 9.5 年才能全面掛牌。汪志冰議員要求交通局在 113 年 11 月 29 日緩衝期結束前，利用多元管道並結合銷售店家懸掛海報宣導，勸導民眾遵守規定並儘速掛牌。"], "response": "交通局局長與警察局交通警察大隊大隊長說明，微型電動二輪車依法不得行駛於人行道及自行車道，且須投保強制險與掛牌。交通局局長表示，會與監理所合作，結合銷售店家及人力仲介公司等管道加強宣導，勸導民眾儘早完成換牌。", "response_removed": false, "topic": "微型電動二輪車法規宣導與掛牌納管"}, {"citations": [{"page": 3795, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=16"}, {"page": 3796, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=17"}, {"page": 3799, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=20"}, {"page": 3799, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=20"}], "councilor_points": ["汪志冰議員指出北市要求 30 年以上私有建築物辦理外牆安全診斷申報，首波列管 913 棟中僅 136 棟完成，申報率僅 14.8%。汪志冰議員出示陳情資料指出，檢測市場報價從 29 萬元到 225 萬元相差 7 倍，且額外巧立各種名目計費，加上每 3 年須申報一次，導致民眾「情願罰款也不想要申報」。汪志冰議員要求建築管理工程處建立價格投訴機制、公開參考報價、延長申報期限、放寬重檢間隔，並依大樓規模彈性調整補助金額。"], "response": "建築管理工程處處長坦承申報率非常低，主因包含未成立管委會、經費籌措及市場訪價過高等複雜因素。都市發展局局長坦言部分公會開出的價格確實過高。建築管理工程處處長與都市發展局局長承諾，會將申報執行價格公開上網參考，並研議放寬申報期限、重檢間隔及依大樓規模調整補助金額。", "response_removed": false, "topic": "建築物外牆安全診斷檢查申報與補助制度"}, {"citations": [{"page": 2220, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=17"}, {"page": 2221, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=18"}, {"page": 2222, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=19"}, {"page": 2223, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=20"}], "councilor_points": ["汪志冰議員指出北市約 23 萬學童食用營養午餐，但 8 年來國小高達 6 成至 7 成 5 的廠商曾遭記點，且部分廠商「劣跡斑斑」卻仍長期遊走各校接單。汪志冰議員指出解約門檻過高，8 年間僅 3 所學校解約、4 所學校停餐一周，如力行國小發生學生喝餿水重大事件竟僅記點罰款 2 萬 6 千元而未解約，顯示把關機制失效。汪志冰議員要求教育局檢討履約規範並增加退場機制、公開違規記點資訊、強化管理責任，並評估公辦公營的可行性。"], "response": "教育局局長認同應建立大數據統計分析，表示表現不佳的廠商應在評選時參考其績效，經常表現不良者應列為拒絕往來戶。教育局局長承諾於 1 個月內檢討修正履約規範、建立退場機制，並一併研議公辦公營的可行性。", "response_removed": false, "topic": "學校營養午餐廠商違規記點與退場機制"}, {"citations": [{"page": 1574, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC#page=1"}, {"page": 1576, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC#page=3"}, {"page": 1576, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC#page=3"}], "councilor_points": ["汪志冰議員指出北市仍有 33%（約 34 萬戶）未接天然瓦斯管，其中 21 處偏遠區塊有 17 處集中在士林與北投區，且平均停滯埋管達 22 年。汪志冰議員以翠山里為例，指出埋管停滯 27 年，2,551 名居民每桶 20 公斤桶裝瓦斯須多付 109 元，且面臨市場壟斷、就地喊價與送氣困難等困境。汪志冰議員質疑主管機關對天然氣事業體監督不周、態度「消極以對」，要求產業發展局主動與業者溝通並於 2 個月內提出具體推進埋管規劃。"], "response": "產業發展局公用事業科科長說明，依天然氣事業法規定，本支管鋪設需由民眾分攤部分費用，且部分偏遠地區因民眾未提出申請而未推進。產業發展局局長表示，會主動與 4 家瓦斯公司溝通協調協助偏遠用戶，並承諾於 2 個月內提出答覆與規劃。", "response_removed": false, "topic": "偏遠地區天然瓦斯管線鋪設與桶裝瓦斯價格"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=1", "transcript_pages": [4214, 4215, 4216, 4217, 4218, 4219, 4220, 4221, 4222, 4223, 4224, 4225], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 5}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 11, "heading": "民政部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162#page=16", "transcript_pages": [1247, 1248, 1249, 1250, 1251, 1252, 1253, 1254], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549E5AE7F438DB9EBDFE03B6E57708536460526FEE37EF8C7FAA852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 11}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 5, "heading": "財政建設部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC#page=1", "transcript_pages": [1574, 1575, 1576, 1577], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 5}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 12, "heading": "教育部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=16", "transcript_pages": [2219, 2220, 2221, 2222, 2223], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 12}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=1", "transcript_pages": [2702, 2703, 2704, 2705, 2706, 2707, 2708, 2709, 2710], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 14}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=8", "transcript_pages": [3185, 3186, 3187, 3188, 3189, 3190, 3191, 3192], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 15}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 15, "heading": "工務部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=15", "transcript_pages": [3794, 3795, 3796, 3797, 3798, 3799], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC','2026-10-01T23:26:23Z');
INSERT INTO "fact" VALUES('summary:14-01:p6da9705b68','p6da9705b68','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-02T16:03:25Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2053, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=3"}, {"page": 2055, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=5"}, {"page": 2056, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=6"}, {"page": 2057, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=7"}], "councilor_points": ["洪健益議員指出寶藏巖國際藝術村現場樓梯等設施缺乏安全防護，若舉辦光節燈光昏暗易生危險（「這個樓梯的設置，如果舉辦光節時燈光又昏暗，這個跌下去會死人的」）。洪健益議員指出閣樓 7 間房間自 107 年至 112 年執行率低落，且單人房 1,600 元與雙人房 2,500 元無早餐且共用浴室，價格偏高（「107 年、108 年、109 年、110 年、111 年、112 年的執行率低到可憐……價格高不高？我個人認為以藝術村這個算高啦」）。洪健益議員建議檢討入住資格審查標準，放寬讓街頭藝人或一般民眾入住體驗（「住宿率持續低迷，要不要放寬標準……供一般民眾入住，要不要給他們體驗藝術村的感覺」）。"], "response": "文化局局長表示接受關於設施安全問題的指謫（「對於議員發現問題的批評和指謫，我完全接受」）。文化局局長坦承閣樓房間較簡陋且房價相較偏高，表示有檢討空間並會深入了解後親自說明（「包括房間可能比較簡陋，房價是不是相對於北投會館稍微比較偏高，這點我承認……看起來還是有檢討空間」）。", "response_removed": false, "topic": "寶藏巖國際藝術村公安維護與閣樓設施經營管理"}, {"citations": [{"page": 3696, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=6"}, {"page": 3697, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=7"}, {"page": 3697, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=7"}, {"page": 3698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=8"}, {"page": 3699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=9"}, {"page": 3700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=10"}, {"page": 3698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=8"}, {"page": 3699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=9"}], "councilor_points": ["洪健益議員指出廣慈博愛園區社宅 111 年電梯設備故障 31 次，112 年截至 4 月達 44 次，且索資資料前後不一，甚至部分故障維修未開立報修單（「廣慈博愛園區111 年電梯設備故障次數總共有 31 次，112 年到 4 月時有 44 次……部分維修因為廠商認定屬外力因素或微調整，故未開立維修單」）。洪健益議員指出社宅電梯發生自頂樓降至 15 樓再掉至 1 樓之異常狀況，要求市府重視安全維護（「電梯在 3 月 27 日前一、二天……從 R 樓瞬間調到 15 樓……再掉到 1 樓」）。洪健益議員質疑門禁卡出現簡體字及連結中國網站，且社宅雲 App 112 年編列 30 萬元維護費卻未更新，要求市府加強營運管理（「門禁卡的內容，英文加簡體中文……連結都到中國網站……112 年花了 30 萬元維護費……更新 0 次」）。"], "response": "都市發展局局長說明將釐清過往紀錄問題，並要求未來每次維修包含保固期間均須明確記錄與填寫報修單（「我覺得這部分我們要來改進，過去的部分我們應該要釐清，未來我們每次的維修都應該要有紀錄，包括在保固期間」）。都市發展局局長表示將聯繫里長了解電梯異常狀況，並針對門禁卡簡體字與網站問題進行查明與更換（「我們來跟里長聯繫，了解相關情形……第 1 點，我們會查明，第 2 點，我們應該立即去將他更換」）。", "response_removed": false, "topic": "廣慈博愛社宅公共設施與電梯維運管理"}, {"citations": [{"page": 2492, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=12"}, {"page": 2493, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=13"}, {"page": 2494, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=14"}, {"page": 2494, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=14"}, {"page": 2495, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=15"}], "councilor_points": ["洪健益議員指出公車過站不停為申訴案件第一名，5 年達 5,927 件且每日至少 3 件，單靠民眾招手易使駕駛分心，對身障者及學童亦具危險性（「公車 10 大申訴案件……全部都是過站不停……5 年 5,927 件，每日至少 3 件……招手會讓司機分心」）。洪健益議員建議參考高雄市與臺中市作法，在候車亭設置智慧型服務燈或放大 LED 數字號碼板，改善過站不停問題（「這個是高雄市版本的輔助公車器……這是臺中市版本……本席倒覺得可以把 LED 燈的數字號碼板放大點」）。"], "response": "公共運輸處處長說明過去曾試辦服務燈，駕駛反映觀看路線面板可能遮蔽視線或造成分心，且臺北市大站位重疊路線與班次較多（「駕駛員覺得看路線的時候有時被遮蔽……也是會分心……臺北市會過站不停的站位大部分都是大站位，所以重疊路線多、班次多」）。交通局局長表示認同招手具危險性，承諾會花時間研究臺中市作法並蒐集各縣市經驗以改良臺北市措施（「這真的很危險……我願意花點時間再去研究剛才所提到臺中市的作為與作法……我們會蒐集各縣市的一些作法來參考」）。", "response_removed": false, "topic": "公車過站不停改善與候車亭服務燈設置"}, {"citations": [{"page": 3237, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC#page=13"}], "councilor_points": ["洪健益議員指出婚後孕前健康檢查補助金額逐年下降，建議將補助時間調整至結婚前申請並於婚後核銷撥款（「補助的金額逐年往下降……希望『婚後孕前健康檢查補助』應該挪到結婚前……確定結婚之後再撥款給民眾」）。洪健益議員指出自 107 年至今婚後孕前檢查累積發現梅毒 52 人、愛滋病 36 人、披衣菌 946 人及男性精液異常比例 47%，顯示檢查之必要性（「梅毒 52 人、愛滋病 36 人、披衣菌 946 人……這是 107 年到現在，歷年累積的數字……精蟲異常比例 47%」）。洪健益議員建議將 X 染色體脆折症及脊髓性肌肉萎縮症等基因檢測項目納入檢查推廣或補助（「有一種 X 染色體脆折症……另外一個叫做脊髓性肌肉萎縮症……希望局長是不是也可以一樣納入結婚前的健康檢查項目」）。"], "response": "衛生局局長表示會將婚前申請、婚後撥款之建議納入參考（「謝謝議員的想法，我們納入參考」）。衛生局局長表示會以專業意見考量並邀請專家學者討論評估將 X 染色體脆折症及脊髓性肌肉萎縮症等基因疾病納入補助之可行性（「我們一定會去評估議員剛剛提到的 X 染色體脆折症、脊髓性肌肉萎縮症等等基因相關的疾病……我們以專業意見來考量」）。", "response_removed": false, "topic": "婚後孕前健康檢查補助與基因檢測推廣"}, {"citations": [{"page": 1541, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=7"}, {"page": 1543, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=9"}], "councilor_points": ["洪健益議員指出臺北市牛肉麵入圍米其林推薦店家從 2018 年 5 間降至 2023 年 3 間，質疑市府補助金額過低且將美食嘉年華 150 萬元預算與牛肉麵節補助 80 萬元合併計算（「2018 年 5 間，到現在 2023 年 5 年了，只剩 3 間……嘉年華加上 80 萬元牛肉麵節預算……為什麼分成 2 筆預算」）。洪健益議員建議市府重視傳統小吃行銷，應獨立編列牛肉麵節預算並擴大宣傳與舉辦規模（「牛肉麵是臺灣重要傳統小吃……要辦活動就要多元舉辦……經費與舉辦規模大小及宣傳廣度與參與人數是呈正比的」）。"], "response": "產業發展局局長與商業處處長說明今年循補助協會 80 萬元及美食推廣 150 萬元（總計 230 萬元）之模式合作推廣牛肉麵（「今年循 2 個模式，前陣子補助牛肉麵協會辦理相關競賽活動……美食推廣預算 150 萬元……總共 230 萬元」）。商業處處長表示規劃於國慶連假期間在花博長廊廣場舉辦牛肉麵嘉年華，預計帶動 5 萬至 6 萬人次以上參與並邀請全國店家展售（「今年會在國慶日前，10 月 7 號、8 號、9 號這 3 天……在花博長廊廣場……至少帶動 5 萬、6 萬以上的人次參加」）。", "response_removed": false, "topic": "臺北市牛肉麵節推廣與預算編列"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC#page=1", "transcript_pages": [4141, 4142, 4143, 4144, 4145, 4146, 4147, 4148, 4149, 4150, 4151, 4152, 4153, 4154, 4161, 4162], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE0958496B2A3891FEA093B7212D39C55BCA4060FD84790AD702F9A184DD7B02D1DE3DCEB210BC", "videos": [{"date": "2023-05-30", "group": 3}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 14, "heading": "民政部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162#page=4", "transcript_pages": [1315, 1322, 1323, 1324, 1325, 1326, 1327, 1328, 1329, 1330, 1331, 1332, 1333, 1334, 1335], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665497D0A74296D3ABDF1BB5094290136F86019AE1C3C19C4D12FA852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 14}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC#page=6", "transcript_pages": [1540, 1541, 1542, 1543, 1544, 1545, 1546], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F3836DFE0AA4D62238BF086942CE5672E30E311A68463D19DB44ADD7575AD60B02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 3}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC#page=1", "transcript_pages": [2051, 2052, 2053, 2054, 2055, 2056, 2057, 2058, 2059, 2060, 2061], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549093FEEAF32D08AD48242636FD35D6C8D71B9D53FA81350D40C0955A395AC6A2802D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 5}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC#page=10", "transcript_pages": [2490, 2491, 2492, 2493, 2494, 2495, 2496, 2497, 2498], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665496A1AAE9F35AAEF15B09B47474232653B308FD344CD0478C8B2C17FF51F77E38602D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 4}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 17, "heading": "警政衛生部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC#page=9", "transcript_pages": [3233, 3234, 3235, 3236, 3237, 3238, 3239, 3240, 3241], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654996FA5911D77BFABF1940DFEE53EA9219772BD67D16ED7E4605ADDFC1AB2AF7AA02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 17}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 9, "heading": "工務部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC#page=5", "transcript_pages": [3695, 3696, 3697, 3698, 3699, 3700, 3701], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549A20CCE6665BA6B0BE4A21447E7507E45A6A7A325DD56455774B9C7DD0CCB921502D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654960EE095