INSERT INTO "fact" VALUES('summary:14-01:p22b242559b','p22b242559b','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-02T16:06:14Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2773, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=13"}, {"page": 2774, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=14"}, {"page": 2784, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=24"}, {"page": 2787, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=27"}, {"page": 2775, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=15"}], "councilor_points": ["洪婉臻議員指出捷運沿線列管建案達「197案」、近15年遭異物入侵「386件」，質詢車廂障礙物偵測桿僅「6公分」無法感應上方懸空異物。洪婉臻議員要求市府改善軟硬體防護，包含優化「自動駕駛的感應系統」、評估增設「月台的緊急停車按鈕」、制定險阻手勢、「1個月內演練緊急狀況的應對措施」，以及建置「交通維持計畫系統」供民眾查詢。"], "response": "捷運工程局局長表示針對禁限建區域工地皆登錄管考系統巡檢，並承諾「3個月的時間做技術評估」發展輔助系統。臺北大眾捷運股份有限公司總經理說明已修改程序「授權站長」及現場人員阻止列車出發，並承諾月台緊急停車按鈕「一定會做」、「1個月內」演練應對措施及加強安全宣導。交通局局長表示認同公開交維計畫，承諾「半個月提出評估和做法的報告」。", "response_removed": false, "topic": "捷運軌道異物入侵防護與緊急應變機制"}, {"citations": [{"page": 1698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=23"}, {"page": 1700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=25"}, {"page": 1700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=25"}, {"page": 1701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=26"}, {"page": 1698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=23"}, {"page": 1701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=26"}, {"page": 1697, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=22"}], "councilor_points": ["洪婉臻議員指出成功市場改建進度僅「33%」、西寧市場「改建進度是零」、環南市場有「15次變更設計，整合為5次契約變更，預算金額從原本55億元增加到65億多元，增加10億多元」，質詢市場改建進度嚴重落後。洪婉臻議員播放錄音檔質詢市場處同仁引導廠商減項不施作飲食攤區內外場分隔牆、要求「儘量放寬」，質詢涉及「不符合GHP（食品良好衛生規範準則）」與知法犯法疑慮，要求「1週內給本質詢組調查報告」並依法辦理。"], "response": "產業發展局局長表示會釐清原始設計是否有遺漏或配合需求調整，若過程中有同仁涉及不法或疑慮「我們會調查清楚」。市場處處長說明市場改建推動困難，強調「GHP的部分，市場處有輔導團隊」，並表示對相關爭議「一定依法辦理」。", "response_removed": false, "topic": "第一果菜及環南等市場改建工程延宕檢討"}, {"citations": [{"page": 3662, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=1"}, {"page": 3665, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=4"}, {"page": 3667, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=6"}, {"page": 3664, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=3"}], "councilor_points": ["洪婉臻議員指出北市發生「15棵」路樹倒塌致民眾受傷，並指出10年來有「8,361件」路樹竄根事件，造成「3起國賠案，1件公共意外險的理賠」，質詢人行道公共安全問題。洪婉臻議員質詢北市數量最多達「1萬1,669株」的榕樹易造成道路鋪面隆起，要求公園處檢討樹種選用並於「1個月」內提出評估報告。"], "response": "公園路燈工程管理處處長說明竄根會依程度進行斷根或阻根牆等處理，表示榕樹「已經不再列為我們種在人行道的樹種」，並承諾「1個月」內提出評估報告與後續檢討。新建工程處處長說明針對「1米2以下或比較窄的人行道」會配合清查檢討移走樹穴或設置格柵。", "response_removed": false, "topic": "行道樹竄根影響公共安全與樹種選用檢討"}, {"citations": [{"page": 2908, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=12"}, {"page": 2909, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=13"}, {"page": 2910, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=14"}, {"page": 2911, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=15"}], "councilor_points": ["洪婉臻議員質詢員警涉違法案件，要求警察局用「嚴格的標準來檢視你們局內自己的人員」，並進行全面清查。洪婉臻議員指出北市警察預算員額「8,280人」、現員「7,833人」，「缺額了四百多人」，且中正區陳抗「每年都是1、2千件在計算」、萬華區勤務繁重，要求爭取足額警力。洪婉臻議員質詢民防義警招募平均年齡達「55歲」，且有裝備不合身及聯誼費扣除旅遊補助後僅剩「2,000元」等問題，要求警察局於「2個星期」內提出檢討報告。"], "response": "警察局局長表示針對違紀行為正進行全面清查，確認警力「大概缺四百人」，並說明民防義警已招募「八百多人」，承諾會整理歷年福利狀況向市府爭取編列，並於「2個星期」內提出檢討報告。", "response_removed": false, "topic": "員警違紀案件清查、警力缺額與民防配備福利檢討"}, {"citations": [{"page": 2292, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=22"}, {"page": 2294, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=24"}, {"page": 2295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=25"}, {"page": 2295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=25"}, {"page": 2296, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=26"}, {"page": 2297, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=27"}], "councilor_points": ["洪婉臻議員質詢連鎖托嬰中心「有7間，258個小嬰兒在裡面」發生不當對待事件，要求社會局開罰「30萬元」、關心家長並協助轉托。洪婉臻議員指出教室內監視器數量不足，且家長調閱面臨「14日」內申請與「30日」保存限制卻畫面缺失，建議參考新北市建置將公托畫面上傳雲端之「公托監管雲」。洪婉臻議員建議於教保與托育人員篩選機制中「往前一步」加入性向測驗或心理諮商考核，以便「在第一關就可以篩選出適合或不適合這一行的人」。"], "response": "社會局副局長表示當天對違規托嬰中心開罰「30萬元」，說明會積極聯繫家長與協助轉托，並表示對雲端監管「認同，也一直在準備當中」。教育局局長表示會協助幼兒轉托，並針對教保人員篩選加入性向測驗表示「我們可以研議」。", "response_removed": false, "topic": "托育機構不當對待事件處置與監視器監管機制"}, {"citations": [{"page": 1351, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=16"}, {"page": 1354, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=19"}, {"page": 1353, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=18"}], "councilor_points": ["洪婉臻議員質詢北市中高齡就業促進補助績效不佳，件數多落在「200件到400件」。洪婉臻議員質詢市府求職網頁對中高齡極不友善、用薪水高低分類職缺，且就業資訊「3年未更新」（最新為「109年3月31日」），要求「1周內給我檢討報告」、打破年齡歧視及宣導中高齡就業專法。"], "response": "勞動局局長說明市府推行企業認證，並承認就業資訊未即時更新確實不妥，承諾「1周內」提供檢討報告。就業服務處處長說明重複連結導致點擊多次，表示市府打算「今年改版」並重新檢視官網。", "response_removed": false, "topic": "中高齡者就業促進與友善求職網站改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=15", "transcript_pages": [1350, 1351, 1352, 1353, 1354, 1355, 1356, 1357, 1358], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 15}]}, {"dates": ["2023-04-25", "2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=21", "transcript_pages": [1696, 1697, 1698, 1699, 1700, 1701, 1702], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 9}, {"date": "2023-04-27", "group": 9}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=22", "transcript_pages": [2292, 2293, 2294, 2295, 2296, 2297, 2298], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 16}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=12", "transcript_pages": [2772, 2773, 2774, 2775, 2776, 2777, 2778, 2779, 2780, 2781, 2782, 2783, 2784, 2785, 2786, 2787, 2788, 2789, 2790], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 16}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 2, "heading": "警政衛生部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=11", "transcript_pages": [2907, 2908, 2909, 2910, 2911, 2912, 2913, 2914, 2915, 2916, 2917], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 2}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC#page=1", "transcript_pages": [3662, 3663, 3664, 3665, 3666, 3667, 3668, 3669], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549DF0789EA27D08C273049211D3624E87071758F1338CE8B8700D13DFC67E1993E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162','2026-10-02T16:06:14Z');
INSERT INTO "fact" VALUES('summary:14-01:p28d7d936d9','p28d7d936d9','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-02T16:10:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1617, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=1"}, {"page": 1621, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=5"}, {"page": 1621, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=5"}, {"page": 1620, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=4"}, {"page": 1620, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=4"}], "councilor_points": ["游淑慧議員指出，臺北農產運銷股份有限公司質譜儀抽檢比率僅約千分之一，且檢驗出農藥超標後遭人員以「校正回歸」改為合格放行流入市場，例如茼蒿驗出「歐殺滅」與「佈飛松」超標2.4倍及2.68倍卻標示合格。（引文：「因為只抽千分之一，即 1,000 件只把關了 1 件。」「把質譜儀檢驗農藥超標的數據，全部『校正回歸』為合格，繼續放行。」「自行送檢驗室檢查，果然驗出有 2 種農藥，『歐殺滅』和『佈飛松』藥劑均超標。」）  游淑慧議員表示，質譜儀校正放行達13萬公斤農藥超標蔬果，且同一天、同一機器對不同供應商的同種農藥竟有「放高超標、銷毀低超標」的不一標準，衛生局市面抽查不合格率達21.8%，遠高於北農校正後的3%。（引文：「同一天、同一種農藥、同一臺機器……為什麼超標 7 倍的過關，超標 4 倍的沒有過關？」「光是 1 號質譜儀檢驗了 849 件，其中結果農藥超標，但是被校正回歸合格放行的重量有 13 萬公斤。」「衛生局在 1 月份抽查市面蔬果的農藥殘留卻有 21.8%……其中相差了 7 倍。」）  游淑慧議員要求市府重新指派官股代表、檢討北農人事，並請政風單位介入調查，若2個星期內未答復將移送檢調。（引文：「市長是否要趕快重新指派市府的官股代表？」「要求政風單位介入調查。如果政風單位無法在 2 個星期之內給本席一個答覆，我直接把資料提供給檢調單位調查」）"], "response": "臺北農產運銷股份有限公司總經理說明，批發市場一天約抽60件（約千分之一），檢驗人員係按可調整條件修正，但未特別針對同一天同農藥放高毀低情況進行調查。（引文：「批發市場一天大概可以抽 60 件。」「大概千分之一」「檢驗人員還是按照可以調整的條件做調整。」「我沒有特別針對這一點去問。」）  市場處處長表示，完全認同議員邏輯，在同時間、品項及農藥下，無法替其說明原因。（引文：「完全認同議員的思考邏輯和想法。在同一個時間、同一個品項，同一種農藥，我也沒辦法替他……」）  產業發展局局長表示，認同議員提出若機器有問題應一致性有問題及校正應按比例之邏輯。（引文：「如果這一臺機器有問題的話，是否今天所有檢驗的東西都有問題？一致性的有問題……是。」）", "response_removed": false, "topic": "批發市場農藥檢測與質譜儀校正機制"}, {"citations": [{"page": 2015, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=2"}, {"page": 2018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=5"}, {"page": 2019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=6"}, {"page": 2017, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=4"}, {"page": 2018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=5"}], "councilor_points": ["游淑慧議員指出，潭美國小因設籍門檻高及為雙語國小導致新生超額嚴重，109至111學年度改分發至新湖、松山、西松國小等非雙語國小，造成家長跨區接送與教育資源落差。（引文：「潭美國小 109 學學年度招生人數 116 人，設籍人數 226 人……改分發人數 92 人」「潭美國小改分發的地方，主要是以下這 3 所國小，內湖區的新湖國小以及松山區的松山國小和西松國小」「改分發到其他的國小統統都是非雙語國小」）  游淑慧議員詢問，先前市府承諾於2026年完成全市國中小雙語化的目標是否會跳票，並質疑教育局採被動申請方式將使政策目標無法達成。（引文：「教育局當時在議會報告要在 2026 年完成臺北市國小雙語化的目標。」「在 2026 年完成雙語教育的政策目標是否還在？是不是還是一樣會如質如期達成？」）  游淑慧議員要求教育局重新檢視前市長卸任前提出的「雙語教育白皮書」，如實向議會提出新的轉型進度、期程與所需預算。（引文：「將……在卸任前突然拋出來的『雙語教育白皮書』重新再檢視一遍，做不到的部分就老實講」「如實如質地再給議會一個新的進度。」）"], "response": "教育局局長說明，潭美國小因新學校與雙語性質產生磁吸效應，市府會加速附近學校校舍改建；雙語政策需由學校主動申請，市府會鼓勵參加並重視質的穩定，朝2026年目標努力。（引文：「潭美國小因為是新學校，加上是雙語國小，的確會讓家長在選擇學校時產生磁吸效應」「雙語學校必須是學校自己主動來申請。」「除了量的擴充之外，質的穩定也很重要。」「我們會朝這個目標努力。」）  教育局中等教育科科長說明，當時希望2026年全北市學校達標，但政策會進行滾動式修正，白皮書由雙語辦公室並找學者專家共同編寫。（引文：「當時是有提到 2026 年的時候，希望臺北市全部學校可以都達標，但是這個政策會做一個滾動式的修正。」「我們雙語辦公室有負責編……我們還有找學者、專家。」）", "response_removed": false, "topic": "國小新生超額改分發與雙語教育政策推動"}, {"citations": [{"page": 3006, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=1"}, {"page": 3007, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=2"}, {"page": 3009, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=4"}, {"page": 3011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=6"}, {"page": 3011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=6"}, {"page": 3007, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=2"}, {"page": 3009, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=4"}, {"page": 3010, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=5"}, {"page": 3008, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=3"}], "councilor_points": ["游淑慧議員指出，衛生局抽檢日本進口草莓農藥不合格率達3至4成，卻僅於專區公布合格資訊、隱匿不合格資訊，質疑此舉為蓋牌。（引文：「今年 1、2 月草莓的抽驗量，不管是本地還是進口草莓，不合格率大約都在 3 到 4 成左右」「合格的有放，不合格的沒放」「要公布就合格及不合格都公布，這樣不是蓋牌嗎？」）  游淑慧議員指出，食材登錄平台運作4年來資訊東缺西缺，業者自主登錄缺件或未更新檢驗報告，市府未落實查核管理。（引文：「花這麼多錢建立一個資訊東缺西缺的平臺，而且已經這麼多年了……到現在 112 年已經 4 年了」「自主提供檢驗報告更新中，這也就等於沒有」）  游淑慧議員建議，衛生局應改變在市面盲目抽查的方式，直接針對北農已檢驗合格放行的蔬果進行源頭抽查與把關。（引文：「何必還要到市面上去抽查呢？直接抽查北農不就好了嗎？」「就應該針對北農檢驗過合格的抽查」）"], "response": "衛生局食品藥物管理科科長說明，不合格訊息係以每月新聞稿發布並放在食藥粧網路地圖抽驗專區，針對議員建議會檢討將結果納入食材登錄平台；平台超過1年的檢驗報告均已要求下架重新檢驗，疫情期間雖未實地查核但網站巡視未停。（引文：「公告的方式有兩種，一種是每月發布的新聞稿……另一種方式是食藥粧網路地圖」「我們會再檢討，看看怎麼把抽驗結果納到食材登錄平臺」「超過一年以上的檢驗報告，我們都會要求他們下架再重新檢驗。」「這幾年確實沒有實地查核，但是網站巡視未停過。」）  衛生局局長表示，對於日本草莓與細節部分不夠專業，會再加強了解，並承諾將研議直接抽查北農合格蔬果之作法。（引文：「對於日本草莓這一部分我的確沒有那麼專業。」「這部分我會再加強。」「議員提的方式我們回去會研議看看。」）", "response_removed": false, "topic": "進口食品農藥檢測資訊公開與食材登錄平台管理"}, {"citations": [{"page": 3561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=8"}, {"page": 3562, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=9"}], "councilor_points": ["游淑慧議員指出，工務局代辦工程多達65件、金額達817億元，已遠超本業負荷，導致管理疏漏。（引文：「你們現在總共代辦的工程有 65 件，金額高達 817 億元，比你們本業多好幾倍」「當你代辦這麼多……就會發生像這個案例一樣，你們會疏於管理」）  游淑慧議員表示，音樂與圖書中心興建工程經費從原本30多億元膨脹至將近80億元，被議會刪減至63億元後，規劃設計預算又在61億元與67億元間上下變動，質疑工程預估方法不實。（引文：「告訴我們只需要 30 多億元……送到議會的時候已經將近 80 億元」「刪到工程費剩 63 億元」「半年前廠商可以用 61 億元得標，半年後設計出來後說……又變回 67 億元」）  游淑慧議員質疑，圖書館與音樂中心造價不應各認一半，要求市府釐清係由需求單位或代辦單位負責預算估算。（引文：「圖書館怎麼會需要造價這麼高？需要花費 30 多億元，現在變成音樂中心是 30 多億元、圖書館是 30 多億元。」「到底誰該負責？到底是提需求的單位該負責，還是估預算的單位該負責？」）"], "response": "工務局局長說明，代辦工程817億元為全部計畫總額，單年度約為本業的兩倍，已請總工程司檢討濃縮代辦件數，目前音樂中心與圖書館的預算比例已切開為56%與44%。（引文：「817 億元指的是全部所有計畫」「差不多是本業的 double」「把應該要代辦的再更濃縮」「現在音樂中心和圖書館的比例……56%和 44%」）  水利工程處處長說明，音圖需求係依文化局與教育局提供進行估算，廠商招標時估算61億元，但基本設計出來後真實估算金額已達67億元，未來仍需透過公開招標決定價格。（引文：「這個需求都是依照文化局和教育局的需求來檢視。」「61 億元是廠商來招標當時的估算，但事實上，到基設出來後，真實的估算金額已達 67 億元。」「最後，還是要透過公開招標來決定合議的價格。」）", "response_removed": false, "topic": "工務局代辦工程管理與音樂圖書中心預算規劃"}, {"citations": [{"page": 1227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=35"}, {"page": 1228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=36"}, {"page": 1229, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=37"}, {"page": 1230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=38"}], "councilor_points": ["游淑慧議員指出，社會局對敬老愛心卡預算編列不足額，111年度46萬7千張有效卡若足額應編26.92億元，卻僅編列12.74億元（約47%），存在嚴重執行風險。（引文：「111 年度的有效卡數是 46 萬 7 千張卡，如果你 480 元足額編列 12 個月應該編列 26.92 億元」「但是你們偷吃步，只編列的 12.74 億，只編列了 47%」）  游淑慧議員表示，市府因顧慮預算不足而限縮使用範圍，導致長輩每月480點使用率過低，點數全數用完者僅約5%至7%。（引文：「因為你們把老人卡、敬老卡的使用範圍限縮了」「全部使用完的部分來講，大概這幾年來大概只有 5%到 7%左右」）  游淑慧議員建議，應開放敬老愛心卡點數按年累積，並比照外縣市開放折抵市立聯合醫院門診掛號費，若市府持續怠惰將提自治條例處理。（引文：「每個月沒有使用完的 480 點能不能累積？一年結算一次」「敬老愛心卡應該可以開放門診，或復健費折抵，或者是最少聯醫可以開放」「必要時我也可以提自治條例」）"], "response": "社會局局長說明，預算係依零基預算概念及過去使用率編列，今年已增加台鐵、輕軌、貓纜及計程車抵扣點數（約增加7千8百多萬元預算）；點數累積涉及卡片歸零設計與跨縣市合作問題，會於會期結束前給予答復，並已在規劃門診折抵事宜。（引文：「預算編列裡面有所謂的零基預算的概念。」「今年擴大敬老卡的使用範圍，包括要納入台鐵、輕軌及增加提高計程車的抵扣點數……還有貓纜」「增加預算的部分，大概會是在 7 千 8 百多萬元左右」「這個我們來研議」「這個會期結束前，可不可以給議會答覆？……好」「這一部分我們確實有在做規劃。」）", "response_removed": false, "topic": "敬老愛心卡使用範圍限制與預算編列"}, {"citations": [{"page": 2745, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=22"}, {"page": 2746, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=23"}, {"page": 2744, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=21"}], "councilor_points": ["游淑慧議員詢問，內湖科學園區交通短期改善措施之推動進度，包括發放彈性上下班問卷數量、捷運早晚鳥4折優惠實施時程，以及公車加密班次狀況。（引文：「『鼓勵企業彈性上下班分流』，請問你們去做了嗎？」「『臺北捷運提供早晚鳥票 4 折的優惠』，這個部分要怎麼實施？」「『加密公車班次』呢？你們增加多少班次？」）  游淑慧議員指出，市府僅發出千餘份問卷且未與企業面對面溝通，且市長視察4個月後捷運早晚鳥優惠仍僅停留在構想階段，執行過於被動。（引文：「連員工在內，才發一千多份問卷？」「你們都沒有去和協會面對面的溝通」「在今年 1 月的時候就已經到內湖科學園區視察，沒想到 4 個月後，你告訴我『臺北捷運提供早晚鳥票 4 折的優惠』目前只是一個構想。」）"], "response": "交通局局長說明，已發放一千多份問卷（企業約兩百多件，已有兩百多家回覆），預計5月提供調查報告，6月由副市長陪同與協會溝通；捷運早晚鳥4折優惠將視問卷意願決定是否實施；加密公車部分已在尖峰時間增加12個班次，綠運輸政策將於下半年推行。（引文：「問卷……一千多份……企業界的問卷大概有兩百多件」「目前大概有二百多家的企業有回覆」「6 月的時候，副市長也會陪同我們一起過去商談」「如果員工大部分都願意來買單，我們再來做這個措施」「增加 12 個班次」「綠運輸就是下半年要推行的政策」）", "response_removed": false, "topic": "內湖科學園區交通改善措施與推動進度"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 10, "heading": "民政部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=32", "transcript_pages": [1224, 1225, 1226, 1227, 1228, 1229, 1230, 1231], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 10}]}, {"dates": ["2023-04-25"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=1", "transcript_pages": [1617, 1618, 1619, 1620, 1621], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 7}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=1", "transcript_pages": [2014, 2015, 2016, 2017, 2018, 2019, 2020], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 4}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=21", "transcript_pages": [2744, 2745, 2746, 2747, 2748, 2749, 2750, 2751, 2752], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 15}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=1", "transcript_pages": [3006, 3007, 3008, 3009, 3010, 3011, 3012], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 6}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 4, "heading": "工務部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=1", "transcript_pages": [3554, 3555, 3556, 3557, 3558, 3559, 3560, 3561, 3562, 3563], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 4}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162','2026-10-02T16:10:19Z');
INSERT INTO "fact" VALUES('summary:14-01:p32da79905a','p32da79905a','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-02T16:12:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1678, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=3"}, {"page": 1681, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=6"}, {"page": 1681, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=6"}, {"page": 1680, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=5"}], "councilor_points": ["王孝維議員指出內湖湖興里有 6 座天然氣儲氣槽已存在 40 幾年，鄰近醫院與高樓住宅，讓居民天天擔心害怕 （「內湖地區有 6 座天然氣儲氣槽……這些儲氣槽已經存在四十幾年了……對面是三軍總醫院，裡面住了好多的病人……後面全部是高樓大廈，住滿了居民……居民天天都在擔心害怕」）。王孝維議員建議產業發展局應展現魄力與擔當，比照其他瓦斯公司設於山區之模式，將內湖市區的儲氣槽儘速遷移至人煙稀少處 （「產業發展局要有這個魄力，要有擔當……為什麼欣湖公司的儲氣槽可以設在山上……產業發展局可以比照欣湖瓦斯公司的模式……設在人煙稀少的山谷，然後接管下來……只希望產業發展局能夠將瓦斯儲氣槽儘快遷移」）。王孝維議員要求市府先將作為備用的 2 座儲存槽於今明兩年遷移 （「大台北瓦斯公司說 6 座儲氣槽要減為 4 座，現在將 2 座做為備用儲存槽。這樣好了，今年和明年把這 2 座儲存槽遷移，只留 4 座，可以嗎？」）。"], "response": "產業發展局局長說明因時空背景與過去不同，在供氣穩定的情況下儲氣槽應該要遷移，會持續朝此方向逐年把儲氣槽遷移離開目前位置 （「確實現在內湖的時空背景和過去不太一樣了……在供氣穩定的情況之下，瓦斯儲氣槽應該要遷移……產業發展局會持續朝這個方向，逐年把儲氣槽遷移離開目前的位置」）。產業發展局局長表示關於先遷移 2 座備用儲存槽部分，仍需與大台北瓦斯公司溝通處理 （「這部分產業發展局還是要和大台北瓦斯公司溝通如何處理」）。產業發展局副局長說明天然氣比重比空氣輕，若洩漏會垂直往空中排放，相對不會往左右兩邊對社區有直接影響 （「天然氣洩漏的話，會直接往空中排放……比重比空氣輕……它是會垂直往外洩，相對來講的話，不會往左右兩邊，對社區不會有直接有影響」）。", "response_removed": false, "topic": "內湖瓦斯儲氣槽遷移"}, {"citations": [{"page": 2281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=11"}, {"page": 2283, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=13"}, {"page": 2282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=12"}, {"page": 2282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=12"}, {"page": 2284, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=14"}], "councilor_points": ["王孝維議員指出臺北市實驗學校與機構持續增加，但軟硬體資源不足，恐影響學生學習權並導致教育 M 型化 （「缺點有學校或機構一直在增加，但是這些軟、硬體好像也不太夠，學生的學習權就會有不確定性……受教權已經 M 型化……但如果變成 M 型化的教育，那問題就大了」）。王孝維議員詢問實驗學校在校舍重建、設備設施更新、校長遴選、師資素養及升學銜接等層面是否有完整規劃，並要求不能將學生當成白老鼠 （「我提出的第 1 個問題和第 2 個問題，是所有的資源、經費，有沒有運用在校舍的重建與設備、設施的更新？第 3個問題是校長的遴選資格是什麼？第 4 個問題是行政組織與教師素養以及教師的動能？……學生的學校銜接怎麼辦？……你們不能將學生當成白老鼠實驗」）。王孝維議員詢問若實驗學校評鑑不佳時，市府是否有相應的退場機制 （「如果實驗學校評鑑不佳怎麼辦？有什麼樣的機制可讓它退場？」）。"], "response": "教育局局長說明臺北市公立實驗學校共有 11 所，非學校型態學生有 3,196 名，實驗學校最重要的是設定特定的教育核心理念並依課程規劃環境設備 （「實驗學校現在總共有 11 校……非學校型態的學生大概有 3,196 名……實驗學校最重要的是要有一個特定的教育理念，這是最核心的部分……在環境、設備上做一些規劃與相應」）。教育局局長說明實驗教育以 6 年為 1 個期程，若實驗效果不好會辦理評鑑確定實施結果，等同要退場 （「實驗教育有期程。比如說 6 年 1 個期程……如果實驗的效果不好等同要退場，只是我們會辦理評鑑來確定實施的結果如何」）。", "response_removed": false, "topic": "實驗教育推動與品質監督"}, {"citations": [{"page": 2792, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=32"}, {"page": 2793, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=33"}], "councilor_points": ["王孝維議員指出內湖科學園區工作人口達 13 萬 3,000 人，其中內湖區私人運具高達 4 萬 8 千輛，是造成交通壅塞的主要原因 （「請問 13 萬 3,000 的工作人口來到內湖，基本上他們的交通工具是什麼？……最大的問題是什麼？私人的運具……內湖……4 萬 8 千輛」）。王孝維議員要求交通局應務實探討民眾使用私人運具開車來到內科的原因，並提出解決內部交通問題的具體方案 （「你要去探討這個原因，才有辦法改進內湖、內科的交通……回復務實的行動和行為，解決內湖區內科的交通」）。"], "response": "交通局局長說明內科塞車主因包含平日下午尖峰港墘路上高速公路車輛回堵、區內交通工程有改善空間及上班族開車比率高 （「最重要的根節在於港墘路要上高速公路，在平日下午的尖峰，車輛根本上不去，常常造成回堵……第 2 個，區內的一些交通工程應該有些改善的空間；第 3 個，科學園區的上班族開車的人的比率也滿高的」）。交通局局長表示已針對內科員工進行問卷調查，預計於 5 月底前完成使用運具狀況與原因之交叉分析報告並向質詢組說明 （「這邊剛好就是有做一份內科員工的問卷，他們使用運具的一些狀況……5 月底我再給議員的質詢組，所看到的初步的探討再向議員說明」）。", "response_removed": false, "topic": "內湖及內科交通改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162#page=23", "transcript_pages": [1358, 1359, 1360, 1361, 1362], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654985A07A6EBCECAD7C8C518C2522EF3C24832BD39E32F67013A852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 15}]}, {"dates": ["2023-04-25", "2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC#page=1", "transcript_pages": [1676, 1677, 1678, 1679, 1680, 1681, 1682, 1683], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549712E5B8C55065C1A7E231D8DBB8F38D19BE52339B35298C3749A478D02E1007B02D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 9}, {"date": "2023-04-27", "group": 9}]}, {"dates": ["2023-05-05"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC#page=10", "transcript_pages": [2280, 2281, 2282, 2283, 2284, 2285], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549180AF986513C3C4DB09B47474232653B0587BC916E19B2944816FDCC75956D7602D1DE3DCEB210BC", "videos": [{"date": "2023-05-05", "group": 16}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC#page=31", "transcript_pages": [2791, 2792, 2793, 2794, 2795, 2796], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549688781A4F912B631E3F2CD48328CF4FFD79CFF7449F2693F7C6E015549E3D81402D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 16}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 2, "heading": "警政衛生部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC#page=7", "transcript_pages": [2903, 2904, 2905, 2906, 2907], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665491D2F541EB4ADA4CB3A0A3049603B013F8FAD317FC2D48654944B9B0DFB7D794902D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 2}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.