INSERT INTO "fact" VALUES('summary:14-01:pea1a4317b4','pea1a4317b4','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-02T16:14:12Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4349, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=27"}, {"page": 4350, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=28"}, {"page": 4350, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=28"}, {"page": 4352, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=30"}, {"page": 4352, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=30"}, {"page": 2139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=23"}, {"page": 2140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=24"}, {"page": 2137, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=21"}, {"page": 2137, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=21"}, {"page": 2138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=22"}, {"page": 2138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654911C915EF6BDFFF25C12475E94E12141DFDC3C04D2A5454F1C3387ED607876BBC02D1DE3DCEB210BC#page=22"}, {"page": 4351, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=29"}, {"page": 4353, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=31"}], "councilor_points": ["王欣儀議員指出學校營養午餐面臨物價上漲與價格調漲壓力，建議臺北市政府適度加碼補助以減輕家長負擔，並比照其他縣市爭取國小附設幼兒園中央「三章一Q」全額補助。王欣儀議員建議每週增加有機根莖菇類食材並放寬副菜限制，同時建置公開透明的校園食安通報平台。王欣儀議員表示近年營養午餐違規與異物事件頻傳，要求提高扣點罰金、檢討記點制度、建立備援廠商機制並加聘專業食品技師。"], "response": "市長表示會請教育局全面研議營養午餐補助方案，並參考其他縣市做法，同時積極向中央爭取幼兒園補助。教育局局長說明新學年度將在既有品項中增加有機菇類等食材，並研議建置食安通報平台、提高違規罰責、檢討記點與備援廠商機制。", "response_removed": false, "topic": "學校營養午餐管理與食安補助機制"}, {"citations": [{"page": 4355, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=33"}, {"page": 4356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=34"}, {"page": 3614, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=3"}, {"page": 3615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549BC1B5245771714698580DC0E2417E4F6EB81E659B69DBEDBD2E45818D86ECEAF02D1DE3DCEB210BC#page=4"}, {"page": 4356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=34"}, {"page": 4357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=35"}, {"page": 4358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=36"}], "councilor_points": ["王欣儀議員指出臺北市抽水站委外標案長期由兩家公司輪流承攬且人員近九成相同，甚至有被解僱員工代表公家刊登不實徵人廣告，涉嫌聯合壟斷與違法招募。王欣儀議員質疑水利處內部人事管理鬆散、曾發生漏油與值班打電玩等弊端，要求市府移送政風處深入調查，並檢討防汛期間推動「大分區輪班計畫」的安全疑慮。"], "response": "市長表示若有任何不法情事絕不容忍，會請政風處深入調查並依法查辦。工務局局長與水利工程處處長說明將要求廠商限期說明、移送政風室調查，並對有不良紀錄人員進行管控；水利工程處處長補充大分區制度目前僅進行巡查，防汛期應急操作仍會在原熟悉車站進行。", "response_removed": false, "topic": "抽水站委外營運監督與人事管理弊端"}, {"citations": [{"page": 1174, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=20"}, {"page": 1175, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=21"}, {"page": 1176, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=22"}, {"page": 1176, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=22"}, {"page": 1177, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=23"}, {"page": 1178, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=24"}, {"page": 1179, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=25"}, {"page": 1175, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=21"}, {"page": 1179, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=25"}], "councilor_points": ["王欣儀議員建議彈性調整里長國外考察補助機制，允許里長選擇一次使用全額 5 萬 5,000 元補助前往歐美考察，並要求明定合理契約訂金、設定考察主題及恢復區公所主管隨團。王欣儀議員指出臺北市鄰長自強活動補助費僅 1,210 元為六都最低且 8 年未調整，要求市府提高補助至與新北市、桃園市相同的 3,840 元。"], "response": "民政局局長說明規劃將每 2 年的考察補助由 2 萬 7,500 元調高為 3 萬元（4 年共 6 萬元），針對預算是否留用及恢復區公所主管隨團將帶回研議，並承諾檢討契約訂金與設定考察主題。民政局局長表示已簽核同意將鄰長自強活動費提高至 3,840 元，待核准後編列預算送議會審議。", "response_removed": false, "topic": "里長國外考察與鄰長自強活動補助"}, {"citations": [{"page": 3004, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=25"}, {"page": 3004, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=25"}, {"page": 3005, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654956EE2C16B20A861B7F246278F0BF16F9967F25042EB590B5CBCA1F6B67D7104202D1DE3DCEB210BC#page=26"}], "councilor_points": ["王欣儀議員指出文山第一分局木柵派出所及興隆派出所等建物使用逾 40 年，存在嚴重漏水、壁癌、空間狹窄及械彈室人均面積不足等問題，要求市府推動警舍改建以善待基層員警。"], "response": "警察局局長說明文山第一分局已呈報市府會議規劃改建，興隆派出所將請結構技師進行評估，短期內會先盤點並調整現有可用空間。", "response_removed": false, "topic": "老舊警舍改建與員警辦公環境改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-02"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC#page=23", "transcript_pages": [4345, 4346, 4347, 4348, 4349, 4350, 4351, 4352, 4353, 4354, 4355, 4356, 4357, 4358], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549C4EE05BFA810FE2759661F4B5187A9D1D2740CE5D71ADC30C99C613E5FC2859B02D1DE3DCEB210BC", "videos": [{"date": "2023-06-02", "group": 8}]}, {"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162#page=20", "transcript_pages": [1174, 1175, 1176, 1177, 1178, 1179, 1180], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654950BFCA2460AB97BA93F3CB971D71653DBC8B039638F773D3A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 8}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665499276B0DB24AD507D191BDBDDEEAE1430C489FBE68EF3CFC7BD451E44949D6D2C02D1DE3DCEB210BC#page=1", "transcript_pages": [1783, 1784, 1785, 1786], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1A