INSERT INTO "fact" VALUES('summary:14-01:pd697b2a2b5','pd697b2a2b5','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T00:50:22Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=31"}, {"page": 2044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=31"}], "councilor_points": ["鍾小平議員指出南門國中與弘道國中均招收 4、500 位學生，僅差幾十個名額即額滿，詢問是否有方法解決每年幾十人的就學需求。議員表示南門國中與弘道國中皆為第二次分發後增加幾十個名額才額滿，要求教育局慎重通盤考量。"], "response": "教育局局長說明第一次額滿學校若劃為共同學區會排擠原學區，故基本上不予考量，但目前已在討論與研議非第一次額滿（如第二次分發才額滿）之學校可考量劃為共同學區。教育局局長表示會慎重通盤考量。", "response_removed": false, "topic": "第二次分發額滿學校劃設共同學區之研議"}, {"citations": [{"page": 2044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=31"}], "councilor_points": ["鍾小平議員指出新北市購屋者可透過購買小套房設籍，致使長期租屋者無法競爭，建議教育局建立入學排序機制。"], "response": "教育局局長表示「是」。", "response_removed": false, "topic": "外縣市購屋設籍與入學順序排序機制"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 10, "heading": "民政部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 10}]}, {"dates": ["2023-04-25"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 7}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=30", "transcript_pages": [2043, 2044], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 4}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 15}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA4