INSERT INTO "fact" VALUES('summary:14-01:p67335d29b9','p67335d29b9','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T00:52:50Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2753, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=30"}, {"page": 2754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=31"}, {"page": 2754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=31"}, {"page": 2756, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=33"}, {"page": 2755, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=32"}, {"page": 2756, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=33"}, {"page": 2757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=34"}, {"page": 2757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=34"}, {"page": 2758, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=35"}, {"page": 2758, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=35"}, {"page": 2759, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=36"}, {"page": 2759, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=36"}], "councilor_points": ["鍾沛君議員指出捷運大安站共構大樓進行高空吊掛施工，許可時間為上午 10 時至下午 16 時，但傍晚 17 時 40 分仍在上址施工，超時整整 100 分鐘且現場缺乏監管，質疑相關單位未落實監督與即時通報。鍾沛君議員表示現場施工吊車位於站體與高架軌道之間，要求捷運主管機關跨局處建立周邊工程監管與 Check list 機制，並於 5 月底前提出具體做法。鍾沛君議員質疑捷運站內禁止民眾面交卻許可擺攤展售之標準「因人設事」，建議商業行為不應進入付費區。"], "response": "臺北大眾捷運股份有限公司站務處處長說明施工單位進場時有出示警察局申請書及工務局會勘紀錄，現場並有架設圍籬。臺北大眾捷運股份有限公司總經理回應表示公司無公權力，但關注危害路權並會通報相關單位處理，後續將檢討系統強化的管理流程，並表達工程施工應避免尖峰或繁忙時間。捷運工程局局長說明依大眾捷運法得請違規施工單位停工，並承諾檢討非新建工程作業流程，加註禁限建範圍審查 Check list，於 5 月底前向議員報告具體做法。臺北大眾捷運股份有限公司總經理說明依規定禁止「未經許可」商業行為，展售活動需經安全及動線審查且部分獲利需回饋公部門，若質詢對短期展售有疑慮將從善如流進行研究。", "response_removed": false, "topic": "捷運禁限建範圍施工監管與站內商業行為規範"}, {"citations": [{"page": 3031, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=26"}, {"page": 3032, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=27"}, {"page": 3033, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=28"}, {"page": 3035, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=30"}, {"page": 3034, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=29"}, {"page": 3034, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=29"}, {"page": 3032, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=27"}], "councilor_points": ["鍾沛君議員指出文山第一分局偵查隊於 112 年 1 月 4 日傍晚在勤 19 人中有 13 人跑去轄區外吃尾牙，質疑「翹班率 68%」造成勤務嚴重瑕疵。鍾沛君議員揭露分局同仁出勤紀錄有多種筆跡涉嫌代簽與偽造文書，且後續月份仍持續發生代簽情事，要求警察局檢討內部管理與幹部責任。鍾沛君議員詢問懲處層級與法治教育宣導狀況，質疑檢討報告稱「從重處理」卻與其他案例懲處相差無幾，要求落實懲處與改善勤惰管理風氣。"], "response": "警察局文山第一分局分局長說明該事件可能為個案。警察局局長承認該狀況為重大的勤務瑕疵，主因為幹部內部管理出問題，並說明已將偽造文書代簽者移送法辦，未來將精進電子化簽到退管理、減少手寫板並實施抽測。警察局副局長與警察局局長說明主官考核監督責任處分規定，並表示幹部部分已從重予以記過處分，相關案例會納入法紀教育教材。", "response_removed": false, "topic": "警察局勤惰管理與警紀督導懲處"}, {"citations": [{"page": 3035, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=30"}, {"page": 3581, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=28"}, {"page": 3582, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=29"}, {"page": 3583, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=30"}, {"page": 3584, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=31"}, {"page": 3585, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=32"}], "councilor_points": ["鍾沛君議員指出臺北市設籍人口呈現下滑趨勢，但都市計畫通盤檢討推估 132 年總人口達 289 萬人過於樂觀，且引用國發會 105 年及民政局舊數據，導致推估基礎失真落差達 40 萬至 60 萬人。鍾沛君議員指出都市計畫常住人口推估仍採用 99 年普查數據，未跟進採用電信信令數據，要求都市發展局務實更新數據並排定修正時程。鍾沛君議員指出工務局工作報告重複列入 110 年上半年度已竣工之工程內容，要求提升工作報告品質並加強事前審核。"], "response": "都市發展局局長承認人口推估確實過於樂觀且引用數據未與時俱進，說明目前啟動之全市性通盤檢討會將最新人口數據納入務實調整，預計 114 年進行公開展覽。工務局局長承認將超過半年期之已竣工案件列入工作報告係屬缺失，承諾後續深切檢討改進。", "response_removed": false, "topic": "都市計畫人口數據引用與工務局工作報告內容"}, {"citations": [{"page": 1213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=21"}, {"page": 1215, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=23"}, {"page": 1216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=24"}, {"page": 1217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=25"}, {"page": 1217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=25"}, {"page": 1218, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=26"}], "councilor_points": ["鍾沛君議員指出 112 年 2 月發生殯儀館冰櫃不足、暫放禮廳及租用貨櫃情況，質疑未來死亡人口增加下第二殯儀館興建設施量能是否充足，並建議蔣市長於雙北市長會議提出殯葬資源盤點合作。鍾沛君議員詢問第二殯儀館地下停車位規劃，以及第一殯儀館拆除進度與後續土地規劃。鍾沛君議員指出第一殯儀館周邊約 80 幾家殯葬業者，提醒第二殯儀館周邊無商二至商四區位條件，要求殯葬管理處於拆除過程中進行詳細調查並加強稽查防範違規。"], "response": "殯葬管理處處長說明臺北市 10 年內預計 2.3 萬人死亡，現有設施量能在 5 到 7 年內可支應，坦言雙北合作現狀因新北市設施擴充困難而不對等，並表示空間允許下會繼續租用貨櫃作為備案。殯葬管理處處長說明第二殯儀館地下室 B3、B4 將提供約 254 個民眾停車位；第一殯儀館預計 113 年 1 月正式營運後於春節後拆除，短期先做簡易綠美化及暫做停車場，中長期由都市發展局規劃。殯葬管理處處長說明第一殯儀館周邊約 80 幾家業者大部分傾向留在原地，市府會加強稽查，並討論評估第二殯儀館周邊是否有適合場地合作用途，後續會再調查業者看法。", "response_removed": false, "topic": "殯葬設施服務量能與第一殯儀館拆除規劃"}, {"citations": [{"page": 1652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=36"}, {"page": 2048, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=35"}, {"page": 2049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=36"}, {"page": 2050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=37"}, {"page": 2049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=36"}, {"page": 2050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=37"}], "councilor_points": ["鍾沛君議員指出文山區溪口國小營養午餐出現螺絲釘與尼龍繩，力行國小於 111 年 12 月因廠商內控等因素導致學童喝到餿水湯，質疑對廠商罰款 2 萬 6,000 元及記點懲處不成比例。鍾沛君議員指出現行契約範本需一般違約累計 50 點、重大違規累計 20 點才能解約，質疑門檻過高無法阻絕違規廠商，要求於下一個學年度前提出新版契約範本並提高重大違規記點比例。鍾沛君議員指出該供餐廠商同時供應周邊 4 所國小，質疑停止供餐機制未能根本解決廠商 SOP 散漫問題，詢問同業公會協力支援機制運作情形。"], "response": "教育局局長說明力行國小事件主因廠商內控出問題，當時已處罰停止供餐，並坦言食物敗壞屬嚴重違規。教育局局長承諾檢討合約記點內容與規準，提高學校參考標準，並表示會在下一個學年度換約前檢討提出新版本。教育局局長說明學校亦需加強督導與營養午餐 SOP 流程管控，並說明當單一廠商出狀況時會請臺北市餐盒食品同業公會進行協力支援。", "response_removed": false, "topic": "學校營養午餐食品安全與委外契約罰則"}, {"citations": [{"page": 1211, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=19"}, {"page": 1212, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=20"}, {"page": 1212, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=20"}, {"page": 1213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=21"}, {"page": 1213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=21"}], "councilor_points": ["鍾沛君議員指出臺北市人口跌破 250 萬人致副市長及副秘書長減少 1 人，詢問 112 年 4 月或 5 月人口回升達標機會，以及市府對增設第 3 位副市長與副秘書長人選之準備與領域建議。鍾沛君議員指出國發會報告推估最快 116 年臺北市人口將再次跌破 250 萬人，詢問市府民政局之因應對策。鍾沛君議員詢問研究發展考核委員會及民政局，新成立之「人口對策委員會」組織架構，以及針對臺北市環境量能精算最適宜居人口數之研究進度。"], "response": "民政局局長說明 4 月無法達標，預估 5 月底有機會回升至 250 萬人，因目前僅差約 3,000 人。秘書長兼秘書處處長說明若人口達標需先行文內政部請示，增置人選由市長依市政藍圖重行定位思考，並建議常任文官副秘書長需具文官資格且嫻熟市政。民政局局長說明將結合「催生」、「助養」、「好住」等政策；研究發展考核委員會主任委員說明未來方向為追求人口最適化，人口對策委員會預計 6 月由民政局主政運行。民政局局長與研究發展考核委員會主任委員補充說明人口對策委員會經市長核定預計 6 月底成立，由市長擔任主任委員並分 3 組、12 個局處參與，將精算白天與晚上落差 70 萬人之當日人口變化，研究宜居最適人口數。", "response_removed": false, "topic": "臺北市人口趨勢與人口對策政策規劃"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 10, "heading": "民政部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=18", "transcript_pages": [1210, 1211, 1212, 1213, 1214, 1215, 1216, 1217, 1218], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 10}]}, {"dates": ["2023-04-25"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=31", "transcript_pages": [1647, 1648, 1649, 1650, 1651, 1652], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 7}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=34", "transcript_pages": [2047, 2048, 2049, 2050], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 4}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC#page=30", "transcript_pages": [2753, 2754, 2755, 2756, 2757, 2758, 2759, 2760], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665492E2FF70B480D6BC66D3396F29A5CFE0B7BFB2C180A4A3396BB7FB8711BE8452002D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 15}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=24", "transcript_pages": [3029, 3030, 3031, 3032, 3033, 3034, 3035], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 6}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 4, "heading": "工務部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC#page=28", "transcript_pages": [3581, 3582, 3583, 3584, 3585], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549E245FD8388CB9E0D151DE57401A3E69AE18BB16A7ADA48AB12A08514EEA368F702D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 4}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162','2026-10-03T00:52:50Z');
INSERT INTO "fact" VALUES('summary:14-01:p54ba4cd655','p54ba4cd655','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T00:55:22Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4268, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=22"}, {"page": 4269, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=23"}, {"page": 4269, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=23"}], "councilor_points": ["闕枚莎議員指出臺北市推動雙語教育面臨師資不足等瓶頸，建議重新啟動「臺北英語專案辦公室」做為跨局處溝通橋樑，並以南港區作為優先示範區。議員要求研議更完善的雙語教師師資獎勵制度，並主張在天文館、兒童樂園或動物園等場域擴大辦理暑期創意英語夏令營。此外，議員建議每年召開國中小雙語教育咖啡論壇，全面落實校園雙語標示，提出短中長期精進策略，並規劃各校國際雙語教育課程交流，試辦南港區學校與國立科學工業園區實驗高級中學進行資訊交流。"], "response": null, "response_removed": true, "topic": "雙語教育推動與英語友善城市建置"}, {"citations": [{"page": 2447, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=18"}, {"page": 2445, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=16"}], "councilor_points": ["闕枚莎議員指出臺北市市民以機車與捷運為主要交通工具，要求捷運局針對民生汐止線與環狀線東環段提出加速推動計畫。議員建議評估將捷運信義線地下化東延至南港花園社區、中央研究院及汐止地區，或研議銜接地下化拉至板南線的可行方案，以解決南港交通問題。議員亦建議在環狀線東環段港墘站站體增設親子數位圖書館，並要求捷運公司研議持續推出兒童節限量紀念悠遊卡及於南港車站展示親子彩繪列車廂。"], "response": "捷運局局長說明已向市長建議將汐東線核定系統往西延伸，自東湖直接推至大稻埕，並由臺北市政府主導都市計畫開發；同時說明東環段細部設計希望由一年半縮短至一年內完成，並同意就信義線東延或延伸至板南線之方案配合進行評估研議，大港墘公園站體設置親子數位圖書館部分亦會嘗試規劃。捷運公司總經理表示將於一個月內研議於南港車站展示親子彩繪列車廂等建議。", "response_removed": false, "topic": "捷運路網規劃與大眾運輸服務"}, {"citations": [{"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=1"}, {"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=1"}, {"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=1"}, {"page": 2957, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=1"}, {"page": 2961, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=5"}], "councilor_points": ["闕枚莎議員指出市立聯合醫院醫療技術良好，但整體醫療照護環境較為老舊不便。議員舉出美國亨利福特醫院、泰國康明國際醫院及桃園敏盛智醫城等案例，建議參考其飯店式管理與人性化規劃，配合東區門戶計畫於南港區尋地重新建置全新的忠孝院區，做為市立聯合醫院的示範醫院，並啟動市立聯合醫院十年精進計畫。"], "response": "衛生局局長說明環境舒適確實有助於病患康復，並表示忠孝院區因屬氯離子濃度較高的建築，未來改建時會納入人性關懷、藝術人文、智慧醫療及ESG概念。市立聯合醫院院長對此建議表示認同。", "response_removed": false, "topic": "市立聯合醫院環境改造與醫療品質提升"}, {"citations": [{"page": 3716, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=15"}, {"page": 3717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=16"}, {"page": 3717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=16"}], "councilor_points": ["闕枚莎議員指出共融式遊具除具備創意與趣味外，安全性為重中之重。議員舉出內湖區明湖公園磨石子溜滑梯因坡度過陡及地墊設計不良造成長者「脊椎第12節壓迫性骨折」之受傷案例，要求公園路燈工程管理處全面檢視臺北市所有公園溜滑梯設備之高低落差與傾斜度。此外，議員指出全球暖化導致夏季遊具曝曬過熱容易造成兒童燙傷，建議增加樹蔭遮蔽、加裝遮陽設施、使用安全無毒隔熱塗料及透水鋪面，並要求於三個月內提出全區公園遊具安全性與改善計畫。"], "response": "公園路燈工程管理處處長說明會成立專案小組，並承諾於三個月內全面檢視臺北市所有公園遊具之安全性與缺失，將改善計畫送交議員辦公室。", "response_removed": false, "topic": "公園共融式遊具安全與防熱改善"}, {"citations": [{"page": 1416, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=4"}, {"page": 1417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=5"}], "councilor_points": ["闕枚莎議員指出臺北市客家人口數達 45.4 萬人，且內湖區客家人數為全市十二行政區第一名。議員建議建置專屬於臺北市的第一座國際級客家主題教育園區，融合客語與英語雙語教學，並包含臺北市第一座義民廟、客語情境教室、客英語親子數位圖書館及文化體驗館。議員亦建議啟動辦理跨縣市客英語夏令營與交流活動，並於港湖地區多舉辦客家文化巡迴展演。"], "response": "客家事務委員會主任委員說明已於跨局處會議特別提出主題園區之空間需求，未來會持續努力推動；同時表示今年夏令營將擴大規模讓學童擔任策展人並加強客英語內容，對於南港及內湖地區之活動也會努力辦理。", "response_removed": false, "topic": "客家文化推廣與主題教育園區建置"}, {"citations": [{"page": 4273, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=27"}, {"page": 4275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=29"}, {"page": 4277, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=31"}], "councilor_points": ["闕枚莎議員指出校園毒品問題嚴峻，且新興毒品常偽裝成王子麵、小熊軟糖、梅粉、跳跳糖、毒咖啡及毒奶茶等市售零食，使青少年極難辨識。議員建議市長定期召開校園防制毒品會議，並請社會局研議涉毒兒少後續輔導計畫、警察局加強查緝與留意網路毒品交易訊息。議員亦要求加強宣導青少年藥物濫用事項，並定期舉辦反毒教育咖啡論壇以交流第一線經驗。"], "response": "市長說明已特別指示警察局、教育局及相關單位研擬計畫，以阻絕新興毒品流入校園，並表示議員所提出之各項建議都會積極落實執行。", "response_removed": false, "topic": "校園毒品防制與新興毒品阻絕"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=21", "transcript_pages": [4267, 4268, 4269, 4271, 4272, 4273, 4274, 4275, 4276, 4277, 4278, 4279], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 6}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=1", "transcript_pages": [1413, 1414, 1415, 1416, 1417], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 18}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=21", "transcript_pages": [1568, 1569, 1570, 1571, 1572, 1573], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 4}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=11", "transcript_pages": [1977, 1978, 1979, 1980, 1981, 1982, 1983], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 1}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=14", "transcript_pages": [2443, 2444, 2445, 2446, 2447, 2448, 2449, 2450, 2451], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 2}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=1", "transcript_pages": [2957, 2961], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 4}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=15", "transcript_pages": [3716, 3717, 3718, 3719, 3720, 3721, 3722], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC','2026-10-03T00:55:22Z');
INSERT INTO "fact" VALUES('summary:14-01:pa2aee439f8','pa2aee439f8','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T00:57:14Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=1"}, {"page": 1283, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=2"}, {"page": 1284, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=3"}, {"page": 1285, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=4"}, {"page": 1285, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=4"}, {"page": 1286, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=5"}, {"page": 1287, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=6"}, {"page": 1287, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=6"}, {"page": 1288, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=7"}], "councilor_points": ["陳宥丞議員指出臺北市 0 到 3 歲嬰兒公共化與準公共化收托人數僅 5,983 人、保母收托 5,526 人，家外送托率約 24%，距離「托育政策催生聯盟」建議的 37% 尚有 5,791 人的差距，要求社會局於 1 個月內提出擴充公共托育量能與招募保母人力的報告（引文：「試算所謂的家外送托率大概只有 24%……如果家外送托率能夠穩定維持在 37%，才會是個最好的托育環境……至少要達到 17,300 人……距離目標還有 5,791 人的差距」）。陳宥丞議員指出臺北市定點臨托僅開辦 5 個行政區，其餘行政區開辦進度延後，且現行預約媒合平台不便，建議參考高雄市開辦 24 小時預約臨托及韓國保母預約平台，並於 1 個月內提出評估與研究報告（引文：「臨托的服務對社會局來講也是個非常重要的業務……可不可以具體回應我，哪幾個行政區一定可以在今年落成……請你儘快評估實施 24 小時內預約臨托服務……身為首都市能開始評估自辦或是媒合有興趣的企業先來跟市府做評估跟試用」）。"], "response": "社會局局長說明 112 年預計開辦 4 家公辦民營托嬰中心與托育家園、增加 76 人，並表示萬華、大同今年可配合社宅提供臨托服務，其餘區域將配合社宅興建陸續開辦（引文：「112 年大概開辦 4 家……可以增加的托育人數是……76 人」、「萬華、大同在今年絕對沒有問題，因為有社宅跟新建成大樓，都是配合社宅興建做臨托服務」）。社會局局長表示夜間臨托因專家學者考量幼兒睡眠與褪黑激素受干擾而建議謹慎評估，並承諾會向高雄市請益臨托做法，並於 1 個月又 1 週內研議保母媒合平台與提出報告（引文：「有專家學者認為還要再謹慎評估……我們一定會向高雄市請益，了解他們的執行方式」、「這部分我們回去研究……1 個月又 1 週」）。", "response_removed": false, "topic": "幼兒公共托育量能與定點臨托服務改善"}, {"citations": [{"page": 3036, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=1"}, {"page": 3037, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=2"}, {"page": 3038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=3"}, {"page": 3039, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=4"}, {"page": 3038, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=3"}], "councilor_points": ["陳宥丞議員指出市定古蹟舊廈門街派出所承租業者違規轉租給第三人營業，且該第三人拒絕設置身心障礙參觀 QR code、深夜喧嘩並違規變身為私人招待所，嚴重違反老房子文化運動開放市民參觀之初衷（引文：「第三人為葡香公司……25 坪的空間，他有借給販售甜甜圈的甜點店使用，甚至還有作為商業攝影……承租者拒絕放置 QR code……被爆料作為私人招待所，完全違背當時作為歷史建物的初衷」）。陳宥丞議員指出因環保局與二房東簽訂之公用房地行政契約未直接規範第三人，導致市府對於實際使用者之違規行為無法介入處置，要求法務局與文化局協助修改契約結構漏洞，並於 1 個月內提出個案解決方案與改進處置（引文：「貴局對於契約內容，沒有提出要求與限制……使用者不論怎麼違規，北市府法務局、環保局、文化局，完全無法介入做任何處置……請局長 1 個月內提出方案」）。"], "response": "環保局局長說明二房東得標後花費 1 千多萬元整修，因第三人行為不符合約定且做出違規行為，二房東正對其進行訴訟，並坦言訂約時若能更周延即可馬上處理（引文：「曾先生得標後，花了 1 千多萬元進行全棟 3 層樓的整修……承租人的行為不符合規定……目前正在訴訟」、「我們訂約時若能夠更周延，今天葡香公司做出違反規範行為時，就可以馬上處理」）。法務局法令事務第三科科長說明現行契約僅於環保局與二房東之間生效，轉租為另一份契約，坦言契約有必須檢討修改之處；環保局局長承諾召集相關單位研商，於 1 個月內提出契約修改與個案解決方案（引文：「這份契約是環保局先跟曾先生簽訂，具有相對性……這份契約有必須檢討與修改的地方」、「環保局會召集相關單位進行研商……1 個月內提出方案」）。", "response_removed": false, "topic": "古蹟舊廈門街派出所營運與契約檢討"}, {"citations": [{"page": 2163, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=19"}, {"page": 2164, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=20"}, {"page": 2166, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=22"}, {"page": 2167, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=23"}, {"page": 2165, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=21"}], "councilor_points": ["陳宥丞議員指出教育局推動的高齡校舍逐年改建計畫（EOD）共有 44 件，但目前動工僅分布於 7 個行政區，未能落實「一區一潛力基地」目標，且 19 個 EOD 計畫中僅 2 處納入社福、托老等公共設施（引文：「高齡校舍逐年改建計畫……目前動工的只有 7 個行政區……基本上並沒有落實到一區 1 個 EOD 的目標……19 個 EOD 計畫裡面，居然只有 2 處……真正的有把我們需要的社福、托老、托嬰、公園綠地、機關納入」）。陳宥丞議員指出老舊校舍改建經費龐大，112 年度教育局相關工程預算僅 50 億元不足以支撐，建請教育局向市府爭取運用地政局平均地權基金之 416 億餘元現金餘額作為 EOD 專款專用經費，並於總質詢前送交橫向聯繫報告（引文：「112 年度教育局的總預算……加起來也只有 50 億元……爭取把平均地權基金，拿來作為現在高防災……補助做 EOD 的專款專用」）。"], "response": "教育局局長說明目前 EOD 計畫有 13 件施工中、31 件規劃設計中，並表示推動專案時各單位會依評估提出需求，承諾於總質詢前整理潛力計畫與各單位需求之檢討報告（引文：「現在有 13 件施工中。有另外 31 件在規劃設計」、「各個單位會進來，在規劃設計的時候提出他們的需求……會依照各單位的評估以後再去施作」）。地政局土地開發科科長說明平均地權基金目前現金餘額約 416 億餘元，依法可用於已辦竣公辦重劃與區段徵收範圍內之公有建築補助；教育局局長表示將與地政局研議爭取經費以加速校舍規劃，並於 5 月 29 日前送交工作報告（引文：「現金大概 416 億餘元……只要在臺北市已辦竣的公辦重劃區還有區段徵收範圍內的公共設施或公有建築都可以補助」、「可以來跟地政局一起研議並加速我們的校舍規劃進行……在本質詢組 5 月 29 日質詢前，請你們先送一個初步的報告」）。", "response_removed": false, "topic": "高齡校舍改建 EOD 計畫與預算籌措"}, {"citations": [{"page": 4049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=11"}, {"page": 4050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=12"}, {"page": 4052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=14"}, {"page": 4053, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=15"}, {"page": 4051, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=13"}], "councilor_points": ["陳宥丞議員詢問第三副市長之業務分工與專業需求，指出臺北市有 24 萬家中小企業，建議第三副市長應具備產業、商機與觀光發展思維（引文：「臺北市當年有 25 萬家企業，中小企業占 24 萬家……第三位副市長，除了熟悉產業，還要洞悉商機，還有發展觀光思維」）。陳宥丞議員指出市府女性首長比例僅 21%，未達選前承諾之 30%，要求市長遴選第三副市長時應優先考量女性、跨黨派徵才，並守住底線勿讓黨意凌駕民意（引文：「女性閣員的比例……只有 6 位女性首長，比例只有 21%而已……希望第三位副市長要安排女士優先……請市長守住底線，不要讓黨意凌駕民意」）。"], "response": "市長說明第三副市長專業方向比較偏向產業與財經，認同議員提出之考量方向，並表示會朝女性閣員 30% 比例努力，堅持用人唯才、適才適所（引文：「整體評估第三位副市長，應該比較傾向在產業、財經方面」、「這是一個方向，我們會仔細的參考」、「會用人唯才、適才適所」）。市長表示目前心中已有 5 位以上的人選，包含各個黨籍與專業背景，對於外界與各界推薦之熱門人選都會納入整體考量，並保證絕不會受政黨因素侷限（引文：「至少有 5 位以上的人選」、「各個黨籍的人選都有，各個專業的背景人選都有」、「絕對不會侷限任何政治、政黨因素」）。", "response_removed": false, "topic": "第三副市長遴選條件與人選"}, {"citations": [{"page": 1835, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=29"}, {"page": 1835, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=29"}, {"page": 1836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=30"}, {"page": 1836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=30"}], "councilor_points": ["陳宥丞議員指出內湖區 6 座瓦斯儲氣槽與居民比鄰長達 40 年且距離民宅僅 30 公尺，中油於三接公投通過後仍以工程進度為由拖延換約與遷移，要求產業發展局發揮功能督促落實會議決議（引文：「內湖區瓦斯儲氣槽到目前還沒有停用、遷移……和內湖居民長達 40 年的比鄰……離民宅最近的儲氣槽只距離 30 公尺……不可以用工程還在施作為由繼續拖延吧」）。陳宥丞議員要求產業發展局局長親自召開局長層級會議，邀集中央與中油至市府說明，若中央持續不予理會，應將本案送至六都市長列席之行政院院會，由市長直接與中央談判，並於本會期結束前提出工作報告（引文：「應該要親自召開局長層級會議，要求中央、中油到臺北市政府做說明……本席希望這件案子就送到六都市長列席行政院院會的會報中……請你們送來這樣的一份報告」）。"], "response": "產業發展局局長說明內湖共有 6 座儲氣槽，中油函覆林口氮氣摻配工程已完工測試，但因台中至通霄 36 吋陸管工程預計 112 年 6 月才通氣，中油認為尚未能確保穩定供氣前暫無法換約（引文：「總共有 6 座……林口氮氣摻配工程是在 111 年年底完工……台中至通霄 36 吋陸管工程目標是在 112 年 6 月完成通氣……中油認為還沒辦法確定能夠穩定供氣之前，他們不敢冒然……進行合約換約」）。產業發展局局長承諾將在市政總質詢前召開會議要求中油說明，並會向市長與副市長建議將此案送行政院院會討論，且承諾在本會期結束前送交工作報告（引文：「在市政總質詢前，我們把這個會議召開完畢」、「這部分我會跟市長、副市長建議」、「好，沒問題」）。", "response_removed": false, "topic": "內湖瓦斯儲氣槽遷移與供氣合約"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=7", "transcript_pages": [4045, 4046, 4047, 4048, 4049, 4050, 4051, 4052, 4053, 4078, 4079, 4080, 4081, 4082, 4083, 4084, 4085, 4086, 4087], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 1}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=1", "transcript_pages": [1282, 1283, 1284, 1285, 1286, 1287, 1288, 1289], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 13}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=23", "transcript_pages": [1829, 1830, 1831, 1832, 1833, 1834, 1835, 1836], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 16}]}, {"dates": ["2023-05-02", "2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=17", "transcript_pages": [2161, 2162, 2163, 2164, 2165, 2166, 2167, 2168, 2169, 2170], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 10}, {"date": "2023-05-04", "group": 10}]}, {"dates": ["2023-05-09"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=11", "transcript_pages": [2567, 2568, 2569, 2570, 2571, 2572, 2573, 2574], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC", "videos": [{"date": "2023-05-09", "group": 7}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=1", "transcript_pages": [3036, 3037, 3038, 3039, 3040, 3041, 3042, 3043], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 7}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=21", "transcript_pages": [3607, 3608, 3609, 3610, 3611], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC','2026-10-03T00:57:14Z');
INSERT INTO "fact" VALUES('summary:14-01:pc164e1064f','pc164e1064f','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T00:59:31Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2107, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=1"}, {"page": 2108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=2"}, {"page": 2108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=2"}, {"page": 2109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=3"}, {"page": 2109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=3"}, {"page": 2110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=4"}, {"page": 2111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=5"}, {"page": 2111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=5"}], "councilor_points": ["陳怡君議員指出大貓熊館販售之「臺灣製造」商品遭塗改覆蓋為「中國製造」，質疑是「自我閹割」與「欺騙消費者」，並反映園區亞洲黑熊數量從「9隻」變「8隻」，黑熊「寶貝」過世「1年」未對外說明是「官僚」，且馬來熊與亞洲黑熊出現來回踱步等刻板行為。陳怡君議員亦指出園區缺乏黑熊宣傳與正確商品，並反映吉祥物「熊讚」行程少是「太懶惰」，要求研擬熊讚擔任親善大使走訪動物園，並提撥商品收益推廣黑熊保育。"], "response": "動物園園長說明大貓熊館係委外經營會向廠商了解，並說明亞洲黑熊「寶貝」係於去年「5月」因脊椎骨刺過世且有通報農委會林務局，承諾「112年」有做熊的展示規劃案以豐富化設施空間。觀光傳播局局長說明熊讚出席活動包含接受申請與出外景，商業授權有「5%到 6%」繳入市府公庫，會再補送資料。", "response_removed": false, "topic": "市立動物園經營管理與亞洲黑熊保育改善"}, {"citations": [{"page": 1187, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=7"}, {"page": 1189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=9"}, {"page": 1189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=9"}, {"page": 1191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=11"}, {"page": 1190, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=10"}, {"page": 1191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=11"}], "councilor_points": ["陳怡君議員指出民政局未依《臺北市遊民安置輔導自治條例》進行遊民戶籍清查，並反映「12 個」行政區之遊民查報表格格式不一，其中萬華區公所自「107 年」至今之緊急協助件數均記錄為「0」不符合實際狀況、質疑是「渾水摸魚」。陳怡君議員並舉出街友「瀟灑哥」長年在路邊便溺、自殘及行走於四線車道等危險行為未能獲得系統性協助，以及「圓通居」等盥洗據點假日未開放問題，要求民政局統一查報格式並落實街友關懷。"], "response": "社會局局長說明遊民由社會局列管，戶籍清查與民政局合作；針對萬華區與個案因涉及個資僅提供統計數據，圓通居屬安置處所平時不對外開放，對「瀟灑哥」有請社區精神衛生單位施打長效針，但因非強制或犯罪行為無法直接強制處置。北投區公所區長與萬華區公所區長說明里幹事查報時若遊民不願提供個人資料無法強制，萬華區設有專案小組由跨局處處理，後續可補充資料。", "response_removed": false, "topic": "遊民戶籍清查與查報輔導機制改善"}, {"citations": [{"page": 3731, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=9"}, {"page": 3732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=10"}, {"page": 3733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=11"}, {"page": 3733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=11"}, {"page": 3734, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=12"}], "councilor_points": ["陳怡君議員反映預算資料「32 億元」之行善社會住宅入住不到半年即出現天花板裂痕擴大、天花板與水管滴水形成冰柱、手把鏽蝕、磁磚脫落及植栽泥土硬化等施工與管理瑕疵。陳怡君議員亦指出瑞光社會住宅有住戶在大門敞開裸露下體騷擾鄰里，以及大龍峒社會住宅輪椅身障者無法手感應電梯磁扣等問題，要求逐戶做問卷調查並完善輔導與友善設施。"], "response": "都市發展局局長表示會全面檢視修繕行善社宅漏水與設施問題，並同意針對住戶實施問卷調查。都市發展局住宅服務科科長與社會局社會工作科科長說明瑞光社宅個案已由物管人員勸導並由身障者資源中心持續關懷與加強輔導。住宅及都市更新中心代理執行長說明大龍峒社宅電梯感應設備改善正進行採購，預計「6 月中」完成。", "response_removed": false, "topic": "社會住宅施工品質瑕疵與居住管理改善"}, {"citations": [{"page": 3093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC#page=2"}, {"page": 3093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC#page=2"}, {"page": 3094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC#page=3"}, {"page": 3095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC#page=4"}], "councilor_points": ["陳怡君議員指出裁併後之雙連派出所「1 樓與 2 樓」空間未獲充分運用，並反映使用超過「50 年」之社子警察新村建物鋼筋外露水泥剝落如危樓，以及「111 年」新建落成之社子派出所宿舍出現水痕與修補膠痕。陳怡君議員要求警察局積極推動宿舍改建，並善加規劃閒置空間作為員警待勤室或宿舍。"], "response": "警察局局長說明雙連派出所「1 樓」為民防與義警中隊辦公室，「3 樓與 4 樓」為待勤室；社子警察新村已規劃辦理公辦都更，並表示現有職務宿舍約「380 間」，未來配合「7 個」地方市府政策規劃可擴增至「800 間」。警察局局長補充說明將全面盤點經管廳舍結構無問題者，統一整體規劃優化改建為職務宿舍。", "response_removed": false, "topic": "警察職務宿舍居住環境與閒置派出所空間運用"}, {"citations": [{"page": 1748, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F47124B6071F22F21611575CF38E043B04B5A47D4F5E0717015F038249597DF402D1DE3DCEB210BC#page=11"}, {"page": 1749, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F47124B6071F22F21611575CF38E043B04B5A47D4F5E0717015F038249597DF402D1DE3DCEB210BC#page=12"}, {"page": 1750, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F47124B6071F22F21611575CF38E043B04B5A47D4F5E0717015F038249597DF402D1DE3DCEB210BC#page=13"}], "councilor_points": ["陳怡君議員指出台北通 APP 尋找公廁與無障礙廁所標示不清（如「友、夜、署」縮寫難懂、標示地址找不到廁所），且「12 個」區公所僅能查到「6 筆」結果。陳怡君議員並反映意見調查與 i-Voting 投票時間倒流顯示為「1970 年 1 月 1 日」、捐血站僅顯示「3 個」，以及部分景點缺少人流即時影像，質疑台北通「一竅不通」，要求限期檢討改善。"], "response": "資訊局局長說明投票日期顯示為「1970 年」係上架時預設條件未調整好，即時影像缺失係因場地未提供資訊源。資訊局局長表示會積極溝通提供不間斷影像，並承諾會在市政總質詢前完成盤查並向議員報告。", "response_removed": false, "topic": "台北通 APP 資訊標示與功能缺失改善"}, {"citations": [{"page": 2698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654920F648FE6B4EBA21E4A21447E7507E45A3FF42E2B2CE3FF29EAD67130BB0E77902D1DE3DCEB210BC#page=9"}, {"page": 2698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654920F648FE6B4EBA21E4A21447E7507E45A3FF42E2B2CE3FF29EAD67130BB0E77902D1DE3DCEB210BC#page=9"}, {"page": 2699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654920F648FE6B4EBA21E4A21447E7507E45A3FF42E2B2CE3FF29EAD67130BB0E77902D1DE3DCEB210BC#page=10"}], "councilor_points": ["陳怡君議員指出新生高架橋下公有停車場電子看板常顯示「滿位」但場內實有空位，或顯示有車位進場卻無位可停。陳怡君議員並反映「愛台北市政雲服務」系統之即時車位資訊多處顯示無資料，或連續數個停車場均重複顯示尚有「13 個」車位等錯誤不實狀況，要求停管處查明並於總質詢前改善。"], "response": "停車管理工程處處長說明現場電子看板誤差係壓站線圈布設問題，已縮短調校時間至每週至少「2 次」。停車管理工程處處長並說明網路資訊係因愛台北系統介接錯誤，會與資訊局橫向聯繫查明改善。", "response_removed": false, "topic": "公有停車場即時車位資訊精準度改善"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 9, "heading": "民政部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162#page=6", "transcript_pages": [1186, 1187, 1188, 1189, 1190, 1191, 1192], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162", "videos": [{"date": "2023-04-18", "group": 9}]}, {"dates": ["2023-04-27"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F47124B6071F22F21611575CF38E043B04B5A47D4F5E0717015F038249597DF402D1DE3DCEB210BC#page=10", "transcript_pages": [1747, 1748, 1749, 1750], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549F47124B6071F22F21611575CF38E043B04B5A47D4F5E0717015F038249597DF402D1DE3DCEB210BC", "videos": [{"date": "2023-04-27", "group": 13}]}, {"dates": ["2023-05-02"], "dept": "教育", "doc_type": "部門質詢", "group": 8, "heading": "教育部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC#page=1", "transcript_pages": [2107, 2108, 2109, 2110, 2111, 2112], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549A2FAC3B42E60D5F761315C7D7783CC50461677F3348EC2FB98459F6C9614AFE902D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 8}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "heading": "交通部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654920F648FE6B4EBA21E4A21447E7507E45A3FF42E2B2CE3FF29EAD67130BB0E77902D1DE3DCEB210BC#page=8", "transcript_pages": [2697, 2698, 2699, 2700, 2701], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654920F648FE6B4EBA21E4A21447E7507E45A3FF42E2B2CE3FF29EAD67130BB0E77902D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 13}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC#page=1", "transcript_pages": [3092, 3093, 3094, 3095, 3096], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665494D18A5D75D409F737E231D8DBB8F38D15851997FAAD195634B5172F9906ACEB102D1DE3DCEB210BC", "videos": [{"date": "2023-05-18", "group": 10}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 11, "heading": "工務部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC#page=8", "transcript_pages": [3730, 3731, 3732, 3733, 3734, 3735], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549C1E3477319FB74B01982D43EDB57F2786ED0E0A16A738DF9C3E63DD09C1FC14202D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 11}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549EDB36041D1680D08B784B7C40E2B9C4C88E412F3472C3BAFA852238F00A7C162','2026-10-03T00:59:31Z');
INSERT INTO "fact" VALUES('summary:14-01:padc186f41c','padc186f41c','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:01:38Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4180, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=16"}, {"page": 4181, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=17"}, {"page": 4182, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=18"}, {"page": 4182, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=18"}, {"page": 4183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=19"}], "councilor_points": ["陳慈慧議員詢問社子島開發爭取從優安置與補償條件是否影響開發期程，並表示市府不應以虧損為由拒絕提升居民補償訴求（引文：「爭取這些條件的同時，想請問市長，這會影響到開發的期程嗎？」、「市府不應該用『目前』開發案虧損為理由，拒絕或防堵居民提升補償方案的訴求」）。陳慈慧議員指出多戶設籍之承租戶未來應可轉為承購，並要求將抵價地比例調高至50%、放寬4樓以上既存違建拆遷費50%限制與84年後新違建補償，以及依物價指數補足重建單價（引文：「剩下的那 4 戶承租戶，未來可能住到一個年限之後可以轉做承購」、「為什麼社子島又比其他縣市相對較為嚴格，只能有 40%的抵價地比例？」、「4 樓以上的既存違建只給 50%……這一點也希望總隊長可以回去討論一下」、「今年你們在調整重建單價的時候，應該要把前 2 年的一併補足」）。陳慈慧議員建議市府給予明確開發期程，並以同理心給予社子島居民更從優、從寬的補償與安置條件（引文：「希望市府能夠明確地給一個期程，告訴我們接下來社子島開發的期程是什麼」、「希望市長能夠用同理心看待社子島的居民，給予我們更從優、從寬的補償條件或是安置條件」）。"], "response": "市長表示爭取從優條件不會影響開發期程，強調開發是為長遠目標之必要投資，承諾延續65歲以上弱勢戶承租專案住宅至終老政策，並會將84年後新違建補償與重建單價調整等意見納入研究（引文：「不會」、「我們的態度絕對不會用『賠錢』這樣的字眼，而是用任何地區的開發是為臺北市長遠的目標 10 年、20 年來看。必要的支出與投資，這些我們都會做」、「會，我們會繼續延續」、「好，這部分我請地政局納入，一併研究」、「可以」）。土地開發總隊總隊長說明，承租轉銷售預計6、7月分會有完整結果，65歲弱勢長者以第一期專案住宅交屋入住日為起算點；抵價地比例係因北市過往以40%為原則且目前財務虧損，未來會配合內政部審議結果調整，重建單價則由工務局每年依營建成本調高，合法者含獎勵金可達每坪接近12萬元（引文：「預計大概 6、7 月分會有一個完整的結果出來」、「65 歲有列冊的這些弱勢長者是以交屋的日子來當作起算點」、「如果有機會可以調整，我們會配合委員審議的結果」、「目前每坪是將近 7 萬元，但是因為社子島如果是合法的話……可以領到重建單價的 1.8 倍，所以是接近 12 萬元左右」）。地政局局長表示相關查估與規劃發包會提早進行以利儘早開發；市長補充已將區段徵收範圍及抵價地比例送內政部，並於行政院院會向院長及內政部表達盼儘速召開審查會議（引文：「即便內政部現在不審這件事情，我們相關可以做的作業也是會提早做……目的其實就是希望能夠儘早開發」、「親自參加行政院院會，也當面向行政院院長以及內政部表達，希望儘快召開專案小組會議審查」）。", "response_removed": false, "topic": "社子島開發與安置補償條件"}, {"citations": [{"page": 2317, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=19"}, {"page": 2318, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=20"}, {"page": 2319, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=21"}, {"page": 2319, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=21"}, {"page": 2321, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=23"}, {"page": 2321, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549925495188DBF0DD3C4B81A6024F97FA61CF17000824551A631A1F6AD2B0F824202D1DE3DCEB210BC#page=23"}], "councilor_points": ["陳慈慧議員指出山區小校特教教師服務時間與人數遠超表面數字，若每週課數未滿20堂需至跨區學校補足，建議教育局採核實計算或彈性方式協助（引文：「山上的小學學生人數比較少一點……沒有辦法每周在學校達到 20 小時、20 堂課，所以老師就必須到其他學校去補足……針對這種的情況、比較特殊的案例，教育局有沒有什麼方式可以來協助這些老師？」）。陳慈慧議員建議針對願意至北投、士林、文山等偏遠山區服務的特教助理員，給予車馬費補貼或依地理位置加給以提高時薪（引文：「針對像比較偏遠地區的學校助教員，他們願意到偏遠地區服務，你們是不是能給他們在時薪方面的加給？比如說用居住地或者是戶籍去計算，給他們一些車馬費的補貼」）。陳慈慧議員建議將特教心評工作專責化以減少特教老師行政負擔，並提議教育局於小學新生入學說明會宣導去標籤化，鼓勵家長讓有需求的孩子接受特教評鑑（引文：「希望可以走向減少特教老師的評鑑，讓專人去負責做心評？」、「能不能在像小學新生入學時辦理家長說明會與家長對話，教育局來發起一個對家長的說明或談話？來鼓勵家長如果孩子有一些比較特殊的情況……能夠讓孩子去參加這個評鑑」）。"], "response": "教育局局長說明特教助理員服務可採比照核實計算模式，把多服務的時數納入，提供彈性計算基礎（引文：「提供的服務我們可以比照一種核實計算的模式，也許可以把多服務的時數加進來，這樣的話，您剛提到服務不滿 20 小時的彈性計算模式，比較會有一些基礎」）。教育局局長表示特教助理員人數為110位，基本時薪依勞動局公告已從168元調至176元並乘上不同等級倍數，對山區服務可採彈性從寬方式檢核（引文：「總人數現在是 110 位，時薪現在已經從 168 元調到 176 元」、「但是您可以對他們的服務，可能以比較彈性從寬計算，我們來做實質上的檢核」）。教育局局長表示鑑定工作由專業人員分割處理之建議可以考量，並說明目前針對特殊幼童進入國小前設有準備班，後續會透過說明讓家長了解特教鑑定的幫助（引文：「鑑定的第一線工作這部分，是不是一定要由特教老師來做……如果把它分割開來其實也不是不行……我們會來因應」、「有請 4 個學校……有一個國小準備班，讓家長能早一點了解……有鑑定以後對孩子的幫助會比較多」）。", "response_removed": false, "topic": "山區小校特殊教育資源與助理員權益"}, {"citations": [{"page": 4202, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=38"}, {"page": 4202, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=38"}, {"page": 4203, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=39"}, {"page": 4203, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=39"}, {"page": 4204, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=40"}], "councilor_points": ["陳慈慧議員指出芝山國小設置日照中心過程因事前溝通不足致家長身心俱疲，建議市府制定降低紛爭的規則，並優先考量設置於1樓以便於動線隔離與逃生（引文：「芝山國小的類似爭議也有可能會再次發生……是不是應該制定個降低紛爭的規則？比如未來日照中心要設置在學校……是否應該要在 1 樓？逃生和動線方面容易做出區隔」）。陳慈慧議員指出芝山國小日照中心扣除辦公室、廁所及走道後長者實際使用面積可能不到1.5坪，建議市府訂定明確規範或屬於臺北市的自治條例（引文：「實際上，算下來可能長者真正使用到的空間是不到 1.5 坪，雖然它符合法規，可是要把長者用不到的空間計算在內，我覺得這個也不合理」、「針對日後日照要進入校園這部分，可以有個稍微明確的規定出來？其實我也希望甚至臺北市可以提出一個屬於自己的自治條例」）。"], "response": "市長表示芝山國小為首例，事前溝通確有改善空間，未來規劃將以1樓為優先考量，並由教育局訂定明確原則作為校園設置日照中心之標準（引文：「芝山國小也是臺北市第 1 件日照中心進駐校園，所以我想一開始的確在規劃上或事前的溝通，其實可以做得更好」、「未來在規劃上，應該是以 1 樓為優先考量」、「由教育局訂定一個較明確的原則，作為未來規劃在校園內設置日照中心的標準」）。社會局局長說明目前預計長期規劃66個學區仍差6個學區未佈建，芝山國小收托人數已改成30名，未來會持續與學校及家長加強溝通（引文：「預計長期的規劃會有 66 個學區，還差 6 個學區還沒佈建」、「現在改成 30 名」、「以後我們都會儘量努力，也能夠持續做溝通及了解」）。教育局局長補充若併入EOD案討論會特別考量獨立動線，舊建築物使用以1樓較為方便，未來整體規劃時會特別處理（引文：「如果是併在 EOD 案子去做討論的話，我們會做個獨立的動線……如果是舊的建築物，在使用上可能還是在 1 樓會比較方便……以後在整體規劃時會特別處理」）。", "response_removed": false, "topic": "校園設置日間照顧中心規劃與規範"}, {"citations": [{"page": 1118, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654909317337FC70442C8673E6B0AD5A3B6D2F7CB2BC84370F88A852238F00A7C162#page=20"}], "councilor_points": ["陳慈慧議員指出第二殯儀館預計增加禮廳容納人數，但停車位增幅不成比例，詢問殯葬管理處針對防止辛亥路塞車及周邊停車空間不足之具體因應方案（引文：「未來的新第二殯儀館增加 3 倍的容納人數，但是以比例來講，卻只有增加兩倍的停車空間，如果真的是好日子的時候，車位絕對是不夠的」、「針對第二殯儀館周邊停車空間不足的問題，還有未來新的第二殯儀館好了，殯葬管理處為了防止辛亥路塞車，有沒有具體因應的一個方案？」）。陳慈慧議員指出捷運淡水信義線目前無懷恩專車站點，而士林、北投去年死亡人數占全市五分之一且人口偏高齡，建議於石牌站、劍潭站或圓山站等大站設點直達接駁（引文：「本席發現紅線淡水線上沒有任何的懷恩專車站點……士林、北投去年死亡人口數的資料，4,257 人占全市過世人數的 1/5」、「本席建議可以在一些大站，比如石牌站、劍潭站，甚至大同區圓山站也可以……未來讓士林、北投的民眾到第二殯儀館能夠更便捷」）。"], "response": "殯葬管理處處長表示第二殯儀館將增加7個禮廳，會加強懷恩專車站點並透過捷運接駁，以減少車輛進入（引文：「針對第二殯儀館的禮廳，之後確實是會增加 7 個禮廳……我們會懷恩專車會再加強站點，希望可以透過捷運接駁民眾過來，減少車輛進到第二殯儀館的領域裡面」）。殯葬管理處處長表示針對士林、北投居民搭乘淡水線紅線部分，會進行研究評估直達接駁不用轉乘，並於2星期內研討及與公運處討論，儘快編列概算爭取明年經費（引文：「針對士林、北投居民坐淡水線的這一個紅線的部分可以直接接駁，不用轉乘到其他線，殯葬管理處會朝這個部分來評估」、「大概需要 2 個星期來研討這個部分……會儘快的編列概算來爭取明年的經費」、「其實殯葬管理處之前有跟公運處討論過，他們原則上都會支持我們這樣子的規劃」）。", "response_removed": false, "topic": "第二殯儀館周邊交通與接駁規劃"}, {"citations": [{"page": 1590, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549E367BA46C4C52BD361315C7D7783CC5021DB9C7658A5F32F1AE2529382CBED3B02D1DE3DCEB210BC#page=4"}, {"page": 1589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549E367BA46C4C52BD361315C7D7783CC5021DB9C7658A5F32F1AE2529382CBED3B02D1DE3DCEB210BC#page=3"}], "councilor_points": ["陳慈慧議員指出北投市場舊館拆除過程中發現樓地板厚度不足、鋼筋鏽蝕及海砂屋等結構問題，建議若安全評估確定需重建，應評估原地重建之可能性（引文：「拆開以後，發現裡面結構有很多問題，像是你剛講的樓地板厚度不足或者是地板之間厚度不平均……鋼筋鏽蝕這些」、「與其要花這麼大的龐大預算去整修這個充滿問題的舊市場，不如乾脆評估之後是不是有未來原地重建的這個可能？」）。陳慈慧議員建議若評估確定重建，可利用剩餘容積設計為多功能大樓，擴大停車空間並容納日照機構或公托中心等設施（引文：「如果說未來 5 月底的這個評估報告，建議北投市場是應該要重建的……未來有沒有可能把它設計成一個多功能的大樓？比如說停車空間再更擴大，或者是有其他的空間能夠容納其他機構，像是日照機構或是公托中心等等」）。"], "response": "市場處處長說明中繼市場已於110年完工營運，舊本體拆除時發現樓地板厚度僅約7至10公分且有龜裂，目前正在做安全鑑定，初步確定有海砂問題，報告預計5月底出爐（引文：「中繼市場的部分在去年 110 年的時候已經完成了……樓地板厚度變比較薄，大概只有 7 公分到 10 公分左右……初步安全鑑定已經出來，它確實是有海砂這樣的問題」、「大概在 5 月底的時候」）。市場處處長表示現階段北投市場容積尚未用完，若確定重建，會蒐集市民與民意代表意見，評估以多目標方式納入社福、公托或托老等使用空間（引文：「現階段的北投市場的容積還沒有用完……除了原本的市場樓層以外，其他可以用多目標的方式使用，所以您所提到的還有沒有其他使用的空間跟可能性，初步判斷起來應該是有這樣的剩餘的空間可以使用」）。", "response_removed": false, "topic": "北投市場結構安全與改建規劃"}, {"citations": [{"page": 3645, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=12"}, {"page": 3645, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=12"}, {"page": 3646, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=13"}, {"page": 3647, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=14"}, {"page": 3647, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=14"}], "councilor_points": ["陳慈慧議員詢問青銀換居政策執行狀況，建議都發局可配合每一里的里鄰工作會報進行宣傳，並關切後續加強宣傳之計畫（引文：「『青銀換居』政策目前執行狀況為何？你滿意嗎？」、「我建議如果人力足夠的話，像上半年度及下半年度每一里都會有里鄰工作會報，你們可以去進行宣傳」、「接下來有沒有再加強宣傳的計畫？」）。陳慈慧議員指出二房型及三房型才是長者同住或請看護之主流需求，詢問準備釋出之戶數，並要求針對社宅6年居住年限研擬長者入住之配套措施（引文：「二房型及三房型才是真正的主流……請問接下來有規劃多少二房型、三房型準備釋出嗎？」、「社宅最多只能住 6 年，如果申請『青銀換居』成功的長輩，因他現在居住的是社宅，請問 6 年之後要再搬家嗎？」）。"], "response": "都市發展局局長說明高齡者搬家較為困難，自1月方案擴大至今尚未有鄰里申請，未來會將市長拜訪入住長者之經驗拍攝成短片加強宣導，並與民政局聯繫於里鄰工作會報宣傳（引文：「『青銀換居』本身就不怎麼好做，因為面對的是高齡者要搬到新的住宅……目前沒有，但是我們已經準備宣傳的短片……好的，我們和民政局聯繫」）。都市發展局局長說明年底華榮、福星新完工社宅會評估二房型及三房型釋出比例，目前已有5戶入住，並表示正在研議長者入住社宅6年期限屆滿後之居住年限延長配套措施（引文：「年底新完工的社宅，有華榮、福星……我們會評估一房型及二房型、三房型的比例」、「總共 5 戶」、「若期限滿了，又要再搬出來，其實這是一個很大的問題，所以現在也在研議長者入住後，『青銀換居』居住年限到底要到什麼時間？是不是應該延長？」）。", "response_removed": false, "topic": "青銀換居政策推動與配套措施"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC#page=14", "transcript_pages": [4178, 4179, 4180, 4181, 4182, 4183, 4184, 4201, 4202, 4203, 4204, 4205, 4206, 4207], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC", "videos": [{"date": "2023-05-30", "group": 4}]}, {"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 6, "heading": "民政部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654909317337FC70442C8673E6B0AD5A3B6D2F7CB2BC84370F88A852238F00A7C162#page=17", "transcript_pages": [1115, 1116, 1117, 1118, 1119, 1120, 1121], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA4613