"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 3, "heading": "警政衛生部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654993BB1F1768C0AAD9198FE74F0907F78778D6E14A22E1DFFA7D1A3FEB0C9CFB3102D1DE3DCEB210BC#page=13", "transcript_pages": [2940, 2941, 2942, 2943, 2944, 2945], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654993BB1F1768C0AAD9198FE74F0907F78778D6E14A22E1DFFA7D1A3FEB0C9CFB3102D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 3}]}, {"dates": ["2023-05-23"], "dept": "工務", "doc_type": "部門質詢", "group": 7, "heading": "工務部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC#page=10", "transcript_pages": [3643, 3644, 3645, 3646, 3647, 3648], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549FC7FE945715E4224813A05136CA6AEA8C7C8AC41D11690D338D8F3322115D1FF02D1DE3DCEB210BC", "videos": [{"date": "2023-05-23", "group": 7}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665497049895B2BCFD83D2E9E5633EBB374119A9B77DF704CD8B1F7577C7BD4890EC402D1DE3DCEB210BC','2026-10-03T01:01:38Z');
INSERT INTO "fact" VALUES('summary:14-01:pfd93c2126e','pfd93c2126e','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:04:14Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2968, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=12"}], "councilor_points": ["陳炳甫議員指出員警受傷高達6成在手部，建議配發防割手套並將拋射式電擊器納為標準配備。陳炳甫議員亦指出北市僅有1套互動式情境模擬射擊靶場，每半年常訓設備不足，建議編列預算增設設備或落實常訓評量紀錄。"], "response": null, "response_removed": true, "topic": "警察勤務裝備配置與射擊模擬訓練"}, {"citations": [{"page": 4258, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=12"}, {"page": 1428, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=16"}, {"page": 1428, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=16"}, {"page": 4259, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=13"}, {"page": 1429, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=17"}], "councilor_points": ["陳炳甫議員指出傳統公托收托時間無法配合服務業家長上班需求，建議新設收托時間為10時30分至21時之公托，並引用調查資料說明高達6成受訪者有送托意願。陳炳甫議員亦指出先前問卷調查的時間與地點不適合，建議直接發文給大型百貨及連鎖餐飲企業重新調查。"], "response": "市長說明已報中央核定最快今年9月試辦獨立新時段（10時30分至21時），規劃於懷生國中附近開辦，並同意拉長試辦時間。社會局局長表示認同議員建議，會主動聯繫服務業者做問卷並擬定試辦計畫。", "response_removed": false, "topic": "服務業從業人員托育服務與需求調查"}, {"citations": [{"page": 4261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=15"}, {"page": 4262, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=16"}, {"page": 3708, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=7"}, {"page": 3707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=6"}, {"page": 3708, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=7"}], "councilor_points": ["陳炳甫議員指出容積代金累計收入230億餘元，但標購支出僅約69億元，執行率僅四分之一，要求提高標購價格並將預算提高至40億元或50億元。陳炳甫議員亦要求修法與建立機制，規定以委員會召開前1個月月底為結算日，將超過3年未標購者提報檢討。"], "response": "市長說明認為議員建議合理，會研議一套機制和執行標準。都發局局長與新建工程處處長說明會配合於委員會召開前1個月結算提報檢討，並檢討提高明年度標購預算。", "response_removed": false, "topic": "容積代金基金標購與預算編列"}, {"citations": [{"page": 1422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=10"}, {"page": 1424, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=12"}], "councilor_points": ["陳炳甫議員指出新移民設籍及等待設籍人口達6萬多人，但僅由人口綜合科兼辦且預算僅約1,480萬元，建議短期成立專門科以編列獨立預算，中期設新移民發展處，長期成立一級機關新住民委員會。陳炳甫議員要求民政局與人事處調整說帖並儘速補齊資料成立專門科，避免成立機關進度延宕。"], "response": null, "response_removed": true, "topic": "新移民專責單位設置與預算編列"}, {"citations": [{"page": 4260, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=14"}, {"page": 1564, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=17"}, {"page": 1565, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=18"}, {"page": 4261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=15"}], "councilor_points": ["陳炳甫議員指出北市寵物灑葬要求個別火化，但動保處僅提供集體火化，而民間個別火化費用高達4,000元起算。陳炳甫議員建議於北北基桃跨市平台討論共同建置動物專用焚化爐，由相關縣市分擔費用並提供市民合理價位之服務。"], "response": "市長說明會提到北北基桃四縣市平台進行討論研究。動保處處長表示會與中央討論寵物生命紀念業管理事宜，並同意將跨市建立動物專用焚化爐納入未來討論方向。", "response_removed": false, "topic": "寵物遺體處置與跨市焚化設施建置"}, {"citations": [{"page": 4264, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=18"}, {"page": 4264, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=18"}, {"page": 4264, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=18"}, {"page": 4265, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=19"}], "councilor_points": ["陳炳甫議員指出教育局16案EOD計畫中真正加入社福機構僅有6案，且遭遇動線混雜之阻力。陳炳甫議員建議將新校舍蓋於臨路位置，一樓與二樓對外部分作為公托、日照中心等設施並設獨立動線，校內空間則供學生使用以切開動線。"], "response": "市長說明認同議員建議並表示會參考採納，認為設置獨立且臨路的出入口係較為有效的配置方式。", "response_removed": false, "topic": "校舍改建EOD與社福設施動線規劃"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC#page=11", "transcript_pages": [4257, 4258, 4259, 4260, 4261, 4262, 4263, 4264, 4265, 4266, 4267], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 6}]}, {"dates": ["2023-04-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162#page=9", "transcript_pages": [1421, 1422, 1423, 1424, 1425, 1426, 1427, 1428, 1429], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB96373566549A4D0D21CA69CB249BB5094290136F860E21F5B02E32CF6FDA852238F00A7C162", "videos": [{"date": "2023-04-21", "group": 18}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC#page=14", "transcript_pages": [1561, 1562, 1563, 1564, 1565, 1566, 1567, 1568], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665494620AEC6AF0488703F1861CC7CA97AE504915EA704557D65E01522A155628FCD02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 4}]}, {"dates": ["2023-05-01"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC#page=1", "transcript_pages": [1967, 1968, 1969, 1970, 1971, 1972, 1973], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549B6178865F807E1C382EDA0BF7308492179B323BBFA550D17115B40418FDD2FB602D1DE3DCEB210BC", "videos": [{"date": "2023-05-01", "group": 1}]}, {"dates": ["2023-05-08"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC#page=22", "transcript_pages": [2451, 2452, 2453, 2454, 2455, 2456], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665490879FC63AD6711A0198FE74F0907F787BC9093C8F8347563EB16E381CE40475402D1DE3DCEB210BC", "videos": [{"date": "2023-05-08", "group": 2}]}, {"dates": ["2023-05-15"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC#page=12", "transcript_pages": [2968, 2969, 2970, 2971, 2972, 2973, 2974], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB9637356654961B8AE9B80FFC9C6A9D767C738F32E9A5BF0324004BAA57CDF8112AB340367A502D1DE3DCEB210BC", "videos": [{"date": "2023-05-15", "group": 4}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC#page=5", "transcript_pages": [3706, 3707, 3708, 3709, 3710, 3711, 3712, 3713, 3714, 3715, 3716], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB9637356654956714E1498A443D8A0A1D0691981CE29B6E181E8F75CF5E89B9DC31659E965D402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB9637356654928607CE90A46FA7A334EE2E30B4B7D819D1EE67B1ABD52717239AA9F8CDADAA502D1DE3DCEB210BC','2026-10-03T01:04:14Z');
INSERT INTO "fact" VALUES('summary:14-01:p2cdc00a729','p2cdc00a729','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:08:47Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1631, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=15"}, {"page": 1632, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=16"}, {"page": 1634, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=18"}, {"page": 1636, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=20"}, {"page": 1636, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=20"}], "councilor_points": ["陳重文議員指出士林區東山路25巷東山社區約96戶居民缺乏公家自來水管，長期負擔高額水費並面臨嚴重漏水問題。陳重文議員建議市府採「無自來水地區」專案補助，從德行東路338巷接管至東山路25巷，由市府負擔更換配水管線費用，住戶自行負擔給水管線費用。陳重文議員要求市府於一個禮拜內將此建議研擬為處內方案並共同開會。"], "response": "自來水事業處處長認同該社區屬於廣義無自來水地區，表示議員提出的接管方案可行，若能取得私地主與全數住戶同意更換管線，將專案簽報市府爭取約5,700萬元更換配水管的預算。自來水事業處處長說明住戶需負擔給水管線費用，並表示同意於一個禮拜內完成研擬方案。", "response_removed": false, "topic": "士林區東山社區自來水供水與管線更換"}, {"citations": [{"page": 1193, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=1"}, {"page": 1194, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=2"}, {"page": 1195, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=3"}, {"page": 1197, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=5"}, {"page": 1195, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=3"}, {"page": 1196, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=4"}, {"page": 1199, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=7"}], "councilor_points": ["陳重文議員指出第一殯儀館拆除後第二殯儀館冰櫃總數將達1,314個，且新北市大體使用比例近四成，質疑冰櫃與14座火化爐量能不足並造成員工加班過度。陳重文議員建議市府針對新北市大體至北市冰存與火化採取限制或控制措施，避免過年期間大體再次堆放於禮廳。陳重文議員要求市府於1個月內進行評估，並將評估方案與內部會議紀錄送交備查。"], "response": "殯葬管理處處長說明二殯新大樓預計9月試營運、明年春節後拆除一殯，非北市民眾使用殯葬設施收費為2至3倍。殯葬管理處處長表示同意於1個月內研討並提出限制外縣市大體數量的評估方案，同時會編列預算評估增加火化爐及爭取委外化妝師人力。", "response_removed": false, "topic": "二殯冰櫃數量與火化量能管制"}, {"citations": [{"page": 1642, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=26"}, {"page": 1642, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=26"}, {"page": 1643, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=27"}, {"page": 1644, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=28"}, {"page": 1641, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB9637356654940347A4919B29DC6E2417F6AF9D6ED41FD86C5912FEFD09A91A39A0BA5BCBA1302D1DE3DCEB210BC#page=25"}], "councilor_points": ["陳重文議員詢問市府對5G智慧型電杆政策的推動態度，指出直接設置5G微型基地台將面臨道路挖掘問題。陳重文議員建議將全市18萬支路燈及2,600多支交通號誌升級為智慧電杆，附掛5G微型基地台並整合充電樁、環境監測與廣播等功能。陳重文議員建議市府可透過收取基地台租金與充電費用實現營運收入，必要時可請捷運公司協助營運。"], "response": "資訊局局長說明前朝留下的良好政策會概括承受，智慧電杆政策傾向繼續辦理，惟需待概念驗證結果出來後決定擴大程度。資訊局局長認同利用號誌與路燈部署5G微型基地台及充電設施的建議，並表示會進行內部盤點與研議。", "response_removed": false, "topic": "5G智慧型電杆應用計畫與推動"}, {"citations": [{"page": 3022, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=17"}, {"page": 3023, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=18"}, {"page": 3023, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=18"}, {"page": 3025, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=20"}, {"page": 3025, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499EFF5E6F4177B2E1D80F193ED8C8EDEFB9E597F2F7B225843A488394CC7DA00802D1DE3DCEB210BC#page=20"}], "councilor_points": ["陳重文議員指出臺北市市民平均不健康臥床時間達8.47年，主張應透過運動延緩失智症與肌少症。陳重文議員指出市府跨局處每年約有10億元健康促進預算，建議整合成立高齡健康前瞻中心，培訓中級體適能師資並建立長者轉介機制。陳重文議員建議設置A、B、C三級樂齡健康運動站，並要求衛生局於3個月內完成跨局處資源盤點。"], "response": "衛生局局長表達認同透過運動增加健康不臥床餘命的理念，說明轄下健康服務中心與門診均可協助長者轉介與照護。衛生局局長表示同意於3個月內盤點跨局處資源並提出具體規劃方向。", "response_removed": false, "topic": "高齡健康前瞻中心與樂齡健康運動站整合"}, {"citations": [{"page": 2035, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=22"}, {"page": 2036, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=23"}, {"page": 2036, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=23"}, {"page": 2039, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F0C78E50904ED10D1611575CF38E043BCD4FE12463BEDC8F7936596DCFAB1E0E02D1DE3DCEB210BC#page=26"}], "councilor_points": ["陳重文議員指出公立幼兒園室內工作紀錄器裝設比例僅34%，遠低於私立幼兒園的70%以上，質疑幼童就學安全保障不足。陳重文議員要求教育局設定明確目標，利用設備補助預算將公立幼兒園裝設比例於今年提升至50%以上。陳重文議員建議市府將監視器影像資料備份上傳至雲端，並建立嚴格的調閱SOP以防止影像遭刪除。"], "response": "教育局局長說明公立幼兒園室外監視器已達到100%裝設，室內工作紀錄器為34%，市府規劃於113年至116年每年編列5,000萬元預算鼓勵學校設置。教育局局長表示同意朝提升至50%裝設率的目標努力，並承諾優先辦理影像資料上傳雲端與訂定調閱SOP。", "response_removed": false, "topic": "幼兒園工作紀錄器裝設與雲端備份"}, {"citations": [{"page": 1200, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=8"}, {"page": 1201, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=9"}, {"page": 1202, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=10"}, {"page": 1205, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=13"}, {"page": 1205, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=13"}, {"page": 1204, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=12"}, {"page": 1202, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=10"}, {"page": 1203, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=11"}], "councilor_points": ["陳重文議員指出北市公墓使用以7年為限、最多延長至10年，詢問富德公墓是否落實執行。陳重文議員指出歷史資料顯示有下葬超過10年未起掘案件，且未見市府追討代為處理之費用。陳重文議員要求市府落實逕為起掘與追討費用，或進行相關法規檢討。"], "response": "殯葬管理處處長說明公墓使用原則上滿7年需撿骨，最多可申請延長至10年，近幾年均有確實執行公告與逕為起掘程序。殯葬管理處處長表示針對逾期案件若產生費用會經法院程序處理，並承諾將個別未起掘案件回去查明並回報。", "response_removed": false, "topic": "富德公墓墓基使用年限與逾期起掘管理"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-04-18"], "dept": "民政", "doc_type": "部門質詢", "group": 10, "heading": "民政部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4ED6E7A852238F00A7C162#page=1", "transcript_pages": [1193, 1194, 1195, 1196, 1197, 1198, 1199, 1200, 1201, 1202, 1203, 1204, 1205, 1206, 1207, 1208, 1209, 1210], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665492FECD5CE3746B774D9C6CEAEE7044DFA777453832F4E