INSERT INTO "fact" VALUES('summary:14-01:pc50235ea45','pc50235ea45','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:11:40Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2188, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=11"}, {"page": 2188, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=11"}, {"page": 2189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=12"}, {"page": 2189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=12"}, {"page": 2191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=14"}, {"page": 2191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=14"}, {"page": 2190, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=13"}, {"page": 2193, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=16"}], "councilor_points": ["顏若芳議員指出，各縣市均有代表性音樂節，詢問市府規劃中的「台北國際潮流音樂節」推出時間與預算編列狀況，並要求不得將預算全數用於邀請國外團體而忽略國內表演者。顏若芳議員表示，觀光傳播局舉辦的音樂活動與文化局性質重疊，建議整合預算打造具代表性的觀光音樂節。顏若芳議員建議觀光傳播局重新規劃雙層觀光巴士路線，並結合在地歷史文化進行跨局處整合與國際宣傳。"], "response": "文化局局長說明，潮流音樂節重點在於以音樂帶動產業與數位科技，預計 112 年進行初步規劃、113 年試辦，並承諾會以國際與臺灣本土並重的策略整合北流、北藝、北美館等場館進行；觀光傳播局局長表示，會匯整各項吸引觀光客的元素，並透過跨局處合作進行路線規劃，也會朝年底觀光客回流至 8 成的目標努力。", "response_removed": false, "topic": "台北國際潮流音樂節與觀光發展規劃"}, {"citations": [{"page": 1029, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=11"}, {"page": 1030, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=12"}, {"page": 1032, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=14"}, {"page": 1031, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=13"}], "councilor_points": ["顏若芳議員指出，敬老卡點數每年平均使用完畢的比例不到 1 成，長輩普遍反映「不好用」，詢問市府研議擴大使用範圍至醫療、高鐵及機場捷運的進度。顏若芳議員建議市府將敬老卡每月 480 點改為可累積使用至年底，以避免長輩因搭乘長程交通工具發生點數不足的情況，並要求市府於 1 個月內提出評估報告與需求。"], "response": "社會局局長說明，敬老卡使用率低係部分長輩因健康狀況或由家人照顧而較少外出，目前正研議擴大交通與場館使用，關於醫療部分因醫師公會考量行政議題而未同意，且市府已補助健保費，需謹慎評估；社會局局長表示，高鐵與機捷涉及跨縣市合作及 BOT 案，承諾會在 1 個月內向高鐵與機捷提出需求並進行跨縣市討論。", "response_removed": false, "topic": "敬老卡使用率改善與擴大使用範圍"}, {"citations": [{"page": 1654, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=2"}, {"page": 1658, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=6"}, {"page": 1659, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=7"}, {"page": 1655, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=3"}, {"page": 1657, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=5"}], "councilor_points": ["顏若芳議員指出，臺北市商圈受疫情衝擊，但市府目前的振興方案多為一次性活動，缺乏長遠整體規劃。顏若芳議員建議市府參考高雄市結合都市計畫、演唱會與夜市的整體規劃經驗，了解各商圈特色與目標對象，打造帶狀型的商圈廊帶。顏若芳議員要求產業發展局在本會期提出整體且長遠的商圈發展規劃。"], "response": "產業發展局局長說明，今年規劃約 88 場至 90 場活動刺激買氣，並已打造八德商圈新節慶。產業發展局局長表示，認同應做整體商圈規劃，將審慎評估以大型計畫框架串連各商圈，並承諾本會期會提出整體規劃。", "response_removed": false, "topic": "台北市商圈振興與整體廊帶規劃"}, {"citations": [{"page": 4136, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=35"}, {"page": 4138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=37"}, {"page": 4138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=37"}, {"page": 4139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=38"}, {"page": 4139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=38"}, {"page": 4140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=39"}], "councilor_points": ["顏若芳議員指出，微笑單車 YouBike 系統遭駭客入侵導致全國 4 萬多筆資料外洩，但廠商延遲 2 天才通報交通局，且市府初期僅派 1 人前往了解，質疑市府不夠重視。顏若芳議員表示，廠商公告須於 5 月 28 日前報案才予以賠償且設有上限，條約並不合理，且契約每日違約金僅萬分之 0.1（一天 2,340 元）罰則過輕。顏若芳議員要求法務局協助維護權益、廠商應由第三方認證資安，並重新檢討管理契約罰則與賠償規定。"], "response": "市長說明，已要求廠商未來須即刻通報，並認為賠償時間限制過短，會要求廠商放寬讓過 28 日後報案者亦能獲得補償，同時承諾會檢討違約金計算與契約內容。交通局局長說明，已通報調查局與數位發展部，並會同法務局與資訊局進行稽查。法務局局長說明，報案日期不影響民眾法律權利，民眾可至法院主張損害賠償。", "response_removed": false, "topic": "YouBike系統資安事件與賠償條約檢討"}, {"citations": [{"page": 4111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=10"}, {"page": 4112, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=11"}, {"page": 4113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=12"}, {"page": 4114, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=13"}, {"page": 4113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=12"}, {"page": 4111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=10"}], "councilor_points": ["顏若芳議員指出，臺北市已有 48 家綠色餐廳，但市府未掌握相關名單與民間簽署 MOU 之訊息，且跨局處權責不清、互相推諉。顏若芳議員舉臺南市入選全球永續旅遊目的地為例，質疑觀光傳播局等單位缺乏具體規劃，要求市府明確指定永續發展的主責局處並做好統整。"], "response": "市長說明，目前由環境保護局主責，但屬於跨局處業務，已成立氣候變遷因應推動會，會請產業發展局全面盤點綠色餐廳，並承諾會確認主責單位以做好統整與規劃。環境保護局局長說明，局方一直配合環境保護署推動淨零碳排與綠色生活。產業發展局局長說明，知悉北市有綠色餐廳店家，但細部名單不如議員詳細。觀光傳播局局長說明，有與業者座談推廣綠色餐廳與環保旅館。都市發展局局長說明，過去曾與業者合作試辦社宅家具租用，但成效不顯著。", "response_removed": false, "topic": "綠色餐廳推廣與永續觀光主責分工"}, {"citations": [{"page": 4108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=7"}, {"page": 4108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=7"}, {"page": 4109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=8"}, {"page": 4109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=8"}, {"page": 4110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=9"}], "councilor_points": ["顏若芳議員指出，悠遊卡公司興櫃後臺北市政府持股約 4 成，董事席次卻由興櫃前 9 席降至 6 席（另讓出 3 席獨立董事），質疑市府讓出過多席次無法掌握決策，擔心股份遭稀釋與無法監督。顏若芳議員要求市府於下次改選時堅持不設獨立董事，將董事席次爭取拉回原本的 9 席，以實質控制悠遊卡公司並維護市民權益。"], "response": "市長說明，興櫃係前任市府決定，3 席獨立董事仍由市府推薦且為自然人，可平衡與實質掌控董事會，若議會同意也願意增資以確保控制力，並承諾會釐清興櫃決策過程與瞭解爭取席次事宜。交通局局長說明，市府派任 6 席董事仍可維護市府權益，今年派任董事會特別留意，並會在董事會前就爭議議題進行溝通。", "response_removed": false, "topic": "悠遊卡公司興櫃與董事席次爭議"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC#page=6", "transcript_pages": [4107, 4108, 4109, 4110, 4111, 4112, 4113, 4114, 4136, 4137, 4138, 4139, 4140], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 2}]}, {"dates": ["2023-04-17"], "dept": "民政", "doc_type": "部門質詢", "group": 1, "heading": "民政部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162#page=10", "transcript_pages": [1028, 1029, 1030, 1031, 1032, 1033, 1034, 1035, 1036, 1037, 1038], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB9637356654954F8BA445A6FB939C6F0A29C50BDD0C7B158DFE2A759EB70A852238F00A7C162", "videos": [{"date": "2023-04-17", "group": 1}]}, {"dates": ["2023-04-25"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC#page=1", "transcript_pages": [1653, 1654, 1655, 1656, 1657, 1658, 1659], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665498AFAB405376ED5C0E7043DBAC236DC9661D55A375A8D6F67066151E809B6F3A002D1DE3DCEB210BC", "videos": [{"date": "2023-04-25", "group": 8}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC#page=10", "transcript_pages": [2187, 2188, 2189, 2190, 2191, 2192, 2193, 2194, 2195, 2196], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549F77114121AE5C2BC30583689D61A012FE9145BF005F7B5A03DCB68E940C36A0802D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 11}]}, {"dates": ["2023-05-11"], "dept": "交通", "doc_type": "部門質詢", "group": 12, "heading": "交通部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F96250F5A353C8FF334EE2E30B4B7D813920DC9B2F2092C2928D9102DE330AAF02D1DE3DCEB210BC#page=10", "transcript_pages": [2684, 2685, 2686, 2687, 2688, 2689], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB96373566549F96250F5A353C8FF334EE2E30B4B7D813920DC9B2F2092C2928D9102DE330AAF02D1DE3DCEB210BC", "videos": [{"date": "2023-05-11", "group": 12}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 9, "heading": "警政衛生部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499FB5C4B131A9D740FB7C57C39CF4D192E25BD779F866846ED6BC13EF21971C1D02D1DE3DCEB210BC#page=6", "transcript_pages": [3080, 3081, 3082, 3083, 3084], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665499FB5C4B131A9D740FB7C57C39CF4D192E25BD779F866846ED6BC13EF21971C1D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 9}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC#page=15", "transcript_pages": [3751, 3752, 3753, 3754, 3755, 3756, 3757], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB963735665493D614B53F0D073CE7241EDEFDD9C791001C1D93A6530BA798FBAE498E2AA1BE402D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 12}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549A3477A65E511018DB7C4584F7AB7B7FA33C459B2364BA7D2966B8ED475F1688102D1DE3DCEB210BC','2026-10-03T01:11:40Z');
INSERT INTO "fact" VALUES('summary:14-01:pacac98c45a','pacac98c45a','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:14:09Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=49"}, {"page": 4088, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=50"}, {"page": 4089, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=51"}, {"page": 4092, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=54"}, {"page": 4094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=56"}, {"page": 4091, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=53"}, {"page": 4093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=55"}], "councilor_points": ["黃瀞瑩議員關切社會住宅推動聯盟的訴求，詢問市長規劃的 7,000 戶社會住宅取得管道、期程與相關預算（「這 7,000 戶有沒有取得的管道和期程？有沒有籌備相關的預算？」〔公報第4088頁〕）。黃瀞瑩議員指出 4 年任內屬於現任市府規劃動工的社宅預估僅 90 戶，要求市府提出 7,000 戶潛力基地的具體工作計畫，並透過 EOD 等管道以 5 萬戶為目標持續興辦社宅（「提出 7,000 戶潛力基地具體的工作計畫……以 5 萬戶為目標，持續不斷透過基地盤整、EOD 等管道，興辦社會住宅。」〔公報第4090頁〕）。黃瀞瑩議員表示租金補貼與包租代管無法取代興建社會住宅，建議市府研議與評估實施社會住宅輪候制（「租金補貼和包租代管並不完全取代興建社會住宅……你可以評估輪候制嗎？」〔公報第4093頁、第4094頁〕）。"], "response": "市長說明興建社宅是解決居住問題的政策手段，規劃 4 年內承接前任市府已規劃及招標待開工工程預計有 7,627 戶完工，並預計 4 年內會有 2,820 戶開工（「我們規劃在這 4 年承接前任市府已經規劃及已經招標待開工的工程，預計在這 4 年會有 7,627 戶完工……我們預計在這 4 年會有 2,820 戶開工」〔公報第4087頁、第4088頁〕）。都市發展局局長說明預計於 115 年會有 1 處基地動工，規劃於樟新市場興建 90 戶，並將於明年提出規劃設計預算（「我們預計在 115 年會有 1 處開工……在樟新市場規劃 90 戶……我們會在明年提規劃設計的預算。」〔公報第4088頁、第4089頁〕）。市長與都市發展局局長表示會指派副市長協調 EOD 專案，將對外說明潛力基地計畫，且都市發展局已開始對社宅輪候制進行研究與評估（「我們會指派林副市長……對外說明潛力基地在哪裡……都發局已經開始評估。」〔公報第4091頁、第4093頁、第4094頁〕）。", "response_removed": false, "topic": "社會住宅興辦進度與多元取得管道"}, {"citations": [{"page": 4053, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=15"}, {"page": 4054, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=16"}, {"page": 4055, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=17"}, {"page": 4057, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=19"}, {"page": 4056, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=18"}], "councilor_points": ["黃瀞瑩議員指出環狀線第一階段營運行政契約於 1 月 30 日到期，交接過渡期間仍由臺北捷運公司支援人力與營運，質疑新北市政府未準備好（「行政契約在 1 月 30 日已經到期，一直到 5 月 23 日才完成移轉跟交接……人力的部分還是由臺北捷運公司支援他們」〔公報第4053頁〕）。黃瀞瑩議員詢問 5 月 10 日臺中捷運事件發生後市府清查捷運沿線 121 處工地是否包含新北環狀線第一階段，並要求說明人力支援契約進度（「121 處的工地，有沒有包含環狀線第一階段？……現在的營運契約，人力支援部分，契約內容討論好了嗎？」〔公報第4054頁、第4056頁〕）。黃瀞瑩議員提出環狀線第一階段營運移轉與支援計畫應公開透明，並要求市府爭取捷運環狀線南北環段完工後由臺北捷運公司經營（「第 1 個，環狀線第一階段營運跟移轉計畫，還有支援的情況，應該要公開透明……第 2 點，捷運環狀線南北環段在完工之前，應該要儘速決定經營權的事情，爭取由臺北捷運公司來經營環狀線。」〔公報第4057頁〕）。"], "response": "捷運工程局局長說明 121 處工地為臺北市區捷運線沿線工地，不包含環狀線第一階段，雙方協議自 5 月 13 日起全部運轉與權責移轉至新北市政府（「121 處是臺北市區捷運線的沿線工地……5 月 13 日凌晨全部的運轉、權力、條件全部屬於新北市政府。」〔公報第4054頁〕）。臺北大眾捷運股份有限公司總經理表示與新北捷運公司就人力支援已有共識，預計 6 月 1 日確定後簽約，給予時間招募與訓練新人（「我們跟新北捷運公司已經有共識，會依據共識簽約……6 月 1 日確定好之後就會簽約。」〔公報第4056頁〕）。市長說明捷運周邊施工工地共 179 處，其中 121 處在臺北市市區內，承諾移轉與支援狀況會公開透明，並會爭取環狀線南北環段完工後的經營權（「我們的捷運周邊有施工的工地有 179 處，121 處是在臺北市市區內的施工工地……這兩點我們可以做到，包括確保臺北捷運公司的員工，相關的權益會公開透明，以及爭取捷運環狀線南北環段在完工之後，確定由哪一個縣市經營。」〔公報第4054頁、第4057頁〕）。", "response_removed": false, "topic": "捷運環狀線第一階段營運移交與人力支援"}, {"citations": [{"page": 3589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=3"}, {"page": 3589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=3"}, {"page": 3590, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=4"}, {"page": 3591, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=5"}, {"page": 3592, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=6"}], "councilor_points": ["黃瀞瑩議員關切關渡平原國土功能分區劃設，建議都市發展局在第二次國土審議會召開前至在地舉辦說明會，落實公民參與並聽取農民與地主意見（「希望透過這次的質詢，都市發展局可以再到當地召開說明會……促進都市發展局及在地居民的溝通，進而形成一些共識。」〔公報第3589頁〕）。黃瀞瑩議員指出大度路以南公共設施保留地長期未徵收，並詢問體育局與公園路燈工程管理處對該地劃設公園及運動場館之規劃（「大度路的南側有 2 大塊土地，一塊是公園路燈工程管理處的景觀用地、一塊是體育局的運動公園用地，其實這 30 年以來，這 2 塊公共設施保留地都沒有太多的決定或是想法。」〔公報第3591頁〕）。黃瀞瑩議員要求都市發展局會同工務局與體育局，研擬公共設施保留地取得方法或短期活化策略（「希望都市發展局、工務局、體育局，先行研擬取得的方法或短期活化的一些策略……」〔公報第3592頁〕）。"], "response": "都市發展局局長說明關渡平原大度路以北劃設為農業發展地區第五類，尊重產業發展局維持農業區使用政策，並承諾在第二次國土審議會前至地方辦理說明會（「在大度路以北部分，目前是劃設為農發五，主要還是維持農業發展的部分……我們會儘速再到地方上辦理說明會及溝通。」〔公報第3589頁、第3590頁〕）。體育局運動設施科科長說明關渡運動公園面積約 90 公頃，曾有以容積移轉取得土地及爭取 2038 亞運興建 11 座場館之構想；公園路燈工程管理處處長表示景觀用地面積 85 公頃，預估徵收費用 408 億元，目前尚無徵收計畫（「關渡運動公園的面積非常大，大概有九十公頃左右……以爭取 2038 年亞洲運動會為目標……總共有 11 座場館……這塊土地的面積是 85 公頃，徵收費用就誠如剛才議員所說的 408 億元……目前還沒有徵收的計畫。」〔公報第3591頁、第3592頁〕）。都市發展局局長表示會會同工務局與體育局共同研議，評估採用徵收或容積移轉方式處理公共設施保留地（「我們會同工務局、體育局共同研議，包括土地可以用徵收取得或是容積移轉的方式，對於這麼長久劃為公共設施用地的土地所有權人做一個交代……」〔公報第3592頁〕）。", "response_removed": false, "topic": "關渡平原國土功能分區與公共設施保留地規劃"}, {"citations": [{"page": 1295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=14"}, {"page": 1807, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=1"}, {"page": 1808, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=2"}, {"page": 1808, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=2"}, {"page": 1809, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=3"}, {"page": 1809, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=3"}, {"page": 1810, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=4"}, {"page": 1810, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=4"}], "councilor_points": ["黃瀞瑩議員指出居住正義不能僅靠興建社宅，詢問財政局在稅制改革與租屋市場健全化可扮演的主責角色（「居住正義的實踐是不是不單只靠蓋社宅就可以完成？……財政局在居住正義裡面可以扮演什麼樣的主責角色？」〔公報第1807頁、第1808頁〕）。黃瀞瑩議員建議財政局主責盤點市有房地以配合推動社宅，並要求設定年度目標持續運用低度水電清查空屋（「盤點市有房產這件事情財政局可以作為主責單位……如果每一年持續以低度水電清查房屋，財政局接下來的幾年都應該要列出清楚的工作目標……」〔公報第1808頁、第1809頁〕）。黃瀞瑩議員建議財政局持續推動房屋稅基合理化，並向中央倡議全國歸戶及提高 3.6% 囤房稅上限，同時協助改革租屋黑市（「就你們可以掌握的部分，持續努力讓房屋的稅基合理化……對於多屋族的持有成本可以繼續提高……對於中央該倡議的部分，也應該持續倡議。」〔公報第1810頁〕）。"], "response": "財政局局長說明居住正義涵蓋社宅、稅制與金融等面向，市府正藉由每 3 年不動產房屋稅評價調整進行委託研究，以學術角度讓稅制更公平合理（「它是多面向的，包括社宅或是稅制或是住宅政策，甚至金融面都有關……我們剛好遇到每 3 年不動產房屋稅評價調整……讓稅制更公平合理。」〔公報第1807頁、第1808頁〕）。財政局局長說明過去 3 年運用低度水電清查出 2 萬戶，約半數改非自住課稅，預計今年將由稅捐稽徵處持續清查 1,500 戶（「過去 3 年清查出 2 萬戶，大概快一半發現不是自住，就改非自住課稅……預計今年會持續清查 1,500 戶。」〔公報第1808頁、第1809頁〕）。財政局局長表示目前臺北市約有 12 萬戶適用多屋較高稅率，若各縣市採差別稅率後房價負擔仍高，可討論將上限 3.6% 往上調，並會配合國稅局將租屋黑市檯面化（「目前大概有 12 萬戶是適用多屋比較高的稅率……可以把最高稅率再往上調……我們也會就怎麼讓租屋黑市可以檯面化，讓租賃市場合理化，會一起努力。」〔公報第1809頁、第1810頁〕）。", "response_removed": false, "topic": "臺北市房屋稅制改革與居住正義推動"}, {"citations": [{"page": 1293, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=12"}, {"page": 1293, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=12"}, {"page": 1295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=14"}, {"page": 1294, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=13"}, {"page": 1295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=14"}], "councilor_points": ["黃瀞瑩議員指出社子島開發案歷經防洪、都市計畫與環評，目前停留在內政部審議區段徵收範圍與抵價地比例，詢問市府後續推動態度（「經過各個計畫的審議歷程，包含防洪計畫、都市計畫、文資保存計畫到環境影響評估計畫，而現在停留在區段徵收計畫……所以市府對於整個社子島開發的態度，是繼續朝生態社子島及區段徵收的方向嗎？」〔公報第1292頁、第1293頁〕）。黃瀞瑩議員關切內政部承諾召開的專案小組會前會進度，建議市府官員拜訪中央釐清審議標準（「內政部在公聽會上有答應我們，在專案小組召開第三次會議之前，要召開一場會前會……不曉得局長有沒有率隊到中央釐清相關的問題？」〔公報第1293頁、第1294頁〕）。黃瀞瑩議員要求地政局持續與中央及居民溝通、說明開發案公益性與必要性，並建議市長或副市長親自至地方向居民說明（「第 1 點，身為局長，還是要努力的跟中央溝通。第 2 點，還是要強化社子島開發案的公益性跟必要性的說明跟規劃……第 4 點，建議局長應該要建議市長親自到中央做報告，到地方走一走，跟地方居民說明整體開發政策……」〔公報第1295頁〕）。"], "response": "地政局局長說明市府於 109 年 6 月 23 日將區段徵收範圍與抵價地比例計畫送內政部審議，市府將延續現有方案推動，並滾動式檢討安置計畫（「109 年 6 月 23 日區段徵收範圍跟抵價地比例相關計畫送內政部審議……我們會延續現有的方案，穩健的往後做推動，市長的指示是協助落實安置計畫做滾動式的檢討。」〔公報第1292頁、第1293頁〕）。地政局局長表示無法接受將 9 大聚落全部剔除之建議，並說明已安排由副市長帶隊拜訪內政部地政司（「我們沒有辦法接受要將 9 大聚落全部剔除，這樣的作法影響很大……我們有安排副市長……等安排好之後，再跟議員報告。」〔公報第1293頁、第1294頁〕）。地政局局長表示市府已有召開跨局處聯繫會報逐步處理修繕與環境改善問題，適當時機會向市長報告至地方向居民說明（「市長有授權我對於相關局處的工作有一個聯繫的會報，已經召開一次會議……議員提到市長要到中央或者地方說明，適當的機會跟作業，我一定會跟市長報告。」〔公報第1295頁〕）。", "response_removed": false, "topic": "社子島開發案區段徵收與溝通機制"}, {"citations": [{"page": 2172, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=28"}, {"page": 2173, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=29"}, {"page": 2174, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=30"}, {"page": 2175, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=31"}, {"page": 2174, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=30"}], "councilor_points": ["黃瀞瑩議員指出臺北市 2 歲至 3 歲幼兒入園率為 23%，低於 OECD 國家之 45%，並試算若以 7 成公共化為目標，2 歲專班尚需 4,576 個名額（約 72 班），建議教育局提出未來 4 年增班計畫（「臺北市在學前幼兒，2 歲到 3 歲的入園率大概是 23%，跟 OECD 國家的 45%……我發現臺北市 2 歲專班至少還要 4,576 個人的量能，換句話說，我們還需要 72 班左右……希望教育局可以針對未來四年，應該提出一個 2 歲專班的增班計畫。」〔公報第2172頁、第2173頁〕）。黃瀞瑩議員反映社子國小等幼兒園在增設 2 歲專班時減少 3 到 5 歲班級名額之狀況，要求教育局增加 2 歲專班時不應排擠 3 至 5 歲學童入學機會（「社子國小，2 歲專班在增加的同時，3 到 5 歲的班級居然被減少了……在增加 2 歲專班的同時，不應該減少 3 歲學童入學的機率。」〔公報第2173頁、第2174頁〕）。黃瀞瑩議員關切教育部規劃將 3 到 5 歲班級師生比從 1：15 調降至 1：12，要求教育局提出未來 3 年調降計畫且不影響學童就學機會（「教育部接下來在今年 8 月要開始實施公幼與非營利幼兒園先行推動 3到 5 歲班級的師生比要調降，從 1：15 調到 1：12……希望局長可以提出未來三年各個型態園所的師生比的調降計畫……」〔公報第2174頁、第2175頁〕）。"], "response": "教育局局長說明去年設籍 2 歲幼兒 1 萬 7 千多人中就讀公共幼兒園者為 8,597 人（入園率 49.9%），教育局將先檢視空間，將 3 到 5 歲多餘教室直接改設為 2 歲專班，並規劃增班計畫（「設籍的人數有 1 萬 7 千多個人，來就讀的是 8,597 人，所以它的入園率大概只有 49.9%……像我們這一次 3 到 5 歲班有多出來的，我們就把它直接改成 2 歲專班……」〔公報第2172頁、第2173頁〕）。教育局局長說明係將部分招收未滿額之 3 到 5 歲班級轉為 2 歲專班以避免資源浪費，並承諾增加 2 歲專班時會特別注意不排擠 3 到 5 歲學童入學（「那是因為有一些 3 到 5 歲的班，招生的空額比較多……我們就把它直接轉成 2 歲班……這個部分我們會來特別注意。」〔公報第2173頁、第2174頁〕）。教育局局長說明臺北市已有 10 個幼兒園試辦師生比調降，規劃採增班、增置教保員及偏遠地區直接降至 1：12 等方式，其餘園所採 1：14、1：13 至 1：12 逐年下降（「有 10 個幼兒園已經做試辦計畫……偏遠地區的幼兒園直接就下降到 1：12……其他的幼兒園，我們會朝 1：14、1：13 到 12 逐年下降的方式來做處理。」〔公報第2175頁〕）。", "response_removed": false, "topic": "公立及非營利幼兒園2歲專班增設與師生比調降"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-05-29"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC#page=15", "transcript_pages": [4053, 4054, 4055, 4056, 4057, 4058, 4059, 4060, 4087, 4088, 4089, 4090, 4091, 4092, 4093, 4094, 4095, 4096], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC", "videos": [{"date": "2023-05-29", "group": 1}]}, {"dates": ["2023-04-20"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162#page=8", "transcript_pages": [1289, 1290, 1291, 1292, 1293, 1294, 1295], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6ED3EAB76E53227D4A02DB963735665496D71FF048F1401C7575A1A24A0CD87961427C3321CBBAB95A852238F00A7C162", "videos": [{"date": "2023-04-20", "group": 13}]}, {"dates": ["2023-04-28"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC#page=1", "transcript_pages": [1807, 1808, 1809, 1810, 1811, 1812], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB963735665497F0500801333E94D1A783FDF0608F3F1DFCC62986054436539A068508590C2E502D1DE3DCEB210BC", "videos": [{"date": "2023-04-28", "group": 16}]}, {"dates": ["2023-05-02", "2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC#page=26", "transcript_pages": [2170, 2171, 2172, 2173, 2174, 2175, 2176, 2177], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB96373566549883B8082AA0BFC87CAB74A80DEAD8FD6C3F971CA2609BA0D705732E7743C84E302D1DE3DCEB210BC", "videos": [{"date": "2023-05-02", "group": 10}, {"date": "2023-05-04", "group": 10}]}, {"dates": ["2023-05-09"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC#page=18", "transcript_pages": [2574, 2575, 2576, 2577, 2578, 2579, 2580, 2581, 2582], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB9637356654941C50B329F56C81CA4BACDFEA44A9332E8128D4683FF52A96F81DC63F88CEB6002D1DE3DCEB210BC", "videos": [{"date": "2023-05-09", "group": 7}]}, {"dates": ["2023-05-16"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC#page=8", "transcript_pages": [3043, 3044, 3045, 3046, 3047, 3048, 3049], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB96373566549A8AB247915EA98BD6D3396F29A5CFE0B44C4672B093592CE5F73D747C664765C02D1DE3DCEB210BC", "videos": [{"date": "2023-05-16", "group": 7}]}, {"dates": ["2023-05-22"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC#page=1", "transcript_pages": [3587, 3588, 3589, 3590, 3591, 3592, 3593], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D12FD9044A99DB225B1F22805C37D17E0A4A1EDBC2D0597FEC23F4AB6698199E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-22", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB96373566549F23EC8D51BC19C61E4A21447E7507E45870D981378EA029D331C92CED3F2922D02D1DE3DCEB210BC','2026-10-03T01:14:09Z');
