INSERT INTO "fact" VALUES('ly_interpellation:11-2-14-46:p12180ab9a4','p12180ab9a4','ly_interpellation','2024-12-18','{"co_legislators": [], "meet_id": "院會-11-2-14", "no": "11-2-14-46", "page_end": 6, "page_start": 5, "session": 2, "title": "本院王委員美惠，針對嘉義市醫療資源有待提升，衛生福利部應支持嘉義醫院東院區興建工程所需經費，縮短興建期程，並妥適調整醫療區域，提供嘉義市民充足病床量數，需協助嘉義市地區醫療機構，提升癌症、兒童專科醫療量能，並輔導嘉義市地區設立醫學中心，及改制後的國家中醫藥研究所應落腳嘉義市，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-14-46','2026-10-03T13:07:47Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-3-7-30:p12180ab9a4','p12180ab9a4','ly_interpellation','2025-04-09','{"co_legislators": [], "meet_id": "院會-11-3-7", "no": "11-3-7-30", "page_end": 19, "page_start": 17, "session": 3, "title": "本院王委員美惠，為政府所提出之「大南方新矽谷推動方案」及正在規劃中的嘉義科學園區擴建計畫，應考慮到區域整體發展，針對嘉義市因南部半導體 S 廊帶與科學園區發展後，所需之交通運輸、人口居住、教育文化、用水用電及醫療資源等建設，要求政府均須提早規劃，納入推動方案及擴建計畫中，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-3-7-30','2026-10-03T13:07:47Z');
