INSERT INTO "fact" VALUES('ly_interpellation:11-1-15-56:p6f910e7755','p6f910e7755','ly_interpellation','2024-05-22','{"co_legislators": [], "meet_id": "院會-11-1-15", "no": "11-1-15-56", "page_end": 4, "page_start": 1, "session": 1, "title": "本院陳委員素月，針對許多民眾反映我國 COVID-19 疫苗預 防接種受害救濟程序等待時間冗長，自開始申請至今遲遲未有進度，平均等待期間動輒一年有餘，期間受害民眾歷經全身 紅 疹 發 癢 、 食 不 下 嚥 等 後 遺 症 折 磨 ， 身 心 備 受 煎 熬 ，紛 紛 質疑 疫 苗接 種 受害 救 濟案 件 審議 進 度緩 慢 ，不 符 民 眾期待。據了解，疾管署現今每月召開 2 次審議會議，平均審議約 300 件與 2020 年每月平均 13 件相比成長近 23 倍，而審議專家學者雖已從起初的 24 名增加至逾 50 名，但整體審 議 進度 仍 不見 有 感， 本 席 為 反 映民 情 與民 眾 心聲 ， 建 請行政院研擬相關因應對策，並敦促加速審查速度，特向行政院提出質詢。專案質詢11－1－15－0057立法院議案關係文書 中華民國 113 年 5 月 22 日印發案由：本院陳委員素月，針對農民不斷陳情反映近年來稻米耕作的肥料、農藥、秧苗等人力成本不斷上漲，但公糧收購價格已長達 13 年未調漲，已不敷成本，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-15-56','2026-10-03T13:07:47Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-16-56:p6f910e7755','p6f910e7755','ly_interpellation','2024-05-29','{"co_legislators": [], "meet_id": "院會-11-1-16", "no": "11-1-16-56", "page_end": 5, "page_start": 1, "session": 1, "title": "本院陳委員素月，針對許多民眾反映我國 COVID-19 疫苗預 防接種受害救濟程序等待時間冗長，自開始申請至今遲遲未有進度，平均等待期間動輒一年有餘，期間受害民眾歷經全身 紅 疹 發 癢 、 食 不 下 嚥 等 後 遺 症 折 磨 ， 身 心 備 受 煎 熬 ，紛 紛 質疑 疫 苗接 種 受害 救 濟案 件 審議 進 度緩 慢 ，不 符 民 眾期待。據了解，疾管署現今每月召開 2 次審議會議，平均審議約 300 件，與 2020 年每月平均 13 件相比成長近 23 倍，而審議專家學者雖已從起初的 24 名增加至逾 50 名，但整體 審 議進 度 仍不 見 有感 ， 本 席 為 反映 民 情與 民 眾心 聲 ， 建請行政院研擬相關因應對策，並敦促加速審查速度，特向行政院提出質詢。專案質詢11－1－16－0057立法院議案關係文書 中華民國 113 年 5 月 29 日印發案由：本院陳委員素月，針對農民不斷陳情反映近年來稻米耕作的肥料、農藥、秧苗等人力成本不斷上漲，但公糧收購價格已長達 13 年未調漲，已不敷成本，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-16-56','2026-10-03T13:07:47Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-3-2-8:p6f910e7755','p6f910e7755','ly_interpellation','2025-02-20','{"co_legislators": [], "meet_id": "院會-11-3-2", "no": "11-3-2-8", "page_end": 19, "page_start": 17, "session": 3, "title": "本院陳委員素月，針對經濟部「納管工廠低碳及智慧化基礎轉型個案補助」之民眾陳情案，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-3-2-8','2026-10-03T13:07:47Z');
