INSERT INTO "fact" VALUES('ly_interpellation:11-2-13-43:pb1930075c0','pb1930075c0','ly_interpellation','2024-12-11','{"co_legislators": [], "meet_id": "院會-11-2-13", "no": "11-2-13-43", "page_end": 2, "page_start": 1, "session": 2, "title": "本院何委員欣純，針對菇類為國民日常生活中經常使用之食材，亦為我國重要之農業作物。2023 年我國菇類整體產值達91.31 億元，其中又以臺中新社等中部地區種植之香菇產值最高，對於我國中部地區農業發展貢獻良多。因此，對於香菇、洋菇、金針菇等菇類栽培產業之永續發展，政府應予以協助。基於健全國內菇類產業健全發展及保障食品安全等考量，目前我國並未開放中國大陸香菇進口。然查，市面上仍多有中國大陸香菇循走私途徑或假借第三國產品名義進入國內市場，對我國農業發展及國民健康影響甚鉅。為保障菇農權益、落實食品安全，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-13-43','2026-10-03T13:07:47Z');
