INSERT INTO "fact" VALUES('ly_interpellation:11-1-5-15:p90486bc541','p90486bc541','ly_interpellation','2024-03-13','{"co_legislators": [], "meet_id": "院會-11-1-5", "no": "11-1-5-15", "page_end": 3, "page_start": 1, "session": 1, "title": "本院謝委員龍介，鑑於我國主要消費市場位處北臺灣，常需大型車輛南來北往載運暢貨，串聯產業供應鏈。惟民眾反映，國道服務區及地磅站停車及廁所之設置仍未完善，致生不便。為建立國道服務區及地磅站友善駕駛環境，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-5-15','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-14-54:p90486bc541','p90486bc541','ly_interpellation','2024-05-15','{"co_legislators": [], "meet_id": "院會-11-1-14", "no": "11-1-14-54", "page_end": 3, "page_start": 1, "session": 1, "title": "本院謝委員龍介，鑑於「勞工職業災害保險職業傷病審查準 則」第四條第一項僅規定：「勞工上、下班於適當時間，從日常居、住處所往返工作場所的應經途中發生事故而導致的傷害，視為職業傷害。」若勞工於上班時請假外出辦事，如：看診、赴機關洽公等等，從辦事地點出發再上班時發生意外，卻因出發地非居住處所，不符合通勤定義，不被認為與工作本身緊密連接，而無法被定義為職業災害，於理實屬不合。建請勞動部重新檢討修正前述審查準則規定，以維護勞工權益，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-14-54','2026-10-03T13:34:40Z');
