INSERT INTO "fact" VALUES('ly_bill:222113237410000:pacfb33b588','pacfb33b588','ly_bill','2024-06-21','{"bill_no": "222113237410000", "category": "臨時提案", "status": "排入院會", "title": "有鑑於國營臺灣鐵路股份有限公司於民國（以下同）104至113年辦理「臺鐵整體購置及汰換車輛計畫」，規劃購置1,282輛動力車及客車，以汰換已逾最低使用年限之復興號、莒光號客車。然自114年開始有300餘輛（EMU500型）車逾最低使用年限；116年高達700餘輛車逾最低使用年限，目前均尚無相關汰除計畫，惟參考本期購置及汰換車輛計畫耗時十年，因此無論是考量提昇搭乘體驗抑或是未來可能無零件汰換情形皆有必要立即啟動新一期的購置及汰換車輛計畫。爰此，請國營臺灣鐵路股份有限公司應於一個月之內啟動新一輪「臺鐵整體購置及汰換車輛」之評估計畫，並就過往查核機關指證之缺失，強化採購規劃、發包及驗收等作業；精進未來交車之標準作業流程並增進安全控管。是否有當？請公決案。"}','https://ly.govapi.tw/v2/bill/222113237410000','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_bill:202110021910000:pacfb33b588','pacfb33b588','ly_bill','2024-03-29','{"bill_no": "202110021910000", "category": "法律案", "status": "交付審查", "title": "「偏遠地區學校教育發展條例第八條、第十二條及第二十一條條文修正草案」，請審議案。"}','https://ly.govapi.tw/v2/bill/202110021910000','2026-10-03T13:34:40Z');
