INSERT INTO "fact" VALUES('ly_bill:222113237370000:pacfb33b588','pacfb33b588','ly_bill','2024-04-09','{"bill_no": "222113237370000", "category": "臨時提案", "status": "排入院會", "title": "有鑒於0403花蓮地震，截至目前除造成13人死亡、1,140人受傷、6人失聯外，同時全台各地陸續傳出房屋倒塌、鋼筋牆壁發生龜裂的情況，尤其是花蓮、新北市、台北市、基隆市等更為嚴重；經國土署統計，截至今(8)日止，花蓮縣、台北市、桃園市、新北市及基隆市等五地請求勘災總數已達848件，經確認為紅單的有42件（花蓮32件，臺北2件，桃園4件及新北4件），為黃單的有70件（花蓮35件，臺北13件、桃園14件、新北市7件及基隆1件），無須張貼危險標誌件數693件；惟行政院目前僅撥付3億元救助花蓮強震，比照921大地震時的重建特別條例，實屬遠遠不足。為盡速協助受災戶度過難關及重建家園，爰建請行政院應比照921重建條例或依據預算法第83條提出「0403大地震災害特別條例」，以利爭取更多預算，回應民眾災後重建、修繕的需求。是否有當？請公決案。"}','https://ly.govapi.tw/v2/bill/222113237370000','2026-10-03T13:34:40Z');
