INSERT INTO "fact" VALUES('ly_interpellation:11-1-6-21:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-03-20','{"co_legislators": [], "meet_id": "院會-11-1-6", "no": "11-1-6-21", "page_end": 11, "page_start": 9, "session": 1, "title": "本院吳委員宗憲，針對數位身分證因資安爭議喊卡，政府須賠償廠商二億八千萬元，這筆費用由全民埋單。經查，數位身分證政策 2021 年因資安爭議喊卡，廠商向政府求償總計逾十億元，今年 1 月經六次調解，賠償金額雖砍至二億八千萬元以下，然而內政部僅用一句「無行政疏失」帶過，費用卻由全民埋單。有鑑於數位身分證攸關全民個資安全，且龐大的賠償金額由人民的納稅錢支付，應主動向大眾交代清楚，爰此要求內政部針對數位身分證政策進行檢討，並於一個月內提出書面報告，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-6-21','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-6-22:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-03-20','{"co_legislators": [], "meet_id": "院會-11-1-6", "no": "11-1-6-22", "page_end": 13, "page_start": 11, "session": 1, "title": "本院吳委員宗憲，針對去年我國假投資詐騙案件數創新高，造成多數民眾血本無歸。經查，我國目前尚未有可監管處罰虛擬幣犯罪之專法。有鑑於詐騙集團常利用個人幣商收取贓款，一旦被查獲就稱自己是個人幣商，對相關交易不知情，因此常獲不起訴，爰此要求法務部與金管會儘速針對個人幣商之管理研議專法，並將其研議結果以書面報告送交立法院全體委員，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-6-22','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-6-23:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-03-20','{"co_legislators": [], "meet_id": "院會-11-1-6", "no": "11-1-6-23", "page_end": 14, "page_start": 13, "session": 1, "title": "本院吳委員宗憲，鑑於衛福部於本（3）月 4 日廢止掛號費用調整備查制度，取消健保掛號費上限，此舉引發民間反彈；若就此將掛號費收費全權交由各醫療院所自行決定，美其名曰回歸市場機制，然而將產生的後續效應無可估量，醫療單位想漲就漲，又並無新設或加強現行防堵聯合漲價行為之機制，可能將貶抑民眾就醫意願以及增加其於醫療上之付出。爰此，建請全民健保主管機關衛生福利部，研議暫緩廢止掛號費上限，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-6-23','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-11-44:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-04-24','{"co_legislators": [], "meet_id": "院會-11-1-11", "no": "11-1-11-44", "page_end": 15, "page_start": 13, "session": 1, "title": "本院吳委員宗憲，鑑於近日某大專院校於學生自治選舉中，遭指控發生學校高層大規模安插人選之情事，若類似之介選情事屬實，則將嚴重影響校園內自由民主之自治環境，與學生自治立法之初衷背離甚遠。爰此，建請教育部研議《大學法》及《專科學校法》相關規定，防止校方過度介入學生自治選舉，以健全校園民主之落實，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-11-44','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-12-48:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-05-01','{"co_legislators": [], "meet_id": "院會-11-1-12", "no": "11-1-12-48", "page_end": 3, "page_start": 1, "session": 1, "title": "本院吳委員宗憲，針對高雄民生醫院開錯刀事件，經查 ，原 本 應為 胸 腔膿 包 患者 進 行引 流 手術 ， 然卻 錯 把隔 壁 床 低血 壓 患者 推 入開 刀 房， 直 到主 刀 醫師 動 刀後 ， 才驚 覺 搞 錯對 象，整個過程經手五人，沒有一人確認患者身分。然該院不只 一 次 發 生 嚴 重 醫 療 疏 失 ， 長 此 以 往 恐 引 發 民 眾 對 公 家醫 療安全之疑慮，亦影響對醫院之信任，爰此要求衛福部就手術安全把關執行流程進行檢討，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-12-48','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-12-49:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-05-01','{"co_legislators": [], "meet_id": "院會-11-1-12", "no": "11-1-12-49", "page_end": 5, "page_start": 3, "session": 1, "title": "本院吳委員宗憲，有鑑於曾質詢有關逃兵與軍人自傷之議題，然該軍團再傳出僅入伍 2 天的新兵逃跑後又自行返營，另有一名 19 歲志願役跳樓輕生，短短四天發生 2 起案件，不免 擔 心 是 否 為 軍 中壓 力 過大 所 致。 經 查， 過 去監 察 院 在士 兵自殺調查報告中指出，目前軍隊編制的心理輔導官太少，有 關 精 神 疾 病 的 判 斷 與 診 療 ， 也 應 交 由 專 業 精 神 科 醫 師進 行 協處 ， 爰此 要 求國 防 部儘 快 引入 相 關資 源 ，積 極 照 顧國軍心理健康，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-12-49','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-2-18-65:paf0d0727f1','paf0d0727f1','ly_interpellation','2025-01-15','{"co_legislators": [], "meet_id": "院會-11-2-18", "no": "11-2-18-65", "page_end": 5, "page_start": 1, "session": 2, "title": "本院吳委員宗憲，有鑑於使用牌照稅法第五條第二項規定，完全以電能為動力之機動車輛使用牌照稅將於 114 年 12 月 31 日停止免徵。根據公路局最新統計，領有統一牌照電動汽車高達94,731 輛，機車 770,290 輛，合計超過 17 萬輛。依相關規定，完全以電能為動力之電動小客車、機車、大客車及貨車皆以馬力為收稅標準。然電動車與燃油車的馬力輸出原理不同，使用馬力作為收稅標準可能使電動車有實際對道路損耗較少卻因其高馬力而支付較高稅金的不平等情形產生。爰此要求財政部針對電動車收稅標準，參考各界意見後研議調整方向，以 保障 電能 車之 公 平牌 照稅 收稅 方 式， 特向 行政 院 提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-18-65','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-2-17-65:paf0d0727f1','paf0d0727f1','ly_interpellation','2025-01-08','{"co_legislators": [], "meet_id": "院會-11-2-17", "no": "11-2-17-65", "page_end": 5, "page_start": 1, "session": 2, "title": "本院吳委員宗憲，有鑑於使用牌照稅法第五條第二項規定，完全以電能為動力之機動車輛使用牌照稅將於 114 年 12 月 31 日停止免徵。根據公路局最新統計，領有統一牌照電動汽車高達94,731 輛，機車 770,290 輛，合計超過 17 萬輛。依相關規定，完全以電能為動力之電動小客車、機車、大客車及貨車皆以馬力為收稅標準。然電動車與燃油車的馬力輸出原理不同，使用馬力作為收稅標準可能使電動車有實際對道路損耗較少卻因其高馬力而支付較高稅金的不平等情形產生。爰此要求財政部針對電動車收稅標準，參考各界意見後研議調整方向，以 保 障 電 能 車 之 公 平 牌 照 稅 收 稅 方 式 ， 特 向 行 政 院 提 出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-17-65','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-2-9-36:paf0d0727f1','paf0d0727f1','ly_interpellation','2024-11-13','{"co_legislators": [], "meet_id": "院會-11-2-9", "no": "11-2-9-36", "page_end": 4, "page_start": 3, "session": 2, "title": "本院吳委員宗憲，有鑑於大客車缺工問題嚴重，根據 2024 年公路局更新統計，運輸業人力缺額達 9,693 位。經報導，公會理事長及從業人員皆曾表示，大客車駕駛工時長、風險高等不友善工作環境是使司機不願意從業的原因。駕駛工時長和其複雜的薪資組成有高度相關，經看客運駕駛薪資由高達 14則細項加總而成，其中加班費有可能占了三成以上，且每個月薪資浮動劇烈。中央祭出多項補助仍無法改善缺工問題，足以顯示不僅是薪水高低，其背後更有薪資上的結構性問題。爰此要求勞動部及交通部儘快針對大客車駕駛薪資破碎化進行改善，以保障大客車駕駛之健全就業環境，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-9-36','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-3-2-1:paf0d0727f1','paf0d0727f1','ly_interpellation','2025-02-20','{"co_legislators": [], "meet_id": "院會-11-3-2", "no": "11-3-2-1", "page_end": 5, "page_start": 1, "session": 3, "title": "本院吳委員宗憲，有鑑於使用牌照稅法第五條第二項規定，完全以電能為動力之機動車輛使用牌照稅將於 114 年 12 月 31 日停止免徵。根據公路局最新統計，領有統一牌照電動汽車高達94,731 輛，機車 770,290 輛，合計超過 17 萬輛。依相關規定，完全以電能為動力之電動小客車、機車、大客車及貨車皆以馬力為收稅標準。然電動車與燃油車的馬力輸出原理不同，使用馬力作為收稅標準可能使電動車有實際對道路損耗較少卻因其高馬力而支付較高稅金的不平等情形產生。爰此要求財政部針對電動車收稅標準，參考各界意見後研議調整方向，以 保 障 電 能 車 之 公 平 牌 照 稅 收 稅 方 式 ， 特 向 行 政 院 提 出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-3-2-1','2026-10-03T13:34:40Z');
