INSERT INTO "fact" VALUES('ly_bill:222113237490000:paf0d0727f1','paf0d0727f1','ly_bill','2026-05-29','{"bill_no": "222113237490000", "category": "臨時提案", "status": "排入院會", "title": "鑑於行政院規劃於2025年至2030年投入新臺幣442億元推動無人機產業發展，相關供應鏈涵蓋整機系統、飛控通訊、光學感測、半導體晶片、精密加工及AI應用等領域。然中央目前整體布局僅以單一區域為核心，未充分整合中部既有產業聚落與製造基礎。臺中無人機產業全國最多，並具備航太、精密機械、工具機及智慧製造等完整產業能量，且串聯中部科學園區與工業區供應鏈體系，具備成為國家級無人機產業核心基地之條件。爰建請行政院責成相關部會，於三個月內提出「全國無人機產業供應鏈布局與臺中市核心基地發展評估報告」，以強化國家供應鏈韌性及區域均衡發展。是否有當？請公決案。"}','https://ly.govapi.tw/v2/bill/222113237490000','2026-10-03T13:34:40Z');
