INSERT INTO "fact" VALUES('ly_bill:212110025150000:pc169edfc98','pc169edfc98','ly_bill','2024-03-29','{"bill_no": "212110025150000", "category": "一般提案", "status": "排入院會(討論事項)", "title": "為避免物價因電價調漲，民生痛苦指數飆升，因此反對台電公司調漲電價，建請院會作成決議：「立即停止調漲電價，並要求行政院責成相關部會即刻檢討現行能源政策並提出因應對策與配套措施，以兼顧人民生計、維持供電穩定及台電公司之正常營運。」是否有當？請公決案。"}','https://ly.govapi.tw/v2/bill/212110025150000','2026-10-03T13:34:40Z');
