INSERT INTO "fact" VALUES('ly_interpellation:11-1-20-67:pfcf8b4e24e','pfcf8b4e24e','ly_interpellation','2024-06-26','{"co_legislators": [], "meet_id": "院會-11-1-20", "no": "11-1-20-67", "page_end": 10, "page_start": 9, "session": 1, "title": "本院柯委員志恩，有鑑於行政院投入大筆資源推動國家語言發展政策，以及高級中等教育已將本土語言列入必修課程，惟教育現場出現學生缺乏學習興致，反映課程教材艱澀難懂之現象。為有助提升母語學習之成效，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-20-67','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-1-11-45:pfcf8b4e24e','pfcf8b4e24e','ly_interpellation','2024-04-24','{"co_legislators": [], "meet_id": "院會-11-1-11", "no": "11-1-11-45", "page_end": 17, "page_start": 15, "session": 1, "title": "本院柯委員志恩，有鑑近日國立臺北大學臺北校區學生會正 副 會長 暨 學生 議 會選 舉 中， 該 校副 校 長指 示 經濟 系 主 任請 學 生吃 飯 、協 助 繳交 學 生會 費 ，遊 說 學生 登 記參 選 學 生議 員乙事，恐有違反《大學法》並干涉「學生自治」之疑慮，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-1-11-45','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-2-16-64:pfcf8b4e24e','pfcf8b4e24e','ly_interpellation','2024-12-31','{"co_legislators": [], "meet_id": "院會-11-2-16", "no": "11-2-16-64", "page_end": 8, "page_start": 7, "session": 2, "title": "本院柯委員志恩，鑑於現行《全民健康保險扣取及繳納補充保險費辦法》，免扣取補充保費之規定。另《所得稅法》第十一條及《各類所得扣繳率標準》第二條有關「執行業務所得」之類別認定及「報酬按給付額扣取百分之十之規定」，多有不當。惟考量各行業從業者受薪給付模式不一，論件計酬、約定期程給付者所在多有，又出版業長期低薪、產業蕭條，致從業人員經濟負擔沉重。故建請行政院針對相關法規進行研議，考量各產業工會與支薪狀況之差異，檢討現行上開法規對各行業之規範是否妥適，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-2-16-64','2026-10-03T13:34:40Z');
INSERT INTO "fact" VALUES('ly_interpellation:11-3-7-22:pfcf8b4e24e','pfcf8b4e24e','ly_interpellation','2025-04-09','{"co_legislators": [], "meet_id": "院會-11-3-7", "no": "11-3-7-22", "page_end": 3, "page_start": 1, "session": 3, "title": "本院柯委員志恩，鑑於現行勞動基準法及醫療機構設置標準，有關工作採輪班制者每週班次之安排及醫療機構急性一般病床之護理人員全日平均配置比例相關之規定，多有不當。惟考量護理人員實務工作繁重，排班日夜接替、一週多種班別，致醫護人員工作環境惡劣、休息時數不足。又醫護人員缺乏、護病比過高，或須跨科支援，致護理人員難以負荷之情事所在多有。行政院應針對相關法規進行研議，考量各級醫療機構之差異與護理人員實務狀況，檢討現行上開法規之規範是否妥適及落實，以維護醫護人員權益與醫療品質，特向行政院提出質詢。"}','https://ly.govapi.tw/v2/interpellation/11-3-7-22','2026-10-03T13:34:40Z');
