INSERT INTO "fact" VALUES('ly_bill:212110071450000:pfcf8b4e24e','pfcf8b4e24e','ly_bill','2024-10-25','{"bill_no": "212110071450000", "category": "一般提案", "status": "排入院會(討論事項)", "title": "針對我國現有老舊校舍屋齡超過50年計有2,000棟以上，屋齡超過30年以上則有8,000棟以上，囿於臺灣位處地震帶，且因氣候變遷導致極端氣候常致使災情發生，學生就學與老師教學環境安全應以最高標準審視、以最快速度處理。然而2022年之後，中央主管機關並無針對老舊校舍拆除重建補強之相關專案計畫，亦未編列相關預算以為因應。相較於政府對於都更危老建物之重視，面對未來國家棟梁，不該忍睹國家幼苗在半世紀老舊校舍內冒生命安全學習，應儘速完成全面拆除重建。爰建請院會作成決議：「中央政府應先統計全國超過50年以上老舊校舍數及所需拆除重建經費，並得以編列特別預算方式於八年內完成之。」是否有當？請公決案。"}','https://ly.govapi.tw/v2/bill/212110071450000','2026-10-03T13:34:40Z');
