INSERT INTO "fact" VALUES('summary:14-01:p3092978976','p3092978976','summary','2023-06-12','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:30:53Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3180, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=3"}, {"page": 3183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=6"}, {"page": 3183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=6"}, {"page": 3181, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=4"}, {"page": 3184, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=7"}], "councilor_points": ["秦慧珠議員指出臺北市103年至112年註記幫派組合從93個增加到108個，成員及準成員達2,274人，且黑道大型宴會頻繁，呈現「道高一尺、魔高一丈」的現象。秦慧珠議員並舉出最新修正之組織犯罪防制條例條文，要求警察局與各分局主動運用新法掃蕩轄區幫派。"], "response": "警察局局長說明臺北市幫派增加為大幫派底下之小組合，市府對黑道演變均有掌握，並表示會依據新修正法條加強蒐證與全力執行。刑事警察大隊大隊長補充說明刑大設有專責隊負責管制，各分局偵查隊亦成立掃黑專責小隊即時檢肅。南港分局分局長、士林分局分局長、信義分局分局長與大安分局分局長分別說明轄區幫派掌握情形，並表示會依新法盡全力辦理與掃蕩。", "response_removed": false, "topic": "幫派組織掃蕩與黑道治安防治"}, {"citations": [{"page": 3789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=10"}, {"page": 3789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=10"}, {"page": 3793, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=14"}, {"page": 3791, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=12"}, {"page": 3792, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=13"}], "councilor_points": ["秦慧珠議員指出八里污水處理廠自106年經行政院核定移交新北市政府以來，臺北市政府於109年至112年辦理151次（經現場市府官員更新為155次）移交會勘，新北市政府皆缺席，致使移交延宕6年。秦慧珠議員形容此一僵局「瞎爆了」，要求市府說明後續處理方式，並建議向監察院或行政院陳情。"], "response": "衛生下水道工程處處長說明市府係依照中央協調結論辦理清點會勘，新北市政府則希望中央先核定32.8億元補助計畫才同意接管，市府仍會持續妥善維護代管運作。八里污水處理廠廠長補充說明截至質詢前一日已辦理第155次會勘。", "response_removed": false, "topic": "八里污水處理廠移交新北市僵局"}, {"citations": [{"page": 2212, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=9"}, {"page": 2216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=13"}, {"page": 2216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=13"}, {"page": 2211, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=8"}, {"page": 2213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=10"}, {"page": 2214, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=11"}], "councilor_points": ["秦慧珠議員詢問3月31日宣布之「上課10分鐘、下課40分鐘」政策在全市139所公立小學等學校的執行情形，指出部分學校於市長召開記者會後才接獲通知公文，事前缺乏溝通規劃。秦慧珠議員要求教育局對該專案進行整體評估報告，檢討執行困難以作為未來續辦之改進依據。"], "response": "教育局局長說明此政策係提供學生自主學習之構想，由各校在4月彈性選擇1天或1節課辦理，未來會蒐集資料並召開會議進行經驗分享與檢討加強。敦化國小校長說明該校於4月26日辦理下課翻轉，並因應全校2,150位學生之安全考量安排校園尋寶等配套活動。興雅國小校長表示該校已連續3年自發辦理相關活動，當天規劃魔術表演、體驗分區及安全巡邏等措施。", "response_removed": false, "topic": "國小「上課10分鐘、下課40分鐘」政策執行檢討"}, {"citations": [{"page": 2717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=16"}, {"page": 2718, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=17"}, {"page": 2719, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=18"}, {"page": 2720, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=19"}, {"page": 2720, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=19"}], "councilor_points": ["秦慧珠議員詢問預計7月1日上路之1,200元基北北桃月票籌備進度，指出預估114年發行量達79萬張時臺北市自付負擔將達14.2億元，關切財政預算支應能力。秦慧珠議員建議交通局重新精算並向中央爭取穩定財源，避免拖垮交通財政，並詢問悠遊卡公司發行紀念卡之規劃。"], "response": "交通局局長說明中央於7月起將補助直轄市50%、臺鐵及國道90%，今年預算可由中央補助填補，粗估目標年4縣市總計畫需102億元，已向中央反映需有穩定財源。悠遊卡公司總經理表示市府已有配合發行臺北市版面紀念卡之準備，預計於6月15日提早開放販售與設定。", "response_removed": false, "topic": "1200元基北北桃月票財源與籌備進度"}, {"citations": [{"page": 4242, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=29"}, {"page": 4243, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=30"}, {"page": 4244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=31"}, {"page": 4244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=31"}], "councilor_points": ["秦慧珠議員引據民調數據，指出臺北市施政滿意度於6都中排名落後，且市民最期待解決的問題以交通類高達63.4%居首，都市更新與公共建設20.6%次之。秦慧珠議員表示施政滿意度需市府團隊共同打拼，要求產發局、勞動局等各局處首長積極改善八項市政指標成績。"], "response": "臺北市市長表示市府團隊會全力以赴，說明上任5個多月來已克服大巨蛋、捷運工程等困難，不滿意度已降低近20%，會儘快端出成績讓市民有感。產業發展局局長說明去年度因疫情影響中小企業營運，今年已推出貸款振興方案並加強對外招商以促進經濟。", "response_removed": false, "topic": "市長施政滿意度與各局處指標檢討"}, {"citations": [{"page": 2216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=13"}, {"page": 2218, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=15"}, {"page": 2218, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=15"}, {"page": 2219, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=16"}, {"page": 2217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=14"}, {"page": 2219, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=16"}], "councilor_points": ["秦慧珠議員詢問大貓熊圓仔已9歲9個月之配對進度，指出其繁衍因兩岸關係及配對順序延宕，且100年贈送大陸之長鬃山羊與梅花鹿亦面臨近親繁殖及老化困境。秦慧珠議員要求動物園組團拜會海基會與陸委會提出具體要求，並利用9月兩岸四地研討會積極溝通爭取動物權益。"], "response": "動物園園長說明圓仔因家族基因定序考量，在國際專家會議未列優先繁衍順序，市府會利用9月在臺灣舉辦之大貓熊國際會議持續反映需求。動物園園長補充說明贈送大陸之長鬃山羊現剩2隻、梅花鹿剩10隻，先前因狂犬病檢疫條件未達共識而未再補送，後續會仔細討論積極處理。", "response_removed": false, "topic": "大貓熊圓仔配對與兩岸保育類動物交流"}], "session": "第14屆第1次定期大會", "sources": [{"dates": ["2023-06-01"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC#page=23", "transcript_pages": [4236, 4237, 4238, 4239, 4240, 4241, 4242, 4243, 4244, 4245, 4246], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC", "videos": [{"date": "2023-06-01", "group": 5}]}, {"dates": ["2023-04-24"], "dept": "財政建設", "doc_type": "部門質詢", "group": 5, "heading": "財政建設部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC#page=10", "transcript_pages": [1583, 1584, 1585, 1586], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B2CF4ECB1AB196C3A02DB96373566549DAB73272CFF37C97151DE57401A3E69A23E7385F0E570E80AD0CD5E579407C6D02D1DE3DCEB210BC", "videos": [{"date": "2023-04-24", "group": 5}]}, {"dates": ["2023-05-04"], "dept": "教育", "doc_type": "部門質詢", "group": 12, "heading": "教育部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC#page=7", "transcript_pages": [2210, 2211, 2212, 2213, 2214, 2215, 2216, 2217, 2218, 2219], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61349E7CDA831BB72A02DB9637356654996CB8CCB45E70C7D93CBE11528A7B581B40CD378FB432DA1542433E25B847F2E02D1DE3DCEB210BC", "videos": [{"date": "2023-05-04", "group": 12}]}, {"dates": ["2023-05-12"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC#page=16", "transcript_pages": [2717, 2718, 2719, 2720, 2721, 2722, 2723], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6266A2B7C517583CEA02DB963735665497E7E1A11F53005B993CBE11528A7B581142B27EDCBF61F43FBA2334313F226F802D1DE3DCEB210BC", "videos": [{"date": "2023-05-12", "group": 14}]}, {"dates": ["2023-05-19"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC#page=1", "transcript_pages": [3178, 3179, 3180, 3181, 3182, 3183, 3184, 3185], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6FED7D7F18EF5EF3AA02DB963735665495919216247AF6D31A0E805E42C9CC5771A183D3C6D363BCCDBB2AFE1BF6B0E3F02D1DE3DCEB210BC", "videos": [{"date": "2023-05-19", "group": 15}]}, {"dates": ["2023-05-25"], "dept": "工務", "doc_type": "部門質詢", "group": 15, "heading": "工務部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC#page=9", "transcript_pages": [3788, 3789, 3791, 3792, 3793, 3794], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69BF2B5444A020DE3A02DB96373566549D59A3E9762E7207EEFE2450640F879D243C4F092E4D1AB36E202BC4BA3021FB902D1DE3DCEB210BC", "videos": [{"date": "2023-05-25", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE69AB8DB40EE024D7DA02DB963735665490F4F617724A5F69A267A268D8C7C65B3D2D7E61CB1497DD1486D58CE9F45AFDD02D1DE3DCEB210BC','2026-10-04T08:30:53Z');
INSERT INTO "fact" VALUES('summary:14-02:pcb793ad399','pcb793ad399','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:16:57Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=37"}, {"page": 243, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=39"}, {"page": 244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=40"}, {"page": 244, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=40"}, {"page": 241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=37"}, {"page": 246, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=42"}], "councilor_points": ["何孟樺議員指出老屋拉皮補助在 3 年快 4 年時間僅 2 案通過，要求簡化管委會成立門檻以加速審查。何孟樺議員詢問美學辦公室結束後公共工程與校園建築是否仍納入美學規範，並指出市場改造應建立美學專家陪伴機制與強化補助。何孟樺議員反映市府耶誕邀請卡加上文字落款讓人覺得「不尊重」原創設計，並指出局處首長參與公訓處美學研習課程人數減少，建議由府級角度輔導各局處推動城市美學精進計畫。"], "response": "臺北市長表示會檢討提高老屋拉皮申請件數，並承諾全面檢討以多元方式加強美學宣傳與獎勵；都市更新處處長說明後續只要申請人過半數即會協助辦理。工務局局長指出招標文件與評選機制均有規定納入設計美學專家；臺北市長表示後續市場改建會請專業人士提早參與溝通，並由研究發展考核委員會列管各局處落實美學設計。公務人員訓練處處長說明已針對簡任官員規劃舉辦美學課程；研究發展考核委員會主任委員與臺北市長表示會督導標案納入美學審查機制與建立 SOP。", "response_removed": false, "topic": "城市美學與公共工程規範檢討"}, {"citations": [{"page": 246, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=42"}, {"page": 247, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=43"}, {"page": 248, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=44"}, {"page": 248, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=44"}, {"page": 250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=46"}, {"page": 250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=46"}, {"page": 246, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=42"}], "councilor_points": ["何孟樺議員指出內科交通改善計畫僅 5 頁「有點草率」，反映派員警指揮路口雖事故率下降，但未派員路口及部分路段旅行速率反而惡化。何孟樺議員詢問跳蛙公車搭乘人數下降原因，關注捷運東環段瑞光站施工交維計畫，並要求交通局掌握更精細的通勤轉換分析數據。何孟樺議員指出內科三成多 YouBike 租借站周轉率不到 1，建議市府加強與內科企業合作推廣大眾運輸與 YouBike，並要求及時更新內科交通專區網站資訊。"], "response": "臺北市長表示對內科交通改善並不滿意，說明會持續提出精進方案；交通局局長指出有派員警路口事故率下降，平日尖峰旅行時間有微幅下降，明年度將辦理聯外道路可行性評估。交通局局長說明跳蛙公車 APP 預計明年 3 月改版優化，並承認當初問卷調查不夠精細；臺北市長表示會研究搭乘人數未恢復疫情前水準的原因。交通局局長承認內科交通專區網站資訊未及時更新並致歉，說明今年已有 16 家企業報名合作，承諾會持續檢討調整與擴大辦理。", "response_removed": false, "topic": "內科交通改善措施檢討"}, {"citations": [{"page": 5520, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=12"}, {"page": 5522, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=14"}, {"page": 5522, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=14"}, {"page": 5523, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=15"}, {"page": 5523, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=15"}, {"page": 5524, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=16"}], "councilor_points": ["何孟樺議員指出交通局針對台塑進駐內科僅提供 2009 年舊的交通評估報告，要求市府即時提供最新資料並加速處理交通衝擊配套。何孟樺議員反映潭美公園站國道客運短程開放、新明路公車站至松山車站公車班次不足及成美橋不宜騎乘 YouBike 等問題，要求檢討增加公車班次與評估南京東路六段行人號誌。何孟樺議員指出緯創資通總部於今年 3 月動工並預計 2026 年營運將增加三千多個工作機會，要求交通局針對施工期間及進駐人流提早做通盤交通規劃。"], "response": "交通局局長對提供舊資料致歉，說明 5 月與 9 月均有召開會議檢討交通配置計畫，將以實際數據推估需求。公共運輸處處長說明經與相關單位開會達成共識，原則同意短程開放潭美國小站與南京舊宗路口站，上午尖峰台塑公車已增加至 24 班，並有 3 線公車增班計畫。交通局局長表示已優先開設東側行人穿越道，針對緯創進駐將引以為戒並比照接駁公車等方式提早做通盤規劃。", "response_removed": false, "topic": "台塑企業總部進駐內科交通衝擊與配套"}, {"citations": [{"page": 1308, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=24"}, {"page": 1309, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=25"}, {"page": 1310, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=26"}], "councilor_points": ["何孟樺議員指出室外公共場所二手菸曝露率達到 40%，反映戶外定點吸菸區地點難找、標示不清楚且環境維護與照明不足，要求增加稽查人力與完善吸菸區設置。何孟樺議員建議將戒菸宣導結合公共藝術，並指出衛生局仰賴中央國健署調查數據，要求市府針對北市國高中職及電子菸使用狀況建立自主統計數據。何孟樺議員關切聯醫醫師於臉書發表「北市市民沒有選擇疫苗的權力」之「不實」貼文，詢問衛生局未依傳染病防治法開罰之原因，並要求衛生局與聯醫進行勸導及警告。"], "response": "衛生局局長表示人力吃緊，同意評估檢討吸菸區設置與維護，以降低市民接觸二手菸機率，並承諾努力結合公共藝術宣導。衛生局局長表示會想辦法將電子菸等使用數據納入自主統計，並於 1 個月內提交檢討報告。衛生局局長說明依傳染病防治法裁罰須有客觀舉證與損害事實，但會持續努力並請聯醫針對相關發言進行警示與溝通。", "response_removed": false, "topic": "戶外二手菸防制與吸菸區設置管理"}, {"citations": [{"page": 239, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=10"}, {"page": 240, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=11"}, {"page": 240, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=11"}, {"page": 241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=12"}, {"page": 241, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=12"}], "councilor_points": ["何孟樺議員指出長照交通接送服務需求大幅增加，但 2022 年網路預約失敗率達 40%至 50%、2023 年截至 6 月甚至達 8 成，要求社會局做通盤效益分析與檢討。何孟樺議員反映專車與特約車過半車輛未達每日平均趟次標準，甚至有車輛一天平均不到 1 趟，要求研擬更公平的機制並提高專車與特約車的每日最低趟次。何孟樺議員指出社會局公告文件之車齡限制標準不一，並發現有 4 輛車齡超過 8 年的舊車仍載客營運，要求嚴格控管車輛品質與事後審查。"], "response": "社會局局長說明因多元預約管道分散，導致網路預約成功率偏低，已要求網路預約成功率須達 30%以上，並承諾研議通盤效益分析。社會局局長表示已改為每月檢測，低於 7 成即扣減補助金，並同意研議提高專車與特約車的每日趟次標準。社會局局長確認車齡限制為 8 年，承諾會立即檢查事後審查機制，並要求業者補齊相關資料以保障安全。", "response_removed": false, "topic": "長照交通車服務能量與品質控管"}, {"citations": [{"page": 3517, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=22"}, {"page": 3517, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=22"}, {"page": 3518, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=23"}, {"page": 3518, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=23"}, {"page": 3519, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=24"}], "councilor_points": ["何孟樺議員指出動物之家改建後預計收容量 1,300 隻與現況 1,100 多隻相近且每年增加百隻，反映編制 14 人卻缺額 6 人，詢問人事與飽和問題之解決配套。何孟樺議員指出「浪愛滿屋」合作店家僅 23 家且無里辦公室參與，要求市府提出具體計畫提升領養率，並關注改建後年參訪 2 萬人次目標之規劃。何孟樺議員反映動保處未統計動物在收容所受傷比例、外傷照護費用及兇猛犬隻訓練後被認養之數據，要求於 2 周內提供報告。"], "response": "產業發展局局長說明已規劃短中長期目標，包括聘用人力、放寬職系、向中央爭取計畫人力，並爭取提升動保處位階與職等。動物保護處處長表示會檢討並積極增加合作店家與里辦公室；產業發展局局長補充未來動物之家將規劃故事館、咖啡廳、寵物美容等生命教育場館，並與教育局合作推廣。動物保護處處長說明目前 1 個月訓練 4 隻犬隻回歸團體生活，承諾會加強後續統計與提供報告。", "response_removed": false, "topic": "動物之家改建與收容領養機制"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-27"], "dept": null, "doc_type": "市政總質詢", "group": 7, "heading": "市政總質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=35", "transcript_pages": [239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 254, 255, 256], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC", "videos": [{"date": "2023-11-27", "group": 7}]}, {"dates": ["2023-10-26"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=10", "transcript_pages": [5518, 5519, 5520, 5521, 5522, 5523, 5524, 5525, 5526, 5527], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC", "videos": [{"date": "2023-10-26", "group": 4}]}, {"dates": ["2023-11-02"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 8, "heading": "警政衛生部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=17", "transcript_pages": [1301, 1302, 1303, 1304, 1305, 1306, 1307, 1308, 1309, 1310], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 8}]}, {"dates": ["2023-10-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=21", "transcript_pages": [3516, 3517, 3518, 3519, 3520, 3521, 3522], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162", "videos": [{"date": "2023-10-13", "group": 9}]}, {"dates": ["2023-10-19"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549B6A7C0F8E7B043587357573AA4D417BDA8CF5E11E480A4F2A852238F00A7C162#page=1", "transcript_pages": [3798, 3799, 3800, 3801, 3802], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549B6A7C0F8E7B043587357573AA4D417BDA8CF5E11E480A4F2A852238F00A7C162", "videos": [{"date": "2023-10-19", "group": 1}]}, {"dates": ["2023-11-13"], "dept": "工務", "doc_type": "部門質詢", "group": 11, "heading": "工務部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549DD04126DFA8BD7F9440586DBFEBC60C51033AC13741DC6A2A852238F00A7C162#page=1", "transcript_pages": [5970, 5971, 5972, 5973, 5974, 5975, 5976], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549DD04126DFA8BD7F9440586DBFEBC60C51033AC13741DC6A2A852238F00A7C162", "videos": [{"date": "2023-11-13", "group": 11}]}, {"dates": ["2023-11-20"], "dept": "民政", "doc_type": "部門質詢", "group": 9, "heading": "民政部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162#page=9", "transcript_pages": [238, 239, 240, 241, 242, 243, 244, 245], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654937D6067F1139227680607348DE64F9496B1406A2038056D1A852238F00A7C162", "videos": [{"date": "2023-11-20", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC','2026-10-03T01:16:57Z');
INSERT INTO "fact" VALUES('summary:14-02:pccc2308c1b','pccc2308c1b','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:18:45Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3964, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=2"}, {"page": 3969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=7"}, {"page": 3965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=3"}, {"page": 3967, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=5"}, {"page": 3969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=7"}], "councilor_points": ["侯漢廷議員質疑文化局電影補助評審為獲補助公司之股東，認定僅在審查個人案件時離席為「形式利益迴避」，無法達成實質迴避。侯漢廷議員指出評審對陳情人「拍桌大罵」已違反價值中立原則，且會議紀錄過於簡略，欠缺審查過程與討論內容。侯漢廷議員要求文化局規範外聘委員簽署廉政公約、限制三等親內投資公司不得任評審、預算100萬元以上補助審議需錄音及1,000萬元以上附逐字紀錄，並終止違規委員聘任。"], "response": "文化局局長說明該委員會由7人組成，評審遇到個人利益相關案件均有退出離席，由其他6位委員決定是否給予補助，業務執行合乎規範。文化局局長表示會再確認評審是否有拍桌大罵等不當情事，並承諾針對議員提出的各項訴求研議後提供書面報告。", "response_removed": false, "topic": "文化局電影補助審查利益迴避機制"}, {"citations": [{"page": 182, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549E55931451B22F699A4BACDFEA44A933248821AA734718A7B1E26C65428278FAA02D1DE3DCEB210BC#page=4"}, {"page": 5783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B57CE1516694B22977C617FF3C4303D7973237535DCA67DA6642FBB05D74C41A02D1DE3DCEB210BC#page=6"}, {"page": 185, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549E55931451B22F699A4BACDFEA44A933248821AA734718A7B1E26C65428278FAA02D1DE3DCEB210BC#page=7"}, {"page": 5783, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B57CE1516694B22977C617FF3C4303D7973237535DCA67DA6642FBB05D74C41A02D1DE3DCEB210BC#page=6"}], "councilor_points": ["侯漢廷議員指出YouBike出現無車可借或無柱可還等問題，市府身為甲方卻未依合約要求廠商負起管理責任，反而「窩囊」地幫廠商想解決方案。侯漢廷議員質疑微笑單車公司管理能力未定，市府卻規劃在113年至117年投入5億元採購車輛至2028年，要求市府針對調度問題開罰或要求廠商提出創新方案。侯漢廷議員建議開放2025年契約到期後的競爭投標，並研議於改善服務後適度調漲票價以回歸市場機制。"], "response": "臺北市長說明市府有持續要求微笑單車公司增加調度人力與優化服務，會請交通局依照合約要求廠商負起責任並達到服務水平。交通局局長說明會善用合約工具，若廠商未達到要求的服務水準就會依約裁罰。", "response_removed": false, "topic": "YouBike營運管理與契約裁罰機制"}, {"citations": [{"page": 5969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=6"}, {"page": 261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=2"}, {"page": 262, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=3"}, {"page": 263, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=4"}, {"page": 264, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=5"}, {"page": 264, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=5"}, {"page": 262, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=3"}], "councilor_points": ["侯漢廷議員指出研考會測試電話禮貌要求4秒內接聽並不合理，且抽查頻率過高造成警察與醫療等忙碌機關負擔，建議取消時間測試或延長秒數限制。侯漢廷議員要求研考會落實跨局處橫向聯繫與督導責任，避免基層同仁因無法處理個案陳情而未主動通報上級或其他局處。侯漢廷議員詢問青年局的服務對象與業務定位，要求調研青年迫切需要的5大需求並提出獨創業務，避免「人浮於事」。"], "response": "研究發展考核委員會主任委員說明電話接聽速度確實可以增加彈性，將會同相關單位研議精進方案。研究發展考核委員會主任委員表示會監督與列管跨局處橫向聯繫案，並承諾彙整青年需求與獨特性業務相關資料後向議會報告。", "response_removed": false, "topic": "研考會服務電話測試與青年局籌備規劃"}, {"citations": [{"page": 3524, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=2"}, {"page": 3525, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=3"}, {"page": 3525, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=3"}, {"page": 3526, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=4"}, {"page": 3527, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=5"}, {"page": 3528, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=6"}, {"page": 3528, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=6"}], "councilor_points": ["侯漢廷議員指出中央過去承諾協助北投士林科技園區引進生醫創新聚落及臺灣科技新創基地等計畫均未落實。侯漢廷議員指出園區目前進駐廠商多數為建設公司，生醫廠商僅有1家，要求市府提供詳細的進駐產業類別統計資料。侯漢廷議員建議產業發展局主動拜會企業、參與海內外展會，並向中央投資臺灣事務所爭取將該園區列為外商投資主要推薦標的。"], "response": "產業發展局局長說明園區多數為私有地，需由營造事業體興建辦公大樓後始有廠商進駐，後續會提供詳細產業類別數據。產業發展局局長表示會加強落實拜會企業與參與展會等建議，並向中央爭取提升北投士林科技園區的能見度。", "response_removed": false, "topic": "北投士林科技園區發展與招商規劃"}, {"citations": [{"page": 5965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=2"}, {"page": 5965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=2"}, {"page": 5967, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=4"}, {"page": 5967, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=4"}, {"page": 5968, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=5"}, {"page": 5969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=6"}, {"page": 5966, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=3"}], "councilor_points": ["侯漢廷議員指出洲美社宅因租售混合導致公領域維修權責不清，且發生消防設備誤觸事件時有登錄延遲問題，建議統一由社宅服務雲受理通報。侯漢廷議員建議市府優化設備換新與修繕採購流程，賦予物管公司適當權限以加速處理，並強化跨局處照顧社宅弱勢戶。"], "response": "都市發展局局長說明認同單一窗口通報原則，並表示未來會成立跨局處防災群組進行即時通報與處理。都市發展局住宅服務科科長說明住戶可透過社宅服務雲反映公私領域事項，遇緊急修繕時會授權物管公司立即協助處理。", "response_removed": false, "topic": "社會住宅管理維護與服務通報機制"}, {"citations": [{"page": 1315, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=2"}, {"page": 1316, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=3"}, {"page": 1317, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=4"}, {"page": 1318, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=5"}, {"page": 1318, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=5"}], "councilor_points": ["侯漢廷議員詢問士林分局於無維安情資下動用近40名警力執行總統參選人維安勤務，質疑超出常規2組8人的規定並要求提供檢討紀錄。侯漢廷議員指出北投分局同仁因長官霸凌行為換氣過度送醫，要求警察局督察室啟動調查程序。侯漢廷議員指出中央「識詐行動綱領1.5版」要求警察拍影片、經營粉專及達成各項指標，形成「沒搞死詐騙集團、先搞死基層」的狀況，建議檢討宣導效率。"], "response": "警察局局長說明警力編派會依現場狀況調整，並表示會進行檢討且於會期結束前提供檢討紀錄。警察局局長說明會了解查處北投分局事件，並對防詐宣導加重同仁工作負擔表示抱歉，未來會精進宣導效率。", "response_removed": false, "topic": "警察局維安勤務派遣與防詐宣導負擔"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-27"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549E55931451B22F699A4BACDFEA44A933248821AA734718A7B1E26C65428278FAA02D1DE3DCEB210BC#page=1", "transcript_pages": [179, 180, 181, 182, 183, 184, 185, 186, 187], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549E55931451B22F699A4BACDFEA44A933248821AA734718A7B1E26C65428278FAA02D1DE3DCEB210BC", "videos": [{"date": "2023-11-27", "group": 5}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B57CE1516694B22977C617FF3C4303D7973237535DCA67DA6642FBB05D74C41A02D1DE3DCEB210BC#page=1", "transcript_pages": [5778, 5779, 5780, 5781, 5782, 5783], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B57CE1516694B22977C617FF3C4303D7973237535DCA67DA6642FBB05D74C41A02D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 16}]}, {"dates": ["2023-11-03"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 9, "heading": "警政衛生部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162#page=1", "transcript_pages": [1314, 1315, 1316, 1317, 1318, 1319], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654961363C22ED9EF21F5E883F57EF3E560B29D9E210C46C422AA852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 9}]}, {"dates": ["2023-10-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 10, "heading": "財政建設部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162#page=1", "transcript_pages": [3523, 3524, 3525, 3526, 3527, 3528, 3529, 3530], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B8DA9F72FEA1994610E4D9472BC771E97D8A5B5636D29AAEA852238F00A7C162", "videos": [{"date": "2023-10-13", "group": 10}]}, {"dates": ["2023-10-20"], "dept": "教育", "doc_type": "部門質詢", "group": 8, "heading": "教育部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162#page=1", "transcript_pages": [3963, 3964, 3965, 3966, 3967, 3968, 3969], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665498EE50203DE40D0078A200C93B9AA19CAB459BF7493A0671FA852238F00A7C162", "videos": [{"date": "2023-10-20", "group": 8}]}, {"dates": ["2023-11-13"], "dept": "工務", "doc_type": "部門質詢", "group": 10, "heading": "工務部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162#page=1", "transcript_pages": [5964, 5965, 5966, 5967, 5968, 5969], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549A8CC770FF59747490976269FD974B50012930246DC1C3F05A852238F00A7C162", "videos": [{"date": "2023-11-13", "group": 10}]}, {"dates": ["2023-11-20"], "dept": "民政", "doc_type": "部門質詢", "group": 10, "heading": "民政部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162#page=1", "transcript_pages": [260, 261, 262, 263, 264, 265], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665490CC384D94CF4492DE375996184BB4612C111784A1DC090DCA852238F00A7C162", "videos": [{"date": "2023-11-20", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549E55931451B22F699A4BACDFEA44A933248821AA734718A7B1E26C65428278FAA02D1DE3DCEB210BC','2026-10-03T01:18:45Z');
INSERT INTO "fact" VALUES('summary:14-02:pa0224cb763','pa0224cb763','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:20:56Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 278, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=15"}, {"page": 278, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=15"}, {"page": 281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=18"}, {"page": 281, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=18"}, {"page": 283, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=20"}, {"page": 280, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=17"}, {"page": 282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=19"}], "councilor_points": ["劉耀仁議員指出萬華區住宅老舊，40年以上老屋比例達56.5%，50年以上老屋占臺北市13.7%，面臨都更誘因不足與法令限制之瓶頸（來源引文：「萬華區的老化程度非常地嚴重……40 年以上屋齡的比例，萬華區又是第 1 名，比例高達 56.5%」）。劉耀仁議員建議取消或放寬博愛特區第一管制區與總統府天際線的限制，將檢視基點改設於公園路或回歸《文化資產保存法》處理（來源引文：「如果一定要有管制或是總統府天際線的設置，可不可以就站在活動範圍之內的公園路來看……將一切都回歸『文化資產保存法』去審定」）。劉耀仁議員要求檢討長約1.8公里的艋舺大道土地使用分區與容積率管制，並建議成立淡水河或新店溪水岸窳陋地區都市更新專區（來源引文：「在下一次通盤檢討的時候，我希望你能夠正視臺北市萬華區艋舺大道的問題……把淡水河岸的萬華區跟大同區，這窳陋地區列為都市更新的專區」）。"], "response": "蔣市長表示認同議員看法，已請都市發展局檢討天際線問題並持續與總統府及文化部溝通，且承諾對艋舺大道兩側限制進行通盤檢討（來源引文：「關於天際線這個問題，我請都市發展局去做相關的檢討……萬華區艋舺大道兩邊的限制，我們也會通盤檢討」）。蔣市長表示都市發展局已進行淡水河水岸周邊之全新規劃，會一併討論相關限制與放寬事宜（來源引文：「我們都發局已經在進行水岸周邊的全新規劃，會一併討論相關的限制，以及怎麼放寬」）。", "response_removed": false, "topic": "中正與萬華區都市更新與建築管制檢討"}, {"citations": [{"page": 284, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=21"}, {"page": 286, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=23"}, {"page": 287, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=24"}, {"page": 154, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549D90044C5961D6DD5C3CBA84EBC5E1DF2F8C88EE3C91BF561A852238F00A7C162#page=4"}, {"page": 284, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=21"}, {"page": 286, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=23"}], "councilor_points": ["劉耀仁議員指出萬華區日祥里青年社宅一、二期完工後將聚集302戶弱勢戶，連同原低收入戶137戶預計超過1,300人，造成弱勢人口高度集中（來源引文：「青年一期、二期總共有 791 戶裡面，會有 302 戶的弱勢族群戶，加上原本青年一、二期以外，日祥里有 137 戶的低收入戶，所以那時候會超過 1,300 人」）。劉耀仁議員要求社會局在該區設置專屬社工工作站，並反對由都發局委託物業管理公司招募社工師或將關懷責任轉嫁給里辦公室與里幹事（來源引文：「可不可以在那邊設置社工站……堅決以後不可以叫物業管理公司去招攬社工師……不要給里辦公室多餘的責任」）。劉耀仁議員建議加強跨局處與里辦公室的社安通報與夥伴合作，防止社區弱勢照顧出現死角（來源引文：「區里的關懷網是非常重要的……接下來一定都會要求通報里長」）。"], "response": "蔣市長與社會局局長表示經協調後確定會在青年社宅設置服務工作站，承諾回歸專業與局處分工，並要求社安事件務必通報里長（來源引文：「我們確定會去設置這個工作站……我們會回歸專業……接下來一定都會要求通報里長」）。", "response_removed": false, "topic": "青年社宅弱勢照顧與社工據點設置"}, {"citations": [{"page": 5597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC#page=3"}, {"page": 5597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC#page=3"}, {"page": 5599, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC#page=5"}, {"page": 5600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC#page=6"}], "councilor_points": ["劉耀仁議員指出中正新橋通車後因標誌標線不清楚且採「車種分流」而非「車向分流」，導致汽機車在橋上頻繁交織，行車「險象環生」（來源引文：「標示不清楚，民眾不知道要行駛機車專用道……因為車種分流導致交織混亂」）。劉耀仁議員要求交通局與新建工程處改善指示牌字體過小及反光問題，且配套措施未完善前切勿貿然通車（來源引文：「指示牌字體寫得很小又不清楚……所有的配套措施要做好」）。劉耀仁議員建議加強行人穿越道照明亮度，並可參考外縣市或國外經驗設置感應警示燈以保障行人安全（來源引文：「要改善行穿線的亮度……只要經過行穿線的時候，只要按下按鈕，警示燈就會亮」）。"], "response": null, "response_removed": true, "topic": "中正橋改建交通動線與安全設施改善"}, {"citations": [{"page": 3469, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=1"}, {"page": 3469, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=1"}, {"page": 3470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=2"}, {"page": 3471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=3"}, {"page": 3471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=3"}], "councilor_points": ["劉耀仁議員指出臺北市770處免費飲水站多設於公家機關、學校及醫院，受限於開放時間，建議結合友善店家擴大提供免費飲用水（來源引文：「臺北市的 770 處都是列址在公家機關、學校、醫院裡面……下課時間，能進入學校裝水嗎……就是要結合友善店家」）。劉耀仁議員指出商業處友善店家地圖介面不便且缺少日韓文支援，並反映各行政區友善店家數量落差大，如大安區113家而南港區僅14家、文山區僅20家（來源引文：「友善店家網頁地圖太難用……最高的大安區 113 家，最少的南港區 14 家」）。劉耀仁議員要求商業處改善網頁介面，並訂定目標於明年6月底前將友善店家不足50家的行政區提升至50家以上（來源引文：「讓未足 50 家友善店家的行政區，在明年 6 月底提升到 50 家以上」）。"], "response": "商業處處長說明會調整友善店家地圖之呈現方式，並承諾朝向明年6月底前將各區友善店家提升至50家以上的目標努力招募（來源引文：「我們再來研究一下……我們往這個目標去努力」）。臺北自來水事業處處長表示願意與商業處合作，將友善店家納入台北好水直飲地圖（來源引文：「可以，這個我們來合作」）。", "response_removed": false, "topic": "綠洲臺北計畫與友善店家推廣"}, {"citations": [{"page": 3844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665499463527EE13F66739A027D49442C9FD7175631AF2E2218BBA852238F00A7C162#page=1"}, {"page": 3848, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665499463527EE13F66739A027D49442C9FD7175631AF2E2218BBA852238F00A7C162#page=5"}], "councilor_points": ["劉耀仁議員指出112學年度臺北市達到純雙語教育有108校（含前導學校共167校），詢問教育局推動雙語教育面臨之瓶頸與師資需求（來源引文：「排除前導學校，達到純粹雙語教育是 108 校……最大瓶頸是什麼」）。劉耀仁議員表示反對廢除雙語政策之言論，主張應與國際接軌，並贊成教育局每年增加10%額度穩健推進雙語教育（來源引文：「臺灣走向雙語教育的環境是所有各個領域、各階層團體都是接受的……非常贊成每年有百分之十的額度穩健往前推進」）。劉耀仁議員要求教育局於半年內提出完整的雙語教育政策白皮書，明確列出現況、未來展望與實施期程（來源引文：「半年之內提出一套真正屬於蔣萬安市長的雙語教育政策白皮書」）。"], "response": null, "response_removed": true, "topic": "臺北市雙語教育政策推進與白皮書規劃"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-28"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC#page=15", "transcript_pages": [278, 280, 281, 282, 283, 284, 285, 286, 287, 288], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC", "videos": [{"date": "2023-11-28", "group": 8}]}, {"dates": ["2023-10-27"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC#page=1", "transcript_pages": [5595, 5596, 5597, 5598, 5599, 5600], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E79BA78A6136D2A1924B196A458927BB5827961DD2A0929CA97ACA82A4F10C8902D1DE3DCEB210BC", "videos": [{"date": "2023-10-27", "group": 8}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665490A4BD8600705B2506413418E81676E379BBE1A0EA1D8E1C7A852238F00A7C162#page=8", "transcript_pages": [1328, 1329, 1330, 1331, 1332], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665490A4BD8600705B2506413418E81676E379BBE1A0EA1D8E1C7A852238F00A7C162", "videos": []}, {"dates": ["2023-10-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 7, "heading": "財政建設部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162#page=1", "transcript_pages": [3469, 3470, 3471, 3472], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549190FDFC5AB2723FE7C7596D66B186DE5E62BCC51272C8B02A852238F00A7C162", "videos": [{"date": "2023-10-13", "group": 7}]}, {"dates": ["2023-10-19"], "dept": "教育", "doc_type": "部門質詢", "group": 3, "heading": "教育部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665499463527EE13F66739A027D49442C9FD7175631AF2E2218BBA852238F00A7C162#page=1", "transcript_pages": [3844, 3845, 3846, 3847, 3848, 3849, 3850, 3851], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665499463527EE13F66739A027D49442C9FD7175631AF2E2218BBA852238F00A7C162", "videos": [{"date": "2023-10-19", "group": 3}]}, {"dates": ["2023-11-14"], "dept": "工務", "doc_type": "部門質詢", "group": 17, "heading": "工務部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665493C72BEB69F28B27A0BDCAE506AFAA0F91192F2C7570487A1A852238F00A7C162#page=1", "transcript_pages": [6080, 6081, 6082, 6083, 6084, 6085, 6086, 6087], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665493C72BEB69F28B27A0BDCAE506AFAA0F91192F2C7570487A1A852238F00A7C162", "videos": [{"date": "2023-11-14", "group": 17}]}, {"dates": ["2023-11-17"], "dept": "民政", "doc_type": "部門質詢", "group": 5, "heading": "民政部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549D90044C5961D6DD5C3CBA84EBC5E1DF2F8C88EE3C91BF561A852238F00A7C162#page=1", "transcript_pages": [151, 152, 153, 154, 155, 156], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549D90044C5961D6DD5C3CBA84EBC5E1DF2F8C88EE3C91BF561A852238F00A7C162", "videos": [{"date": "2023-11-17", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665498C844F5FE2AF993182EDA0BF73084921FB85B3DCDA47488FF290D3C4575DA2D202D1DE3DCEB210BC','2026-10-03T01:20:56Z');
INSERT INTO "fact" VALUES('summary:14-02:p4b727b88dc','p4b727b88dc','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-03T01:22:54Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3427, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=18"}, {"page": 3427, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=18"}, {"page": 3429, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=20"}, {"page": 3429, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=20"}, {"page": 3430, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=21"}, {"page": 3431, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=22"}, {"page": 3433, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=24"}, {"page": 3433, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162#page=24"}], "councilor_points": ["吳世正議員指出柯市府成立「臺北市政府市有資產活化及運用小組」將學校校舍視為一般資產進行評估，忽略教育機構人事費用占預算近8成、業務費用僅占2成之特殊性，統一要求各校檢討少子化緊縮空間、縮減改建量體及騰出預算，導致修德國小、誠正國中、碧湖國小及福德國小等校舍與活動中心工程遭受延誤。吳世正議員表示審議小組成員缺乏教育專業，強行要求單間教室117平方公尺縮小、合併學務處與教務處或廣播室等空間，屬「官僚」作風，並以修德國小活動中心因多出18平方公尺即被要求改小重審為例，說明此舉損害學生權益。吳世正議員要求財政局評估將學校校舍排除於市有資產評估之外，堅持教育歸教育，並給予教育單位足夠之預算額度。"], "response": "財政局局長說明市府已撥補教育基金，且秘書長召集之供需整合平臺召開7次會議中已有13案與學校校舍相關，市府相當重視學校校舍。財政局局長表示可能因用詞表達產生誤會，未來開會會特別留意對公有建物之再確認。", "response_removed": false, "topic": "學校校舍改建審查與市有資產小組運作檢討"}, {"citations": [{"page": 3886, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=29"}, {"page": 5803, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=22"}, {"page": 5804, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=23"}, {"page": 5804, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=23"}, {"page": 5804, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=23"}, {"page": 5806, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=25"}], "councilor_points": ["吳世正議員指出海砂屋攸關人命安全，目前臺北市列管重建之海砂屋有97處，進入都更程序者僅65處，但市府推出之「7599專案計畫」設定需位於更新地區、基地面積達2,000平方公尺以上、社區意願達75%及未與潛在實施者簽約等4項門檻，反而阻礙都更並「幫忙建商插旗」。吳世正議員以東湖基地面積1,840平方公尺、意願達100%之海砂屋社區為例，說明現行硬性規定缺乏彈性，並對比新北市海砂屋都更「無面積限制」且「意願達50%即可申請」之做法，要求市府檢討放寬規定。吳世正議員要求都市發展局檢討「7599專案計畫」之4項條件、給予基地面積10%之彈性調整空間、修正關於潛在實施者之規定，並列管未進入程序之32件海砂屋。"], "response": null, "response_removed": true, "topic": "海砂屋公辦都更門檻與放寬條件"}, {"citations": [{"page": 32, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=24"}, {"page": 34, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=26"}, {"page": 35, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=27"}, {"page": 36, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=28"}, {"page": 37, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=29"}, {"page": 34, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=26"}], "councilor_points": ["吳世正議員指出敬老卡文康休閒據點分布不均，例如65歲以上人口達65,344人之大安區僅有3個據點，且多區之游泳池及運動場館敬老卡使用人次呈現數據掛0，要求社會局調查大安區潛在場館並釐清使用率掛0之原因。吳世正議員要求社會局與教育局、體育局開會協商，建立公益時段使用人數之統計機制，並在官網及場館臉書加強扣點價格與使用方式之說明。吳世正議員建議社會局克服技術與退費問題，將臺北市立交響樂團及國樂團門票與國道客運納入敬老卡扣點範圍，並於1個月內提出相關計畫與調查結果。"], "response": "社會局局長說明部分場館數據掛0係因長者多於公益時段免費入場未刷卡、購買便宜套票或場館尚未向社會局請款所致，承諾未來會與教育局及體育局合作統計公益時段人數。社會局局長表示會在兩週內調查大安區有潛力加入敬老卡據點之場館名單，並加強場館扣點宣導計畫。社會局局長表示將與兩市立樂團溝通現場購票刷卡扣點事宜，並已邀集國道客運業者座談，先以北北基桃及宜蘭路線研議試辦可行性。", "response_removed": false, "topic": "敬老卡使用據點與場館扣點效益檢討"}, {"citations": [{"page": 5715, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=1"}, {"page": 5715, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=1"}, {"page": 5715, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=1"}, {"page": 5717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=3"}, {"page": 5717, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=3"}, {"page": 5719, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=5"}, {"page": 5718, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=4"}], "councilor_points": ["吳世正議員指出臺灣交通事故死亡率偏高，而臺北市部分易肇事路口（如西寧北路與鄭州路口改善僅花費9萬元、重慶南路與貴陽街口僅花費2萬3,000元、信義路與松仁路口僅花費1萬8,000元）改善預算過低且事故件數仍增加，質疑改善效果「慘不忍睹」。吳世正議員指出臺北市至當年7月底死亡事故達73件（增加40%）、高齡死亡率增加55%、行人死亡事故達28件（增加75%），要求交通局與交通管制工程處增加號誌與標線預算。吳世正議員建議市府參考國外做法，改進「斑馬線掛帥」問題，於無號誌路口採用折線或凸起路面，並增加中央分隔島避難空間、低位號誌及感應號誌等設施。"], "response": "交通局局長承認先前路口改善方法有精進空間，強調「該花的錢絕對不能省」，未來將製作碰撞構圖分析歷年碰撞型態以根本改變路型。交通管制工程處處長說明113年號誌與標線型預算已增加9千多萬元，交通局局長亦表示會向中央爭取補助並持續加編預算。交通局局長對傷亡數字表示遺憾，承諾會隨時監控並將議員提出之標誌標線與工程改善建議帶回研究，於總質詢前提出檢討報告。", "response_removed": false, "topic": "行人路權改善與易肇事路口交通安全"}, {"citations": [{"page": 1198, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=1"}, {"page": 1199, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=2"}, {"page": 1201, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=4"}, {"page": 1200, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=3"}], "councilor_points": ["吳世正議員指出市立聯合醫院護理人員缺額由111年底之119名增加至216名，缺額率接近10%，並導致各院區合計關床達325床（或院方統計之263床），加重留任人員負擔並形成惡性循環。吳世正議員要求衛生局與市立聯合醫院加強對外宣傳優於私立醫院之薪資待遇，建立基層同仁意見蒐集機制以了解實際需求，並辦理未婚聯誼或戶外活動以凝聚向心力。吳世正議員建議引進AI技術協助整理護理資料，並採用運送型機器人代送文件、器材與藥品，以減輕護理人員負擔，要求衛生局與聯醫於1個月內提出規劃計畫。"], "response": "市立聯合醫院總院長說明實際關床數精確統計為263床，關床主因係護理人力短缺，強調聯醫薪資待遇已調升且優於私立醫院，但宣傳及媒體曝光不足。衛生局局長補充護理人力流失受疫情衝擊、職涯選擇多元及剛畢業護理師投入職場意願低等影響，同意重視基層民意反映。衛生局局長與市立聯合醫院總院長承諾於1個月內提出結合基層意見、獎勵鼓勵與行銷宣傳之計畫，並積極研究引進智慧醫療與機器人以減輕護理同仁庶務負擔。", "response_removed": false, "topic": "市立聯合醫院護理人力短缺與因應措施"}, {"citations": [{"page": 3881, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=24"}, {"page": 3882, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=25"}, {"page": 3883, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=26"}, {"page": 3882, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=25"}, {"page": 3884, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=27"}], "councilor_points": ["吳世正議員指出教育部發布「高級中等學校學生入住宿舍性別友善處理原則」要求學校負責處理跨性別學生申請，但以性別認同取代生理性別恐衍生驗證、安全及家長疑慮等複雜問題，批評教育部推卸責任給個別學校。吳世正議員表示北市轄內有14所學校設有宿舍，包含2所女校，若有男學生以性別認同為由申請入住女校宿舍，學校難以單獨承擔風險。吳世正議員要求教育局未雨綢繆，於1個月內召集設有宿舍之14所學校、專家學者、家長代表及學生開會研討，制定統一之指導原則與應對機制。"], "response": "教育局局長說明目前北市14所設有宿舍之學校尚無學生提出相關申請，並指出過往性別辨識以生理為基礎，心理認同確實需要適應與因應。教育局局長表示認同議員關切之議題需未雨綢繆，宿舍可透過單間設計或動線區隔來減少干擾，並經由學校性別平等教育委員會進行討論程序。教育局局長承諾會儘快召集設有宿舍之學校、專家學者、家長代表及學生開會研討，制定共通處理方式與指導原則。", "response_removed": false, "topic": "高中學生宿舍性別友善處理原則與因應"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-30"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=4", "transcript_pages": [448, 450, 451, 452, 453, 454, 455, 456, 457, 458], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162", "videos": [{"date": "2023-11-30", "group": 11}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "heading": "交通部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=1", "transcript_pages": [5715, 5717, 5718, 5719, 5720], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 13}]}, {"dates": ["2023-11-02"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=1", "transcript_pages": [1198, 1199, 1200, 1201, 12