, "heading": "民政部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665496FEFDFECF94185E4A3DB483AE5426AE1B9D49124F0BCCDF5A852238F00A7C162#page=7", "transcript_pages": [334, 335, 336, 337, 338, 339, 340, 341], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665496FEFDFECF94185E4A3DB483AE5426AE1B9D49124F0BCCDF5A852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 14}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665491B30518CFD9CFC28C3CBA84EBC5E1DF27BA2B21E128A5B4CA852238F00A7C162','2026-10-03T01:38:37Z');
INSERT INTO "fact" VALUES('summary:14-02:p47f1fe2e84','p47f1fe2e84','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:33:25Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3369, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=2"}, {"page": 3370, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=3"}, {"page": 3372, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=5"}, {"page": 3375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=8"}, {"page": 3371, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=4"}, {"page": 3373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=6"}, {"page": 3375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=8"}], "councilor_points": ["指出有四口之家民眾因採自動扣款，六年多來內管漏水一萬多度（相當於四個奧運游泳池水量）、被多扣七萬多元水費才獲通知，質疑現行僅靠貼單與帳單備註之預警機制不足且各營業分處做法不一。建議臺北自來水事業處不應以「擾民」為理由，應建立電話、簡訊或電子郵件等主動預警通知機制並檢討修正相關規定。"], "response": "臺北自來水事業處處長說明表後漏水依法由用戶負責，修繕完畢可退還最近一期一半水費，目前以程式控管對突增超過 30% 且超過 30 度者採貼單與憑證備註提醒，未來會檢討擬訂更平衡的通知做法。產業發展局局長表示對於中長期的漏水情形，確實應另外設計防止機制。", "response_removed": false, "topic": "自來水用戶內管漏水預警與通知機制"}, {"citations": [{"page": 611, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=28"}, {"page": 612, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=29"}, {"page": 613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=30"}, {"page": 614, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=31"}, {"page": 615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=32"}, {"page": 615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=32"}], "councilor_points": ["指出三十年以上且十一樓以上老舊大樓未申報率達 74%，且檢測與修繕費用落差極大，例如私有檢測每平方公尺價差達 30 倍，公有修繕最高達 9,000 萬元，連 2025 年即將拆除的西寧出租國宅亦花費 5,000 多萬元。質疑檢查項目認定標準彈性過大，要求統一收費與檢測標準、成立府級小組，並提高現行每棟 10 萬元的補助金額以增加誘因。"], "response": "建築管理工程處處長說明申報率低主因缺乏管委會及費用龐大，費用落差係因工法差異與個案難易度不同，承諾會將判斷標準與修繕方法具體化，並檢討提高補助金額。都市發展局局長說明公部門多採全面拉皮故費用較高。市長表示會請建管處公告檢測與修繕費用並研究訂出更細緻明確的分級標準。", "response_removed": false, "topic": "老舊大樓外牆安全診斷檢測與修繕機制"}, {"citations": [{"page": 1438, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=22"}, {"page": 1439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=23"}, {"page": 1437, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=21"}, {"page": 1438, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=22"}], "councilor_points": ["指出臺北市立聯合醫院護理人員缺額 250 人（約一成），病房助理缺額 153 人（近三成五，部分院區達四成），恐造成惡性循環並影響醫療品質。建議衛生局與教育局研議跨局處方案，給予護理人員子女優先就讀在地額滿學校的優惠，以提高留才誘因。"], "response": "臺北市立聯合醫院總院長說明調薪後護理師離職率已降至 1% 以下，病房助理未來規劃朝向照服員方向調整，並提供教育獎助金及進修管道。衛生局局長承諾在一個月內完成內部問卷調查，並與教育局研議護理人員子女教育權益方案。教育局體育及衛生保健科科長說明現行優先入學辦法係針對教育局編制內教職員工，將與衛生局針對聯醫部分進行討論。", "response_removed": false, "topic": "市立聯合醫院護理與病房助理人力缺額與留才"}, {"citations": [{"page": 3375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=8"}, {"page": 4011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=20"}, {"page": 4008, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=17"}, {"page": 4011, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=20"}, {"page": 4010, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=19"}, {"page": 4012, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=21"}], "councilor_points": ["指出準公共幼兒園依法不得另開才藝班收費，但今年裁罰 4 件、去年 8 件，且有才藝班每月收取 6,000 元費用，增加家長負擔。質疑現行 166 家準公幼中違規開班僅為冰山一角，要求教育局補強契約漏洞、加強稽查，並儘速與業者座談溝通解決轉型困境。"], "response": "教育局局長說明依規定幼兒園不得開設才藝班另外收費，違規者會依法裁罰，承諾會再與準公幼業者進行溝通說明。教育局學前教育科科長補充每年定期稽查至少 210 家，幼兒園不得收取超過備查項目以外的費用。", "response_removed": false, "topic": "準公共幼兒園違規開設才藝班與收費管理"}, {"citations": [{"page": 5685, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=20"}, {"page": 5686, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=21"}, {"page": 5687, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=22"}], "councilor_points": ["指出機車待轉格前劃設槽化線（如文湖路與江南街口等，今年已開罰 9 張）屬「白癡設計」與工程設施不當，使機車騎士陷入壓線被開單或與直行車碰撞之危險。要求交通管制工程處一個月內盤點塗銷舊有槽化線，並要求交通警察大隊對此類因道路設計不當產生的違規罰單予以撤銷。"], "response": "交通管制工程處處長說明劃設槽化線係為保護待轉機車，新式已不再劃設，承諾在一個月內完成清查並檢討改善設計。警察局交通警察大隊大隊長表示此類工程設置確實有調整空間，若屬工程不當導致無法避免之違規會考慮撤單。交通局局長表示會研究改用時相開放左轉等方式取代槽化線。", "response_removed": false, "topic": "機車待轉區前劃設槽化線不當與罰單撤銷"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-04"], "dept": null, "doc_type": "市政總質詢", "group": 15, "heading": "市政總質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=26", "transcript_pages": [609, 610, 611, 612, 613, 614, 615, 616, 617, 618, 619, 620], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162", "videos": [{"date": "2023-12-04", "group": 15}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=15", "transcript_pages": [5680, 5681, 5682, 5683, 5684, 5685, 5686, 5687, 5688], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 11}]}, {"dates": ["2023-11-07"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=18", "transcript_pages": [1434, 1435, 1436, 1437, 1438, 1439, 1440], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162", "videos": [{"date": "2023-11-07", "group": 14}]}, {"dates": ["2023-10-12"], "dept": "財政建設", "doc_type": "部門質詢", "group": 2, "heading": "財政建設部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=1", "transcript_pages": [3368, 3369, 3370, 3371, 3372, 3373, 3374, 3375], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162", "videos": [{"date": "2023-10-12", "group": 2}]}, {"dates": ["2023-10-23"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=16", "transcript_pages": [4007, 4008, 4009, 4010, 4011, 4012, 4013, 4014, 4015], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162", "videos": [{"date": "2023-10-23", "group": 10}]}, {"dates": ["2023-11-09"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=9", "transcript_pages": [5824, 5825, 5826, 5827, 5828, 5829], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162", "videos": [{"date": "2023-11-09", "group": 3}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=7", "transcript_pages": [353, 354, 355, 356, 357, 358, 359], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162','2026-10-04T08:33:25Z');
INSERT INTO "fact" VALUES('summary:14-02:pc524c2d6ef','pc524c2d6ef','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:35:16Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 5833, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=18"}, {"page": 5834, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=19"}, {"page": 5834, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=19"}, {"page": 5836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=21"}, {"page": 5837, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=22"}, {"page": 5835, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=20"}], "councilor_points": ["李柏毅議員指出臺北市 111 年普查 4 萬多株行道樹，詢問廠商宣稱 5 分鐘完成單株檢查是否符合專家認定的 30 分鐘標準。李柏毅議員表示市府將行道樹健檢拆為 A 項（預算 1,170 萬元檢測 2 萬 3,000 株）與 B 項（預算 1,120 萬元檢測 2 萬 5,000 株），卻由同一家公司得標且單株費用不同，要求 1 星期內提供說明。李柏毅議員建議樹木修剪證照考試改委託專業單位辦理，並建議將修剪枝條做資源回收再利用。"], "response": "工務局公園路燈工程管理處處長說明，健檢作業會請專家學者就成果報告進行審查，拆標係因第一次招標尚不清楚市場廠商量能，兩標案金額與株數差異源於後續施作項目不同，承諾 1 星期內提供報告。工務局公園路燈工程管理處處長表示，會檢討將樹木修剪證照課程委託專業單位辦理，並會與產業發展局溝通研議枝條回收再利用。", "response_removed": false, "topic": "行道樹安全健檢標案與管理機制"}, {"citations": [{"page": 5688, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=23"}, {"page": 5689, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=24"}, {"page": 5690, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=25"}, {"page": 5691, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=26"}, {"page": 5692, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=27"}], "councilor_points": ["李柏毅議員播放影片詢問警方對機車駕駛在特勤車隊行經路線上比中指進行攔查的法律依據與處置態度。李柏毅議員詢問警方是否贊成現場盤查有不雅舉動的民眾，並要求警方未來執行特勤維安勤務時應一致嚴格執法。"], "response": "警察局交通警察大隊大隊長說明，道路警衛線視同安全維護區，員警因判斷比中指動作可能有危害疑慮才上前盤查，攔查目的並無問題。警察局交通警察大隊大隊長與警察局松山分局分局長表示，贊成攔查以了解動機與危害狀況，並承諾會檢討員警執勤技巧與態度。", "response_removed": false, "topic": "車隊特勤維安警衛盤查標準"}, {"citations": [{"page": 588, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=5"}, {"page": 588, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=5"}, {"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=6"}, {"page": 589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=6"}], "councilor_points": ["李柏毅議員指出市府認定的 YouBike 每 1 公里減碳 0.097 公斤為最高，但在「減碳存摺」活動中 YouBike 單次僅計 0.17 公斤，導致抽獎次數遠低於公車與捷運。李柏毅議員指出 11 月 1 日至 12 月 20 日數據中前 4 名抽獎高達 70 至 80 次，遠高於前 20 名平均約 30 次，甚至出現每月搭捷運 84 趟與公車 209 段票之異常極端值。李柏毅議員要求市府重新檢討減碳值計算公式，並針對月票抽獎次數設定合理上限。"], "response": "交通局局長與悠遊卡股份有限公司董事長說明，YouBike 因無法量測里程而以時間基礎換算，抽獎次數偏高亦可能與多卡總歸戶給親友使用有關。臺北市市長與交通局局長表示，認同應檢討遊戲規則與換算方式，將研議設定抽獎上限以維持公平。", "response_removed": false, "topic": "「我的減碳存摺」活動減碳計算與抽獎規則"}, {"citations": [{"page": 5694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC#page=29"}, {"page": 1417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=1"}, {"page": 1418, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=2"}, {"page": 1419, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=3"}], "councilor_points": ["李柏毅議員指出臺北市 111 年詐騙發生 4,044 件、破獲 4,482 件使得破案率達 110.8%，但攔阻率卻在六都墊底，質疑數據包含他轄破案數而與市民感受不符。李柏毅議員舉出愛情詐欺陳情案指出，家屬持假身分證報案遭警方拒絕，警方反而受理當事人控告家屬侵占房契，指出第一線員警無視偽造身分證之公訴罪與處理流程。李柏毅議員要求警察局單獨揭露臺北市轄內真實破案數字，並再教育第一線員警及落實事前攔截。"], "response": "警察局局長說明，破案率計算包含查獲他轄案件，並表示該起陳情案警方未查證清楚且處置有錯，只要有犯罪嫌疑就應受理調查。警察局局長表示，將調查該個案、加強外勤同仁教育，並同意調整統計呈報方式以反映真實狀況。", "response_removed": false, "topic": "詐騙案件統計數據真實性與受理報案流程"}, {"citations": [{"page": 3384, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=17"}, {"page": 3384, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=17"}, {"page": 3385, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=18"}, {"page": 3386, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=19"}, {"page": 3386, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=19"}, {"page": 3385, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=18"}], "councilor_points": ["李柏毅議員詢問市府輔導萬華 91 家阿公店合法化政策，指出阿公店多有女性陪侍，市府輔導其為飲酒店業而非酒家業不符合實際狀況。李柏毅議員指出既存違建依規不得經營飲酒店業，市府卻允許萬華阿公店於既存違建經營，表示缺乏一體適用的公平標準。李柏毅議員要求市府重新研議法規，在確保安全與公平原則的前提下輔導產業。"], "response": "商業處處長說明，輔導係針對萬華茶室提供場所與酒類之飲酒店業，與店家本身提供對價陪侍之酒家業不同，且對該區既存建物設有消防與公安申報等條件限制。商業處處長表示，會再思考並檢視相關配套作業，以讓規定更加完善。", "response_removed": false, "topic": "萬華茶室阿公店輔導合法化與業別規範"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-04"], "dept": null, "doc_type": "市政總質詢", "group": 15, "heading": "市政總質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=1", "transcript_pages": [584, 585, 586, 587, 588, 589, 590, 591, 592, 593], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162", "videos": [{"date": "2023-12-04", "group": 15}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "htt