/gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162", "videos": [{"date": "2023-10-23", "group": 10}]}, {"dates": ["2023-11-09"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=14", "transcript_pages": [5829, 5830, 5831, 5832, 5833, 5834, 5835, 5836, 5837, 5838, 5839, 5840], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162", "videos": [{"date": "2023-11-09", "group": 3}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=22", "transcript_pages": [368, 369, 370, 371, 372, 373, 374, 375, 376], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 15}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162','2026-10-04T08:35:16Z');
INSERT INTO "fact" VALUES('summary:14-02:p072095ef7a','p072095ef7a','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:36:50Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1204, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=7"}, {"page": 1206, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=9"}, {"page": 1207, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=10"}, {"page": 1207, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=10"}, {"page": 1205, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=8"}], "councilor_points": ["李芳儒議員指出 26 歲至 40 歲的清潔隊員中大專畢業生占 54%以上，建議市府結合勞動局或職訓中心提供進修與轉職技能訓練的機會。李芳儒議員建議環保局在招考甄選簡章增列日夜班別選項，並於分派前清楚告知新進人員工作項目。李芳儒議員肯定環保局超額進用原住民，並建議規劃溝渠隊原住民名額達 6% 至 7%。"], "response": "環境保護局局長表示會研議協助有志考試的同仁，並多方思考招考班別與工作項目說明的改善作法。環境保護局人事室主任說明原住民保障類組自 87 年起開始執行，環境保護局局長並表示會評估規劃溝渠隊原住民進用比例。", "response_removed": false, "topic": "清潔隊員權益保障與招考管理改善"}, {"citations": [{"page": 5812, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=31"}, {"page": 5813, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=32"}, {"page": 5813, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=32"}, {"page": 5814, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=33"}], "councilor_points": ["李芳儒議員指出未來招租社宅一房型高達 67%，南港機廠社宅一房型更高達 76%，建議未來一房型比例勿超過 40%，並以二房型及三房型為主力。李芳儒議員建議社宅對育兒家庭直接設定保障抽籤比例，並試行由政府協助儲蓄部分租金作為購屋基金。李芳儒議員根據試算指出瑞光社宅與行善社宅分別約 25 年與 26 年即可還本，建議拉長還本時間以降低社宅租金。"], "response": "都市發展局局長說明目前已將一房型調整為 40%、二房型調整為 50%，且針對育兒家庭已有補助與將入住年限由 6 年放寬至 12 年的措施。都市發展局局長表示社宅興建還款係以 50 年計算且管理維護成本高，會再就租金及各項建議進行討論研議。", "response_removed": false, "topic": "社會住宅房型比例調整與育兒家庭權益保障"}, {"citations": [{"page": 460, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=16"}, {"page": 462, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=18"}, {"page": 460, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=16"}, {"page": 462, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=18"}], "councilor_points": ["李芳儒議員指出臺北市兩百多所學校僅有七十多位族語師資，且 60 歲以上占 60%以上、40 歲以下不足 5%，面臨師資不足與挖角問題。李芳儒議員建議建立專責的行政法人原住民族教育中心以整合資源並培育師資，並開放取得中高級認證且修畢 20 學分培訓人員先至國小教學。"], "response": "教育局局長說明族語師資認證門檻較高，並表示取得中高級認證者已於今年度開始試辦投入教學。臺北市長表示會請教育局研議原住民族教育中心法人化。", "response_removed": false, "topic": "行政法人原住民族教育中心設立與師資培育"}, {"citations": [{"page": 3860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=3"}, {"page": 3861, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=4"}], "councilor_points": ["李芳儒議員指出校園仍存在言論不友善現象，建議明年度開始實施原住民族教育檢核表，並訂定包含校園環境布置與歧視言論處置等 6 個建議指標進行友善校園評鑑。李芳儒議員指出原住民族語教學助理時薪 175 元過低，要求市府檢討並提高原住民族語教學支援老師與教學助理的薪資待遇。"], "response": "教育局局長回應可將議員提出的評鑑指標納入中小學教育品質保證實施計畫參考，並承諾在不違反中央法規下檢討教學助理的薪資待遇。", "response_removed": false, "topic": "友善原住民族校園評鑑與族語師資待遇改善"}, {"citations": [{"page": 11, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=3"}, {"page": 12, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=4"}], "councilor_points": ["李芳儒議員提出原民起飛計畫，主張將扶植分為青年學生、社會新鮮人、職場成熟、創業萌芽、經營穩定及經營突破等六大階段。李芳儒議員建議由產業發展局、勞動局與原住民族事務委員會成立工作小組，整合資源建立簡易單一的創業與職訓平臺。"], "response": "原住民族事務委員會主任委員與勞動局局長說明目前已與相關局處定期流通就業與創業資訊。產業發展局專門委員表示會後三個單位將共同研議如何將資料進行整合與呈現。", "response_removed": false, "topic": "跨局處整合推動原住民族總體經濟與創業平臺"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-30"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=14", "transcript_pages": [458, 459, 460, 462, 463, 464, 465], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162", "videos": [{"date": "2023-11-30", "group": 11}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "heading": "交通部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC#page=6", "transcript_pages": [5720, 5721, 5722, 5723, 5724], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549393E6A88A1B8E7111A783FDF0608F3F1E9A867024A40BE3F24C02E5705F2BF4102D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 13}]}, {"dates": ["2023-11-02"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=5", "transcript_pages": [1202, 1204, 1205, 1206, 1207, 1208], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162", "videos": [{"date": "2023-11-02", "group": 4}]}, {"dates": ["2023-10-12"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654932621E4D6E9743654EA47D9920AF4A747114C6A366111280A852238F00A7C162", "videos": [{"date": "2023-10-12", "group": 4}]}, {"dates": ["2023-10-19"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162#page=1", "transcript_pages": [3858, 3860, 3861, 3862], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654940C9B5D35507F7E093B58383F99E8F8D59AA1D6D277C8A3BA852238F00A7C162", "videos": [{"date": "2023-10-19", "group": 4}]}, {"dates": ["2023-11-09"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=28", "transcript_pages": [5809, 5810, 5811, 5812, 5813, 5814, 5815], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162", "videos": [{"date": "2023-11-09", "group": 2}]}, {"dates": ["2023-11-16"], "dept": "民政", "doc_type": "部門質詢", "group": 1, "heading": "民政部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162#page=1", "transcript_pages": [9, 10, 11, 12, 13, 14], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549E39796C9075EC2818D9DD67FAF8F47C8ED5476E330221E65A852238F00A7C162", "videos": [{"date": "2023-11-16", "group": 1}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162','2026-10-04T08:36:50Z');
INSERT INTO "fact" VALUES('summary:14-02:p772a0a5bf9','p772a0a5bf9','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:38:38Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 502, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=6"}, {"page": 501, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=5"}, {"page": 504, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=8"}, {"page": 502, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=6"}, {"page": 503, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=7"}], "councilor_points": ["林世宗議員指出台智光 25 年的合約將近百億元壟斷給特定廠商，並包含 4 個特許（「25 年的一只合約將近百億元壟斷給台智光，不只如此，還給他 4 個特許」）。林世宗議員要求市長站在除弊興利的立場，將此案在議場澈底解決（「期待市長站在剛剛承諾市民除弊興利的立場上，將這件不公不義的事情在議場澈底解決」）。"], "response": "市長表示已責成法務局與研考會討論，並強調會依合約與法律辦理（「我已經責成法務局、研考會討論這個案子」、「我們一定依合約、依法進行」）。資訊局局長說明 TGSN 費率部分屬於合法且合理（「就 TGSN 費率的部分是合法、合理的」）。法務局局長表示合約架構具備調整機制，經審視後選用合理費率可行（「合約的架構是有調整及機制選擇的空間，我們審視完是可以的」）。", "response_removed": false, "topic": "台灣智慧光網傳輸費率與契約監督"}, {"citations": [{"page": 508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=12"}, {"page": 509, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=13"}, {"page": 510, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=14"}, {"page": 511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=15"}, {"page": 512, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=16"}], "councilor_points": ["林世宗議員指出臺北藝術中心興建費用從 38 億元追加至 69 億元，且編列 460 人人事預算與高額委外費用（「臺北藝術中心從設計到完工，從 38 億元一直追加到 69 億元」、「北藝中心編列 460 個人，1 年要 1 億 5,000 萬元的薪水支出」）。林世宗議員要求市府建立公開透明的財務查核機制並改善營運（「財務要公開透明化」、「要組一個高階以上官員的查核覈實單位」）。"], "response": "臺北表演藝術中心執行長說明中心編制為 162 人，目前聘任將近 150 人，其餘為按小時計酬的臨時工（「本中心編制只有 162 人，目前聘任將近 150 人」、「事實上他們都是按照小時計酬的臨時工與特約人員」）。市長表示接手後認為財務與經營不理想，已要求即刻提出具體改善計畫（「接手之後，的確也認為在整個經營、財務上面不是很理想」、「會要求文化局請北藝中心，即刻提出接下來非常具體明確地經營以及財務改善計畫」）。文化局局長表示未來會嚴格要求做好經營和管理工作（「文化局會在未來時間裡，嚴格要求北藝中心做好經營和管理的工作」）。", "response_removed": false, "topic": "臺北表演藝術中心營運財務與人事監督"}, {"citations": [{"page": 5739, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B02C035267B79CF232126E64385DE9CC3E16148D0178670275719C9B55D433CC02D1DE3DCEB210BC#page=2"}, {"page": 5994, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665490C7A347FAB0E5CCB9F9C11EACF3594C5E9752D642BE319F7A852238F00A7C162#page=4"}], "councilor_points": ["林世宗議員關切福星公園地下停車場與造價 2,710 萬元的風雨操場興建進度，要求如期於 113 年底竣工並完善水電設施（「造價是 2,710 萬元」、「配合公 1 在 113 年底竣工，包含風雨操場在內會一起竣工」、「請務必要留意水電等其他基礎設施的完整性」）。林世宗議員建議在北投兒童公園與新興公園進行設施改善並增設友善廁所等設備（「新興公園興建友善廁所及風雨操場」、「如何改善、興建讓它能夠滿足整個北投觀光區域的共同共榮」）。"], "response": null, "response_removed": true, "topic": "公園設施改善與地下停車場興建計畫"}, {"citations": [{"page": 189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654926558C85422ABD9EFC401830E0C8AC1C34D439F54BC79541A852238F00A7C162#page=1"}, {"page": 190, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654926558C85422ABD9EFC401830E0C8AC1C34D439F54BC79541A852238F00A7C162#page=2"}, {"page": 191, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654926558C85422ABD9EFC401830E0C8AC1C34D439F54BC79541A852238F00A7C162#page=3"}], "councilor_points": ["林世宗議員指出奇岩長照中心獲得社會局補助卻樣樣收費且將停車位外包，要求嚴謹考核與監督（「5 年之間社會局補助 6,100 萬元」、「請你們好好監督，好好了解，好好嚴謹考核」）。林世宗議員建議因應高齡化社會，針對長者人口較多的鄰里增加社區關懷據點並加強稽核（「因應高齡化社會……讓關懷據點能夠全部展開」、「適度的嚴格稽查、嚴謹的稽核」）。"], "response": "社會局局長說明奇岩長照大樓 55 個停車位已進行調整，其中 23 個開放給一般學員使用（「55 個停車位，目前已做了調整」、「23 個開放給一般的學員」）。社會局局長表示會參考建議，研議在長者人口較多的鄰里增設社區關懷據點（「像剛剛議員說如果老人人口較多的里是不是能有較多的社區關懷據點」、「一定會參考」）。", "response_removed": false, "topic": "長照機構營運監督與社區關懷據點設置"}, {"citations": [{"page": 512, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=16"}, {"page": 513, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=17"}, {"page": 514, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=18"}, {"page": 515, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=19"}], "councilor_points": ["林世宗議員指出臺北市歲出 1,908 億元且短差 65 億元，需調度 144 億元，質疑財政吃緊（「總預算的歲出……1,908 億元」、「短差……65 億元」、「所以要去調度 144 億元」）。林世宗議員詢問 29 個基金共 1,291.5 億元的資金去向，要求財政局釐清帳目與財政全貌（「29 個基金 1,291.5 億元這麼多錢」、「責成財政局好好把帳算一下」）。"], "response": "市長說明總預算歲出為 1,908 億元，短差 65 億元，債務償還 78 億多元，需調度 144 億元（「1,908 億元」、「65 億元」、「78 億多元」、「對，沒錯」）。財政局局長說明目前市庫存款約 60 至 70 億元，且 31 個基金依法原則上由市庫集中保管（「目前市庫存款的話，是有 60、70 億元左右」、「依照公庫法的規定，原則上要由市庫集中保管」）。", "response_removed": false, "topic": "臺北市政府財政狀況與特種基金管理"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-01"], "dept": null, "doc_type": "市政總質詢", "group": 12, "heading": "市政總質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162#page=4", "transcript_pages": [500, 501, 502, 503, 504, 508, 509, 510, 511, 512, 513, 514, 515, 516], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162", "videos": [{"date": "2023-12-01", "group": 12}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B02C035267B79CF232126E64385DE9CC3E16148D0178670275719C9B55D433CC02D1DE3DCEB210BC#page=1", "transcript_pages": [5738, 5739, 5740, 5741, 5742, 5743, 5744, 5745], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549B02C035267B79CF232126E64385DE9CC3E16148D0178670275719C9B55D433CC02D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 14}]}, {"dates": ["2023-11-02"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 1, "heading": "警政衛生部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498B06693247562945F51C8070DE091317CFFEAF58F0AFF4F2A852238F00A7C162#page=1", "transcript_pages": [1133, 1134, 1135, 1136, 1137, 1138, 1139, 1140, 1141], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498B06693247562945F51C8070DE091317CFFEAF58F0AFF4F2A852238F00A7C162", "videos": [{"date": "2023-11-02", "group": 1}]}, {"dates": ["2023-10-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654941915CEB1DDC3F8EB674059599A0BAD269B00CBBB5A3B588A852238F00A7C162#page=1", "transcript_pages": [3616, 3617, 3618, 3619, 3620, 3621, 3622], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654941915CEB1DDC3F8EB674059599A0BAD269B00CBBB5A3B588A852238F00A7C162", "videos": [{"date": "2023-10-16", "group": 14}]}, {"dates": ["2023-10-19"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665494B1E7EB852DBC96D63221642FBD02ED01D305ACA439A4870A852238F00A7C162#page=1", "transcript_pages": [3887, 3888, 3889, 3890, 3891, 3892, 3893, 3894, 3895], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665494B1E7EB852DBC96D63221642FBD02ED01D305ACA439A4870A852238F00A7C162", "videos": [{"date": "2023-10-19", "group": 5}]}, {"dates": ["2023-11-13"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665490C7A347FAB0E5CCB9F9C11EACF3594C5E9752D642BE319F7A852238F00A7C162#page=1", "transcript_pages": [5991, 5992, 5993, 5994, 5995, 5996], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665490C7A347FAB0E5CCB9F9C11EACF3594C5E9752D642BE319F7A852238F00A7C162", "videos": [{"date": "2023-11-13", "group": 12}]}, {"dates": ["2023-11-17"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654926558C85422ABD9EFC401830E0C8AC1C34D439F54BC79541A852238F00A7C162#page=1", "transcript_pages": [189, 190, 191, 192, 193, 194, 195], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654926558C85422ABD9EFC401830E0C8AC1C34D439F54BC79541A852238F00A7C162", "videos": [{"date": "2023-11-17", "group": 7}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654963F8B8BB5180ECC9D037B52F56D07C24711A27108E8464E5A852238F00A7C162','2026-10-04T08:38:38Z');
INSERT INTO "fact" VALUES('summary:14-02:pcc848fb570','pcc848fb570','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:40:37Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3686, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=6"}, {"page": 3688, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=8"}, {"page": 3683, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=3"}, {"page": 3687, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=7"}, {"page": 3682, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=2"}], "councilor_points": ["林亮君議員指出臺北農產運銷公司於9月5日發生職場性騷擾事件，質疑公司高層全程在場卻未當場處置，且事後處理態度「非常、非常的消極」。林亮君議員要求該公司說明依《性別平等工作法》採取的有效糾正與補救措施，包含性平課程是否涵蓋全體員工，並於委員會工作報告前提供本案處理過程、補救措施及行政處分說明。"], "response": "臺北農產運銷公司總經理說明於9月8日得知後即請律師事務所調查，因當事人表示不願公開及申訴，故程序完結。臺北農產運銷公司董事長表示公司以嚴謹態度面對並安排性平課程與專人關懷，承諾會將處理過程與補救措施資料提供給議員。", "response_removed": false, "topic": "臺北農產運銷公司職場性騷擾事件處理"}, {"citations": [{"page": 5587, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=4"}, {"page": 5588, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=5"}, {"page": 5588, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=5"}, {"page": 5589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=6"}, {"page": 5587, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=4"}, {"page": 5589, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=6"}], "councilor_points": ["林亮君議員指出交通局協助遠雄公司設計的8種交通測試情境參與人數過少，無法如實反映萬人活動時的情形，並質疑情境未納入周邊車禍及鄰近場館同時辦活動等狀況。林亮君議員要求將周邊交通事故納入演練，並於亞錦賽後提出交通數據檢討報告與落實議會附帶決議的處置標準。"], "response": "交通局局長說明測試情境旨在找出基礎標示與動線等問題，正式活動規模不同，亞錦賽後會繼續觀察。警察局交通警察大隊大隊長表示已針對不同人數預擬2個交通疏導方案，交通局局長並承諾於亞錦賽期間收集資訊做為改善參考。", "response_removed": false, "topic": "臺北大巨蛋交通設施實地測試與周邊交通應變"}, {"citations": [{"page": 4131, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=12"}, {"page": 4132, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=13"}, {"page": 4133, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=14"}], "councilor_points": ["林亮君議員詢問在大巨蛋使用執照註記符合《建築技術規則》第127條的相關規則訂定前，是否不會舉辦非體育性展演活動。林亮君議員指出市府辦理1萬人壓力測試缺乏明確的撤離時間標準，與議會期待落實電腦模擬8分鐘與15分鐘疏散標準有所落差。"], "response": "體育局局長說明在相關規則訂定前不會舉辦非體育性大型活動，並表示本次演練係以正常營運狀況模擬動線順暢度而非緊急疏散標準，未來會採逐次遞增人數的方式演練。", "response_removed": false, "topic": "臺北大巨蛋使用執照註記與壓力測試疏散標準"}, {"citations": [{"page": 156, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=3"}, {"page": 157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=4"}, {"page": 157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=4"}], "councilor_points": ["林亮君議員指出敦煌碼頭廢棄許久且與道路動線衝突、社子島都市計畫未定致輕軌停滯，以及圓山會展專區規劃時程延至2028年，導致三大區域發展契機皆停滯。林亮君議員建議市府將敦煌碼頭周邊、迪化污水處理廠及堤外設施進行計畫性整體規劃，並儘快設計規劃圓山會展專用區。"], "response": "市長說明針對敦煌碼頭及淡水河堤岸正在進行整體規劃，並承諾1個月內提供初步規劃結果。產業發展局局長表示因需等南港會展中心完工，圓山會展專區預計最快118年或119年完工，會同步雙軌進行前期規劃。", "response_removed": false, "topic": "北大同區與北中山區區域發展規劃"}, {"citations": [{"page": 4135, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=16"}, {"page": 5942, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=2"}, {"page": 5942, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=2"}, {"page": 5943, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=3"}, {"page": 5944, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=4"}, {"page": 5945, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=5"}], "councilor_points": ["林亮君議員以晴光市場附近側溝積水處理半年的案例，指出水利工程處僅介接環境保護局清疏用的簡略資料，未掌握側溝內部結構圖資。林亮君議員建議市府應確實普查臺北市所有側溝並建立圖資系統，以提升處理效率並因應極端氣候排水需求。"], "response": "水利工程處處長說明未來會改善檢測工具以找出積水原因。工務局局長表示會先了解其他縣市政府對側溝管理及建置機制的做法後，再向議員回報。", "response_removed": false, "topic": "臺北市道路側溝圖資系統建置與權責整合"}, {"citations": [{"page": 422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=10"}, {"page": 423, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=11"}, {"page": 423, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=11"}, {"page": 424, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=12"}, {"page": 425, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=13"}], "councilor_points": ["林亮君議員指出臺北市55歲後勞動參與率大幅下降，被歸類為非勞動力的退休族群占近50%，建議跨局處合作於鄰里宣導高齡就業對健康的價值，促進勞動力重返職場。林亮君議員建議針對高缺工產業及不同企業規模細緻化銀髮友善企業認證標準，並增加企業取得標章的誘因。"], "response": "勞動局局長說明支持以健康勞動概念進行宣導，民政局局長與社會局局長亦表示願意配合加強鄰里宣導與彈性人力媒合。勞動局局長補充表示會輔導未通過認證的企業，並持續交流觀摩。", "response_removed": false, "topic": "中高齡勞動力重返職場與銀髮友善企業認證"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-24"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?i