, 3689, 3690], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162", "videos": [{"date": "2023-10-17", "group": 17}]}, {"dates": ["2023-10-24"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=10", "transcript_pages": [4129, 4130, 4131, 4132, 4133, 4134, 4135], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162", "videos": [{"date": "2023-10-24", "group": 16}]}, {"dates": ["2023-11-10"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=1", "transcript_pages": [5941, 5942, 5943, 5944, 5945, 5946], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 8}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=10", "transcript_pages": [422, 423, 424, 425], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 18}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC','2026-10-04T08:40:37Z');
INSERT INTO "fact" VALUES('summary:14-02:p5fb3d560bb','p5fb3d560bb','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:42:27Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3441, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654968C26EBB690312BA1013BB8163C7E583648F8BAB74320659A852238F00A7C162#page=7"}, {"page": 4051, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162#page=2"}, {"page": 4052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162#page=3"}, {"page": 4052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162#page=3"}, {"page": 4054, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162#page=5"}], "councilor_points": ["林延鳳議員指出臺北市自2002年起與中國上海及北京圖書館合作，並在2013年與2017年簽訂MOU互贈館藏，但上海向臺北贈書809種、870冊，臺北贈書上海僅687冊，數量並不對等。林延鳳議員表示市立圖書館設置「閱讀北京、上海之窗」專區，擺放涉及「一國兩制」、「和平統一」及統戰地圖等矮化主權內容之書籍，要求將有疑慮的書籍下架並退回。"], "response": "教育局局長與市立圖書館館長說明，圖書館展示書籍係尊重城市外交互贈交流，雖然書籍屬於對方觀點，但會針對展示方式與重點進行盤整調整，並同時展示臺灣對民主自由的論述。", "response_removed": false, "topic": "市立圖書館雙城論壇贈書與專區設置"}, {"citations": [{"page": 1335, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=2"}, {"page": 1337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=4"}, {"page": 1335, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=2"}, {"page": 1336, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=3"}, {"page": 1338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=5"}, {"page": 1337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=4"}], "councilor_points": ["林延鳳議員指出大巨蛋預計開放一萬三千多人入場進行壓力測試，消防局卻遲至11月10日才辦理消防演練，且仍沿用2015年擬訂的搶救計畫。林延鳳議員表示救災車輛與避難人潮動線皆集中於忠孝東路與光復南路，且70公尺及50公尺雲梯車調派至現場需將近半小時，要求演練應採最高標準、公開兵推劇本並進行多角度直播。"], "response": "消防局局長說明演練主要為車輛定位、進入動線熟悉及佈線，火警派遣會採逐案推升機制提前調派周邊資源，並表示會研究辦理公開劇本與多角度直播等建議。", "response_removed": false, "topic": "大巨蛋消防搶救演練與災防規劃"}, {"citations": [{"page": 5855, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162#page=7"}, {"page": 5857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162#page=9"}, {"page": 5857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162#page=9"}, {"page": 5858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162#page=10"}], "councilor_points": ["林延鳳議員指出前山公園溫泉公共浴室因管線老舊破損漏水及缺水問題長期關閉，而媽祖窟與羅漢窟溫泉公共浴室拆除10年仍未完成重選新址。林延鳳議員要求市府儘速修繕管線，研議最小量能的短期供水替代方案，並重新評估媽祖窟與羅漢窟的選址可行性。"], "response": "公園路燈工程管理處處長說明將儘速申請檢修破損管線，並評估維持基本供水的最小量能方案；大地工程處處長與產業發展局公用事業科科長表示，原址送件4次未獲通過，將重新研議選址與可行性評估。", "response_removed": false, "topic": "前山公園與溫泉公共浴室營運維護"}, {"citations": [{"page": 309, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162#page=1"}, {"page": 310, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162#page=2"}, {"page": 311, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162#page=3"}, {"page": 312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162#page=4"}], "councilor_points": ["林延鳳議員指出萬華與士林新移民會館使用率偏低，士林會館在111年使用人數僅244人，月平均單日使用不到1人。林延鳳議員表示市民當家熱線1999轉接新移民會館通譯服務的成功率僅26.17%，且時段受限，建議優化轉介機制或增加多語服務。"], "response": "民政局局長承認場館使用率偏低，承諾將擬定優化計畫與目標指標以活絡空間；研究發展考核委員會主任委員說明將針對1999轉接服務進行短期機制優化與回撥服務，並視需求評估增加語言人才。", "response_removed": false, "topic": "新移民會館使用率與通譯服務改善"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-07"], "dept": null, "doc_type": "市政總質詢", "group": 18, "heading": "市政總質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549DCAD7CD0F21B175AD96F00F4A8D98CD2E7BEAFA5FDDB234DA852238F00A7C162#page=9", "transcript_pages": [740, 741, 742, 743, 744, 745, 746, 747, 748, 749, 750, 751, 752, 753, 754, 755], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549DCAD7CD0F21B175AD96F00F4A8D98CD2E7BEAFA5FDDB234DA852238F00A7C162", "videos": [{"date": "2023-12-07", "group": 18}]}, {"dates": ["2023-10-26"], "dept": "交通", "doc_type": "部門質詢", "group": 3, "heading": "交通部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654998D53231B0A3E343924B196A458927BB5D417DB5C0F0BC72F918E1D965CAF46502D1DE3DCEB210BC#page=12", "transcript_pages": [5501, 5502, 5503, 5504, 5505, 5506, 5507], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654998D53231B0A3E343924B196A458927BB5D417DB5C0F0BC72F918E1D965CAF46502D1DE3DCEB210BC", "videos": [{"date": "2023-10-26", "group": 3}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 11, "heading": "警政衛生部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162#page=1", "transcript_pages": [1334, 1335, 1336, 1337, 1338, 1339, 1340], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498F3902A0F21AE009A3853EA5999DF0C26F4C9138DC9DBCC5A852238F00A7C162", "videos": []}, {"dates": ["2023-10-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 5, "heading": "財政建設部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654968C26EBB690312BA1013BB8163C7E583648F8BAB74320659A852238F00A7C162#page=1", "transcript_pages": [3435, 3436, 3437, 3438, 3439, 3440, 3441, 3442], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654968C26EBB690312BA1013BB8163C7E583648F8BAB74320659A852238F00A7C162", "videos": [{"date": "2023-10-13", "group": 5}]}, {"dates": ["2023-10-23"], "dept": "教育", "doc_type": "部門質詢", "group": 13, "heading": "教育部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162#page=1", "transcript_pages": [4050, 4051, 4052, 4053, 4054, 4055, 4056], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491E59533FDFF945BBE85515EE1BC9B55B9530B7D8BF0E3A34A852238F00A7C162", "videos": [{"date": "2023-10-23", "group": 13}]}, {"dates": ["2023-11-09"], "dept": "工務", "doc_type": "部門質詢", "group": 4, "heading": "工務部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162#page=7", "transcript_pages": [5855, 5856, 5857, 5858, 5859, 5860], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665492E3A4A4F1F4B9E23BD13F15BD1E03768C66DAA3CB20EDCCBA852238F00A7C162", "videos": [{"date": "2023-11-09", "group": 4}]}, {"dates": ["2023-11-20"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162#page=1", "transcript_pages": [309, 310, 311, 312, 313, 314, 315, 316, 317, 318], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654954B7DBD58A88EF506B29A287333E31DCAE116DE6EB7A74E1A852238F00A7C162", "videos": [{"date": "2023-11-20", "group": 13}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549DCAD7CD0F21B175AD96F00F4A8D98CD2E7BEAFA5FDDB234DA852238F00A7C162','2026-10-04T08:42:27Z');
INSERT INTO "fact" VALUES('summary:14-02:pcdef61ef89','pcdef61ef89','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:45:00Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 168, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=2"}, {"page": 168, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=2"}, {"page": 169, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=3"}, {"page": 170, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=4"}, {"page": 171, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=5"}, {"page": 172, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=6"}], "councilor_points": ["林杏兒議員指出重陽敬老金多元致送造成基層與長輩困擾，將近四分之一長輩需至定點領取，且里幹事身懷鉅款發放現金、使用紙本名冊領取存有資安風險（「將近四分之一是定點領取，55 萬人的四分之一要到定點領取」、「2 億 1,000 萬元在臺北市的每個里裡面流動，平均 1 個里的里幹事要發 46 萬元」、「紙本領取的狀況下，里辦進出的人非常多，每個人都看得到那些資料」）。林杏兒議員建議社會局結合民政局里辦數位系統進行 E 化靠卡發放，並建議配備至少 2 臺平板電腦供里辦使用（「為什麼社會局沒有考慮和民政局將系統融合在一起，讓發放重陽敬老金 E 化呢」、「2 臺是最基本的配備」）。林杏兒議員建議簡化申請程序，對於已有相關補助帳戶的長輩採取主動通知並直接匯款（「申請程序越簡單越好」、「只要有申請過補助的帳戶，你們就該用那個帳戶給他們，只需要通知他們」）。"], "response": "社會局局長說明，本次恢復發放係多元致送，靠卡人數為 37 萬多人，定點領取人數增加會再進行檢討，目前社福資料庫無法與民政局系統介接，明年會增加合作銀行並簡化作業（「多元致送」、「這次靠卡的民眾是 37 萬多人」、「目前我們的社福資料庫沒辦法和這個系統介接」、「明年我們會提前作業，增加銀行的帳戶」）。民政局局長說明，若里辦辦理活動有需求，區公所均有支援的系統與配備可隨時支援（「我們有支援的系統和配備，區公所也有」、「只要他們提出需求，我們就會隨時支援」）。", "response_removed": false, "topic": "重陽敬老金發放管道與資安及作業優化"}, {"citations": [{"page": 5826, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665493836D984DE05B7C01940DFEE53EA9219A94D7EFF50EE1F9828AC3845FC91CEBF02D1DE3DCEB210BC#page=8"}, {"page": 1164, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654915890AB6B6839F68DCA11C5C8FA52EFF3C6A8619B157BA77A852238F00A7C162#page=19"}, {"page": 1165, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654915890AB6B6839F68DCA11C5C8FA52EFF3C6A8619B157BA77A852238F00A7C162#page=20"}, {"page": 1167, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654915890AB6B6839F68DCA11C5C8FA52EFF3C6A8619B157BA77A852238F00A7C162#page=22"}, {"page": 1166, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654915890AB6B6839F68DCA11C5C8FA52EFF3C6A8619B157BA77A852238F00A7C162#page=21"}], "councilor_points": ["林杏兒議員指出中央放寬 13 項民眾檢舉後，臺北市舉發與申訴案件暴增三倍，造成基層員警與里長極大負擔（「立法院通過，可以讓民眾檢舉增加了 13 項」、「從原本案件七萬多件，但到現在 8 月 13 萬件」、「每月申訴破 3,000 件」、「暴增三倍」）。林杏兒議員表示一年內記 12 點會被吊扣駕照 2 個月，嚴格規定導致民眾計較並引發違規點數轉移買賣的新興非法產業，點數每點約 3,000 元（「一年內記十二點就會被吊扣駕照兩個月」、「違規點數轉移七月到八月爆增一倍，六月才兩萬兩千多件，八月就已經到四萬多件」、「交通記點販售，一點我聽到 3,000 元」）。林杏兒議員要求市府向中央反映相關法令執行困難，並建議設置專人審核紅單以減輕分局負擔（「地方沒辦法執行、有困難，你應該要去跟中央反映」、「請專人認定這些紅單，不要再給所有分局基層的人」）。"], "response": "警察局局長說明，目前仍以現有人力處理審核，爭議案件會確認是否符合規定，標誌標線不清楚部分會反映給交通局改善（「我們還是現有人力」、「案件我們受理會審核」、「標誌、標線不清楚，我們反映給交通局來做改善」）。警察局局長表示，議員反映的記點與法規爭議屬於中央法律問題，會向中央反映相關狀況（「前幾天因為記點狀況，計程車司機到交通部去陳情抗議，那我想議員你在這邊質詢的，有一些是法律上問題」、「我們會反映」）。", "response_removed": false, "topic": "交通違規檢舉與違規記點制度爭議"}, {"citations": [{"page": 5768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654918DDFD07446CCAF7773092551F9BE27EB27433E845258DF5A852238F00A7C162#page=8"}, {"page": 5768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654918DDFD07446CCAF7773092551F9BE27EB27433E845258DF5A852238F00A7C162#page=8"}, {"page": 5769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654918DDFD07446CCAF7773092551F9BE27EB27433E845258DF5A852238F00A7C162#page=9"}], "councilor_points": ["林杏兒議員指出危老重建推動師培訓僅需上課 3 天且通過率達 95%，市府發給識別證及印有北市府 LOGO 名片易使民眾誤認為公務員而交付個資（「上完 3 天的課程然後考完試就有這張認可證」、「通過率是 95%」、「名片上有臺北市政府的 LOGO，當然一般民眾很容易誤以為他是公務人員」）。林杏兒議員指出 108 年至 112 年市府補助金額達 5,877 萬 5,000 元，但通過初步評估有 1,244 件，最終重建計畫僅 169 件，部分推動師僅為領取初步評估每件 2 萬多元或最高 40 萬元補助（「108 年到 112 年的資料，市府總共已經發出 5 千多萬元的補助金額」、「補助都更案件的經費有 5,877 萬 5,000 元，但是經過初步評估的案件有 1,244 件」、「平均初步評估 1 件可以領到 2 萬多元」、「最高可以申請到 40 萬元」、「重建計畫只有 169 件」）。林杏兒議員質疑建商員工取得推動師資格後雙邊賺取補助金，要求市府重新檢討培訓與識別證發放制度並約束避嫌（「有一些建商僱用的人，本身就是危老重建推動師」、「雙邊賺錢」、「請你們重新檢討這個制度到底可不可行」）。"], "response": "建築管理工程處處長說明，推動師培訓目前已限縮資格，發放識別證係證明其通過測驗，核發補助費係因推動師協助完成耐震初評（「過去本來有 5 個類組，現在只有實際從事相關工作或專業技師才可以參加危老推動師的培訓」、「我們輔導完成了才會核發補助費」、「我們發給他們識別證，只是證明他們有經過考試、測驗」）。建築管理工程處處長表示，將會對培訓機構特別要求，並檢討改進推動業務方式以避免民眾誤會（「我們會對於培訓的機構再特別要求」、「我們會再要求危老推動重建師，未來在推動危老業務的時候，有沒有可以改進的地方，避免讓民眾誤會」）。", "response_removed": false, "topic": "危老重建推動師制度與個資規範"}, {"citations": [{"page": 3977, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549404CA0D07AA1DA41C7086CECA261F6A8236A7FDBFCE4829DA852238F00A7C162#page=7"}, {"page": 3978, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549404CA0D07AA1DA41C7086CECA261F6A8236A7FDBFCE4829DA852238F00A7C162#page=8"}, {"page": 3979, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549404CA0D07AA1DA41C7086CECA261F6A8236A7FDBFCE4829DA852238F00A7C162#page=9"}, {"page": 3980, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549404CA0D07AA1DA41C7086CECA261F6A8236A7FDBFCE4829DA852238F00A7C162#page=10"}], "councilor_points": ["林杏兒議員指出北市導護志工共 5,647 人，每年設備預算僅 369 萬元，平均每人約 655 元，且導護志工保險保額 200 萬元低於一般志工的 100 萬至 300 萬元，亦無住院醫療保障（「本市導護志工總共有 5,647 人，但是每年的預算才 369 萬元，等於 1 個人才 655 元」、「一般的志工身故保險金、失能保險金，是 100 萬元至 300 萬元，但是導護志工只有 200 萬元」、「一般的志工還有住院、醫療保險金……但是導護志工沒有保障」）。林杏兒議員建議提高導護志工保額至 300 萬元並增加住院醫療保險，編列預算發給肩夾警示燈以保障執勤安全（「應該將導護志工的保險金額提高到 300 萬元，而且要增加他的住院醫療保險金」、「編列肩夾警示燈給他們」）。林杏兒議員建議擴增招募管道、加強情緒與感恩教育，並於複雜路口動用警力或編列經費由義交協助（「擴增更多管道」、「應該要教育學生多說『謝謝』」、「動用警力來指揮交通」）。"], "response": "教育局局長說明，369 萬元為採購設備預算，導護志工保險採定型化契約每人每年 150 元，失能保額為 100 萬至 300 萬元，針對提高保額與一致性會研議處理（「那是採購設備的預算」、「保險費每人每年 150 元」、「如果失能的話，保額是 100 萬元到 300 萬元」、「我們會一起研議，儘量看他們的保險能不能一致」）。教育局局長說明，受過培訓的義交導護約 1,800 位，針對約 9 個需義交協助的路口會研議編列經費，並會研議配發肩夾警示燈與加強學生感恩教育（「大概有 1,800 位屬於義交」、「大概剩下 9 個地方可能還需要請警察局的義交協助」、「研議辦理」、「會一起來努力」）。", "response_removed": false, "topic": "校園導護志工權益保障與人力設備改善"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-23", "2023-11-24"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549C5CF2FEBF4DC35CE707192FE38705FD3A37955134EEE9EC0399F61A2200C5A0402D1DE3DCEB210BC#page=22", "transcript_pages": [88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549C5CF2FEBF4DC35CE707192FE38705FD3A37955134EEE9EC0399F61A2200C5A0402D1DE3DCEB210BC", "videos": [{"date": "2023-11-23", "group": 2}, {"date": "2023-11-24", "group": 2}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 18, "heading": "交通部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665493836D984DE05B7C01940DFEE53EA9219A94D7EFF50EE1F9828AC3845FC91CEBF02D1DE3DCEB210BC#page=1", "transcript_pages": [5819, 5820, 5821, 5822, 5823, 5824, 5825, 5826], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE