rl": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654918DDFD07446CCAF7773092551F9BE27EB27433E845258DF5A852238F00A7C162#page=6", "transcript_pages": [5766, 5767, 5768, 5769, 5770], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654918DDFD07446CCAF7773092551F9BE27EB27433E845258DF5A852238F00A7C162", "videos": [{"date": "2023-11-09", "group": 1}]}, {"dates": ["2023-11-17"], "dept": "民政", "doc_type": "部門質詢", "group": 6, "heading": "民政部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162#page=1", "transcript_pages": [167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654947AF0076EDE11A90DFAE314AB1CDD657AD9F4C4A2A4406BEA852238F00A7C162", "videos": [{"date": "2023-11-17", "group": 6}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549C5CF2FEBF4DC35CE707192FE38705FD3A37955134EEE9EC0399F61A2200C5A0402D1DE3DCEB210BC','2026-10-04T08:45:00Z');
INSERT INTO "fact" VALUES('summary:14-02:p41a7902cc9','p41a7902cc9','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T08:50:11Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 624, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=41"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=42"}, {"page": 626, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=43"}, {"page": 626, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=43"}, {"page": 627, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=44"}, {"page": 5841, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=26"}, {"page": 5842, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=27"}, {"page": 5842, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=27"}, {"page": 5844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=29"}, {"page": 5845, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=30"}, {"page": 5846, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=31"}, {"page": 5847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=32"}, {"page": 5847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549366A248EF996C89562940B4A011E25BD65409194C4DF9BF1A852238F00A7C162#page=32"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=42"}], "councilor_points": ["柳采葳議員指出基泰大直事件發生超過3個月，市府角色「很像路人甲」且「變成傳聲筒」，要求市府展現魄力，依鑑定報告由基泰或福益營造直接以金錢賠償受損戶與家具損害，並要求於農曆年前完成巷弄管線復原。柳采葳議員要求都發局與建管處掌握技師公會之鑑定報告與透地雷達檢測數據，加速福益營造對通報鄰損戶之修繕，並針對儒林園地下室換坪問題提供專案補償。柳采葳議員要求市府揭露預售屋買賣契約解約退款與違約金訊息，並持續督促基泰建設將款項匯入指定專戶。"], "response": "市長說明市府立場堅定且積極處理，要求基泰負起賠償責任，並表示會努力在農曆年前修好管線與道路，若發文無效會採取非常手段。建築管理工程處處長與法務局局長說明已發文要求基泰依鑑定金額進行協商與修繕，說明已有27戶完成修繕，並承諾於指定期限提供包含透地雷達檢測之鑑定報告。都市更新處處長與地政局科長說明會將地下室狀況納入估價討論。", "response_removed": false, "topic": "基泰大直新建案鄰損與賠償處理"}, {"citations": [{"page": 627, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=44"}, {"page": 629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=46"}, {"page": 630, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=47"}, {"page": 631, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=48"}, {"page": 360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=14"}, {"page": 360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=14"}, {"page": 362, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=16"}, {"page": 363, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=17"}, {"page": 363, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=17"}, {"page": 364, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=18"}, {"page": 365, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654952A08CBD10ED0DEF48F2313A77D0D3F860D48ACE85F18D2AA852238F00A7C162#page=19"}, {"page": 628, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=45"}, {"page": 630, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=47"}], "councilor_points": ["柳采葳議員指出社會住宅已成為「犯罪溫床」，有多起刑事與毒品案件發生，但都發局完全狀況外且未依規約解約，要求研擬專責主任進駐社宅以加強安全掌控。柳采葳議員舉出社宅發生高中生涉及13起對小男童之性騷與猥褻案件，指出都發局不在社會安全網內導致無法即時知悉與解約，讓家長與學童處於不安全環境。柳采葳議員要求將都發局納入社會安全網，建立刑事案件之風險分級、通報SOP與強制解約機制，並由秘書長主責橫向溝通協調。"], "response": "市長表示已建立管理平台將都發局與警察局納入社宅安全網，並承諾研議設置專責主任管理社宅。住宅及都市更新中心代理執行長說明委託物業保全依契約執行社宅管理與違約處理，並會提供相關工作月報。秘書長與社會局局長表示會強化社會局社福中心功能，並由秘書長邀集相關單位召開會議，建立都發局納入社安網之通報機制與分級SOP。", "response_removed": false, "topic": "社會住宅安全管理與犯罪通報機制"}, {"citations": [{"page": 3393, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=26"}, {"page": 4016, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=25"}, {"page": 4017, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=26"}, {"page": 4018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=27"}, {"page": 4019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=28"}, {"page": 4019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=28"}, {"page": 4020, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549508F05F8C7634F6DE88A45D60F425403727E8E341ADD19ACA852238F00A7C162#page=29"}], "councilor_points": ["柳采葳議員指出市面上充斥盜版假熊讚商品，智慧財產局以「熊讚」屬於通俗用語為由駁回商標申請，要求觀傳局再次積極送件申請商標專利。柳采葳議員指出有非簽約廠商製造販售熊讚商品甚至以二手名義販售，要求市府建立控管機制與監督產品品質。"], "response": "觀光傳播局局長表示熊讚能代表臺北意象，承諾會委託代理人儘速重新向智慧財產局送件申請註冊商標。觀光傳播局城市旅遊科科長與市場處副處長說明非簽約廠商標示符合商標法規定且以二手商品名義販售，觀傳局會研究建立品質規範與控管機制。", "response_removed": false, "topic": "臺北市吉祥物熊讚商標申請與授權管理"}, {"citations": [{"page": 633, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=50"}, {"page": 1442, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=26"}, {"page": 1442, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=26"}], "councilor_points": ["柳采葳議員指出環保局自108年以來接獲6件職場霸凌申訴均不成立，且申訴當中有3件係針對同一人，質疑判定標準不公。柳采葳議員指出調查小組由3位內部主管與2位外聘專家學者組成，內部人員占多數易有包庇疑慮，要求增加外聘專家學者比例並提出進度報告。"], "response": "環境保護局局長說明霸凌申訴案件均依程序由委員會審查決定，已規劃增加外聘專家學者擔任審查委員，並會提出進度報告。", "response_removed": false, "topic": "環保局職場霸凌申訴與調查機制改善"}, {"citations": [{"page": 3390, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=23"}, {"page": 3390, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=23"}, {"page": 3391, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=24"}], "councilor_points": ["柳采葳議員指出動物之家去年退養數達53件創歷年新高，且提供30天猶豫期過長，導致民眾因「不會叫」等不合理理由退養寵物。柳采葳議員建議將退養毛小孩之民眾予以註記，並要求經註記之認養人若再次認養，必須通過動保處家訪確認資格。"], "response": "動物保護處處長說明30天猶豫期係讓認養人與動物互相了解適應，並表示會研議退養註記與二次認養家訪審查機制。", "response_removed": false, "topic": "動物之家寵物退養與認養審核機制"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-04"], "dept": null, "doc_type": "市政總質詢", "group": 15, "heading": "市政總質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162#page=37", "transcript_pages": [620, 621, 622, 623, 624, 625, 626, 627, 628, 629, 630, 631, 632, 633], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549B8772E6ACF46C91D1EF13CEEF79D30854D36B48595F8B7B7A852238F00A7C162", "videos": [{"date": "2023-12-04", "group": 15}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549388DF31CE04A7B270FD7050B329BB5B9C1B026F741864062B3B91BCCB1E2760102D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 11}]}, {"dates": ["2023-11-07"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162#page=24", "transcript_pages": [1440, 1441, 1442, 1443, 1444, 1445], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665491102BD067B6DC1CBF51C8070DE0913170B5F5E449894FA2CA852238F00A7C162", "videos": [{"date": "2023-11-07", "group": 14}]}, {"dates": ["2023-10-12"], "dept": "財政建設", "doc_type": "部門質詢", "group": 2, "heading": "財政建設部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654995C9E967BF062C0A134A14589CD77873B01B01FC3EE603ADA852238F00A7C162#page=22", "transcript_pages": [3389, 33