INSERT INTO "fact" VALUES('summary:14-02:p28d7d936d9','p28d7d936d9','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T09:01:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 668, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=2"}, {"page": 669, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=3"}, {"page": 667, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=1"}], "councilor_points": ["游淑慧議員指出父母若具中華民國國籍，其海外出生子女在國籍、戶籍與居留申請上遭遇困境，詢問相關法律程序與認定方式。游淑慧議員說明子女出生時雖具申請資格，仍需依規定辦理認領或申辦程序，若父母放棄國籍亦影響子女，並表示成年後重新申請屬「回復國籍」而非歸化。游淑慧議員要求市府若掌握正副總統參選人之國籍相關資料，應主動且勇於任事提供給中央選舉委員會查核。"], "response": "民政局局長說明依屬人主義，父母具中華民國國籍者子女即具國籍，且戶籍資料均記載清楚。市長表示正副總統資格事關重大，中選會或當事人應說明清楚，若向市府索取相關資料，市府依法都會配合提供。", "response_removed": false, "topic": "海外出生子女國籍認定與參選資格查核"}, {"citations": [{"page": 677, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=11"}, {"page": 677, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=11"}, {"page": 679, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=13"}, {"page": 681, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=15"}, {"page": 682, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=16"}, {"page": 682, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=16"}, {"page": 678, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=12"}], "councilor_points": ["游淑慧議員詢問市府約見內政部部長溝通社子島開發案之進度，並指出該案預算約 2,180 億元均由北市自籌，質疑內政部要求剔除反對戶等條件造成開發延宕。游淑慧議員建議市府應每月催辦，並要求市府做好相關準備，以利中央核定後能迅速啟動工程。游淑慧議員建議市長可利用行政院會場合直接與內政部部長溝通反映社子島開發問題。"], "response": "地政局局長說明目前尚未約見到內政部部長，並表示市府已針對九大聚落擬定調整方案並於 11 月 30 日送出，將兼顧公益性與必要性持續推進。市長表示市府持續透過管道邀請內政部部長，並已針對內政部意見盡可能調整，希望中央能盡快核定。", "response_removed": false, "topic": "社子島區段徵收開發案推進與中央溝通"}, {"citations": [{"page": 5936, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=26"}, {"page": 5937, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=27"}, {"page": 5938, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=28"}, {"page": 5939, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=29"}, {"page": 5938, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=28"}], "councilor_points": ["游淑慧議員指出臺北市第三種住宅區基準容積率僅為 225%，為六都最低且自民國 72 年訂定後 40 年未檢討，造成老舊公寓都市更新困難。游淑慧議員表示現行容積管制與公設及消防等法規環境已不相同，建議都發局應開放思考，比照其他縣市因地制宜調整各行政區住三基準容積率，以提升民眾參與都更之誘因。"], "response": "都市發展局局長說明住三基準容積率係於民國 72 年依每公頃 900 人之密度推估，目前整體容積預估可容納 350 萬人口，並表示現階段已提出防災型都更等獎勵措施來促進都市更新。", "response_removed": false, "topic": "第三種住宅區基準容積率檢討"}, {"citations": [{"page": 3920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=22"}, {"page": 3923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=25"}, {"page": 3924, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=26"}], "councilor_points": ["游淑慧議員指出北市公立學校超過 40 年之校舍高達六成，部分屬於海砂屋之校舍卻僅做補強而未優先排入改建，質疑市府改建速度過於緩慢。游淑慧議員指出過去 11 年校舍改建預算總計僅 95 億元，要求教育局應積極編列預算並加速推動老舊及高風險校舍之改建。"], "response": "教育局局長說明目前已就 30 年以上校舍進行結構與氯離子等指標評估，並表示市府已提高改建預算，未來將依工程進度增加編列以加速推進。", "response_removed": false, "topic": "公立學校老舊與海砂校舍改建進度"}, {"citations": [{"page": 1389, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=8"}, {"page": 1389, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=8"}, {"page": 1391, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=10"}, {"page": 1392, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=11"}, {"page": 1392, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=11"}, {"page": 1393, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=12"}, {"page": 1391, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=10"}, {"page": 1390, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=9"}], "councilor_points": ["游淑慧議員指出市立聯合醫院護理人員與藥師離職率上升，導致關床數達到 200 多床，質疑單靠調高薪資仍無法解決留才困境。游淑慧議員建議市府除調整薪資外，應全面改善醫護工作環境，並向衛福部與中央機關反映法規及制度面之問題。"], "response": "市立聯合醫院院長說明醫院關床約 200 床，係因大環境與民間社區藥局競爭搶人，已透過調高單位津貼與提升起跳薪資改善離職率，並持續與醫護專科學校進行建教合作。衛生局局長說明疫情後護理人員轉往居家照護比例增加，已將市立醫院遭遇之困境向衛福部反映。", "response_removed": false, "topic": "市立聯合醫院醫護人員離職潮與關床問題"}, {"citations": [{"page": 5786, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=3"}, {"page": 5787, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=4"}, {"page": 5785, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=2"}, {"page": 5787, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=4"}], "councilor_points": ["游淑慧議員指出捷運頂埔站聯合開發案簽約超過 14 年仍未開發，私地主提供 76% 土地但分回比例僅 16%，且市府將地下空間作為停車場營運收取 2,000 多萬元副業收入卻未分給地主。游淑慧議員要求捷運局釐清開發利益歸屬、支付地主合理土地租金，並建議未來聯開契約應訂定最晚開發完成期限。"], "response": "捷運工程局局長說明因房地產不景氣及招轉移等因素致作業延宕，承認行政過程對地主不夠即時，承諾將研擬對原地主最佳之法律與權益分配救濟方案，並修正未來契約機制。臺北大眾捷運股份有限公司總經理表示該停車場收入確實列為公司副業收入。", "response_removed": false, "topic": "捷運頂埔站聯合開發案延宕與地主權益保障"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=1", "transcript_pages": [667, 668, 669, 670, 671, 672, 673, 674, 675, 676, 677, 678, 679, 680, 681, 682, 683, 684, 685], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 17}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=1", "transcript_pages": [5784, 5785, 5786, 5787, 5788, 5789, 5790, 5791], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 17}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=1", "transcript_pages": [1382, 1383, 1384, 1385, 1386, 1387, 1388, 1389, 1390, 1391, 1392, 1393], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?