INSERT INTO "fact" VALUES('summary:14-02:p32da79905a','p32da79905a','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T09:03:24Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3803, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549B6A7C0F8E7B043587357573AA4D417BDA8CF5E11E480A4F2A852238F00A7C162#page=6"}, {"page": 3806, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549B6A7C0F8E7B043587357573AA4D417BDA8CF5E11E480A4F2A852238F00A7C162#page=9"}, {"page": 3804, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549B6A7C0F8E7B043587357573AA4D417BDA8CF5E11E480A4F2A852238F00A7C162#page=7"}], "councilor_points": ["王孝維議員指出非學校型態實驗教育機構租借公立學校教室之「租金可能不一樣」，且補助金額甚至「已 cover 租金」，卻使用學校行政、醫護與安全資源，形成「一國兩制」。王孝維議員建議教育局應將相關機構「列入單位管理」，並合理計算租金與補助。"], "response": "教育局局長說明租金是「適用公定價格」，補助係依「臺北市高級中等以下教育階段非學校型態實驗教育獎勵補助要點」辦理，並表示「會檢討這部分，盤整他們使用模式」。", "response_removed": false, "topic": "非學校型態實驗教育機構管理與資源使用"}, {"citations": [{"page": 3497, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=2"}, {"page": 3498, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495E292F5DDB62297F06F08F9854E84FD8728E8A5D92A6991BA852238F00A7C162#page=3"}], "councilor_points": ["王孝維議員指出南港區成德市場內部「坑洞一堆」、「水會倒灌」且電力系統「三天就跳一次電」，影響地坪安全與環境衛生。王孝維議員要求市府在「一個月之內修補好」地坪坑洞與管線問題，且維修時不應要求攤商停業。"], "response": "市場處處長說明會先以「零星修繕」處理解決地坪坑洞與污水管疏通，承諾「在市政總質詢之前完成」，並會尋找其他廠商解決電力問題及進行「BOT 的財務評估計畫」。", "response_removed": false, "topic": "成德市場設施破損與改善處置"}, {"citations": [{"page": 1311, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=27"}, {"page": 1312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497865360A42C5EC07616BC257C5FAB6DE80924850A508E165A852238F00A7C162#page=28"}], "councilor_points": ["王孝維議員指出交通違規開單一年推算「會有將近260萬件」，且「檢舉已經超過60%」，記點扣照影響計程車與物流司機生計。王孝維議員要求交工處「去設置 1 個友善的臨時停車位」限時5分鐘供臨停，並建議警察局「用勸導的方式」執行勤務以減輕警員負擔。"], "response": "警察局局長表示「交工處是不是可以多劃設」可臨停地點，實體發現臨停可「用勸導的方式來做執行」，並表示同意議員對減少警員負擔與維護公信力的看法。", "response_removed": false, "topic": "交通違規舉發件數過高與友善臨時停車位設置"}, {"citations": [{"page": 256, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=52"}], "councilor_points": ["王孝維議員指出每日往來新北市與臺北市的機車族將近百萬，但「路邊機車停車格有將近 26 萬個」，機車退出騎樓與人行道2.0政策缺乏配套。王孝維議員要求市府「1 個月內要提出來」配套措施，並應以「勸導的方式」代替強行開罰單。"], "response": "市長說明會「研擬相關的配套」如設機車彎與增設停車空間，表示會「檢討」勸導事宜；交通局局長表示「交通局會做檢討」。", "response_removed": false, "topic": "機車退出騎樓與人行道2.0政策配套"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-27"], "dept": null, "doc_type": "市政總質詢", "group": 7, "heading": "市政總質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC#page=52", "transcript_pages": [256, 257, 258, 259, 260, 261, 262, 263], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497C3F3F0F3DFCD3E66C935823F58C14CD23E958517FE552EDE0861F1B16FE772F02D1DE3DCEB210BC", "videos": [{"date": "2023-11-27", "group": 7}]}, {"dates": ["2023-10-26"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E40A85823A1BF9681A783FDF0608F3F1336AA38B2523CBB060070A2614BBD04102D1DE3DCEB210BC#page=19", "transcript_pages": [5527, 5528, 5529, 5530, 5531], "transcript_