INSERT INTO "fact" VALUES('summary:14-02:p70a5d9018c','p70a5d9018c','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T09:11:24Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 5886, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162#page=20"}, {"page": 5890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162#page=24"}, {"page": 5890, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162#page=24"}], "councilor_points": ["王閔生議員指出，水利工程處今年編列 2 千 1 百多萬元預算辦理河濱花海工程，但官網連結及「花IN台北」網站缺乏詳細花種、地點與交通介紹（「水利處每年花費在花海工程的經費大概是 1、2 千萬元，今年是編列 2 千 1 百多萬元預算」）。王閔生議員建議將資訊做到一目了然，包含設置河濱花海專區、依春秋冬分類介紹並結合交通圖照說明，並橫向整合「台北河𨑨迌」與公園路燈工程管理處同步更新（「我建議把河濱公園花海的花季資訊，可以再設置一個專區」、「可以分春、夏、秋、冬 4 個季節」、「希望你們做好橫向的整合」）。"], "response": "水利工程處處長與公園路燈工程管理處處長說明，會配合設置專區與橫向連結，並於 2 個星期內將初步改進方向回報（「我們來跟花 IN 台北再……本處也會有一個專區」）。", "response_removed": false, "topic": "臺北河濱花海資訊整合與宣傳優化"}, {"citations": [{"page": 1251, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=24"}, {"page": 1251, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=24"}, {"page": 1252, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=25"}, {"page": 1253, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=26"}], "councilor_points": ["王閔生議員指出，市立聯合醫院病房助理因人力不足出現過勞及支援傳送員問題，現階段亦無法達成 1：10 至 1：15 的照護比例（「病房助理因為有照顧服務員或是居家照顧服務員的資格……卻因為人力不足造成過勞」、「意思就是現在做不到我們訂定的照護比」）。王閔生議員表示，辦理的照顧服務員訓練班 108 人訓練後實際留任僅 18 人，建議透過發給獎金與年終獎金提高誘因以補足人力缺口（「總共有 108 人來接受訓練……實際留在聯醫的病房助理加起來才 18 人」、「用獎金提高誘因」）。"], "response": "衛生局局長與市立聯合醫院總院長說明，正密切監測照護比例並進行滾動式調整，明年 1 月 1 日調整薪資時會一併調整，並研議增加訓練班次與招聘誘因（「明定的工作內容與照護比例……正密切的監測當中」、「未來在 2 個月後，1 月 1日調整薪資時，他們也會一併調整薪資」）。", "response_removed": false, "topic": "市立聯合醫院病房助理權益保障與人力補充"}, {"citations": [{"page": 5639, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=31"}, {"page": 5640, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=32"}, {"page": 5640, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=32"}], "councilor_points": ["王閔生議員表示，不贊成恢復 YouBike 前 30 分鐘免費，認為應將資金用於增加車輛調度人力（「我很不贊成恢復前 30 分鐘免費的事情」、「如果這 5 元可以讓民眾有車可借、有位子可還，可以增加調度的人力」）。王閔生議員建議，5 年 5 億元擴增計畫導入 4,000 輛以上 E-Bike（電動輔助自行車）應進行北北桃跨市整合，並合理配置山區地點及加強後勤調度與騎乘安全（「導入 E-Bike 是鑑於臺北市老年人口比例逐漸提高……考量長距離以及跨市騎乘的需求」、「要規劃 E-Bike 合理的配置地點」）。"], "response": "交通局局長說明，調度費用應由微笑單車公司負擔，E-Bike 目標於 117 年達到 4,000 輛以上，並正與新北市及桃園市洽談跨市整合與費率擬定（「YouBike 整個調度人力的費用，本來就應該由微笑單車公司負擔」、「我們目標是到 117 年 4,000 輛」、「目前我們和新北市政府和桃園市政府都在洽談之中」）。", "response_removed": false, "topic": "微笑單車YouBike與E-Bike推動規劃"}, {"citations": [{"page": 129, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=20"}, {"page": 128, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=19"}, {"page": 130, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=21"}], "councilor_points": ["王閔生議員指出，三貓計畫 2.0 包含源自指南宮 133 年歷史山川祭典的「臺北里山川公共藝術計畫」，去年 10 天活動吸引 13,000 多人參與（「三貓計畫 2.0 源自於指南宮百年的歷史，1890 年建造，現在已經有 133 年悠久」、「10 天活動中，包含平假日總共有 13,000多人參與活動」）。王閔生議員要求市府跨局處共同重視，結合觀傳局宣傳、產發局與商業處商圈推廣、捷運公司文創商品及政治大學等資源，將里山川打造成臺北市文化活動品牌（「希望這不只是文山區，應該是臺北市一個文化活動的品牌」、「交辦各個局處共同重視並協助明年的里山川」）。"], "response": "市長表示絕對非常重視，已規劃於指南宮後山圓滿森境搭建固定舞台，並承諾未來結合觀光、文化、宗教與商圈等局處全力支持，打造成一年一度的盛事（「未來規劃搭建固定的舞台」、「未來會打造成為臺北市一年一度的盛事……全力來支持里山川」）。", "response_removed": false, "topic": "貓空三貓計畫2.0與臺北里山川公共藝術計畫推動"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-24"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=18", "transcript_pages": [127, 128, 129, 130, 144, 145, 146, 147, 149, 150, 151, 152, 153], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC", "videos": [{"date": "2023-11-24", "group": 3}]}, {"dates": ["2023-10-27"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=24", "transcript_pages": [5632, 5633, 5634, 5635, 5636, 5637, 5638, 5639, 5640, 5641], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC", "videos": [{"date": "2023-10-27", "group": 9}]}, {"dates": ["2023-11-03"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 5, "heading": "警政衛生部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=23", "transcript_pages": [1250, 1251, 1252, 1253], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 5}]}, {"dates": ["2023-10-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=21", "transcript_pages": [3652, 3653, 3654, 3655, 3656, 3657], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162", "videos": [{"date": "2023-10-17", "group": 15}]}, {"dates": ["2023-10-20"], "dept": "教育", "doc_type": "部門質詢", "group": 7, "heading": "教育部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=25", "transcript_pages": [3956, 3957, 3958, 3959, 3960, 3961, 3962], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162", "videos": [{"date": "2023-10-20", "group": 7}]}, {"dates": ["2023-11-10"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162#page=19", "transcript_pages": [5885, 5886, 5887, 5888, 5889, 5890, 5891, 5892, 5893, 5894, 5895, 5896], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 5}]}, {"dates": ["2023-11-17"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=22", "transcript_pages": [221, 222, 223, 224, 225, 226, 227, 228, 229], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162", "videos": [{"date": "2023-11-17", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC','2026-10-04T09:11:24Z');
INSERT INTO "fact" VALUES('summary:14-02:p3092978976','p3092978976','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T09:14:46Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3708, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=13"}, {"page": 3840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549ED46C20EB1D9919F46FCE732E5A27C94A6763E185232AA9CA852238F00A7C162#page=17"}, {"page": 3840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549ED46C20EB1D9919F46FCE732E5A27C94A6763E185232AA9CA852238F00A7C162#page=17"}], "councilor_points": ["秦議員慧珠指出，近期發生東湖國小合唱團站梯垮台致 10 位學生送醫、松山工農學生在網路及實體爭執後於教室噴灑滅火器致 19 位學生送醫，以及和平高中學生因偷拍案後續網路爭議而在網路發布恐嚇大屠殺言論等校園安全與網路脫序事件（引文：「東湖國小合唱團的站梯居然垮台了，東湖國小有 10 位同學受傷」、「最後這個同學拿起一個滅火器隨便噴灑，那個滅火器讓 19 個同學受到波及也受傷」、「和平高中居然有人恐嚇學校要大屠殺」）。秦議員慧珠建議，教育局應重新檢查各校相關設備，並檢討學生網路行為、情緒控管及匿名社群平台互動機制，將學生網路打工與當網紅等新形態行為納入了解與輔導（引文：「這個案子我請你們回去通令所有學校，是不是重新檢查一下相關的設備」、「是不是要注意這些網路的問題，還有這些學生情緒的控管」、「網路的問題學校可能要再去關注」）。"], "response": "教育局局長說明，會請各校重新檢查設備，並加強學生情緒教育與人際互動學習，同時整理了解學生網路行為（引文：「學校對孩子在網路上的行為，做一些必要的了解，對孩子的教育跟輔導也會有幫助，這個我們會來做一些整理」）。和平高中校長說明，學校第一時間即進行校安通報及召開性平會議移送地檢署，過程均遵守保密原則（引文：「我們都在規定的時間內，在我們第一天獲悉後就進行了校安通報，隔天我們召開了性平會議」）。警察局大安分局分局長建議，遇有校園犯罪問題應儘快檢舉事證向派出所報案（引文：「遇有犯罪的問題，希望能夠儘快檢舉相關的事證，向當地的派出所來報案」）。", "response_removed": false, "topic": "校園安全防護與學生網路脫序行為"}, {"citations": [{"page": 3706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=11"}, {"page": 3706, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=11"}, {"page": 3708, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=13"}, {"page": 3707, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=12"}], "councilor_points": ["秦議員慧珠指出，環南市場改建工程原編列 86 億元並經歷多次追加預算至 95.5 億元，但 9 層大樓中僅 1 樓及 2 樓部分區域共 1,095 個攤位做市場使用（占面積 24.2%），其餘空間多規劃為 3,218 個各類車位及辦公室，形容該案「主體從頭到尾就是停車場」（引文：「環南市場改建原先編列 86 億元...追加預算，合計共 95.5 億元」、「真正做市場的只有 1 層」、「所有的車輛停車位加起來高達 3，218個，攤位只有 1，095 個」、「主體從頭到尾就是停車場」）。秦議員慧珠建議，市府未來針對北投市場、西寧市場及東門市場等大型市場改建案，應重新檢討市場設計邏輯，亦可請停管處參建專業管理停車場，並依少子化與高齡化需求增加長照及托育等社福設施（引文：「我要和談的是市場設計的邏輯應該是如何，請你們注意一下」、「你應該請停管處來參建，停管處在這方面比你專業」、「我們需要更多的社福設施...更應該搭配停車場放在這棟大樓裡面」）。"], "response": "市場處處長說明，該預算是於二、三十年前編列，且汽車位 1,720 個及機車位 1,433 個主要是供給採買消費者與攤商使用（引文：「這筆預算是 88年下半年到 89 年，也就是大概在二、三十年前編列的」、「摩托車的停車位數量是 1，433 個，這部分可能比較是供給消費者去使用的」）。", "response_removed": false, "topic": "環南市場改建與停車場空間規劃"}, {"citations": [{"page": 5477, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E0E27CF232D36FAD334EE2E30B4B7D810739F3F5575E3ECAF0E233C4F8975A4602D1DE3DCEB210BC#page=4"}, {"page": 5477, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E0E27CF232D36FAD334EE2E30B4B7D810739F3F5575E3ECAF0E233C4F8975A4602D1DE3DCEB210BC#page=4"}, {"page": 5478, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E0E27CF232D36FAD334EE2E30B4B7D810739F3F5575E3ECAF0E233C4F8975A4602D1DE3DCEB210BC#page=5"}], "councilor_points": ["秦議員慧珠指出，捷運公司推出「早餐生活節 1.0」支出 145 萬元僅收入 41 萬元，「早餐生活節 2.0」雖然依車站熱門程度微調租金至 6,000 元以上，但因招商攤位減少且仍有 36 萬 490 元短差，整體活動截至當時仍處於虧損狀態（引文：「早餐生活節，它的立意很好，但在 1.0 時花了 145 萬元，卻只賺 41 萬元」、「2.0 時每一攤的租金都提高了...但是攤位變少了」、「收到 67萬 9,510 元，距離支出的 145 萬元還差了 36 萬 490 元」）。秦議員慧珠建議，捷運公司針對微型商場（如南京復興站租金收入 984 萬元，業者營業額 6,400 萬元）與商業空間應精算成本效益，適當提高租金或分潤比例，並針對 3.0 方案加強規範以增加業外收入（引文：「南京復興站 10 家店的營業額到 9 月分就有 6,400 萬元」、「明年的租金是不是應該再調高？」、「去算自己花了多少錢和能夠賺回多少錢，並且持續地改善」）。"], "response": "臺北大眾捷運股份有限公司總經理說明，早餐生活節活動係為服務旅客並測試接受度，經過調整租金後，第 2 期 3 個月增加一百九十幾萬元租金收入，加上第 1 個月收 45 萬元，預計年底前會有 95 萬元盈餘（引文：「當初這個活動是為了服務旅客，再來就是蒐集各站對這種服務的接受程度」、「我們實施第 2 期，3 個月也增加了一百九十幾萬的租金收入，加上第 1 個月收 45 萬元，年底前就有 95 萬元的盈餘」）。臺北大眾捷運股份有限公司總經理補充，微型商場租金約占業者營業額 10%至 15%，符合市場行情與廠商負擔能力，未來會持續優化商業模式並精進營運（引文：「租金佔整個營業額的 15%，也符合市場行情」、「平均都是 10 到 15%營業額的租金」、「我們會持續精進」）。", "response_removed": false, "topic": "捷運公司早餐生活節與微型商場經營收益"}, {"citations": [{"page": 649, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665491B30518CFD9CFC28C3CBA84EBC5E1DF27BA2B21E128A5B4CA852238F00A7C162#page=15"}, {"page": 649, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665491B30518CFD9CFC28C3CBA84EBC5E1DF27BA2B21E128A5B4CA852238F00A7C162#page=15"}], "councilor_points": ["秦議員慧珠指出，大巨蛋開幕後賽事與演唱會將衍生黃牛票問題，過去市府查緝績效偏低，而亞洲棒球錦標賽期間警察局單日即查獲 83 件 84 人、最高售價 5,000 元，且文化局受理中央移交 540 件黃牛檢舉案僅裁罰 5 件（占 9%），警察局網路巡查負擔過重（引文：「將來大巨蛋開幕以後，黃牛票的問題如影隨形」、「文化局回復經過中央轉給文化局的黃牛案件有 540 件...才罰了 5 件」、「才罰了 9%」）。秦議員慧珠建議，市府應建立自治法規或規範要點，規定租用北市場館售票一律採「實名制」、限制購票張數，並對販售或購買黃牛票者裁處 1 至 2 年或 3 個月內禁止於北市場館購票之處分（引文：「如果市府要訂定自治法規...要點裡面可以列幾個項目，第 1 個，將來臺北市任何單位主管的場館要售票，一定要實名制」、「只要在臺北市的場館被查到有賣黃牛票的事實...就禁止他 1 年或 2 年在臺北市買票」、「如果買黃牛票被查到，3 個月內也不准在臺北市買票」）。"], "response": "市長表示，會請法務局邀集相關局處從法制面研議議員提出的實名制等建議，並進行整體考量（引文：「我會請法務局邀集相關局處，從法制面好好研議議員的建議，包括剛剛議員所說的實名制等」）。文化局局長說明，中央移交的五百多件案件中有四百多件因無黃牛事實而結案，文化局亦缺乏警察向銀行調閱個人資料之權限，需要警察局合作協助（引文：「五百多件案件中有將近四百多件結案了，也就是沒有黃牛的事實」、「文化局沒有警察的權力，比如：文化局沒有辦法向銀行調個人資料」）。", "response_removed": false, "topic": "大巨蛋與市府場館黃牛票查緝管理"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 16, "heading": "市政總質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665491B30518CFD9CFC28C3CBA84EBC5E1DF27BA2B21E128A5B4CA852238F00A7C162#page=12", "transcript_pages": [646, 647, 648, 649, 650, 651, 652, 653, 654, 655], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665491B30518CFD9CFC28C3CBA84EBC5E1DF27BA2B21E128A5B4CA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 16}]}, {"dates": ["2023-10-26"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E0E27CF232D36FAD334EE2E30B4B7D810739F3F5575E3ECAF0E233C4F8975A4602D1DE3DCEB210BC#page=1", "transcript_pages": [5474, 5475, 5476, 5477, 5478], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549E0E27CF232D36FAD334EE2E30B4B7D810739F3F5575E3ECAF0E233C4F8975A4602D1DE3DCEB210BC", "videos": [{"date": "2023-10-26", "group": 2}]}, {"dates": ["2023-11-07"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654937FCD5054664784ECC78C52ACF512780A0339BF6398ED2F9A852238F00A7C162#page=6", "transcript_pages": [1451, 1452, 1453, 1454, 1455, 1456, 1457], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB9637356654937FCD5054664784ECC78C52ACF512780A0339BF6398ED2F9A852238F00A7C162", "videos": [{"date": "2023-11-07", "group": 15}]}, {"dates": ["2023-10-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 18, "heading": "財政建設部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A7C162#page=8", "transcript_pages": [3703, 3704, 3705, 3706, 3707, 3708], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB9637356654922B332F8DFD755403A7BBAF09BE62D9427C07B51B2D8FEC6A852238F00A