INSERT INTO "fact" VALUES('summary:14-02:pf84e91ca73','pf84e91ca73','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-04T09:16:44Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 302, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=14"}, {"page": 303, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=15"}, {"page": 303, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=15"}, {"page": 305, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=17"}, {"page": 308, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=20"}, {"page": 309, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=21"}, {"page": 311, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=23"}, {"page": 312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=24"}, {"page": 302, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=14"}, {"page": 309, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=21"}], "councilor_points": ["簡舒培議員指出針對前任市府留下的爭議案件，包含臺北表演藝術中心「2.36 億元」工程爭議款、臺北流行音樂中心「1.9 億元」賠償款及「10 筆」合約訴訟案等「爛帳」，要求市府釐清責任並進行調查。簡舒培議員表示八大基金被當成「小金庫」，透過解繳市庫「180.7 億元」、減少撥補及虧空等方式挪移「273.5 億元」，其中地方教育發展基金「8 年」虧空「70.7 億元」，導致「862 棟」校舍壁癌無法處理。簡舒培議員要求市長將相關案件移送廉政透明委員會，並於「2 個月」內完成調查且公開所有資料。"], "response": "市長回應表示「該公開就要公開」，合約規定在「64 億元」範圍內服務費不該再追加，關於各項爭議款與訴訟案會逐項釐清瞭解。市長說明前任市府沒有適時撥補地方教育發展基金，導致接手後必須撥款「40 億元」補上，並表示給市府「2 個月」的時間把相關案子釐清後向議員報告。", "response_removed": false, "topic": "前市府市政爭議案件與基金運用調查"}, {"citations": [{"page": 1470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=8"}, {"page": 1471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=9"}, {"page": 1474, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=12"}, {"page": 1472, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=10"}, {"page": 1472, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=10"}, {"page": 1473, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=11"}], "councilor_points": ["簡舒培議員指出大巨蛋在國父紀念館側規劃「80 公尺」地下通廊，但在「3 本」環評書皆記載通往國父紀念館「80 公尺」通廊的情況下，實際開闢僅「18 公尺」，詢問是否違反環境影響評估法。簡舒培議員要求環保局應依環境影響評估法第「23」條對開發單位開罰「30 萬元到 150 萬元」，並要求體育局送環境影響差異分析報告，且在環差通過前應要求大巨蛋停止使用。"], "response": "環保局局長說明大巨蛋過忠孝東路到國父紀念館前面有「80 公尺」空間，但通道為「20 公尺」，並表示「80 公尺」地下通廊屬於市府應辦事項，初步評估開發行為施工不包括在內。環保局局長表示會依據質詢資料進行檢討與評估，若確認違反環境影響評估法會依法處理。", "response_removed": false, "topic": "大巨蛋地下通廊開闢與環評爭議"}, {"citations": [{"page": 6095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=2"}, {"page": 6095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=2"}, {"page": 6097, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=4"}, {"page": 6098, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=5"}, {"page": 6099, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=6"}, {"page": 6100, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=7"}, {"page": 6101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=8"}], "councilor_points": ["簡舒培議員指出大巨蛋於「11 月 18 日」預備賽將引入「13,000 人」，但市府對於忠孝東路「80 米」地下通廊是否開放出現說法不一的情形，質疑內部溝通與資訊掌握狀況。簡舒培議員指出淨寬「18 米 8」的通廊經評估每分鐘僅能供「633 人」通行，且樓梯側夜間僅有「2 米 5」供行人使用，要求市府評估疏散人數並於「2 個月」內邀請身障人士進行現場體驗。"], "response": "臺北文化體育園區籌備處副執行長說明預備賽引入「13,000 人」，經開會檢討後最後定案決定開放地下通廊。新建工程處處長說明通廊淨寬「18 米 8」經評估可供每小時「3 萬 8 千人」通行，兩側疏散加起來約「3 萬 4 千人」，建築管理工程處處長表示同意在「2 個月」內再找身障人士勘查大巨蛋。", "response_removed": false, "topic": "大巨蛋測試賽地下通廊開放與疏散規劃"}, {"citations": [{"page": 4105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=13"}, {"page": 4109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=17"}, {"page": 4110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=18"}, {"page": 4111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=19"}, {"page": 4112, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=20"}, {"page": 4113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=21"}, {"page": 4114, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=22"}, {"page": 4114, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=22"}], "councilor_points": ["簡舒培議員指出大巨蛋使用執照已簽報核准，詢問若實地壓力測試無法達到「8 分鐘」內離開觀眾席、「15 分鐘」內完成全館避難之安全原則時應如何處置。簡舒培議員表示大巨蛋位於地面以下「7 公尺」，無法符合「建築技術規則」第「127」條規定，要求市府說明由第三方專業機構進行防火逃生避難安全審查的具體標準與流程。"], "response": "體育局局長說明若測試未達成要求會進行原因評估與檢討，並表示舉辦大型活動皆會依照「臺北市大型群聚活動安全管理自治條例」進行審查。建築管理工程處副總工程司說明大巨蛋若無法符合「建築技術規則」第「127」條，須經第三方公正單位審查防火逃生避難安全，市府會先訂出規定。", "response_removed": false, "topic": "大巨蛋使用執照核發與演唱會審查規範"}, {"citations": [{"page": 4101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=9"}, {"page": 4102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=10"}, {"page": 4103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=11"}, {"page": 4104, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=12"}, {"page": 4102, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=10"}, {"page": 4105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=13"}], "councilor_points": ["簡舒培議員指出文化部自「6 月」設立檢舉黃牛專區後移交案件，文化局收到「511 件」檢舉、成案「80 件」，但開罰件數為「0 件」，要求提升查處效率。簡舒培議員建議成立府級小組訂定跨局處調查標準作業流程，並要求文化局比照文化部提出補助，鼓勵演唱會業者採用實名制售票以補貼行政成本。"], "response": "文化局局長說明目前收到案件正進行查核，並有請警察局協助，承諾會將具體案例提供給警察局協助調查。文化局局長表示同意一週內拜訪文化部釐清疑義、安排至高雄市考察，並於「1 個月」內提供鼓勵實名制售票的研擬方式，第「3」點成立府級小組會呈報府級長官。", "response_removed": false, "topic": "演唱會黃牛查處與實名制推動"}, {"citations": [{"page": 5757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=6"}, {"page": 5757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=6"}, {"page": 5758, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=7"}, {"page": 5760, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=9"}, {"page": 5759, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=8"}], "councilor_points": ["簡舒培議員指出北市停車位短缺約「14 萬位」，但前任市府「8 年」期間將停管基金繳庫「87.7 億元」，為前前任市府「28.5 億元」的「3 倍」，質疑基金過度繳庫未積極興建停車場。簡舒培議員指出「2021 年」與「2022 年」市府汽車停車供需調查竟顯示各行政區皆可滿足需求，要求停管基金應回歸落實增加停車位供給的目標，並於「2 個星期」內提供明年繳庫規劃報告。"], "response": "交通局局長與停車管理工程處處長說明停車位仍不夠，目前有「12 個」停車場在興建中，基金收入主要用於停車環境改善與場館興建，盈餘依規定統籌分配繳庫。交通局局長與停車管理工程處處長表示會再檢討縮小供需調查的分區，並同意在「2 個星期」內向議員提出合理的說明報告。", "response_removed": false, "topic": "停車場特別基金盈餘繳庫與停車位改善"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-28"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=12", "transcript_pages": [300, 301, 302, 303, 304, 305, 306, 307, 308, 309, 310, 311, 312, 316, 317, 318, 319, 320], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC", "videos": [{"date": "2023-11-28", "group": 9}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=1", "transcript_pages": [5752, 5753, 5754, 5755, 5756, 5757, 5758, 5759, 5760], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 15}]}, {"dates": ["2023-11-07"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 16, "heading": "警政衛生部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=7", "transcript_pages": [1469, 1470, 1471, 1472, 1473, 1474, 1475, 1476, 1477, 1478], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162", "videos": [{"date": "2023-11-07", "group": 16}]}, {"dates": ["2023-10-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 11, "heading": "財政建設部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162#page=8", "transcript_pages": [3538, 3539, 3540, 3541, 3542, 3543, 3544, 3545], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162", "videos": [{"date": "2023-10-16", "group": 11}]}, {"dates": ["2023-10-24"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=8", "transcript_pages": [4100, 4101, 4102, 4103, 4104, 4105, 4109, 4110, 4111, 4112, 4113, 4114, 4115], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162", "videos": [{"date": "2023-10-24", "group": 15}]}, {"dates": ["2023-11-14"], "dept": "工務", "doc_type": "部門質詢", "group": 18, "heading": "工務部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=1", "transcript_pages": [6094, 6095, 6096, 6097, 6098, 6099, 6100, 6101], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162", "videos": [{"date": "2023-11-14", "group": 18}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 17, "heading": "民政部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=8", "transcript_pages": [397, 398, 399, 400, 401, 402, 403], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 17}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC','2026-10-04T09:16:44Z');
INSERT INTO "fact" VALUES('summary:14-02:pb8d278f1da','pb8d278f1da','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T05:55:30Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1269, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549E85CA3C45ABFB92F07606F07373E376C5837D9859F86AC59A852238F00A7C162#page=16"}, {"page": 1269, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549E85CA3C45ABFB92F07606F07373E376C5837D9859F86AC59A852238F00A7C162#page=16"}], "councilor_points": ["耿葳議員指出民眾陳情市立聯合醫院附設長照機構與護理之家的網路預約登記缺乏透明機制，出現較晚申請者優先收治入住，而較早申請且狀態標示為「進行中」或「住院中」者卻持續等待的情況。耿葳議員要求衛生局與市立聯合醫院檢討入住評核程序與審核標準，並以白紙黑字及醫療數據標準公開透明訂定優先順序。"], "response": "衛生局局長說明入住標準設有評核程序並分為三大類，承諾會檢討評核程序執行面不清楚之處，並由市立聯合醫院研議改善。市立聯合醫院護理部主任說明醫師會根據病患疾病狀況判定是否有立即入住需求，並表示會進行內部檢討與明確提示註記。", "response_removed": false, "topic": "市立聯合醫院長照機構入住預約審核機制"}, {"citations": [{"page": 4088, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491974E39F941C0D4FFC4DBF95AF520F57CBB837F03FAC9B51A852238F00A7C162#page=13"}, {"page": 4089, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491974E39F941C0D4FFC4DBF95AF520F57CBB837F03FAC9B51A852238F00A7C162#page=14"}], "councilor_points": ["耿葳議員詢問臺北大巨蛋預計於11月舉辦的閉門測試賽與開放觀眾入場測試賽是由何單位主辦，並指出大巨蛋作為BOT案，遠雄應承擔營運前領照與測試責任。耿葳議員要求市府應堅守監督審核角色，釐清測試賽經費來源，不得作為遠雄的次級單位。"], "response": "體育局局長說明11月中旬的2場測試賽皆由遠雄主辦且費用由遠雄自行負擔，市府未代辦亦未支付或收受經費，並承諾會對未來整體規劃進行完整說明。臺北文化體育園區籌備處副執行長表示暖身賽與測試賽係由遠雄及棒球協會主導舉辦。", "response_removed": false, "topic": "臺北大巨蛋測試賽辦理與監督"}, {"citations": [{"page": 417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=9"}, {"page": 418, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=10"}, {"page": 420, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=12"}, {"page": 420, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=12"}], "councilor_points": ["耿葳議員指出市立聯合醫院在市政會議後直接對外發布法人化議題與高達147億元的改建計畫，詢問相關程序與經費來源。耿葳議員建議市府應詳細評估公立醫院法人化利弊得失，重大政策應由府級發言人或局處正式發布。"], "response": "市長說明市政會議僅針對相關議題進行公開討論與初步研議，並承諾未來重大決定將由府級發言人陪同相關局處對外正式說明。衛生局局長表示法人化與改建計畫金額係初步研議及各院區推估階段，尚未確定具體財源與方向。", "response_removed": false, "topic": "市立聯合醫院法人化評估與改建計畫發布程序"}, {"citations": [{"page": 6077, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549001553CF0749DD7C9525AF269582D7CD113B82451D5C4420A852238F00A7C162#page=17"}, {"page": 6078, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549001553CF0749DD7C9525AF269582D7CD113B82451D5C4420A852238F00A7C162#page=18"}, {"page": 424, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=16"}, {"page": 425, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=17"}, {"page": 6078, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549001553CF0749DD7C9525AF269582D7CD113B82451D5C4420A852238F00A7C162#page=18"}], "councilor_points": ["耿葳議員指出臺北市道路於銑鋪後仍頻繁開挖，自治條例禁止開挖規定因例外條款而形同虛設，且現行每日200元之施工規費過低無法抑止隨意開挖。耿葳議員建議市府檢討道路開挖罰則，並研議於銑鋪後重新施工時依比例與時間加徵補償費。"], "response": "市長表示會進行檢討與研議。工務局局長說明將檢討相關機制，並研議如何讓管線單位預先規劃及提高收取費用以抑止隨意開挖。", "response_removed": false, "topic": "市區道路重複開挖管制與規費機制"}, {"citations": [{"page": 420, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=12"}, {"page": 422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=14"}, {"page": 423, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=15"}, {"page": 423, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=15"}], "councilor_points": ["耿葳議員指出仙跡岩步道、貓空周邊及文山森林公園遭小花蔓澤蘭與紅樓花等外來植物大規模入侵，危害本土生態。耿葳議員反映林務局設於潮州街之收購點地點遠且開放時間不便，要求市府跨局處合作進行源頭防治與根除計畫。"], "response": "市長表示將請大地工程處與公園路燈工程管理處研議，除緊急處理外亦著手進行事前預防工作。工務局局長說明公園處發現公有土地外來種會立即處理，仙跡岩步道兩側會先行清理並向私人土地所有權人宣導，並將與林業署溝通增加收購時間便利性。", "response_removed": false, "topic": "外來植物侵襲與清除防治"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-28", "2023-11-30"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162#page=1", "transcript_pages": [409, 410, 411, 412, 413, 414, 415, 416, 417, 418, 419, 420, 421, 422, 423, 424, 425], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162", "videos": [{"date": "2023-11-28", "group": 10}, {"date": "2023-11-30", "group": 10}]}, {"dates": ["2023-10-26"], "dept": "交通", "doc_type": "部門質詢", "group": 12, "heading": "交通部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496F3245F8E7D2564663A340E0C238AC3B36646288D65263FB48F2080BDC9615A802D1DE3DCEB210BC#page=1", "transcript_pages": [5696, 5697, 5698, 5699, 5700, 5701, 5702], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496F3245F8E7D2564663A340E0C238AC3B36646288D65263FB48F2080BDC9615A802D1DE3DCEB210BC", "videos": [{"date": "2023-10-30", "group": 12}]}, {"dates": ["2023-11-03"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549E85CA3C45ABFB92F07606F07373E376C5837D9859F86AC59A852238F00A7C162#page=9", "transcript_pages": [1262, 1263, 1264, 1265, 1266, 1267, 1268, 1269, 1270, 1271], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549E85CA3C45ABFB92F07606F07373E376C5837D9859F86AC59A852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 6}]}, {"dates": ["2023-10-13"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665496CCBD65B90AA8F35DDBAB098C8228A7577148AF56CAEC8A2A852238F00A7C162#page=6", "transcript_pages": [3484, 3485, 3486, 3487, 3488, 3489, 3490, 3491, 3492], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665496CCBD65B90AA8F35DDBAB098C8228A7577148AF56CAEC8A2A852238F00A7C162", "videos": [{"date": "2023-10-13", "group": 8}]}, {"dates": ["2023-10-23"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491974E39F941C0D4FFC4DBF95AF520F57CBB837F03FAC9B51A852238F00A7C162#page=12", "transcript_pages": [4087, 4088, 4089, 4090, 4091, 4092], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665491974E39F941C0D4FFC4DBF95AF520F57CBB837F03FAC9B51A852238F00A7C162", "videos": [{"date": "2023-10-23", "group": 14}]}, {"dates": ["2023-11-14"], "dept": "工務", "doc_type": "部門質詢", "group": 16, "heading": "工務部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549001553CF0749DD7C9525AF269582D7CD113B82451D5C4420A852238F00A7C162#page=12", "transcript_pages": [6072, 6073, 6074, 6075, 6076, 6077, 6078, 6079], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB96373566549001553CF0749DD7C9525AF269582D7CD113B82451D5C4420A852238F00A7C162", "videos": [{"date": "2023-11-14", "group": 16}]}, {"dates": ["2023-11-16"], "dept": "民政", "doc_type": "部門質詢", "group": 3, "heading": "民政部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665498A52FA4BDB5A261B494A067263F26EE87E35B6F92D897E20A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB963735665498A52FA4BDB5A261B494A067263F26EE87E35B6F92D897E20A852238F00A7C162", "videos": [{"date": "2023-11-16", "group": 3}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549463297D58AF60EAF24066F4C5A582A2528D80D404F5CD0ECA852238F00A7C162','2026-10-05T05:55:30Z');
INSERT INTO "fact" VALUES('summary:14-02:p8ff8ce5488','p8ff8ce5488','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T05:57:33Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4121, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=2"}, {"page": 4123, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=4"}, {"page": 4124, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=5"}, {"page": 4126, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=7"}, {"page": 4122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=3"}], "councilor_points": ["苗博雅議員詢問大巨蛋使用執照之註記內容，指出依據《建築技術規則建築設計施工編》第127條進行個案檢討時應制定標準作業程序（「大巨蛋建築技術規則施工編第127 條，個案檢討的部分，你們到底有沒有 SOP？」）。苗博雅議員表示體育場館若多數時間非進行體育活動，恐不符合體育場館用途，要求市府進行檢討與管理（「體育場館如果多數時間不是做為體育活動使用，還算體育場館嗎？」）。苗博雅議員指出大巨蛋北側6米通道在消防車輛抵達時不作為避難疏散使用，要求市府了解安全避難審查之附帶條件並落實動線規劃（「北側 6 米通道在消防車輛抵達時，不作為避難疏散使用，這是當初都審通過疏散避難時候，消防局的要求」）。"], "response": "體育局局長說明，註記內容為須檢討符合《建築技術規則建築設計施工編》第127條規定或經專業機構驗證安全才可以使用，非體育使用須依內政部函釋辦理，並表示會在3個月內研議相關SOP（「給我們 3 個月時間」、「特別針對演唱會等非體育使用」）。體育局局長表示未來使用要求一定以體育賽事為主，若非體育活動日數太少會進行檢討，並承諾針對北側6米通道做動線規劃（「我們未來在使用要求上一定要以體育賽事為主」、「我們會就這個部分做個規劃」）。", "response_removed": false, "topic": "大巨蛋使用執照註記與安全避難機制"}, {"citations": [{"page": 416, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=4"}, {"page": 418, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=6"}, {"page": 417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=5"}], "councilor_points": ["苗博雅議員指出第一殯儀館拆除與第二殯儀館試營運連動計畫之時間軸不明確，要求市府提出清楚明確的規劃與時間表（「關於一殯和二殯的時程，必須要有一個清楚明確的規劃」）。苗博雅議員表示第二殯儀館禮廳數從11間增至28間、冷藏櫃增加588屜後對周邊衝擊加大，要求市府於修正回饋金計算方式前應廣納大安區與文山區里長意見（「原本有 11 間禮廳，現在一口氣增加了 17 間，變成 28 間禮廳」、「務必先廣納大安區和文山區里長的意見」）。"], "response": "殯葬管理處處長說明，第二殯儀館新大樓規劃於12月中開始試營運，並希望第一殯儀館服務能在明年2月春節時告一段落（「二殯的新大樓目前規劃是在 12 月中會開始試營運」、「希望一殯的服務，可以在明年 2 月春節的時候告一個段落」）。民政局局長表示，未來會保障大安區原有居民權益，研議調整同心圓半徑等計算公式，並承諾提出計算公式前會廣納大安區與文山區里長意見（「勢必要提出計算公式送議會審議」）。", "response_removed": false, "topic": "第二殯儀館試營運與回饋金機制"}, {"citations": [{"page": 172, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=19"}, {"page": 176, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=23"}, {"page": 175, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=22"}], "councilor_points": ["苗博雅議員舉2019年曙光祭活動為例，指出過去有市長室機要於上班時間幫廠商處理場地與協調贊助等情事，要求市府建立防弊機制（「針對未來市政府和各機關學校，和民間合辦活動相關拉贊助的限制和規範，還有事後如何檢核和把關的機制為何？」）。苗博雅議員建議市府於1個月內研商合辦活動拉贊助之限制規範與把關機制，並於2個月內檢視過去與民間廠商合辦活動有無為特定廠商找錢之情形（「可不可在 1 個月之內商討完後提出？」、「2 個月好不好？……過去和民間廠商合辦活動，有沒有類似這種量身訂作、為特定廠商找錢的事？」）。"], "response": "市長表示團隊絕對不允許此類行為，並答應請法務局於1個月內研究擬訂防弊機制，且同意於2個月內回頭了解過去市府與民間廠商合辦活動之相關情況（「我請法務局來研究，我們來擬訂 1 個防弊機制」、「可以，我們去了解」）。文化局局長說明，現行團隊不會出現為特定廠商開辦活動之狀況，若廠商爭取贊助會在預算範圍之外讓活動更好（「蔣市府團隊不會出現這樣的狀況」、「他為了要讓活動辦得更多、更好，他會爭取一些廠商贊助」）。", "response_removed": false, "topic": "市府與民間廠商合辦活動防弊機制"}, {"citations": [{"page": 3693, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=13"}, {"page": 3694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=14"}, {"page": 3694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=14"}, {"page": 3692, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=12"}, {"page": 3692, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=12"}], "councilor_points": ["苗博雅議員詢問臺北農產運銷股份有限公司職場性騷擾事件之專案調查結果，要求市府與該公司說明調查結果為成立或不成立（「到底有沒有發生性騷擾？」、「到底是成立性騷擾還是不成立」）。苗博雅議員指出該公司態度遮遮掩掩，未能依據相關法規將調查結果告知作為監督機關之議會與社會大眾（「我們不能接受的是北農這樣遮遮掩掩的態度」、「完全不告知議會」）。"], "response": "臺北農產運銷股份有限公司董事長說明，公司委託律師事務所進行專案調查，相關事件確實有發生，且調查報告經雙方認可，但因當事人未做性平申訴及相關要求，無法簡單回答成立或不成立（「這個事件在我們得知之後，我們按照程序並請律師事務所來做專案調查的這個事情是有的」、「這個調查報告經過兩造當事人的同意並在律師的見證下已經有一個他們認可的結論，但是，不是像您說的能簡單回答出是性騷擾或不是性騷擾」）。臺北農產運銷股份有限公司總經理表示，今年並無此類事件，公司均根據相關法規進行程序處理（「今年並沒有這樣的事件」、「我們是根據相關的法規做程序的處理」）。", "response_removed": false, "topic": "臺北農產運銷公司職場性騷擾事件調查與處置"}, {"citations": [{"page": 1272, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=1"}, {"page": 1274, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=3"}, {"page": 1274, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=3"}, {"page": 1275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=4"}, {"page": 1275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=4"}, {"page": 1276, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=5"}], "councilor_points": ["苗博雅議員指出臺北市每日產生約150公噸廚餘且每年編列1,600萬至1,700萬元處理費用，詢問生質能源廚餘廠之規劃進度（「現在臺北市 1 天會產生多少的廚餘？」、「每一年都要編列 1,600 萬元至 1,700 萬元左右，處理這些有機廢棄物」）。苗博雅議員指出過往推動生質能源廠評估花費1,446萬元卻無下文，要求市府提出具體計畫與期程，透過轉廢為能妥善處理廚餘（「臺北市政府已經花了 1,446 萬元做生質能源廠的評估工作」、「本席希望能看到具體的計畫」）。"], "response": "環境保護局局長說明，臺北市每日約產生150公噸廚餘，生質能源為未來轉型與再生能源之重要方案（「大概 150 公噸左右」、「而且這是再生能源」）。環境保護局局長表示，環保局已於淨零轉型路徑中提出規劃並編列預算，將結合內湖焚化爐轉型為綠能園區執行，並承諾朝此目標前進（「環境保護局在淨零轉型、淨零排放路徑時就已提出，而且編列預算從明年開始執行」、「因為內湖焚化爐要做轉型為綠能園區」、「環境保護局會往這個目標前進」）。", "response_removed": false, "topic": "臺北市廚餘處理與生質能源廠規劃"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-24"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC#page=14", "transcript_pages": [167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC", "videos": [{"date": "2023-11-24", "group": 4}]}, {"dates": ["2023-10-27"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC#page=7", "transcript_pages": [5590, 5591, 5592, 5593, 5594], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB9637356654987E5663A927295C5E1C77FB4F9652329789BF1D21086A353070AE82CD888B97202D1DE3DCEB210BC", "videos": [{"date": "2023-10-27", "group": 7}]}, {"dates": ["2023-11-02"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 7, "heading": "警政衛生部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162#page=1", "transcript_pages": [1272, 1273, 1274, 1275, 1276, 1277, 1278, 1279], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499C35D5D7B0D34564BADA431966188C1D2D4DB3ED1C0DDFE2A852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 7}]}, {"dates": ["2023-10-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162#page=10", "transcript_pages": [3690, 3691, 3692, 3693, 3694, 3695], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549B7C099ECAA301423DDBAB098C8228A75473409F5F0E08942A852238F00A7C162", "videos": [{"date": "2023-10-17", "group": 17}]}, {"dates": ["2023-10-24"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162#page=1", "transcript_pages": [4120, 4121, 4122, 4123, 4124, 4125, 4126, 4127, 4128, 4129], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549330337F364615B59820CDCA51716BAED647743E5E7203031A852238F00A7C162", "videos": [{"date": "2023-10-24", "group": 16}]}, {"dates": ["2023-11-10"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162#page=6", "transcript_pages": [5946, 5947, 5948, 5949, 5950, 5951], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665499DE5CF75F6B8543055F95AA25A853FC95ABF04D9BD175FF1A852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 8}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 18, "heading": "民政部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162#page=1", "transcript_pages": [413, 414, 415, 416, 417, 418, 419, 420, 421, 422], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB9637356654984515BEBAEF25037E1D42ECDB0049E5532020AF8877B5A83A852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 18}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665493A3B00CE5B16557CF2BCF583BB9F4863F4D8F48FF3DB9968BA21D57F157168FD02D1DE3DCEB210BC','2026-10-05T05:57:33Z');
INSERT INTO "fact" VALUES('summary:14-02:p4cf586308f','p4cf586308f','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:00:58Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 688, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=22"}, {"page": 3900, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=2"}, {"page": 3903, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=5"}, {"page": 689, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=23"}, {"page": 3900, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=2"}, {"page": 3903, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=5"}], "councilor_points": ["詹為元議員詢問「大巨蛋現在可不可以辦演唱會」，並建議市府針對「中華職棒」開幕戰「相關的租金趕快跟遠雄協調」。詹為元議員指出壓力測試若僅以「1萬人」為主恐強度不足，要求市府針對未來首次開放「2萬人」與「4萬人」等大型活動時「要有類似壓力測試這樣子的公告」讓民眾了解風險。"], "response": "體育局局長說明體育賽事以外屬於「臨時性的活動」，會在「亞錦賽之後」開會討論標準，且市長表示已請遠雄「在月底提方案出來」送到市府。體育局局長表示大巨蛋開放原則為「由少而多、逐次遞增」，並承諾會要求遠雄在對外公告中告知民眾「可能會產生的風險」。", "response_removed": false, "topic": "臺北大巨蛋營運規劃與壓力測試"}, {"citations": [{"page": 41, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=2"}, {"page": 42, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=3"}, {"page": 43, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=4"}, {"page": 44, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=5"}, {"page": 46, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=7"}, {"page": 47, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=8"}, {"page": 47, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=8"}], "councilor_points": ["詹為元議員指出信義區與松山區共「74個里」中有「21個里沒有關懷據點」，詢問市府設置之目標與KPI。詹為元議員表示據點之「業務費」應考慮調整，並反映臨時更換教師或課程易遭扣分之問題。詹為元議員建議重新研議加分事項，避免里辦公室因制度限制「在加分的事項上就是不平等的」。"], "response": "社會局局長說明目前「第一優先是希望未來能讓每個里都有 1 個關懷據點」，若課程更換有「事先報准」或正當理由就不會扣分。社會局局長與社會局老人福利科科長表示里辦公室可透過電子公文等項目加分，並承諾會就「加分及扣分條件」之差異進行修正。", "response_removed": false, "topic": "社區照顧關懷據點設置與考核機制"}, {"citations": [{"page": 1401, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=20"}, {"page": 1402, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=21"}, {"page": 1403, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=22"}, {"page": 1404, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=23"}, {"page": 1405, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=24"}, {"page": 1402, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=21"}, {"page": 1407, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162#page=26"}], "councilor_points": ["詹為元議員指出市府於「109年」已知中央將減少補助，自籌經費卻「逐年編高」，停辦前夕缺乏溝通致使里長不滿。詹為元議員表示「資收關懷計畫」受限於「6,000元」補助上限及部分物品關懷價低於市價，導致「參加該計畫只有 26 人至 41 人」。詹為元議員詢問如何補足資收大軍停辦後「將近 2,000 公噸」的回收量能。"], "response": "環境保護局資源循環管理科科長說明市府係「配合中央」政策停辦資收大軍，轉型辦理資收關懷計畫，且關懷價格係「由環境部說明」之原則訂定。環境保護局局長表示每年會提撥資源回收變賣收入「3 成左右」給各里，並將回收力量轉至「低碳永續家園計畫」評選績優給予獎勵。", "response_removed": false, "topic": "資源回收政策與資收大軍停辦因應"}, {"citations": [{"page": 692, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=26"}, {"page": 693, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=27"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=28"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=28"}, {"page": 695, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=29"}], "councilor_points": ["詹為元議員指出第一殯儀館預定地之說明會「只有 5 人」當地里民反對即否決提案，顯示說明會宣傳不力且缺乏代表性。詹為元議員建議修改SOP提高里民參與率，並統整公有場地以推動「公私協力」廣設狗活動區。詹為元議員建議市府根據犬隻數量訂定增設目標與「KPI」，例如以每「4,000 至 5,000 隻」設置 1 個活動區為目標。"], "response": "市長表示同意「加強說明會邀請更多的里民能夠參與加入討論」，並會請動保單位規劃增設之KPI與加強地方溝通。動物保護處處長表示會統整公有場域做為「寵物友善的空間或是狗活動區」，並參考國內外資訊研議依隻數訂定設立狗公園之標準。", "response_removed": false, "topic": "寵物公園與狗活動區設置機制"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=19", "transcript_pages": [685, 686, 687, 688, 689, 690, 691, 692, 693, 694, 695, 696, 697, 698, 699, 700], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 17}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=23", "transcript_pages": [5806, 5807, 5808, 5809, 5810, 5811, 5812], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 17}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.t