url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 7}]}, {"dates": ["2023-11-16"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=1", "transcript_pages": [40, 41, 42, 43, 44, 45, 46, 47, 48, 56, 57, 58], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162", "videos": [{"date": "2023-11-16", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162','2026-10-05T06:00:58Z');
INSERT INTO "fact" VALUES('summary:14-02:p06dbec1b42','p06dbec1b42','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:02:50Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1210, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=13"}, {"page": 1212, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=15"}, {"page": 1213, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=16"}, {"page": 1214, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=17"}, {"page": 1214, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=17"}, {"page": 1216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=19"}, {"page": 1208, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=11"}, {"page": 1215, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=18"}, {"page": 1216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=19"}, {"page": 1217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665498443B2EF35AF7D4615499A937BE8597F29E193AEF745E6DDA852238F00A7C162#page=20"}], "councilor_points": ["郭昭巖議員指出《臺北市淨零碳排管理自治條例》「函報行政院」後「遲遲沒有核定」，建議市府透過民間團體向候選人宣導以督促中央溝通。郭昭巖議員反映中央停辦「資收大軍」計畫影響地方回收，並建議研議校園「循環杯」推廣、學校設置「太陽光電」與「雨撲滿」、擴大「透水性人行道鋪面」及增加區里低碳推廣補助。郭昭巖議員指出現行低收入戶更換一級能效電冰箱補助申請率僅「3.32%」，要求檢討宣導方式與「多元」補助項目。"], "response": "環保局局長說明《氣候變遷因應法》公布後中央有審查意見需修正，市府「自己編列預算來推動」政府部門減碳，並表示會加強資源回收宣導、評估學校設置循環杯意願，以及考量增加區里低碳推廣補助與深入宣導家電補助。教育局科長說明已陸續在「148校」設置太陽光電，並每年編列「雨撲滿」預算。水利工程處科長表示會與市場處討論「太陽光電」設置可行性。公園路燈工程管理處主任秘書表示青年公園整建與艋舺公園改建將納入雨撲滿規劃。新建工程處科長表示每年更新約「15所」學校周邊人行道並鋪設透水鋪面。", "response_removed": false, "topic": "溫室氣體減量與淨零碳排政策推動"}, {"citations": [{"page": 5786, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=5"}, {"page": 5786, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=5"}, {"page": 5788, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=7"}, {"page": 5789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=8"}, {"page": 5790, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=9"}, {"page": 5782, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=1"}, {"page": 5784, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665494D7A5BFDCDAE88110FC6B0F52727A1827578A7E841996F11A852238F00A7C162#page=3"}], "councilor_points": ["郭昭巖議員詢問嘉禾新村公辦都更中軍方、臺大及農委會等公有土地權責單位的溝通進度，建議結合立法委員與私地主力量主動出擊。郭昭巖議員關切水源二、三期變更期程、南機場各單元推動進度與中繼宅安置，並要求檢討西園整宅說明會通知與簽到方式。郭昭巖議員建議「臺北市土地使用分區管制自治條例第80之2條」修法應扣除自辦都更，避免爭議以順利推動公辦都更。"], "response": "都市更新處處長說明嘉禾新村公有土地權責單位尚無善意回應，將持續協商並處理違占戶，水源二、三期會與相關單位協調，南機場單元三預計「12月要公告招商」，中央住都中心規劃興辦社宅作為中繼，預計明年第一季提報董事會，西園整宅將配合改為假日辦理說明會並採門牌分區簽到。都市發展局局長表示會密集協調南機場案，並對土管條例第80條之2進行整體考量。", "response_removed": false, "topic": "老舊社區公辦都更推動"}, {"citations": [{"page": 466, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=22"}, {"page": 467, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=23"}, {"page": 467, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=23"}, {"page": 468, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=24"}, {"page": 479, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=35"}, {"page": 487, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=43"}, {"page": 466, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=22"}], "councilor_points": ["郭昭巖議員指出第一果菜及萬大魚類批發市場改建工程扣除「標餘款 9.3 億元」後，市府仍要求增編「49.93 億元」，要求市府明確說明標餘款具體用途與規劃。郭昭巖議員質疑擴建 6 樓至 8 樓共「6,000 坪」空間的委外 OT 可行性與人潮吸引力，並指出農一期工程延至「115 年 6 月」恐造成攤商壓力，要求市府於預算審查前提出更務實的計畫與溝通說明。"], "response": "市長表示會請市場處準備「9.3 億元標餘款」實際具體用途，於「2 個星期內」向議員回覆，並承諾未來經營管理會做效益評估、聆聽地方聲音及加強溝通。市場處處長說明標餘款屬於「水庫的概念」，可能放在需求調整與建築工程等項目，會再將具體規劃「弄清楚」。", "response_removed": false, "topic": "第一果菜及萬大魚類批發市場改建工程"}, {"citations": [{"page": 471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=27"}, {"page": 471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=27"}, {"page": 472, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=28"}, {"page": 473, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=29"}, {"page": 474, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=30"}, {"page": 475, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=31"}], "councilor_points": ["郭昭巖議員建議市府應跨局處辦理年度活動串聯在地美食與觀光產業，指出地方振興政策經費分配不均，例如「八德 3C 哈樂 day」投入「800 萬元」卻未外溢至周邊。郭昭巖議員指出美食推廣活動以「家次/人次」計算屬浮報效果，要求進行檢討。郭昭巖議員建議檢討臺北燈節將主燈放在「行旅廣場」等無商圈人潮處的規劃，要求更換至有人潮與買氣的地方。"], "response": "市長表示認同議員建議，將請副秘書長擔任 PM 檢視各商圈活動成效並進行「全面總體檢」，針對臺北燈節燈區調整會再溝通研究。商業處處長說明「八德 3C 哈樂 day」活動帶來人潮並帶動店家消費，表示會檢討精進。觀光傳播局局長表示已與承商及當地做好溝通，辦完後會深入檢討。", "response_removed": false, "topic": "跨局處商圈行銷與觀光活動整合"}, {"citations": [{"page": 468, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=24"}, {"page": 470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=26"}, {"page": 470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=26"}, {"page": 471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=27"}, {"page": 469, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=25"}], "councilor_points": ["郭昭巖議員指出南門市場試營運期間「Wi-Fi 收訊不良」，要求市府督促電信業者改善。郭昭巖議員反映環南市場第一期工程存在標示與位置圖老舊不清、地下停車場大雨淹水卻「不做棚架」等問題，要求追蹤建置遮棚進度。郭昭巖議員指出環南市場「物業管理維護過髒」，要求嚴格檢討並更換維護不善的物管公司。"], "response": "市長表示會要求三大公司在「12 月中以前」解決 Wi-Fi 問題，指示市場處評估環南市場遮棚建置，並強調「絕對不會包庇」物業管理品質問題。市場處處長說明已要求三大公司處理 Wi-Fi，環南市場遮雨棚因「建蔽率的問題」會再評估，並表示會改善位置圖與加強物管服務品質。", "response_removed": false, "topic": "環南市場設施改善與維護管理"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-30"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162#page=21", "transcript_pages": [465, 466, 467, 468, 469, 470, 471, 472, 473, 474, 475, 476, 477, 478, 479, 480, 487], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654962A2FC1C7EA39421941941C3B6562A8BA9136CF3D8176C9CA852238F00A7C162", "videos": [{"date": "2023-11-30", "group": 11}]}, {"dates": ["2023-10-30"], "dept": "交通", "doc_type": "部門質詢", "group": 13, "head