er.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A9172A05E789C591D96F00F4A8D98CD2EC3FF09E18FFB2CEA852238F00A7C162", "videos": [{"date": "2023-11-20", "group": 11}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB963735665493CCA1284E6E7B42BD5B16720985F30BE1E66A42DFA5A802DA852238F00A7C162','2026-10-05T06:04:38Z');
INSERT INTO "fact" VALUES('summary:14-02:pd697b2a2b5','pd697b2a2b5','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:06:33Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=34"}, {"page": 701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=35"}, {"page": 701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=35"}], "councilor_points": ["鍾小平議員詢問市長是否認為大巨蛋是弊案，並指出前市長稱其為「弊案」且涵蓋前市長郝龍斌與馬英九的16年任期，對國民黨很不公平。鍾小平議員表示郝前市長交接時工程進度已達「7、8成」，詢問貿然停工是否合理。鍾小平議員指出內政部營建署於110年審查通過防災逃生避難後，當時市府另訂7項法規致使進度拖延。"], "response": "市長說明上任後會儘快將大巨蛋完工啟用，並表示從前行政院院長拍板到馬前市長、郝前市長及每一任市長對大巨蛋完工均有參與和付出。副市長說明郝前市長交接時工程進度已達7成多，內政部國土管理署已將過程說明清楚。副市長補充說明當時市政府跳開所有法規，另訂7項法規處理防災部分。", "response_removed": false, "topic": "大巨蛋工程歷程與責任探討"}, {"citations": [{"page": 701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=35"}, {"page": 702, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=36"}, {"page": 703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=37"}, {"page": 702, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=36"}], "councilor_points": ["鍾小平議員指出萬華區面臨私娼流竄問題，要求市府將艋舺公園整體整理乾淨。鍾小平議員建議拆除龍山寺站的遮蔽物以改善遊民聚集狀況，並要求市府約束團體或民眾發放食物與金錢。"], "response": "市長說明文化局已規劃對阿公店及茶室進行外觀與區域改造，使其成為在地文化觀光景點。社會局局長說明市府拜會團體協調將便當交由市府按日發放，並結合9個局處開會、警察巡邏驅離、提供行李整理及發行待用券，每年協助超過250位遊民脫離遊民身分。市長表示會思考拆除龍山寺站遮蔽物的建議。", "response_removed": false, "topic": "艋舺公園遊民與萬華區色情問題處理"}, {"citations": [{"page": 703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=37"}, {"page": 704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=38"}], "councilor_points": ["鍾小平議員詢問市府每年給予萬華區主要商業區的補助預算金額。鍾小平議員指出市府給予商圈的「500萬元左右」預算過少，建議向中央爭取「2、3億元」進行商圈招牌換新與整體再造，並要求北市府配合建設萬華。"], "response": "商業處處長說明目前補助4個商圈共約200萬元，加上萬華地區振興活動一年約250萬元，總計約500萬元。市長表示希望議員若進入立法院可向中央大力爭取經費，並承諾市府會配合建設萬華。", "response_removed": false, "topic": "萬華區商圈振興與建設"}, {"citations": [{"page": 5792, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=9"}], "councilor_points": ["鍾小平議員詢問捷運萬大中和線第一期工程自行政院核定至今的時間，並要求捷運工程局說明預計全部完工與通車的年份。鍾小平議員指出該工程從核定到通車需時「17年」，比一般地下工程晚了「7年」，要求市府儘快完成以帶動地方發展。"], "response": "捷運工程局局長說明萬大線第一期工程於民國99年核定，預計於民國116年完工。捷運工程局局長表示會想盡辦法在民國116年將工程做完。", "response_removed": false, "topic": "捷運萬大中和線第一期工程進度"}, {"citations": [{"page": 704, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=38"}, {"page": 705, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=39"}], "councilor_points": ["鍾小平議員詢問市長與體育局局長平時的運動項目，並強調健康是臺北市最重要的公共政策。鍾小平議員邀請市長與體育局局長在議場共同做「30個」伏地挺身。"], "response": "市長說明平時運動包括打籃球、跑步、游泳及重訓，體育局局長說明常做的運動為打籃球與跑步。市長表示議場較不方便，建議下次約在運動場或球場切磋。", "response_removed": false, "topic": "市府首長運動習慣與推廣"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=34", "transcript_pages": [700, 701, 702, 703, 704, 705], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 17}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=8", "transcript_pages": [5791, 5792, 5793, 5794], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 17}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665497EF9DE33F91C553B554612F3C92B419C5ADDD461EC4EB2D7A852238F00A7C162", "videos": []}, {"dates": ["2023-10-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162", "videos": [{"date": "2023-10-16", "group": 13}]}, {"dates": ["2023-10-20"], "dept": "教育", "doc_type": "部門質詢", "group": 6, "heading": "教育部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162", "videos": [{"date": "2023-10-20", "group": 6}]}, {"dates": ["2023-11-10"], "dept": "工務", "doc_type": "部門質詢", "group": 7, "heading": "工務部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 7}]}, {"dates": ["2023-11-16"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162", "videos": [{"date": "2023-11-16", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162','2026-10-05T06:06:33Z');
INSERT INTO "fact" VALUES('summary:14-02:p67335d29b9','p67335d29b9','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:08:45Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 725, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=59"}, {"page": 725, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=59"}, {"page": 728, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=62"}, {"page": 729, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=63"}, {"page": 729, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=63"}, {"page": 728, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=62"}], "councilor_points": ["鍾沛君議員指出市府各區公所舉辦單身聯誼活動預算逐年上升但參加人數下降，且活動設計缺乏吸引力。鍾沛君議員指出部分活動如手作、烹飪或算命形式尷尬且時間短暫，甚至出現公關公司工作人員充當參加者的亂象，建議參考國外引進多元活潑形式或元宇宙等做法。鍾沛君議員要求民政局建立審查與追蹤機制，拋棄「刻板的想法」，並改善活動內容以提升民眾參加意願。"], "response": "臺北市市長表示活動設計可跳脫既有框架並參考國外做法進行檢討改進。民政局局長說明過往活動辦理情形，表示將會集思廣益，明年擬運用預備金規劃較為精進多元的活動，並建立追蹤問卷與審查機制。", "response_removed": false, "topic": "市府單身聯誼活動辦理成效與設計檢討"}, {"citations": [{"page": 3926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=28"}, {"page": 3926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=28"}, {"page": 3927, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=29"}, {"page": 3927, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=29"}, {"page": 3928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=30"}, {"page": 3928, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654917D553D97F9605EDB674059599A0BAD23C06843E7244235EA852238F00A7C162#page=30"}], "councilor_points": ["鍾沛君議員指出臺北流行音樂中心舉辦音樂會遭觀眾反映爆量與低頻共振等音質問題，建議場方於事前技術協調會給予主辦單位防範建議。鍾沛君議員指出展演廳2樓與3樓走道寬度僅95公分，相較其他場館偏狹窄且引發緊急疏散安全疑慮，建議評估調整。"], "response": "臺北流行音樂中心董事長說明每場演出均有不同混音與音響團隊，事前皆有技術協調會，會再與主辦單位溝通以保證品質。臺北流行音樂中心執行長與工務局新建工程處科長說明走道寬度符合建築技術規則規定，文化局局長表示會與相關單位會商確定法規並研擬解決方案。", "response_removed": false, "topic": "臺北流行音樂中心音質演出效果與場館安全改善"}, {"citations": [{"page": 58, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=19"}, {"page": 61, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=22"}, {"page": 58, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=19"}, {"page": 59, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=20"}, {"page": 60, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=21"}, {"page": 60, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=21"}], "councilor_points": ["鍾沛君議員指出第二殯儀館未來成為臺北市唯一殯儀館後服務件數增加，建議殯葬管理處思考將回饋金擴大發放至鄰近受影響區域。鍾沛君議員指出殯儀館更名活動評分標準過寬導致許多「惡趣味」投稿，建議市府專心處理第二殯儀館啟用與第一殯儀館移轉後的量能問題。"], "response": "殯葬管理處處長說明殯儀館與焚化爐回饋金法令不同，係依各自規定發放。殯葬管理處處長說明更名活動採開放徵件後由專家學者與內部委員開會討論評選，不會直接開放投票。", "response_removed": false, "topic": "第二殯儀館回饋金發放範圍與更名活動檢討"}, {"citations": [{"page": 5813, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=30"}, {"page": 5814, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=31"}, {"page": 5815, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=32"}, {"page": 5814, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=31"}, {"page": 5816, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=33"}], "councilor_points": ["鍾沛君議員指出悠遊卡於沖繩開辦境外支付服務後消費筆數與金額不如預期，且分潤極低導致業務虧損。鍾沛君議員指出行銷宣傳效果不彰，要求悠遊卡公司積極與日方洽談，將服務擴展至電車或公車等交通工具與小額消費通路。"], "response": "悠遊卡股份有限公司總經理說明境外支付受單筆1,500元上限與實名制等法規限制。悠遊卡股份有限公司總經理表示已與琉球銀行達成共識，會努力在明年6月觀光旺季前推動將悠遊卡適用於電車或公車等交通工具，並加強宣傳。", "response_removed": false, "topic": "悠遊卡沖繩境外支付服務效益與通路拓展"}, {"citations": [{"page": 720, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=54"}, {"page": 5923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=13"}, {"page": 720, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=54"}, {"page": 721, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=55"}, {"page": 722, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=56"}, {"page": 721, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=55"}, {"page": 5923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=13"}], "councilor_points": ["鍾沛君議員指出大巨蛋測試賽及亞錦賽免費門票秒殺且黃牛高價轉售賺取暴利，質疑現行裁罰機制對免費門票無法發揮作用。鍾沛君議員建議市府研議實名制、抽籤或購票回答問題等防堵機制，並要求警方確保各分局與派出所明確知曉只要提供黃牛資訊即可受理檢舉。"], "response": "臺北市市長說明已請法務局研議防堵做法，並配合中央修法及評估實名制與抽籤等方案。警察局局長說明只要提供確定賣黃牛票資訊就會進行調查，並承諾讓各分局知曉受理標準；體育局主任秘書表示已呼籲民眾抵制並將研議相關防範處置方案。", "response_removed": false, "topic": "大巨蛋賽事免費門票黃牛轉售防堵機制"}, {"citations": [{"page": 66, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=27"}, {"page": 67, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=28"}, {"page": 66, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=27"}], "councilor_points": ["鍾沛君議員質疑戶政事務所夜間服務自疫情停辦迄今未恢復，影響上班時間不便洽公之民眾。鍾沛君議員建議臺北市率先恢復夜間服務以服務市民，並要求民政局於1週內分析北基桃民眾使用比例與恢復服務所需之預算。"], "response": "民政局局長說明北北基桃目前均未開放，且基層加班費極少、案件量大，若單獨開放恐造成案件集中。民政局局長承諾於1週內提供北基桃民眾比率分析與恢復夜間服務所需預算資料。", "response_removed": false, "topic": "戶政事務所夜間服務恢復效益評估"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=53", "transcript_pages": [719, 720, 721, 722, 723, 724, 725, 726, 727, 728, 729, 730, 731], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 17}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=30", "transcript_pages": [5813, 5814, 5815, 5816, 5817], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC", "videos": [{"date": "2023-10-31", "group": 17}]}, {"dates": ["2023-11-06"], 