921, 5922, 5923, 5924, 5925, 5926, 5927, 5928], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162", "videos": [{"date": "2023-11-10", "group": 7}]}, {"dates": ["2023-11-16"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=19", "transcript_pages": [58, 59, 60, 61, 62, 63, 64, 65, 66, 67], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162", "videos": [{"date": "2023-11-16", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162','2026-10-05T06:08:45Z');
INSERT INTO "fact" VALUES('summary:14-02:p54ba4cd655','p54ba4cd655','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:10:37Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 554, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=13"}, {"page": 5642, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=1"}, {"page": 5643, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=2"}, {"page": 5644, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=3"}, {"page": 5644, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=3"}, {"page": 5650, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=9"}, {"page": 5646, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=5"}, {"page": 5647, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=6"}, {"page": 5651, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=10"}], "councilor_points": ["闕枚莎議員關注港湖交通改善，詢問捷運民生汐止線臺北路段綜規報告進度與東環段動工時程，並建議評估信義線東延至中央研究院或規劃捷運支線連結板南線。闕枚莎議員亦建議於東環段大港墘公園站增設無人親子雙語智慧圖書館。此外，闕枚莎議員建議捷運公司於南港車站設置縮小版模擬彩繪列車，並由悠遊卡公司持續發行內附英文教學之年度紀念悠遊卡。"], "response": "捷運工程局局長說明，民生汐止線綜規計畫希望在今年底前完成並於113年第1季送中央審核，東環段細設期程已由18個月縮短為10個月，且會持續研究延伸至中央研究院或支線方案，並結合戶外下凹式庭園規劃大港墘公園站圖書館。捷運股份有限公司總經理表示，全車隊140輛已完成設置親子友善區，寵物專車評估於特定節慶繼續辦理，並將研議設計縮小版模型列車。捷運股份有限公司行車處處長說明，新北大都會公園秋季親子書香電影院活動由臺北市負擔電影院費用，新北市負擔部分費用、行動書車及場地。", "response_removed": false, "topic": "捷運路網建設與親子友善乘車環境規劃"}, {"citations": [{"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=4"}, {"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=4"}, {"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=4"}, {"page": 4158, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549A94FBB77E2AD4ED92C05DC1358A8AAA6C2F7E402911574C2A852238F00A7C162#page=23"}, {"page": 545, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=4"}, {"page": 546, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=5"}, {"page": 4157, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549A94FBB77E2AD4ED92C05DC1358A8AAA6C2F7E402911574C2A852238F00A7C162#page=22"}], "councilor_points": ["闕枚莎議員建議成立府級英語友善城市推動專案小組，由市長擔任召集人、副市長擔任執行長，並優先從東區門戶計畫南港區試辦。闕枚莎議員建議教育局局長每年至少主持一場全市雙語教育聯盟會議，研議更完善的雙語教師薪資獎勵制度，落實校園雙語標示全面化，並利用兒童樂園等場域辦理創意英語夏令營。闕枚莎議員亦建議仿效高雄市與位於內湖的美國在台協會合作，打造臺北市雙語教育培訓基地。"], "response": "市長說明，市府已主動向新加坡教育部長提出雙語教育合作，英、澳等國代表處亦表達提供相關資源之意願，已請教育局對接，並表示會研議成立專案小組及辦理英語情境夏令營等建議。教育局局長說明，目前推動雙語教學係採獎勵金及減授鐘點方式處理，對於議員提出每年主持全市雙語聯盟會議、研議雙語教師獎勵薪資制度、落實校園雙語標示及與美國在台協會合作打造培訓基地等建議，將納入參考研議。", "response_removed": false, "topic": "雙語教育政策與英語友善環境推動"}, {"citations": [{"page": 549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=8"}, {"page": 1373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=17"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=19"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=19"}, {"page": 551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=10"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=19"}, {"page": 1375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=19"}], "councilor_points": ["闕枚莎議員建議市府啟動「北市聯醫十年精進計畫」，引進飯店式管理與客製化醫療服務，並優先以忠孝院區作為示範區進行改建。闕枚莎議員建議將忠孝院區與對面的成德市場進行整體EOD規劃設計，並強調計畫成功的兩大關鍵為規劃完善的中繼醫院及研議調升醫護人員薪資福利。闕枚莎議員要求衛生局於2個月內提出比較具體的臺北市聯醫10年精進計畫。"], "response": "市長表示，市府會朝該方向研議，以病患為核心提升醫療品質，並提供醫護人員良好的職場環境。衛生局局長說明老舊建物改建係逐步辦理，澄清醫院護病比規範不超過1比12，並同意於2個月內提出具體的10年精進計畫。市立聯合醫院院長表示會朝該方向研議，並將彙整醫護人員薪資與福利資料提供給衛生局。", "response_removed": false, "topic": "臺北市立聯合醫院十年精進計畫"}, {"citations": [{"page": 6041, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162#page=8"}, {"page": 6043, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162#page=10"}, {"page": 6044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162#page=11"}, {"page": 6042, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162#page=9"}], "councilor_points": ["闕枚莎議員指出109年至112年公園設施受傷陳情案中，溜滑梯受傷高達181件，並以明美公園磨石子溜滑梯坡度過陡造成長者骨折為例，要求改善高低落差及避開高溫材質。闕枚莎議員提出公園遊具4點建議，包括遊具材質需具耐熱性、設置警語提醒、定期檢驗維護，以及設計具故事性與在地特色的共融式遊具。闕枚莎議員亦建議市府打造國際級特色公園，並以碧湖公園為優先示範區，於一個月內與文化局及臺灣戲曲學院研議規劃「年度碧湖水上劇場」。"], "response": "公園路燈工程管理處處長說明，針對無樹遮蔭之場域已逐步加裝12座遮陽設施，未來遊戲場設計將依議員提出之4點原則辦理並特別注意明美公園改善，同時會與文化局及臺灣戲曲學院研擬討論碧湖水上劇場規劃。", "response_removed": false, "topic": "公園遊具安全改善與特色公園規劃"}, {"citations": [{"page": 551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=10"}, {"page": 552, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=11"}, {"page": 553, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=12"}], "councilor_points": ["闕枚莎議員指出臺北市公有市場使用年限超過20年者達9成，而南港區成德市場與中研市場已超過55年且未納入現有17處改建計畫。闕枚莎議員建議參考荷蘭鹿特丹馬克塔爾（Markthal）市場經驗，將成德市場與中研市場打造成具城市美學、雙語教學標示（配合第5座親子數位圖書館）及結合產學合作文創基地的國際級多功能現代化傳統市場。闕枚莎議員並提醒市府在市場改建過程中，必須進行雙向溝通並聽取攤商需求，且妥善設置中繼市場。"], "response": "市場處處長說明，未來成德市場改建案會融入議員建議之文創、雙語、親子等先進想法。市長表示，會朝該方向將成德市場打造成示範點，融入雙語、親子、文創等元素並參考荷蘭案例，同時強調會聽取攤商意見以符合其需求。", "response_removed": false, "topic": "傳統市場現代化與多功能改建"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-01"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162#page=1", "transcript_pages": [542, 543, 544, 545, 546, 547, 548, 549, 550, 551, 552, 553, 554], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162", "videos": [{"date": "2023-12-01", "group": 14}]}, {"dates": ["2023-10-27"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC#page=1", "transcript_pages": [5642, 5643, 5644, 5645, 5646, 5647, 5648, 5649, 5650, 5651], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665498AEE61DE1B14C829261F0D1640D6C7B0279A2B2B587D9A673CF01040659E810402D1DE3DCEB210BC", "videos": [{"date": "2023-10-27", "group": 10}]}, {"dates": ["2023-11-06"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 12, "heading": "警政衛生部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162#page=17", "transcript_pages": [1373, 1375, 1376, 1377], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB963735665499A42EF31B50E67D8CE0DF80026EC508F16F37E9EC2D89C8EA852238F00A7C162", "videos": []}, {"dates": ["2023-10-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 16, "heading": "財政建設部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D70306EE2643FC5FDA8A752C986A27A6069B942CE8EE14EEA852238F00A7C162#page=7", "transcript_pages": [3664, 3665, 3666, 3667, 3668, 3669, 3670, 3671], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D70306EE2643FC5FDA8A752C986A27A6069B942CE8EE14EEA852238F00A7C162", "videos": [{"date": "2023-10-17", "group": 16}]}, {"dates": ["2023-10-24"], "dept": "教育", "doc_type": "部門質詢", "group": 17, "heading": "教育部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549A94FBB77E2AD4ED92C05DC1358A8AAA6C2F7E402911574C2A852238F00A7C162#page=21", "transcript_pages": [4156, 4157, 4158, 4159, 4160, 4161, 4162, 4163], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB96373566549A94FBB77E2AD4ED92C05DC1358A8AAA6C2F7E402911574C2A852238F00A7C162", "videos": [{"date": "2023-10-24", "group": 17}]}, {"dates": ["2023-11-13", "2023-11-14"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162#page=5", "transcript_pages": [6038, 6039, 6040, 6041, 6042, 6043, 6044], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654989627EE71441A24BA21D5C28C28E27ACFF55AD723222B0BFA852238F00A7C162", "videos": [{"date": "2023-11-13", "group": 14}, {"date": "2023-11-14", "group": 14}]}, {"dates": ["2023-11-20"], "dept": "民政", "doc_type": "部門質詢", "group": 12, "heading": "民政部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549130CEE2BE31FD96B13780A0EFFA3B4CFD8110B90C9888B04A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549130CEE2BE31FD96B13780A0EFFA3B4CFD8110B90C9888B04A852238F00A7C162", "videos": [{"date": "2023-11-20", "group": 12}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB9637356654949E426E6DF8885B075DC6F661B19A5C4AAF57DB7FDDB4B12A852238F00A7C162','2026-10-05T06:10:37Z');
INSERT INTO "fact" VALUES('summary:14-02:padc186f41c','padc186f41c','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:16:31Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1247, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=20"}, {"page": 1248, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=21"}, {"page": 1250, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=23"}, {"page": 1245, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=18"}, {"page": 1249, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=22"}], "councilor_points": ["陳慈慧議員指出臺北市科技執法設備增加且可舉發多項違規，但告示牌字體不夠明顯，建議於路口增設LED跑馬燈推播舉發類型。此外，陳慈慧議員指出民眾檢舉交通違規件數增加，因紅單照片不清晰且郵寄時間長導致行車紀錄器檔案被覆蓋，建議研討開放民眾線上調閱被檢舉違規影片的可行性。"], "response": "警察局局長說明科技執法設備今年至明年會增加47處，並表示會將多項違規路口使用LED跑馬燈顯示取締項目納入討論。警察局局長與警察局交通警察大隊大隊長說明公開影片涉及車號等個資洩漏風險，但承諾會就法規面研討線上調閱影片的可行性。", "response_removed": false, "topic": "科技執法設備告示與違規採證影片調閱機制"}, {"citations": [{"page": 3649, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=18"}, {"page": 3649, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=18"}, {"page": 3650, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=19"}, {"page": 3651, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=20"}, {"page": 3652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=21"}, {"page": 3650, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=19"}, {"page": 3652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=21"}], "councilor_points": ["陳慈慧議員反映北投市場重建規劃中攤位空間狹小，建議攤位面積應大於舊市場的1.8坪。陳慈慧議員亦指出合署單位空間需求增加恐排擠公托與日照設施，建議市場處與都市發展局協調專屬都市計畫法規以放寬容積率與建蔽率。此外，陳慈慧議員指出地下4層停車空間恐不足應付採買人潮，建議評估增加地下開挖樓層。"], "response": "市場處處長說明攤位數已減少並會將後場處理區與賣場區隔，空間會放至需求整合平台與合署單位討論，且明年拆除辦理地質鑽探後會再討論是否往下開挖。都市發展局都市規劃科科長表示，若市場改建有放寬容積率與建蔽率的需求，可盤整後循都市計畫程序協助處理。", "response_removed": false, "topic": "北投市場重建與設施空間規劃"}, {"citations": [{"page": 5627, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=19"}, {"page": 5627, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=19"}, {"page": 5629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=21"}, {"page": 5629, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=21"}, {"page": 5626, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=18"}], "councilor_points": ["陳慈慧議員指出民眾對車輛未禮讓行人的取締標準仍有認知落差，建議交通局與交通警察大隊拍攝情境劇短片於公共空間及公車上加強宣導。此外，陳慈慧議員指出人潮眾多或路幅狹窄路口易因行人通行造成車輛回堵，建議積極評估擴大推動行人專用時相。"], "response": "交通警察大隊大隊長說明警方依車輛是否有停讓動作及行穿線為取締標準，交通局局長表示12月起會拍攝短片於多種管道宣傳。交通管制工程處處長與交通局局長說明目前優先推動學校周邊行人綠燈早開，對幹道或適合路口會計算車流後評估推動行人專用時相。", "response_removed": false, "topic": "車輛停讓行人取締標準與號誌時相評估"}, {"citations": [{"page": 215, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=16"}, {"page": 216, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=17"}, {"page": 217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=18"}, {"page": 217, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=18"}, {"page": 218, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A7984718F7A2647B494C76E2F4EE9F9BC8D23FB557D5E714A852238F00A7C162#page=19"}], "councilor_points": ["陳慈慧議員指出待徵集役男等待入伍時間長達半年以上影響職涯與就業，建議兵役局向中央協調爭取更多員額，並針對弱勢家庭役男提供以工代賑資訊。此外，陳慈慧議員指出「役職挺你」專案申請人數過少且校園宣導場次不足，要求調整宣導方式並增加高中與大學的宣導場次。"], "response": "兵役局局長與兵役局徵集勤務科科長說明已向中央申請並獲同意增加役男員額，並承諾將以工代賑資訊告知役男。兵役局局長表示會研議改善「役職挺你」的宣導方式，並與教育局及學校聯繫增加校園宣導場次。", "response_removed": false, "topic": "役男徵集入伍等待時間過長與職能培育宣導"}, {"citations": [{"page": 3941, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=10"}, {"page": 3942, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=11"}, {"page": 3942, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=11"}, {"page": 3943, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=12"}, {"page": 3944, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=13"}, {"page": 3944, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=13"}], "councilor_points": ["陳慈慧議員指出臺北市觀光旅館平均房價調漲至4,831元且住用率下降，詢問觀傳局稽查次數偏少之原因，並建議將業者報備房價公開於網路供旅客比價。此外，陳慈慧議員建議觀傳局媒合旅宿業者與交通票券提供折扣優惠，以吸引旅客留在臺北市住宿消費。"], "response": "觀光傳播局觀光產業科科長說明每年均對轄內15家一般觀光旅館進行稽查，且業者依法須於官網、台灣旅宿網及櫃檯揭露房價。觀光傳播局局長說明飯店因人力未完全恢復使房價接近報備上限，並表示會努力媒合相關結合優惠，提升旅客留宿誘因。", "response_removed": false, "topic": "臺北市旅宿業房價過高與國旅優惠行銷"}, {"citations": [{"page": 140, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=31"}, {"page": 141, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=32"}, {"page": 142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=33"}, {"page": 143, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=34"}], "councilor_points": ["陳慈慧議員指出社子島長期遭不肖業者違法傾倒廢棄物，並質疑檢查站固定1.5小時的攔檢時段易被業者規避。陳慈慧議員建議於偷倒熱點增設監視器、實施機動攔查，並會同法務局探討公布違法傾倒業者名單的可行性。"], "response": "環保局局長說明每日安排稽查攔檢並每月以無人機巡檢33處熱點。警察局局長表示明年預計增設3支監視器。市長表示會請法務局研究公布違法業者名單，並承諾機動調整稽查攔查時段，嚴查嚴辦。", "response_removed": false, "topic": "社子島非法傾倒廢棄物查緝與預防機制"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-24"], "dept": null, "doc_type": "市政總質詢", "group": 3, "heading": "市政總質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC#page=13", "transcript_pages": [122, 123, 124, 137, 138, 139, 140, 141, 142, 143, 144], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB963735665497E743F72D977A5E662B74DFE80EC498C58AF50B8A3B26EA4E12198B7DFD3748A02D1DE3DCEB210BC", "videos": [{"date": "2023-11-24", "group": 3}]}, {"dates": ["2023-10-27"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC#page=17", "transcript_pages": [5625, 5626, 5627, 5628, 5629, 5630, 5631, 5632], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665496376BFF8F94A65571940DFEE53EA921902B9E00DAFEBADFF3DFA1F4BD8E204AC02D1DE3DCEB210BC", "videos": [{"date": "2023-10-27", "group": 9}]}, {"dates": ["2023-11-03"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 5, "heading": "警政衛生部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162#page=15", "transcript_pages": [1242, 1243, 1244, 1245, 1246, 1247, 1248, 1249, 1250], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549F0012FC1EF4CC8F5A6326A9851470EA5B140623AAC111689A852238F00A7C162", "videos": [{"date": "2023-11-03", "group": 5}]}, {"dates": ["2023-10-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 15, "heading": "財政建設部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162#page=15", "transcript_pages": [3646, 3647, 3648, 3649, 3650, 3651, 3652], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549D237126AA44393629A027D49442C9FD77BF3113BF0E377E8A852238F00A7C162", "videos": [{"date": "2023-10-17", "group": 15}]}, {"dates": ["2023-10-20"], "dept": "教育", "doc_type": "部門質詢", "group": 7, "heading": "教育部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162#page=8", "transcript_pages": [3939, 3940, 3941, 3942, 3943, 3944, 3945], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB963735665493CCB350597EEEC468AE87E8EE8EE0E586853C60E8DF5D212A852238F00A7C162", "videos": [{"date": "2023-10-20", "group": 7}]}, {"dates": ["2023-11-10"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654955CA342E10495D0A6DD1BE6630EBAB8FDDC5AB445DD0D6BFA852238F00A7C162#page=14", "transcript_p