INSERT INTO "fact" VALUES('summary:14-02:p3371a36c1c','p3371a36c1c','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:22:12Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 6113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=20"}, {"page": 391, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=2"}, {"page": 392, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=3"}, {"page": 393, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=4"}, {"page": 394, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=5"}, {"page": 394, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=5"}, {"page": 395, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=6"}], "councilor_points": ["陳賢蔚議員指出臺北市少子女化與人口議題嚴峻，詢問勞動局針對市府委員會決議如何積極營造對女性更友善的職場環境。陳賢蔚議員表示未滿 2 歲兒童有高達 68%由家內照顧，指出現行托育政策未完全滿足家長需求，建議社會局正視家長不敢生育的原因並調整政策目標。陳賢蔚議員建議市府跳脫單純經濟補助思維，研議具體作為以表達對勇於生育母親的感謝。"], "response": "勞動局局長說明已推動性別平等認證，未來收到會議紀錄後將與企業及相關局處連結合作。社會局局長說明目前公共化托育供給量能高於需求，並表示會持續精進托育環境與少子女化對策。民政局局長說明少子女化指標旨在提供更好的育兒環境。", "response_removed": false, "topic": "少子女化對策與托育環境改善"}, {"citations": [{"page": 5770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=19"}, {"page": 5771, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=20"}, {"page": 5772, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=21"}, {"page": 5773, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=22"}, {"page": 5773, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=22"}, {"page": 5774, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB963735665495A82C05599663295CAB74A80DEAD8FD6353DE87D337116E733E08FDA934B459102D1DE3DCEB210BC#page=23"}], "councilor_points": ["陳賢蔚議員指出交通局編列高額預算設置智慧號誌，詢問交控中心人工操作現況與改善成效。陳賢蔚議員表示現行智慧號誌多偏向車本思維，建議市府重新調整政策優先順序，將資源更多投入於保護行人的安全設施。陳賢蔚議員建議於淡北道路等新興重大交通衝擊區域，運用智慧號誌掌握主導權以降低交通衝擊。"], "response": "交通管制工程處處長說明號誌連線情況，並表示智慧號誌旨在提升綠燈使用效率與降低車輛空等時間。交通局局長說明相關預算為年度連續型預算，強調市府重視行人交通安全，承諾會加入人本觀念分配秒數。", "response_removed": false, "topic": "智慧號誌設置與人本交通檢討"}, {"citations": [{"page": 1466, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=4"}, {"page": 1465, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=3"}], "councilor_points": ["陳賢蔚議員指出流感疫苗議題遭泛政治化會弱化防疫成效，詢問衛生局關於臺北市流感疫苗接種率偏低的原因。陳賢蔚議員表示不宜將疫苗議題泛政治化，建議衛生局應以科學與醫學專業主導公衛政策並加強闢謠宣導。"], "response": "衛生局局長說明公費流感疫苗施打與訂購進度，表示政策制定考量專業亦包含大眾聲音，並承諾會持續宣導推廣疫苗接種。", "response_removed": false, "topic": "流感疫苗接種政策與衛教宣導"}, {"citations": [{"page": 1469, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE65BB10AA629AB0925A02DB96373566549DC25061E23043CC6AF05AE858417F1E694520146B0F33388A852238F00A7C162#page=7"}, {"page": 3532, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162#page=2"}, {"page": 3533, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162#page=3"}, {"page": 3534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162#page=4"}], "councilor_points": ["陳賢蔚議員指出「台北好水直飲台」自主維護紀錄存在逾 2 天未維護、出現未來日期及同一時間多處檢測等數據異常現象。陳賢蔚議員要求臺北自來水事業處全面檢視直飲台維護狀況，禁止維護機關怠惰造假，以保障市民飲水安全。"], "response": "臺北自來水事業處處長說明自主維護係於工作日進行台面清潔，並表示會於會後查明原因，承諾在 3 個星期內向議員提出完整報告。", "response_removed": false, "topic": "直飲台自主維護資料真實性檢討"}, {"citations": [{"page": 6108, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=15"}, {"page": 6110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=17"}, {"page": 6110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=17"}, {"page": 6111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=18"}, {"page": 6112, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=19"}], "councilor_points": ["陳賢蔚議員指出臺北市熱島效應與行道樹樹冠覆蓋率問題，詢問高風險樹木之檢測與移除進度。陳賢蔚議員要求工務局與都發局建立預防方案及補植計畫，避免移除危樹後影響綠覆蓋率，並建議完善綠建築管理。"], "response": "工務局局長說明公園處持續檢測高風險樹木並儘速辦理移除，未來會結合人行環境改善進行整體考慮。建築管理工程處處長說明可統計取得綠建築標章之建築物，並於屆期時提醒社區辦理展延認可。都市發展局局長表示會研議相關檢視標準並向議員說明。", "response_removed": false, "topic": "高風險路樹安全管理與綠覆蓋率"}, {"citations": [{"page": 3538, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB96373566549BD6FE060B94226FA060198D1FD3275CB419B8EEB3B8DDD31A852238F00A7C162#page=8"}, {"page": 4093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=1"}, {"page": 4095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=3"}], "councilor_points": ["陳賢蔚議員指出臺北市有高達 3 成校舍屋齡已達 50 年以上，建議教育局推動新世代校園改建十大建設指標。陳賢蔚議員要求校舍改建應結合社服機構、停車空間、友善接送、風雨運動處所與藝文表演場館，並落實公民參與溝通。"], "response": "教育局局長表示議員提出的十項指標建議非常好，包含社服設施、綠建築及生命教育場域等均會納入改建參考。", "response_removed": false, "topic": "新世代校園改建指標與規劃"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-11-28"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC#page=32", "transcript_pages": [320, 321, 322, 323, 324, 325, 326, 327, 329, 331], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2E