/gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162#page=1", "transcript_pages": [4093, 4094, 4095, 4096, 4097, 4098, 4099, 4100], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE686A1CED547AEAFFEA02DB9637356654981F0CCC556AC19EE4A16EFF798CFD22980D7BE4FE461B5D1A852238F00A7C162", "videos": [{"date": "2023-10-24", "group": 15}]}, {"dates": ["2023-11-14"], "dept": "工務", "doc_type": "部門質詢", "group": 18, "heading": "工務部門質詢第18組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162#page=14", "transcript_pages": [6107, 6108, 6109, 6110, 6111, 6112, 6113], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB9637356654901A3E52D8112DD2B27B3B7693824A41B5760B05BD5E88BDFA852238F00A7C162", "videos": [{"date": "2023-11-14", "group": 18}]}, {"dates": ["2023-11-21"], "dept": "民政", "doc_type": "部門質詢", "group": 17, "heading": "民政部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162#page=1", "transcript_pages": [390, 391, 392, 393, 394, 395, 396, 397], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549A0B0404DD567F51D88FB82BC2FCF36A0B45686BAE634CACEA852238F00A7C162", "videos": [{"date": "2023-11-21", "group": 17}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A619732791E90528A02DB96373566549DF594911859E2EA4D80F193ED8C8EDEF4EA775CA2EE2AA254A74A2595111329C02D1DE3DCEB210BC','2026-10-05T06:22:12Z');
INSERT INTO "fact" VALUES('summary:14-02:p2cdc00a729','p2cdc00a729','summary','2023-12-07','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:24:02Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 3594, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=16"}, {"page": 3595, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=17"}, {"page": 3596, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=18"}, {"page": 3591, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=13"}, {"page": 3595, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=17"}, {"page": 3597, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6670651E05EC84C7CA02DB963735665495D49C147AB3AB1F50AFE3BA05A83704A94376E70C1266FF2A852238F00A7C162#page=19"}], "councilor_points": ["陳重文議員指出網路購物平台販售AI虛擬兒少寫真、大麻種子、管制刀具及壯陽藥等違規商品，並表示現行關鍵字若未及時更新將無法查獲違禁品。陳重文議員要求商業處與消保官應主動針對網路平台實施全面稽查，並於3個月內提報跨局處整合做法。"], "response": "商業處處長說明每季皆會開會更新關鍵字，並要求平台業者配合下架違規商品廣告。商業處處長與主任消費者保護官表示會整合市府相關單位力量，並於3個月內討論評估全面稽查與維護網購環境的做法。", "response_removed": false, "topic": "網路購物平台違規商品稽查與關鍵字管理"}, {"citations": [{"page": 5914, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=4"}, {"page": 5915, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=5"}, {"page": 5916, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=6"}, {"page": 5913, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=3"}, {"page": 5915, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=5"}], "councilor_points": ["陳重文議員詢問市長承諾盤點7,000戶潛力社會住宅基地的執行規劃，並指出北投捷運機廠擬採人工地盤共構興建社宅已引發在地里民疑慮。陳重文議員要求都市發展局與捷運公司應主動聽取地方意見，並召開聯合說明會化解民眾疑慮。"], "response": "都市發展局局長說明目前已盤點出3處預估可蓋540戶的社宅基地，至於北投機廠則尚在辦理工程可行性評估階段。捷運公司工務處處長說明北投機廠係因應里長訴求研擬採人工地盤開發以解決噪音問題，都市發展局局長並承諾於今年年底前前往地方召開說明會聽取居民意見。", "response_removed": false, "topic": "北投捷運機廠興建社會住宅規劃與地方溝通"}, {"citations": [{"page": 5916, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=6"}, {"page": 5917, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=7"}, {"page": 5919, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=9"}, {"page": 5920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE640660B60D06DFB92A02DB963735665496C945BB5A7628F020EAACFCD52486EFDC580B91FD0641569A852238F00A7C162#page=10"}], "councilor_points": ["陳重文議員關切老舊公寓增設外掛電梯政策，指出106年至112年間僅完成38件補助，推動成效有限。陳重文議員建議都市更新處應科學化研判老齡化嚴重的社區，主動出擊加強輔導團推動力度，並製作模擬問答宣導以協助住戶克服溝通障礙。"], "response": "都市更新處處長說明外掛電梯補助已提高至1案最高300萬元，且土地同意比例門檻已降至二分之一。都市更新處處長表示後續會請輔導團增加推動力度，並加強相關宣導與溝通工作。", "response_removed": false, "topic": "老舊公寓增設外掛電梯補助與主動輔導宣導"}, {"citations": [{"page": 71, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=32"}, {"page": 72, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=33"}, {"page": 72, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=33"}, {"page": 73, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE67DBC80F76A9CB0B0A02DB96373566549AE2F91171C810576177F6D23902B8021258EA0CC39A42EE1A852238F00A7C162#page=34"}], "councilor_points": ["陳重文議員質詢親密關係家暴案件中受暴者寵物遭威脅或帶走時的處置困境，指出緊急保護令需4小時核發、通常保護令需1至2個月，恐無法即時救回寵物。陳重文議員指出「臺北市動物保護自治條例」第21條未具強制性，要求社會局與法務局研擬因應之策以即時維護受暴者與毛小孩安全。"], "response": "社會局局長說明受暴者可透過親密關係暴力評估聲請保護令，由警察執行交付命令取回寵物。法務局局長說明若有脅迫過程之錄音錄影等足夠事證，得依規定由動保處會同警察進行調查，並表示會針對即時安全取回寵物的問題研想因應對策。", "response_removed": false, "topic": "親密關係家暴案件受暴者寵物安全處置與保護令機制"}, {"citations": [{"page": 713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=47"}, {"page": 713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=47"}, {"page": 713, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=47"}, {"page": 714, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=48"}, {"page": 714, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=48"}, {"page": 715, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=49"}], "councilor_points": ["陳重文議員質詢警察局編列2億5,000萬元向中華電信續租10年監視器機房之合理性，詢問何不於康樂大樓進行機房自建。陳重文議員指出資訊局已說明技術上可分批搬遷機櫃或透過雲端備份，要求市府指定專案經理人並於1個月內召開會議重啟自建評估。"], "response": "資訊局局長說明在同時考量成本與技術下，分批搬遷機櫃或將資料上傳雲端在技術上皆可行。市長表示會交由副秘書長擔任專案經理人，並承諾於1個月內召集會議重啟專業評估。", "response_removed": false, "topic": "警察局錄影監視器機房自建與續租評估"}], "session": "第14屆第2次定期大會", "sources": [{"dates": ["2023-12-05"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162#page=39", "transcript_pages": [705, 706, 707, 708, 709, 710, 711, 712, 713, 714, 715, 716, 717, 718, 719], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE641DE345F6C1C5B07A02DB96373566549E65F91D092656C5DF42857368A0B776D8A0CEB903F96D84BA852238F00A7C162", "videos": [{"date": "2023-12-05", "group": 17}]}, {"dates": ["2023-10-31"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC#page=11", "transcript_pages": [5794, 5795, 5796, 5797, 5798, 5799, 5800, 5801, 5802, 5803, 5804, 5805, 5806], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6A94044FCF1E14CADA02DB96373566549DB210FA4731A7491BC1ECCE3BE571E0DC699E441C03AB273970B4511AD710DC002D1DE3DCEB210BC", "videos": [