INSERT INTO "fact" VALUES('platform:2022-local:p060f2ce2d0','p060f2ce2d0','platform','2022-11-26','{"district_id": "cyi-council-02", "election": "2022-local", "office": "cyi_councilor", "text": "一、力挺市民，反映民意，監督市政。\n二、督促計畫道路拓寬、污水下水道工程，改善排水系統流暢，嚴防豪大雨成災。\n三、爭取警消人員福利，加強維護治安及防災演練，保障市民生命財產安全。\n四、監督市府通盤檢討都更，打造嘉義市成雲嘉觀光中心，帶動觀光休閒發展。\n五、關懷照顧老、弱、婦、孺、殘障人士，落實各項社會福利相關政策。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
INSERT INTO "fact" VALUES('profile:2022-local:p060f2ce2d0','p060f2ce2d0','profile','2022-11-26','{"education": ["垂楊國小\n大業國中\n嘉義高工\n吳鳳科技大學附設專科進\n修學校（二年制）"], "election": "2022-local", "experience": ["嘉義市第八、九、十屆市議員、曆基土木\n包工業負責人、上井加油站有限公司負責\n人、嘉義縣加油站公會常務理事、長榮派\n出所警友站站長、湖內義消分隊副團長、\n崇文國民小學家長會會長、垂楊國民小學\n家長會顧問、大業國中校友會副理事長、\n興華高級中學副會長、嘉義嘉職顧問、嘉\n義市棒委會主委"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
