INSERT INTO "fact" VALUES('platform:2022-local:p0b4a1d9552','p0b4a1d9552','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "一、推動在地食物銀行計畫，讓需要幫助的人獲得及時援助。\n二、持續全力推動「嘉義市國中小營養午餐免費」。\n三、推動國中小學電子圍籬及高解析度監視系統設置，並持續推動國際安全校園認證，以確保學童安全的就學環境。\n四、針對全市公園內兒童遊戲設施的維護修繕，訂定全市整合的巡察修繕機制，定期巡查報修，提高使用安全性及使用效益。\n五、積極爭取在東區設置「英語村」，提供國中小學生更多的學習機會，提升學生的國際視野。\n六、整合嘉義市醫療資源，推動多元化「老人照護計劃」。\n七、加強落實婦幼保護政策，提供不幸婦女第二專長訓練及輔導就業。\n八、推動落實兩性平權，提升女性職場功能價值。\n九、防範毒品、色情等惡習入侵家庭、校園，以創造優質生活環境。\n十 、督促衛生單位加強食物品管監控，確保市民飲食健康。\n十一、加強建構社區防護網，以確保市民居住品質。\n十二、爭取於東西區各設置一座寵物公園。\n十三、爭取闢建國際規格滑板場。\n十四、推動將情緒教育納入國中小教育課程；並將國中小教師納入情緒教育的課程訓練中，讓嘉義市的情緒教育從家庭到學校，全方位無死\n角。\n十五、推動全面加速汰換全市國中小教室傳統燈具，達到節能省電成效，改善學童視力狀況。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
INSERT INTO "fact" VALUES('profile:2022-local:p0b4a1d9552','p0b4a1d9552','profile','2022-11-26','{"education": ["中華醫事技術學院醫檢科\n國立中正大學管理研究所\n碩士"], "election": "2022-local", "experience": ["嘉義市第7～10屆市議員\n推動市民聯署運動，成功爭取東西區各興\n建一座市民運動中心\n嘉義市「國際安全校園認證」計畫推動者\n極限運動、木球運動委員會主委\n街舞推動發展委員會榮譽主委\n滑板協會理事長\n民進黨嘉義市黨部主委\n蕙蘭獅子會會長\n愛在嘉義婦幼關懷協會會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
