INSERT INTO "fact" VALUES('profile:2022-local:p18efc26692','p18efc26692','profile','2022-11-26','{"education": ["美國奧克拉荷馬州立中央\n大學教育碩士\n大同技術學院\n嘉義高級商業職業學校\n北興國中\n博愛國小"], "election": "2022-local", "experience": ["2016、2020蔡英文總統嘉義市競選總部決\n策委員\n民主進步黨嘉義市黨部第16、17屆主任委\n員\n市議員黃正男、黃露慧服務處主任\n嘉義市青年回嘉協會執行長\n嘉義市雲林同鄉會第十屆理事長\n嘉義市博愛國小98學年度家長會長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
