INSERT INTO "fact" VALUES('platform:2022-local:p1962a09b92','p1962a09b92','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "1、主張嘉義市編列經費補助65歲以上老人免費裝全口假牙。\n2、監督市府落實北排整治與清淤，解決水患。\n3、督促市府將中庄里、仁義里、義教里、後湖里、頂庄里、荖藤里納入污水下水道接管工程。\n4、發揮專業加強預算把關，不債留子孫。\n5、要求市府做好路平，保障市民行車安全。\n6、嘉義市鐵路高架化，監督市府做好高架化後都市縫合。\n7、提倡生態保育，成立鳥類及時救援站。\n8、推動嘉義市觀光發展，串連嘉義山海景點。\n9、為嘉義市原住民及新住民爭取權益，保障基本生活。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
