INSERT INTO "fact" VALUES('profile:2022-local:p3a3151f609','p3a3151f609','profile','2022-11-26','{"education": ["東海大學政治學研究所碩\n士\n輔仁大學歷史學系\n嘉華高中\n輔仁中學\n大同國小"], "election": "2022-local", "experience": ["嘉義市議員(第九屆、第十屆)。\n啟思民本基金會董事。\n嘉義市不動產開發商公會榮譽顧問。\n嘉義市大同國小校友會常務理事。\n嘉義市家庭扶助中心委員。\n中國時報記者。"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
