INSERT INTO "fact" VALUES('platform:2022-local:p3de7517b5c','p3de7517b5c','platform','2022-11-26','{"district_id": "cyi-council-02", "election": "2022-local", "office": "cyi_councilor", "text": "1.推動老人長期照護升級版，減輕老人及家屬醫療負擔。\n2.推動安心成家，生育、托育、教育，無後顧之憂。\n3.爭取興建串聯高鐵、台鐵、森鐵，三鐵一條龍（台鐵支線）。\n4.推動西區大開發，建設為繁榮的嘉義新都心。\n5.爭取西區設立公立高中職。\n6.推動全民體育運動，更新場館設備，安全活動空間。\n7.爭取多功能全民科技電子競技館，發展電競科技。\n8.爭取產業園區，留住年青人在「嘉」，創造就業機會。\n9.推動政府大數據執行，提高行政效能，便民大躍進。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
