INSERT INTO "fact" VALUES('platform:2022-local:p4efc7647d0','p4efc7647d0','platform','2022-11-26','{"district_id": "cyi-council-02", "election": "2022-local", "office": "cyi_councilor", "text": "如何留下人才：近幾年回嘉創業青年不少，政府如何在合理適當的政策下，輔導以及給予資源。\n社會福利：在現有中央以及地方政府的政策下，設計更多適用於在地的配套，在兒少、長照、弱勢的部份可以受\n到更好的照顧。\n運動：每年在嘉義市舉辦許多全國賽事，如何將各單項運動統整打造一個運動季，也可以帶來許多經濟效益。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
