INSERT INTO "fact" VALUES('platform:2022-local:p76c5bcf4b8','p76c5bcf4b8','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "1.監督市政，為民喉舌，反映民意需求。\n2.推動優質科學教育，培育科技人才，與國際接軌。\n3.促進產業發展，策動工商投資，發展觀光旅遊。\n4.加速都更計畫，繁榮城市新願景。\n5.完善長照，老年安養計畫，保障婦幼權益。\n6.促進市民運動風氣，增進市民健康。\n7.推動嘉義市升級計畫，東區大進步，西區大發展。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
