INSERT INTO "fact" VALUES('platform:2022-local:p7d64f269fb','p7d64f269fb','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "1.堅持教育優先，推動雙語教學\n2.關心流浪毛小孩照護與安置\n3.提攜青年參與公眾事務\n4.協助青年就業與創業\n5.提升觀光亮點、支持經濟政策\n6.鼓勵新婚生育、提高補助及優化育兒環境\n7.推動公園2.0建設全齡親子遊戲場\n8.創造高齡友善、樂活空間\n9.治安、消防、交通設備升級，保障市民安全\n10.捍衛市民權利以市民利益優先", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
