INSERT INTO "fact" VALUES('platform:2022-local:pb8ec1541ab','pb8ec1541ab','platform','2022-11-26','{"district_id": "cyi-council-02", "election": "2022-local", "office": "cyi_councilor", "text": "1.維護性別平權，建構性別平等之服務設施與工作環境和機會。\n2.落實日照與長照政策，協助修法改善老人及弱勢族群安養問題。\n3.推動 e 政府再升級，強化簡政便民之政策。\n4.建立各項專業事務委外審查機制，提升行政效率。\n5.監督鐵路高架完工後，鐵路兩側都市縫合之規劃與執行工作之公平性與前瞻性。\n6.促進雲嘉嘉區域治理平台之運作，有效整合區域資源之分治與共享。\n7.催生市政府北棟大樓及西區國民運動中心早日動工。\n8.建立公有停車場離場自動感應扣款機制。\n9.推動紅瓦里、北新里及大溪里聯外道路改善工程，解決單線出入之交通問題。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
