INSERT INTO "fact" VALUES('platform:2022-local:pca1707192f','pca1707192f','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "「嘉倍幸福，一言為定」郭定緯以細膩、堅定態度，站在第一線，把關市政、挺身捍衛市民權益，讓嘉義更宜居、\n更幸福。\n●監督市政一定強：1.堅持理性問政，捍衛公益與市民權益。 2.專業嚴審預算，為市民荷包把關。\n●服務市民一定衝：1.勤奮走動基層，親力親為替市民發聲。\n●青年就業一定穩：1.放寬青年創業補助門檻，並發展創業募資平台，吸引青年回嘉創業。2.閒置公有地增建青年\n住宅，讓青年返鄉買得起房。\n●教育扎根一定好：1.推動嘉義市圖書總館，豐富城市精神食糧。2.增加重點體育學校經費，培植優秀體育選手。\n●文化傳承一定行：1.市內公園的主題串連，編織嘉義在地故事。\n●高齡照護一定優：1.閒置空間增設日照中心，創造友善銀髮城市。2.普設居家照護鈴，塑造老齡友善社區環境。\n●交通一定順：1.增加行人徒步區，擴大市區無障礙步行空間。2.增設自行車專用道，提高公共空間自行車停車設\n施。\n●生育一定安：1.提高生育津貼，並推動施行坐月子津貼。2.爭取增設公辦托育、幼兒園，落實社區保母優質化。\n●毛孩一定樂：1.爭取推動市立動物醫院，並規劃專屬寵物公園。2.增設公園狗便清潔箱，兼具美化與境教功能。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
