INSERT INTO "fact" VALUES('profile:2022-local:pce31a34873','pce31a34873','profile','2022-11-26','{"education": ["國立中正大學管理學院高\n階主管管理碩士"], "election": "2022-local", "experience": ["市議會第六～十屆議員、嘉鳳獅子會第八\n屆會長\n國際獅子會300D1區19～20年度總監\n鳳凰志工、警察志工第一中隊中隊長、體\n育會、商業會、工業會、不動產開發商業\n同業公會顧問、不動產仲介經紀商業同業\n公會、張廖簡姓宗親會、華商校友會、救\n難協會顧問、世明慈惠堂副主任委員、中\n正大學EMBA校友會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC2%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
INSERT INTO "fact" VALUES('bulletin:2022-local:pdd756d61b5','pdd756d61b5','bulletin','2022-11-26','{"district_id": "cyi-council-01", "elected": true, "election": "2022-local", "office": "cyi_councilor", "page": 1, "title": "2022 選舉公報"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
INSERT INTO "fact" VALUES('platform:2022-local:pdd756d61b5','pdd756d61b5','platform','2022-11-26','{"district_id": "cyi-council-01", "election": "2022-local", "office": "cyi_councilor", "text": "1.爭取廣設市立托嬰中心，提高幼兒教育補助；推動國中小校校有英語外師，同時外師至各公幼做共融式教學，\n強化學生國際觀的教育環境。\n2.推動社會住宅，讓無殼蝸牛有舒適便宜的住宅可以租賃。\n3.爭取置設青創基地，提供青年研究辦公室，提供迅速完整創業資訊，輔導青年創新創意及行銷通路，並協助青\n創貸款，讓年青人創業不是夢。\n4.督促市府儘速完成圖書總館的規劃設計及興建，並爭取新建一所圖書館多元化場域，讓市民有更豐富多元的休\n閒閱覽空間。\n5.打造嘉義市成為水漾城市，爭取八掌溪高灘地成為河濱公園，北排治理成嘉義柳川，南排爭取淨水廠，鹿寮排\n水及野溪整治為親水小溪。\n6.普查嘉義市各室內外場運動館所，升級設施器材活化利用，讓市民有好的運動環境，同時爭取運動競賽來嘉比\n賽，用運動經濟帶動本市經濟發展。\n7.營造嘉義市成為西部走廊的觀光消費新都心，行銷觀光軸帶並結合各宗教廟宇及博物館的文化底蘊，讓來嘉遊\n客盡情暢遊各觀光景點和品嚐地方小吃，帶動觀光業發展增加商機。\n8.爭取經費照顧身障團體及清寒家庭。\n9.親力親為全心服務做市民代言人，為市民爭建設謀福祉。", "title": "2022 選舉公報政見"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
INSERT INTO "fact" VALUES('profile:2022-local:pdd756d61b5','pdd756d61b5','profile','2022-11-26','{"education": ["中正大學公共與國際事務\n碩士\n南榮科技大學\n蘭潭國中\n民族國小"], "election": "2022-local", "experience": ["東川里里長 救國團東區委員會會長 籃\n球推廣協會理事長 嘉義家職家長會會長\n後指部東區輔導中心主任 警察志工大隊\n中隊長 東區扶輪社社長 諸羅山同濟會\n會長 嘉義市青創會理事長 中小企業跨\n業交流協會會長 文財殿附屬文通慈善會\n顧問 嘉義市消防局第二大隊顧問 諸羅\n山登山協會理事長"], "title": "2022 選舉公報學經歷"}','https://bulletin.cec.gov.tw/01%E9%81%B8%E8%88%89%E5%85%AC%E5%A0%B1/06%E7%B8%A3%E5%B8%82%E8%AD%B0%E5%93%A1/111%E5%B9%B4/22%E5%98%89%E7%BE%A9%E5%B8%82/%E5%98%89%E7%BE%A9%E5%B8%82%E7%AC%AC1%E9%81%B8%E8%88%89%E5%8D%80.pdf','2026-10-06T03:06:38Z');
