INSERT INTO "fact" VALUES('summary:14-03:pcb793ad399','pcb793ad399','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:29:12Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2066, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=18"}, {"page": 2068, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=20"}, {"page": 2068, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=20"}, {"page": 2072, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=24"}, {"page": 2070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=22"}, {"page": 2067, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=19"}, {"page": 2069, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=21"}], "councilor_points": ["何孟樺議員指出臺北市員警早餐與宵夜誤餐費 50 元難因應物價，要求比照本市消防局調高至 80 元。何孟樺議員表示外勤單位「謝老師」多為兼任且有管考同仁兼任情形，要求檢討減輕其業務負擔、避免研考同仁兼任。何孟樺議員建議擴增委外心理諮商機構，避免諮商人員與局內心輔委員重複。"], "response": "警察局局長表示因應物價水平，同意爭取將誤餐費調高。警察局局長說明「謝老師」主要負責轉介，是否由研考人員兼任授權各分局分配。警察局局長承諾將委外心理諮商機構預算提升至 93 萬元並擴增至 6 家，且未來會避免與局內心輔人員重複。", "response_removed": false, "topic": "員警福利與心理輔導機制"}, {"citations": [{"page": 852, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=60"}, {"page": 852, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=60"}, {"page": 853, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=61"}, {"page": 854, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=62"}, {"page": 854, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=62"}, {"page": 855, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=63"}, {"page": 856, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=64"}], "councilor_points": ["何孟樺議員指出臺北表演藝術中心成立 4 年未完備預防計畫，且處置職場霸凌案流程不符規範造成受害者二次傷害。何孟樺議員提出檢舉照片表示內部主管要求員工先打卡下班再加班，訴求文化局調查霸凌案並懲處疏失主管，且要求勞動局調查北藝中心與各局處之勞動條件。"], "response": "臺北表演藝術中心董事長說明「防範職場暴力預防計畫」已於 5 月 9 日公告，承認霸凌處理流程確實有疏失，並表示會了解打卡加班情事。文化局局長表示會派小組調查該案並於 2 星期內提供報告，勞動局局長表示將於 1 個月內彙整各局處檢討資料。臺北市市長表示會請文化局督導調查，並要求各局處檢視相關作為以符合法令規定。", "response_removed": false, "topic": "臺北表演藝術中心職場霸凌與勞動權益調查"}, {"citations": [{"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=68"}, {"page": 861, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=69"}, {"page": 861, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=69"}, {"page": 862, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=70"}, {"page": 863, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=71"}, {"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=68"}], "councilor_points": ["何孟樺議員指出偏心左轉專用道等道路改善工程涉及跨局處權責，新建工程處將大型工程認定為單一路口並要求交通管制工程處吸收經費，且各行政區作法不一。何孟樺議員要求市府檢討單一路口工程定義與跨局處預算劃分，並展示臺中市行人感應投射燈影片建議市府參考辦理。"], "response": "交通局局長說明緊急案件會動支預備金，明年交通管制工程處土木預算已編列雙倍，並表示會與工務局溝通及考察其他縣市作法。工務局局長說明新建工程處年度計畫與臨時性會勘案件之經費編列差異，同意重新討論預算劃分。臺北市市長表示會請兩局局長協調檢視，確保各行政區預算支出與標準一致。", "response_removed": false, "topic": "道路改善工程經費劃分與行人友善路口"}, {"citations": [{"page": 1403, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549C84D7A33DC66A831F841C0A7EC9C80DD8AE532E93ABA699BA852238F00A7C162#page=9"}, {"page": 1405, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549C84D7A33DC66A831F841C0A7EC9C80DD8AE532E93ABA699BA852238F00A7C162#page=11"}], "councilor_points": ["何孟樺議員指出國民教育法修正後規定校務會議應邀請學生代表列席，但本市國中 58 所中有 21 所未邀請、國小 148 所中有 106 所未邀請，私立學校亦未邀請。何孟樺議員要求教育局落實法規，並建議訂定國中學生自治運作注意事項、舉辦自治營隊及加強宣導高中社團活動經費補助計畫。"], "response": "教育局局長表示會向學校做最後確認並請未做到者依照國民教育法規定改善，承諾於 2 星期內提供報告。教育局中等教育科科長說明純國中約有 37 校有班聯會等自治組織。教育局局長對訂定學生自治指引與辦理國中自治營隊表示認同，並表示會加強宣導高中社團補助計畫且於 2 星期內提送報告。", "response_removed": false, "topic": "國中小學生自治與校務會議學生代表列席"}, {"citations": [{"page": 4160, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=24"}, {"page": 4161, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=25"}, {"page": 4161, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=25"}, {"page": 4162, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=26"}, {"page": 4163, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=27"}], "councilor_points": ["何孟樺議員指出台智光母約規範光纖建設、子約規範服務內容，終止子約 3 個月後於 7 月 8 日台智光有權斷網。何孟樺議員表示若斷網且備援系統未能及時完成，將導致全市 1 萬 8,000 支警用監視器無法即時監看，質疑短時間內無法完成設定，要求警察局與法務局於 1 個月內提出檢討報告。"], "response": "資訊局局長說明母約與子約之功能分工，並表示若斷網確實需更換 1 萬 8,000 支監視器之設備。法務局專門委員表示子約解約後將回歸母約規定解釋，台智光須繼續提供服務。警察局犯罪預防科科長表示正積極洽商廠商進行備援系統備標，絕不容許治安受到影響。", "response_removed": false, "topic": "台智光合約解約與警用監視器備援系統"}, {"citations": [{"page": 857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=65"}, {"page": 857, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=65"}, {"page": 858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=66"}, {"page": 860, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=68"}, {"page": 858, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=66"}, {"page": 859, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=67"}], "councilor_points": ["何孟樺議員詢問市府參與大阪世界博覽會之參展與露出計畫，指出市府先前缺乏相關規劃。何孟樺議員建議市府爭取與中央合作融入臺北元素、參與 SDGs 共創挑戰，並要求成立跨局處專案小組且於 2 星期內提送報告。"], "response": "臺北市市長說明已與大阪府知事表達相互宣傳世壯運與世博會意願，將研議行銷方式並向中央爭取設臺北館或跨局處合作。觀光傳播局局長表示已與大阪觀光局簽署合作交流協定書，承諾於 2 星期內提出行銷計畫報告。", "response_removed": false, "topic": "大阪世界博覽會參展與行銷規劃"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-22"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=54", "transcript_pages": [846, 847, 848, 849, 850, 851, 852, 853, 854, 855, 856, 857, 858, 859, 860, 861, 862, 863, 864], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162", "videos": [{"date": "2024-05-22", "group": 1}]}, {"dates": ["2024-04-11", "2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549C84D7A33DC66A831F841C0A7EC9C80DD8AE532E93ABA699BA852238F00A7C162#page=1", "transcript_pages": [1395, 1396, 1397, 1398, 1399, 1400, 1401, 1402, 1403, 1404, 1405, 1406], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=