INSERT INTO "fact" VALUES('summary:14-03:pa0224cb763','pa0224cb763','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:33:18Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2105, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=8"}, {"page": 2107, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=10"}, {"page": 2106, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=9"}], "councilor_points": ["劉耀仁議員指出雙北市為共同生活圈但資源回收規定不同，而臺北市資源回收入口網站僅有條列式文字，內容表達不清且難以檢索。劉耀仁議員指出臺北市資源回收網站查詢功能為六都最差，要求環保局與資訊局合作，於7月前設計親民且好查詢的網頁。劉耀仁議員亦指出部分物品在各縣市回收標準不一，建議市府向中央提議制定全國統一規範。"], "response": "環境保護局局長表示網頁查詢功能確實需要加強，承諾會與資訊局合作於7月前完成易於查詢的網頁。資訊局數位創新中心主任表示可以提供技術協助。環境保護局局長亦表示會向環境部請益，看是否能統一全國回收規範。", "response_removed": false, "topic": "資源回收分類資訊系統改善"}, {"citations": [{"page": 2101, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=4"}, {"page": 2099, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=2"}], "councilor_points": ["劉耀仁議員接獲民眾陳情，指出員警躲在民宅法定空地拍攝，並大鳴警笛追緝車速緩慢且僅未於停字停下的騎士，忽略周邊違規停車與未依規定兩段式開門等較嚴重違規。劉耀仁議員指出警方追緝600元罰鍰的輕微違規違反比例原則，且於私有法定空地埋伏並不適當，要求警察局光明正大執法。"], "response": "警察局局長表示認同不應追緝輕微違規，亦同意員警不應躲在隱密處執法。警察局局長承諾會調查該案並將影片作為教材教育員警，遵守取締的比例原則。", "response_removed": false, "topic": "警察交通執法方式與比例原則檢討"}, {"citations": [{"page": 4310, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=2"}, {"page": 4311, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=3"}, {"page": 4312, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=4"}, {"page": 4313, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=5"}, {"page": 4314, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=6"}, {"page": 4314, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=6"}], "councilor_points": ["劉耀仁議員指出友善店家每年僅審查1次，若外語員工離職或旅店易主容易產生資料未更新的空窗期，建議提高檢查密度。劉耀仁議員建議商業處推廣提供飲用水與親子友善項目，並要求提供日文及韓文網頁服務，以增加店家主動加入的吸引力。"], "response": "商業處處長說明目前每年進行1次現場查核，且已有72家友善店家加入提供飲用水服務。商業處處長表示會檢討查核密度、研究納入親子友善項目，並承諾於6月底前提供基本資料的日文與韓文翻譯服務。", "response_removed": false, "topic": "商業處友善店家審查與服務項目推廣"}, {"citations": [{"page": 1432, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=1"}, {"page": 1432, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=1"}, {"page": 1433, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=2"}, {"page": 1434, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=3"}, {"page": 1434, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=3"}], "councilor_points": ["劉耀仁議員播放影片舉發連鎖產後護理之家的保母粗暴餵奶虐嬰，並指出業者監視器畫面僅保存10天且有攝影死角，致衛生局稽查無功而返。劉耀仁議員要求市府保護吹哨者、澈底調查，並要求業者道歉認錯、加裝監視設備及保存監視畫面30天以上。"], "response": "臺北市市長表示衛生局與社會局會跨局處合作並確保吹哨者安全，若查證屬實必依法嚴辦。臺北市市長亦表示社會局會即刻召開專家學者會議並查證相關事證，依程序辦理。", "response_removed": false, "topic": "產後護理機構虐嬰疑雲稽查與吹哨者保護"}, {"citations": [{"page": 1613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549670D972AC45C8ECFF841C0A7EC9C80DD82F1E9548F9D5EAEA852238F00A7C162#page=3"}, {"page": 1615, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549670D972AC45C8ECFF841C0A7EC9C80DD82F1E9548F9D5EAEA852238F00A7C162#page=5"}, {"page": 1613, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549670D972AC45C8ECFF841C0A7EC9C80DD82F1E9548F9D5EAEA852238F00A7C162#page=3"}], "councilor_points": ["劉耀仁議員指出臺灣國中生每日平均睡眠7.3小時，支持延後到校政策以增加學生睡眠時間。劉耀仁議員表示教育局試辦8年僅有4所學校，要求教育局積極主動推廣並辦理親師投票，期許1年後能有50所學校跟進。"], "response": null, "response_removed": true, "topic": "國中小學延後到校政策推動"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 15, "heading": "市政總質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162#page=1", "transcript_pages": [1432, 1433, 1434, 1435, 1436, 1437, 1438, 1439, 1440, 1441, 1442], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162", "videos": [{"date": "2024-06-03", "group": 15}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 15, "heading": "教育部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549670D972AC45C8ECFF841C0A7EC9C80DD82F1E9548F9D5EAEA852238F00A7C162#page=1", "transcript_pages": [1611, 1612, 1613, 1614, 1615], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549670D972AC45C8ECFF841C0A7EC9C80DD82F1E9548F9D5EAEA852238F00A7C162", "videos": [{"date": "2024-04-16", "group": 15}]}, {"dates": ["2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 12, "heading": "交通部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AEBA5FD6989EE451E32A73AA014395A21C6DA2FD7D55F24BA852238F00A7C162#page=8", "transcript_pages": [748, 749, 750, 751, 752], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AEBA5FD6989EE451E32A73AA014395A21C6DA2FD7D55F24BA852238F00A7C162", "videos": [{"date": "2024-04-22", "group": 12}]}, {"dates": ["2024-04-30"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 15, "heading": "警政衛生部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162#page=1", "transcript_pages": [2098, 2099, 2100, 2101, 2102, 2103, 2104, 2105, 2106, 2107], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB963735665490A7D57FE842C409BC8F3EB37F6084FB2A9714155B7C9547AA852238F00A7C162", "videos": [{"date": "2024-04-30", "group": 15}]}, {"dates": ["2024-05-06"], "dept": "工務", "doc_type": "部門質詢", "group": 13, "heading": "工務部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490DCDE7D1D97AC50EA7CFEB403B94286AB3011EB597BEF928A852238F00A7C162#page=1", "transcript_pages": [2491, 2492, 2493, 2494], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490DCDE7D1D97AC50EA7CFEB403B94286AB3011EB597BEF928A852238F00A7C162", "videos": [{"date": "2024-05-06", "group": 13}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 4, "heading": "民政部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F132E27B0C2CCEBBBF5138F4A6D3BDF759E1970261F5D114A852238F00A7C162#page=1", "transcript_pages": [2736, 2737, 2738, 2739], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F132E27B0C2CCEBBBF5138F4A6D3BDF759E1970261F5D114A852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 4}]}, {"dates": ["2024-05-20"], "dept": "財政建設", "doc_type": "部門質詢", "group": 13, "heading": "財政建設部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162#page=1", "transcript_pages": [4309, 4310, 4311, 4312, 4313, 4314], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665496738051AC0527AB170E5A010D15A9D88A22CB845116E372CA852238F00A7C162", "videos": [{"date": "2024-05-20", "group": 13}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665496177374A0C6B9DEFE03B6E5770853646202CDA3E15EB97CFA852238F00A7C162','2026-10-05T06:33:18Z');
INSERT INTO "fact" VALUES('summary:14-03:p4b727b88dc','p4b727b88dc','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:34:44Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4350, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=25"}, {"page": 4351, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=26"}, {"page": 4356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=31"}, {"page": 4357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=32"}, {"page": 4358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=33"}, {"page": 4348, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=23"}, {"page": 4349, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=24"}, {"page": 4356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=31"}], "councilor_points": ["吳世正議員指出動物之家的貓狗籠舍空間過小、未鋪設貓砂與墊子，且大型犬隻與貓隻生活環境欠佳，要求動物保護處改善收容設施並妥善運用志工人力。吳世正議員表示臺北市已明令禁止捕獸鋏，要求動物保護處加強源頭管理、宣導地主責任並加強巡查網路電商平台。"], "response": "動物保護處處長表示會盤點動物籠舍狀況並檢討改善，下半年將完成移交汰換貓籠，並持續採購籠舍與宣導違法捕獸鋏規定。動物救援隊隊長說明已針對捕獸鋏採加強源頭管理，向可能販售的五金行業者與農戶宣導，並每週巡查網路平台。", "response_removed": false, "topic": "動物之家收容環境改善與捕獸鋏查處"}, {"citations": [{"page": 1266, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=42"}, {"page": 1267, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=43"}, {"page": 1267, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=43"}, {"page": 1268, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=44"}, {"page": 1270, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=46"}, {"page": 1270, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=46"}, {"page": 1268, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=44"}, {"page": 1272, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=48"}], "councilor_points": ["吳世正議員指出前市府時期停招技工導致工務單位正職人力縮減，並大量增加約聘與委外人力，造成緊急災害時外包人力無法派動、正職技工負擔過重。吳世正議員要求市府補齊工務單位編制內正職人力，並儘快發放公園路燈工程管理處基層員工因緊急搶災積欠的加班費及准予補假。"], "response": "市長表示人力不足確實是現實問題，依法該給予的加班費會按照規定程序儘快發給，並請工務局局長儘快瞭解處理。工務局局長表示會趕快來處理加班費問題。", "response_removed": false, "topic": "工務單位編制人力與外包制度檢討"}, {"citations": [{"page": 2410, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=2"}, {"page": 2410, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=2"}, {"page": 2415, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=7"}, {"page": 2415, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=7"}], "councilor_points": ["吳世正議員詢問參事情前市府任內北投士林科技園區招商條件調整及京華城容積獎勵案的交辦過程，指出市府曾召開會議調降囤房稅並將北士科基地拆分且放寬產業限制。吳世正議員質疑這些決策涉有圖利疑慮，要求官員至檢調或議會調查委員會說明清楚。"], "response": "參事表示北士科採公開招標拆分基地是經促參會決議以吸引更多廠商投標，過程合規且自己有信心沒有圖利，並說明自己絕對沒有參與京華城案。", "response_removed": false, "topic": "前市府土地開發及容積獎勵案檢討"}, {"citations": [{"page": 620, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=22"}, {"page": 620, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=22"}, {"page": 623, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=25"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=27"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=27"}, {"page": 625, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=27"}, {"page": 621, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=23"}, {"page": 624, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=26"}], "councilor_points": ["吳世正議員指出自行車與行人發生的交通事故增加，要求交通局重視人車分道，勿再推動窄路人車共道，並要求警察局加強取締自行車侵犯人行道。吳世正議員表示臺北市兒童交通事故死傷創新高，建議參考日本經驗設置低位置交通警示設施、推廣通學道及加強校園安全宣導。"], "response": "交通局局長說明會朝人車分道方向努力，工程上儘量分隔人行道與自行車道，並透過教育及警察取締加強管理。警察局交通警察大隊大隊長表示已訂定事故防治計畫，會針對違規行駛人行道與自行車違規加強執法。", "response_removed": false, "topic": "行人與兒童交通安全防護措施"}, {"citations": [{"page": 2914, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=11"}, {"page": 2916, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=13"}, {"page": 2915, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=12"}], "councilor_points": ["吳世正議員指出市政大樓中央南區五至七樓廁所施工長達三個月，且將原本的身障廁所拆除改為親子廁所，造成身障員工不便。吳世正議員表示後續二次修改仍不符合無障礙設施規範，門開關困難且內部空間過小輪椅無法迴轉，要求市府檢討改善流程並於一個月內恢復符合標準的身障廁所。"], "response": "市政大樓公共事務管理中心主任表示依規定每三層樓需設置一處親子廁所，將會優先改善七樓部分，並承諾於一個月內改善完畢，未來施工前會先調查員工需求。", "response_removed": false, "topic": "市政大樓無障礙廁所改建工程檢討"}, {"citations": [{"page": 1275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=51"}, {"page": 1593, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=9"}, {"page": 1594, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=10"}], "councilor_points": ["吳世正議員指出許多中小學生未吃早餐或食物營養不均衡，影響發育與學習效率，建議教育局調查家長意願並訂定章程補助學校提供營養早餐。吳世正議員表示可參考國外提供免費或補助早餐做法，對一般學生酌收費用、弱勢學生免費，建立全面性制度。"], "response": "教育局局長表示目前針對弱勢學生提供早餐補助，針對非弱勢學生部分會與學校研究掌握狀況，並研議相關做法。市長表示早餐非常重要。", "response_removed": false, "topic": "中小學生營養早餐政策試辦與研議"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-28"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=41", "transcript_pages": [1265, 1266, 1267, 1268, 1270, 1271, 1272, 1273, 1274, 1275], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162", "videos": [{"date": "2024-05-28", "group": 10}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=8", "transcript_pages": [1592, 1593, 1594, 1595, 1596, 1597, 1598], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162", "videos": [{"date": "2024-04-16", "group": 14}]}, {"dates": ["2024-04-19"], "dept": "交通", "doc_type"