 2917, 2918, 2919, 2920, 2921, 2922], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162", "videos": [{"date": "2024-05-13", "group": 12}]}, {"dates": ["2024-05-21"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=21", "transcript_pages": [4346, 4347, 4348, 4349, 4350, 4351, 4352, 4353, 4354, 4355, 4356, 4357, 4358], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162", "videos": [{"date": "2024-05-21", "group": 14}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162','2026-10-05T06:34:44Z');
INSERT INTO "fact" VALUES('summary:14-03:pefa8e31df3','pefa8e31df3','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:36:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1082, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=41"}, {"page": 1084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=43"}, {"page": 1085, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=44"}, {"page": 1085, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=44"}, {"page": 2487, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=18"}, {"page": 1084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=43"}, {"page": 2486, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=17"}, {"page": 1083, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=42"}], "councilor_points": ["吳志剛議員指出南機場 13 號基地都更案因財政局不出資且住戶信託借款無法達百分之百，若市府不協助恐致都更失敗，並質疑轉為公辦都更會耗時且減少獎勵。吳志剛議員建議市府評估由社宅基金或都更基金編列費用出資，或採用地主先行墊付資金、拆屋後市府再撥款等替代方案。吳志剛議員要求市府站在市民角度思考，儘快提出解決方案以推動都更。"], "response": "都市更新處處長說明，市府出資四十多億元有困難，且自治會傾向自主都更並拒絕公辦都更，市府將持續溝通並協助尋找金融機構融資貸款。市長表示，大地震後以居住安全為重，希望住戶轉變思維，市府會加速審查程序並積極提供各項行政協助。財政局非公用財產開發科科長表示，市有土地參與都更過往係採權利變換折價抵付，會持續與更新會溝通協調可行方案。", "response_removed": false, "topic": "南機場 13 號基地都市更新案"}, {"citations": [{"page": 732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=17"}, {"page": 732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=17"}, {"page": 733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=18"}], "councilor_points": ["吳志剛議員詢問因應《行人交通安全設施條例》三讀通過，市府對於機車退出騎樓、劃設機車格及排除變電箱等障礙物之配套措施。吳志剛議員指出標線型人行道若遇號誌或燈柱應妥善移設，並建議引進行人觸動號誌按鈕及感應敬老卡延長綠燈秒數等科技設備。吳志剛議員要求市府做好整體規劃與配套措施，勿「先射箭再畫靶」或「為了做而做」。"], "response": "交通局局長說明，市府已跨局處協商分工落實中央法令，將以機車澈底離開人行道為終極目標，並透去除障礙物及規劃替代停車空間等方式打造行人友善環境。停車管理工程處處長補充，將優先針對主要幹道執行機車退出騎樓與人行道，並透過秩序整理與增加路外停車位處理機車停放問題。交通管制工程處處長說明，臺北市已於十幾個路口設置按鈕式延長秒數，並於 45 個路口提供感應式延長秒數服務，未來會逐步推廣至老人較多及醫院附近的區域。", "response_removed": false, "topic": "行人交通安全設施條例與通行環境改善"}, {"citations": [{"page": 1090, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=49"}, {"page": 1456, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=13"}, {"page": 1457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=14"}, {"page": 1458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=15"}, {"page": 1458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=15"}, {"page": 1457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=14"}], "councilor_points": ["吳志剛議員詢問青草巷頂棚會勘結論與處理進度，指出該頂棚因缺乏使用執照且權責機關未定，致使長期無法修繕並存在漏水問題。吳志剛議員表示樂見將頂棚納入文化資產附屬設施，但擔心審議與施工流程曠日廢時，要求市府儘快跨局處協調處置。"], "response": "文化局文化資產科科長說明，調查研究與會勘確認頂棚最早影像為民國 88 年，文資委員一致同意納入文化資產再利用必要設施，確立其非違建身分，未來由主管單位編列預算維護。文化局局長補充說明，確認身分後即可提送專案小組處理，承諾會儘快在府內跨局處確定後續作法並回報進度。新建工程處副總工程司說明，新工處已於去年 5 月 25 日完成短期協助修繕，長期處理將配合文化局規劃進行辦理。", "response_removed": false, "topic": "艋舺龍山寺青草巷頂棚納入文化資產附屬設施"}, {"citations": [{"page": 1086, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=45"}, {"page": 1086, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=45"}, {"page": 1087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=46"}, {"page": 1087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=46"}, {"page": 1088, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=47"}], "councilor_points": ["吳志剛議員指出臺北市國小與國中棒球隊實力雄厚，但升高中後優秀選手常被外縣市傳統強校挖走，詢問市府改善棒球環境與留育人才之作法。吳志剛議員關切學雜費與競賽獎勵措施，並詢問是否可能研擬針對未留任臺北市升學之選手收回獎補助金的機制。"], "response": "教育局局長說明，市府每年編列約 1,500 多萬元補助棒壘球重點學校，單校最高可獲 100 萬元，並已提高外縣市參賽及出國培訓補助，同時管控招生員額以吸引並留下優秀選手。市長表示，傾向透過正面鼓勵與政策誘因留住人才，將擬定中長期計畫改善訓練環境、師資與銜接管道，協助選手看見未來發展願景。", "response_removed": false, "topic": "臺北市三級棒球選手留育與政策獎勵"}, {"citations": [{"page": 1458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=15"}, {"page": 1459, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=16"}, {"page": 1460, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=17"}, {"page": 1460, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=17"}, {"page": 1461, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=18"}], "councilor_points": ["吳志剛議員關切臺北市受保護樹木之查核人力與測量機制，指出鄰地外推 3 公尺保護範圍若涉及私人土地，民眾無法自行進去測量。吳志剛議員建議文化局應主動介入協助，派具公權力之人員前往私人土地測量，並注意 Google 街景圖資可能存在時間差與未獲政府認證之問題。"], "response": "文化局文化資源科科長說明，文化局現有 4 名兼辦人力負責相關業務，若鄰地無法進入測量，可先由基地內拍照確認，若有疑慮會派技師到現場量測。文化局局長表示，若民眾有私人土地測量疑慮，文化局身為公部門理應協助，會以空照圖補充並派員至現場實地查看，亦會在機制上明確告知市民申請流程。", "response_removed": false, "topic": "受保護樹木鄰地測量與維護機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=41", "transcript_pages": [1082, 1083, 1084, 1085, 1086, 1087, 1088, 1089, 1090], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162", "videos": [{"date": "2024-05-27", "group": 8}]}, {"dates": ["2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 7, "heading": "教育部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=13", "transcript_pages": [1456, 1457, 1458, 1459, 1460, 1461], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162", "videos": [{"date": "2024-04-12", "group": 7}]}, {"dates": ["2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=14", "transcript_pages": [729, 730, 731, 732, 733, 734], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162", "videos": [{"date": "2024-04-22", "group": 11}]}, {"dates": ["2024-04-26"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 8, "heading": "警政衛生部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=1", "transcript_pages": [1922, 1923, 1924, 1925, 1926], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162", "videos": [{"date": "2024-04-26", "group": 8}]}, {"dates": ["2024-05-06"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=16", "transcript_pages": [2485, 2486, 2487, 2488, 2489, 2490], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162", "videos": [{"date": "2024-05-06", "group": 12}]}, {"dates": ["2024-05-14"], "dept": "民政", "doc_type": "部門質詢", "group": 15, "heading": "民政部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162#page=27", "transcript_pages": [3025, 3026], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162", "videos": [{"date": "2024-05-14", "group": 15}]}, {"dates": ["2024-05-20"], "dept": "財政建設", "doc_type": "部門質詢", "group": 12, "heading": "財政建設部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B4FBD88C72B8BE4C6F779CF2C4016EE4BBB97C0BA4BEE7E7A852238F00A7C162#page=7", "transcript_pages": [4295, 4296, 4297, 4298, 4299, 4300, 4301], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B4FBD88C72B8BE4C6F779CF2C4016EE4BBB97C0BA4BEE7E7A852238F00A7C162", "videos": [{"date": "2024-05-20", "group": 12}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162','2026-10-05T06:36:19Z');
INSERT INTO "fact" VALUES('summary:14-03:p155e15fe02','p155e15fe02','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:38:19Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=3"}, {"page": 1457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=3"}, {"page": 1470, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=16"}, {"page": 1471, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=17"}, {"page": 1472, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=18"}, {"page": 1473, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=19"}, {"page": 1474, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=20"}, {"page": 1475, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=21"}], "councilor_points": ["張志豪議員指出市長曾承諾於115年前將消防服務人口比提升至1比1,000，並關心消防員組工會之進度。張志豪議員建議市府主動查核高樓建築管道間之防火填塞，並針對救災通訊研議併用UHF頻率與移動式中繼設備。張志豪議員要求市府結合能量研發救災定位系統，並增加熱顯像儀配備數量與通盤檢討安全官制度之SOP。"], "response": "市長說明會持續向中央溝通消防員額與危險加給，並正面看待且支持消防員組工會。建築管理工程處處長與消防局局長說明將找公會討論落實方式，並規劃主動檢視與稽查方案。消防局局長表示會研議評估UHF系統、行動中繼臺及救災定位系統，並持續編列預算更新熱顯像儀，且承諾於1個月內提供安全官SOP。", "response_removed": false, "topic": "消防人員員額與救災安全保障"}, {"citations": [{"page": 1496, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=42"}, {"page": 1498, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=44"}, {"page": 2558, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=14"}, {"page": 2559, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=15"}, {"page": 2560, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=16"}, {"page": 2560, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=16"}, {"page": 2562, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=18"}, {"page": 2562, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=18"}, {"page": 2563, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=19"}, {"page": 1498, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=44"}, {"page": 1501, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=47"}, {"page": 2561, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=17"}], "councilor_points": ["張志豪議員詢問防災型都更與「575專案」之申請與列管狀況，建議市府向民眾說明都更「1坪換1坪」需經科學計算，避免過高期待延遲都更推動。張志豪議員建議建立都更線上查詢平臺與專責單一窗口，以提供民眾專業諮詢、技術支援及法律協助。張志豪議員指出應解決1樓店面與頂樓違建參與都更之利益折衷問題，並要求市府妥善規劃中繼住宅以照顧弱勢租屋戶。"], "response": "市長表示會加強宣導防災型都更，並主動協助列管之高氯離子建築了解專案，亦同意研議成立都更諮詢平臺與運用人工智慧加速回覆。都市更新處處長說明防災型都更已有2件申請達門檻，並表示會在宣導會中說明都更計算原則，且儘力協助個案進行。都市發展局局長說明將持續滾動式檢討改善都更方案，並研訂社會住宅控留中繼住宅之計畫。", "response_removed": false, "topic": "都市更新政策與推動機制改善"}, {"citations": [{"page": 1501, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=47"}, {"page": 1502, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=48"}, {"page": 2566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=22"}, {"page": 4196, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=2"}, {"page": 4196, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=2"}, {"page": 4197, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=3"}, {"page": 1503, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=49"}, {"page": 4198, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=4"}, {"page": 4199, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=5"}, {"page": 4200, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=6"}], "councilor_points": ["張志豪議員指出木新市場改建與中繼市場選址引發地方爭議，質疑市府欠缺地震後結構安全評估與量化之坪效公共價值分析。張志豪議員表示中繼市場選址評分機制未能平息民眾質疑，建議優先評估建造與時間等成本，並調查周邊里民需求與回饋方案。張志豪議員要求市府檢討溝通順序與邏輯，並於2周內重新評估期程與應辦事項。"], "response": "市長說明目前以實踐國中停車場為較理想中繼點，承諾會由相關局處規劃方案並加強與里長、居民及學校溝通。市場處處長說明木新市場1樓與2樓建造年份不同且2樓有海砂問題導致分歧，並說明評分表係為量化評定，承諾於2周內提出檢討與重新評估報告。產業發展局局長表示會檢討溝通事宜，並承諾針對潛在場地與周邊里長及市民溝通退場後貼近地方需求之使用。", "response_removed": false, "topic": "木新市場改建與中繼市場選址溝通"}, {"citations": [{"page": 1643, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=18"}, {"page": 663, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=17"}, {"page": 664, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=18"}, {"page": 665, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=19"}, {"page": 668, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=22"}, {"page": 669, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=23"}, {"page": 669, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=23"}, {"page": 665, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=19"}], "councilor_points": ["張志豪議員指出文山區樟新里、樟腳里與木新里巷弄交通事故率高，要求交通局針對住宅區巷弄與學校、托育機構周邊提出行人用路改善方案。張志豪議員指出興隆路三段185巷口於110年至112年間發生15件A2交通事故，已達設置號誌標準，要求市府主動盤點未設置號誌路口並擬定年度設置計畫。張志豪議員指出路邊計次停車格遭特定車輛跨日佔用，要求停管處推動全市路邊停車格智慧化管理與費率檢討，並於會期結束前提出改善報告。"], "response": "交通局局長表示會針對學校通學步道主動會勘，並承諾於本會期結束前就文山區河岸3里巷弄提出用路改善規劃。交通管制工程處處長說明興隆路三段185巷口符合設置號誌標準，會於1星期內答覆，並承諾初擬計畫每年檢討增設號誌。停車管理工程處處長表示會檢討修正費率，並承諾最晚於明年呈現所有停車格資訊，且在本會期結束前提出具體改善報告。", "response_removed": false, "topic": "住宅區巷弄交通安全與停車格管理"}, {"citations": [{"page": 1505, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=51"}, {"page": 1634, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=9"}, {"page": 1636, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=11"}, {"page": 1636, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=11"}, {"page": 1635, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=10"}], "councilor_points": ["張志豪議員指出學生自殺自傷問題與校園霸凌相關，並舉出4個實例說明教職員常因個人判斷而未於知悉或疑似霸凌時之24小時內通報。張志豪議員要求教育局對所有學校明確定義性平與霸凌事件，以案例宣導方式讓師生及家長了解霸凌定義，並加速案件處理量能。張志豪議員要求教育局於1星期內提出將上述訴求落實之檢討報告。"], "response": "教育局局長說明學校執行通報時可能加入自我判斷而致誤判或延遲，並認同應由專業團隊處理以保護學生與教師。教育局學務校安室主任說明每個月均有提醒各校依規定於疑似案件時即進行通報。教育局局長表示同意明確定義知悉即通報、採案例宣導及加速處理速度，並承諾於1星期內提交報告。", "response_removed": false, "topic": "校園霸凌定義與通報機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 16, "heading": "市政總質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=1", "transcript_pages": [1455, 1456, 1457, 1458, 1469, 1470, 1471, 1472, 1473, 1474, 1475, 1476, 1496, 1497, 1498, 1499, 1500, 1501, 1502, 1503, 1504, 1505], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162", "videos": [{"date": "2024-06-03", "group": 16}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=9", "transcript_pages": [1634, 1635, 1636, 1637, 1638, 1639, 1640, 1641, 1642, 1643], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162", 