07018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=14", "transcript_pages": [2558, 2559, 2560, 2561, 2562, 2563, 2564, 2565, 2566], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 16}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=1", "transcript_pages": [4195, 4196, 4197, 4198, 4199, 4200, 4201, 4202], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162','2026-10-05T06:38:19Z');
INSERT INTO "fact" VALUES('summary:14-03:p499663cb96','p499663cb96','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:39:57Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 834, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=42"}, {"page": 836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=44"}, {"page": 836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=44"}, {"page": 837, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=45"}, {"page": 838, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=46"}, {"page": 839, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=47"}, {"page": 838, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=46"}, {"page": 840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=48"}], "councilor_points": ["張文潔議員詢問臺北市幼兒園與高級中等以下學校因腸病毒停班的狀況，並指出現行腸病毒疫苗 2 劑費用約 1 萬元，關切市府是否提供費用補助。張文潔議員指出臺北市為「領頭羊」，建議除了低收入戶幼童外，亦應考量將一般家庭幼童納入腸病毒疫苗費用補助，並詢問衛生局針對 5 月與 6 月腸病毒流行高峰期的稽查機制。張文潔議員指出班級因腸病毒停課時雙薪家庭面臨照顧與臨托保母媒合困難，要求市府研擬更嚴密的因應計畫。"], "response": "衛生局局長說明臺北市因腸病毒停班有 117 班，預計 6 月中開始提供低收入戶與第二類兒童醫療補助資格幼兒施打腸病毒疫苗，並承諾 2 週內提出將一般家庭納入補助的評估報告。衛生局局長表示 5 月與 6 月已重新啟動一波查核，並非不查核，會再提供更精確的資料。社會局局長表示會透過居家托育服務中心協助媒合保母，並承諾於 2 週內研擬因應計畫。", "response_removed": false, "topic": "幼兒腸病毒防治與疫苗補助"}, {"citations": [{"page": 840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=48"}, {"page": 840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=48"}, {"page": 841, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=49"}, {"page": 842, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=50"}, {"page": 842, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=50"}, {"page": 843, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=51"}, {"page": 844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=52"}, {"page": 844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=52"}, {"page": 845, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=53"}], "councilor_points": ["張文潔議員詢問好孕 2U 專車核發人次與趟次，指出目標服務申請率 60% 偏低，並反映台北市支付介面僅能透過台北通造成使用不便，建議提供多元支付管道與提高補助金額。張文潔議員建議將好孕專車使用期限敘述由「預產期」修正為「生產日後 6 個月內」，並要求市府於醫療院所與診所周邊設置婦幼專屬停車格或共用臨停區。張文潔議員詢問「臺北市政府管理到府坐月子服務機構作業要點」停止適用原因，建議建立產後坐月子到宅服務媒合平台，並探討增設「婦幼發展局」之可行性。"], "response": "社會局局長表示會與資訊局研究多元支付。市長表示使用率已達 70%，同意將文字說明修正為生產後 6 個月，並承諾 1 個月內研議規劃醫療院所周邊臨停區。衛生局局長承諾 2 星期內了解坐月子要點停止原因並向議員報告；市長表示會研究坐月子媒合平台，並說明婦幼相關政策目前推行順利。", "response_removed": false, "topic": "好孕2U專車服務與婦幼政策改善"}, {"citations": [{"page": 830, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=38"}, {"page": 831, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=39"}, {"page": 832, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=40"}, {"page": 833, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=41"}, {"page": 831, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=39"}], "councilor_points": ["張文潔議員指出廣慈托嬰中心托育人員使用不具避震功能的嬰兒床將幼童推至戶外硬鋪面路面，且讓幼童在堅硬磁磚地面爬行，質疑公托設備安全性與防疫問題。張文潔議員要求市府對全臺北市 83 間公立托嬰中心進行全面性檢視，並提供補助金讓公托添購合格的多人座嬰幼兒推車等設備。張文潔議員要求市府於 1 個月內完成全臺北市公托中心的檢查與設備添購。"], "response": "社會局局長說明嬰兒床僅能於室內或緊急逃難時使用，表示托育人員不應方便行事，承諾會要求廣慈托嬰中心嚴格改進並了解戶外爬行狀況。市長與社會局局長表示會對廣慈托嬰中心做改進，並承諾以 1 個月時間將臺北市內 83 家托嬰中心做一次全面檢視。", "response_removed": false, "topic": "廣慈托嬰中心設備缺失與公托設施檢視"}, {"citations": [{"page": 4151, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=15"}, {"page": 4152, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=16"}, {"page": 4150, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=14"}], "councilor_points": ["張文潔議員肯定動保處增加 206 處公有場域寵物友善空間，並詢問捷運寵物友善列車上隨車寵物訓練師與獸醫師之配置人數與實際功能。張文潔議員指出列車應融入動物教育功能，加強對飼主與一般乘客的宣導，並建議調查參加者意見及建立沿線配合之動物醫院緊急醫療配套。"], "response": "動物保護處處長說明公有場域寵物友善空間已公告於網路，並表示寵物友善列車上配置獸醫師 1 位及寵物訓練師 1 位提供諮詢。動物保護處處長表示會接受建議將教育方向納入考量，並承諾於 1 個月內研議相關配套措施。", "response_removed": false, "topic": "捷運寵物友善列車配套措施與動物教育"}, {"citations": [{"page": 2660, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=6"}, {"page": 2661, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=7"}, {"page": 2662, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=8"}, {"page": 2664, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=10"}, {"page": 2663, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=9"}], "councilor_points": ["張文潔議員關切剴剴案發生的原因，指出居托中心訪視紀錄與兒盟紀錄存有落差，且未落實脆弱家庭跨轄資訊掌握與不定期訪視。張文潔議員表示不應因「一粒老鼠屎、壞了一鍋粥」而打擊全體保母，要求社會局針對全臺北市 4,200 多位合格保母建立長久的獎勵機制，關懷並肯定優良保母。"], "response": "社會局局長說明去年調查成案且違反兒少法之保母有 4 案，並表示將檢討建立跨轄資料分享與三方共訪機制。社會局局長表示會提供保母更多資源，並研議建立家長推薦平台與優良保母獎勵機制。", "response_removed": false, "topic": "剴剴案後續檢討與居家托育訪視機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-22"], "dept": null, "doc_type": "市政總質詢", "group": 1, "heading": "市政總質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162#page=32", "transcript_pages": [824, 825, 826, 827, 828, 829, 830, 831, 832, 833, 834, 835, 836, 837, 838, 839, 840, 841, 842, 843, 844, 845, 846], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162", "videos": [{"date": "2024-05-22", "group": 1}]}, {"dates": ["2024-04-11", "2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 5, "heading": "教育部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549C84D7A33DC66A831F841C0A7EC9C80DD8AE532E93ABA699BA852238F00A7C162#page=24", "transcript_pages": [1418, 1419, 1420, 1421, 1422, 1423, 1424, 1425], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549C84D7A33DC66A831F841C0A7EC9C80DD8AE532E93ABA699BA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 5}, {"date": "2024-04-12", "group": 5}]}, {"dates": ["2024-04-23"], "dept": "交通", "doc_type": "部門質詢", "group": 15, "heading": "交通部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549732D46B642F6641967C30A734F11702A5EFBA1A1FEEE1013A852238F00A7C162#page=1", "transcript_pages": [791, 792, 793, 794, 795, 796, 797, 798, 799, 800, 801, 802, 803], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549732D46B642F6641967C30A734F11702A5EFBA1A1FEEE1013A852238F00A7C162", "videos": [{"date": "2024-04-23", "group": 15}]}, {"dates": ["2024-04-29"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 13, "heading": "警政衛生部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162#page=8", "transcript_pages": [2056, 2057, 2058, 2059, 2060, 2061, 2062, 2063, 2064, 2065], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549CE2A4F75364A0F324C0941704114BAAA9D75432D4AA980E6A852238F00A7C162", "videos": [{"date": "2024-04-29", "group": 13}]}, {"dates": ["2024-05-07"], "dept": "工務", "doc_type": "部門質詢", "group": 15, "heading": "工務部門質詢第15組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494D0ACB1BF5AF7A0100B08304483B87211D87057054F19684A852238F00A7C162#page=23", "transcript_pages": [2541, 2542, 2543, 2544], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494D0ACB1BF5AF7A0100B08304483B87211D87057054F19684A852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 15}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 1, "heading": "民政部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162#page=1", "transcript_pages": [2655, 2656, 2657, 2658, 2659, 2660, 2661, 2662, 2663, 2664, 2665], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665494600EB22D6F80F9753D5313F25E58EEC95ED375F243F96ACA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 1}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 5, "heading": "財政建設部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162#page=11", "transcript_pages": [4147, 4148, 4149, 4150, 4151, 4152, 4153, 4154, 4155, 4156, 4157, 4158, 4159], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654928EBDDA948CD3AF5338524E561A19BCB31D3E63783F923F1A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 5}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549F874AF7B5ECF01BACF4D34A819B580737EB00290ECCCB859A852238F00A7C162','2026-10-05T06:39:57Z');
INSERT INTO "fact" VALUES('summary:14-03:p62ab44979e','p62ab44979e','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:03:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2303, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=6"}, {"page": 2864, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=1"}, {"page": 2865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=2"}, {"page": 2865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=2"}, {"page": 2866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=3"}, {"page": 2867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=4"}, {"page": 2868, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=5"}, {"page": 2869, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=6"}], "councilor_points": ["徐立信議員指出艋舺公園周邊街友聚集與環境髒亂引發里民陳情，詢問社會局局長如何輔導街友重返社會與自力更生。徐立信議員表示地方反映街友問題與隨地大小便、亂丟垃圾情形嚴重，要求環保局在一星期內加強稽查取締與環境改善。徐立信議員建議禁止現場發放便當以避免環境惡化，並要求社會局主動發文邀請商圈參與好食堂愛心便當捐助專案。"], "response": "社會局局長說明市府已推動跨局處合作與就業支持，並表示將與警方聯合取締現場發放便當，同時推廣好食堂愛心餐機制。環保局環境清潔管理科科長說明每日皆有安排路面清潔，並承諾在一星期內針對重點地點加強稽查取締與路面清洗。", "response_removed": false, "topic": "街友輔導安置與艋舺公園周邊環境改善"}, {"citations": [{"page": 1813, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=1"}, {"page": 1814, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=2"}, {"page": 1814, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=2"}, {"page": 1817, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=5"}], "councilor_points": ["徐立信議員指出有員警前往現場處理案件時未清楚表明所屬分局與事由，致使當事人產生疑慮，詢問警察局局長相關偵辦程序是否合乎規定。徐立信議員指出員警未先透過公開文件查證債務狀況，且在債務人提及希望減額100萬元時未即時阻止，建議警方優辦偵查技巧並避免非必要擾民。"], "response": "警察局局長說明該案係奉臺北地檢署檢察官指揮查訪，員警現場有出示證件表明身分。警察局局長表示未來員警在偵查案件時應更清楚表達案件起源，並同意在偵查方式與執法溝通層面上會再檢討精進與優化。", "response_removed": false, "topic": "員警偵辦案件程序與溝通檢討"}, {"citations": [{"page": 1818, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=6"}, {"page": 2298, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=1"}, {"page": 2299, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=2"}, {"page": 2300, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=3"}, {"page": 2300, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=3"}, {"page": 2301, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=4"}], "councilor_points": ["徐立信議員指出位於金山南路與濟南路口的建築基地拆除工程停擺近1年，僅拆至1樓至3樓即停工，導致周邊人行道被占用且環境雜亂，詢問相關執照期限規定。徐立信議員表示拆除與新建執照併案導致工期長達70多個月，要求市府釐清停工原因並對未善盡維護責任的建商依法要求改善及裁罰。"], "response": "建築管理工程處處長說明該案為拆除執照與建造執照併案申請，故建築期限回歸建造執照計算。建築管理工程處處長表示會儘速聯絡起造人了解暫停施工原因，並要求建商改善工地現況與維護公共安全，若限期未改善將依建築法相關法規裁罰。", "response_removed": false, "topic": "建築物拆除工程停工與周邊安全維護"}, {"citations": [{"page": 921, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162#page=2"}, {"page": 922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162#page=3"}, {"page": 923, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162#page=4"}, {"page": 920, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162#page=1"}], "councilor_points": ["徐立信議員播放影片指出警方辦案追捕嫌犯時翻牆進入民宅，造成房屋門鎖與家具毀損並留下血跡，且事後未即時告知屋主及做善後處理，詢問執法程序是否適當。徐立信議員要求市府針對類似案件建立SOP，規定若因執法破壞民宅或造成鄰損應立即處理與賠償。"], "response": "市長說明警察局會深入調查個案並釐清執行過程是否符合SOP及執法有無過當，並承諾請警察局研議建立破壞民宅及鄰損處理的SOP。警察局代理局長說明員警係持拘票執行追捕，表示搜捕過程有精進空間，警方會盡快聯絡屋主並承擔負責賠償責任。", "response_removed": false, "topic": "警方搜捕嫌犯侵入民宅與損壞處置"}, {"citations": [{"page": 4086, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549815E79A9E99C36C2AE45A062B585EDF633024D8627543783A852238F00A7C162#page=7"}, {"page": 4087, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549815E79A9E99C36C2AE45A062B585EDF633024D8627543783A852238F00A7C162#page=8"}, {"page": 4088, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549815E79A9E99C36C2AE45A062B585EDF633024D8627543783A852238F00A7C162#page=9"}], "councilor_points": ["徐立信議員指出華山市場於下午2點半至4點半關閉通往2樓的鐵捲門限制營業，且規定不得攜帶1樓食物至2樓食用，引發消費者陳情與攤商不滿，詢問管理規範是否合理。徐立信議員針對星期一市場休市等營業時間爭議，建議市場處採行問卷調查方式，以民主理性方式搜集攤商意見並進行調整。"], "response": "市場處處長說明華山市場為公用場域，表示會找1樓與2樓自治會溝通協調統一規範。市場處處長同意採行問卷調查方式調查攤商意願，順應多數意見並由市場處協助後續管理。", "response_removed": false, "topic": "華山市場營運規範與溝通機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-23"], "dept": null, "doc_type": "市政總質詢", "group": 4, "heading": "市政總質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162#page=1", "transcript_pages": [920, 921, 922, 923, 924, 925, 926, 927, 928, 929], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162", "videos": [{"date": "2024-05-23", "group": 4}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 2, "heading": "交通部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549E24AC2DE3D31B916A066F097ED9D423B177F0E9EF632D7B6A852238F00A7C162#page=8", "transcript_pages": [522, 523, 524, 525], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549E24AC2DE3D31B916A066F097ED9D423B177F0E9EF632D7B6A852238F00A7C162", "videos": [{"date": "2024-04-18", "group": 2}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 3, "heading": "教育部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549FF14A7A5FB7A9F937D0603C2BB688008DD03E9D6E9731519A852238F00A7C162#page=1", "transcript_pages": [1362, 1363, 1364, 1365, 1366, 1367, 1368], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549FF14A7A5FB7A9F937D0603C2BB688008DD03E9D6E9731519A852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 3}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 2, "heading": "警政衛生部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162#page=1", "transcript_pages": [1813, 1814, 1815, 1816, 1817, 1818], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549BC0F585233B406038A43FA1A10533806202FF807A6B68F21A852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 2}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 3, "heading": "工務部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162#page=1", "transcript_pages": [2298, 2299, 2300, 2301, 2302, 2303], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665495353A526AB35743414E81E8F3064F7DD4C87221635D1782BA852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 3}]}, {"dates": ["2024-05-10"], "dept": "民政", "doc_type": "部門質詢", "group": 9, "heading": "民政部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162#page=1", "transcript_pages": [2864, 2865, 2866, 2867, 2868, 2869], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654909A5FDD5EC15116701069DD285C273EDE36F087DB5B99B52A852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 9}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 2, "heading": "財政建設部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549815E79A9E99C36C2AE45A062B585EDF633024D8627543783A852238F00A7C162#page=7", "transcript_pages": [4086, 4087, 4088], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549815E79A9E99C36C2AE45A062B585EDF633024D8627543783A852238F00A7C162", "videos": [{"date": "2024-05-16", "group": 2}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DA53C0512612A1FBD5B16720985F30BE9550B872589B0637A852238F00A7C162','2026-10-05T12:03:21Z');
INSERT INTO "fact" VALUES('summary:14-03:p741562d334','p741562d334','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:05:38Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 948, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=7"}, {"page": 950, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=9"}, {"page": 951, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=10"}, {"page": 1891, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654971F8822ED7A35FE908AF36F43203936F60EC811A3524AD2AA852238F00A7C162#page=8"}, {"page": 1893, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654971F8822ED7A35FE908AF36F43203936F60EC811A3524AD2AA852238F00A7C162#page=10"}, {"page": 952, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=11"}], "councilor_points": ["曾獻瑩議員指出，臺北市攔阻詐騙金額達到 17 億 9,500 多萬元且破獲率為六都最高，但財損金額仍達 12 億 2,400 多萬元，較前一年增加將近 4 億元，且其中三分之一的投資詐騙案集中在大安區與文山區（「攔阻金額是 17 億 9,500 多萬元……財損金額 12 億 2,400 多萬元，較去年財損 18 億 2,000 多萬元增加將近 4 億元……大安區 16%加上文山區 16%，加起來有三成」）。曾獻瑩議員建議市府應增加預防詐騙的預算與人力，並發文要求銀行不得因行員進行關懷提問遭客訴而打差考績，且應將降低財損金額列為指標，針對大安區與文山區加強宣導（「讓臺北市各銀行分行不能夠因為這種關心提問被客訴，就把這個行員的考績打差……預防詐騙列為指標，提高詐騙攔阻的金額、降低財損的金額」）。"], "response": "市長說明，市府願意在財政允許下投注資源打擊詐騙，並會與金融機構溝通勿將行員多加詢問遭客訴列入考績（「不管在人力、經費上面，只要財政允許，我們都願意投注在打擊詐騙方面……希望他們不要把行員多一分詢問而被客訴，列入他們的年終考績項目」）。警察局代理局長表示，會遵照指示將識詐與宣導列為重中之重，並加強大安區與文山區的投資詐騙預防（「遵照議員的指示，把識詐及宣導部分列為重中之重……好的，可以」）。警察局局長補充，警察局會發文支持銀行行員且明年會增加編列預算，並會針對大安區與文山區及不同年齡層進行分齡分眾宣導（「資料給警察局對口……針對客訴狀況不能對行員有不利處置……明年會增加編列預算……警察局會分齡、分眾宣導」）。", "response_removed": false, "topic": "詐騙防範與財損降低"}, {"citations": [{"page": 1330, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=16"}, {"page": 1330, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=16"}, {"page": 1334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=20"}, {"page": 1334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=20"}, {"page": 1335, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=21"}], "councilor_points": ["曾獻瑩議員指出，臺北市政府應對涉入兒少性剝削及 MeToo 事件的藝人展現零容忍態度，要求下架過去合作的 62 筆網路資料，並擬訂標準作業程序與宣示永不合作（「涉及到兒少的性剝削，或者是 MeToo 這種性別的事件，臺北市政府是不是要有一個零容忍的態度……包含 SOP、是不是要賠償……態度就是永遠不要合作」）。曾獻瑩議員表示，2022 年全臺灣性侵被害人有 8,401 人且未成年占 57%，臺北市有 767 人受害並推估約四百多人為未成年，但教育局掌握的校園通報僅 25 人（國小 1 人、國中 8 人、高中 16 人），質疑通報案件太少且落差過大（「全臺灣有 8,401 位被害人被性侵……未成年人占了所有性侵被害人一半以上……臺北市有 767 位受害者……教育局在性平案件中的性侵案卻只有 25 人……國小 1人，國中 8 人，高中 16 人」）。曾獻瑩議員要求教育局於 2 個星期內查對數據釐清黑數，並加強學生自我保護及情感交友指導（「請局長瞭解一下這個部分……需要多久時間可以回覆我們……教導孩子怎麼樣保護自己」）。"], "response": "觀光傳播局局長說明，市府已將相關爭議資料下架，未來標案會研究納入違規條款，並承諾永不與涉案藝人合作。教育局局長回應，學校調查僅限教職員與學生之間，而衛福部統計包含一般民眾，承諾會在 2 個星期內查對數據，並會加強性平教育與學生人際交往指導（「我們學校調查的是學校裡面老師、教職員及學生之間的，而衛福部的範圍比較大……大概 2 個星期……在性平教育的部分，我們都會再做更多的加強」）。", "response_removed": false, "topic": "兒少性剝削防範與校園性侵通報"}, {"citations": [{"page": 2331, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=2"}, {"page": 2332, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=3"}], "councilor_points": ["曾獻瑩議員指出，京華城由工業用地轉商業用地捐地 30%，容積率由原本認定的 392%提升至 560%及後續的 20%容積獎勵，對比南隆鋼鐵（378%）、士林電機（353%）及國產實業（353%）等捐地 40.5%的案例，容積率明顯偏高（「捐 30％的土地……市府認定是 392％……南隆鋼鐵公司松山廠……回饋了 40.5％土地……概算容積率是 378%……士林電機廠也是一樣捐了 40.5％……概算出來容積率是 353％……國產實業……捐贈 40.5%……容積率是 353％」）。曾獻瑩議員表示，都發局原本堅持 392%容積率長達一年半，但在監委約詢與質問的壓力下才退讓變更，強調市長與府級長官應有肩膀扛住壓力，強力支持公務員堅持市府立場（「在監委持續的約詢、質問的壓力，公務員承受很大的壓力……市長要有肩膀、要有責任、要能夠扛得住各方來的壓力」）。"], "response": "都市發展局局長說明，當時都發局向監委說明相關規範後堅持了一年半，但公務員在監委持續約詢與質問下承受極大壓力（「糾正之後我們都還堅持了一年半……監察院對於案件的約詢，我們公務員一定會有壓力」）。都市發展局局長表示，若能得到市長與府級長官的支持，自己會堅持 392%的容積率立場，且不會核可 20%的容積獎勵。", "response_removed": false, "topic": "京華城容積率變更審議"}, {"citations": [{"page": 946, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=5"}, {"page": 948, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=7"}, {"page": 947, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=6"}, {"page": 948, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=7"}], "councilor_points": ["曾獻瑩議員指出，臺北市社區牆面與店家門口遭違法塗鴉情況嚴重，去年僅告發 31 件且其中 26 件為 30 歲以下年輕人，現行開罰 2,400 元至 6,000 元罰則過輕且嚇阻效果有限（「臺北市去年才告發了 31 件……有 26 件是 30 歲以下的年輕人……從 2,400 元到 6,000元不等……嚇阻的效果或者是抓到人的效果都不大」）。曾獻瑩議員建議環保局應積極向中央爭取提高罰則至上萬元，並與警察局合作掌握塗鴉者模式進行教育輔導，從源頭杜絕塗鴉破壞市容（「罰則過輕，我希望環保局積極地向中央爭取……同一批人可能這邊畫、那邊畫，你們要幫助這一些人……要教育、幫助……一定要從源頭開始」）。"], "response": "環境保護局局長說明，市府已於去年及今年兩度發函向中央反映提高罰則，希望將罰則提高至上萬元以上以產生嚇阻力（「去年和今年都有分別向中央提出……我們希望至少上萬元……上萬元以上才會比較有感覺」）。市長回應，同意塗鴉問題應從源頭開始杜絕，並會交由環保局與警察局共同協助辦理。", "response_removed": false, "topic": "違法塗鴉防治與罰則提升"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-23"], "dept": null, "doc_type": "市政總質詢", "group": 5, "heading": "市政總質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162#page=1", "transcript_pages": [942, 943, 944, 945, 946, 947, 948, 949, 950, 951, 952, 953, 954, 955, 956, 957], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162", "videos": [{"date": "2024-05-23", "group": 5}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 1, "heading": "教育部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162#page=15", "transcript_pages": [1329, 1330, 1331, 1332, 1333, 1334, 1335, 1336], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549183961DFCBE9D5DC996D64B1147ADF5BA29A54FE9C92ECDDA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 1}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 4, "heading": "交通部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549549619B908F9230EE1BC28D3B4379BDDD73456EBD71F51BFA852238F00A7C162#page=1", "transcript_pages": [532, 533, 534, 535, 536, 537, 538, 539, 540], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549549619B908F9230EE1BC28D3B4379BDDD73456EBD71F51BFA852238F00A7C162", "videos": [{"date": "2024-04-18", "group": 4}]}, {"dates": ["2024-04-26"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 6, "heading": "警政衛生部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654971F8822ED7A35FE908AF36F43203936F60EC811A3524AD2AA852238F00A7C162#page=6", "transcript_pages": [1889, 1890, 1891, 1892, 1893, 1894, 1895], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654971F8822ED7A35FE908AF36F43203936F60EC811A3524AD2AA852238F00A7C162", "videos": [{"date": "2024-04-26", "group": 6}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 5, "heading": "工務部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=1", "transcript_pages": [2330, 2331, 2332, 2333, 2334, 2335, 2336, 2337], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 5}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 2, "heading": "民政部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=8", "transcript_pages": [2703, 2704, 2705, 2706, 2707, 2708, 2709, 2710, 2711, 2712], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 2}]}, {"dates": ["2024-05-20"], "dept": "財政建設", "doc_type": "部門質詢", "group": 11, "heading": "財政建設部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665495293B4A8A1D89332AE45A062B585EDF6ED2AB8F77BF17D4BA852238F00A7C162#page=14", "transcript_pages": [4280, 4281, 4282, 4283, 4284, 4285, 4286, 4287, 4288], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665495293B4A8A1D89332AE45A062B585EDF6ED2AB8F77BF17D4BA852238F00A7C162", "videos": [{"date": "2024-05-20", "group": 11}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654915445EAE3BD0C93CF4F762CDB128AEE491CEBB9F9382F14EA852238F00A7C162','2026-10-05T12:05:38Z');
INSERT INTO "fact" VALUES('summary:14-03:p47f1fe2e84','p47f1fe2e84','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T06:50:18Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1525, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=4"}, {"page": 1526, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=5"}, {"page": 1527, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=6"}, {"page": 1528, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=7"}, {"page": 1529, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=8"}, {"page": 1533, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=12"}, {"page": 1534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=13"}, {"page": 1535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=14"}, {"page": 1528, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=7"}, {"page": 1526, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=5"}, {"page": 1527, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=6"}, {"page": 1534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=13"}], "councilor_points": ["李明賢議員指出，前任市長任內首年申請的都更案有1件耗時3074天核定，且至今仍有43%（78件）未完成核定，要求市府追蹤原因並給予協助。李明賢議員表示，公辦都更10個案件中有9件可做到「1坪換1坪」，詢問民辦都更如何拉近差距。李明賢議員亦關切海砂屋列管案件訴訟比例高達四分之一及大型管委會劃分問題，建議市府提供法令指導與協助。"], "response": "市長表示，會請都市更新處針對該78件未核定案逐案了解原因並設法克服。都市更新處處長說明，會透過「都市更新150專案」及「都市審議130快速通關專案」簡化審查，並協助民眾進行免費試算。建築管理工程處處長表示，將與中央溝通及輔導社區透過區權會劃分權責規約，以降低爭議並加速流程。", "response_removed": false, "topic": "都市更新審議效率與推動改善"}, {"citations": [{"page": 690, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=14"}, {"page": 692, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=16"}, {"page": 693, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=17"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=18"}, {"page": 696, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=20"}, {"page": 694, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=18"}, {"page": 696, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=20"}], "councilor_points": ["李明賢議員指出，河濱公園道路界定不明，過去5年發生將近1000件車禍，民眾在非道路用地發生事故無法開立車禍聯單鑑定肇責。李明賢議員表示，水利工程處核發河濱通行證達6000張，加上裁罰無證進入約2000件，車輛過多增加事故風險，要求研擬管理機制並明確公告標線道路。"], "response": "警察局交通警察大隊大隊長表示，會與交通局確認河濱堤外道路範圍並清楚認定。交通局局長說明，河濱公園範疇複雜，將從法規訂定上再行研議。水利工程處河川管理科科長表示，會分析通行證資料並會同相關單位建立處理機制。", "response_removed": false, "topic": "河濱公園道路認定與交通事故處理"}, {"citations": [{"page": 1978, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=2"}, {"page": 1980, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=4"}, {"page": 1981, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=5"}, {"page": 1982, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=6"}, {"page": 1981, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=5"}], "councilor_points": ["李明賢議員指出，全市列管6890座公廁大多評為特優或優等，但自106年以來民眾透過1999陳情達四千八百多件、跌倒受傷達73件，顯示評鑑與實際感受有落差。李明賢議員要求市府檢討12位巡查人員的工作負擔與評鑑機制，並盤點易跌倒的高風險公廁進行補強。"], "response": "環境保護局局長說明，會檢討減輕巡查人員負擔，並針對民眾反映有問題的公廁加強複查。環境保護局資源循環管理科科長表示，針對局管市場公廁已加裝扶手及坡道，並會在今年內完成全面加鋪防滑墊片。", "response_removed": false, "topic": "公廁清潔評鑑與跌倒安全改善"}, {"citations": [{"page": 4258, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=30"}, {"page": 4258, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=30"}, {"page": 4260, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=32"}, {"page": 4261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=33"}, {"page": 4260, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=32"}, {"page": 4261, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=33"}], "councilor_points": ["李明賢議員指出，自109年至今透過1999檢舉麻將館賭博達237件，查獲人數近2000人，顯示賭博行為確實存在。李明賢議員表示，市府禁止新增麻將館登記後，業者轉以休閒館或桌遊館名義登記，要求商業處於源頭從嚴審查並比照新北市考量列入特定行業，同時要求警方加強稽查頻率。"], "response": "警察局刑事警察大隊技正說明，警方每週皆會排定擴大臨檢，若接獲線索或證據將依法偵辦。商業處處長表示，將與警察局進行橫向聯繫，針對疑似案件加強注意並研議前段管控方式。", "response_removed": false, "topic": "休閒場館商業登記與賭博稽查"}, {"citations": [{"page": 2396, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=20"}, {"page": 2397, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=21"}, {"page": 2399, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=23"}, {"page": 2399, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=23"}, {"page": 2397, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=21"}, {"page": 2398, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=22"}], "councilor_points": ["李明賢議員指出，30年以上且11層樓以上建物之外牆安全未申報率達69%，現行最高補助10萬元誘因不足。李明賢議員建議市府提高補助金額，放寬外牆拉皮以「面」為單位申請，並訂定統一的公安圖示標準以防範違規。"], "response": "建築管理工程處處長表示，規劃於2個月內提高個案補助金額，並會將圖例畫出及落實要求檢查機構傳達正確訊息。都市更新處處長說明，整維申請是以棟為單位。都市發展局局長補充說明，民眾以棟申請但僅修繕拉皮單一界面是可以的，會依申請範圍進行補助。", "response_removed": false, "topic": "建物外牆安全申報與公安標準統一"}, {"citations": [{"page": 1535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=14"}, {"page": 1536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=15"}, {"page": 1537, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=16"}, {"page": 1536, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=15"}, {"page": 1537, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=16"}], "councilor_points": ["李明賢議員指出，市府投入各項措施改善內湖交通，但港墘至堤頂路口僅改善12秒，要求訂定目標動態管理以持續提升效益。李明賢議員關切堤頂交流道北上引道增設匝道工程進度，建議確保施工期間車道數不減少，維護交通順暢。"], "response": "交通局局長說明，預計明年7月完成匝道工程，且用地位於綠地範圍內，施工期間不會縮減原車道數。市長表示，會訂出目標持續改善路口秒數，並做好交通維持將工程衝擊降至最低。", "response_removed": false, "topic": "內湖交通改善方案與匝道工程進度"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-04"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=1", "transcript_pages": [1522, 1523, 1524, 1525, 1526, 1527, 1528, 1529, 1530, 1531, 1532, 1533, 1534, 1535, 1536, 1537, 1538], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162", "videos": [{"date": "2024-06-04", "group": 17}]}, {"dates": ["2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 8, "heading": "教育部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=32", "transcript_pages": [1493, 1494, 1495, 1496], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162", "videos": [{"date": "2024-04-12", "group": 8}]}, {"dates": ["2024-04-19", "2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=13", "transcript_pages": [689, 690, 691, 692, 693, 694, 695, 696, 697], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 10}, {"date": "2024-04-22", "group": 10}]}, {"dates": ["2024-04-29"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=1", "transcript_pages": [1977, 1978, 1979, 1980, 1981, 1982, 1983, 1984], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162", "videos": [{"date": "2024-04-29", "group": 10}]}, {"dates": ["2024-05-03"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162#page=20", "transcript_pages": [2396, 2397, 2398, 2399, 2400], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F00A7C162", "videos": [{"date": "2024-05-03", "group": 8}]}, {"dates": ["2024-05-10"], "dept": "民政", "doc_type": "部門質詢", "group": 6, "heading": "民政部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 6}]}, {"dates": ["2024-05-20"], "dept": "財政建設", "doc_type": "部門質詢", "group": 10, "heading": "財政建設部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=28", "transcript_pages": [4256, 4257, 4258, 4259, 4260, 4261, 4262, 4263, 4264, 4265], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162", "videos": [{"date": "2024-05-20", "group": 10}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162','2026-10-05T06:50:18Z');
INSERT INTO "fact" VALUES('summary:14-03:p072095ef7a','p072095ef7a','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:07:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1229, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=5"}, {"page": 1229, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=5"}, {"page": 1600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=16"}, {"page": 1600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=16"}, {"page": 1600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=16"}, {"page": 1230, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=6"}, {"page": 1600, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=16"}, {"page": 1602, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=18"}, {"page": 1231, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=7"}], "councilor_points": ["李芳儒議員指出，現行原住民族教育資源中心層級與協調能力不足，且族語師資面臨高齡化與跨區跑校困境，建議成立獨立的「原住民族教育中心」統籌原住民族教育事務（「希望未來能夠設立臺北市原住民族教育中心，獨立運作原住民族的教育事務，真正推動全民原教」）。李芳儒議員表示，臺北市擁有91位原住民籍教師，建議市府及早規劃成立涵蓋16族的原住民族實驗學校（「希望預計在臺北市開辦的原住民實驗學校能夠有 16 族」）。"], "response": "市長表示，已將原住民族教育審議會拉至府級，並請教育局針對成立教育中心與實驗學校進行研議（「市府可以來研議」、「這個請教育局去研究」）。教育局局長說明，將先透過府級運作加強橫向聯繫，並考量學生分散情形研究實驗學校的實施方式（「是不是等現在運作以後，教育局再逐一看看有沒有其他問題」、「我們也在考量實施的方式」）。", "response_removed": false, "topic": "原住民族教育中心設立與實驗學校開辦"}, {"citations": [{"page": 1226, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=2"}, {"page": 1226, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=2"}, {"page": 2922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=19"}, {"page": 2922, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=19"}, {"page": 1227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=3"}, {"page": 2924, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=21"}, {"page": 1228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=4"}], "councilor_points": ["李芳儒議員指出，「臺北市促進原住民就業自治條例」於民國88年12月13日制定，早於中央法規，市府111年修正報請備查卻於113年5月3日遭行政院函告部分條文無效（「中央在之前都沒說臺北市所核備的條例是違法，現在居然說我們是違法的，說實在，本席沒有辦法接受」）。李芳儒議員要求，市府應依法於30天法定期限內提起訴願等行政爭訟，必要時提起憲法訴訟以捍衛地方自治權限（「本席特別要求市府要依法於法定的期限內循序進行行政爭訟，有必要的話，提起憲法訴訟，以維護本市原住民的權益，捍衛本市地方自治權限」）。"], "response": "市長表示，市府會堅定立場，依規定進行行政救濟途徑以捍衛自治權限（「臺北市政府一定會堅定立場，該尋求的行政救濟途徑，一定會依規定來進行」）。原住民族事務委員會主任委員與法務局局長說明，已研擬訴願內容並確認會在30天內提起訴願（「本會已經在研擬提訴願的內容了，30 天內一定會提起訴願」）。", "response_removed": false, "topic": "「臺北市促進原住民就業自治條例」自治權限維護"}, {"citations": [{"page": 1234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=10"}, {"page": 2418, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=10"}, {"page": 1234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=10"}, {"page": 2419, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=11"}], "councilor_points": ["李芳儒議員指出，臺北市建物平均年齡達37.63年，建議將「都更八箭」政策轉換為智慧化系統，方便民眾輸入條件查詢適合方案（「把所有的條件輸入到系統裡面，這個系統告訴我們哪一箭才是適合民眾的」）。李芳儒議員建議，市府重新通盤檢討「都更八箭」，因地制宜評估各地區適用方案並主動向民眾說明（「希望都更 8 箭部分，好好再去做檢討，哪裡適合就用哪一箭向民眾做討論」）。"], "response": "市長表示，同意研究建立智慧化系統，幫助民眾了解適合的都更政策（「我們可以來研究，就是針對民眾不同的情境，然後他可以了解，哪個政策是適合的」）。都市發展局局長與都市更新處處長說明，都更難點在於整合，現階段以防災型都更最符合需求，並承諾對政策進行檢討（「防災型都市更新專案……最符合需求」、「好的，我們來檢討」）。", "response_removed": false, "topic": "都市更新政策檢討與「都更八箭」執行機制"}, {"citations": [{"page": 1234, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=10"}, {"page": 1231, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=7"}, {"page": 1233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=9"}, {"page": 2924, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=21"}, {"page": 2925, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=22"}, {"page": 2925, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=22"}, {"page": 2926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=23"}, {"page": 2927, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=24"}], "councilor_points": ["李芳儒議員建議，市府換位思考，區分社會局「救助」與原民會「補助」之功能，要求原民會訂定符合臺北市族人需求的脫貧政策及細則（「請原民會因應現階段的臺北市原住民族，提出一套符合原住民脫貧政策及細則」）。李芳儒議員指出，中央原住民族就業獎勵計畫因跨年採計產生退款爭議，建議改採申請日認定，並建議將特殊才能獎學金擴大至大專學生及獎勵族語認證（「基本上以申請日為主」、「希望在要點裡增加大專這一塊」）。"], "response": "市長表示，同意換位思考，市府除給予救助補助外，也會提供輔導以協助自立（「除了給魚，我們也給釣竿教釣魚」）。原住民族事務委員會主任委員說明，會持續向中央反映就業獎勵改善建議，並將研議擴大特殊才能獎學金至大專及調整族語獎勵（「針對特殊才能的部分，我們再把補助對象擴大至大專」、「這部分我們再研議」）。", "response_removed": false, "topic": "原住民族脫貧政策與扶助獎勵機制檢討"}, {"citations": [{"page": 1825, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=2"}, {"page": 1825, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=2"}, {"page": 1826, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=3"}], "councilor_points": ["李芳儒議員提出，家長接送幼童遭車輛拖吊案例，建議幼兒園及校園周邊設置臨時停車格，並以開單取代拖吊（「建議針對幼兒園及校園周遭，是不是可以設置臨時的停車格，另外針對於周遭違規停車的取締，以開單為主，不要以拖吊為主」）。李芳儒議員指出，民眾檢舉交通違規案急速上升，建議警察局分析檢舉次數並廣設科技執法以減輕警力負擔（「善用 AI 處理減少警察的工作量，讓警察的勤務能夠真正導入治安裡面」）。"], "response": "交通管制工程處副總工程司說明，幼兒園可申請規劃15公尺至20公尺臨停空間，上放學期間會與警察局溝通適度開放臨停（「原則上每個幼兒園大概都會規劃至少 15 公尺至 20 公尺的長度，供家長臨時停車使用」、「在上、放學期間是不是能夠適度檢討開放」）。警察局局長表示，目前未對檢舉次數做統計分析，目前已設有38處科技執法，會配合善用科技執法（「目前沒有針對檢舉人次數做統計分析」、「38 處」）。", "response_removed": false, "topic": "學校周邊接送幼童臨停與交通執法改善"}, {"citations": [{"page": 2417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=9"}, {"page": 2417, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=9"}], "councilor_points": ["李芳儒議員指出，40年以上老舊建築安全梯多位於防火巷，要求建管處主動查核列冊並拆除占用防火巷之違建與違規營業以維護公共安全（「針對防火巷和防火間隔的部分，希望能夠徹底查核，甚至對於在防火巷違規建營業的，更要要求恢復原狀」）。"], "response": "建築管理工程處處長說明，凡接獲通報占用防火巷之違建或違規營業，都會列入年度專案進行處理（「對於防火巷、防火間隔，只要有通報受理的，不管是違反『公寓大廈管理條例』或者違反『違章建築處理辦法』的一定都會在年度裡列入專案處理」）。", "response_removed": false, "topic": "老舊建築防火巷與防火間隔違建查核"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-28"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=1", "transcript_pages": [1225, 1226, 1227, 1228, 1229, 1230, 1231, 1232, 1233, 1234, 1235], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162", "videos": [{"date": "2024-05-28", "group": 10}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=14", "transcript_pages": [1598, 1599, 1600, 1602, 1603], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162", "videos": [{"date": "2024-04-16", "group": 14}]}, {"dates": ["2024-04-19"], "dept": "交通", "doc_type": "部門質詢", "group": 7, "heading": "交通部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 7}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 3, "heading": "警政衛生部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=1", "transcript_pages": [1824, 1825, 1826, 1827], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 3}]}, {"dates": ["2024-05-03"], "dept": "工務", "doc_type": "部門質詢", "group": 9, "heading": "工務部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=8", "transcript_pages": [2416, 2417, 2418, 2419, 2420, 2421], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162", "videos": [{"date": "2024-05-03", "group": 9}]}, {"dates": ["2024-05-13"], "dept": "民政", "doc_type": "部門質詢", "group": 12, "heading": "民政部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162#page=19", "transcript_pages": [2922, 2924, 2925, 2926, 2927], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654932BE903BD28873A95CDC24BD4B026A7C23380A13AEC405A5A852238F00A7C162", "videos": [{"date": "2024-05-13", "group": 12}]}, {"dates": ["2024-05-21"], "dept": "財政建設", "doc_type": "部門質詢", "group": 14, "heading": "財政建設部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162", "transcript_pages": [], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162", "videos": [{"date": "2024-05-21", "group": 14}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162','2026-10-05T12:07:21Z');
INSERT INTO "fact" VALUES('summary:14-03:p772a0a5bf9','p772a0a5bf9','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:09:17Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 987, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=3"}, {"page": 2728, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=8"}, {"page": 789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=10"}, {"page": 1852, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=1"}, {"page": 1853, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=2"}, {"page": 1853, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=2"}, {"page": 988, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=4"}, {"page": 2729, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=9"}, {"page": 2730, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=10"}, {"page": 4189, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162#page=5"}, {"page": 2729, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=9"}], "councilor_points": ["林世宗議員指出台智光案涉入不當情事且未達承諾，質疑市府先前同意3M費率2,100元方案之適法性。林世宗議員要求警察局於終止子約後應依市長核定費率支付並研擬備援方案，且應將各速率及幹線費率納入合理價格討論。林世宗議員建議市府應積極研擬發函解除母約並進行無償接管，以追究業者責任。"], "response": "市長說明市府已即刻解除子約並終止警用監視器專用合約，若發現不法將依法辦理。警察局局長表示子約終止後改依TGSN費率支付，將積極尋找備援方案並同意研商幹線費率。副秘書長說明費率會議是由三個局處共同討論，法務局局長與資訊局局長表示本案屬重大情事，若符合母約提前終止規定將依規定處理。", "response_removed": false, "topic": "台智光網路傳輸服務案與合約處理"}, {"citations": [{"page": 2730, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=10"}, {"page": 985, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=1"}, {"page": 1002, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=18"}, {"page": 2732, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=12"}, {"page": 1005, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=21"}, {"page": 2733, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=13"}], "councilor_points": ["林世宗議員指出臺北市65歲以上長者達55萬至56萬人（占22%），全市456個里中有103個里未設社區照顧關懷據點，建議鬆綁僵化制度並開放學校、財團法人或社團法人參與設立。林世宗議員指出敬老悠遊卡每人每月480點預算僅編列13億餘元，建議擴大用途至市立聯合醫院掛號看診及積累使用。"], "response": "市長說明會請社會局於2個禮拜內擬定計畫盤點需求，優先尋找空間並結合民間與企業資源設置據點，並說明市府已恢復1,500元重陽敬老金且持續擴大480點使用範圍。社會局局長說明會將學校及財團法人納入補助對象，並表示敬老卡至市立聯合醫院掛號看診尚涉及技術層面，正與衛生局研議中。", "response_removed": false, "topic": "社區照顧關懷據點設置與長者福利政策"}, {"citations": [{"page": 4187, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162#page=3"}, {"page": 990, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=6"}, {"page": 4188, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162#page=4"}, {"page": 990, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=6"}], "councilor_points": ["林世宗議員指出臺北市168萬用戶水表採購長期由單一廠商壟斷，質疑推動計畫預算由48億元調增至86億元、單價由2,900元增至5,100元，且目前仍編列3.68億元執行7萬2,700顆水表標案。林世宗議員要求市府遵照議會附帶決議落實複數決標，懸崖勒馬並審慎檢討預算與招標過程。"], "response": "市長說明市府去年已停辦全面加裝智慧水表，並將機制改為FOT2以引進新廠商參與。臺北自來水事業處處長說明因財務無法負擔已於去年停辦原計畫，現遵照議會附帶決議採複數決標辦理，近期8標中已開標之3標即包含2家不同廠商。", "response_removed": false, "topic": "智慧水表推動與採購招標疑慮"}, {"citations": [{"page": 1005, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=21"}, {"page": 2268, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=2"}, {"page": 1006, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=22"}, {"page": 2269, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=3"}], "councilor_points": ["林世宗議員指出關渡碼頭周邊先前已投入約2.3億元（含2.1億元及1,760萬元）進行改善工程，但現場河道仍嚴重淤積。林世宗議員質疑市府將周邊空間標租給業者經營輕食市集，租金1年僅4萬500元（或每月6,600元），要求市府檢討標租條件並儘速執行清淤計畫。"], "response": "水利工程處處長說明該案係以公告地價10%進行公開標租且由業者以最高價得標，今年已編列預算針對中港河及紅樹林進行疏濬與疏伐。市長說明該合約租期為4年，工務局局長說明碼頭水深狀況係受退潮影響。", "response_removed": false, "topic": "關渡碼頭設施整建與周邊經營清淤"}, {"citations": [{"page": 1856, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=5"}], "councilor_points": ["林世宗議員指出北投焚化廠處理臺北市60%垃圾，但水洗飛灰比例過低，每年仍有一萬多公噸飛灰固化送往山豬窟掩埋，預計8至9年後山豬窟將無法容納。林世宗議員要求環境保護局引進日本水洗技術並推動飛灰活化再利用（如製作高速磚），以減少環境污染。"], "response": "環境保護局局長表示認同議員建議，說明山豬窟目前容量估計尚可使用11.71年，並承諾於3個星期內就增加飛灰水洗與再利用、減少固化等規劃提出書面報告。", "response_removed": false, "topic": "北投焚化廠飛灰處理與環境污染改善"}, {"citations": [{"page": 1553, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=7"}, {"page": 1553, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=7"}], "councilor_points": ["林世宗議員詢問2025雙北世界壯年運動會預算效益，指出該案自109年至113年已使用6.7億餘元，並質疑共同主辦的新北市僅負擔300萬歐元（約1億元臺幣）權利金分攤不均。林世宗議員要求體育局提供經費使用明細，並要求說明士北科C基地運動場是否興建。"], "response": "體育局局長說明活動總經費約18億元且不會追加預算，目標吸引3萬名選手與隨行人員，並說明新北市免費提供賽事場地。體育局局長承諾於1週內提供經費明細，並於2週內就士北科場館興建規劃提供答案。", "response_removed": false, "topic": "2025雙北世界壯年運動會籌備與經費分攤"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-24"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=1", "transcript_pages": [985, 986, 987, 988, 989, 990, 1002, 1003, 1004, 1005, 1006], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162", "videos": [{"date": "2024-05-24", "group": 6}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 12, "heading": "教育部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=5", "transcript_pages": [1551, 1552, 1553, 1554, 1555, 1556, 1557, 1558, 1559], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 12}]}, {"dates": ["2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=6", "transcript_pages": [785, 786, 787, 788, 789, 790], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162", "videos": [{"date": "2024-04-22", "group": 14}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=1", "transcript_pages": [1852, 1853, 1854, 1855, 1856, 1862], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 4}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 1, "heading": "工務部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=1", "transcript_pages": [2267, 2268, 2269, 2270, 2271, 2272, 2273], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 1}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 3, "heading": "民政部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=7", "transcript_pages": [2727, 2728, 2729, 2730, 2731, 2732, 2733, 2734, 2735], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 3}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162#page=1", "transcript_pages": [4185, 4186, 4187, 4188, 4189], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162','2026-10-05T12:09:17Z');
INSERT INTO "fact" VALUES('summary:14-03:pcc848fb570','pcc848fb570','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:10:56Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=18"}, {"page": 2769, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=19"}, {"page": 2770, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=20"}, {"page": 2771, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=21"}, {"page": 2768, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=18"}], "councilor_points": ["林亮君議員指出臺北市近2年列管街友人數平穩但脫遊人數不升反降，建議市府分析街友實際醫療需求、指導基本衛教保健觀念並設置定點醫療站。林亮君議員表示部分街友因自身債務或官司面臨薪水扣押而降低就職意願，建議市府於地方自治權限內設置屬於街友的「社會自助專戶」代管機制以確保基本消費能力。林亮君議員指出現行處所如圓通居與廣安居環境較為擁擠老舊，建議改善居住與社交環境以提高街友適應度。"], "response": "社會局局長說明街友脫遊面臨反覆回歸、就業意願低落及安置處所不足等瓶頸，並表示將研議突發狀況之緊急醫療服務以及設置專戶的法規與執行可行性。勞動局局長表示會研議調整職訓課程以提升街友技能，並放寬計畫將街友納入職務再設計服務。", "response_removed": false, "topic": "街友脫遊輔導策略改善"}, {"citations": [{"page": 1277, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=1"}, {"page": 1280, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=4"}, {"page": 1282, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=6"}, {"page": 1279, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=3"}, {"page": 1279, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=3"}], "councilor_points": ["林亮君議員指出「8橫8縱」機車退出人行道政策將減少將近7,000個機車停車位，而共享機車存在占據車位與每日平均閒置23小時等外部成本。林亮君議員詢問現行行政契約規範連續停放不得超過72小時、違規移車給予4小時寬限是否過於寬鬆，並建議市府調整契約內容。林亮君議員表示共享運具小客車每年收取2,000元、機車600元權利金過低，要求市府重新計算權利金並請業者提供數據以評估降低私人運具之政策成效。"], "response": "市長說明會檢討並調整行政契約，認為違規不應給予4小時寬限，並將檢討權利金與研議給予更大誘因鼓勵業者汰換為電動或低碳機車。交通局局長說明當初權利金有設定鼓勵減免，承諾會在2個月內親自與業者座談，針對轉換率取得與行政契約內容進行溝通調整。", "response_removed": false, "topic": "共享運具管理與權利金檢討"}, {"citations": [{"page": 824, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=3"}, {"page": 825, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=4"}, {"page": 826, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=5"}, {"page": 825, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=4"}], "councilor_points": ["林亮君議員指出改善計畫實施後主要幹道僅降低約7%車流，且高達85%的內科通勤族不利用YouBike通勤係因道路設計不友善與站點密度不足。林亮君議員指出通勤專車班次與站點不符大眾需求，詢問交通局是否有檢討規劃。林亮君議員表示捷運環狀線東環段預計明年開工並橫越瑞光路，要求交通局擴大交通改善範圍至通勤族主要來源之行政區與縣市，並加強事前社會溝通。"], "response": "交通局局長說明正在優化自行車環境，並預計於6月推出園區內巡迴公車與北環線公車。交通局局長說明因應東環段施工瑞光路車道將縮減，目前正評估實施時段性公車專用道等措施，並承諾擴大改善範圍與規劃替代路徑。", "response_removed": false, "topic": "內湖科技園區交通改善與東環段施工因應"}, {"citations": [{"page": 4128, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=12"}, {"page": 4129, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=13"}, {"page": 4130, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=14"}, {"page": 4130, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=14"}], "councilor_points": ["林亮君議員指出臺北市列管52處攤販集中場中，5年內僅5處申請裝設油脂截留器補助，全北市5,841攤僅720攤申請，裝設比例偏低。林亮君議員詢問非固定式攤販之污水處理替代方案，並指出夜市污水接管進度緩慢，距離萬華中原夜市接管已過多年。林亮君議員要求市府提出具體期程與目標，並要求市場處於1個月內與衛工處研擬夜市污水直接銜接衛工管之專案計畫。"], "response": "市場處處長說明將針對飲食攤採宣導或較強制方式提升油脂截留器裝設率，並承諾於1個月內與衛工處研擬夜市污水直接接到衛工管的規劃專案。衛生下水道工程處副總工程司表示衛工處會全力配合市場處的接管計畫。", "response_removed": false, "topic": "夜市與攤販集中場油脂截留器裝設與污水處理"}, {"citations": [{"page": 1380, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162#page=5"}, {"page": 1382, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162#page=7"}, {"page": 1379, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162#page=4"}], "councilor_points": ["林亮君議員指出「文化小旅行」網站之36個文化點缺乏歸納分類與交通資訊，且多國語言版本內容呈現不一致。林亮君議員指出觀光傳播局「臺北旅遊網」之主題旅遊行程缺乏建議抵達時間、停留時間與移動交通車資等資訊，且使用者需在兩局處網站間跳轉。林亮君議員要求文化局與觀光傳播局將使用者體驗納入調整，並就優化與整合規劃提出報告。"], "response": "文化局局長說明將優化網站，將文化點依五大類及12行政區分類，並預計於7月前規劃出50條路線及影片。觀光傳播局局長表示會全面檢討檢視網站內容，並提供建議前往時機與景點停留時間等資訊。", "response_removed": false, "topic": "臺北文化小旅行與觀光導覽網站整合"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=1", "transcript_pages": [1277, 1278, 1279, 1280, 1281, 1282, 1283, 1284, 1285, 1286, 1287, 1288, 1289], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162", "videos": [{"date": "2024-05-30", "group": 11}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162#page=1", "transcript_pages": [1376, 1377, 1378, 1379, 1380, 1381, 1382], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 4}]}, {"dates": ["2024-04-23"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=1", "transcript_pages": [822, 823, 824, 825, 826, 827, 828], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162", "videos": [{"date": "2024-04-23", "group": 16}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 5, "heading": "警政衛生部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=16", "transcript_pages": [1879, 1880, 1881, 1882, 1883], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 5}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=15", "transcript_pages": [2293, 2294, 2295, 2296, 2297], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 2}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 5, "heading": "民政部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=15", "transcript_pages": [2765, 2766, 2767, 2768, 2769, 2770, 2771], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 5}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=9", "transcript_pages": [4125, 4126, 4127, 4128, 4129, 4130, 4131], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162", "videos": [{"date": "2024-05-16", "group": 4}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162','2026-10-05T12:10:56Z');
INSERT INTO "fact" VALUES('summary:14-03:p5fb3d560bb','p5fb3d560bb','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:13:03Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1504, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=2"}, {"page": 1504, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=2"}, {"page": 1505, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=3"}, {"page": 1506, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=4"}, {"page": 1506, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=4"}, {"page": 1507, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=5"}, {"page": 1505, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=3"}], "councilor_points": ["林延鳳議員指出，文化局編列將近2,000萬元的「臺北國際潮流音樂節」預算，需求規範書預期人次卻僅設定1,000人次，質疑「目標訂得有點低」且投資報酬率不佳。林延鳳議員指出，招標規範要求廠商邀請具票房實力的歌手且自負盈虧，受限於場館規模，且原本僅指定信義區與南港區，對其他行政區並不公平。林延鳳議員要求文化局檢討相關內容與關鍵績效指標（KPI），並提供書面報告。"], "response": "文化局局長說明，需求規範書所列1,000人次是指與民間小型live house合作的目標，今年活動為測試營運模式的試辦版。文化局局長表示，合作範圍已調整為全臺北市，並承諾會進行內部檢討且向議員提交詳細說明資料。", "response_removed": false, "topic": "臺北國際潮流音樂節效益與招標規範"}, {"citations": [{"page": 4063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=5"}, {"page": 4063, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=5"}, {"page": 4066, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=8"}, {"page": 4067, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=9"}, {"page": 4066, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=8"}, {"page": 4065, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=7"}], "councilor_points": ["林延鳳議員詢問財政局局長擔任台北富邦銀行官股董事的職責與表現。林延鳳議員指出，台北富邦銀行涉及特定房屋貸款爭議、遴選副董事長時官股董事未表示異議、對中國大陸高額曝險以及放款給租賃公司等問題。林延鳳議員要求財政局於一星期內提供官股董事監督的會議紀錄與改善報告。"], "response": "財政局局長說明，官股董事均以市府權益為優先並積極監督營運，今年富邦金控發放股利3元優於同業預期。財政局局長表示，金融監督管理委員會已就個案了解貸款狀況，且富邦華一銀行已重新檢視中國大陸不動產放款並逐步收回信用放款，同意在一星期內提供相關報告。", "response_removed": false, "topic": "台北富邦銀行官股董事監督責任與營運爭議"}, {"citations": [{"page": 2843, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=4"}, {"page": 2844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=5"}, {"page": 2844, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=5"}, {"page": 2846, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=7"}, {"page": 2847, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=8"}], "councilor_points": ["林延鳳議員指出，市府規劃花費400萬元聘請5位非編制人力，且相關預算未曾送至議會進行審查。林延鳳議員詢問預定赴青年局任職的市府人員對青年失業率及92萬青年服務人口等基本業務資料的掌握狀況。林延鳳議員詢問臺北市政府發言人6月1日兼任青年局局長後的業務專注度，要求市府將預算送至議會審查。"], "response": "臺北市政府副發言人說明，市府先前已於附件資料中提供青年局業務與預算劃撥說明。臺北市政府發言人表示，接任青年局局長為團隊人事安排，若屬市長交辦任務會全力以赴。", "response_removed": false, "topic": "青年局籌備預算與人事任用質疑"}, {"citations": [{"page": 642, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=15"}, {"page": 643, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=16"}, {"page": 644, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=17"}, {"page": 645, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=18"}, {"page": 645, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=18"}], "councilor_points": ["林延鳳議員指出，兒童新樂園美食街9間店家中有5間網路評價不到2顆星，並列舉餐點出現蟲、發霉及食材不潔等缺失。林延鳳議員指出，捷運公司過去5年僅裁罰4次各3,000元，認為自主檢查機制失能，且衛生局的稽查作業亦不夠嚴謹。林延鳳議員要求建立評鑑與稽查機制，並落實食安督導。"], "response": "臺北大眾捷運股份有限公司總經理說明，將建立三級管控機制，針對累犯廠商會要求停止營業或解約。臺北大眾捷運股份有限公司遊憩休閒事業處處長表示，已要求承商於5月15日前提出整體改善計畫，並將重新建立自主檢查與評鑑制度。", "response_removed": false, "topic": "兒童新樂園美食街食安衛生與品質監督"}, {"citations": [{"page": 867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=3"}, {"page": 867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=3"}], "councilor_points": ["林延鳳議員詢問市長對於藐視國會罪與藐視議會罪的態度，並指出若依藐視國會罪標準，官員不陳述或拒絕提供資料即可處以2萬元到10萬元罰鍰。林延鳳議員指出，市府過去在台智光案、寶林案稽查紀錄及雙城論壇備忘錄等索資上，曾以個資或商業機密為由未提供資料。林延鳳議員建議市府提出藐視議會罪條例送交議會審議。"], "response": "市長說明其支持國會改革，目前議會並無藐視議會罪規定，若議員提案會表示尊重。市長表示，針對市政議題均據實回答，且市府皆依法提供相關文件及資料。", "response_removed": false, "topic": "藐視國會罪爭議與市府索資回應"}, {"citations": [{"page": 4061, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=3"}], "councilor_points": ["林延鳳議員詢問工程施作單位與監造單位若具母子公司關係是否產生利益衝突。林延鳳議員指出，台灣智慧光網將光纖建置工程交由母公司台通光電施作，形成子公司監造母公司的情形，認為有「球員兼裁判」之疑慮。林延鳳議員要求資訊局公開監造紀錄供委員會檢視，並會同第三方公證單位實地會勘光纖覆蓋率。"], "response": "資訊局局長與工務局採購管理科科長說明，此類關係在利益迴避與觀感上確實較不理想，採購法雖未明定禁止但機關須注意履約管理。資訊局局長表示，會重新特別檢核相關監造數據與紀錄，若發現不法會移送檢調與政風單位。", "response_removed": false, "topic": "台智光光纖網路建置母子公司監造問題"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-22"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=1", "transcript_pages": [865, 866, 867, 868, 869, 896, 897, 898, 899, 900, 901, 902], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162", "videos": [{"date": "2024-05-22", "group": 2}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=1", "transcript_pages": [1503, 1504, 1505, 1506, 1507, 1508, 1509], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 10}]}, {"dates": ["2024-04-19"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=15", "transcript_pages": [642, 643, 644, 645], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 8}]}, {"dates": ["2024-04-30"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162#page=7", "transcript_pages": [2085, 2086, 2087, 2088, 2089, 2090], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162", "videos": [{"date": "2024-04-30", "group": 14}]}, {"dates": ["2024-05-07"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CC6FB88B7121BA54BCDA3DCAE4FCE1A81C2378305888797DA852238F00A7C162#page=1", "transcript_pages": [2502, 2503, 2504, 2505, 2506], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CC6FB88B7121BA54BCDA3DCAE4FCE1A81C2378305888797DA852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 14}]}, {"dates": ["2024-05-10"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=1", "transcript_pages": [2840, 2841, 2842, 2843, 2844, 2845, 2846, 2847, 2848], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 8}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 1, "heading": "財政建設部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=1", "transcript_pages": [4059, 4060, 4061, 4062, 4063, 4064, 4065, 4066, 4067, 4068], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162", "videos": [{"date": "2024-05-16", "group": 1}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162','2026-10-05T12:13:03Z');
INSERT INTO "fact" VALUES('summary:14-03:pcdef61ef89','pcdef61ef89','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:15:14Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 562, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=12"}, {"page": 565, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=15"}, {"page": 567, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=17"}, {"page": 564, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=14"}, {"page": 566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=16"}, {"page": 568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=18"}], "councilor_points": ["林杏兒議員指出士林區與北投區公有停車場之汽機車格位不足，要求交通局通盤檢討全臺北市沒必要的紅線改劃成黃線「機車停車格位不足占 78%」、「通盤檢討沒必要的紅線」。林杏兒議員表示市府發布之共用臨停區政策應訂定明確申請標準，並建議將臨停 3 分鐘之限制評估人性化調整及搭配智慧車柱管控「把一些條件、審查方式、申請需求的認定要趕快訂定出來」、「3 分鐘時間值得去討論一下，到底 3 分鐘夠不夠人性化」。"], "response": "交通管制工程處處長說明市府已主動盤點出 236 處紅線改劃設黃線，並表示會重新檢討劃設原則後於 2 個月內提供報告「盤點出這 236 處紅線，改劃設黃線」、「2 個月提供給議員」。停車管理工程處處長表示共用臨停區未來會透過民政鄰里系統由地方提出需求，比照黃線臨停 3 分鐘概念，並將智慧車柱等科技管理納入未來研究方向「透過民政鄰里系統，讓各里辦公室提出需求」、「比照黃線的概念，臨停 3 分鐘」、「透過更科技的方式」。", "response_removed": false, "topic": "道路紅線劃設與共用臨停區政策"}, {"citations": [{"page": 2451, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=4"}, {"page": 2452, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=5"}, {"page": 2449, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=2"}, {"page": 2448, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=1"}], "councilor_points": ["林杏兒議員指出臺北市 30 年以上建築物達 20 萬棟且海砂屋列管件數高，並舉明德路及芝蘭段都更案為例，要求市府展現魄力加速海砂屋拆除與聽證會公調排程「30 年以上的建築物就占 20 萬棟」、「同意都更的比率已經達 92%以上」、「同意率 97.2%的案子」。林杏兒議員建議市府針對同意比率高的都更案優先納入審查排序，並研議招聘約聘人員或實習生以補足都市更新處人力不足問題「整體同意比率高的趕快納入優先排序」、「招聘約聘人員，讓人趕快進來」。"], "response": "都市發展局局長說明針對海砂屋有推出「575專案」進行輔導，並表示條件完備之案子會協助儘速辦理公調及提報委員會「海砂屋有 575 專案」、「協助他們處理」。建築管理工程處處長表示海砂屋規定 2 年內停止使用、希望 3 年內自行拆除，並會在每年度請三大技師公會進行巡檢「規定 2 年內要停止使用，希望他們能夠在 3 年內自行拆除」、「每年度找三大技師公會對這些列管的海砂屋做巡檢」。都市更新處處長表示相關都更案公調與聽證程序資料齊備後會趕快處理「公調我們會趕快處理」。", "response_removed": false, "topic": "海砂屋拆除重建與都更審議人力"}, {"citations": [{"page": 1357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=21"}, {"page": 1360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=24"}, {"page": 1356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=20"}, {"page": 1356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=20"}, {"page": 1357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=21"}, {"page": 1359, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=23"}], "councilor_points": ["林杏兒議員指出蘿蔔刀與噼叭筒等具危險性玩具易取得，且校園管教衝突事件增加，要求教育局落實安全教育與預防管控「四處都非常容易取得」、「管教、衝突事件，也增加 1.68 倍」。林杏兒議員詢問團膳業者是否提供進貨發票單據，並要求團膳業者廚房應加裝監視器及強制安裝 GPS 以管控車程 30 分鐘之規定「進貨的發票單據」、「要求團膳業者加裝監視器」、「要求廠商裝 GPS」。"], "response": "教育局局長表示已轉文請學校留意學用品使用安全，並說明教育部有特別同意針對個案可以在第三人見證下檢查書包，同時會加強親師溝通以降低衝突「轉文到學校，請他們要特別留意」、「在別人見證底下，學務處可以看他的書包」、「加強親師的溝通」。教育局體育及衛生保健科科長說明進貨到學校餐廳每日須提供單據驗證「三章一Q」，每年有約 100 場聯合稽查，目前有桃源國小與景興國小在教育部補助下裝設監視系統，並由學校營養師查核車程時間「必須要有驗證標章」、「有 100 場」、「桃源國小與景興國小在教育部補助款下有裝監視系統」、「學校的營養師」。", "response_removed": false, "topic": "校園危險物品防範與營養午餐食安管控"}, {"citations": [{"page": 2973, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=2"}, {"page": 2974, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=3"}, {"page": 2973, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=2"}, {"page": 2975, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=4"}], "councilor_points": ["林杏兒議員指出第二殯儀館動用第二預備金辦理電子輓聯欠缺事前規劃，並要求改善電梯缺乏指示燈、辛亥路塞車、計程車排班動線與圍籬等問題「動用第二預備金去做電子輓聯」、「連上下指示燈都沒有」、「辛亥路上其實就塞車了」。林杏兒議員表示館內緊急求救鈕與對講機缺乏標示，且男廁未設置求救鈕，建議補齊中英文標示與防護蓋並定期維護防撞設施「男廁為什麼沒有設緊急求救鈕」、「貼一個防水的貼紙標籤」、「定期去維護」。"], "response": "殯葬管理處處長說明電梯指示燈預計 7 月初設置完成，並已與交通局開會調整行人號誌秒數，亦會請義交協助處理臨停秩序「希望 7 月初就可以設置好」、「直接調人行的秒數」、「有排義交」。殯葬管理處處長表示求救鈕會補上中英文說明並於男廁增設，對於緊急對講機標示與防撞條脫落問題亦會請館長儘速處理「中、英文的說明，我們一定會馬上補上」、「男廁的部分……我們會再增設」、「請館長趕快把它弄好」。", "response_removed": false, "topic": "第二殯儀館設施與周邊交通改善"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-27", "2024-05-28"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=1", "transcript_pages": [1092, 1093, 1094, 1095, 1096, 1097, 1098, 1099, 1100, 1101, 1102, 1103], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162", "videos": [{"date": "2024-05-27", "group": 9}, {"date": "2024-05-28", "group": 9}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 2, "heading": "教育部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=19", "transcript_pages": [1355, 1356, 1357, 1358, 1359, 1360, 1361], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 2}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=12", "transcript_pages": [562, 563, 564, 565, 566, 567, 568, 569], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A