6139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=1", "transcript_pages": [4399, 4400, 4401, 4402, 4403, 4404], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162", "videos": [{"date": "2024-05-21", "group": 17}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162','2026-10-05T12:15:14Z');
INSERT INTO "fact" VALUES('summary:14-03:p9ff03a516c','p9ff03a516c','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:16:52Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4219, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=25"}, {"page": 4227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=33"}, {"page": 4227, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=33"}, {"page": 4228, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=34"}, {"page": 4220, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=26"}, {"page": 4223, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=29"}], "councilor_points": ["林珍羽議員指出臺北市政府宣稱與台智光終止合約，詢問市府各機關是否已實質建立網路備援機制。林珍羽議員表示經現場詢問近40個市府局處單位，多數機關僅處於「洽談中」且無實質備援機制，質疑市府「在打假球」。"], "response": "資訊局局長說明警察局CCTV子約已終止，但母約尚未解除，各單位仍持續使用台智光服務。稅捐稽徵處資訊室主任、消防局救災救護指揮中心技正、臺北捷運公司資訊處主任等官員說明，部分單位已有切換中華電信或雙通道等備援機制，其餘多數局處官員則表示目前正與廠商洽談備援方案中。", "response_removed": false, "topic": "台智光網路備援機制與合約終止"}, {"citations": [{"page": 1506, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=52"}, {"page": 1507, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=53"}, {"page": 1508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=54"}, {"page": 1508, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=54"}, {"page": 1509, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=55"}, {"page": 1510, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=56"}, {"page": 1511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=57"}, {"page": 1510, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=56"}], "councilor_points": ["林珍羽議員指出市府宣稱推進都市更新與社會住宅結合，但給予2倍獎勵至今無業者申請，質疑政策「淪為紙上談兵」與「芭樂票」。林珍羽議員詢問大同區斯文里二期整宅公辦都更停滯原因，指出市府招標編列每坪19萬元及預備金20萬元之造價不符合市場行情，致招商兩次流標。林珍羽議員要求市府提出明確招商與規劃方向，勿將都更延宕責任歸咎住戶，並要求於下會期開議前提出完整說明報告。"], "response": "市長說明目前手邊有1萬多戶社宅正在進行，並承諾於1個月內提出斯文里二期整宅改採公開徵求投資人的招商報告。", "response_removed": false, "topic": "斯文里整宅都更與都市更新政策"}, {"citations": [{"page": 1646, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=21"}, {"page": 1644, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=19"}, {"page": 1646, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=21"}, {"page": 1647, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=22"}], "councilor_points": ["林珍羽議員指出臺北市國中生補習率超過72.4%，且學生因高課業壓力致自戕意圖比例由2017年的21.3%提升至2023年的28.1%。林珍羽議員指出學校存在早自習以練習卷測驗等規避教學正常化的現象，建議教育局設立專線或申訴信箱供學生反映。"], "response": "教育局局長表示理解學生考試不宜過多，同意內部討論直接反映的管道，並承諾於1個月內研議設置學生申訴信箱。教育局中等教育科科長說明市府以不定期抽查方式至各校訪視教學正常化，若發現未落實將要求學校做相關檢討與改善。", "response_removed": false, "topic": "國中小學生課業壓力與教學正常化督導"}, {"citations": [{"page": 1649, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=24"}, {"page": 1648, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=23"}, {"page": 1650, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=25"}, {"page": 1647, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=22"}], "councilor_points": ["林珍羽議員指出市府編列3年2.5億元推動STEAM教育，但預算多投入於AI生成、3D環景掃瞄儀等設備，過於偏重科技與科學領域。林珍羽議員指出政策缺乏跨領域、動手做及五感學習的實質內容，要求教育局補齊缺失，並於1個月內提供完整計畫報告。"], "response": "教育局局長說明成立STEAM及新科技發展辦公室係為統整資源與做系統性執行，並承諾於1個月內將相關計畫提供給議員辦公室。教育局資訊教育科科長說明推動計畫包含智慧教育、STEAM教育、AI科技及科技人文關懷等項目，希望將科技與自然、數學結合以解決生活問題。", "response_removed": false, "topic": "STEAM與新科技發展辦公室規劃"}, {"citations": [{"page": 1969, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=28"}, {"page": 1970, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=29"}, {"page": 1971, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=30"}, {"page": 1972, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=31"}, {"page": 1974, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=33"}], "councilor_points": ["林珍羽議員指出警察局實際預算缺額達392人且多為巡官以上幹部，加上過多專案評比與長工時，造成基層同仁負擔過重與惡性循環。林珍羽議員要求全面盤點人力、取消無意義專案評比、研議警眷家庭日及檢討科技執法誤判成因，並要求於1個月內提出分析報告。"], "response": "警察局局長說明警力缺額多為巡官以上幹部，外勤基層均盡量補滿，並承諾於1個月內針對盤點人力、取消無必要評比及警眷家庭日等訴求提出評估分析報告。", "response_removed": false, "topic": "基層警力缺額與專案評比負擔"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 16, "heading": "市政總質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=4", "transcript_pages": [1458, 1459, 1460, 1477, 1478, 1479, 1480, 1506, 1507, 1508, 1509, 1510, 1511, 1512, 1521], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162", "videos": [{"date": "2024-06-03", "group": 16}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.g