.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 7}]}, {"dates": ["2024-05-07"], "dept": "工務", "doc_type": "部門質詢", "group": 16, "heading": "工務部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162#page=22", "transcript_pages": [2566, 2567, 2568, 2569, 2570, 2571], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 16}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=25", "transcript_pages": [4219, 4220, 4221, 4222, 4223, 4224, 4225, 4226, 4227, 4228], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162','2026-10-05T12:16:52Z');
INSERT INTO "fact" VALUES('summary:14-03:p41a7902cc9','p41a7902cc9','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:19:35Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1572, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=51"}, {"page": 1998, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=22"}, {"page": 1999, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=23"}, {"page": 1575, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=54"}, {"page": 1571, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=50"}, {"page": 1576, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=55"}, {"page": 1573, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=52"}, {"page": 2001, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=25"}], "councilor_points": ["柳采葳議員指出臺北市近期發生連鎖餐飲店與美食街等食安事件，部分店家初查不合格率偏高且稽查人力有限，詢問市府相關因應措施。柳采葳議員建議修訂《臺北市食品安全自治條例》，要求有營業登記的餐廳至少需有 1 名廚師持證，並提供外語食品安全衛生講習，同時規劃將食安官拉回府級或成立食安處。"], "response": "市長說明市府第一時間已提供寶林茶室受害家屬法律諮詢與發放慰問金，並表示會研議將食安官拉至府級，由秘書長擔任以督導跨局處業務。衛生局局長說明會針對高風險廠商加強稽查、推動預防教育，並表示將研議提供外語衛生講習及修訂相關規範。", "response_removed": false, "topic": "餐飲食安管理與稽查"}, {"citations": [{"page": 2805, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=33"}, {"page": 4231, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=3"}, {"page": 4233, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=5"}, {"page": 4237, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=9"}, {"page": 4236, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665492AE4D4135983F3D97288C089DA7CD17CE7AE925B9367E8F4A852238F00A7C162#page=8"}], "councilor_points": ["柳采葳議員指出許多寵物咖啡廳及動物主題餐廳以動物吸引顧客或販售互動商品，但未取得動物展演許可且缺乏稽查名冊，疑有不當對待動物情形。柳采葳議員要求動保處應於《臺北市動物保護自治條例》新增場所規範與稽查機制，並輔導業者取得動物展演許可及建立列管名冊。"], "response": "動保處處長表示不支持以寵物為噱頭吸引客人的餐廳，並說明若業者涉及違反動保法或未妥善飼養會依法處置，後續將研議議員提出修改自治條例與輔導業者的建議。", "response_removed": false, "topic": "動物主題餐廳管理與稽查"}, {"citations": [{"page": 2789, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=17"}, {"page": 2790, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=18"}, {"page": 2793, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=21"}, {"page": 2796, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=24"}, {"page": 2796, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=24"}, {"page": 2798, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=26"}, {"page": 2790, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=18"}, {"page": 2792, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=20"}], "councilor_points": ["柳采葳議員指出兒少性剝削案件中性影像外流嚴重，且接獲通報後影片下架率低、行政裁處困難，詢問市府處理機制與下架成效。柳采葳議員要求社會局與警察局加強橫向聯繫及合作追查犯罪網站，並優化警方受理報案流程與教育訓練。"], "response": "社會局局長說明兒少性影像會依規要求限期下架或封網，因網站多設置於國外致裁處困難，後續會與警察局研議加強合作並向中央反映改善限制接取與封網流程。警察局婦幼警察隊隊長說明警方負責查緝與通報衛福部性影像處理中心下架，並持續對同仁辦理保護被害人隱私之教育訓練。", "response_removed": false, "topic": "數位性暴力與非法兒少性影像處理"}, {"citations": [{"page": 1564, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=43"}, {"page": 1565, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=44"}, {"page": 698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=22"}, {"page": 699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=23"}, {"page": 1565, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=44"}, {"page": 1567, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=46"}, {"page": 1568, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=47"}, {"page": 1566, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=45"}, {"page": 700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=24"}], "councilor_points": ["柳采葳議員指出電動輔助自行車與微型電動二輪車僅以有無腳踏板做分辨易生混淆，且電輔車可經改裝或解碼提高時速，行駛於人車共道對行人安全構成威脅。柳采葳議員建議市府將電輔車納入登記並懸掛牌照，且應與鄰近縣市統一路權規範，加強違規稽查與自行車道規劃。"], "response": "市長回應表示若業者或消費者刻意改裝造成執法誤導會進行檢討，並說明市府會朝多元方式規劃專用自行車道或人車分流。交通局局長說明電動輔助自行車若經改裝會影響執法辨識，已向中央反映納入管理，並表示雙北與桃園已達成共識車速規範在每小時 25 公里以下及設置於足夠寬的人車共道，後續會檢討安全與法規統一性。", "response_removed": false, "topic": "電動輔助自行車與微型電動二輪車管理"}, {"citations": [{"page": 1577, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=56"}, {"page": 1464, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=3"}, {"page": 1464, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=3"}, {"page": 1465, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=4"}, {"page": 1467, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=6"}, {"page": 1466, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=5"}, {"page": 1463, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=2"}], "councilor_points": ["柳采葳議員詢問臺北大巨蛋何時能舉辦演唱會，並指出營運單位向台灣建築中心遞交之審查資料未獲收件，要求市府釐清卡關原因並積極協助突破。柳采葳議員亦關注大巨蛋票房抽成改為無上限及公益檔期僅 10 天問題，建議市府研議增加公益檔期天數。"], "response": "體育局局長說明大巨蛋臨時性使用可舉辦演唱會，近期會召開跨局處會議檢討使用執照註記及協助遠雄釐清性能審查範圍，關於抽成無上限是指票價回歸市場機制且 10% 抽成比例固定，公益檔期依 111 年合約之 10 天辦理，未來若有需要會與遠雄討論。文化局局長表示若確定通過相關檢討條件，文化局會全力協助配合業界需求。", "response_removed": false, "topic": "臺北大巨蛋舉辦演藝活動與營運規範"}, {"citations": [{"page": 2798, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=26"}, {"page": 2798, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=26"}, {"page": 2799, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=27"}, {"page": 2799, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=27"}, {"page": 2800, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=28"}, {"page": 2800, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=28"}, {"page": 2801, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=29"}, {"page": 2802, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=30"}, {"page": 2802, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654971F7EB66CE54679912CC16D0BB253DCCDDBEB58EF652499BA852238F00A7C162#page=30"}], "councilor_points": ["柳采葳議員指出北市兒少保護通報案件增加，部分行政區保母訪視員負荷過重且庶務繁多，要求社會局調整工作內容與規劃薪資調整。柳采葳議員亦針對保母拒訪漏洞，要求社會局訂定明確的拒訪應變指引與懲處規範。"], "response": "社會局局長說明以實際收托人數計算訪視員負擔可接受，若有增加人力需求會行溝通，調薪案正簽文處理中。社會局局長另表示將訂定保母拒訪工作指引並納入教育訓練，於 2 個月內完成研議與相關規範。", "response_removed": false, "topic": "保母托育訪視與兒少保護機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-04"], "dept": null, "doc_type": "市政總質詢", "group": 17, "heading": "市政總質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162#page=42", "transcript_pages": [1563, 1564, 1565, 1566, 1567, 1568, 1569, 1570, 1571, 1572, 1573, 1574, 1575, 1576, 1577], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549E3C70BFF0E1757C384238DA7F47DCACF0EB2EFA673FBDF20A852238F00A7C162", "videos": [{"date": "2024-06-04", "group": 17}]}, {"dates": ["2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 8, "heading": "教育部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162#page=1", "transcript_pages": [1462, 1463, 1464, 1465, 1466, 1467, 1468, 1469], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654956A34E537880B4EDF3C76F532C2F395C0BF34705C5BBB85AA852238F00A7C162", "videos": [{"date": "2024-04-12", "group": 8}]}, {"dates": ["2024-04-19", "2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 10, "heading": "交通部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162#page=21", "transcript_pages": [697, 698, 699, 700, 701], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549A30112F9E4AEFCBFC21607C8E540D49B150C31F6EEF4A6F0A852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 10}, {"date": "2024-04-22", "group": 10}]}, {"dates": ["2024-04-29"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 10, "heading": "警政衛生部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162#page=20", "transcript_pages": [1996, 1997, 1998, 1999, 2000, 2001, 2002], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549FDB8305EBCC43BB1616BC257C5FAB6DEAD82608CAA2E7D8FA852238F00A7C162", "videos": [{"date": "2024-04-29", "group": 10}]}, {"dates": ["2024-05-03"], "dept": "工務", "doc_type": "部門質詢", "group": 8, "heading": "工務部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654977E4ABDE3FD58AB4FE14BF6EFE3272FDA7667363378F6B8FA852238F