INSERT INTO "fact" VALUES('summary:14-03:paf86790352','paf86790352','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:21:26Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 606, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=8"}, {"page": 608, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=10"}, {"page": 612, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=14"}, {"page": 607, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=9"}, {"page": 610, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=12"}, {"page": 611, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549712731ED5321C0F06B29A287333E31DCD56BE22B42FB17BAA852238F00A7C162#page=13"}], "councilor_points": ["楊植斗議員指出，臺北市設置 192 個有聲號誌，每年維修費用達 800 萬元至 900 萬元，但市府門口路口實測四個角落有三個故障，評估「妥善率很低」。楊植斗議員建議市府應要求廠商保固與妥善率，並多推廣結合「臺北好行」APP 之藍牙導向讀報系統，以逐步取代易生噪音干擾與高故障率之蜂鳴器設備。"], "response": "交通管制工程處處長說明，因前幾年原廠停產，自 111 年起尋找新廠商重新開模與生產設備，致維護費用上升，新設設備均要求保固 1 年以上；目前已試辦結合藍牙與 APP 自動讀報秒數系統，每年約增加 3 至 5 個路口，並會持續收集使用者意見進行檢討與推廣。交通局局長表示，市政府路口故障率 75%「不太及格」，並說明靠個人隨身手機讀報是未來發展方向，若設備穩定度高值得繼續開發。", "response_removed": false, "topic": "有聲號誌維護改善與藍牙導向推廣"}, {"citations": [{"page": 4337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=12"}, {"page": 4338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=13"}, {"page": 4338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=13"}, {"page": 4339, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=14"}, {"page": 4341, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=16"}, {"page": 4342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FF19BCC69EF015A39C5DC727A438FBB294B7A00083F2CF44A852238F00A7C162#page=17"}], "councilor_points": ["楊植斗議員指出，動物保護處獸醫師與民間薪水相差約一倍，導致 35 位獸醫師編額中缺額達 10 位左右，招考常無人報到，要求市府研擬加薪或改善待遇以留住人才。楊植斗議員表示，飼主不擬續養寵物一次性收取 1 萬 4,000 元費用並不合理，建議市府針對非生重病或非老殘弱之飼主，按月加收照顧留置費用，避免飼主隨意棄置寵物給市府負擔。"], "response": "動物保護處處長說明，目前獸醫師缺額約 10 來個，因薪水與業務壓力導致招募困難，已進行調整將部分行政工作改由非獸醫師職系擔任，並會就按月收取照顧費之建議進行研討。產業發展局局長表示，1 萬 4,000 元不擬續養費用為去年調升後價格，未來若棄養狀況持續增加，會重新檢討相關費用。", "response_removed": false, "topic": "動保處獸醫師缺額與不擬續養規費機制"}, {"citations": [{"page": 1836, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=13"}, {"page": 1837, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=14"}, {"page": 1837, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=14"}, {"page": 1839, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=16"}, {"page": 1840, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=17"}, {"page": 1839, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654951721BC5EDED8C75E33E0D8CA67A1C8679919A116170BDB5A852238F00A7C162#page=16"}], "councilor_points": ["楊植斗議員詢問，市府提高亂丟垃圾罰金至 3,600 元後之裁罰件數與收入變化，並關切第一線清潔隊巡查員執行公權力時遭遇民眾逃跑等困難。楊植斗議員指出，去年巡查員抓獲亂丟垃圾 1 萬多件，但民眾檢舉獲獎僅 88 件，建議市府提高檢舉誘因並宣導明確檢舉要件。"], "response": "環境保護局環境清潔管理科科長說明，全北市 12 區共有 113 位清潔隊員擔任巡查員，去年垃圾包裁處 1 萬 745 件、裁罰收入 2,000 萬元；民眾不配合出示證件為少數，去年 8 月 15 日起已依法加重裁罰起跳金額至 3,600 元。環境保護局局長表示，去年民眾檢舉垃圾包案量為 163 件，因單憑臉部辨識成案難度高，需有明確車牌辨識較易成立，市府會在觀光熱點試設垃圾桶與加強公眾教育間取得平衡。", "response_removed": false, "topic": "行人亂丟垃圾裁罰與巡查告發機制"}, {"citations": [{"page": 2435, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=27"}, {"page": 2437, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=29"}, {"page": 2437, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=29"}, {"page": 2438, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=30"}, {"page": 2439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=31"}], "councilor_points": ["楊植斗議員指出，地震後建管處收到 2,100 多件建物災損陳情，但初期僅 1 位同仁承辦，關切勘查技師車馬費與人力配置，提醒勿讓資源遭到濫用。楊植斗議員關切外牆磁磚剝落補助成效與核定件數，並建議市府清查 3 年或多年無人居住之老舊空屋，評估潛在倒塌風險。"], "response": "建管處處長說明，通報 2,100 多件中已勘查 1,140 多件，核定紅黃單共 19 件，已抽調同仁至 3 人支援；近 3 年外牆剝落申請 290 多件、核定 230 多件，預計 1 個月內提出結合稅捐、水電紀錄套疊篩選老舊無人居住空屋之計畫。都市發展局局長說明，已向市府回報勘查人力狀況，改由各區公所人員共同協助處理。", "response_removed": false, "topic": "震後建物安全勘查與老舊空屋風險清查"}, {"citations": [{"page": 2431, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=23"}, {"page": 2435, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=27"}, {"page": 2434, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=26"}, {"page": 2434, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=26"}, {"page": 2435, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549BB885E85B6A8DB45E8AB417E9C2239A281A4A7114062A8DCA852238F00A7C162#page=27"}], "councilor_points": ["楊植斗議員詢問，京華城工程施工進度及若檢調調查涉及不法時市府之處置機制，關切是否包含勒令停工或要求拆除之選項。楊植斗議員要求都市發展局說明容積率從 560%增加至 840%所衍生之獲利估算金額，並釐清市府依法可爭取之回饋金額與處置法源。"], "response": "都市發展局局長說明，京華城目前進行連續壁施作，施工進度尚未達 30%，近期會找法務局討論不同法律層面之停工標準，若停工需經都市計畫層面處理，可依《臺北市土地使用分區管制自治條例》第 80 條之 2 要求淨利 70%之回饋。建管處處長說明，該工程地下室構造係延續原本建築物結構施作。", "response_removed": false, "topic": "京華城容積率爭議與停工處置標準"}, {"citations": [{"page": 1587, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=3"}, {"page": 1591, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=7"}, {"page": 1591, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=7"}], "councilor_points": ["楊植斗議員指出，北市某高中發生特教生與教師肢體衝突事件，因原任課教師請假交接疏漏，致兼代課之學務處組長不知該生為特教生，要求教育局檢討通報與交接 SOP。楊植斗議員表示，109 年至 113 年師生肢體衝突通報共 41 件，其中涉及特教生達 24 件，建議教育局落實特教生個別化教育計畫（IEP），避免特教生遭到汙名化。"], "response": "教育局局長說明，該校有 63 位特教生，因代課教師交接疏漏未掌握資訊，教育局已重新修訂 SOP 發給學校落實；將建立完整通報系統與預警制度，落實 IEP 輔導與用藥追蹤，以達預防效果。", "response_removed": false, "topic": "特教生校園衝突與資訊交接機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-28"], "dept": null, "doc_type": "市政總質詢", "group": 10, "heading": "市政總質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162#page=23", "transcript_pages": [1247, 1248, 1249, 1250, 1251, 1252, 1253, 1254, 1255, 1256, 1257, 1258, 1259, 1260, 1261, 1262, 1263, 1264, 1265], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162", "videos": [{"date": "2024-05-28", "group": 10}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 14, "heading": "教育部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162#page=1", "transcript_pages": [1585, 1586, 1587, 1588, 1589, 1590, 1591, 1592], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549833EB156A32CC3BAF14FAC8823DCF093620739B3648AE048A852238F00A7C162", "videos": [{"date": "2024-04-16", "group": 