INSERT INTO "fact" VALUES('summary:14-03:p6ad3a2608b','p6ad3a2608b','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T12:23:16Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=3"}, {"page": 2699, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=4"}, {"page": 2700, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=5"}, {"page": 2701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=6"}, {"page": 2698, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=3"}, {"page": 2703, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=8"}, {"page": 2701, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549B8CB2A54F039907619AB249D356180B135B355E30C98499AA852238F00A7C162#page=6"}], "councilor_points": ["汪志冰議員指出臺北市房地產價格高而易成為不動產詐騙目標，但全臺北市僅1萬7,171人申請「地籍異動即時通」，顯見宣導成效有限。汪志冰議員建議地政局應與地政士長期合作推廣，並要求與稅捐稽徵處協調在地價稅及房屋稅繳款信封封面加註警語與QR Code，方便民眾掃碼申請。"], "response": "地政局局長說明已於112年11月修改作業流程，對久未繼承等異常登記主動調查並進行電話或電子郵件通知。地政局局長表示會持續與地政士公會合作推廣，並已與稅捐稽徵處處長溝通，規劃於稅單信封封面印製QR Code以方便民眾申請。", "response_removed": false, "topic": "地籍異動即時通推廣與不動產防詐措施"}, {"citations": [{"page": 4276, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665495293B4A8A1D89332AE45A062B585EDF6ED2AB8F77BF17D4BA852238F00A7C162#page=10"}, {"page": 4277, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665495293B4A8A1D89332AE45A062B585EDF6ED2AB8F77BF17D4BA852238F00A7C162#page=11"}], "councilor_points": ["汪志冰議員指出依動物保護法規定寵物應辦理絕育，但臺北市未絕育犬貓累計達5萬7,603隻，且9年間絕育補助申請數僅4萬4,000多隻，顯見補助量能不足。汪志冰議員建議動物保護處應提高絕育補助額數與誘因，並與獸醫師公會及動物醫院合作，由醫院於絕育時主動協助登錄資訊。"], "response": "動物保護處處長說明因每年絕育補助經費固定，僅約四分之一的民眾能申請到補助。動物保護處處長表示會研議提高補助額數，並承諾與相關公會合作協助更新登記資訊及訂定年度目標。", "response_removed": false, "topic": "家犬貓絕育管理與補助推廣"}, {"citations": [{"page": 2342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=13"}, {"page": 2342, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=13"}, {"page": 2347, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=18"}, {"page": 2344, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=15"}, {"page": 2345, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654960331708B7F416A52D96D6E0FD4FD04EFA05D2FEF077DAB8A852238F00A7C162#page=16"}], "councilor_points": ["汪志冰議員指出臺北市30年以上老舊建物達10萬棟，且921與331震災至今仍有47件黃單建物未補強或拆除，存在安全隱憂。汪志冰議員建議市府應分階段公告0403震災受損清單，並設立單一窗口服務民眾，同時對逾期未補強建物依法開罰行政怠金及儘速提出修繕補助方案。"], "response": "建築管理工程處處長說明目前正進行0403震災通報案件勘檢，預計2個月內完成並依行政一貫性上網公告，且已於上週開始對逾期未補強者裁處行政怠金。都市發展局局長表示市府已著手研擬修繕補助方案，會儘速擬定後陳報市府並對外公告。", "response_removed": false, "topic": "地震危險建物列管與修繕補助機制"}], "sessio