INSERT INTO "fact" VALUES('summary:14-03:pb8d278f1da','pb8d278f1da','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:06:33Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 4389, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=11"}, {"page": 4390, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=12"}, {"page": 4391, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=13"}, {"page": 4392, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=14"}, {"page": 4388, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=10"}, {"page": 4392, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=14"}, {"page": 4395, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665498271A4C00A30AC695FF4CAED741BFE75C7DD2140A677A03CA852238F00A7C162#page=17"}], "councilor_points": ["耿葳議員指出臺中捷運事件引發民眾恐慌，建議捷運公司加強廣播宣導緊急求救鈕之使用與通報方式（引文：「建議捷運公司在這幾天或未來做持續性、高強度的廣播」、「加強宣導乘客遇到緊急狀況時該怎麼做」）。耿葳議員指出民眾反映搭車遇到持打火機男子，站務人員因規定無法使用手機記錄照片，影響即時通報（引文：「站務人員很想和這位媽媽拿照片還有影片，但是沒辦法，因為他們規定不能用手機」、「連你們的站務人員都不能拿手機，也不能即時的記下對方長相，即時的通報」）。耿葳議員要求捷運警察隊與捷運公司針對重大案件加強橫向對接，於 1 個月後提出精進計畫（引文：「希望捷運警察隊強力與捷運公司做對接」、「希望在 1 個月後給我非常明確的精進計畫」）。"], "response": "臺北大眾捷運股份有限公司站務處副處長表示會透過廣播、月台電視與 App 加強宣導（引文：「透過廣播或月台、閘門旁的電視」）。警察局捷運警察隊隊長表示已調閱影像鎖定持打火機男子並提供資料給派出所通知到案，承諾會與捷運公司重新檢討作業程序並於 1 個月後提出精進計畫（引文：「我們有調閱影像跟票卡後鎖定對象」、「後續會把資料提供給受理的派出所，通知他到案」）。", "response_removed": false, "topic": "捷運車廂安全應變與橫向聯繫機制"}, {"citations": [{"page": 1439, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB963735665491612CABE0711A2501E1647A0875B037BDECEB3AE12CD7D83A852238F00A7C162#page=14"}, {"page": 1441, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB963735665491612CABE0711A2501E1647A0875B037BDECEB3AE12CD7D83A852238F00A7C162#page=16"}, {"page": 1440, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB963735665491612CABE0711A2501E1647A0875B037BDECEB3AE12CD7D83A852238F00A7C162#page=15"}], "councilor_points": ["耿葳議員指出 0403 花蓮大地震造成全市 202 所學校校舍受損，其中大安、文山區有 55 所學校受損（引文：「總計有 202 所學校受損」、「大安、文山區為例，就有 55 所學校校舍受損，占全市校舍受損 28%」）。耿葳議員指出公立學校校舍過半數屋齡逾 40 年，質疑教育局提供的改建校舍資料將已完工學校納入，要求數據應精準不可美化數字（引文：「公立學校校舍總共有 1,520 棟，其中有 60%，過半以上的屋齡超過 40 年」、「去年(112 年)已經有 4 所學校早就完工」、「本席希望臺北市政府拴緊螺絲……不要為了美化數字趕快把資料丟出來」）。耿葳議員要求教育局局長盡力爭取大幅增加校舍改建預算，維護學生安全（引文：「請局長盡力爭取，讓校舍改建比例或是預算大幅增加，小朋友才能在無虞安全的環境下好好上課」）。"], "response": "教育局局長說明統計資料為各校通報，已有 147 所學校提出災損、經費 1 億 800 萬元，並表示盤整計畫後每年改建預算擬由 21 億元調高至 40 億元（引文：「後來統計有 147 所學校提出災損，經費 1 億 800 萬元」、「市政府要將原來的 21 億元預算調高至 40 億元」）。教育局工程及財產科科長表示會再加強資料彙整精準度（引文：「報告議員，這部分我們再加強」）。", "response_removed": false, "topic": "老舊校舍改建計畫與災損評估"}, {"citations": [{"page": 1807, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DA346A16229943EFBF6354478D7BA7D90130076B8C6952F1A852238F00A7C162#page=14"}, {"page": 2325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549DE5A2B5D990F0B719111A06633E96F00FEFBF7E86C0ECDBFA852238F00A7C162#page=15"}, {"page": 2325, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549DE5A2B5D990F0B719111A06633E96F00FEFBF7E86C0ECDBFA852238F00A7C162#page=15"}, {"page": 2327, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549DE5A2B5D990F0B719111A06633E96F00FEFBF7E86C0ECDBFA852238F00A7C162#page=17"}], "councilor_points": ["耿葳議員指出淡水河空間環境改造工程期程為期 5 年、花費 18 億元，質疑工務局未將施政願景列入委員會報告即逕行官宣（引文：「這個淡水河空間環境改造期程總共多久……將為期 5 年！」、「工期總共是 5 年，花費 18 億元」、「從頭到尾沒有看到這個計畫出現在議員的桌上」）。耿葳議員指出該案動用其他工程項目經費進行規劃，要求市府重大計畫應落實溝通與程序，避免先 po 上網後才規劃（引文：「先動用 113 年的河川及雨水下水道工程經費……總預算 1,000萬元進行規劃設計」、「未來臺北市政府在做任何規劃，都不要這麼地草率。應該要走的流程，就要確實地完成」）。耿葳議員建議市府比照淡水河岸計畫，針對文山區景美溪流域評估設置大型遊憩區或生態藝廊（引文：「是否針對文山區景美溪流域附近，做一些大型的遊憩區、生態藝廊」）。"], "response": "工務局局長說明淡水河岸改造案尚在規劃程序中，正進行訪談與籌備說明會（引文：「還在規劃的程序當中」、「目前正在訪談，後續也會有說明會」）。水利工程處處長說明規劃案係動用河川溪溝案約 390 萬元，並表示景美溪支流指南溪正進行整體生態改造工程（引文：「大概用了 390 萬元」、「景美溪支流指南溪正在進行整體工程改造……營造出生態型的緩坡護坡工程」）。", "response_removed": false, "topic": "淡水河岸改造工程與景美溪水岸規劃"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-24"], "dept": null, "doc_type": "市政總質詢", "group": 7, "heading": "市政總質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DBF677844579277FF9957C254D2A087C12BF63455AAE745DA852238F00A7C162#page=20", "transcript_pages": [1026, 1027, 1028, 1029, 1030, 1031, 1032, 1033, 1034, 1035, 1036, 1037, 1038, 1039, 1040, 1041], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549DBF677844579277FF9957C254D2A087C12BF63455AAE745DA852238F00A7C162", "videos": [{"date": "2024-05-24", "group": 7}]}, {"dates": ["2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 6, "heading": "教育部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB963735665491612CABE0711A2501E1647A0875B037BDECEB3AE12CD7D83A852238F00A7C162#page=12", "transcript_pages": [1437, 1438, 1439, 1440, 1441, 1442, 1443], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654