INSERT INTO "fact" VALUES('summary:14-03:p369c0f3b74','p369c0f3b74','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:13:10Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1363, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=28"}, {"page": 1368, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=33"}, {"page": 1539, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=18"}, {"page": 1543, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=22"}, {"page": 2357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=10"}, {"page": 2358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=11"}, {"page": 1540, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=19"}, {"page": 1543, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=22"}, {"page": 2359, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=12"}, {"page": 2360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=13"}], "councilor_points": ["許淑華議員指出大巨蛋營運後屢發設備問題，要求市府建立監督機制，若廠商連續 2 年評分低於 70 分應依法終止契約。許淑華議員建議市府成立審查單位評估防火逃生避難安全以辦理演唱會，並要求找第三方單位重新精算營收分潤。許淑華議員詢問大巨蛋全區開放時間，要求市府於年底前爭取進行 59,833 人的全區滿載測試。"], "response": "市長表示會依合約機制處理，並同意在 1 個月內完成評比機制且委員會不讓廠商參與。體育局局長說明會召開跨局處會議討論防火逃生避難安全，並表示會在 2 個月內提出營收分潤方案。體育局主任秘書與建築管理工程處處長說明全區預計明年開放，舉辦臨時性活動須由第三方機構做防火避難驗證，並會與廠商研議滿載測試。", "response_removed": false, "topic": "大巨蛋營運監督與安全機制"}, {"citations": [{"page": 2025, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=4"}, {"page": 2027, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=6"}, {"page": 2028, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=7"}, {"page": 4089, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=1"}, {"page": 4090, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=2"}, {"page": 4092, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=4"}, {"page": 2026, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=5"}, {"page": 2028, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=7"}, {"page": 4091, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=3"}], "councilor_points": ["許淑華議員詢問警察局終止台智光子約後的硬體轉移與備援進度，要求明年預算改依母約核定價格編列，並建議若廠商 5 月 2 日未出席協調應於 5 月內研議提起訴訟。許淑華議員指出前市府拍板 3M 傳輸費率 2,200 元之合規性疑慮，要求資訊局與警察局於 6 月底前提出備援方案以確保 18,000 支警用監視器不斷網。"], "response": "警察局局長與法務局副局長說明終止子約後僅會依母約 TGSN 支付 1,761 元，若廠商不出席協調不排除直接提起訴訟，並已著手準備備援方案。警察局犯罪預防科科長說明費率係依府函發下執行，並表示絕對不會讓監視器斷網。資訊局局長說明已接觸 6 家有意願的廠商提供給警察局。", "response_removed": false, "topic": "台智光案與警用監視器傳輸費率處置"}, {"citations": [{"page": 2959, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=24"}, {"page": 2963, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=28"}, {"page": 2964, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=29"}, {"page": 2965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=30"}, {"page": 2965, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=30"}, {"page": 2966, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=31"}, {"page": 2962, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=27"}], "councilor_points": ["許淑華議員詢問青年局 6 月 1 日掛牌的員額配置與人事預算編列情況，指出基層人力缺乏，要求市府釐清 50 人編制與約僱人員等預算細節。許淑華議員詢問青創貸款業務自產發局移撥的辦理進度，要求說明有擔保與無擔保貸款期限，並建議市府與銀行洽談降低貸款利率。"], "response": "青年局局長說明預計 6 月 1 日派令會有 47 人以上，加上 5 名約僱人員共有 55 人，年度總預算約為 2 億 6,000 多萬元。青年局局長表示青創貸款業務因切分困難預計於明年初移撥承接，會進一步了解貸款期限等細節並朝降低利率方向推動。秘書長表示會後會再提供補充資料。", "response_removed": false, "topic": "青年局組織籌備與業務交接"}, {"citations": [{"page": 1356, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=21"}, {"page": 1357, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=22"}, {"page": 1358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=23"}, {"page": 1358, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=23"}, {"page": 1359, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=24"}, {"page": 1359, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=24"}, {"page": 1360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=25"}, {"page": 1360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=25"}], "councilor_points": ["許淑華議員詢問國會職權修法程序是否完備，指出二讀逐條審查未修正文字。許淑華議員質疑藐視國會罪中「反質詢」與「虛偽陳述」缺乏明確法律定義，並詢問悠遊卡公司以商業機密為由不提供資料是否構成藐視議會。許淑華議員指出調查權規定一般民眾等社會關係人不得拒絕繳交資料且拒絕即處 1 萬元至 10 萬元罰鍰，以及民眾接受詢問須經主席同意始得請律師等規定涉及侵害人權，詢問市府立場。"], "response": "市長說明立法院有依議事規則進行相關程序，包含委員會詢答、3 場公聽會及專案報告。市長表示「反質詢」為備詢者不能反問質詢者，「虛偽陳述」為不實陳述，字面上相當清楚，且若牽涉商業機密或個資依法確實不能提供。市長表示尊重立法院三讀通過的法律，若條文有侵犯人權疑慮，可依法定程序由足夠人數連署提出釋憲。", "response_removed": false, "topic": "國會職權修法內容與人權疑慮"}, {"citations": [{"page": 578, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=3"}, {"page": 579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=4"}, {"page": 579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=4"}, {"page": 582, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=7"}, {"page": 583, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=8"}, {"page": 585, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=10"}, {"page": 584, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=9"}, {"page": 582, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=7"}], "councilor_points": ["許淑華議員詢問捷運閘門花費 4.5 億元重置後 Apple Pay 的合作進度，以及何時能讓蘋果手機直接感應進站。許淑華議員指出悠遊卡公司轉投資群信公司與點鑽公司共虧損 2.1 億元，要求聘請外部會計師清查 108 年至 111 年的帳務與轉投資狀況。許淑華議員指出正在測試的貼紙卡售價 350 元過高，要求重新評估價格以親民服務為導向。"], "response": "悠遊卡投資控股股份有限公司董事長說明正持續與蘋果公司溝通，明年底 Apple Pay 可以在新閘門使用，但要在 Apple Pay 下載悠遊卡所需資本額比公司登記資本額 7 億元還高，仍需進一步協商。悠遊卡投資控股股份有限公司董事長說明點鑽公司已轉手、群信公司虧損 3,574 萬元，帳務均有會計師及審計委員會審查，會提供轉投資資料並對可清查部分進行了解。悠遊卡投資控股股份有限公司董事長表示貼紙卡仍在測試尚未正式對外，會將價格檢討建議納入評估。", "response_removed": false, "topic": "悠遊卡公司經營與服務改善"}, {"citations": [{"page": 4092, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=4"}, {"page": 4093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=5"}, {"page": 4093, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=5"}, {"page": 4094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=6"}, {"page": 4094, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=6"}, {"page": 4095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=7"}, {"page": 4095, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=7"}], "councilor_points": ["許淑華議員指出廠商於 109 年 11 月 6 日已發信表示不參與後續投標，詢問市府於 11 月 12 日會議拍板三塊基地拆開招標且 T17 與 T18 免投資計畫書後，又於 12 月 16 日找該廠商訪談之決策流程。許淑華議員詢問政風處調查進度，指出相關人員已公開表示願意配合說明，要求政風處主動約談並於 5 月底前完成調查報告函覆議會。"], "response": "產業發展局工商服務科科長說明第二次流標後係依領標紀錄邀請廠商訪談，該廠商於 12 月 16 日係經由前副秘書長辦公室通知約定後前往。政風處處長說明該案有關 12 月 16 日會議部分已查證至相當段落並回報檢察機關，後續將與檢察官協調聯繫配合，待資料更齊全後再進行約談。", "response_removed": false, "topic": "北士科設定地上權招標案與政風調查"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-31"], "dept": null, "doc_type": "市政總質詢", "group": 13, "heading": "市政總質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=19", "transcript_pages": [1354, 1355, 1356, 1357, 1358, 1359, 1360, 1361, 1362, 1363, 1364, 1365, 1366, 1367, 1368, 1369, 1385, 1386, 1387, 1388, 1389], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162", "videos": [{"date": "2024-05-31", "group": 13}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=16", "transcript_pages": [1537, 1538, 1539, 1540, 1541, 1542, 1543], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 11}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 6, "heading": "交通部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162#page=1", "transcript_pages": [576, 577, 578, 579, 580, 581, 582, 583, 584, 585], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665499D17322D3CC9184577635FFCD1EC325FF8F94C29007FB31BA852238F00A7C162", "videos": [{"date": "2024-04-18", "group": 6}]}, {"dates": ["2024-04-29"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 12, "heading": "警政衛生部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=1", "transcript_pages": [2022, 2023, 2024, 2025, 2026, 2027, 2028, 2029], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162", "videos": [{"date": "2024-04-29", "group": 12}]}, {"dates": ["2024-05-03"], "dept": "工務", "doc_type": "部門質詢", "group": 6, "heading": "工務部門質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=7", "transcript_pages": [2354, 2355, 2356, 2357, 2358, 2359, 2360, 2361], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162", "videos": [{"date": "2024-05-03", "group": 6}]}, {"dates": ["2024-05-13"], "dept": "民政", "doc_type": "部門質詢", "group": 13, "heading": "民政部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=22", "transcript_pages": [2957, 2958, 2959, 2960, 2961, 2962, 2963, 2964, 2965, 2966, 2967, 2968], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162", "videos": [{"date": "2024-05-13", "group": 13}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 3, "heading": "財政建設部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=1", "transcript_pages": [4089, 4090, 4091, 4092, 4093, 4094, 4095, 4096], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162", "videos": [{"date": "2024-05-16", "group": 3}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162','2026-10-06T03:13:10Z');
INSERT INTO "fact" VALUES('summary:14-03:p4cf586308f','p4cf586308f','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-05T14:01:58Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=20"}, {"page": 1113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=22"}, {"page": 1113, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=22"}, {"page": 571, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=21"}, {"page": 571, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=21"}, {"page": 573, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=23"}, {"page": 574, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=24"}, {"page": 573, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665498A35F8A1AD9B9631177F6D23902B8021C2D9CF73C18B6C8AA852238F00A7C162#page=23"}], "councilor_points": ["詹為元議員指出YouBike坐墊晃動與車輛久占問題，建議參考日本經驗試辦前90分鐘免費、超時收費之智慧停車鎖管理，並關注引進YouBike 2.01電動車之騎乘規範。詹為元議員指出YouBike「見車率」以全日平均計算且以一輛車即認定有車，無法真實反映尖峰時段與非熱門站點之缺車情形，建議獨立統計尖峰時間見車率並優化調度人力。"], "response": "交通局局長說明YouBike坐墊晃動係為利故障翻轉之設計，2.01電輔車規劃速限25公里並擬降至20公里不再供電，且會與新北市溝通騎乘規範。停車管理工程處處長與市長說明，將評估找尋合適空間試辦智慧自行車停車格，科技大樓立體停車場亦規劃採此管理方式。交通局局長與交通局運輸管理科科長說明，見車率以九成以上為目標，內部已就各站點時段進行細部分析，並會向微笑單車公司建議增加調度人力。", "response_removed": false, "topic": "公共自行車營運與自行車停放管理"}, {"citations": [{"page": 1104, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=13"}, {"page": 1114, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=23"}, {"page": 1349, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=13"}, {"page": 1350, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=14"}, {"page": 1351, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=15"}, {"page": 1351, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=15"}, {"page": 1352, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=16"}, {"page": 1353, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=17"}, {"page": 1103, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=12"}, {"page": 1349, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=13"}], "councilor_points": ["詹為元議員詢問大巨蛋舉辦演唱會是否適用建築技術規則第127條，建議市府要求遠雄公司就超過5,000人等不同級距人流做好防災避難逃生模擬標準。詹為元議員指出大巨蛋育嬰哺乳室數量不足且拉簾缺乏隱私安全感，要求體育局督導遠雄公司於兩週內改善哺乳室可鎖拉門並於一個月內確定無障礙廁所增設尿布檯。詹為元議員反映大巨蛋外野電梯未啟用及手扶梯停用問題，建議開放身障者與帶小孩家長優先使用電梯，並要求體育局詢問遠雄公司將一、三壘側白色柱子改為隱形護網之意願與時程，以及建議規劃參觀行程。"], "response": "市長與建築管理工程處處長說明，內政部函釋大巨蛋不適用建築技術規則第127條，而係依大型群聚活動自治條例管理，凡超越原本模擬人數均需重新驗證，遠雄公司完成安全驗證及審查後即可供活動主辦方適用。體育局局長說明，正評估於無障礙廁所加裝簡易尿布檯，並會督導遠雄公司將哺乳室拉簾改為可上鎖裝置與研議增設空間。體育局局長表示，外野電梯完成驗證後即可啟用，並會將改善護網與規劃參觀行程等建議轉達遠雄公司要求明確回復。", "response_removed": false, "topic": "大巨蛋營運管理與設施改善"}, {"citations": [{"page": 2993, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=22"}, {"page": 2993, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=22"}, {"page": 2995, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=24"}, {"page": 2996, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=25"}, {"page": 2996, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549514FB81F794B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162#page=25"}], "councilor_points": ["詹為元議員關切臺北市首創「事業單位實施居家工作勞動條件保障指導原則」之落實情形，指出雇主於非工作時間發送訊息應加註「無須立即回覆」之提醒文字。詹為元議員指出該原則無法律罰則且民眾檢舉仍需回歸勞基法，建議勞動局加強對勞工端之權益宣導，並提前準備爭議認定機制與申訴管道。"], "response": "勞動局局長說明，指導原則明定居家工作之上下班時間與加班方式，若雇主交辦工作要求即時交付且未給付加班費，勞工可提出申訴或申請調解。勞動局局長與勞動局勞動基準科科長表示，實務上主張離線權之陳情案件不多，目前已透過商業同業公會等管道宣導，未來會持續對資方宣導並加強勞工之權利認知。", "response_removed": false, "topic": "勞工離線權指導原則與落實"}, {"citations": [{"page": 2137, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654985C772EACDC91825360E5589BB18C949837929985A43E94EA852238F00A7C162#page=20"}, {"page": 2138, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654985C772EACDC91825360E5589BB18C949837929985A43E94EA852238F00A7C162#page=21"}, {"page": 2139, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654985C772EACDC91825360E5589BB18C949837929985A43E94EA852238F00A7C162#page=22"}, {"page": 2141, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654985C772EACDC91825360E5589BB18C949837929985A43E94EA852238F00A7C162#page=24"}, {"page": 2142, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654985C772EACDC91825360E5589BB18C949837929985A43E94EA852238F00A7C162#page=25"}], "councilor_points": ["詹為元議員質詢標線型人行道違停檢舉案遭以無法證明停滿3分鐘為由不成立不合理，建議警察局針對不同違規樣態區別對待，以保障行人通行權。詹為元議員指出詐騙損失金額逐年上升，且「解除分期付款」等老梗詐騙類型仍高居第二，建議警察局編列預算進行網路數位廣告之精準投放。"], "response": "警察局局長說明，臨停規定為3分鐘，若警察在場會開單，並表示未來針對佔用標線型人行道且阻礙通行之明顯違規行為應該可以開單。警察局局長說明打詐臺北隊已進行分齡分眾及百工百業宣導，並表示認同針對手機投放精準廣告之建議，會回去研議處理。", "response_removed": false, "topic": "詐騙防制與交通違規檢舉"}, {"citations": [{"page": 2456, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=9"}, {"page": 2456, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=9"}, {"page": 2458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=11"}, {"page": 2458, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=11"}, {"page": 2457, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654916327303172E381A8C7717274067087FB4846551C327D708A852238F00A7C162#page=10"}], "councilor_points": ["詹為元議員指出臺北市土壤液化中、高潛勢區面積佔全市32%，且許多老舊建築興建於規定做地質調查之前，詢問市府對舊建築之土壤液化調查與補強作為。詹為元議員質詢土壤液化高風險區是否給予都市更新獎勵，並建議市府結合建築結構安全重新修訂劃定標準，提供市民明確之判斷依據。"], "response": "工務局局長說明，土壤液化分析係採用素地資料，若建築物已有地下室基礎結構則較不受液化影響，目前結構安全考慮以承受地震搖晃之梁柱為主。都市發展局局長說明，都更案均需做地質鑽探，進行地質改良者向第三方公正單位申請耐震標章即可獲得獎勵。工務局局長表示，會回去檢討評估標準。", "response_removed": false, "topic": "土壤液化潛勢區評估與都更獎勵"}, {"citations": [{"page": 4410, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=12"}, {"page": 4410, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=12"}, {"page": 4412, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=14"}, {"page": 4412, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=14"}, {"page": 4413, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=15"}, {"page": 4414, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=16"}, {"page": 4411, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=13"}], "councilor_points": ["詹為元議員指出「臺北市智慧城市產業場域實驗試辦計畫」近兩成案件中途終止，且獲獎之機車智慧車鎖計畫試辦後亦未續辦，質詢試辦計畫轉化率不到兩成之問題。詹為元議員要求資訊局於新創計畫獲獎或試辦完成後進行後續追蹤、輔導及跨局處檢討，釐清廠商困境以落實新創城市精神。"], "response": "停車管理工程處營運科科長說明，機車智慧停車鎖試辦可行，但考量普及化設備費用較高、維護問題及民眾使用習慣，故當時未討論實際上線。資訊局局長說明，試辦計畫轉換率確實不到兩成，今年已提供廠商部分實作成本補貼以列管進度，並會面對廠商癥結點進行檢討與努力。", "response_removed": false, "topic": "智慧城市試辦計畫與創新轉化"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-27", "2024-05-28"], "dept": null, "doc_type": "市政總質詢", "group": 9, "heading": "市政總質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162#page=12", "transcript_pages": [1103, 1104, 1105, 1106, 1107, 1108, 1109, 1110, 1111, 1112, 1113, 1114], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162", "videos": [{"date": "2024-05-27", "group": 9}, {"date": "2024-05-28", "group": 9}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 2, "heading": "教育部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162#page=12", "transcript_pages": [1348, 1349, 1350, 1351, 1352, 1353, 1354, 1355], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654992A4A18380BBDB32B5F0F8D2154AD6A700AE3680C1266EFEA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 2}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 5, "heading": "交通部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0