4B01621CC900482EDC67FB28E59E2CC83CE97EA852238F00A7C162", "videos": [{"date": "2024-05-14", "group": 14}]}, {"dates": ["2024-05-21"], "dept": "財政建設", "doc_type": "部門質詢", "group": 17, "heading": "財政建設部門質詢第17組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162#page=11", "transcript_pages": [4409, 4410, 4411, 4412, 4413, 4414, 4415, 4416, 4417], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FFAB130A2EA1DFD91EFEEDFEFFF61AE91D1E6E4F1C5BCF64A852238F00A7C162", "videos": [{"date": "2024-05-21", "group": 17}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654930E4EF0B2551E80F2D5DA55BF83AED798C4E253B4564BB96A852238F00A7C162','2026-10-05T14:01:58Z');
INSERT INTO "fact" VALUES('summary:14-03:p3d9ce55419','p3d9ce55419','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:14:42Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1292, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=16"}, {"page": 1293, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=17"}, {"page": 1295, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=19"}, {"page": 1297, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=21"}, {"page": 1298, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=22"}, {"page": 1294, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=18"}], "councilor_points": ["鍾佩玲議員指出臺北市截至2023年底有2萬1,432戶低收入戶，並詢問「青年培力希望發展帳戶專案」未來是否改由青年局管轄。鍾佩玲議員表示該專案平均每戶每月僅存1,300多元，且課程參與率僅約二成、參與家戶數僅占符合資格戶數的3%，要求市府檢討課程時間並提出提高儲蓄金額的手段。鍾佩玲議員建議研擬考取證照給予獎金等激勵方式，並要求社會局與青年局加強橫向聯繫。"], "response": "社會局局長說明該計畫主要針對高中生與大學生培養儲蓄習慣，將研究調整開課時間至假日，並持續推動職能培力獎金。臺北市長表示該計畫參與比例過低確實需要改進，市府會重新檢視累積數據，並思考預先提供第一筆存款加成金以增加誘因。", "response_removed": false, "topic": "低收入戶青年脫貧與儲蓄培力專案"}, {"citations": [{"page": 2757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=7"}, {"page": 4117, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=1"}, {"page": 4121, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=5"}, {"page": 4119, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=3"}, {"page": 4120, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=4"}, {"page": 4121, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=5"}, {"page": 4118, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=2"}, {"page": 4118, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=2"}, {"page": 4122, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=6"}], "councilor_points": ["鍾佩玲議員指出臺北市營利電動車充換電站現行規範缺乏法律效力，詢問產發局是否主動訂定自治條例。鍾佩玲議員展示稽查照片，指出充換電站滅火器存在紀錄疑似造假、故障逾月未換、逾3年未做性能檢查及未設置滅火器等問題。鍾佩玲議員要求產發局負起主管機關責任，於7月提出是否制定自治條例的結論，且勿將檢查責任全推給消防局。"], "response": "產業發展局局長表示將於6月召開會議邀請專家學者與業界代表討論，並承諾於7月給予是否朝法制化推動的結論與進程。產業發展局副局長表示對紀錄疑慮會要求公司處理，產業發展局公用事業科科長則說明用電場所若不改善最重可廢止用電。", "response_removed": false, "topic": "電動車充換電站安全自治條例與滅火器管理"}, {"citations": [{"page": 1865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=2"}, {"page": 1865, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=2"}, {"page": 1868, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=5"}, {"page": 1866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=3"}, {"page": 1866, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=3"}, {"page": 1867, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=4"}, {"page": 1869, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=6"}], "councilor_points": ["鍾佩玲議員指出低碳永續家園計畫補助之雨撲滿造價出現容量小者反而較貴的異常價差，建議針對單一輔導項目訂定合理經費上限。鍾佩玲議員指出環保局過去僅以抽查驗收且112年現地勘查為零，並舉出27平方公尺種植870株變葉木遠超專業建議等情事。鍾佩玲議員要求環保局落實現地勘查，並研擬更周延的驗收方式與程序。"], "response": "環境保護局局長說明各里因加強基座或造型不同導致成本差異，同意回去後明列細項並針對輔導項目類別訂定金額上限。環境保護局局長承認驗收程序有檢討空間，承諾未來會先與里長現勘確認需求，並加強專家學者審核與驗收。", "response_removed": false, "topic": "低碳永續家園雨撲滿及植栽驗收管理"}, {"citations": [{"page": 2752, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=2"}, {"page": 2753, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=3"}, {"page": 2754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=4"}, {"page": 2756, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=6"}, {"page": 2757, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=7"}, {"page": 2754, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=4"}, {"page": 2753, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=3"}], "councilor_points": ["鍾佩玲議員指出目睹家暴兒少心靈易受創傷，詢問第一線人員評估目睹兒時是否直接詢問兒少本人。鍾佩玲議員表示臺北市兒少保護案件通報數與開案數落差極大，且社會局與家防中心缺額達33人，關切是否會造成漏接個案。鍾佩玲議員要求將學齡後兒少本人意見納入評估，並補足人力與加強未開案高風險個案之橫向聯繫追蹤。"], "response": "社會局局長說明實務上會針對成人訪視，學齡後孩子若有通報會直接接觸，承諾將學齡後兒少意見納入評估並強化社工教育訓練。社會局局長表示目前家防中心有兩成缺額，會透過彈性招募與大學實習爭取人力，並規劃轉介後的回報追蹤機制。", "response_removed": false, "topic": "目睹家暴兒少輔導與兒少保護開案追蹤"}, {"citations": [{"page": 830, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=9"}, {"page": 831, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=10"}, {"page": 834, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=13"}, {"page": 834, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=13"}, {"page": 831, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=10"}, {"page": 833, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=12"}], "councilor_points": ["鍾佩玲議員指出恢復YouBike前30分鐘免費後，非尖峰時段仁愛路仍有連續5個站點無車可借，質疑調度成效。鍾佩玲議員指出民眾向1999反映無車可借卻收到無位可還的回覆，且調度人力不足致備用車綁於一旁卻未能及時上架。鍾佩玲議員要求交通局儘速計算出臺北市車與車柱的最適比例，並將見車率加上周轉率作為評估指標。"], "response": "交通局局長說明問題僅局部解決，今年已增加3,200輛車，並就1999文不對題之回覆向議員致歉。交通局局長與交通局運輸管理科科長說明目前車柱與車之比例為1.75：1，承諾會持續觀察計算最適比例，並同意將見車率結合周轉率精進控管。", "response_removed": false, "topic": "YouBike車輛調度與車與車柱最適比例"}, {"citations": [{"page": 2286, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=8"}, {"page": 2287, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=9"}, {"page": 2288, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=10"}, {"page": 2288, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=10"}], "councilor_points": ["鍾佩玲議員關切大巨蛋舉辦演唱會是否符合建築技術規則第124條之1及第127條規定，並指出市府過去一年均未開會討論。鍾佩玲議員詢問使照註記規定之防火逃生避難安全性能審查執行方式。鍾佩玲議員提醒經內政部認可的消防安全中心基金會曾涉及爭議，要求都發局注意機構公信力並研擬備案。"], "response": "建築管理工程處處長說明內政部已函示臨時展演不適用第127條規定，因此沒有劃定排除的問題。建築管理工程處處長與都市發展局局長說明非體育活動之臨時使用仍須經台灣建築中心或消防安全中心基金會驗證防火逃生避難安全，驗證後再進行審查。", "response_removed": false, "topic": "大巨蛋舉辦演唱會之防火避難審查"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 11, "heading": "市政總質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162#page=13", "transcript_pages": [1289, 1290, 1291, 1292, 1293, 1294, 1295, 1296, 1297, 1298, 1299, 1300, 1301, 1302, 1303, 1304, 1305], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665494A148510BBF7806C7A9A58DD7ED629322573044525A7ABC7A852238F00A7C162", "videos": [{"date": "2024-05-30", "group": 11}]}, {"dates": ["2024-04-11"], "dept": "教育", "doc_type": "部門質詢", "group": 4, "heading": "教育部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162#page=13", "transcript_pages": [1388, 1389, 1390, 1391, 1392, 1393, 1394], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549A3827CF8F1C86230C2DF990CAEF06B98326E6CA081FAFD4BA852238F00A7C162", "videos": [{"date": "2024-04-11", "group": 4}]}, {"dates": ["2024-04-23"], "dept": "交通", "doc_type": "部門質詢", "group": 16, "heading": "交通部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162#page=7", "transcript_pages": [828, 829, 830, 831, 832, 833, 834, 835], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491C47100A3E758A96F1A5D0F2F262283CFB7EB916869003B4A852238F00A7C162", "videos": [{"date": "2024-04-23", "group": 16}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 5, "heading": "警政衛生部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162#page=1", "transcript_pages": [1864, 1865, 1866, 1867, 1868, 1869, 1870, 1871], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549C6761738DCA185901809E56BAB5CB248EEB9B7F5719F3325A852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 5}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 2, "heading": "工務部門質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162#page=6", "transcript_pages": [2284, 2285, 2286, 2287, 2288, 2289, 2290, 2291], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665496B3E18414E16BF6A7E1A2370D0CFDE7A7CD12238D78CB59BA852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 2}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 5, "heading": "民政部門質詢第5組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162#page=1", "transcript_pages": [2751, 2752, 2753, 2754, 2755, 2756, 2757], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549205C59FEA59521B9FCA9F4E224401525C8BFCDB7D68FBABBA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 5}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 4, "heading": "財政建設部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665499E9F57B042F9ED1948F75FC39F50B2AA08A24EAFB3CDC8BFA852238F00A7C162#page=1", "transcript_pages": [4117, 4118, 4119, 4120, 4121, 4122, 4123,