INSERT INTO "fact" VALUES('summary:14-03:pd697b2a2b5','pd697b2a2b5','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:16:30Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1665, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654965A0D91507BB5FEDE252419A917DA0C09FB6A7AF2252B979A852238F00A7C162#page=8"}, {"page": 2018, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=5"}, {"page": 4180, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=5"}, {"page": 4183, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=8"}, {"page": 2014, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=1"}, {"page": 2017, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=4"}, {"page": 2019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=6"}, {"page": 2020, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=7"}], "councilor_points": ["鍾小平議員詢問前市長時期簽署台灣智慧光網案的決策背景，指出警用監視器傳輸費率由每月1,761元調升至2,200元，預算由4.6億元增加至5.5億元再調整為5.1億元，關切市府承受的壓力與議價過程。鍾小平議員表示前市長時期採BOT模式由廠商投資鋪設光纖，相較於每年向中華電信支付4億元租金，期滿後網路可回歸市府。鍾小平議員關切市府解約後的備援系統處置，詢問若廠商不同意1,761元費率或中斷服務時市府的法令依據與因應措施。"], "response": "資訊局資通安全中心主任說明，前市長時期推動光纖到府計畫，由廠商負擔建設與營運費用且25年期滿後移轉回市府。警察局局長說明，廠商堅持專線網路費率為每月2,200元，經11次協商及議價後費率調降80元，預算增加係因頻寬由2Mbps升級至3Mbps及新增監視器，並依實際執行採取實支實付，並未承受特定指示壓力。資訊局局長說明，市府經7次議價降至2,100元，解約後回歸公版1,761元費率，現正提出有線電視Cable線、無線或其他光纖業者等備援方案供警察局研評。", "response_removed": false, "topic": "台灣智慧光網服務費與備援系統"}, {"citations": [{"page": 2021, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654915C391D2958C1EC2C7AB13A8A191A2B9477219FBF7434AF0A852238F00A7C162#page=8"}, {"page": 2370, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549C81D96CA9A35CDCF70EA93113E3F8E650DD2CBD40F1E4DD6A852238F00A7C162#page=2"}, {"page": 2373, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549C81D96CA9A35CDCF70EA93113E3F8E650DD2CBD40F1E4DD6A852238F00A7C162#page=5"}, {"page": 2375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549C81D96CA9A35CDCF70EA93113E3F8E650DD2CBD40F1E4DD6A852238F00A7C162#page=7"}, {"page": 1332, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=11"}, {"page": 1333, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=12"}, {"page": 1334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=13"}, {"page": 2375, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549C81D96CA9A35CDCF70EA93113E3F8E650DD2CBD40F1E4DD6A852238F00A7C162#page=7"}, {"page": 1334, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=13"}], "councilor_points": ["鍾小平議員詢問京華城案容積率由392%增加至560%、再提高至840%的決策過程，指出該案不適用都市更新條例，質疑給予20%容積獎勵與30%容積移轉的合法性。鍾小平議員指出開發案總銷售金額可達1,600億元至1,700億元、獲利逾1,000億元，要求市府依法行政、追回20%容積獎勵或研議凍結與廢止建照。鍾小平議員在市政總質詢中詢問市長對前市府給予容積獎勵的看法，要求市府嚴格把關。"], "response": "都市發展局局長說明，該案並非都市更新案故不適用都市更新條例，20%容積獎勵係參照都更獎勵且過去無前例，後續須先研議都市計畫變更或廢止等法令程序，若涉及不法將立即處理，未來不再受理自提細部計畫增加容積獎勵之申請。市長表示，該案非都更案故不會給予20%容積獎勵，監察院指出重大違失後市府已做修正，未來依都市計畫法第24條自提細部計畫增加容積獎勵者市府一律不受理，一切依法行政。副市長表示，公務人員必須依法行政，對於容積獎勵的適法性會精準把關。", "response_removed": false, "topic": "京華城容積獎勵案"}, {"citations": [{"page": 3047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665496F357645A651755ED5119AB32B931A172B0166497B0B6CA8A852238F00A7C162#page=1"}, {"page": 3047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665496F357645A651755ED5119AB32B931A172B0166497B0B6CA8A852238F00A7C162#page=1"}, {"page": 3048, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665496F357645A651755ED5119AB32B931A172B0166497B0B6CA8A852238F00A7C162#page=2"}, {"page": 4178, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=3"}, {"page": 4179, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=4"}, {"page": 3050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665496F357645A651755ED5119AB32B931A172B0166497B0B6CA8A852238F00A7C162#page=4"}, {"page": 4177, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=2"}, {"page": 4177, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665490319AF4D224E726E03F77AE291928974C1C5B737173B7D7AA852238F00A7C162#page=2"}], "councilor_points": ["鍾小平議員詢問北投士林科技園區T16、T17、T18基地拆分招標、取消30%醫療樓地板面積限制及免附投資計畫書之決策過程，指出此舉造成權利金與市庫損失。鍾小平議員指出政風處科長曾簽具反對放寬條件及維持原招標條件之意見，質疑該科長後續調職原因。鍾小平議員詢問市府訪談廠商紀錄中會議主持人未簽名之疑義，並關切地上權移轉之合約規定。"], "response": "政風處處長說明，科長調職係接近3年任期之正規職期輪調，當時處長亦認同科長之簽辦意見，目前相關案情正由政風處配合檢調調查中。產業發展局局長說明，招標模式變更係歷經多次流標後彙整潛在廠商意見，經促參委員會討論並陳報市長室會議拍板，地上權移轉合約規定須於7年內取得所有使用執照且須經市府同意。產業發展局工商服務科科長補充說明，廠商訪談會議紀錄均有送至副秘書長辦公室並蓋章核退。", "response_removed": false, "topic": "北投士林科技園區招商開發案"}, {"citations": [{"page": 1658, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654965A0D91507BB5FEDE252419A917DA0C09FB6A7AF2252B979A852238F00A7C162#page=1"}, {"page": 1326, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=5"}, {"page": 1661, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654965A0D91507BB5FEDE252419A917DA0C09FB6A7AF2252B979A852238F00A7C162#page=4"}], "councilor_points": ["鍾小平議員指出臺北市出生人口減少及少子化問題嚴峻，詢問幼兒園2歲專班與3至5歲班備取人數眾多、公托抽籤錄取率低的原因。鍾小平議員建議市府積極盤點國小閒置空間及1樓場域，擴大設立2歲專班，並提議放寬公宅容積以提供0至2歲托育空間與育兒津貼。"], "response": "教育局局長說明，2歲專班因師生比限制每班僅收16人，且設置需位於國小1樓場域而受限於空間，市府已逐校盤點備取需求，將招生不足之3至5歲班轉為2歲班或運用餘裕空間增班。市長表示，認同照顧年輕世代的理念，青年局成立後會通盤研究財務負擔與財務精算，並考量居住、低薪及就業等實質協助做法。", "response_removed": false, "topic": "幼兒園設置與少子化因應措施"}, {"citations": [{"page": 510, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=4"}, {"page": 511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=5"}, {"page": 511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=5"}, {"page": 513, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=7"}, {"page": 513, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=7"}], "councilor_points": ["鍾小平議員關切內湖交通塞車改善情形，詢問交通局與警察局採取的疏導措施與效果。鍾小平議員詢問捷運環狀線、萬大線工程因預算增加60%後的招標與通車時程，以及松山機場若遷建後規劃跨越基隆河聯外道路以紓解內湖交通的可行性。"], "response": "交通局局長與警察局交通警察大隊大隊長說明，市府規劃19處崗哨派員疏導，並實施市民高架道路銜接環河北路下坡段下午尖峰時段禁右轉等工程改善措施，已使下班車潮提早疏散。捷運工程局局長說明，萬大線以116年通車為目標，環狀線南北環段預計年中完成發包，若發包順利約9至10年可全線完工，預計可轉移三成交通量。交通局局長補充表示，松山機場遷建後之聯外道路目前尚未進入研究階段，將研讀既有報告評估可行性。", "response_removed": false, "topic": "內湖交通改善與捷運路網建設"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-30"], "dept": null, "doc_type": "市政總質詢", "group": 12, "heading": "市政總質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162#page=1", "transcript_pages": [1322, 1323, 1324, 1325, 1326, 1327, 1328, 1329, 1330, 1331, 1332, 1333, 1334, 1335], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549295F234B448ADCCDBB5094290136F86047E34BA6428EACF8A852238F00A7C162", "videos": [{"date": "2024-05-30", "group": 12}]}, {"dates": ["2024-04-18"], "dept": "交通", "doc_type": "部門質詢", "group": 1, "heading": "交通部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549F5D33D54C36605ACEA776F894E5A6FC34B7748FBC20B2F93A852238F00A7C162#page=1", "transcript_pages": [507, 508, 509, 510, 511, 512, 513, 514], "transcript_url": "https://g