cript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB9637356654937807018F3EF7FA7EB175D5E3609B43427F4291CBD64B7EBA852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 16}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 9, "heading": "財政建設部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162#page=17", "transcript_pages": [4211, 4212, 4213, 4214, 4215, 4216, 4217, 4218], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB963735665491FEE10A52DB1A010F9F4B4FC4E5B15A4379E06E52652F0F0A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 9}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162','2026-10-06T03:24:58Z');
INSERT INTO "fact" VALUES('summary:14-03:pc164e1064f','pc164e1064f','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:26:48Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2721, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=1"}, {"page": 2723, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=3"}, {"page": 2723, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=3"}, {"page": 2723, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=3"}, {"page": 2725, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=5"}, {"page": 2722, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=2"}], "councilor_points": ["陳怡君議員指出第二殯儀館館內6部電梯之顯示板位置過低且未張貼許可證，停車場格位指示燈與實際狀況不符，無障礙車位門開會撞牆且缺少滅火器，親子廁所門縫過大影響隱私，且部分逃生緩降機安全帶缺失、檢驗貼紙過期。陳怡君議員指出館內緊急疏散平面圖標示之滅火器數量與現場不符，4個禮廳僅配置1支中國製造之滅火器，且地下汽車停放區於雨天發生積水現象。陳怡君議員要求市府於1週內針對消防安全、廁所門縫及地下停車場淹水等問題進行改善。"], "response": "殯葬管理處處長表示，針對指教項目會儘快改善並加強督導，與新大樓有關之缺失會要求承包廠商負起保固責任，淹水問題已改善完畢並會再測試，無障礙廁所門縫與消防滅火器也會即刻改善。新建工程處科長說明，去年11月取得使用執照時已同步取得電梯使用許可，會再檢視是否疏漏未張貼於電梯內，電梯均按照電梯協會安檢標準通過，無障礙廁所門縫與停車場淹水問題會立刻處理。", "response_removed": false, "topic": "第二殯儀館設施與公共安全改善"}, {"citations": [{"page": 997, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=13"}, {"page": 1000, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=16"}, {"page": 1001, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=17"}, {"page": 1002, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=18"}, {"page": 997, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=13"}, {"page": 999, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=15"}], "councilor_points": ["陳怡君議員指出基泰臺大建案屋頂平台屋突層涉違規使用與擅自加裝，且地下停車場隔間、高級交誼廳、健身房及R樓逾200坪之違建未個別登載於違建查報網。陳怡君議員指出該建案屋頂額外載重達160噸，住戶擔憂結構安全，且依規定土木技師僅能對36公尺以下建物做簽證，該建物早就超過36公尺。陳怡君議員指出基泰大直災害原因調查報告顯示施工期間水泥使用量偏少、未提送施工計畫書與品質檢驗紀錄，連續壁厚度私自改成50公分甚至40公分，且20點開挖支撐沉陷點中有15點超過警戒值，要求市府嚴加查核基泰於臺北市之建案。"], "response": "建築管理工程處處長說明，屋突涉及擅自裝修已要求限期補辦手續並裁罰，框架部分已查報並拆除部分樓板，違建若無法合法化或無法結案必會拆到不堪使用，地下停車場擅自隔間於去年已複查改善完成，並會至現場確認違建狀況。臺北市市長表示，市府對違建嚴加查核，會全面了解與調查相關照片與結案狀況，若依法必須拆除會要求符合拆除至不堪使用之規定。", "response_removed": false, "topic": "基泰臺大建案違建查報與施工檢測缺失"}, {"citations": [{"page": 1547, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=1"}, {"page": 1549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=3"}, {"page": 1549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=3"}, {"page": 1549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=3"}, {"page": 1549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=3"}, {"page": 1551, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=5"}, {"page": 1549, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=3"}], "councilor_points": ["陳怡君議員指出觀傳局委外舉辦之2024臺北燈節點燈記者會，表演出現不當歌詞內容，建議公共場合之活動應檢討並避免不良示範。陳怡君議員指出文化小旅行景點存在標示不清與指引缺乏問題，如甜水鴛鴦湖無交通說明、新福本坑告示牌遭樹葉遮擋且木棧道損壞、和興炭坑指示牌傾斜，小坑溪文學步道詩詞牌面腐朽且有廢水，北投兒童樂園溜滑梯水泥破裂，且官方YouTube與外文網站點閱數偏低。陳怡君議員要求文化小旅行路線應加強標示指引與設施維護、納入臺北通宣傳、設置網紅拍照打卡點並推出集點送禮物活動，以及整合文化局網頁。"], "response": "觀光傳播局局長表示，未來辦理活動會注意相關細節。文化局局長表示，接受議員批評與見地，優化方案刻正辦理中且將推出新網站，並會參考議員所提各項建議。", "response_removed": false, "topic": "文化小旅行景點設施維護與宣傳改善"}, {"citations": [{"page": 991, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=7"}, {"page": 992, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=8"}, {"page": 993, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=9"}], "councilor_points": ["陳怡君議員指出市府提供之性騷擾申訴統計資料未列入市場處案件，並轉述同仁陳情表示市場處副處長對多名女同事進行不當肢體接觸與性騷擾，關切該員停職期間之給薪與後續懲處調職情形。陳怡君議員指出市場處存在管理問題，包括要求承辦人員以個人薪水代墊費用、工作分配不均、主管語言霸凌，以及同仁陳情由被投訴之長官親自回覆之狀況。陳怡君議員指出市場處111年至113年4月30日離職與調職人員過多、人力長期不足，要求市府正視職場管理與性騷擾問題，並建議衛生局提供相關心理與生理輔導資源。"], "response": "人事處處長說明，調查統計係針對申訴案件，市場處該案並非申訴案件，市府係以最高規格標準處理。產業發展局局長說明，事發後已於3月26日將該名副處長停職且停職期間無給薪，考績會決議建議記1大過並啟動調職作業，目前正在辦理新任職務安排。臺北市市長表示，市府絕不容許性騷擾，已成立委員會調查並經考績會開會確定記1大過懲處。衛生局局長說明，若同仁有心理輔導需求，衛生局心理衛生科及社區心理衛生中心均可提供協助。", "response_removed": false, "topic": "市場處職場性騷擾申訴與人事管理"}, {"citations": [{"page": 2274, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=8"}, {"page": 2275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=9"}, {"page": 2275, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=9"}], "councilor_points": ["陳怡君議員指出市府於113年1月10日修正發布管理要點，規定承造人於申報放樣勘驗及竣工勘驗前須進行基地四周20公尺範圍內透地雷達檢測，但市府未訂定測線間距與密度規範，導致檢測方式無所適從。陳怡君議員指出檢測報告缺乏孔洞分級及責任歸屬標準，若未明確規範間距與處理程序，恐產生安全漏洞。陳怡君議員要求新工處立即訂定查核規範，載明檢測結論、明確範圍、孔洞分級、處置標準作業程序及責任歸屬。"], "response": "新建工程處處長說明，目前現場查核係比較地面高程有無明顯變形，檢測範圍須涵蓋20公尺，若放樣勘驗發現道路有孔洞跡象會移交新工處處理，並承諾將訂定相關查核規範。工務局局長說明，修正管理要點時係訂定較廣義條件，若需規範更實際探測方式，會再向建管處了解並做調整。", "response_removed": false, "topic": "建築工程透地雷達檢測規範與權責劃分"}, {"citations": [{"page": 780, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=1"}, {"page": 780, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=1"}, {"page": 781, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=2"}, {"page": 782, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=3"}], "councilor_points": ["陳怡君議員指出即時交通資訊網之傳輸畫面品質不佳，部分監視器出現無法點閱、顯示Page not found、拍攝角度偏斜或遭樹枝與號誌遮擋之情形。陳怡君議員指出交通局於111年及112年各編列955萬元、113年編列近千萬元通訊費，要求資訊局與交通局提出檢視與解約備案對策。陳怡君議員要求交通局善盡監督職責，優化車流即時影像與拍攝角度，並做確實維護與調整。"], "response": "資訊局資通安全中心主任說明，傳輸品質涉及法律與技術層面，會再了解相關契約並協助與廠商反映及溝通。交通局局長說明，感謝議員提醒，針對沒有畫面或角度不對之監視器會立即進行修正與調整。", "response_removed": false, "topic": "即時交通資訊網傳輸品質與監視器維護"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-24"], "dept": null, "doc_type": "市政總質詢", "group": 6, "heading": "市政總質詢第6組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162#page=6", "transcript_pages": [990, 991, 992, 993, 994, 995, 996, 997, 998, 999, 1000, 1001, 1002], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162", "videos": [{"date": "2024-05-24", "group": 6}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 12, "heading": "教育部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162#page=1", "transcript_pages": [1547, 1548, 1549, 1551], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549BE9AB25169C1BFCC88470B698B02C4C6FFF8A208F39036E6A852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 12}]}, {"dates": ["2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 14, "heading": "交通部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162#page=1", "transcript_pages": [780, 781, 782, 783, 784, 785], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549AB5811C237955242E7E20318967E66E35D22B8A50B7E5915A852238F00A7C162", "videos": [{"date": "2024-04-22", "group": 14}]}, {"dates": ["2024-04-25"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 4, "heading": "警政衛生部門質詢第4組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162#page=5", "transcript_pages": [1856, 1857, 1858, 1860, 1861, 1862], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB9637356654958C9391230B84C508C518C2522EF3C242608B52BF1EC5B5AA852238F00A7C162", "videos": [{"date": "2024-04-25", "group": 4}]}, {"dates": ["2024-05-02"], "dept": "工務", "doc_type": "部門質詢", "group": 1, "heading": "工務部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162#page=7", "transcript_pages": [2273, 2274, 2275, 2276, 2277, 2278], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665494E96AB9747AA17AB4C0941704114BAAA23659A72166BC30EA852238F00A7C162", "videos": [{"date": "2024-05-02", "group": 1}]}, {"dates": ["2024-05-09"], "dept": "民政", "doc_type": "部門質詢", "group": 3, "heading": "民政部門質詢第3組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162#page=1", "transcript_pages": [2721, 2722, 2723, 2725, 2726, 2727], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549769A93BB2FF625795CDC24BD4B026A7C7B10E97F2B4B326DA852238F00A7C162", "videos": [{"date": "2024-05-09", "group": 3}]}, {"dates": ["2024-05-17"], "dept": "財政建設", "doc_type": "部門質詢", "group": 8, "heading": "財政建設部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162#page=5", "transcript_pages": [4189, 4190, 4191, 4192, 4193, 4194], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549FAD70F09AD89A80135FF2C21CF48A4923E2509C0EA5F0D97A852238F00A7C162", "videos": [{"date": "2024-05-17", "group": 8}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549591FECD1548E1A23E0BBB312F69B13A1AE2771050A28847FA852238F00A7C162','2026-10-06T03:26:48Z');
INSERT INTO "fact" VALUES('summary:14-03:padc186f41c','padc186f41c','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:29:59Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1404, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=10"}, {"page": 1406, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=12"}, {"page": 1406, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=12"}, {"page": 1408, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=14"}, {"page": 1409, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=15"}, {"page": 1405, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=11"}, {"page": 1409, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=15"}], "councilor_points": ["陳慈慧議員詢問社子島建物查估進度，建議市府公告查估結果、拆遷補償費用與安置住宅預估房價房型，並請市府明確告知里長有關學童因就學遷戶籍的安置資格規定。陳慈慧議員表示安置資格不應硬性以單一拆遷公告日為限，建議對拆遷公告期間家中有人往生者改以時間區間從優認定。陳慈慧議員亦反映5,200戶安置住宅集中於13公頃土地恐引發交通與消防安全問題，要求市府與中央積極溝通並儘速提供計算結果初稿。"], "response": "地政局局長說明有編釘門牌建物查估比率約77%，會同步進行查估補償與安置房型計算，最慢於區段徵收計畫完成時提供計算初稿。土地開發總隊總隊長與市長表示，學童因就學遷出戶籍者，於拆遷公告前2個月或完成註冊後2個月內遷回仍具配售資格，訊息將透過區里管道公告。地政局局長與市長說明新生兒或結婚設籍可納入配售資格計算，往生者影響資格部分會做加強說明與個案檢討，且都市計畫及環評已考量社子大橋與捷運輕軌等聯外交通。", "response_removed": false, "topic": "社子島開發與拆遷安置補償機制"}, {"citations": [{"page": 2585, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665498FE713C9C3CC787DAAE9C642C80FF41DA34ABE679DCF3887A852238F00A7C162#page=14"}, {"page": 2878, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665491F296C40579C7E2382B8E59054FAC75F5C4E8D2DDD9A5759A852238F00A7C162#page=3"}, {"page": 2879, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665491F296C40579C7E2382B8E59054FAC75F5C4E8D2DDD9A5759A852238F00A7C162#page=4"}, {"page": 2880, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665491F296C40579C7E2382B8E59054FAC75F5C4E8D2DDD9A5759A852238F00A7C162#page=5"}, {"page": 2880, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665491F296C40579C7E2382B8E59054FAC75F5C4E8D2DDD9A5759A852238F00A7C162#page=5"}], "councilor_points": ["陳慈慧議員指出敬老卡每月點數用畢比例偏低，建議市府擴大北北基桃宜大眾運輸補助，並檢討臺鐵起迄站僅限臺北市4個車站之不便限制。陳慈慧議員反映53個可扣點場館中有38個是游泳池，資源分布不均，建議爭取更多文化場館折抵並研議納入診所部分負擔醫療費與庇護工場商品。陳慈慧議員提出盤點適合場館、檢討行政區資源分配、評估弱勢醫療社福機構使用及擴大大眾運輸適用範圍等四點精進建議。"], "response": "社會局局長說明目前規劃與57條北北基桃宜國道客運路線合作，預計10月開辦，且7月起試辦臺鐵北北基桃宜5縣市任一站點起訖扣點補助。社會局局長表示敬老卡主要目的為鼓勵長者外出走動，醫療部分負擔方案仍在研議中，場館部分已爭取臺北流行音樂中心常設展及動物園遊客列車納入扣點。社會局局長表示會研議將庇護工場商品納入評估，並將檢討各行政區敬老卡使用範圍與資源分配。", "response_removed": false, "topic": "敬老卡使用範圍擴大與場館資源分配"}, {"citations": [{"page": 1574, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162#page=15"}, {"page": 1574, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162#page=15"}, {"page": 1575, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162#page=16"}, {"page": 1575, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162#page=16"}], "councilor_points": ["陳慈慧議員詢問每年維護營運經費四百多萬元的臺北旅遊網運作情形，指出穆斯林友善店家頁面竟出現宜蘭、屏東等非臺北市場所。陳慈慧議員反映西班牙文、泰文、越南文與印尼文等4種語系頁面過於簡略且無連結，日文版連結YouBike和大臺北公車網站僅提供中英文，印尼文頁面更顯示錯誤時差。陳慈慧議員要求觀傳局檢討網站內容，跨局處協調並完整改善多語系服務，避免誤導外國遊客。"], "response": "觀光傳播局局長與視聽資訊室主任說明穆斯林頁面係因系統改版導致參數失效，會立即處理修正。觀光傳播局視聽資訊室主任與局長說明4個語系係因改版簡化為迎賓頁面以降低維護翻譯成本，會再檢討如何調整。觀光傳播局局長表示若無法請交通局提供完整翻譯將考慮不予連結，並承諾立即檢視並改進網站各項細節與時差問題。", "response_removed": false, "topic": "臺北旅遊網網站功能與多語系內容優化"}, {"citations": [{"page": 2883, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665491F296C40579C7E2382B8E59054FAC75F5C4E8D2DDD9A5759A852238F00A7C162#page=8"}, {"page": 4360, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B18BF614451764F69BF22F618F3A9C632F0EAFEE63C0393FA852238F00A7C162#page=2"}, {"page": 4361, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B18BF614451764F69BF22F618F3A9C632F0EAFEE63C0393FA852238F00A7C162#page=3"}, {"page": 4361, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B18BF614451764F69BF22F618F3A9C632F0EAFEE63C0393FA852238F00A7C162#page=3"}, {"page": 4362, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B18BF614451764F69BF22F618F3A9C632F0EAFEE63C0393FA852238F00A7C162#page=4"}], "councilor_points": ["陳慈慧議員指出市府推動公有零售市場電子支付建置率雖高，但48處市場中僅16處有交易申請，且平均單一市場每月僅四十多件，使用率顯著偏低。陳慈慧議員反映大龍夜市與西昌街夜市電子支付使用率低或未建置，要求產發局針對中高齡族群加強宣導教育與促銷活動。陳慈慧議員建議產發局順應無紙化趨勢，持續貼近使用者習慣精進獎勵計畫與系統服務。"], "response": "產業發展局局長與市場處處長說明公有市場7,182攤中有7,152攤已設置電子支付，夜市設置率為72.9%，但傳統市場中高齡消費族群仍習慣使用現金。市場處處長說明西昌街夜市因商品特殊且飲食攤少未設置，大龍夜市飲食攤較零散導致使用率偏低，而寧夏夜市每月則有上千筆交易。產業發展局局長表示將請市場處加強宣導、舉辦促銷活動及輔導攤商，並持續觀察攤商需求以精進電子支付措施。", "response_removed": false, "topic": "公有市場與夜市無現金電子支付推廣"}, {"citations": [{"page": 1422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=28"}, {"page": 1422, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=28"}, {"page": 1423, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=29"}, {"page": 1421, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=27"}], "councilor_points": ["陳慈慧議員反映臺北市橋梁機車道常因車禍、號誌異常或汽車誤闖發生大塞車，且三輪式物流機車因車身較寬易受狹窄機車道限制。陳慈慧議員指出水泥分隔島上的鐵條、凸起物等異物如「路上血滴子」，若騎士摔倒易造成嚴重傷害，要求市府進行全面體檢與重整剔除。陳慈慧議員建議市府參考新北市於中興橋、重新橋等設置活動式閘門以疏導車流，並檢討水泥分隔島之存廢與替代標線方案。"], "response": "交通管制工程處處長說明機車專用道因汽機車速差仍有存在必要，目前已於福和橋試辦槽劃線標線分隔，並檢討轄內橋梁空間。新建工程處處長表示分隔島凸起物為早期施工吊鉤，承諾會進行檢視與總體檢。市長與交通管制工程處處長表示，將檢討避免凸出物露出，並同意研議參考新北市活動式閘門作法及檢討水泥分隔島存廢。", "response_removed": false, "topic": "臺北市橋梁機車道水泥分隔島安全體檢與改善"}, {"citations": [{"page": 2579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665498FE713C9C3CC787DAAE9C642C80FF41DA34ABE679DCF3887A852238F00A7C162#page=8"}, {"page": 2579, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665498FE713C9C3CC787DAAE9C642C80FF41DA34ABE679DCF3887A852238F00A7C162#page=8"}, {"page": 2581, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665498FE713C9C3CC787DAAE9C642C80FF41DA34ABE679DCF3887A852238F00A7C162#page=10"}, {"page": 2581, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665498FE713C9C3CC787DAAE9C642C80FF41DA34ABE679DCF3887A852238F00A7C162#page=10"}], "councilor_points": ["陳慈慧議員指出臺北市人口老化嚴重，但青銀換居計畫試辦至2024年2月底僅媒合9戶，成績有很大改善空間。陳慈慧議員表示長輩習慣原社區生活圈而不願搬遷，詢問市府如何克服搬遷困難及處理記點制度之疑慮。陳慈慧議員建議都發局推動滾動式檢討布點時，應考量長者的交通便利性、生活機能及與現居地遠近。"], "response": "都市發展局局長說明計畫推動困難在於長者不願離開熟悉環境，市府已將房型擴增至二房型及三房型，並將租期由6年延長至12年。都市發展局局長說明目前6,363戶出租社宅中保留21戶供青銀換居，未來隨新社宅完工將於各行政區保留布點，讓長者不必離家太遠。都市發展局局長說明記點制度係基本居住要求，入住前會先告知溝通，並承諾將交通便利性納入滾動式檢討考量。", "response_removed": false, "topic": "青銀換居計畫執行進度與政策檢討"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-31"], "dept": null, "doc_type": "市政總質詢", "group": 14, "heading": "市政總質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162#page=10", "transcript_pages": [1404, 1405, 1406, 1407, 1408, 1409, 1410, 1417, 1418, 1419, 1420, 1421, 1422, 1423, 1424, 1428, 1429], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB96373566549C84D7A33DC66A831D9C6CEAEE7044DFA78C900B2C3D0DEAAA852238F00A7C162", "videos": [{"date": "2024-05-31", "group": 14}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 13, "heading": "教育部門質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162#page=9", "transcript_pages": [1568, 1569, 1570, 1571, 1572, 1573, 1574, 1575, 1576], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654994A46BD8F6EB2058BADA431966188C1DF4BCF0FC51E34625A852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 13}]}, {"dates": ["2024-04-23"], "dept": "交通", "doc_type": "部門質詢", "group": 17, "heading": "交通部門質詢第17組", "tra