INSERT INTO "fact" VALUES('summary:14-03:pfd93c2126e','pfd93c2126e','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:32:21Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1051, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=10"}, {"page": 1052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=11"}, {"page": 1450, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=7"}, {"page": 1451, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=8"}, {"page": 1053, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=12"}, {"page": 1053, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=12"}, {"page": 1054, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=13"}, {"page": 1052, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=11"}, {"page": 1055, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=14"}, {"page": 1448, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=5"}], "councilor_points": ["陳炳甫議員指出臺北市236所學校中有170間出現災損，且有112所屬急迫性危險校舍，按現有每年40億元預算推估竟需30年才能完成改建，建議市府借用其他基金擴大校舍改建經費「請考慮從這些暫時用不到的基金先借用一點支持學校的改建」。此外，陳炳甫議員表示雙蓮國小EOD改建案土地未充分利用且大幅減班33%，要求市府於2個月內重劃設計圖，將基地蓋滿並納入公托與日照「把可以放進去的都要放進去，包括公托、公幼及日照等」。"], "response": "市長說明校舍改建固定每年編列40億元經費，並答覆將請教育局重新評估減班數、於2個月內修改雙蓮國小設計圖以納入公托「請教育局修改設計圖，最重要的是這裡未來是EOD示範點……確實可以納進公托」；教育局局長說明過往校舍改建流程約需10年，112所急迫性改建校舍以每年40億元預算推估約需30年，並表示會持續向中央爭取補助及搭配平均地權基金增加經費「我們會再向中央爭取補助，包括教育部……平均地權基金……搭配增加ㄧ些預算」。", "response_removed": false, "topic": "老舊校舍改建預算與雙蓮國小規劃"}, {"citations": [{"page": 1049, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=8"}, {"page": 1930, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=9"}, {"page": 1930, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=9"}, {"page": 1926, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=5"}, {"page": 1932, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=11"}, {"page": 1050, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=9"}, {"page": 1929, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=8"}], "councilor_points": ["陳炳甫議員指出聯合醫院小兒科主治醫師僅41位、住院醫師僅4位，且公職醫護人員比例僅16.53%，質疑市府定於115年成立獨立婦幼專責醫院的可行性「在聯合醫院只有這樣的人力的情況下，到底能做哪些事情」。此外，陳炳甫議員表示幼兒專責醫師制度在臺北市覆蓋率僅12.7%，要求市府盤點法規並檢討婦幼醫療資源整合「如何讓專責制度能夠更積極地照顧到臺北市市民……希望衛生局要積極地面對這問題」。"], "response": "市長說明成立婦幼專責醫院係對市民的承諾，會努力達成中央規定的19科並全面檢視具體計畫「我們會再全面檢視相關具體的計畫，盤點相關的法規，確定 115 年是不是可以達成」；衛生局局長說明預計於115年年中前成立獨立院區「衛生局預計在 115 年年中之前，集合各界的努力成立獨立院區」；聯合醫院院長說明將朝向社區型婦幼專責醫院發展，規劃約10個次專科，並說明公職醫護比例僅16.53%係因歷史「公職遇缺不補」規則，目前正在研議組織再造「目前我們在研議組織再造，一定要開放公職，或是就現有的編制做再造」。", "response_removed": false, "topic": "婦幼專責醫院籌設與醫療人力整合"}, {"citations": [{"page": 3019, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162#page=21"}, {"page": 3021, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162#page=23"}, {"page": 3022, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162#page=24"}, {"page": 3020, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB963735665497172C592314DB52CA08322FA15710AB0D8A20B56818ED1CCA852238F00A7C162#page=22"}], "councilor_points": ["陳炳甫議員以剴剴案為例，指出僅提高訪視頻率或發放自我篩檢工具包未必能發現問題，主張中央與地方權責應適度重疊合作以補足社會安全網漏洞「藉由互補來共同合作，把每一個漏洞都儘量避免掉」。此外，陳炳甫議員表示訪視次數增加將加大第一線負擔，要求市府為訪視員調薪並積極督導委外受託單位對保母等服務提供者的監督責任「臺北市政府就應該更積極地督導該單位，看能不能夠找出提供服務者的缺失」。"], "response": "社會局局長說明已與中央召開會議檢討收出養制度，並表示人民在中央與地方合作照顧下才會幸福「一定是要合作，人民在中央與地方合作的照顧之下才會是幸福」；針對人力負擔與監督機制，社會局局長說明正研議調整訪視員薪資比照社工員起薪，並承諾回去研議強化對受委託單位的監督措施。", "response_removed": false, "topic": "居家托育訪視與社會安全網機制"}, {"citations": [{"page": 1046, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=5"}, {"page": 1047, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=6"}, {"page": 1048, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=7"}, {"page": 2477, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=8"}, {"page": 2476, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=7"}, {"page": 2478, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F59FFC57F2E838A852238F00A7C162#page=9"}], "councilor_points": ["陳炳甫議員指出市府於113年3月26日修正申報辦法，將原定滿15年申報放寬至滿30年才首次申報，但該統計未納入4月3日大地震後的受損數據，要求市府面對新事實進行滾動式檢討「地震發生後才是問題發生的開始……請市府做滾動式管理重新檢討和研議到底適不適合」。此外，陳炳甫議員建議市府參考日本國土交通省指南，鼓勵或研議規定新大樓管委會按月提撥修繕預備金「學習日本要求區分所有權人提撥一定比例的金額作為修繕預備金」。"], "response": "市長說明3月底發布後發生大地震，會針對相關規定進行整體檢視與調整，並參考日本做法及向中央反映修法「因應這樣的狀況，我們可以來檢視相關的規定，再細緻地看怎麼做一個調整」；建築管理工程處處長說明先前統計剝落案件多為30年以上建築，若有新數據會在適當時間調整，並表示可將修繕準備金製作成臺北市版的指引供社區參考「我們可以把它變成是臺北市版的指南或是 1 個指引，提供公寓大廈收取公寓大廈基金的參考」。", "response_removed": false, "topic": "建築物外牆安全診斷申報與修繕預備金"}, {"citations": [{"page": 1044, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=3"}, {"page": 1046, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=5"}, {"page": 738, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=23"}, {"page": 1045, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=4"}], "councilor_points": ["陳炳甫議員指出電動YouBike最高時速達25公里，若允許在人行道騎乘將對行人造成危險，建議將人行道騎乘時速調降至15公里以下「如果可以騎上人行道建議時速在 15 公里以下」。此外，陳炳甫議員要求市府於2週內儘速與新北市及桃園市協調，確定雙北人行道是否開放人車共道及統一騎乘規範「要跟新北市討論雙北要不要開放人行道『人車共道』部分」。"], "response": null, "response_removed": true, "topic": "電動自行車騎乘規範與限速調整"}, {"citations": [{"page": 4289, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B4FBD88C72B8BE4C6F779CF2C4016EE4BBB97C0BA4BEE7E7A852238F00A7C162#page=1"}, {"page": 4291, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB96373566549B4FBD88C72B8BE4C6F779CF2C4016EE4BBB97C0BA4BEE7E7A852238F00A7C162#page=3"}], "councilor_points": ["陳炳甫議員指出臺灣65歲以上勞動參與率僅9.6%，遠低於南韓的37.3%，建議市府改變傳統觀念並善用長者經驗「臺灣中高齡或高齡勞動力的參與率是非常的低……可以好好的運用長者的活力與經驗」。此外，陳炳甫議員建議市府盤點各局處約聘僱職缺，評估調整為適合長者或二度就業者的兼職或半天職缺，以緩解缺工問題「先盤點臺北市政府有多少的職缺，是可以適合長者或二度就業的人來做」。"], "response": "產業發展局局長說明會向府級長官及相關局處報告討論，儘可能推動讓有經驗的退休人員再次貢獻所長「我會向府級長官及相關局處報告討論之後，看怎麼樣儘可能去推動，讓這些有經驗的前輩能夠再次貢獻所長」。", "response_removed": false, "topic": "中高齡者就業促進與市府職缺盤點"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-27"], "dept": null, "doc_type": "市政總質詢", "group": 8, "heading": "市政總質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162#page=1", "transcript_pages": [1042, 1043, 1044, 1045, 1046, 1047, 1048, 1049, 1050, 1051, 1052, 1053, 1054, 1055], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB96373566549217D35A413282A3C84238DA7F47DCACFA2B785D24EE91E52A852238F00A7C162", "videos": [{"date": "2024-05-27", "group": 8}]}, {"dates": ["2024-04-12"], "dept": "教育", "doc_type": "部門質詢", "group": 7, "heading": "教育部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162#page=5", "transcript_pages": [1448, 1449, 1450, 1451, 1452, 1453, 1454, 1455, 1456], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549DB7B8F20B6FD06ACB5F0F8D2154AD6A73E25F46D62585D9AA852238F00A7C162", "videos": [{"date": "2024-04-12", "group": 7}]}, {"dates": ["2024-04-22"], "dept": "交通", "doc_type": "部門質詢", "group": 11, "heading": "交通部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162#page=19", "transcript_pages": [734, 735, 736, 737, 738, 739, 740], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB96373566549BBA998BA5D76AF24BB44B76775930B5528F57DBA4C91CE0FA852238F00A7C162", "videos": [{"date": "2024-04-22", "group": 11}]}, {"dates": ["2024-04-26"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 8, "heading": "警政衛生部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162#page=5", "transcript_pages": [1926, 1927, 1929, 1930, 1931, 1932, 1933], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DE9E7FD99CCE24A8F9957C254D2A087CE0C1338FA5BBF8EEA852238F00A7C162", "videos": [{"date": "2024-04-26", "group": 8}]}, {"dates": ["2024-05-06"], "dept": "工務", "doc_type": "部門質詢", "group": 12, "heading": "工務部門質詢第12組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB963735665490D264C46AAAD4B1A032D9523FAADD9F342F