INSERT INTO "fact" VALUES('summary:14-03:p3371a36c1c','p3371a36c1c','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:38:09Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 1337, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=2"}, {"page": 1338, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=3"}, {"page": 1340, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=5"}, {"page": 1339, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=4"}, {"page": 1341, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=6"}], "councilor_points": ["陳賢蔚議員引用「願榮光歸香港」被香港法院禁止播放的時事指出自由逐漸消失，詢問市長對民主自由憲政體制、國家與政黨的排序與立場。陳賢蔚議員關心國會擴權法案若宣告違憲的態度，並要求市長在任內遇民眾陳情抗爭時捍衛集會遊行自由與民主自由憲政體制。"], "response": "市長說明憲法保障言論自由且禁歌不會在臺灣發生，表示個人力挺反送中運動的態度一致，並強調民主自由憲政體制與國家同等重要。市長表示法案是否違憲尊重大法官憲法法庭決議，並承諾會依法捍衛人民集會遊行權利。", "response_removed": false, "topic": "香港反送中與臺灣民主自由憲政體制捍衛"}, {"citations": [{"page": 2936, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=1"}, {"page": 2937, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=2"}, {"page": 2938, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=3"}, {"page": 2937, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=2"}, {"page": 2939, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=4"}, {"page": 2940, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=5"}, {"page": 2938, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=3"}, {"page": 2939, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654904E4DE5956DA9A45EB175D5E3609B434000ADEB206224DB0A852238F00A7C162#page=4"}], "councilor_points": ["陳賢蔚議員檢視「兒童保護7+1」政策辦理情形，指出若無法在訓練及實務操作中將高風險或心態異常者篩檢出來，政策將流於形式。陳賢蔚議員指出不適任保母退場機制的重要性，建議市府研擬實務操作觀察機制並連結專業醫學團體看法，將不適任者篩選汰換。"], "response": "社會局局長說明預計於7月開辦回流訓練並增加案例教育與法治教育，但表示單純懷疑他人格有問題在無犯錯下無法剝奪其工作權，法規上確有困難。社會局局長表示會繼續尋求專業解套機制並加強訪視與督導。", "response_removed": false, "topic": "兒童保護7+1政策執行與不適任保母退場機制"}, {"citations": [{"page": 2030, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=9"}, {"page": 2034, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=13"}, {"page": 2031, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=10"}, {"page": 2033, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=12"}, {"page": 2031, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=10"}, {"page": 2032, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549DFC3CE360D76A64704B9C9A4D4C2BBDE94F79E94F15FB04CA852238F00A7C162#page=11"}], "councilor_points": ["陳賢蔚議員關注北投溫泉偷拍案與「創意私房」案，指出性影像外流被害人報警率僅57%偏低，反映民眾對警方信賴感有待提升。陳賢蔚議員要求警察局與社會局確保承辦人員受過完整性平與隱私保護教育訓練，並指出家防中心網站專區位置不明顯及婦幼隊教學影片不夠淺顯易懂，要求優化宣導與處理流程。"], "response": "警察局局長說明警方有家防官及婦幼隊專責處理SOP以避免二次傷害，並表示會加強同仁教育訓練，承諾優化蒐證流程影片。家庭暴力及性侵害防治中心主任表示會立即修正網站頁面，將專區標示於明顯位置。", "response_removed": false, "topic": "數位性別暴力性影像處理機制與宣導流程優化"}, {"citations": [{"page": 2361, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=14"}, {"page": 2361, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=14"}, {"page": 2364, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=17"}, {"page": 2365, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=18"}, {"page": 2363, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=16"}, {"page": 2363, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CCEDDE0DFA230AE681A302E180D27F4B5A358B5FBFD2D56AA852238F00A7C162#page=16"}], "councilor_points": ["陳賢蔚議員指出都市更新處近5年離職人數過高，且建管處資深人力不足，導致公辦與民辦都更及危老重建建照審核期程延宕。陳賢蔚議員要求都發局、都更處及建管處於1個月內提出補齊人力缺額與加速審核進度的具體改善方案。"], "response": "都市更新處處長說明離職後業務均會交接給熟悉人員，並透過外補、報考及增加約聘僱人員補強人力，會後承諾於1個月內提出改善方案。建築管理工程處處長說明建照科目前缺額4名，且承辦人年資2年以上者為個位數。", "response_removed": false, "topic": "都市更新與建築管理人員高流動率及審查效率"}, {"citations": [{"page": 4107, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=19"}, {"page": 4109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=21"}, {"page": 4109, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=21"}, {"page": 4110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=22"}, {"page": 4111, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=23"}, {"page": 4110, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654984FBE9CA0452721561B68D91D8175C7D907EC358AFC7D15AA852238F00A7C162#page=22"}], "councilor_points": ["陳賢蔚議員關注新光人壽T17及T18基地開發進度延宕問題，並指出T12基地已兩次流標，質疑招標條件與底價設定吸引力不足。陳賢蔚議員要求市府主動追蹤履約狀況，並由產業發展局與地政局跨局處合作召開公開招商說明會，重新檢討標規與開發策略。"], "response": "產業發展局局長說明將與地政局研議舉辦公開招商說明會以吸引廠商投資，地政局土地開發總隊科長說明目前正就環境等因素檢討流標原因。", "response_removed": false, "topic": "北投士林科技園區開發進度與招商招標策略"}, {"citations": [{"page": 1533, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=12"}, {"page": 1534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=13"}, {"page": 1534, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=13"}, {"page": 1535, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=14"}], "councilor_points": ["陳賢蔚議員指出大巨蛋在B2球場層舉辦賽事時有上千名觀眾入場，質疑逃生安全規範與讀賣巨人交流賽時動線混亂問題。陳賢蔚議員要求體育局查明遠雄與主辦單位是否配足都市計畫審查要求的427位避難引導人力，並要求告知租借單位動線資訊及辦理實際演練。"], "response": "體育局局長表示會要求主辦單位依大型群聚活動安全管理自治條例提出疏散規劃與人員管控，並承諾在1個月內提供查明資料與相關計畫。", "response_removed": false, "topic": "大巨蛋球場層安全疏散與避難動線演練"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-31"], "dept": null, "doc_type": "市政總質詢", "group": 13, "heading": "市政總質詢第13組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162#page=1", "transcript_pages": [1336, 1337, 1338, 1339, 1340, 1341, 1342, 1343, 1344, 1369, 1370, 1371, 1372, 1374], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB9637356654985A07A6EBCECAD7CC2DF990CAEF06B98C22A066A793D6E69A852238F00A7C162", "videos": [{"date": "2024-05-31", "group": 13}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 11, "heading": "教育部門質詢第11組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549E3C70BFF0E1757C374F8795B683F2AD82F9DD8CC68610C2BA852238F00A7C162#page=11", "transcript_pages": [1532, 1533, 1534, 1535, 1536, 1537], "transcr