tml?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665490B1F0E8037FA840A8322F6B39C8B36FB1D3F11B9CD8F40DCA852238F00A7C162','2026-10-07T09:07:46Z');
INSERT INTO "fact" VALUES('summary:14-03:pc50235ea45','pc50235ea45','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-07T09:07:46Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2079, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162#page=1"}, {"page": 2084, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162#page=6"}, {"page": 2081, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162#page=3"}], "councilor_points": ["顏若芳議員詢問衛生局於寶林茶室案初次稽查時未帶回刀具與料理盆等嫌疑食材之原因，並建議重新檢討食物中毒現場稽查紀錄表、增加具公衛背景之食安官，以及重新檢討食物中毒作業 SOP（引文：「24 日你們檢驗了什麼？砧板、廚師的手，但沒有檢驗刀子、調味料、料理盆等，這些都沒有」；「第一點，修訂食物中毒現場稽查黨紀錄表，不適用於環境衛生，這部分請重新修正。第 2 點，食安官應該要有公衛背景，增加有公衛背景的專業人士，避免食安官不曉得整現場狀況。第 3 點，關於食物中毒的 SOP 應重新檢討」）。"], "response": "衛生局局長說明將針對相關檢驗與流程進行精進，並表示專家會議定於 5 月 1 日討論相關事項，預計於會議後 2 個禮拜到 1 個月內提供相關紀錄與研擬內容（引文：「專家會議定於 5 月 1 日會討論」；「大約在會議後的 2 個禮拜到 1個月內提供」）。食品藥物管理科科長說明進行食品中毒案稽查時，現場會採取針對環境部分的表單並作成書面紀錄（引文：「我們進行食品中毒案稽查時，現場會採取右邊表單針對環境部分，包括作業場所環境衛生檢查，稽查員還會將在稽查現場看到的狀況，作成書面紀錄」）。", "response_removed": false, "topic": "寶林茶室食品中毒案稽查與採樣流程"}, {"citations": [{"page": 4069, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=11"}, {"page": 4073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=15"}, {"page": 4070, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=12"}, {"page": 4073, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=15"}], "councilor_points": ["顏若芳議員要求資訊局查核台智光光纖幹線覆蓋率 99.9%之真實性，指出警用監視器 3M 傳輸速率價格偏高，並要求重新檢討 3M 費率之計費方式（引文：「報出來的數字是 99.9%，對於這麼高的數字，本席表示存疑，希望你們不要只是人家報了數字進來就統統照單全收」；「解約之前，是不是跟台智光重新就母約進行談判，3M 的計費方式應該重新檢討」）。"], "response": "資訊局局長表示會研議現勘與查核辦法，並說明資訊局負責議定價格合理性及尋找備援方案，承諾會就 3M 費率問題與相關單位商議後於 1 個月內答覆（引文：「80%到 99.9%的這一段，剛剛承諾林議員會進行現勘」；「在解約上面，我們現在負責幫忙尋找其他可能的備援可行方案」；「因為費率並不是資訊局的權責，所以可能要跟其他人商議之後，才能夠給議員一個明確的時間點」）。", "response_removed": false, "topic": "台智光案費率覆蓋率與公文紀錄調閱"}, {"citations": [{"page": 875, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=11"}, {"page": 872, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=8"}, {"page": 874, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=10"}], "councilor_points": ["顏若芳議員詢問今年上海-臺北雙城論壇舉辦時間與討論主題，並要求市府於論壇舉辦前 1 個星期完整向臺北市議會報告相關內容（引文：「在雙城論壇前 1 個禮拜是不是可以完整地向臺北市議會報告」）。"], "response": "市長說明今年舉辦時間仍在與上海協調溝通中，主題經中央核定且確定後可向議員說明（引文：「今年的時間我們確實還沒有訂，還在與上海溝通中」；「只要中央核定，議員有需要，我們都可以私下個別跟議員做清楚的說明」）。觀光傳播局局長說明視訊會議已討論今年舉辦時間、預定地點及 MOU 方向（引文：「視訊會議討論今年可能在什麼時間舉辦，也提了一些預定地點。在 MOU 的部分，今年大概是朝哪個方向進行」）。", "response_removed": false, "topic": "雙城論壇籌備與資訊公開"}, {"citations": [{"page": 1511, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=9"}], "councilor_points": ["顏若芳議員指出文化資產委外場館不應以營利金額作為考核 KPI，建議依文化資產保存法精神採平等簽約合作並彈性調整委外作業要點（引文：「把這個文化資產、無形資產、無價的資產，用賺錢的 KPI來衡量是否繼續經營」；「希望能夠在 4 月底修改臺北市政府文化局委外館所經營管理督導委員會作業要點」）。"], "response": "文化局局長說明已與蔡瑞月基金會溝通，承諾可研議修正不合理之 KPI 並將咖啡廳項目替換，且會依議員建議的方向研擬辦理及向文化部接洽（引文：「我有跟他談，KPI 若不合理，可以研議修正」；「我會依照議員期望的這 3 點去進行」）。", "response_removed": false, "topic": "蔡瑞月舞蹈社及文化資產委外經營模式"}, {"citations": [{"page": 876, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=12"}, {"page": 877, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=13"}], "councilor_points": ["顏若芳議員詢問市長是否獲邀參加大巨蛋商場開幕，指出體育局對於遠雄公司缺乏監督強制力，並建議市府應掌握大巨蛋營運主導權（引文：「都即將要進駐開幕了，市長有沒有被邀請」；「你要怎麼樣把臺北市政府的主導權，讓體育局能夠主導或者是跟遠雄同步並行合作」）。"], "response": "市長說明大巨蛋為 BOT 案，市府有簽訂合約與要求機制，將借鏡日本考察經驗要求遠雄做得更好，並表示漏水問題會在 5 月底改善完成（引文：「我們跟遠雄都有簽訂合約，有相關機制可以要求」；「漏水的問題在 5 月底就會改善完成」）。產業發展局局長說明遠東 SOGO Garden City 第 1 期預計於月底開幕，當時尚未收到邀請（引文：「遠東 SOGO 的 Garden City 第 1 期，大概一千四百坪左右，會在月底開幕」；「目前還沒有收到」）。體育局局長說明會持續督導遠雄，漏水問題於月底會完成改善（引文：「持續改善，這個月底會完成漏水的改善，我們也都有去督導」）。", "response_removed": false, "topic": "臺北大巨蛋營運管理與分潤機制"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-05-22"], "dept": null, "doc_type": "市政總質詢", "group": 2, "heading": "市政總質詢第2組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162#page=5", "transcript_pages": [869, 870, 871, 872, 873, 874, 875, 876, 877, 878, 879, 902, 903, 904], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162", "videos": [{"date": "2024-05-22", "group": 2}]}, {"dates": ["2024-04-15"], "dept": "教育", "doc_type": "部門質詢", "group": 10, "heading": "教育部門質詢第10組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162#page=7", "transcript_pages": [1509, 1510, 1511, 1512, 1513, 1514], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB9637356654927B5A7B949365C867A9A58DD7ED629328BBB325421BA3701A852238F00A7C162", "videos": [{"date": "2024-04-15", "group": 10}]}, {"dates": ["2024-04-19"], "dept": "交通", "doc_type": "部門質詢", "group": 8, "heading": "交通部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162#page=8", "transcript_pages": [635, 636, 637, 638, 639, 640, 641, 642], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB9637356654993073EDD21C94FA2A3DB483AE5426AE104397EAD1C75C6AEA852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 8}]}, {"dates": ["2024-04-30"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 14, "heading": "警政衛生部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162#page=1", "transcript_pages": [2079, 2080, 2081, 2082, 2083, 2084, 2085], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549454FE07257DC92667E1A2370D0CFDE7A095CE8B71262D78CA852238F00A7C162", "videos": [{"date": "2024-04-30", "group": 14}]}, {"dates": ["2024-05-07"], "dept": "工務", "doc_type": "部門質詢", "group": 14, "heading": "工務部門質詢第14組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CC6FB88B7121BA54BCDA3DCAE4FCE1A81C2378305888797DA852238F00A7C162#page=6", "transcript_pages": [2507, 2508, 2509, 2510, 2511], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE66F11DD4EFE3C749BA02DB96373566549CC6FB88B7121BA54BCDA3DCAE4FCE1A81C2378305888797DA852238F00A7C162", "videos": [{"date": "2024-05-07", "group": 14}]}, {"dates": ["2024-05-10"], "dept": "民政", "doc_type": "部門質詢", "group": 8, "heading": "民政部門質詢第8組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162#page=17", "transcript_pages": [2856, 2857, 2858, 2859, 2860, 2861, 2862, 2863], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB96373566549F1FD55CEFEFD91CE401FB357E4B12CDF07E9B7D725795D28A852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 8}]}, {"dates": ["2024-05-16"], "dept": "財政建設", "doc_type": "部門質詢", "group": 1, "heading": "財政建設部門質詢第1組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162#page=10", "transcript_pages": [4068, 4069, 4070, 4071, 4072, 4073, 4074, 4075, 4076, 4077, 4078, 4079], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6693AF57BCE813431A02DB9637356654951EF1EF6DA5339F36D22397A584E69FB54E0DED384829BE3A852238F00A7C162", "videos": [{"date": "2024-05-16", "group": 1}]}], "status": "ok"}','https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE679528458FEF3D8FDA02DB9637356654900BAB5787AE507EA8CF9D41CE963653542FBDF860ACCD0FFA852238F00A7C162','2026-10-07T09:07:46Z');
INSERT INTO "fact" VALUES('summary:14-03:pacac98c45a','pacac98c45a','summary','2024-06-04','{"disclaimer": "質詢摘要為AI產出，僅供參考用途，詳細事實以原質詢速記錄與影片為準", "generated_at": "2026-10-06T03:43:38Z", "generator": "NotebookLM", "issues": [{"citations": [{"page": 2807, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162#page=2"}, {"page": 2809, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162#page=4"}, {"page": 2811, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162#page=6"}, {"page": 2808, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162#page=3"}], "councilor_points": ["黃瀞瑩議員指出，衛生福利部新訂居家托育訪視指引將一般訪視提高為 1 年 4 次、加強訪視為 1 年至少 6 次，且臺北市部分行政區訪視人員平均負責案量達 60 件以上，顯見人力量能遠遠不足（引文：「「一般訪視」提高為一年 4 次，而「加強訪視」為 1 年至少 6 次」；「平均負責案量都有 60 件以上，這樣的數據已經超出原本的標準規範，所以臺北市訪視人員的量能，看起來真的是遠遠不夠」）。黃瀞瑩議員建議社會局研議久任津貼以留住訪視人力，並應因應保母人力斷層、儘速上路全日托喘息服務，同時持續推動公辦民營機構人員薪資隨軍公教調薪（引文：「朝著「久任津貼」這件事情做研議與討論」；「7 月即將實施全日托的保母喘息服務」；「儘快讓公辦民營機構的人員薪資，可以隨著軍公教調薪」）。"], "response": "社會局局長說明，市府會完全遵照中央指引規範，針對全日托與夜間托育增加訪視規劃（引文：「我們會完全遵照中央的指引規範來做事」）。社會局局長表示，會持續關心訪視人員並觀察調薪後的久任效果，規劃於 7 月實施喘息服務，並積極與尚未調薪的 20 間公辦民營機構溝通（引文：「我們還是很關心訪視人員，所以有不斷有與他們開會。」；「原則上應該是 7 月可以開始實施，沒有問題。」；「現在目前尚有 20 間公辦民營機構未調整薪資」）。", "response_removed": false, "topic": "居家托育服務與公辦民營機構薪資改善"}, {"citations": [{"page": 1460, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=6"}, {"page": 1461, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=7"}, {"page": 1481, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=27"}, {"page": 1483, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=29"}, {"page": 1482, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=28"}, {"page": 1483, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=29"}], "councilor_points": ["黃瀞瑩議員詢問，臺北市政府針對社會住宅新增 7,000 戶的目標是否改變，並指出預估期程下修至 5,360 戶且少掉 1,640 戶，若樟新市場與黎元市場基地止步，任內恐僅有新工處保養廠 198 戶開工（引文：「是不是還是朝著 7,000 戶的方向前進？」；「我發現你們偷偷地把 7,000 戶修到五千多戶，這裡面不見的一千六百多戶到底去哪裡了？」；「4 年下來，你只會完成 198 戶。」）。黃瀞瑩議員建議臺北市政府應主動與國防部對接溝通接手大我退舍分期開發社宅，並要求於 4 年任內推行輪候制（引文：「大我退舍在臺北市社會局也好，都發局也好，願不願意去跟國防部做一個對接跟溝通？臺北市主動來協助這些退員的安置？」；「在市長您的任內這 4 年，有沒有可能開始推行輪候制？」）。"], "response": "臺北市市長說明，市府仍以目標努力盤點資源土地，新內閣上任後會再次主動與國防部了解並表達接手大我退舍意願，輪候制則需邀集專家學者與民團開工作坊細緻討論（引文：「我們當然是把目標訂定出來，我們也很努力、積極盤點目前臺北市可以使用的資源、土地，確實並不容易。」；「新內閣上任後，我們會再次主動跟國防部了解。」；「可能還要更多細緻的討論。」）。都市發展局局長說明，研議中的輪候制包含排序與搭配積分，搭配積分對弱勢族群較有幫助，但年輕族群會考量積分問題（引文：「我們研究的輪候制會有輪候的排序，還要搭配積分，搭配積分是對弱勢族群比較有幫助的，但是年輕族群會覺得他的積分……」）。", "response_removed": false, "topic": "社會住宅興建目標與政策推動"}, {"citations": [{"page": 1515, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=61"}, {"page": 1516, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=62"}, {"page": 1519, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=65"}, {"page": 1520, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=66"}], "councilor_points": ["黃瀞瑩議員指出，幼兒接種輪狀疫苗費用達 5,400 元至 5,700 元，建議市府放寬第一類設籍 2 年之限制，並擴大全額補助對象至中低收入戶、寄養家庭、小爸媽等族群，同時倡議將輪狀疫苗及腸病毒 71 型疫苗納入公費（引文：「單以這個疫苗本身的費用是 5,400 元到 5,700 元」；「應該把中低收入戶也納入補助範圍；另外是寄養家庭、20 歲以下的小爸媽、身心障礙子女、早產兒及藥癮寶寶，這些是不是也都可以一併納入評估的對象？」；「輪狀病毒及 71 型腸病毒疫苗都一起納入公費疫苗的補助範圍」）。黃瀞瑩議員指出，自費產檢項目費用高昂，建議市府將非侵入性胎兒染色體分析（NIPT）納入孕婦產檢補助，並提高自費產檢補助金額至 3,500 元（引文：「希望臺北市可以把 NIPT 納入孕婦產檢的補助項目之一，另外，也可以檢討對於這些自費產檢項目裡面的補助金額，是不是可以再擴大？我覺得至少要和嘉義市差不多，補助到 3,500 元」）。"], "response": "臺北市市長表示，市府確定於明年將輪狀疫苗定額補助之父母設籍限制由 2 年改為 10 個月，全額補助對象與腸病毒疫苗擴大範圍則進行盤點評估，並會積極向中央倡議納入公費（引文：「明年我們就會一致改成 10 個月。」；「我們先做盤點和總經費的精算，好不好？」；「我們會積極向中央倡議，我們都可以研議。」）。臺北市市長說明，會整體研議將 NIPT 納為產檢選項之一並估算整體經費增加補助（引文：「可以，我們整體研議，也許可以把 NIPT 納成是選項之一，估算整體經費，增加一些補助。」）。", "response_removed": false, "topic": "兒童疫苗補助與孕婦產檢加碼"}, {"citations": [{"page": 650, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=4"}, {"page": 652, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=6"}, {"page": 653, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=7"}, {"page": 654, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=8"}, {"page": 656, "source_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=10"}], "councilor_points": ["黃瀞瑩議員指出，YouBike 恢復前 30 分鐘免費後使用次數增加 30%，但調度人力由去年同期的 279 人降至 266 人，且「里民小幫手」僅有 10 人，導致無車可借與無柱可還問題加劇（引文：「前 30 分鐘免費的政策下，增加多少的使用次數？」；「113 年 2 月是 266 人，相較去年 2 月當時還有 279 人。」；「「里民小幫手」衛環人員人數 3 人加調度人員人數 7 人」）。黃瀞瑩議員要求交通局檢討精進「里民小幫手」計畫、提出有效調度人力對策，並優先改善熱門站點周遭之自行車用路環境與增劃安全自行車道（引文：「希望你們能夠檢討和精進「里民小幫手」的計畫，提出有效 YouBike 調度人力的對策。」；「優先檢討、改善 YouBike 熱門站點周遭的自行車用路環境，增劃安全的自行車道」）。"], "response": "交通局局長說明，YouBike 恢復前 30 分鐘免費後使用次數增加約 30%，汽機車移轉率約 22%，未來看待車輛與站點增加也會要求微單公司同比例增加人力（引文：「before（以前）跟 after（以後）大概增加 30%左右。」；「未來一年還會再增加更多的車輛跟站點，勢必人力要同比例或一定比例的增加，這是我們一定要去要求的。」）。交通局局長表示，人車分道是終極追求目標，能做人車分道會儘量做，若人行道過窄則不讓自行車騎上人行道，並承諾針對調度人力與自行車路網提出書面報告（引文：「所以能夠做自行車道人車分道的話，我們一定儘量做。」；「狹窄不夠寬度的人行道，就乾脆不要讓自行車騎上人行道」；「我們會把目前執行的和以前有做過的路網建議一起提出來。」）。", "response_removed": false, "topic": "YouBike前30分鐘免費配套與自行車道劃設"}], "session": "第14屆第3次定期大會", "sources": [{"dates": ["2024-06-03"], "dept": null, "doc_type": "市政總質詢", "group": 16, "heading": "市政總質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162#page=6", "transcript_pages": [1460, 1461, 1462, 1480, 1481, 1482, 1483, 1484, 1485, 1486, 1487, 1512, 1513, 1514, 1515, 1516, 1517, 1518, 1519, 1520, 1521], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE645649DC1D7A0148BA02DB963735665497C3D3EADC245BD617A9A58DD7ED629326CC4FE71E4F69908A852238F00A7C162", "videos": [{"date": "2024-06-03", "group": 16}]}, {"dates": ["2024-04-16"], "dept": "教育", "doc_type": "部門質詢", "group": 16, "heading": "教育部門質詢第16組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162#page=26", "transcript_pages": [1651, 1652, 1653, 1654, 1655, 1656, 1657], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE6B8A3C67662495C29A02DB96373566549B5269BD8B27946A2BCE7BB64118CF0DB82F0FE3BED0AEA7EA852238F00A7C162", "videos": [{"date": "2024-04-16", "group": 16}]}, {"dates": ["2024-04-19"], "dept": "交通", "doc_type": "部門質詢", "group": 9, "heading": "交通部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162#page=1", "transcript_pages": [647, 648, 649, 650, 651, 652, 653, 654, 655, 656], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE647F45DA5D0EB5492A02DB963735665491DFF58504D91117648F2313A77D0D3F87B544050971E9658A852238F00A7C162", "videos": [{"date": "2024-04-19", "group": 9}]}, {"dates": ["2024-04-26"], "dept": "警政衛生", "doc_type": "部門質詢", "group": 9, "heading": "警政衛生部門質詢第9組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162#page=9", "transcript_pages": [1950, 1951, 1952, 1953, 1954, 1955, 1956, 1957, 1958, 1959], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE61C99DD2E70ED0A3BA02DB96373566549141E1072BE44DFCD8322F6B39C8B36FBF221A79CF0489527A852238F00A7C162", "videos": [{"date": "2024-04-26", "group": 9}]}, {"dates": ["2024-05-10"], "dept": "民政", "doc_type": "部門質詢", "group": 7, "heading": "民政部門質詢第7組", "transcript_page_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162#page=1", "transcript_pages": [2806, 2807, 2808, 2809, 2810, 2811, 2812, 2813, 2814, 2815, 2816], "transcript_url": "https://gaz.tcc.gov.tw/pdf/viewer.html?id=EA46139178DD3AE627D587DB9E690225A02DB9637356654938DFF99717A5FC66C611FF747A6B4EEA7300BB4DC95B4111A852238F00A7C162", "videos": [{"date": "2024-05-10", "group": 7}]}, {"dates": ["2024-05-07"], "dept": "工務", "doc_type"