INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1056:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1056, "session": "第20屆第6次定期大會", "term": 20, "title": "Meet Pacific 花蓮創新創業嘉年華對年輕人是很好的機會，但不要只專注在成名團體，要雪中送炭，聚焦的部分是否可多元化？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1056','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1058:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "主計處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1058, "session": "第20屆第6次定期大會", "term": 20, "title": "一、明（115）年度縣府總預算為 401 億元，主要的編列方向與原則為何？在預算分配過程中，又是如何平衡各局處之間的經費需求？二、明年度的預算相較今年度有明顯成長，但中央補助的部分是否有刪減或延遲核定？縣府雖在 10 月已將預算送出，但程序委員會未獲通過，至今仍未收到正式的預算書。三、面對中央補助款減少或延遲公布的情形，縣府有何應變措施？哪些項目屬於法定必須支出，導致縣府的財務運作空間受限？四、預算編列過程中，是否有參考各局處的績效評估結果？希望能提供各局處預算執行數據。五、年底常見的「趕執行」或「花錢潮」現象，縣府有何具體的管理措施以避免浪費或效率低落？針對中程或重大建設計畫若有延宕的情形，預算移用或保留應如何處理？是否有導入績效預算或成果導向管理制度？縣府如何確保各局處遵守《預算法》與《會計法》相關規定，避免違規動支或超支的情形？六、建議主計單位建立一套可行的緊急小額支付機制，強化災害現場的即時應變能力。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1058','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1061:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1061, "session": "第20屆第6次定期大會", "term": 20, "title": "財劃法相關預算是否歸類好？很多預算都下到縣府，中央將很多補助案申請案歸納為地方政府的業務。是否有將相關的預算歸類好，讓地方鄉鎮市公所有所依據了嗎？例如藝文交流，未來地方要申請，你們有應對的政策了嗎？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1061','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1062:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1062, "session": "第20屆第6次定期大會", "term": 20, "title": "「族語治理鄉鎮」，災難發生時，大量的警示、公告、物資訊息，皆以漢語發布，部落長者根本無法第一時間獲取關鍵資訊。原民處應立即會同消防、警政、社會處，把「阿美語為主的族語告警模板」與「緊急輪播口白」準備到位。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1062','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1062:1:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "財政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1062, "session": "第20屆第6次定期大會", "term": 20, "title": "重大建設支出及財源調度是否公開透明？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1062','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1063:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "財政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1063, "session": "第20屆第6次定期大會", "term": 20, "title": "各局處預算執行率與預算結餘狀況如何？是否有閒置及重複編列的問題？是否推行績效預算及滾動檢討制度？如何提升支出效益？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1063','2026-10-07T15:11:39Z');
