INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1070:1:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1070, "session": "第20屆第6次定期大會", "term": 20, "title": "花蓮縣要徹底解決廚餘及垃圾問題，就是要自建花蓮縣的焚化廠與廚餘廠，因為現在垃圾放在各鄉鎮的暫置區及交給台泥去化，其實量能遠遠不足。請問環保局到底有沒有要做自建花蓮縣垃圾焚化廠的規劃？是否與殯葬設施可以同步規劃？殯葬一元化已經進入要召開民眾說明會的階段，你們也應該要開始規劃垃圾焚化廠。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1070','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1071:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1071, "session": "第20屆第6次定期大會", "term": 20, "title": "花蓮各河川疏濬廢土及建築廢棄物的去向，環保局是如何追蹤，還是只是抽查？是否有加強查緝非法傾倒廢土或棄置泥砂的專案？環保局如何與水利署及地政單位協調，以避免「疏濬變掩埋」的情況發生？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1071','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1071:1:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1071, "session": "第20屆第6次定期大會", "term": 20, "title": "因應非洲豬瘟疫情防疫禁止廚餘養豬，廚餘處理問題是否可以補助家戶廚餘處理機？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1071','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1072:0:p75beb1f83f','p75beb1f83f','interpellation','2025-10-31','{"councillors": ["笛布斯．顗賚"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1072, "session": "第20屆第6次定期大會", "term": 20, "title": "花蓮縣的廚餘回收率是多少？因為我們民生與營業廚餘量每天大概各 20噸，這個回收與全國平均相比是高還是低？我們環科每天可以處理的廚餘量也是 20 噸而已，廠區的機器應該要再增加。廚餘再利用（堆肥、沼氣、生質能）目前有哪些合作或示範場域，可以讓有意願的民眾去觀摩嗎？是否規劃建置中小型社區堆肥中心？目前你們只有設置 14 處堆肥示範點，有沒有可能結合部落農業循環利用？能與教育單位合作推動「廚餘減量與再利用」校園示範計畫？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1072','2026-10-07T15:11:39Z');
