INSERT INTO "fact" VALUES('hlccq:20260922155504-147:807:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["李正文", "笛布斯．顗賚", "蔡依靜"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 807, "session": "第20屆第6次定期大會", "term": 20, "title": "有關補助各直轄市及縣（市）政府聘僱用原住民社工員（師）實施計畫，原住民族委員會 115 年無編列預算支應，建請縣府應保障原住民社工員（師）工作權益，並研擬相關應變措施以續編明年度人事費用。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=807','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:856:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜", "林則葹"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 856, "session": "第20屆第6次定期大會", "term": 20, "title": "一、農地部分沒有取得保留地的部分中，農地受損的部分，其實都有地段地號可以調出申請人、土地所有權人，是否可以主動提供資訊給這些受災戶，主動寄相關資料給對方，看看用什麼方式讓這樣的申請可以更簡便？（蔡依靜議員）二、樺加沙颱風的部分，農業部的定點服務站有在光豐地區農會跟農糧署東區分署兩個地方。農業處在光復有一站式服務，因為鳳林的受災戶也很多，農業處這邊有沒有更積極的作法？另外，農業部提供了許多農業補助，農業處還可以協助什麼更積極的做法，讓農民可以更了解，可以與當地農會、公所做更積極的服務？（林則葹議員）"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=856','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1188:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1188, "session": "第20屆第6次定期大會", "term": 20, "title": "114 年 9 月 23 日光復鄉堰塞湖災害後，請問下水道後續因應及規劃計畫？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1188','2026-10-07T15:11:39Z');
