INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1190:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1190, "session": "第20屆第6次定期大會", "term": 20, "title": "一站式服務的第一線人員，必須要很了解所有申請項目、準備資料、延長申請時間，像是現金救助已經延長到 11 月 6 日、農機補助需要農機證已經放寬，由村長來開證明認定，有關相關申請實際怎麼執行，請提出說明。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1190','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1192:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1192, "session": "第20屆第6次定期大會", "term": 20, "title": "座談會有民眾反映，這次農地沒有受損的範圍，因為灌溉系統已經受損，可預知未來會影響收成，要擬定辦法提供救助。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1192','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1193:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1193, "session": "第20屆第6次定期大會", "term": 20, "title": "流域治理與農業是一體的，像水利單位在堤防加強的部分，也會吃到農地的部分，到底之後這個區塊的農地會怎麼使用？規劃是什麼？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1193','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1193:1:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1193, "session": "第20屆第6次定期大會", "term": 20, "title": "每個地區的受損的程度不一，農地垃圾要怎麼處理？是否橫向跟環保局討論？農地土的流失怎麼處理？可不可以說哪個地方的土可以拿來填補流失的土？請針對上禮拜會議當中大家提出來的項目來回復，會議記錄裡面縣府可以協助的部分提供書面資料來回復。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1193','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1195:0:p9c11191d7e','p9c11191d7e','interpellation','2025-10-31','{"councillors": ["蔡依靜"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1195, "session": "第20屆第6次定期大會", "term": 20, "title": "光復重建縣府的各局處都很有關聯性，花蓮縣政府的各局處是怎麽去對應中央的相關單位？縣府的重建委員會，我們自己到底是怎麽樣子的對口窗口？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1195','2026-10-07T15:11:39Z');
