INSERT INTO "fact" VALUES('hlccq:20251230114145-135:781:1:peca6b544a1','peca6b544a1','interpellation','2025-05-19','{"councillors": ["魏嘉賢"], "dept": "民政處－公共造產科", "doc_type": "口頭質詢答覆", "no_date": true, "page": 781, "session": "第20屆第5次定期大會", "term": 20, "title": "蘇花落石不斷，有沒有更快速的方法可以採取土石之後儘速運送？砂石可否輸出到日本？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=781','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:782:0:peca6b544a1','peca6b544a1','interpellation','2025-05-19','{"councillors": ["魏嘉賢"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 782, "session": "第20屆第5次定期大會", "term": 20, "title": "花蓮其實已有許多優秀的學生參與科展、小論文與發明展，這些比賽在學校端扮演著培養科技人才的重要角色。不少得獎的孩子未來有機會代表台灣前往日本、東南亞等地，參加國際級的發明競賽。然而，相對於學生的表現與潛力，花蓮似乎還未真正正視這些科學展覽與發明競賽背後的長期價值。我們是否可以重新思考，如何從國中、高中階段開始，系統性地培養在地孩子的研究能力與創新精神，一路銜接到大學，進一步讓他們的創意有持續發展的空間？是否有機會投入更多經費資源，支持學生進行實驗與研究？這不僅能鼓勵學子投入學術與技術創新，更可能為花蓮帶來新一代具創新能量的產業構想。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=782','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:783:0:peca6b544a1','peca6b544a1','interpellation','2025-05-19','{"councillors": ["魏嘉賢"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 783, "session": "第20屆第5次定期大會", "term": 20, "title": "本縣轄內殯葬設施設備多老舊，所編列補列各鄉鎮市公所辦理殯設施改善經費僅一千餘萬元，顯有不足。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=783','2026-10-07T15:11:39Z');
