INSERT INTO "fact" VALUES('hlccq:20240830153621-166:717:0:peca6b544a1','peca6b544a1','interpellation','2023-10-30','{"councillors": ["魏嘉賢"], "dept": "社會處、消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 717, "session": "第20屆第2次定期大會", "term": 20, "title": "一、查中華紙漿股份有限公司 111 年起至 112 年 9 月 31 日止，職業安全衛生法及勞動基準法，遭主管機關開罰共計 19 件。二、為避免重演 2023 年 9 月屏東明揚工廠因違法囤放過量化學品等原因釀成多名員工及消防員死亡之悲劇，建請社會處對中華紙漿股份有限公司花蓮廠按勞動檢查法規定進行職安檢查；同時本席也建請消防局針對該廠區化學品庫存、存放位置、消防自衛編組等是否符合相關法律規定要求依法進行檢查。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=717','2026-10-07T15:11:39Z');
