INSERT INTO "fact" VALUES('hlccq:20260922155504-147:903:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 903, "session": "第20屆第6次定期大會", "term": 20, "title": "縣府已經禁用廚餘養豬多年，目前議員辦公室有接到陳情疑似尚有豬農用廚餘養豬，農業處應訂定一個合適的監督及查核機制。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=903','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:904:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 904, "session": "第20屆第6次定期大會", "term": 20, "title": "樺加沙颱風針對河川地土地流失及埋沒的部分是沒有補助的。但是在 113年花蓮縣政府有開立專案，針對河川地土石流失埋沒的區域分別予以補助。今年光復洪災，縣府是否比照 113 年康芮颱風予以補助？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=904','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:904:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "主計處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 904, "session": "第20屆第6次定期大會", "term": 20, "title": "災害準備金的動支與預算匡列的相關問題：一、針對災害準備金的使用，縣府是否有完善的查核機制或標準作業流程？這次災害準備金動支時，發現匡列金額非常龐大，但實際運用上並不會動用到如此高額。縣府為何要匡列如此巨大的金額？這樣的匡列是否容易引起外界質疑？二、有關標準擴充的問題，標案的擴充是否是無上限的？擴充的依據與標準為何？縣府如何決定可擴充的範圍與金額？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=904','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:905:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 905, "session": "第20屆第6次定期大會", "term": 20, "title": "監視器車辨系統要跟上全國平均值 68% 需要 15 年，提醒警察局本縣近十年總預算已提升 40%，但警察局年度預算僅增加不到 5%，檢視本縣各警察駐地環境、警用裝備均非常老舊，造成本縣員警缺額持續攀高，在明年總預算增加七十幾億的狀況下，警察局應思考如何爭取預算，改善整體環境，並優先增設全縣監視器車辨系統，期儘早追上全國平均值。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=905','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:906:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 906, "session": "第20屆第6次定期大會", "term": 20, "title": "請警察局針對緊急防災系統傳遞，建立新的機制，避免再次誤鳴。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=906','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:906:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 906, "session": "第20屆第6次定期大會", "term": 20, "title": "光復災區救災車輛違規，警察局是否可以協助撤銷？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=906','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:907:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 907, "session": "第20屆第6次定期大會", "term": 20, "title": "這次洪災的發生，雖然事先知道有堰塞湖存在，但沒有先評估好相關嚴重狀況，在災害搶救的當中，消防局因為忙的關係，在系統中出了很多問題——別的縣市消防人員安排住在民宿、飯店，但本縣的消防員卻睡在路邊。雖然消防員有睡袋、帳篷，但仍然沒有很舒適。我想請教的是後勤有什麼問題？花蓮天災不斷，要面臨各式挑戰，爾後再發生相同情況，是否有準備好照顧消防員？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=907','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:907:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 907, "session": "第20屆第6次定期大會", "term": 20, "title": "目前光復仍有 5 名失蹤，家屬希望可以繼續搜救，剛剛局長報告會小額採購重機具繼續搜尋，但家屬似乎不知道這件事，希望消防局可以跟家屬好好溝通，與家屬做好資訊平衡，以免受非議。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=907','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:908:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 908, "session": "第20屆第6次定期大會", "term": 20, "title": "在災害發生的當下，會不斷的接到電話，需要即時的搶救，希望消防局能發展 AI 語音辨識系統，彌補人力不足。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=908','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:908:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 908, "session": "第20屆第6次定期大會", "term": 20, "title": "去年暑假觀光從 0403 之後對外交通很困難，但今年暑假交通沒問題，天氣也穩定，情況還是一樣，夏戀嘉年華及鯉魚潭花蓮 FUN 暑假花了快五千萬，辦了許多活動，也都沒有創新，對觀光本質也沒有推展也沒幫忙，花蓮本地人參與較多。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=908','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:909:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 909, "session": "第20屆第6次定期大會", "term": 20, "title": "垃圾掩埋場火災過於頻繁，對於民眾和隊員的健康及壓力造成負擔，過去台翔悶燒事件做出對應處置，設置足夠熱顯像儀，防止燃燒等部分，應加以宣導民眾勿將線香等危險物品丟入垃圾車。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=909','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:909:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 909, "session": "第20屆第6次定期大會", "term": 20, "title": "非洲豬瘟問題，鳳林環科園區因洪災受創嚴重，雖已恢復處理廚餘，過去全縣廚餘多數轉往其他有廚餘養豬的縣市，環保局向中央爭取提升本縣量能予以支持，也支持用縣預算先行辦理。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=909','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:910:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 910, "session": "第20屆第6次定期大會", "term": 20, "title": "針對本次災害應變，社會處物資收受發放，仍未跟上現今應有的程度及能力。收容安置與安排等資訊之提供，仍然不夠快確實與普及。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=910','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:910:1:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 910, "session": "第20屆第6次定期大會", "term": 20, "title": "本次災害物資發放訊息更新進度不及。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=910','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:911:0:p16f8911174','p16f8911174','interpellation','2025-10-31','{"councillors": ["胡仁順"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 911, "session": "第20屆第6次定期大會", "term": 20, "title": "請提供11月13日韓國首航直航至今各航班中韓國旅客的實際入境人數統計。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=911','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:756:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "行政曁研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 756, "session": "第20屆第5次定期大會", "term": 20, "title": "請提供縣府臺北聯絡處工作執行內容 、 人力與工作職掌 ， 及內部空間配置 （布置）等說明。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=756','2026-10-07T15:11:39Z');
