INSERT INTO "fact" VALUES('hlccq:20251230114145-135:768:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 768, "session": "第20屆第5次定期大會", "term": 20, "title": "近日有民眾反映，部分學生改裝電動機車並因此發生交通事故情形。為維護交通安全，請警察局加強相關宣導工作，並強化對改裝車輛的稽查與執法。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=768','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:773:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 773, "session": "第20屆第5次定期大會", "term": 20, "title": "有關舊田埔車站文化園區百年老樹護樹相關維護措施及與向中央主管機關申請相關經費公文資料。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=773','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:827:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 827, "session": "第20屆第5次定期大會", "term": 20, "title": "生命園區可行性評估及先期規劃作業進度？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=827','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:828:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 828, "session": "第20屆第5次定期大會", "term": 20, "title": "花蓮市戶所收發人員調到二樓原因？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=828','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:828:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 828, "session": "第20屆第5次定期大會", "term": 20, "title": "多縣市頻傳幼兒性侵事件，本縣是否已建立事先預防機制，包括跨局處通報和合作？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=828','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:829:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "政風處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 829, "session": "第20屆第5次定期大會", "term": 20, "title": "政風處於109年6月29日於官網張貼，其中第二點第三款敘明「承辦單位受理後，應簽會政風處及行政暨研考處文書檔案科，並經縣長或授權人員核定後，始可提供案卷資料，擅將文件檔案資料影印自行提供，將違反檔案法及公務機密維護等相關規定。另交卷或還卷時亦應詳細清點並作成紀錄以釐清責任歸屬。」若當縣長有違法時，上開說明是否合理？是否需要修正？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=829','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:830:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 830, "session": "第20屆第5次定期大會", "term": 20, "title": "北中南區主、副主任與各區戶政主任重疊參與公祭時，是否能協調由北、中、南區、副主任參與，讓各戶政主任回歸戶政業務？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=830','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:830:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 830, "session": "第20屆第5次定期大會", "term": 20, "title": "「疊石藝術季」舉辦以來廣受好評，活動規模逐年擴大，惟查近年活動辦理過程中，較少提及該活動創辦人，該活動係由一位在地民宿業者自發發起，未來辦理疊石藝術節相關活動時，應積極結合在地民間小型活動，並彰顯創辦人貢獻，延續活動初衷。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=830','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:831:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 831, "session": "第20屆第5次定期大會", "term": 20, "title": "臺東觀光進步，花蓮連車尾燈都看不到！期待花蓮觀光能再有之前的前景。花蓮觀光有什麼樣的缺點？會為此做什麼樣的改善？花蓮未來的走向？應重新定義觀光在未來的十年。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=831','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:832:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "花蓮縣地方稅務局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 832, "session": "第20屆第5次定期大會", "term": 20, "title": "請提供以下資料：一、謝謝縣長終於肯定議會通過在徐縣長任內合法礦石稅的徵收，當年抹黑議長、抹黑議員、抹黑議會的過去的歷史，縣長應該向議會道歉。二、財政部支持地方課徵特別稅，但不代表可以提前廢止舊法還漲 7 倍，請縣長不要混為一談。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=832','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:832:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "花蓮縣地方稅務局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 832, "session": "第20屆第5次定期大會", "term": 20, "title": "礦石稅部分，已經退還給業者，經過十幾年奔波，爭議也順勢解決，如果今天超收、超徵稅額，退還業者很合理，但是利息部分如何解決？從地方稅務局的記者會，只是一個二億多總數，還包含利息，利息部分用什麼樣方式退還給業者？利息部分不用再另外編列科目進到我們大會？會後請再提供書面資料回復。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=832','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:833:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "花蓮縣地方稅務局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 833, "session": "第20屆第5次定期大會", "term": 20, "title": "房屋稅新制採全國歸戶，民眾對於稅制不清楚，房屋同時供自住及民宿營業使用，為什麼按「非自住」之住家用稅率課稅？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=833','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:834:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 834, "session": "第20屆第5次定期大會", "term": 20, "title": "去年底因菸葉廠園區標示不清，夜間燈光不明，民眾摔傷導致韌帶斷裂開刀，目前已進入申請國賠階段，請會後查明回覆。園區內部負責單位如何區分？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=834','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:834:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 834, "session": "第20屆第5次定期大會", "term": 20, "title": "文化局辦理大型活動時，經常到北部開記者會，但在縣內似乎沒有辦記者會或採訪通知？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=834','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:835:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 835, "session": "第20屆第5次定期大會", "term": 20, "title": "北昌村將劃分成二個村，但當地僅有北昌一個派出所，對於人力、廳舍的設備要妥適規劃因應。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=835','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:836:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 836, "session": "第20屆第5次定期大會", "term": 20, "title": "台翔公司物料堆置導致火災，包括空氣污染、公共危險等，影響甚廣，必須深刻檢討並改善相關措施，以避免再度發生類似事件。一、請提供台翔、同心農等花蓮縣內所有SRF廠之緊急應變計畫，必須包括異溫預防管理機制。二、貴局在台翔悶燒事件後，是否又進行相關之檢討，並擬定改進措施，甚至與消防局的應變計劃檢討？若有，請提供本席參考。三、台翔二廠燃燒時，因必須從外地調用相關空污監測車輛來到花蓮，已喪失第一時間的空污監測正確性。而戴奧辛等監測也非第一時間進行，對民眾的健康影響無硛法據此協助。希望未來發生類似事件皆能在第一時間即開始詳細監測，以提供民眾健康引導方向，請貴局提供加速空污監測之檢討報告。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=836','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:842:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 842, "session": "第20屆第5次定期大會", "term": 20, "title": "垃圾車在前一天沒有收垃圾的日子，脫班非常嚴重，可以差到快兩小時，請問有方式可以補上這個問題嗎？很多人有事、沒辦法一直待在家等，最後垃圾就是亂丟，花蓮的各空地、路邊都是垃圾。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=842','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:944:1:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "政風處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 944, "session": "第20屆第5次定期大會", "term": 20, "title": "觀光處辦理自行車品牌招標案，沒有在 30 天內上無法決標公告，以及評審委員不符資格等情，請政風處瞭解。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=944','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:945:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 945, "session": "第20屆第5次定期大會", "term": 20, "title": "對於社會關懷據點撥款速度 ， 過去是每一季請款一次 ，第 4 個月就能請到款，近幾個月有發現將近半年款項都尚未請款下來，也許只是少數個案，請社會處多加留意。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=945','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:946:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 946, "session": "第20屆第5次定期大會", "term": 20, "title": "提醒社工與保母的心理健康要多加留意，不希望再發生剴剴案，如人力不足請補足。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=946','2026-10-07T15:11:39Z');
