INSERT INTO "fact" VALUES('hlccq:20251230114145-135:947:0:p16f8911174','p16f8911174','interpellation','2025-05-19','{"councillors": ["胡仁順"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 947, "session": "第20屆第5次定期大會", "term": 20, "title": "一、除了 AQI 監測之外其他監測空氣汙染的方式說明。二、說明本縣 SRF 廠是否有包含睿成，SRF 機構除了台翔興及同心農，其他機構是否也有緊急應變計畫？三、台翔二廠堆置情況及去化說明。四、空氣品質監測是否規劃項中央申請相關計畫補助。五、廠內逕流汙水後續處理方式說明 。 除了 AQI 監測之外其他監測空氣汙染的方式說明。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=947','2026-10-07T15:11:39Z');
