INSERT INTO "fact" VALUES('hlccq:20250515155455-161:763:0:p16f8911174','p16f8911174','interpellation','2024-10-17','{"councillors": ["胡仁順"], "dept": "行政暨研考處新聞科", "doc_type": "口頭質詢答覆", "no_date": true, "page": 763, "session": "第20屆第4次定期大會", "term": 20, "title": "行研處新聞科編列 2,900 多萬整合各局處相關廣播電視形象 ， 請問各局處是否無編列這筆預算嗎？一年花多少？縣政報導編列 3 百多萬是否足夠？建議在額度使用，中南區部分可派到村里辦公室，讓想看的民眾自取。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=763','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:763:1:p16f8911174','p16f8911174','interpellation','2024-10-17','{"councillors": ["胡仁順"], "dept": "行政曁研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 763, "session": "第20屆第4次定期大會", "term": 20, "title": "行研處編列北中南服務中心 6 位約用分別到北中南區服務，為何還要編列約用人員在行研處，處內人力夠嗎？"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=763','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:764:0:p16f8911174','p16f8911174','interpellation','2024-10-17','{"councillors": ["胡仁順"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 764, "session": "第20屆第4次定期大會", "term": 20, "title": "簡報沒有提及廠商的背景還有營業項目，民眾及議員都不清楚，現場只看到垃圾山，都不清楚廠商到底是在燒什麼。從事發到啟動監測調查花了一個禮拜動作太慢了，現場還在燜燒有無後續處理的 SOP，之後能不能送去鳳林的掩埋場？空汙發生之後需要檢測才能知道是否有毒物質，有處理的 SOP嗎？現在東北季風強盛時期有無即時發佈訊息？事發當下沒有作為，民眾透過媒體知道現在還在燜燒造成恐慌，縣政府卻無作為來安撫民心，縣政府未做好事前管理，事發後未向縣民報告，後續的處置也沒有完整的說明。目前還在燜燒要如何處置，不是罰錢了事而已，目前工廠內還有 5,000 公頓是什麽？之後是不是要送去鳳林掩埋場？請如實回答如何處理。燜燒是否與堆置過高有關，是被人放火還是自燃？有無去調查了解？環保局是這個事件的主責單位，但是對整個事情的緊急處理，還有對民眾的說明都完全失策。目前媒體及民意都還在關注這個事情，但是環保局只有二天公布一次訊息。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=764','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:766:1:p16f8911174','p16f8911174','interpellation','2024-10-17','{"councillors": ["胡仁順", "林品仰", "林玉芬"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 766, "session": "第20屆第4次定期大會", "term": 20, "title": "一、外籍教學人員在本縣的整體分佈及薪級分配。二、外籍教學人員聘任後服務於偏鄉地區的生活費及交通費的補助。三、推動偏鄉英語教育，跨校共聘外籍教學人員，以及運用外籍教學人員協助學校教師、家長學習英語，共創英語學習環境。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=766','2026-10-07T15:11:39Z');
