INSERT INTO "fact" VALUES('hlccq:20240830153621-166:760:1:p16f8911174','p16f8911174','interpellation','2023-10-30','{"councillors": ["胡仁順"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 760, "session": "第20屆第2次定期大會", "term": 20, "title": "一、花蓮觀光立縣，國內旅客推廣的部分，如何提升在地旅遊品質及多樣性；年年舉辦大型活動變化性不大，創造性不足，建議可以有更新穎更有創意的活動，提升活動亮點。二、另，國外旅客對花蓮不熟悉，境外旅客的設定重要，攸關縣內後續各國語言設置及指示；依據工作報告內容和各國都有做觀光交流，是否有設定未來觀光走向主流客人從哪裡來？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=760','2026-10-07T15:11:39Z');
