INSERT INTO "fact" VALUES('hlccq:20241226155839-140:733:2:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 733, "session": "第20屆第3次定期大會", "term": 20, "title": "針對屋主沒有提報的部分，未來是不是有一個機制，在多少時間內提出來做補強或重建的申請？而且連帶造成的損失，如租金的損失或其他方面，應建構一個機制，才能讓這一次的災害處理更完備。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=733','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:734:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 734, "session": "第20屆第3次定期大會", "term": 20, "title": "一、有關國土計畫法花蓮縣及各縣市進度為何？二、據了解報內政部版本與公開展覽版本差異甚大，民眾對此有極大的疑慮，可否再加開 1 至 3 場公開說明會作為補救措施？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=734','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:735:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 735, "session": "第20屆第3次定期大會", "term": 20, "title": "一、平均地權條例預售屋制度施行後，縣府迄今總計裁罰業者金額？並請加強宣導，避免業者遭受裁罰。二、代銷業者營業員是否需具營業員資格？請向代銷業者多加宣導。三、不動產開發建設公司與私人土地地主合建分售或分銷，預售屋是否可以由建設公司直接銷售？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=735','2026-10-07T15:11:39Z');
