INSERT INTO "fact" VALUES('hlccq:20241226155839-140:738:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 738, "session": "第20屆第3次定期大會", "term": 20, "title": "請問觀光處針對地震後是否有將局處或民間機關參訪留在花蓮，觀光處是否有相關作為應對。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=738','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:738:1:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 738, "session": "第20屆第3次定期大會", "term": 20, "title": "打造國際觀光友善城市，推動數位城鄉，優化無線網路 iTaiwan 熱點有 536處，但資訊上顯示 106 年網路就有 600 多處熱點，當時就敘明要增加 100處，這幾年下來沒增加，請說明。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=738','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:739:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 739, "session": "第20屆第3次定期大會", "term": 20, "title": "雲產業基地開幕至今 4 個月來才處理委託營運招標決標，時間上延宕那麼久，請說明，未來發展如何？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=739','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:739:1:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 739, "session": "第20屆第3次定期大會", "term": 20, "title": "一、許多公費疫苗於公告後就打完了，針對需求量大的疫苗，是不是可以增加數量？自費疫苗可否爭取為公費疫苗？接種疫苗落實疾病預防但同時應該要健康平權。二、成人應該要接種哪些疫苗？有沒有宣導？是不是可以建構成人施打疫苗的健康卡？登錄後可以方便民眾檢視查詢接種期程與紀錄。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=739','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:740:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 740, "session": "第20屆第3次定期大會", "term": 20, "title": "心理諮詢諮商使用率高，結案過後是否有提供短、中、長期關懷？另外針對心情溫度計施測後，是否提供統計與後續措施。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=740','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:740:1:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 740, "session": "第20屆第3次定期大會", "term": 20, "title": "0403 地震後，謝謝消防局的付出，想請教是否有相關的獎勵辦法？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=740','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:741:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 741, "session": "第20屆第3次定期大會", "term": 20, "title": "住警器一萬多戶為何要拒絕裝設？是否有因應措施？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=741','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:741:1:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 741, "session": "第20屆第3次定期大會", "term": 20, "title": "請說明現行社區營造計畫的內容、目的及方向。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=741','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:742:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["韓林梅"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 742, "session": "第20屆第3次定期大會", "term": 20, "title": "請說明將軍府周邊交通問題處理方案。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=742','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:964:1:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["黃馨", "韓林梅"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 964, "session": "第20屆第3次定期大會", "term": 20, "title": "一、國土計畫目前在本島只有花蓮縣送中央，其中僅 12% 為農業有效用地，非常不合理，包含保育用地的劃設影響地主權益，建議申請展延提出計畫。特別是目前提出版本與公展落差甚鉅，有 80% 不同。另吉安殺雞場的設置或相關嫌惡設施 ，建議在國土規劃中設有專區 ， 避免民怨。二、請地政處與建設處注意，未來國土計畫應確保米崙斷層上建築的安全，需要完整規劃與重建計畫。諸如專案補助、以地易地，或是建築防震規範都需與法規連結。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=964','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:978:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["楊華美", "傅國淵", "張美慧", "鄭寶秀", "韓林梅"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 978, "session": "第20屆第3次定期大會", "term": 20, "title": "一、個人計程車加入需透過工會推薦，目前 80 個個人行加入，判斷數量還是不足，花蓮幅員狹長，敬老愛心計程車量能的長期規劃為何？二、敬老愛心計程車－個人行何時可以加入營運？解決長者叫不到車的窘境，社會處是否有去了解及處理？請向大會報告，敬老愛心計程車配套措施要再加強。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=978','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:979:0:p05f49c81e0','p05f49c81e0','interpellation','2024-05-06','{"councillors": ["黃馨", "韓林梅"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 979, "session": "第20屆第3次定期大會", "term": 20, "title": "一、國土規劃全國除了連江、金門外，花蓮縣全國第一件送中央的，第三階是針對原住民的部分，土地列使用有非常大的落差，縣府無規劃土地發展，原住民權益受損，一階及二階也請地政處注意，包含農業處，對農民的配套措施尚未規劃，請撤回進行檢視修訂。勿以中央法規訂定而應以民眾權益考量。請會後提供第二階與第三階相關資料。二、國土計畫法，媒體有很大的報導，縣府是否知道會延後實施？又做了什麼因應及了解？是否有考量到農民的權益？為何公開的版本變動這麼大？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=979','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:776:0:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "政風處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 776, "session": "第20屆第2次定期大會", "term": 20, "title": "政風有無針對鄉公所積欠廠商貨款、工程款辦理相關查核？如何處置？有無要求鄉公所進行改善？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=776','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:776:1:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 776, "session": "第20屆第2次定期大會", "term": 20, "title": "選手代表本縣外出參賽（體育或表演藝術等），本府補助情形，以及獲獎之獎勵。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=776','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:777:0:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 777, "session": "第20屆第2次定期大會", "term": 20, "title": "目前學校少子化嚴重，請提供花蓮市學校空餘教室情形，並以表列方式呈現。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=777','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:778:0:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 778, "session": "第20屆第2次定期大會", "term": 20, "title": "不動產業界之金仲獎頒獎典禮，未來希望地政處能爭取全國表揚大會在花蓮舉辦。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=778','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:778:1:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 778, "session": "第20屆第2次定期大會", "term": 20, "title": "危險老舊建物評估、補強及重建補助僅呈現 106 年至 112 年的申請數量，請就 111 年與 112 年來作比較，才知道成效。輔導團已完成發包，請加強輔導團隊來配合實際需要並調整目標。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=778','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:779:0:p05f49c81e0','p05f49c81e0','interpellation','2023-10-30','{"councillors": ["韓林梅"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 779, "session": "第20屆第2次定期大會", "term": 20, "title": "詐欺案件有些 6 個月才曝光，手法多樣化，也有合法公司發行虛擬貨幣，還有以 line 聯絡，款項面交方法，如何防詐？希望加強媒體宣導，使民眾獲新知警覺以利防詐工作。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=779','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:838:0:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 838, "session": "第20屆第6次定期大會", "term": 20, "title": "一、警察局查獲二級毒品「依托咪酯」使用者之年齡層分布情形？二、今（114）年查緝依托咪酯案件數是否較去（113）年增加？三、校園少年涉用依托咪酯案件是否有上升情形？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=838','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:878:2:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 878, "session": "第20屆第6次定期大會", "term": 20, "title": "光復鄉親請託對於災害補助的資格有諸多疑義。先前 0403 時也有類似狀況，有關籍在人不在或屋主未設籍等情形，就無法請領到相關之災害補助金，又或者房東與房客，誰才符合請領補助資格？這些對象即便已拿到村長核發的實際居住證明，仍不得請領補助金。社會處會後能否提供列冊名單或是查詢名冊，以便後民眾查詢資格？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=878','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1226:0:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "社會處", "doc_type": "書面質詢", "no_date": true, "page": 1226, "session": "第20屆第6次定期大會", "term": 20, "title": "乙級技術士證照獎勵金發放？哪些縣市有？可以領多少？花蓮許多人在關心乙級技術士技能檢定考照後，有沒獎助金？台北目前是從 113 年開始有新增補助辦法金額給到了 5,000 元，新北一直都有 3,000 元。桃園的金額最高，給到了 8,000 元，但有限制資格，就是年輕人與中高齡。宜蘭目前獎勵金也是有 3,500 元，但是目前花蓮沒有！是不是縣府可以考慮增設這樣的獎勵金？不管是對青年部分或是退休中高齡的獎勵。附：原本有獎勵金的縣市，因為勞動部推動「重點產業青年取得重點產業職類技術士證及穩定就業獎勵試辦計畫」，有些縣市就把獎勵合併到該計畫中，但這個計畫沒有就業服務乙級，所以彰化原本有，也因此就取消了。但重點產業的計畫，因為成效不佳，變成高中、職學生考取電腦丙級的獎學金發放獎勵，對就業促進完全沒有幫助，113 年年底後就不再施行。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1226','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1227:0:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "農業處", "doc_type": "書面質詢", "no_date": true, "page": 1227, "session": "第20屆第6次定期大會", "term": 20, "title": "佐倉步道獼猴族群異常增長，很多登山客、在地居民都親身碰過。就是「花蓮佐倉步道」的獼猴，現在數量真的太多了！這些猴子很聰明，族群一直擴大，已經對遊客的安全造成威脅，也衝擊到生態平衡，且靠近人類活動區是一個越來越嚴重的問題。很多猴子直接在步道口找東西吃、甚至攔路，跟遊客要食物。人跟猴子的距離越來越近，衝突的機會當然就變高。這說明了什麼？這說明我們是不是在猴群的監測、管理和警示都跟不上實際情況了。猴子不是突然變兇，是因為我們的管理有漏洞，讓他們習慣靠人類的食物過活。不管是遊客主動餵，還是東西沒收好留下味道，都會讓猴子覺得「靠近人類」就有東西吃。這根本是人為造成的衝突。縣府現在的宣導、告示牌，還有管理方法，真的不夠力。安全風險已非單點事件，光是今年，就發生好多起猴子太靠近人的事件。有遊客被搶包包，還有被突然衝出來的猴子嚇到跌倒。我們不能等到真的有人「重傷」了，才來補救。佐倉步道不是給我們做實驗的地方。安全問題，一定要做在前面，不能老是出事才處理。現在佐倉獼猴的狀況，縣府沒有定期公布數量、沒有做熱區監測，連衝突紀錄也不完整。沒有數據，就沒辦法管理。沒辦法管理，政策當然會失準。現在是登山客和村民，自己在 LINE 群組裡互相通報：「今天猴子在哪裡！」這種資訊落差，真的很危險。建議一：設立「獼猴警示區」與即時通報。請縣府立刻在佐倉步道設立「獼猴警示區」。在步道口、轉彎點、停車場，都要有清楚的標示，告訴遊客該注意什麽。再來，要建立「猴群熱點地圖」 ，搭配即時通報機制。讓縣府、遊客、巡守員都能隨時掌握狀況。現在的資訊太少了，根本沒辦法保護遊客。建議二：落實餵食罰則與教育宣導。我們不是沒有法規，也不是沒有罰則，但現在幾乎看不到有人在取締餵食。這讓猴子越來越依賴人類的食物。一邊要加強勸導和取締，另一邊也要加強宣導。特別是對遊客、網路社群、登山團體，要不斷提醒。宣導不是貼個牌子就算了，要讓「不餵食」變成大家真的會遵守的習慣。建議三：建立長期監測與學者合作機制。佐倉的彌猴不會自己消失，他們會繼續生、繼續靠近人類。所以縣府一定要開始做：長期的族群監測一一掌握數量、分布和熱點。找學者專家一起合作一一了解猴群行為、季節變化。每年提出檢討報告，向民眾公開。這不是一個月就能解決的事，一定要有制度，長期來做。總結：保護自然，也要保護人。佐倉步道是花蓮很美的自然資產，獼猴也應該受到尊重和保護。但是，「保護自然」不應該讓「遊客來承擔風險」。人和野生動物之間，一定要找到一個安全的距離。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1227','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1228:0:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "觀光處", "doc_type": "書面質詢", "no_date": true, "page": 1228, "session": "第20屆第6次定期大會", "term": 20, "title": "觀光資源整合不足：花蓮的觀光資源整合不足！絕對不是沒有觀光活動、沒有亮點。問題恰恰相反－我們有活動，但沒有整合；有亮點，但沒有被串聯起來。這次本席要具體指出，花蓮目前最缺乏的就是一個全縣級的「觀光作戰指揮中心」，以及能夠把遊客送進各鄉鎮的「活動接駁專車」。問題一：活動資訊破碎，旅客難以掌握現在每個鄉鎮公所都很努力，各自辦活動。但問題是，資訊太分散了！每個單位更新的速度也不一樣。一個旅客來到花蓮轉運站、來到火車站，他想知道「今天整個花蓮，哪裡有活動可以參加？」他會發現：找不到、看不到、不知道。這真的不是旅客不認真查，是我們縣府從頭就欠缺一個整合的機制。花蓮現在需要的，不是辦更多活動，而是把現有的活動資訊，更好地送到旅客面前。問題二：沒有「活動專車」，人潮無法被導流很多民眾跟本席反應： 「我知道某某鄉鎮有活動，很想去，但不知道怎麽去。」「我沒有開車，根本不可能跑到那麼遠的地方參加活動。」這就造成一個很可惜的現象：活動辦得很努力，但人潮就是進不來。我們過去辦「溫泉專車」的經驗非常成功，確實帶動了整個溫泉區跟周邊的產業。但為什麼其他的特色活動，就沒有同樣的交通規劃呢？沒有便捷的交通，就沒有真正的觀光，這是最基本的道理。問題三：觀光處缺乏「統一中控」角色現在的狀況是，每個鄉鎮自己努力、自己宣傳、自己辦活動。但請記住，旅客看的是一個「完整的花蓮」，他不會只看你單一的一個鄉鎮。觀光處在這裡，應該要扮演一個「中央廚房」的角色。負責整合所有資訊、統籌整體行銷、規劃交通路線，甚至主動媒合不同鄉鎮的活動一起合作。但目前，我們完全沒有這樣的系統。結果就是，很多好活動沒被看見，很多潛在的人潮沒有被引導。這不是觀光處不努力，是它的戰略角色沒有被建立起來。建議一：建立縣級「觀光活動資料庫＋即時更新機制」本席的第一個具體建議，就是請縣府建立一個「縣級觀光活動資料庫」，並且要有即時更新的機制，同步到官方 APP 和網站上。這個資料庫要包含：所有鄉鎮的年度活動時程表、當日活動的即時推播、明確的活動地圖和交通方式、直接的官網與購票連結，讓旅客一到花蓮，打開手機就能立刻知道：「今天去哪裡最好玩」。這是一個觀光大縣應該提供的最基本服務。建議二：規劃「活動專車」串接特色活動強烈建議觀光處借鏡溫泉專車的成功經驗，主動開辦 「花蓮活動接駁專車」 。具體做法可以是：根據不同活動的地點，規劃專屬路線、結合定點班次與預約制，彈性調度、在轉運站、火車站設置清楚的資訊站、和民宿、旅館合作推廣交通套票，觀光最怕的就是「知道好玩，但到不了」。活動專車就像血管一樣，能把遊客這股活水，直接輸送到各個活動現場，自然就能帶動人潮、消費和整個在地產業。建議三：建立「觀光中控台」作為縣府統籌窗口這是最關鍵的一步，建議縣府成立一個「花蓮觀光中控台」。它的功能必須包括：整合 13 個鄉鎮所有的活動資訊、統一製作行銷素材，進行主題式包裝、主動媒合跨鄉鎮的活動，形成主題遊程、設計全縣季節性活動的主視覺、成為所有媒體和旅遊業者唯一的資訊窗口，只有這樣，才能讓花蓮的觀光從「單點閃耀」，變成「整體發光」。花蓮其實從來不缺亮點、不缺創意、更不缺願意辦好活動的人。我們最缺的，是一個能把所有珍珠串成美麗項鍊的那條線，那隻手。如果縣府能把「資訊整合」「交通接駁」「跨域行銷」這三件事情做到位，那麼花蓮的每一個活動，都可以成為吸引旅客再訪的理由，每一個鄉鎮，也都能從中真正受益。讓我們一起努力，把花蓮的觀光模式，從過去「人辛苦找活動」，翻轉成未來「活動主動吸引人」。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1228','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1232:0:pde739c60c6','pde739c60c6','interpellation','2025-10-31','{"councillors": ["徐子芳"], "dept": "教育處、花蓮縣警察局", "doc_type": "書面質詢", "no_date": true, "page": 1232, "session": "第20屆第6次定期大會", "term": 20, "title": "孩子的數位遊樂場，真的安全嗎？關於「Roblox」～現在很多家長，尤其是國小家長，心裡都很擔心的一件事－就是我們孩子在網路上的安全問題。現在，幾乎每個國小中高年級的孩子，都知道一個叫「Roblox」 的線上遊戲平台。它讓孩子可以自己創作、跟朋友互動、玩遊戲，看起來好像沒什麼。但事實上，它已經變成孩子們最主要的網路社交場所。而這裡面的風險，正是我們今天不能迴避的問題。問題一：平台風險被低估。Roblox 最大的問題，不是遊戲本身，是它的設計。它非常開放，可以即時互動，裡面有很多陌生人，伺服器還遍布全球。孩子在裡面可能會遇到：陌生人主動加你好友、收到來路不明的連結、被引誘購買遊戲點數、在聊天室被詐騙，甚至有成年人裝成小孩，在裡面接近他們，這些情況都不是個案，是真實且持續在發生的。我們絕對不能再抱著「那不過是個遊戲」的想法，來看這件事。問題二：政府介入有限，家長難以防範。Roblox 是一個國際平台，我們台灣地方政府沒辦法直接去管理它的內容。這導致很多家長根本搞不清楚：我的孩子到底在跟誰玩他們在聊天室裡聊了什麼？孩子有沒有被騙，不小心付了錢？連學校老師也很困難，因為他們對這個平台也不熟悉。本席必須講一句比較重的話：現在是孩子在網路世界裡奔跑，而我們大人，完全跟不上。問題三：缺乏制度化的數位安全教育。人們現在做的防詐騙、數位安全教育，大部分還停留在「不要亂點連結」、「不給個人資料」這種很基本的層次。但孩子們實際遇到的，是更複雜的情況：虛擬貨幣交易、遊戲裡的購買誘惑、陌生人的組隊邀請、聊天室的詐騙話術、甚至用暗語來溝通，面對這些新型態的風險，我們教育處沒有系統化的教材，警察局沒有針對兒少的宣導模組，學校也缺乏專門的輔導資源，這個落差，我們必須正視。建議一：將「網路平台風險」正式納入校園教育～所以我的第一個具體建議，是請教育處把「網路平台風險教育」，正式放進學校的課程裡面。這不能只是一次性的宣導講座，而是要像交通安全、性平教育一樣，每學期、每學年，有系統地來教。要讓孩子學會：怎麽判斷陌生網友可不可信識破常見的詐騙話術、管理遊戲內的消費、分清真實身份和虛擬身份的界線，這些能力，已經是現代孩子的必修課。建議二：建立「校園數位安全輔導員」制度～建議縣府試辦「校園數位安全輔導員」制度。人數不用多，但這些人必須要懂數位平台、了解孩子的使用習慣，能夠在第一時間，給老師和家長最直接的幫助。當孩子真的在網路上遇到問題時，不能只靠班導師自己上網查資料、自己想辦法。我們需要一個有系統、有制度的專業支援。建議三：建立「兒少數位安全聯防」跨局處機制～強烈建議縣府，成立一個「兒少數位安全聯防平台」，把教育處、警察局、社會處、資訊科都整合進來。因為這個問題，單靠一個局處根本解決不了。孩子被詐騙，需要警察局介入，孩子被誘惑加入不良群組，社會處要輔導，孩子在學校使用網路，教育處要負責宣導與管理，只有跨局處合作，才能真正為孩子織起一張安全的防護網。孩子在 Roblox 這個虛擬世界裡築夢、探索，我們大人該做的，就是在現實世界裡，為他們築起一道堅固的安全防線。我們不能等到真的有孩子受傷、受騙了，才來後悔說「早知道就應該早點處理」。網路世界的風險跑得很快，我們的保護措施必須要跑得更前面。只有讓制度先到位，我們的孩子才能安心、安全地長大。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1232','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:926:1:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 926, "session": "第20屆第4次定期大會", "term": 20, "title": "振興券是否有防偽？民眾有人收到假券，請縣府會同警察局確認是否屬實？避免造成民眾恐慌。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=926','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:926:2:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 926, "session": "第20屆第4次定期大會", "term": 20, "title": "針對公益、弱勢店家的商品做有效的行銷與推廣。本席建議：本縣可以開設一個類似『社會創新平台』透過有效的資訊檢核機制，讓縣內相關名產、手作、公益的商品有個被看見、被購買的機會。透過由縣府建立的推薦平台讓無法到花蓮旅遊卻想網路購買而幫助花蓮，讓平台去推薦的商店連結。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=926','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:927:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 927, "session": "第20屆第4次定期大會", "term": 20, "title": "截至今年 8 月，國內入出境人數逆差 64 萬，在疫情解封後，國人出國人數遠大於國外旅客來台，加上國旅退燒，如此巨大的逆差，花蓮的觀光該如何重生？本席的建議：一、跨局處整合將農遊、原民體驗做有系統的輔導，包含定價策略、服務品質等項目，讓縣內相關旅遊接待的店家是符合遊客與旅行社得期待。二、跨局處對縣內各局處的活動有整體行銷，分工推動的做法，譬如，豐年節的遊客招攬由觀光處協助。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=927','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1011:2:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["周駿宥", "徐子芳"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1011, "session": "第20屆第4次定期大會", "term": 20, "title": "惠請提供 113 年度補助民間團體辦理宗教活動相關經費資料。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1011','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1111:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "建設處", "doc_type": "書面質詢", "no_date": true, "page": 1111, "session": "第20屆第4次定期大會", "term": 20, "title": "每一個卓越的城市都有一條河流，像母親般的孕育著這個城市，花蓮市從水源地也有一條美崙溪，吉安也有七腳川溪，在親水的活動中，是否能規劃親水場域、溪流整治、河岸規劃、親水場域、親水活動？本席建議：盤點美崙溪周邊可開發的場域，進行潔淨河流的規劃，讓美崙溪成為縣民的驕傲，也是親水的好地方。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1111','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1112:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "教育處", "doc_type": "書面質詢", "no_date": true, "page": 1112, "session": "第20屆第4次定期大會", "term": 20, "title": "請提供獨木舟、風帆、立槳、潛水、沖浪、沙灘車、飛行傘、輕航機、體驗活動之相關管理權責單位，花蓮目前發展現現況、相關業者、活動場域，推廣與管理的規劃？建議從北到南依區域、活動種類做的長期規劃。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1112','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1113:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "觀光處、農業處、原住民行政處", "doc_type": "書面質詢", "no_date": true, "page": 1113, "session": "第20屆第4次定期大會", "term": 20, "title": "有關徐子芳議員提案，詢問康芮颱風帶來豐沛雨量及壯觀漂流木景象，北濱、南濱、化仁海堤、漁港際累積近一萬三千多噸的漂流木會何去何從？建議辦一場漂流木創作大賽，讓漂流木重新找到生命、打造新景點及創造新旅遊議題，請說明。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1113','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1114:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "原住民行政處", "doc_type": "書面質詢", "no_date": true, "page": 1114, "session": "第20屆第4次定期大會", "term": 20, "title": "原民處的『原鄉 e 市集』是否有具體銷售的績效提供給本席？本席建議：這網站已成立多年，具體協助多少原民、基本存在商品銷售低迷的原因應該有效檢討，否則就會淪為無效的網站。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1114','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1115:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "觀光處、農業處、原住民行政處", "doc_type": "書面質詢", "no_date": true, "page": 1115, "session": "第20屆第4次定期大會", "term": 20, "title": "截至今年 8 月，國內入出境人數逆差 641 萬，在疫情解封後，國人出國人數遠大於國外旅客來台，加上國遊退燒，如此巨大的逆差，花蓮的觀光該如何重生？本席的建議：一、跨局處整合將農遊、原民體驗做有系統的輔導，包含定價策略、服務品質等項目，讓縣內相關旅遊接待的店家是符合遊客與旅行社的期待。二、跨局處對縣內各局處的活動有整體行銷，分工推動的做法，譬如，豐年節的遊客招攬遊觀光處協助。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1115','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1116:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "農業處", "doc_type": "書面質詢", "no_date": true, "page": 1116, "session": "第20屆第4次定期大會", "term": 20, "title": "有關徐子芳議員提案，詢問康芮颱風帶來豐沛雨量及壯觀漂流木景象，北濱、南濱、化仁海堤、漁港際累積近一萬三千多噸的漂流木會何去何從？建議辦一場漂流木創作大賽，讓漂流木重新找到生命、打造新景點及創造新旅遊議題，請說明。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1116','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1117:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "觀光處、農業處、原住民行政處", "doc_type": "書面質詢", "no_date": true, "page": 1117, "session": "第20屆第4次定期大會", "term": 20, "title": "每一個卓越的城市都有一條河流，像母親一般的孕育著這個城市。花蓮市從水源地到北濱也有一條美崙溪，吉安也有七腳川溪，在親水的活動中，是否能規劃親水場域，河流整治、河岸規劃、親水場域、親水活動？本席建議：盤點美崙溪周邊可開發的場域，進行潔淨河流的規劃，讓美崙溪成為縣民的驕傲，也是親水的好地方。延續親水，花蓮有長達 175 公里的海岸線，海洋遊憩活動中多，是否可以納入觀光的項目之中，來增加年輕人的到訪率？本席建議：提供給本席獨木舟、風帆、立槳、潛水、衝浪、沙灘車、飛行傘、輕航機、體驗活動之相關權責單位，花蓮目前發展現況、相關業者、活動場域，推廣與管理的規劃，建議從北到南依區域、活動種類做里海的長期規劃。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1117','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1118:0:pde739c60c6','pde739c60c6','interpellation','2024-10-17','{"councillors": ["徐子芳"], "dept": "觀光處", "doc_type": "書面質詢", "no_date": true, "page": 1118, "session": "第20屆第4次定期大會", "term": 20, "title": "跨局處對縣內各局處的活動有整體行銷，分工推動的做法，譬如豐年節的遊客招攬由觀光處協助。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1118','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:742:1:pde739c60c6','pde739c60c6','interpellation','2024-05-06','{"councillors": ["徐子芳"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 742, "session": "第20屆第3次定期大會", "term": 20, "title": "一、建議繼續受理災後的建物安全評估。二、建議委請建築、地質專業人員檢測斷層帶上建物安全性，及辦理後續耐震補強及補貼。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=742','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:743:0:pde739c60c6','pde739c60c6','interpellation','2024-05-06','{"councillors": ["徐子芳"], "dept": "花蓮縣地方稅務局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 743, "session": "第20屆第3次定期大會", "term": 20, "title": "0403 震災受損房屋進行拆除作業時，道路封閉影響周邊商家權益，是否有相關稅務減免措施？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=743','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:780:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 780, "session": "第20屆第2次定期大會", "term": 20, "title": "關於社造點補助案評審委員資格與補助預算分配：對於我們社區營造點補助的評審過程和預算分配有所關注。根據所獲得的資訊，近幾年來，多次重複參與評審的委員中包括了廣播節目主持人和出版社編輯負責人等，本席希望了解這些經歷是否符合貴局對評審委員的資格要求。此外，我也關注到社區營造補助預算似乎掌握在固定的人士與組織手中。為了保證公平性和透明度，要諮詢文化局：評審委員的資格標準：請問貴局在審理社區總體營造評審委員時，所依據的資格標準是什麼？近年來參與評審的委員是否符合這些標準？評審選擇的透明度：貴局在選擇評審委員的過程中是否有一套公開透明的標準和程序？補助預算的分配公平性：對於社區總體營造補助預算，貴局如何確保資源分配的公平性和透明度？是否有防止預算長期掌握在固定人士或組織的機制？監督和評估機制：貴局是否設有監督和評估機制，以確保補助資金的有效利用和計畫的成功實施？社區參與與反饋：貴局是否鼓勵並接受來自社區的參與和反饋，以持續改進補助計畫的實施？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=780','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:978:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "民政處", "doc_type": "書面質詢", "no_date": true, "page": 978, "session": "第20屆第2次定期大會", "term": 20, "title": "建議持續支持美崙溪水燈祈福活動。本席特此提出對於去年成功舉辦的美崙溪水燈活動的關注。該活動不僅是文化傳承的重要渠道，也是促進社區凝聚和文化交流的絕佳機會。鑑於去年該活動由中央文化部補助，而今年因補助不足而停辦的情況，本席建議貴處考慮提供支援，以確保這一有意義的活動得以延續。鑑於此，誠摯地建議貴處考慮明年的美崙溪水燈活動提供必要的支援與補助，以確保這一具有意義的活動能夠持續下去。一、補助與資源支持：考慮對美崙溪水燈活動提供適當的活動補助和其他必要資源。二、組織與協調：協助活動組織者在籌劃和實施活動過程中，提供必要的行政協調和支持。三、宣傳與推廣：透過政府渠道和社區網絡，增加對美崙溪水燈活動的宣傳，吸引更多民眾參與。四、文化與環保結合：鼓勵將環保理念融入活動設計，如去年使用可自然分解的材料製作水燈，以強化活動的環保意識。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=978','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:979:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "消防局", "doc_type": "書面質詢", "no_date": true, "page": 979, "session": "第20屆第2次定期大會", "term": 20, "title": "關於花蓮縣吉安鄉南海三街火災事故：對於近日發生在吉安鄉南海三街的重大火災事故深感關切。此次火災造了嚴重的人員傷亡和財產損失，特別是 1 名高中生不幸罹難，令人痛心疾首。針對此次火災～一、火災發生經過與救援情況：請問消防局在接到報案後的反應時間、出動的人員和設備情況，以及救援行動的具體過程是如何的？二、火災原因調查：目前對於起火原因的調查進展如何？是否已有初步的判斷或發現？三、防火安全檢查與教育：請問消防局是否定期對居民住宅進行防火安全檢查？是否有針對社區居民進行防火安全教育和演習？四、住宅火警警報器安裝情況：據報導，受影響住戶中只有部分安裝了住宅用火警警報器。請問當前花蓮縣住宅火警警報器的安裝普及率如何？消防局是否有計劃提高這一比率？五、應對大規模火災的準備：針對此類大規模火災，消防局有何應對措施和預案？是否有足夠的人力和資源來有效應對？六、家屬與受影響居民的援助：對於此次火災的受害者和家屬，以及受影響的居民，消防局和相關部門提供了哪些援助和支持？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=979','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:982:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "衛生局", "doc_type": "書面質詢", "no_date": true, "page": 982, "session": "第20屆第2次定期大會", "term": 20, "title": "關於花蓮縣學童與青少年網路成癮問題～我們學童和青少年在網路及手機遊戲上的沈迷問題。根據與花蓮門諾醫院身心科醫師的交談，這已經成為一個不容忽視的社會問題，每週都有超過一名病患因網路成癮尋求幫助。本席認為，這不僅是個別現象，而是需要我們縣政府、學校、家庭及全社會共同面對的重大課題。為此，要諮詢教育處與衛生局：一、當前狀況與調查分析：請問目前教育處與衛生局對於花蓮縣學童和青少年網路成癮的現狀有何了解？是否有進行過相關的調查或研究？二、教育介入與預防策略：教育處針對網路成癮問題有何預防和介入的策略？學校如何在教育過程中，幫助學生建立正確的數位生活觀念？三、公共衛生與心理輔導支持：衛生局在面對網路成癮問題時，提供了哪些公共衛生服務和心理輔導支持？四、家庭與社區的參與：教育處與衛生局如何促進家庭和社區對於解決學童和青少年網路成癮問題的參與？五、專業輔導、治療與康復服務：目前花蓮縣是否有足夠的專業輔導、治療與康復服務來支持面對網路成癮的學童和青少年？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=982','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:983:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "教育處", "doc_type": "書面質詢", "no_date": true, "page": 983, "session": "第20屆第2次定期大會", "term": 20, "title": "關於花蓮縣學童與青少年網路成癮問題～"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=983','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:986:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "衛生局", "doc_type": "書面質詢", "no_date": true, "page": 986, "session": "第20屆第2次定期大會", "term": 20, "title": "關於花蓮縣長照 2.0 計畫服務品質～隨著我國人口結構的變化，高齡化社會的到來，長期照護服務的重要性日益凸顯。花蓮縣作為一個具有高比例老年人口的地區，對於長照服務的需求尤為迫切。政府自 106 年推出長照 2.0 計畫以來，對於長照服務的投入持續增加，從初期的 50 億元增至超過 600 億元，展現了政府對此議題的重視。然而，隨著長照機構的快速增加，公眾對於服務品質的關切也隨之增強。作為民眾選舉的代表，本席有責任確保政府投入的資源能夠有效地用於提高長者的生活品質。因此，就教衛生局：一、長照機構的監管標準：請問花蓮縣衛生局目前針對長照機構有哪些質量監管的標準和機制？這些標準和機制是否進行定期的評估和更新？二、資源分配的效益評估：面對龐大的長照預算，衛生局如何評估這些資源分配的效果？是否有具體指標來衡量投入與產出的關聯？三、服務質量的改善措施：對於存在服務品質問題的長照機構，衛生局有何改善計畫或介入措施？如何確保長者獲得應有的照顧質量？四、業者與政府的互動：目前長照業者對於衛生局提供的支援和輔導評價如何？是否有進行定期的滿意度調查？五、未來規劃：面對日益增長的長照需求，衛生局未來有何新的規劃或策略，以確保長照服務的持續提升和發展？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=986','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:989:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "教育處", "doc_type": "書面質詢", "no_date": true, "page": 989, "session": "第20屆第2次定期大會", "term": 20, "title": "關於校園內塑膠玩具（蘿蔔刀、蘿蔔槍）使用問題～本席注意到近期有關於學生在校園內使用塑膠製玩具蘿蔔刀及蘿蔔槍的報導，這些玩具可能對學生的安全與心理健康造成不良影響。本席對於花蓮縣在這一問題上的態度和措施感到關心，因此特此提出以下幾點質詢：一、當前情況了解：請問教育處是否已經注意到類似情況在花蓮縣校園內發生？是否有進行相應的調查或監測？二、安全措施與政策：針對學生在校園內使用可能具有潛在危險性的玩具，教育處有哪些具體的安全措施和政策？三、家長與學校的溝通：教育處是否有計劃加強與家長和學校之間的溝通，共同提高對此類玩具潛在風險的認識？四、教育與指導：對於學生使用這類玩具的行為，教育處是否有提供相應的教育和指導，以幫助學生了解其潛在風險，並培養安全的行為習慣？五、後續監督與評估：教育處計劃如何持續監督和評估相關政策的實施效果，確保學生的安全與健康？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=989','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:991:0:pde739c60c6','pde739c60c6','interpellation','2023-10-30','{"councillors": ["徐子芳"], "dept": "觀光處", "doc_type": "書面質詢", "no_date": true, "page": 991, "session": "第20屆第2次定期大會", "term": 20, "title": "觀光大縣生活成本與收入不匹配問題～對於花蓮縣近年來面臨的經濟與民生問題深感關切。花蓮被譽為天然的度假天堂，但實際上，許多縣民正面臨「偏鄉的收入，都市的高消費」的困境。觀光業作為花蓮的主要經濟來源，在帶動經濟的同時，也導致生活成本的不斷上升，特別是房價和日常開銷。這對本地居民，尤其是年輕一代的生活品質造成了影響，也加重了勞動市場的缺工問題，特別是在服務業。針對此問題：一、生活成本與收入不匹配的調查與分析：請問貴處是否有進行過關於花蓮縣推動觀光發展卻造成本地居民生活成本與收入不匹配問題的調查與分析？目前有哪些具體數據可以說明這一問題的嚴重性？二、觀光發展與民生平衡的策略：面對觀光發展帶來的挑戰，貴處有何策略或措施來平衡觀光發展與保障當地居民的生活品質？三、缺工問題的解決方案：針對服務業勞動力市場的缺工問題，貴處有何具體的解決方案或計劃？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=991','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:843:0:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 843, "session": "第20屆第6次定期大會", "term": 20, "title": "考量本縣協勤民力協勤辛勞及物價波動，建議將年度縣外參訪經費由現行每人 5,300 元調整至 6,500 元，以提振士氣，並請警察局研議於 115 年度預算編列時辦理。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=843','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1023:2:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1023, "session": "第20屆第6次定期大會", "term": 20, "title": "營建廢棄物的土石場目前同意新設 2 場，另外是否還有土資場申請家數？請建設處提供資料。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1023','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1024:0:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "地政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1024, "session": "第20屆第6次定期大會", "term": 20, "title": "一、有關太昌路 170 後巷，民眾配合縣府辦理污水下水道工程申辦土地鑑界，經地所人員測量後，現場鑑界成果有 3 個鑑界樁位不一致之情形。二、民眾需求土地複丈辦理過長，影響民眾權益及建築業者成本增加。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1024','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1024:1:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1024, "session": "第20屆第6次定期大會", "term": 20, "title": "請警方交通執法時，輕微違規能以勸導代替取締。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1024','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1024:2:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1024, "session": "第20屆第6次定期大會", "term": 20, "title": "地方治安座談會已淪為形式，都是熟悉面孔參加，請規劃較為吸引民眾參與方式的舉辦。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1024','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1025:0:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1025, "session": "第20屆第6次定期大會", "term": 20, "title": "立霧溪、木瓜溪河床高度都高於外面農地，像馬太鞍溪如果長時間加強疏濬，災情就不會嚴重，河床高了應該要加強疏濬。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1025','2026-10-07T15:11:39Z');
