INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1026:0:p2b1e47921b','p2b1e47921b','interpellation','2025-10-31','{"councillors": ["鄭乾龍"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1026, "session": "第20屆第6次定期大會", "term": 20, "title": "地方稅務局依據建設處公文（公共設施完竣認定）加收地價稅（溯及前五年），二個單位應該要互相同步資料。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1026','2026-10-07T15:11:39Z');
