INSERT INTO "fact" VALUES('hlccq:20251230114145-135:759:0:p2b1e47921b','p2b1e47921b','interpellation','2025-05-19','{"councillors": ["鄭乾龍"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 759, "session": "第20屆第5次定期大會", "term": 20, "title": "民眾有反映年輕員警執法態度對老人家口氣很強硬，一定要開罰單，如是輕微違規可以勸導，請警察局能要求年輕員警加強執勤態度。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=759','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:870:0:p2b1e47921b','p2b1e47921b','interpellation','2025-05-19','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 870, "session": "第20屆第5次定期大會", "term": 20, "title": "儘速電桿地下化。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=870','2026-10-07T15:11:39Z');
