INSERT INTO "fact" VALUES('hlccq:20251230114145-135:872:1:p2b1e47921b','p2b1e47921b','interpellation','2025-05-19','{"councillors": ["鄭乾龍"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 872, "session": "第20屆第5次定期大會", "term": 20, "title": "吉安慶豐原為土地公廟，後變為城隍爺，有其故事性，請文化局研議是否能開創為一個新的景點？"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=872','2026-10-07T15:11:39Z');
