INSERT INTO "fact" VALUES('hlccq:20250515155455-161:989:2:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 989, "session": "第20屆第4次定期大會", "term": 20, "title": "文化局室內活動已夠多，應多辦理室外活動，如戶外電影院，讓民眾參與，相關文化活動在壽豐、鳳林、光復及豐濱等區域，一年至少辦理一場戶外活動，並加強宣導廣告，讓民眾走到室外，凝聚鄉親的心。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=989','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:990:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 990, "session": "第20屆第4次定期大會", "term": 20, "title": "振興券發放目的？"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=990','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:991:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 991, "session": "第20屆第4次定期大會", "term": 20, "title": "建議於木瓜溪、花蓮溪出海口辦理水上活動。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=991','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:991:1:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 991, "session": "第20屆第4次定期大會", "term": 20, "title": "農民受災反映公所勘查，經常回覆會再去看，但實際現勘時間拖的較久，導致損災現況與之前提報時有所差異，也影響農民復耕。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=991','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:992:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 992, "session": "第20屆第4次定期大會", "term": 20, "title": "七星潭、化仁海堤流浪犬數量過多，收容所收容量能不足，絕育後回置不能解決流浪犬追車追人問題。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=992','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:993:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 993, "session": "第20屆第4次定期大會", "term": 20, "title": "一、屠宰場土地已撥用，請清查目前使用的土地中是否還有國有地？二、肉品市場土地周邊環境等問題，未來應投入一定金額，積極改善建築物、設備等，另請內外一併規劃（容納外面有需要的如殺雞殺鴨）。三、環境衛生不佳的情形是否有定期去稽查屠宰場之環境衛生？"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=993','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:993:1:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 993, "session": "第20屆第4次定期大會", "term": 20, "title": "花蓮果菜批發市場拍賣場擴建工程，縣府請建築師評估結果為何？維管建議請提供大會參考。監察院糾正案後，縣府對後續辦理規劃為何？"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=993','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:994:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 994, "session": "第20屆第4次定期大會", "term": 20, "title": "本縣轄內許多學校學生人數少於 50 人，惟因涉及原住民相關法規無法併校，導致學生競爭力不足，且經費運用無法發揮最大效益。請教育處針對小校合併問題進行研議並做說明。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=994','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:994:1:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 994, "session": "第20屆第4次定期大會", "term": 20, "title": "後續會推出甚麼新的景點或活動？"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=994','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:995:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "客家事務處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 995, "session": "第20屆第4次定期大會", "term": 20, "title": "一、客家傳統精神及由來需要傳承，可以在各項活動、或是教育教學中來推廣及宣揚。二、吉安五榖宮為客家信仰中心，近幾年投入哪些客家資源？三、伯公遍路調查計畫建議將慶豐市場的土地公廟納入，可推廣其晉升城隍爺之故事及觀光行銷。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=995','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:996:0:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 996, "session": "第20屆第4次定期大會", "term": 20, "title": "處理燜燒面臨挖與不挖兩難問題，還是要研議如何處理。花蓮境內還有多少類似露天儲存堆積木屑、木頭、塑膠的廠商，要主動去巡查規範勸導，不容許再有第二家廠商發生這一種事故，以台翔案件作為教材。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=996','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20250515155455-161:1084:1:p2b1e47921b','p2b1e47921b','interpellation','2024-10-17','{"councillors": ["鄭乾龍"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1084, "session": "第20屆第4次定期大會", "term": 20, "title": "每年臨近春節時，常有宵小盜採農民種植的高價農產品。請警察局長督促各分局落實「護農專案」，在農產品收成期間加強夜間巡邏，務求減少農民的損失。"}','https://www.hlcc.gov.tw/upfile/20250515155455-161.pdf#page=1084','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:815:1:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 815, "session": "第20屆第3次定期大會", "term": 20, "title": "市立殯儀館空間不足，建議於北區閒置空間規劃殯儀館二館。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=815','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:816:0:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 816, "session": "第20屆第3次定期大會", "term": 20, "title": "建議花蓮縣政府應參考其他縣市的大型宗教活動，研議辦理相關大型宗教活動。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=816','2026-10-07T15:11:39Z');
