INSERT INTO "fact" VALUES('hlccq:20241226155839-140:816:2:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 816, "session": "第20屆第3次定期大會", "term": 20, "title": "戶政事務所洽公要便民，等待民眾多時，可否適時調整人力，減少民眾等待時間？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=816','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:816:3:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 816, "session": "第20屆第3次定期大會", "term": 20, "title": "一、簡報內呈現土石開採一年大概 100 多公噸，為縣庫注人 5,000 多萬結餘，花蓮河川非常多河床都高過土堤，建議加強疏濬，避免強降雨沖毀土堤造成民地流失。二、業者反映，開採土石運輸人力及成品太高，規費再跟業者研究一下，希望可以降低成本。三、砂石業者底泥砂泥不能做一般用途，不能拿到農田回填，也不能供建築使用，只能落到事業廢棄物，建議跨局處研議開採完之底泥如何去化。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=816','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:817:0:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "財政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 817, "session": "第20屆第3次定期大會", "term": 20, "title": "有關 0403 震災，應研議辦理縣有基地租金減免事宜。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=817','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:817:1:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 817, "session": "第20屆第3次定期大會", "term": 20, "title": "一、0403 紅、黃單建物，紅單戶由縣府拆除，經費由縣府負擔，土方及廢棄物送往國福暫置，民眾自行拆除者，是否也可以統一將土方及廢棄物送往國福暫置？二、自行拆除的補助金額過低。三、0403 後，許多集合式住宅沒立即危險的會辦理補強，但將來再碰到強震時，是否可承受？四、拆除的大樓都會重建，缺工缺料情形嚴重，建照的期限是否可延長 2年？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=817','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:818:0:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 818, "session": "第20屆第3次定期大會", "term": 20, "title": "紅黃單拆除補助 30 萬元的部分，僱工拆除也許夠、也許不夠，拆除下來的營建土方，是進到國福土資場，還是民間的土資場？國福土資場是沒有收費，民間的土資場有分 B2 類及 B5 類，營建廢棄物需要分類會收取費用 1公斤 8 元或 10 元，對屋主是個沉重負擔，這部分是不是縣府也可以負擔？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=818','2026-10-07T15:11:39Z');
