INSERT INTO "fact" VALUES('hlccq:20241226155839-140:821:0:p2b1e47921b','p2b1e47921b','interpellation','2024-05-06','{"councillors": ["鄭乾龍"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 821, "session": "第20屆第3次定期大會", "term": 20, "title": "有關民間單位申請興辦事業計畫，從登記到完成動輒耗時三、五年，審查流程應簡化、公平化，並以法規範為主。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=821','2026-10-07T15:11:39Z');
