INSERT INTO "fact" VALUES('hlccq:20240830153621-166:846:1:p2b1e47921b','p2b1e47921b','interpellation','2023-10-30','{"councillors": ["鄭乾龍"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 846, "session": "第20屆第2次定期大會", "term": 20, "title": "10 月 24 日農產運銷公司現勘，器具老舊，不管縣或中央補助，已達 1 億多元，是否可爭取經費，把外面的業者都容納進來，這樣比較完善，不然花再多錢都不會完善。前幾天看到的斃死豬處理廠，也是閒置在那，斃死豬可以處理 100 多隻，我們的屠宰場還是閒置在那，把外面的屠宰場養雞場規劃進來，比較完善，縣民也食得安心。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=846','2026-10-07T15:11:39Z');
