INSERT INTO "fact" VALUES('hlccq:20260922155504-147:995:1:p94f5630fc0','p94f5630fc0','interpellation','2025-10-31','{"councillors": ["鍾素政"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 995, "session": "第20屆第6次定期大會", "term": 20, "title": "一、如何讓光復鄉民眾有更方便的就醫路程？花蓮縣南區有三大醫院，當有民眾有醫療需求時，需要轉送花蓮慈濟醫院或是門諾醫院，當光復鄉便道無法行駛時，如何讓救護順利通行？或是當 193 縣道路況崎嶇，常導致送醫時間增加，影響病患生命安全，是否有與醫院急診醫師或醫療討論目前交通因素如何因應？二、對於緊急醫療措施，如何讓位於中區的鳳林榮民醫院增加緊急醫療急救站？或是如何加強醫師與醫療之重要性？或是協助與協調？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=995','2026-10-07T15:11:39Z');
