INSERT INTO "fact" VALUES('hlccq:20251230114145-135:955:0:p94f5630fc0','p94f5630fc0','interpellation','2025-05-19','{"councillors": ["鍾素政"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 955, "session": "第20屆第5次定期大會", "term": 20, "title": "工作報告第 14 頁，鼓勵長者參與志願服務方案，本席從事志願服務已有 29年，現在有看到長者從事志願服務工作瓶頸，當初從沒有保險到有保險，有的長者從 40～50 歲就開始服務，服務到現在也有 70～80 歲，但是因保險年齡受限，是否有考量高齡志工保險部分或有其他保障？檢視所有單位志工加保情況，或有其他加強保障部分，可以請社會處整合。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=955','2026-10-07T15:11:39Z');
