INSERT INTO "fact" VALUES('hlccq:20240830153621-166:862:1:p94f5630fc0','p94f5630fc0','interpellation','2023-10-30','{"councillors": ["鍾素政"], "dept": "客家事務處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 862, "session": "第20屆第2次定期大會", "term": 20, "title": "一、伯公照護站各據點之計畫執行落實面（如文化傳承、家庭客語對話）有無達到？客家處應予以輔導，讓其計畫執行更精進。二、學校客語教育未落實於家庭中。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=862','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:863:0:p94f5630fc0','p94f5630fc0','interpellation','2023-10-30','{"councillors": ["鍾素政"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 863, "session": "第20屆第2次定期大會", "term": 20, "title": "每個議員建議案有沒有沒執行的，提案都去會勘了，是否會給會議紀錄？有時候收得到，有時候收不到。沒收到的情況下，會勘後還沒執行的，可以不可以執行，也要給會議紀錄；可以執行的，讓我們知道進行；不可以執行的，到底案子跑到哪裡去？第一次會勘水保科來了，第二次會勘農工科來了，第三次第九河川局來了，最後不知道提案跑到哪裡去了！趕快找找看，不能執行的，請告訴我。包括所有議員都一樣，提案到哪個階段，要讓我們知道。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=863','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:864:0:p94f5630fc0','p94f5630fc0','interpellation','2023-10-30','{"councillors": ["鍾素政"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 864, "session": "第20屆第2次定期大會", "term": 20, "title": "員警攔停車輛注意攔停位置，避免後方車輛反應不及，請加強教育訓練。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=864','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:864:1:p94f5630fc0','p94f5630fc0','interpellation','2023-10-30','{"councillors": ["鍾素政"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 864, "session": "第20屆第2次定期大會", "term": 20, "title": "手持或移動測速照相，勿在轉彎處，以免駕駛突然煞車發生危險；另測速要明顯告示，警車勿隱藏，以免造成觀感不佳。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=864','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:854:0:p48561646c9','p48561646c9','interpellation','2025-10-31','{"councillors": ["傅國淵", "林正福", "林源富"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 854, "session": "第20屆第6次定期大會", "term": 20, "title": "帶狀疱疹病毒疫苗接種率已達 98.4%，民眾需要 65 歲以上可以免費接種，現在財劃法通過後，建議是否可降低補助年齡及增加疫苗採購數量？帶狀疱疹 114 年採購 6,000 劑，使用率已達 98.4%，可看出仍有很大的需求量，是否可增加採購數量至 8,000 劑？若打得好，可增加至 1 萬劑。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=854','2026-10-07T15:11:39Z');
