INSERT INTO "fact" VALUES('hlccq:20241226155839-140:746:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 746, "session": "第20屆第3次定期大會", "term": 20, "title": "一、敬老愛心計程車開始實施至今，一開始僅由三大車行營運導致車輛數不足，目前已經在 5 月 2 日做了教育訓練補強，那如果當天有事請假無法參加訓練，是否就無法參與本計畫提供服務？二、敬老愛心計程車裝設刷卡機設備業務須透過三大車行平台才完成，但幾家車行的系統都有根據車資抽取相關費用且比例不一，如果系統建置及裝機的部分由縣政府主導的話，是否能減輕駕駛經濟負擔？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=746','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:747:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 747, "session": "第20屆第3次定期大會", "term": 20, "title": "馥邑京華一開始已貼紅單，經過二次地震以後，最少六名結構技師看過，都認為要強制拆除，但縣府要住戶自行拆除。建築物的拆除認定要公平，這關係到民眾的財產，被判定為危險建築物，縣府應承擔責任協助拆除。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=747','2026-10-07T15:11:39Z');
