INSERT INTO "fact" VALUES('hlccq:20241226155839-140:748:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "教育處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 748, "session": "第20屆第3次定期大會", "term": 20, "title": "辦理無動力飛行運動業申請經營許可，不能只是審查書面資料，地點是否適合飛行也很重要，須請專家學者評估或現場會勘。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=748','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:749:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 749, "session": "第20屆第3次定期大會", "term": 20, "title": "0403 災害補助，過去針對農產品補助（2.9 提高 4.3 元），蘇花斷了，所有的運輸都往南走，運輸時間和車程都增加，無形都增加了農產品成本，運輸業者也快撐不住，每公斤 6.9 元，農業處未來要怎麼因應？請完成書面報告，讓我們了解怎麼解決農民的問題。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=749','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:749:1:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 749, "session": "第20屆第3次定期大會", "term": 20, "title": "花蓮漁港是否規劃浮動碼頭？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=749','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:750:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 750, "session": "第20屆第3次定期大會", "term": 20, "title": "5 月 3 日至 5 月 5 日西門站展售會效果很好，觀光處是否有規劃下一波，不只有伴手禮還有很多商家，是否一併列入輔導當中？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=750','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:751:1:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "政風處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 751, "session": "第20屆第3次定期大會", "term": 20, "title": "政風處對於採購查核缺失、民眾陳情及追究行政責任等案件，是否得提供相關資料？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=751','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:753:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 753, "session": "第20屆第3次定期大會", "term": 20, "title": "基層員警開巡邏車執勤時，免不了發生交通事故，同仁因擔心遭受處分，遇到車禍可能會因為不敢往上陳報而自行負擔維條費用，造成負擔。員警努力工作維持治安，發生交通事故懲處時應以肇因來做判定，而維修、理賠應由保險公司來處理，不應該同仁自行負擔費用，請上級長官多加支持，會後請提供書面報告。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=753','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:754:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 754, "session": "第20屆第3次定期大會", "term": 20, "title": "因應八堵派出所駐地遭衝撞，駐地安維在警政署初步規劃為防撞桿，員警在第一線執勤安全，如警察局無法在今年編列預算，警察局如何因應？可否由花蓮縣政府規劃預算施作？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=754','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:755:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 755, "session": "第20屆第3次定期大會", "term": 20, "title": "有關於本次 0403 大地震無法即刻辨識追蹤太魯閣進出車輛，造成搜救辨識的難度，建議警察局於太魯閣閣口進入砂卡礑洞內車輛交會處及天祥等路段加裝車牌辨識系統，發生同樣事故時有利追查車輛是否受困或安全離開太魯閣內，讓觀光民眾加一層安全保障，也讓搜救人員能第一時間知道車輛是否安全進出太魯閣。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=755','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:755:1:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "花蓮縣消防局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 755, "session": "第20屆第3次定期大會", "term": 20, "title": "0403 地震東華大學校舍火災 1 案，因當時不確定化學物質為何，故採取侷限火勢。未來請局長儘速採購乾粉式的消防車並加強瞭解危險物品儲存量、管控作為。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=755','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:756:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 756, "session": "第20屆第3次定期大會", "term": 20, "title": "鳳林鎮醫療焚化爐三十年有餘，設備已老舊，雖目前還屬堪用，但有發現溫度不夠，是否向中央爭取經費汰換，再以 BOT 或 ROT 方式處理？該如何協助經費？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=756','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:757:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 757, "session": "第20屆第3次定期大會", "term": 20, "title": "因蘇花公路聯外道路中斷，再生資源利用中心每天都可以幫忙去化生活垃圾，現在啟動各區域進行掩埋，本縣掩埋場餘裕量將近飽和，是否可以提供協調台鐵公司每日運輸的垃圾量數據？尤其是目前暫置垃圾量和處理量，請饒副局長會後提供請台鐵公司運輸量及中區區域性垃圾衛生掩埋場掩埋量。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=757','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:758:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 758, "session": "第20屆第3次定期大會", "term": 20, "title": "一、縣轄內 22 家毒性及關注化學物質存放場所，請提供 22 家名單及地點予各區域議員參考。二、紙漿廠囤積大量危險物質及毒性物質，地震後是否有去稽查，或是否有可以加強的地方，以避免發生災害？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=758','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:759:0:p48561646c9','p48561646c9','interpellation','2024-05-06','{"councillors": ["傅國淵"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 759, "session": "第20屆第3次定期大會", "term": 20, "title": "環保局垃圾清運招標一案，去年 12 月 18 日下午 5 點半開標，因是評審最有利標按照規定即使只有一家廠商環保局按規定必須開標，結果環保局竟然叫廠商拿回未開標之標單，說延後 3 天開標，要更改公告，更改公告時間為 12 月 19 日，這不是相當詭異嗎？環保局要更改公告不是要先停止公告後，再另行招標時間嗎，當然最後 12 月 21 日有兩家投入評審，結果就讓大家去想。請政風處去調查是否有違反採購法？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=759','2026-10-07T15:11:39Z');
