INSERT INTO "fact" VALUES('hlccq:20260922155504-147:855:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹", "林源富", "楊華美"], "dept": "花蓮縣衛生局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 855, "session": "第20屆第6次定期大會", "term": 20, "title": "一、本縣各項疫苗接種率不佳，是否可提高各項疫苗接種率？二、新冠疫苗長者施打率僅 12.1%（全國 16.3%），現行新冠病毒仍於社區流行中，是否有提高疫苗接種率措施？三、本縣長者肺炎鏈球菌疫苗兩劑接種率未達三成，是否可有效提高接種率，達到至少可五成，以減少長者感染風險？另外長者接種完兩劑後是否需要再補種？平均多久需要再打一次？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=855','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:856:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["蔡依靜", "林則葹"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 856, "session": "第20屆第6次定期大會", "term": 20, "title": "一、農地部分沒有取得保留地的部分中，農地受損的部分，其實都有地段地號可以調出申請人、土地所有權人，是否可以主動提供資訊給這些受災戶，主動寄相關資料給對方，看看用什麼方式讓這樣的申請可以更簡便？（蔡依靜議員）二、樺加沙颱風的部分，農業部的定點服務站有在光豐地區農會跟農糧署東區分署兩個地方。農業處在光復有一站式服務，因為鳳林的受災戶也很多，農業處這邊有沒有更積極的作法？另外，農業部提供了許多農業補助，農業處還可以協助什麼更積極的做法，讓農民可以更了解，可以與當地農會、公所做更積極的服務？（林則葹議員）"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=856','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1000:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "花蓮縣警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1000, "session": "第20屆第6次定期大會", "term": 20, "title": "救災期間，議員車輛因 193 線管制無法進入災區，並被要求北返，但同時段立法委員車輛卻可進入，請說明管制作業及標準？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1000','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1001:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1001, "session": "第20屆第6次定期大會", "term": 20, "title": "農產業保險的部分，像是西瓜也有在保險項目裡面，但保險的農民人數似乎非常少，農業處是否有去了解西瓜的農民為什麼不去投保？是否可以向中央反映農民的需求，讓中央去調整？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1001','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1002:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1002, "session": "第20屆第6次定期大會", "term": 20, "title": "農業保險有納入豬隻，那畜牧場養牛或羊是否也有像豬隻一樣的保險？農業處是否可以輔導他們有類似的保險？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1002','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1003:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1003, "session": "第20屆第6次定期大會", "term": 20, "title": "花蓮災害發生率頻繁，是否建請社會處與民政處及各地方鄉公所主動合作，調查盤點在地長者機構，或者住家中行動不便、無法自行撤離者？我們應該要握有充足的資訊，以預防及因應往後撒離時，可主動優先協助將這些長者撤離。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1003','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1003:1:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1003, "session": "第20屆第6次定期大會", "term": 20, "title": "有關災害預防及應變清查機構及社區中長者行動不便的名單或與民政處合作完成調查。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1003','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1004:0:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1004, "session": "第20屆第6次定期大會", "term": 20, "title": "針對 65 歲長者健保費補助，請問補助細節，是否有條件限制？或是如修正法規發布主旨，只要年滿 65 歲長者，即有受補助之福利資格？在此有無個人或撫養人的綜合所得稅率未達 20% 或 5% 等條件的設定，又或者是至少必須設籍花蓮多久之資格？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1004','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1004:1:p759731e3c0','p759731e3c0','interpellation','2025-10-31','{"councillors": ["林則葹"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1004, "session": "第20屆第6次定期大會", "term": 20, "title": "簡報中這 3 條溪流的疏濬量是怎麼訂的？0403 之後土石鬆動，疏濬量是否有考慮這些條件去擬定疏濬量？疏濬量是否要檢討調整？有些溪流很多年都沒有疏濬，萬一這些溪流有堰塞湖，是否容易發生洪災？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1004','2026-10-07T15:11:39Z');
