INSERT INTO "fact" VALUES('hlccq:20251230114145-135:1017:1:p759731e3c0','p759731e3c0','interpellation','2025-05-19','{"councillors": ["林則葹"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1017, "session": "第20屆第5次定期大會", "term": 20, "title": "一、台翔二廠針對再利用管理辦法第 14 條內廢棄物送往再利用機構之進料等紀錄。二、台翔二廠之設備及再利用產品之生產方法。三、台翔二廠 CCTV 及溫度檢測之精進作為。四、針對台翔興廢棄物管理及稽查概況。五、悶燒事件後前後 1 個月之氣象、風向、風速跟濕度的數據比較分析。六、台翔二廠發生火警後提出的悶燒廢棄物緊急應變處置計畫書及去化計畫。七、台翔二廠水汙染防治作為。八、台翔二廠收受廢棄物之來源、檢測狀況及去化管道。（環團）九、CCTV 架設位置及溫度檢測區域。（環團）十、台翔二廠汙水排放管制及空氣汙染管制作為。（環團）十一、針對本專案之風險管理及風險告知之作為。（環團）"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=1017','2026-10-07T15:11:39Z');
