INSERT INTO "fact" VALUES('hlccq:20241226155839-140:782:1:p759731e3c0','p759731e3c0','interpellation','2024-05-06','{"councillors": ["林則葹"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 782, "session": "第20屆第3次定期大會", "term": 20, "title": "地方創生協助各公所提計畫也提供建議修正，建議花東基金方面也能主動協助公所提案管道，因為公所在經驗、人力能量不足，應該予以主動協助，使其計畫更完善，符合在地發展。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=782','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:782:2:p759731e3c0','p759731e3c0','interpellation','2024-05-06','{"councillors": ["林則葹"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 782, "session": "第20屆第3次定期大會", "term": 20, "title": "本次鳳林、壽豐西瓜的災情，提醒農業處這過程可改善，我這邊安排 5/2 會勘，縣府 4/30 安排勘查，是否能站在農民立場想，可把會勘資訊透露給議員，我們也會配合時間，才不會讓農民一直去面對，會勘過程請調整思考。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=782','2026-10-07T15:11:39Z');
