INSERT INTO "fact" VALUES('hlccq:20241226155839-140:834:0:p1c64cd8d07','p1c64cd8d07','interpellation','2024-05-06','{"councillors": ["黃玲蘭"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 834, "session": "第20屆第3次定期大會", "term": 20, "title": "一、113 年 1 月的里長聯誼會反映，焚燒稻草有組專案，去的農民超過 120位，謝謝消防局、農業處到場聆聽。農民還是關心是否可以焚燒稻草，臺東縣政府是依據專案同意農民焚燒稻草，希望 6 月定期會結束可以同意，焚燒稻草可以當有機肥，反映農民聲音（玉里稻田8千多公頃）。二、西瓜的產量價格，也謝謝處長和縣長在第一時間去關心，南區芒果有開花無結果，一千棵的夏雪芒果無產量，這部分農業處請妥處。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=834','2026-10-07T15:11:39Z');
