INSERT INTO "fact" VALUES('hlccq:20241226155839-140:774:0:pf662504649','pf662504649','interpellation','2024-05-06','{"councillors": ["鄭寶秀"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 774, "session": "第20屆第3次定期大會", "term": 20, "title": "一、回饋金比例 80% 回饋給和平村、10% 回饋給崇德村、10% 回饋給環保局，請問給環保局的 10% 是指回饋給各鄉鎮嗎？二、回饋金比例是否全部回饋到秀林鄉，是否不要寫緊鄰，直接寫秀林鄉？否則澳花村及新城村是否也能申請？三、目前回饋金自治條例還沒有通過，那到目前為止的回饋金怎麼計算？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=774','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:978:0:pf662504649','pf662504649','interpellation','2024-05-06','{"councillors": ["楊華美", "傅國淵", "張美慧", "鄭寶秀", "韓林梅"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 978, "session": "第20屆第3次定期大會", "term": 20, "title": "一、個人計程車加入需透過工會推薦，目前 80 個個人行加入，判斷數量還是不足，花蓮幅員狹長，敬老愛心計程車量能的長期規劃為何？二、敬老愛心計程車－個人行何時可以加入營運？解決長者叫不到車的窘境，社會處是否有去了解及處理？請向大會報告，敬老愛心計程車配套措施要再加強。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=978','2026-10-07T15:11:39Z');
