INSERT INTO "fact" VALUES('hlccq:20240830153621-166:795:0:pf662504649','pf662504649','interpellation','2023-10-30','{"councillors": ["鄭寶秀"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 795, "session": "第20屆第2次定期大會", "term": 20, "title": "有關新城鄉大漢段 879、880 土地放置定置漁場竹筏及大型漁網等物件事宜：因定置漁場業者作業需求及作業方式，須採搶攤載運漁獲為主，故須於靠近該漁場旁將竹筏及作業繩索暫置於該處，並於該處有整補漁網具之需求。定置業者並非占用及獨占該處使用，實有作業及整補漁網具之需求，請花蓮縣政府能夠協助替漁民發聲。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=795','2026-10-07T15:11:39Z');
