INSERT INTO "fact" VALUES('hlccq:20241226155839-140:583:0:p6efd903822','p6efd903822','interpellation','2024-05-06','{"councillors": ["徐雪玉"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 583, "session": "第20屆第3次定期大會", "term": 20, "title": "193 線 42K＋200 的部分，上個月有跟縣長勘查，地基嚴重塌陷已有進行搶修。還有共和村的二號橋和三號橋能夠儘速搶修完成，讓門諾分院跟理想大地都能順利的通行，謝謝縣府團隊。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=583','2026-10-07T15:11:39Z');
