INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1235:0:pdb287922cd','pdb287922cd','interpellation','2025-10-31','{"councillors": ["金淑敏"], "dept": "建設處", "doc_type": "書面質詢", "no_date": true, "page": 1235, "session": "第20屆第6次定期大會", "term": 20, "title": "為關切災後復建工程進度，維護偏鄉用路權益、維繫部落地方各項產業發展，請說明花蓮縣南區道路、邊坡、排水復建相關執行進度。質詢內容：一、花 73 線卓富大橋引道風災復建工程，進度時而間斷，難免遭受指責，本席屢次協助勸進台電與施工單位緊密配合，鄉親熱切期待加強施工進度。二、花 75 線石平段 16.5K 邊坡風災復建工程，恐受 7 月薇帕、9 月樺加沙颱風影響 、 工程進度稍緩 ， 施工進度人員應惕勵加強 ， 2026 年初是否完工？進度為何？三、花 73 線 0K+800「康芮」、1K+180、1K+550、1K+520 處，災後復建，各段施工期程不一，工程完竣預計時間？四、卓溪鄉往中興部落聯絡道康芮風災復建預計工程完竣日期？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1235','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1236:0:pdb287922cd','pdb287922cd','interpellation','2025-10-31','{"councillors": ["金淑敏"], "dept": "建設處", "doc_type": "書面質詢", "no_date": true, "page": 1236, "session": "第20屆第6次定期大會", "term": 20, "title": "為關切災後復建工程進度，維護偏鄉用路權益、維繫部落地方各項產業發展，請說明花蓮縣南區道路、邊坡、排水復建相關執行進度情形。請問：卓溪鄉古風排水康芮風災復建工程，9 月開工，預計工程完竣時間？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1236','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20251230114145-135:778:0:pdb287922cd','pdb287922cd','interpellation','2025-05-19','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 778, "session": "第20屆第5次定期大會", "term": 20, "title": "卓溪鄉中正部落發生黑熊活動接近工寮、水田，吃掉雞隻與咬傷犬隻等情形，相關單位應有積極及妥適的機制與作為，請提出處理對策。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=778','2026-10-07T15:11:39Z');
