INSERT INTO "fact" VALUES('hlccq:20251230114145-135:961:0:pdb287922cd','pdb287922cd','interpellation','2025-05-19','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 961, "session": "第20屆第5次定期大會", "term": 20, "title": "一、請提供～113 年 12 月 11 日府農工字第 1130248490 號函案 ， 核定補助辦理搶險救災工作，辦理該工程完竣後應檢具之請款資料及驗收、決算等（應檢核之書件）含施工座落位置明細。二、113 年 12 月 25 日會同農業處、原民處位於卓溪橋右前－卓溪中正部落天主教會前聯絡道路及野溪遭土石掩埋，當時兩處皆確認該筆災修補助款為該段清淤土石支用，惟迄今該河段溪溝仍佈滿土石，尾段排水仍推置土石，鄉親難除疑竇並有安全後患，令人不解。"}','https://www.hlcc.gov.tw/upfile/20251230114145-135.pdf#page=961','2026-10-07T15:11:39Z');
