INSERT INTO "fact" VALUES('hlccq:20241226155839-140:938:1:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 938, "session": "第20屆第3次定期大會", "term": 20, "title": "詳列卓溪鄉境內復建工程項下上級核撥金額及工程進度。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=938','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:940:0:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 940, "session": "第20屆第3次定期大會", "term": 20, "title": "花蓮縣南區自 0918 震災後，旋即颱風侵襲接踵，遭受災損甚鉅，惟經地方至中央各級關切、積極反映爭取修建重建經費核定到位，使橋梁重建工程亦或農路道路受災設施如火如荼進行重建修復中。盱衡南區原住民鄉鎮受害基層待修基地，係屬不穩定坡段，修復工程經費雖經核定，仍礙諸多考量、鄉親子民殷殷期待及關切，建請詳列卓溪鄉境、復建工程項下上級核撥金額及工程進度：卓溪中正部落庄業道路海葵風災復建工程？崙山立山村往水源頭農路杜蘇芮風災復建工程？卓溪往賽谷過水路面杜蘇芮風災復建工程？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=940','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:941:0:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 941, "session": "第20屆第3次定期大會", "term": 20, "title": "南區 0918 地震以後的農路工程是否都完成？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=941','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:946:0:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 946, "session": "第20屆第3次定期大會", "term": 20, "title": "花蓮南區自 0918 震災後，旋即颱風侵襲接踵，受災損甚鉅，惟經地方至中央各級關切、積極反映爭取修建重建經費核定到位，使橋樑重建工程或農路道路受災設施如火如荼進行重建修復中，盱衡南區原民鄉鎮受害基層待修基地，係屬不穩定坡段，修復工程經費雖經核定，仍礙諸多考量、鄉親子民殷殷期待及關切 ， 建請詳列卓溪鄉境 、 復建工程項下上級核撥金額及工程進度：一、1.清水部落簡易自來水海葵風災復建工程 2.卓溪鄉民代表會重建工程3.花 73.75 線復建工程 4.卓溪鄉中正部落產業道路海葵風災復建工程5.卓溪太平及清水部落海葵風災復建工程 6.崙山立山村往水源頭落路杜蘇芮風災復建工程 7.花 68 線杜蘇芮風災復建工程 8.卓溪往賽谷過水路面杜蘇芮風災復建工程 9.花 73 線道路下邊坡及排洪涵管海葵風災復建工程 10.石平 16.6K 坍方復建工程。二、玉里鎮東豐坪頂路落後方山坡 0918 震災及排洪復建工程。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=946','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:946:1:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 946, "session": "第20屆第3次定期大會", "term": 20, "title": "0918 地震過後卓清村南安、清水及卓樂部落自來水執行進度為何？清水部落簡易自來水自 0918 地震後至 113 年風災復建工程已挹注 1,158 萬元及鑒井工程，目前水的問題尚未解決，造成部落不便，有關清水部落簡水工程請參考崙山部落簡易自來水之作法，施工前邀請相關專業工程等單位會同勘查，進行了解，以找出解決方法。最近又在清水部落發包有關海葵颱風災害修復工程計 475 萬元，挹注了很多經費，何時才會解決用水問題？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=946','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:948:0:pdb287922cd','pdb287922cd','interpellation','2024-05-06','{"councillors": ["金淑敏"], "dept": "環保局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 948, "session": "第20屆第3次定期大會", "term": 20, "title": "卓清村簡易自來水，自地震後水質混濁，可否協助水質檢測？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=948','2026-10-07T15:11:39Z');
