INSERT INTO "fact" VALUES('hlccq:20240830153621-166:963:1:pdb287922cd','pdb287922cd','interpellation','2023-10-30','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 963, "session": "第20屆第2次定期大會", "term": 20, "title": "民眾陳情休耕，今天沒有過，隔天收到公文要再去會勘，播種下去到長大要數日，請好好輔導基層公所運用專業。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=963','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:964:0:pdb287922cd','pdb287922cd','interpellation','2023-10-30','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 964, "session": "第20屆第2次定期大會", "term": 20, "title": "本席將近一年提出很多建議案改善工程，到目前為止只有會勘，沒有下文或公文回覆說怎麼處理，能不能做要告知，面對鄉親很多在詢問甚麼時候可以執行，希望儘快處理，不要一看再看。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=964','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:964:1:pdb287922cd','pdb287922cd','interpellation','2023-10-30','{"councillors": ["金淑敏"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 964, "session": "第20屆第2次定期大會", "term": 20, "title": "卓溪卓樂段十多公頃水田無法灌溉，治理改善水圳也看了，沒有下文，最重要第一次定期會提出玉里東豐里坪頂 0918 治山防洪改善工程，哪一個處或單位要處理，會勘沒有下文，經費已經來了有沒有在做，何時動工？還有富里鄉福岡段農田水圳旁邊，也是看了沒有下文。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=964','2026-10-07T15:11:39Z');
