INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1133:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1133, "session": "第20屆第6次定期大會", "term": 20, "title": "0923 重建的工作，地方中央各部會都有相關，道路、下水道、水利設施等基礎設施是否有提供給中央部分資訊？針對中央協調所之前與現在是否有更新資訊，不要打口水仗。整理出縣府所提供的意見，中央怎麽做、地方怎麼建議、如何用縣預算補足。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1133','2026-10-07T15:11:39Z');
