INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1136:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1136, "session": "第20屆第6次定期大會", "term": 20, "title": "自堰塞湖災情發生後，鄉親突然非常關注每一條河流疏濬問題。民眾開始反應，住家旁邊的溪流整個墊兩層樓高；還反映住家已經是一個溪流的衝撞點，沒有疏濬，已經開始擔心會不會被沖刷，家園是不是土石流也會跟著來。警覺性都非常高，面臨這樣的狀況，中央管河川中央要去處理，縣管河川是不是要疏濬，怎麼疏濬？留在原地嗎？還是疏濬到哪裡去？怎麼解決？事情非常重要，因為堰塞湖事件輕忽這個問題，希望縣團隊能夠保護每一個人民的家園，讓我們生活能夠安居樂業。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1136','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1137:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1137, "session": "第20屆第6次定期大會", "term": 20, "title": "疏濬經費用完後，不足部分還可以再儘快申請來執行嗎？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1137','2026-10-07T15:11:39Z');
