INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1143:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "花蓮縣環境保護局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1143, "session": "第20屆第6次定期大會", "term": 20, "title": "有關南區民眾陳情秀姑巒溪有魚大量死亡：一、環保單位檢測方式是否能代表該河川流域水質？二、若有魚類大量死亡情形，民眾要（請環保局）如何處理？三、若河流如果有遇到大量藻類會造成溶氧變少，導致魚類缺氣而死亡，所以有大量藻類時，環保局會如何處理？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1143','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1144:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1144, "session": "第20屆第6次定期大會", "term": 20, "title": "族語單詞競賽都是團體組，是否可增加個人組，以俾利族語推廣？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1144','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1145:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1145, "session": "第20屆第6次定期大會", "term": 20, "title": "原保地權利回復部分，總案量是多少？能夠來對照目前的績效，可以看得更清楚需要多少年可以完成，包含又他項權利設定尚為轉所有權移轉的案件，我們怎麼要幫助他們？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1145','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1145:1:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1145, "session": "第20屆第6次定期大會", "term": 20, "title": "請原住民行政處提供部落產業與經濟發展之扶植數據。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1145','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1148:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1148, "session": "第20屆第6次定期大會", "term": 20, "title": "本縣受理增劃編原住民保留地申請中案件有多少？是幾千還是幾萬件？還要花多少年的努力才能完成？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1148','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1149:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "主計處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1149, "session": "第20屆第6次定期大會", "term": 20, "title": "一、根據 112 年度的報告，追加減經費在當年度為 28.19 億元，而今年度則為 25.27 億元，這個數據部分應該要再進一步修正，以確保資料正確。請提供本縣歷年中央補助收入情形。二、今年中央在一般性補助款方面是否有苛扣經費？被扣減的部分，中央是否透過計畫型補助款進行回補？有沒有將款項補回來？一般性補助款主要用於教育、社會福利及基本設施經費等項目，這些都是地方施政的核心。按照中央的規定，補助款的編列不得少於前一年度的預算數。為什麼中央政府可以在 114 年度、甚至 115 年度，出現經費減列或不予補助的情形？主計處針對 114 年度與 115 年度補助款的變動情形，以及中央減列或延遲補助的原因，向議會詳細說明。三、針對捐款帳戶，我要嚴正質疑：為何在上次災害中，花蓮縣未即時設立專戶接受社會捐助？這一點必須由縣府明確說明。四、目前整個重建工作幾乎是由中央掌握與主導，許多重建機會與資源的分配來源於中央，但在權責與資訊傳遞上出現混淆，導致地方與中央的責任不清、作為不一，影響重建效率與資訊透明。對此，縣府應提出完整說明：中央與縣府在重建各階段的權責分工為何？縣府如何確保地方民眾的權益與參與？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1149','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1150:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2025-10-31','{"councillors": ["林玉芬"], "dept": "民政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 1150, "session": "第20屆第6次定期大會", "term": 20, "title": "法律諮詢都是固定的律師輪值嗎？還是由法扶輪流派？希望法律諮詢品質能夠關注，希望能夠幫助求救的鄉民。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1150','2026-10-07T15:11:39Z');
