INSERT INTO "fact" VALUES('hlccq:20241226155839-140:920:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 920, "session": "第20屆第3次定期大會", "term": 20, "title": "一、文旦災害補助，農民都知道農業災害的補助，雙方會勘農業部到現在還沒回復，損害 30-40% 以符合補助，請農業處跟農業部溝通幫忙農民。二、農業處產業保險，縣府提高至 20%，水稻和文旦有多少農民參加、獲得實質補助？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=920','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:921:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "農業處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 921, "session": "第20屆第3次定期大會", "term": 20, "title": "今年文旦柚受天然災害影響，請協助農民不要慌，請農民照顧好柚子，收成時不要讓盤商亂喊價，縣府能做萬全準備的行銷幫助，重啟中國行銷規劃要做好。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=921','2026-10-07T15:11:39Z');
