INSERT INTO "fact" VALUES('hlccq:20241226155839-140:924:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 924, "session": "第20屆第3次定期大會", "term": 20, "title": "瑞穗鄉掃叭頂及鶺櫓棧部落聚會所興建進度？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=924','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:925:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 925, "session": "第20屆第3次定期大會", "term": 20, "title": "一、今年文健站新增據點有幾處？位於何處？二、先前新增地點都在部落聚會所，在不得已情況下還是會選擇在教會等其他處所，希望地點要優先設置於聚會所。三、有關 113 年度「原住民族長期照顧文化健康站查核計畫」案，以往考核委員考核缺點未詳細列出應改進的事項，無法作為改善依據，考核委員也應該要了解文健站的業務，先前有委員提出經費不足應向部落籌款及部落文健站設施設備不足，為何在該處（聚會所）開站等疑問，文健站開站都經過審核，委員說出這樣的話代表對業務不嫻熟，希望跟原民會建議，指派了解業務的評審委員到場。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=925','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:926:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "客家事務處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 926, "session": "第20屆第3次定期大會", "term": 20, "title": "一、關於工作報告第 14、15 頁，補助辦理客家民俗技藝課程方面，玉里鎮113 年無提出相關課程？請平衡各鄉鎮活動。另活動可多元化方式辦理，並讓不同社團辦理以呈現不同樣貌。二、客語方面，可舉辦客語相關競賽，並分幼兒組、國中小組、社青組、銀髮組等，鄉內比完後換縣比，對客語傳承有很大幫助。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=926','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:926:1:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 926, "session": "第20屆第3次定期大會", "term": 20, "title": "推動智慧城市相關計劃中有關畜牧糞尿沼渣沼液作為農地肥分使用，目前南區有沼澤，因有這計劃民眾也很願意收，免費提供農民肥料使用，因為農民不知道或害怕用了不知會怎樣，請行研處提供相關資訊讓農民知道這樣是可以使用，回收的業務也能正常回到環保議題，有收也有出。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=926','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:927:0:p59f3c4e6f1','p59f3c4e6f1','interpellation','2024-05-06','{"councillors": ["林玉芬"], "dept": "花蓮縣地方稅務局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 927, "session": "第20屆第3次定期大會", "term": 20, "title": "105 年間調漲礦石稅，請調查業者水泥售價有無因此而提高？礦石稅議題應回歸公平正義，如果業者取得成本低，售出價格高，就不符合公平正義。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=927','2026-10-07T15:11:39Z');
