INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1217:0:pc671c2e6f7','pc671c2e6f7','interpellation','2025-10-31','{"councillors": ["吳建志"], "dept": "花蓮縣警察局", "doc_type": "書面質詢", "no_date": true, "page": 1217, "session": "第20屆第6次定期大會", "term": 20, "title": "逃逸外籍移工對臺灣整體產業治安發生重大影響，目前屢傳詐欺集團車手、高利貸放款、地下匯兌、山老鼠（在山上已有固定地盤）、工廠建築黑工等犯罪類型越來多，專勤隊在當地配置人員不足，再加上縣境南北狹長，無法及時掌握資料，逮捕逃逸移工。央請貴局協助，擬定政策方向，維持正面發展。"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1217','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20260922155504-147:1218:0:pc671c2e6f7','pc671c2e6f7','interpellation','2025-10-31','{"councillors": ["吳建志"], "dept": "花蓮縣文化局", "doc_type": "書面質詢", "no_date": true, "page": 1218, "session": "第20屆第6次定期大會", "term": 20, "title": "文化預算分配與執行：文化局今年預算中，哪三項計畫編列最高、執行率最低？原因為何？是否有不當延宕或行政效率問題？"}','https://www.hlcc.gov.tw/upfile/20260922155504-147.pdf#page=1218','2026-10-07T15:11:39Z');
