INSERT INTO "fact" VALUES('hlccq:20241226155839-140:815:0:pc671c2e6f7','pc671c2e6f7','interpellation','2024-05-06','{"councillors": ["吳建志"], "dept": "花蓮縣文化局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 815, "session": "第20屆第3次定期大會", "term": 20, "title": "文化平權、政治與文化的關係。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=815','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:832:0:pc671c2e6f7','pc671c2e6f7','interpellation','2023-10-30','{"councillors": ["吳建志"], "dept": "客家事務處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 832, "session": "第20屆第2次定期大會", "term": 20, "title": "一、如何做出東部當代客家文化特色？應以藝文創新發展為主軸，鼓勵傳統客家智慧融合新世代文化轉譯。二、客家文化工作方面，困難在於年輕族群投入不足，建請客家處著重青年投入，滿足縣長 SDGs 文化永續的期待。三、關於幼年族群培養，除客語語言課程外，應還有文化創新培養，尤其是客家青年培養政策缺乏創意，應對症下藥投入資源，如客家流行音樂、當代客家文學、創意美食、客家當代藝術、客家流行文化產業等，這些領域一條龍輔導的資源，從創意到轉出、從通路到行銷，皆不可缺少。四、請客家處思考每年舉辦客家當代文化創新大賞之可能性，可參採文化局洄瀾美展、花蓮影視獎等評選機制，邀請各類文化創作者發表，透過各類型如客家流行音樂共賞、當代文學走讀、創意美食、當代藝術展演、流行文化等多元呈現，以拉動年輕人參與體驗各項客家文化創意創新的內涵。另請客家處回覆以下四點：五、客家產業交流中心，未來如何吸引更多年輕人投入？指標為何？如何整合產官學資源來推廣花蓮客家文化的永續傳承？六、如何透過政策引導客家社團進行青銀共創活動及課程？七、花蓮縣何時能主辦世界客家博覽會？八、客庄產業創新加值計畫細節說明，另花蓮有無可能成為客庄旅遊示範區？有無鄉村旅遊產業鏈？"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=832','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:834:0:pc671c2e6f7','pc671c2e6f7','interpellation','2023-10-30','{"councillors": ["吳建志"], "dept": "客家事務處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 834, "session": "第20屆第2次定期大會", "term": 20, "title": "在客語深根計畫部分從 8 月 1 日至 8 月 16 日為期 12 天，針對花蓮縣政府客家事務處從老師上課第一天開始至最後一天結束皆派員視察巡查，請就此部分作說明。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=834','2026-10-07T15:11:39Z');
