INSERT INTO "fact" VALUES('hlccq:20241226155839-140:867:2:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 867, "session": "第20屆第3次定期大會", "term": 20, "title": "2024 年聯合豐年節改名為 「太平洋南島聯合豐年節」 的原因和理由是什麼？改名之後的聯合豐年節在辦理的內容和形式上是否也有改變？今年還有南島語族的團體來到現場演出嗎？0403 地震之後，會不會影響觀光客參加的意願？如何因應？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=867','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:868:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 868, "session": "第20屆第3次定期大會", "term": 20, "title": "一、花蓮南區最重要的音樂活動－FaliFali音樂節已經舉辦5年了，今年將在哪裡舉辦？如何辦理？去年有馬達加斯加的歌手加入演唱是一個亮點，今年是否也有亮點？原住民族音樂節在各地都有舉辦，除了花蓮的FaliFali 之外 ， 還又哪些？各自的特色又是什麼？FaliFali 如何展現獨特性與吸引力？二、原民處對於推動原住民族音樂發展的長期規劃是什麼？如何進行？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=868','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:869:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "原住民行政處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 869, "session": "第20屆第3次定期大會", "term": 20, "title": "請原住民行政處提供玉里鎮觀音里達谷寮部落路面改善工程相關資料：一、決標日期、決標金額、得標廠商。二、路面改善工程項目。三、請安排施工前說明會日期，並通知當地民意代表參與，以利部落族人共同關心、表達意見，透過部落鄉親全民督工，以確保工程品質。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=869','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:931:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 931, "session": "第20屆第3次定期大會", "term": 20, "title": "一、請提供從 4 月 3 日強震後到 5 月 3 日一個月間花蓮旅宿業住宿率？二、觀光處有無概估花蓮旅宿業今年從 4 月到年底損失金額？三、請提供太魯閣國家公園 112 年遊客數及估計為花蓮地區帶來多少經濟效益？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=931','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:952:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "社會處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 952, "session": "第20屆第3次定期大會", "term": 20, "title": "盤點縣內公有土地閒置空間，建置南區原鄉親子館。少子化是台灣目前重大問題，儼然成為新國安危機，內政部日前公布 2022年全國人口統計數據，其中花蓮縣新生嬰兒 110 年、111 年均未超過 2,000名，創了 60 年來最低紀錄，如何創造更為友善的托育環境來提高生育率，對花蓮縣政府來說刻不容緩。在孩子成長過程中，家庭扮演重要關鍵角色，哈尼．噶照認為政府首要之務是提供有托育需求的家庭一個近便、專業的社區支持資源，讓孩子在社區有一個安全的活動空間，讓家長也能獲得喘息機會，舒緩照顧兒童的壓力。目前花蓮縣陸續建置花蓮市洄瀾、新秀、吉安、鳳林、玉里及豐濱等 7 處親子館，另外也結合民間單位於瑞穗鄉、萬榮鄉、卓溪鄉設立部落遊戲屋親子據點等，來滿足不同區域與類型之育兒家庭。徐榛蔚縣長在施政總報告中不斷宣示要在全縣打造一鄉鎮市一親子館，營造共學、共玩、共讀空間，建構育兒友善場域，因花蓮縣地幅遼闊，南區原鄉部落育兒資源取得不易，多數原住民鄉鎮尚未完成親子館建置。哈尼．噶照認為每個孩子都是上天給予的禮物，都是父母的寶貝，不能因在原鄉而被遺忘，建議縣府儘速盤點縣內閒置空間及公有土地，規劃設置親子館，縣府需挹注更多經費將親子館等微型福利設施普及化，以完善社會安全福利網絡。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=952','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:953:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 953, "session": "第20屆第3次定期大會", "term": 20, "title": "0403 強震震跑觀光客，花蓮縣觀光業遭受重大打擊，少了太魯閣國家公園，花蓮觀光產業雪上加霜，震後花蓮南區觀光旅遊也是另一個選擇，花蓮觀光振興 4 支箭真能扭轉花蓮觀光困境？整合花蓮南區觀光資源及活動串聯遊程，並加強宣傳。另建議推動花蓮 193 縣道旅遊。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=953','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:955:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 955, "session": "第20屆第3次定期大會", "term": 20, "title": "一、針對花蓮觀光產業發展，因為海路比較安全，在 0403 地震後應可以考慮發展水上路線，重點規劃從基隆、蘇澳到花蓮的藍色公路，沿途風景漂亮必定能吸引國際觀光客，來振興花蓮觀光產業。二、太魯閣線自 113 年 4 月 12 日起，行駛路線暫時調整為花蓮轉運站至太魯閣遊客中心站往返，請縣府觀光處向中央建議滾動式調整太魯閣線改為台灣好行 193 縣道線，以作為南區遊程景點接駁。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=955','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:956:0:p629769c6e4','p629769c6e4','interpellation','2024-05-06','{"councillors": ["哈尼．噶照"], "dept": "觀光處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 956, "session": "第20屆第3次定期大會", "term": 20, "title": "輔導原民部落民宿合法化，促進原鄉觀光發展。"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=956','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20241226155839-140:581:0:p8c3f1f2b68','p8c3f1f2b68','interpellation','2024-05-06','{"councillors": ["張峻"], "dept": "警察局", "doc_type": "口頭質詢答覆", "no_date": true, "page": 581, "session": "第20屆第3次定期大會", "term": 20, "title": "民眾陳情吉安轄區內知卡宣大道，為東西向四線道路，為什有許多大貨車都要申請路權才可以行駛？雖然陳情民眾現開的是砂石車或水泥預拌車，沒超載也沒超速，也都不能行駛，都會被依道交規定被開單，說沒申請路權，如車要北上，都必須行駛海岸路，道路兩旁住戶多，且任何車共用，也要繞一大圈，真不知知卡宣大道是要留給什麼車種行駛？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=581','2026-10-07T15:11:39Z');
INSERT INTO "fact" VALUES('hlccq:20240830153621-166:685:0:p8c3f1f2b68','p8c3f1f2b68','interpellation','2023-10-30','{"councillors": ["張峻"], "dept": "行政暨研考處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 685, "session": "第20屆第2次定期大會", "term": 20, "title": "請縣府提供 111 年至 112 年委託媒體或自辦之各項活動所有對外宣傳、行銷費及縣政宣導等各項金額及得標廠商名稱（若自行辦理宣導亦須填寫）。"}','https://www.hlcc.gov.tw/upfile/20240830153621-166.pdf#page=685','2026-10-07T15:11:39Z');
