INSERT INTO "fact" VALUES('hlccq:20241226155839-140:730:0:p60222eb82f','p60222eb82f','interpellation','2024-05-06','{"councillors": ["謝國榮"], "dept": "建設處", "doc_type": "口頭質詢答覆", "no_date": true, "page": 730, "session": "第20屆第3次定期大會", "term": 20, "title": "紅單建築如無立即危險是否需拆除，營建廢棄土方之費用，一噸的處理費用要 5,000 元，金額不低，是否應將拆除與否之責任釐清，讓紅單民眾確認是否要拆，拆除費用由政府還是民間負擔？拆除建築廢棄物是否由縣內國福土資場一併容納？台泥土資場可以回收 B5 類減少經費支出？"}','https://www.hlcc.gov.tw/upfile/20241226155839-140.pdf#page=730','2026-10-07T15:11:39Z');
