INSERT INTO "fact" VALUES('tttattend:20t:pc81296549c','pc81296549c','attendance','2026-03-23','{"duty": 0, "from_lists": true, "leave": 0, "meetings": 5, "present": 5, "session": "第20屆第20次臨時會", "term": 20, "title": "第20屆第20次臨時會會議紀錄"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/01.pdf#page=160','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:508:1:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "行政處公共園區管理科", "doc_type": "書面質詢", "no_date": true, "page": 508, "session": "第20屆第5次定期會", "term": 20, "title": "鐵花商圈夜間人潮分佈不均，台東市的鐵花商圈是市區夜間觀光的重點區域，週五、六、日人潮旺盛，但週一至週四因微光市集休市與攤位數量減少，夜間顯得冷清。建議縣府考慮於週一至週四期間，採取彈性租金優惠政策，吸引新型態攤商，在地小農、青年創業者或文創業者進駐，活絡平日商圈氣氛，使商圈能達成平假日皆常態營運的目標，提供遊客更多元的夜間消費選擇。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=508','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:508:2:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "原住民族行政處", "doc_type": "書面質詢", "no_date": true, "page": 508, "session": "第20屆第5次定期會", "term": 20, "title": "莿桐部落與杉原海水浴場活動及莿桐部落的海洋學習基地可與每年舉辦的阿美族豐年祭結合，設計年輕人參與常態課程，如造船祭儀學習與文化導覽訓練，並透過活動宣傳提升部落文化能見度與觀光價值。此外考慮到杉原海水浴場頻繁舉辦如東浪嘉年華等大型活動，應同步強化周邊停車設施與交通動線規劃，避免人車壅塞，提升遊客整體體驗。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=508','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:510:3:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處", "doc_type": "書面質詢", "no_date": true, "page": 510, "session": "第20屆第5次定期會", "term": 20, "title": "自然景點導覽系統與原住民文化推廣，台東縣境內自然景觀豐富，但分佈零散，極需統一規劃與系統導覽，建置數位與實體整合的觀光導覽系統，包括互動地圖、旅遊APP、AR擴增實境導覽，並設計主題式旅遊行程〈如原住民文化深度旅遊，農村慢活體驗〉，提升旅遊可讀性與便利性。同時設立常態性的原住民文化館與工藝體驗基地，推廣傳統技藝與生活智慧，透過旅宿品質升級，導覽人才培訓與商品品牌行銷，結合文創與數位平台，將部落經濟擴展具備國際吸引力的深度文化旅遊資源。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=510','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:512:4:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處", "doc_type": "書面質詢", "no_date": true, "page": 512, "session": "第20屆第5次定期會", "term": 20, "title": "活動整合行銷與在地延伸，針對熱氣球嘉年華、阿美族豐年祭等重大節慶活動，應強化整合行銷策略，並結合市集、夜市文化、手作體驗與藝文表演，設計出一系列可延伸停留時間的旅遊產品。透過跨區域串聯(如海線→山線→市區的套票旅遊)與交通接駁配套，鼓勵遊客延長旅程，深入探索在地及部落風貌，提升觀光經濟效益。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=512','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:515:5:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "國際發展及計畫處資訊發展科", "doc_type": "書面質詢", "no_date": true, "page": 515, "session": "第20屆第5次定期會", "term": 20, "title": "各鄉鎮與部落電子美食地圖推廣，建置各鄉鎮各部落可即時更新電子美食地圖，支援手機下載與離線使用，內容包含在地特色料理、部落原住民風味餐、營業時間、交通資訊等。可整合旅遊APP平台作為導遊工具，讓遊客不再為去哪裡吃？吃什麼困擾，也更利於本縣縣民探索更多在地美食資源。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=515','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:515:6:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處", "doc_type": "書面質詢", "no_date": true, "page": 515, "session": "第20屆第5次定期會", "term": 20, "title": "小野柳(富岡地質公園)觀光推廣，富岡地質公園因地質變動與海浪侵蝕，形成壯觀的特殊岩層景觀(如豆腐岩、蜂窩岩、大眼蛙、駱駝石等)具高度教育與觀光價值，建議加強多種語言導覽設施及景點解說，設計文創商品和網絡行銷活動。並與學校及旅遊業者合作規劃主題地質旅遊，擴大觀光效益與知名度。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=515','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:516:7:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處", "doc_type": "書面質詢", "no_date": true, "page": 516, "session": "第20屆第5次定期會", "term": 20, "title": "山線、海線串聯遊程，透過山線→縱谷→海線串聯設計跨鄉鎮部落旅遊行程，如山線(鹿野高台飛行傘、茶園、鸞山會走路的樹、延平紅葉温泉、紅葉棒球村)縱谷(池上、關山農業體驗)南迴(太麻里金針山、金崙温泉、南田阿朗壹古道)海線(都蘭、東河藝術村、成功漁港觀鯨、長濱金剛山、八仙洞)結合公路旅遊，腳踏車路線、鐵道旅遊，增加多樣化體驗。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=516','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:516:8:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處觀光管理科", "doc_type": "書面質詢", "no_date": true, "page": 516, "session": "第20屆第5次定期會", "term": 20, "title": "青年旅客友善設施，提供青年背包客旅店、青年旅遊優惠、文化交流活動(如旅人講座、共餐市集)吸引自由行年輕旅客群。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=516','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:517:9:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 517, "session": "第20屆第5次定期會", "term": 20, "title": "推動地方創生據點，具文化或產業特色的部落及社區（如成功漁村、延平紅葉部落）成立地方創生據點，提供共創空間，社區及部落導覽與課程，讓旅客體驗深度交流及文化學習，更可讓部落和社區居民參與觀光規劃與收益分享。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=517','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:532:10:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "交通及觀光發展處", "doc_type": "書面質詢", "no_date": true, "page": 532, "session": "第20屆第5次定期會", "term": 20, "title": "台東舊站及鐵花商圈，現在正全面規劃與建設帶給台東舊車站新的面貌及展望，當然有建設就有破壞，以及帶給周邊商家和居民的不便。尤其在交通方面，常因施工而交通管制，如此一來造成行的不便及停車困難的問題，甚至影響商家的營業。如南京路→桂林路→新生路→中華路→博愛路→更生路，這些路段都因施工而管制，尤其在秀泰影城原有計程車停車格往中華路方向劃設，造成前往附近商家消費辦事的民眾無法停車。建議縣府重新檢討劃設計程車臨時停車格之位置，改善附近商家停車問題。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=532','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:05-04:533:11:p507c8b7b57','p507c8b7b57','interpellation','2025-05-05','{"councillors": ["林琮翰"], "dept": "財政及經濟發展處工商管理科", "doc_type": "書面質詢", "no_date": true, "page": 533, "session": "第20屆第5次定期會", "term": 20, "title": "馬當聚會所及文健站没有自來水可用，目前都由大豐消防分隊暫時接水供應，部落的豐年祭即將登場，用水問題如不即時改善，將會帶給部落非常嚴重的用水困境。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_05/04.pdf#page=533','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:530:1:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "社會處兒少及婦女福利科", "doc_type": "書面質詢", "no_date": true, "page": 530, "session": "第20屆第6次定期會", "term": 20, "title": "社會照護與長照服務需強化，多數原住民家庭同時肩負托幼與照顧老人的壓力，建議推動跨代共照模式，整合托育中心與長照據點。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=530','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:531:2:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "教育處課程暨專業發展科", "doc_type": "書面質詢", "no_date": true, "page": 531, "session": "第20屆第6次定期會", "term": 20, "title": "縣府與原民會合作擴增族語師資培訓計劃，讓學校有足夠族語老師。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=531','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:533:3:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "原住民族行政處部落經濟科", "doc_type": "書面質詢", "no_date": true, "page": 533, "session": "第20屆第6次定期會", "term": 20, "title": "許多原住民青年返鄉缺乏就業機會，縣府應設立原青創生中心，串聯旅遊文化與科技產業，協助青年返鄉創業。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=533','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:533:4:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 533, "session": "第20屆第6次定期會", "term": 20, "title": "持續推動部落品牌推廣計畫，協助原住民工藝、農特產品及文創商品，進入主流市場與電商平台。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=533','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:533:5:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "建設處土木科", "doc_type": "書面質詢", "no_date": true, "page": 533, "session": "第20屆第6次定期會", "term": 20, "title": "交通建設與聯外運輸無法滿足縣民之需求：進出台東的台9線與台11線車道窄、雙黃線又多，可供超車之路段少，造成一台烏龜車擋一路用路人，建議在適合區段拓寬道路、增加車道。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=533','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:534:6:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 534, "session": "第20屆第6次定期會", "term": 20, "title": "公車路線不足與班次稀少，偏鄉（如：延平、海端、達仁、東河）地區，班次太少，甚至没有班次（如：東河鄉泰源美蘭無公車）；學生、長者出行困難，應加強微型巴士或預約公車制。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=534','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:535:7:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 535, "session": "第20屆第6次定期會", "term": 20, "title": "航空與鐵路一票難求之問題依舊存在，尤其假日時更是嚴重，應與航空公司及台鐵協調如何來滿足縣民的需要，改善此種一票難求之現象。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=535','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:535:8:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 535, "session": "第20屆第6次定期會", "term": 20, "title": "夜間經濟活動薄弱，文創市集不穏定，台東故事館、鐵花村、波浪屋缺乏長期之規劃與招商透明度。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=535','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:536:9:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 536, "session": "第20屆第6次定期會", "term": 20, "title": "溫泉區老化和缺乏長期營造，知本温泉區，平假日遊客稀少，建議比照杉林溪或是國外大量種植櫻花及花旗木，美化環境道路景觀，來吸引遊客。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=536','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:536:10:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 536, "session": "第20屆第6次定期會", "term": 20, "title": "台東新站附近停車格嚴重不足，連續假日時，情況更是嚴重，造成要搭車的民眾没有地方停車；除此之外，停車繳費也常見大排長龍情形，繳費給民眾帶來不便與民怨。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=536','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:537:11:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 537, "session": "第20屆第6次定期會", "term": 20, "title": "因教育資源的落差，偏鄉學校缺乏英語師資，特教資源與數位設備不足，使得青年人口外流嚴重，應請中央支援並成立山海教育均質化專案，讓青年人願意留下來為自己的故鄉奮鬥打拚。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=537','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:539:12:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "民政處自治科", "doc_type": "書面質詢", "no_date": true, "page": 539, "session": "第20屆第6次定期會", "term": 20, "title": "海岸線、南迴線沿岸廢棄物污染嚴重，市郊或其他民眾不常出入及較隱蔽的地方如：太平溪出海口、海濱公園周遭、知本濕地常發現民眾丟棄的大型家具、瓶罐與垃圾等廢棄物，嚴重污染環境，除了影響民眾健康，更破壞觀瞻，應設立監視器材，取締這些棄置垃圾的民眾。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=539','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:06-04:540:13:p507c8b7b57','p507c8b7b57','interpellation','2025-10-22','{"councillors": ["林琮翰"], "dept": "財政及經濟發展處工商管理科", "doc_type": "書面質詢", "no_date": true, "page": 540, "session": "第20屆第6次定期會", "term": 20, "title": "風力發電與生態衝突問題，應落實環評與部落諮商機制，而不是開發單位已經到部落召開說明會時，再來提出反對與抗議。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_06/04.pdf#page=540','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:503:1:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 503, "session": "第20屆第7次定期會", "term": 20, "title": "2026台東博覽會整體規劃與財務效益：台東縣政府大力推動2026台東博覽會，並以Slow for Life及慢經濟作為主軸，宣稱結合南島文化、永續發展及國際觀光，打造台東大型國際展會。然而，本席關切：中央補助與地方自籌比例是否排擠原有社福、教育、道路及基礎建設預算？展期結束後是否留下長期效益？包括觀光產值、遊客停留天數、國際旅客人數、在地商家的收益、青年返鄉就業數據為何？博覽會是否淪為短期煙火式活動？是否建立議會監督專案報告機制？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=503','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:523:2:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 523, "session": "第20屆第7次定期會", "term": 20, "title": "台東博覽會是否真正照顧在地產業：縣府表示已有品牌授權、快閃店及商品合作計劃，本席質疑，目前參與廠商中，台東在地比例多少？外縣市廠商多少？小農及小型文創及部落工坊是否有能力參與？是否設有保障在地業者比例？縣府是否有公平、公開遴選機制？是否有實際行動支持原住民工藝、部落餐飲進入博覽會供應鏈？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=523','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:542:3:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 542, "session": "第20屆第7次定期會", "term": 20, "title": "原住民文化是否遭過度商業化：縣府多次強調南島文化與原住民元素將作為博覽會核心，本席關切原住民是否真正參與策展決策？是否取得各部落文化授權與諮商同意？原住民文化是否被當成觀光表演素材？是否建立了文化收益回饋機制？原住民青年是否有具體參與工作與創業機會？並保障了原住民傳統知識與文化智慧財產權？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=542','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:545:4:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "交通及工程養護處交通管理科", "doc_type": "書面質詢", "no_date": true, "page": 545, "session": "第20屆第7次定期會", "term": 20, "title": "交通能量是否足以承載博覽會人潮：博覽會預估將帶來大量觀光人流，但目前台東仍面臨台鐵班次不足、機票昂貴、市區停車空間不足，海岸線、縱谷線、南迴線等大眾運輸運能不足。本席要求縣府說明是否已完成交通衝擊評估？是否增加接駁系統，停五立體停車場停工後如何因應停車需求？工程爭議如何處理？是否涉及履約管理失當？市區停車黑暗期如何因應？新成立交通處，權責整合後是否真能改善交通效率？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=545','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:546:5:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "觀光發展處觀光管理科", "doc_type": "書面質詢", "no_date": true, "page": 546, "session": "第20屆第7次定期會", "term": 20, "title": "觀光發展與國際觀光推動是否失衡：2026「台東一遊未盡」包機獎勵方案，國際包機航線與包機實際成果如何？近年台東大量舉辦熱氣球嘉年華、演唱會大型活動、台東博覽會，但基層民眾普遍反應房價飆漲、薪資未提升、青年買不起房、淡季觀光仍低迷，縣府是否評估過活動經濟的真實效益？活動收益是否真正留在地方？或者僅集中在少數旅宿與大型業者？如何協助地方店家與夜市攤商並建立長期產業轉型策略？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=546','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:549:6:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "民政處戶政科", "doc_type": "書面質詢", "no_date": true, "page": 549, "session": "第20屆第7次定期會", "term": 20, "title": "青年外流與人口危機：台東長期面臨少子化、青年外流、高齡化、低薪問題，本席要求說明，台東博覽會能創造多少長期工作、是否有青年返鄉就業配套？新生兒補助是否足夠？公托、公幼及育兒資源是否充足？社會住宅政策進度如何？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=549','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:552:7:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "文化處藝文推廣科", "doc_type": "書面質詢", "no_date": true, "page": 552, "session": "第20屆第7次定期會", "term": 20, "title": "財政紀律與大型活動監督：本席要求縣府提供台東博覽會完整預算明細，各局處活動分配金額、對外標案與得標廠商資料，是否有追加預算風險？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=552','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:561:8:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "臺東縣環境保護局綜合計畫科", "doc_type": "書面質詢", "no_date": true, "page": 561, "session": "第20屆第7次定期會", "term": 20, "title": "環保與永續是否流於口號：縣府強調永續與慢經濟，但垃圾問題日益嚴重，焚化爐爭議持續，海岸線垃圾增加，東海岸開發壓力升高，博覽會是否有完整減碳計劃，活動期間垃圾如何處理？是否落實海岸保護？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=561','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:562:9:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "原住民族行政處保留地管理科", "doc_type": "書面質詢", "no_date": true, "page": 562, "session": "第20屆第7次定期會", "term": 20, "title": "原住民族土地與傳統領域權益：台東縣為全國原住民人口比例最高縣市之一，然而近年觀光開發，風電、光電、地熱、旅宿及大型活動持續進入原鄉，部落卻普遍反應參與不足，本席要求縣府說明，目前針對原住民傳統領域劃設進度為何？各種重大開發案是否完成部落諮商同意程序？是否發生未充分溝通即推動開發情形？部落會議決議是否真正被尊重？原住民土地流失問題是否持續惡化？縣府如何防止財團大量進入原鄉土地？原保地使用限制是否影響部落產業發展？是否協助族人合法利用祖傳土地？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=562','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:565:10:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "原住民族行政處文教行政科", "doc_type": "書面質詢", "no_date": true, "page": 565, "session": "第20屆第7次定期會", "term": 20, "title": "原鄉青年外流與文化斷層：目前許多原鄉面臨青年人口外流、部落高齡化、母語流失、傳統技藝失傳，縣府是否有完整的原住民青年返鄉計劃？是否協助原住民青年返鄉從事農業、文創、傳統藝能、生態旅遊之各項輔導政策？原住民族語教育專業不足、部落文化人才出現斷層，是否可以建立耆老文化傳承制度及如何避免原住民文化只剩活動表演化？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=565','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:567:11:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "原住民族行政處部落經濟科", "doc_type": "書面質詢", "no_date": true, "page": 567, "session": "第20屆第7次定期會", "term": 20, "title": "部落觀光收益問題：台東近年大量推動部落旅遊，但部落族人反應，遊客進來了，但收益沒有留在部落，本席要求縣府說明部落觀光收益分配機制為何？是否由少數業者壟斷資源，部落族人根本得不到任何效益？部落導覽、餐飲、民宿是否優先由在地經營？建立原住民品牌認證，協助部落小型工坊與青年品牌行銷。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=567','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:568:12:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "國際發展及計畫處資訊發展科", "doc_type": "書面質詢", "no_date": true, "page": 568, "session": "第20屆第7次定期會", "term": 20, "title": "原鄉基礎建設長期落差：許多原鄉仍存在道路破損、排水不良、路燈不足、通訊不穩、土石流風險，原鄉建設經費是否長期不足、為何部落道路災後修繕仍持續損壞？山區網路與通訊死角何時能改善？防災預警是否真正進入部落？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=568','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:571:13:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "臺東縣衛生局長期照顧科", "doc_type": "書面質詢", "no_date": true, "page": 571, "session": "第20屆第7次定期會", "term": 20, "title": "原住民健康與平均壽命問題：原住民長期面臨醫療及長照資源缺乏，平均壽命較低，本席要求縣府說明原鄉醫療是否足夠？偏鄉巡迴醫療頻率如何？長照據點是否普及？"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=571','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:574:14:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "原住民族行政處文教行政科", "doc_type": "書面質詢", "no_date": true, "page": 574, "session": "第20屆第7次定期會", "term": 20, "title": "原住民族教育與族語保存：現今許多原住民學童母語能力下降、缺乏族語環境、族語老師不足、沒有落實族語沉浸式教育、原住民實驗教育是否受到支持、如何保存原住民族語言，需縣府重視。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=574','2026-10-08T12:55:37Z');
INSERT INTO "fact" VALUES('tttq:07-04:578:15:p507c8b7b57','p507c8b7b57','interpellation','2026-05-06','{"councillors": ["林琮翰"], "dept": "原住民族行政處保留地管理科", "doc_type": "書面質詢", "no_date": true, "page": 578, "session": "第20屆第7次定期會", "term": 20, "title": "原住民保留地與居住正義問題：原住民現今面臨原保地限制嚴格、房屋合法化困難，本席要求縣府說明原保地使用是否過度僵化？可否協助族人合法興建住宅？推動部落聚落整體規劃、原鄉住宅老舊問題改善。"}','https://www.taitungcc.gov.tw/img/download/meeting/meeting20_07/04.pdf#page=578','2026-10-08T12:55:37Z');
