INSERT INTO "fact" VALUES('ntccq:202609011615240:129:0:p5c9f9f446a','p5c9f9f446a','interpellation','2026-04-29','{"councillors": ["陳宜君"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 129, "session": "第20屆第7次定期會", "term": 20, "title": "1.有關補助本縣 65 歲以上長者健保費政策，建請透過關懷據點、巷弄長照站多加宣傳、說明。2.建議針對已領取完「青年就業獎勵金」的個案進行大數據分析。若青年領完 1 萬 2 千元獎勵金後即離開南投縣，需追蹤原因（如薪資、環境因素），供作未來縣政府推動青年發展政策的依據。3.去年僅有 12 家企業參與青年實習與僱傭計畫，應開發更多企業加入，提供更多實習的工作機會。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=129','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:13:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-04','{"councillors": ["陳宜君"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "建議發文各鄉鎮公所，請施工廠商要用警示標誌與人員指揮管制，讓用路人更安全。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:140:0:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-04','{"councillors": ["陳宜君"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 140, "session": "第20屆第7次定期會", "term": 20, "title": "興建南投縣美術館經費 37.5 億，是否可以開國際標讓全球知名的廠商都可以參與，讓南投縣能見度可以提高。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:140:1:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-04','{"councillors": ["陳宜君"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 140, "session": "第20屆第7次定期會", "term": 20, "title": "1. 兩湖論談是否有談到農業行銷具體方案？2. 抓蛇業務是否可以回到農業處。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:140:2:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-04','{"councillors": ["陳宜君"], "dept": "防治所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 140, "session": "第20屆第7次定期會", "term": 20, "title": "埔里寵物運動公園何時可以完工，經費為多少？地點在那？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:144:3:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-05','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 144, "session": "第20屆第7次定期會", "term": 20, "title": "1. 埔里允捷掩埋場申請案是否可以實質駁回而不是行政駁回？並請在 2 個月召開相關會議，讓民眾安心。2. 埔里沒有垃圾掩埋場，雖然環保局有 50 萬元的補助，但是很快的就用完了，不知道垃圾要堆置到何處？請縣府應研商如何長期的協助埔里垃圾問題。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:144:4:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-05','{"councillors": ["陳宜君"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 144, "session": "第20屆第7次定期會", "term": 20, "title": "建請參酌其他縣市的小校轉型優質計畫，將地方特色產業融入校本課程，讓學生了解地方產業文化與歷史發展，也培養學生帶著走能力，展現學生多元學習及國民素養能力。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:147:4:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-06','{"councillors": ["陳宜君"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 147, "session": "第20屆第7次定期會", "term": 20, "title": "廚餘如果沒有處理的好，會滋生蚊蟲、蒼蠅、老鼠等病媒，導致漢他病毒的傳染，建請向民眾宣導防治。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=147','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:147:5:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-06','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 147, "session": "第20屆第7次定期會", "term": 20, "title": "1. 埔里清潔隊沒有場地，可以收運處理廚餘問題，是否請縣府協助解決。2. 明年開始廚餘不能再飼養豬隻，學校廚餘如何處理，教育處有何規劃？是否大的學校可以購置大型的廚餘處理機？並可以協助小校廚餘的處理。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=147','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:149:1:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-06','{"councillors": ["陳宜君"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 149, "session": "第20屆第7次定期會", "term": 20, "title": "1. 面對少子化，不是裁校而是轉型，應避免直接廢校，改為活化小校功能，讓小校持續發展、創造價值，讓小校成為在地亮點。2. 賴總統的少子化的政策，從 0-6 歲國家一起養，將擴大延伸到 18 歲，縣府是否有因應的策略？是否有做相關數據的調查？3. 南投縣小校功能轉型三項具體政策要求：（1）小校分類制度，依規模、區域與功能，建立分級分類機制。（2）資源再配置，依需求與效能調整資源，提升整體教育效益。（3）教育平衡白皮書，揭露城鄉教育差距，提出長期改善策略。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=149','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:151:4:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-07','{"councillors": ["陳宜君"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 151, "session": "第20屆第7次定期會", "term": 20, "title": "1. 南投縣面臨少子化，但特教生的人數卻持續攀升。身障生占全校學生數 10%以上的小學有16 所，國中有 5 所。應深入了解源頭找到對策，建議解方如下：(1)建立跨局處兒童發展資料庫：建議計畫處整合衛生、社政與教育局處，從母親孕期健康、家庭環境到學習歷程進行源頭追蹤與大數據分析，以找出確切對策。(2)強化多元輔療系統：針對早療鑑定時程過長的問題，建議正式將音樂治療、藝術治療及運動介入導入校園，幫助自閉症或過動症孩子提升專注力與穩定身心。3.建議效法雲林縣調降班級人數，達到減輕教師負擔、提升教學品質與兼顧特教生的三贏局面。4.埔里大成國中節電措施案例分享。建請教育處提供節電有成的案例供其他學校學習。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:154:1:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-07','{"councillors": ["陳宜君"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 154, "session": "第20屆第7次定期會", "term": 20, "title": "家長陳情學校營養午餐實際用餐時間僅約 15 分鐘，時間過於緊湊，學童無法好好用餐，且易造成廚餘過剩。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:154:2:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-07','{"councillors": ["陳宜君"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 154, "session": "第20屆第7次定期會", "term": 20, "title": "1.請摘錄南投美術館 PCM 廠商期末報告重點，供所有議員參考。2.設計南投美術館之建築師應具國際觀，建築設計必須展現南投縣在地特色。就教目前辦理進度，局長個人有何看法?是否會召開地方說明會，盡量讓民眾參與。另停車位數量應依據相關調查統計數據，妥善規劃。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:156:2:p5c9f9f446a','p5c9f9f446a','interpellation','2026-05-08','{"councillors": ["陳宜君"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 156, "session": "第20屆第7次定期會", "term": 20, "title": "1.全球趨勢城市外交正在改變，之前埔里鎮與日本出水市建立長期合作關係，深化城市關係，共創永續未來。教育交流培養下一代外交能力，文化交流讓城市外交更有溫度，讓交流真正被民眾感受。2.目前南投城市外交的三個問題，交流深度不足、缺乏永續機制、交流指標過於單一。真正重要的是是否持續、是否深入地方、是否培養人才。3.教育先行把學生帶進國際交流，讓年輕世代未來能代表南投與世界對話。深化民間與文化交流。建立治理論壇與對話平台。從參訪提升到共同解決問題。信任需要時間累積，真正的外交不是一次性的，也不僅是增加曝光。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=156','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:155:0:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-14','{"councillors": ["陳宜君"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 155, "session": "第20屆第6次定期會", "term": 20, "title": "1.本縣少子化問題日益嚴重，縣府雖已編列生育獎勵金尚無法完全解決少子化。創造友善的育兒空間，才能讓父母安心生養小孩。2.埔里地區托育人才培訓計畫是否完備？就教科長 10 月 18 日假日托育人員培訓班是否能如期開班？3.因應氣候變遷天氣炎熱，建議 0-2 歲托育中心如有戶外空間應增設遮陽設備。4.本縣親子館營運是否有監督機制？建請建立評鑑制度及指標，提供經營者營運方向及確保服務品質。5.就教本縣「好孕專車」計畫實施情形。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:155:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-14','{"councillors": ["陳宜君"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 155, "session": "第20屆第6次定期會", "term": 20, "title": "今年度縣政府辦理各項大型活動頻率過高，是否影響縣府團隊日常行政工作進度且造成壓力與負擔？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:10:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-16','{"councillors": ["陳宜君"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "1.埔里觀音瀑布入口處交通安全要升級，要有短期跟中長期決策。2.巧咖節辦理期間，是否可以調整辦理日期。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:169:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-17','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 169, "session": "第20屆第6次定期會", "term": 20, "title": "1. 全台事業廢棄物掩埋場在掩埋什麼東西？吉衛公司是否在處理飛灰固化物？2. 2020 年南烘溪及耶馬溪畔發生山崩事件，其山崩量達 6 萬 5 千立方米、堆積 40 公尺高；面對極端氣候的天災，仍無法保證一百分的安全，請不要讓埔里、魚池成為下一個馬太鞍，也不要成為台灣第一個有毒的堰塞湖出現？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=169','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:7:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-23','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "南崗工業區廚餘堆肥場的進度為何？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:8:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-23','{"councillors": ["陳宜君"], "dept": "工務交管", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "要促進觀光，交通是很重要的。遠見雜誌的評比南投縣成績都不錯。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:9:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-23','{"councillors": ["陳宜君"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "埔里中心碑分隊人力嚴重不足，勤務分配失衡，長期加班，休息不足。調派人員的依據為何？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:187:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-27','{"councillors": ["陳宜君"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 187, "session": "第20屆第6次定期會", "term": 20, "title": "面對每年不斷生長的樹木，但樹木變危樹時，學校未編列樹木體檢的經費，而且在修剪時都是斷頭式的修剪，對樹木會有何影響？請修訂管理辦法，以符合樹木的生長"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:187:2:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-27','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 187, "session": "第20屆第6次定期會", "term": 20, "title": "1. 允捷事業在埔里申請提出興辦事業計畫，縣府審查進度如何？2. 水源、水質是否會影響？是否有將各單位的意見提供給審查委員？3. 該掩埋場將會破壞生物、植物的多樣性，站在環境保護的立場縣府應該反對。4. 掩埋場位處河川上游與集水區，一旦防滲層發生滲漏，滲漏液可能經由地下水與支流逕流進入烏溪主流，進入鳥嘴潭人工湖，造成下游飲用水及灌溉水污染，對草屯、南投及彰化居民造成影響。5. 多雨與地震頻繁，會提高水頭壓力與結構變形風險，容易外溢造成宣洩。6. 環境與產業敏感，觀光與農業倚賴潔淨水源與良好形象，容錯度極低。7. 整治代價高昂，一旦污染形成，修復週期長、成本高且不確定性大。8. 環保局應要求開發單位儘速辦理公聽會，讓埔里鎮民參與並充分表達意見，以消除社會疑慮。9. 在開發單位沒有召開公聽會前，興辦事業計畫應停止審查。10.縣府應本維護環境之職責，宣示不支持的態度，凍結此案。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:193:0:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-28','{"councillors": ["陳宜君"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "有關「電圍網」補助應廣為周知。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:193:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-28','{"councillors": ["陳宜君"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "請於本次會期結束後一個月盤點本縣 13 鄉鎮避難處所，將相關資料供議員參考。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:193:2:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-28','{"councillors": ["陳宜君"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "提高「樂樂定點臨時托育服務中心」使用率相關建議：1.提供多元服務時段，增設彈性時段延長托育時間；採用預約制及臨時名額制度併行。2.簡化預約流程，開發 APP 或 LINE 帳號整合線上預約、名額查詢及候補功能。3.強化宣導與體驗推廣，與托嬰中心、親子館合作舉辦體驗托育日。加強在地宣導與 QR Code 導引。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:193:3:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-28','{"councillors": ["陳宜君"], "dept": "社勞原民教育", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "原民兒少性侵案件通報數高，亟待被重視與解決。建請聘請專業團隊進入校園及社區，透過互動與案例討論協助兒少及家長。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:193:4:p5c9f9f446a','p5c9f9f446a','interpellation','2025-10-28','{"councillors": ["陳宜君"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "請說明有關埔里大湳托育中心辦理進度延後之原因。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:114:0:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-23','{"councillors": ["陳宜君"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 114, "session": "第20屆第5次定期會", "term": 20, "title": "1. 表揚社勞局人民團體科呂建蒼科長，認真協助埔里鎮社區評鑑、臺灣夢兒少基地通過審查並獲得補助經費。2. 青年朋友反映青年發展所之成立顯現縣府對於青年返鄉之重視。肯定青年發展所楊紹宏所長傾聽並實踐各青年基地負責人反饋之意見。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=114','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:114:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-23','{"councillors": ["陳宜君"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 114, "session": "第20屆第5次定期會", "term": 20, "title": "1. 感謝處長及宗教禮俗科周洋攀科長協助清音寺申請案，及跨局處協調相關事宜。2. 縣府與廣隆光電、慈濟基金會自去年11月至今年5月份提供縣府員工蔬食餐，未來將由縣府民政處繼續推動，建議計算蔬食帶來的環保減碳效益，藉此鼓勵同仁淨零減碳。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=114','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:114:2:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-23','{"councillors": ["陳宜君"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 114, "session": "第20屆第5次定期會", "term": 20, "title": "因應氣候變遷法已於 112 年2 月15 日公布實施，本縣是否有計劃訂定縣內淨零排放自治條例？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=114','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:114:3:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-23','{"councillors": ["陳宜君"], "dept": "人事", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 114, "session": "第20屆第5次定期會", "term": 20, "title": "1. 如何掌握各局處針對職場霸凌案的調查進度？確保調查過程遵守程序正義，避免行政瑕疵。2. 對人事處處理職場霸凌案的提醒：(1) 針對職場霸凌的定義以及調查的標準作業流程應讓縣府各局處都了解，避免行政瑕疵。(2) 人事處除了掌握調查進度，必須告知調查過程中若有行政疏失或爭議時，要如何處理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=114','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:119:3:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-26','{"councillors": ["陳宜君"], "dept": "財政消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 119, "session": "第20屆第5次定期會", "term": 20, "title": "1. 因應中央補助款刪減，希望財主單位能夠做好管控。2. 建請消防局多跟民眾宣導緊急救難包的準備。3. 今年緊急救護案件較去年人數明顯增加，希望消防局要跟衛生局橫向聯繫，保障民眾生命安全。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=119','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:4:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-27','{"councillors": ["陳宜君"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "樹木褐根病防治，有補助經費給學校嗎？學校需要主動申請嗎？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:5:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-27','{"councillors": ["陳宜君"], "dept": "工務交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "埔里轉運站的進度？要符合多功能也要綠建築。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:6:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-27','{"councillors": ["陳宜君"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "1. 埔里觀音瀑布工程進度？觀音瀑布停車場到園區這段道路要好好規劃。2. 要推廣文化觀光，像埔里的日月老茶廠、廣興紙寮都是很好的旅遊地點。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:127:8:p5c9f9f446a','p5c9f9f446a','interpellation','2025-05-28','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 127, "session": "第20屆第5次定期會", "term": 20, "title": "1.埔里麒麟里掩埋場申請為何種項目廢棄物？爐渣、污泥是否為收受之範圍？2. 其掩埋場位置鄰界仁愛、埔里、魚池等 3 個鄉且流經牛洞自來水取水口、第一淨水場等，對農業、產業影響層面相當大，請廠商做謹慎長期的生態調查。3. 請允捷公司在 6 月份興辦事業計畫內容舉辦說明會時，讓民眾更了解。4. 垃圾源頭要減量，請環保局提供 6 年的垃圾成長狀況及外運量。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=127','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:6:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-04','{"councillors": ["陳宜君"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "1. 南投縣選委會裡的委員應該有更多政黨參與。2. 南投縣選委會對罷免案發言要更小心。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:7:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-04','{"councillors": ["陳宜君"], "dept": "社政衛生", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "1. 南投縣65歲以上長輩增加，正處在一個集體老化的社會之中。2. 建議衛生局和社勞局合作，共同研議如何讓縣內169個社區關懷據點及巷弄長照站長輩能有機會接受失智篩檢施測 AD-8表。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:140:0:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-04','{"councillors": ["陳宜君"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 140, "session": "第20屆第5次定期會", "term": 20, "title": "1. 感謝教育處經過兩年的努力與爭取，促成台中教育大學至南投縣開設小學教育學程學分班，鼓勵縣內代理教師就近進修。2. 目前有老師提出疑問，如果是學校自行招聘的代課老師是否有報名資格？3. 希望教育處能夠將報名的資格向各校說明清楚，也盡量爭取每年續辦。4. 中等學校的部份，建議繼續與暨大師資培育中心合作，規劃進修方案。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:141:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-04','{"councillors": ["陳宜君"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 141, "session": "第20屆第5次定期會", "term": 20, "title": "1. 觀音瀑布由觀光處向中央爭取4765萬整修，預計10月份完工對外開放，但入口道路的安全成為最大的挑戰，如何讓遊客安全過馬路，觀光處有何想法？2. 觀光處應盡速與工務段研商，考慮使用雙閃燈，加上測速照相使車輛降速，保障行人穿越馬路的安全。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=141','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:143:3:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-05','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 143, "session": "第20屆第5次定期會", "term": 20, "title": "1. 民間事業申請的垃圾掩埋場地點南港溪的上游，銜接野溪與第一淨水廠相距1公里，水源污染堪虞。2. 垃圾掩埋場如果要進行會勘，請邀請中央、立法委員，並通知轄區議員一起。3. 民間申請掩埋場設立地點需行經投69線紅仙水隧道，其該基地的聯外道路尚未拓寬，全段未符合要求，雖1018-10地號為農林公司所有，但現況為山坡地，是否可不經審查而進行拓寬？4. 依據非都市土地開發審議作業規範，垃圾掩埋場基地聯外道路，應至少有獨立兩條通往連外道路，且其中一條其路寬至少8公尺以上，另一條可為緊急通路，且寬度須容納消防車通行。5. 垃圾分類、焚燒只能治標，最重要的是源頭減量才能治本，請縣府跨局處共同研擬有效的減量策略，例如推動市集不使用一次性的餐具，改用餐具租借方式等。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:148:0:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-06','{"councillors": ["陳宜君"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 148, "session": "第20屆第5次定期會", "term": 20, "title": "埔里事業廢棄物掩埋場未來如有滲漏，補救措施之疑義。選址位於南港溪上游集水區屬水源地，有汙染水源之虞，不宜設置掩埋場。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=148','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:148:1:p5c9f9f446a','p5c9f9f446a','interpellation','2025-06-06','{"councillors": ["陳宜君"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 148, "session": "第20屆第5次定期會", "term": 20, "title": "本縣雖已成立交通運輸工程管理所，但仍未成立交通專責單位，整體交通發展缺乏全面性規劃。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=148','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:129:1:pc917d42434','pc917d42434','interpellation','2026-04-29','{"councillors": ["王秋淑"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 129, "session": "第20屆第7次定期會", "term": 20, "title": "1.就教目前敬老愛心卡用途，建請擴充使用範圍，補助長輩就醫掛號費用。2.魚池鄉武登社區建築物老舊，建請規劃無障礙設施，保障長輩安全。3.建請提高本縣重陽敬老禮金額度。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=129','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:134:2:pc917d42434','pc917d42434','interpellation','2026-04-30','{"councillors": ["王秋淑"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "消防局務必儘快協調偏遠地區 119 與急診醫療站救護車聯動機制，及時搶救傷患，以免因等待遠處的救護車而發生搶救不及的憾事。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:134:3:pc917d42434','pc917d42434','interpellation','2026-04-30','{"councillors": ["王秋淑"], "dept": "稅務", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "稅務局不要處處刁難農民。如果稅務局對於農地農用標準過於嚴苛，農民都不敢回南投，此亦造成本縣人口外移的原因之一。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:148:2:pc917d42434','pc917d42434','interpellation','2026-05-06','{"councillors": ["王秋淑"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 148, "session": "第20屆第7次定期會", "term": 20, "title": "帶狀疱疹俗稱皮蛇，後遺症嚴重影響身體健康，是否有疫苗可供年長者民眾施打？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=148','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:148:3:pc917d42434','pc917d42434','interpellation','2026-05-06','{"councillors": ["王秋淑"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 148, "session": "第20屆第7次定期會", "term": 20, "title": "1. 消防人員補休未能確實休假，二年內未能休完者，休假時數就會消滅，建請增編預算經費補助，提升超時加班費？2.EMT 緊急救護技術員分級為初、中、高級等三級，目前南投縣 3 個分隊沒有高級救護員，建請能夠補足，以提升救護品質。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=148','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:151:0:pc917d42434','pc917d42434','interpellation','2026-05-07','{"councillors": ["王秋淑"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 151, "session": "第20屆第7次定期會", "term": 20, "title": "農作物是否有休耕期？休耕期農地農用如何認定?"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:151:1:pc917d42434','pc917d42434','interpellation','2026-05-07','{"councillors": ["王秋淑"], "dept": "稅務", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 151, "session": "第20屆第7次定期會", "term": 20, "title": "有關農地(香菇寮)休耕期間房屋稅課徵疑義。香菇寮在休耕期如何認定是否有農地農用?魚池農民菇寮拆除時，局長是否指示埔里分局主任及承辦人前去了解？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:0:pc917d42434','pc917d42434','interpellation','2025-10-16','{"councillors": ["王秋淑"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "日月潭為國家級風景區，為南投縣的門面，舊的日月潭消防隊廳舍要做何使用？如何規劃？不要荒廢在那裡，讓遊客觀感不好。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:1:pc917d42434','pc917d42434','interpellation','2025-10-16','{"councillors": ["王秋淑"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "1. 投 131 線旁水溝要清淤，什麼時候才能清除完畢。2. 投 62 線頭社道路路面不平，人孔蓋沒跟道路齊平，何時能完成改善？3. 131 線明隧道評估進度到那裡？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:2:pc917d42434','pc917d42434','interpellation','2025-10-16','{"councillors": ["王秋淑"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "魚池公共托育中心進度如何？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:170:5:pc917d42434','pc917d42434','interpellation','2025-10-17','{"councillors": ["王秋淑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 170, "session": "第20屆第6次定期會", "term": 20, "title": "1. 水源是人民和農作物的命脈，廢棄物掩埋會影響到水源的污染，危害民眾的健康和農作的生長。2. 補助地方政府辦理石綿建材廢棄物清除處理工作，為什麼地方不知道有這項補助？3. 石綿瓦掩埋後也會對土壤造成危害，甚至民眾的健康，請宣導讓民眾知道。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:1:pc917d42434','pc917d42434','interpellation','2025-10-23','{"councillors": ["王秋淑"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "1.希望台中捷運延伸到南投地區，促進南投縣觀光人潮。2.投 58 線道路施工進度為何？3.爭取共和村 131 線通往埔里道路施設明隧道。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:2:pc917d42434','pc917d42434','interpellation','2025-10-23','{"councillors": ["王秋淑"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣 65 以上長輩明(115)年度不用繳納健保費由縣府支出嗎？2. 敬老愛心卡 1000 元是否擴大使用？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:3:pc917d42434','pc917d42434','interpellation','2025-10-23','{"councillors": ["王秋淑"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "1. 母嬰營養補助金的推動，是否擴展到中低收戶。2. 2025 年生育津貼，南投縣首胎補助 1 萬。3. 一鄉一鎮設 0-2 歲托育中心。4. 九九重陽禮金縣府發 65-99 歲領 1000 元。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:185:3:pc917d42434','pc917d42434','interpellation','2025-10-27','{"councillors": ["王秋淑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 185, "session": "第20屆第6次定期會", "term": 20, "title": "1. 魚池鄉共和村與仁愛鄉交界處將設置廢棄物掩埋場，會影響水源，危害農作物等，請縣府重視該掩埋場的申請案。2. 台灣發生非洲豬瘟案例致禁止廚餘養豬政策，廚餘要如何處理？3. 現在南投的廚餘一天有多少的量？暫置在哪裡？4. 廚餘的惡臭很讓人受不了，請環保局重視及儘快處理，不要讓環境受到危害，也不要成為廚餘山，沒有堆肥場的鄉鎮給予協助處理，對於設備老舊的堆肥場，也給予增購換新設備來因應。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:185:4:pc917d42434','pc917d42434','interpellation','2025-10-27','{"councillors": ["王秋淑"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 185, "session": "第20屆第6次定期會", "term": 20, "title": "1. 建請學校汰換傳統課桌椅，以符合人體工學且舒適的桌椅，讓課桌椅變成午休床，改善學童午休，提升休息品質。2. 前逢甲大學發生校樹壓死人，教育處怎麼看？請全縣校園盤查是否有病蟲害影響樹木健康之情形，若發現有危樹時應儘速防治或移除。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:0:pc917d42434','pc917d42434','interpellation','2025-10-27','{"councillors": ["王秋淑"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "這次茶博活動有比上次提升，但是在熟食區未設置水槽，不太衛生，應與洗手間區隔；如同茶博「品味南投」的活動，大都是用站著品茗，及熟食區未設置水槽，業者需到洗手間水槽使用，應與洗手間要有區隔；以上規劃上不是很好，也覺得不太衛生，請未來再辦理相關活動時能改善。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:191:0:pc917d42434','pc917d42434','interpellation','2025-10-28','{"councillors": ["王秋淑"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 191, "session": "第20屆第6次定期會", "term": 20, "title": "開設急診救護站的目的為何？請加強跟民眾宣導其醫療服務項目。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=191','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:191:1:pc917d42434','pc917d42434','interpellation','2025-10-28','{"councillors": ["王秋淑"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 191, "session": "第20屆第6次定期會", "term": 20, "title": "1.就教處長，農業廢棄物如何變黃金？2.農業廢棄物如何再生利用？請開發多元用途，並結合輔導返鄉青農創業多加推廣應用。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=191','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:140:2:pc917d42434','pc917d42434','interpellation','2025-06-04','{"councillors": ["王秋淑"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 140, "session": "第20屆第5次定期會", "term": 20, "title": "敬老愛心卡每月補助1000元，單趟使用100元，是否可以不要限制單趟使用金額？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:140:3:pc917d42434','pc917d42434','interpellation','2025-06-04','{"councillors": ["王秋淑"], "dept": "地政工務", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 140, "session": "第20屆第5次定期會", "term": 20, "title": "1. 魚池鄉頭社區重劃區是何時重劃的？目前社區AC路面不平，請縣府改善。2. 投61線道路改善工程，要另外增設自來水管線，為什麼道路改善好了，自來水管線還沒有裝設好。3.131線道水里段路面不平請縣府改善。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:140:4:pc917d42434','pc917d42434','interpellation','2025-06-04','{"councillors": ["王秋淑"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 140, "session": "第20屆第5次定期會", "term": 20, "title": "131線旁野溪土石淤積嚴重，雨季快到了請縣府改善。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:143:1:pc917d42434','pc917d42434','interpellation','2025-06-05','{"councillors": ["王秋淑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 143, "session": "第20屆第5次定期會", "term": 20, "title": "1. 民間申請垃圾掩埋場佔地25公頃毗鄰魚池鄉，所以鄉民也在反對，為何會選址在這裡？請縣府嚴謹審慎的把關。2. 魚池鄉台16線13.5K處有很多亂丟垃圾造成地方的髒亂，請裝設監視器取締及協助清理垃圾。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=143','2026-10-15T03:46:11Z');
