INSERT INTO "fact" VALUES('ntccq:202609011615240:139:8:p16605c3901','p16605c3901','interpellation','2026-05-04','{"councillors": ["林芳伃"], "dept": "交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "1. 埔里行政園區停車空間規劃已完成，是否已開始收費？要跟埔里公所溝通繳費要用多元方式。2. 道路標線劃設要讓行人知道用意，要多宣導。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:9:p16605c3901','p16605c3901','interpellation','2026-05-04','{"councillors": ["林芳伃"], "dept": "觀光風管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "埔里觀音瀑布是蝴蝶生長的地點，之前封閉很久，目前已開放，建議要多種植花草美化景觀。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:143:6:p16605c3901','p16605c3901','interpellation','2026-05-05','{"councillors": ["林芳伃"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 143, "session": "第20屆第7次定期會", "term": 20, "title": "學校軟硬體設備應全面性檢視，有安全之虞的設施應予改善，儘量協助學校所需。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:144:0:p16605c3901','p16605c3901','interpellation','2026-05-05','{"councillors": ["林芳伃"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 144, "session": "第20屆第7次定期會", "term": 20, "title": "埔里允捷掩埋場申請案因為影響甚大，所以埔里區的議員一提再提，請教縣府傾向是駁回的態度嗎？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:181:1:p16605c3901','p16605c3901','interpellation','2026-05-19','{"councillors": ["林芳伃"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 181, "session": "第20屆第7次定期會", "term": 20, "title": "就教有關內政部「老宅延壽機能復新計畫」，縣府如何因應：1.本縣符合 30 年以上的老舊公寓或透天厝具體數量是多少？2.縣府目前預收登記案件是否都符合該計畫的法規與資格規定？3.依據人口比例推估，中央 50 億預算分配到南投可能只有 60 戶能獲得補助，對於供不應求（登記已達 96 案）多出戶數，縣府今年編列了多少預算？是否有自辦補助的規劃？4.南投在 921 地震時錯過城市更新的機會，建請縣府應把握此次政策，將老宅機能復新視為整體環境與市容改造的一部分，藉此改善公共空間老化、提升居住安全、保存地方特色，進而推動「宜居南投」並留住年輕人。5.許多民眾認為政府的錢綁手綁腳、流程繁瑣，導致好政策變成「畫大餅」，建請縣府不僅給予經費補助，更要加強宣傳與輔導，讓民眾真正看得到、拿得到。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:181:2:p16605c3901','p16605c3901','interpellation','2026-05-19','{"councillors": ["林芳伃"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 181, "session": "第20屆第7次定期會", "term": 20, "title": "埔里第一公墓(覆鼎金)轉型遺址公園還要等多久？請說明目前規劃辦理進度。辦理時程過久，應縮短流程積極催辦，落實地盡其利，帶動地方繁榮。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:2:p16605c3901','p16605c3901','interpellation','2026-05-21','{"councillors": ["林芳伃"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1.全台測速照相及科技執法是為了民眾安全，請問局長南投科技執法設置幾處？科技執法路口如遇到救護車，民眾讓不讓？會不會被開單？2.交通標誌標線劃設問題，交通檢舉制度有問題，台灣政府聽得見人民心聲嗎？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:3:p16605c3901','p16605c3901','interpellation','2026-05-21','{"councillors": ["林芳伃"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "114 年 9 月 14 仁愛鄉高麗菜園受到猴害及天然災害，損失慘重，政府如何輔導農民及有什麼防範措施？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:4:p16605c3901','p16605c3901','interpellation','2026-05-21','{"councillors": ["林芳伃"], "dept": "財政衛生消防", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1. 縣府的負債，縣長上任短短 3 年已還清。既然已都還清了，縣府各局處人員缺額要盡速補足。2. 帶狀泡疹疫苗請縣府研議開放限制年齡免費施打或補助部份金額。3. 消防人員超勤方面，請縣府補足超勤費用。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
