INSERT INTO "fact" VALUES('ntccq:202606090806090:161:10:p16605c3901','p16605c3901','interpellation','2025-10-15','{"councillors": ["林芳伃"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 161, "session": "第20屆第6次定期會", "term": 20, "title": "1. 感謝警察局在國慶煙火的交通疏散表現。2. 埔里街頭路面劃滿綠色的標線型人行道，但是許多民眾不了解用意為何，希望警察局多加宣導，避免民眾不了解而受罰。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=161','2026-10-15T03:46:11Z');
