INSERT INTO "fact" VALUES('ntccq:202606090806090:174:0:p16605c3901','p16605c3901','interpellation','2025-10-20','{"councillors": ["林芳伃"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 174, "session": "第20屆第6次定期會", "term": 20, "title": "1. 公共道路設施如號誌燈、路燈等的底座設計潛藏的危險，機車騎士一不小心，會造成生命的危險，建請在基礎上做些改變，如加裝保護套，在突出的螺栓上加裝有彈性的橡膠保護套包覆，以提供緩衝有效遮蔽，減少因外露碰撞的危險。2. 電動車的掛牌率愈來愈多，但是本縣的電動車充電樁卻不普及化，建請參考國外利用電桿方式的做法，可以更普及方便駕駛人。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=174','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:174:1:p16605c3901','p16605c3901','interpellation','2025-10-20','{"councillors": ["林芳伃"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 174, "session": "第20屆第6次定期會", "term": 20, "title": "縣內停車格由鄉鎮市公所規劃畫設，原本停放的車輛就改停到社區巷道內，造成社區居民的不便，建請路邊的停車格收費能改月租（票）方式。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=174','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:6:p16605c3901','p16605c3901','interpellation','2025-10-22','{"councillors": ["林芳伃"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "新版財劃法通過後，對縣府財政影響如何？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:115:4:p16605c3901','p16605c3901','interpellation','2025-05-23','{"councillors": ["林芳伃"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 115, "session": "第20屆第5次定期會", "term": 20, "title": "有關縣政府綜合大樓使用情形及管轄單位？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=115','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:115:5:p16605c3901','p16605c3901','interpellation','2025-05-23','{"councillors": ["林芳伃"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 115, "session": "第20屆第5次定期會", "term": 20, "title": "1.對於縣政府綜合大樓空間使用規劃及內、外觀之看法？2樓橫樑已斑駁建請先行改善。2. 埔里仁愛公園經常有上百位弱勢民眾、遊民排隊領取寺廟提供之愛心便當，局長有何看法？3. 請加強社區關懷據點長者餐食內容之查核；活動課程規劃應多元化。4. 對於青年返鄉、留鄉發展、創業、就業輔導、居住優惠等，青年發展所的作為有哪些？5. 建請及時更新網站內容以供青年朋友查閱。6. 有關本縣點石成金2.0計畫獎勵金發放內容為何？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=115','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:118:3:p16605c3901','p16605c3901','interpellation','2025-05-26','{"councillors": ["林芳伃"], "dept": "財政警察", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 118, "session": "第20屆第5次定期會", "term": 20, "title": "1. 中央統刪減補助款的政策，希望各局處能夠持續現有進行的工作及福利政策，把影響降到最低。2. 詐騙案件層出不窮，街頭掛滿防詐紅布條，希望警局還是要深入社區宣導。3. 交通違規罰則變化快速，網路上充滿許多假消息，造成民眾困擾，希望警局能夠正確宣導交通法規讓民眾理解。4. 毒品氾濫，今年1到 4月的查緝量已經快達去年全年的查緝量，希望查緝工作要持續，不要讓毒品流竄在南投縣內。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=118','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:7:p16605c3901','p16605c3901','interpellation','2025-05-27','{"councillors": ["林芳伃"], "dept": "觀光風管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "觀光能夠帶動地方產業。鯉魚潭風景區經營方式為何？需要收費嗎？縣府投入多少經費？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:8:p16605c3901','p16605c3901','interpellation','2025-05-27','{"councillors": ["林芳伃"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "天然災害災修提報有時間性嗎？去年10月定期會提的案件到目前還沒動工。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:127:2:p16605c3901','p16605c3901','interpellation','2025-05-28','{"councillors": ["林芳伃"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 127, "session": "第20屆第5次定期會", "term": 20, "title": "針對萊猪流向及明確標示本縣稽查及執行情形？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=127','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:127:3:p16605c3901','p16605c3901','interpellation','2025-05-28','{"councillors": ["林芳伃"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 127, "session": "第20屆第5次定期會", "term": 20, "title": "1. 對於新北市三峽區發生學生重大交通事故、毒品、詐騙進入校園，校園安全讓人擔憂，請強化學童安全的保障、無障礙設施，提供校園安全的建置。2. 今年度追加預算是在哪個部分？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=127','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:127:4:p16605c3901','p16605c3901','interpellation','2025-05-28','{"councillors": ["林芳伃"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 127, "session": "第20屆第5次定期會", "term": 20, "title": "埔里鎮麒麟里垃圾掩埋場是農林公司的土地，請問該面積有多大？該公司是否已進入二階的環評作業？日後對空氣、環境造成什麼樣的影響？其已經引起地方的關注及討論，不要破壞好的水質及環境。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=127','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:131:0:p16605c3901','p16605c3901','interpellation','2025-05-29','{"councillors": ["林芳伃"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 131, "session": "第20屆第5次定期會", "term": 20, "title": "縣府負責交通業務人員僅2 人，尚還要辦理停車催繳工作，曝露人力嚴重不足困窘。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=131','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:131:1:p16605c3901','p16605c3901','interpellation','2025-05-29','{"councillors": ["林芳伃"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 131, "session": "第20屆第5次定期會", "term": 20, "title": "1. 食安問題萊猪來了怎麼辦？2. 呼籲政府應公布萊猪流向，並明確標示，不允許黑箱作業，加强市場攤商稽查。3. 現在南投的查驗量是多少？是否有清楚的標示？4. 學校只限用國產肉品，若違規使用進品肉品，建請取消團膳承攬資格。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=131','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:133:2:p16605c3901','p16605c3901','interpellation','2025-06-02','{"councillors": ["林芳伃"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 133, "session": "第20屆第5次定期會", "term": 20, "title": "本縣長照業務仍有不足之處，有待改善：1. 地理限制：長照中心集中於市區，偏鄉可近性低。2. 交通不便：缺乏公共運輸，長輩難以到達服務據點，即便有交通補助，實際使用率仍受限。3. 偏鄉專業團隊人力資源短缺、原住民地區文化敏感度不足，結合文化習俗照護相關培訓較少。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=133','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:133:3:p16605c3901','p16605c3901','interpellation','2025-06-02','{"councillors": ["林芳伃"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 133, "session": "第20屆第5次定期會", "term": 20, "title": "1. 長照多元服務不足，如失智症專責服務，夜間及假日支援較少，難以滿足家庭需求。2. 居家醫療整合待加強，山區醫療資源不足，居家醫療與長照銜接率低，遇有需要醫療或緊急狀況如何給予支援？3.如何申請使用居家醫療服務？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=133','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:130:4:p1022630c83','p1022630c83','interpellation','2026-04-29','{"councillors": ["林庭秝"], "dept": "新聞行政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 130, "session": "第20屆第7次定期會", "term": 20, "title": "縣府大樓動線複雜，本席及族人前往縣府各局處洽公時實感不便，建請儘速改善。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:130:5:p1022630c83','p1022630c83','interpellation','2026-04-29','{"councillors": ["林庭秝"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 130, "session": "第20屆第7次定期會", "term": 20, "title": "請說明仁愛鄉翠巒及瑞岩部落遷村案辦理進度。應建立溝通平台或定期下鄉專案說明，使橫向的溝通更明確，讓遷村期程不再延宕，符合族人的期待。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:11:p1022630c83','p1022630c83','interpellation','2026-05-04','{"councillors": ["林庭秝"], "dept": "交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "埔里路邊停車繳費要多元方式進行。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:12:p1022630c83','p1022630c83','interpellation','2026-05-04','{"councillors": ["林庭秝"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "每逢大雨造成投 89 線 30K 等多處坍方，梅雨季也快到了，縣府有無對應方案？經費需要多少？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:143:4:p1022630c83','p1022630c83','interpellation','2026-05-05','{"councillors": ["林庭秝"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 143, "session": "第20屆第7次定期會", "term": 20, "title": "1. 仁愛鄉有 5 個國小沒有校長，何時才能夠補足？2. 山地偏遠地區校長、教師未能久任，如何改善？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:1:p1022630c83','p1022630c83','interpellation','2026-05-11','{"councillors": ["林庭秝"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "支持南投縣興建焚化爐與家庭式廚餘機經費補助。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:2:p1022630c83','p1022630c83','interpellation','2026-05-11','{"councillors": ["林庭秝"], "dept": "原民建設", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "1. 仁愛鄉中正村簡易自來水失效暨盤點全鄉水源與鑿井需求。2. 具體建議全面盤點仁愛鄉各村無穩定水源部落清冊及啟動替代水源評估方案以及專案補助與分級處理設立偏鄉供水改善專案。3. 南投縣簡易自來水事業設備及設施之改善或新建經費補助辦法，個案申請經費為 100 萬以下，是否可以調整修正補助上限？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:0:p1022630c83','p1022630c83','interpellation','2026-05-12','{"councillors": ["林庭秝"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "1. 仁愛鄉特教生計有 55，原班級授課包含一般生及特教生，教師教學無形的壓力甚大，請給予偏遠山地資源，建請班級學生人數再調降，以減輕教師負擔。2. 建請教育處可與衛生局等單位跨局處合作，以健全教育環境，並提升教師專業、集中設班、持續給予學校相對的資源。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:155:2:p1022630c83','p1022630c83','interpellation','2025-10-14','{"councillors": ["林庭秝"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 155, "session": "第20屆第6次定期會", "term": 20, "title": "埔里和仁愛為共同生活圈，埔里保育人員假日培訓班資訊在仁愛鄉宣導不足。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:155:3:p1022630c83','p1022630c83','interpellation','2025-10-14','{"councillors": ["林庭秝"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 155, "session": "第20屆第6次定期會", "term": 20, "title": "1.國慶焰火首度在南投舉辦，結合茶葉博覽會年度大型活動，肯定縣府的辛勞。就本席近日觀看的留言及討論，聲量較高部分如下：(1)施放當天煙霧太大，施放地點、高度、發數是否由縣府主導規劃?(2)環保意識抬頭，煙火可選擇低煙、無煙。天候因素難以考量，細部計畫、採購品項等，是否由縣府統籌規劃？(3)散場交通管制、接駁車量能、路線在活動辦理之前是否有做壓力測試並達到分流？建請將本次經驗，做為未來辦理大型活動之參考。2.一般民眾無法進入主場，因此產生階級落差，觀感不佳。後續如有規劃大型活動，主會場應納入一般民眾，增加參與度。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:7:p1022630c83','p1022630c83','interpellation','2025-10-16','{"councillors": ["林庭秝"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "精英村往馬赫坡橋墩被土石沖刷，要如何改善？有什麼解決方法？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:206:0:p1022630c83','p1022630c83','interpellation','2025-11-03','{"councillors": ["林庭秝"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 206, "session": "第20屆第6次定期會", "term": 20, "title": "1.南投縣各鄉鎮目前垃圾的總堆積量是多少？在仰賴外縣市處理的現況下，每天實際能清運處理的量是多少？2.本縣興建垃圾焚化廠相關探討：(1)選址於名間鄉新民村的專業考量依據是什麼？是否已明確避開農田區與水質保護區？(2)目前環評辦理進度？民眾的意見陳述，是否都已納入檢討流程？(3)焚化爐的煙霧淨化與廢水排放設備，能否真正達到零排放、零污染？(4)作為「嫌惡設施」，若未來仍造成環境污染或農損，縣府的配套措施與補償機制是什麼？(5)焚化爐興建需時 6 年，過渡期間縣府是否有加強推動垃圾源頭減量及提高資源回收的環保政策？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=206','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:206:1:p1022630c83','p1022630c83','interpellation','2025-11-03','{"councillors": ["林庭秝"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 206, "session": "第20屆第6次定期會", "term": 20, "title": "1.因非洲豬瘟禁止使用廚餘養豬，目前本縣廚餘處理情形？是否會因處理不當造成環境污染或者是防疫漏洞？2.雲林縣 7 年前已禁廚餘養豬，處理廚餘的經驗值得借鏡，3.集集鎮引進「黑水虻」分解廚餘，其他鄉鎮是否有相對措施？縣府是否有給予協助？3.縣府是否能在明年恢復辦理「家用廚餘機」的補助方案？4.縣府是否有規劃針對學校或餐飲業，推動廚餘減量的中長期計畫？5.針對南崗工業區採 BOT 模式建置的廚餘中心：(1)處理流程、規模及預計辦理期程？(2)縣府的監督機制如何設計？規劃過中是否確保資訊公開透明，並讓當地居民充分參與？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=206','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:3:p1022630c83','p1022630c83','interpellation','2025-11-04','{"councillors": ["林庭秝"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "埔里全民運動館與原民集會所的共構案的期程如何？原民集會所的空間場域是屬於獨立使用空間還是附屬在運動場地內？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:4:p1022630c83','p1022630c83','interpellation','2025-11-04','{"councillors": ["林庭秝"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "原住民集會所的規劃、工程經費如何？未來設計規劃上能否納入原住民代表？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:5:p1022630c83','p1022630c83','interpellation','2025-11-04','{"councillors": ["林庭秝"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "1. 仁愛鄉消防站成立期程，力行線、得鹿谷線、法治線的地點、人員配置如何？2. 仁愛鄉有許多失蹤人口協尋的案件，消防局在處理案件上有沒有什麼流程？出隊時間、出隊人數上有沒有相關規定？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:214:9:p1022630c83','p1022630c83','interpellation','2025-11-05','{"councillors": ["林庭秝"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 214, "session": "第20屆第6次定期會", "term": 20, "title": "1.禁伐補助，感謝縣府的支持。2.南投縣彩虹織女織布、聽夢藝術節、千人烤大豬、原舞藝動這些原民活動，請原民處多辦理這類型活動，如原住民音樂節等等。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=214','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:115:0:p1022630c83','p1022630c83','interpellation','2025-05-23','{"councillors": ["林庭秝"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 115, "session": "第20屆第5次定期會", "term": 20, "title": "淨零排放是國際趨勢，本縣訂定自治條例的腳步應加快。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=115','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:115:1:p1022630c83','p1022630c83','interpellation','2025-05-23','{"councillors": ["林庭秝"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 115, "session": "第20屆第5次定期會", "term": 20, "title": "1. 本席曾提議原民處建置原鄉「一村一球場」，仁愛鄉中正村、精英村及南豐村等目前辦理情況及進度？2. 仁愛鄉中正村運動公園集會所今年度能否動工興建？3. 南豐村是否有其他公有地適合做集會所或球場？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=115','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:118:4:p1022630c83','p1022630c83','interpellation','2025-05-26','{"councillors": ["林庭秝"], "dept": "稅務", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 118, "session": "第20屆第5次定期會", "term": 20, "title": "房屋稅2.0上路，有關自住優惠稅率的部分，921地震時政府在瑞岩部落蓋了賑災屋供災民使用，希望稅務局能夠以專案方式讓族人能夠取得所有權，得以適用自住優惠稅率。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=118','2026-10-15T03:46:11Z');
