INSERT INTO "fact" VALUES('ntccq:202512051057560:126:0:p1022630c83','p1022630c83','interpellation','2025-05-28','{"councillors": ["林庭秝"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 126, "session": "第20屆第5次定期會", "term": 20, "title": "1. 偏鄉牙醫嚴重不足，是否可以多設立幾個醫療站。2. 建請今年在仁愛鄉再成立一個醫療站，以方便照護偏鄉老人。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=126','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:0:p1022630c83','p1022630c83','interpellation','2025-06-09','{"councillors": ["林庭秝"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "1. 新版財劃法公布實施後，南投縣可以增加多少財源？2. 增加的財源什麼時候可以撥下來？3. 新版財劃法通過後對地方政府有何利弊？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:1:p1022630c83','p1022630c83','interpellation','2025-06-09','{"councillors": ["林庭秝"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "梅雨季造成仁愛鄉多處道路坍方，希望未來地方財源增加後能夠改善，給仁愛鄉民一條安心回家的路。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:2:p1022630c83','p1022630c83','interpellation','2025-06-09','{"councillors": ["林庭秝"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "感謝縣府對偏鄉醫療重視，仁愛鄉送藥到府的服務效能能不能符合當地居民的需求？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:155:1:p1022630c83','p1022630c83','interpellation','2025-06-10','{"councillors": ["林庭秝"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 155, "session": "第20屆第5次定期會", "term": 20, "title": "1. 長期都靠外縣市幫忙焚化垃圾，南投縣建興垃圾焚化廠是有必要的。2. 焚化爐要提出完整的報告，才能讓民眾信服。3. 在埔里鎮民間業者申請垃圾掩埋場，選址地點為水源區，請縣府要嚴格審查跟把關，有沒有讓民眾可以表達意見的平台？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:158:4:p1022630c83','p1022630c83','interpellation','2025-06-11','{"councillors": ["林庭秝"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 158, "session": "第20屆第5次定期會", "term": 20, "title": "仁愛鄉曲冰遺址建請文化局提出配套措施，未來做一個完善的規劃。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=158','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:130:6:pf24e796773','pf24e796773','interpellation','2026-04-29','{"councillors": ["陳淑惠"], "dept": "地政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 130, "session": "第20屆第7次定期會", "term": 20, "title": "許多農地圖資久未更新，經常造成地主與鄰地鑑界之後很多困擾。農地重測鑑界後產生誤解的後遺症相當大，建請更新圖資，避免造成地主間的誤會。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:130:7:pf24e796773','pf24e796773','interpellation','2026-04-29','{"councillors": ["陳淑惠"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 130, "session": "第20屆第7次定期會", "term": 20, "title": "有關長照補助，照顧管理專員核准長照居服員工作時數之標準有待商榷。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:136:2:pf24e796773','pf24e796773','interpellation','2026-04-30','{"councillors": ["陳淑惠"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 136, "session": "第20屆第7次定期會", "term": 20, "title": "消防分隊經費編列不足，向議員爭取配合款，本席連續兩年在 1 月底 2 月初開立小型工程配合款補助消防分隊，接獲回覆經費已用罄。有關議員小型工程款之應公平分配，建請編足分隊之預算。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:136:3:pf24e796773','pf24e796773','interpellation','2026-04-30','{"councillors": ["陳淑惠"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 136, "session": "第20屆第7次定期會", "term": 20, "title": "警察在執法的過程中自身安全非常重要，也要顧及民眾的安全，執法過程亦應守法。如果民眾拍照蒐集警察為開罰單而違規之事證，該檢舉是否有效？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:10:pf24e796773','pf24e796773','interpellation','2026-05-04','{"councillors": ["陳淑惠"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "農地農用轉為綠能設施發電，建議縣府多輔導農民法條的認知。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:0:pf24e796773','pf24e796773','interpellation','2026-05-11','{"councillors": ["陳淑惠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "1. 南投縣目前堆積垃圾多少噸？垃圾外運處理一噸要多少錢？一年要多少錢？2. 南投興建焚化爐完成後，一年可省下多少錢？3. 請局長說明焚化爐營運廢水零排放整個安置過程為何？4. 名間鄉為苶葉故鄉，農民會憂心焚化爐興建後會汙染農作物，這會發生嗎？5. 名間鄉掩埋場最近有自燃現象，產生的汙染也對空氣影響蠻大的。6. 焚化爐興建完成後，南投縣 32 萬噸堆置垃圾要多少可以處理完？7. 要盡快推動家庭式廚餘機，讓南投縣環境會更好。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:4:pf24e796773','pf24e796773','interpellation','2026-05-12','{"councillors": ["陳淑惠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "本縣幅地大都屬於山嶺丘陵地形，中央政策要劃設人行道時，勢必會壓縮車道面積而變狹小，建請審慎研討。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:163:4:pf24e796773','pf24e796773','interpellation','2026-05-12','{"councillors": ["陳淑惠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 163, "session": "第20屆第7次定期會", "term": 20, "title": "大眾運輸無法到達的偏遠地區，建請規劃幸褔巴士，更可以造褔偏遠鄉親民眾及年長者。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=163','2026-10-15T03:46:11Z');
