INSERT INTO "fact" VALUES('ntccq:202609011615240:165:2:pf24e796773','pf24e796773','interpellation','2026-05-13','{"councillors": ["陳淑惠"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 165, "session": "第20屆第7次定期會", "term": 20, "title": "1.本縣多處無自來水可用，係囿於法令規定無法取得接水證明。接水用電證明應由公所或縣府核發？有些公所會看人開立證明，一直拿不到接水證明者，能否請縣府開立？2.部分公所因承辦人更迭，未掌握法令異動。請縣府行文各鄉鎮市公所，重申自來水延管及無自來水地區住戶申請自來水相關規定已放寬。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=165','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:165:3:pf24e796773','pf24e796773','interpellation','2026-05-13','{"councillors": ["陳淑惠"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 165, "session": "第20屆第7次定期會", "term": 20, "title": "就教有關信義鄉同富村灌溉飲用水管線汰換工程，所需經費約 70 至 80 萬，是否給予補助？並請注意更換使用之管線材質。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=165','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:165:4:pf24e796773','pf24e796773','interpellation','2026-05-13','{"councillors": ["陳淑惠"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 165, "session": "第20屆第7次定期會", "term": 20, "title": "有關縣府將輔導協助有製酒意願農民依規定取得製酒許可執照，目前辦理進度。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=165','2026-10-15T03:46:11Z');
