INSERT INTO "fact" VALUES('ntccq:202606090806090:157:6:pf24e796773','pf24e796773','interpellation','2025-10-14','{"councillors": ["陳淑惠"], "dept": "地政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 157, "session": "第20屆第6次定期會", "term": 20, "title": "有關農地農用相關規定建請中央修正法令，以利人民未來辦理繼承、買賣過戶更加簡便。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:160:4:pf24e796773','pf24e796773','interpellation','2025-10-15','{"councillors": ["陳淑惠"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 160, "session": "第20屆第6次定期會", "term": 20, "title": "1. 本縣舉辦許多大型活動，許多實際經驗的累積，感謝警察局團隊的付出。2. 建請警察局邀請監理單位宣導交通號誌、標線或罰則的宣導，讓民眾可以對法令有更清楚的認識。3. 員警的執法必須合理並且注意雙方的安全，不要讓民眾有被搶劫的感覺。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=160','2026-10-15T03:46:11Z');
