INSERT INTO "fact" VALUES('ntccq:202606090806090:165:10:pf24e796773','pf24e796773','interpellation','2025-10-16','{"councillors": ["陳淑惠"], "dept": "交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 165, "session": "第20屆第6次定期會", "term": 20, "title": "跟縣民宣導標誌標線用途，讓縣民可以遵守交通規則。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=165','2026-10-15T03:46:11Z');
