INSERT INTO "fact" VALUES('ntccq:202606090806090:170:0:pf24e796773','pf24e796773','interpellation','2025-10-17','{"councillors": ["陳淑惠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 170, "session": "第20屆第6次定期會", "term": 20, "title": "1. 校事會議是由哪個單位所訂定的？其組成的委員及經費來源？學校有編列經費嗎？2. 校事會議是針對教師嗎？老師可以申訴嗎？申訴管道是如何？會不會有矯枉過正情事？學校可否要求學生轉學？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:170:1:pf24e796773','pf24e796773','interpellation','2025-10-17','{"councillors": ["陳淑惠"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 170, "session": "第20屆第6次定期會", "term": 20, "title": "建請擴大心理健康諮詢的年齡層，也讓 45 歲以上的人可以找心理師諮商，並向中央再爭取更多的經費。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:205:0:pf24e796773','pf24e796773','interpellation','2025-11-03','{"councillors": ["陳淑惠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 205, "session": "第20屆第6次定期會", "term": 20, "title": "1.去年度共有多少團體申請補助參觀其他縣市焚化廠進行環境教育？成效如何？民眾認同度是否達標？明年是否續辦環境教育補助？2.環保團體因國慶當天焰火施放後煙霧不散，質疑本縣不宜興建焚化廠，請說明國慶焰火施放後產生的煙霧和未來焚化廠焚燒垃圾後產生的煙霧有何不同？3.本縣焚化廠將建置於名間鄉新民村，是否會影響周邊的茶葉、農作物？4.請說明未來焚化廠產生之廢水處理情形。5.目前本縣垃圾外運其他縣市焚燒後產生的底渣，是否需載運回本縣再利用於公共工程？未來自有焚化爐的底渣將如何處理及再利用？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=205','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:0:pf24e796773','pf24e796773','interpellation','2025-11-04','{"councillors": ["陳淑惠"], "dept": "各局處", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "有些單位的施政報告每年的工作計劃都寫一樣，請縣府局處長應用心編寫，盡力達成目標。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:1:pf24e796773','pf24e796773','interpellation','2025-11-04','{"councillors": ["陳淑惠"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "1. 社勞局輔導社區參加全國金卓越社區選拔成績亮眼，縣長更宣布加碼社區評鑑的獎勵金，希望未來能夠更多輔導社區參加評鑑。2. 全年起 65 歲以上健保費補助，是不是確定會實施？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:2:pf24e796773','pf24e796773','interpellation','2025-11-04','{"councillors": ["陳淑惠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣各國中小的 5 人制足球參賽成績亮眼，目前水里鄉已經有三座風雨球場，建請教育處向中央爭取一座多功能的室內球場。2. 學校的廚工的薪資待遇如何？目前學生 200人以上配一位廚工，工作吃重，建請縣府檢討。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:215:1:pf24e796773','pf24e796773','interpellation','2025-11-05','{"councillors": ["陳淑惠"], "dept": "建設社政", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 215, "session": "第20屆第6次定期會", "term": 20, "title": "各鄉鎮活動中心領照問題，請縣府輔導讓其合法化。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=215','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:215:2:pf24e796773','pf24e796773','interpellation','2025-11-05','{"councillors": ["陳淑惠"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 215, "session": "第20屆第6次定期會", "term": 20, "title": "1.推動智慧觀光低碳旅遊，南投縣觀光發展細部計劃，水里鄉水里溪景色很美，從之前到現在縣府都沒有在水里溪辦過活動，希望可以跟在地公所與農會聯合辦活動。2.建議在水里溪辦理水舞活動，結合玩水里玩水嘉年華。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=215','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:215:3:pf24e796773','pf24e796773','interpellation','2025-11-05','{"councillors": ["陳淑惠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 215, "session": "第20屆第6次定期會", "term": 20, "title": "災修工程案件提報，請縣府全力支持。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=215','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:215:4:pf24e796773','pf24e796773','interpellation','2025-11-05','{"councillors": ["陳淑惠"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 215, "session": "第20屆第6次定期會", "term": 20, "title": "自來水接水證明自治條例有修改放寬，請建設處多向水利署申請補助讓自來水管線延伸。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=215','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:119:0:pf24e796773','pf24e796773','interpellation','2025-05-26','{"councillors": ["陳淑惠"], "dept": "財政警察", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 119, "session": "第20屆第5次定期會", "term": 20, "title": "1. 中央刪減近 35 億的補助款，衝擊許多縣政工作，許縣長第一時間馬上提出對策，讓縣民安心，希望財主單位能夠多給縣長支持。2. 北大國小前發生重大車禍，讓政府下修高齡駕駛者年齡到70歲，希望警察局能夠向上反應除了年齡外，更應該納入其辨識能力及體能的考量。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=119','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:2:pf24e796773','pf24e796773','interpellation','2025-05-27','{"councillors": ["陳淑惠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "1. 災修工程發包延宕，要如何檢討改善？2. 投147線水里鄉段拓寬工程進度如何？3. 縣道兩旁雜草要定期清理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:3:pf24e796773','pf24e796773','interpellation','2025-05-27','{"councillors": ["陳淑惠"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "酪梨可以申請農業補償嗎？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:126:4:pf24e796773','pf24e796773','interpellation','2025-05-28','{"councillors": ["陳淑惠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 126, "session": "第20屆第5次定期會", "term": 20, "title": "建興焚化爐是全縣縣民所期待的，南投縣長期以來都須仰賴其他縣市幫忙焚燒垃圾，如果縣府要做民調，應全縣性的民調調查，並日後以科學數據、理性誠意、回饋機制來讓民眾安心。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=126','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:150:0:pf24e796773','pf24e796773','interpellation','2025-06-09','{"councillors": ["陳淑惠"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 150, "session": "第20屆第5次定期會", "term": 20, "title": "統刪地方補助款，導致縣政府的社會福利政策被迫喊停，呼籲縣民投下罷免反對票。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=150','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:150:1:pf24e796773','pf24e796773','interpellation','2025-06-09','{"councillors": ["陳淑惠"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 150, "session": "第20屆第5次定期會", "term": 20, "title": "安養機構的床位一位難求，本縣核定床位1700多位，但是入住數600多位而已，建請縣府要求機構必須盡速聘足照顧人力，避免空床閒置。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=150','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:150:2:pf24e796773','pf24e796773','interpellation','2025-06-09','{"councillors": ["陳淑惠"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 150, "session": "第20屆第5次定期會", "term": 20, "title": "1. 長照服務普及率與服務品質如何？長照站的設置與使用效益？2. 托嬰及托育服務的量能與品質是否滿足縣民需求？3. 建議將水里鄉玉峰國小活化成長照站及托育中心。4. 居家照護督導員督導訪視應該合乎人情，不要流於形式。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=150','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:150:3:pf24e796773','pf24e796773','interpellation','2025-06-09','{"councillors": ["陳淑惠"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 150, "session": "第20屆第5次定期會", "term": 20, "title": "新冠疫情又開始流行，希望衛生局能宣導縣民保持良好衛生習慣。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=150','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:5:pf24e796773','pf24e796773','interpellation','2025-06-09','{"councillors": ["陳淑惠"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "原民鄉也有許多漢人居住，縣府允諾的災修工程可以被部落會議推翻？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:5:pf24e796773','pf24e796773','interpellation','2025-06-10','{"councillors": ["陳淑惠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "1. 民意為重、環境為本。南投縣垃圾焚化廠土地取得問題，有取得合適的土地嗎？2. 丹麥、法國的焚化爐美輪美奐、美麗又環保，建議南投縣政府參考，要結合在地特色興建。3. 省道縣道，道路二旁都堆置廢棄車輛，影響市容，請相關單位處理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:155:0:pf24e796773','pf24e796773','interpellation','2025-06-10','{"councillors": ["陳淑惠"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 155, "session": "第20屆第5次定期會", "term": 20, "title": "雙十節煙火施放地點今年在南投縣，請問縣長要選在南投那裡？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:5:pf24e796773','pf24e796773','interpellation','2025-06-11','{"councillors": ["陳淑惠"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "縣府幸褔巴士2.0計畫，透過預約接送服務，滿足偏鄉長者的交通需求，減少高齡者自行駕車或騎機車的風險，並於學校、社區、超商皆可設點，且收費最高75元，並於7月試辦，9月正式啟動。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:6:pf24e796773','pf24e796773','interpellation','2025-06-11','{"councillors": ["陳淑惠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "1. 學校有相關問題的孩子，是要轉校或是留校輔導？2. 家庭教育中心是否與學校、社區結合辦理活動？辦了幾場？成效如何？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:130:8:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-29','{"councillors": ["吳棋楠"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 130, "session": "第20屆第7次定期會", "term": 20, "title": "1.南投與宜蘭地理環境、人文條件類似，建請參採宜蘭傳藝園區的作法，尋覓全新的地點或與中央溝通設在中興新村，提供藝術家創作與青年創業舞台。2.就教管制考核科，一般公文辦理時效，逾時辦理是否有相關懲處？3.有關大眾汽車教練場一直有淹水的問題。該案是否已結案？是否有繼續列管追蹤？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:131:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-29','{"councillors": ["吳棋楠"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 131, "session": "第20屆第7次定期會", "term": 20, "title": "1.南投殯儀館附近公墓遷葬後規劃為殯葬園區，因緊鄰南投市區、社會住宅等，勢必影響市容，建請以都市計畫角度進行討論，將該地點改建為公園供南投市民使用。2.許多宮廟因早期漏未辦理土地登記，因此登記到公所名下，請協助有類似情形且有意合法化的寺廟以合理價格買回土地，以利後續辦理寺廟登記。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=131','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:131:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-29','{"councillors": ["吳棋楠"], "dept": "地政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 131, "session": "第20屆第7次定期會", "term": 20, "title": "請盤點測量用車輛，若已超過使用年限，建請逐年編列經費予以汰換，以保障公務人員生命財產安全。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=131','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:134:4:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-30','{"councillors": ["吳棋楠"], "dept": "稅務", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "有關農地農用與香菇寮認定問題，希望房屋稅科在認定方面能更加彈性。本縣是農業縣，農民不容易，不應以過高標準約束，請稅務局檢討。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:134:5:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-30','{"councillors": ["吳棋楠"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "有關善心人士或社團捐贈救護車、復康巴士等，建請設計一套完整的表格，讓多人合資捐贈的民眾順利拿收據扣抵個人綜合所得稅。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:134:6:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-30','{"councillors": ["吳棋楠"], "dept": "主計", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "114 年決算收支賸餘還有 19 億，能否研議本縣 40 萬縣民每人發放 4,000 元（約需 16億），增加縣民福利？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:135:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-04-30','{"councillors": ["吳棋楠"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 135, "session": "第20屆第7次定期會", "term": 20, "title": "1.就教交通隊，近日南投市文化路標線改劃，造成車道縮減、機車撞到電線桿等問題。會勘時警察局、交管所、市公所都在場，為何卻畫出不合理的標線？2.南投市許多狹小道路被畫上雙黃線，民眾買東西短暫違停，後車閃避時跨越雙黃線被檢舉達人錄影。違停要警察到場才能開單，但跨越雙黃線卻可直接檢舉，是否合理？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=135','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-04','{"councillors": ["吳棋楠"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "農地休耕時是否要符合農地農用?"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-04','{"councillors": ["吳棋楠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "1. 軍功里大眾汽車訓練場近來常淹水，為什麼預算書沒編購地經費來規劃滯洪池？2. 外轆排水進度到那裡了？用地變更開始進行了嗎？土地面積多少？周邊的環境可以規劃好。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-04','{"councillors": ["吳棋楠"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "新規劃美術館跟表演藝術中心進度到那裡了？地點在那裡？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:139:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-04','{"councillors": ["吳棋楠"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 139, "session": "第20屆第7次定期會", "term": 20, "title": "松嶺之星何時可以完工？營運第一次招商無人投標，第二次是什麼時候招商營運？周邊交通有改善嗎？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:142:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-05','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 142, "session": "第20屆第7次定期會", "term": 20, "title": "1. 本縣運動會成績表現優異，有哪一部分是處長認為還需要努力的？2. 去年本縣國中會考成績達到 5A 只有 146 人，是歷年來最少的，今年可以提升多少？3. 建請教育處的增 A 減 C 計畫，增列給予教師獎勵金？4. 建請訂定國中生手機統一保管方案。5. 本縣國小畢業生為什麼都跑到大都市去？顯示國中 S 型分班應該做些調整，給予學生能夠有好的學習環境。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=142','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:142:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-05','{"councillors": ["吳棋楠"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 142, "session": "第20屆第7次定期會", "term": 20, "title": "1. 國立中興大學在中興新村南核心大學城的重大工程：循環經濟研究學院一館、南投分部循環經濟研究大樓、學人宿舍整修、松園 12 館及 2館整修等統包工程，現在進度為何？2. 美術館、表演中心人員編制如何？經費 35 億興建打造一個文化城，請詳細規劃、縝密討論。3. 建請中興新村可以進駐美術、書法家等，以增進藝文文化氛圍。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=142','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:142:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-05','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 142, "session": "第20屆第7次定期會", "term": 20, "title": "縣府所興辦公共建設召開的會議，為什麼議員不能参加？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=142','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:148:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-06','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 148, "session": "第20屆第7次定期會", "term": 20, "title": "1. 焚化爐預定用地地目變更是否完成？且聯外道路未取得水利署代管土地的同意，即進行拓寬工程，這樣合乎程序嗎？2. 名間是全台重要茶鄉，茶葉種植面積約 2,200公頃，不能與台北木柵包種茶區 20 多公頃旁也有焚化爐作為類比，若未來因土地變更問題，導致焚化爐無法設置，縣府目前已投入約 1 億5,800 萬元購地及規劃費用，恐淪為沉沒成本。3. 環評範疇界定會議不應流於形式，應針對替代方案進行實質討論，而非只聚焦單一主方案。4. 焚化廠用地是動支哪個基金經費？可以不經議會審查同意嗎？5. 焚化爐預定地與八寶圳農田水利灌溉水源距離是多少？是否會影響水質？6. 請借鏡雲林縣林內焚化爐前車之鑑，勿重蹈覆轍。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=148','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:152:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-07','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 152, "session": "第20屆第7次定期會", "term": 20, "title": "1.處長是否知道電費帳單上「功率因數」所指為何?2.建議找一所學校採購小型儲電器先行試用，由學校向台電申請兩段式電價，晚上電價大約只有三成，利用該時段將電存至儲電器，白天再供給學校使用，藉此提升用電功率因素，節省電費。3.舊議會將改建為南投樂活運動館，原規劃停車空間不足，建請檢討改善。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=152','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:153:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-07','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 153, "session": "第20屆第7次定期會", "term": 20, "title": "1.就教有關以廢棄物清理基金，購買廢棄物清理廠興建地點土地之疑義。2. 如果採垃圾費隨袋徵收，依照台北市過去的經驗，垃圾可以減量多少？建議本縣可先採垃圾費隨袋徵收，如採取後垃圾大幅減量，是否還需要焚化廠？3.本縣焚化廠建置後，局長是否能確保絕不收外縣市垃圾的承諾？4.本縣掩埋在地下的垃圾量有多少？5. 名間鄉新民村焚化廠興建預定地，以往逢豪暴雨經常會淹水，將如何因應？6.茶葉為名間鄉主要農作物，不要因為焚化廠的設置造成名間鄉經濟產業衰敗。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=153','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:154:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2026-05-07','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 154, "session": "第20屆第7次定期會", "term": 20, "title": "可否至國道南投休息站取締車聚噪音？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=154','2026-10-15T03:46:11Z');
