INSERT INTO "fact" VALUES('ntccq:202606090806090:157:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-14','{"councillors": ["吳棋楠"], "dept": "地政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 157, "session": "第20屆第6次定期會", "term": 20, "title": "1.能否協助覓得疏濬土石堆置土地，讓貓羅溪疏濬土壤有放置處。2.名間鄉焚化爐用地徵收補償標準非常低，縣府是否有協助解決的方式？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:157:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-14','{"councillors": ["吳棋楠"], "dept": "新聞", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 157, "session": "第20屆第6次定期會", "term": 20, "title": "處長認為茶葉博覽會一心二夜演唱會辦得如何？參與人數？明年度新聞及行政處增編 1,000多萬經費，期待邀請知名韓國團體前來表演，藉此讓本縣 13 鄉鎮旅館皆客滿，增加觀光收入。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=157','2026-10-15T03:46:11Z');
