INSERT INTO "fact" VALUES('ntccq:202606090806090:161:6:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-15','{"councillors": ["吳棋楠"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 161, "session": "第20屆第6次定期會", "term": 20, "title": "國慶煙火疏散，在中興路及東閔路的交通疏散情形不順，請問警察局有沒有檢討改善？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=161','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:8:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-16','{"councillors": ["吳棋楠"], "dept": "交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "1. 台中捷運橘線延伸到南投進度如何？2. 南投交管所人數太少？要發展南投觀光，交通是很重要的，建議縣府把交管所升格為交通處。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:164:9:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-16','{"councillors": ["吳棋楠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 164, "session": "第20屆第6次定期會", "term": 20, "title": "會勘大眾駕訓班抽水站後，目前規劃抽水機進度如何？是否可以加大抽水機的噸數？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=164','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:168:4:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-17','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 168, "session": "第20屆第6次定期會", "term": 20, "title": "國慶焰火這次在南投縣舉辦，煙火施放造成煙霧瀰漫嚴重的空污；相對的名間焚化爐是否也會造成空污的問題。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=168','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:168:5:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-17','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 168, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣幾十年來未設立舞蹈班，請教育處評估可否設置。2. 中興、三光國中棒球隊學生畢業後到哪裡去了？建議教育處能與縣內高中協商設立棒球隊，幫學生找到出路。3. 校園檢舉案件太多，校事會議召開過於頻繁，影響教師及學生權利，是不是可以先做溝通協調，了解案情輕重緩急，以減少冗長的會議，降低學生的傷害及教師的權益。4. 高中會考南投縣的成績退步很多，教育處的增 A減 C 沒有達到目標，請再加強提升高中會考成績。5. 中興國中數理資優班已開辦了幾年？據了解已開設超過 30 年，而目前這幾年是代課老師來教授數理課程，請補足專任的數理師資。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=168','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-23','{"councillors": ["吳棋楠"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "南投縣舉辦國慶焰火及茶博大型活動交通是很重要的，請問交管所有沒有可能升格為交管處。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-23','{"councillors": ["吳棋楠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "軍功里大眾駕訓班附近易淹水，有沒有可能再增設固定式抽水機？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-23','{"councillors": ["吳棋楠"], "dept": "新聞行政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "韓團來南投表演有可能嗎？如何請五月天樂團來南投，有可能嗎？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:182:4:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-23','{"councillors": ["吳棋楠"], "dept": "教育新聞行政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "1. 國土署有補助南投市平和國小人行道工程，請問現有的樹木會移除嗎？2. 學校的校事會議可否成立專責單位執行？是否先用調解的後再送校事會議？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-27','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "1. 建請縣長重視及支持在南投縣國中小能設立舞蹈班。2. 樂活運動館規劃情形及進度如何？三和游泳池是否也在這計畫中？3. 樂活運動館佔地有多大？停車格有多少位？二千坪的土地只有 6、70 個停車格，需求夠嗎？為什麼規劃的時候不能考量更多？考量提供給縣府員工停車，可以再增加停車位嗎？4. 救國團標到樂活館的權利金有多少？10 年 1 千萬，1 年只要 100 萬，平均月租只有 8 萬元，政府花 5 億的經費，收益的權利金和租金不符比例原則，這樣合理嗎？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-27','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "1. 空氣的污染源來自台中的火力發電廠和雲林六輕工業區，造成本縣天空一片灰濛濛，現在焚化爐要設在名間鄉新民村，是否我們的天空以後是灰色的空污。2. 焚化爐設在名間鄉的新民村，有什麼回饋給新民村的村民？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-27','{"councillors": ["吳棋楠"], "dept": "地政", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "目前台灣哪裡還有在辦理公地放領的政策？請協助名間鄉公地放領回歸給新民村村民。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:4:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-27','{"councillors": ["吳棋楠"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "縣府是否有可能再推動辦理沙雕藝術節？請研究辦理。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:186:5:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-27','{"councillors": ["吳棋楠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 186, "session": "第20屆第6次定期會", "term": 20, "title": "1. 猫羅溪的疏浚如何與中央共同推動？2. 經濟部水利署第三河川分署為什麼不願辦理疏浚？3. 針對疏浚的土石置放地點，請訂定自治條例來規範。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=186','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:191:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-28','{"councillors": ["吳棋楠"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 191, "session": "第20屆第6次定期會", "term": 20, "title": "就教有關南投市三塊厝排水口設置自動匣門疑義，必要時應加設抽水機以解決平和里淹水問題。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=191','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:191:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-28','{"councillors": ["吳棋楠"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 191, "session": "第20屆第6次定期會", "term": 20, "title": "長照交通接送特約業者集中在南投市、草屯鎮等市區，如遇有偏遠鄉鎮民眾申請派車，業者必須耗費大半天時間及更多油資遠從市區發車至偏鄉接送民眾，縣府對此是否有解決或補償方案？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=191','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:191:4:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-10-28','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 191, "session": "第20屆第6次定期會", "term": 20, "title": "有關南投市樂活運動館房屋租金計算標準應符合相關規定。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=191','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:119:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-05-26','{"councillors": ["吳棋楠"], "dept": "財政警察消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 119, "session": "第20屆第5次定期會", "term": 20, "title": "1. 因應預算困窘，各單位如有追加減預算的需求，請縣府確實依需求盡速提出。2. 外縣市有導入檢舉案件簡訊提醒功能，請縣府評估是否可行？3. 為避免類似新光三越氣爆案發生，請縣府加強落實公共使用建築物的消防設備安檢。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=119','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-05-27','{"councillors": ["吳棋楠"], "dept": "工務交管", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "1. 為什麼最近南投市區 8 米以下巷道路畫雙黃線？有什麼原因嗎？2. 南投國小、平和國小周邊道路改善，讓學生上下學更安全。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:125:2:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-05-28','{"councillors": ["吳棋楠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 125, "session": "第20屆第5次定期會", "term": 20, "title": "1. 拜託請校長與老師、家長、志工、警察局等共同研討協商來讓交通更安全。2. 中興國中的桌球班招生及比賽成績如何？桌球訓練場地在該校活動中心地下室，其高度、空間不足如何改善？請向中央爭取經費來改善。3. 縣內國中小參加科展比賽，縣府是否有給予補助？每位老師及學童付出心血及智慧的努力很多，不應只有得獎才有獎勵金。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=125','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:125:3:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-05-28','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 125, "session": "第20屆第5次定期會", "term": 20, "title": "1. 縣府要在名間鄉設立焚化爐，有承諾名間鄉民要過半同意才會興建，是否有對名間鄉民做民調了嗎？未來會做嗎？2. 未來對茶葉產業影響，有做評估嗎？報告何時會做出來？3. 未來名間鄉設立焚化爐所產生的爐渣如何處理？是否會運至埔里處理而會造成水源污染？4.民間企業擬在埔里興建的廢棄物處理場現階段是否已進行一階或二階的環評？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=125','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-06-04','{"councillors": ["吳棋楠"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "1. 罷免案死亡連署書，是怎麼得到連署的資料？2. 連署案什麼情形才會寄查詢單？3. 南投縣選委會副總幹事與裡面職員的薪資從那裡支出？為什麼選委會職員不需要來議會備詢？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:144:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-06-05','{"councillors": ["吳棋楠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 144, "session": "第20屆第5次定期會", "term": 20, "title": "1. 垃圾掩埋場選址地點非常重要，請勿選在山溝位置點，因為山溝是水流會流經的路線。2. 焚化爐的設置除了全縣民調外，也要針對名間鄉做民意的調查；日後設立的說明會溝通的地點可以在議會辦理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:145:1:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-06-05','{"councillors": ["吳棋楠"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 145, "session": "第20屆第5次定期會", "term": 20, "title": "1. 國六通車後，中潭公路沿線商家就逐漸蕭條，建請規劃或有何方案來帶動沿線觀光。2. 建請規劃台14線草屯至埔里、魚池、日月潭自行車道。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=145','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:147:0:pdb3cfd1da4','pdb3cfd1da4','interpellation','2025-06-06','{"councillors": ["吳棋楠"], "dept": "主計財政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 147, "session": "第20屆第5次定期會", "term": 20, "title": "1. 就教主計處主任，有關主計長刪除一般性補助款的說法對嗎？2. 對於縣長6月4日向中央爭取被刪除的35億補助款表示認同。惟跟中央要經費低調一點是不是比較好？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=147','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:131:2:p8863b421c2','p8863b421c2','interpellation','2026-04-29','{"councillors": ["張婉慈"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 131, "session": "第20屆第7次定期會", "term": 20, "title": "有關老人假牙補助政策，應廣為宣傳。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=131','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:144:5:p8863b421c2','p8863b421c2','interpellation','2026-05-05','{"councillors": ["張婉慈"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 144, "session": "第20屆第7次定期會", "term": 20, "title": "新興毒品侵入校園，教育處是否有收到此類案件的通報？建請與中央連線，並與衛生、警察等單位合作，到國中小及高中職校做毒品的宣導，讓所有的學校是健康且安全的。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:170:0:p8863b421c2','p8863b421c2','interpellation','2026-05-14','{"councillors": ["張婉慈"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 170, "session": "第20屆第7次定期會", "term": 20, "title": "1. \"依託咪酯\"原為醫療用途所使用，而今卻變成新興的毒品，其是否己侵入校園內？本縣學校是否有檢測的工具器材？如何做檢測？其是否有偽裝為電子煙？2. 建議警察局應有的具體措施：（1）毒駕稽查，非隨機、非無差別攔檢。（2）情資蒐集，成立新興毒品專責偵查小組。（3）法規強化，向中央建議。（4）聯合稽查，警政、教育、衛生三方聯合行動。（5）警察局應推廣路邊唾液採樣打擊毒駕。3.對於網路平台的販賣，有無察查的機制？緝獲案件有多少？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:170:1:p8863b421c2','p8863b421c2','interpellation','2026-05-14','{"councillors": ["張婉慈"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 170, "session": "第20屆第7次定期會", "term": 20, "title": "1.教育處重點與管制建議：（1）預防教育，宣導課程，辨識訓練。（2）早期發現，輔導機制，通報系統。（3）介入輔導，心理諮商，家長協助。2.教育處應編列預算採購唾液快篩供學校應急使用。3.不定時舉辦師生新興毒品辨識訓練。4.從校園扎根，讓每一位學生認識、拒絕新興毒品。5.強化稽查能力，切斷供貨來源與流通管道。6.完善戒治資源，協助濫藥者回歸社會。7.請教育處、警察局、衛生局在短期內提出具體防制計畫，並加強落實。8.高中職校以上的學校，如何與中央配合預防？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:170:2:p8863b421c2','p8863b421c2','interpellation','2026-05-14','{"councillors": ["張婉慈"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 170, "session": "第20屆第7次定期會", "term": 20, "title": "對於管制藥品藥物的流向、流動性，是否有確實的掌握？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:172:0:p8863b421c2','p8863b421c2','interpellation','2026-05-15','{"councillors": ["張婉慈"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 172, "session": "第20屆第7次定期會", "term": 20, "title": "1. 局長你在消防領域多久了？當消防人員有保障嗎?2.要保障消防人員，建立完善制度，保險保額建議提高，保障第一線消防人員。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=172','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:172:1:p8863b421c2','p8863b421c2','interpellation','2026-05-15','{"councillors": ["張婉慈"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 172, "session": "第20屆第7次定期會", "term": 20, "title": "1. 科技守護，點亮南投，建立路燈維修二維碼標籤，縣府出錢、公所出力，南投全縣共享。2. 路燈報修不再迷路，安全更有溫度，讓南投的每一盞燈都成為守護回家的光。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=172','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:156:2:p8863b421c2','p8863b421c2','interpellation','2025-10-14','{"councillors": ["張婉慈"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 156, "session": "第20屆第6次定期會", "term": 20, "title": "1.有關國慶焰火在地居民通行證事前協調作業及發放疑義。2.日後辦理大型活動實施大面積管制，應加強地方溝通，傾聽在地居民的聲音。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=156','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:161:11:p8863b421c2','p8863b421c2','interpellation','2025-10-15','{"councillors": ["張婉慈"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 161, "session": "第20屆第6次定期會", "term": 20, "title": "1. 新聞上各縣市發生許多毒駕傷亡案件，為避免毒駕案件發生，請警察局多加查緝。2. 民眾頻繁報案檢舉，造成員警疲於奔命，被檢舉民眾也不堪其擾，建請警察局應過濾反覆報案的案件。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=161','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:168:3:p8863b421c2','p8863b421c2','interpellation','2025-10-17','{"councillors": ["張婉慈"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 168, "session": "第20屆第6次定期會", "term": 20, "title": "學校的輔導老師應具有專業的倫理規範，對於學生資料應要保密，學生在開學或轉學時不同的階段，應經當事人或監護人的同意後，資料才能移轉，保障學童不會被貼上標籤。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=168','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:199:5:p8863b421c2','p8863b421c2','interpellation','2025-10-30','{"councillors": ["張婉慈"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 199, "session": "第20屆第6次定期會", "term": 20, "title": "每年茶博吸引破百萬的人潮，但是本縣不只是茶葉出名，既然縣政府推出品味南投的認證制度，希望縣政府在舉辦大型活動時，能夠大力推廣各種南投優質好物。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=199','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:199:6:p8863b421c2','p8863b421c2','interpellation','2025-10-30','{"councillors": ["張婉慈"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 199, "session": "第20屆第6次定期會", "term": 20, "title": "許多歷史悠久的學校都種植大王椰子，但是落葉、落果容易砸傷學童，教育處要如何防範這種校園內的天然危機？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=199','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:200:0:p8863b421c2','p8863b421c2','interpellation','2025-10-30','{"councillors": ["張婉慈"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 200, "session": "第20屆第6次定期會", "term": 20, "title": "全國因為非洲豬瘟緣故，禁運禁宰 10 天，且禁止廚餘飼養，豬農在飼料負擔上相當龐大，本縣有無相關補助？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=200','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:200:7:p8863b421c2','p8863b421c2','interpellation','2025-10-30','{"councillors": ["張婉慈"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 200, "session": "第20屆第6次定期會", "term": 20, "title": "因應中央禁止廚餘餵養豬隻，本縣如何處理廚餘去化的問題？建議環保局購置廚餘傾倒裝置，保障清潔隊員的工作安全。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=200','2026-10-15T03:46:11Z');
