INSERT INTO "fact" VALUES('ntccq:202609011615240:147:3:p869f96eeda','p869f96eeda','interpellation','2026-05-06','{"councillors": ["蘇昱誠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 147, "session": "第20屆第7次定期會", "term": 20, "title": "1. 埔里地區因為焚燒廢棄物影響空氣品質，環保局受理通報了幾次？環保人員進駐埔里有多少人？請加強取締、嚴格執行。2. 雨水是可以飲用的嗎？好的水質需要土地的涵養，設置掩埋場是縣長宜居城市政策的一部分嗎？掩埋場申請案撤案是什麼時侯？請給我一個明確的時間，併請加快腳步進行。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=147','2026-10-15T03:46:11Z');
