INSERT INTO "fact" VALUES('ntccq:202609011615240:152:1:p869f96eeda','p869f96eeda','interpellation','2026-05-07','{"councillors": ["蘇昱誠"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 152, "session": "第20屆第7次定期會", "term": 20, "title": "有關送藥到府服務相關探討：1.目前特約藥局最多分佈在哪裡？偏鄉藥局較少，如何保障偏鄉長輩的權益？2.目前系統申請數由長輩自行操作或他人代辦較多?3.許多獨居長輩不識字、無智慧型手機，是否有透過里長或社工告知。？4.服務對象年齡是否有下修的機會？其他年齡罕見疾病、身障無法外出者，未來是否有機會納入服務對象。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=152','2026-10-15T03:46:11Z');
