INSERT INTO "fact" VALUES('ntccq:202606090806090:182:6:p869f96eeda','p869f96eeda','interpellation','2025-10-23','{"councillors": ["蘇昱誠"], "dept": "農業家畜農產公司", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 182, "session": "第20屆第6次定期會", "term": 20, "title": "1.之前的口蹄疫台灣損失很慘重。本次染上非洲豬瘟的豬隻特徵為何？2.南投縣養豬場有幾場？有沒有用廚餘養豬的？有沒有準備養豬場防疫檢查？有沒有與警察局合作攔查運豬的車輛？豬農知道要怎麼通報嗎？3.南投縣肉品市場有沒有收到農業部什麼消息？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=182','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:185:0:p869f96eeda','p869f96eeda','interpellation','2025-10-27','{"councillors": ["蘇昱誠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 185, "session": "第20屆第6次定期會", "term": 20, "title": "1. 花蓮馬太鞍溪堰塞湖事件、燕子口堰塞湖，縣府如何看待？2. 埔里水頭里南港溪谷大崩塌事件，堅固的建築物也抵擋不了天災人禍，桃米坑掩埋場污染水源，抽出來的水是褐色的，而有業者在埔里與魚池交界海拔 600 公尺處，申請興建廢棄物掩埋場，比桃米坑掩埋場還大 8 倍，且申請所在地是地質敏感區；縣府在推動永續發展，埔里掩埋場的設置是否能夠永續？埔里人堅決反對設置事業廢棄物掩埋場。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:185:1:p869f96eeda','p869f96eeda','interpellation','2025-10-27','{"councillors": ["蘇昱誠"], "dept": "行政", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 185, "session": "第20屆第6次定期會", "term": 20, "title": "新聞業務是縣府的化妝師，新聞行政處所操刀的新聞真實性有多高？請重視事實的真相，應要公平、公開，最重要的是信任二個字。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:185:2:p869f96eeda','p869f96eeda','interpellation','2025-10-27','{"councillors": ["蘇昱誠"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 185, "session": "第20屆第6次定期會", "term": 20, "title": "縣府的團隊螺絲是不是鬆了？有些局處不參加審查會，要議員背書，是不是自滿、看不起議員、反正議員看不懂等，請尊重議會、尊重議員，希望互相尊重。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=185','2026-10-15T03:46:11Z');
