INSERT INTO "fact" VALUES('ntccq:202512051057560:125:1:p869f96eeda','p869f96eeda','interpellation','2025-05-28','{"councillors": ["蘇昱誠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 125, "session": "第20屆第5次定期會", "term": 20, "title": "1.5月19日在新北市三峽區下課時間發生重大交通事故，校園周邊交通安全不能忽視，希望維護師生上下學安全，本縣是否有確實做交通安全宣導。2.導護老師、志工是否有提供交通安全教育訓練？並盤點各校導護安全設備。3.導護老師是否會接受急救教育研習及有否持續性的複訓？不要流於形式。4.什麼是AED？全縣國中小是否有設置？每所學校配置幾台？5.全縣國中小老師是否有AED及CPR的訓練，請擴及行政人員、導護、志工等參加 AED、CPR 等的急救教育。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=125','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:3:p869f96eeda','p869f96eeda','interpellation','2025-06-04','{"councillors": ["蘇昱誠"], "dept": "各局處", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "不要因人設事，要照顧南投縣民。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:4:p869f96eeda','p869f96eeda','interpellation','2025-06-04','{"councillors": ["蘇昱誠"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "1.健康老化的核心在於維持功能，不是只有醫療介入。2.60歲之後肌肉流失很快，長照據點應試辦長者肌力訓練。3.南投縣政府對於發展遲緩的幼兒有沒有什麼幫助？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:139:5:p869f96eeda','p869f96eeda','interpellation','2025-06-04','{"councillors": ["蘇昱誠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 139, "session": "第20屆第5次定期會", "term": 20, "title": "1. 幼兒園的兒童在語言障礙的比例有多少？疫情後應該有增無減。2. 幼兒園專業老師的配置有沒有到位？學前語言治療很重要。家長怕錯過黃金治療期。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=139','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:141:0:p869f96eeda','p869f96eeda','interpellation','2025-06-04','{"councillors": ["蘇昱誠"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 141, "session": "第20屆第5次定期會", "term": 20, "title": "埔里巧咖節已經開始了，遊客人次達10萬人，縣府給自己打幾分？下雨時停車場路面會積水，請問要如何處理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=141','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:143:0:p869f96eeda','p869f96eeda','interpellation','2025-06-05','{"councillors": ["蘇昱誠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 143, "session": "第20屆第5次定期會", "term": 20, "title": "1. 埔里有什麼大宗的農作物？茭白筍、百香果栽種的面積有多少公頃？產值有多少？水源對農業有重要嗎？2. 今天賴以為生的水源，卻要蓋垃圾掩埋場，對農業的衝擊是否會很大？3. 埔里麒麟里的里民和仁愛鄉中正村的村民，反對興建垃圾掩埋場，對日後生態、居住環境所造成的污染產生焦慮。4. SDGs 永續發展目標讓孩子認識什麼是土地與地下水污染及來源。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:147:3:p869f96eeda','p869f96eeda','interpellation','2025-06-06','{"councillors": ["蘇昱誠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 147, "session": "第20屆第5次定期會", "term": 20, "title": "就教縣長對於民間業者申請在埔里設置事業廢棄物掩埋場之看法：1. 縣長是否曾去過預定地現場？2. 該地點是否適合設置廢棄物掩埋場？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=147','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:147:4:p869f96eeda','p869f96eeda','interpellation','2025-06-06','{"councillors": ["蘇昱誠"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 147, "session": "第20屆第5次定期會", "term": 20, "title": "1. 埔里地區交通從月初迄今是否造成警力之負擔？巧咖節期間交通順暢且無爆量之情形。2. 交通、治安、反詐騙等宣傳請再加強。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=147','2026-10-15T03:46:11Z');
