INSERT INTO "fact" VALUES('ntccq:202609011615240:134:0:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-04-30','{"councillors": ["石慶龍"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 134, "session": "第20屆第7次定期會", "term": 20, "title": "魚池鄉日月村村民遭野蜂攻擊，經送醫搶救後仍不治。目前 119 通報系統中心設在南投，若偏遠鄉鎮發生急難，由中心調派救護車。要求消防局即日起，將日月村急診醫療站納入 119通報派遣 SOP，中心應同步確認救護站若有救護車，應就近優先派遣。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:143:0:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-05','{"councillors": ["石慶龍"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 143, "session": "第20屆第7次定期會", "term": 20, "title": "縣府在偏遠及山地等地區設置救護站，本席給予肯定，而救護站內是否有蜂、蛇毒血清的備品？也請消防局就救護車的部分，一併檢討改善"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:5:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-20','{"councillors": ["石慶龍"], "dept": "消防衛生", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "有關本席於第二審查會單位質詢時建議將偏鄉急診醫療站(水里、伊達邵、清境)納入 119 通報派遣 SOP，醫療站若有救護車，應就近優先派遣，提供即時就近救護一案，消防局與衛生局是否已完成協調？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:6:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-20','{"councillors": ["石慶龍"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "偏鄉及原鄉衛生所、急診醫療站是否皆有配備毒蛇、毒蜂等急救血清、藥物？或是一定要送到大型醫院才能處理？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:185:0:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-20','{"councillors": ["石慶龍"], "dept": "原民觀光", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 185, "session": "第20屆第7次定期會", "term": 20, "title": "《民宿管理辦法》與露營區主政機關為觀光處，觀光處應主動平行協助原民處，而非將原住民區塊的業務全丟給原民處，各自為政。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:185:1:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-20','{"councillors": ["石慶龍"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 185, "session": "第20屆第7次定期會", "term": 20, "title": "《財政收支劃分法》修正實施後，原先依靠中央 100%補助的計畫經費傳出將縮減，甚至歸零。若補助經費歸零，建請縣長針對原民處年度經費預算，盡量不減少且應予以增加，以彌補中央補助的缺口。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:185:2:p7ff5ea1b58','p7ff5ea1b58','interpellation','2026-05-20','{"councillors": ["石慶龍"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 185, "session": "第20屆第7次定期會", "term": 20, "title": "建議縣府規劃小規模的都會區「原住民文化住宅」。利用縣有地或國有地，爭取中央原民會或內政部經費興建，在建築規劃中融入文化傳承空間，提供原住民承租，改善其居住空間及環境。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=185','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:2:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-10-22','{"councillors": ["石慶龍"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣以農業及觀光為發展主軸，但是 113年、112 年十大觀光休憩區卻都榜上無名，縣內的交通或住宿都無法滿足遊客的需求，建請縣政府要多舉辦能夠吸引人潮的活動。2. 建請觀光處多輔導業者轉型合法化露營區，露營區經營不易，不要動不動就開罰。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:3:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-10-22','{"councillors": ["石慶龍"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "建請縣政府爭取軌道系統進到南投。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:4:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-10-22','{"councillors": ["石慶龍"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "貓羅溪、信義橋、力行產業道路等縣內許多地點，往往風災一來就發生淹水、土石流，建請縣政府要向中央爭取經費整治改善。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:126:2:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-05-28','{"councillors": ["石慶龍"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 126, "session": "第20屆第5次定期會", "term": 20, "title": "1. 社區藥局送藥到府線上申請系統，目前成效、據點及後續辦理情形。2. 衛褔部今年送藥到府計畫目前執行狀況如何？對偏遠區如魚池、信義、仁愛等鄉，沒有超過 3間藥局者如何來落實？可否涵蓋全鄉？3. 如何讓更多的藥局有意願參與送藥到府計畫的投入，發揮更好的效果。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=126','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:126:3:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-05-28','{"councillors": ["石慶龍"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 126, "session": "第20屆第5次定期會", "term": 20, "title": "1. 全縣中小學教師參加全年度的研習活動是否有落實？2. 請落實多元族群文化教育並相互尊重。3. 建請在南投開設教育學程，這樣偏鄉的代理教師就不用大老遠的跑到台中等大都會區了。4. 中小學每周 1 小時的地方語言課程並不足夠，請增設遠距離教學。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=126','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:0:p7ff5ea1b58','p7ff5ea1b58','interpellation','2025-06-02','{"councillors": ["石慶龍"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "肯定本縣推行送藥到府線上系統，請說明該服務辦理情形。偏鄉、原鄉配合的藥局較少，是否能達到服務量能？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
