INSERT INTO "fact" VALUES('ntccq:202606090806090:193:10:p4ee41a9021','p4ee41a9021','interpellation','2025-10-28','{"councillors": ["宋懷琳"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 193, "session": "第20屆第6次定期會", "term": 20, "title": "1.近期台中傳出非洲豬瘟疫情，是否因食用餿水(廚餘)而造成？2.目前因情況緊急已停止使用廚餘餵豬，請說明本縣回收廚餘的去向。掩埋廚餘處理恐有廢水汙染環境之虞；曝曬廚餘產生惡臭亦有影響環境衛生疑慮。3.請說明本縣興建焚化廠辦理進度。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=193','2026-10-15T03:46:11Z');
