INSERT INTO "fact" VALUES('ntccq:202512051057560:136:5:p4ee41a9021','p4ee41a9021','interpellation','2025-06-03','{"councillors": ["宋懷琳"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "1. 高齡駕駛事故頻傳，70歲以上長者開車換照問題，如何避免事故發生？2. 南投縣的大眾運輸佈建進度如何？3. 南投國小旁佈滿停車格，家長接送不便，許多學童被迫走到馬路上來，希望工務處在畫設停車格應多加考量。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:136:6:p4ee41a9021','p4ee41a9021','interpellation','2025-06-03','{"councillors": ["宋懷琳"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "1. 老師難當，教師遭濫訴案件頻傳，部分被校長針對的教師在校事會議中難以發聲，建議教育處能幫遭濫訴的老師聘請律師顧問，維護教師工作權益。2. 國中小校園禁止使用手機，但是老師如果不願意負手機保管責任，教育處這邊有沒有配套辦法？3.城鄉差距造成本縣雙語教育的成效不高，教育處在外籍教師聘請及課程配置上有什麼看法？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
