INSERT INTO "fact" VALUES('ntccq:202609011615240:136:5:pe563198cd8','pe563198cd8','interpellation','2026-04-30','{"councillors": ["陳玉鈴"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 136, "session": "第20屆第7次定期會", "term": 20, "title": "竹山消防分隊建築物是何時啟用？使用空間是否足夠？建議如現有建物安全係數足夠，建議在原址後方增設廳舍擴充使用空間，不予拆遷。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:147:1:pe563198cd8','pe563198cd8','interpellation','2026-05-06','{"councillors": ["陳玉鈴"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 147, "session": "第20屆第7次定期會", "term": 20, "title": "1. 建請研究是否與黑水虻業者合作，解決處理廚餘問題。2. 建請於竹山空污重點區域，設置空氣監測站，併主動前往取締。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=147','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:149:4:pe563198cd8','pe563198cd8','interpellation','2026-05-06','{"councillors": ["陳玉鈴"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 149, "session": "第20屆第7次定期會", "term": 20, "title": "1. 讓全民運動館符合全民的需求，南投館進度如何？極限館、滑板館、輪動場是否能夠如期動工及完工？2.建請縣府成立運動處，以帶動全民運動風氣及選手的培養。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=149','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:151:3:pe563198cd8','pe563198cd8','interpellation','2026-05-07','{"councillors": ["陳玉鈴"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 151, "session": "第20屆第7次定期會", "term": 20, "title": "1.原民孩童會說母語的人數比例有多少？2.羅娜國小合唱團受邀演出，應以具代表性的原住民母語歌謠為主，但縣府卻安排在 4 月 1日南投縣兒童節表揚模範兒童大會發表淨化歌曲「四維八德幸福歌」。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:156:0:pe563198cd8','pe563198cd8','interpellation','2026-05-08','{"councillors": ["陳玉鈴"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 156, "session": "第20屆第7次定期會", "term": 20, "title": "1. 竹山鎮殯葬處理困境，竹山鎮內建設生命園區改善殯葬園區不足，建議可以設置在原南投縣綠能永續環保中心再生燃料廠預定地。2. 建議縣府啟動竹山生命園區可行性評估，將原綠能中心地目更改為殯葬用地。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=156','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:157:7:pe563198cd8','pe563198cd8','interpellation','2025-10-14','{"councillors": ["陳玉鈴"], "dept": "新聞", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 157, "session": "第20屆第6次定期會", "term": 20, "title": "1.115 年度新聞宣導及媒體管理經費共增編1,000 多萬預算，需求原因為何？各大活動已經有編相關費用，是否有重覆？2.南投三大影音新聞平台內容重覆報導，成效如何？議題重覆是否造成資訊疲乏？3.建議南投人南投事、平衡報導為民發聲：(1)多追蹤重大議題的進度。(2)現有「政令節目」多是官方自述，應增加互動性提高收視率。保持新聞媒體中立原則，多面向報導。(3)請試著直播、宣導重大議題的說明會、座談會等與民對談的場合，減少因資訊落差產生的衝突。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:165:5:pe563198cd8','pe563198cd8','interpellation','2025-10-16','{"councillors": ["陳玉鈴"], "dept": "交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 165, "session": "第20屆第6次定期會", "term": 20, "title": "竹山國中小通學區人行道增設，人行道不連貫，路邊白線停車，學生被迫與車爭道，行走空間不足。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=165','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:169:5:pe563198cd8','pe563198cd8','interpellation','2025-10-17','{"councillors": ["陳玉鈴"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 169, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣內違規布條處理方案到底是什麼？南投市到名間鄉的沿路滿街都是違規廣告布條，縣府的拆貼大作戰誘因不足，民眾參意願低，目前為止參與 3 公斤換洗碗精的人數有多少？2. 目前的檢舉機制是什麼？會有什麼罰則？是否還有其他辦法改善違法布條？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=169','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:0:pe563198cd8','pe563198cd8','interpellation','2025-10-23','{"councillors": ["陳玉鈴"], "dept": "工務交管", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "1.鄉鎮的連結，道路是很重要的。主動出擊-貫穿南投交通完整性。2.台中捷運延伸到南投地區之可能性與後續分工為何？為何捷運不延伸至竹山鎮？3.南投縣軌道道路網整體規劃，2038 年整體交通網健全了嗎？4.遊客來南投怎麼移動？從南投市轉運站到竹山鎮方便嗎？5.竹山鎮紫南宮人潮即是交通網路的服務對象。6.定位南投縣交通樞紐中心功能。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:188:0:pe563198cd8','pe563198cd8','interpellation','2025-10-27','{"councillors": ["陳玉鈴"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 188, "session": "第20屆第6次定期會", "term": 20, "title": "1. 非洲豬瘟來襲，南投養豬業者準備好了嗎？縣內有執照的養豬場有多少家？2. 養豬場有不定時在稽查嗎？過去有違法排放污水、環境髒亂等設備之豬舍，應列為優先稽查對象。3. 目前有多少家養豬場使用廚餘養豬？4. 請落實人員與車輛管制，嚴禁外人隨意進出，車輛須經消毒。5. 病豬隔離，發現異常豬隻立即通報，病死豬應依規定掩埋或焚化，不可以隨意棄置。6. 鼓勵業者申請補助轉型為現代化豬舍，導入自動化設備，飼料供應、自動清洗、環境監控系統，減少人為污染，及定期辦理非洲豬瘟防疫訓練。7. 建立生物安全區域與緩衝帶，將養豬場分區管理，減少場與場間交叉感染。8. 定期採樣檢測，建立地方防疫資料庫，由縣府整合農業、環保、動物防疫所共同稽查與輔導。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=188','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:188:1:pe563198cd8','pe563198cd8','interpellation','2025-10-27','{"councillors": ["陳玉鈴"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 188, "session": "第20屆第6次定期會", "term": 20, "title": "鼓勵入籍南投縣，會不會比鼓勵生育比較快？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=188','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:192:0:pe563198cd8','pe563198cd8','interpellation','2025-10-28','{"councillors": ["陳玉鈴"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 192, "session": "第20屆第6次定期會", "term": 20, "title": "1.如何培養本縣防災力？應加強培養民間救災、防災緊急應變能力並提供訓練資源。2.建議社區開設避難包相關課程，為鄉親長輩準備避難物資。3.本縣防災地圖過於簡陋，應重新規劃。4.綜合建議：(1)培訓村里社區防災士課程。(2)增加縣內各關懷地點防災課程。(3)鼓勵民眾自組 T-Cert 自主應變隊。(4)土石流警戒區防災撤離演練。(5)加強社區宣導，確保民眾了解周遭防災施。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=192','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:4:pe563198cd8','pe563198cd8','interpellation','2025-05-27','{"councillors": ["陳玉鈴"], "dept": "防治所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "1. 流浪貓狗要如何處理？收容所有空間安置嗎？2. 惡意毒殺貓狗有違法嗎？有何對策？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:5:pe563198cd8','pe563198cd8','interpellation','2025-05-27','{"councillors": ["陳玉鈴"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "1. 極端氣候影響，竹山茂谷柑產區農損嚴重，收成不如預期，果農生計大受影響，縣府有何對策？2. 柑橘類有農災保險嗎？是否請縣府分擔補助？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:128:0:pe563198cd8','pe563198cd8','interpellation','2025-05-28','{"councillors": ["陳玉鈴"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 128, "session": "第20屆第5次定期會", "term": 20, "title": "1. 文化部對藝文館舍項目無差別凍結 30%補助款，對我們是否有影響？2. 地方文化內涵多倚靠中央補助，建請增列預算或評估設立文資維護基金。3. 南投縣文化志工如何有效的巡迴照顧各鄉鎮文化資產？4. 文化局 114 年人員是否減少？請思考未來若美術館業務，沒有足夠管理人力，要如何應付？5. 宜居城市會讓文化資產環境髒亂而放棄嗎？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=128','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:140:5:pe563198cd8','pe563198cd8','interpellation','2025-06-04','{"councillors": ["陳玉鈴"], "dept": "各局處", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 140, "session": "第20屆第5次定期會", "term": 20, "title": "縣府跨局處平台要整合。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:144:2:pe563198cd8','pe563198cd8','interpellation','2025-06-05','{"councillors": ["陳玉鈴"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 144, "session": "第20屆第5次定期會", "term": 20, "title": "1. 南投縣的垃圾空污 PM 排放是一般的1,800倍，衝破焚化爐的極限。2. 焚化爐並不是全部都燒，沒有確實分類，無法進爐，遭苗栗縣退運，未來能自律嗎？3. 如何協助各鄉鎮分類改善計畫，達到垃圾減量、資源回收增量目標？4. 訂定垃圾分類獎懲制度，減少垃圾量計畫。5. 請重視雲林、彰化縣反對聲浪，焚化爐選址爭議、水源保育、空氣污染等問題。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:144:3:pe563198cd8','pe563198cd8','interpellation','2025-06-05','{"councillors": ["陳玉鈴"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 144, "session": "第20屆第5次定期會", "term": 20, "title": "1. 建置竹山環狀路線竹山-鹿谷-溪頭-杉林溪-竹山暢通生活圈。2. 並於沿途規劃中繼站、眺望台，吸引遊客探索周邊。3.竹山大鞍往杉林溪觀光路線缺乏完整，如何發展潛力的路線，及改善投49線道。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:140:7:p3f175f21de','p3f175f21de','interpellation','2026-05-04','{"councillors": ["何勝豐"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 140, "session": "第20屆第7次定期會", "term": 20, "title": "工務處辦理工程業務有幾科？加速議員配合款時效。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=140','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:170:2:p3f175f21de','p3f175f21de','interpellation','2025-10-17','{"councillors": ["何勝豐"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 170, "session": "第20屆第6次定期會", "term": 20, "title": "1. 南投縣 10 及 20 人以下學生數的學校有多少校？2. 現在教育、老師不好做，學生人數愈來愈少，而學校的經費一年就要好幾百億，請校長、老師要有愛心，但是也不要讓老師受到委曲。3. 請教育處針對小校可以評估裁併校。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=170','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:144:6:pce66fab6ae','pce66fab6ae','interpellation','2026-05-05','{"councillors": ["蔡銘軒"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 144, "session": "第20屆第7次定期會", "term": 20, "title": "1. 教師的鐘點費去年已提高，而課後輔導鐘點費辦理情形如何？該會議在 4 月份業已召開，是否已有明確？而費用調升的 20%，是由家長或縣府支付?建請由縣府編列預算經費支應，不要讓家長來負擔，請縣府概算出課輔經費，送議會討論。2. 定點託育中心，建請增加國定例假日。3. 草屯樂活運動館進度如何？是否有將游泳考量納入規劃？何時動工？4. 日前監察院對於本縣校園體罰霸凌而教師停聘案件糾正乙節，校是會議調查是否合理？如經法院判決確定，是由縣府或校長應負賠償責任？對於濫訴往往會造成不合理，教育處應審慎處理。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=144','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:149:2:pce66fab6ae','pce66fab6ae','interpellation','2026-05-06','{"councillors": ["蔡銘軒"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 149, "session": "第20屆第7次定期會", "term": 20, "title": "1. 有關補助環保金爐及禮炮車，是否能將宗教寺廟、人民團體納入予以補助？2. 建請編列經費，可供補助購置廚餘處理機。3. 建請於草屯地區增設噪音偵測器，併加強深夜改裝車輛之取締。4. 住宅區內 24 小時營業的桌遊店，半夜時段吵雜影響居民安寧如何防治？還給民眾安寧環境。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=149','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:153:5:pce66fab6ae','pce66fab6ae','interpellation','2026-05-07','{"councillors": ["蔡銘軒"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 153, "session": "第20屆第7次定期會", "term": 20, "title": "1.少子化趨勢下，本縣營養午餐費用支出應有減少。建請研議將部分經費改為補助 0 到 6 歲每個月 500 元育兒津貼。2.建請於草屯地區設立臨托地點。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=153','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:153:6:pce66fab6ae','pce66fab6ae','interpellation','2026-05-07','{"councillors": ["蔡銘軒"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 153, "session": "第20屆第7次定期會", "term": 20, "title": "交通罰緩收入是否進入縣庫 ( 大水庫) 統籌運用？建議提高專款專用比例，將收受之罰鍰回歸運用於改善交通安全。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=153','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:4:pce66fab6ae','pce66fab6ae','interpellation','2025-10-23','{"councillors": ["蔡銘軒"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "提高生育津貼補助，讓年青人可以留在南投。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:181:5:pce66fab6ae','pce66fab6ae','interpellation','2025-10-23','{"councillors": ["蔡銘軒"], "dept": "工務交管", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 181, "session": "第20屆第6次定期會", "term": 20, "title": "1. 台中捷運延伸到南投地區之可能性期末報告結論是什麼？草屯段的部份是規劃輕軌還是捷運？2. 南投縣路邊停車有那幾個鄉鎮？要如何繳費？3. 交管所編制人數為幾人？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=181','2026-10-15T03:46:11Z');
