INSERT INTO "fact" VALUES('ntccq:202512051057560:143:2:pce66fab6ae','pce66fab6ae','interpellation','2025-06-05','{"councillors": ["蔡銘軒"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 143, "session": "第20屆第5次定期會", "term": 20, "title": "1. 草屯垃圾山原是垃圾掩埋場，從民國90年開始運作，經過20年的時間已是5層樓高的垃圾山，與鳥嘴潭相距 1公里，因此就被要求移除，而埔里的垃圾掩埋場就在其上游，有水源污染的隠憂。2. 垃圾掩埋場如果設立後，對縣府有稅收嗎？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=143','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:3:p33130c7539','p33130c7539','interpellation','2026-05-11','{"councillors": ["廖梓佑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "1.南投縣要興建焚化爐，設置地點也蠻重要的，垃圾要減量分類也要做好。2.南投縣很多鄉鎮不收廚餘，要推動家庭式廚餘機是否有困難？何時可以推動？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:4:p33130c7539','p33130c7539','interpellation','2026-05-11','{"councillors": ["廖梓佑"], "dept": "工務交管所", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "草屯鎮轉運站設置何時能完工？草屯鎮各方面條件都很好，人口慢慢增加，景點也很多。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:1:p33130c7539','p33130c7539','interpellation','2026-05-12','{"councillors": ["廖梓佑"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "特教生容易受到其他同儕的歧視與言語的霸凌，所以本席今天要特別的感謝草屯國小的老師，有這份愛心和專業的素養。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:2:p33130c7539','p33130c7539','interpellation','2026-05-12','{"councillors": ["廖梓佑"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "據中寮鄉親的反映，現在所施做的人行道排水側溝會有積水、排水性差及破損等情形，請儘速檢討改善。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:167:1:p33130c7539','p33130c7539','interpellation','2026-05-13','{"councillors": ["廖梓佑"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 167, "session": "第20屆第7次定期會", "term": 20, "title": "本縣自 4 月 1 日起補助 65 歲以上民眾健保費自付額，民眾反映 5 月份原代扣健保費的金融機構仍持續在扣款，請了解是否相關單位業務整合尚未完成？請於會後以書面答覆。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=167','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:167:2:p33130c7539','p33130c7539','interpellation','2026-05-13','{"councillors": ["廖梓佑"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 167, "session": "第20屆第7次定期會", "term": 20, "title": "1.草屯御富路整排路燈的基座都有鏤空及斑駁的狀況，請主管單位先釐清該路段的路燈是否屬於縣府的轄管範圍，並實地去了解整排路燈的實際受損情況。2.草屯往北投里方向，橫跨自立巷及投 6 線沿途路邊護欄生鏽，長期鏽蝕會造成損壞，危及行人安全，建請逐年編利預算予以改善。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=167','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:167:3:p33130c7539','p33130c7539','interpellation','2026-05-13','{"councillors": ["廖梓佑"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 167, "session": "第20屆第7次定期會", "term": 20, "title": "民眾詢問翻修 3、40 年的老屋，政府有給予補助，是否確有相關預算？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=167','2026-10-15T03:46:11Z');
