INSERT INTO "fact" VALUES('ntccq:202606090806090:207:0:p33130c7539','p33130c7539','interpellation','2025-11-03','{"councillors": ["廖梓佑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 207, "session": "第20屆第6次定期會", "term": 20, "title": "1.焚化爐的建置勢在必行，選址必須審慎；應以科學化數據告訴知民眾焚化爐不會影響周邊農業；帶民眾參訪、了解焚化爐的運作、不產生誤解，是順利地推動建置焚化爐的最好方式。2.焚化爐建置後是永續委外或是未來歸縣府所有？未來除了處理縣內垃圾，能否承載收外縣市垃圾？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=207','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:207:1:p33130c7539','p33130c7539','interpellation','2025-11-03','{"councillors": ["廖梓佑"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 207, "session": "第20屆第6次定期會", "term": 20, "title": "1.肯定縣府縣府預定明年度實施 65 歲以上長者免健保費的政策。2.目前申請敬老愛心卡人數有多少？實際使用人數及經費執行率？是否可增加其他給付充分利用。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=207','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:3:p33130c7539','p33130c7539','interpellation','2025-11-04','{"councillors": ["廖梓佑"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "愛心敬老卡目前以乘車為主，建議未來開放可以使用縣內的運動場館或游泳池的使用費，養成全民運動的習慣。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:4:p33130c7539','p33130c7539','interpellation','2025-11-04','{"councillors": ["廖梓佑", "林憶如"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "有民眾欲在中寮的中集路申請舉辦汽機車的計時賽，該路段為中寮鄉民日常使用的路段，且非合法合規的封閉賽道，不適合舉辦競速賽。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:122:3:p33130c7539','p33130c7539','interpellation','2025-05-27','{"councillors": ["廖梓佑"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 122, "session": "第20屆第5次定期會", "term": 20, "title": "1. 這幾年極端氣候影響，汙水下水道工程很重要，接管工程要更加小心，有民眾反應汙水管有倒流到屋內的情形。2. 草屯鎮汙水下水道第2期工程何時開始？管材用料有沒有含鉛？有沒有要求廠商？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=122','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:8:p33130c7539','p33130c7539','interpellation','2025-06-09','{"councillors": ["廖梓佑"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "預算問題紛紛擾擾，希望中央與地方要有智慧地把問題協調好，照顧好百姓。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:9:p33130c7539','p33130c7539','interpellation','2025-06-09','{"councillors": ["廖梓佑"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "舊有工廠辦理特定工廠登記申請請建設處盡量協助民眾，給廠方改善機會，不然退件後要重跑，耗日費時。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:152:0:p33130c7539','p33130c7539','interpellation','2025-06-09','{"councillors": ["廖梓佑"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 152, "session": "第20屆第5次定期會", "term": 20, "title": "最近重大車禍頻傳，希望工務處未來規劃道路設計時能夠多用心，讓縣民能安心出門，平安回家。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=152','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:0:p33130c7539','p33130c7539','interpellation','2025-06-10','{"councillors": ["廖梓佑"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "1. 南投縣垃圾處理問題，垃圾何去何從？事業廢棄物外運或掩埋？考驗行政首長的智慧跟決心。2. 南投縣需要有自己的垃圾焚化廠處理本縣的垃圾。3. 對於垃圾焚化廠選址的地點，縣府有沒有對附近產業的影響評估進去？4. 南投市南崗工業區有事業廢棄物焚化廠，設立的時間多久了？會不會對附近環境汙染有影響？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:1:p33130c7539','p33130c7539','interpellation','2025-06-10','{"councillors": ["廖梓佑"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "1. 社會老化的問題，台灣人口數連16月負成長，生不如死，家庭經濟影響，很多人都不敢結婚跟不敢生小孩。2. 南投縣每個鄉鎮都有長照據點，草屯有22個據點，局長你覺得夠不夠？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:158:2:p33130c7539','p33130c7539','interpellation','2025-06-11','{"councillors": ["廖梓佑"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 158, "session": "第20屆第5次定期會", "term": 20, "title": "1. 中寮鄉因交通不便、人口老化，辦理活動時未能吸引人潮，建請縣府協助中寮鄉規劃創造生機，活化13鄉鎮均衡發展。2. 草屯鎮位處與台中都會區交界，交通發達且便利，但卻不能留下觀光客，請縣府協助草屯觀光發展。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=158','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:159:5:p99f76f925a','p99f76f925a','interpellation','2026-05-11','{"councillors": ["林憶如"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 159, "session": "第20屆第7次定期會", "term": 20, "title": "1. 南投縣要在名間興建焚化爐，為什麼要選址在名間鄉？可以跟鄉親說明嗎？2. 名間鄉民對於興建焚化爐擔心有疑慮大於反對的，要多跟鄉民多宣傳降低民眾疑慮。3. 名間鄉焚化爐興建用地範圍多大？是否有用科學證據數據化？4. 嘉義縣焚化爐環境教育中心開放讓民眾參觀預約課程。5. 環境衛生為民眾所關心的，廚餘處理方面很重要。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=159','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:3:p99f76f925a','p99f76f925a','interpellation','2026-05-12','{"councillors": ["林憶如"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "1. 校園周邊改善人行道空間、增設庇護設施，未見交通更安全，勿因設計不當，造成工務的浪費，要真的去了解民眾的需求。2. 筆直的道路中線忽然變成了 S 型，用路人要如何行駛？尤其在夜間視線昏暗時，更容易造成危險。3. 道路標線劃設未因地制宜，且兩旁又劃設停車格，民眾駕駛車輛閃避行人或障礙物，往往會跨越雙黃線，而遭檢舉及罰款，造成民怨。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:157:4:p99f76f925a','p99f76f925a','interpellation','2025-10-14','{"councillors": ["林憶如"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 157, "session": "第20屆第6次定期會", "term": 20, "title": "感謝縣政府辦理國慶焰火所有工作人員，建請將活動辦理後的檢討供中央及接辦縣市作為借鏡。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:4:p99f76f925a','p99f76f925a','interpellation','2025-11-04','{"councillors": ["廖梓佑", "林憶如"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "有民眾欲在中寮的中集路申請舉辦汽機車的計時賽，該路段為中寮鄉民日常使用的路段，且非合法合規的封閉賽道，不適合舉辦競速賽。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:210:6:p99f76f925a','p99f76f925a','interpellation','2025-11-04','{"councillors": ["林憶如"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 210, "session": "第20屆第6次定期會", "term": 20, "title": "肯定社勞局在社區經營上的卓越成績，期待未來在局長輔導下讓更多的社區可以成長。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=210','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:0:p99f76f925a','p99f76f925a','interpellation','2025-11-04','{"councillors": ["林憶如"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "恭喜衛生局榮獲健康與醫療服務應用類 AI 應用卓越獎，希望未來可以與社勞局好好配合，共同為南投縣民的健康把關。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:1:p99f76f925a','p99f76f925a','interpellation','2025-11-04','{"councillors": ["林憶如"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "1. 文化局未來辦公廳舍搬去美術館後，現有辦公廳舍有什麼規劃嗎？2. 現在科技進步，小朋友使用 3C 頻繁，習慣快速地獲得資訊，希望文化局培養學童靜下心來閱讀的習慣。3. 文化局圖書館座位不足，每到假日一位難求，建請文化局未來規劃更多閱讀空間讓學生足夠使用。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:214:7:p99f76f925a','p99f76f925a','interpellation','2025-11-05','{"councillors": ["林憶如"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 214, "session": "第20屆第6次定期會", "term": 20, "title": "1.南投縣得到學習城市認證獲獎，感謝教育處的努力。2.觀光及農業結合也推動南投縣的能見度。3.衛生局也獲獎無數。4.民政處主辦這次國慶焰火很辛苦，也讓全國看見南投縣。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=214','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:214:8:p99f76f925a','p99f76f925a','interpellation','2025-11-05','{"councillors": ["林憶如"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 214, "session": "第20屆第6次定期會", "term": 20, "title": "1. 松嶺之星明年度即將啟用，請問觀光處有無規劃觀光串聯。2. 139 線是否可以規劃電輔腳踏車，可以串聯各景點旅遊。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=214','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:2:p99f76f925a','p99f76f925a','interpellation','2025-06-10','{"councillors": ["林憶如"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "肯定南投縣政府對於垃圾處理的問題。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:3:p99f76f925a','p99f76f925a','interpellation','2025-06-10','{"councillors": ["林憶如"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "1. 局長對於長照據點人員不足的問題，有何看法？有何因應辦法？2. 居家服務人員時間比較彈性，人數有變多。3. 很多新生兒家長等不到合格的保母。4. 肯定南投縣對於社區評鑑的輔導，得到好的成績。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:154:4:p99f76f925a','p99f76f925a','interpellation','2025-06-10','{"councillors": ["林憶如"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 154, "session": "第20屆第5次定期會", "term": 20, "title": "1. 南投市青年住宅的入住進度為何？還剩19戶還未有人選。協助年輕人貸款。2. 南投縣中興、南投、草屯都市計畫區的進度為何？3. 南投市八卦山土地有無都市計畫？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=154','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:158:1:p99f76f925a','p99f76f925a','interpellation','2025-06-11','{"councillors": ["林憶如"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 158, "session": "第20屆第5次定期會", "term": 20, "title": "1. 縣內大型活動每年都會吸引很多的觀光客，如燈會、茶博、巧咖節等，建請縣府辦理活動時應做好動線安排、化粧室、攤販、停車位、垃圾處理等規劃能夠美觀舒適，尤其今年因應國慶煙火的活動，提早作規劃。2. 因中興會堂周邊整修工程，茶博會場場域將受改變，是否會取消部分活動項目？3. 南投星空季活動在八卦山辦理，鄰近鄉鎮是否足夠提供住宿量？如何串連其他景點行銷南投？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=158','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:160:0:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-11','{"councillors": ["簡峻庭"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "1. 肯定環保局長為名間鄉興建焚化爐的努力付出。焚化爐一定要做到零汙染。2. 草屯之前也有一座小的焚化爐，燃燒溫度為800 多度，不符現代法規需求且處理費用太貴，目前也已停止運作。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:160:1:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-11','{"councillors": ["簡峻庭"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "本縣轄區內有多少家儲蓄互助社？是否為縣府財政處管理？有沒有經營不善情形發生？有無查到問題？儲蓄互助社沒有納入存款保險。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:160:2:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-11','{"councillors": ["簡峻庭"], "dept": "警政教育", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "南投交通問題有很大的改善空間。很多新手駕駛剛拿到駕照對於交通觀念不足，會造成行人及駕駛人的危險，請多宣導正確交通安全。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:160:3:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-11','{"councillors": ["簡峻庭"], "dept": "稅務", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "1. 房屋稅為地方稅，南投縣是否有自治條例？鋼構與非鋼構房屋繳稅標準是否一樣？可否修改本縣自治條例？2. 沒有營業的店面是否要繳營業稅？請多宣導民眾。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:160:4:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-11','{"councillors": ["簡峻庭"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "1. 補助公益團體金額為多少？一年可申請幾次？2. 社區發展協會成立縣府核准，中央有補助經費多少？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:5:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-12','{"councillors": ["簡峻庭"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "路小、路面又狹窄，如要劃設人行道，會造成民怨。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:162:6:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-12','{"councillors": ["簡峻庭"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 162, "session": "第20屆第7次定期會", "term": 20, "title": "縣內介聘教師，代課老師一定要有教師證照，否則會排擠具有教師證的流浪教師。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=162','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:163:1:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-12','{"councillors": ["簡峻庭"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 163, "session": "第20屆第7次定期會", "term": 20, "title": "1. 公共設施應全盤檢討，後續如何規劃應告訴民眾，或於一定期間內完成。2. 民間可以自辦市地重劃嗎？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=163','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:165:0:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-13','{"councillors": ["簡峻庭"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 165, "session": "第20屆第7次定期會", "term": 20, "title": "1.草屯隘寮溪排水系統行經太平路至草溪路段（行政園區預定地），兩側約幾百公尺遲未施作堤防。建請工務處立即著手進行堤防整治規劃，不要再與行政園區綁在一起，期盼能在兩三年內完成施作。2.請副縣長與水利署溝通，極力向中央爭取太平路至草溪路段堤防工程一次全面施作完成。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=165','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:165:1:p3cb312bfb9','p3cb312bfb9','interpellation','2026-05-13','{"councillors": ["簡峻庭"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 165, "session": "第20屆第7次定期會", "term": 20, "title": "中央不予補助草屯「觀心園愛心工作坊」的原因為何？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=165','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:205:1:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-03','{"councillors": ["簡峻庭"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 205, "session": "第20屆第6次定期會", "term": 20, "title": "本縣首座小型焚化爐建於草屯鎮，該焚化爐已退役，當時技術條件遠不如現在，亦無環保團體抗爭。本縣現今確實有興建焚化爐之需要，呼籲環保團體理性看待。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=205','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:205:2:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-03','{"councillors": ["簡峻庭"], "dept": "主計", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 205, "session": "第20屆第6次定期會", "term": 20, "title": "1.《財政收支劃分法》公布實施後，本縣可以獲得多少統籌分配稅款？相較於去年有何差別？2.明年度是否有編列補助 65 歲以上長者健保費用？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=205','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:205:3:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-03','{"councillors": ["簡峻庭"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 205, "session": "第20屆第6次定期會", "term": 20, "title": "1.近期非洲豬瘟爆發自鄰近的台中市，本縣有多少座養豬場？目前各養豬場防疫措施掌握情形如何？是否有先行演練可能發生情形？2.豬隻死亡保險是否持續在辦理？3.全國禁止屠宰豬隻 15 天，肉品市場應藉此期間加強廠區全面清潔消毒。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=205','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:212:0:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-04','{"councillors": ["簡峻庭"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 212, "session": "第20屆第6次定期會", "term": 20, "title": "草屯鎮太平路與中興路的槽化線設計不當，影響交通安全及順暢，上個會期反應後只改善一半，建請交管所及警察局會後辦理現場會勘。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=212','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:212:1:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-04','{"councillors": ["簡峻庭"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 212, "session": "第20屆第6次定期會", "term": 20, "title": "草屯鎮許多路口，因為交通燈號不順，造成交通阻塞，建請警察局交通隊巡邏時如發現有問題時，應記錄下來，嗣後通報交管所改善。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=212','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:212:2:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-04','{"councillors": ["簡峻庭"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 212, "session": "第20屆第6次定期會", "term": 20, "title": "這幾年發生猝死案例的頻率頻繁，但是死因都不詳，希望衛生局可以去統計並了解看看原因為何。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=212','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:215:0:p3cb312bfb9','p3cb312bfb9','interpellation','2025-11-05','{"councillors": ["簡峻庭"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 215, "session": "第20屆第6次定期會", "term": 20, "title": "1. 學生管教問及傷害問題，學生家長投訴老師時，教育處受理時是否有先把關投訴事由再召開學校校事會議。2. 教育處是否有諮商窗口輔導教師。3. 希望教育處成立法律協助窗口協助教師。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=215','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:150:4:p3cb312bfb9','p3cb312bfb9','interpellation','2025-06-09','{"councillors": ["簡峻庭"], "dept": "主計", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 150, "session": "第20屆第5次定期會", "term": 20, "title": "統刪地方補助款，本縣被刪減的項目為哪些？各項占比為多少？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=150','2026-10-15T03:46:11Z');
