INSERT INTO "fact" VALUES('ntccq:202512051057560:155:4:p3cb312bfb9','p3cb312bfb9','interpellation','2025-06-10','{"councillors": ["簡峻庭"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 155, "session": "第20屆第5次定期會", "term": 20, "title": "1. 雙十節煙火施放地點今年在南投縣，是南投建縣第一次，可以跟茶業博覽會結合，可以帶來更多的觀光人潮。2. 關稅問題會不會影響到南投的產業。請工策會成員輔導工業區廠商。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:158:3:p3cb312bfb9','p3cb312bfb9','interpellation','2025-06-11','{"councillors": ["簡峻庭"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 158, "session": "第20屆第5次定期會", "term": 20, "title": "山坡地回饋基金制度本來就不對，不合時宜，對南投縣不公平，建請農業單位向政府反應修正。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=158','2026-10-15T03:46:11Z');
