INSERT INTO "fact" VALUES('ntccq:202609011615240:160:8:pdffeb5d50f','pdffeb5d50f','interpellation','2026-05-11','{"councillors": ["黃春麟"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第9會次", "page": 160, "session": "第20屆第7次定期會", "term": 20, "title": "南投縣興建焚化爐後，清運路線的規畫為何？是否有內外部數位監控管理？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:163:2:pdffeb5d50f','pdffeb5d50f','interpellation','2026-05-12','{"councillors": ["黃春麟"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 163, "session": "第20屆第7次定期會", "term": 20, "title": "1. 無障礙交通車車上人員配置幾人？駕駛員、隨車人員是否有 SOP 處理的程序和在職訓練？2. 特教生放學回家後，若引發偏差行為，父母親照顧責任不周，教育處有何作為？或是可以輔導、安置，與社勞局相互配合。3. 瑞峰國中併校後，學生安置於哪所學校？學生的接送可以考慮幸褔巴士作為一個選項。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=163','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:163:3:pdffeb5d50f','pdffeb5d50f','interpellation','2026-05-12','{"councillors": ["黃春麟"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第10會次", "page": 163, "session": "第20屆第7次定期會", "term": 20, "title": "1. 幸褔巴士學生的搭乘率高，是否可以推動學生票專案？2. 請宣導長輩多多利用搭乘幸褔巴士，可以長輩們交通更安全。3. 建請規劃濁水溪線幸褔巴士，未來能夠有更優質的服務。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=163','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:160:1:pdffeb5d50f','pdffeb5d50f','interpellation','2025-10-15','{"councillors": ["黃春麟"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 160, "session": "第20屆第6次定期會", "term": 20, "title": "1. 警察有依照法令開單的義務，建請警局與相關單位共同檢討縣內的標線號誌的現況，避免不合理的交通現況造成民眾被罰的情形。2. 本次國慶煙火是本縣難得一見的大型活動，希望警局能夠吸收這次的經驗，未來能夠更順暢的疏導交通人流。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=160','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:207:4:pdffeb5d50f','pdffeb5d50f','interpellation','2025-11-03','{"councillors": ["黃春麟"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 207, "session": "第20屆第6次定期會", "term": 20, "title": "1.衛生局以「智慧健康雲」(南投健康樂活 APP)獲獎，目前在縣內的普及率與使用率各是多少？健康雲針對長輩居較多，有沒有預防相關的設計？2.有關兒童保健總共分為幾類？兒童生長遲緩是否有早期療育補助？3.兒童的基因檢測、代謝異常疾病，有沒有包包含在公費篩檢項目之中？4.孕產婦之胎兒基因檢測，針對罕見疾病是否有相關補助？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=207','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:211:2:pdffeb5d50f','pdffeb5d50f','interpellation','2025-11-04','{"councillors": ["黃春麟"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "有關民眾欲申請中寮的中集路舉辦汽機車的計時賽，請問該道路是否符合辦理競速賽的標準？萬一因路況發生意外，縣府是否應負責？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:118:0:pdffeb5d50f','pdffeb5d50f','interpellation','2025-05-26','{"councillors": ["黃春麟"], "dept": "財政警察消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 118, "session": "第20屆第5次定期會", "term": 20, "title": "1. 中央政府統刪 25%一般性補助款，會造成縣政什麼樣的衝擊？2. 刪減的補助款影響最大的是哪方面？3. 在社福方面的各項育兒政策及老人福利(65歲以上健保費補助)會不會有影響？4. 現在高壓的工作環境，警察局、消防局有無提供同仁心理諮商的關懷措施？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=118','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:3:pdffeb5d50f','pdffeb5d50f','interpellation','2025-06-09','{"councillors": ["黃春麟"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "溫馨巴士的補助來源為何？目前的巴士數量是否足夠服務縣民？有縣民反映溫馨巴士因為數量不足，路線上常常需要繞來繞去的載人，相望縣府車輛調度上可以再研議。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:151:4:pdffeb5d50f','pdffeb5d50f','interpellation','2025-06-09','{"councillors": ["黃春麟"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 151, "session": "第20屆第5次定期會", "term": 20, "title": "信義鄉保留地內有一平民合法取得之土地，最近因風災造成邊坡土地流失，縣長允諾修繕，但遭部落會議否決，請問原住民的部落會議的決議事項有法律效力嗎？建議原民處協調地方部落會議建立溝通平台。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=151','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:155:2:pdffeb5d50f','pdffeb5d50f','interpellation','2025-06-10','{"councillors": ["黃春麟"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第13會次", "page": 155, "session": "第20屆第5次定期會", "term": 20, "title": "1. 台灣目前興建焚化爐標準空污排放量，有辦法跟歐洲丹麥、法國焚化爐比嗎？2. 南投縣興建焚化爐經費要多少？要如何配置監控系統？3. 南投縣空氣品質檢測站設置地點在那裡？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=155','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:7:pdffeb5d50f','pdffeb5d50f','interpellation','2025-06-11','{"councillors": ["黃春麟"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "1. 如何留住教育人材？偏鄉長期教師不足，國中小學校是否有配置宿舍？宿舍屋齡老舊超過使用年限的有多少？2. 各國中小有沒有自來水設施，是否有進水塔或儲水設施？應該要滿足師生的需求。3. 依據中央法規對於偏鄉教師久任獎金是否都有實施？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:8:pdffeb5d50f','pdffeb5d50f','interpellation','2025-06-11','{"councillors": ["黃春麟"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "1. 國土計畫內縣民所承租的土地，是否都有符合天然災害補助資格？2.山坡地回饋金現在徵收6~12%，建請農業單位向政府反應修正為3~6%。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
