INSERT INTO "fact" VALUES('ntccq:202609011615240:166:0:p83677fb866','p83677fb866','interpellation','2026-05-13','{"councillors": ["李洲忠"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "環保局務必責成回饋機制，盡量補償名間鄉焚化廠周圍民眾。呼籲民眾支持焚化廠之興建。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
