INSERT INTO "fact" VALUES('ntccq:202606090806090:211:8:p83677fb866','p83677fb866','interpellation','2025-11-04','{"councillors": ["李洲忠"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 211, "session": "第20屆第6次定期會", "term": 20, "title": "校事會議讓老師疲於奔命，無法用心在教育上，建請教育處呼籲中央政府檢討現行制度設計，以解決教育現場的困境。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=211','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:166:1:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "「南投幸福 GO」以便民為主，目前兩人以上可預約派車，本項政策偏向社會福利，建議改由社勞局主責。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:166:2:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "請加快日月潭地區通盤檢討速度，日月潭林班地地目應與附近的土地相同。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:166:3:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "有關民眾違反山坡地開發規定，通常先罰款再要求補辦程序。既然可補辦程序，是否可以讓民眾先補辦程序，如仍不符水土保持法規定再予以開罰？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:166:4:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "1.有關縣道 131 線道路超車開罰爭議，該路段路面並不寬闊，駕駛人若要超車，勢必會跨越黃線。有民眾刻意拍照檢舉，警察局便隨之開出罰單。建請警方在處理此類違規事件時，應該要視路面的寬窄程度來斟酌個案，不應一接到檢舉就直接開罰。2.信義鄉公所至和社路程僅 13 公里，設置 3 個測速器是否真有必要？請警察局與信義分局重新檢討。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:166:5:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "建築", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 166, "session": "第20屆第7次定期會", "term": 20, "title": "有關騎樓停放車輛的法令規定模糊，相關建議如下：1.騎樓產權雖屬屋主，但能否停車的規範並不夠明確，導致民眾遭檢舉時，警察基於職責不得不開罰。建議建設處與警察局共同商討較為周全的辦法，以更貼近民眾立場的方式來考量與處理。2.警方接獲騎樓停車檢舉到場時，可以採取較為柔性的處理方式，直接請車主馬上將車輛開走即可，盡量避免直接開單。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=166','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:167:0:pccd9c95944','pccd9c95944','interpellation','2026-05-13','{"councillors": ["謝明謀"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第11會次", "page": 167, "session": "第20屆第7次定期會", "term": 20, "title": "1.日月潭水位下降導致觀光客銳減。水位大幅下降，碼頭的引道與浮排必須跟著降低。許多船隻本身缺乏無障礙空間，水位下降造成的陡峭高低差，讓輪椅族等身障人士要搭船遊湖變得極度不便與困難。2.縣府應重新思考水資源的分配，優先顧好南投在地縣民與觀光環境，檢討是否能停止或減少因外縣市需求而放水。3.日月潭船隻缺乏無障礙設施，但為此改造現有設施所費不貲，請研議是否有其他替代方案。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=167','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:160:2:pccd9c95944','pccd9c95944','interpellation','2025-10-15','{"councillors": ["謝明謀"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第3會次", "page": 160, "session": "第20屆第6次定期會", "term": 20, "title": "日月潭分隊的管理問題。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=160','2026-10-15T03:46:11Z');
