INSERT INTO "fact" VALUES('ntccq:202606090806090:207:2:pccd9c95944','pccd9c95944','interpellation','2025-11-03','{"councillors": ["謝明謀"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 207, "session": "第20屆第6次定期會", "term": 20, "title": "有關公所不收風景區民宿或小型業者的一般垃圾，請環保局儘速將代理清運收費之自治條例草案送至議會審議，以解決風景區的垃圾處理問題。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=207','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:207:3:pccd9c95944','pccd9c95944','interpellation','2025-11-03','{"councillors": ["謝明謀"], "dept": "消防", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 207, "session": "第20屆第6次定期會", "term": 20, "title": "1.有關水域溺水事件，打撈溺者屍體是否為消防局的責任？潛水搜救已過黃金時間不及搶救的溺水者，是否有必要？救難同時應考量警消義消等搜救人員安全，避免其發生意外。2.建請汰舊消防船隻，以保障日月潭水域安全。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=207','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:212:3:pccd9c95944','pccd9c95944','interpellation','2025-11-04','{"councillors": ["謝明謀"], "dept": "各局處", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 212, "session": "第20屆第6次定期會", "term": 20, "title": "縣府各單位表現優異，受到中央的肯定獲獎時，應該要大方地向縣民分享榮耀，一方面讓縣民了解縣府的表現，一方面鼓勵所屬。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=212','2026-10-15T03:46:11Z');
