INSERT INTO "fact" VALUES('ntccq:202606090806090:214:6:pccd9c95944','pccd9c95944','interpellation','2025-11-05','{"councillors": ["謝明謀"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 214, "session": "第20屆第6次定期會", "term": 20, "title": "花蓮縣有辦理太平洋國際龍舟賽，那南投要善用日月潭公開水域辦理大型國際性活動，讓南投縣可以國際化，製造商機。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=214','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:0:pccd9c95944','pccd9c95944','interpellation','2025-06-11','{"councillors": ["謝明謀"], "dept": "財政", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "縣府負債從91億至還債賸餘30億，撙節支出顯現出成效，對於明年的財劃法，縣府原計畫補助65歲以上老人健保，有辦法負擔嗎？建請以民眾褔祉為優先。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:1:pccd9c95944','pccd9c95944','interpellation','2025-06-11','{"councillors": ["謝明謀"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "埔里營建廢棄物掩埋場為何選址在烏溪的上游？民眾有憂慮的存在，請縣府審慎的嚴謹把關。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:2:pccd9c95944','pccd9c95944','interpellation','2025-06-11','{"councillors": ["謝明謀"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "水里至信義民和路段，台16線能夠拓寬改善，讓鄉親出入更安全。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:3:pccd9c95944','pccd9c95944','interpellation','2025-06-11','{"councillors": ["謝明謀"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "對於信義鄉發生斷電後再送電時，常造成鄉民家中電器用品損壞，建請台電公司於水里和信義鄉中間設置變電站，讓民眾用電無虞。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:157:4:pccd9c95944','pccd9c95944','interpellation','2025-06-11','{"councillors": ["謝明謀"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 157, "session": "第20屆第5次定期會", "term": 20, "title": "縣府對於交通不便地方實施預約接駁服務，建請擴大到偏鄉。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=157','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:176:0:p9e7c620bab','p9e7c620bab','interpellation','2026-05-18','{"councillors": ["林友友"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 176, "session": "第20屆第7次定期會", "term": 20, "title": "虛實整合觀光，南投準備好了嗎？建請參酌嘉義市政府的\"皮克敏遊戲\"吸引人潮，運用於茶博、巧咖節等活動行銷南投。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:176:1:p9e7c620bab','p9e7c620bab','interpellation','2026-05-18','{"councillors": ["林友友"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 176, "session": "第20屆第7次定期會", "term": 20, "title": "1. 偷拍零容忍，隱私要安全，對涉及醫療隱私要稽查，防範外部人士所偷裝設的針孔，保護醫院診所的聲譽及病患的隱私。2. 請警察局、衛生局協同到診所稽查讓民眾安心，鼓勵業者自主反針孔檢測。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:177:0:p9e7c620bab','p9e7c620bab','interpellation','2026-05-18','{"councillors": ["林友友"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 177, "session": "第20屆第7次定期會", "term": 20, "title": "1. 搶救母語，搶救偏鄉小校，推動母語教學，建議成立台語實驗小學。2. 聘請專業的母語老師教授一般老師，並取得認證資格，讓學校有重生的機會。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=177','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:203:0:p9e7c620bab','p9e7c620bab','interpellation','2025-10-31','{"councillors": ["林友友"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 203, "session": "第20屆第6次定期會", "term": 20, "title": "建請打造南投縣成為匹克球運動都心。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=203','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:203:1:p9e7c620bab','p9e7c620bab','interpellation','2025-10-31','{"councillors": ["林友友"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 203, "session": "第20屆第6次定期會", "term": 20, "title": "政府普發 1 萬元即將上路，觀光處是否有掌握相鄰縣市的購物節相關活動，及加碼或延長南投旅遊好康月，以促進消費，吸引更多的遊客，把這 1 萬元留在南投，促進南投的經濟。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=203','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:203:2:p9e7c620bab','p9e7c620bab','interpellation','2025-10-31','{"councillors": ["林友友"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 203, "session": "第20屆第6次定期會", "term": 20, "title": "非洲豬瘟破口，政府只有補助公私立的攤商，但是連帶也影響到下游的廠商、商家及攤販，縣府是否有了解掌握這些情形？可否對公有市場免租金等優惠？以協助這些商家渡過難關。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=203','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:203:3:p9e7c620bab','p9e7c620bab','interpellation','2025-10-31','{"councillors": ["林友友"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 203, "session": "第20屆第6次定期會", "term": 20, "title": "1. 年輕族群罹癌率逐漸增多，思考如何降低罹癌的風險？2. 中央有補助，地方沒門路，南投縣女性生育權卡住。3. 有凍精及凍卵的需求時要去哪裡？是否可以輔導本縣的醫療機構設備，對這項政策的補助多些支持。4. 凍精/凍卵補助不孕議題，南投縣配套措施？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=203','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:203:4:p9e7c620bab','p9e7c620bab','interpellation','2025-10-31','{"councillors": ["林友友"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第14會次", "page": 203, "session": "第20屆第6次定期會", "term": 20, "title": "青年發展所建置的影音版、聲音版宣導，對青年朋友帶來很多的讚賞，請研究如何延續對青年的幫助。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=203','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:123:8:p9e7c620bab','p9e7c620bab','interpellation','2025-05-27','{"councillors": ["林友友"], "dept": "工務交管所", "doc_type": "議員建議事項", "meeting": "第4會次", "page": 123, "session": "第20屆第5次定期會", "term": 20, "title": "1. 轉運站預備好了，路網準備好了嗎？南投縣民眾為何不搭乘大眾交通工具？2. 建議 ubike進入南投縣，讓遊客更方便。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=123','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:128:4:p9e7c620bab','p9e7c620bab','interpellation','2025-05-28','{"councillors": ["林友友"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 128, "session": "第20屆第5次定期會", "term": 20, "title": "1. 垃圾清運APP全縣竟未統一，且未能有效更新，建請環保局協助各鄉鎮建置完整。2. 垃圾清運查詢系統南投縣裝設率是全國最後一名，請檢討改進。3. 垃圾清運及資源回收後端管理數據化，讓民眾查詢更能貼切生活更便利。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=128','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:161:0:p9e7c620bab','p9e7c620bab','interpellation','2025-06-12','{"councillors": ["林友友"], "dept": "觀光", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 161, "session": "第20屆第5次定期會", "term": 20, "title": "1. 就教觀光處長有關本縣各觀光景點之排名。統計方法各異，據點人流與中央補助相關，中興新村、會展中心、福興溫泉及宗教寺廟(紫南宮、石龍宮等)為何未納入考量？補助經費不僅影響觀光處，而是整個縣政府。2. 本縣七大觀光軸線分別是哪些？3. 本席曾要求修繕中寮鄉龍鳳瀑布損壞步道，風景區管理所回應非當年度重點景區，故無相關經費，置民眾安全於不顧。4. 就觀光統計出發，本縣推動觀光政策所面臨的核心問題：(1) 統計方式結構性劣勢，導致無法反映實際人次。(2) 提報據點嚴重落差，如紫南宮等實際人潮極高的熱點未納入統計，數字上無從呈現，導致本縣觀光表現長期被低估。(3) 辦理大型活動累積許多人流數據，卻未有效轉化為中央政策可見的資源基礎。5. 本縣不是沒有觀光成績，而是成績沒被看見，應該讓努力化為數據進入中央視野，爭取應有的支持與資源。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=161','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:168:1:p9e7c620bab','p9e7c620bab','interpellation','2025-06-16','{"councillors": ["林友友"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 168, "session": "第20屆第5次定期會", "term": 20, "title": "1. 讓南投也有聽障者行車友善貼紙，別讓南投縣成為聽障施的孤島。2. 打造行車友善環境，以閃燈取代喇叭，一同打造共融環境。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=168','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:179:0:p3601d7eff2','p3601d7eff2','interpellation','2026-05-19','{"councillors": ["簡千翔"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 179, "session": "第20屆第7次定期會", "term": 20, "title": "1.就教計畫處長，本縣人口僅剩 46 萬人，究竟是發生什麼事？2.生不如死(出生人數不如死亡人數)的趨勢目前無法阻擋。縣府委託暨南大學所做的「南投縣政府區域均衡發展與人口外移對策專案研究」，並與日本出水市進行比較。是否有將重點跟縣長報告，作為未來施政的方針？3.本席整理有關「南投縣政府區域均衡發展與人口外移對策專案研究」，比較南投縣與日本出水市與豐岡市提出的三個戰略如下：(1)南投山水是我們的觀光財，連結、整合、永續才是王道，單點的時代已經過去。(2)只有 13 鄉鎮的協力共創未來，單一鄉鎮單打獨鬥無法聚集成為產業聚落。(3)把縣政的財政建設主力集中在醫療、教育、交通。4.若少子化、老年化、產業外移是無法扭轉的趨勢，如何提升南投縣民的「光榮感」首當其衝。期待未來把財力集中在醫療、教育與交通。請教縣長，針對這份研究報告有何看法？5.超高齡社會來臨，南投應爭取高齡人口移居，中興新村有南投醫院的分院，宜居、對外交通也便利，爭取中興新村作為全國最大的銀髮養生聚落，盼縣府能介入整合，主導計畫。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:0:p3601d7eff2','p3601d7eff2','interpellation','2026-05-19','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "南投縣是全國唯一沒有全民運動中心的縣市，就教第一座全民運動中心目前辦理進度？盼在兩年內完成。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:1:p3601d7eff2','p3601d7eff2','interpellation','2026-05-19','{"councillors": ["簡千翔"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "AI 詐騙頻傳，公眾人物頭像被盜用，一般市井小民如何來分辨網路假資訊？警察局有什麼相對應的作法？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:2:p3601d7eff2','p3601d7eff2','interpellation','2026-05-19','{"councillors": ["簡千翔"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "有關不肖業者詐騙販賣本縣農產品，處長有何看法？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:0:p3601d7eff2','p3601d7eff2','interpellation','2026-05-21','{"councillors": ["簡千翔"], "dept": "建設環境", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1.少子化僑光國小、德興國小、富功國小預定地已沒有蓋學校，都市計劃通盤檢討什麼時候可以解編還地於民？2.空地環境衛生方面，環保局可以協助辦理嗎？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:1:p3601d7eff2','p3601d7eff2','interpellation','2026-05-21','{"councillors": ["簡千翔", "林儒暘"], "dept": "警政家畜所", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1.犬隻被綑綁，要保護毛小孩，動保警察制度是有必要的，動物防治所動保團體沒有公權力，警察沒有辦法判斷是否有虐待的事實。2.建議要有動保警察制度，公家私人協力，授權給民間團體收集證據，警力給予保護與支援。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:8:p3601d7eff2','p3601d7eff2','interpellation','2026-05-21','{"councillors": ["簡千翔"], "dept": "家畜所", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "路殺方面貓隻多於犬隻，為什麼？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:176:0:p3601d7eff2','p3601d7eff2','interpellation','2025-10-21','{"councillors": ["簡千翔"], "dept": "綜合", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 176, "session": "第20屆第6次定期會", "term": 20, "title": "1.茶葉博覽會結合國慶焰火大幅提升本縣可見度，雖有美中不足之處仍瑕不掩瑜。肯定縣長勇於接受挑戰，讓人民有參與感、光榮感。2.提醒縣府團隊，年輕人注重的議題：青年住宅、國民運動中心、大型醫院。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:176:1:p3601d7eff2','p3601d7eff2','interpellation','2025-10-21','{"councillors": ["簡千翔"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 176, "session": "第20屆第6次定期會", "term": 20, "title": "鑒於花蓮縣堰塞湖溢流，莫忘貓羅溪淹水的教訓，縣府應要求主管單位第三河川局加強貓羅溪整治、清淤疏濬。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=176','2026-10-15T03:46:11Z');
