INSERT INTO "fact" VALUES('ntccq:202606090806090:176:3:p3601d7eff2','p3601d7eff2','interpellation','2025-10-21','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 176, "session": "第20屆第6次定期會", "term": 20, "title": "就教有關平和國小學童上下學安全問題。學校附近大卡車進出頻繁，學童通行經常險象環生，應予以改善。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:177:0:p3601d7eff2','p3601d7eff2','interpellation','2025-10-21','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 177, "session": "第20屆第6次定期會", "term": 20, "title": "1.校事會議衍生問題事態嚴重，該制度導致第一線從業人員產生不想負責任的想法。校事會議廢除前，本縣有何作為？2.各校校事會議做成決議後，縣府(教育處)後續有哪些行政處置？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=177','2026-10-15T03:46:11Z');
