INSERT INTO "fact" VALUES('ntccq:202512051057560:130:0:p3601d7eff2','p3601d7eff2','interpellation','2025-05-29','{"councillors": ["簡千翔"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "1. 貓羅溪整治問題，雨季將至，淹水惡夢重演，民眾生命財產無法受到保障。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:1:p3601d7eff2','p3601d7eff2','interpellation','2025-05-29','{"councillors": ["簡千翔"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "1. 輝達將落腳北市科，南投何時會有大廠來進駐？2. 宜居城市其中一個指標就是就業率，建請南投工業區擴大建置。3. 目前加工園區及旺萊產業園區招商情形狀況如何？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:2:p3601d7eff2','p3601d7eff2','interpellation','2025-05-29','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "新北市連續3 次的重大車禍事故喚起大家對交通安全的重視，請盤點各級學校上下學交通狀況，通盤檢討，安全通學區並迅速法制化，包含設實體人行道、防護欄、庇護島、減速帶設施，讓駕駛明確認知此區特定時段需慢行。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:3:p3601d7eff2','p3601d7eff2','interpellation','2025-05-29','{"councillors": ["簡千翔"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "日前名間鄉垃圾堆置場大火，所造成的空氣污狀況，現在掌握到哪裡了？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:1:p3601d7eff2','p3601d7eff2','interpellation','2025-06-02','{"councillors": ["簡千翔"], "dept": "社勞教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "因少子化，閒置校舍增加，盤點後可釋出供作公辦民營托育空間。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:2:p3601d7eff2','p3601d7eff2','interpellation','2025-06-02','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "1. 現行國中每班學生人數以30人為原則，能否調降？2. 南投如何創造下一個陳柏清？起碼提供孩子一個可以被看見的舞台。能否研擬改善本縣唯一的棒球場？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:3:p3601d7eff2','p3601d7eff2','interpellation','2025-06-02','{"councillors": ["簡千翔"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "公費補助縣民施打帶狀疱疹疫苗，是否可行？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:4:p3601d7eff2','p3601d7eff2','interpellation','2025-06-02','{"councillors": ["簡千翔"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "本縣山區山猪吊、獸鋏氾濫，動物斷肢悲歌屢傳，依據南投縣動物保護自治條例開罰有據，但幅員廣大要如何執行？目前開罰案例有哪些？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:136:3:p3601d7eff2','p3601d7eff2','interpellation','2025-06-03','{"councillors": ["簡千翔"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "校園霸凌案件頻傳，老師害怕管教過當，教育熱誠消失，造成校園冷漠，教育處有沒有什麼辦法改善？孩子除了校園教育外，教育處更應該重視家庭教育。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:3:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "1.112 年至 114 年本縣出生人口數減幅 16%。人口數增減，除了自然出生、死亡，最重要的即「移入以及移出」。如何讓南投更加便利？交通、醫療、教育都非常重要。2.韓國出生率從 0.69 成長到 0.93，主要仰賴中央政府各項補助。3.現在年輕人不生小孩的原因：經濟及照顧問題。每個孩子都是寶貝，但年輕人亦重視自由與生活品質。政府應成為後盾，特別是「托育」問題。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:4:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "1.本縣公共托嬰中心目前收托人數僅 110 位，就教未來布建規劃及可收托人數。2.建議未來社福大樓應將托育中心納入規劃。3.每年提供多少居家托育(保母)培訓課程？改善居家托育環境，是否有相關補助？4.興建青年住宅應規劃托嬰、托育空間。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:5:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "南投在地醫院紛紛增加新型設備，應廣為宣傳周知，讓民眾了解在地醫療正在大步邁進。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:6:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "幸福 GO 將在草屯、南投上路。中興新村常有很多鄉親叫不到計程車，幸福 GO 能上路後更加便利。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:180:7:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "社政", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 180, "session": "第20屆第7次定期會", "term": 20, "title": "1.運動中心即將開工，建議將附近的縣府宿舍群空間活化，打造為商圈或聚落，讓年輕人聚集。2.國發會釋出 28 間宿舍招租，目前最大瓶頸需要有一個團隊一次進駐，否則個別青年的租金成本過高、難以負擔。建議縣府應站出來成為「媒合的中心點」，協助媒合青年發展所或青農集體進駐國發會的宿舍。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=180','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:181:0:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-19','{"councillors": ["林儒暘"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 181, "session": "第20屆第7次定期會", "term": 20, "title": "AI 詐騙手法日新月異，林前縣長與許縣長都曾被造假合成照片或 AI 影片。請縣政府宣導：購買東西有疑慮應打 165 反詐騙專線；年輕朋友要協助長輩注意網路活動。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=181','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:1:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-21','{"councillors": ["簡千翔", "林儒暘"], "dept": "警政家畜所", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1.犬隻被綑綁，要保護毛小孩，動保警察制度是有必要的，動物防治所動保團體沒有公權力，警察沒有辦法判斷是否有虐待的事實。2.建議要有動保警察制度，公家私人協力，授權給民間團體收集證據，警力給予保護與支援。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:5:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-21','{"councillors": ["林儒暘"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "學校預定地要主動還地於民，什麼時候才可以解編？要主動跟中央部會多溝通，早點解編。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:6:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-21','{"councillors": ["林儒暘"], "dept": "家畜所", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "1959 動保專線要多宣傳給民眾知道。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:187:7:p4810cd0fd3','p4810cd0fd3','interpellation','2026-05-21','{"councillors": ["林儒暘"], "dept": "文化", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 187, "session": "第20屆第7次定期會", "term": 20, "title": "孩童多閱讀可以獲得更好的成長。南投縣各鄉鎮圖書館線上借閱系統要整合方便讓民眾借閱。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=187','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:156:3:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-14','{"councillors": ["林儒暘"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第2會次", "page": 156, "session": "第20屆第6次定期會", "term": 20, "title": "1.有關國慶焰火共動員多少人力？有多少民眾進場觀賞？肯定民政處及參與人員的辛勞。2.國慶焰火係由哪個單位主責辦理？3.本縣對外交通不便，在 2、3 小時內完成焰火觀賞人潮疏散實屬不易，應藉此凸顯本縣大眾運輸工具之欠缺。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=156','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:168:2:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-17','{"councillors": ["林儒暘"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第5會次", "page": 168, "session": "第20屆第6次定期會", "term": 20, "title": "1. 建請全民運動中心能夠規劃具有複合式的功能，例如 5 人的足球等。2. 教師行政工作不減反增，造成教師的行政逃亡；學校人員的編制問題現在進行的流程到哪？什麼時候才能開始增加科室組？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=168','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:173:0:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-20','{"councillors": ["林儒暘"], "dept": "衛生", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 173, "session": "第20屆第6次定期會", "term": 20, "title": "1. 因應人口結構變遷與醫療照護需求增加，並促進健保永續，政府啟動「健康臺灣深耕計畫」，南投縣獲得 1.8 億元的經費，建請與彰化基督教醫院合作建立癌症及重症醫療中心，及協助南投署立醫院成立重症急救醫院，並擴及 13 鄉鎮市衛生所遠距醫療，以提升本縣醫療品質。2. 提升醫療系統應先把設備提升，在各鄉鎮市衛生所 20 年以上的機車，有安全上的疑慮，請衛生局編列預算汰舊換新。3. 各衛生所自動插卡報到系統，可否於今年底建置完成？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=173','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:173:5:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-20','{"councillors": ["林儒暘"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 173, "session": "第20屆第6次定期會", "term": 20, "title": "縣府在每次的活動結束後應做相關的檢討，以期許下次的活動會更完善、更好，諸如活動的細節與項目，能標示清楚及活動後的垃圾問題能夠解決。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=173','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:173:6:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-20','{"councillors": ["林儒暘"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 173, "session": "第20屆第6次定期會", "term": 20, "title": "南投縣的建案在打地基的時候往往造成鄰損，而房損問題與建商間意見不一時造成糾紛；建請縣府協助第三公證單位來介入、認證、協助等，讓雙方都可以信服，解決紛爭。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=173','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:176:4:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-21','{"councillors": ["林儒暘"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 176, "session": "第20屆第6次定期會", "term": 20, "title": "本縣各國中小校園周邊學生通行區域，是否有全盤規劃？教育處、警察局及工務處應相互配合做全面性考量。就已提出改善需求的學校先進行討論；準備在今年度施作改善設施的學校應儘速完成。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:176:5:p4810cd0fd3','p4810cd0fd3','interpellation','2025-10-21','{"councillors": ["林儒暘"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 176, "session": "第20屆第6次定期會", "term": 20, "title": "1.「老師荒」比少子化更為嚴重。退休潮造成人力斷層，新進老師獨自摸索壓力大、校事會議濫訴、教師不受尊重等問題，均是教師壓力來源。2.校事會議調查人員是否受相關專業訓練？3.管教越認真的老師被投訴的越多，投訴內容千奇百怪，目前機制無法處理濫訴、重複投訴的問題，校事會議影響老師教學意願、減低教學熱忱。4.校事會議「高受理、高啟動、高成本」，投訴者無成本。處長是否贊成廢除校事會議？建議不受理匿名案件；投訴案件不成立時，投訴者應分擔成本。學校應給予校師更多輔導、協助資源。5.對於管教無效的學生是否有解決方案？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=176','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:4:p4810cd0fd3','p4810cd0fd3','interpellation','2025-05-29','{"councillors": ["林儒暘"], "dept": "環保", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "1. 名間鄉垃圾堆置場為何會自燃？沒有任何方式可以預防自燃防止發生嗎？有什麼辦法來避免？2. 垃圾外運被退回，是因垃圾分類做的不好，請加强宣導垃圾分類。3. 垃圾外運情況是否有遇到什麼樣的的困難和問題？請讓民眾知道和了解，現在垃圾污染情形是多麼嚴重。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:5:p4810cd0fd3','p4810cd0fd3','interpellation','2025-05-29','{"councillors": ["林儒暘"], "dept": "建設", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "1. 建請擴大工業區計畫，增加就業機會。2. 招商可以朝向優良廠商及隱形冠軍的這些企業，以提高南投的就業率。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:130:6:p4810cd0fd3','p4810cd0fd3','interpellation','2025-05-29','{"councillors": ["林儒暘"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第6會次", "page": 130, "session": "第20屆第5次定期會", "term": 20, "title": "1. 今年度開始實施停車收費，而縣府所發出停車收費單確是一年前的？為什麼延遲一年後才催繳呢？會造成民眾的不便和困擾。2. 南投市、草屯鎮、埔里鎮、集集鎮等公所與民間簽約路邊收費系統，為何是縣府在做催繳的業務？縣府僅 2 位同仁負責全縣交通管理業務，而還需承辦催繳工作，業務龐雜，建請縣府和公所合作宣導民眾繳費方式或委外處理。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=130','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:133:0:p4810cd0fd3','p4810cd0fd3','interpellation','2025-06-02','{"councillors": ["林儒暘"], "dept": "社勞", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 133, "session": "第20屆第5次定期會", "term": 20, "title": "1. 去年度本縣新生兒僅2400多名，南投市約600名，公共托育資源仍遠遠不足，未來各鄉鎮公托布建方向為何？校舍如有剩餘空間亦可納入規劃。2. 有關保母收托人數規定為何？依據資料本縣保母人數甚多，為何委請保母托育的嬰幼兒人數偏少？請加強保母媒合及查核。3. 建請從醫院(產檢時)、戶政事務所(新生兒報戶口時)加強托育資源宣導。4. 請加強布建公共托育資源及媒合保母托育宣傳。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=133','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:5:p4810cd0fd3','p4810cd0fd3','interpellation','2025-06-02','{"councillors": ["林儒暘"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "雖然中央補助款受阻，仍請以本預算先行改善縣立棒球場安全防護設施。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:134:6:p4810cd0fd3','p4810cd0fd3','interpellation','2025-06-02','{"councillors": ["林儒暘"], "dept": "民政", "doc_type": "議員建議事項", "meeting": "第7會次", "page": 134, "session": "第20屆第5次定期會", "term": 20, "title": "依中選會之新聞稿，戶政資訊系統並未建置民眾簽名檔。有關近期罷免案查對，本縣選委會利用該系統查驗民眾筆跡之傳聞，請予以說明。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=134','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:183:0:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 183, "session": "第20屆第7次定期會", "term": 20, "title": "1.近年來對於族語的發展，縣府的做法有哪些重點或者是比較特別的方式？2.族語師資分為：專職族語老師、教學支援人員、一般現職教師，這三者在資格與身分上有何區別？3.語言教學應該要由老師當面教導，為何有些學校採用直播共學的方式教學？直播式的教學方式，對原住民學生初級族語認證考試是否有影響？請調查以直播共學的學生，通過認證的比例。3.中興國中班級數甚多，只有布農族的巒社群有實體族語老師，其他的語別則是直播共學。學校附近有很多原住民同胞生活，周邊應該也有一些師資。為何學校不挑選做重點發展，請實體族語老師教學？是學校沒有申請或教育處有什麼問題？4.有些原住民在平地學校就讀，在校學的是閩南語，是家長或學校的要求？還是學生本身的選擇？5.請教育處多了解少數語別的教學情形，並留意認證考試及格的比例。不只要發展族語、讓學生了解文化，亦關係日後升學考試的保障或加分。6.就教有關原住民族語師資薪資(鐘點費)之疑義7.族語教師是否可以納入師鐸獎表揚或另外辦理專屬表揚？使其備感光榮、認可與肯定。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=183','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:0:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "原民處對於族語及文化發展責無旁貸。原民處及中央原民會相關政策有何特別或需要持續加強之處？"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:1:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "就教「原住民教育資源中心」運作情形及成果。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:2:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "警政", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "有關 3 月 4 日至 3 月 8 日台 16 線民和國中前密集攔檢與超速執法疑慮：1.警察局表示因該路段發生 A1 死亡車禍而進行連續五天的密集交通稽查，但實際攔檢點與當初發生車禍的地點相差 2 公里，為何不在事發地點執法？2.依據警察局提供書面資料，該路段 1 至 5 月共取締 102 件違規，但這五天 60 幾件就佔了一半以上，且其中九成是當地三個部落的族人，讓人質疑是否有針對性。3.車輛是族人們上班必備的交通工具，密集攔檢造成許多族人因超速被吊扣牌照或重罰無法上班、影響生計。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:3:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "工務農業", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "信義鄉東埔村日月橋附近因土石流災損已近兩年尚未修復，請工務處及農業處分別就業務責任範圍說明災修辦理情形。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202609011615240:184:4:p35747b7ff2','p35747b7ff2','interpellation','2026-05-20','{"councillors": ["全文才"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第16會次", "page": 184, "session": "第20屆第7次定期會", "term": 20, "title": "就教信義鄉雙龍部落聯外道路「天坑」災害修復工程進度。"}','https://www.ntcc.gov.tw/upload/news/202609011615240.pdf#page=184','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:0:p35747b7ff2','p35747b7ff2','interpellation','2025-10-22','{"councillors": ["全文才"], "dept": "農業", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "1. 2001 年桃芝颱風過後，信義鄉許多地方被劃為土石流警戒區，請問縣府有沒有檢討縮小範圍？2. 信義鄉濁水溪線的四個村，沒有特色的農產品，建請縣府可以輔導農民發展策略，推廣行銷。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:179:1:p35747b7ff2','p35747b7ff2','interpellation','2025-10-22','{"councillors": ["全文才"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 179, "session": "第20屆第6次定期會", "term": 20, "title": "日前原民處去沖繩考察道之驛許田、恩納之驛休憩市場，有甚麼啟發可以借鏡到原之驛商場市集，讓國民可以到原之驛參觀消費？"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=179','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:136:0:p35747b7ff2','p35747b7ff2','interpellation','2025-06-03','{"councillors": ["全文才"], "dept": "教育", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "族語語文競賽的比賽地點以往都在原鄉舉辦，為甚麼今年會改變？競賽希望可以盡量邀請到各個社群的評審，以求公正。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:136:1:p35747b7ff2','p35747b7ff2','interpellation','2025-06-03','{"councillors": ["全文才"], "dept": "原民", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "去年風災造成信義鄉的多處災情，雙龍到地利的道路天坑，迄今尚未修復，何時可以進行施工修復？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:136:2:p35747b7ff2','p35747b7ff2','interpellation','2025-06-03','{"councillors": ["全文才"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第8會次", "page": 136, "session": "第20屆第5次定期會", "term": 20, "title": "信義鄉拉普拉斯村的農路復建工程的辦理進度？"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=136','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:196:6:pf8e5702de0','pf8e5702de0','interpellation','2025-10-29','{"councillors": ["張秀枝"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 196, "session": "第20屆第6次定期會", "term": 20, "title": "9 月 10 月份南投縣辧的大型活動非常成功，讓南投縣能見度非常高，值得肯定。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=196','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202606090806090:196:7:pf8e5702de0','pf8e5702de0','interpellation','2025-10-29','{"councillors": ["張秀枝"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第12會次", "page": 196, "session": "第20屆第6次定期會", "term": 20, "title": "1.遇到豪大雨時，貓羅溪畔常大淹水，要如何整治及規劃抽水站？2.南投市綠美橋被列為危橋，請縣府要重視。"}','https://www.ntcc.gov.tw/upload/news/202606090806090.pdf#page=196','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:161:1:pf8e5702de0','pf8e5702de0','interpellation','2025-06-12','{"councillors": ["張秀枝"], "dept": "計畫", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 161, "session": "第20屆第5次定期會", "term": 20, "title": "南投市轉運站完成用地取得表示肯定。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=161','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:161:2:pf8e5702de0','pf8e5702de0','interpellation','2025-06-12','{"councillors": ["張秀枝"], "dept": "工務", "doc_type": "議員建議事項", "meeting": "第15會次", "page": 161, "session": "第20屆第5次定期會", "term": 20, "title": "1. 有關貓羅溪防災減災、遠離水患五大訴求：(1) 全境疏濬：將南投市境貓羅溪上游振興橋至下游平林橋碧山巖全境 10 公里疏濬500 萬立方米土方。(2) 施設攔砂壩：貓羅溪上游平林溪(南中寮)、樟平溪(北中寮)施設攔水壩，防止中寮土方匯入貓羅溪。(3) 施設抽水站：貓羅溪沿岸低窪地區千秋、振興、軍功、內興、內新、營南、平和、福興等地設置固定抽水站，防區域排水倒灌。(4) 徵收：振興、平林橋河段土地全面徵收，以利河川局疏濬。(5) 施設樟平溪小溪橋上游堤防：右岸700公尺、左岸─南投酒廠至龍南排水300公尺堤防、左岸─龍南排水至小溪橋增高堤防1公尺。2. 貓羅溪沿岸雜草叢生亦為水患主因之一，應予以整治。3. 振興里、平和里高架橋下方，去年因颱風來襲挾帶大雨導致上百輛車泡水，未來仍應防範大水宣洩不及的情形。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=161','2026-10-15T03:46:11Z');
INSERT INTO "fact" VALUES('ntccq:202512051057560:168:0:pf8e5702de0','pf8e5702de0','interpellation','2025-06-16','{"councillors": ["張秀枝"], "dept": "全", "doc_type": "議員建議事項", "meeting": "第17會次", "page": 168, "session": "第20屆第5次定期會", "term": 20, "title": "貓羅溪水患，內水無法排出，民眾要如何預防？要增加抽水機防範。"}','https://www.ntcc.gov.tw/upload/news/202512051057560.pdf#page=168','2026-10-15T03:46:11Z');
